        emailVerificationExpiry: null,
      },
    });

    console.log('✅ Email verification successful');

    // Verify email verification
    const updatedVerifyUser = await prisma.user.findUnique({
      where: { id: verifyUser.id },
    });

    if (!updatedVerifyUser)
