                  onClick={() => (window.location.href = '/track')}
                >
                  Track Move
                </Button>
              </HStack>
            </VStack>
          </MotionBox>
        </VStack>
      </Container>

      {/* Home Footer */}
      <HomeFooter />

      {/* Trustpilot Widget Section */}
      <TrustpilotWidget />
    </Box>
  );
}

