];

export default function AnalyticsReportsPage() {
  const [reports, setReports] = useState<Report[]>([]);
  const [selectedTemplate, setSelectedTemplate] = useState<string>('');
  const [reportName, setReportName] = useState('');
  const [reportDescription, setReportDescription] = useState('');
  const [selectedMetrics, setSelectedMetrics] = useState<string[]>([]);
  const [selectedDimensions, setSelectedDimensions] = useState<string[]>([]);
  const [dateRange, setDateRange] = useState('30d');
  const [schedule, setSchedule] = useState<
    'none' | 'daily' | 'weekly' | 'monthly'
  >('none');
  const [recipients, setRecipients] = useState<string[]>([]);
  const [newRecipient, setNewRecipient] = useState('');
  const [previewData, setPreviewData] = useState<any>(null);
  const [loading, setLoading] = useState(false);

  const bgColor = useColorModeValue('white', 'gray.800');
  const borderColor = useColorModeValue('gray.200', 'gray.700');

  // Load saved reports on mount
  useEffect(() => {
    loadSavedReports();
  }, []);

  const loadSavedReports = async () => {
    try {
      const response = await fetch('/api/admin/analytics/reports');
      if (response.ok) {
        const data = await response.json();
        setReports(data.reports || []);
      }
    } catch (error) {
      console.error('Failed to load reports:', error);
    }
  };

  const handleTemplateSelect = (templateId: string) => {
    const template = REPORT_TEMPLATES.find(t => t.id === templateId);
    if (template) {
      setSelectedTemplate(templateId);
      setReportName(template.name);
      setReportDescription(template.description);
      setSelectedMetrics(template.metrics);
      setSelectedDimensions(template.dimensions);
      setDateRange(template.defaultFilters.dateRange);
    }
  };

  const handleMetricToggle = (metricId: string) => {
    setSelectedMetrics(prev =>
      prev.includes(metricId)
        ? prev.filter(id => id !== metricId)
        : [...prev, metricId]
    );
  };

  const handleDimensionToggle = (dimensionId: string) => {
    setSelectedDimensions(prev =>
      prev.includes(dimensionId)
        ? prev.filter(id => id !== dimensionId)
        : [...prev, dimensionId]
    );
  };

  const addRecipient = () => {
    if (newRecipient && !recipients.includes(newRecipient)) {
      setRecipients([...recipients, newRecipient]);
      setNewRecipient('');
    }
  };

  const removeRecipient = (email: string) => {
    setRecipients(recipients.filter(r => r !== email));
  };

  const generatePreview = async () => {
    if (selectedMetrics.length === 0 || selectedDimensions.length === 0) {
      return;
    }

    setLoading(true);
    try {
      const response = await fetch('/api/admin/analytics/reports/preview', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          metrics: selectedMetrics,
          dimensions: selectedDimensions,
          filters: { dateRange },
        }),
      });

      if (response.ok) {
        const data = await response.json();
        setPreviewData(data);
      }
    } catch (error) {
      console.error('Failed to generate preview:', error);
    } finally {
      setLoading(false);
    }
  };

  const saveReport = async () => {
    if (!reportName || selectedMetrics.length === 0) {
      return;
    }

    try {
      const response = await fetch('/api/admin/analytics/reports', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: reportName,
          description: reportDescription,
          metrics: selectedMetrics,
          dimensions: selectedDimensions,
          filters: { dateRange },
          schedule,
          recipients,
        }),
      });

      if (response.ok) {
        await loadSavedReports();
        // Reset form
        setReportName('');
        setReportDescription('');
        setSelectedMetrics([]);
        setSelectedDimensions([]);
        setSchedule('none');
        setRecipients([]);
        setSelectedTemplate('');
      }
    } catch (error) {
      console.error('Failed to save report:', error);
    }
  };

  const runReport = async (reportId: string) => {
    try {
      const response = await fetch(
        `/api/admin/analytics/reports/${reportId}/run`,
        {
          method: 'POST',
        }
      );
      if (response.ok) {
        // Refresh reports list
        await loadSavedReports();
      }
    } catch (error) {
      console.error('Failed to run report:', error);
    }
  };

  const toggleReportStatus = async (
    reportId: string,
    currentStatus: string
  ) => {
    const newStatus = currentStatus === 'active' ? 'paused' : 'active';
    try {
      const response = await fetch(`/api/admin/analytics/reports/${reportId}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: newStatus }),
      });
      if (response.ok) {
        await loadSavedReports();
      }
    } catch (error) {
      console.error('Failed to update report status:', error);
    }
  };

  const deleteReport = async (reportId: string) => {
    if (!confirm('Are you sure you want to delete this report?')) {
      return;
    }

    try {
      const response = await fetch(`/api/admin/analytics/reports/${reportId}`, {
        method: 'DELETE',
      });
      if (response.ok) {
        await loadSavedReports();
      }
    } catch (error) {
      console.error('Failed to delete report:', error);
    }
  };

  const exportReport = async (reportId: string, format: 'csv' | 'xlsx') => {
    try {
      const response = await fetch(
        `/api/admin/analytics/reports/${reportId}/export?format=${format}`
      );
      if (response.ok) {
        const blob = await response.blob();
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `report-${reportId}.${format}`;
        a.click();
        window.URL.revokeObjectURL(url);
      }
    } catch (error) {
      console.error('Failed to export report:', error);
    }
  };

  const getScheduleColor = (schedule: string) => {
    switch (schedule) {
      case 'daily':
        return 'blue';
      case 'weekly':
        return 'green';
      case 'monthly':
        return 'purple';
      default:
        return 'gray';
    }
  };

  return (
    <Box p={6} display="flex" flexDirection="column" gap={6}>
      {/* Header */}
      <HStack justify="space-between">
        <VStack align="start" spacing={1}>
          <Heading size="lg">Analytics Reports</Heading>
          <Text color="gray.600">
            Build, schedule, and manage custom reports
          </Text>
        </VStack>
        <HStack spacing={3}>
          <Button leftIcon={<FiDownload />} variant="outline" size="sm">
            Export All
          </Button>
          <Button leftIcon={<FiPlus />} colorScheme="blue" size="sm">
            Create Report
          </Button>
        </HStack>
      </HStack>

      <Tabs>
        <TabList>
          <Tab>Saved Reports</Tab>
          <Tab>Report Builder</Tab>
          <Tab>Scheduled Reports</Tab>
          <Tab>Templates</Tab>
        </TabList>

        <TabPanels>
          {/* Saved Reports Tab */}
          <TabPanel>
            <Grid templateColumns={{ base: '1fr', lg: '2fr 1fr' }} gap={6}>
              {/* Reports List */}
              <Card bg={bgColor} borderColor={borderColor}>
                <CardBody>
                  <Heading size="md" mb={4}>
                    Saved Reports
                  </Heading>
                  <VStack spacing={4} align="stretch">
                    {reports.map(report => (
                      <Card
                        key={report.id}
                        variant="outline"
                        bg={bgColor}
                        borderColor={borderColor}
                      >
                        <CardBody>
                          <HStack justify="space-between" mb={3}>
                            <VStack align="start" spacing={1}>
                              <Text fontWeight="bold">{report.name}</Text>
                              <Text fontSize="sm" color="gray.600">
                                {report.description}
                              </Text>
                            </VStack>
                            <Badge
                              colorScheme={getScheduleColor(report.schedule)}
                            >
                              {report.schedule}
                            </Badge>
                          </HStack>

                          <HStack spacing={4} mb={3}>
                            <VStack align="start" spacing={1}>
                              <Text fontSize="sm" fontWeight="bold">
                                Metrics
                              </Text>
                              <HStack spacing={1}>
                                {report.metrics.map(metric => (
                                  <Badge
                                    key={metric}
                                    size="sm"
                                    variant="outline"
                                  >
                                    {metric}
                                  </Badge>
                                ))}
                              </HStack>
                            </VStack>
                            <VStack align="start" spacing={1}>
                              <Text fontSize="sm" fontWeight="bold">
                                Dimensions
                              </Text>
                              <HStack spacing={1}>
                                {report.dimensions.map(dimension => (
                                  <Badge
                                    key={dimension}
                                    size="sm"
                                    variant="outline"
                                  >
                                    {dimension}
                                  </Badge>
                                ))}
                              </HStack>
                            </VStack>
                          </HStack>

                          <HStack justify="space-between">
                            <Text fontSize="sm" color="gray.600">
                              Last run:{' '}
                              {report.lastRun
                                ? new Date(report.lastRun).toLocaleString()
                                : 'Never'}
                            </Text>
                            <HStack spacing={2}>
                              <Button
                                size="xs"
                                variant="outline"
                                onClick={() => runReport(report.id)}
                              >
                                <FiPlay />
                                <span style={{ marginLeft: '0.25rem' }}>Run</span>
                              </Button>
                              <Button
                                size="xs"
                                variant="outline"
                                onClick={() => exportReport(report.id, 'csv')}
                              >
                                <FiDownload />
                                <span style={{ marginLeft: '0.25rem' }}>CSV</span>
                              </Button>
                              <Button
                                size="xs"
                                variant="outline"
                                onClick={() => exportReport(report.id, 'xlsx')}
                              >
                                <FiFileText />
                                <span style={{ marginLeft: '0.25rem' }}>Excel</span>
                              </Button>
                              <Button size="xs" variant="outline">
                                <FiEdit />
                                <span style={{ marginLeft: '0.25rem' }}>Edit</span>
                              </Button>
                            </HStack>
                          </HStack>
                        </CardBody>
                      </Card>
                    ))}
                  </VStack>
                </CardBody>
              </Card>

              {/* Quick Stats */}
              <VStack spacing={6} align="stretch">
                <Card bg={bgColor} borderColor={borderColor}>
                  <CardBody>
                    <Heading size="md" mb={4}>
                      Report Statistics
                    </Heading>
                    <VStack spacing={4} align="stretch">
                      <HStack justify="space-between">
                        <Text fontSize="sm">Total Reports</Text>
                        <Text fontWeight="bold">{reports.length}</Text>
                      </HStack>
                      <HStack justify="space-between">
                        <Text fontSize="sm">Active Schedules</Text>
                        <Text fontWeight="bold">
                          {reports.filter(r => r.status === 'active').length}
                        </Text>
                      </HStack>
                      <HStack justify="space-between">
                        <Text fontSize="sm">Last 24h Runs</Text>
                        <Text fontWeight="bold">12</Text>
                      </HStack>
                    </VStack>
                  </CardBody>
                </Card>

                <Card bg={bgColor} borderColor={borderColor}>
                  <CardBody>
                    <Heading size="md" mb={4}>
                      Popular Reports
                    </Heading>
                    <VStack spacing={3} align="stretch">
                      <HStack justify="space-between">
                        <Text fontSize="sm">Daily Revenue</Text>
                        <Text fontSize="sm" color="gray.600">
                          24 runs
                        </Text>
                      </HStack>
                      <HStack justify="space-between">
                        <Text fontSize="sm">Driver Performance</Text>
                        <Text fontSize="sm" color="gray.600">
                          12 runs
                        </Text>
                      </HStack>
                      <HStack justify="space-between">
                        <Text fontSize="sm">Customer Retention</Text>
                        <Text fontSize="sm" color="gray.600">
                          8 runs
                        </Text>
                      </HStack>
                    </VStack>
                  </CardBody>
                </Card>
              </VStack>
            </Grid>
          </TabPanel>

          {/* Report Builder Tab */}
          <TabPanel>
            <Grid templateColumns={{ base: '1fr', lg: '1fr 1fr' }} gap={6}>
              {/* Builder Form */}
              <Card bg={bgColor} borderColor={borderColor}>
                <CardBody>
                  <Heading size="md" mb={4}>
                    Report Builder
                  </Heading>
                  <VStack spacing={4} align="stretch">
                    <FormControl>
                      <FormLabel>Start with Template</FormLabel>
                      <Select
                        value={selectedTemplate}
                        onChange={e => handleTemplateSelect(e.target.value)}
                        suppressHydrationWarning
                      >
                        <option value="">Choose a template...</option>
                        {REPORT_TEMPLATES.map(template => (
                          <option key={template.id} value={template.id}>
                            {template.name}
                          </option>
                        ))}
                      </Select>
                    </FormControl>

                    <FormControl>
                      <FormLabel>Report Name</FormLabel>
                      <Input
                        value={reportName}
                        onChange={e => setReportName(e.target.value)}
                        placeholder="Enter report name"
                      />
                    </FormControl>

                    <FormControl>
                      <FormLabel>Description</FormLabel>
                      <Textarea
                        value={reportDescription}
                        onChange={e => setReportDescription(e.target.value)}
                        placeholder="Enter report description"
                      />
                    </FormControl>

                    <FormControl>
                      <FormLabel>Metrics</FormLabel>
                      <CheckboxGroup
                        value={selectedMetrics}
                        onChange={values =>
                          setSelectedMetrics(values as string[])
                        }
                      >
                        <SimpleGrid columns={2} spacing={2}>
                          {AVAILABLE_METRICS.map(metric => (
                            <Checkbox key={metric.id} value={metric.id}>
                              <HStack>
                                <Text fontSize="sm">{metric.name}</Text>
                                <Badge size="sm" variant="outline">
                                  {metric.category}
                                </Badge>
                              </HStack>
                            </Checkbox>
                          ))}
                        </SimpleGrid>
                      </CheckboxGroup>
                    </FormControl>

                    <FormControl>
                      <FormLabel>Dimensions</FormLabel>
                      <CheckboxGroup
                        value={selectedDimensions}
                        onChange={values =>
                          setSelectedDimensions(values as string[])
                        }
                      >
                        <SimpleGrid columns={2} spacing={2}>
                          {AVAILABLE_DIMENSIONS.map(dimension => (
                            <Checkbox key={dimension.id} value={dimension.id}>
                              <HStack>
                                <Text fontSize="sm">{dimension.name}</Text>
                                <Badge size="sm" variant="outline">
                                  {dimension.category}
                                </Badge>
                              </HStack>
                            </Checkbox>
                          ))}
                        </SimpleGrid>
                      </CheckboxGroup>
                    </FormControl>

                    <FormControl>
                      <FormLabel>Date Range</FormLabel>
                      <Select
                        value={dateRange}
                        onChange={e => setDateRange(e.target.value)}
                        suppressHydrationWarning
                      >
                        <option value="7d">Last 7 days</option>
                        <option value="30d">Last 30 days</option>
                        <option value="90d">Last 90 days</option>
                        <option value="6m">Last 6 months</option>
                        <option value="1y">Last year</option>
                      </Select>
                    </FormControl>

                    <FormControl>
                      <FormLabel>Schedule (Optional)</FormLabel>
                      <Select
                        value={schedule}
                        onChange={e => setSchedule(e.target.value as any)}
                        suppressHydrationWarning
                      >
                        <option value="none">No schedule</option>
                        <option value="daily">Daily</option>
                        <option value="weekly">Weekly</option>
                        <option value="monthly">Monthly</option>
                      </Select>
                    </FormControl>

                    {schedule !== 'none' && (
                      <FormControl>
                        <FormLabel>Recipients</FormLabel>
                        <HStack>
                          <Input
                            value={newRecipient}
                            onChange={e => setNewRecipient(e.target.value)}
                            placeholder="Enter email address"
                            onKeyPress={e =>
                              e.key === 'Enter' && addRecipient()
                            }
                          />
                          <Button onClick={addRecipient} size="sm">
                            Add
                          </Button>
                        </HStack>
                        <HStack spacing={1} mt={2} flexWrap="wrap">
                          {recipients.map(email => (
                            <Badge key={email} colorScheme="blue" size="sm">
                              {email}
                              <Button
                                size="xs"
                                variant="ghost"
                                onClick={() => removeRecipient(email)}
                                ml={1}
                              >
                                ×
                              </Button>
                            </Badge>
                          ))}
                        </HStack>
                      </FormControl>
                    )}

                    <HStack spacing={3}>
                      <Button
                        onClick={generatePreview}
                        disabled={loading || selectedMetrics.length === 0}
                      >
                        {loading ? 'Generating...' : 'Preview Report'}
                      </Button>
                      <Button
                        onClick={saveReport}
                        variant="outline"
                        disabled={!reportName || selectedMetrics.length === 0}
                      >
                        Save Report
                      </Button>
                    </HStack>
                  </VStack>
                </CardBody>
              </Card>

              {/* Preview */}
              <Card bg={bgColor} borderColor={borderColor}>
                <CardBody>
                  <Heading size="md" mb={4}>
                    Report Preview
                  </Heading>
                  {previewData ? (
                    <VStack spacing={4}>
                      <Text fontSize="sm" color="gray.600">
                        Preview data for {selectedMetrics.length} metrics ×{' '}
                        {selectedDimensions.length} dimensions
                      </Text>
                      <Box
                        bg="gray.50"
                        p={4}
                        rounded="lg"
                        maxH="400px"
                        overflow="auto"
                      >
                        <pre className="text-xs">
                          {JSON.stringify(previewData, null, 2)}
                        </pre>
                      </Box>
                    </VStack>
                  ) : (
                    <VStack spacing={4} justify="center" h="400px">
                      <FiBarChart2 size={48} color="#666" />
                      <Text color="gray.500">
                        Report preview will appear here
                      </Text>
                      <Text fontSize="sm" color="gray.400">
                        Select metrics and dimensions to generate preview
                      </Text>
                    </VStack>
                  )}
                </CardBody>
              </Card>
            </Grid>
          </TabPanel>

          {/* Scheduled Reports Tab */}
          <TabPanel>
            <Card bg={bgColor} borderColor={borderColor}>
              <CardBody>
                <Heading size="md" mb={4}>
                  Scheduled Reports
                </Heading>
                <Table variant="simple">
                  <Thead>
                    <Tr>
                      <Th>Report Name</Th>
                      <Th>Schedule</Th>
                      <Th>Recipients</Th>
                      <Th>Last Run</Th>
                      <Th>Next Run</Th>
                      <Th>Status</Th>
                      <Th>Actions</Th>
                    </Tr>
                  </Thead>
                  <Tbody>
                    {reports
                      .filter(r => r.schedule !== 'none')
                      .map(report => (
                        <Tr key={report.id}>
                          <Td>
                            <VStack align="start" spacing={1}>
                              <Text fontWeight="bold">{report.name}</Text>
                              <Text fontSize="sm" color="gray.600">
                                {report.description}
                              </Text>
                            </VStack>
                          </Td>
                          <Td>
                            <Badge
                              colorScheme={getScheduleColor(report.schedule)}
                            >
                              {report.schedule}
                            </Badge>
                          </Td>
                          <Td>
                            <Text fontSize="sm">
                              {report.recipients?.slice(0, 2).join(', ')}
                              {report.recipients?.length > 2 &&
                                ` +${report.recipients.length - 2}`}
                            </Text>
                          </Td>
                          <Td>
                            <Text fontSize="sm">
                              {new Date(report.lastRun).toLocaleDateString()}
                            </Text>
                          </Td>
                          <Td>
                            <Text fontSize="sm">
                              {report.nextRun
                                ? new Date(report.nextRun).toLocaleDateString()
                                : 'N/A'}
                            </Text>
                          </Td>
                          <Td>
                            <Badge
                              colorScheme={
                                report.status === 'active' ? 'green' : 'gray'
                              }
                            >
                              {report.status}
                            </Badge>
                          </Td>
                          <Td>
                            <HStack spacing={2}>
                              <Button
                                size="xs"
                                variant="outline"
                                onClick={() =>
                                  toggleReportStatus(report.id, report.status)
                                }
                              >
                                {report.status === 'active' ? (
                                  <FiPause />
                                ) : (
                                  <FiPlay />
                                )}
                              </Button>
                              <Button size="xs" variant="outline">
                                <FiEdit />
                              </Button>
                              <Button
                                size="xs"
                                variant="outline"
                                onClick={() => deleteReport(report.id)}
                              >
                                <FiTrash2 />
                              </Button>
                            </HStack>
                          </Td>
                        </Tr>
                      ))}
                  </Tbody>
                </Table>
              </CardBody>
            </Card>
          </TabPanel>

          {/* Templates Tab */}
          <TabPanel>
            <Card bg={bgColor} borderColor={borderColor}>
              <CardBody>
                <Heading size="md" mb={4}>
                  Report Templates
                </Heading>
                <SimpleGrid columns={{ base: 1, md: 2 }} spacing={4}>
                  {REPORT_TEMPLATES.map(template => (
                    <Card
                      key={template.id}
                      variant="outline"
                      bg={bgColor}
                      borderColor={borderColor}
                    >
                      <CardBody>
                        <HStack justify="space-between" mb={3}>
                          <VStack align="start" spacing={1}>
                            <Text fontWeight="bold">{template.name}</Text>
                            <Text fontSize="sm" color="gray.600">
                              {template.description}
                            </Text>
                          </VStack>
                          <Badge variant="outline">{template.category}</Badge>
                        </HStack>

                        <VStack spacing={3} mb={3}>
                          <VStack align="start" spacing={1}>
                            <Text fontSize="sm" fontWeight="bold">
                              Metrics:
                            </Text>
                            <HStack spacing={1} flexWrap="wrap">
                              {template.metrics.map(metric => (
                                <Badge
                                  key={metric}
                                  size="sm"
                                  colorScheme="blue"
                                >
                                  {metric}
                                </Badge>
                              ))}
                            </HStack>
                          </VStack>

                          <VStack align="start" spacing={1}>
                            <Text fontSize="sm" fontWeight="bold">
                              Dimensions:
                            </Text>
                            <HStack spacing={1} flexWrap="wrap">
                              {template.dimensions.map(dimension => (
                                <Badge
                                  key={dimension}
                                  size="sm"
                                  variant="outline"
                                >
                                  {dimension}
                                </Badge>
                              ))}
                            </HStack>
                          </VStack>
                        </VStack>

                        <Button
                          size="sm"
                          onClick={() => handleTemplateSelect(template.id)}
                          width="full"
                        >
                          Use Template
                        </Button>
                      </CardBody>
                    </Card>
                  ))}
                </SimpleGrid>
              </CardBody>
            </Card>
          </TabPanel>
        </TabPanels>
      </Tabs>
    </Box>
  );
}

'use client';

/**
 * Pending Approvals Client Component
 * Real-time dashboard for reviewing cap-breached driver payments
 */

import { useEffect, useState, useCallback } from 'react';
import {
  Box,
  Container,
  Heading,
  Text,
  VStack,
  HStack,
  Card,
  CardBody,
  Button,
  Badge,
  Spinner,
  useToast,
  Stat,
  StatLabel,
  StatNumber,
  StatHelpText,
  SimpleGrid,
  Divider,
  Collapse,
  IconButton,
  Modal,
  ModalOverlay,
  ModalContent,
  ModalHeader,
  ModalFooter,
  ModalBody,
  ModalCloseButton,
  Textarea,
  NumberInput,
  NumberInputField,
  NumberInputStepper,
  NumberIncrementStepper,
  NumberDecrementStepper,
  Alert,
  AlertIcon,
  AlertTitle,
  AlertDescription,
  useDisclosure,
} from '@chakra-ui/react';
import { ChevronDownIcon, ChevronUpIcon, CheckIcon, CloseIcon } from '@chakra-ui/icons';
import Pusher from 'pusher-js';

// Types
interface PendingApproval {
  assignmentId: string;
  bookingReference: string;
  driver: {
    id: string;
    name: string;
    email: string;
  };
  jobDetails: {
    pickup: string;
    dropoff: string;
    estimatedDistanceMiles?: number;
    serviceType: string;
  };
  capContext: {
    currentDailyTotal: number;
    remainingAllowance: number;
    dailyCapPence: number;
    currentDailyTotalGBP: string;
    remainingAllowanceGBP: string;
  };
  timing: {
    completedAt: string;
    waitingMinutes: number;
  };
  status: string;
}

interface ApprovalModalData {
  assignmentId: string;
  driverName: string;
  bookingReference: string;
  action: 'approved' | 'rejected';
  suggestedAmount: number;
}

export default function PendingApprovalsClient() {
  const [approvals, setApprovals] = useState<PendingApproval[]>([]);
  const [loading, setLoading] = useState(true);
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [processingId, setProcessingId] = useState<string | null>(null);
  const [stats, setStats] = useState({
    totalPending: 0,
    totalWaitingValue: '0.00',
    avgWaitTime: 0,
  });

  const { isOpen, onOpen, onClose } = useDisclosure();
  const [modalData, setModalData] = useState<ApprovalModalData | null>(null);
  const [adminNotes, setAdminNotes] = useState('');
  const [approvedAmount, setApprovedAmount] = useState(0);

  const toast = useToast();

  // Fetch pending approvals
  const fetchApprovals = useCallback(async () => {
    try {
      const response = await fetch('/api/admin/jobs/pending-approval');
      if (!response.ok) throw new Error('Failed to fetch pending approvals');

      const data = await response.json();
      setApprovals(data.pendingApprovals || []);

      // Calculate stats
      const totalPending = data.count || 0;
      const totalWaitingValue = data.pendingApprovals
        ?.reduce((sum: number, item: PendingApproval) => sum + item.capContext.currentDailyTotal, 0)
        .toFixed(2) || '0.00';
      const avgWaitTime = data.pendingApprovals?.length > 0
        ? Math.round(
            data.pendingApprovals.reduce((sum: number, item: PendingApproval) => sum + item.timing.waitingMinutes, 0) /
              data.pendingApprovals.length
          )
        : 0;

      setStats({ totalPending, totalWaitingValue, avgWaitTime });
    } catch (error) {
      console.error('Error fetching approvals:', error);
      toast({
        title: 'Error loading data',
        description: 'Failed to load pending approvals',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setLoading(false);
    }
  }, [toast]);

  // Setup Pusher real-time updates
  useEffect(() => {
    fetchApprovals();

    // Initialize Pusher
    const PUSHER_KEY = '407cb06c423e6c032e9c';
    const PUSHER_CLUSTER = 'eu';
    const pusher = new Pusher(PUSHER_KEY, {
      cluster: PUSHER_CLUSTER,
    });

    const channel = pusher.subscribe('admin-notifications');
    
    channel.bind('payment-approval-required', (data: any) => {
      console.log('🔔 New payment approval required:', data);
      toast({
        title: 'New approval request',
        description: `Driver ${data.driverId} requires admin approval`,
        status: 'info',
        duration: 10000,
        isClosable: true,
      });
      fetchApprovals();
    });

    channel.bind('payment-approved', () => {
      fetchApprovals();
    });

    return () => {
      channel.unbind_all();
      channel.unsubscribe();
      pusher.disconnect();
    };
  }, [fetchApprovals, toast]);

  // Open approval modal
  const handleOpenModal = (approval: PendingApproval, action: 'approved' | 'rejected') => {
    setModalData({
      assignmentId: approval.assignmentId,
      driverName: approval.driver.name,
      bookingReference: approval.bookingReference,
      action,
      suggestedAmount: approval.capContext.remainingAllowance,
    });
    setApprovedAmount(approval.capContext.remainingAllowance / 100);
    setAdminNotes('');
    onOpen();
  };

  // Submit approval decision
  const handleSubmitDecision = async () => {
    if (!modalData) return;

    setProcessingId(modalData.assignmentId);

    try {
      const response = await fetch(`/api/admin/jobs/${modalData.assignmentId}/approve-payment`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: modalData.action,
          approved_amount_pence: modalData.action === 'approved' ? Math.round(approvedAmount * 100) : 0,
          admin_notes: adminNotes || undefined,
        }),
      });

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.message || 'Failed to process decision');
      }

      const result = await response.json();

      toast({
        title: modalData.action === 'approved' ? 'Approved successfully' : 'Rejected',
        description:
          modalData.action === 'approved'
            ? `Approved £${result.data.approvedAmountGBP} for driver ${modalData.driverName}`
            : `Payment rejected for driver ${modalData.driverName}`,
        status: 'success',
        duration: 5000,
        isClosable: true,
      });

      onClose();
      fetchApprovals();
    } catch (error: any) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to process decision',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setProcessingId(null);
    }
  };

  if (loading) {
    return (
      <Container maxW="container.xl" py={8}>
        <VStack spacing={4}>
          <Spinner size="xl" color="blue.500" />
          <Text>Loading pending approvals...</Text>
        </VStack>
      </Container>
    );
  }

  return (
    <Container maxW="container.xl" py={8}>
      <VStack spacing={6} align="stretch">
        {/* Header */}
        <Box>
          <Heading size="lg" mb={2}>
            Pending Approvals
          </Heading>
          <Text color="gray.600">Review and approve driver payments that exceeded the daily cap (£500)</Text>
        </Box>

        {/* Stats Cards */}
        <SimpleGrid columns={{ base: 1, md: 3 }} spacing={4}>
          <Card>
            <CardBody>
              <Stat>
                <StatLabel>Pending Requests</StatLabel>
                <StatNumber>{stats.totalPending}</StatNumber>
                <StatHelpText>Awaiting approval</StatHelpText>
              </Stat>
            </CardBody>
          </Card>

          <Card>
            <CardBody>
              <Stat>
                <StatLabel>Average Wait Time</StatLabel>
                <StatNumber>{stats.avgWaitTime} minutes</StatNumber>
                <StatHelpText>Since job completion</StatHelpText>
              </Stat>
            </CardBody>
          </Card>

          <Card>
            <CardBody>
              <Stat>
                <StatLabel>Total Pending Amount</StatLabel>
                <StatNumber>£{stats.totalWaitingValue}</StatNumber>
                <StatHelpText>Awaiting processing</StatHelpText>
              </Stat>
            </CardBody>
          </Card>
        </SimpleGrid>

        {/* No Approvals */}
        {approvals.length === 0 && (
          <Alert status="success" borderRadius="md">
            <AlertIcon />
            <AlertTitle>No pending approvals</AlertTitle>
            <AlertDescription>All payments have been processed!</AlertDescription>
          </Alert>
        )}

        {/* Approvals List */}
        {approvals.map((approval) => (
          <Card key={approval.assignmentId} variant="outline">
            <CardBody>
              <VStack spacing={4} align="stretch">
                {/* Header Row */}
                <HStack justify="space-between">
                  <HStack spacing={4}>
                    <Box>
                      <Text fontWeight="bold" fontSize="lg">
                        {approval.driver.name}
                      </Text>
                      <Text fontSize="sm" color="gray.600">
                        {approval.driver.email}
                      </Text>
                    </Box>
                    <Badge colorScheme="orange" fontSize="sm">
                      {approval.bookingReference}
                    </Badge>
                  </HStack>

                  <HStack>
                    <Badge colorScheme="red" fontSize="md" px={3} py={1}>
                      Waiting {approval.timing.waitingMinutes} minutes
                    </Badge>
                    <IconButton
                      aria-label="Toggle details"
                      icon={expandedId === approval.assignmentId ? <ChevronUpIcon /> : <ChevronDownIcon />}
                      size="sm"
                      variant="ghost"
                      onClick={() => setExpandedId(expandedId === approval.assignmentId ? null : approval.assignmentId)}
                    />
                  </HStack>
                </HStack>

                {/* Cap Context */}
                <SimpleGrid columns={{ base: 1, md: 3 }} spacing={4}>
                  <Box>
                    <Text fontSize="xs" color="gray.600">
                      Daily Cap
                    </Text>
                    <Text fontWeight="bold" fontSize="lg">
                      £{(approval.capContext.dailyCapPence / 100).toFixed(2)}
                    </Text>
                  </Box>
                  <Box>
                    <Text fontSize="xs" color="gray.600">
                      Current Total
                    </Text>
                    <Text fontWeight="bold" fontSize="lg" color="orange.500">
                      £{approval.capContext.currentDailyTotalGBP}
                    </Text>
                  </Box>
                  <Box>
                    <Text fontSize="xs" color="gray.600">
                      Remaining
                    </Text>
                    <Text fontWeight="bold" fontSize="lg" color="green.500">
                      £{approval.capContext.remainingAllowanceGBP}
                    </Text>
                  </Box>
                </SimpleGrid>

                {/* Expanded Details */}
                <Collapse in={expandedId === approval.assignmentId} animateOpacity>
                  <VStack spacing={3} align="stretch" pt={2}>
                    <Divider />
                    <Box>
                      <Text fontSize="sm" fontWeight="bold" mb={2}>
                        Job Details:
                      </Text>
                      <SimpleGrid columns={{ base: 1, md: 2 }} spacing={2}>
                        <Box>
                          <Text fontSize="xs" color="gray.600">
                            Service Type
                          </Text>
                          <Text fontSize="sm">{approval.jobDetails.serviceType}</Text>
                        </Box>
                        {approval.jobDetails.estimatedDistanceMiles && (
                          <Box>
                            <Text fontSize="xs" color="gray.600">
                              Distance
                            </Text>
                            <Text fontSize="sm">{approval.jobDetails.estimatedDistanceMiles} miles</Text>
                          </Box>
                        )}
                        <Box>
                          <Text fontSize="xs" color="gray.600">
                            Pickup
                          </Text>
                          <Text fontSize="sm">{approval.jobDetails.pickup}</Text>
                        </Box>
                        <Box>
                          <Text fontSize="xs" color="gray.600">
                            Dropoff
                          </Text>
                          <Text fontSize="sm">{approval.jobDetails.dropoff}</Text>
                        </Box>
                      </SimpleGrid>
                    </Box>
                    <Box>
                      <Text fontSize="xs" color="gray.600" mb={1}>
                        Completion Time
                      </Text>
                      <Text fontSize="sm">{new Date(approval.timing.completedAt).toLocaleString('ar-EG')}</Text>
                    </Box>
                  </VStack>
                </Collapse>

                {/* Action Buttons */}
                <HStack spacing={3} pt={2}>
                  <Button
                    colorScheme="green"
                    leftIcon={<CheckIcon />}
                    flex={1}
                    isDisabled={processingId === approval.assignmentId}
                    onClick={() => handleOpenModal(approval, 'approved')}
                  >
                    Approve
                  </Button>
                  <Button
                    colorScheme="red"
                    leftIcon={<CloseIcon />}
                    flex={1}
                    isDisabled={processingId === approval.assignmentId}
                    onClick={() => handleOpenModal(approval, 'rejected')}
                  >
                    Reject
                  </Button>
                </HStack>
              </VStack>
            </CardBody>
          </Card>
        ))}
      </VStack>

      {/* Approval Modal */}
      <Modal isOpen={isOpen} onClose={onClose} size="lg">
        <ModalOverlay />
        <ModalContent>
          <ModalHeader>
            {modalData?.action === 'approved' ? 'Approve Payment' : 'Reject Payment'}
          </ModalHeader>
          <ModalCloseButton />
          <ModalBody>
            <VStack spacing={4} align="stretch">
              <Box>
                <Text fontWeight="bold">Driver: {modalData?.driverName}</Text>
                <Text fontSize="sm" color="gray.600">
                  Booking Ref: {modalData?.bookingReference}
                </Text>
              </Box>

              {modalData?.action === 'approved' && (
                <Box>
                  <Text mb={2} fontWeight="bold">
                    Approved Amount (£)
                  </Text>
                  <NumberInput
                    value={approvedAmount}
                    onChange={(_, valueAsNumber) => setApprovedAmount(valueAsNumber)}
                    min={0}
                    max={(modalData?.suggestedAmount || 0) / 100}
                    step={0.01}
                    precision={2}
                  >
                    <NumberInputField />
                    <NumberInputStepper>
                      <NumberIncrementStepper />
                      <NumberDecrementStepper />
                    </NumberInputStepper>
                  </NumberInput>
                  <Text fontSize="xs" color="gray.600" mt={1}>
                    Maximum available: £{((modalData?.suggestedAmount || 0) / 100).toFixed(2)}
                  </Text>
                </Box>
              )}

              <Box>
                <Text mb={2} fontWeight="bold">
                  Admin Notes (optional)
                </Text>
                <Textarea
                  value={adminNotes}
                  onChange={(e) => setAdminNotes(e.target.value)}
                  placeholder="Add any notes..."
                  rows={3}
                />
              </Box>

              {modalData?.action === 'rejected' && (
                <Alert status="warning" borderRadius="md">
                  <AlertIcon />
                  <AlertDescription fontSize="sm">
                    The driver will be notified of the payment rejection. Make sure to add the reason for rejection in the notes.
                  </AlertDescription>
                </Alert>
              )}
            </VStack>
          </ModalBody>

          <ModalFooter>
            <Button variant="ghost" mr={3} onClick={onClose}>
              Cancel
            </Button>
            <Button
              colorScheme={modalData?.action === 'approved' ? 'green' : 'red'}
              isLoading={processingId === modalData?.assignmentId}
              onClick={handleSubmitDecision}
            >
              {modalData?.action === 'approved' ? 'Confirm Approval' : 'Confirm Rejection'}
            </Button>
          </ModalFooter>
        </ModalContent>
      </Modal>
    </Container>
  );
}

'use client';

/**
 * Audit Trail Client Component
 * Complete audit log of all admin actions
 */

import { useEffect, useState, useCallback } from 'react';
import {
  Box,
  Container,
  Heading,
  Text,
  VStack,
  HStack,
  Card,
  CardBody,
  Button,
  Badge,
  Spinner,
  useToast,
  SimpleGrid,
  Divider,
  IconButton,
  Input,
  Select,
  FormControl,
  FormLabel,
  Code,
  Collapse,
  useDisclosure,
  Modal,
  ModalOverlay,
  ModalContent,
  ModalHeader,
  ModalBody,
  ModalCloseButton,
  Table,
  Thead,
  Tbody,
  Tr,
  Th,
  Td,
  TableContainer,
} from '@chakra-ui/react';
import { ChevronDownIcon, ChevronUpIcon, SearchIcon, ViewIcon } from '@chakra-ui/icons';

// Types
interface AuditRecord {
  id: string;
  type: string;
  entityType: string;
  entityId: string;
  adminId: string;
  adminName: string | null;
  action: string;
  previousValue: any;
  newValue: any;
  reason: string | null;
  notes: string | null;
  approvedAt: string;
}

export default function AuditTrailClient() {
  const [audits, setAudits] = useState<AuditRecord[]>([]);
  const [filteredAudits, setFilteredAudits] = useState<AuditRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [selectedAudit, setSelectedAudit] = useState<AuditRecord | null>(null);

  // Filters
  const [typeFilter, setTypeFilter] = useState<string>('all');
  const [actionFilter, setActionFilter] = useState<string>('all');
  const [searchQuery, setSearchQuery] = useState<string>('');
  const [dateFrom, setDateFrom] = useState<string>('');
  const [dateTo, setDateTo] = useState<string>('');

  const { isOpen, onOpen, onClose } = useDisclosure();
  const toast = useToast();

  // Fetch audit records
  const fetchAudits = useCallback(async () => {
    try {
      // Note: This endpoint needs to be created
      const response = await fetch('/api/admin/audit-trail');
      if (!response.ok) {
        // If endpoint doesn't exist yet, use mock data
        console.warn('Audit trail endpoint not available, using mock data');
        const mockData: AuditRecord[] = [
          {
            id: 'audit_1',
            type: 'daily_cap_breach',
            entityType: 'driver_earnings',
            entityId: 'earn_123',
            adminId: 'admin_1',
            adminName: 'Admin User',
            action: 'approved',
            previousValue: { status: 'pending_admin_review', amount: 48000 },
            newValue: { status: 'approved', approvedAmount: 48000 },
            reason: 'Approved exceptional circumstance',
            notes: 'Driver had emergency delivery',
            approvedAt: new Date(Date.now() - 1000 * 60 * 30).toISOString(),
          },
          {
            id: 'audit_2',
            type: 'bonus_approval',
            entityType: 'bonus_request',
            entityId: 'bonus_456',
            adminId: 'admin_1',
            adminName: 'Admin User',
            action: 'approved',
            previousValue: { status: 'pending', requestedAmount: 5000 },
            newValue: { status: 'approved', approvedAmount: 5000 },
            reason: null,
            notes: 'Excellent customer feedback',
            approvedAt: new Date(Date.now() - 1000 * 60 * 60 * 2).toISOString(),
          },
        ];
        setAudits(mockData);
        setFilteredAudits(mockData);
        setLoading(false);
        return;
      }

      const data = await response.json();
      setAudits(data.audits || []);
      setFilteredAudits(data.audits || []);
    } catch (error) {
      console.error('Error fetching audit trail:', error);
      toast({
        title: 'Error loading data',
        description: 'Failed to load audit trail',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setLoading(false);
    }
  }, [toast]);

  useEffect(() => {
    fetchAudits();
  }, [fetchAudits]);

  // Apply filters
  useEffect(() => {
    let filtered = [...audits];

    // Type filter
    if (typeFilter !== 'all') {
      filtered = filtered.filter((a) => a.type === typeFilter);
    }

    // Action filter
    if (actionFilter !== 'all') {
      filtered = filtered.filter((a) => a.action === actionFilter);
    }

    // Search query
    if (searchQuery) {
      const query = searchQuery.toLowerCase();
      filtered = filtered.filter(
        (a) =>
          a.entityId.toLowerCase().includes(query) ||
          a.adminName?.toLowerCase().includes(query) ||
          a.notes?.toLowerCase().includes(query) ||
          a.reason?.toLowerCase().includes(query)
      );
    }

    // Date range
    if (dateFrom) {
      const fromDate = new Date(dateFrom);
      filtered = filtered.filter((a) => new Date(a.approvedAt) >= fromDate);
    }
    if (dateTo) {
      const toDate = new Date(dateTo);
      toDate.setHours(23, 59, 59, 999);
      filtered = filtered.filter((a) => new Date(a.approvedAt) <= toDate);
    }

    setFilteredAudits(filtered);
  }, [audits, typeFilter, actionFilter, searchQuery, dateFrom, dateTo]);

  const handleViewDetails = (audit: AuditRecord) => {
    setSelectedAudit(audit);
    onOpen();
  };

  const getTypeLabel = (type: string) => {
    const types: Record<string, string> = {
      daily_cap_breach: 'Daily Cap Breach',
      bonus_approval: 'Bonus Approval',
      manual_override: 'Manual Override',
    };
    return types[type] || type;
  };

  const getTypeColor = (type: string) => {
    const colors: Record<string, string> = {
      daily_cap_breach: 'orange',
      bonus_approval: 'purple',
      manual_override: 'blue',
    };
    return colors[type] || 'gray';
  };

  const getActionColor = (action: string) => {
    return action === 'approved' ? 'green' : 'red';
  };

  const getActionLabel = (action: string) => {
    return action === 'approved' ? 'Approved' : 'Rejected';
  };

  const formatValue = (value: any) => {
    if (!value) return 'N/A';
    if (typeof value === 'object') {
      return JSON.stringify(value, null, 2);
    }
    return String(value);
  };

  if (loading) {
    return (
      <Container maxW="container.xl" py={8}>
        <VStack spacing={4}>
          <Spinner size="xl" color="blue.500" />
          <Text>Loading audit trail...</Text>
        </VStack>
      </Container>
    );
  }

  return (
    <Container maxW="container.xl" py={8}>
      <VStack spacing={6} align="stretch">
        {/* Header */}
        <Box>
          <Heading size="lg" mb={2}>
            Audit Trail
          </Heading>
          <Text color="gray.600">Complete record of all admin decisions and approvals</Text>
        </Box>

        {/* Filters */}
        <Card>
          <CardBody>
            <SimpleGrid columns={{ base: 1, md: 2, lg: 5 }} spacing={4}>
              <FormControl>
                <FormLabel fontSize="sm">Record Type</FormLabel>
                <Select value={typeFilter} onChange={(e) => setTypeFilter(e.target.value)} size="sm">
                  <option value="all">All</option>
                  <option value="daily_cap_breach">Daily Cap Breach</option>
                  <option value="bonus_approval">Bonus Approval</option>
                  <option value="manual_override">Manual Override</option>
                </Select>
              </FormControl>

              <FormControl>
                <FormLabel fontSize="sm">Action</FormLabel>
                <Select value={actionFilter} onChange={(e) => setActionFilter(e.target.value)} size="sm">
                  <option value="all">All</option>
                  <option value="approved">Approved</option>
                  <option value="rejected">Rejected</option>
                </Select>
              </FormControl>

              <FormControl>
                <FormLabel fontSize="sm">From Date</FormLabel>
                <Input type="date" value={dateFrom} onChange={(e) => setDateFrom(e.target.value)} size="sm" />
              </FormControl>

              <FormControl>
                <FormLabel fontSize="sm">To Date</FormLabel>
                <Input type="date" value={dateTo} onChange={(e) => setDateTo(e.target.value)} size="sm" />
              </FormControl>

              <FormControl>
                <FormLabel fontSize="sm">Search</FormLabel>
                <Input
                  placeholder="ID, admin, notes..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  size="sm"
                />
              </FormControl>
            </SimpleGrid>

            <HStack mt={4}>
              <Button
                size="sm"
                leftIcon={<SearchIcon />}
                onClick={() => {
                  // Filters are applied automatically via useEffect
                }}
              >
                Search
              </Button>
              <Button
                size="sm"
                variant="ghost"
                onClick={() => {
                  setTypeFilter('all');
                  setActionFilter('all');
                  setSearchQuery('');
                  setDateFrom('');
                  setDateTo('');
                }}
              >
                Reset
              </Button>
              <Box flex={1} />
              <Text fontSize="sm" color="gray.600">
                {filteredAudits.length} of {audits.length} records
              </Text>
            </HStack>
          </CardBody>
        </Card>

        {/* Stats */}
        <SimpleGrid columns={{ base: 1, md: 3 }} spacing={4}>
          <Card>
            <CardBody>
              <Text fontSize="sm" color="gray.600">
                Total Records
              </Text>
              <Text fontSize="2xl" fontWeight="bold">
                {audits.length}
              </Text>
            </CardBody>
          </Card>
          <Card>
            <CardBody>
              <Text fontSize="sm" color="gray.600">
                Approvals
              </Text>
              <Text fontSize="2xl" fontWeight="bold" color="green.500">
                {audits.filter((a) => a.action === 'approved').length}
              </Text>
            </CardBody>
          </Card>
          <Card>
            <CardBody>
              <Text fontSize="sm" color="gray.600">
                Rejections
              </Text>
              <Text fontSize="2xl" fontWeight="bold" color="red.500">
                {audits.filter((a) => a.action === 'rejected').length}
              </Text>
            </CardBody>
          </Card>
        </SimpleGrid>

        {/* Audit Records */}
        {filteredAudits.length === 0 && (
          <Card>
            <CardBody>
              <Text textAlign="center" color="gray.500">
                No records match the selected filters
              </Text>
            </CardBody>
          </Card>
        )}

        {filteredAudits.map((audit) => (
          <Card key={audit.id} variant="outline">
            <CardBody>
              <VStack spacing={3} align="stretch">
                {/* Header Row */}
                <HStack justify="space-between">
                  <HStack spacing={3}>
                    <Badge colorScheme={getTypeColor(audit.type)} fontSize="sm">
                      {getTypeLabel(audit.type)}
                    </Badge>
                    <Badge colorScheme={getActionColor(audit.action)} fontSize="sm">
                      {getActionLabel(audit.action)}
                    </Badge>
                  </HStack>

                  <HStack>
                    <Text fontSize="sm" color="gray.600">
                      {new Date(audit.approvedAt).toLocaleString('ar-EG')}
                    </Text>
                    <IconButton
                      aria-label="Toggle details"
                      icon={expandedId === audit.id ? <ChevronUpIcon /> : <ChevronDownIcon />}
                      size="sm"
                      variant="ghost"
                      onClick={() => setExpandedId(expandedId === audit.id ? null : audit.id)}
                    />
                  </HStack>
                </HStack>

                {/* Summary */}
                <SimpleGrid columns={{ base: 1, md: 3 }} spacing={4}>
                  <Box>
                    <Text fontSize="xs" color="gray.600">
                      Admin
                    </Text>
                    <Text fontSize="sm" fontWeight="bold">
                      {audit.adminName || audit.adminId}
                    </Text>
                  </Box>
                  <Box>
                    <Text fontSize="xs" color="gray.600">
                      Entity Type
                    </Text>
                    <Text fontSize="sm">{audit.entityType}</Text>
                  </Box>
                  <Box>
                    <Text fontSize="xs" color="gray.600">
                      Entity ID
                    </Text>
                    <Code fontSize="xs">{audit.entityId}</Code>
                  </Box>
                </SimpleGrid>

                {/* Expanded Details */}
                <Collapse in={expandedId === audit.id} animateOpacity>
                  <VStack spacing={3} align="stretch" pt={2}>
                    <Divider />

                    {audit.reason && (
                      <Box>
                        <Text fontSize="sm" fontWeight="bold" mb={1}>
                          Reason:
                        </Text>
                        <Text fontSize="sm" color="gray.700">
                          {audit.reason}
                        </Text>
                      </Box>
                    )}

                    {audit.notes && (
                      <Box>
                        <Text fontSize="sm" fontWeight="bold" mb={1}>
                          Notes:
                        </Text>
                        <Text fontSize="sm" color="gray.700" bg="gray.50" p={2} borderRadius="md">
                          {audit.notes}
                        </Text>
                      </Box>
                    )}

                    <SimpleGrid columns={{ base: 1, md: 2 }} spacing={4}>
                      <Box>
                        <Text fontSize="sm" fontWeight="bold" mb={2}>
                          Previous Value:
                        </Text>
                        <Code display="block" whiteSpace="pre" p={3} fontSize="xs" borderRadius="md">
                          {formatValue(audit.previousValue)}
                        </Code>
                      </Box>
                      <Box>
                        <Text fontSize="sm" fontWeight="bold" mb={2}>
                          New Value:
                        </Text>
                        <Code display="block" whiteSpace="pre" p={3} fontSize="xs" borderRadius="md">
                          {formatValue(audit.newValue)}
                        </Code>
                      </Box>
                    </SimpleGrid>

                    <HStack pt={2}>
                      <Button size="sm" leftIcon={<ViewIcon />} onClick={() => handleViewDetails(audit)}>
                        View Full Details
                      </Button>
                    </HStack>
                  </VStack>
                </Collapse>
              </VStack>
            </CardBody>
          </Card>
        ))}
      </VStack>

      {/* Details Modal */}
      <Modal isOpen={isOpen} onClose={onClose} size="xl">
        <ModalOverlay />
        <ModalContent>
          <ModalHeader>Audit Record Details</ModalHeader>
          <ModalCloseButton />
          <ModalBody pb={6}>
            {selectedAudit && (
              <VStack spacing={4} align="stretch">
                <TableContainer>
                  <Table size="sm" variant="simple">
                    <Tbody>
                      <Tr>
                        <Td fontWeight="bold" width="30%">
                          Record ID
                        </Td>
                        <Td>
                          <Code>{selectedAudit.id}</Code>
                        </Td>
                      </Tr>
                      <Tr>
                        <Td fontWeight="bold">Type</Td>
                        <Td>
                          <Badge colorScheme={getTypeColor(selectedAudit.type)}>
                            {getTypeLabel(selectedAudit.type)}
                          </Badge>
                        </Td>
                      </Tr>
                      <Tr>
                        <Td fontWeight="bold">Action</Td>
                        <Td>
                          <Badge colorScheme={getActionColor(selectedAudit.action)}>
                            {getActionLabel(selectedAudit.action)}
                          </Badge>
                        </Td>
                      </Tr>
                      <Tr>
                        <Td fontWeight="bold">Admin</Td>
                        <Td>{selectedAudit.adminName || selectedAudit.adminId}</Td>
                      </Tr>
                      <Tr>
                        <Td fontWeight="bold">Entity Type</Td>
                        <Td>{selectedAudit.entityType}</Td>
                      </Tr>
                      <Tr>
                        <Td fontWeight="bold">Entity ID</Td>
                        <Td>
                          <Code>{selectedAudit.entityId}</Code>
                        </Td>
                      </Tr>
                      <Tr>
                        <Td fontWeight="bold">Date & Time</Td>
                        <Td>{new Date(selectedAudit.approvedAt).toLocaleString('en-GB')}</Td>
                      </Tr>
                    </Tbody>
                  </Table>
                </TableContainer>

                <Divider />

                {selectedAudit.reason && (
                  <Box>
                    <Text fontWeight="bold" mb={2}>
                      Reason:
                    </Text>
                    <Text>{selectedAudit.reason}</Text>
                  </Box>
                )}

                {selectedAudit.notes && (
                  <Box>
                    <Text fontWeight="bold" mb={2}>
                      Notes:
                    </Text>
                    <Text bg="gray.50" p={3} borderRadius="md">
                      {selectedAudit.notes}
                    </Text>
                  </Box>
                )}

                <Divider />

                <Box>
                  <Text fontWeight="bold" mb={2}>
                    Previous Value:
                  </Text>
                  <Code display="block" whiteSpace="pre" p={4} fontSize="xs" borderRadius="md" maxH="200px" overflowY="auto">
                    {formatValue(selectedAudit.previousValue)}
                  </Code>
                </Box>

                <Box>
                  <Text fontWeight="bold" mb={2}>
                    New Value:
                  </Text>
                  <Code display="block" whiteSpace="pre" p={4} fontSize="xs" borderRadius="md" maxH="200px" overflowY="auto">
                    {formatValue(selectedAudit.newValue)}
                  </Code>
                </Box>
              </VStack>
            )}
          </ModalBody>
        </ModalContent>
      </Modal>
    </Container>
  );
}

'use client';
import React, { useEffect, useState } from 'react';
import {
  Box,
  Heading,
  HStack,
  VStack,
  Text,
  Badge,
  Card,
  CardBody,
  Button,
  Table,
  Thead,
  Tbody,
  Tr,
  Th,
  Td,
  Input,
  Select,
  InputGroup,
  InputLeftElement,
  SimpleGrid,
  Stat,
  StatLabel,
  StatNumber,
  StatHelpText,
  Modal,
  ModalOverlay,
  ModalContent,
  ModalHeader,
  ModalBody,
  ModalCloseButton,
  useDisclosure,
  Spinner,
  Alert,
  AlertIcon,
  AlertTitle,
  AlertDescription,
} from '@chakra-ui/react';
import {
  FiSearch,
  FiFilter,
  FiDownload,
  FiRefreshCw,
  FiEye,
  FiUser,
  FiActivity,
  FiClock,
  FiAlertTriangle,
  FiShield,
} from 'react-icons/fi';

interface AuditLog {
  id: string;
  timestamp: string;
  actor: string;
  actorRole: string;
  action: string;
  entity: string;
  entityId: string | null;
  ip: string | null;
  userAgent: string | null;
  before: any;
  after: any;
  details: any;
}

interface AuditStats {
  totalLogs: number;
  securityEvents: number;
  financialActions: number;
  userActions: number;
}

export default function AuditPage() {
  const [mounted, setMounted] = useState(false);
  const [logs, setLogs] = useState<AuditLog[]>([]);
  const [stats, setStats] = useState<AuditStats>({
    totalLogs: 0,
    securityEvents: 0,
    financialActions: 0,
    userActions: 0,
  });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [selectedLog, setSelectedLog] = useState<AuditLog | null>(null);
  const [filters, setFilters] = useState({
    search: '',
    action: '',
    entity: '',
    actorRole: '',
    from: '',
    to: '',
  });
  const [pagination, setPagination] = useState({
    page: 1,
    limit: 50,
    total: 0,
    pages: 0,
  });

  const { isOpen, onOpen, onClose } = useDisclosure();

  async function loadAuditLogs(page = 1, reset = false) {
    setLoading(true);
    setError(null);

    try {
      const params = new URLSearchParams({
        page: page.toString(),
        limit: pagination.limit.toString(),
        ...filters,
      });

      const response = await fetch(`/api/admin/audit?${params.toString()}`);
      if (!response.ok) {
        throw new Error('Failed to fetch audit logs');
      }

      const data = await response.json();

      if (reset) {
        setLogs(data.items);
      } else {
        setLogs(prev => [...prev, ...data.items]);
      }

      setPagination({
        page,
        limit: pagination.limit,
        total: data.total || 0,
        pages: Math.ceil((data.total || 0) / pagination.limit),
      });

      // Calculate stats
      calculateStats(data.items);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An error occurred');
    } finally {
      setLoading(false);
    }
  }

  function calculateStats(logs: AuditLog[]) {
    const securityEvents = logs.filter(
      log =>
        log.action &&
        (log.action.includes('login') ||
          log.action.includes('password') ||
          log.action.includes('security') ||
          log.action.includes('unauthorized'))
    ).length;

    const financialActions = logs.filter(
      log =>
        log.action &&
        (log.action.includes('payment') ||
          log.action.includes('refund') ||
          log.action.includes('payout') ||
          log.action.includes('invoice'))
    ).length;

    const userActions = logs.filter(
      log =>
        log.action &&
        (log.action.includes('user') ||
          log.action.includes('profile') ||
          log.action.includes('account'))
    ).length;

    setStats({
      totalLogs: logs.length,
      securityEvents,
      financialActions,
      userActions,
    });
  }

  function handleFilterChange(key: string, value: string) {
    setFilters(prev => ({ ...prev, [key]: value }));
  }

  function handleSearch() {
    setPagination(prev => ({ ...prev, page: 1 }));
    loadAuditLogs(1, true);
  }

  function handleLoadMore() {
    if (pagination.page < pagination.pages) {
      loadAuditLogs(pagination.page + 1, false);
    }
  }

  function viewLogDetails(log: AuditLog) {
    setSelectedLog(log);
    onOpen();
  }

  function getActionColor(action: string | null | undefined) {
    if (!action) return 'gray';

    if (action.includes('error') || action.includes('failed')) return 'red';
    if (action.includes('warning')) return 'yellow';
    if (action.includes('security') || action.includes('login'))
      return 'purple';
    if (action.includes('payment') || action.includes('financial'))
      return 'green';
    if (action.includes('create')) return 'blue';
    if (action.includes('update')) return 'orange';
    if (action.includes('delete')) return 'red';
    return 'gray';
  }

  function getEntityIcon(entity: string | null | undefined) {
    if (!entity) return <FiActivity />;

    switch (entity.toLowerCase()) {
      case 'user':
        return <FiUser />;
      case 'order':
        return <FiActivity />;
      case 'payment':
        return <FiShield />;
      default:
        return <FiActivity />;
    }
  }

  useEffect(() => {
    setMounted(true);
  }, []);

  useEffect(() => {
    if (mounted) {
      // Use a small delay to ensure consistent hydration
      const timer = setTimeout(() => {
        loadAuditLogs(1, true);
      }, 100);

      return () => clearTimeout(timer);
    }
  }, [mounted]);

  // Don't render until component is mounted and initial data is loaded to prevent hydration issues
  if (!mounted || (loading && logs.length === 0)) {
    return (
      <Box textAlign="center" py={20}>
        <Spinner size="xl" />
        <Text mt={4}>
          {!mounted ? 'Initializing...' : 'Loading audit logs...'}
        </Text>
      </Box>
    );
  }

  // Ensure logs is always an array to prevent hydration issues
  const safeLogs = Array.isArray(logs) ? logs : [];

  // Ensure pagination is properly initialized
  const safePagination = pagination || {
    page: 1,
    limit: 50,
    total: 0,
    pages: 0,
  };

  // Ensure stats is properly initialized
  const safeStats = stats || {
    totalLogs: 0,
    securityEvents: 0,
    financialActions: 0,
    userActions: 0,
  };

  // Ensure filters is properly initialized
  const safeFilters = filters || {
    search: '',
    action: '',
    entity: '',
    actorRole: '',
    from: '',
    to: '',
  };

  return (
    <Box>
      <HStack justify="space-between" mb={6}>
        <VStack align="start" spacing={1}>
          <Heading size="lg">Audit Log</Heading>
          <Text color="gray.600">
            Complete audit trail of all system activities
          </Text>
        </VStack>
        <HStack spacing={3}>
          <Button
            leftIcon={<FiRefreshCw />}
            variant="outline"
            size="sm"
            onClick={() => loadAuditLogs(1, true)}
          >
            Refresh
          </Button>
          <Button leftIcon={<FiDownload />} variant="outline" size="sm">
            Export
          </Button>
        </HStack>
      </HStack>

      {/* Stats Row */}
      {safeLogs.length > 0 && (
        <SimpleGrid columns={{ base: 1, md: 2, lg: 4 }} spacing={4} mb={6}>
          <Card>
            <CardBody>
              <Stat>
                <StatLabel>Total Logs</StatLabel>
                <StatNumber>
                  {(
                    safePagination.total ||
                    safeLogs.length ||
                    0
                  ).toLocaleString()}
                </StatNumber>
                <StatHelpText>
                  <FiActivity />
                  <span style={{ marginLeft: '4px' }}>All time</span>
                </StatHelpText>
              </Stat>
            </CardBody>
          </Card>

          <Card>
            <CardBody>
              <Stat>
                <StatLabel>Security Events</StatLabel>
                <StatNumber color="purple.500">
                  {safeStats.securityEvents}
                </StatNumber>
                <StatHelpText>
                  <FiShield />
                  <span style={{ marginLeft: '4px' }}>Last 24 hours</span>
                </StatHelpText>
              </Stat>
            </CardBody>
          </Card>

          <Card>
            <CardBody>
              <Stat>
                <StatLabel>Financial Actions</StatLabel>
                <StatNumber color="green.500">
                  {safeStats.financialActions}
                </StatNumber>
                <StatHelpText>
                  <FiActivity />
                  <span style={{ marginLeft: '4px' }}>Last 24 hours</span>
                </StatHelpText>
              </Stat>
            </CardBody>
          </Card>

          <Card>
            <CardBody>
              <Stat>
                <StatLabel>User Actions</StatLabel>
                <StatNumber color="blue.500">
                  {safeStats.userActions}
                </StatNumber>
                <StatHelpText>
                  <FiUser />
                  <span style={{ marginLeft: '4px' }}>Last 24 hours</span>
                </StatHelpText>
              </Stat>
            </CardBody>
          </Card>
        </SimpleGrid>
      )}

      {/* Filters */}
      {safeLogs.length > 0 && (
        <Card mb={6}>
          <CardBody>
            <VStack spacing={4}>
              <HStack justify="space-between" w="full">
                <Heading size="md">Filters</Heading>
                <Button
                  leftIcon={<FiFilter />}
                  colorScheme="blue"
                  size="sm"
                  onClick={handleSearch}
                >
                  Apply Filters
                </Button>
              </HStack>

              <SimpleGrid
                columns={{ base: 1, md: 2, lg: 3 }}
                spacing={4}
                w="full"
              >
                <InputGroup>
                  <InputLeftElement>
                    <FiSearch />
                  </InputLeftElement>
                  <Input
                    placeholder="Search logs..."
                    value={safeFilters.search}
                    onChange={e => handleFilterChange('search', e.target.value)}
                  />
                </InputGroup>

                <Select
                  placeholder="Filter by action"
                  value={safeFilters.action}
                  onChange={e => handleFilterChange('action', e.target.value)}
                >
                  <option value="login">Login Events</option>
                  <option value="payment">Payment Actions</option>
                  <option value="order">Order Actions</option>
                  <option value="user">User Actions</option>
                  <option value="security">Security Events</option>
                </Select>

                <Select
                  placeholder="Filter by entity"
                  value={safeFilters.entity}
                  onChange={e => handleFilterChange('entity', e.target.value)}
                >
                  <option value="user">Users</option>
                  <option value="order">Orders</option>
                  <option value="payment">Payments</option>
                  <option value="driver">Drivers</option>
                  <option value="customer">Customers</option>
                </Select>

                <Select
                  placeholder="Filter by role"
                  value={safeFilters.actorRole}
                  onChange={e =>
                    handleFilterChange('actorRole', e.target.value)
                  }
                >
                  <option value="admin">Admin</option>
                  <option value="driver">Driver</option>
                  <option value="customer">Customer</option>
                  <option value="system">System</option>
                </Select>

                <Input
                  type="date"
                  placeholder="From date"
                  value={safeFilters.from}
                  onChange={e => handleFilterChange('from', e.target.value)}
                />

                <Input
                  type="date"
                  placeholder="To date"
                  value={safeFilters.to}
                  onChange={e => handleFilterChange('to', e.target.value)}
                />
              </SimpleGrid>
            </VStack>
          </CardBody>
        </Card>
      )}

      {/* Error Alert */}
      {error && (
        <Alert status="error" mb={4}>
          <AlertIcon />
          <AlertTitle>Error!</AlertTitle>
          <AlertDescription>{error}</AlertDescription>
        </Alert>
      )}

      {/* Audit Logs Table */}
      {safeLogs.length > 0 ? (
        <Card>
          <CardBody>
            <Table variant="simple">
              <Thead>
                <Tr>
                  <Th>Timestamp</Th>
                  <Th>Actor</Th>
                  <Th>Role</Th>
                  <Th>Action</Th>
                  <Th>Entity</Th>
                  <Th>IP Address</Th>
                  <Th>Actions</Th>
                </Tr>
              </Thead>
              <Tbody>
                {loading && safeLogs.length === 0 ? (
                  <Tr key="loading">
                    <Td colSpan={7} textAlign="center">
                      <VStack spacing={2}>
                        <Spinner />
                        <Text>Loading audit logs...</Text>
                      </VStack>
                    </Td>
                  </Tr>
                ) : safeLogs.length === 0 ? (
                  <Tr key="empty">
                    <Td colSpan={7} textAlign="center">
                      <Text color="gray.500">No audit logs found</Text>
                    </Td>
                  </Tr>
                ) : (
                  safeLogs.map(log => (
                    <Tr key={log.id || `log-${Math.random()}`}>
                      <Td>
                        <VStack align="start" spacing={1}>
                          <Text fontSize="sm">
                            {log.timestamp
                              ? new Date(log.timestamp).toLocaleDateString()
                              : 'N/A'}
                          </Text>
                          <Text fontSize="xs" color="gray.600">
                            {log.timestamp
                              ? new Date(log.timestamp).toLocaleTimeString()
                              : 'N/A'}
                          </Text>
                        </VStack>
                      </Td>
                      <Td>
                        <HStack spacing={2}>
                          <FiUser size={12} />
                          <Text fontSize="sm">{log.actor || 'Unknown'}</Text>
                        </HStack>
                      </Td>
                      <Td>
                        <Badge colorScheme="blue" size="sm">
                          {log.actorRole || 'Unknown'}
                        </Badge>
                      </Td>
                      <Td>
                        <Badge
                          colorScheme={getActionColor(log.action || '')}
                          size="sm"
                        >
                          {log.action || 'Unknown'}
                        </Badge>
                      </Td>
                      <Td>
                        <HStack spacing={2}>
                          {getEntityIcon(log.entity)}
                          <Text fontSize="sm">
                            {log.entity || 'Unknown'}{' '}
                            {log.entityId ? `#${log.entityId}` : ''}
                          </Text>
                        </HStack>
                      </Td>
                      <Td>
                        <Text fontSize="sm" color="gray.600">
                          {log.ip || '-'}
                        </Text>
                      </Td>
                      <Td>
                        <Button
                          size="xs"
                          variant="outline"
                          leftIcon={<FiEye />}
                          onClick={() => log && viewLogDetails(log)}
                          isDisabled={!log}
                        >
                          View Details
                        </Button>
                      </Td>
                    </Tr>
                  ))
                )}
              </Tbody>
            </Table>

            {/* Load More */}
            {safeLogs.length > 0 &&
              safePagination.page < safePagination.pages && (
                <HStack justify="center" mt={4}>
                  <Button
                    onClick={handleLoadMore}
                    isLoading={loading}
                    loadingText="Loading..."
                    variant="outline"
                  >
                    Load More
                  </Button>
                </HStack>
              )}

            {loading && safeLogs.length > 0 && (
              <HStack justify="center" mt={4}>
                <Spinner />
                <Text>Loading more audit logs...</Text>
              </HStack>
            )}
          </CardBody>
        </Card>
      ) : (
        <Card>
          <CardBody>
            <Text textAlign="center" color="gray.500" py={8}>
              No audit logs available. Try adjusting your filters or refresh the
              page.
            </Text>
          </CardBody>
        </Card>
      )}

      {/* Log Details Modal */}
      <Modal isOpen={isOpen} onClose={onClose} size="xl">
        <ModalOverlay />
        <ModalContent>
          <ModalHeader>Audit Log Details</ModalHeader>
          <ModalCloseButton />
          <ModalBody pb={6}>
            {selectedLog ? (
              <VStack spacing={4} align="stretch">
                <SimpleGrid columns={2} spacing={4}>
                  <Box>
                    <Text fontWeight="bold">Actor</Text>
                    <Text>{selectedLog.actor || 'Unknown'}</Text>
                  </Box>
                  <Box>
                    <Text fontWeight="bold">Role</Text>
                    <Text>{selectedLog.actorRole || 'Unknown'}</Text>
                  </Box>
                  <Box>
                    <Text fontWeight="bold">Action</Text>
                    <Text>{selectedLog.action || 'Unknown'}</Text>
                  </Box>
                  <Box>
                    <Text fontWeight="bold">Entity</Text>
                    <Text>
                      {selectedLog.entity || 'Unknown'}{' '}
                      {selectedLog.entityId ? `#${selectedLog.entityId}` : ''}
                    </Text>
                  </Box>
                  <Box>
                    <Text fontWeight="bold">IP Address</Text>
                    <Text>{selectedLog.ip || 'N/A'}</Text>
                  </Box>
                  <Box>
                    <Text fontWeight="bold">User Agent</Text>
                    <Text fontSize="sm" noOfLines={2}>
                      {selectedLog.userAgent || 'N/A'}
                    </Text>
                  </Box>
                </SimpleGrid>

                {selectedLog.before && (
                  <Box>
                    <Text fontWeight="bold" mb={2}>
                      Before
                    </Text>
                    <Card variant="outline">
                      <CardBody>
                        <pre style={{ fontSize: '12px', overflow: 'auto' }}>
                          {JSON.stringify(selectedLog.before, null, 2)}
                        </pre>
                      </CardBody>
                    </Card>
                  </Box>
                )}

                {selectedLog.after && (
                  <Box>
                    <Text fontWeight="bold" mb={2}>
                      After
                    </Text>
                    <Card variant="outline">
                      <CardBody>
                        <pre style={{ fontSize: '12px', overflow: 'auto' }}>
                          {JSON.stringify(selectedLog.after, null, 2)}
                        </pre>
                      </CardBody>
                    </Card>
                  </Box>
                )}

                {selectedLog.details && (
                  <Box>
                    <Text fontWeight="bold" mb={2}>
                      Additional Details
                    </Text>
                    <Card variant="outline">
                      <CardBody>
                        <pre style={{ fontSize: '12px', overflow: 'auto' }}>
                          {JSON.stringify(selectedLog.details, null, 2)}
                        </pre>
                      </CardBody>
                    </Card>
                  </Box>
                )}
              </VStack>
            ) : (
              <Text textAlign="center" color="gray.500">
                No log details available
              </Text>
            )}
          </ModalBody>
        </ModalContent>
      </Modal>
    </Box>
  );
}

'use client';

/**
 * Bonus Requests Client Component
 * Dashboard for reviewing and approving driver bonus requests
 */

import { useEffect, useState, useCallback } from 'react';
import {
  Box,
  Container,
  Heading,
  Text,
  VStack,
  HStack,
  Card,
  CardBody,
  Button,
  Badge,
  Spinner,
  useToast,
  Stat,
  StatLabel,
  StatNumber,
  StatHelpText,
  SimpleGrid,
  Divider,
  Collapse,
  IconButton,
  Modal,
  ModalOverlay,
  ModalContent,
  ModalHeader,
  ModalFooter,
  ModalBody,
  ModalCloseButton,
  Textarea,
  NumberInput,
  NumberInputField,
  NumberInputStepper,
  NumberIncrementStepper,
  NumberDecrementStepper,
  Alert,
  AlertIcon,
  AlertTitle,
  AlertDescription,
  useDisclosure,
  Table,
  Thead,
  Tbody,
  Tr,
  Th,
  Td,
  TableContainer,
  Tabs,
  TabList,
  TabPanels,
  Tab,
  TabPanel,
  Input,
  FormControl,
  FormLabel,
  Select,
} from '@chakra-ui/react';
import { ChevronDownIcon, ChevronUpIcon, CheckIcon, CloseIcon, AddIcon } from '@chakra-ui/icons';
import Pusher from 'pusher-js';

// Types
interface BonusRequest {
  bonusRequestId: string;
  driver: {
    id: string;
    name: string;
    email: string;
    performance: {
      completedJobs30d: number;
      totalEarnings30dGBP: string;
      avgEarnings30dGBP: string;
    };
  };
  bonusDetails: {
    type: string;
    requestedAmountGBP: string;
    reason: string;
    requestedBy: string;
    requestedAt: string;
  };
  assignmentId?: string;
}

interface BonusModalData {
  bonusRequestId: string;
  driverName: string;
  action: 'approved' | 'rejected';
  requestedAmount: number;
}

interface NewBonusForm {
  driverId: string;
  assignmentId: string;
  bonusType: string;
  requestedAmountPence: number;
  reason: string;
  autoApprove: boolean;
}

export default function BonusRequestsClient() {
  const [bonuses, setBonuses] = useState<BonusRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [processingId, setProcessingId] = useState<string | null>(null);
  const [stats, setStats] = useState({
    totalPending: 0,
    totalAmountGBP: '0.00',
    avgRequestGBP: '0.00',
  });

  const { isOpen: isDecisionOpen, onOpen: onDecisionOpen, onClose: onDecisionClose } = useDisclosure();
  const { isOpen: isCreateOpen, onOpen: onCreateOpen, onClose: onCreateClose } = useDisclosure();
  
  const [modalData, setModalData] = useState<BonusModalData | null>(null);
  const [adminNotes, setAdminNotes] = useState('');
  const [approvedAmount, setApprovedAmount] = useState(0);

  // New bonus form
  const [newBonus, setNewBonus] = useState<NewBonusForm>({
    driverId: '',
    assignmentId: '',
    bonusType: 'manual_admin_bonus',
    requestedAmountPence: 0,
    reason: '',
    autoApprove: false,
  });

  const toast = useToast();

  // Fetch pending bonuses
  const fetchBonuses = useCallback(async () => {
    try {
      const response = await fetch('/api/admin/bonuses/pending');
      if (!response.ok) throw new Error('Failed to fetch bonus requests');

      const data = await response.json();
      setBonuses(data.pendingBonuses || []);

      // Calculate stats
      const totalPending = data.count || 0;
      const totalAmount = data.pendingBonuses
        ?.reduce((sum: number, item: BonusRequest) => sum + parseFloat(item.bonusDetails.requestedAmountGBP), 0) || 0;
      const avgRequest = totalPending > 0 ? totalAmount / totalPending : 0;

      setStats({
        totalPending,
        totalAmountGBP: totalAmount.toFixed(2),
        avgRequestGBP: avgRequest.toFixed(2),
      });
    } catch (error) {
      console.error('Error fetching bonuses:', error);
      toast({
        title: 'Error loading data',
        description: 'Failed to load bonus requests',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setLoading(false);
    }
  }, [toast]);

  // Setup Pusher real-time updates
  useEffect(() => {
    fetchBonuses();

    // Initialize Pusher
    const PUSHER_KEY = '407cb06c423e6c032e9c';
    const PUSHER_CLUSTER = 'eu';
    const pusher = new Pusher(PUSHER_KEY, {
      cluster: PUSHER_CLUSTER,
    });

    const channel = pusher.subscribe('admin-notifications');
    
    channel.bind('bonus-request-created', (data: any) => {
      console.log('🔔 New bonus request:', data);
      toast({
        title: 'New bonus request',
        description: `Bonus request from driver ${data.driverId}`,
        status: 'info',
        duration: 10000,
        isClosable: true,
      });
      fetchBonuses();
    });

    channel.bind('bonus-decision', () => {
      fetchBonuses();
    });

    return () => {
      channel.unbind_all();
      channel.unsubscribe();
      pusher.disconnect();
    };
  }, [fetchBonuses, toast]);

  // Open decision modal
  const handleOpenDecisionModal = (bonus: BonusRequest, action: 'approved' | 'rejected') => {
    setModalData({
      bonusRequestId: bonus.bonusRequestId,
      driverName: bonus.driver.name,
      action,
      requestedAmount: parseFloat(bonus.bonusDetails.requestedAmountGBP),
    });
    setApprovedAmount(parseFloat(bonus.bonusDetails.requestedAmountGBP));
    setAdminNotes('');
    onDecisionOpen();
  };

  // Submit bonus decision
  const handleSubmitDecision = async () => {
    if (!modalData) return;

    setProcessingId(modalData.bonusRequestId);

    try {
      const response = await fetch(`/api/admin/bonuses/${modalData.bonusRequestId}/approve`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: modalData.action,
          approved_amount_pence: modalData.action === 'approved' ? Math.round(approvedAmount * 100) : undefined,
          admin_notes: adminNotes || undefined,
        }),
      });

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.message || 'Failed to process decision');
      }

      const result = await response.json();

      toast({
        title: modalData.action === 'approved' ? 'Approved successfully' : 'Rejected',
        description:
          modalData.action === 'approved'
            ? `Bonus of £${approvedAmount.toFixed(2)} approved for driver ${modalData.driverName}`
            : `Bonus request rejected for driver ${modalData.driverName}`,
        status: 'success',
        duration: 5000,
        isClosable: true,
      });

      onDecisionClose();
      fetchBonuses();
    } catch (error: any) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to process decision',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setProcessingId(null);
    }
  };

  // Create manual bonus
  const handleCreateBonus = async () => {
    try {
      const response = await fetch('/api/admin/bonuses/request', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          driver_id: newBonus.driverId,
          assignment_id: newBonus.assignmentId,
          bonus_type: newBonus.bonusType,
          requested_amount_pence: newBonus.requestedAmountPence,
          reason: newBonus.reason,
          auto_approve: newBonus.autoApprove,
        }),
      });

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.message || 'Failed to create bonus');
      }

      const result = await response.json();

      toast({
        title: 'Bonus created successfully',
        description: newBonus.autoApprove
          ? `Bonus of £${(newBonus.requestedAmountPence / 100).toFixed(2)} approved automatically`
          : 'Bonus request created and is awaiting approval',
        status: 'success',
        duration: 5000,
        isClosable: true,
      });

      onCreateClose();
      setNewBonus({
        driverId: '',
        assignmentId: '',
        bonusType: 'manual_admin_bonus',
        requestedAmountPence: 0,
        reason: '',
        autoApprove: false,
      });
      fetchBonuses();
    } catch (error: any) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to create bonus',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    }
  };

  const getBonusTypeLabel = (type: string) => {
    const types: Record<string, string> = {
      exceptional_service: 'Exceptional Service',
      manual_admin_bonus: 'Admin Bonus',
      referral_bonus: 'Referral Bonus',
      milestone_bonus: 'Milestone Bonus',
    };
    return types[type] || type;
  };

  const getBonusTypeColor = (type: string) => {
    const colors: Record<string, string> = {
      exceptional_service: 'green',
      manual_admin_bonus: 'blue',
      referral_bonus: 'purple',
      milestone_bonus: 'orange',
    };
    return colors[type] || 'gray';
  };

  if (loading) {
    return (
      <Container maxW="container.xl" py={8}>
        <VStack spacing={4}>
          <Spinner size="xl" color="blue.500" />
          <Text>Loading bonus requests...</Text>
        </VStack>
      </Container>
    );
  }

  return (
    <Container maxW="container.xl" py={8}>
      <VStack spacing={6} align="stretch">
        {/* Header */}
        <HStack justify="space-between">
          <Box>
            <Heading size="lg" mb={2}>
              Bonus Requests
            </Heading>
            <Text color="gray.600">Review and approve driver bonus requests</Text>
          </Box>
          <Button leftIcon={<AddIcon />} colorScheme="blue" onClick={onCreateOpen}>
            Create Bonus
          </Button>
        </HStack>

        {/* Stats Cards */}
        <SimpleGrid columns={{ base: 1, md: 3 }} spacing={4}>
          <Card>
            <CardBody>
              <Stat>
                <StatLabel>Pending Requests</StatLabel>
                <StatNumber>{stats.totalPending}</StatNumber>
                <StatHelpText>Awaiting approval</StatHelpText>
              </Stat>
            </CardBody>
          </Card>

          <Card>
            <CardBody>
              <Stat>
                <StatLabel>Total Pending Bonuses</StatLabel>
                <StatNumber>£{stats.totalAmountGBP}</StatNumber>
                <StatHelpText>Sum of requests</StatHelpText>
              </Stat>
            </CardBody>
          </Card>

          <Card>
            <CardBody>
              <Stat>
                <StatLabel>Average Bonus Request</StatLabel>
                <StatNumber>£{stats.avgRequestGBP}</StatNumber>
                <StatHelpText>Per request</StatHelpText>
              </Stat>
            </CardBody>
          </Card>
        </SimpleGrid>

        {/* No Bonuses */}
        {bonuses.length === 0 && (
          <Alert status="success" borderRadius="md">
            <AlertIcon />
            <AlertTitle>No pending bonus requests</AlertTitle>
            <AlertDescription>All bonus requests have been processed!</AlertDescription>
          </Alert>
        )}

        {/* Bonuses List */}
        {bonuses.map((bonus) => (
          <Card key={bonus.bonusRequestId} variant="outline">
            <CardBody>
              <VStack spacing={4} align="stretch">
                {/* Header Row */}
                <HStack justify="space-between">
                  <HStack spacing={4}>
                    <Box>
                      <Text fontWeight="bold" fontSize="lg">
                        {bonus.driver.name}
                      </Text>
                      <Text fontSize="sm" color="gray.600">
                        {bonus.driver.email}
                      </Text>
                    </Box>
                    <Badge colorScheme={getBonusTypeColor(bonus.bonusDetails.type)} fontSize="sm">
                      {getBonusTypeLabel(bonus.bonusDetails.type)}
                    </Badge>
                  </HStack>

                  <HStack>
                    <Badge colorScheme="purple" fontSize="md" px={3} py={1}>
                      £{bonus.bonusDetails.requestedAmountGBP}
                    </Badge>
                    <IconButton
                      aria-label="Toggle details"
                      icon={expandedId === bonus.bonusRequestId ? <ChevronUpIcon /> : <ChevronDownIcon />}
                      size="sm"
                      variant="ghost"
                      onClick={() => setExpandedId(expandedId === bonus.bonusRequestId ? null : bonus.bonusRequestId)}
                    />
                  </HStack>
                </HStack>

                {/* Quick Info */}
                <SimpleGrid columns={{ base: 1, md: 3 }} spacing={4}>
                  <Box>
                    <Text fontSize="xs" color="gray.600">
                      Completed Jobs (30 days)
                    </Text>
                    <Text fontWeight="bold" fontSize="lg">
                      {bonus.driver.performance.completedJobs30d}
                    </Text>
                  </Box>
                  <Box>
                    <Text fontSize="xs" color="gray.600">
                      Total Earnings (30 days)
                    </Text>
                    <Text fontWeight="bold" fontSize="lg" color="green.500">
                      £{bonus.driver.performance.totalEarnings30dGBP}
                    </Text>
                  </Box>
                  <Box>
                    <Text fontSize="xs" color="gray.600">
                      Average Earnings
                    </Text>
                    <Text fontWeight="bold" fontSize="lg">
                      £{bonus.driver.performance.avgEarnings30dGBP}
                    </Text>
                  </Box>
                </SimpleGrid>

                {/* Expanded Details */}
                <Collapse in={expandedId === bonus.bonusRequestId} animateOpacity>
                  <VStack spacing={3} align="stretch" pt={2}>
                    <Divider />
                    <Box>
                      <Text fontSize="sm" fontWeight="bold" mb={2}>
                        Bonus Request Reason:
                      </Text>
                      <Text fontSize="sm" color="gray.700" bg="gray.50" p={3} borderRadius="md">
                        {bonus.bonusDetails.reason}
                      </Text>
                    </Box>
                    <SimpleGrid columns={{ base: 1, md: 2 }} spacing={3}>
                      <Box>
                        <Text fontSize="xs" color="gray.600">
                          Request Date
                        </Text>
                        <Text fontSize="sm">{new Date(bonus.bonusDetails.requestedAt).toLocaleString('ar-EG')}</Text>
                      </Box>
                      <Box>
                        <Text fontSize="xs" color="gray.600">
                          Requested By
                        </Text>
                        <Text fontSize="sm">
                          {bonus.bonusDetails.requestedBy === 'system_auto' ? 'Automatic System' : bonus.bonusDetails.requestedBy}
                        </Text>
                      </Box>
                    </SimpleGrid>
                  </VStack>
                </Collapse>

                {/* Action Buttons */}
                <HStack spacing={3} pt={2}>
                  <Button
                    colorScheme="green"
                    leftIcon={<CheckIcon />}
                    flex={1}
                    isDisabled={processingId === bonus.bonusRequestId}
                    onClick={() => handleOpenDecisionModal(bonus, 'approved')}
                  >
                    Approve
                  </Button>
                  <Button
                    colorScheme="red"
                    leftIcon={<CloseIcon />}
                    flex={1}
                    isDisabled={processingId === bonus.bonusRequestId}
                    onClick={() => handleOpenDecisionModal(bonus, 'rejected')}
                  >
                    Reject
                  </Button>
                </HStack>
              </VStack>
            </CardBody>
          </Card>
        ))}
      </VStack>

      {/* Decision Modal */}
      <Modal isOpen={isDecisionOpen} onClose={onDecisionClose} size="lg">
        <ModalOverlay />
        <ModalContent>
          <ModalHeader>
            {modalData?.action === 'approved' ? 'Approve Bonus' : 'Reject Bonus'}
          </ModalHeader>
          <ModalCloseButton />
          <ModalBody>
            <VStack spacing={4} align="stretch">
              <Box>
                <Text fontWeight="bold">Driver: {modalData?.driverName}</Text>
              </Box>

              {modalData?.action === 'approved' && (
                <Box>
                  <Text mb={2} fontWeight="bold">
                    Approved Amount (£)
                  </Text>
                  <NumberInput
                    value={approvedAmount}
                    onChange={(_, valueAsNumber) => setApprovedAmount(valueAsNumber)}
                    min={0}
                    max={modalData?.requestedAmount || 0}
                    step={0.01}
                    precision={2}
                  >
                    <NumberInputField />
                    <NumberInputStepper>
                      <NumberIncrementStepper />
                      <NumberDecrementStepper />
                    </NumberInputStepper>
                  </NumberInput>
                  <Text fontSize="xs" color="gray.600" mt={1}>
                    Requested amount: £{(modalData?.requestedAmount || 0).toFixed(2)}
                  </Text>
                </Box>
              )}

              <Box>
                <Text mb={2} fontWeight="bold">
                  Admin Notes (optional)
                </Text>
                <Textarea
                  value={adminNotes}
                  onChange={(e) => setAdminNotes(e.target.value)}
                  placeholder="Add any notes..."
                  rows={3}
                />
              </Box>

              {modalData?.action === 'rejected' && (
                <Alert status="warning" borderRadius="md">
                  <AlertIcon />
                  <AlertDescription fontSize="sm">
                    The driver will be notified of the bonus rejection. It's recommended to add the reason for rejection in the notes.
                  </AlertDescription>
                </Alert>
              )}
            </VStack>
          </ModalBody>

          <ModalFooter>
            <Button variant="ghost" mr={3} onClick={onDecisionClose}>
              Cancel
            </Button>
            <Button
              colorScheme={modalData?.action === 'approved' ? 'green' : 'red'}
              isLoading={processingId === modalData?.bonusRequestId}
              onClick={handleSubmitDecision}
            >
              {modalData?.action === 'approved' ? 'Confirm Approval' : 'Confirm Rejection'}
            </Button>
          </ModalFooter>
        </ModalContent>
      </Modal>

      {/* Create Bonus Modal */}
      <Modal isOpen={isCreateOpen} onClose={onCreateClose} size="lg">
        <ModalOverlay />
        <ModalContent>
          <ModalHeader>Create New Bonus</ModalHeader>
          <ModalCloseButton />
          <ModalBody>
            <VStack spacing={4} align="stretch">
              <FormControl isRequired>
                <FormLabel>Driver ID</FormLabel>
                <Input
                  value={newBonus.driverId}
                  onChange={(e) => setNewBonus({ ...newBonus, driverId: e.target.value })}
                  placeholder="Enter driver ID"
                />
              </FormControl>

              <FormControl isRequired>
                <FormLabel>Assignment ID (optional)</FormLabel>
                <Input
                  value={newBonus.assignmentId}
                  onChange={(e) => setNewBonus({ ...newBonus, assignmentId: e.target.value })}
                  placeholder="Enter assignment ID"
                />
              </FormControl>

              <FormControl isRequired>
                <FormLabel>Bonus Type</FormLabel>
                <Select
                  value={newBonus.bonusType}
                  onChange={(e) => setNewBonus({ ...newBonus, bonusType: e.target.value })}
                >
                  <option value="manual_admin_bonus">Admin Bonus</option>
                  <option value="exceptional_service">Exceptional Service</option>
                  <option value="milestone_bonus">Milestone Bonus</option>
                  <option value="referral_bonus">Referral Bonus</option>
                </Select>
              </FormControl>

              <FormControl isRequired>
                <FormLabel>Amount (£)</FormLabel>
                <NumberInput
                  value={newBonus.requestedAmountPence / 100}
                  onChange={(_, valueAsNumber) =>
                    setNewBonus({ ...newBonus, requestedAmountPence: Math.round(valueAsNumber * 100) })
                  }
                  min={0}
                  step={0.01}
                  precision={2}
                >
                  <NumberInputField />
                  <NumberInputStepper>
                    <NumberIncrementStepper />
                    <NumberDecrementStepper />
                  </NumberInputStepper>
                </NumberInput>
              </FormControl>

              <FormControl isRequired>
                <FormLabel>Reason</FormLabel>
                <Textarea
                  value={newBonus.reason}
                  onChange={(e) => setNewBonus({ ...newBonus, reason: e.target.value })}
                  placeholder="Explain the reason for granting this bonus..."
                  rows={3}
                />
              </FormControl>

              <FormControl>
                <HStack>
                  <input
                    type="checkbox"
                    checked={newBonus.autoApprove}
                    onChange={(e) => setNewBonus({ ...newBonus, autoApprove: e.target.checked })}
                  />
                  <FormLabel mb={0}>Auto-approve (bonus will be applied immediately)</FormLabel>
                </HStack>
              </FormControl>

              {!newBonus.autoApprove && (
                <Alert status="info" borderRadius="md">
                  <AlertIcon />
                  <AlertDescription fontSize="sm">
                    The bonus request will be created and will appear in the pending requests list for approval later.
                  </AlertDescription>
                </Alert>
              )}
            </VStack>
          </ModalBody>

          <ModalFooter>
            <Button variant="ghost" mr={3} onClick={onCreateClose}>
              Cancel
            </Button>
            <Button
              colorScheme="blue"
              onClick={handleCreateBonus}
              isDisabled={
                !newBonus.driverId ||
                !newBonus.assignmentId ||
                !newBonus.reason ||
                newBonus.requestedAmountPence <= 0
              }
            >
              Create Bonus
            </Button>
          </ModalFooter>
        </ModalContent>
      </Modal>
    </Container>
  );
}

'use client';

import { useState, useEffect } from 'react';
import {
  Box,
  Container,
  Heading,
  Text,
  Table,
  Thead,
  Tbody,
  Tr,
  Th,
  Td,
  Badge,
  Button,
  useToast,
  Select,
  HStack,
  Modal,
  ModalOverlay,
  ModalContent,
  ModalHeader,
  ModalBody,
  ModalFooter,
  ModalCloseButton,
  useDisclosure,
  VStack,
  Textarea,
  Link,
  Spinner,
  Card,
  CardBody,
  Icon,
  IconButton,
} from '@chakra-ui/react';
import { FiEye, FiCheck, FiX, FiDownload, FiBriefcase } from 'react-icons/fi';

interface Application {
  id: string;
  fullName: string;
  email: string;
  phone: string;
  position: string;
  cvUrl: string;
  coverLetter: string;
  status: string;
  createdAt: string;
  reviewedBy?: string;
  reviewedAt?: string;
  rejectionReason?: string;
  contractSent: boolean;
  contractSentAt?: string;
}

const STATUS_COLORS: Record<string, string> = {
  pending: 'yellow',
  under_review: 'blue',
  approved: 'green',
  rejected: 'red',
  contract_sent: 'purple',
};

export default function AdminCareersPage() {
  const [applications, setApplications] = useState<Application[]>([]);
  const [filteredApplications, setFilteredApplications] = useState<Application[]>([]);
  const [statusFilter, setStatusFilter] = useState('all');
  const [selectedApplication, setSelectedApplication] = useState<Application | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [actionLoading, setActionLoading] = useState(false);
  const [rejectionReason, setRejectionReason] = useState('');

  const { isOpen, onOpen, onClose } = useDisclosure();
  const {
    isOpen: isRejectOpen,
    onOpen: onRejectOpen,
    onClose: onRejectClose,
  } = useDisclosure();

  const toast = useToast();

  useEffect(() => {
    fetchApplications();
  }, []);

  useEffect(() => {
    if (statusFilter === 'all') {
      setFilteredApplications(applications);
    } else {
      setFilteredApplications(
        applications.filter((app) => app.status === statusFilter)
      );
    }
  }, [statusFilter, applications]);

  const fetchApplications = async () => {
    try {
      setIsLoading(true);
      console.log('📋 Fetching career applications...');
      
      const response = await fetch('/api/admin/careers');
      console.log('📡 Response status:', response.status);
      
      const data = await response.json();
      console.log('📦 Response data:', data);

      if (data.success) {
        setApplications(data.data.applications);
        console.log('✅ Applications loaded:', data.data.applications.length);
      } else {
        console.error('❌ API returned error:', data.error);
        throw new Error(data.error || 'Failed to fetch applications');
      }
    } catch (error: any) {
      console.error('❌ Fetch error:', error);
      toast({
        title: 'Error Loading Applications',
        description: error.message || 'Failed to fetch applications. Please check console for details.',
        status: 'error',
        duration: 7000,
        isClosable: true,
      });
      // Set empty array so UI shows "no applications" instead of loading forever
      setApplications([]);
    } finally {
      setIsLoading(false);
    }
  };

  const handleViewDetails = (application: Application) => {
    setSelectedApplication(application);
    onOpen();
  };

  const handleApprove = async (id: string) => {
    if (
      !confirm(
        'Are you sure you want to approve this application and send the employment contract?'
      )
    ) {
      return;
    }

    try {
      setActionLoading(true);
      const response = await fetch(`/api/admin/careers/${id}/approve`, {
        method: 'POST',
      });

      const data = await response.json();

      if (data.success) {
        toast({
          title: 'Application Approved',
          description: 'Employment contract has been sent to the applicant.',
          status: 'success',
          duration: 5000,
        });
        fetchApplications();
        onClose();
      } else {
        throw new Error(data.error);
      }
    } catch (error: any) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to approve application',
        status: 'error',
        duration: 5000,
      });
    } finally {
      setActionLoading(false);
    }
  };

  const handleReject = async () => {
    if (!selectedApplication) return;

    try {
      setActionLoading(true);
      const response = await fetch(
        `/api/admin/careers/${selectedApplication.id}/reject`,
        {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({ reason: rejectionReason }),
        }
      );

      const data = await response.json();

      if (data.success) {
        toast({
          title: 'Application Rejected',
          description: 'Rejection email has been sent to the applicant.',
          status: 'success',
          duration: 5000,
        });
        setRejectionReason('');
        fetchApplications();
        onClose();
        onRejectClose();
      } else {
        throw new Error(data.error);
      }
    } catch (error: any) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to reject application',
        status: 'error',
        duration: 5000,
      });
    } finally {
      setActionLoading(false);
    }
  };

  const openRejectModal = (application: Application) => {
    setSelectedApplication(application);
    onRejectOpen();
  };

  if (isLoading) {
    return (
      <Box textAlign="center" py={20} bg="bg.surface" minH="100vh">
        <Spinner size="xl" color="neon.500" />
        <Text mt={4} color="text.primary">Loading applications...</Text>
      </Box>
    );
  }

  return (
    <Box bg="bg.surface" minH="100vh" p={6}>
      <Container maxW="container.xl">
        <VStack align="stretch" spacing={6}>
          {/* Header */}
          <HStack justify="space-between" align="center">
            <HStack>
              <Icon as={FiBriefcase} boxSize={8} color="neon.500" />
              <Heading size="lg" color="text.primary">Career Applications</Heading>
            </HStack>
            <Badge colorScheme="blue" fontSize="md" px={3} py={1}>
              {applications.length} Total
            </Badge>
          </HStack>

          {/* Filter */}
          <Card bg="bg.surface" border="1px solid" borderColor="border.primary">
            <CardBody>
            <HStack>
              <Text fontWeight="bold" color="text.primary">Filter by Status:</Text>
              <Select
                value={statusFilter}
                onChange={(e) => setStatusFilter(e.target.value)}
                maxW="250px"
                bg="gray.700"
                color="text.primary"
                borderColor="border.primary"
                sx={{
                  option: {
                    bg: 'gray.800',
                    color: 'white',
                  }
                }}
              >
                <option value="all">All Applications</option>
                <option value="pending">Pending</option>
                <option value="under_review">Under Review</option>
                <option value="approved">Approved</option>
                <option value="rejected">Rejected</option>
                <option value="contract_sent">Contract Sent</option>
              </Select>
              <Text color="text.secondary">
                ({filteredApplications.length} showing)
              </Text>
            </HStack>
          </CardBody>
        </Card>

        {/* Applications Table */}
        <Card bg="bg.surface" border="1px solid" borderColor="border.primary">
          <CardBody p={0}>
            <Box overflowX="auto">
              <Table variant="simple">
                <Thead bg="bg.surface" borderBottom="1px solid" borderColor="border.primary">
                  <Tr>
                    <Th color="text.primary">Date</Th>
                    <Th color="text.primary">Name</Th>
                    <Th color="text.primary">Position</Th>
                    <Th color="text.primary">Email</Th>
                    <Th color="text.primary">Phone</Th>
                    <Th color="text.primary">Status</Th>
                    <Th color="text.primary">Actions</Th>
                  </Tr>
                </Thead>
                <Tbody>
                  {filteredApplications.length === 0 ? (
                    <Tr>
                      <Td colSpan={7} textAlign="center" py={10}>
                        <Text color="text.secondary">No applications found</Text>
                      </Td>
                    </Tr>
                  ) : (
                    filteredApplications.map((app) => (
                      <Tr key={app.id} _hover={{ bg: 'gray.700' }}>
                        <Td color="text.secondary">
                          {new Date(app.createdAt).toLocaleDateString('en-GB')}
                        </Td>
                        <Td fontWeight="bold" color="text.primary">{app.fullName}</Td>
                        <Td color="text.secondary">{app.position}</Td>
                        <Td color="text.secondary">{app.email}</Td>
                        <Td color="text.secondary">{app.phone}</Td>
                        <Td>
                          <Badge colorScheme={STATUS_COLORS[app.status]}>
                            {app.status.replace('_', ' ').toUpperCase()}
                          </Badge>
                        </Td>
                        <Td>
                          <HStack spacing={2}>
                            <IconButton
                              aria-label="View details"
                              icon={<FiEye />}
                              size="sm"
                              onClick={() => handleViewDetails(app)}
                            />
                            {app.status === 'pending' ||
                            app.status === 'under_review' ? (
                              <>
                                <IconButton
                                  aria-label="Approve"
                                  icon={<FiCheck />}
                                  colorScheme="green"
                                  size="sm"
                                  onClick={() => handleApprove(app.id)}
                                  isLoading={actionLoading}
                                />
                                <IconButton
                                  aria-label="Reject"
                                  icon={<FiX />}
                                  colorScheme="red"
                                  size="sm"
                                  onClick={() => openRejectModal(app)}
                                  isLoading={actionLoading}
                                />
                              </>
                            ) : null}
                            <IconButton
                              aria-label="Download CV"
                              icon={<FiDownload />}
                              as="a"
                              href={app.cvUrl}
                              target="_blank"
                              size="sm"
                              variant="outline"
                            />
                          </HStack>
                        </Td>
                      </Tr>
                    ))
                  )}
                </Tbody>
              </Table>
            </Box>
          </CardBody>
        </Card>
        </VStack>
      </Container>

      {/* View Details Modal */}
      <Modal isOpen={isOpen} onClose={onClose} size="xl">
        <ModalOverlay />
        <ModalContent bg="bg.surface" borderColor="border.primary" border="1px solid">
          <ModalHeader color="text.primary">Application Details</ModalHeader>
          <ModalCloseButton color="text.primary" />
          <ModalBody>
            {selectedApplication && (
              <VStack align="stretch" spacing={4}>
                <Box>
                  <Text fontWeight="bold" color="text.primary">Full Name:</Text>
                  <Text color="text.secondary">{selectedApplication.fullName}</Text>
                </Box>
                <Box>
                  <Text fontWeight="bold" color="text.primary">Email:</Text>
                  <Text color="text.secondary">{selectedApplication.email}</Text>
                </Box>
                <Box>
                  <Text fontWeight="bold" color="text.primary">Phone:</Text>
                  <Text color="text.secondary">{selectedApplication.phone}</Text>
                </Box>
                <Box>
                  <Text fontWeight="bold" color="text.primary">Position:</Text>
                  <Text color="text.secondary">{selectedApplication.position}</Text>
                </Box>
                <Box>
                  <Text fontWeight="bold" color="text.primary">Status:</Text>
                  <Badge colorScheme={STATUS_COLORS[selectedApplication.status]}>
                    {selectedApplication.status.replace('_', ' ').toUpperCase()}
                  </Badge>
                </Box>
                <Box>
                  <Text fontWeight="bold" color="text.primary">Applied On:</Text>
                  <Text color="text.secondary">
                    {new Date(selectedApplication.createdAt).toLocaleString('en-GB')}
                  </Text>
                </Box>
                <Box>
                  <Text fontWeight="bold" color="text.primary">Cover Letter:</Text>
                  <Box
                    p={4}
                    bg="gray.700"
                    border="1px solid"
                    borderColor="border.primary"
                    borderRadius="md"
                    maxH="200px"
                    overflowY="auto"
                  >
                    <Text whiteSpace="pre-wrap" color="text.secondary">{selectedApplication.coverLetter}</Text>
                  </Box>
                </Box>
                <Box>
                  <Text fontWeight="bold" color="text.primary">CV:</Text>
                  <Button
                    as="a"
                    href={selectedApplication.cvUrl}
                    target="_blank"
                    leftIcon={<FiDownload />}
                    size="sm"
                    variant="outline"
                    colorScheme="blue"
                  >
                    Download CV
                  </Button>
                </Box>
                {selectedApplication.reviewedBy && (
                  <>
                    <Box>
                      <Text fontWeight="bold" color="text.primary">Reviewed By:</Text>
                      <Text color="text.secondary">{selectedApplication.reviewedBy}</Text>
                    </Box>
                    <Box>
                      <Text fontWeight="bold" color="text.primary">Reviewed At:</Text>
                      <Text color="text.secondary">
                        {new Date(selectedApplication.reviewedAt!).toLocaleString(
                          'en-GB'
                        )}
                      </Text>
                    </Box>
                  </>
                )}
                {selectedApplication.rejectionReason && (
                  <Box>
                    <Text fontWeight="bold" color="text.primary">Rejection Reason:</Text>
                    <Box p={4} bg="red.900" borderColor="red.500" border="1px solid" borderRadius="md">
                      <Text color="red.200">{selectedApplication.rejectionReason}</Text>
                    </Box>
                  </Box>
                )}
                {selectedApplication.contractSent && (
                  <Box>
                    <Text fontWeight="bold" color="green.400">
                      ✓ Employment contract sent on:{' '}
                      {new Date(selectedApplication.contractSentAt!).toLocaleString(
                        'en-GB'
                      )}
                    </Text>
                  </Box>
                )}
              </VStack>
            )}
          </ModalBody>
          <ModalFooter>
            {selectedApplication &&
              (selectedApplication.status === 'pending' ||
                selectedApplication.status === 'under_review') && (
                <>
                  <Button
                    colorScheme="green"
                    mr={3}
                    onClick={() => handleApprove(selectedApplication.id)}
                    isLoading={actionLoading}
                    leftIcon={<FiCheck />}
                  >
                    Approve & Send Contract
                  </Button>
                  <Button
                    colorScheme="red"
                    mr={3}
                    onClick={() => openRejectModal(selectedApplication)}
                    leftIcon={<FiX />}
                  >
                    Reject
                  </Button>
                </>
              )}
            <Button variant="ghost" onClick={onClose}>
              Close
            </Button>
          </ModalFooter>
        </ModalContent>
      </Modal>

      {/* Reject Modal */}
      <Modal isOpen={isRejectOpen} onClose={onRejectClose}>
        <ModalOverlay />
        <ModalContent bg="bg.surface" borderColor="border.primary" border="1px solid">
          <ModalHeader color="text.primary">Reject Application</ModalHeader>
          <ModalCloseButton color="text.primary" />
          <ModalBody>
            <VStack align="stretch" spacing={4}>
              <Text color="text.secondary">
                Are you sure you want to reject this application? You can optionally
                provide a reason that will be sent to the applicant.
              </Text>
              <Textarea
                value={rejectionReason}
                onChange={(e) => setRejectionReason(e.target.value)}
                placeholder="Reason for rejection (optional)"
                rows={4}
                bg="gray.700"
                color="text.primary"
                borderColor="border.primary"
                _placeholder={{ color: 'text.tertiary' }}
              />
            </VStack>
          </ModalBody>
          <ModalFooter>
            <Button
              colorScheme="red"
              mr={3}
              onClick={handleReject}
              isLoading={actionLoading}
            >
              Confirm Rejection
            </Button>
            <Button variant="ghost" onClick={onRejectClose} color="text.secondary">
              Cancel
            </Button>
          </ModalFooter>
        </ModalContent>
      </Modal>
    </Box>
  );
}

'use client';

import React, { useState, useEffect, useRef } from 'react';
import {
  Box,
  Heading,
  VStack,
  HStack,
  Text,
  Card,
  CardBody,
  Button,
  Avatar,
  Badge,
  Flex,
  Textarea,
  useToast,
  Spinner,
  Icon,
  Grid,
  Tabs,
  TabList,
  TabPanels,
  Tab,
  TabPanel,
  Alert,
  AlertIcon,
  AlertDescription,
  IconButton,
  Tooltip,
} from '@chakra-ui/react';
import {
  FiMessageSquare,
  FiSend,
  FiUser,
  FiCheck,
  FiShield,
  FiTruck,
  FiLock,
  FiUnlock,
  FiArchive,
} from 'react-icons/fi';
import Pusher from 'pusher-js';
import { closeChat, reopenChat, fetchActiveChats, fetchArchivedChats } from '@/lib/chat-helpers';

interface ChatMessage {
  id: string;
  senderId: string;
  senderName: string;
  senderRole: string;
  message: string;
  timestamp: string;
  read: boolean;
}

interface ChatConversation {
  id: string;
  participants: Array<{
    id: string;
    name: string;
    role: string;
  }>;
  lastMessage: ChatMessage | null;
  unreadCount: number;
  updatedAt: string;
  isActive: boolean;
  closedAt?: string;
  closedBy?: {
    id: string;
    name: string;
    role: string;
  };
}

export default function EnhancedAdminChatPage() {
  const [activeConversations, setActiveConversations] = useState<ChatConversation[]>([]);
  const [archivedConversations, setArchivedConversations] = useState<ChatConversation[]>([]);
  const [selectedConversation, setSelectedConversation] = useState<ChatConversation | null>(null);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [newMessage, setNewMessage] = useState('');
  const [loading, setLoading] = useState(true);
  const [sending, setSending] = useState(false);
  const [otherUserTyping, setOtherUserTyping] = useState(false);
  const [tabIndex, setTabIndex] = useState(0);
  const [isTyping, setIsTyping] = useState(false);
  const toast = useToast();
  const pusherRef = useRef<Pusher | null>(null);
  const channelRef = useRef<any>(null);
  const processedMessageIds = useRef<Set<string>>(new Set());
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const typingTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const typingIndicatorTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    let mounted = true;
    
    if (mounted) {
      loadAllChats();
      setupPusher();
      
      // Broadcast admin online status
      broadcastAdminStatus('online');
    }

    return () => {
      mounted = false;
      // Broadcast offline status before cleanup
      broadcastAdminStatus('offline');
      cleanupPusher();
    };
  }, []);

  const loadAllChats = async () => {
    try {
      setLoading(true);
      const [activeData, archivedData] = await Promise.all([
        fetchActiveChats(),
        fetchArchivedChats(),
      ]);

      if (activeData.success) {
        setActiveConversations(activeData.chats || []);
      }

      if (archivedData.success) {
        setArchivedConversations(archivedData.chats || []);
      }
    } catch (error) {
      console.error('Error loading chats:', error);
      toast({
        title: 'Error',
        description: 'Failed to load conversations',
        status: 'error',
        duration: 5000,
      });
    } finally {
      setLoading(false);
    }
  };

  const setupPusher = () => {
    const pusherKey = '407cb06c423e6c032e9c';
    const pusherCluster = 'eu';

    if (!pusherKey || pusherRef.current) return;

    try {
      pusherRef.current = new Pusher(pusherKey, {
        cluster: pusherCluster,
      });

      channelRef.current = pusherRef.current.subscribe('admin-chat');

      // Driver message received
      channelRef.current.bind('driver_message', (data: any) => {
        const messageId = data.messageId || `${data.driverId}_${data.timestamp}`;
        if (processedMessageIds.current.has(messageId)) return;
        processedMessageIds.current.add(messageId);

        toast({
          title: 'New Message',
          description: data.message.substring(0, 50),
          status: 'info',
          duration: 5000,
        });

        loadAllChats();
        if (selectedConversation?.id === data.sessionId) {
          loadMessages(data.sessionId);
        }
      });

      // Typing indicator
      channelRef.current.bind('typing_indicator', (data: any) => {
        if (data.userRole === 'driver' && selectedConversation?.id === data.chatId) {
          setOtherUserTyping(data.isTyping);
          
          if (typingTimeoutRef.current) clearTimeout(typingTimeoutRef.current);
          if (data.isTyping) {
            typingTimeoutRef.current = setTimeout(() => {
              setOtherUserTyping(false);
            }, 3000);
          }
        }
      });

      // Chat closed
      channelRef.current.bind('chat_closed', () => {
        loadAllChats();
      });

      // Chat reopened
      channelRef.current.bind('chat_reopened', () => {
        loadAllChats();
      });

      // Message read receipt
      channelRef.current.bind('message_read', (data: any) => {
        console.log('✓✓ Message read by driver:', data);
        if (selectedConversation?.id === data.sessionId) {
          setMessages(prev =>
            prev.map(msg =>
              msg.id === data.messageId ? { ...msg, read: true } : msg
            )
          );
        }
      });

      if (process.env.NODE_ENV === 'development') {
        console.log('✅ Admin chat Pusher connected');
      }
    } catch (error) {
      console.error('❌ Failed to setup Pusher:', error);
    }
  };

  const cleanupPusher = () => {
    try {
      if (channelRef.current) {
        channelRef.current.unbind_all();
        channelRef.current = null;
      }
      if (pusherRef.current) {
        pusherRef.current.unsubscribe('admin-chat');
        pusherRef.current.disconnect();
        pusherRef.current = null;
      }
    } catch (error) {
      // Silently handle cleanup errors in production
      if (process.env.NODE_ENV === 'development') {
        console.warn('Pusher cleanup warning:', error);
      }
    }
  };

  const loadMessages = async (conversationId: string) => {
    try {
      const response = await fetch(`/api/admin/chat/conversations/${conversationId}/messages`);
      if (response.ok) {
        const data = await response.json();
        const sanitizedMessages = data.messages.map((msg: ChatMessage) => ({
          ...msg,
          senderName: msg.senderRole === 'admin' ? 'Support' : msg.senderName
        }));
        setMessages(sanitizedMessages);
        
        // Auto-scroll to bottom
        setTimeout(() => {
          messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
        }, 100);
      }
    } catch (error) {
      console.error('Error fetching messages:', error);
    }
  };

  const handleConversationSelect = (conversation: ChatConversation) => {
    setSelectedConversation(conversation);
    loadMessages(conversation.id);
  };

  const handleSendMessage = async () => {
    if (!newMessage.trim() || !selectedConversation) return;

    // Prevent sending to closed chats
    if (!selectedConversation.isActive) {
      toast({
        title: 'Chat Closed',
        description: 'This conversation is closed. Reopen it first.',
        status: 'warning',
        duration: 3000,
      });
      return;
    }

    // Stop typing indicator
    if (isTyping) {
      setIsTyping(false);
      sendTypingIndicator(false);
    }

    setSending(true);
    try {
      const response = await fetch(`/api/admin/chat/conversations/${selectedConversation.id}/messages`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          message: newMessage.trim(),
        }),
      });

      if (response.ok) {
        const data = await response.json();
        const sanitizedMessage = {
          ...data.message,
          senderName: 'Support'
        };

        setMessages(prev => {
          const isDuplicate = prev.some(msg => msg.id === sanitizedMessage.id);
          if (isDuplicate) return prev;
          return [...prev, sanitizedMessage];
        });

        setNewMessage('');
        
        // Auto-scroll
        setTimeout(() => {
          messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
        }, 100);
      }
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to send message',
        status: 'error',
        duration: 3000,
      });
    } finally {
      setSending(false);
    }
  };

  const sendTypingIndicator = async (typing: boolean) => {
    if (!selectedConversation) return;

    try {
      await fetch('/api/admin/chat/typing', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          sessionId: selectedConversation.id,
          isTyping: typing,
        }),
      });
    } catch (error) {
      console.error('Failed to send typing indicator:', error);
    }
  };

  const broadcastAdminStatus = async (status: 'online' | 'offline') => {
    try {
      await fetch('/api/admin/chat/status', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ status }),
      });
      console.log(`✅ Admin status broadcasted: ${status}`);
    } catch (error) {
      console.error('Failed to broadcast admin status:', error);
    }
  };

  const handleMessageInputChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    setNewMessage(e.target.value);

    // Send typing indicator
    if (!isTyping && e.target.value.trim()) {
      setIsTyping(true);
      sendTypingIndicator(true);
    }

    // Clear existing timeout
    if (typingIndicatorTimeoutRef.current) {
      clearTimeout(typingIndicatorTimeoutRef.current);
    }

    // Stop typing indicator after 2 seconds of no typing
    if (e.target.value.trim()) {
      typingIndicatorTimeoutRef.current = setTimeout(() => {
        setIsTyping(false);
        sendTypingIndicator(false);
      }, 2000);
    } else {
      setIsTyping(false);
      sendTypingIndicator(false);
    }
  };

  const handleCloseChat = async () => {
    if (!selectedConversation) return;

    try {
      await closeChat(selectedConversation.id, 'Issue resolved');
      
      toast({
        title: 'Success',
        description: 'Conversation closed successfully',
        status: 'success',
        duration: 3000,
      });

      setSelectedConversation(null);
      loadAllChats();
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to close conversation',
        status: 'error',
        duration: 3000,
      });
    }
  };

  const handleReopenChat = async () => {
    if (!selectedConversation) return;

    try {
      await reopenChat(selectedConversation.id);
      
      toast({
        title: 'Success',
        description: 'Conversation reopened successfully',
        status: 'success',
        duration: 3000,
      });

      loadAllChats();
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to reopen conversation',
        status: 'error',
        duration: 3000,
      });
    }
  };

  const getRoleColor = (role: string) => {
    switch (role) {
      case 'admin':
        return 'red';
      case 'driver':
        return 'blue';
      default:
        return 'gray';
    }
  };

  const getRoleIcon = (role: string) => {
    switch (role) {
      case 'admin':
        return FiShield;
      case 'driver':
        return FiTruck;
      default:
        return FiUser;
    }
  };

  if (loading) {
    return (
      <Box p={6}>
        <Flex justify="center" align="center" minH="400px">
          <Spinner size="xl" />
        </Flex>
      </Box>
    );
  }

  const displayConversations = tabIndex === 0 ? activeConversations : archivedConversations;

  return (
    <Box p={6}>
      <VStack spacing={6} align="stretch">
        {/* Header */}
        <Flex justify="space-between" align="center">
          <VStack align="start" spacing={1}>
            <Heading size="lg">Chat Support</Heading>
            <Text color="gray.600">
              Manage driver communications
            </Text>
          </VStack>
        </Flex>

        <Tabs index={tabIndex} onChange={setTabIndex}>
          <TabList>
            <Tab>
              <HStack spacing={2}>
                <Icon as={FiMessageSquare} />
                <Text>Active Chats</Text>
                <Badge colorScheme="green">{activeConversations.length}</Badge>
              </HStack>
            </Tab>
            <Tab>
              <HStack spacing={2}>
                <Icon as={FiArchive} />
                <Text>Archived</Text>
                <Badge colorScheme="gray">{archivedConversations.length}</Badge>
              </HStack>
            </Tab>
          </TabList>

          <TabPanels>
            <TabPanel p={0} pt={4}>
              <Grid templateColumns="1fr 2fr" gap={6} minH="600px">
                {/* Conversations List */}
                <Card>
                  <CardBody>
                    <VStack spacing={4} align="stretch">
                      <Heading size="md">Active Conversations</Heading>

                      <VStack spacing={2} align="stretch" maxH="500px" overflowY="auto">
                        {displayConversations.map(conversation => (
                          <Card
                            key={conversation.id}
                            cursor="pointer"
                            onClick={() => handleConversationSelect(conversation)}
                            bg={selectedConversation?.id === conversation.id ? 'blue.900' : 'gray.800'}
                            _hover={{ bg: 'gray.700' }}
                            borderWidth={selectedConversation?.id === conversation.id ? 2 : 1}
                            borderColor={selectedConversation?.id === conversation.id ? 'blue.500' : 'gray.200'}
                          >
                            <CardBody p={3}>
                              <VStack align="start" spacing={2}>
                                <HStack justify="space-between" w="full">
                                  <HStack>
                                    <Avatar size="sm" name={conversation.participants[0]?.name} />
                                    <VStack align="start" spacing={0}>
                                      <Text fontWeight="medium" fontSize="sm">
                                        {conversation.participants.map(p => p.name).join(', ')}
                                      </Text>
                                      <HStack spacing={2}>
                                        <Badge size="sm" colorScheme={getRoleColor(conversation.participants[0]?.role)}>
                                          {conversation.participants[0]?.role}
                                        </Badge>
                                        <Badge 
                                          size="sm" 
                                          colorScheme={conversation.isActive ? 'green' : 'red'}
                                          variant="subtle"
                                        >
                                          {conversation.isActive ? '🟢 Active' : '🔴 Closed'}
                                        </Badge>
                                      </HStack>
                                    </VStack>
                                  </HStack>
                                </HStack>

                                {conversation.lastMessage && (
                                  <Text fontSize="sm" color="gray.600" noOfLines={1}>
                                    {conversation.lastMessage.message}
                                  </Text>
                                )}

                                <Text fontSize="xs" color="gray.500">
                                  {new Date(conversation.updatedAt).toLocaleString()}
                                </Text>
                              </VStack>
                            </CardBody>
                          </Card>
                        ))}

                        {displayConversations.length === 0 && (
                          <VStack spacing={4} py={8}>
                            <Icon as={FiMessageSquare} boxSize="48px" color="gray.400" />
                            <Text color="gray.500">
                              {tabIndex === 0 ? 'No active conversations' : 'No archived conversations'}
                            </Text>
                          </VStack>
                        )}
                      </VStack>
                    </VStack>
                  </CardBody>
                </Card>

                {/* Chat Area */}
                <Card>
                  <CardBody>
                    {selectedConversation ? (
                      <VStack spacing={4} align="stretch" h="full">
                        {/* Chat Header */}
                        <HStack justify="space-between" pb={2} borderBottom="1px" borderColor="gray.200">
                          <VStack align="start" spacing={1}>
                            <HStack>
                              <Avatar size="sm" name={selectedConversation.participants[0]?.name} />
                              <Heading size="md">
                                {selectedConversation.participants.map(p => p.name).join(', ')}
                              </Heading>
                            </HStack>
                            <HStack spacing={2}>
                              {selectedConversation.participants.map((participant, index) => (
                                <Badge key={index} size="sm" colorScheme={getRoleColor(participant.role)}>
                                  <Icon as={getRoleIcon(participant.role)} mr={1} />
                                  {participant.role}
                                </Badge>
                              ))}
                              <Badge 
                                size="sm" 
                                colorScheme={selectedConversation.isActive ? 'green' : 'red'}
                              >
                                {selectedConversation.isActive ? '🟢 Active' : '🔴 Closed'}
                              </Badge>
                            </HStack>
                            {otherUserTyping && (
                              <Text fontSize="sm" color="green.500" fontStyle="italic">
                                Driver is typing...
                              </Text>
                            )}
                          </VStack>

                          <HStack spacing={2}>
                            {selectedConversation.isActive ? (
                              <Tooltip label="Close Conversation">
                                <IconButton
                                  aria-label="Close conversation"
                                  icon={<FiLock />}
                                  size="sm"
                                  colorScheme="red"
                                  variant="ghost"
                                  onClick={handleCloseChat}
                                />
                              </Tooltip>
                            ) : (
                              <Tooltip label="Reopen Conversation">
                                <IconButton
                                  aria-label="Reopen conversation"
                                  icon={<FiUnlock />}
                                  size="sm"
                                  colorScheme="green"
                                  variant="ghost"
                                  onClick={handleReopenChat}
                                />
                              </Tooltip>
                            )}
                          </HStack>
                        </HStack>

                        {/* Closed Chat Banner */}
                        {!selectedConversation.isActive && (
                          <Alert status="warning" borderRadius="md">
                            <AlertIcon />
                            <AlertDescription>
                              This conversation was closed on{' '}
                              {selectedConversation.closedAt
                                ? new Date(selectedConversation.closedAt).toLocaleString()
                                : 'unknown date'}
                              . Click the unlock icon to reopen.
                            </AlertDescription>
                          </Alert>
                        )}

                        {/* Messages */}
                        <VStack
                          spacing={3}
                          align="stretch"
                          flex={1}
                          maxH="400px"
                          overflowY="auto"
                          p={2}
                        >
                          {messages.map(message => (
                            <HStack
                              key={message.id}
                              justify={message.senderRole === 'admin' ? 'flex-end' : 'flex-start'}
                              align="start"
                              spacing={2}
                            >
                              {message.senderRole !== 'admin' && (
                                <Avatar size="sm" name={message.senderName} />
                              )}

                              <VStack
                                align={message.senderRole === 'admin' ? 'flex-end' : 'flex-start'}
                                spacing={1}
                                maxW="70%"
                              >
                                <Card
                                  bg={message.senderRole === 'admin' ? 'blue.500' : 'gray.700'}
                                  color={message.senderRole === 'admin' ? 'white' : 'black'}
                                >
                                  <CardBody p={3}>
                                    <Text fontSize="sm">{message.message}</Text>
                                  </CardBody>
                                </Card>

                                <HStack spacing={1}>
                                  <Text fontSize="xs" color="gray.500">
                                    {message.senderName}
                                  </Text>
                                  <Text fontSize="xs" color="gray.500">
                                    {new Date(message.timestamp).toLocaleTimeString([], {
                                      hour: '2-digit',
                                      minute: '2-digit',
                                    })}
                                  </Text>
                                  {message.read && message.senderRole === 'admin' && (
                                    <Icon as={FiCheck} boxSize="12px" color="blue.500" />
                                  )}
                                </HStack>
                              </VStack>

                              {message.senderRole === 'admin' && (
                                <Avatar size="sm" name="Support" />
                              )}
                            </HStack>
                          ))}

                          <div ref={messagesEndRef} />

                          {messages.length === 0 && (
                            <VStack spacing={4} py={8}>
                              <Icon as={FiMessageSquare} boxSize="48px" color="gray.400" />
                              <Text color="gray.500">No messages in this conversation</Text>
                            </VStack>
                          )}
                        </VStack>

                        {/* Message Input */}
                        <HStack spacing={2}>
                          <Textarea
                            placeholder="Type your message..."
                            value={newMessage}
                            onChange={handleMessageInputChange}
                            onKeyPress={e => {
                              if (e.key === 'Enter' && !e.shiftKey) {
                                e.preventDefault();
                                handleSendMessage();
                              }
                            }}
                            resize="none"
                            rows={2}
                            isDisabled={!selectedConversation.isActive}
                          />
                          <Button
                            leftIcon={<FiSend />}
                            colorScheme="blue"
                            onClick={handleSendMessage}
                            isLoading={sending}
                            loadingText="Sending..."
                            isDisabled={!newMessage.trim() || !selectedConversation.isActive}
                          >
                            Send
                          </Button>
                        </HStack>
                      </VStack>
                    ) : (
                      <VStack spacing={6} justify="center" minH="400px">
                        <Icon as={FiMessageSquare} boxSize="64px" color="gray.400" />
                        <VStack spacing={2}>
                          <Heading size="md" color="gray.600">
                            Select a conversation
                          </Heading>
                          <Text color="gray.500" textAlign="center">
                            Choose a conversation from the list to start chatting
                          </Text>
                        </VStack>
                      </VStack>
                    )}
                  </CardBody>
                </Card>
              </Grid>
            </TabPanel>

            <TabPanel p={0} pt={4}>
              <Grid templateColumns="1fr 2fr" gap={6} minH="600px">
                {/* Same structure for archived - reuse component */}
                <Card>
                  <CardBody>
                    <VStack spacing={4} align="stretch">
                      <Heading size="md">Archived Conversations</Heading>

                      <VStack spacing={2} align="stretch" maxH="500px" overflowY="auto">
                        {archivedConversations.map(conversation => (
                          <Card
                            key={conversation.id}
                            cursor="pointer"
                            onClick={() => handleConversationSelect(conversation)}
                            bg={selectedConversation?.id === conversation.id ? 'red.900' : 'gray.800'}
                            _hover={{ bg: 'gray.700' }}
                          >
                            <CardBody p={3}>
                              <VStack align="start" spacing={2}>
                                <HStack justify="space-between" w="full">
                                  <HStack>
                                    <Avatar size="sm" name={conversation.participants[0]?.name} />
                                    <VStack align="start" spacing={0}>
                                      <Text fontWeight="medium" fontSize="sm">
                                        {conversation.participants.map(p => p.name).join(', ')}
                                      </Text>
                                      <Badge size="sm" colorScheme="red">
                                        🔴 Closed
                                      </Badge>
                                    </VStack>
                                  </HStack>
                                </HStack>

                                {conversation.lastMessage && (
                                  <Text fontSize="sm" color="gray.600" noOfLines={1}>
                                    {conversation.lastMessage.message}
                                  </Text>
                                )}

                                <Text fontSize="xs" color="gray.500">
                                  Closed: {conversation.closedAt ? new Date(conversation.closedAt).toLocaleString() : 'Unknown'}
                                </Text>
                              </VStack>
                            </CardBody>
                          </Card>
                        ))}

                        {archivedConversations.length === 0 && (
                          <VStack spacing={4} py={8}>
                            <Icon as={FiArchive} boxSize="48px" color="gray.400" />
                            <Text color="gray.500">No archived conversations</Text>
                          </VStack>
                        )}
                      </VStack>
                    </VStack>
                  </CardBody>
                </Card>

                {/* Archived Chat View - Reuse same component */}
                <Card>
                  <CardBody>
                    {selectedConversation ? (
                      <VStack spacing={4} align="stretch" h="full">
                        <HStack justify="space-between" pb={2} borderBottom="1px" borderColor="gray.200">
                          <VStack align="start" spacing={1}>
                            <HStack>
                              <Avatar size="sm" name={selectedConversation.participants[0]?.name} />
                              <Heading size="md">
                                {selectedConversation.participants.map(p => p.name).join(', ')}
                              </Heading>
                            </HStack>
                            <Badge colorScheme="red">🔴 Closed</Badge>
                          </VStack>

                          <Tooltip label="Reopen Conversation">
                            <Button
                              leftIcon={<FiUnlock />}
                              size="sm"
                              colorScheme="green"
                              onClick={handleReopenChat}
                            >
                              Reopen
                            </Button>
                          </Tooltip>
                        </HStack>

                        <Alert status="info">
                          <AlertIcon />
                          <AlertDescription>
                            This conversation is archived. Reopen it to continue chatting.
                          </AlertDescription>
                        </Alert>

                        {/* Messages - Read only */}
                        <VStack
                          spacing={3}
                          align="stretch"
                          flex={1}
                          maxH="400px"
                          overflowY="auto"
                          p={2}
                        >
                          {messages.map(message => (
                            <HStack
                              key={message.id}
                              justify={message.senderRole === 'admin' ? 'flex-end' : 'flex-start'}
                              align="start"
                              spacing={2}
                            >
                              {message.senderRole !== 'admin' && (
                                <Avatar size="sm" name={message.senderName} />
                              )}

                              <VStack
                                align={message.senderRole === 'admin' ? 'flex-end' : 'flex-start'}
                                spacing={1}
                                maxW="70%"
                              >
                                <Card
                                  bg={message.senderRole === 'admin' ? 'blue.500' : 'gray.700'}
                                  color={message.senderRole === 'admin' ? 'white' : 'black'}
                                >
                                  <CardBody p={3}>
                                    <Text fontSize="sm">{message.message}</Text>
                                  </CardBody>
                                </Card>

                                <Text fontSize="xs" color="gray.500">
                                  {new Date(message.timestamp).toLocaleTimeString([], {
                                    hour: '2-digit',
                                    minute: '2-digit',
                                  })}
                                </Text>
                              </VStack>

                              {message.senderRole === 'admin' && (
                                <Avatar size="sm" name="Support" />
                              )}
                            </HStack>
                          ))}
                        </VStack>
                      </VStack>
                    ) : (
                      <VStack spacing={6} justify="center" minH="400px">
                        <Icon as={FiArchive} boxSize="64px" color="gray.400" />
                        <Text color="gray.500">Select an archived conversation to view</Text>
                      </VStack>
                    )}
                  </CardBody>
                </Card>
              </Grid>
            </TabPanel>
          </TabPanels>
        </Tabs>
      </VStack>
    </Box>
  );
}

'use client';
import React, { useState, useEffect } from 'react';
import {
  Box,
  Heading,
  HStack,
  VStack,
  Text,
  Badge,
  Card,
  CardBody,
  Button,
  Table,
  Thead,
  Tbody,
  Tr,
  Th,
  Td,
  Input,
  Select,
  Switch,
  FormControl,
  FormLabel,
  NumberInput,
  NumberInputField,
  NumberInputStepper,
  NumberIncrementStepper,
  NumberDecrementStepper,
  useDisclosure,
  Modal,
  ModalOverlay,
  ModalContent,
  ModalHeader,
  ModalBody,
  ModalFooter,
  Textarea,
  Grid,
  GridItem,
  Alert,
  AlertIcon,
  useToast,
  Tag,
  TagLabel,
  TagCloseButton,
  InputGroup,
  InputRightElement,
} from '@chakra-ui/react';
import {
  FiPlus,
  FiEdit,
  FiEye,
  FiTrash2,
  FiSave,
  FiX,
  FiMapPin,
} from 'react-icons/fi';

interface ServiceArea {
  id: string;
  name: string;
  description?: string;
  postcodes: string[];
  polygon?: any;
  capacity: number;
  status: string;
  blackoutDates: string[];
  surgeMultiplier: number;
  createdBy: string;
  createdAt: string;
  updatedAt: string;
}

export default function ServiceAreasPage() {
  const [serviceAreas, setServiceAreas] = useState<ServiceArea[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedArea, setSelectedArea] = useState<ServiceArea | null>(null);
  const { isOpen, onOpen, onClose } = useDisclosure();
  const toast = useToast();

  // Form state
  const [formData, setFormData] = useState({
    name: '',
    description: '',
    postcodes: [] as string[],
    polygon: null,
    capacity: 100,
    status: 'active',
    blackoutDates: [] as string[],
    surgeMultiplier: 1.0,
  });

  const [newPostcode, setNewPostcode] = useState('');
  const [newBlackoutDate, setNewBlackoutDate] = useState('');

  useEffect(() => {
    fetchServiceAreas();
  }, []);

  const fetchServiceAreas = async () => {
    try {
      const response = await fetch('/api/admin/content/areas');
      if (response.ok) {
        const data = await response.json();
        setServiceAreas(data);
      }
    } catch (error) {
      console.error('Error fetching service areas:', error);
      toast({
        title: 'Error',
        description: 'Failed to load service areas',
        status: 'error',
        duration: 5000,
      });
    } finally {
      setLoading(false);
    }
  };

  const handleCreateNew = () => {
    setSelectedArea(null);
    setFormData({
      name: '',
      description: '',
      postcodes: [],
      polygon: null,
      capacity: 100,
      status: 'active',
      blackoutDates: [],
      surgeMultiplier: 1.0,
    });
    onOpen();
  };

  const handleEdit = (area: ServiceArea) => {
    setSelectedArea(area);
    setFormData({
      name: area.name,
      description: area.description || '',
      postcodes: area.postcodes,
      polygon: area.polygon,
      capacity: area.capacity,
      status: area.status,
      blackoutDates: area.blackoutDates,
      surgeMultiplier: area.surgeMultiplier,
    });
    onOpen();
  };

  const handleSave = async () => {
    try {
      const response = await fetch('/api/admin/content/areas', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(formData),
      });

      if (response.ok) {
        toast({
          title: 'Success',
          description: 'Service area saved successfully',
          status: 'success',
          duration: 5000,
        });
        onClose();
        fetchServiceAreas();
      } else {
        const error = await response.json();
        toast({
          title: 'Error',
          description: error.error || 'Failed to save service area',
          status: 'error',
          duration: 5000,
        });
      }
    } catch (error) {
      console.error('Error saving service area:', error);
      toast({
        title: 'Error',
        description: 'Failed to save service area',
        status: 'error',
        duration: 5000,
      });
    }
  };

  const addPostcode = () => {
    if (
      newPostcode &&
      !formData.postcodes.includes(newPostcode.toUpperCase())
    ) {
      setFormData({
        ...formData,
        postcodes: [...formData.postcodes, newPostcode.toUpperCase()],
      });
      setNewPostcode('');
    }
  };

  const removePostcode = (postcode: string) => {
    setFormData({
      ...formData,
      postcodes: formData.postcodes.filter(p => p !== postcode),
    });
  };

  const addBlackoutDate = () => {
    if (newBlackoutDate && !formData.blackoutDates.includes(newBlackoutDate)) {
      setFormData({
        ...formData,
        blackoutDates: [...formData.blackoutDates, newBlackoutDate],
      });
      setNewBlackoutDate('');
    }
  };

  const removeBlackoutDate = (date: string) => {
    setFormData({
      ...formData,
      blackoutDates: formData.blackoutDates.filter(d => d !== date),
    });
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'active':
        return 'green';
      case 'inactive':
        return 'gray';
      case 'draft':
        return 'yellow';
      default:
        return 'gray';
    }
  };

  if (loading) {
    return (
      <Box>
        <Text>Loading service areas...</Text>
      </Box>
    );
  }

  return (
    <Box>
      <HStack justify="space-between" mb={6}>
        <VStack align="start" spacing={1}>
          <Heading size="lg">Service Areas</Heading>
          <Text color="gray.600">
            Manage geographic service boundaries and capacity
          </Text>
        </VStack>
        <Button
          leftIcon={<FiPlus />}
          colorScheme="blue"
          onClick={handleCreateNew}
        >
          New Service Area
        </Button>
      </HStack>

      <Alert status="info" mb={6}>
        <AlertIcon />
        Service areas define where you operate and can include capacity limits
        and blackout dates.
      </Alert>

      <Card>
        <CardBody>
          <Table variant="simple">
            <Thead>
              <Tr>
                <Th>Name</Th>
                <Th>Postcodes</Th>
                <Th>Capacity</Th>
                <Th>Status</Th>
                <Th>Surge Multiplier</Th>
                <Th>Blackout Dates</Th>
                <Th>Actions</Th>
              </Tr>
            </Thead>
            <Tbody>
              {serviceAreas.map(area => (
                <Tr key={area.id}>
                  <Td>
                    <VStack align="start" spacing={0}>
                      <Text fontWeight="bold">{area.name}</Text>
                      {area.description && (
                        <Text fontSize="sm" color="gray.500">
                          {area.description}
                        </Text>
                      )}
                    </VStack>
                  </Td>
                  <Td>
                    <HStack spacing={1} flexWrap="wrap">
                      {area.postcodes.slice(0, 3).map(postcode => (
                        <Badge key={postcode} size="sm" variant="outline">
                          {postcode}
                        </Badge>
                      ))}
                      {area.postcodes.length > 3 && (
                        <Badge size="sm" variant="outline">
                          +{area.postcodes.length - 3} more
                        </Badge>
                      )}
                    </HStack>
                  </Td>
                  <Td>
                    <Text>{area.capacity} jobs/day</Text>
                  </Td>
                  <Td>
                    <Badge colorScheme={getStatusColor(area.status)}>
                      {area.status}
                    </Badge>
                  </Td>
                  <Td>
                    <Text>{(area.surgeMultiplier * 100).toFixed(0)}%</Text>
                  </Td>
                  <Td>
                    <Text fontSize="sm">
                      {area.blackoutDates.length > 0
                        ? `${area.blackoutDates.length} dates`
                        : 'None'}
                    </Text>
                  </Td>
                  <Td>
                    <HStack spacing={2}>
                      <Button
                        size="xs"
                        leftIcon={<FiEdit />}
                        variant="outline"
                        onClick={() => handleEdit(area)}
                      >
                        Edit
                      </Button>
                      <Button
                        size="xs"
                        leftIcon={<FiMapPin />}
                        variant="outline"
                      >
                        Map
                      </Button>
                    </HStack>
                  </Td>
                </Tr>
              ))}
            </Tbody>
          </Table>
        </CardBody>
      </Card>

      {/* Service Area Modal */}
      <Modal isOpen={isOpen} onClose={onClose} size="xl">
        <ModalOverlay />
        <ModalContent>
          <ModalHeader>
            {selectedArea ? 'Edit Service Area' : 'New Service Area'}
          </ModalHeader>
          <ModalBody>
            <VStack spacing={4}>
              <Grid templateColumns="repeat(2, 1fr)" gap={4} w="full">
                <GridItem>
                  <FormControl isRequired>
                    <FormLabel>Name</FormLabel>
                    <Input
                      value={formData.name}
                      onChange={e =>
                        setFormData({ ...formData, name: e.target.value })
                      }
                      placeholder="e.g., Central London"
                    />
                  </FormControl>
                </GridItem>
                <GridItem>
                  <FormControl>
                    <FormLabel>Status</FormLabel>
                    <Select
                      value={formData.status}
                      onChange={e =>
                        setFormData({ ...formData, status: e.target.value })
                      }
                    >
                      <option value="active">Active</option>
                      <option value="inactive">Inactive</option>
                      <option value="draft">Draft</option>
                    </Select>
                  </FormControl>
                </GridItem>
              </Grid>

              <FormControl>
                <FormLabel>Description</FormLabel>
                <Textarea
                  value={formData.description}
                  onChange={e =>
                    setFormData({ ...formData, description: e.target.value })
                  }
                  placeholder="Optional description of this service area"
                />
              </FormControl>

              <Grid templateColumns="repeat(2, 1fr)" gap={4} w="full">
                <GridItem>
                  <FormControl>
                    <FormLabel>Daily Capacity</FormLabel>
                    <NumberInput
                      value={formData.capacity}
                      onChange={value =>
                        setFormData({ ...formData, capacity: parseInt(value) })
                      }
                      min={1}
                      max={1000}
                    >
                      <NumberInputField />
                      <NumberInputStepper>
                        <NumberIncrementStepper />
                        <NumberDecrementStepper />
                      </NumberInputStepper>
                    </NumberInput>
                  </FormControl>
                </GridItem>
                <GridItem>
                  <FormControl>
                    <FormLabel>Surge Multiplier (%)</FormLabel>
                    <NumberInput
                      value={formData.surgeMultiplier * 100}
                      onChange={value =>
                        setFormData({
                          ...formData,
                          surgeMultiplier: parseFloat(value) / 100,
                        })
                      }
                      min={100}
                      max={300}
                      precision={0}
                    >
                      <NumberInputField />
                      <NumberInputStepper>
                        <NumberIncrementStepper />
                        <NumberDecrementStepper />
                      </NumberInputStepper>
                    </NumberInput>
                  </FormControl>
                </GridItem>
              </Grid>

              <FormControl>
                <FormLabel>Postcodes</FormLabel>
                <InputGroup>
                  <Input
                    value={newPostcode}
                    onChange={e => setNewPostcode(e.target.value)}
                    placeholder="Enter postcode (e.g., SW1A 1AA)"
                    onKeyPress={e => e.key === 'Enter' && addPostcode()}
                  />
                  <InputRightElement>
                    <Button size="sm" onClick={addPostcode}>
                      Add
                    </Button>
                  </InputRightElement>
                </InputGroup>
                <HStack spacing={2} mt={2} flexWrap="wrap">
                  {formData.postcodes.map(postcode => (
                    <Tag
                      key={postcode}
                      size="md"
                      colorScheme="blue"
                      borderRadius="full"
                    >
                      <TagLabel>{postcode}</TagLabel>
                      <TagCloseButton
                        onClick={() => removePostcode(postcode)}
                      />
                    </Tag>
                  ))}
                </HStack>
              </FormControl>

              <FormControl>
                <FormLabel>Blackout Dates</FormLabel>
                <InputGroup>
                  <Input
                    type="date"
                    value={newBlackoutDate}
                    onChange={e => setNewBlackoutDate(e.target.value)}
                  />
                  <InputRightElement>
                    <Button size="sm" onClick={addBlackoutDate}>
                      Add
                    </Button>
                  </InputRightElement>
                </InputGroup>
                <HStack spacing={2} mt={2} flexWrap="wrap">
                  {formData.blackoutDates.map(date => (
                    <Tag
                      key={date}
                      size="md"
                      colorScheme="red"
                      borderRadius="full"
                    >
                      <TagLabel>{date}</TagLabel>
                      <TagCloseButton
                        onClick={() => removeBlackoutDate(date)}
                      />
                    </Tag>
                  ))}
                </HStack>
              </FormControl>

              <Alert status="info">
                <AlertIcon />
                Geographic boundaries can be set using the map interface in the
                full editor.
              </Alert>
            </VStack>
          </ModalBody>
          <ModalFooter>
            <Button variant="ghost" mr={3} onClick={onClose}>
              Cancel
            </Button>
            <Button
              leftIcon={<FiSave />}
              colorScheme="blue"
              onClick={handleSave}
            >
              Save Service Area
            </Button>
          </ModalFooter>
        </ModalContent>
      </Modal>
    </Box>
  );
}

'use client';
import React, { useState, useEffect } from 'react';
import {
  Box,
  Heading,
  HStack,
  VStack,
  Text,
  Badge,
  Card,
  CardBody,
  Button,
  Table,
  Thead,
  Tbody,
  Tr,
  Th,
  Td,
  Input,
  Select,
  Switch,
  FormControl,
  FormLabel,
  NumberInput,
  NumberInputField,
  NumberInputStepper,
  NumberIncrementStepper,
  NumberDecrementStepper,
  useDisclosure,
  Modal,
  ModalOverlay,
  ModalContent,
  ModalHeader,
  ModalBody,
  ModalFooter,
  Textarea,
  Grid,
  GridItem,
  Alert,
  AlertIcon,
  useToast,
  Tag,
  TagLabel,
  TagCloseButton,
  InputGroup,
  InputRightElement,
  Progress,
} from '@chakra-ui/react';
import {
  FiPlus,
  FiEdit,
  FiEye,
  FiTrash2,
  FiSave,
  FiX,
  FiGift,
} from 'react-icons/fi';

interface Promotion {
  id: string;
  reference: string;
  name: string;
  description?: string;
  type: string;
  value: number;
  minSpend: number;
  maxDiscount: number;
  usageLimit: number;
  usedCount: number;
  validFrom: string;
  validTo: string;
  status: string;
  applicableAreas: string[];
  applicableVans: string[];
  firstTimeOnly: boolean;
  createdBy: string;
  createdAt: string;
  updatedAt: string;
}

export default function PromotionsPage() {
  const [promotions, setPromotions] = useState<Promotion[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedPromo, setSelectedPromo] = useState<Promotion | null>(null);
  const { isOpen, onOpen, onClose } = useDisclosure();
  const toast = useToast();

  // Form state
  const [formData, setFormData] = useState({
    reference: '',
    name: '',
    description: '',
    type: 'percentage',
    value: 10,
    minSpend: 0,
    maxDiscount: 0,
    usageLimit: 1000,
    validFrom: new Date().toISOString().split('T')[0],
    validTo: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000)
      .toISOString()
      .split('T')[0],
    status: 'active',
    applicableAreas: [] as string[],
    applicableVans: [] as string[],
    firstTimeOnly: false,
  });

  const [newArea, setNewArea] = useState('');
  const [newVan, setNewVan] = useState('');

  useEffect(() => {
    fetchPromotions();
  }, []);

  const fetchPromotions = async () => {
    try {
      const response = await fetch('/api/admin/content/promos');
      if (response.ok) {
        const data = await response.json();
        setPromotions(data);
      }
    } catch (error) {
      console.error('Error fetching promotions:', error);
      toast({
        title: 'Error',
        description: 'Failed to load promotions',
        status: 'error',
        duration: 5000,
      });
    } finally {
      setLoading(false);
    }
  };

  const handleCreateNew = () => {
    setSelectedPromo(null);
    setFormData({
      reference: '',
      name: '',
      description: '',
      type: 'percentage',
      value: 10,
      minSpend: 0,
      maxDiscount: 0,
      usageLimit: 1000,
      validFrom: new Date().toISOString().split('T')[0],
      validTo: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000)
        .toISOString()
        .split('T')[0],
      status: 'active',
      applicableAreas: [],
      applicableVans: [],
      firstTimeOnly: false,
    });
    onOpen();
  };

  const handleEdit = (promo: Promotion) => {
    setSelectedPromo(promo);
    setFormData({
      reference: promo.reference,
      name: promo.name,
      description: promo.description || '',
      type: promo.type,
      value: promo.value,
      minSpend: promo.minSpend,
      maxDiscount: promo.maxDiscount,
      usageLimit: promo.usageLimit,
      validFrom: new Date(promo.validFrom).toISOString().split('T')[0],
      validTo: new Date(promo.validTo).toISOString().split('T')[0],
      status: promo.status,
      applicableAreas: promo.applicableAreas,
      applicableVans: promo.applicableVans,
      firstTimeOnly: promo.firstTimeOnly,
    });
    onOpen();
  };

  const handleSave = async () => {
    try {
      const response = await fetch('/api/admin/content/promos', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(formData),
      });

      if (response.ok) {
        toast({
          title: 'Success',
          description: 'Promotion saved successfully',
          status: 'success',
          duration: 5000,
        });
        onClose();
        fetchPromotions();
      } else {
        const error = await response.json();
        toast({
          title: 'Error',
          description: error.error || 'Failed to save promotion',
          status: 'error',
          duration: 5000,
        });
      }
    } catch (error) {
      console.error('Error saving promotion:', error);
      toast({
        title: 'Error',
        description: 'Failed to save promotion',
        status: 'error',
        duration: 5000,
      });
    }
  };

  const addArea = () => {
    if (newArea && !formData.applicableAreas.includes(newArea)) {
      setFormData({
        ...formData,
        applicableAreas: [...formData.applicableAreas, newArea],
      });
      setNewArea('');
    }
  };

  const removeArea = (area: string) => {
    setFormData({
      ...formData,
      applicableAreas: formData.applicableAreas.filter(a => a !== area),
    });
  };

  const addVan = () => {
    if (newVan && !formData.applicableVans.includes(newVan)) {
      setFormData({
        ...formData,
        applicableVans: [...formData.applicableVans, newVan],
      });
      setNewVan('');
    }
  };

  const removeVan = (van: string) => {
    setFormData({
      ...formData,
      applicableVans: formData.applicableVans.filter(v => v !== van),
    });
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'active':
        return 'green';
      case 'inactive':
        return 'gray';
      case 'scheduled':
        return 'blue';
      case 'expired':
        return 'red';
      default:
        return 'gray';
    }
  };

  const getUsagePercentage = (promo: Promotion) => {
    return (promo.usedCount / promo.usageLimit) * 100;
  };

  const isExpired = (promo: Promotion) => {
    return new Date() > new Date(promo.validTo);
  };

  const isScheduled = (promo: Promotion) => {
    return new Date() < new Date(promo.validFrom);
  };

  if (loading) {
    return (
      <Box>
        <Text>Loading promotions...</Text>
      </Box>
    );
  }

  return (
    <Box>
      <HStack justify="space-between" mb={6}>
        <VStack align="start" spacing={1}>
          <Heading size="lg">Promotions</Heading>
          <Text color="gray.600">Manage promotional codes and discounts</Text>
        </VStack>
        <Button
          leftIcon={<FiPlus />}
          colorScheme="blue"
          onClick={handleCreateNew}
        >
          New Promotion
        </Button>
      </HStack>

      <Alert status="info" mb={6}>
        <AlertIcon />
        Promotions can be percentage or fixed discounts with usage limits and
        validity periods.
      </Alert>

      <Card>
        <CardBody>
          <Table variant="simple">
            <Thead>
              <Tr>
                <Th>Code</Th>
                <Th>Name</Th>
                <Th>Type</Th>
                <Th>Value</Th>
                <Th>Usage</Th>
                <Th>Valid Period</Th>
                <Th>Status</Th>
                <Th>Actions</Th>
              </Tr>
            </Thead>
            <Tbody>
              {promotions.map(promo => (
                <Tr key={promo.id}>
                  <Td>
                    <Text fontWeight="bold" fontFamily="mono">
                      {promo.reference}
                    </Text>
                  </Td>
                  <Td>
                    <VStack align="start" spacing={0}>
                      <Text fontWeight="bold">{promo.name}</Text>
                      {promo.description && (
                        <Text fontSize="sm" color="gray.500">
                          {promo.description}
                        </Text>
                      )}
                    </VStack>
                  </Td>
                  <Td>
                    <Badge variant="outline" colorScheme="blue">
                      {promo.type}
                    </Badge>
                  </Td>
                  <Td>
                    <Text>
                      {promo.type === 'percentage'
                        ? `${promo.value}%`
                        : `£${promo.value.toFixed(2)}`}
                    </Text>
                  </Td>
                  <Td>
                    <VStack align="start" spacing={1}>
                      <Text fontSize="sm">
                        {promo.usedCount}/{promo.usageLimit}
                      </Text>
                      <Progress
                        value={getUsagePercentage(promo)}
                        size="sm"
                        colorScheme={
                          getUsagePercentage(promo) > 80 ? 'red' : 'green'
                        }
                        w="100px"
                      />
                    </VStack>
                  </Td>
                  <Td>
                    <Text fontSize="sm">
                      {new Date(promo.validFrom).toLocaleDateString()} -{' '}
                      {new Date(promo.validTo).toLocaleDateString()}
                    </Text>
                  </Td>
                  <Td>
                    <Badge colorScheme={getStatusColor(promo.status)}>
                      {isExpired(promo)
                        ? 'Expired'
                        : isScheduled(promo)
                          ? 'Scheduled'
                          : promo.status}
                    </Badge>
                  </Td>
                  <Td>
                    <HStack spacing={2}>
                      <Button
                        size="xs"
                        leftIcon={<FiEdit />}
                        variant="outline"
                        onClick={() => handleEdit(promo)}
                      >
                        Edit
                      </Button>
                      <Button size="xs" leftIcon={<FiEye />} variant="outline">
                        Preview
                      </Button>
                    </HStack>
                  </Td>
                </Tr>
              ))}
            </Tbody>
          </Table>
        </CardBody>
      </Card>

      {/* Promotion Modal */}
      <Modal isOpen={isOpen} onClose={onClose} size="xl">
        <ModalOverlay />
        <ModalContent>
          <ModalHeader>
            {selectedPromo ? 'Edit Promotion' : 'New Promotion'}
          </ModalHeader>
          <ModalBody>
            <VStack spacing={4}>
              <Grid templateColumns="repeat(2, 1fr)" gap={4} w="full">
                <GridItem>
                  <FormControl isRequired>
                    <FormLabel>Promotion Code</FormLabel>
                    <Input
                      value={formData.reference}
                      onChange={e =>
                        setFormData({
                          ...formData,
                          reference: e.target.value.toUpperCase(),
                        })
                      }
                      placeholder="e.g., FIRST10"
                      fontFamily="mono"
                    />
                  </FormControl>
                </GridItem>
                <GridItem>
                  <FormControl isRequired>
                    <FormLabel>Name</FormLabel>
                    <Input
                      value={formData.name}
                      onChange={e =>
                        setFormData({ ...formData, name: e.target.value })
                      }
                      placeholder="e.g., First Order Discount"
                    />
                  </FormControl>
                </GridItem>
              </Grid>

              <FormControl>
                <FormLabel>Description</FormLabel>
                <Textarea
                  value={formData.description}
                  onChange={e =>
                    setFormData({ ...formData, description: e.target.value })
                  }
                  placeholder="Optional description of this promotion"
                />
              </FormControl>

              <Grid templateColumns="repeat(3, 1fr)" gap={4} w="full">
                <GridItem>
                  <FormControl isRequired>
                    <FormLabel>Type</FormLabel>
                    <Select
                      value={formData.type}
                      onChange={e =>
                        setFormData({ ...formData, type: e.target.value })
                      }
                    >
                      <option value="percentage">Percentage</option>
                      <option value="fixed">Fixed Amount</option>
                      <option value="free_shipping">Free Shipping</option>
                    </Select>
                  </FormControl>
                </GridItem>
                <GridItem>
                  <FormControl isRequired>
                    <FormLabel>
                      {formData.type === 'percentage'
                        ? 'Percentage (%)'
                        : 'Amount (£)'}
                    </FormLabel>
                    <NumberInput
                      value={formData.value}
                      onChange={value =>
                        setFormData({ ...formData, value: parseFloat(value) })
                      }
                      min={0}
                      max={formData.type === 'percentage' ? 100 : 1000}
                      precision={formData.type === 'percentage' ? 0 : 2}
                    >
                      <NumberInputField />
                      <NumberInputStepper>
                        <NumberIncrementStepper />
                        <NumberDecrementStepper />
                      </NumberInputStepper>
                    </NumberInput>
                  </FormControl>
                </GridItem>
                <GridItem>
                  <FormControl>
                    <FormLabel>Status</FormLabel>
                    <Select
                      value={formData.status}
                      onChange={e =>
                        setFormData({ ...formData, status: e.target.value })
                      }
                    >
                      <option value="active">Active</option>
                      <option value="inactive">Inactive</option>
                      <option value="scheduled">Scheduled</option>
                    </Select>
                  </FormControl>
                </GridItem>
              </Grid>

              <Grid templateColumns="repeat(2, 1fr)" gap={4} w="full">
                <GridItem>
                  <FormControl>
                    <FormLabel>Minimum Spend (£)</FormLabel>
                    <NumberInput
                      value={formData.minSpend}
                      onChange={value =>
                        setFormData({
                          ...formData,
                          minSpend: parseFloat(value),
                        })
                      }
                      min={0}
                      precision={2}
                    >
                      <NumberInputField />
                      <NumberInputStepper>
                        <NumberIncrementStepper />
                        <NumberDecrementStepper />
                      </NumberInputStepper>
                    </NumberInput>
                  </FormControl>
                </GridItem>
                <GridItem>
                  <FormControl>
                    <FormLabel>Maximum Discount (£)</FormLabel>
                    <NumberInput
                      value={formData.maxDiscount}
                      onChange={value =>
                        setFormData({
                          ...formData,
                          maxDiscount: parseFloat(value),
                        })
                      }
                      min={0}
                      precision={2}
                    >
                      <NumberInputField />
                      <NumberInputStepper>
                        <NumberIncrementStepper />
                        <NumberDecrementStepper />
                      </NumberInputStepper>
                    </NumberInput>
                  </FormControl>
                </GridItem>
              </Grid>

              <Grid templateColumns="repeat(2, 1fr)" gap={4} w="full">
                <GridItem>
                  <FormControl>
                    <FormLabel>Usage Limit</FormLabel>
                    <NumberInput
                      value={formData.usageLimit}
                      onChange={value =>
                        setFormData({
                          ...formData,
                          usageLimit: parseInt(value),
                        })
                      }
                      min={1}
                      max={100000}
                    >
                      <NumberInputField />
                      <NumberInputStepper>
                        <NumberIncrementStepper />
                        <NumberDecrementStepper />
                      </NumberInputStepper>
                    </NumberInput>
                  </FormControl>
                </GridItem>
                <GridItem>
                  <FormControl>
                    <FormLabel>First Time Only</FormLabel>
                    <Switch
                      isChecked={formData.firstTimeOnly}
                      onChange={e =>
                        setFormData({
                          ...formData,
                          firstTimeOnly: e.target.checked,
                        })
                      }
                    />
                  </FormControl>
                </GridItem>
              </Grid>

              <Grid templateColumns="repeat(2, 1fr)" gap={4} w="full">
                <GridItem>
                  <FormControl isRequired>
                    <FormLabel>Valid From</FormLabel>
                    <Input
                      type="date"
                      value={formData.validFrom}
                      onChange={e =>
                        setFormData({ ...formData, validFrom: e.target.value })
                      }
                    />
                  </FormControl>
                </GridItem>
                <GridItem>
                  <FormControl isRequired>
                    <FormLabel>Valid To</FormLabel>
                    <Input
                      type="date"
                      value={formData.validTo}
                      onChange={e =>
                        setFormData({ ...formData, validTo: e.target.value })
                      }
                    />
                  </FormControl>
                </GridItem>
              </Grid>

              <FormControl>
                <FormLabel>Applicable Areas</FormLabel>
                <InputGroup>
                  <Input
                    value={newArea}
                    onChange={e => setNewArea(e.target.value)}
                    placeholder="Enter area ID"
                    onKeyPress={e => e.key === 'Enter' && addArea()}
                  />
                  <InputRightElement>
                    <Button size="sm" onClick={addArea}>
                      Add
                    </Button>
                  </InputRightElement>
                </InputGroup>
                <HStack spacing={2} mt={2} flexWrap="wrap">
                  {formData.applicableAreas.map(area => (
                    <Tag
                      key={area}
                      size="md"
                      colorScheme="blue"
                      borderRadius="full"
                    >
                      <TagLabel>{area}</TagLabel>
                      <TagCloseButton onClick={() => removeArea(area)} />
                    </Tag>
                  ))}
                </HStack>
              </FormControl>

              <FormControl>
                <FormLabel>Applicable Van Types</FormLabel>
                <InputGroup>
                  <Input
                    value={newVan}
                    onChange={e => setNewVan(e.target.value)}
                    placeholder="Enter van type"
                    onKeyPress={e => e.key === 'Enter' && addVan()}
                  />
                  <InputRightElement>
                    <Button size="sm" onClick={addVan}>
                      Add
                    </Button>
                  </InputRightElement>
                </InputGroup>
                <HStack spacing={2} mt={2} flexWrap="wrap">
                  {formData.applicableVans.map(van => (
                    <Tag
                      key={van}
                      size="md"
                      colorScheme="green"
                      borderRadius="full"
                    >
                      <TagLabel>{van}</TagLabel>
                      <TagCloseButton onClick={() => removeVan(van)} />
                    </Tag>
                  ))}
                </HStack>
              </FormControl>
            </VStack>
          </ModalBody>
          <ModalFooter>
            <Button variant="ghost" mr={3} onClick={onClose}>
              Cancel
            </Button>
            <Button
              leftIcon={<FiSave />}
              colorScheme="blue"
              onClick={handleSave}
            >
              Save Promotion
            </Button>
          </ModalFooter>
        </ModalContent>
      </Modal>
    </Box>
  );
}

'use client';
import React, { useState, useEffect } from 'react';
import {
  Box,
  Heading,
  HStack,
  VStack,
  Text,
  Badge,
  Card,
  CardBody,
  Button,
  Tabs,
  TabList,
  TabPanels,
  Tab,
  TabPanel,
  Grid,
  GridItem,
  Avatar,
  Stat,
  StatLabel,
  StatNumber,
  StatHelpText,
  SimpleGrid,
  Table,
  Thead,
  Tbody,
  Tr,
  Th,
  Td,
  Divider,
  useToast,
  Spinner,
  Alert,
  AlertIcon,
  Modal,
  ModalOverlay,
  ModalContent,
  ModalHeader,
  ModalBody,
  ModalFooter,
  ModalCloseButton,
  useDisclosure,
  Input,
  Textarea,
  Select,
} from '@chakra-ui/react';
import {
  FiUser,
  FiMail,
  FiPhone,
  FiMapPin,
  FiPackage,
  FiMessageSquare,
  FiFileText,
  FiDollarSign,
  FiFlag,
  FiDownload,
  FiRefreshCw,
  FiEdit,
} from 'react-icons/fi';
import { useRouter } from 'next/navigation';

interface CustomerDetailPageProps {
  params: {
    id: string;
  };
}

interface Customer {
  id: string;
  name: string;
  email: string;
  phone?: string;
  createdAt: string;
  joinedAt?: string;
  emailVerified: boolean;
  cancellations?: number;
  totalOrders?: number;
  lastOrder?: any;
  invoices?: any[];
  stats: {
    totalOrders: number;
    completedOrders: number;
    cancelledOrders: number;
    totalLtv: number;
    openTickets: number;
    urgentTickets: number;
    addressesCount: number;
    contactsCount: number;
  };
  orders: Array<{
    id: string;
    ref: string;
    status: string;
    amount: number;
    date: string;
    items: string[];
  }>;
  addresses: Array<{
    id: string;
    label: string;
    line1: string;
    line2: string;
    city: string;
    postcode: string;
    floor: string;
    flat: string;
    lift: boolean;
    notes: string;
    isDefault: boolean;
    createdAt: string;
    type?: string;
    address?: string;
  }>;
  contacts: Array<{
    id: string;
    label: string;
    name: string;
    phone: string;
    email: string;
    notes: string;
    isDefault: boolean;
    createdAt: string;
    relationship?: string;
  }>;
  supportTickets: Array<{
    id: string;
    category: string;
    orderRef: string;
    description: string;
    email: string;
    phone: string;
    status: string;
    priority: string;
    attachments: string[];
    createdAt: string;
    updatedAt: string;
    subject?: string;
    resolvedAt?: string;
    responses: Array<{
      id: string;
      message: string;
      isFromSupport: boolean;
      attachments: string[];
      createdAt: string;
    }>;
  }>;
  notificationPrefs?: any;
}

export default function CustomerDetailPage({
  params,
}: CustomerDetailPageProps) {
  const [customer, setCustomer] = useState<Customer | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [actionLoading, setActionLoading] = useState(false);
  const { isOpen, onOpen, onClose } = useDisclosure();
  const [actionData, setActionData] = useState({
    action: '',
    amount: '',
    reason: '',
    bookingId: '',
    notes: '',
  });

  const toast = useToast();
  const router = useRouter();

  // Fetch customer data from API
  const fetchCustomer = async () => {
    try {
      setLoading(true);
      setError(null);

      const response = await fetch(`/api/admin/customers/${params.id}`);

      if (!response.ok) {
        if (response.status === 404) {
          throw new Error('Customer not found');
        }
        throw new Error('Failed to fetch customer');
      }

      const data: Customer = await response.json();
      setCustomer(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An error occurred');
      toast({
        title: 'Error',
        description: 'Failed to fetch customer data',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setLoading(false);
    }
  };

  // Load customer data on mount
  useEffect(() => {
    const fetchCustomer = async () => {
      try {
        setLoading(true);
        const response = await fetch(`/api/admin/customers/${params.id}`);
        if (!response.ok) {
          throw new Error('Failed to fetch customer data');
        }
        const data: Customer = await response.json();
        setCustomer(data);
      } catch (error) {
        console.error('Error fetching customer:', error);
        toast({
          title: 'Error',
          description: 'Failed to load customer data',
          status: 'error',
        });
      } finally {
        setLoading(false);
      }
    };

    fetchCustomer();
  }, [params.id, toast]);

  // Handle customer actions
  const handleAction = async () => {
    if (!customer) return;

    try {
      setActionLoading(true);

      const response = await fetch(
        `/api/admin/customers/${customer.id}/actions`,
        {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify(actionData),
        }
      );

      if (!response.ok) {
        throw new Error('Failed to process action');
      }

      const result = await response.json();

      toast({
        title: 'Success',
        description: result.message,
        status: 'success',
        duration: 3000,
        isClosable: true,
      });

      onClose();
      setActionData({
        action: '',
        amount: '',
        reason: '',
        bookingId: '',
        notes: '',
      });

      // Refresh customer data
      fetchCustomer();
    } catch (err) {
      toast({
        title: 'Error',
        description:
          err instanceof Error ? err.message : 'Failed to process action',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setActionLoading(false);
    }
  };

  // Handle action modal
  const openActionModal = (action: string, bookingId?: string) => {
    setActionData({
      action,
      amount: '',
      reason: '',
      bookingId: bookingId || '',
      notes: '',
    });
    onOpen();
  };

  if (loading) {
    return (
      <Box>
        <VStack spacing={4} py={8}>
          <Spinner size="lg" />
          <Text>Loading customer data...</Text>
        </VStack>
      </Box>
    );
  }

  if (error || !customer) {
    return (
      <Box>
        <Alert status="error" mb={6}>
          <AlertIcon />
          {error || 'Customer not found'}
        </Alert>
        <Button
          onClick={() => router.push('/admin/customers')}
          variant="outline"
        >
          Back to Customers
        </Button>
      </Box>
    );
  }

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'active':
        return 'green';
      case 'inactive':
        return 'gray';
      case 'flagged':
        return 'red';
      case 'completed':
        return 'green';
      case 'cancelled':
        return 'red';
      case 'resolved':
        return 'green';
      case 'open':
        return 'yellow';
      case 'paid':
        return 'green';
      default:
        return 'gray';
    }
  };

  const getPriorityColor = (priority: string) => {
    switch (priority) {
      case 'high':
        return 'red';
      case 'medium':
        return 'yellow';
      case 'low':
        return 'green';
      default:
        return 'gray';
    }
  };

  return (
    <Box>
      {/* Header */}
      <HStack justify="space-between" mb={6}>
        <HStack spacing={4}>
          <Avatar size="lg" name={customer.name} />
          <VStack align="start" spacing={1}>
            <Heading size="lg">{customer.name}</Heading>
            <HStack spacing={2}>
              <Badge
                colorScheme={customer.stats.totalOrders > 0 ? 'green' : 'gray'}
              >
                {customer.stats.totalOrders > 0 ? 'Active' : 'New'}
              </Badge>
              {customer.emailVerified && (
                <Badge colorScheme="blue" variant="outline">
                  Verified
                </Badge>
              )}
              {customer.stats.openTickets > 0 && (
                <Badge colorScheme="orange">
                  {customer.stats.openTickets} Open Tickets
                </Badge>
              )}
            </HStack>
            <Text color="gray.600">
              Joined {new Date(customer.createdAt).toLocaleDateString()}
            </Text>
          </VStack>
        </HStack>
        <HStack spacing={3}>
          <Button
            leftIcon={<FiRefreshCw />}
            variant="outline"
            size="sm"
            onClick={fetchCustomer}
            isLoading={loading}
          >
            Refresh
          </Button>
          <Button
            leftIcon={<FiFlag />}
            variant="outline"
            size="sm"
            onClick={() => openActionModal('add_flag')}
          >
            Flag Customer
          </Button>
          <Button
            leftIcon={<FiDownload />}
            variant="outline"
            size="sm"
            onClick={() => openActionModal('export_data')}
          >
            Export Data
          </Button>
          <Button colorScheme="blue" size="sm">
            Edit Profile
          </Button>
        </HStack>
      </HStack>

      {/* Stats Row */}
      <SimpleGrid columns={{ base: 1, md: 2, lg: 4 }} spacing={4} mb={6}>
        <Card>
          <CardBody>
            <Stat>
              <StatLabel>Total Orders</StatLabel>
              <StatNumber>{customer.stats.totalOrders}</StatNumber>
              <StatHelpText>
                <FiPackage style={{ display: 'inline', marginRight: '4px' }} />
                All time
              </StatHelpText>
            </Stat>
          </CardBody>
        </Card>

        <Card>
          <CardBody>
            <Stat>
              <StatLabel>Lifetime Value</StatLabel>
              <StatNumber>
                £{(customer.stats.totalLtv || 0).toLocaleString()}
              </StatNumber>
              <StatHelpText>
                <FiDollarSign
                  style={{ display: 'inline', marginRight: '4px' }}
                />
                Total spent
              </StatHelpText>
            </Stat>
          </CardBody>
        </Card>

        <Card>
          <CardBody>
            <Stat>
              <StatLabel>Cancellations</StatLabel>
              <StatNumber>{customer.stats.cancelledOrders}</StatNumber>
              <StatHelpText>
                <FiFlag style={{ display: 'inline', marginRight: '4px' }} />
                Rate:{' '}
                {(
                  ((customer.cancellations || 0) /
                    (customer.totalOrders || 1)) *
                  100
                ).toFixed(1)}
                %
              </StatHelpText>
            </Stat>
          </CardBody>
        </Card>

        <Card>
          <CardBody>
            <Stat>
              <StatLabel>Member Since</StatLabel>
              <StatNumber>
                {new Date(
                  customer.joinedAt || customer.createdAt
                ).getFullYear()}
              </StatNumber>
              <StatHelpText>
                <FiUser style={{ display: 'inline', marginRight: '4px' }} />
                {new Date(
                  customer.joinedAt || customer.createdAt
                ).toLocaleDateString()}
              </StatHelpText>
            </Stat>
          </CardBody>
        </Card>
      </SimpleGrid>

      <Tabs>
        <TabList>
          <Tab>Overview</Tab>
          <Tab>Orders</Tab>
          <Tab>Support</Tab>
          <Tab>Invoices</Tab>
        </TabList>

        <TabPanels>
          {/* Overview Tab */}
          <TabPanel>
            <Grid templateColumns={{ base: '1fr', lg: '2fr 1fr' }} gap={6}>
              <VStack spacing={6} align="stretch">
                {/* Contact Information */}
                <Card>
                  <CardBody>
                    <Heading size="md" mb={4}>
                      Contact Information
                    </Heading>
                    <VStack spacing={4} align="stretch">
                      <HStack>
                        <FiMail />
                        <VStack align="start" spacing={1}>
                          <Text fontWeight="bold">Email</Text>
                          <Text>{customer.email}</Text>
                        </VStack>
                      </HStack>
                      <HStack>
                        <FiPhone />
                        <VStack align="start" spacing={1}>
                          <Text fontWeight="bold">Phone</Text>
                          <Text>{customer.phone}</Text>
                        </VStack>
                      </HStack>
                      <HStack>
                        <FiUser />
                        <VStack align="start" spacing={1}>
                          <Text fontWeight="bold">Last Order</Text>
                          <Text>
                            {customer.lastOrder
                              ? new Date(
                                  customer.lastOrder
                                ).toLocaleDateString()
                              : 'No orders'}
                          </Text>
                        </VStack>
                      </HStack>
                    </VStack>
                  </CardBody>
                </Card>

                {/* Saved Addresses */}
                <Card>
                  <CardBody>
                    <Heading size="md" mb={4}>
                      Saved Addresses
                    </Heading>
                    <VStack spacing={3} align="stretch">
                      {(customer.addresses || []).map(address => (
                        <HStack
                          key={address.id}
                          justify="space-between"
                          p={3}
                          bg="gray.50"
                          borderRadius="md"
                        >
                          <VStack align="start" spacing={1}>
                            <HStack>
                              <FiMapPin />
                              <Text
                                fontWeight="bold"
                                textTransform="capitalize"
                              >
                                {address.type || 'Address'}
                              </Text>
                              {address.isDefault && (
                                <Badge colorScheme="green" size="sm">
                                  Default
                                </Badge>
                              )}
                            </HStack>
                            <Text fontSize="sm">
                              {address.address ||
                                `${address.line1}, ${address.city}`}
                            </Text>
                          </VStack>
                          <Button size="sm" variant="outline">
                            Edit
                          </Button>
                        </HStack>
                      ))}
                    </VStack>
                  </CardBody>
                </Card>

                {/* Emergency Contacts */}
                <Card>
                  <CardBody>
                    <Heading size="md" mb={4}>
                      Emergency Contacts
                    </Heading>
                    <VStack spacing={3} align="stretch">
                      {(customer.contacts || []).map(contact => (
                        <HStack
                          key={contact.id}
                          justify="space-between"
                          p={3}
                          bg="gray.50"
                          borderRadius="md"
                        >
                          <VStack align="start" spacing={1}>
                            <Text fontWeight="bold">{contact.name}</Text>
                            <Text fontSize="sm" color="gray.600">
                              {contact.relationship || 'Contact'}
                            </Text>
                            <Text fontSize="sm">{contact.phone}</Text>
                            <Text fontSize="sm">{contact.email}</Text>
                          </VStack>
                          <Button size="sm" variant="outline">
                            Edit
                          </Button>
                        </HStack>
                      ))}
                    </VStack>
                  </CardBody>
                </Card>
              </VStack>

              <VStack spacing={6} align="stretch">
                {/* Quick Actions */}
                <Card>
                  <CardBody>
                    <Heading size="md" mb={4}>
                      Quick Actions
                    </Heading>
                    <VStack spacing={3} align="stretch">
                      <Button
                        leftIcon={<FiPackage />}
                        colorScheme="blue"
                        size="sm"
                      >
                        Create New Order
                      </Button>
                      <Button
                        leftIcon={<FiMessageSquare />}
                        variant="outline"
                        size="sm"
                      >
                        Send Message
                      </Button>
                      <Button
                        leftIcon={<FiDollarSign />}
                        variant="outline"
                        size="sm"
                      >
                        Issue Refund
                      </Button>
                      <Button
                        leftIcon={<FiFileText />}
                        variant="outline"
                        size="sm"
                      >
                        Generate Invoice
                      </Button>
                    </VStack>
                  </CardBody>
                </Card>

                {/* Recent Activity */}
                <Card>
                  <CardBody>
                    <Heading size="md" mb={4}>
                      Recent Activity
                    </Heading>
                    <VStack spacing={3} align="stretch">
                      <HStack justify="space-between">
                        <Text fontSize="sm">Order completed</Text>
                        <Text fontSize="sm" color="gray.600">
                          2 days ago
                        </Text>
                      </HStack>
                      <HStack justify="space-between">
                        <Text fontSize="sm">Support ticket opened</Text>
                        <Text fontSize="sm" color="gray.600">
                          1 day ago
                        </Text>
                      </HStack>
                      <HStack justify="space-between">
                        <Text fontSize="sm">Payment received</Text>
                        <Text fontSize="sm" color="gray.600">
                          3 days ago
                        </Text>
                      </HStack>
                    </VStack>
                  </CardBody>
                </Card>
              </VStack>
            </Grid>
          </TabPanel>

          {/* Orders Tab */}
          <TabPanel>
            <Card>
              <CardBody>
                <Heading size="md" mb={4}>
                  Order History
                </Heading>
                <Table variant="simple">
                  <Thead>
                    <Tr>
                      <Th>Order Ref</Th>
                      <Th>Date</Th>
                      <Th>Items</Th>
                      <Th>Amount</Th>
                      <Th>Status</Th>
                      <Th>Actions</Th>
                    </Tr>
                  </Thead>
                  <Tbody>
                    {(customer.orders || []).map(order => (
                      <Tr key={order.id}>
                        <Td>
                          <Text fontWeight="bold">{order.ref}</Text>
                        </Td>
                        <Td>
                          <Text fontSize="sm">
                            {new Date(order.date).toLocaleDateString()}
                          </Text>
                        </Td>
                        <Td>
                          <Text fontSize="sm">
                            {(order.items || []).join(', ')}
                          </Text>
                        </Td>
                        <Td>
                          <Text fontWeight="bold">
                            £{(order.amount || 0).toFixed(2)}
                          </Text>
                        </Td>
                        <Td>
                          <Badge colorScheme={getStatusColor(order.status)}>
                            {order.status}
                          </Badge>
                        </Td>
                        <Td>
                          <HStack spacing={2}>
                            <Button size="xs" variant="outline">
                              View
                            </Button>
                            {order.status === 'completed' && (
                              <Button size="xs" variant="outline">
                                Refund
                              </Button>
                            )}
                          </HStack>
                        </Td>
                      </Tr>
                    ))}
                  </Tbody>
                </Table>
              </CardBody>
            </Card>
          </TabPanel>

          {/* Support Tab */}
          <TabPanel>
            <Card>
              <CardBody>
                <Heading size="md" mb={4}>
                  Support Tickets
                </Heading>
                <Table variant="simple">
                  <Thead>
                    <Tr>
                      <Th>Subject</Th>
                      <Th>Status</Th>
                      <Th>Priority</Th>
                      <Th>Created</Th>
                      <Th>Resolved</Th>
                      <Th>Actions</Th>
                    </Tr>
                  </Thead>
                  <Tbody>
                    {(customer.supportTickets || []).map(ticket => (
                      <Tr key={ticket.id}>
                        <Td>
                          <Text fontWeight="bold">{ticket.subject}</Text>
                        </Td>
                        <Td>
                          <Badge colorScheme={getStatusColor(ticket.status)}>
                            {ticket.status}
                          </Badge>
                        </Td>
                        <Td>
                          <Badge
                            colorScheme={getPriorityColor(ticket.priority)}
                          >
                            {ticket.priority}
                          </Badge>
                        </Td>
                        <Td>
                          <Text fontSize="sm">
                            {new Date(ticket.createdAt).toLocaleDateString()}
                          </Text>
                        </Td>
                        <Td>
                          <Text fontSize="sm">
                            {ticket.resolvedAt
                              ? new Date(ticket.resolvedAt).toLocaleDateString()
                              : '-'}
                          </Text>
                        </Td>
                        <Td>
                          <Button size="xs" variant="outline">
                            View
                          </Button>
                        </Td>
                      </Tr>
                    ))}
                  </Tbody>
                </Table>
              </CardBody>
            </Card>
          </TabPanel>

          {/* Invoices Tab */}
          <TabPanel>
            <Card>
              <CardBody>
                <Heading size="md" mb={4}>
                  Invoices
                </Heading>
                <Table variant="simple">
                  <Thead>
                    <Tr>
                      <Th>Invoice Ref</Th>
                      <Th>Date</Th>
                      <Th>Due Date</Th>
                      <Th>Amount</Th>
                      <Th>Status</Th>
                      <Th>Actions</Th>
                    </Tr>
                  </Thead>
                  <Tbody>
                    {(customer.invoices || []).map(invoice => (
                      <Tr key={invoice.id}>
                        <Td>
                          <Text fontWeight="bold">{invoice.ref}</Text>
                        </Td>
                        <Td>
                          <Text fontSize="sm">
                            {invoice.date
                              ? new Date(invoice.date).toLocaleDateString()
                              : 'N/A'}
                          </Text>
                        </Td>
                        <Td>
                          <Text fontSize="sm">
                            {invoice.dueDate
                              ? new Date(invoice.dueDate).toLocaleDateString()
                              : 'N/A'}
                          </Text>
                        </Td>
                        <Td>
                          <Text fontWeight="bold">
                            £{(invoice.amount || 0).toFixed(2)}
                          </Text>
                        </Td>
                        <Td>
                          <Badge colorScheme={getStatusColor(invoice.status)}>
                            {invoice.status}
                          </Badge>
                        </Td>
                        <Td>
                          <HStack spacing={2}>
                            <Button size="xs" variant="outline">
                              View
                            </Button>
                            <Button size="xs" variant="outline">
                              Download
                            </Button>
                          </HStack>
                        </Td>
                      </Tr>
                    ))}
                  </Tbody>
                </Table>
              </CardBody>
            </Card>
          </TabPanel>
        </TabPanels>
      </Tabs>

      {/* Action Modal */}
      <Modal isOpen={isOpen} onClose={onClose}>
        <ModalOverlay />
        <ModalContent>
          <ModalHeader>
            {actionData.action === 'issue_refund' && 'Issue Refund'}
            {actionData.action === 'issue_credit' && 'Issue Credit'}
            {actionData.action === 'add_flag' && 'Flag Customer'}
            {actionData.action === 'remove_flag' && 'Remove Flag'}
            {actionData.action === 'export_data' && 'Export Customer Data'}
            {actionData.action === 'resend_invoice' && 'Resend Invoice'}
          </ModalHeader>
          <ModalCloseButton />
          <ModalBody>
            {actionData.action === 'issue_refund' && (
              <VStack spacing={4}>
                <Select
                  placeholder="Select booking"
                  value={actionData.bookingId}
                  onChange={e =>
                    setActionData(prev => ({
                      ...prev,
                      bookingId: e.target.value,
                    }))
                  }
                >
                  {(customer.orders || [])
                    .filter(b => b.status === 'completed')
                    .map(booking => (
                      <option key={booking.id} value={booking.id}>
                        {booking.ref} - £{(booking.amount || 0).toFixed(2)}
                      </option>
                    ))}
                </Select>
                <Input
                  placeholder="Amount (£)"
                  type="number"
                  step="0.01"
                  value={actionData.amount}
                  onChange={e =>
                    setActionData(prev => ({ ...prev, amount: e.target.value }))
                  }
                />
                <Select
                  placeholder="Reason"
                  value={actionData.reason}
                  onChange={e =>
                    setActionData(prev => ({ ...prev, reason: e.target.value }))
                  }
                >
                  <option value="customer_request">Customer Request</option>
                  <option value="service_issue">Service Issue</option>
                  <option value="billing_error">Billing Error</option>
                  <option value="other">Other</option>
                </Select>
                <Textarea
                  placeholder="Additional notes"
                  value={actionData.notes}
                  onChange={e =>
                    setActionData(prev => ({ ...prev, notes: e.target.value }))
                  }
                />
              </VStack>
            )}

            {actionData.action === 'issue_credit' && (
              <VStack spacing={4}>
                <Input
                  placeholder="Amount (£)"
                  type="number"
                  step="0.01"
                  value={actionData.amount}
                  onChange={e =>
                    setActionData(prev => ({ ...prev, amount: e.target.value }))
                  }
                />
                <Select
                  placeholder="Reason"
                  value={actionData.reason}
                  onChange={e =>
                    setActionData(prev => ({ ...prev, reason: e.target.value }))
                  }
                >
                  <option value="compensation">Compensation</option>
                  <option value="loyalty">Loyalty Credit</option>
                  <option value="promotion">Promotion</option>
                  <option value="other">Other</option>
                </Select>
                <Textarea
                  placeholder="Additional notes"
                  value={actionData.notes}
                  onChange={e =>
                    setActionData(prev => ({ ...prev, notes: e.target.value }))
                  }
                />
              </VStack>
            )}

            {(actionData.action === 'add_flag' ||
              actionData.action === 'remove_flag') && (
              <VStack spacing={4}>
                <Select
                  placeholder="Reason"
                  value={actionData.reason}
                  onChange={e =>
                    setActionData(prev => ({ ...prev, reason: e.target.value }))
                  }
                >
                  <option value="payment_issues">Payment Issues</option>
                  <option value="service_complaints">Service Complaints</option>
                  <option value="fraud_suspicion">Fraud Suspicion</option>
                  <option value="other">Other</option>
                </Select>
                <Textarea
                  placeholder="Additional notes"
                  value={actionData.notes}
                  onChange={e =>
                    setActionData(prev => ({ ...prev, notes: e.target.value }))
                  }
                />
              </VStack>
            )}

            {actionData.action === 'export_data' && (
              <VStack spacing={4}>
                <Text>This will export all customer data including:</Text>
                <Text fontSize="sm" color="gray.600">
                  • Personal information
                  <br />
                  • Order history
                  <br />
                  • Addresses and contacts
                  <br />
                  • Support tickets
                  <br />• Payment information
                </Text>
                <Text fontSize="sm" color="blue.600">
                  This action is logged for GDPR compliance.
                </Text>
              </VStack>
            )}

            {actionData.action === 'resend_invoice' && (
              <VStack spacing={4}>
                <Select
                  placeholder="Select booking"
                  value={actionData.bookingId}
                  onChange={e =>
                    setActionData(prev => ({
                      ...prev,
                      bookingId: e.target.value,
                    }))
                  }
                >
                  {(customer.orders || [])
                    .filter(b => b.status === 'completed')
                    .map(booking => (
                      <option key={booking.id} value={booking.id}>
                        {booking.ref} - £{(booking.amount || 0).toFixed(2)}
                      </option>
                    ))}
                </Select>
              </VStack>
            )}
          </ModalBody>
          <ModalFooter>
            <Button variant="ghost" mr={3} onClick={onClose}>
              Cancel
            </Button>
            <Button
              colorScheme="blue"
              onClick={handleAction}
              isLoading={actionLoading}
            >
              {actionData.action === 'export_data' ? 'Export Data' : 'Confirm'}
            </Button>
          </ModalFooter>
        </ModalContent>
      </Modal>
    </Box>
  );
}

'use client';

import React, { useState, useEffect, useCallback, useRef } from 'react';
import {
  Box,
  Grid,
  GridItem,
  Heading,
  Text,
  Stat,
  StatLabel,
  StatNumber,
  StatHelpText,
  Badge,
  VStack,
  HStack,
  Card,
  CardBody,
  SimpleGrid,
  Alert,
  AlertIcon,
  Button,
  Spinner,
  useToast,
  IconButton,
  Tooltip,
  Flex,
  Progress,
} from '@chakra-ui/react';
import {
  FiDollarSign,
  FiTruck,
  FiClock,
  FiMessageSquare,
  FiAlertTriangle,
  FiPlus,
  FiRefreshCw,
  FiMapPin,
  FiExternalLink,
  FiTrendingUp,
  FiTrendingDown,
  FiCheck,
} from 'react-icons/fi';
import { AdminShell } from '@/components/admin';
import { DashboardMap } from '@/components/admin/DashboardMap';
import RoutingModeToggle from '@/components/admin/RoutingModeToggle';
import { useRouter } from 'next/navigation';

interface DashboardData {
  alerts: {
    unassignedBookings: number;
    slaBreached: number;
    urgentBookings: number;
  };
  statistics: {
    todayRevenue: number;
    todayBookings: number;
    activeJobs: number;
    completedToday: number;
    pendingAssignments: number;
    driverUtilization: number;
  };
  unassignedBookings: Array<{
    id: string;
    reference: string;
    customer: string;
    customerPhone: string;
    pickupAddress: string;
    dropoffAddress: string;
    scheduledAt: string;
    totalAmount: number;
    waitingMinutes: number;
    priority: string;
    slaBreached: boolean;
    itemsCount: number;
    createdAt: string;
  }>;
  availableDrivers: Array<{
    id: string;
    name: string;
    email: string;
    status: string;
    currentJobs: number;
    isOnline: boolean;
    lastSeen: string;
  }>;
  recentActivity: Array<{
    id: string;
    action: string;
    actorName: string;
    targetType: string;
    targetId: string;
    createdAt: string;
    details: any;
  }>;
  adminUsers: Array<{
    id: string;
    name: string;
    email: string;
    adminRole: string;
    isActive: boolean;
    lastLogin: string;
    isOnline: boolean;
  }>;
  systemHealth: {
    database: string;
    queue: string;
    pusher: string;
    stripeWebhooks: string;
  };
}

export default function AdminDashboard() {
  const [data, setData] = useState<DashboardData | null>(null);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [lastUpdated, setLastUpdated] = useState<Date | null>(null);
  const toast = useToast();
  const router = useRouter();
  const intervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const fetchRef = useRef<(() => Promise<void>) | null>(null);

  const fetchDashboardData = useCallback(async () => {
    try {
      const response = await fetch('/api/admin/dashboard-enhanced', {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
      });

      if (!response.ok) {
        throw new Error('Failed to fetch dashboard data');
      }

      const result = await response.json();
      setData(result.data);
      setLastUpdated(new Date());
    } catch (error) {
      console.error('Error fetching dashboard data:', error);
      toast({
        title: 'Error',
        description: 'Failed to load dashboard data',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  }, [toast]);

  // Update ref whenever fetchDashboardData changes
  useEffect(() => {
    fetchRef.current = fetchDashboardData;
  }, [fetchDashboardData]);

  useEffect(() => {
    fetchDashboardData();
  }, [fetchDashboardData]);

  // Auto-refresh every 15 seconds to ensure all new orders are visible
  useEffect(() => {
    // Clear any existing interval
    if (intervalRef.current) {
      clearInterval(intervalRef.current);
    }

    intervalRef.current = setInterval(() => {
      // Use ref to avoid stale closure
      if (fetchRef.current && !loading) {
        fetchRef.current();
      }
    }, 15000); // Reduced from 30 to 15 seconds

    return () => {
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
        intervalRef.current = null;
      }
    };
  }, []); // Empty dependency array to prevent re-creation

  const handleRefresh = () => {
    setRefreshing(true);
    fetchDashboardData();
  };

  const handleCreateOrder = () => {
    router.push('/booking-luxury');
  };

  const handleCardClick = (type: string, value?: string) => {
    switch (type) {
      case 'revenue':
        router.push('/admin/analytics');
        break;
      case 'activeJobs':
        router.push(
          '/admin/orders?status=assigned,en-route,at-pickup,in-transit,at-drop'
        );
        break;
      case 'newOrders':
        router.push('/admin/orders?status=pending,confirmed');
        break;
      case 'driverApplications':
        router.push('/admin/drivers/applications');
        break;
      case 'pendingRefunds':
        router.push('/admin/finance/refunds');
        break;
      case 'openIncidents':
        router.push('/admin/dispatch?filter=incidents');
        break;
      case 'job':
        if (value) {
          router.push(`/admin/orders/${value}`);
        }
        break;
      default:
        break;
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'en-route':
        return 'blue';
      case 'at-pickup':
        return 'yellow';
      case 'in-transit':
        return 'purple';
      case 'at-drop':
        return 'orange';
      case 'late-pickup':
        return 'red';
      default:
        return 'gray';
    }
  };

  const getHealthColor = (status: string) => {
    return status === 'healthy' ? 'green' : 'red';
  };

  if (loading) {
    return (
      <AdminShell title="Dashboard" subtitle="Loading...">
        <Flex justify="center" align="center" height="400px">
          <Spinner size="xl" />
        </Flex>
      </AdminShell>
    );
  }

  if (!data) {
    return (
      <AdminShell title="Dashboard" subtitle="Error loading data">
        <Alert status="error">
          <AlertIcon />
          Failed to load dashboard data. Please try refreshing.
        </Alert>
      </AdminShell>
    );
  }

  return (
    <AdminShell
      title="Dashboard"
      subtitle="Real-time operations overview"
      showCreateButton={true}
      onCreateClick={handleCreateOrder}
      actions={
        <HStack spacing={2}>
          <Text fontSize="sm" color="gray.500">
            <span suppressHydrationWarning>
              Last updated: {lastUpdated?.toLocaleTimeString() || 'Loading...'}
            </span>
          </Text>
          <Tooltip label="Refresh dashboard data">
            <IconButton
              size="sm"
              variant="outline"
              icon={<FiRefreshCw />}
              onClick={handleRefresh}
              isLoading={refreshing}
              aria-label="Refresh"
            />
          </Tooltip>
          <Button
            size="sm"
            variant="outline"
            leftIcon={<FiMapPin />}
            onClick={() => router.push('/admin/dispatch/map')}
          >
            Live Map
          </Button>
        </HStack>
      }
    >
      {/* Routing Mode Toggle */}
      <Box mb={6}>
        <RoutingModeToggle />
      </Box>
      <Box>
        {/* KPI Row */}
        <SimpleGrid columns={{ base: 1, md: 2, lg: 5 }} spacing={4} mb={8}>
          <Card
            cursor="pointer"
            onClick={() => handleCardClick('revenue')}
            _hover={{ transform: 'translateY(-2px)', shadow: 'lg' }}
            transition="all 0.2s"
          >
            <CardBody>
              <Stat>
                <StatLabel>Today Revenue</StatLabel>
                <StatNumber>
                  £{(data.statistics.todayRevenue || 0).toLocaleString('en-GB', {
                    minimumFractionDigits: 2,
                    maximumFractionDigits: 2
                  })}
                </StatNumber>
                <StatHelpText>
                  <HStack spacing={1}>
                    <FiTrendingUp color="green" />
                    <Text color="green.500">
                      Bookings: {data.statistics.todayBookings || 0}
                    </Text>
                  </HStack>
                </StatHelpText>
              </Stat>
            </CardBody>
          </Card>

          <Card
            cursor="pointer"
            onClick={() => handleCardClick('activeJobs')}
            _hover={{ transform: 'translateY(-2px)', shadow: 'lg' }}
            transition="all 0.2s"
          >
            <CardBody>
              <Stat>
                <StatLabel>Active Jobs</StatLabel>
                <StatNumber>{data.statistics.activeJobs || 0}</StatNumber>
                <StatHelpText>
                  <FiTruck style={{ display: 'inline', marginRight: '4px' }} />
                  In progress
                </StatHelpText>
              </Stat>
            </CardBody>
          </Card>

          <Card
            cursor="pointer"
            onClick={() => handleCardClick('newOrders')}
            _hover={{ transform: 'translateY(-2px)', shadow: 'lg' }}
            transition="all 0.2s"
            bg={(data.alerts.unassignedBookings || 0) > 0 ? 'orange.50' : 'white'}
            borderColor={
              (data.alerts.unassignedBookings || 0) > 0 ? 'orange.200' : 'gray.200'
            }
          >
            <CardBody>
              <Stat>
                <StatLabel>New Orders</StatLabel>
                <StatNumber
                  color={
                    (data.alerts.unassignedBookings || 0) > 0 ? 'orange.600' : 'inherit'
                  }
                >
                  {data.alerts.unassignedBookings || 0}
                </StatNumber>
                <StatHelpText>
                  <FiPlus style={{ display: 'inline', marginRight: '4px' }} />
                  Pending assignment
                </StatHelpText>
              </Stat>
            </CardBody>
          </Card>

          <Card>
            <CardBody>
              <Stat>
                <StatLabel>Completed Today</StatLabel>
                <StatNumber>{data.statistics.completedToday || 0}</StatNumber>
                <StatHelpText>
                  <FiCheck style={{ display: 'inline', marginRight: '4px' }} />
                  Finished jobs
                </StatHelpText>
              </Stat>
            </CardBody>
          </Card>

          <Card>
            <CardBody>
              <Stat>
                <StatLabel>Driver Utilization</StatLabel>
                <StatNumber>{data.statistics.driverUtilization || 0}%</StatNumber>
                <StatHelpText>
                  <FiTruck
                    style={{ display: 'inline', marginRight: '4px' }}
                  />
                  Active drivers
                </StatHelpText>
              </Stat>
            </CardBody>
          </Card>

          <Card
            cursor="pointer"
            onClick={() => handleCardClick('openIncidents')}
            _hover={{ transform: 'translateY(-2px)', shadow: 'lg' }}
            transition="all 0.2s"
          >
            <CardBody>
              <Stat>
                <StatLabel>SLA Breached</StatLabel>
                <StatNumber>{data.alerts.slaBreached || 0}</StatNumber>
                <StatHelpText>
                  <FiAlertTriangle
                    style={{ display: 'inline', marginRight: '4px' }}
                  />
                  Need attention
                </StatHelpText>
              </Stat>
            </CardBody>
          </Card>
        </SimpleGrid>

        <Grid templateColumns={{ base: '1fr', lg: '2fr 1fr' }} gap={6}>
          {/* Live Ops Panel */}
          <Card>
            <CardBody>
              <Flex justify="space-between" align="center" mb={4}>
                <Heading size="md">Live Operations</Heading>
                <Badge colorScheme="blue">{data.unassignedBookings.length} pending</Badge>
              </Flex>
              <VStack spacing={3} align="stretch">
                {data.unassignedBookings.length === 0 ? (
                  <Text color="gray.500" textAlign="center" py={4}>
                    No pending bookings at the moment
                  </Text>
                ) : (
                  data.unassignedBookings.map(booking => (
                    <Card
                      key={booking.id}
                      size="sm"
                      cursor="pointer"
                      onClick={() => handleCardClick('booking', booking.id)}
                      _hover={{ shadow: 'md' }}
                      transition="all 0.2s"
                    >
                      <CardBody p={3}>
                        <HStack justify="space-between">
                          <VStack align="start" spacing={1} flex={1}>
                            <HStack>
                              <Text fontWeight="bold">{booking.reference}</Text>
                              <IconButton
                                size="xs"
                                variant="ghost"
                                icon={<FiExternalLink />}
                                aria-label="View booking details"
                                onClick={e => {
                                  e.stopPropagation();
                                  handleCardClick('booking', booking.id);
                                }}
                              />
                            </HStack>
                            <Text fontSize="sm" color="gray.600">
                              {booking.customer}
                            </Text>
                            <Text fontSize="xs" color="gray.500" noOfLines={1}>
                              {booking.pickupAddress} → {booking.dropoffAddress}
                            </Text>
                          </VStack>
                          <VStack align="end" spacing={1}>
                            <Badge colorScheme={booking.slaBreached ? 'red' : booking.priority === 'high' ? 'orange' : 'blue'}>
                              {booking.slaBreached ? 'SLA BREACH' : booking.priority.toUpperCase()}
                            </Badge>
                            <Text fontSize="sm" color="gray.600">
                              £{booking.totalAmount}
                            </Text>
                            <Text fontSize="xs" color="gray.500">
                              {booking.waitingMinutes}m waiting
                            </Text>
                          </VStack>
                        </HStack>
                        {/* SLA Progress Bar */}
                        {booking.waitingMinutes > 0 && (
                          <Progress
                            value={Math.min(
                              (booking.waitingMinutes / 60) * 100,
                              100
                            )}
                            size="xs"
                            mt={2}
                            colorScheme={
                              booking.slaBreached ? 'red' : booking.waitingMinutes > 30 ? 'orange' : 'blue'
                            }
                          />
                        )}
                      </CardBody>
                    </Card>
                  ))
                )}
              </VStack>
            </CardBody>
          </Card>

          {/* Queue & Health */}
          <VStack spacing={6}>
            {/* Queue */}
            <Card>
              <CardBody>
                <Heading size="md" mb={4}>
                  Queue
                </Heading>
                <VStack spacing={3} align="stretch">
                  <Card
                    size="sm"
                    cursor="pointer"
                    onClick={() => handleCardClick('driverApplications')}
                    _hover={{ shadow: 'md' }}
                    transition="all 0.2s"
                  >
                    <CardBody p={3}>
                      <HStack justify="space-between">
                        <Text>Available Drivers</Text>
                        <Badge colorScheme="green">
                          {data.availableDrivers.length}
                        </Badge>
                      </HStack>
                    </CardBody>
                  </Card>

                  <Card
                    size="sm"
                    cursor="pointer"
                    onClick={() => handleCardClick('pendingRefunds')}
                    _hover={{ shadow: 'md' }}
                    transition="all 0.2s"
                  >
                    <CardBody p={3}>
                      <HStack justify="space-between">
                        <Text>Pending Assignments</Text>
                        <Badge colorScheme="orange">
                          {data.statistics.pendingAssignments}
                        </Badge>
                      </HStack>
                    </CardBody>
                  </Card>

                  <Card
                    size="sm"
                    cursor="pointer"
                    onClick={() => router.push('/admin/finance/payouts')}
                    _hover={{ shadow: 'md' }}
                    transition="all 0.2s"
                  >
                    <CardBody p={3}>
                      <HStack justify="space-between">
                        <Text>Urgent Bookings</Text>
                        <Badge colorScheme="red">
                          {data.alerts.urgentBookings}
                        </Badge>
                      </HStack>
                    </CardBody>
                  </Card>
                </VStack>
              </CardBody>
            </Card>

            {/* System Health */}
            <Card>
              <CardBody>
                <Heading size="md" mb={4}>
                  System Health
                </Heading>
                <VStack spacing={3} align="stretch">
                  {Object.entries(data.systemHealth).map(
                    ([service, status]) => (
                      <HStack key={service} justify="space-between">
                        <Text textTransform="capitalize">
                          {service.replace(/([A-Z])/g, ' $1')}
                        </Text>
                        <Badge colorScheme={getHealthColor(status)}>
                          {status}
                        </Badge>
                      </HStack>
                    )
                  )}
                </VStack>
              </CardBody>
            </Card>

            {/* Admin Team */}
            <Card>
              <CardBody>
                <Flex justify="space-between" align="center" mb={4}>
                  <Heading size="md">Admin Team</Heading>
                  <Button
                    size="sm"
                    colorScheme="blue"
                    leftIcon={<FiPlus />}
                    onClick={() => router.push('/admin/settings/team')}
                  >
                    Manage Team
                  </Button>
                </Flex>
                <VStack spacing={3} align="stretch">
                  {(data.adminUsers || []).slice(0, 3).map((admin) => (
                    <HStack key={admin.id} justify="space-between">
                      <VStack align="start" spacing={0}>
                        <Text fontWeight="medium" fontSize="sm">
                          {admin.name || 'Admin User'}
                        </Text>
                        <Text fontSize="xs" color="gray.500">
                          {admin.email || 'admin@speedy-van.co.uk'}
                        </Text>
                      </VStack>
                      <VStack align="end" spacing={0}>
                        <Badge colorScheme={admin.isOnline ? 'green' : 'gray'} size="sm">
                          {admin.isOnline ? 'Online' : 'Offline'}
                        </Badge>
                        <Text fontSize="xs" color="gray.500">
                          {admin.adminRole || 'admin'}
                        </Text>
                      </VStack>
                    </HStack>
                  ))}
                  {(!data.adminUsers || data.adminUsers.length === 0) && (
                    <Text fontSize="sm" color="gray.500" textAlign="center" py={2}>
                      No admin users found
                    </Text>
                  )}
                </VStack>
              </CardBody>
            </Card>
          </VStack>
        </Grid>

        {/* Map Snapshot */}
        <Card mt={6}>
          <CardBody>
            <Flex justify="space-between" align="center" mb={4}>
              <Heading size="md">Active Crews & Order Heat Map</Heading>
              <Button
                size="sm"
                variant="outline"
                leftIcon={<FiMapPin />}
                onClick={() => router.push('/admin/dispatch/map')}
              >
                View Full Map
              </Button>
            </Flex>
            <DashboardMap
              activeJobs={[]}
              height="300px"
              showControls={true}
            />
          </CardBody>
        </Card>
      </Box>
    </AdminShell>
  );
}

'use client';

import React, { useState } from 'react';
import {
  Box,
  Grid,
  Card,
  CardBody,
  CardHeader,
  Heading,
  Text,
  Badge,
  HStack,
  VStack,
  Button,
  SimpleGrid,
  Table,
  Thead,
  Tbody,
  Tr,
  Th,
  Td,
  useToast,
  Alert,
  AlertIcon,
  AlertTitle,
  AlertDescription,
  Spinner,
  Stat,
  StatLabel,
  StatNumber,
  StatHelpText,
} from '@chakra-ui/react';
import {
  FaTruck,
  FaUserTie,
  FaCheckCircle,
  FaExclamationTriangle,
  FaMapMarkedAlt,
  FaUsers,
  FaClock,
} from 'react-icons/fa';

interface DispatchData {
  jobsByStatus: Record<string, number>;
  activeJobs: any[];
  availableDrivers: any[];
  openIncidents: any[];
  autoAssignRules: any;
}

interface DispatchClientProps {
  data: DispatchData;
}

export default function DispatchClient({ data }: DispatchClientProps) {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const toast = useToast();

  // Error boundary for component
  if (error) {
    return (
      <Box p={6}>
        <Alert status="error" mb={4}>
          <AlertIcon />
          <AlertTitle>Error!</AlertTitle>
          <AlertDescription>{error}</AlertDescription>
        </Alert>
        <Button onClick={() => setError(null)} colorScheme="blue">
          Try Again
        </Button>
      </Box>
    );
  }

  // Validate data structure with better error handling
  if (!data || typeof data !== 'object') {
    return (
      <Box p={6}>
        <Alert status="error" mb={4}>
          <AlertIcon />
          <AlertTitle>Data Error!</AlertTitle>
          <AlertDescription>
            Invalid dispatch data received. Please refresh the page.
          </AlertDescription>
        </Alert>
        <Button onClick={() => window.location.reload()} colorScheme="blue">
          Refresh Page
        </Button>
      </Box>
    );
  }

  // Additional validation for required data properties
  if (
    !data.jobsByStatus ||
    !data.activeJobs ||
    !data.availableDrivers ||
    !data.openIncidents
  ) {
    return (
      <Box p={6}>
        <Alert status="warning" mb={4}>
          <AlertIcon />
          <AlertTitle>Incomplete Data!</AlertTitle>
          <AlertDescription>
            Some dispatch data is missing. Please refresh the page.
          </AlertDescription>
        </Alert>
        <Button onClick={() => window.location.reload()} colorScheme="blue">
          Refresh Page
        </Button>
      </Box>
    );
  }

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'DRAFT':
        return 'gray';
      case 'CONFIRMED':
        return 'blue';
      case 'COMPLETED':
        return 'green';
      case 'CANCELLED':
        return 'red';
      default:
        return 'gray';
    }
  };

  const handleAssignJob = async (jobId: string, driverId: string) => {
    setLoading(true);
    try {
      const response = await fetch(`/api/admin/dispatch/assign`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          jobId,
          driverId,
        }),
      });

      if (response.ok) {
        toast({
          title: 'Job assigned successfully',
          description: 'The job has been assigned to the driver',
          status: 'success',
          duration: 3000,
          isClosable: true,
        });
        // Refresh data
        window.location.reload();
      } else {
        throw new Error('Assignment failed');
      }
    } catch (error) {
      toast({
        title: 'Assignment failed',
        description: 'Failed to assign job to driver',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setLoading(false);
    }
  };

  return (
    <Box>
      {/* Header */}
      <VStack align="start" spacing={4} mb={6}>
        <Heading size="lg">Dispatch & Operations</Heading>
        <Text color="gray.600">
          Manage job assignments and monitor operations
        </Text>
      </VStack>

      {/* Stats Overview */}
      <SimpleGrid columns={{ base: 1, md: 2, lg: 4 }} spacing={4} mb={6}>
        <Card>
          <CardBody>
            <Stat>
              <StatLabel>Total Jobs</StatLabel>
              <StatNumber>
                {Object.values(data.jobsByStatus).reduce((a, b) => a + b, 0)}
              </StatNumber>
              <StatHelpText>
                <FaTruck style={{ display: 'inline', marginRight: '4px' }} />
                All statuses
              </StatHelpText>
            </Stat>
          </CardBody>
        </Card>

        <Card>
          <CardBody>
            <Stat>
              <StatLabel>Available Drivers</StatLabel>
              <StatNumber>{data.availableDrivers.length}</StatNumber>
              <StatHelpText>
                <FaUsers style={{ display: 'inline', marginRight: '4px' }} />
                Online drivers
              </StatHelpText>
            </Stat>
          </CardBody>
        </Card>

        <Card>
          <CardBody>
            <Stat>
              <StatLabel>Active Jobs</StatLabel>
              <StatNumber>{data.activeJobs.length}</StatNumber>
              <StatHelpText>
                <FaClock style={{ display: 'inline', marginRight: '4px' }} />
                In progress
              </StatHelpText>
            </Stat>
          </CardBody>
        </Card>

        <Card>
          <CardBody>
            <Stat>
              <StatLabel>Open Incidents</StatLabel>
              <StatNumber color="red.500">
                {data.openIncidents.length}
              </StatNumber>
              <StatHelpText>
                <FaExclamationTriangle
                  style={{ display: 'inline', marginRight: '4px' }}
                />
                Requires attention
              </StatHelpText>
            </Stat>
          </CardBody>
        </Card>
      </SimpleGrid>

      {/* Job Status Overview */}
      <Card mb={6}>
        <CardHeader>
          <Heading size="md">Job Status Overview</Heading>
        </CardHeader>
        <CardBody>
          <SimpleGrid columns={{ base: 2, md: 4 }} spacing={4}>
            {Object.entries(data.jobsByStatus).map(([status, count]) => (
              <Box
                key={status}
                textAlign="center"
                p={4}
                borderWidth={1}
                borderRadius="md"
              >
                <Badge colorScheme={getStatusColor(status)} mb={2}>
                  {status}
                </Badge>
                <Text fontSize="2xl" fontWeight="bold">
                  {count}
                </Text>
                <Text fontSize="sm" color="gray.600">
                  jobs
                </Text>
              </Box>
            ))}
          </SimpleGrid>
        </CardBody>
      </Card>

      {/* Active Jobs */}
      <Card mb={6}>
        <CardHeader>
          <Heading size="md">Active Jobs</Heading>
        </CardHeader>
        <CardBody>
          {data.activeJobs.length === 0 ? (
            <Text color="gray.500" textAlign="center" py={8}>
              No active jobs at the moment
            </Text>
          ) : (
            <Table variant="simple">
              <Thead>
                <Tr>
                  <Th>Reference</Th>
                  <Th>Customer</Th>
                  <Th>Driver</Th>
                  <Th>Status</Th>
                  <Th>Created</Th>
                  <Th>Actions</Th>
                </Tr>
              </Thead>
              <Tbody>
                {data.activeJobs.slice(0, 10).map(job => (
                  <Tr key={job.id}>
                    <Td>
                      <Text fontWeight="bold" fontSize="sm">
                        {job.reference}
                      </Text>
                    </Td>
                    <Td>
                      <Text fontSize="sm">
                        {job.customer && job.customer.name
                          ? job.customer.name
                          : 'Unknown'}
                      </Text>
                    </Td>
                    <Td>
                      <Text fontSize="sm">
                        {job.driver && job.driver.user && job.driver.user.name
                          ? job.driver.user.name
                          : 'Unassigned'}
                      </Text>
                    </Td>
                    <Td>
                      <Badge colorScheme={getStatusColor(job.status)} size="sm">
                        {job.status}
                      </Badge>
                    </Td>
                    <Td>
                      <Text fontSize="sm">
                        {new Date(job.createdAt).toLocaleDateString()}
                      </Text>
                    </Td>
                    <Td>
                      {!job.driver && data.availableDrivers.length > 0 && (
                        <Button
                          size="sm"
                          colorScheme="blue"
                          isLoading={loading}
                          onClick={() =>
                            handleAssignJob(job.id, data.availableDrivers[0].id)
                          }
                        >
                          Assign
                        </Button>
                      )}
                    </Td>
                  </Tr>
                ))}
              </Tbody>
            </Table>
          )}
        </CardBody>
      </Card>

      {/* Available Drivers */}
      <Card mb={6}>
        <CardHeader>
          <Heading size="md">Available Drivers</Heading>
        </CardHeader>
        <CardBody>
          {data.availableDrivers.length === 0 ? (
            <Text color="gray.500" textAlign="center" py={8}>
              No drivers available at the moment
            </Text>
          ) : (
            <SimpleGrid columns={{ base: 1, md: 2, lg: 3 }} spacing={4}>
              {data.availableDrivers.map(driver => (
                <Box key={driver.id} p={4} borderWidth={1} borderRadius="md">
                  <HStack justify="space-between" mb={2}>
                    <Text fontWeight="bold">
                      {driver.user && driver.user.name
                        ? driver.user.name
                        : 'Unknown'}
                    </Text>
                    <Badge colorScheme="green" size="sm">
                      Available
                    </Badge>
                  </HStack>
                  <Text fontSize="sm" color="gray.600">
                    {driver.user && driver.user.email
                      ? driver.user.email
                      : 'No email'}
                  </Text>
                  {driver.vehicles && driver.vehicles.length > 0 && (
                    <Text fontSize="sm" color="gray.600">
                      Vehicle: {driver.vehicles[0].make}{' '}
                      {driver.vehicles[0].model}
                    </Text>
                  )}
                </Box>
              ))}
            </SimpleGrid>
          )}
        </CardBody>
      </Card>

      {/* Open Incidents */}
      {data.openIncidents.length > 0 && (
        <Card>
          <CardHeader>
            <Heading size="md">Open Incidents</Heading>
          </CardHeader>
          <CardBody>
            <Table variant="simple">
              <Thead>
                <Tr>
                  <Th>Driver</Th>
                  <Th>Type</Th>
                  <Th>Description</Th>
                  <Th>Reported</Th>
                </Tr>
              </Thead>
              <Tbody>
                {data.openIncidents.map(incident => (
                  <Tr key={incident.id}>
                    <Td>
                      <Text fontSize="sm">
                        {incident.driver &&
                        incident.driver.user &&
                        incident.driver.user.name
                          ? incident.driver.user.name
                          : 'Unknown'}
                      </Text>
                    </Td>
                    <Td>
                      <Badge colorScheme="red" size="sm">
                        {incident.type}
                      </Badge>
                    </Td>
                    <Td>
                      <Text fontSize="sm">{incident.description}</Text>
                    </Td>
                    <Td>
                      <Text fontSize="sm">
                        {new Date(incident.createdAt).toLocaleDateString()}
                      </Text>
                    </Td>
                  </Tr>
                ))}
              </Tbody>
            </Table>
          </CardBody>
        </Card>
      )}
    </Box>
  );
}

import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { redirect } from 'next/navigation';
import { prisma } from '@/lib/prisma';
import DispatchClient from './DispatchClient';

// CRITICAL: Force dynamic rendering because we use getServerSession()
export const dynamic = 'force-dynamic';
export const revalidate = 0;

async function getDispatchData() {
  // Get jobs by status for board view
  const jobsByStatus = await prisma.booking.groupBy({
    by: ['status'],
    where: {
      status: {
        in: ['DRAFT', 'CONFIRMED', 'COMPLETED', 'CANCELLED'],
      },
    },
    _count: {
      id: true,
    },
  });

  // Get active jobs with driver info
  const activeJobs = await prisma.booking.findMany({
    where: {
      status: {
        in: ['CONFIRMED'],
      },
    },
    include: {
      driver: {
        include: {
          User: {
            select: {
              id: true,
              name: true,
              email: true,
              role: true,
              createdAt: true,
              isActive: true,
              lastLogin: true,
              resetTokenExpiry: true,
              emailVerificationExpiry: true
            }
          },
          DriverAvailability: true,
        },
      },
    },
    orderBy: {
      createdAt: 'desc',
    },
  });

  // Get available drivers
  const availableDrivers = await prisma.driver.findMany({
    where: {
      status: 'active',
      onboardingStatus: 'approved',
      DriverAvailability: {
        status: 'online',
      },
    },
    include: {
      User: {
        select: {
          id: true,
          name: true,
          email: true,
          role: true,
          createdAt: true,
          isActive: true,
          lastLogin: true,
          resetTokenExpiry: true,
          emailVerificationExpiry: true
        }
      },
      DriverAvailability: true,
      DriverVehicle: true,
    },
  });

  // Get open incidents
  const openIncidents = await prisma.driverIncident.findMany({
    where: {
      status: 'reported',
    },
    include: {
      Driver: {
        include: {
          User: {
            select: {
              id: true,
              name: true,
              email: true,
              role: true,
              createdAt: true,
              isActive: true,
              lastLogin: true,
              resetTokenExpiry: true,
              emailVerificationExpiry: true
            }
          },
        },
      },
      Assignment: {
        include: {
          Booking: true,
        },
      },
    },
    orderBy: {
      createdAt: 'desc',
    },
    take: 10,
  });

  // Get auto-assign rules (from config or default)
  const autoAssignRules = {
    radius: 5000, // 5km
    vehicleType: 'any',
    capacity: 'any',
    loadLimit: 'any',
    rating: 4.0,
    maxJobs: 3,
  };

  // Serialize data to ensure it can be passed to client components
  const serializedActiveJobs = activeJobs.map(job => ({
    ...job,
    createdAt: job.createdAt.toISOString(),
    updatedAt: job.updatedAt.toISOString(),
    scheduledAt: job.scheduledAt.toISOString(),
    paidAt: job.paidAt?.toISOString(),
    driver: job.driver ? {
      ...job.driver,
      createdAt: job.driver.createdAt.toISOString(),
      updatedAt: job.driver.updatedAt.toISOString(),
      approvedAt: job.driver.approvedAt?.toISOString(),
      user: {
        ...job.driver.User,
        createdAt: job.driver.User.createdAt.toISOString(),
        lastLogin: job.driver.User.lastLogin?.toISOString(),
        resetTokenExpiry: job.driver.User.resetTokenExpiry?.toISOString(),
        emailVerificationExpiry: job.driver.User.emailVerificationExpiry?.toISOString(),
      },
      availability: job.driver.DriverAvailability ? {
        ...job.driver.DriverAvailability,
        createdAt: job.driver.DriverAvailability.createdAt.toISOString(),
        updatedAt: job.driver.DriverAvailability.updatedAt.toISOString(),
      } : null,
    } : null,
  }));

  const serializedAvailableDrivers = availableDrivers.map(driver => ({
    ...driver,
    createdAt: driver.createdAt.toISOString(),
    updatedAt: driver.updatedAt.toISOString(),
    approvedAt: driver.approvedAt?.toISOString(),
    user: {
      ...driver.User,
      createdAt: driver.User.createdAt.toISOString(),
      lastLogin: driver.User.lastLogin?.toISOString(),
      resetTokenExpiry: driver.User.resetTokenExpiry?.toISOString(),
      emailVerificationExpiry: driver.User.emailVerificationExpiry?.toISOString(),
    },
    availability: driver.DriverAvailability ? {
      ...driver.DriverAvailability,
      createdAt: driver.DriverAvailability.createdAt.toISOString(),
      updatedAt: driver.DriverAvailability.updatedAt.toISOString(),
    } : null,
    vehicles: driver.DriverVehicle.map(vehicle => ({
      ...vehicle,
      createdAt: vehicle.createdAt.toISOString(),
      motExpiry: vehicle.motExpiry?.toISOString(),
    })),
  }));

  const serializedOpenIncidents = openIncidents.map(incident => ({
    ...incident,
    createdAt: incident.createdAt.toISOString(),
    updatedAt: incident.updatedAt?.toISOString(),
    driver: {
      ...incident.Driver,
      createdAt: incident.Driver.createdAt.toISOString(),
      updatedAt: incident.Driver.updatedAt.toISOString(),
      approvedAt: incident.Driver.approvedAt?.toISOString(),
      user: {
        ...incident.Driver.User,
        createdAt: incident.Driver.User.createdAt.toISOString(),
        lastLogin: (incident.Driver.User as any).lastLogin?.toISOString(),
        resetTokenExpiry: (incident.Driver.User as any).resetTokenExpiry?.toISOString(),
        emailVerificationExpiry: (incident.Driver.User as any).emailVerificationExpiry?.toISOString(),
      },
    },
    Assignment: incident.Assignment ? {
      ...incident.Assignment,
      createdAt: incident.Assignment.createdAt.toISOString(),
      updatedAt: incident.Assignment.updatedAt.toISOString(),
      Booking: {
        ...incident.Assignment.Booking,
        createdAt: incident.Assignment.Booking.createdAt.toISOString(),
        updatedAt: incident.Assignment.Booking.updatedAt.toISOString(),
        scheduledAt: incident.Assignment.Booking.scheduledAt.toISOString(),
        paidAt: incident.Assignment.Booking.paidAt?.toISOString(),
      },
    } : null,
  }));

  return {
    jobsByStatus: jobsByStatus.reduce(
      (acc, item) => {
        acc[item.status] = item._count.id;
        return acc;
      },
      {} as Record<string, number>
    ),
    activeJobs: serializedActiveJobs,
    availableDrivers: serializedAvailableDrivers,
    openIncidents: serializedOpenIncidents,
    autoAssignRules,
  };
}

export default async function DispatchPage() {
  const session = await getServerSession(authOptions);
  if (!session?.user || (session.user as any).role !== 'admin')
    redirect('/auth/login');

  const data = await getDispatchData();

  return <DispatchClient data={data} />;
}

'use client';

import { useEffect, useState } from 'react';
import { useParams, useRouter } from 'next/navigation';
