}

interface DriverEarnings {
  driver: {
    id: string;
    user: {
      name: string;
      email: string;
    };
    commissionRate: number;
  };
  summary: {
    totalEarnings: number;
    totalCommission: number;
    netEarnings: number;
    completedJobs: number;
    averagePerJob: number;
  };
