              <span className="text-gray-600">Value:</span>
              <span className="font-semibold text-green-600">£{item.value.toFixed(2)}</span>
            </div>
          </div>
        </div>
        <button
          onClick={() => router.push(`/admin/routes/${item.id}`)}
          className="ml-4 px-3 py-1 bg-blue-600 text-white rounded hover:bg-blue-700 text-sm"
        >
          View
        </button>
      </div>
    </div>
  );

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
      </div>
    );
  }

  if (!schedule) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen">
        <h1 className="text-2xl font-bold text-gray-900 mb-4">Driver Not Found</h1>
        <button
          onClick={() => router.push('/admin/routes')}
          className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700"
        >
          Back to Routes
        </button>
      </div>
    );
  }

  const currentItems = activeTab === 'today' ? schedule.today :
                       activeTab === 'upcoming' ? schedule.upcoming :
                       schedule.completed;

  return (
    <div className="container mx-auto px-4 py-8">
      {/* Header */}
      <div className="mb-6">
        <button
          onClick={() => router.push('/admin/routes')}
          className="mb-4 text-blue-600 hover:text-blue-800 flex items-center"
        >
          ← Back to Routes
        </button>
        <h1 className="text-3xl font-bold text-gray-900">Driver Schedule</h1>
      </div>

      {/* Driver Info Card */}
      <div className="bg-white rounded-lg shadow-md p-6 mb-6">
        <div className="flex items-center justify-between">
          <div>
            <h2 className="text-2xl font-bold">{schedule.driver.user.name}</h2>
            <p className="text-gray-600">{schedule.driver.user.email}</p>
            {schedule.driver.user.phone && (
              <p className="text-gray-600">{schedule.driver.user.phone}</p>
            )}
          </div>
          <span className={`px-4 py-2 rounded-full text-sm font-medium ${
            schedule.driver.status === 'ONLINE' ? 'bg-green-100 text-green-800' :
            schedule.driver.status === 'BUSY' ? 'bg-yellow-100 text-yellow-800' :
            'bg-gray-100 text-gray-800'
          }`}>
            {schedule.driver.status}
          </span>
        </div>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
        <div className="bg-white rounded-lg shadow-md p-6">
          <p className="text-sm text-gray-600">Today's Jobs</p>
          <p className="text-3xl font-bold text-blue-600">{schedule.today.length}</p>
        </div>
        <div className="bg-white rounded-lg shadow-md p-6">
          <p className="text-sm text-gray-600">Upcoming Jobs</p>
          <p className="text-3xl font-bold text-purple-600">{schedule.upcoming.length}</p>
        </div>
        <div className="bg-white rounded-lg shadow-md p-6">
          <p className="text-sm text-gray-600">Completed Jobs</p>
          <p className="text-3xl font-bold text-green-600">{schedule.completed.length}</p>
        </div>
      </div>

      {/* Tabs */}
      <div className="bg-white rounded-lg shadow-md">
        <div className="border-b">
          <div className="flex space-x-4 px-6">
            <button
              onClick={() => setActiveTab('today')}
              className={`py-4 px-2 border-b-2 font-medium text-sm ${
                activeTab === 'today'
                  ? 'border-blue-600 text-blue-600'
                  : 'border-transparent text-gray-500 hover:text-gray-700'
              }`}
            >
              Today ({schedule.today.length})
            </button>
            <button
              onClick={() => setActiveTab('upcoming')}
              className={`py-4 px-2 border-b-2 font-medium text-sm ${
                activeTab === 'upcoming'
                  ? 'border-blue-600 text-blue-600'
                  : 'border-transparent text-gray-500 hover:text-gray-700'
              }`}
            >
              Upcoming ({schedule.upcoming.length})
            </button>
            <button
              onClick={() => setActiveTab('completed')}
              className={`py-4 px-2 border-b-2 font-medium text-sm ${
                activeTab === 'completed'
                  ? 'border-blue-600 text-blue-600'
                  : 'border-transparent text-gray-500 hover:text-gray-700'
              }`}
            >
              Completed ({schedule.completed.length})
            </button>
          </div>
        </div>

        {/* Schedule Items */}
        <div className="p-6">
          {currentItems.length === 0 ? (
            <div className="text-center py-12 text-gray-500">
              No {activeTab} jobs
            </div>
          ) : (
            <div className="space-y-4">
              {currentItems.map(renderScheduleItem)}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import {
  Box,
  Container,
  VStack,
  HStack,
  Heading,
  Text,
  Button,
  Card,
  CardBody,
  CardHeader,
  Badge,
  Grid,
  GridItem,
  Image,
  Divider,
  Alert,
  AlertIcon,
  Spinner,
  useToast,
  Modal,
  ModalOverlay,
  ModalContent,
  ModalHeader,
  ModalBody,
  ModalFooter,
  ModalCloseButton,
  useDisclosure,
  Textarea,
  Select,
  FormControl,
  FormLabel,
  Stat,
  StatLabel,
  StatNumber,
  StatHelpText,
  Progress,
  Flex,
  Icon,
  useColorModeValue,
} from '@chakra-ui/react';
import {
  FiUser,
  FiMail,
  FiPhone,
  FiMapPin,
  FiCalendar,
  FiFileText,
  FiTruck,
  FiShield,
  FiCreditCard,
  FiUsers,
  FiCheck,
  FiX,
  FiEye,
  FiDownload,
  FiArrowLeft,
  FiStar,
  FiAlertTriangle,
} from 'react-icons/fi';
import { AdminShell } from '@/components/admin';
import { useRouter } from 'next/navigation';
import { useParams } from 'next/navigation';

interface DriverApplicationDetails {
  id: string;
  name: string;
  email: string;
  phone: string;
  dateOfBirth: string;
  nationalInsuranceNumber: string;
  score: number;
  scorePercentage: number;
  status: 'pending' | 'approved' | 'rejected' | 'under_review' | 'requires_additional_info';
  
  address: {
    line1: string;
    line2?: string;
    city: string;
    postcode: string;
    county: string;
    fullAddress: string;
  };
  
  driving: {
    licenseNumber: string;
    licenseExpiry: string;
    licenseFrontImage?: string;
    licenseBackImage?: string;
  };
  
  insurance: {
    provider: string;
    policyNumber: string;
    expiry: string;
    document?: string;
  };
  
  banking: {
    bankName: string;
    accountHolderName: string;
    sortCode: string;
    accountNumber: string;
  };
  
  rightToWork: {
    shareCode: string;
    document?: string;
  };
  
  emergencyContact: {
    name: string;
    phone: string;
    relationship: string;
  };
  
  terms: {
    agreeToTerms: boolean;
    agreeToDataProcessing: boolean;
    agreeToBackgroundCheck: boolean;
  };
  
  documents: {
    license: { status: string; url?: string };
    insurance: { status: string; url?: string };
    rightToWork: { status: string; url?: string };
  };
  
  appliedAt: string;
  applicationAge: number;
  complianceIssues: string[];
  complianceWarnings: string[];
  autoApproveEligible: boolean;
  reviewedAt?: string;
  reviewedBy?: string;
  reviewNotes?: string;
}

export default function DriverApplicationDetailsPage() {
  const params = useParams();
  const router = useRouter();
  const toast = useToast();
  const [application, setApplication] = useState<DriverApplicationDetails | null>(null);
  const [loading, setLoading] = useState(true);
  const [actionLoading, setActionLoading] = useState(false);
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [reviewNotes, setReviewNotes] = useState('');
  const [newStatus, setNewStatus] = useState<string>('');
  
  const { isOpen: isReviewOpen, onOpen: onReviewOpen, onClose: onReviewClose } = useDisclosure();
  const { isOpen: isImageOpen, onOpen: onImageOpen, onClose: onImageClose } = useDisclosure();
  
  const bgColor = useColorModeValue('white', 'gray.800');
  const borderColor = useColorModeValue('gray.200', 'gray.700');

  useEffect(() => {
    if (params?.id) {
      fetchApplicationDetails();
    }
  }, [params?.id]);

  const fetchApplicationDetails = async () => {
    try {
      setLoading(true);
      const response = await fetch(`/api/admin/drivers/applications/${params?.id}`);
      
      if (response.ok) {
        const data = await response.json();
        setApplication(data);
        setReviewNotes(data.reviewNotes || '');
        setNewStatus(data.status || '');
      } else {
        throw new Error('Failed to fetch application details');
      }
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to load application details',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
      console.error('Error fetching application details:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleStatusUpdate = async () => {
    if (!application || !newStatus) return;
    
    try {
      setActionLoading(true);
      const response = await fetch(`/api/admin/drivers/applications/${application.id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          status: newStatus,
          reviewNotes: reviewNotes,
        }),
      });

      if (response.ok) {
        toast({
          title: 'Success',
          description: 'Application status updated successfully',
          status: 'success',
          duration: 3000,
          isClosable: true,
        });
        fetchApplicationDetails();
        onReviewClose();
      } else {
        throw new Error('Failed to update application');
      }
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to update application status',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setActionLoading(false);
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'approved':
        return 'green';
      case 'rejected':
        return 'red';
      case 'under_review':
        return 'blue';
      case 'requires_additional_info':
        return 'orange';
      case 'pending':
      default:
        return 'yellow';
    }
  };

  const getScoreColor = (score: number) => {
    if (score >= 90) return 'green';
    if (score >= 70) return 'yellow';
    if (score >= 50) return 'orange';
    return 'red';
  };

  const openImageModal = (imageUrl: string) => {
    setSelectedImage(imageUrl);
    onImageOpen();
  };

  if (loading) {
    return (
      <AdminShell title="Application Details" subtitle="Loading...">
        <Flex justify="center" align="center" height="400px">
          <Spinner size="xl" />
        </Flex>
      </AdminShell>
    );
  }

  if (!application) {
    return (
      <AdminShell title="Application Details" subtitle="Not Found">
        <Alert status="error">
          <AlertIcon />
          Application not found or you don't have permission to view it.
        </Alert>
      </AdminShell>
    );
  }

  return (
    <AdminShell 
      title="Application Details" 
      subtitle={`${application.name} - ${application.email}`}
      actions={
        <HStack spacing={3}>
          <Button
            variant="outline"
            leftIcon={<FiArrowLeft />}
            onClick={() => router.push('/admin/drivers/applications')}
          >
            Back to Applications
          </Button>
          <Button
            colorScheme="blue"
            leftIcon={<FiFileText />}
            onClick={onReviewOpen}
          >
            Review Application
          </Button>
        </HStack>
      }
    >
      <Container maxW="container.xl" py={6}>
        <VStack spacing={8} align="stretch">
          
          {/* Application Overview */}
          <Grid templateColumns={{ base: '1fr', lg: '2fr 1fr' }} gap={6}>
            <VStack spacing={6} align="stretch">
              
              {/* Personal Information */}
              <Card bg={bgColor} borderColor={borderColor}>
                <CardHeader>
                  <HStack spacing={3}>
                    <Icon as={FiUser} color="blue.500" boxSize={5} />
                    <Heading size="md">Personal Information</Heading>
                  </HStack>
                </CardHeader>
                <CardBody>
                  <Grid templateColumns="repeat(2, 1fr)" gap={4}>
                    <Box>
                      <Text fontSize="sm" color="gray.500" mb={1}>Full Name</Text>
                      <Text fontWeight="medium">{application.name}</Text>
                    </Box>
                    <Box>
                      <Text fontSize="sm" color="gray.500" mb={1}>Email</Text>
                      <Text fontWeight="medium">{application.email}</Text>
                    </Box>
                    <Box>
                      <Text fontSize="sm" color="gray.500" mb={1}>Phone</Text>
                      <Text fontWeight="medium">{application.phone}</Text>
                    </Box>
                    <Box>
                      <Text fontSize="sm" color="gray.500" mb={1}>Date of Birth</Text>
                      <Text fontWeight="medium">
                        {new Date(application.dateOfBirth).toLocaleDateString('en-GB')}
                      </Text>
                    </Box>
                    <Box>
                      <Text fontSize="sm" color="gray.500" mb={1}>National Insurance</Text>
                      <Text fontWeight="medium">{application.nationalInsuranceNumber}</Text>
                    </Box>
                  </Grid>
                </CardBody>
              </Card>

              {/* Address Information */}
              <Card bg={bgColor} borderColor={borderColor}>
                <CardHeader>
                  <HStack spacing={3}>
                    <Icon as={FiMapPin} color="green.500" boxSize={5} />
                    <Heading size="md">Address Information</Heading>
                  </HStack>
                </CardHeader>
                <CardBody>
                  <VStack spacing={3} align="stretch">
                    <Box>
                      <Text fontSize="sm" color="gray.500" mb={1}>Full Address</Text>
                      <Text fontWeight="medium">{application.address.fullAddress}</Text>
                    </Box>
                    <Grid templateColumns="repeat(2, 1fr)" gap={4}>
                      <Box>
                        <Text fontSize="sm" color="gray.500" mb={1}>City</Text>
                        <Text fontWeight="medium">{application.address.city}</Text>
                      </Box>
                      <Box>
                        <Text fontSize="sm" color="gray.500" mb={1}>Postcode</Text>
                        <Text fontWeight="medium">{application.address.postcode}</Text>
                      </Box>
                    </Grid>
                  </VStack>
                </CardBody>
              </Card>

              {/* Driving Information */}
              <Card bg={bgColor} borderColor={borderColor}>
                <CardHeader>
                  <HStack spacing={3}>
                    <Icon as={FiTruck} color="purple.500" boxSize={5} />
                    <Heading size="md">Driving Information</Heading>
                  </HStack>
                </CardHeader>
                <CardBody>
                  <Grid templateColumns="repeat(2, 1fr)" gap={4}>
                    <Box>
                      <Text fontSize="sm" color="gray.500" mb={1}>License Number</Text>
                      <Text fontWeight="medium">{application.driving.licenseNumber}</Text>
                    </Box>
                    <Box>
                      <Text fontSize="sm" color="gray.500" mb={1}>License Expiry</Text>
                      <Text fontWeight="medium">
                        {new Date(application.driving.licenseExpiry).toLocaleDateString('en-GB')}
                      </Text>
                    </Box>
                  </Grid>
                  
                  <Divider my={4} />
                  
                  <Text fontSize="sm" color="gray.500" mb={3}>License Images</Text>
                  <HStack spacing={4}>
                    {application.driving.licenseFrontImage && (
                      <Box>
                        <Text fontSize="xs" color="gray.500" mb={2}>Front</Text>
                        <Box
                          w="120px"
                          h="80px"
                          borderRadius="md"
                          overflow="hidden"
                          cursor="pointer"
                          onClick={() => openImageModal(application.driving.licenseFrontImage!)}
                          _hover={{ transform: 'scale(1.05)' }}
                          transition="transform 0.2s"
                        >
                          <Image
                            src={application.driving.licenseFrontImage}
                            alt="License Front"
                            w="100%"
                            h="100%"
                            objectFit="cover"
                          />
                        </Box>
                      </Box>
                    )}
                    {application.driving.licenseBackImage && (
                      <Box>
                        <Text fontSize="xs" color="gray.500" mb={2}>Back</Text>
                        <Box
                          w="120px"
                          h="80px"
                          borderRadius="md"
                          overflow="hidden"
                          cursor="pointer"
                          onClick={() => openImageModal(application.driving.licenseBackImage!)}
                          _hover={{ transform: 'scale(1.05)' }}
                          transition="transform 0.2s"
                        >
                          <Image
                            src={application.driving.licenseBackImage}
                            alt="License Back"
                            w="100%"
                            h="100%"
                            objectFit="cover"
                          />
                        </Box>
                      </Box>
                    )}
                  </HStack>
                </CardBody>
              </Card>

              {/* Insurance & Banking */}
              <Grid templateColumns={{ base: '1fr', md: 'repeat(2, 1fr)' }} gap={6}>
                <Card bg={bgColor} borderColor={borderColor}>
                  <CardHeader>
                    <HStack spacing={3}>
                      <Icon as={FiShield} color="orange.500" boxSize={5} />
                      <Heading size="md">Insurance</Heading>
                    </HStack>
                  </CardHeader>
                  <CardBody>
                    <VStack spacing={3} align="stretch">
                      <Box>
                        <Text fontSize="sm" color="gray.500" mb={1}>Provider</Text>
                        <Text fontWeight="medium">{application.insurance.provider}</Text>
                      </Box>
                      <Box>
                        <Text fontSize="sm" color="gray.500" mb={1}>Policy Number</Text>
                        <Text fontWeight="medium">{application.insurance.policyNumber}</Text>
                      </Box>
                      <Box>
                        <Text fontSize="sm" color="gray.500" mb={1}>Expiry Date</Text>
                        <Text fontWeight="medium">
                          {new Date(application.insurance.expiry).toLocaleDateString('en-GB')}
                        </Text>
                      </Box>
                      {application.insurance.document && (
                        <Button
                          size="sm"
                          variant="outline"
                          leftIcon={<FiEye />}
                          onClick={() => openImageModal(application.insurance.document!)}
                        >
                          View Document
                        </Button>
                      )}
                    </VStack>
                  </CardBody>
                </Card>

                <Card bg={bgColor} borderColor={borderColor}>
                  <CardHeader>
                    <HStack spacing={3}>
                      <Icon as={FiCreditCard} color="teal.500" boxSize={5} />
                      <Heading size="md">Banking</Heading>
                    </HStack>
                  </CardHeader>
                  <CardBody>
                    <VStack spacing={3} align="stretch">
                      <Box>
                        <Text fontSize="sm" color="gray.500" mb={1}>Bank Name</Text>
                        <Text fontWeight="medium">{application.banking.bankName}</Text>
                      </Box>
                      <Box>
                        <Text fontSize="sm" color="gray.500" mb={1}>Account Holder</Text>
                        <Text fontWeight="medium">{application.banking.accountHolderName}</Text>
                      </Box>
                      <Grid templateColumns="repeat(2, 1fr)" gap={3}>
                        <Box>
                          <Text fontSize="sm" color="gray.500" mb={1}>Sort Code</Text>
                          <Text fontWeight="medium">{application.banking.sortCode}</Text>
                        </Box>
                        <Box>
                          <Text fontSize="sm" color="gray.500" mb={1}>Account Number</Text>
                          <Text fontWeight="medium">****{application.banking.accountNumber.slice(-4)}</Text>
                        </Box>
                      </Grid>
                    </VStack>
                  </CardBody>
                </Card>
              </Grid>

              {/* Emergency Contact */}
              <Card bg={bgColor} borderColor={borderColor}>
                <CardHeader>
                  <HStack spacing={3}>
                    <Icon as={FiUsers} color="red.500" boxSize={5} />
                    <Heading size="md">Emergency Contact</Heading>
                  </HStack>
                </CardHeader>
                <CardBody>
                  <Grid templateColumns="repeat(3, 1fr)" gap={4}>
                    <Box>
                      <Text fontSize="sm" color="gray.500" mb={1}>Name</Text>
                      <Text fontWeight="medium">{application.emergencyContact.name}</Text>
                    </Box>
                    <Box>
                      <Text fontSize="sm" color="gray.500" mb={1}>Phone</Text>
                      <Text fontWeight="medium">{application.emergencyContact.phone}</Text>
                    </Box>
                    <Box>
                      <Text fontSize="sm" color="gray.500" mb={1}>Relationship</Text>
                      <Text fontWeight="medium">{application.emergencyContact.relationship}</Text>
                    </Box>
                  </Grid>
                </CardBody>
              </Card>
            </VStack>

            {/* Sidebar */}
            <VStack spacing={6} align="stretch">
              
              {/* Application Status */}
              <Card bg={bgColor} borderColor={borderColor}>
                <CardBody>
                  <VStack spacing={4} align="stretch">
                    <HStack justify="space-between">
                      <Text fontSize="sm" color="gray.500">Status</Text>
                      <Badge colorScheme={getStatusColor(application.status)} size="lg">
                        {application.status.replace('_', ' ').toUpperCase()}
                      </Badge>
                    </HStack>
                    
                    <HStack justify="space-between">
                      <Text fontSize="sm" color="gray.500">Application Score</Text>
                      <HStack spacing={2}>
                        <Text fontWeight="bold" color={getScoreColor(application.score)}>
                          {application.score}/100
                        </Text>
                        <Badge colorScheme={getScoreColor(application.score)}>
                          {application.scorePercentage}%
                        </Badge>
                      </HStack>
                    </HStack>
                    
                    <Box>
                      <Text fontSize="sm" color="gray.500" mb={2}>Completeness</Text>
                      <Progress 
                        value={application.scorePercentage} 
                        colorScheme={getScoreColor(application.score)}
                        size="lg"
                        borderRadius="md"
                      />
                    </Box>

                    <HStack justify="space-between">
                      <Text fontSize="sm" color="gray.500">Applied</Text>
                      <Text fontSize="sm" fontWeight="medium">
                        {application.applicationAge} days ago
                      </Text>
                    </HStack>

                    {application.autoApproveEligible && (
                      <Alert status="success" size="sm">
                        <AlertIcon />
                        <Text fontSize="sm">Auto-approve eligible</Text>
                      </Alert>
                    )}

                    {application.complianceIssues.length > 0 && (
                      <Alert status="error" size="sm">
                        <AlertIcon />
                        <VStack align="start" spacing={1}>
                          <Text fontSize="sm" fontWeight="bold">Compliance Issues:</Text>
                          {application.complianceIssues.map((issue, index) => (
                            <Text key={index} fontSize="xs">• {issue}</Text>
                          ))}
                        </VStack>
                      </Alert>
                    )}

                    {application.complianceWarnings.length > 0 && (
                      <Alert status="warning" size="sm">
                        <AlertIcon />
                        <VStack align="start" spacing={1}>
                          <Text fontSize="sm" fontWeight="bold">Warnings:</Text>
                          {application.complianceWarnings.map((warning, index) => (
                            <Text key={index} fontSize="xs">• {warning}</Text>
                          ))}
                        </VStack>
                      </Alert>
                    )}
                  </VStack>
                </CardBody>
              </Card>

              {/* Document Status */}
              <Card bg={bgColor} borderColor={borderColor}>
                <CardHeader>
                  <Heading size="md">Document Status</Heading>
                </CardHeader>
                <CardBody>
                  <VStack spacing={3} align="stretch">
                    <HStack justify="space-between">
                      <Text fontSize="sm">Driving License</Text>
                      <Badge colorScheme={application.documents.license.status === 'complete' ? 'green' : 'red'}>
                        {application.documents.license.status}
                      </Badge>
                    </HStack>
                    <HStack justify="space-between">
                      <Text fontSize="sm">Insurance</Text>
                      <Badge colorScheme={application.documents.insurance.status === 'complete' ? 'green' : 'red'}>
                        {application.documents.insurance.status}
                      </Badge>
                    </HStack>
                    <HStack justify="space-between">
                      <Text fontSize="sm">Right to Work</Text>
                      <Badge colorScheme={application.documents.rightToWork.status === 'complete' ? 'green' : 'red'}>
                        {application.documents.rightToWork.status}
                      </Badge>
                    </HStack>
                  </VStack>
                </CardBody>
              </Card>

              {/* Quick Actions */}
              <Card bg={bgColor} borderColor={borderColor}>
                <CardHeader>
                  <Heading size="md">Quick Actions</Heading>
                </CardHeader>
                <CardBody>
                  <VStack spacing={3} align="stretch">
                    <Button
                      colorScheme="green"
                      leftIcon={<FiCheck />}
                      onClick={() => {
                        setNewStatus('approved');
                        setReviewNotes('Application approved - all requirements met');
                        onReviewOpen();
                      }}
                      isDisabled={application.status === 'approved'}
                    >
                      Approve Application
                    </Button>
                    <Button
                      colorScheme="red"
                      variant="outline"
                      leftIcon={<FiX />}
                      onClick={() => {
                        setNewStatus('rejected');
                        setReviewNotes('');
                        onReviewOpen();
                      }}
                      isDisabled={application.status === 'rejected'}
                    >
                      Reject Application
                    </Button>
                    <Button
                      colorScheme="orange"
                      variant="outline"
                      leftIcon={<FiAlertTriangle />}
                      onClick={() => {
                        setNewStatus('requires_additional_info');
                        setReviewNotes('');
                        onReviewOpen();
                      }}
                    >
                      Request More Info
                    </Button>
                  </VStack>
                </CardBody>
              </Card>
            </VStack>
          </Grid>
        </VStack>
      </Container>

      {/* Review Modal */}
      <Modal isOpen={isReviewOpen} onClose={onReviewClose} size="lg">
        <ModalOverlay />
        <ModalContent>
          <ModalHeader>Review Application</ModalHeader>
          <ModalCloseButton />
          <ModalBody>
            <VStack spacing={4} align="stretch">
              <FormControl>
                <FormLabel>New Status</FormLabel>
                <Select
                  value={newStatus}
                  onChange={(e) => setNewStatus(e.target.value)}
                >
                  <option value="pending">Pending</option>
                  <option value="under_review">Under Review</option>
                  <option value="requires_additional_info">Requires Additional Info</option>
                  <option value="approved">Approved</option>
                  <option value="rejected">Rejected</option>
                </Select>
              </FormControl>
              
              <FormControl>
                <FormLabel>Review Notes</FormLabel>
                <Textarea
                  value={reviewNotes}
                  onChange={(e) => setReviewNotes(e.target.value)}
                  placeholder="Add notes about this review decision..."
                  rows={4}
                />
              </FormControl>
            </VStack>
          </ModalBody>
          <ModalFooter>
            <Button variant="outline" mr={3} onClick={onReviewClose}>
              Cancel
            </Button>
            <Button
              colorScheme="blue"
              onClick={handleStatusUpdate}
              isLoading={actionLoading}
              loadingText="Updating..."
            >
              Update Status
            </Button>
          </ModalFooter>
        </ModalContent>
      </Modal>

      {/* Image Modal */}
      <Modal isOpen={isImageOpen} onClose={onImageClose} size="xl">
        <ModalOverlay />
        <ModalContent>
          <ModalHeader>Document Preview</ModalHeader>
          <ModalCloseButton />
          <ModalBody>
            {selectedImage && (
              <Box position="relative">
                <Image
                  src={selectedImage}
                  alt="Document"
                  w="100%"
                  maxH="500px"
                  objectFit="contain"
                  fallback={
                    <Alert status="error">
                      <AlertIcon />
                      <VStack align="start" spacing={2}>
                        <Text fontWeight="bold">Document not found</Text>
                        <Text fontSize="sm">The file may have been moved or deleted.</Text>
                        <Text fontSize="xs" color="gray.500">Path: {selectedImage}</Text>
                      </VStack>
                    </Alert>
                  }
                  onError={(e) => {
                    console.error('Failed to load document:', selectedImage);
                    toast({
                      title: 'Error loading document',
                      description: 'The document file could not be found. It may have been deleted or moved.',
                      status: 'error',
                      duration: 5000,
                      isClosable: true,
                    });
                  }}
                />
              </Box>
            )}
          </ModalBody>
          <ModalFooter>
            <Button variant="outline" mr={3} onClick={onImageClose}>
              Close
            </Button>
            {selectedImage && (
              <Button
                as="a"
                href={selectedImage}
                target="_blank"
                rel="noopener noreferrer"
                colorScheme="blue"
                leftIcon={<FiDownload />}
                download
              >
                Download
              </Button>
            )}
          </ModalFooter>
        </ModalContent>
      </Modal>
    </AdminShell>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import {
  Box,
  Container,
  VStack,
  HStack,
  Heading,
  Text,
  Card,
  CardBody,
  CardHeader,
  Table,
  Thead,
  Tbody,
  Tr,
  Th,
  Td,
  useToast,
  Spinner,
  Alert,
  AlertIcon,
  Badge,
  Button,
  Input,
  InputGroup,
  InputLeftElement,
  Select,
  Flex,
  IconButton,
  Modal,
  ModalOverlay,
  ModalContent,
  ModalHeader,
  ModalBody,
  ModalFooter,
  ModalCloseButton,
  useDisclosure,
  Textarea,
  SimpleGrid,
  GridItem,
  Divider,
  Image,
  Tag,
  TagLabel,
  TagLeftIcon,
  Stat,
  StatLabel,
  StatNumber,
  StatHelpText,
  StatArrow,
  FormControl,
  FormLabel,
} from '@chakra-ui/react';
import {
  FiCheck,
  FiX,
  FiEye,
  FiSearch,
  FiRefreshCw,
  FiUser,
  FiTruck,
  FiCreditCard,
  FiFileText,
  FiCalendar,
  FiMail,
  FiPhone,
  FiMapPin,
} from 'react-icons/fi';
import { format } from 'date-fns';

interface DriverApplication {
  id: string;
  fullName: string;
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
  address: string;
  addressLine1: string;
  addressLine2?: string;
  city: string;
  county: string;
  postcode: string;
  dateOfBirth: string;
  nationalInsuranceNumber: string;
  drivingLicenseNumber: string;
  drivingLicenseExpiry: string;

  // Bank Information
  bankName: string;
  accountHolderName: string;
  sortCode: string;
  accountNumber: string;

  // Documents and Files
  drivingLicenseFrontImage?: string;
  drivingLicenseBackImage?: string;
  insuranceDocument?: string;
  rightToWorkDocument?: string;

  // Insurance Details
  insuranceProvider?: string;
  insurancePolicyNumber?: string;
  insuranceExpiry?: string;

  // Right to Work Details
  rightToWorkShareCode?: string;

  // Application Status and Review
  status: string;
  reviewNotes?: string;
  reviewedBy?: string;
  reviewedAt?: string;
  applicationDate: string;

  // Metadata
  userId: string;
}

interface ApplicationsData {
  applications: DriverApplication[];
  pagination: {
    page: number;
    limit: number;
    total: number;
    pages: number;
  };
  summary: {
    total: number;
    statusCounts: Record<string, number>;
  };
}

const statusColors = {
  pending: 'yellow',
  under_review: 'blue',
  approved: 'green',
  rejected: 'red',
  requires_additional_info: 'orange',
};

const statusLabels = {
  pending: 'Pending',
  under_review: 'Under Review',
  approved: 'Approved',
  rejected: 'Rejected',
  requires_additional_info: 'Requires Info',
};

export default function DriverApplicationsPage() {
  const [applicationsData, setApplicationsData] = useState<ApplicationsData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedStatus, setSelectedStatus] = useState<string>('');
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedApplication, setSelectedApplication] = useState<DriverApplication | null>(null);
  const [rejectionReason, setRejectionReason] = useState('');
  const [isProcessing, setIsProcessing] = useState<string | null>(null);
  
  const toast = useToast();
  const { isOpen: isDetailsOpen, onOpen: onDetailsOpen, onClose: onDetailsClose } = useDisclosure();
  const { isOpen: isRejectOpen, onOpen: onRejectOpen, onClose: onRejectClose } = useDisclosure();

  const fetchApplications = async () => {
    try {
      setLoading(true);
      setError(null);
      
      const params = new URLSearchParams();
      if (selectedStatus) params.append('status', selectedStatus);
      if (searchTerm) params.append('search', searchTerm);
      
      const response = await fetch(`/api/admin/driver-applications?${params}`);
      
      if (!response.ok) {
        throw new Error('Failed to fetch applications');
      }
      
      const data = await response.json();
      setApplicationsData(data.data);
    } catch (err) {
      console.error('Error fetching applications:', err);
      setError(err instanceof Error ? err.message : 'Unknown error');
      toast({
        title: 'Error',
        description: 'Failed to load driver applications',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchApplications();
  }, [selectedStatus, searchTerm]);

  const handleApprove = async (applicationId: string) => {
    try {
      setIsProcessing(applicationId);
      
      const response = await fetch(`/api/admin/driver-applications/${applicationId}/approve`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
      });
      
      if (!response.ok) {
        throw new Error('Failed to approve application');
      }
      
      toast({
        title: 'Application Approved! 🎉',
        description: 'Driver has been successfully approved and can now start working.',
        status: 'success',
        duration: 5000,
        isClosable: true,
      });
      
      await fetchApplications();
    } catch (error) {
      console.error('Error approving application:', error);
      toast({
        title: 'Error',
        description: 'Failed to approve application',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setIsProcessing(null);
    }
  };

  const handleReject = async (applicationId: string) => {
    try {
      setIsProcessing(applicationId);
      
      const response = await fetch(`/api/admin/driver-applications/${applicationId}/reject`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ rejectionReason }),
      });
      
      if (!response.ok) {
        throw new Error('Failed to reject application');
      }
      
      toast({
        title: 'Application Rejected',
        description: 'Driver application has been rejected.',
        status: 'info',
        duration: 5000,
        isClosable: true,
      });
      
      await fetchApplications();
      onRejectClose();
      setRejectionReason('');
    } catch (error) {
      console.error('Error rejecting application:', error);
      toast({
        title: 'Error',
        description: 'Failed to reject application',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setIsProcessing(null);
    }
  };

  const openDetails = (application: DriverApplication) => {
    setSelectedApplication(application);
    onDetailsOpen();
  };

  const openReject = (application: DriverApplication) => {
    setSelectedApplication(application);
    onRejectOpen();
  };

  if (loading) {
    return (
      <Container maxW="container.xl" py={8}>
        <VStack spacing={8} align="center">
          <Spinner size="xl" color="blue.500" />
          <Text>Loading driver applications...</Text>
        </VStack>
      </Container>
    );
  }

  if (error) {
    return (
      <Container maxW="container.xl" py={8}>
        <Alert status="error" mb={4}>
          <AlertIcon />
          <Box>
            <Text fontWeight="bold">Error loading applications</Text>
            <Text fontSize="sm">{error}</Text>
          </Box>
        </Alert>
        <Button onClick={fetchApplications} colorScheme="blue">
          Try Again
        </Button>
      </Container>
    );
  }

  return (
    <Container maxW="container.xl" py={8}>
      <VStack spacing={8} align="stretch">
        {/* Header */}
        <Flex justify="space-between" align="center">
          <Box>
            <Heading size="lg" mb={2}>Driver Applications</Heading>
            <Text color="gray.600">
              Manage driver applications and approvals
            </Text>
          </Box>
          <HStack spacing={4}>
            <IconButton
              aria-label="Refresh"
              icon={<FiRefreshCw />}
              onClick={fetchApplications}
              colorScheme="blue"
              variant="outline"
            />
          </HStack>
        </Flex>

        {/* Summary Stats */}
        {applicationsData?.summary && (
          <SimpleGrid columns={{ base: 2, md: 5 }} spacing={6}>
            <Card>
              <CardBody>
                <Stat>
                  <StatLabel>Total</StatLabel>
                  <StatNumber>{applicationsData.summary.total}</StatNumber>
                </Stat>
              </CardBody>
            </Card>
            {Object.entries(applicationsData.summary.statusCounts).map(([status, count]) => (
              <Card key={status}>
                <CardBody>
                  <Stat>
                    <StatLabel>{statusLabels[status as keyof typeof statusLabels]}</StatLabel>
                    <StatNumber color={`${statusColors[status as keyof typeof statusColors]}.500`}>
                      {count}
                    </StatNumber>
                  </Stat>
                </CardBody>
              </Card>
            ))}
          </SimpleGrid>
        )}

        {/* Filters */}
        <Card>
          <CardBody>
            <HStack spacing={4}>
              <InputGroup>
                <InputLeftElement pointerEvents="none">
                  <FiSearch color="gray.300" />
                </InputLeftElement>
                <Input
                  placeholder="Search by name, email, or phone..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                />
              </InputGroup>
              <Select
                placeholder="All Statuses"
                value={selectedStatus}
                onChange={(e) => setSelectedStatus(e.target.value)}
                width="200px"
              >
                {Object.entries(statusLabels).map(([value, label]) => (
                  <option key={value} value={value}>
                    {label}
                  </option>
                ))}
              </Select>
            </HStack>
          </CardBody>
        </Card>

        {/* Applications Table */}
        <Card>
          <CardHeader>
            <Heading size="md">Applications</Heading>
          </CardHeader>
          <CardBody>
            {applicationsData?.applications.length === 0 ? (
              <Box textAlign="center" py={8}>
                <Text color="gray.500">No applications found</Text>
              </Box>
            ) : (
              <Table size="sm">
                <Thead>
                  <Tr>
                    <Th>Driver</Th>
                    <Th>Contact</Th>
                    <Th>License</Th>
                    <Th>Status</Th>
                    <Th>Applied</Th>
                    <Th>Actions</Th>
                  </Tr>
                </Thead>
                <Tbody>
                  {applicationsData?.applications.map((app) => (
                    <Tr key={app.id}>
                      <Td>
                        <VStack align="start" spacing={1}>
                          <Text fontWeight="medium">{app.fullName}</Text>
                          <Text fontSize="sm" color="gray.600">
                            {app.postcode}
                          </Text>
                        </VStack>
                      </Td>
                      <Td>
                        <VStack align="start" spacing={1}>
                          <HStack>
                            <FiMail size={12} />
                            <Text fontSize="sm">{app.email}</Text>
                          </HStack>
                          <HStack>
                            <FiPhone size={12} />
                            <Text fontSize="sm">{app.phone}</Text>
                          </HStack>
                        </VStack>
                      </Td>
                      <Td>
                        <VStack align="start" spacing={1}>
                          <Text fontSize="sm">
                            License: {app.drivingLicenseNumber}
                          </Text>
                          <Text fontSize="xs" color="gray.600">
                            Expires: {app.drivingLicenseExpiry ? format(new Date(app.drivingLicenseExpiry), 'MMM dd, yyyy') : 'N/A'}
                          </Text>
                        </VStack>
                      </Td>
                      <Td>
                        <Badge
                          colorScheme={statusColors[app.status as keyof typeof statusColors]}
                          variant="subtle"
                        >
                          {statusLabels[app.status as keyof typeof statusLabels]}
                        </Badge>
                      </Td>
                      <Td>
                        <Text fontSize="sm">
                          {app.applicationDate && !isNaN(new Date(app.applicationDate).getTime()) 
                            ? format(new Date(app.applicationDate), 'MMM dd, yyyy')
                            : 'N/A'
                          }
                        </Text>
                      </Td>
                      <Td>
                        <HStack spacing={2}>
                          <IconButton
                            aria-label="View details"
                            icon={<FiEye />}
                            size="sm"
                            variant="outline"
                            onClick={() => openDetails(app)}
                          />
                          {app.status === 'pending' || app.status === 'under_review' ? (
                            <>
                              <Button
                                size="sm"
                                colorScheme="green"
                                leftIcon={<FiCheck />}
                                onClick={() => handleApprove(app.id)}
                                isLoading={isProcessing === app.id}
                                loadingText="Approving..."
                              >
                                Approve
                              </Button>
                              <Button
                                size="sm"
                                colorScheme="red"
                                leftIcon={<FiX />}
                                onClick={() => openReject(app)}
                                isLoading={isProcessing === app.id}
                                loadingText="Rejecting..."
                              >
                                Reject
                              </Button>
                            </>
                          ) : (
                            <Text fontSize="sm" color="gray.500">
                              {app.status === 'approved' ? 'Approved' : 'Rejected'}
                            </Text>
                          )}
                        </HStack>
                      </Td>
                    </Tr>
                  ))}
                </Tbody>
              </Table>
            )}
          </CardBody>
        </Card>

        {/* Application Details Modal */}
        <Modal isOpen={isDetailsOpen} onClose={onDetailsClose} size="xl">
          <ModalOverlay />
          <ModalContent>
            <ModalHeader>Application Details</ModalHeader>
            <ModalCloseButton />
            <ModalBody>
              {selectedApplication && (
                <VStack spacing={6} align="stretch">
                  {/* Personal Information */}
                  <Card>
                    <CardHeader>
                      <Heading size="sm">Personal Information</Heading>
                    </CardHeader>
                    <CardBody>
                      <SimpleGrid columns={2} spacing={4}>
                        <Box>
                          <Text fontWeight="medium">Full Name</Text>
                          <Text>{selectedApplication.fullName}</Text>
                        </Box>
                        <Box>
                          <Text fontWeight="medium">Email</Text>
                          <Text>{selectedApplication.email}</Text>
                        </Box>
                        <Box>
                          <Text fontWeight="medium">Phone</Text>
                          <Text>{selectedApplication.phone}</Text>
                        </Box>
                        <Box>
                          <Text fontWeight="medium">Postcode</Text>
                          <Text>{selectedApplication.postcode}</Text>
                        </Box>
                        <GridItem colSpan={2}>
                          <Text fontWeight="medium">Address</Text>
                          <Text>{selectedApplication.address}</Text>
                        </GridItem>
                      </SimpleGrid>
                    </CardBody>
                  </Card>

                  {/* Driver License Information */}
                  <Card>
                    <CardHeader>
                      <Heading size="sm">Driver License Information</Heading>
                    </CardHeader>
                    <CardBody>
                      <SimpleGrid columns={2} spacing={4}>
                        <Box>
                          <Text fontWeight="medium">License Number</Text>
                          <Text>{selectedApplication.drivingLicenseNumber || 'N/A'}</Text>
                        </Box>
                        <Box>
                          <Text fontWeight="medium">Expiry Date</Text>
                          <Text>
                            {selectedApplication.drivingLicenseExpiry && !isNaN(new Date(selectedApplication.drivingLicenseExpiry).getTime()) 
                              ? format(new Date(selectedApplication.drivingLicenseExpiry), 'MMM dd, yyyy')
                              : 'N/A'
                            }
                          </Text>
                        </Box>
                        <Box>
                          <Text fontWeight="medium">National Insurance</Text>
                          <Text>{selectedApplication.nationalInsuranceNumber || 'N/A'}</Text>
                        </Box>
                        <Box>
                          <Text fontWeight="medium">Date of Birth</Text>
                          <Text>
                            {selectedApplication.dateOfBirth && !isNaN(new Date(selectedApplication.dateOfBirth).getTime()) 
                              ? format(new Date(selectedApplication.dateOfBirth), 'MMM dd, yyyy')
                              : 'N/A'
                            }
                          </Text>
                        </Box>
                      </SimpleGrid>
                    </CardBody>
                  </Card>

                  {/* Bank Account */}
                  <Card>
                    <CardHeader>
                      <Heading size="sm">Bank Account</Heading>
                    </CardHeader>
                    <CardBody>
                      <SimpleGrid columns={2} spacing={4}>
                        <Box>
                          <Text fontWeight="medium">Account Name</Text>
                          <Text>{selectedApplication.accountHolderName || 'N/A'}</Text>
                        </Box>
                        <Box>
                          <Text fontWeight="medium">Bank Name</Text>
                          <Text>{selectedApplication.bankName || 'N/A'}</Text>
                        </Box>
                        <Box>
                          <Text fontWeight="medium">Sort Code</Text>
                          <Text>{selectedApplication.sortCode || 'N/A'}</Text>
                        </Box>
                        <Box>
                          <Text fontWeight="medium">Account Number</Text>
                          <Text>{selectedApplication.accountNumber || 'N/A'}</Text>
                        </Box>
                      </SimpleGrid>
                    </CardBody>
                  </Card>

                  {/* Application Status */}
                  <Card>
                    <CardHeader>
                      <Heading size="sm">Application Status</Heading>
                    </CardHeader>
                    <CardBody>
                      <VStack align="stretch" spacing={2}>
                        <HStack justify="space-between">
                          <Text fontWeight="medium">Status:</Text>
                          <Badge
                            colorScheme={statusColors[selectedApplication.status as keyof typeof statusColors]}
                            variant="subtle"
                          >
                            {statusLabels[selectedApplication.status as keyof typeof statusLabels]}
                          </Badge>
                        </HStack>
                        <HStack justify="space-between">
                          <Text fontWeight="medium">Applied:</Text>
                          <Text>
                            {selectedApplication.applicationDate && !isNaN(new Date(selectedApplication.applicationDate).getTime()) 
                              ? format(new Date(selectedApplication.applicationDate), 'MMM dd, yyyy HH:mm')
                              : 'N/A'
                            }
                          </Text>
                        </HStack>
                        {selectedApplication.reviewedAt && (
                          <HStack justify="space-between">
                            <Text fontWeight="medium">Reviewed:</Text>
                            <Text>
                              {selectedApplication.reviewedAt && !isNaN(new Date(selectedApplication.reviewedAt).getTime()) 
                                ? format(new Date(selectedApplication.reviewedAt), 'MMM dd, yyyy HH:mm')
                                : 'N/A'
                              }
                            </Text>
                          </HStack>
                        )}
                        {selectedApplication.reviewNotes && (
                          <Box>
                            <Text fontWeight="medium">Review Notes:</Text>
                            <Text color="red.500">{selectedApplication.reviewNotes}</Text>
                          </Box>
                        )}
                      </VStack>
                    </CardBody>
                  </Card>

                  {/* Documents Section */}
                  <Card>
                    <CardHeader>
                      <Heading size="sm">Documents & Files</Heading>
                    </CardHeader>
                    <CardBody>
                      <VStack spacing={4} align="stretch">
                        {/* Driving License */}
                        <Box>
                          <Text fontWeight="medium" mb={2}>Driving License</Text>
                          <SimpleGrid columns={2} spacing={4}>
                            {selectedApplication.drivingLicenseFrontImage ? (
                              <Box>
                                <Text fontSize="sm" color="gray.600" mb={1}>Front Image</Text>
                                <Image
                                  src={selectedApplication.drivingLicenseFrontImage}
                                  alt="Driving License Front"
                                  borderRadius="md"
                                  maxH="150px"
                                  cursor="pointer"
                                  onClick={() => window.open(selectedApplication.drivingLicenseFrontImage, '_blank')}
                                  _hover={{ opacity: 0.8 }}
                                  fallback={
                                    <Box
                                      p={4}
                                      bg="gray.100"
                                      borderRadius="md"
                                      textAlign="center"
                                    >
                                      <Text fontSize="xs" color="gray.500">
                                        Image not available
                                      </Text>
                                    </Box>
                                  }
                                />
                              </Box>
                            ) : (
                              <Box>
                                <Text fontSize="sm" color="gray.600">Front Image</Text>
                                <Text color="red.500">Not provided</Text>
                              </Box>
                            )}
                            {selectedApplication.drivingLicenseBackImage ? (
                              <Box>
                                <Text fontSize="sm" color="gray.600" mb={1}>Back Image</Text>
                                <Image
                                  src={selectedApplication.drivingLicenseBackImage}
                                  alt="Driving License Back"
                                  borderRadius="md"
                                  maxH="150px"
                                  cursor="pointer"
                                  onClick={() => window.open(selectedApplication.drivingLicenseBackImage, '_blank')}
                                  _hover={{ opacity: 0.8 }}
                                  fallback={
                                    <Box
                                      p={4}
                                      bg="gray.100"
                                      borderRadius="md"
                                      textAlign="center"
                                    >
                                      <Text fontSize="xs" color="gray.500">
                                        Image not available
                                      </Text>
                                    </Box>
                                  }
                                />
                              </Box>
                            ) : (
                              <Box>
                                <Text fontSize="sm" color="gray.600">Back Image</Text>
                                <Text color="red.500">Not provided</Text>
                              </Box>
                            )}
                          </SimpleGrid>
                        </Box>

                        <Divider />

                        {/* Insurance Document */}
                        <Box>
                          <Text fontWeight="medium" mb={2}>Insurance Document</Text>
                          {selectedApplication.insuranceDocument ? (
                            <Box>
                              <HStack spacing={2} mb={2}>
                                <FiFileText />
                                <Text fontSize="sm">Insurance Document</Text>
                              </HStack>
                              <Image
                                src={selectedApplication.insuranceDocument}
                                alt="Insurance Document"
                                borderRadius="md"
                                maxH="200px"
                                cursor="pointer"
                                onClick={() => window.open(selectedApplication.insuranceDocument, '_blank')}
                                _hover={{ opacity: 0.8 }}
                                fallback={
                                  <Box
                                    p={4}
                                    bg="gray.100"
                                    borderRadius="md"
                                    textAlign="center"
                                  >
                                    <Text fontSize="xs" color="gray.500">
                                      Document not available
                                    </Text>
                                  </Box>
                                }
                              />
                            </Box>
                          ) : (
                            <Text color="red.500">Not provided</Text>
                          )}
                        </Box>

                        <Divider />

                        {/* Right to Work Document */}
                        <Box>
                          <Text fontWeight="medium" mb={2}>Right to Work Document</Text>
                          {selectedApplication.rightToWorkDocument ? (
                            <Box>
                              <HStack spacing={2} mb={2}>
                                <FiFileText />
                                <Text fontSize="sm">Right to Work Document</Text>
                              </HStack>
                              <Image
                                src={selectedApplication.rightToWorkDocument}
                                alt="Right to Work Document"
                                borderRadius="md"
                                maxH="200px"
                                cursor="pointer"
                                onClick={() => window.open(selectedApplication.rightToWorkDocument, '_blank')}
                                _hover={{ opacity: 0.8 }}
                                fallback={
                                  <Box
                                    p={4}
                                    bg="gray.100"
                                    borderRadius="md"
                                    textAlign="center"
                                  >
                                    <Text fontSize="xs" color="gray.500">
                                      Document not available
                                    </Text>
                                  </Box>
                                }
                              />
                            </Box>
                          ) : (
                            <Text color="red.500">Not provided</Text>
                          )}
                        </Box>
                      </VStack>
                    </CardBody>
                  </Card>

                  {/* Insurance & Right to Work Details */}
                  <SimpleGrid columns={2} spacing={4}>
                    {/* Insurance Details */}
                    <Card>
                      <CardHeader>
                        <Heading size="sm">Insurance Details</Heading>
                      </CardHeader>
                      <CardBody>
                        <VStack spacing={3} align="stretch">
                          <Box>
                            <Text fontWeight="medium">Provider</Text>
                            <Text>{selectedApplication.insuranceProvider || 'N/A'}</Text>
                          </Box>
                          <Box>
                            <Text fontWeight="medium">Policy Number</Text>
                            <Text>{selectedApplication.insurancePolicyNumber || 'N/A'}</Text>
                          </Box>
                          <Box>
                            <Text fontWeight="medium">Expiry Date</Text>
                            <Text>
                              {selectedApplication.insuranceExpiry && !isNaN(new Date(selectedApplication.insuranceExpiry).getTime())
                                ? format(new Date(selectedApplication.insuranceExpiry), 'MMM dd, yyyy')
                                : 'N/A'
                              }
                            </Text>
                          </Box>
                        </VStack>
                      </CardBody>
                    </Card>

                    {/* Right to Work Details */}
                    <Card>
                      <CardHeader>
                        <Heading size="sm">Right to Work</Heading>
                      </CardHeader>
                      <CardBody>
                        <VStack spacing={3} align="stretch">
                          <Box>
                            <Text fontWeight="medium">Share Code</Text>
                            <Text>{selectedApplication.rightToWorkShareCode || 'N/A'}</Text>
                          </Box>
                        </VStack>
                      </CardBody>
                    </Card>
                  </SimpleGrid>

                  {/* Application Outcomes */}
                  {selectedApplication.reviewNotes && (
                    <Card>
                      <CardHeader>
                        <Heading size="sm">Application Outcomes</Heading>
                      </CardHeader>
                      <CardBody>
                        <VStack spacing={4} align="stretch">
                          {selectedApplication.reviewNotes && (
                            <Box>
                              <HStack spacing={2} mb={2}>
                                <FiFileText color="blue" />
                                <Text fontWeight="medium" color="blue.500">Review Notes</Text>
                              </HStack>
                              <Text color="blue.600">{selectedApplication.reviewNotes}</Text>
                            </Box>
                          )}

                          {selectedApplication.reviewedBy && (
                            <Box>
                              <Text fontWeight="medium">Reviewed By</Text>
                              <Text>{selectedApplication.reviewedBy}</Text>
                            </Box>
                          )}
                        </VStack>
                      </CardBody>
                    </Card>
                  )}

                  {/* Metadata */}
                  <Card>
                    <CardHeader>
                      <Heading size="sm">Application Metadata</Heading>
                    </CardHeader>
                    <CardBody>
                      <SimpleGrid columns={2} spacing={4}>
                        <Box>
                          <Text fontWeight="medium">User ID</Text>
                          <Text fontSize="sm" fontFamily="mono">{selectedApplication.userId}</Text>
                        </Box>
                        <Box>
                          <Text fontWeight="medium">Application Date</Text>
                          <Text fontSize="sm">
                            {selectedApplication.applicationDate && !isNaN(new Date(selectedApplication.applicationDate).getTime())
                              ? format(new Date(selectedApplication.applicationDate), 'MMM dd, yyyy HH:mm')
                              : 'N/A'
                            }
                          </Text>
                        </Box>
                      </SimpleGrid>
                    </CardBody>
                  </Card>

                </VStack>
              )}
            </ModalBody>
            <ModalFooter>
              <Button onClick={onDetailsClose}>Close</Button>
            </ModalFooter>
          </ModalContent>
        </Modal>

        {/* Reject Application Modal */}
        <Modal isOpen={isRejectOpen} onClose={onRejectClose}>
          <ModalOverlay />
          <ModalContent>
            <ModalHeader>Reject Application</ModalHeader>
            <ModalCloseButton />
            <ModalBody>
              <VStack spacing={4} align="stretch">
                <Text>
                  Are you sure you want to reject this application? This action cannot be undone.
                </Text>
                <FormControl>
                  <FormLabel>Rejection Reason (Optional)</FormLabel>
                  <Textarea
                    value={rejectionReason}
                    onChange={(e) => setRejectionReason(e.target.value)}
                    placeholder="Enter reason for rejection..."
                    rows={3}
                  />
                </FormControl>
              </VStack>
            </ModalBody>
            <ModalFooter>
              <Button variant="outline" mr={3} onClick={onRejectClose}>
                Cancel
              </Button>
              <Button
                colorScheme="red"
                onClick={() => selectedApplication && handleReject(selectedApplication.id)}
                isLoading={isProcessing === selectedApplication?.id}
                loadingText="Rejecting..."
              >
                Reject Application
              </Button>
            </ModalFooter>
          </ModalContent>
        </Modal>
      </VStack>
    </Container>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import {
  Box,
  Container,
  VStack,
  HStack,
  Heading,
  Text,
  Card,
  CardBody,
  CardHeader,
  SimpleGrid,
  Badge,
  Button,
  Select,
  Table,
  Thead,
  Tbody,
  Tr,
  Th,
  Td,
  useToast,
  Spinner,
  Alert,
  AlertIcon,
  Tabs,
  TabList,
  TabPanels,
  Tab,
  TabPanel,
  Stat,
  StatLabel,
  StatNumber,
  StatHelpText,
  StatArrow,
  Divider,
  Flex,
  IconButton,
  Tooltip,
} from '@chakra-ui/react';
import {
  FiDollarSign,
  FiUsers,
  FiTrendingUp,
  FiCalendar,
  FiRefreshCw,
  FiDownload,
  FiEye,
  FiEdit,
} from 'react-icons/fi';
import { format, startOfWeek, startOfMonth, endOfWeek, endOfMonth } from 'date-fns';

interface DriverEarning {
  id: string;
  driverId: string;
  driverName: string;
  assignmentId: string;
  bookingReference: string;
  customerName: string;
  baseAmount: string;
  surgeAmount: string;
  tipAmount: string;
  feeAmount: string;
  netAmount: string;
  currency: string;
  calculatedAt: string;
  paidOut: boolean;
}

interface DriverStats {
  driverId: string;
  driverName: string;
  driverEmail: string;
  totalEarnings: string;
  totalJobs: number;
  jobs: Array<{
    assignmentId: string;
    bookingReference: string;
    customerName: string;
    earnings: string;
    calculatedAt: string;
    paidOut: boolean;
  }>;
}

interface EarningsData {
  period: string;
  dateRange: {
    start: string;
    end: string;
  };
  summary: {
    totalEarnings: string;
    totalJobs: number;
    totalPlatformFees: string;
    averageEarningsPerJob: string;
  };
  driverStats: DriverStats[];
  rawEarnings: DriverEarning[];
}

export default function DriverEarningsPage() {
  const [earningsData, setEarningsData] = useState<EarningsData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedPeriod, setSelectedPeriod] = useState('today');
  const [selectedDriver, setSelectedDriver] = useState<string>('all');
  const [selectedTab, setSelectedTab] = useState(0);
  
  const toast = useToast();

  const formatCurrency = (pence: number) => (pence / 100).toFixed(2);

  const periods = [
    { value: 'today', label: 'Today' },
    { value: 'week', label: 'This Week' },
    { value: 'month', label: 'This Month' },
  ];

  const fetchEarnings = async () => {
    try {
      setLoading(true);
      setError(null);
      
      const params = new URLSearchParams({
        period: selectedPeriod,
        ...(selectedDriver !== 'all' && { driverId: selectedDriver }),
      });
      
      const response = await fetch(`/api/admin/drivers/earnings?${params}`);
      
      if (!response.ok) {
        throw new Error('Failed to fetch earnings data');
      }
      
      const data = await response.json();
      setEarningsData(data.data);
    } catch (err) {
      console.error('Error fetching earnings:', err);
      setError(err instanceof Error ? err.message : 'Unknown error');
      toast({
        title: 'Error',
        description: 'Failed to load driver earnings',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchEarnings();
  }, [selectedPeriod, selectedDriver]);

  const formatDate = (dateString: string) => {
    return format(new Date(dateString), 'MMM dd, yyyy HH:mm');
  };

  const formatDateRange = (start: string, end: string) => {
    const startDate = format(new Date(start), 'MMM dd, yyyy');
    const endDate = format(new Date(end), 'MMM dd, yyyy');
    return `${startDate} - ${endDate}`;
  };

  if (loading) {
    return (
      <Container maxW="container.xl" py={8}>
        <VStack spacing={8} align="center">
          <Spinner size="xl" color="blue.500" />
          <Text>Loading driver earnings...</Text>
        </VStack>
      </Container>
    );
  }

  if (error) {
    return (
      <Container maxW="container.xl" py={8}>
        <Alert status="error" mb={4}>
          <AlertIcon />
          <Box>
            <Text fontWeight="bold">Error loading earnings</Text>
            <Text fontSize="sm">{error}</Text>
          </Box>
        </Alert>
        <Button onClick={fetchEarnings} colorScheme="blue">
          Try Again
        </Button>
      </Container>
    );
  }

  if (!earningsData) {
    return (
      <Container maxW="container.xl" py={8}>
        <Text>No earnings data available</Text>
      </Container>
    );
  }

  return (
    <Container maxW="container.xl" py={8}>
      <VStack spacing={8} align="stretch">
        {/* Header */}
        <Flex justify="space-between" align="center">
          <Box>
            <Heading size="lg" mb={2}>Driver Earnings</Heading>
            <Text color="gray.600">
              {formatDateRange(earningsData.dateRange.start, earningsData.dateRange.end)}
            </Text>
          </Box>
          <HStack spacing={4}>
            <Select
              value={selectedPeriod}
              onChange={(e) => setSelectedPeriod(e.target.value)}
              width="150px"
            >
              {periods.map((period) => (
                <option key={period.value} value={period.value}>
                  {period.label}
                </option>
              ))}
            </Select>
            <Select
              value={selectedDriver}
              onChange={(e) => setSelectedDriver(e.target.value)}
              width="200px"
            >
              <option value="all">All Drivers</option>
              {earningsData.driverStats.map((driver) => (
                <option key={driver.driverId} value={driver.driverId}>
                  {driver.driverName}
                </option>
              ))}
            </Select>
            <IconButton
              aria-label="Refresh"
              icon={<FiRefreshCw />}
              onClick={fetchEarnings}
              colorScheme="blue"
              variant="outline"
            />
            <Button
              leftIcon={<FiDownload />}
              colorScheme="green"
              variant="outline"
              onClick={() => {
                // TODO: Implement CSV export
                toast({
                  title: 'Export',
                  description: 'CSV export feature coming soon',
                  status: 'info',
                  duration: 3000,
                  isClosable: true,
                });
              }}
            >
              Export
            </Button>
          </HStack>
        </Flex>

        {/* Summary Stats */}
        <SimpleGrid columns={{ base: 1, md: 4 }} spacing={6}>
          <Card>
            <CardBody>
              <Stat>
                <StatLabel>Total Earnings</StatLabel>
                <StatNumber color="green.500">
                  £{earningsData.summary.totalEarnings}
                </StatNumber>
                <StatHelpText>
                  <StatArrow type="increase" />
                  {earningsData.summary.totalJobs} jobs
                </StatHelpText>
              </Stat>
            </CardBody>
          </Card>
          
          <Card>
            <CardBody>
              <Stat>
                <StatLabel>Total Jobs</StatLabel>
                <StatNumber color="blue.500">
                  {earningsData.summary.totalJobs}
                </StatNumber>
                <StatHelpText>
                  Completed jobs
                </StatHelpText>
              </Stat>
            </CardBody>
          </Card>
          
          <Card>
            <CardBody>
              <Stat>
                <StatLabel>Platform Fees</StatLabel>
                <StatNumber color="orange.500">
                  £{earningsData.summary.totalPlatformFees}
                </StatNumber>
                <StatHelpText>
                  15% platform fee
                </StatHelpText>
              </Stat>
            </CardBody>
          </Card>
          
          <Card>
            <CardBody>
              <Stat>
                <StatLabel>Avg per Job</StatLabel>
                <StatNumber color="purple.500">
                  £{earningsData.summary.averageEarningsPerJob}
                </StatNumber>
                <StatHelpText>
                  Average driver earnings
                </StatHelpText>
              </Stat>
            </CardBody>
          </Card>
        </SimpleGrid>

        {/* Tabs */}
        <Tabs index={selectedTab} onChange={setSelectedTab}>
          <TabList>
            <Tab>Driver Summary</Tab>
            <Tab>All Earnings</Tab>
          </TabList>

          <TabPanels>
            {/* Driver Summary Tab */}
            <TabPanel px={0}>
              <VStack spacing={4} align="stretch">
                {earningsData.driverStats.map((driver) => (
                  <Card key={driver.driverId}>
                    <CardHeader>
                      <Flex justify="space-between" align="center">
                        <Box>
                          <Heading size="md">{driver.driverName}</Heading>
                          <Text fontSize="sm" color="gray.600">
                            {driver.driverEmail}
                          </Text>
                        </Box>
                        <VStack align="end" spacing={1}>
                          <Text fontSize="lg" fontWeight="bold" color="green.500">
                            £{driver.totalEarnings}
                          </Text>
                          <Text fontSize="sm" color="gray.600">
                            {driver.totalJobs} jobs
                          </Text>
                        </VStack>
                      </Flex>
                    </CardHeader>
                    <CardBody pt={0}>
                      <Table size="sm">
                        <Thead>
                          <Tr>
                            <Th>Reference</Th>
                            <Th>Customer</Th>
                            <Th>Type</Th>
                            <Th>Earnings</Th>
                            <Th>Status</Th>
                            <Th>Actions</Th>
                          </Tr>
                        </Thead>
                        <Tbody>
                          {driver.jobs.map((job) => (
                            <Tr key={job.assignmentId || job.calculatedAt}>
                              <Td fontFamily="mono" fontSize="sm">
                                {job.bookingReference}
                              </Td>
                              <Td>{job.customerName}</Td>
                              <Td>
                                {(job as any).isBonus ? (
                                  <Badge colorScheme="orange" variant="subtle" size="sm">
                                    {(job as any).bonusType || 'Bonus'}
                                  </Badge>
                                ) : (
                                  <Badge colorScheme="blue" variant="subtle" size="sm">
                                    Job
                                  </Badge>
                                )}
                              </Td>
                              <Td>
                            <VStack align="start" spacing={0}>
                              <Text fontWeight="bold" color="green.500">
                                £{formatCurrency(Number(job.earnings))}
                              </Text>
                              {(job as any).bonusAmount > 0 && (
                                <Text fontSize="xs" color="orange.500">
                                  Bonus: £{formatCurrency(Number((job as any).bonusAmount))}
                                </Text>
                              )}
                            </VStack>
                              </Td>
                              <Td>
                                {!job.paidOut ? (
                                  <Badge colorScheme="orange" variant="subtle">
                                    Pending
                                  </Badge>
                                ) : (
                                  <Badge colorScheme="green" variant="subtle">
                                    Paid
                                  </Badge>
                                )}
                              </Td>
                              <Td>
                                {!job.paidOut && (
                                  <Tooltip label="Adjust earnings">
                                    <IconButton
                                      size="xs"
                                      icon={<FiEdit />}
                                      variant="ghost"
                                      colorScheme="blue"
                                      aria-label="Adjust earnings"
                                      onClick={() => {
                                        // Open adjustment modal
                                        toast({
                                          title: 'Feature Coming Soon',
                                          description: 'Manual earnings adjustment will be available soon',
                                          status: 'info',
                                          duration: 3000,
                                        });
                                      }}
                                    />
                                  </Tooltip>
                                )}
                              </Td>
                            </Tr>
                          ))}
                        </Tbody>
                      </Table>
                    </CardBody>
                  </Card>
                ))}
              </VStack>
            </TabPanel>

            {/* All Earnings Tab */}
            <TabPanel px={0}>
              <Card>
                <CardHeader>
                  <Heading size="md">All Driver Earnings</Heading>
                </CardHeader>
                <CardBody>
                  <Table size="sm">
                    <Thead>
                      <Tr>
                        <Th>Driver</Th>
                        <Th>Job Ref</Th>
                        <Th>Customer</Th>
                        <Th>Base</Th>
                        <Th>Surge</Th>
                        <Th>Tips</Th>
                        <Th>Fees</Th>
                        <Th>Net</Th>
                        <Th>Date</Th>
                        <Th>Status</Th>
                      </Tr>
                    </Thead>
                    <Tbody>
                      {earningsData.rawEarnings.map((earning) => (
                        <Tr key={earning.id}>
                          <Td fontWeight="medium">{earning.driverName}</Td>
                          <Td fontFamily="mono" fontSize="sm">
                            {earning.bookingReference}
                          </Td>
                          <Td>{earning.customerName}</Td>
                          <Td>£{earning.baseAmount}</Td>
                          <Td>£{earning.surgeAmount}</Td>
                          <Td>£{earning.tipAmount}</Td>
                          <Td>£{earning.feeAmount}</Td>
                          <Td fontWeight="bold" color="green.500">
                            £{earning.netAmount}
                          </Td>
                          <Td fontSize="sm">
                            {formatDate(earning.calculatedAt)}
                          </Td>
                          <Td>
                            <Badge
                              colorScheme={earning.paidOut ? 'green' : 'yellow'}
                              variant="subtle"
                            >
                              {earning.paidOut ? 'Paid' : 'Pending'}
                            </Badge>
                          </Td>
                        </Tr>
                      ))}
                    </Tbody>
                  </Table>
                </CardBody>
              </Card>
            </TabPanel>
          </TabPanels>
        </Tabs>
      </VStack>
    </Container>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import {
