  Booking: {
    id: string;
    orderRef: string;
    scheduledAt: string;
    totalGBP: number;
    status: string;
    customer: {
      name: string;
      email: string;
    };
  };
  breakdown: {
    baseAmountPence: number;
    surgeAmountPence: number;
    tipAmountPence: number;
    feeAmountPence: number;
    netAmountPence: number;
  };
  calculatedAt: string;
  paidOut: boolean;
  paidOutAt: string;
}

interface LedgerData {
  ledger: LedgerEntry[];
  pagination: {
    page: number;
    limit: number;
    total: number;
    pages: number;
  };
  summary: {
    totalRevenue: number;
    totalOrders: number;
    earningsBreakdown: {
      baseAmount: number;
      surgeAmount: number;
      tipAmount: number;
      feeAmount: number;
      netAmount: number;
    };
