                  <Td>
                    <VStack align="start" spacing={0}>
                      <Text fontSize="sm">{entry.Booking.customer.name}</Text>
                      <Text fontSize="xs" color="gray.500">
                        {entry.Booking.customer.email}
                      </Text>
                    </VStack>
                  </Td>
                  <Td>
                    <Text fontSize="sm">{entry.driver.name}</Text>
                  </Td>
                  <Td>
                    <Text fontWeight="bold" fontSize="sm">
                      {formatCurrency(entry.Booking.totalGBP)}
                    </Text>
                  </Td>
                  <Td>
                    <Text fontSize="sm">
                      {formatCurrency(entry.breakdown.baseAmountPence)}
                    </Text>
                  </Td>
                  <Td>
                    <Text fontSize="sm">
                      {formatCurrency(entry.breakdown.surgeAmountPence)}
                    </Text>
                  </Td>
                  <Td>
                    <Text fontSize="sm">
                      {formatCurrency(entry.breakdown.tipAmountPence)}
                    </Text>
                  </Td>
                  <Td>
                    <Text fontSize="sm">
                      {formatCurrency(entry.breakdown.feeAmountPence)}
                    </Text>
                  </Td>
                  <Td>
                    <Text fontWeight="bold" fontSize="sm">
                      {formatCurrency(entry.breakdown.netAmountPence)}
                    </Text>
                  </Td>
                  <Td>
                    <Badge
                      colorScheme={getStatusColor(entry.Booking.status)}
                      size="sm"
                    >
                      {entry.Booking.status}
                    </Badge>
                  </Td>
                  <Td>
                    <Menu>
                      <MenuButton
                        as={IconButton}
                        icon={<FiMoreVertical />}
                        variant="ghost"
                        size="sm"
                      />
                      <MenuList>
                        <MenuItem
                          icon={<FiEye />}
                          onClick={() => handleViewEntry(entry)}
                        >
                          View Details
                        </MenuItem>
                        <MenuItem icon={<FiDownload />}>Export Entry</MenuItem>
                      </MenuList>
                    </Menu>
                  </Td>
                </Tr>
              ))}
            </Tbody>
          </Table>

          {/* Pagination */}
          {data && data.pagination.pages > 1 && (
            <HStack justify="center" mt={6}>
              <Button
                size="sm"
                variant="outline"
                isDisabled={currentPage === 1}
                onClick={() => setCurrentPage(currentPage - 1)}
              >
                Previous
              </Button>
              <Text>
                Page {currentPage} of {data.pagination.pages}
              </Text>
              <Button
                size="sm"
                variant="outline"
                isDisabled={currentPage === data.pagination.pages}
                onClick={() => setCurrentPage(currentPage + 1)}
              >
                Next
              </Button>
            </HStack>
          )}
        </CardBody>
      </Card>

      {/* Ledger Entry Detail Modal */}
      <Modal isOpen={isOpen} onClose={onClose} size="xl">
        <ModalOverlay />
        <ModalContent>
          <ModalHeader>Ledger Entry Details</ModalHeader>
          <ModalCloseButton />
          <ModalBody pb={6}>
            {selectedEntry && (
              <VStack spacing={6} align="stretch">
                {/* Job Information */}
                <Card>
                  <CardBody>
                    <Heading size="md" mb={4}>
                      Job Information
                    </Heading>
                    <VStack spacing={3} align="stretch">
                      <HStack justify="space-between">
                        <Text fontWeight="bold">Order Reference:</Text>
                        <Text>{selectedEntry.Booking.orderRef}</Text>
                      </HStack>
                      <HStack justify="space-between">
                        <Text fontWeight="bold">Customer:</Text>
                        <VStack align="end" spacing={0}>
                          <Text>{selectedEntry.Booking.customer.name}</Text>
                          <Text fontSize="sm" color="gray.500">
                            {selectedEntry.Booking.customer.email}
                          </Text>
                        </VStack>
                      </HStack>
                      <HStack justify="space-between">
                        <Text fontWeight="bold">Driver:</Text>
                        <VStack align="end" spacing={0}>
                          <Text>{selectedEntry.driver.name}</Text>
                          <Text fontSize="sm" color="gray.500">
                            {selectedEntry.driver.email}
                          </Text>
                        </VStack>
                      </HStack>
                      <HStack justify="space-between">
                        <Text fontWeight="bold">Scheduled Date:</Text>
                        <Text>
                          {new Date(
                            selectedEntry.Booking.scheduledAt
                          ).toLocaleDateString()}
                        </Text>
                      </HStack>
                      <HStack justify="space-between">
                        <Text fontWeight="bold">Payment Status:</Text>
                        <Badge
                          colorScheme={getStatusColor(
                            selectedEntry.Booking.status
                          )}
                        >
                          {selectedEntry.Booking.status}
                        </Badge>
                      </HStack>
                    </VStack>
                  </CardBody>
                </Card>

                {/* Financial Breakdown */}
                <Card>
                  <CardBody>
                    <Heading size="md" mb={4}>
                      Financial Breakdown
                    </Heading>
                    <VStack spacing={3} align="stretch">
                      <HStack justify="space-between">
                        <Text fontWeight="bold">Total Revenue:</Text>
                        <Text fontSize="lg" fontWeight="bold">
                          {formatCurrency(selectedEntry.Booking.totalGBP)}
                        </Text>
                      </HStack>
                      <Divider />
                      <HStack justify="space-between">
                        <Text>Base Amount:</Text>
                        <Text>
                          {formatCurrency(
                            selectedEntry.breakdown.baseAmountPence
                          )}
                        </Text>
                      </HStack>
                      <HStack justify="space-between">
                        <Text>Surge Amount:</Text>
                        <Text>
                          {formatCurrency(
                            selectedEntry.breakdown.surgeAmountPence
                          )}
                        </Text>
                      </HStack>
                      <HStack justify="space-between">
                        <Text>Tips:</Text>
                        <Text>
                          {formatCurrency(
                            selectedEntry.breakdown.tipAmountPence
                          )}
                        </Text>
                      </HStack>
                      <HStack justify="space-between">
                        <Text>Platform Fees:</Text>
                        <Text color="red.500">
                          -
                          {formatCurrency(
                            selectedEntry.breakdown.feeAmountPence
                          )}
                        </Text>
                      </HStack>
                      <Divider />
                      <HStack justify="space-between">
                        <Text fontWeight="bold">Driver Net Earnings:</Text>
                        <Text fontSize="lg" fontWeight="bold">
                          {formatCurrency(
                            selectedEntry.breakdown.netAmountPence
                          )}
                        </Text>
                      </HStack>
                      <HStack justify="space-between">
                        <Text fontWeight="bold">Platform Margin:</Text>
                        <Text fontSize="lg" fontWeight="bold" color="green.500">
                          {formatCurrency(
                            selectedEntry.Booking.totalGBP -
                              selectedEntry.breakdown.netAmountPence
                          )}
                        </Text>
                      </HStack>
                    </VStack>
                  </CardBody>
                </Card>

                {/* Payment Status */}
                <Card>
                  <CardBody>
                    <Heading size="md" mb={4}>
                      Payment Status
                    </Heading>
                    <VStack spacing={3} align="stretch">
                      <HStack justify="space-between">
                        <Text fontWeight="bold">Calculated At:</Text>
                        <Text>
                          {new Date(
                            selectedEntry.calculatedAt
                          ).toLocaleDateString()}
                        </Text>
                      </HStack>
                      <HStack justify="space-between">
                        <Text fontWeight="bold">Paid Out:</Text>
                        <Badge
                          colorScheme={
                            selectedEntry.paidOut ? 'green' : 'yellow'
                          }
                        >
                          {selectedEntry.paidOut ? 'Yes' : 'No'}
                        </Badge>
                      </HStack>
                      {selectedEntry.paidOutAt && (
                        <HStack justify="space-between">
                          <Text fontWeight="bold">Paid Out At:</Text>
                          <Text>
                            {new Date(
                              selectedEntry.paidOutAt
                            ).toLocaleDateString()}
                          </Text>
                        </HStack>
                      )}
                    </VStack>
                  </CardBody>
                </Card>
              </VStack>
            )}
          </ModalBody>
        </ModalContent>
      </Modal>
    </Box>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import {
  Box,
  Heading,
  HStack,
  VStack,
  Text,
  Badge,
  Card,
  CardBody,
  Button,
  Table,
  Thead,
  Tbody,
  Tr,
  Th,
  Td,
  Input,
  Select,
  useToast,
  Spinner,
  Alert,
  AlertIcon,
  Modal,
  ModalOverlay,
  ModalContent,
  ModalHeader,
  ModalBody,
  ModalCloseButton,
  useDisclosure,
  IconButton,
  Menu,
  MenuButton,
  MenuList,
  MenuItem,
  SimpleGrid,
  Divider,
  Progress,
  Tooltip,
} from '@chakra-ui/react';
import {
  FiSearch,
  FiFilter,
  FiDownload,
  FiEye,
  FiDollarSign,
  FiMoreVertical,
  FiCalendar,
  FiUser,
  FiTruck,
  FiCheck,
  FiX,
  FiClock,
} from 'react-icons/fi';

interface Payout {
  id: string;
  driver: {
    name: string;
    email: string;
    phone: string;
  };
  totalAmountPence: number;
  currency: string;
  status: string;
  processedAt: string;
  failedAt: string;
  failureReason: string;
  stripeTransferId: string;
  bankAccountId: string;
  createdAt: string;
  earnings: Array<{
    id: string;
    assignmentId: string;
    Booking: {
      id: string;
      orderRef: string;
      scheduledAt: string;
    };
    baseAmountPence: number;
    surgeAmountPence: number;
    tipAmountPence: number;
    feeAmountPence: number;
    netAmountPence: number;
    calculatedAt: string;
  }>;
}

interface PayoutsData {
  payouts: Payout[];
  pagination: {
    page: number;
    limit: number;
    total: number;
    pages: number;
  };
  summary: {
    pendingPayouts: number;
    payoutCount: number;
    statusBreakdown: Array<{
      status: string;
      amount: number;
      count: number;
    }>;
    earningsBreakdown: {
      baseAmount: number;
      surgeAmount: number;
      tipAmount: number;
      feeAmount: number;
      netAmount: number;
    };
  };
}

export default function PayoutsPage() {
  const [data, setData] = useState<PayoutsData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [filters, setFilters] = useState({
    search: '',
    status: '',
    driverId: '',
    fromDate: '',
    toDate: '',
  });
  const [currentPage, setCurrentPage] = useState(1);
  const [selectedPayout, setSelectedPayout] = useState<Payout | null>(null);
  const { isOpen, onOpen, onClose } = useDisclosure();
  const toast = useToast();

  const fetchPayouts = async () => {
    try {
      setLoading(true);
      const params = new URLSearchParams({
        page: currentPage.toString(),
        limit: '20',
        ...filters,
      });

      const response = await fetch(`/api/admin/finance/payouts?${params}`);
      if (!response.ok) {
        throw new Error('Failed to fetch payouts');
      }
      const payoutsData = await response.json();
      setData(payoutsData);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An error occurred');
      toast({
        title: 'Error',
        description: 'Failed to load payouts',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchPayouts();
  }, [currentPage, filters]);

  const formatCurrency = (totalGBP: number) => {
    return `£${(totalGBP / 100).toFixed(2)}`;
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'processed':
        return 'green';
      case 'pending':
        return 'yellow';
      case 'processing':
        return 'blue';
      case 'failed':
        return 'red';
      default:
        return 'gray';
    }
  };

  const handleProcessPayout = async (payoutId: string) => {
    try {
      const response = await fetch(
        `/api/admin/finance/payouts/${payoutId}/process`,
        {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
        }
      );

      if (response.ok) {
        toast({
          title: 'Payout processed',
          description: 'The payout has been processed successfully',
          status: 'success',
          duration: 3000,
          isClosable: true,
        });
        fetchPayouts(); // Refresh data
      } else {
        const errorData = await response.json();
        throw new Error(errorData.error || 'Payout processing failed');
      }
    } catch (error) {
      toast({
        title: 'Payout processing failed',
        description:
          error instanceof Error ? error.message : 'Failed to process payout',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    }
  };

  const handleViewPayout = (payout: Payout) => {
    setSelectedPayout(payout);
    onOpen();
  };

  if (loading) {
    return (
      <Box
        display="flex"
        justifyContent="center"
        alignItems="center"
        minH="400px"
      >
        <Spinner size="xl" />
      </Box>
    );
  }

  if (error) {
    return (
      <Alert status="error">
        <AlertIcon />
        {error}
      </Alert>
    );
  }

  return (
    <Box>
      <HStack justify="space-between" mb={6}>
        <VStack align="start" spacing={1}>
          <Heading size="lg">Payouts</Heading>
          <Text color="gray.600">Manage driver payouts and earnings</Text>
        </VStack>
        <Button leftIcon={<FiDownload />} colorScheme="blue" size="sm">
          Export Payouts
        </Button>
      </HStack>

      {/* Filters */}
      <Card mb={6}>
        <CardBody>
          <HStack spacing={4} wrap="wrap">
            <Input
              placeholder="Search drivers..."
              value={filters.search}
              onChange={e => setFilters({ ...filters, search: e.target.value })}
              maxW="300px"
            />
            <Select
              placeholder="Payout Status"
              value={filters.status}
              onChange={e => setFilters({ ...filters, status: e.target.value })}
              maxW="200px"
            >
              <option value="pending">Pending</option>
              <option value="processing">Processing</option>
              <option value="processed">Processed</option>
              <option value="failed">Failed</option>
            </Select>
            <Input
              type="date"
              value={filters.fromDate}
              onChange={e =>
                setFilters({ ...filters, fromDate: e.target.value })
              }
              maxW="150px"
            />
            <Input
              type="date"
              value={filters.toDate}
              onChange={e => setFilters({ ...filters, toDate: e.target.value })}
              maxW="150px"
            />
            <Button
              leftIcon={<FiFilter />}
              variant="outline"
              onClick={() =>
                setFilters({
                  search: '',
                  status: '',
                  driverId: '',
                  fromDate: '',
                  toDate: '',
                })
              }
            >
              Clear Filters
            </Button>
          </HStack>
        </CardBody>
      </Card>

      {/* Summary Stats */}
      {data && (
        <SimpleGrid columns={{ base: 1, md: 5 }} spacing={4} mb={6}>
          <Card>
            <CardBody>
              <HStack>
                <FiDollarSign size={24} />
                <VStack align="start" spacing={0}>
                  <Text fontSize="sm" color="gray.600">
                    Pending Payouts
                  </Text>
                  <Text fontSize="xl" fontWeight="bold">
                    {formatCurrency(data.summary.pendingPayouts)}
                  </Text>
                </VStack>
              </HStack>
            </CardBody>
          </Card>
          <Card>
            <CardBody>
              <HStack>
                <FiTruck size={24} />
                <VStack align="start" spacing={0}>
                  <Text fontSize="sm" color="gray.600">
                    Total Payouts
                  </Text>
                  <Text fontSize="xl" fontWeight="bold">
                    {data.summary.payoutCount}
                  </Text>
                </VStack>
              </HStack>
            </CardBody>
          </Card>
          <Card>
            <CardBody>
              <HStack>
                <FiUser size={24} />
                <VStack align="start" spacing={0}>
                  <Text fontSize="sm" color="gray.600">
                    Base Earnings
                  </Text>
                  <Text fontSize="xl" fontWeight="bold">
                    {formatCurrency(data.summary.earningsBreakdown.baseAmount)}
                  </Text>
                </VStack>
              </HStack>
            </CardBody>
          </Card>
          <Card>
            <CardBody>
              <HStack>
                <FiDollarSign size={24} />
                <VStack align="start" spacing={0}>
                  <Text fontSize="sm" color="gray.600">
                    Tips
                  </Text>
                  <Text fontSize="xl" fontWeight="bold">
                    {formatCurrency(data.summary.earningsBreakdown.tipAmount)}
                  </Text>
                </VStack>
              </HStack>
            </CardBody>
          </Card>
          <Card>
            <CardBody>
              <HStack>
                <FiCalendar size={24} />
                <VStack align="start" spacing={0}>
                  <Text fontSize="sm" color="gray.600">
                    Showing
                  </Text>
                  <Text fontSize="xl" fontWeight="bold">
                    {data.payouts.length} of {data.pagination.total}
                  </Text>
                </VStack>
              </HStack>
            </CardBody>
          </Card>
        </SimpleGrid>
      )}

      {/* Payouts Table */}
      <Card>
        <CardBody>
          <Table variant="simple">
            <Thead>
              <Tr>
                <Th>Driver</Th>
                <Th>Amount</Th>
                <Th>Status</Th>
                <Th>Jobs</Th>
                <Th>Created</Th>
                <Th>Processed</Th>
                <Th>Actions</Th>
              </Tr>
            </Thead>
            <Tbody>
              {data?.payouts.map(payout => (
                <Tr key={payout.id}>
                  <Td>
                    <VStack align="start" spacing={0}>
                      <Text fontSize="sm" fontWeight="medium">
                        {payout.driver.name}
                      </Text>
                      <Text fontSize="xs" color="gray.500">
                        {payout.driver.email}
                      </Text>
                    </VStack>
                  </Td>
                  <Td>
                    <Text fontWeight="bold" fontSize="sm">
                      {formatCurrency(payout.totalAmountPence)}
                    </Text>
                  </Td>
                  <Td>
                    <Badge
                      colorScheme={getStatusColor(payout.status)}
                      size="sm"
                    >
                      {payout.status}
                    </Badge>
                  </Td>
                  <Td>
                    <Text fontSize="sm">{payout.earnings.length} jobs</Text>
                  </Td>
                  <Td>
                    <Text fontSize="sm">
                      {payout.createdAt
                        ? new Date(payout.createdAt).toLocaleDateString()
                        : 'N/A'}
                    </Text>
                  </Td>
                  <Td>
                    <Text fontSize="sm">
                      {payout.processedAt
                        ? new Date(payout.processedAt).toLocaleDateString()
                        : 'N/A'}
                    </Text>
                  </Td>
                  <Td>
                    <Menu>
                      <MenuButton
                        as={IconButton}
                        icon={<FiMoreVertical />}
                        variant="ghost"
                        size="sm"
                      />
                      <MenuList>
                        <MenuItem
                          icon={<FiEye />}
                          onClick={() => handleViewPayout(payout)}
                        >
                          View Details
                        </MenuItem>
                        {payout.status === 'pending' && (
                          <MenuItem
                            icon={<FiCheck />}
                            onClick={() => handleProcessPayout(payout.id)}
                          >
                            Process Payout
                          </MenuItem>
                        )}
                        <MenuItem icon={<FiDownload />}>
                          Download Receipt
                        </MenuItem>
                      </MenuList>
                    </Menu>
                  </Td>
                </Tr>
              ))}
            </Tbody>
          </Table>

          {/* Pagination */}
          {data && data.pagination.pages > 1 && (
            <HStack justify="center" mt={6}>
              <Button
                size="sm"
                variant="outline"
                isDisabled={currentPage === 1}
                onClick={() => setCurrentPage(currentPage - 1)}
              >
                Previous
              </Button>
              <Text>
                Page {currentPage} of {data.pagination.pages}
              </Text>
              <Button
                size="sm"
                variant="outline"
                isDisabled={currentPage === data.pagination.pages}
                onClick={() => setCurrentPage(currentPage + 1)}
              >
                Next
              </Button>
            </HStack>
          )}
        </CardBody>
      </Card>

      {/* Payout Detail Modal */}
      <Modal isOpen={isOpen} onClose={onClose} size="xl">
        <ModalOverlay />
        <ModalContent>
          <ModalHeader>Payout Details</ModalHeader>
          <ModalCloseButton />
          <ModalBody pb={6}>
            {selectedPayout && (
              <VStack spacing={6} align="stretch">
                {/* Driver Info */}
                <Card>
                  <CardBody>
                    <Heading size="md" mb={4}>
                      Driver Information
                    </Heading>
                    <VStack spacing={3} align="stretch">
                      <HStack justify="space-between">
                        <Text fontWeight="bold">Name:</Text>
                        <Text>{selectedPayout.driver.name}</Text>
                      </HStack>
                      <HStack justify="space-between">
                        <Text fontWeight="bold">Email:</Text>
                        <Text>{selectedPayout.driver.email}</Text>
                      </HStack>
                      <HStack justify="space-between">
                        <Text fontWeight="bold">Phone:</Text>
                        <Text>{selectedPayout.driver.phone}</Text>
                      </HStack>
                    </VStack>
                  </CardBody>
                </Card>

                {/* Payout Summary */}
                <Card>
                  <CardBody>
                    <Heading size="md" mb={4}>
                      Payout Summary
                    </Heading>
                    <VStack spacing={3} align="stretch">
                      <HStack justify="space-between">
                        <Text fontWeight="bold">Total Amount:</Text>
                        <Text fontSize="lg" fontWeight="bold">
                          {formatCurrency(selectedPayout.totalAmountPence)}
                        </Text>
                      </HStack>
                      <HStack justify="space-between">
                        <Text fontWeight="bold">Status:</Text>
                        <Badge
                          colorScheme={getStatusColor(selectedPayout.status)}
                          size="lg"
                        >
                          {selectedPayout.status}
                        </Badge>
                      </HStack>
                      <HStack justify="space-between">
                        <Text fontWeight="bold">Created:</Text>
                        <Text>
                          {new Date(
                            selectedPayout.createdAt
                          ).toLocaleDateString()}
                        </Text>
                      </HStack>
                      {selectedPayout.processedAt && (
                        <HStack justify="space-between">
                          <Text fontWeight="bold">Processed:</Text>
                          <Text>
                            {new Date(
                              selectedPayout.processedAt
                            ).toLocaleDateString()}
                          </Text>
                        </HStack>
                      )}
                      {selectedPayout.stripeTransferId && (
                        <HStack justify="space-between">
                          <Text fontWeight="bold">Stripe Transfer ID:</Text>
                          <Text fontSize="sm">
                            {selectedPayout.stripeTransferId}
                          </Text>
                        </HStack>
                      )}
                      {selectedPayout.failureReason && (
                        <HStack justify="space-between">
                          <Text fontWeight="bold">Failure Reason:</Text>
                          <Text color="red.500">
                            {selectedPayout.failureReason}
                          </Text>
                        </HStack>
                      )}
                    </VStack>
                  </CardBody>
                </Card>

                {/* Earnings Breakdown */}
                <Card>
                  <CardBody>
                    <Heading size="md" mb={4}>
                      Earnings Breakdown
                    </Heading>
                    <Table variant="simple" size="sm">
                      <Thead>
                        <Tr>
                          <Th>Job</Th>
                          <Th>Base</Th>
                          <Th>Surge</Th>
                          <Th>Tips</Th>
                          <Th>Fees</Th>
                          <Th>Net</Th>
                        </Tr>
                      </Thead>
                      <Tbody>
                        {selectedPayout.earnings.map(earning => (
                          <Tr key={earning.id}>
                            <Td>
                              <Text fontSize="sm">
                                {earning.Booking.orderRef}
                              </Text>
                              <Text fontSize="xs" color="gray.500">
                                {new Date(
                                  earning.Booking.scheduledAt
                                ).toLocaleDateString()}
                              </Text>
                            </Td>
                            <Td>
                              <Text fontSize="sm">
                                {formatCurrency(earning.baseAmountPence)}
                              </Text>
                            </Td>
                            <Td>
                              <Text fontSize="sm">
                                {formatCurrency(earning.surgeAmountPence)}
                              </Text>
                            </Td>
                            <Td>
                              <Text fontSize="sm">
                                {formatCurrency(earning.tipAmountPence)}
                              </Text>
                            </Td>
                            <Td>
                              <Text fontSize="sm">
                                {formatCurrency(earning.feeAmountPence)}
                              </Text>
                            </Td>
                            <Td>
                              <Text fontSize="sm" fontWeight="bold">
                                {formatCurrency(earning.netAmountPence)}
                              </Text>
                            </Td>
                          </Tr>
                        ))}
                      </Tbody>
                    </Table>
                  </CardBody>
                </Card>
              </VStack>
            )}
          </ModalBody>
        </ModalContent>
      </Modal>
    </Box>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import {
  Box,
  Heading,
  HStack,
  VStack,
  Text,
  Badge,
  Card,
  CardBody,
  Button,
  Table,
  Thead,
  Tbody,
  Tr,
  Th,
  Td,
  Input,
  Select,
  useToast,
  Spinner,
  Alert,
  AlertIcon,
  Modal,
  ModalOverlay,
  ModalContent,
  ModalHeader,
  ModalBody,
  ModalCloseButton,
  useDisclosure,
  FormControl,
  FormLabel,
  Textarea,
  NumberInput,
  NumberInputField,
  NumberInputStepper,
  NumberIncrementStepper,
  NumberDecrementStepper,
  IconButton,
  Menu,
  MenuButton,
  MenuList,
  MenuItem,
  SimpleGrid,
  Divider,
} from '@chakra-ui/react';
import {
  FiSearch,
  FiFilter,
  FiDownload,
  FiEye,
  FiRefreshCw,
  FiMoreVertical,
  FiCalendar,
  FiUser,
  FiDollarSign,
  FiPlus,
} from 'react-icons/fi';

interface Refund {
  id: string;
  orderRef: string;
  customer: {
    name: string;
    email: string;
    phone: string;
  };
  totalGBP: number;
  refundAmountPence: number;
  refundReason: string;
  refundNotes: string;
  refundedAt: string;
  refundedBy: string;
  stripePaymentIntentId: string;
  stripeRefundId: string;
}

interface RefundsData {
  refunds: Refund[];
  pagination: {
    page: number;
    limit: number;
    total: number;
    pages: number;
  };
  summary: {
    totalRefunds: number;
    refundCount: number;
    reasonsBreakdown: Array<{
      reason: string;
      amount: number;
      count: number;
    }>;
  };
}

const REFUND_REASONS = [
  'Service not provided',
  'Customer cancellation',
  'Driver no-show',
  'Poor service quality',
  'Billing error',
  'Technical issue',
  'Weather conditions',
  'Vehicle breakdown',
  'Other',
];

export default function RefundsPage() {
  const [data, setData] = useState<RefundsData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [filters, setFilters] = useState({
    search: '',
    reason: '',
    fromDate: '',
    toDate: '',
  });
  const [currentPage, setCurrentPage] = useState(1);
  const [selectedRefund, setSelectedRefund] = useState<Refund | null>(null);
  const [refundForm, setRefundForm] = useState({
    amount: '',
    reason: '',
    notes: '',
    type: 'full',
  });
  const { isOpen, onOpen, onClose } = useDisclosure();
  const {
    isOpen: isRefundOpen,
    onOpen: onRefundOpen,
    onClose: onRefundClose,
  } = useDisclosure();
  const toast = useToast();

  const fetchRefunds = async () => {
    try {
      setLoading(true);
      const params = new URLSearchParams({
        page: currentPage.toString(),
        limit: '20',
        ...filters,
      });

      const response = await fetch(`/api/admin/finance/refunds?${params}`);
      if (!response.ok) {
        throw new Error('Failed to fetch refunds');
      }
      const refundsData = await response.json();
      setData(refundsData);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An error occurred');
      toast({
        title: 'Error',
        description: 'Failed to load refunds',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchRefunds();
  }, [currentPage, filters]);

  const formatCurrency = (totalGBP: number) => {
    return `£${(totalGBP / 100).toFixed(2)}`;
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'processed':
        return 'green';
      case 'pending':
        return 'yellow';
      case 'failed':
        return 'red';
      default:
        return 'gray';
    }
  };

  const handleIssueRefund = async () => {
    if (!refundForm.amount || !refundForm.reason) {
      toast({
        title: 'Missing information',
        description: 'Please fill in all required fields',
        status: 'warning',
        duration: 3000,
        isClosable: true,
      });
      return;
    }

    try {
      const response = await fetch('/api/admin/finance/refunds', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          bookingId: selectedRefund?.id,
          totalGBP: parseFloat(refundForm.amount) * 100,
          reason: refundForm.reason,
          notes: refundForm.notes,
          type: refundForm.type,
        }),
      });

      if (response.ok) {
        toast({
          title: 'Refund issued successfully',
          description: 'The refund has been processed',
          status: 'success',
          duration: 3000,
          isClosable: true,
        });
        setRefundForm({ amount: '', reason: '', notes: '', type: 'full' });
        onRefundClose();
        fetchRefunds(); // Refresh data
      } else {
        const errorData = await response.json();
        throw new Error(errorData.error || 'Refund failed');
      }
    } catch (error) {
      toast({
        title: 'Refund failed',
        description:
          error instanceof Error ? error.message : 'Failed to process refund',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    }
  };

  const handleViewRefund = (refund: Refund) => {
    setSelectedRefund(refund);
    onOpen();
  };

  const handleNewRefund = () => {
    setRefundForm({ amount: '', reason: '', notes: '', type: 'full' });
    onRefundOpen();
  };

  if (loading) {
    return (
      <Box
        display="flex"
        justifyContent="center"
        alignItems="center"
        minH="400px"
      >
        <Spinner size="xl" />
      </Box>
    );
  }

  if (error) {
    return (
      <Alert status="error">
        <AlertIcon />
        {error}
      </Alert>
    );
  }

  return (
    <Box>
      <HStack justify="space-between" mb={6}>
        <VStack align="start" spacing={1}>
          <Heading size="lg">Refunds</Heading>
          <Text color="gray.600">Manage customer refunds and processing</Text>
        </VStack>
        <Button
          leftIcon={<FiPlus />}
          colorScheme="blue"
          size="sm"
          onClick={handleNewRefund}
        >
          Issue Refund
        </Button>
      </HStack>

      {/* Filters */}
      <Card mb={6}>
        <CardBody>
          <HStack spacing={4} wrap="wrap">
            <Input
              placeholder="Search refunds, customers..."
              value={filters.search}
              onChange={e => setFilters({ ...filters, search: e.target.value })}
              maxW="300px"
            />
            <Select
              placeholder="Refund Reason"
              value={filters.reason}
              onChange={e => setFilters({ ...filters, reason: e.target.value })}
              maxW="200px"
            >
              {REFUND_REASONS.map(reason => (
                <option key={reason} value={reason}>
                  {reason}
                </option>
              ))}
            </Select>
            <Input
              type="date"
              value={filters.fromDate}
              onChange={e =>
                setFilters({ ...filters, fromDate: e.target.value })
              }
              maxW="150px"
            />
            <Input
              type="date"
              value={filters.toDate}
              onChange={e => setFilters({ ...filters, toDate: e.target.value })}
              maxW="150px"
            />
            <Button
              leftIcon={<FiFilter />}
              variant="outline"
              onClick={() =>
                setFilters({ search: '', reason: '', fromDate: '', toDate: '' })
              }
            >
              Clear Filters
            </Button>
          </HStack>
        </CardBody>
      </Card>

      {/* Summary Stats */}
      {data && (
        <SimpleGrid columns={{ base: 1, md: 4 }} spacing={4} mb={6}>
          <Card>
            <CardBody>
              <HStack>
                <FiDollarSign size={24} />
                <VStack align="start" spacing={0}>
                  <Text fontSize="sm" color="gray.600">
                    Total Refunds
                  </Text>
                  <Text fontSize="xl" fontWeight="bold">
                    {formatCurrency(data.summary.totalRefunds)}
                  </Text>
                </VStack>
              </HStack>
            </CardBody>
          </Card>
          <Card>
            <CardBody>
              <HStack>
                <FiRefreshCw size={24} />
                <VStack align="start" spacing={0}>
                  <Text fontSize="sm" color="gray.600">
                    Refund Count
                  </Text>
                  <Text fontSize="xl" fontWeight="bold">
                    {data.summary.refundCount}
                  </Text>
                </VStack>
              </HStack>
            </CardBody>
          </Card>
          <Card>
            <CardBody>
              <HStack>
                <FiCalendar size={24} />
                <VStack align="start" spacing={0}>
                  <Text fontSize="sm" color="gray.600">
                    Showing
                  </Text>
                  <Text fontSize="xl" fontWeight="bold">
                    {data.refunds.length} of {data.pagination.total}
                  </Text>
                </VStack>
              </HStack>
            </CardBody>
          </Card>
          <Card>
            <CardBody>
              <HStack>
                <FiUser size={24} />
                <VStack align="start" spacing={0}>
                  <Text fontSize="sm" color="gray.600">
                    Top Reason
                  </Text>
                  <Text fontSize="xl" fontWeight="bold">
                    {data.summary.reasonsBreakdown[0]?.reason || 'N/A'}
                  </Text>
                </VStack>
              </HStack>
            </CardBody>
          </Card>
        </SimpleGrid>
      )}

      {/* Refunds Table */}
      <Card>
        <CardBody>
          <Table variant="simple">
            <Thead>
              <Tr>
                <Th>Order Ref</Th>
                <Th>Customer</Th>
                <Th>Original Amount</Th>
                <Th>Refund Amount</Th>
                <Th>Reason</Th>
                <Th>Date</Th>
                <Th>Actions</Th>
              </Tr>
            </Thead>
            <Tbody>
              {data?.refunds.map(refund => (
                <Tr key={refund.id}>
                  <Td>
                    <Text fontWeight="bold" fontSize="sm">
                      {refund.orderRef}
                    </Text>
                  </Td>
                  <Td>
                    <VStack align="start" spacing={0}>
                      <Text fontSize="sm" fontWeight="medium">
                        {refund.customer.name}
                      </Text>
                      <Text fontSize="xs" color="gray.500">
                        {refund.customer.email}
                      </Text>
                    </VStack>
                  </Td>
                  <Td>
                    <Text fontSize="sm">{formatCurrency(refund.totalGBP)}</Text>
                  </Td>
                  <Td>
                    <Text fontWeight="bold" fontSize="sm" color="red.500">
                      -{formatCurrency(refund.refundAmountPence)}
                    </Text>
                  </Td>
                  <Td>
                    <Text fontSize="sm">{refund.refundReason}</Text>
                  </Td>
                  <Td>
                    <Text fontSize="sm">
                      {refund.refundedAt
                        ? new Date(refund.refundedAt).toLocaleDateString()
                        : 'N/A'}
                    </Text>
                  </Td>
                  <Td>
                    <Menu>
                      <MenuButton
                        as={IconButton}
                        icon={<FiMoreVertical />}
                        variant="ghost"
                        size="sm"
                      />
                      <MenuList>
                        <MenuItem
                          icon={<FiEye />}
                          onClick={() => handleViewRefund(refund)}
                        >
                          View Details
                        </MenuItem>
                        <MenuItem icon={<FiDownload />}>
                          Download Receipt
                        </MenuItem>
                      </MenuList>
                    </Menu>
                  </Td>
                </Tr>
              ))}
            </Tbody>
          </Table>

          {/* Pagination */}
          {data && data.pagination.pages > 1 && (
            <HStack justify="center" mt={6}>
              <Button
                size="sm"
                variant="outline"
                isDisabled={currentPage === 1}
                onClick={() => setCurrentPage(currentPage - 1)}
              >
                Previous
              </Button>
              <Text>
                Page {currentPage} of {data.pagination.pages}
              </Text>
              <Button
                size="sm"
                variant="outline"
                isDisabled={currentPage === data.pagination.pages}
                onClick={() => setCurrentPage(currentPage + 1)}
              >
                Next
              </Button>
            </HStack>
          )}
        </CardBody>
      </Card>

      {/* Refund Detail Modal */}
      <Modal isOpen={isOpen} onClose={onClose} size="xl">
        <ModalOverlay />
        <ModalContent>
          <ModalHeader>Refund Details</ModalHeader>
          <ModalCloseButton />
          <ModalBody pb={6}>
            {selectedRefund && (
              <VStack spacing={4} align="stretch">
                <HStack justify="space-between">
                  <Text fontWeight="bold">Order Reference:</Text>
                  <Text>{selectedRefund.orderRef}</Text>
                </HStack>
                <HStack justify="space-between">
                  <Text fontWeight="bold">Customer:</Text>
                  <VStack align="end" spacing={0}>
                    <Text>{selectedRefund.customer.name}</Text>
                    <Text fontSize="sm" color="gray.500">
                      {selectedRefund.customer.email}
                    </Text>
                  </VStack>
                </HStack>
                <HStack justify="space-between">
                  <Text fontWeight="bold">Original Amount:</Text>
                  <Text>{formatCurrency(selectedRefund.totalGBP)}</Text>
                </HStack>
                <HStack justify="space-between">
                  <Text fontWeight="bold">Refund Amount:</Text>
                  <Text color="red.500">
                    -{formatCurrency(selectedRefund.refundAmountPence)}
                  </Text>
                </HStack>
                <HStack justify="space-between">
                  <Text fontWeight="bold">Reason:</Text>
                  <Text>{selectedRefund.refundReason}</Text>
                </HStack>
                <HStack justify="space-between">
                  <Text fontWeight="bold">Refund Date:</Text>
                  <Text>
                    {selectedRefund.refundedAt
                      ? new Date(selectedRefund.refundedAt).toLocaleDateString()
                      : 'N/A'}
                  </Text>
                </HStack>
                <HStack justify="space-between">
                  <Text fontWeight="bold">Stripe Refund ID:</Text>
                  <Text fontSize="sm">
                    {selectedRefund.stripeRefundId || 'N/A'}
                  </Text>
                </HStack>
                {selectedRefund.refundNotes && (
                  <>
                    <Divider />
                    <VStack align="start" spacing={2}>
                      <Text fontWeight="bold">Notes:</Text>
                      <Text fontSize="sm">{selectedRefund.refundNotes}</Text>
                    </VStack>
                  </>
                )}
              </VStack>
            )}
          </ModalBody>
        </ModalContent>
      </Modal>

      {/* Issue Refund Modal */}
      <Modal isOpen={isRefundOpen} onClose={onRefundClose} size="md">
        <ModalOverlay />
        <ModalContent>
          <ModalHeader>Issue Refund</ModalHeader>
          <ModalCloseButton />
          <ModalBody pb={6}>
            <VStack spacing={4}>
              <FormControl>
                <FormLabel>Refund Type</FormLabel>
                <Select
                  value={refundForm.type}
                  onChange={e =>
                    setRefundForm({ ...refundForm, type: e.target.value })
                  }
                >
                  <option value="full">Full Refund</option>
                  <option value="partial">Partial Refund</option>
                </Select>
              </FormControl>

              {refundForm.type === 'partial' && (
                <FormControl>
                  <FormLabel>Refund Amount (£)</FormLabel>
                  <NumberInput
                    value={refundForm.amount}
                    onChange={value =>
                      setRefundForm({ ...refundForm, amount: value })
                    }
                    min={0}
                    precision={2}
                  >
                    <NumberInputField />
                    <NumberInputStepper>
                      <NumberIncrementStepper />
                      <NumberDecrementStepper />
                    </NumberInputStepper>
                  </NumberInput>
                </FormControl>
              )}

              <FormControl>
                <FormLabel>Refund Reason</FormLabel>
                <Select
                  value={refundForm.reason}
                  onChange={e =>
                    setRefundForm({ ...refundForm, reason: e.target.value })
                  }
                >
                  <option value="">Select a reason</option>
                  {REFUND_REASONS.map(reason => (
                    <option key={reason} value={reason}>
                      {reason}
                    </option>
                  ))}
                </Select>
              </FormControl>

              <FormControl>
                <FormLabel>Notes (Optional)</FormLabel>
                <Textarea
                  value={refundForm.notes}
                  onChange={e =>
                    setRefundForm({ ...refundForm, notes: e.target.value })
                  }
                  placeholder="Additional notes about the refund..."
                />
              </FormControl>

              <HStack spacing={3} w="full">
                <Button variant="outline" onClick={onRefundClose} flex={1}>
                  Cancel
                </Button>
                <Button colorScheme="red" onClick={handleIssueRefund} flex={1}>
                  Issue Refund
                </Button>
              </HStack>
            </VStack>
          </ModalBody>
        </ModalContent>
      </Modal>
    </Box>
  );
}

'use client';

import React, { useEffect, useState } from 'react';
import {
  Box,
  Heading,
  HStack,
  VStack,
  Text,
  Badge,
  Card,
  CardBody,
  Button,
  SimpleGrid,
  Stat,
  StatLabel,
  StatNumber,
  StatHelpText,
  Grid,
  GridItem,
  Progress,
  Alert,
  AlertIcon,
  AlertTitle,
  AlertDescription,
} from '@chakra-ui/react';
import LoadingSpinner from '@/components/admin/LoadingSpinner';
import {
  FiActivity,
  FiDatabase,
  FiServer,
  FiWifi,
  FiClock,
  FiRefreshCw,
  FiAlertTriangle,
  FiCheckCircle,
} from 'react-icons/fi';

interface ServiceHealth {
  status: string;
  responseTime: string;
  connections?: number;
  maxConnections?: number;
  memoryUsage?: string;
  hitRate?: string;
  depth?: number;
  maxDepth?: number;
  processingRate?: string;
  successRate?: string;
  pendingWebhooks?: number;
  channels?: number;
  apiLatency?: string;
  webhookSuccess?: string;
  lastHeartbeat: string;
}

interface SystemHealth {
  overall: string;
  uptime: string;
  lastCheck: string;
  responseTime: number;
  services: {
    database: ServiceHealth;
    cache: ServiceHealth;
    queue: ServiceHealth;
    webhooks: ServiceHealth;
    pusher: ServiceHealth;
    stripe: ServiceHealth;
  };
  recentIncidents: Array<{
    id: string;
    service: string;
    severity: string;
    message: string;
    timestamp: string;
    resolved: boolean;
  }>;
  performanceMetrics: {
    avgResponseTime: string;
    requestsPerSecond: number;
    errorRate: string;
    activeUsers: number;
  };
}

export default function HealthPage() {
  const [healthData, setHealthData] = useState<SystemHealth | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [lastRefresh, setLastRefresh] = useState<Date>(new Date());

  async function loadHealthData() {
    setLoading(true);
    setError(null);

    try {
      const response = await fetch('/api/admin/health');
      if (!response.ok) {
        throw new Error('Failed to fetch health data');
      }

      const data = await response.json();
      setHealthData(data);
      setLastRefresh(new Date());
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An error occurred');
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    loadHealthData();

    // Auto-refresh every 30 seconds
    const interval = setInterval(loadHealthData, 30000);
    return () => clearInterval(interval);
  }, []);

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'healthy':
        return 'green';
      case 'warning':
        return 'yellow';
      case 'error':
        return 'red';
      case 'degraded':
        return 'orange';
      default:
        return 'gray';
    }
  };

  const getSeverityColor = (severity: string) => {
    switch (severity) {
      case 'critical':
        return 'red';
      case 'error':
        return 'red';
      case 'warning':
        return 'yellow';
      case 'info':
        return 'blue';
      default:
        return 'gray';
    }
  };

  if (!healthData && !loading) {
    return (
      <Box p={6}>
        <Alert status="error" mb={4}>
          <AlertIcon />
          <AlertTitle>Error!</AlertTitle>
          <AlertDescription>
            Failed to load health data. Please try refreshing the page.
          </AlertDescription>
        </Alert>
        <Button
          onClick={loadHealthData}
          colorScheme="blue"
          leftIcon={<FiRefreshCw />}
        >
          Retry
        </Button>
      </Box>
    );
  }

  return (
    <Box>
      <HStack justify="space-between" mb={6}>
        <VStack align="start" spacing={1}>
          <Heading size="lg">System Health</Heading>
          <Text color="text.secondary">
            Real-time system monitoring and status
          </Text>
        </VStack>
        <HStack spacing={3}>
          <Text fontSize="sm" color="text.secondary">
            <span suppressHydrationWarning>
              Last updated: {lastRefresh.toLocaleTimeString()}
            </span>
          </Text>
          <Button
            leftIcon={<FiRefreshCw />}
            variant="outline"
            size="sm"
            onClick={loadHealthData}
            isLoading={loading}
          >
            Refresh
          </Button>
        </HStack>
      </HStack>

      {/* Error Alert */}
      {error && (
        <Alert status="error" mb={4}>
          <AlertIcon />
          <AlertTitle>Error!</AlertTitle>
          <AlertDescription>{error}</AlertDescription>
        </Alert>
      )}

      {/* Loading State */}
      {loading && !healthData && (
        <LoadingSpinner message="Loading health data..." />
      )}

      {healthData && (
        <>
          {/* Overall Status */}
          <Card mb={6}>
            <CardBody>
              <HStack justify="space-between">
                <VStack align="start" spacing={1}>
                  <HStack>
                    <FiActivity />
                    <Text fontWeight="bold" fontSize="lg">
                      Overall System Status
                    </Text>
                  </HStack>
                  <Text color="text.secondary">All systems operational</Text>
                </VStack>
                <VStack align="end" spacing={1}>
                  <Badge
                    colorScheme={getStatusColor(healthData.overall)}
                    size="lg"
                  >
                    {(healthData.overall || 'unknown').toUpperCase()}
                  </Badge>
                  <Text fontSize="sm" color="text.secondary">
                    Uptime: {healthData.uptime}
                  </Text>
                </VStack>
              </HStack>
            </CardBody>
          </Card>

          {/* Performance Metrics */}
          <SimpleGrid columns={{ base: 1, md: 2, lg: 4 }} spacing={4} mb={6}>
            <Card>
              <CardBody>
                <Stat>
                  <StatLabel>Avg Response Time</StatLabel>
                  <StatNumber>
                    {healthData.performanceMetrics.avgResponseTime}
                  </StatNumber>
                  <StatHelpText>
                    <FiClock
                      style={{ display: 'inline', marginRight: '4px' }}
                    />
                    API performance
                  </StatHelpText>
                </Stat>
              </CardBody>
            </Card>

            <Card>
              <CardBody>
                <Stat>
                  <StatLabel>Requests/Second</StatLabel>
                  <StatNumber>
                    {(
                      healthData.performanceMetrics.requestsPerSecond || 0
                    ).toLocaleString()}
                  </StatNumber>
                  <StatHelpText>
                    <FiActivity
                      style={{ display: 'inline', marginRight: '4px' }}
                    />
                    Current load
                  </StatHelpText>
                </Stat>
              </CardBody>
            </Card>

            <Card>
              <CardBody>
                <Stat>
                  <StatLabel>Error Rate</StatLabel>
                  <StatNumber color="red.500">
                    {healthData.performanceMetrics.errorRate}
                  </StatNumber>
                  <StatHelpText>
                    <FiAlertTriangle
                      style={{ display: 'inline', marginRight: '4px' }}
                    />
                    Last hour
                  </StatHelpText>
                </Stat>
              </CardBody>
            </Card>

            <Card>
              <CardBody>
                <Stat>
                  <StatLabel>Active Users</StatLabel>
                  <StatNumber>
                    {healthData.performanceMetrics.activeUsers}
                  </StatNumber>
                  <StatHelpText>
                    <FiWifi style={{ display: 'inline', marginRight: '4px' }} />
