                  </StatHelpText>
                </Stat>
              </CardBody>
            </Card>
          </SimpleGrid>

          <Grid templateColumns={{ base: '1fr', lg: '2fr 1fr' }} gap={6}>
            {/* Service Status */}
            <VStack spacing={6} align="stretch">
              <Card>
                <CardBody>
                  <Heading size="md" mb={4}>
                    Service Status
                  </Heading>
                  <VStack spacing={4} align="stretch">
                    {Object.entries(healthData.services || {}).map(
                      ([service, data]: [string, ServiceHealth]) => (
                        <Card key={service} variant="outline">
                          <CardBody>
                            <HStack justify="space-between">
                              <VStack align="start" spacing={1}>
                                <HStack>
                                  <Text
                                    fontWeight="bold"
                                    textTransform="capitalize"
                                  >
                                    {service}
                                  </Text>
                                  <Badge
                                    colorScheme={getStatusColor(data.status)}
                                    size="sm"
                                  >
                                    {data.status}
                                  </Badge>
                                </HStack>
                                <Text fontSize="sm" color="gray.600">
                                  Last heartbeat:{' '}
                                  {data.lastHeartbeat
                                    ? new Date(
                                        data.lastHeartbeat
                                      ).toLocaleTimeString()
                                    : 'N/A'}
                                </Text>
                              </VStack>
                              <VStack align="end" spacing={1}>
                                {service === 'database' && (
                                  <>
                                    <Text fontSize="sm">
                                      Connections: {data.connections || 0}/
                                      {data.maxConnections || 0}
                                    </Text>
                                    <Progress
                                      value={
                                        data.connections && data.maxConnections
                                          ? (data.connections /
                                              data.maxConnections) *
                                            100
                                          : 0
                                      }
                                      size="sm"
                                      w="100px"
                                    />
                                  </>
                                )}
                                {service === 'cache' && (
                                  <>
                                    <Text fontSize="sm">
                                      Memory: {data.memoryUsage || 'N/A'}
                                    </Text>
                                    <Text fontSize="sm">
                                      Hit Rate: {data.hitRate || 'N/A'}
                                    </Text>
                                  </>
                                )}
                                {service === 'queue' && (
                                  <>
                                    <Text
                                      fontSize="sm"
                                      color={
                                        data.depth &&
                                        data.maxDepth &&
                                        data.depth > data.maxDepth
                                          ? 'red.500'
                                          : 'gray.600'
                                      }
                                    >
                                      Depth:{' '}
                                      {(data.depth || 0).toLocaleString()}
                                    </Text>
                                    <Text fontSize="sm">
                                      {data.processingRate || 'N/A'}
                                    </Text>
                                  </>
                                )}
                                {service === 'webhooks' && (
                                  <>
                                    <Text fontSize="sm">
                                      Success: {data.successRate || 'N/A'}
                                    </Text>
                                    <Text fontSize="sm">
                                      Pending: {data.pendingWebhooks || 0}
                                    </Text>
                                  </>
                                )}
                                {service === 'pusher' && (
                                  <>
                                    <Text fontSize="sm">
                                      Connections:{' '}
                                      {(data.connections || 0).toLocaleString()}
                                    </Text>
                                    <Text fontSize="sm">
                                      Channels: {data.channels || 0}
                                    </Text>
                                  </>
                                )}
                                {service === 'stripe' && (
                                  <>
                                    <Text fontSize="sm">
                                      Latency: {data.apiLatency || 'N/A'}
                                    </Text>
                                    <Text fontSize="sm">
                                      Webhooks: {data.webhookSuccess || 'N/A'}
                                    </Text>
                                  </>
                                )}
                              </VStack>
                            </HStack>
                          </CardBody>
                        </Card>
                      )
                    )}
                  </VStack>
                </CardBody>
              </Card>
            </VStack>

            {/* Recent Incidents & Quick Actions */}
            <VStack spacing={6} align="stretch">
              {/* Recent Incidents */}
              <Card>
                <CardBody>
                  <Heading size="md" mb={4}>
                    Recent Incidents
                  </Heading>
                  <VStack spacing={3} align="stretch">
                    {(healthData.recentIncidents || []).map(incident => (
                      <Alert
                        key={incident.id}
                        status={getSeverityColor(incident.severity) as any}
                        variant="left-accent"
                      >
                        <AlertIcon />
                        <VStack align="start" spacing={1}>
                          <AlertTitle fontSize="sm">
                            {incident.service}
                          </AlertTitle>
                          <AlertDescription fontSize="sm">
                            {incident.message}
                          </AlertDescription>
                          <Text fontSize="xs" color="gray.600">
                            {new Date(incident.timestamp).toLocaleString()}
                          </Text>
                        </VStack>
                      </Alert>
                    ))}
                    {(healthData.recentIncidents || []).length === 0 && (
                      <Text color="gray.500" textAlign="center" py={4}>
                        No recent incidents
                      </Text>
                    )}
                  </VStack>
                </CardBody>
              </Card>

              {/* Quick Actions */}
              <Card>
                <CardBody>
                  <Heading size="md" mb={4}>
                    Quick Actions
                  </Heading>
                  <VStack spacing={3} align="stretch">
                    <Button
                      leftIcon={<FiDatabase />}
                      variant="outline"
                      size="sm"
                    >
                      Test Database Connection
                    </Button>
                    <Button leftIcon={<FiServer />} variant="outline" size="sm">
                      Clear Cache
                    </Button>
                    <Button leftIcon={<FiWifi />} variant="outline" size="sm">
                      Test Webhooks
                    </Button>
                    <Button
                      leftIcon={<FiRefreshCw />}
                      variant="outline"
                      size="sm"
                    >
                      Restart Queue Workers
                    </Button>
                  </VStack>
                </CardBody>
              </Card>

              {/* System Info */}
              <Card>
                <CardBody>
                  <Heading size="md" mb={4}>
                    System Information
                  </Heading>
                  <VStack spacing={3} align="stretch">
                    <HStack justify="space-between">
                      <Text fontSize="sm">Environment</Text>
                      <Badge colorScheme="blue" size="sm">
                        Production
                      </Badge>
                    </HStack>
                    <HStack justify="space-between">
                      <Text fontSize="sm">Version</Text>
                      <Text fontSize="sm">v2.1.0</Text>
                    </HStack>
                    <HStack justify="space-between">
                      <Text fontSize="sm">Region</Text>
                      <Text fontSize="sm">eu-west-2</Text>
                    </HStack>
                    <HStack justify="space-between">
                      <Text fontSize="sm">Last Deployment</Text>
                      <Text fontSize="sm">2024-01-15 10:30</Text>
                    </HStack>
                  </VStack>
                </CardBody>
              </Card>
            </VStack>
          </Grid>

          {/* Health Checks */}
          <Card mt={6}>
            <CardBody>
              <Heading size="md" mb={4}>
                Health Checks
              </Heading>
              <SimpleGrid columns={{ base: 1, md: 2, lg: 4 }} spacing={4}>
                <HStack
                  justify="space-between"
                  p={3}
                  bg="gray.50"
                  borderRadius="md"
                >
                  <HStack>
                    <FiCheckCircle color="green" />
                    <Text fontSize="sm">Database</Text>
                  </HStack>
                  <Text fontSize="sm" color="green.500">
                    ✓
                  </Text>
                </HStack>
                <HStack
                  justify="space-between"
                  p={3}
                  bg="gray.50"
                  borderRadius="md"
                >
                  <HStack>
                    <FiCheckCircle color="green" />
                    <Text fontSize="sm">Cache</Text>
                  </HStack>
                  <Text fontSize="sm" color="green.500">
                    ✓
                  </Text>
                </HStack>
                <HStack
                  justify="space-between"
                  p={3}
                  bg="yellow.50"
                  borderRadius="md"
                >
                  <HStack>
                    <FiAlertTriangle color="orange" />
                    <Text fontSize="sm">Queue</Text>
                  </HStack>
                  <Text fontSize="sm" color="orange.500">
                    ⚠
                  </Text>
                </HStack>
                <HStack
                  justify="space-between"
                  p={3}
                  bg="gray.50"
                  borderRadius="md"
                >
                  <HStack>
                    <FiCheckCircle color="green" />
                    <Text fontSize="sm">Webhooks</Text>
                  </HStack>
                  <Text fontSize="sm" color="green.500">
                    ✓
                  </Text>
                </HStack>
              </SimpleGrid>
            </CardBody>
          </Card>
        </>
      )}
    </Box>
  );
}

import React from 'react';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { redirect } from 'next/navigation';
import nextDynamic from 'next/dynamic';
const UnifiedNavigationClient = nextDynamic(() => import('@/components/shared/UnifiedNavigation').then(m => m.UnifiedNavigation), { ssr: false });
import UnifiedErrorBoundary from '@/components/shared/UnifiedErrorBoundary';
import { ROUTES } from '@/lib/routing';
import SpeedyAIChatbotProvider from '@/components/admin/SpeedyAIChatbotProvider';

// CRITICAL: Force dynamic rendering because we use getServerSession() which requires cookies()
// This prevents DYNAMIC_SERVER_USAGE error in production builds
export const dynamic = 'force-dynamic';
export const revalidate = 0;

export default async function AdminLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  const session = await getServerSession(authOptions);

  // Add debugging
  console.log('🔐 Admin Layout - Session check:', {
    hasSession: !!session,
    userId: session?.user?.id,
    userRole: (session?.user as any)?.role,
    adminRole: (session?.user as any)?.adminRole,
    email: session?.user?.email,
    timestamp: new Date().toISOString(),
  });

  if (!session?.user) {
    console.log('❌ Admin Layout - No session, redirecting to login');
    redirect(ROUTES.LOGIN);
  }

  if ((session.user as any).role !== 'admin') {
    console.log('❌ Admin Layout - User is not admin, redirecting to login');
    redirect(ROUTES.LOGIN);
  }

  console.log('✅ Admin Layout - Access granted for admin user');

  return (
    <>
      {/* Load Pusher for real-time notifications */}
      <script src="https://js.pusher.com/8.2.0/pusher.min.js" async></script>
      
      <UnifiedNavigationClient role="admin" isAuthenticated={true}>
        <UnifiedErrorBoundary role="admin">{children}</UnifiedErrorBoundary>
      </UnifiedNavigationClient>
      
      {/* Speedy AI Chatbot */}
      <SpeedyAIChatbotProvider />
    </>
  );
}

import { authOptions } from '@/lib/auth';
import { getServerSession } from 'next-auth';
import { redirect } from 'next/navigation';
import { prisma } from '@/lib/prisma';
import AdminDashboard from '@/components/admin/AdminDashboard';

// CRITICAL: Force dynamic rendering because we use getServerSession()
export const dynamic = 'force-dynamic';
export const revalidate = 0;

async function getDashboardData() {
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const tomorrow = new Date(today);
  tomorrow.setDate(tomorrow.getDate() + 1);

  // Today's revenue
  const todayRevenue = await prisma.booking.aggregate({
    where: {
      paidAt: {
        gte: today,
        lt: tomorrow,
      },
      status: 'CONFIRMED', // Use booking status instead of paymentStatus
    },
    _sum: {
      totalGBP: true,
    },
  });

  // Active jobs
  const activeJobs = await prisma.booking.count({
    where: {
      status: {
        in: ['CONFIRMED'], // Use valid BookingStatus values
      },
    },
  });

  // Average ETA (simplified - would need actual calculation)
  const avgEta = '25 min';

  // First response time (simplified)
  const firstResponseTime = '3.2 min';

  // Open incidents
  const openIncidents = await prisma.driverIncident.count({
    where: {
      status: 'reported',
    },
  });

  // Jobs in progress with SLA timers
  const jobsInProgress = await prisma.booking.findMany({
    where: {
      status: {
        in: ['CONFIRMED'], // Use valid BookingStatus values
      },
    },
    include: {
      driver: {
        include: {
          User: {
            select: {
              id: true,
              name: true,
              email: true,
              role: true,
              createdAt: true,
              isActive: true,
              lastLogin: true,
              resetTokenExpiry: true,
              emailVerificationExpiry: true
            }
          },
        },
      },
    },
    orderBy: {
      createdAt: 'desc',
    },
    take: 5,
  });

  // New driver applications
  const newApplications = await prisma.driverApplication.count({
    where: {
      status: 'pending',
    },
  });

  // Get recent driver application notifications
  const recentDriverApplications = await prisma.adminNotification.findMany({
    where: {
      type: 'new_driver_application',
      isRead: false,
    },
    orderBy: {
      createdAt: 'desc',
    },
    take: 5,
  });

  // Get unread admin notifications count
  const unreadNotifications = await prisma.adminNotification.count({
    where: {
      isRead: false,
    },
  });

  // Get high priority notifications
  const highPriorityNotifications = await prisma.adminNotification.count({
    where: {
      priority: 'high',
      isRead: false,
    },
  });

  // Pending refunds
  const pendingRefunds = await prisma.booking.count({
    where: {
      status: 'CANCELLED', // Use booking status instead of paymentStatus
      updatedAt: {
        gte: new Date(Date.now() - 24 * 60 * 60 * 1000), // Last 24 hours
      },
    },
  });

  // System health check
  const dbHealth = 'healthy';
  const queueHealth = 'healthy';
  const pusherHealth = 'healthy';
  const stripeHealth = 'healthy';

  // Serialize data to ensure it can be passed to client components
  const serializedJobsInProgress = jobsInProgress.map(job => ({
    ...job,
    createdAt: job.createdAt.toISOString(),
    updatedAt: job.updatedAt.toISOString(),
    scheduledAt: job.scheduledAt.toISOString(),
    paidAt: job.paidAt?.toISOString(),
    driver: job.driver ? {
      ...job.driver,
      createdAt: job.driver.createdAt.toISOString(),
      updatedAt: job.driver.updatedAt.toISOString(),
      approvedAt: job.driver.approvedAt?.toISOString(),
      user: {
        ...job.driver.User,
        createdAt: job.driver.User.createdAt.toISOString(),
        lastLogin: job.driver.User.lastLogin?.toISOString(),
        resetTokenExpiry: job.driver.User.resetTokenExpiry?.toISOString(),
        emailVerificationExpiry: job.driver.User.emailVerificationExpiry?.toISOString(),
      },
    } : null,
  }));

  const serializedRecentDriverApplications = recentDriverApplications.map(notification => ({
    ...notification,
    createdAt: notification.createdAt.toISOString(),
    updatedAt: notification.updatedAt.toISOString(),
  }));

  return {
    todayRevenue: todayRevenue._sum.totalGBP || 0,
    activeJobs,
    avgEta,
    firstResponseTime,
    openIncidents,
    jobsInProgress: serializedJobsInProgress,
    newApplications,
    recentDriverApplications: serializedRecentDriverApplications,
    unreadNotifications,
    highPriorityNotifications,
    pendingRefunds,
    dbHealth,
    queueHealth,
    pusherHealth,
    stripeHealth,
  };
}

