  const [stats, setStats] = useState<PeopleStats | null>(null);
  const [drivers, setDrivers] = useState<Driver[]>([]);
  const [applications, setApplications] = useState<DriverApplication[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState(0);
  const toast = useToast();
  const router = useRouter();
  const bgColor = useColorModeValue('white', 'gray.800');

  const loadPeopleData = async (showLoading = true) => {
    try {
      if (showLoading) {
        setLoading(true);
      }
      
      // Load stats
      try {
        const statsResponse = await fetch('/api/admin/people/stats');
        if (statsResponse.ok) {
          const statsData = await statsResponse.json();
          setStats(statsData);
        }
      } catch (error) {
        console.error('Error loading stats:', error);
      }

      // Load drivers
      try {
        const driversResponse = await fetch('/api/admin/drivers?limit=10');
        if (driversResponse.ok) {
          const driversData = await driversResponse.json();
          setDrivers(Array.isArray(driversData) ? driversData : (driversData.drivers || []));
        }
      } catch (error) {
        console.error('Error loading drivers:', error);
        setDrivers([]);
      }

      // Load applications
      try {
        const applicationsResponse = await fetch('/api/admin/drivers/applications?limit=10');
        if (applicationsResponse.ok) {
          const applicationsData = await applicationsResponse.json();
          setApplications(Array.isArray(applicationsData) ? applicationsData : (applicationsData.applications || []));
        }
      } catch (error) {
        console.error('Error loading applications:', error);
        setApplications([]);
      }

      // Load customers
      try {
        const customersResponse = await fetch('/api/admin/customers?limit=10');
        if (customersResponse.ok) {
          const customersData = await customersResponse.json();
          setCustomers(Array.isArray(customersData) ? customersData : (customersData.customers || []));
        }
      } catch (error) {
        console.error('Error loading customers:', error);
        setCustomers([]);
      }

    } catch (error) {
      console.error('Error loading people data:', error);
      toast({
        title: 'Error',
        description: 'Failed to load people data',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadPeopleData();
  }, []);

  const getStatusColor = (status?: string) => {
    if (!status) return 'gray';
    
    switch (status.toLowerCase()) {
      case 'active':
      case 'approved':
      case 'online':
        return 'green';
      case 'pending':
      case 'under_review':
        return 'yellow';
      case 'inactive':
      case 'rejected':
      case 'offline':
        return 'red';
      case 'suspended':
        return 'orange';
      default:
        return 'gray';
    }
  };

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('en-GB');
  };

  if (loading) {
    return (
      <AdminShell title="People" subtitle="Manage drivers, applications, and customers">
        <Container maxW="7xl">
          <VStack spacing={8} align="center" py={12}>
            <Spinner size="xl" color="blue.500" />
            <Text>Loading people data...</Text>
          </VStack>
        </Container>
      </AdminShell>
    );
  }

  return (
    <AdminShell 
      title="People Management" 
      subtitle="Drivers, applications, and customers overview"
      actions={
        <HStack spacing={2}>
          <Tooltip label="Refresh data">
            <IconButton
              size="sm"
              variant="outline"
              icon={<FiRefreshCw />}
              onClick={() => loadPeopleData(true)}
              aria-label="Refresh"
            />
          </Tooltip>
        </HStack>
      }
    >
      <Container maxW="7xl">
        <VStack spacing={6} align="stretch">
          
          {/* Statistics Overview */}
          {stats && (
            <SimpleGrid columns={{ base: 1, md: 2, lg: 6 }} spacing={4}>
              <Card bg={bgColor}>
                <CardBody>
                  <Stat>
                    <StatLabel>Total Drivers</StatLabel>
                    <StatNumber color="blue.500">{stats.totalDrivers}</StatNumber>
                    <StatHelpText>
                      <FiTruck style={{ display: 'inline', marginRight: '4px' }} />
                      All drivers
                    </StatHelpText>
                  </Stat>
                </CardBody>
              </Card>

              <Card bg={bgColor}>
                <CardBody>
                  <Stat>
                    <StatLabel>Active Drivers</StatLabel>
                    <StatNumber color="green.500">{stats.activeDrivers}</StatNumber>
                    <StatHelpText>
                      <FiUserCheck style={{ display: 'inline', marginRight: '4px' }} />
                      Online now
                    </StatHelpText>
                  </Stat>
                </CardBody>
              </Card>

              <Card bg={bgColor}>
                <CardBody>
                  <Stat>
                    <StatLabel>Pending Applications</StatLabel>
                    <StatNumber color="yellow.500">{stats.pendingApplications}</StatNumber>
                    <StatHelpText>
                      <FiUserPlus style={{ display: 'inline', marginRight: '4px' }} />
                      Need review
                    </StatHelpText>
                  </Stat>
                </CardBody>
              </Card>

              <Card bg={bgColor}>
                <CardBody>
                  <Stat>
                    <StatLabel>Total Customers</StatLabel>
                    <StatNumber color="purple.500">{stats.totalCustomers}</StatNumber>
                    <StatHelpText>
                      <FiUsers style={{ display: 'inline', marginRight: '4px' }} />
                      All customers
                    </StatHelpText>
                  </Stat>
                </CardBody>
              </Card>

              <Card bg={bgColor}>
                <CardBody>
                  <Stat>
                    <StatLabel>Active Customers</StatLabel>
                    <StatNumber color="green.500">{stats.activeCustomers}</StatNumber>
                    <StatHelpText>
                      <FiUserCheck style={{ display: 'inline', marginRight: '4px' }} />
                      Recent bookings
                    </StatHelpText>
                  </Stat>
                </CardBody>
              </Card>

              <Card bg={bgColor}>
                <CardBody>
                  <Stat>
                    <StatLabel>New This Month</StatLabel>
                    <StatNumber color="blue.500">{stats.newCustomersThisMonth}</StatNumber>
                    <StatHelpText>
                      <FiUserPlus style={{ display: 'inline', marginRight: '4px' }} />
                      New customers
                    </StatHelpText>
                  </Stat>
                </CardBody>
              </Card>
            </SimpleGrid>
          )}

          {/* Tabs for Different People Categories */}
          <Card bg={bgColor}>
            <CardBody>
              <Tabs index={activeTab} onChange={setActiveTab} variant="enclosed">
                <TabList>
                  <Tab>
                    <HStack spacing={2}>
                      <FiTruck />
                      <Text>Drivers ({drivers.length})</Text>
                    </HStack>
                  </Tab>
                  <Tab>
                    <HStack spacing={2}>
                      <FiUserPlus />
                      <Text>Applications ({applications.length})</Text>
                    </HStack>
                  </Tab>
                  <Tab>
                    <HStack spacing={2}>
                      <FiUsers />
                      <Text>Customers ({customers.length})</Text>
                    </HStack>
                  </Tab>
                </TabList>

                <TabPanels>
                  {/* Drivers Tab */}
                  <TabPanel>
                    <VStack spacing={4} align="stretch">
                      <HStack justify="space-between">
                        <Heading size="md">Active Drivers</Heading>
                        <Button
                          size="sm"
                          colorScheme="blue"
                          onClick={() => router.push('/admin/drivers')}
                        >
                          View All Drivers
                        </Button>
                      </HStack>
                      
                      <Table variant="simple" size="sm">
                        <Thead>
                          <Tr>
                            <Th>Name</Th>
                            <Th>Email</Th>
                            <Th>Status</Th>
                            <Th>Jobs Completed</Th>
                            <Th>Rating</Th>
                            <Th>Last Seen</Th>
                            <Th>Actions</Th>
                          </Tr>
                        </Thead>
                        <Tbody>
                          {drivers.map((driver) => (
                            <Tr key={driver.id}>
                              <Td>
                                <HStack>
                                  <FiTruck />
                                  <Text fontWeight="medium">{driver.name}</Text>
                                </HStack>
                              </Td>
                              <Td>{driver.email}</Td>
                              <Td>
                                <Badge colorScheme={getStatusColor(driver.status)}>
                                  {driver.status || 'Unknown'}
                                </Badge>
                              </Td>
                              <Td>{driver.totalJobs || 0}</Td>
                              <Td>⭐ {(driver.rating || 0).toFixed(1)}/5</Td>
                              <Td>
                                <span suppressHydrationWarning>
                                  {driver.lastSeen ? formatDate(driver.lastSeen) : 'Never'}
                                </span>
                              </Td>
                              <Td>
                                <Menu>
                                  <MenuButton
                                    as={IconButton}
                                    icon={<FiMoreVertical />}
                                    variant="ghost"
                                    size="sm"
                                  />
                                  <MenuList>
                                    <MenuItem
                                      icon={<FiEye />}
                                      onClick={() => router.push(`/admin/drivers/${driver.id}`)}
                                    >
                                      View Details
                                    </MenuItem>
                                    <MenuItem
                                      icon={<FiEdit />}
                                      onClick={() => router.push(`/admin/drivers/${driver.id}?action=edit`)}
                                    >
                                      Edit Driver
                                    </MenuItem>
                                  </MenuList>
                                </Menu>
                              </Td>
                            </Tr>
                          ))}
                        </Tbody>
                      </Table>
                    </VStack>
                  </TabPanel>

                  {/* Applications Tab */}
                  <TabPanel>
                    <VStack spacing={4} align="stretch">
                      <HStack justify="space-between">
                        <Heading size="md">Driver Applications</Heading>
                        <Button
                          size="sm"
                          colorScheme="blue"
                          onClick={() => router.push('/admin/drivers/applications')}
                        >
                          View All Applications
                        </Button>
                      </HStack>
                      
                      <Table variant="simple" size="sm">
                        <Thead>
                          <Tr>
                            <Th>Name</Th>
                            <Th>Email</Th>
                            <Th>Phone</Th>
                            <Th>Status</Th>
                            <Th>Submitted</Th>
                            <Th>Reviewed By</Th>
                            <Th>Actions</Th>
                          </Tr>
                        </Thead>
                        <Tbody>
                          {applications.map((application) => (
                            <Tr key={application.id}>
                              <Td>
                                <HStack>
                                  <FiUserPlus />
                                  <Text fontWeight="medium">{application.name}</Text>
                                </HStack>
                              </Td>
                              <Td>{application.email}</Td>
                              <Td>{application.phone}</Td>
                              <Td>
                                <Badge colorScheme={getStatusColor(application.status)}>
                                  {application.status || 'Unknown'}
                                </Badge>
                              </Td>
                              <Td>
                                <span suppressHydrationWarning>
                                  {formatDate(application.submittedAt)}
                                </span>
                              </Td>
                              <Td>{application.reviewedBy || 'Pending'}</Td>
                              <Td>
                                <Menu>
                                  <MenuButton
                                    as={IconButton}
                                    icon={<FiMoreVertical />}
                                    variant="ghost"
                                    size="sm"
                                  />
                                  <MenuList>
                                    <MenuItem
                                      icon={<FiEye />}
                                      onClick={() => router.push(`/admin/drivers/applications/${application.id}`)}
                                    >
                                      Review Application
                                    </MenuItem>
                                  </MenuList>
                                </Menu>
                              </Td>
                            </Tr>
                          ))}
                        </Tbody>
                      </Table>
                    </VStack>
                  </TabPanel>

                  {/* Customers Tab */}
                  <TabPanel>
                    <VStack spacing={4} align="stretch">
                      <HStack justify="space-between">
                        <Heading size="md">Customers</Heading>
                        <Button
                          size="sm"
                          colorScheme="blue"
                          onClick={() => router.push('/admin/customers')}
                        >
                          View All Customers
                        </Button>
                      </HStack>
                      
                      <Table variant="simple" size="sm">
                        <Thead>
                          <Tr>
                            <Th>Name</Th>
                            <Th>Email</Th>
                            <Th>Total Bookings</Th>
                            <Th>Total Spent</Th>
                            <Th>Last Booking</Th>
                            <Th>Status</Th>
                            <Th>Actions</Th>
                          </Tr>
                        </Thead>
                        <Tbody>
                          {customers.map((customer) => (
                            <Tr key={customer.id}>
                              <Td>
                                <HStack>
                                  <FiUsers />
                                  <Text fontWeight="medium">{customer.name}</Text>
                                </HStack>
                              </Td>
                              <Td>{customer.email}</Td>
                              <Td>{customer.totalBookings || 0}</Td>
                              <Td>£{(customer.totalSpent || 0).toFixed(2)}</Td>
                              <Td>
                                <span suppressHydrationWarning>
                                  {customer.lastBooking ? formatDate(customer.lastBooking) : 'Never'}
                                </span>
                              </Td>
                              <Td>
                                <Badge colorScheme={getStatusColor(customer.status)}>
                                  {customer.status || 'Unknown'}
                                </Badge>
                              </Td>
                              <Td>
                                <Menu>
                                  <MenuButton
                                    as={IconButton}
                                    icon={<FiMoreVertical />}
                                    variant="ghost"
                                    size="sm"
                                  />
                                  <MenuList>
                                    <MenuItem
                                      icon={<FiEye />}
                                      onClick={() => router.push(`/admin/customers/${customer.id}`)}
                                    >
                                      View Profile
                                    </MenuItem>
                                    <MenuItem
                                      icon={<FiMail />}
                                      onClick={() => window.open(`mailto:${customer.email}`)}
                                    >
                                      Send Email
                                    </MenuItem>
                                  </MenuList>
                                </Menu>
                              </Td>
                            </Tr>
                          ))}
                        </Tbody>
                      </Table>
                    </VStack>
                  </TabPanel>
                </TabPanels>
              </Tabs>
            </CardBody>
          </Card>

          {/* Quick Actions */}
          <SimpleGrid columns={{ base: 1, md: 3 }} spacing={4}>
            <Card bg={bgColor}>
              <CardBody>
                <VStack spacing={4}>
                  <FiTruck size={24} color="blue" />
                  <Heading size="sm">Manage Drivers</Heading>
                  <Text fontSize="sm" color="gray.600" textAlign="center">
                    View, edit, and manage all registered drivers
                  </Text>
                  <Button
                    size="sm"
                    colorScheme="blue"
                    onClick={() => router.push('/admin/drivers')}
                  >
                    Go to Drivers
                  </Button>
                </VStack>
              </CardBody>
            </Card>

            <Card bg={bgColor}>
              <CardBody>
                <VStack spacing={4}>
                  <FiUserPlus size={24} color="orange" />
                  <Heading size="sm">Review Applications</Heading>
                  <Text fontSize="sm" color="gray.600" textAlign="center">
                    Review and approve new driver applications
                  </Text>
                  <Button
                    size="sm"
                    colorScheme="orange"
                    onClick={() => router.push('/admin/drivers/applications')}
                  >
                    Review Applications
                  </Button>
                </VStack>
              </CardBody>
            </Card>

            <Card bg={bgColor}>
              <CardBody>
                <VStack spacing={4}>
                  <FiUsers size={24} color="purple" />
                  <Heading size="sm">Manage Customers</Heading>
                  <Text fontSize="sm" color="gray.600" textAlign="center">
                    View customer profiles and booking history
                  </Text>
                  <Button
                    size="sm"
                    colorScheme="purple"
                    onClick={() => router.push('/admin/customers')}
                  >
                    Go to Customers
                  </Button>
                </VStack>
              </CardBody>
            </Card>
          </SimpleGrid>
        </VStack>
      </Container>
    </AdminShell>
  );
}

'use client';

import { useEffect, useState } from 'react';
import { useParams, useRouter } from 'next/navigation';
import {
  Box,
  Container,
  Heading,
  Text,
  Button,
  VStack,
  HStack,
  Card,
  CardBody,
  Grid,
  Badge,
  Divider,
  Alert,
  AlertIcon,
  useToast,
  Spinner,
  Icon,
  Table,
  Thead,
  Tbody,
  Tr,
  Th,
  Td,
  Modal,
  ModalOverlay,
  ModalContent,
  ModalHeader,
  ModalBody,
  ModalFooter,
  ModalCloseButton,
  useDisclosure,
  FormControl,
  FormLabel,
  Input,
  Select,
  Textarea,
  Tabs,
  TabList,
  TabPanels,
  Tab,
  TabPanel,
  Menu,
  MenuButton,
  MenuList,
  MenuItem,
  Switch,
  Progress,
  Stat,
  StatLabel,
  StatNumber,
  StatHelpText,
  StatArrow,
} from '@chakra-ui/react';
import {
  FiArrowLeft,
  FiEdit,
  FiTrash2,
  FiUser,
  FiMapPin,
  FiClock,
  FiTruck,
  FiCheck,
  FiX,
  FiMoreVertical,
  FiRefreshCw,
  FiAlertCircle,
  FiBarChart2,
  FiSettings,
} from 'react-icons/fi';
import AdminShell from '@/components/admin/AdminShell';

interface Drop {
  id: string;
  pickupAddress: string;
  deliveryAddress: string;
  status: string;
  quotedPrice: number;
  timeWindowStart: string;
  timeWindowEnd: string;
  completedAt?: string;
  Booking?: {
    id: string;
    reference: string;
    customerName: string;
    customerPhone: string;
  };
  User: {
    name: string;
    email: string;
  };
}

interface RouteDetails {
  id: string;
  reference: string;
  status: string;
  serviceTier: string;
  startTime: string;
  endTime?: string;
  totalDrops: number;
  completedDrops: number;
  optimizedDistanceKm?: number;
  estimatedDuration?: number;
  routeNotes?: string;
  adminNotes?: string;
  isModifiedByAdmin: boolean;
  driver?: {
    id: string;
    name: string;
    email: string;
    phone?: string;
  };
  drops: Drop[];
  createdAt: string;
  updatedAt: string;
}

interface Analytics {
  performanceMetrics: any;
  costAnalysis: any;
  efficiencyScores: any;
  suggestions: any[];
}

export default function RouteDetailsPage() {
  const params = useParams();
  const router = useRouter();
  const toast = useToast();
  const routeId = params?.id as string;
  
  const [route, setRoute] = useState<RouteDetails | null>(null);
  const [analytics, setAnalytics] = useState<Analytics | null>(null);
  const [loading, setLoading] = useState(true);
  const [loadingAnalytics, setLoadingAnalytics] = useState(false);
  const [actionLoading, setActionLoading] = useState(false);

  // Modals
  const { isOpen: isStatusModalOpen, onOpen: onStatusModalOpen, onClose: onStatusModalClose } = useDisclosure();
  const { isOpen: isDriverModalOpen, onOpen: onDriverModalOpen, onClose: onDriverModalClose } = useDisclosure();
  const { isOpen: isDeleteModalOpen, onOpen: onDeleteModalOpen, onClose: onDeleteModalClose } = useDisclosure();

  // Form states
  const [newStatus, setNewStatus] = useState('');
  const [statusReason, setStatusReason] = useState('');
  const [selectedDriver, setSelectedDriver] = useState('');
  const [drivers, setDrivers] = useState<any[]>([]);
  const [deleteReason, setDeleteReason] = useState('');

  useEffect(() => {
    loadRouteDetails();
    loadDrivers();
  }, [routeId]);

  const loadRouteDetails = async () => {
    try {
      setLoading(true);
      const response = await fetch(`/api/admin/routes/${routeId}/details`);
      
      if (!response.ok) {
        throw new Error('Failed to load route details');
      }
      
      const data = await response.json();
      setRoute(data);
    } catch (error) {
      console.error('Error loading route details:', error);
      toast({
        title: 'Error',
        description: 'Failed to load route details',
        status: 'error',
        duration: 3000,
      });
    } finally {
      setLoading(false);
    }
  };

  const loadAnalytics = async () => {
    try {
      setLoadingAnalytics(true);
      const response = await fetch(`/api/admin/routes/${routeId}/analytics`);
      
      if (!response.ok) {
        throw new Error('Failed to load analytics');
      }
      
      const result = await response.json();
      setAnalytics(result.data);
    } catch (error) {
      console.error('Error loading analytics:', error);
      toast({
        title: 'Error',
        description: 'Failed to load analytics',
        status: 'error',
        duration: 3000,
      });
    } finally {
      setLoadingAnalytics(false);
    }
  };

  const loadDrivers = async () => {
    try {
      const response = await fetch('/api/admin/drivers/available');
      const result = await response.json();
      
      console.log('Drivers API response:', result);
      
      if (result.success && result.data) {
        // API returns drivers in result.data.drivers
        setDrivers(result.data.drivers || []);
        console.log('Loaded drivers:', result.data.drivers?.length || 0);
      } else {
        console.error('Invalid drivers response:', result);
        setDrivers([]);
      }
    } catch (error) {
      console.error('Error loading drivers:', error);
      setDrivers([]);
    }
  };

  const handleForceStatusChange = async () => {
    if (!newStatus || !statusReason) {
      toast({
        title: 'Validation Error',
        description: 'Status and reason are required',
        status: 'warning',
        duration: 3000,
      });
      return;
    }

    try {
      setActionLoading(true);
      const response = await fetch(`/api/admin/routes/${routeId}/force-status`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          status: newStatus,
          reason: statusReason,
          updateDrops: true,
        }),
      });

      const data = await response.json();

      if (data.success) {
        toast({
          title: 'Success',
          description: `Route status changed to ${newStatus}`,
          status: 'success',
          duration: 3000,
        });
        onStatusModalClose();
        loadRouteDetails();
      } else {
        throw new Error(data.error || 'Failed to change status');
      }
    } catch (error: any) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to change status',
        status: 'error',
        duration: 5000,
      });
    } finally {
      setActionLoading(false);
    }
  };

  const handleReassignDriver = async () => {
    if (!selectedDriver) {
      toast({
        title: 'Validation Error',
        description: 'Please select a driver',
        status: 'warning',
        duration: 3000,
      });
      return;
    }

    try {
      setActionLoading(true);
      const response = await fetch(`/api/admin/routes/${routeId}/reassign`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          driverId: selectedDriver,
          reason: 'Admin reassignment from route details',
        }),
      });

      const data = await response.json();

      if (data.success) {
        toast({
          title: 'Success',
          description: 'Driver reassigned successfully',
          status: 'success',
          duration: 3000,
        });
        onDriverModalClose();
        loadRouteDetails();
      } else {
        throw new Error(data.error || 'Failed to reassign driver');
      }
    } catch (error: any) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to reassign driver',
        status: 'error',
        duration: 5000,
      });
    } finally {
      setActionLoading(false);
    }
  };

  const handleDeleteRoute = async () => {
    if (!deleteReason) {
      toast({
        title: 'Validation Error',
        description: 'Please provide a reason for deletion',
        status: 'warning',
        duration: 3000,
      });
      return;
    }

    try {
      setActionLoading(true);
      const response = await fetch(
        `/api/admin/routes/multi-drop?routeId=${routeId}&reason=${encodeURIComponent(deleteReason)}`,
        {
          method: 'DELETE',
        }
      );

      const data = await response.json();

      if (data.success) {
        toast({
          title: 'Success',
          description: 'Route cancelled successfully',
          status: 'success',
          duration: 3000,
        });
        router.push('/admin/routes');
      } else {
        throw new Error(data.error || 'Failed to delete route');
      }
    } catch (error: any) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to delete route',
        status: 'error',
        duration: 5000,
      });
    } finally {
      setActionLoading(false);
    }
  };

  const getStatusColor = (status: string) => {
    const colors: Record<string, string> = {
      planned: 'blue',
      pending_assignment: 'yellow',
      assigned: 'orange',
      active: 'green',
      completed: 'gray',
      cancelled: 'red',
      failed: 'red',
    };
    return colors[status] || 'gray';
  };

  const getDropStatusColor = (status: string) => {
    const colors: Record<string, string> = {
      pending: 'gray',
      assigned_to_route: 'blue',
      picked_up: 'orange',
      in_transit: 'green',
      delivered: 'green',
      failed: 'red',
    };
    return colors[status] || 'gray';
  };

  if (loading) {
    return (
      <AdminShell title="Route Details">
        <Box
          minH="100vh"
          display="flex"
          alignItems="center"
          justifyContent="center"
        >
          <VStack spacing={4}>
            <Spinner size="xl" color="blue.500" />
            <Text>Loading route details...</Text>
          </VStack>
        </Box>
      </AdminShell>
    );
  }

  if (!route) {
    return (
      <AdminShell title="Route Not Found">
        <Box
          minH="100vh"
          display="flex"
          alignItems="center"
          justifyContent="center"
        >
          <VStack spacing={4}>
            <Icon as={FiAlertCircle} boxSize={12} color="red.500" />
            <Heading size="lg">Route Not Found</Heading>
            <Button
              leftIcon={<FiArrowLeft />}
              colorScheme="blue"
              onClick={() => router.push('/admin/routes')}
            >
              Back to Routes
            </Button>
          </VStack>
        </Box>
      </AdminShell>
    );
  }

  const completionRate = route.totalDrops > 0 
    ? (route.completedDrops / route.totalDrops) * 100 
    : 0;

  return (
    <AdminShell title={`Route ${route.reference}`}>
      <Container maxW="container.xl" py={8}>
        <VStack spacing={6} align="stretch">
          {/* Header */}
          <HStack justify="space-between">
            <HStack spacing={4}>
              <Button
                leftIcon={<FiArrowLeft />}
                variant="ghost"
                onClick={() => router.push('/admin/routes')}
              >
                Back
              </Button>
              <Box>
                <Heading size="lg">Route {route.reference}</Heading>
                <Text color="gray.600" fontSize="sm">
                  Created {new Date(route.createdAt).toLocaleString()}
                </Text>
              </Box>
            </HStack>
            <Menu>
              <MenuButton
                as={Button}
                rightIcon={<FiMoreVertical />}
                variant="outline"
              >
                Actions
              </MenuButton>
              <MenuList>
                <MenuItem icon={<FiSettings />} onClick={onStatusModalOpen}>
                  Force Change Status
                </MenuItem>
                <MenuItem icon={<FiUser />} onClick={onDriverModalOpen}>
                  Reassign Driver
                </MenuItem>
                <MenuItem icon={<FiRefreshCw />} onClick={loadRouteDetails}>
                  Refresh Data
                </MenuItem>
                <MenuItem icon={<FiBarChart2 />} onClick={loadAnalytics}>
                  Load Analytics
                </MenuItem>
                <Divider />
                <MenuItem icon={<FiTrash2 />} onClick={onDeleteModalOpen} color="red.500">
                  Cancel Route
                </MenuItem>
              </MenuList>
            </Menu>
          </HStack>

          {/* Admin Modified Alert */}
          {route.isModifiedByAdmin && (
            <Alert status="info">
              <AlertIcon />
              This route has been modified by admin
            </Alert>
          )}

          {/* Status and Progress */}
          <Card>
            <CardBody>
              <Grid templateColumns="repeat(auto-fit, minmax(200px, 1fr))" gap={4}>
                <Box>
                  <Text fontSize="sm" color="gray.600">Status</Text>
                  <Badge colorScheme={getStatusColor(route.status)} fontSize="md" mt={1}>
                    {route.status.replace(/_/g, ' ').toUpperCase()}
                  </Badge>
                </Box>
                <Box>
                  <Text fontSize="sm" color="gray.600">Service Tier</Text>
                  <Text fontSize="lg" fontWeight="bold">{route.serviceTier}</Text>
                </Box>
                <Box>
                  <Text fontSize="sm" color="gray.600">Completion</Text>
                  <HStack>
                    <Progress value={completionRate} size="sm" colorScheme="green" flex={1} />
                    <Text fontSize="sm" fontWeight="bold">{Math.round(completionRate)}%</Text>
                  </HStack>
                  <Text fontSize="xs" color="gray.500">
                    {route.completedDrops} of {route.totalDrops} drops
                  </Text>
                </Box>
                <Box>
                  <Text fontSize="sm" color="gray.600">Distance</Text>
                  <Text fontSize="lg" fontWeight="bold">
                    {route.optimizedDistanceKm?.toFixed(1) || 'N/A'} km
                  </Text>
                </Box>
              </Grid>
            </CardBody>
          </Card>

          {/* Driver Info */}
          <Card>
            <CardBody>
              <HStack justify="space-between" mb={4}>
                <Heading size="md">Driver Information</Heading>
                <Button
                  size="sm"
                  leftIcon={<FiEdit />}
                  onClick={onDriverModalOpen}
                >
                  Change Driver
                </Button>
              </HStack>
              {route.driver ? (
                <Grid templateColumns="repeat(auto-fit, minmax(200px, 1fr))" gap={4}>
                  <Box>
                    <Text fontSize="sm" color="gray.600">Name</Text>
                    <Text fontSize="lg" fontWeight="bold">{route.driver.name}</Text>
                  </Box>
                  <Box>
                    <Text fontSize="sm" color="gray.600">Email</Text>
                    <Text fontSize="md">{route.driver.email}</Text>
                  </Box>
                  <Box>
                    <Text fontSize="sm" color="gray.600">Phone</Text>
                    <Text fontSize="md">{route.driver.phone || 'N/A'}</Text>
                  </Box>
                </Grid>
              ) : (
                <Alert status="warning">
                  <AlertIcon />
                  No driver assigned to this route
                </Alert>
              )}
            </CardBody>
          </Card>

          {/* Tabs */}
          <Tabs>
            <TabList>
              <Tab>Drops ({route.drops.length})</Tab>
              <Tab>Timeline</Tab>
              <Tab>Notes</Tab>
              {analytics && <Tab>Analytics</Tab>}
            </TabList>

            <TabPanels>
              {/* Drops Tab */}
              <TabPanel>
                <VStack spacing={4} align="stretch">
                  {route.drops.map((drop, index) => (
                    <Card key={drop.id}>
                      <CardBody>
                        <HStack justify="space-between" mb={3}>
                          <HStack>
                            <Box
                              w={8}
                              h={8}
                              borderRadius="full"
                              bg="blue.500"
                              color="white"
                              display="flex"
                              alignItems="center"
                              justifyContent="center"
                              fontWeight="bold"
                            >
                              {index + 1}
                            </Box>
                            <Box>
                              <Text fontWeight="bold">
                                {drop.Booking?.reference || `Drop ${index + 1}`}
                              </Text>
                              <Badge colorScheme={getDropStatusColor(drop.status)}>
                                {drop.status.replace(/_/g, ' ')}
                              </Badge>
                            </Box>
                          </HStack>
                          <Text fontWeight="bold" fontSize="lg">
                            £{(drop.quotedPrice / 100).toFixed(2)}
                          </Text>
                        </HStack>

                        <Grid templateColumns="repeat(auto-fit, minmax(250px, 1fr))" gap={4}>
                          <Box>
                            <Text fontSize="sm" color="gray.600">Customer</Text>
                            <Text fontWeight="medium">{drop.User.name}</Text>
                            <Text fontSize="sm" color="gray.500">{drop.User.email}</Text>
                          </Box>
                          <Box>
                            <Text fontSize="sm" color="gray.600">Pickup</Text>
                            <Text fontWeight="medium">{drop.pickupAddress}</Text>
                          </Box>
                          <Box>
                            <Text fontSize="sm" color="gray.600">Delivery</Text>
                            <Text fontWeight="medium">{drop.deliveryAddress}</Text>
                          </Box>
                          <Box>
                            <Text fontSize="sm" color="gray.600">Time Window</Text>
                            <Text fontSize="sm">
                              {new Date(drop.timeWindowStart).toLocaleTimeString()} - 
                              {new Date(drop.timeWindowEnd).toLocaleTimeString()}
                            </Text>
                          </Box>
                        </Grid>

                        {drop.completedAt && (
                          <Box mt={3} p={2} bg="green.50" borderRadius="md">
                            <Text fontSize="sm" color="green.700">
                              <Icon as={FiCheck} mr={1} />
                              Completed at {new Date(drop.completedAt).toLocaleString()}
                            </Text>
                          </Box>
                        )}
                      </CardBody>
                    </Card>
                  ))}
                </VStack>
              </TabPanel>

              {/* Timeline Tab */}
              <TabPanel>
                <VStack spacing={4} align="stretch">
                  <Box p={4} borderLeft="2px" borderColor="blue.500">
                    <Text fontSize="sm" color="gray.600">Created</Text>
                    <Text fontWeight="bold">{new Date(route.createdAt).toLocaleString()}</Text>
                  </Box>
                  <Box p={4} borderLeft="2px" borderColor="green.500">
                    <Text fontSize="sm" color="gray.600">Scheduled Start</Text>
                    <Text fontWeight="bold">{new Date(route.startTime).toLocaleString()}</Text>
                  </Box>
                  {route.endTime && (
                    <Box p={4} borderLeft="2px" borderColor="gray.500">
                      <Text fontSize="sm" color="gray.600">Completed</Text>
                      <Text fontWeight="bold">{new Date(route.endTime).toLocaleString()}</Text>
                    </Box>
                  )}
                </VStack>
              </TabPanel>

              {/* Notes Tab */}
              <TabPanel>
                <VStack spacing={4} align="stretch">
                  {route.routeNotes && (
                    <Box>
                      <Text fontSize="sm" color="gray.600" mb={2}>Route Notes</Text>
                      <Box p={4} bg="gray.50" borderRadius="md">
                        <Text>{route.routeNotes}</Text>
                      </Box>
                    </Box>
                  )}
                  {route.adminNotes && (
                    <Box>
                      <Text fontSize="sm" color="gray.600" mb={2}>Admin Notes</Text>
                      <Box p={4} bg="blue.50" borderRadius="md">
                        <Text whiteSpace="pre-wrap">{route.adminNotes}</Text>
                      </Box>
                    </Box>
                  )}
                </VStack>
              </TabPanel>

              {/* Analytics Tab */}
              {analytics && (
                <TabPanel>
                  {loadingAnalytics ? (
                    <Box textAlign="center" py={8}>
                      <Spinner size="lg" />
                    </Box>
                  ) : (
                    <VStack spacing={6} align="stretch">
                      {/* Performance Metrics */}
                      <Card>
                        <CardBody>
                          <Heading size="md" mb={4}>Performance Metrics</Heading>
                          <Grid templateColumns="repeat(auto-fit, minmax(200px, 1fr))" gap={4}>
                            <Stat>
                              <StatLabel>Completion Rate</StatLabel>
                              <StatNumber>{analytics.performanceMetrics.completionRate}%</StatNumber>
                            </Stat>
                            <Stat>
                              <StatLabel>On-Time Rate</StatLabel>
                              <StatNumber>{analytics.performanceMetrics.onTimeRate}%</StatNumber>
                            </Stat>
                            <Stat>
                              <StatLabel>Average Delay</StatLabel>
                              <StatNumber>{analytics.performanceMetrics.averageDelay} min</StatNumber>
                            </Stat>
                          </Grid>
                        </CardBody>
                      </Card>

                      {/* Efficiency Scores */}
                      <Card>
                        <CardBody>
                          <Heading size="md" mb={4}>Efficiency Scores</Heading>
                          <Grid templateColumns="repeat(auto-fit, minmax(200px, 1fr))" gap={4}>
                            <Stat>
                              <StatLabel>Overall</StatLabel>
                              <StatNumber>{analytics.efficiencyScores.overall}%</StatNumber>
                              <StatHelpText>{analytics.efficiencyScores.rating}</StatHelpText>
                            </Stat>
                            <Stat>
                              <StatLabel>Distance</StatLabel>
                              <StatNumber>{analytics.efficiencyScores.distance}%</StatNumber>
                            </Stat>
                            <Stat>
                              <StatLabel>Time</StatLabel>
                              <StatNumber>{analytics.efficiencyScores.time}%</StatNumber>
                            </Stat>
                          </Grid>
                        </CardBody>
                      </Card>

                      {/* Suggestions */}
                      {analytics.suggestions.length > 0 && (
                        <Card>
                          <CardBody>
                            <Heading size="md" mb={4}>Optimization Suggestions</Heading>
                            <VStack spacing={3} align="stretch">
                              {analytics.suggestions.map((suggestion: any, index: number) => (
                                <Alert
                                  key={index}
                                  status={suggestion.priority === 'high' ? 'warning' : 'info'}
                                >
                                  <AlertIcon />
                                  <Box flex={1}>
                                    <Text fontWeight="bold">{suggestion.message}</Text>
                                    <Text fontSize="sm" color="gray.600">{suggestion.impact}</Text>
                                  </Box>
                                </Alert>
                              ))}
                            </VStack>
                          </CardBody>
                        </Card>
                      )}
                    </VStack>
                  )}
                </TabPanel>
              )}
            </TabPanels>
          </Tabs>
        </VStack>
      </Container>

      {/* Force Status Change Modal */}
      <Modal isOpen={isStatusModalOpen} onClose={onStatusModalClose}>
        <ModalOverlay />
        <ModalContent>
          <ModalHeader>Force Change Status</ModalHeader>
          <ModalCloseButton />
          <ModalBody>
            <VStack spacing={4}>
              <Alert status="warning">
                <AlertIcon />
                This will bypass all validation rules
              </Alert>
              <FormControl isRequired>
                <FormLabel>New Status</FormLabel>
                <Select
                  value={newStatus}
                  onChange={(e) => setNewStatus(e.target.value)}
                  placeholder="Select status"
                >
                  <option value="planned">Planned</option>
                  <option value="pending_assignment">Pending Assignment</option>
                  <option value="assigned">Assigned</option>
                  <option value="active">Active</option>
                  <option value="completed">Completed</option>
                  <option value="cancelled">Cancelled</option>
                  <option value="failed">Failed</option>
                </Select>
              </FormControl>
              <FormControl isRequired>
                <FormLabel>Reason</FormLabel>
                <Textarea
                  value={statusReason}
                  onChange={(e) => setStatusReason(e.target.value)}
                  placeholder="Explain why you're forcing this status change"
                />
              </FormControl>
            </VStack>
          </ModalBody>
          <ModalFooter>
            <Button variant="ghost" mr={3} onClick={onStatusModalClose}>
              Cancel
            </Button>
            <Button
              colorScheme="blue"
              onClick={handleForceStatusChange}
              isLoading={actionLoading}
            >
              Change Status
            </Button>
          </ModalFooter>
        </ModalContent>
      </Modal>

      {/* Reassign Driver Modal */}
      <Modal isOpen={isDriverModalOpen} onClose={onDriverModalClose}>
        <ModalOverlay />
        <ModalContent>
          <ModalHeader>Reassign Driver</ModalHeader>
          <ModalCloseButton />
          <ModalBody>
            <FormControl isRequired>
              <FormLabel>Select Driver</FormLabel>
              <Select
                value={selectedDriver}
                onChange={(e) => setSelectedDriver(e.target.value)}
                placeholder="Select driver"
              >
                {drivers.map((driver) => (
                  <option key={driver.id} value={driver.id}>
                    {driver.name} - {driver.email}
                  </option>
                ))}
              </Select>
            </FormControl>
          </ModalBody>
          <ModalFooter>
            <Button variant="ghost" mr={3} onClick={onDriverModalClose}>
              Cancel
            </Button>
            <Button
              colorScheme="blue"
              onClick={handleReassignDriver}
              isLoading={actionLoading}
            >
              Reassign
            </Button>
          </ModalFooter>
        </ModalContent>
      </Modal>

      {/* Delete Route Modal */}
      <Modal isOpen={isDeleteModalOpen} onClose={onDeleteModalClose}>
        <ModalOverlay />
        <ModalContent>
          <ModalHeader>Cancel Route</ModalHeader>
          <ModalCloseButton />
          <ModalBody>
            <VStack spacing={4}>
              <Alert status="error">
                <AlertIcon />
                This will cancel the route and mark all drops as failed
              </Alert>
              <FormControl isRequired>
                <FormLabel>Reason for Cancellation</FormLabel>
                <Textarea
                  value={deleteReason}
                  onChange={(e) => setDeleteReason(e.target.value)}
                  placeholder="Explain why you're cancelling this route"
                />
              </FormControl>
            </VStack>
          </ModalBody>
          <ModalFooter>
            <Button variant="ghost" mr={3} onClick={onDeleteModalClose}>
              Cancel
            </Button>
            <Button
              colorScheme="red"
              onClick={handleDeleteRoute}
              isLoading={actionLoading}
            >
              Cancel Route
            </Button>
          </ModalFooter>
        </ModalContent>
      </Modal>
    </AdminShell>
  );
}

/**
 * Manual Route Creation Page
 * Allow admins to manually create routes by selecting bookings
 */

'use client';

import React, { useState, useEffect } from 'react';
import {
  Box,
  Container,
  Heading,
  Text,
  Button,
  VStack,
  HStack,
  Card,
  CardBody,
  Grid,
  Badge,
  Checkbox,
  FormControl,
  FormLabel,
  Input,
  Select,
  Divider,
  Alert,
  AlertIcon,
  useToast,
  Spinner,
  Icon,
  Table,
  Thead,
  Tbody,
  Tr,
  Th,
  Td,
} from '@chakra-ui/react';
import {
  FiPackage,
  FiMapPin,
  FiClock,
  FiTruck,
  FiCheck,
  FiArrowLeft,
} from 'react-icons/fi';
import { useRouter } from 'next/navigation';
import { AdminShell } from '@/components/admin';

interface Booking {
  id: string;
  reference: string;
  customerName: string;
  pickupAddress: string;
  dropoffAddress: string;
  scheduledAt: Date;
  totalGBP: number;
  serviceTier: string;
  status: string;
  pickupLat?: number;
  pickupLng?: number;
  dropoffLat?: number;
  dropoffLng?: number;
  distance?: number; // Distance between pickup and dropoff in km
}

interface Driver {
  id: string;
  name: string;
  status: string;
}

export default function CreateRoutePage() {
  const router = useRouter();
  const toast = useToast();

  const [bookings, setBookings] = useState<Booking[]>([]);
  const [drivers, setDrivers] = useState<Driver[]>([]);
  const [selectedBookings, setSelectedBookings] = useState<string[]>([]);
  const [selectedDriver, setSelectedDriver] = useState('');
  const [isLoading, setIsLoading] = useState(true);
  const [isCreating, setIsCreating] = useState(false);
  const [isSuggestingRoute, setIsSuggestingRoute] = useState(false);

  // Haversine formula to calculate distance between two points in miles
  const calculateDistance = (lat1: number, lon1: number, lat2: number, lon2: number): number => { // DEPRECATED - internal use only
    const R = 3958.8; // Earth's radius in miles (changed from 6371 km)
    const dLat = (lat2 - lat1) * Math.PI / 180;
    const dLon = (lon2 - lon1) * Math.PI / 180;
    const a = 
      Math.sin(dLat / 2) * Math.sin(dLat / 2) +
      Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) *
      Math.sin(dLon / 2) * Math.sin(dLon / 2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
    return R * c;
  };

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    setIsLoading(true);
    try {
      const [bookingsRes, driversRes] = await Promise.all([
        fetch('/api/admin/routes/pending-drops'),
        fetch('/api/admin/drivers/available'),
      ]);

      if (!bookingsRes.ok) {
        throw new Error(`Bookings API failed: ${bookingsRes.status} ${bookingsRes.statusText}`);
      }
      if (!driversRes.ok) {
        throw new Error(`Drivers API failed: ${driversRes.status} ${driversRes.statusText}`);
      }

      const bookingsData = await bookingsRes.json();
      const driversData = await driversRes.json();

      if (bookingsData && bookingsData.success) {
        setBookings(bookingsData.drops || []);
      } else {
        console.error('❌ Bookings API failed:', bookingsData);
        setBookings([]);
      }

      if (driversData && driversData.success && driversData.data) {
        setDrivers(driversData.data.drivers || []);
      } else {
        console.error('❌ Drivers API failed:', driversData);
        setDrivers([]);
      }
    } catch (error) {
      console.error('Failed to load data:', error);
      toast({
        title: 'Error',
        description: 'Failed to load bookings and drivers',
        status: 'error',
        duration: 3000,
      });
    } finally {
      setIsLoading(false);
    }
  };

  const handleToggleBooking = (bookingId: string) => {
    setSelectedBookings(prev =>
      prev.includes(bookingId)
        ? prev.filter(id => id !== bookingId)
        : [...prev, bookingId]
    );
  };

  const handleSelectAll = () => {
    if (selectedBookings.length === (bookings?.length || 0)) {
      setSelectedBookings([]);
    } else {
      setSelectedBookings(bookings?.map(b => b.id) || []);
    }
  };

  // Smart Route Suggestion using Nearest Neighbor algorithm
  const handleSuggestSmartRoute = () => {
    if (selectedBookings.length < 2) {
      toast({
        title: 'Not Enough Bookings',
        description: 'Please select at least 2 bookings for route optimization',
        status: 'warning',
        duration: 3000,
      });
      return;
    }

    setIsSuggestingRoute(true);

    try {
      const selectedBookingsData = bookings?.filter(b => selectedBookings.includes(b.id)) || [];
      
      // Check if all bookings have coordinates
      const hasCoordinates = selectedBookingsData.every(b => 
        b.pickupLat && b.pickupLng && b.dropoffLat && b.dropoffLng
      );

      if (!hasCoordinates) {
        toast({
          title: 'Missing Location Data',
          description: 'Some bookings are missing coordinates. Using time-based ordering.',
          status: 'info',
          duration: 4000,
        });
        
        // Fallback: sort by scheduled time
        const sortedByTime = selectedBookingsData.sort((a, b) => 
          new Date(a.scheduledAt).getTime() - new Date(b.scheduledAt).getTime()
        );
        setSelectedBookings(sortedByTime.map(b => b.id));
        return;
      }

      // Nearest Neighbor algorithm for route optimization
      const optimizedRoute: string[] = [];
      const remaining = [...selectedBookingsData];
      
      // Start with the booking that has earliest scheduled time
      const startBooking = remaining.reduce((earliest, current) => 
        new Date(current.scheduledAt) < new Date(earliest.scheduledAt) ? current : earliest
      );
      
      optimizedRoute.push(startBooking.id);
      remaining.splice(remaining.indexOf(startBooking), 1);
      
      let currentLat = startBooking.dropoffLat!;
      let currentLng = startBooking.dropoffLng!;
      
      // Find nearest neighbor for each subsequent stop
      while (remaining.length > 0) {
        let nearestIndex = 0;
        let nearestDistance = Infinity;
        
        remaining.forEach((booking, index) => {
          const distance = calculateDistance( // DEPRECATED - internal use only
            currentLat,
            currentLng,
            booking.pickupLat!,
            booking.pickupLng!
          );
          
          if (distance < nearestDistance) {
            nearestDistance = distance;
            nearestIndex = index;
          }
        });
        
        const nearestBooking = remaining[nearestIndex];
        optimizedRoute.push(nearestBooking.id);
        currentLat = nearestBooking.dropoffLat!;
        currentLng = nearestBooking.dropoffLng!;
        remaining.splice(nearestIndex, 1);
      }
      
      setSelectedBookings(optimizedRoute);
      
      // Calculate total distance
      let totalDistance = 0;
      for (let i = 0; i < optimizedRoute.length - 1; i++) {
        const current = selectedBookingsData.find(b => b.id === optimizedRoute[i])!;
        const next = selectedBookingsData.find(b => b.id === optimizedRoute[i + 1])!;
        totalDistance += calculateDistance( // DEPRECATED - internal use only
          current.dropoffLat!,
          current.dropoffLng!,
          next.pickupLat!,
          next.pickupLng!
        );
      }
      
      toast({
        title: 'Route Optimized!',
        description: `Suggested route order with total distance: ${totalDistance.toFixed(1)} miles`,
        status: 'success',
        duration: 5000,
      });
      
    } catch (error) {
      console.error('Route suggestion error:', error);
      toast({
        title: 'Optimization Failed',
        description: 'Could not optimize route. Using current selection order.',
        status: 'error',
        duration: 3000,
      });
    } finally {
      setIsSuggestingRoute(false);
    }
  };

  const handleCreateRoute = async () => {
    if (selectedBookings.length === 0) {
      toast({
        title: 'No Bookings Selected',
        description: 'Please select at least one booking',
        status: 'warning',
        duration: 3000,
      });
      return;
    }

    setIsCreating(true);
    try {
      const response = await fetch('/api/admin/routes', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          bookingIds: selectedBookings, // Send booking IDs
          driverId: selectedDriver || null,
          startTime: new Date().toISOString(),
          serviceTier: 'standard',
          isAutomatic: false,
        }),
      });

      const data = await response.json();

      if (data.success) {
        toast({
          title: 'Route Created Successfully!',
          description: `${selectedBookings.length} booking(s) added to route. Redirecting to Total Routes...`,
          status: 'success',
          duration: 3000,
        });
        
        // Clear selections
        setSelectedBookings([]);
        setSelectedDriver('');
        
        // Redirect to routes page where the new route will appear in Total Routes
        router.push('/admin/routes');
        router.refresh(); // Force refresh to show new route
      } else {
        throw new Error(data.error || 'Failed to create route');
      }
    } catch (error: any) {
      console.error('Failed to create route:', error);
      toast({
        title: 'Error',
        description: error.message || 'Failed to create route',
        status: 'error',
        duration: 5000,
      });
    } finally {
      setIsCreating(false);
    }
  };

  const totalValue = (bookings || [])
    .filter(b => selectedBookings.includes(b.id))
    .reduce((sum, b) => {
      const value = Number(b.totalGBP || 0);
      return (Number.isFinite(value) && value >= 0 && value <= Number.MAX_SAFE_INTEGER) ? sum + value : sum;
    }, 0);

  return (
    <AdminShell title="Create Manual Route">
      <Container maxW="container.xl" py={8}>
        <VStack spacing={6} align="stretch">
          {/* Header */}
          <HStack justify="space-between">
            <Box>
              <HStack spacing={3} mb={2}>
                <Button
                  leftIcon={<FiArrowLeft />}
                  variant="ghost"
                  onClick={() => router.push('/admin/routes')}
                >
                  Back
                </Button>
              </HStack>
              <Heading size="lg" color="white">Create Manual Route</Heading>
              <Text color="gray.400" mt={1}>
                Select bookings and optionally assign a driver
              </Text>
            </Box>
            <Button
              leftIcon={<FiCheck />}
              colorScheme="blue"
              size="lg"
              onClick={handleCreateRoute}
              isLoading={isCreating}
              isDisabled={selectedBookings.length === 0 || isCreating}
            >
              Create Route ({selectedBookings.length})
            </Button>
          </HStack>

          {/* Summary Cards */}
          <Grid templateColumns="repeat(3, 1fr)" gap={4}>
            <Card bg="gray.800" borderWidth="1px" borderColor="gray.700">
              <CardBody>
                <HStack>
                  <Icon as={FiPackage} color="blue.400" boxSize={5} />
                  <Box>
                    <Text color="gray.400" fontSize="sm">Selected Bookings</Text>
                    <Text color="white" fontSize="2xl" fontWeight="bold">
                      {selectedBookings.length}
                    </Text>
                  </Box>
                </HStack>
              </CardBody>
            </Card>

            <Card bg="gray.800" borderWidth="1px" borderColor="gray.700">
              <CardBody>
                <HStack>
                  <Icon as={FiPackage} color="green.400" boxSize={5} />
                  <Box>
                    <Text color="gray.400" fontSize="sm">Total Value</Text>
                    <Text color="white" fontSize="2xl" fontWeight="bold">
                      £{(totalValue / 100).toFixed(2)}
                    </Text>
                  </Box>
                </HStack>
              </CardBody>
            </Card>

            <Card bg="gray.800" borderWidth="1px" borderColor="gray.700">
              <CardBody>
                <HStack>
                  <Icon as={FiTruck} color="purple.400" boxSize={5} />
                  <Box>
                    <Text color="gray.400" fontSize="sm">Available Bookings</Text>
                    <Text color="white" fontSize="2xl" fontWeight="bold">
                      {bookings?.length || 0}
                    </Text>
                  </Box>
                </HStack>
              </CardBody>
            </Card>
          </Grid>

          {/* Selected Drops Preview */}
          {selectedBookings.length > 0 && (
            <Card bg="blue.900" borderWidth="2px" borderColor="blue.500">
              <CardBody>
                <HStack justify="space-between" mb={3}>
                  <VStack align="start" spacing={0}>
                    <Text color="white" fontSize="lg" fontWeight="bold">
                      Selected Drops ({selectedBookings.length})
                    </Text>
                    {selectedBookings.length > 1 && (() => {
                      const selectedBookingsData = selectedBookings
                        .map(id => bookings?.find(b => b.id === id))
                        .filter(b => b && b.pickupLat && b.pickupLng && b.dropoffLat && b.dropoffLng);
                      
                      if (selectedBookingsData.length > 1) {
                        let totalDistance = 0;
                        for (let i = 0; i < selectedBookingsData.length - 1; i++) {
                          const current = selectedBookingsData[i]!;
                          const next = selectedBookingsData[i + 1]!;
                          totalDistance += calculateDistance( // DEPRECATED - internal use only
                            current.dropoffLat!,
                            current.dropoffLng!,
                            next.pickupLat!,
                            next.pickupLng!
                          );
                        }
                        
                        return (
                          <Text color="gray.300" fontSize="sm">
                            Total Route Distance: {totalDistance.toFixed(1)} miles
                          </Text>
                        );
                      }
                      return null;
                    })()}
                  </VStack>
                  <Button
                    size="sm"
                    colorScheme="red"
                    variant="outline"
                    onClick={() => setSelectedBookings([])}
                  >
                    Clear All
                  </Button>
                </HStack>
                <VStack spacing={2} align="stretch">
                  {selectedBookings.map((bookingId, index) => {
                    const booking = bookings?.find(b => b.id === bookingId);
                    const nextBookingId = selectedBookings[index + 1];
                    const nextBooking = nextBookingId ? bookings?.find(b => b.id === nextBookingId) : null;
                    
                    let distanceToNext = 0;
                    if (booking && nextBooking && 
                        booking.dropoffLat && booking.dropoffLng && 
                        nextBooking.pickupLat && nextBooking.pickupLng) {
                      distanceToNext = calculateDistance( // DEPRECATED - internal use only
                        booking.dropoffLat,
                        booking.dropoffLng,
                        nextBooking.pickupLat,
                        nextBooking.pickupLng
                      );
                    }
                    
                    return (
                      <Box key={bookingId}>
                        <HStack 
                          p={2} 
                          bg="blue.800" 
                          borderRadius="md"
                          justify="space-between"
                        >
                          <HStack spacing={3}>
                            <Badge colorScheme="purple" fontSize="md" px={2}>
                              {index + 1}
                            </Badge>
                            <VStack align="start" spacing={0}>
                              <Text color="white" fontSize="sm" fontWeight="bold">
                                {booking?.customerName || 'Unknown'}
                              </Text>
                              <HStack spacing={2} fontSize="xs" color="gray.300">
                                <Text>{booking?.pickupAddress?.slice(0, 30)}...</Text>
                                {booking?.distance && (
                                  <Badge colorScheme="purple" fontSize="xs">
                                    {booking.distance.toFixed(1)} miles
                                  </Badge>
                                )}
                              </HStack>
                            </VStack>
                          </HStack>
                          <Button
                            size="xs"
                            colorScheme="red"
                            variant="ghost"
                            onClick={() => handleToggleBooking(bookingId)}
                          >
                            Remove
                          </Button>
                        </HStack>
                        
                        {distanceToNext > 0 && (
                          <HStack justify="center" py={1}>
                            <Icon as={FiMapPin} color="gray.400" boxSize={3} />
                            <Text color="gray.400" fontSize="xs">
                              ↓ {distanceToNext.toFixed(1)} miles to next stop
                            </Text>
                          </HStack>
                        )}
                      </Box>
                    );
                  })}
                </VStack>
              </CardBody>
            </Card>
          )}

          {/* Route Configuration */}
          {selectedBookings.length > 0 && (
            <Card bg="gray.800" borderWidth="1px" borderColor="gray.700">
              <CardBody>
                <Text color="white" fontSize="lg" fontWeight="bold" mb={4}>
                  Route Configuration
                </Text>
                <Grid templateColumns="repeat(2, 1fr)" gap={4}>
                  <FormControl>
                    <FormLabel color="gray.400">
                      <HStack spacing={2}>
                        <Icon as={FiPackage} color="green.400" />
                        <Text>Route Number</Text>
                      </HStack>
                    </FormLabel>
                    <Input
                      value="Auto-generated (e.g., RT1A2B3C4D)"
                      isReadOnly
                      bg="gray.700"
                      color="gray.400"
                      borderColor="gray.600"
                      cursor="not-allowed"
                      fontStyle="italic"
                    />
                    <Text fontSize="xs" color="gray.500" mt={1}>
                      ✓ Route number will be generated automatically upon creation
                    </Text>
                  </FormControl>

                  <FormControl isRequired>
                    <FormLabel color="gray.400">
                      <HStack spacing={2}>
                        <Icon as={FiTruck} color="blue.400" />
                        <Text>Assign Driver</Text>
                        {selectedDriver && <Badge colorScheme="green" fontSize="xs">Selected</Badge>}
                      </HStack>
                    </FormLabel>
                    <Select
                      placeholder="Choose a driver"
                      value={selectedDriver}
                      onChange={(e) => setSelectedDriver(e.target.value)}
                      bg="gray.700"
                      color="white"
                      borderColor={selectedDriver ? 'green.500' : 'gray.600'}
                      _hover={{ borderColor: 'gray.500' }}
                      size="lg"
                    >
                      {drivers?.filter(d => d.status === 'online').map(driver => (
                        <option key={driver.id} value={driver.id}>
                          {driver.name} - {driver.status}
                        </option>
                      ))}
                    </Select>
                    {drivers?.filter(d => d.status === 'online').length === 0 && (
                      <Text color="orange.300" fontSize="xs" mt={1}>
                        ⚠️ No drivers currently online. Route will be created unassigned.
                      </Text>
                    )}
                  </FormControl>
                </Grid>
              </CardBody>
            </Card>
          )}

          {/* Bookings Table */}
          <Card bg="gray.800" borderWidth="1px" borderColor="gray.700">
            <CardBody>
              <HStack justify="space-between" mb={4}>
                <Text color="white" fontSize="lg" fontWeight="bold">
                  Available Bookings
                </Text>
                <HStack spacing={3}>
                  <Button
                    size="sm"
                    leftIcon={<Icon as={FiMapPin} />}
                    colorScheme="purple"
                    variant="solid"
                    onClick={handleSuggestSmartRoute}
                    isLoading={isSuggestingRoute}
                    isDisabled={selectedBookings.length < 2}
                  >
                    Suggest Smart Route
                  </Button>
                  <Button
                    size="sm"
                    variant="outline"
                    onClick={handleSelectAll}
                    colorScheme="blue"
                  >
                    {selectedBookings.length === (bookings?.length || 0) ? 'Deselect All' : 'Select All'}
                  </Button>
                </HStack>
              </HStack>

              {isLoading ? (
                <Box textAlign="center" py={12}>
                  <Spinner size="xl" color="blue.400" />
                  <Text color="gray.400" mt={4}>Loading bookings...</Text>
                </Box>
              ) : (bookings?.length || 0) === 0 ? (
                <Alert status="info" borderRadius="md">
                  <AlertIcon />
                  No confirmed bookings available for route creation
                </Alert>
              ) : (
                <Box overflowX="auto">
                  <Table variant="simple" size="sm">
                    <Thead>
                      <Tr>
                        <Th color="gray.400" w="50px">#</Th>
                        <Th color="gray.400">Actions</Th>
                        <Th color="gray.400">Reference</Th>
                        <Th color="gray.400">Customer</Th>
                        <Th color="gray.400">Pickup → Dropoff</Th>
                        <Th color="gray.400">Distance</Th>
                        <Th color="gray.400">Scheduled</Th>
                        <Th color="gray.400">Value</Th>
                        <Th color="gray.400">Status</Th>
                      </Tr>
                    </Thead>
                    <Tbody>
                      {bookings?.map((booking, index) => {
                        const isSelected = selectedBookings.includes(booking.id);
                        const orderInRoute = selectedBookings.indexOf(booking.id) + 1;
                        return (
                          <Tr
                            key={booking.id}
                            bg={isSelected ? 'blue.900' : 'transparent'}
                            _hover={{ bg: isSelected ? 'blue.800' : 'gray.700' }}
                            transition="all 0.2s"
                            borderLeftWidth={isSelected ? '4px' : '0'}
                            borderLeftColor="blue.400"
                          >
                            <Td>
                              {isSelected ? (
                                <Badge colorScheme="blue" fontSize="md" px={2} py={1}>
                                  {orderInRoute}
                                </Badge>
                              ) : (
                                <Text color="gray.600" fontSize="sm">
                                  {index + 1}
                                </Text>
                              )}
                            </Td>
                            <Td>
                              <HStack spacing={2}>
                                {!isSelected ? (
                                  <Button
                                    size="sm"
                                    colorScheme="green"
                                    variant="solid"
                                    leftIcon={<Icon as={FiCheck} />}
                                    onClick={() => handleToggleBooking(booking.id)}
                                    _hover={{ transform: 'scale(1.05)' }}
                                    transition="all 0.2s"
                                  >
                                    Add
                                  </Button>
                                ) : (
                                  <Button
                                    size="sm"
                                    colorScheme="red"
                                    variant="solid"
                                    onClick={() => handleToggleBooking(booking.id)}
                                    _hover={{ transform: 'scale(1.05)' }}
                                    transition="all 0.2s"
                                  >
                                    Remove
                                  </Button>
                                )}
                              </HStack>
                            </Td>
                          <Td>
                            <Text color="white" fontSize="sm" fontWeight="medium">
                              {booking.reference || booking.id.slice(0, 8)}
                            </Text>
                          </Td>
                          <Td>
                            <Text color="white" fontSize="sm">
                              {booking.customerName}
                            </Text>
                          </Td>
                          <Td>
                            <VStack align="start" spacing={0}>
                              <Text color="gray.300" fontSize="xs">
                                {booking.pickupAddress}
                              </Text>
                              <Text color="gray.500" fontSize="xs">
                                → {booking.dropoffAddress}
                              </Text>
                            </VStack>
                          </Td>
                          <Td>
                            {booking.distance ? (
                              <HStack spacing={1}>
                                <Icon as={FiMapPin} color="purple.400" boxSize={3} />
                                <Text color="white" fontSize="sm" fontWeight="medium">
                                  {booking.distance.toFixed(1)} miles
                                </Text>
                              </HStack>
                            ) : (
                              <Text color="gray.500" fontSize="xs">
                                N/A
                              </Text>
                            )}
                          </Td>
                          <Td>
                            <Text color="gray.300" fontSize="xs">
                              {new Date(booking.scheduledAt).toLocaleString('en-GB')}
                            </Text>
                          </Td>
                          <Td>
                            <Text color="white" fontSize="sm" fontWeight="medium">
                              £{(booking.totalGBP / 100).toFixed(2)}
                            </Text>
                          </Td>
                          <Td>
                            {isSelected ? (
                              <Badge colorScheme="green" fontSize="xs">
                                ✓ Added to Route
                              </Badge>
                            ) : (
                              <Badge colorScheme="gray" fontSize="xs">
                                Available
                              </Badge>
                            )}
                          </Td>
                        </Tr>
                        );
                      })}
                    </Tbody>
                  </Table>
                </Box>
              )}
            </CardBody>
          </Card>
        </VStack>
      </Container>
    </AdminShell>
  );
}

'use client';
import React, { useState } from 'react';
import {
  Box,
  VStack,
  HStack,
  Heading,
  Text,
  Button,
  Card,
  CardBody,
  FormControl,
  FormLabel,
  Input,
  InputGroup,
  InputRightElement,
  Switch,
  FormHelperText,
  Badge,
  Alert,
  AlertIcon,
  useToast,
  Divider,
  Grid,
  Icon,
  useColorModeValue,
  Tooltip,
  Textarea,
  Select,
} from '@chakra-ui/react';
import {
  FiEye,
  FiEyeOff,
  FiCopy,
  FiRefreshCw,
  FiCheck,
  FiX,
  FiAlertCircle,
  FiCreditCard,
  FiMessageSquare,
  FiMap,
  FiMail,
  FiGlobe,
  FiShield,
} from 'react-icons/fi';

interface Integration {
  id: string;
  name: string;
  description: string;
  icon: React.ElementType;
  status: 'connected' | 'disconnected' | 'error';
  config: Record<string, any>;
  isEnabled: boolean;
}

const mockIntegrations: Integration[] = [
  {
    id: 'stripe',
    name: 'Stripe',
    description: 'Payment processing and subscription management',
    icon: FiCreditCard,
    status: 'connected',
    isEnabled: true,
    config: {
      publishableKey: 'pk_live_...',
      secretKey: 'sk_live_...',
      webhookSecret: 'whsec_...',
    },
  },
  {
    id: 'pusher',
    name: 'Pusher',
    description: 'Real-time notifications and live updates',
    icon: FiMessageSquare,
    status: 'connected',
    isEnabled: true,
    config: {
      appId: '1234567',
      key: 'abcdef123456',
      secret: 'ghijkl789012',
      cluster: 'eu',
    },
  },
  {
    id: 'mapbox',
    name: 'Mapbox',
    description: 'Geocoding, directions, and location services',
    icon: FiMap,
    status: 'connected',
    isEnabled: true,
    config: {
      accessToken: 'pk.eyJ1Ijoi...',
      styleUrl: 'mapbox://styles/mapbox/streets-v12',
      geocodingEndpoint: 'https://api.mapbox.com/geocoding/v5',
    },
  },
  {
    id: 'email',
    name: 'SendGrid',
    description: 'Transactional email delivery',
    icon: FiMail,
    status: 'connected',
    isEnabled: true,
    config: {
      apiKey: 'SG...',
      fromEmail: 'noreply@speedy-van.co.uk',
      fromName: 'Speedy Van',
    },
  },
  {
    id: 'webhooks',
    name: 'Webhooks',
    description: 'Outbound webhook notifications',
    icon: FiGlobe,
    status: 'disconnected',
    isEnabled: false,
    config: {
      endpoints: [],
      retryAttempts: 3,
      timeout: 5000,
    },
  },
  {
    id: 'security',
    name: 'Security Headers',
    description: 'CSP, HSTS, and security configurations',
    icon: FiShield,
    status: 'connected',
    isEnabled: true,
    config: {
      cspEnabled: true,
      hstsEnabled: true,
      rateLimitEnabled: true,
    },
  },
];

export default function IntegrationsSettings() {
  const [integrations, setIntegrations] =
    useState<Integration[]>(mockIntegrations);
  const [showSecrets, setShowSecrets] = useState<Record<string, boolean>>({});
  const [editingIntegration, setEditingIntegration] = useState<string | null>(
    null
  );
  const toast = useToast();
  const bgColor = useColorModeValue('white', 'gray.800');
  const borderColor = useColorModeValue('gray.200', 'gray.700');

  const toggleSecretVisibility = (integrationId: string) => {
    setShowSecrets(prev => ({
      ...prev,
      [integrationId]: !prev[integrationId],
    }));
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    toast({
      title: 'Copied to clipboard',
      status: 'success',
      duration: 2000,
    });
  };

  const testConnection = (integrationId: string) => {
    toast({
      title: 'Testing connection...',
      status: 'info',
      duration: 2000,
    });

    // Simulate API test
    setTimeout(() => {
      toast({
        title: 'Connection successful',
        description: 'The integration is working correctly.',
        status: 'success',
      });
    }, 2000);
  };

  const updateIntegration = (
    integrationId: string,
    updates: Partial<Integration>
  ) => {
    setIntegrations(prev =>
      prev.map(integration =>
        integration.id === integrationId
          ? { ...integration, ...updates }
          : integration
      )
    );
    setEditingIntegration(null);
    toast({
      title: 'Integration updated',
      status: 'success',
    });
  };

  const getStatusColor = (status: string) => {
    const colors: Record<string, string> = {
      connected: 'green',
      disconnected: 'gray',
      error: 'red',
    };
    return colors[status] || 'gray';
  };

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'connected':
        return FiCheck;
      case 'error':
        return FiX;
      default:
        return FiAlertCircle;
    }
  };

  return (
    <Box p={6}>
      <VStack align="start" spacing={6} w="full">
        <Box>
          <Heading size="lg" mb={2}>
            Integrations
          </Heading>
          <Text color="gray.600">
            Configure third-party services and API connections for your
            platform.
          </Text>
        </Box>

        <Grid
          templateColumns="repeat(auto-fit, minmax(400px, 1fr))"
          gap={6}
          w="full"
        >
          {integrations.map(integration => (
            <Card
              key={integration.id}
              bg={bgColor}
              border="1px solid"
              borderColor={borderColor}
            >
              <CardBody>
                <VStack align="start" spacing={4}>
                  {/* Header */}
                  <HStack justify="space-between" w="full">
                    <HStack>
                      <Icon
                        as={integration.icon}
                        boxSize={5}
                        color="brand.500"
                      />
                      <Box>
                        <Heading size="md">{integration.name}</Heading>
                        <Text fontSize="sm" color="gray.600">
                          {integration.description}
                        </Text>
                      </Box>
                    </HStack>
                    <VStack align="end" spacing={1}>
                      <Badge colorScheme={getStatusColor(integration.status)}>
                        {integration.status}
                      </Badge>
                      <Switch
                        isChecked={integration.isEnabled}
                        onChange={e =>
                          updateIntegration(integration.id, {
                            isEnabled: e.target.checked,
                          })
                        }
                        size="sm"
                      />
                    </VStack>
                  </HStack>

                  {/* Status */}
                  <HStack>
                    <Icon
                      as={getStatusIcon(integration.status)}
                      color={`${getStatusColor(integration.status)}.500`}
                    />
                    <Text fontSize="sm">
                      {integration.status === 'connected' &&
                        'Connected and working'}
                      {integration.status === 'disconnected' && 'Not connected'}
                      {integration.status === 'error' && 'Connection error'}
                    </Text>
                  </HStack>

                  {/* Configuration */}
                  {editingIntegration === integration.id ? (
                    <IntegrationConfigForm
                      integration={integration}
                      onSave={config =>
                        updateIntegration(integration.id, { config })
                      }
                      onCancel={() => setEditingIntegration(null)}
                    />
                  ) : (
                    <IntegrationConfigDisplay
                      integration={integration}
                      showSecrets={showSecrets[integration.id] || false}
                      onToggleSecrets={() =>
                        toggleSecretVisibility(integration.id)
                      }
                      onCopy={copyToClipboard}
                    />
                  )}

                  {/* Actions */}
                  <HStack spacing={2} w="full">
                    <Button
                      size="sm"
                      variant="outline"
                      onClick={() => setEditingIntegration(integration.id)}
                    >
                      Configure
                    </Button>
                    <Button
                      size="sm"
                      variant="outline"
                      leftIcon={<FiRefreshCw />}
                      onClick={() => testConnection(integration.id)}
                    >
                      Test
                    </Button>
                  </HStack>
                </VStack>
              </CardBody>
            </Card>
          ))}
        </Grid>

        {/* Security Notice */}
        <Alert status="info" borderRadius="md">
          <AlertIcon />
          <Box>
            <Text fontWeight="medium">Security Notice</Text>
            <Text fontSize="sm">
              API keys and secrets are encrypted at rest and only displayed when
              needed. Never share these credentials or commit them to version
              control.
            </Text>
          </Box>
        </Alert>
      </VStack>
    </Box>
  );
}

interface IntegrationConfigFormProps {
  integration: Integration;
  onSave: (config: Record<string, any>) => void;
  onCancel: () => void;
}

function IntegrationConfigForm({
  integration,
  onSave,
  onCancel,
}: IntegrationConfigFormProps) {
  const [config, setConfig] = useState(integration.config);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave(config);
  };

  const renderField = (key: string, value: any) => {
    if (typeof value === 'boolean') {
      return (
        <FormControl key={key}>
          <FormLabel>
            {key
              .replace(/([A-Z])/g, ' $1')
              .replace(/^./, str => str.toUpperCase())}
          </FormLabel>
          <Switch
            isChecked={value}
            onChange={e => setConfig({ ...config, [key]: e.target.checked })}
          />
        </FormControl>
      );
    }

    if (typeof value === 'number') {
      return (
        <FormControl key={key}>
          <FormLabel>
            {key
              .replace(/([A-Z])/g, ' $1')
              .replace(/^./, str => str.toUpperCase())}
          </FormLabel>
          <Input
            type="number"
            value={value}
            onChange={e =>
              setConfig({ ...config, [key]: parseInt(e.target.value) })
            }
          />
        </FormControl>
      );
    }

    if (Array.isArray(value)) {
      return (
        <FormControl key={key}>
          <FormLabel>
            {key
              .replace(/([A-Z])/g, ' $1')
              .replace(/^./, str => str.toUpperCase())}
          </FormLabel>
          <Textarea
            value={value.join('\n')}
            onChange={e =>
              setConfig({
                ...config,
                [key]: e.target.value.split('\n').filter(Boolean),
              })
            }
            placeholder="Enter values, one per line"
          />
        </FormControl>
      );
    }

    return (
      <FormControl key={key}>
        <FormLabel>
          {key
            .replace(/([A-Z])/g, ' $1')
            .replace(/^./, str => str.toUpperCase())}
        </FormLabel>
        <Input
          value={value}
          onChange={e => setConfig({ ...config, [key]: e.target.value })}
          placeholder={`Enter ${key}`}
        />
      </FormControl>
    );
  };

  return (
    <Box as="form" onSubmit={handleSubmit} w="full">
      <VStack spacing={3} align="start">
        {Object.entries(config).map(([key, value]) => renderField(key, value))}
        <HStack spacing={2}>
          <Button type="submit" size="sm" colorScheme="brand">
            Save
          </Button>
          <Button size="sm" variant="ghost" onClick={onCancel}>
            Cancel
          </Button>
        </HStack>
      </VStack>
    </Box>
  );
}

interface IntegrationConfigDisplayProps {
  integration: Integration;
  showSecrets: boolean;
  onToggleSecrets: () => void;
  onCopy: (text: string) => void;
}

function IntegrationConfigDisplay({
  integration,
  showSecrets,
  onToggleSecrets,
  onCopy,
}: IntegrationConfigDisplayProps) {
  const isSecretKey = (key: string) =>
    key.toLowerCase().includes('secret') ||
    key.toLowerCase().includes('key') ||
    key.toLowerCase().includes('token');

  return (
    <VStack align="start" spacing={2} w="full">
      <Text fontSize="sm" fontWeight="medium" color="gray.700">
        Configuration:
      </Text>
      {Object.entries(integration.config).map(([key, value]) => (
        <Box key={key} w="full">
          <Text fontSize="xs" color="gray.500" mb={1}>
            {key
              .replace(/([A-Z])/g, ' $1')
              .replace(/^./, str => str.toUpperCase())}
            :
          </Text>
          <HStack>
            <Input
              size="sm"
              value={
                isSecretKey(key) && !showSecrets ? '••••••••' : String(value)
              }
              isReadOnly
              fontFamily="mono"
            />
            {isSecretKey(key) && (
              <Tooltip label={showSecrets ? 'Hide' : 'Show'}>
                <Button size="sm" variant="ghost" onClick={onToggleSecrets}>
                  <Icon as={showSecrets ? FiEyeOff : FiEye} />
                </Button>
              </Tooltip>
            )}
            <Tooltip label="Copy">
              <Button
                size="sm"
                variant="ghost"
                onClick={() => onCopy(String(value))}
              >
                <Icon as={FiCopy} />
              </Button>
            </Tooltip>
          </HStack>
        </Box>
      ))}
    </VStack>
  );
}

