                  Export All Documents
                </Button>
                <Button leftIcon={<FiUpload />} variant="outline">
                  Import Documents
                </Button>
              </HStack>
            </VStack>
          </CardBody>
        </Card>
      </VStack>
    </Box>
  );
}

