interface Staff {
  id: string;
  employeeId: string;
  department: string | null;
  position: string | null;
  employmentType: string;
  status: string;
  workSchedule: any;
  User: {
    id: string;
    email: string;
    name: string | null;
    phone: string | null;
    role?: string;
    adminRole?: string;
  };
}

export default function AdminStaffPage() {
  const [staff, setStaff] = useState<Staff[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [departmentFilter, setDepartmentFilter] = useState('');
  const [statusFilter, setStatusFilter] = useState('');
  const [selectedStaff, setSelectedStaff] = useState<Staff | null>(null);
  const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [isRotaModalOpen, setIsRotaModalOpen] = useState(false);
  const [isPayslipOpen, setIsPayslipOpen] = useState(false);
  const toast = useToast();

  const {
    isOpen: isDeleteOpen,
    onOpen: onDeleteOpen,
    onClose: onDeleteClose,
  } = useDisclosure();

  useEffect(() => {
    fetchStaff();
  }, [departmentFilter, statusFilter]);

  const fetchStaff = async () => {
    try {
      setLoading(true);
      const params = new URLSearchParams();
      if (departmentFilter && departmentFilter.trim()) params.append('department', departmentFilter);
      if (statusFilter && statusFilter.trim()) params.append('status', statusFilter);
      if (searchTerm && searchTerm.trim()) params.append('search', searchTerm);

      const response = await fetch(`/api/admin/staff?${params.toString()}`);
      
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      
      const data = await response.json();

      if (data.success) {
        setStaff(data.staff);
      } else {
        throw new Error(data.error || 'Failed to fetch staff');
      }
    } catch (error) {
      console.error('Error fetching staff:', error);
      toast({
        title: 'Error',
        description: error instanceof Error ? error.message : 'Failed to fetch staff',
        status: 'error',
        duration: 3000,
      });
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id: string) => {
    try {
      const response = await fetch(`/api/admin/staff/${id}`, {
        method: 'DELETE',
      });

      const data = await response.json();

      if (data.success) {
        toast({
          title: 'Success',
          description: 'Staff deleted successfully',
          status: 'success',
          duration: 3000,
        });
        fetchStaff();
        onDeleteClose();
      } else {
        throw new Error(data.error);
      }
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to delete staff',
        status: 'error',
        duration: 3000,
      });
    }
  };

  const filteredStaff = staff.filter((s) => {
    if (!searchTerm) return true;
    const term = searchTerm.toLowerCase();
    return (
      s.employeeId.toLowerCase().includes(term) ||
      s.User.name?.toLowerCase().includes(term) ||
      s.User.email.toLowerCase().includes(term)
    );
  });

  const departments = Array.from(
    new Set(staff.map((s) => s.department).filter((d): d is string => !!d))
  );

  return (
    <Box p={6}>
      <Flex justify="space-between" align="center" mb={6}>
        <Heading size="lg">Staff Management</Heading>
        <HStack spacing={3}>
          <Button variant="outline" onClick={async () => {
            try {
              const res = await fetch('/api/admin/staff/sync-admins', { method: 'POST' });
              if (!res.ok) throw new Error(`HTTP ${res.status}`);
              const data = await res.json();
              if (!data.success) throw new Error(data.error || 'Failed to sync admins');
              toast({
                title: 'Admins synced',
                description: `Created: ${data.created}, Skipped: ${data.skipped}`,
                status: 'success',
                duration: 3000,
              });
              fetchStaff();
            } catch (e: any) {
              toast({
                title: 'Sync failed',
                description: e?.message || 'Unable to sync admins',
                status: 'error',
                duration: 4000,
              });
            }
          }}>
            Sync Admins
          </Button>
          <Button
            leftIcon={<FiPlus />}
            colorScheme="blue"
            onClick={() => setIsCreateModalOpen(true)}
          >
            Add Staff
          </Button>
        </HStack>
      </Flex>

      <Flex justify="flex-end" mb={4}>
        <Button variant="outline" onClick={() => setIsPayslipOpen(true)}>
          Generate Payslips
        </Button>
      </Flex>

      {/* Filters */}
      <Card mb={6}>
        <CardBody>
          <Stack direction={{ base: 'column', md: 'row' }} spacing={4}>
            <InputGroup flex={1}>
              <InputLeftElement pointerEvents="none">
                <FiSearch />
              </InputLeftElement>
              <Input
                placeholder="Search by name, email, or employee ID..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </InputGroup>
            <Select
              placeholder="All Departments"
              value={departmentFilter}
              onChange={(e) => setDepartmentFilter(e.target.value)}
              maxW="200px"
            >
              {departments.map((dept) => (
                <option key={dept} value={dept}>
                  {dept}
                </option>
              ))}
            </Select>
            <Select
              placeholder="All Status"
              value={statusFilter}
              onChange={(e) => setStatusFilter(e.target.value)}
              maxW="200px"
            >
              <option value="active">Active</option>
              <option value="inactive">Inactive</option>
              <option value="suspended">Suspended</option>
              <option value="terminated">Terminated</option>
              <option value="on_leave">On Leave</option>
            </Select>
          </Stack>
        </CardBody>
      </Card>

      {/* Staff Table */}
      <Card>
        <CardBody>
          {loading ? (
            <Flex justify="center" p={8}>
              <Spinner size="xl" />
            </Flex>
          ) : (
            <Table variant="simple">
              <Thead>
                <Tr>
                  <Th>Employee ID</Th>
                  <Th>Name</Th>
                  <Th>Email</Th>
                  <Th>Phone</Th>
                  <Th>Department</Th>
                  <Th>Position</Th>
                  <Th>Source</Th>
                  <Th>Status</Th>
                  <Th>Actions</Th>
                </Tr>
              </Thead>
              <Tbody>
                {filteredStaff.length === 0 ? (
                  <Tr>
                    <Td colSpan={8} textAlign="center" py={8}>
                      <Text color="gray.500">No staff found</Text>
                    </Td>
                  </Tr>
                ) : (
                  filteredStaff.map((s) => (
                    <Tr key={s.id}>
                      <Td fontWeight="medium">{s.employeeId}</Td>
                      <Td>{s.User.name || 'N/A'}</Td>
                      <Td>{s.User.email}</Td>
                      <Td>{s.User.phone || 'N/A'}</Td>
                      <Td>{s.department || 'N/A'}</Td>
                      <Td>{s.position || 'N/A'}</Td>
                      <Td>
                        {s.employeeId?.startsWith('ADM-') || s.User.role === 'admin' ? (
                          <Badge colorScheme="green">Admin Sync</Badge>
                        ) : (
                          <Badge colorScheme="gray">Standard</Badge>
                        )}
                      </Td>
                      <Td>
                        <Badge
                          colorScheme={
                            s.status === 'active'
                              ? 'green'
                              : s.status === 'suspended'
                              ? 'red'
                              : s.status === 'on_leave'
                              ? 'yellow'
                              : 'gray'
                          }
                        >
                          {s.status}
                        </Badge>
                      </Td>
                      <Td>
                        <Menu>
                          <MenuButton
                            as={IconButton}
                            icon={<FiMoreVertical />}
                            variant="ghost"
                            size="sm"
                          />
                          <MenuList>
                            <MenuItem
                              icon={<FiEdit />}
                              onClick={() => {
                                setSelectedStaff(s);
                                setIsEditModalOpen(true);
                              }}
                            >
                              Edit
                            </MenuItem>
                            <MenuItem
                              icon={<FiClock />}
                              onClick={() => {
                                setSelectedStaff(s);
                                setIsRotaModalOpen(true);
                              }}
                            >
                              Edit Rota
                            </MenuItem>
                            <MenuDivider />
                            <MenuItem
                              icon={<FiTrash2 />}
                              color="red.500"
                              onClick={() => {
                                setSelectedStaff(s);
                                onDeleteOpen();
                              }}
                            >
                              Delete
                            </MenuItem>
                          </MenuList>
                        </Menu>
                      </Td>
                    </Tr>
                  ))
                )}
              </Tbody>
            </Table>
          )}
        </CardBody>
      </Card>

      {/* Create Staff Modal */}
      <CreateStaffModal
        isOpen={isCreateModalOpen}
        onClose={() => setIsCreateModalOpen(false)}
        onSuccess={() => {
          setIsCreateModalOpen(false);
          fetchStaff();
        }}
      />

      {/* Edit Staff Modal */}
      {selectedStaff && (
        <>
          <EditStaffModal
            isOpen={isEditModalOpen}
            onClose={() => {
              setIsEditModalOpen(false);
              setSelectedStaff(null);
            }}
            staff={selectedStaff}
            onSuccess={() => {
              setIsEditModalOpen(false);
              setSelectedStaff(null);
              fetchStaff();
            }}
          />
          <RotaEditorModal
            isOpen={isRotaModalOpen}
            onClose={() => {
              setIsRotaModalOpen(false);
              setSelectedStaff(null);
            }}
            staff={selectedStaff}
            onSuccess={() => {
              setIsRotaModalOpen(false);
              setSelectedStaff(null);
              fetchStaff();
            }}
          />
        </>
      )}

      {/* Payslip Generator Modal */}
      <PayslipGeneratorModal
        isOpen={isPayslipOpen}
        onClose={() => setIsPayslipOpen(false)}
      />

      {/* Delete Confirmation Modal */}
      <Modal isOpen={isDeleteOpen} onClose={onDeleteClose}>
        <ModalOverlay />
        <ModalContent>
          <ModalHeader>Delete Staff</ModalHeader>
          <ModalCloseButton />
          <ModalBody>
            <Text>
              Are you sure you want to delete {selectedStaff?.User.name}? This action cannot be
              undone.
            </Text>
          </ModalBody>
          <ModalFooter>
            <Button variant="ghost" mr={3} onClick={onDeleteClose}>
              Cancel
            </Button>
            <Button
              colorScheme="red"
              onClick={() => selectedStaff && handleDelete(selectedStaff.id)}
            >
              Delete
            </Button>
          </ModalFooter>
        </ModalContent>
      </Modal>
    </Box>
  );
}

// Create Staff Modal Component
function CreateStaffModal({
  isOpen,
  onClose,
  onSuccess,
}: {
  isOpen: boolean;
  onClose: () => void;
  onSuccess: () => void;
}) {
  const [formData, setFormData] = useState({
    email: '',
    name: '',
    phone: '',
    employeeId: '',
    department: '',
    position: '',
    employmentType: 'full_time',
    password: '',
  });
  const [loading, setLoading] = useState(false);
  const toast = useToast();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      const response = await fetch('/api/admin/staff', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData),
      });

      const data = await response.json();

      if (data.success) {
        toast({
          title: 'Success',
          description: 'Staff created successfully',
          status: 'success',
          duration: 3000,
        });
        onSuccess();
        setFormData({
          email: '',
          name: '',
          phone: '',
          employeeId: '',
          department: '',
          position: '',
          employmentType: 'full_time',
          password: '',
        });
      } else {
        throw new Error(data.error);
      }
    } catch (error: any) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to create staff',
        status: 'error',
        duration: 3000,
      });
    } finally {
      setLoading(false);
    }
  };

  return (
    <Modal isOpen={isOpen} onClose={onClose} size="xl">
      <ModalOverlay />
      <ModalContent>
        <ModalHeader>Add New Staff</ModalHeader>
        <ModalCloseButton />
        <form onSubmit={handleSubmit}>
          <ModalBody>
            <Stack spacing={4}>
              <FormControl isRequired>
                <FormLabel>Email</FormLabel>
                <Input
                  type="email"
                  value={formData.email}
                  onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                />
              </FormControl>
              <FormControl isRequired>
                <FormLabel>Name</FormLabel>
                <Input
                  value={formData.name}
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                />
              </FormControl>
              <FormControl>
                <FormLabel>Phone</FormLabel>
                <Input
                  value={formData.phone}
                  onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
                />
              </FormControl>
              <FormControl isRequired>
                <FormLabel>Employee ID</FormLabel>
                <Input
                  value={formData.employeeId}
                  onChange={(e) => setFormData({ ...formData, employeeId: e.target.value })}
                />
              </FormControl>
              <FormControl>
                <FormLabel>Department</FormLabel>
                <Input
                  value={formData.department}
                  onChange={(e) => setFormData({ ...formData, department: e.target.value })}
                />
              </FormControl>
              <FormControl>
                <FormLabel>Position</FormLabel>
                <Input
                  value={formData.position}
                  onChange={(e) => setFormData({ ...formData, position: e.target.value })}
                />
              </FormControl>
              <FormControl isRequired>
                <FormLabel>Employment Type</FormLabel>
                <Select
                  value={formData.employmentType}
                  onChange={(e) =>
                    setFormData({ ...formData, employmentType: e.target.value })
                  }
                  sx={{
                    'option': {
                      color: 'black',
                    },
                  }}
                >
                  <option value="full_time">Full Time</option>
                  <option value="part_time">Part Time</option>
                  <option value="contract">Contract</option>
                  <option value="temporary">Temporary</option>
                  <option value="intern">Intern</option>
                </Select>
              </FormControl>
              <FormControl isRequired>
                <FormLabel>Password</FormLabel>
                <Input
                  type="password"
                  value={formData.password}
                  onChange={(e) => setFormData({ ...formData, password: e.target.value })}
                />
              </FormControl>
            </Stack>
          </ModalBody>
          <ModalFooter>
            <Button variant="ghost" mr={3} onClick={onClose}>
              Cancel
            </Button>
            <Button type="submit" colorScheme="blue" isLoading={loading}>
              Create
            </Button>
          </ModalFooter>
        </form>
      </ModalContent>
    </Modal>
  );
}

