// Rota Editor Modal Component
function RotaEditorModal({
  isOpen,
  onClose,
  staff,
  onSuccess,
}: {
  isOpen: boolean;
  onClose: () => void;
  staff: Staff;
  onSuccess: () => void;
}) {
  const [workSchedule, setWorkSchedule] = useState(
    staff.workSchedule || {
      defaultShift: { start: '09:00', end: '17:00' },
      breakMinutes: 60,
      minHours: 8,
      weeklyOverrides: {},
    }
  );
  const [loading, setLoading] = useState(false);
  const toast = useToast();

  const days = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday'];

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      const response = await fetch(`/api/admin/staff/${staff.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ workSchedule }),
      });

      const data = await response.json();

      if (data.success) {
        toast({
          title: 'Success',
          description: 'Rota updated successfully',
          status: 'success',
          duration: 3000,
        });
        onSuccess();
      } else {
        throw new Error(data.error);
      }
    } catch (error: any) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to update rota',
        status: 'error',
        duration: 3000,
      });
    } finally {
      setLoading(false);
    }
  };

  const updateDefaultShift = (field: 'start' | 'end', value: string) => {
    setWorkSchedule({
      ...workSchedule,
      defaultShift: {
        ...workSchedule.defaultShift,
        [field]: value,
      },
    });
  };

  const updateDayOverride = (day: string, field: 'start' | 'end', value: string) => {
    const overrides = workSchedule.weeklyOverrides || {};
    if (!overrides[day]) {
      overrides[day] = { start: '09:00', end: '17:00' };
    }
    overrides[day][field] = value;
    setWorkSchedule({
      ...workSchedule,
      weeklyOverrides: overrides,
    });
  };

  const removeDayOverride = (day: string) => {
    const overrides = { ...workSchedule.weeklyOverrides };
    delete overrides[day];
    setWorkSchedule({
      ...workSchedule,
      weeklyOverrides: overrides,
    });
  };

  return (
    <Modal isOpen={isOpen} onClose={onClose} size="2xl">
      <ModalOverlay />
      <ModalContent>
        <ModalHeader>Edit Rota - {staff.User.name}</ModalHeader>
        <ModalCloseButton />
        <form onSubmit={handleSubmit}>
          <ModalBody>
            <Stack spacing={6}>
              <Box>
                <Text fontWeight="bold" mb={3}>
                  Default Shift
                </Text>
                <HStack spacing={4}>
                  <FormControl>
                    <FormLabel>Start Time</FormLabel>
                    <Input
                      type="time"
                      value={workSchedule.defaultShift.start}
                      onChange={(e) => updateDefaultShift('start', e.target.value)}
                    />
                  </FormControl>
                  <FormControl>
                    <FormLabel>End Time</FormLabel>
                    <Input
                      type="time"
                      value={workSchedule.defaultShift.end}
                      onChange={(e) => updateDefaultShift('end', e.target.value)}
                    />
                  </FormControl>
                </HStack>
              </Box>

              <Divider />

              <Box>
                <Text fontWeight="bold" mb={3}>
                  Weekly Overrides
                </Text>
                <Stack spacing={3}>
                  {days.map((day) => {
                    const override = workSchedule.weeklyOverrides?.[day];
                    return (
                      <Box key={day} p={3} borderWidth={1} borderRadius="md">
                        <Flex justify="space-between" align="center" mb={2}>
                          <Text fontWeight="medium" textTransform="capitalize">
                            {day}
                          </Text>
                          {override ? (
                            <Button
                              size="sm"
                              variant="ghost"
                              onClick={() => removeDayOverride(day)}
                            >
                              Remove Override
                            </Button>
                          ) : (
                            <Button
                              size="sm"
                              colorScheme="blue"
                              onClick={() =>
                                updateDayOverride(day, 'start', workSchedule.defaultShift.start)
                              }
                            >
                              Add Override
                            </Button>
                          )}
                        </Flex>
                        {override && (
                          <HStack spacing={4}>
                            <FormControl>
                              <FormLabel>Start</FormLabel>
                              <Input
                                type="time"
                                value={override.start}
                                onChange={(e) => updateDayOverride(day, 'start', e.target.value)}
                              />
                            </FormControl>
                            <FormControl>
                              <FormLabel>End</FormLabel>
                              <Input
                                type="time"
                                value={override.end}
                                onChange={(e) => updateDayOverride(day, 'end', e.target.value)}
                              />
                            </FormControl>
                          </HStack>
                        )}
                      </Box>
                    );
                  })}
                </Stack>
              </Box>

              <HStack spacing={4}>
                <FormControl>
                  <FormLabel>Break Minutes</FormLabel>
                  <Input
                    type="number"
                    value={workSchedule.breakMinutes}
                    onChange={(e) =>
                      setWorkSchedule({
                        ...workSchedule,
                        breakMinutes: parseInt(e.target.value) || 0,
                      })
                    }
                  />
                </FormControl>
                <FormControl>
                  <FormLabel>Minimum Hours</FormLabel>
                  <Input
                    type="number"
                    value={workSchedule.minHours}
                    onChange={(e) =>
                      setWorkSchedule({
                        ...workSchedule,
                        minHours: parseFloat(e.target.value) || 0,
                      })
                    }
                  />
                </FormControl>
              </HStack>
            </Stack>
          </ModalBody>
          <ModalFooter>
            <Button variant="ghost" mr={3} onClick={onClose}>
              Cancel
            </Button>
            <Button type="submit" colorScheme="blue" isLoading={loading}>
              Save Rota
            </Button>
          </ModalFooter>
        </form>
      </ModalContent>
    </Modal>
  );
}

// Payslip Generator Modal
function PayslipGeneratorModal({
  isOpen,
  onClose,
}: {
  isOpen: boolean;
  onClose: () => void;
}) {
  const [period, setPeriod] = useState<'weekly' | 'monthly' | 'custom'>('monthly');
  const [weekEnding, setWeekEnding] = useState<string>('');
  const [month, setMonth] = useState<number>(new Date().getMonth() + 1);
  const [year, setYear] = useState<number>(new Date().getFullYear());
  const [from, setFrom] = useState<string>('');
  const [to, setTo] = useState<string>('');
  const [loading, setLoading] = useState(false);
  const [results, setResults] = useState<any[] | null>(null);
  const [summary, setSummary] = useState<any | null>(null);
  const toast = useToast();

  const generate = async () => {
    try {
      setLoading(true);
      setResults(null);
      setSummary(null);

      const payload: any = { period };
      if (period === 'weekly' && weekEnding) payload.weekEnding = weekEnding;
      if (period === 'monthly') {
        payload.month = month;
        payload.year = year;
      }
      if (period === 'custom' && from && to) {
        payload.from = new Date(from).toISOString();
        payload.to = new Date(to).toISOString();
      }

      const res = await fetch('/api/admin/staff/payslips', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });
      if (!res.ok) {
        throw new Error(`HTTP ${res.status}`);
      }
      const data = await res.json();
      if (!data.success) throw new Error(data.error || 'Failed to generate payslips');

      setResults(data.payslips || []);
      setSummary(data.summary || null);
    } catch (e: any) {
      toast({
        title: 'Generation failed',
        description: e?.message || 'Unable to generate payslips',
        status: 'error',
        duration: 4000,
      });
    } finally {
      setLoading(false);
    }
  };

  const downloadCsv = () => {
    if (!results) return;
    const headers = [
      'Employee ID',
      'Name',
      'Email',
      'Hours',
      'Hourly Rate',
      'Gross Pay',
      'NI',
      'PAYE',
      'Other Deductions',
      'Net Pay',
    ];
    const rows = results.map((p: any) => [
      p.employeeId,
      p.name,
      p.email,
      p.hours,
      p.hourlyRate,
      p.grossPay,
      p.deductions?.ni ?? 0,
      p.deductions?.paye ?? 0,
      p.deductions?.other ?? 0,
      p.netPay,
    ]);
    const csv =
      headers.join(',') +
      '\n' +
      rows.map(r => r.map(v => (typeof v === 'string' && v.includes(',') ? `"${v}"` : v)).join(',')).join('\n');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'payslips.csv';
    a.click();
    URL.revokeObjectURL(url);
  };

  return (
    <Modal isOpen={isOpen} onClose={onClose} size="3xl">
      <ModalOverlay />
      <ModalContent>
        <ModalHeader>Generate Payslips</ModalHeader>
        <ModalCloseButton />
        <ModalBody>
          <Stack spacing={6}>
            <FormControl as={Box}>
              <FormLabel>Period</FormLabel>
              <RadioGroup value={period} onChange={(v) => setPeriod(v as any)}>
                <Stack direction="row">
                  <Radio value="weekly">Weekly</Radio>
                  <Radio value="monthly">Monthly</Radio>
                  <Radio value="custom">Custom Range</Radio>
                </Stack>
              </RadioGroup>
              <FormHelperText>
                Weekly uses a 7-day range ending on the selected date. Monthly uses calendar month.
              </FormHelperText>
            </FormControl>

            {period === 'weekly' && (
              <FormControl isRequired>
                <FormLabel>Week ending</FormLabel>
                <Input type="date" value={weekEnding} onChange={(e) => setWeekEnding(e.target.value)} />
              </FormControl>
            )}

            {period === 'monthly' && (
              <Stack direction={{ base: 'column', md: 'row' }} spacing={4}>
                <FormControl isRequired>
                  <FormLabel>Month</FormLabel>
                  <Select value={month} onChange={(e) => setMonth(parseInt(e.target.value))}>
                    {Array.from({ length: 12 }).map((_, i) => (
                      <option key={i + 1} value={i + 1}>
                        {new Date(0, i).toLocaleString('en', { month: 'long' })}
                      </option>
                    ))}
                  </Select>
                </FormControl>
                <FormControl isRequired>
                  <FormLabel>Year</FormLabel>
                  <Input
                    type="number"
                    value={year}
                    onChange={(e) => setYear(parseInt(e.target.value || `${new Date().getFullYear()}`))}
                  />
                </FormControl>
              </Stack>
            )}

            {period === 'custom' && (
              <Stack direction={{ base: 'column', md: 'row' }} spacing={4}>
                <FormControl isRequired>
                  <FormLabel>From</FormLabel>
                  <Input type="date" value={from} onChange={(e) => setFrom(e.target.value)} />
                </FormControl>
                <FormControl isRequired>
                  <FormLabel>To</FormLabel>
                  <Input type="date" value={to} onChange={(e) => setTo(e.target.value)} />
                </FormControl>
              </Stack>
            )}

            <Button colorScheme="blue" onClick={generate} isLoading={loading} alignSelf="flex-start">
              Generate
            </Button>

            {summary && (
              <Box>
                <Heading size="sm" mb={2}>
                  Summary
                </Heading>
                <Text fontSize="sm">Total Staff: {summary.totalStaff}</Text>
                <Text fontSize="sm">Total Hours: {summary.totalHours}</Text>
                <Text fontSize="sm">Total Gross: £{summary.totalGross}</Text>
                <Text fontSize="sm">Total Net: £{summary.totalNet}</Text>
              </Box>
            )}

            {results && results.length > 0 && (
              <Box>
                <Flex justify="space-between" align="center" mb={3}>
                  <Heading size="sm">Payslips</Heading>
                  <Button size="sm" onClick={downloadCsv}>
                    Download CSV
                  </Button>
                </Flex>
                <Box overflowX="auto">
                  <Table size="sm">
                    <Thead>
                      <Tr>
                        <Th>Employee ID</Th>
                        <Th>Name</Th>
                        <Th>Hours</Th>
                        <Th>Rate</Th>
                        <Th>Gross</Th>
                        <Th>Net</Th>
                      </Tr>
                    </Thead>
                    <Tbody>
                      {results.map((p: any) => (
                        <Tr key={p.staffId}>
                          <Td>{p.employeeId}</Td>
                          <Td>{p.name}</Td>
                          <Td>{p.hours}</Td>
                          <Td>£{p.hourlyRate}</Td>
                          <Td>£{p.grossPay}</Td>
                          <Td>£{p.netPay}</Td>
                        </Tr>
                      ))}
                    </Tbody>
                  </Table>
                </Box>
              </Box>
            )}
          </Stack>
        </ModalBody>
        <ModalFooter>
          <Button onClick={onClose}>Close</Button>
        </ModalFooter>
      </ModalContent>
    </Modal>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import {
  Box,
  Heading,
  Text,
  Card,
  CardBody,
  VStack,
  HStack,
  Button,
  useToast,
  Table,
  Thead,
  Tbody,
  Tr,
  Th,
  Td,
  Select,
  Stack,
  Flex,
  Spinner,
  Stat,
  StatLabel,
  StatNumber,
  StatHelpText,
  Grid,
  GridItem,
  Badge,
} from '@chakra-ui/react';
import { FiDownload, FiCalendar, FiTrendingUp } from 'react-icons/fi';

export default function AdminReportsPage() {
  const [report, setReport] = useState<any>(null);
  const [loading, setLoading] = useState(false);
  const [period, setPeriod] = useState('month');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const toast = useToast();

  useEffect(() => {
    fetchReport();
  }, [period, startDate, endDate]);

  const fetchReport = async () => {
    try {
      setLoading(true);
      const params = new URLSearchParams();
      params.append('period', period);
      if (startDate) params.append('startDate', startDate);
      if (endDate) params.append('endDate', endDate);

      const response = await fetch(`/api/admin/staff/attendance/reports?${params.toString()}`);
      const data = await response.json();

      if (data.success) {
        setReport(data.report);
      }
    } catch (error) {
      console.error('Error fetching report:', error);
      toast({
        title: 'Error',
        description: 'Failed to fetch report',
        status: 'error',
        duration: 3000,
      });
    } finally {
      setLoading(false);
    }
  };

  const handleExportCSV = () => {
    if (!report) return;

    const headers = ['Date', 'Staff', 'Employee ID', 'Check In', 'Check Out', 'Hours', 'Status'];
    const rows = report.attendances.map((a: any) => [
      new Date(a.date).toLocaleDateString(),
      a.Staff.User.name,
      a.Staff.employeeId,
      a.checkIn ? new Date(a.checkIn).toLocaleTimeString() : 'N/A',
      a.checkOut ? new Date(a.checkOut).toLocaleTimeString() : 'N/A',
      a.totalHours?.toFixed(2) || '0',
      a.status,
    ]);

    const csv = [headers, ...rows].map((row) => row.join(',')).join('\n');
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `attendance-report-${new Date().toISOString().split('T')[0]}.csv`;
    a.click();
  };

  const handleExportPDF = () => {
    toast({
      title: 'Info',
      description: 'PDF export functionality will be implemented',
      status: 'info',
      duration: 3000,
    });
  };

  if (loading && !report) {
    return (
      <Box p={6}>
        <Flex justify="center" align="center" minH="400px">
          <Spinner size="xl" />
        </Flex>
      </Box>
    );
  }

  return (
    <Box p={6}>
      <Flex justify="space-between" align="center" mb={6}>
        <Heading size="lg">Attendance Reports</Heading>
        <HStack>
          <Button leftIcon={<FiDownload />} onClick={handleExportCSV}>
            Export CSV
          </Button>
          <Button leftIcon={<FiDownload />} onClick={handleExportPDF}>
            Export PDF
          </Button>
        </HStack>
      </Flex>

      {/* Filters */}
      <Card mb={6}>
        <CardBody>
          <Stack direction={{ base: 'column', md: 'row' }} spacing={4}>
            <Select value={period} onChange={(e) => setPeriod(e.target.value)} maxW="200px">
              <option value="day">Today</option>
              <option value="week">Last 7 Days</option>
              <option value="month">Last 30 Days</option>
            </Select>
            <Box>
              <Text fontSize="sm" mb={1}>
                Start Date
              </Text>
              <input
                type="date"
                value={startDate}
                onChange={(e) => setStartDate(e.target.value)}
                style={{ padding: '8px', border: '1px solid #ccc', borderRadius: '4px' }}
              />
            </Box>
            <Box>
              <Text fontSize="sm" mb={1}>
                End Date
              </Text>
              <input
                type="date"
                value={endDate}
                onChange={(e) => setEndDate(e.target.value)}
                style={{ padding: '8px', border: '1px solid #ccc', borderRadius: '4px' }}
              />
            </Box>
          </Stack>
        </CardBody>
      </Card>

      {report && (
        <>
          {/* Summary Stats */}
          <Grid templateColumns={{ base: '1fr', md: 'repeat(4, 1fr)' }} gap={4} mb={6}>
            <Card>
              <CardBody>
                <Stat>
                  <StatLabel>Total Days</StatLabel>
                  <StatNumber>{report.summary.totalDays}</StatNumber>
                  <StatHelpText>
                    {report.startDate && new Date(report.startDate).toLocaleDateString()} -{' '}
                    {report.endDate && new Date(report.endDate).toLocaleDateString()}
                  </StatHelpText>
                </Stat>
              </CardBody>
            </Card>
            <Card>
              <CardBody>
                <Stat>
                  <StatLabel>Present Days</StatLabel>
                  <StatNumber>{report.summary.presentDays}</StatNumber>
                  <StatHelpText>
                    {report.summary.totalDays > 0
                      ? ((report.summary.presentDays / report.summary.totalDays) * 100).toFixed(1)
                      : 0}
                    % attendance rate
                  </StatHelpText>
                </Stat>
              </CardBody>
            </Card>
            <Card>
              <CardBody>
                <Stat>
                  <StatLabel>Total Hours</StatLabel>
                  <StatNumber>{report.summary.totalHours.toFixed(1)}</StatNumber>
                  <StatHelpText>Hours worked</StatHelpText>
                </Stat>
              </CardBody>
            </Card>
            <Card>
              <CardBody>
                <Stat>
                  <StatLabel>Late Days</StatLabel>
                  <StatNumber>{report.summary.lateDays}</StatNumber>
                  <StatHelpText>
                    {report.summary.earlyLeaveDays} early leaves
                  </StatHelpText>
                </Stat>
              </CardBody>
            </Card>
          </Grid>

          {/* By Staff Summary */}
          {report.byStaff && report.byStaff.length > 0 && (
            <Card mb={6}>
              <CardBody>
                <Heading size="md" mb={4}>
                  Summary by Staff
                </Heading>
                <Table variant="simple">
                  <Thead>
                    <Tr>
                      <Th>Staff</Th>
                      <Th>Total Days</Th>
                      <Th>Present</Th>
                      <Th>Absent</Th>
                      <Th>Late</Th>
                      <Th>Total Hours</Th>
                      <Th>Attendance Rate</Th>
                    </Tr>
                  </Thead>
                  <Tbody>
                    {report.byStaff.map((staff: any, idx: number) => (
                      <Tr key={idx}>
                        <Td>
                          <VStack align="start" spacing={0}>
                            <Text fontWeight="medium">
                              {staff.staff.User.name || 'N/A'}
                            </Text>
                            <Text fontSize="sm" color="gray.500">
                              {staff.staff.employeeId}
                            </Text>
                          </VStack>
                        </Td>
                        <Td>{staff.totalDays}</Td>
                        <Td>{staff.presentDays}</Td>
                        <Td>{staff.absentDays}</Td>
                        <Td>{staff.lateDays}</Td>
                        <Td>{staff.totalHours.toFixed(1)}h</Td>
                        <Td>
                          <Badge
                            colorScheme={staff.attendanceRate >= 95 ? 'green' : 'orange'}
                          >
                            {staff.attendanceRate.toFixed(1)}%
                          </Badge>
                        </Td>
                      </Tr>
                    ))}
                  </Tbody>
                </Table>
              </CardBody>
            </Card>
          )}

          {/* Detailed Records */}
          <Card>
            <CardBody>
              <Heading size="md" mb={4}>
                Detailed Records
              </Heading>
              <Table variant="simple">
                <Thead>
                  <Tr>
                    <Th>Date</Th>
                    <Th>Staff</Th>
                    <Th>Check In</Th>
                    <Th>Check Out</Th>
                    <Th>Hours</Th>
                    <Th>Status</Th>
                  </Tr>
                </Thead>
                <Tbody>
                  {report.attendances.length === 0 ? (
                    <Tr>
                      <Td colSpan={6} textAlign="center" py={8}>
                        <Text color="gray.500">No records found</Text>
                      </Td>
                    </Tr>
                  ) : (
                    report.attendances.map((attendance: any) => (
                      <Tr key={attendance.id}>
                        <Td>
                          {new Date(attendance.date).toLocaleDateString('en-GB')}
                        </Td>
                        <Td>
                          {attendance.Staff.User.name} ({attendance.Staff.employeeId})
                        </Td>
                        <Td>
                          {attendance.checkIn
                            ? new Date(attendance.checkIn).toLocaleTimeString('en-GB', {
                                hour: '2-digit',
                                minute: '2-digit',
                              })
                            : 'N/A'}
                        </Td>
                        <Td>
                          {attendance.checkOut
                            ? new Date(attendance.checkOut).toLocaleTimeString('en-GB', {
                                hour: '2-digit',
                                minute: '2-digit',
                              })
                            : 'N/A'}
                        </Td>
                        <Td>{attendance.totalHours?.toFixed(2) || '0'}h</Td>
                        <Td>
                          <Badge
                            colorScheme={
                              attendance.status === 'present'
                                ? 'green'
                                : attendance.status === 'absent'
                                ? 'red'
                                : 'orange'
                            }
                            textTransform="capitalize"
                          >
                            {attendance.status.replace('_', ' ')}
                          </Badge>
                        </Td>
                      </Tr>
                    ))
                  )}
                </Tbody>
              </Table>
            </CardBody>
          </Card>
        </>
      )}
    </Box>
  );
}

'use client';

import { useEffect, useState } from 'react';
import {
  Box,
  Container,
  VStack,
  HStack,
  Text,
  Heading,
  Card,
  CardBody,
  Badge,
  Button,
  useToast,
  useColorModeValue,
  Grid,
  GridItem,
  Code,
  List,
  ListItem,
  ListIcon,
  Spinner,
  Alert,
  AlertIcon,
  AlertTitle,
  AlertDescription,
} from '@chakra-ui/react';
import {
  FiWifi,
  FiWifiOff,
  FiCheckCircle,
  FiAlertCircle,
  FiRefreshCw,
  FiPlay,
  FiDatabase,
} from 'react-icons/fi';
import { useAdminRealTimeTracking } from '@/hooks/useRealTimeTracking';

interface DiagnosticData {
  timestamp: string;
  database: {
    connected: boolean;
    activeBookings: number;
    driversWithLocations: number;
    recentTrackingPings: number;
  };
  pusher: {
    configured: boolean;
    credentials: any;
    serverInstance: boolean;
  };
  realTimeFlow: {
    driverToAdmin: boolean;
    lastLocationUpdate: any;
    testChannelWorking: boolean;
  };
  recommendations: string[];
}

export default function AdminTrackingDiagnostics() {
  const [diagnosticData, setDiagnosticData] = useState<DiagnosticData | null>(null);
  const [loading, setLoading] = useState(true);
  const [testingChannel, setTestingChannel] = useState(false);
  const [simulatingUpdate, setSimulatingUpdate] = useState(false);
  const [realtimeMessages, setRealtimeMessages] = useState<any[]>([]);

  const toast = useToast();
  const bgColor = useColorModeValue('white', 'gray.800');

  // Real-time tracking hook with detailed logging
  const { isConnected, connectionStatus } = useAdminRealTimeTracking({
    onUpdate: update => {
      console.log('🔄 Diagnostic page received real-time update:', update);
      
      // Add to message log
      setRealtimeMessages(prev => [
        {
          timestamp: new Date().toISOString(),
          type: update.type,
          data: update,
        },
        ...prev.slice(0, 9) // Keep only last 10 messages
      ]);

      toast({
        title: 'Real-time Update Received!',
        description: `${update.type.toUpperCase()}: ${update.data?.bookingReference || update.bookingId}`,
        status: 'success',
        duration: 3000,
        isClosable: true,
      });
    },
  });

  useEffect(() => {
    loadDiagnostics();
  }, []);

  const loadDiagnostics = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/admin/tracking-diagnostics');
      if (response.ok) {
        const data = await response.json();
        setDiagnosticData(data.diagnostics);
      } else {
        throw new Error('Failed to load diagnostics');
      }
    } catch (error) {
      console.error('Error loading diagnostics:', error);
      toast({
        title: 'Error',
        description: 'Failed to load diagnostic data',
        status: 'error',
        duration: 3000,
        isClosable: true,
      });
    } finally {
      setLoading(false);
    }
  };

  const testAdminChannel = async () => {
    try {
      setTestingChannel(true);
      const response = await fetch('/api/admin/tracking-diagnostics', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'test-admin-channel' }),
      });

      if (response.ok) {
        toast({
          title: 'Test Sent',
          description: 'Test message sent to admin-tracking channel. Check console for received message.',
          status: 'info',
          duration: 3000,
          isClosable: true,
        });
      }
    } catch (error) {
      console.error('Error testing channel:', error);
      toast({
        title: 'Error',
        description: 'Failed to send test message',
        status: 'error',
        duration: 3000,
        isClosable: true,
      });
    } finally {
      setTestingChannel(false);
    }
  };

  const simulateLocationUpdate = async () => {
    try {
      setSimulatingUpdate(true);
      const response = await fetch('/api/admin/tracking-diagnostics', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'simulate-location-update' }),
      });

      if (response.ok) {
        const data = await response.json();
        toast({
          title: 'Location Update Simulated',
          description: `Simulated update for booking: ${data.booking?.reference}`,
          status: 'success',
          duration: 3000,
          isClosable: true,
        });
      }
    } catch (error) {
      console.error('Error simulating update:', error);
      toast({
        title: 'Error',
        description: 'Failed to simulate location update',
        status: 'error',
        duration: 3000,
        isClosable: true,
      });
    } finally {
      setSimulatingUpdate(false);
    }
  };

  if (loading) {
    return (
      <Container maxW="container.xl" py={8}>
        <VStack spacing={8} align="stretch">
          <Heading size="lg">Admin Tracking Diagnostics</Heading>
          <Spinner size="xl" />
        </VStack>
      </Container>
    );
  }

  return (
    <Container maxW="container.xl" py={8}>
      <VStack spacing={8} align="stretch">
        {/* Header */}
        <HStack justify="space-between" align="center">
          <VStack align="start" spacing={2}>
            <Heading size="lg">Admin Tracking Diagnostics</Heading>
            <Text color="gray.600">
              Monitor real-time tracking system health and connectivity
            </Text>
          </VStack>
          <Button
            leftIcon={<FiRefreshCw />}
            onClick={loadDiagnostics}
            isLoading={loading}
          >
            Refresh
          </Button>
        </HStack>

        {/* Connection Status */}
        <Card>
          <CardBody>
            <VStack align="start" spacing={4}>
              <Heading size="md">Real-time Connection Status</Heading>
              <HStack>
                {isConnected ? (
                  <>
                    <FiWifi color="green" size={24} />
                    <Badge colorScheme="green">Connected</Badge>
                    <Text>Admin dashboard is receiving real-time updates</Text>
                  </>
                ) : (
                  <>
                    <FiWifiOff color="red" size={24} />
                    <Badge colorScheme="red">Disconnected</Badge>
                    <Text>Admin dashboard is NOT receiving real-time updates</Text>
                  </>
                )}
              </HStack>
            </VStack>
          </CardBody>
        </Card>

        {/* System Health */}
        <Grid templateColumns={{ base: '1fr', md: '1fr 1fr' }} gap={6}>
          <Card>
            <CardBody>
              <VStack align="start" spacing={4}>
                <HStack>
                  <FiDatabase />
                  <Heading size="md">Database Status</Heading>
                </HStack>
                {diagnosticData && (
                  <VStack align="start" spacing={2}>
                    <HStack>
                      <FiCheckCircle color="green" />
                      <Text>Active Bookings: {diagnosticData.database.activeBookings}</Text>
                    </HStack>
                    <HStack>
                      <FiCheckCircle color="green" />
                      <Text>Drivers with Jobs: {diagnosticData.database.driversWithLocations}</Text>
                    </HStack>
                    <HStack>
                      <FiCheckCircle color="green" />
                      <Text>Recent Location Pings: {diagnosticData.database.recentTrackingPings}</Text>
                    </HStack>
                  </VStack>
                )}
              </VStack>
            </CardBody>
          </Card>

          <Card>
            <CardBody>
              <VStack align="start" spacing={4}>
                <HStack>
                  <FiWifi />
                  <Heading size="md">Pusher Configuration</Heading>
                </HStack>
                {diagnosticData && (
                  <VStack align="start" spacing={2}>
                    <HStack>
                      {diagnosticData.pusher.configured ? (
                        <FiCheckCircle color="green" />
                      ) : (
                        <FiAlertCircle color="red" />
                      )}
                      <Text>
                        Pusher: {diagnosticData.pusher.configured ? 'Configured' : 'Not Configured'}
                      </Text>
                    </HStack>
                    <HStack>
                      {diagnosticData.pusher.serverInstance ? (
                        <FiCheckCircle color="green" />
                      ) : (
                        <FiAlertCircle color="red" />
                      )}
                      <Text>
                        Server Instance: {diagnosticData.pusher.serverInstance ? 'Active' : 'Inactive'}
                      </Text>
                    </HStack>
                  </VStack>
                )}
              </VStack>
            </CardBody>
          </Card>
        </Grid>

        {/* Test Controls */}
        <Card>
          <CardBody>
            <VStack align="start" spacing={4}>
              <Heading size="md">Real-time Testing</Heading>
              <HStack spacing={4}>
                <Button
                  leftIcon={<FiPlay />}
                  onClick={testAdminChannel}
                  isLoading={testingChannel}
                  colorScheme="blue"
                >
                  Test Admin Channel
                </Button>
                <Button
                  leftIcon={<FiPlay />}
                  onClick={simulateLocationUpdate}
                  isLoading={simulatingUpdate}
                  colorScheme="green"
                >
                  Simulate Driver Location Update
                </Button>
              </HStack>
              <Text fontSize="sm" color="gray.600">
                Use these buttons to test real-time connectivity. Messages should appear in the log below.
              </Text>
            </VStack>
          </CardBody>
        </Card>

        {/* Real-time Message Log */}
        <Card>
          <CardBody>
            <VStack align="start" spacing={4}>
              <Heading size="md">Real-time Message Log</Heading>
              {realtimeMessages.length === 0 ? (
                <Text color="gray.500">No real-time messages received yet</Text>
              ) : (
                <VStack align="start" spacing={2} w="100%">
                  {realtimeMessages.map((message, index) => (
                    <Box key={index} p={3} bg={bgColor} borderRadius="md" w="100%">
                      <HStack justify="space-between">
                        <Badge colorScheme={message.type === 'location' ? 'green' : 'blue'}>
                          {message.type}
                        </Badge>
                        <Text fontSize="sm" color="gray.500">
                          {new Date(message.timestamp).toLocaleTimeString()}
                        </Text>
                      </HStack>
                      <Code fontSize="sm" mt={2}>
                        {JSON.stringify(message.data, null, 2).slice(0, 200)}...
                      </Code>
                    </Box>
                  ))}
                </VStack>
              )}
            </VStack>
          </CardBody>
        </Card>

        {/* Recommendations */}
        {diagnosticData && diagnosticData.recommendations.length > 0 && (
          <Alert status="warning">
            <AlertIcon />
            <Box>
              <AlertTitle>Issues Detected</AlertTitle>
              <AlertDescription>
                <List spacing={1} mt={2}>
                  {diagnosticData.recommendations.map((rec, index) => (
                    <ListItem key={index}>
                      <ListIcon as={FiAlertCircle} color="orange.500" />
                      {rec}
                    </ListItem>
                  ))}
                </List>
              </AlertDescription>
            </Box>
          </Alert>
        )}
      </VStack>
    </Container>
  );
}

'use client';

import { useEffect, useState, useRef } from 'react';
import {
  Box,
  Container,
  VStack,
  HStack,
  Text,
  Heading,
  Card,
  CardBody,
  Badge,
  Spinner,
  useToast,
  useColorModeValue,
  Grid,
  GridItem,
  Select,
  Input,
  Button,
  IconButton,
  Tooltip,
  Flex,
  Stat,
  StatLabel,
  StatNumber,
  StatHelpText,
  Progress,
  Divider,
  Alert,
  AlertIcon,
  Tabs,
  TabList,
  TabPanels,
  Tab,
  TabPanel,
  List,
  ListItem,
  ListIcon,
  Modal,
  ModalOverlay,
  ModalContent,
  ModalHeader,
  ModalBody,
  ModalCloseButton,
  useDisclosure,
} from '@chakra-ui/react';
import {
  FiMapPin,
  FiClock,
  FiTruck,
  FiRefreshCw,
  FiSearch,
  FiFilter,
  FiEye,
  FiNavigation,
  FiWifi,
  FiWifiOff,
  FiCheckCircle,
  FiAlertCircle,
  FiInfo,
  FiMap,
} from 'react-icons/fi';
import dynamic from 'next/dynamic';
import { useAdminRealTimeTracking } from '@/hooks/useRealTimeTracking';

const LiveMap = dynamic(() => import('@/components/Map/LiveMap'), {
  ssr: false,
});

interface TrackingBooking {
  id: string;
  reference: string;
  unifiedBookingId?: string;
  status: string;
  scheduledAt: string;
  customer: {
    name: string;
    email: string;
    phone: string;
  };
  driver?: {
    id: string;
    name: string;
    email: string;
  };
  addresses: {
    pickup: {
      label: string;
      postcode: string;
      coordinates: { lat: number; lng: number };
    };
    dropoff: {
      label: string;
      postcode: string;
      coordinates: { lat: number; lng: number };
    };
  };
  routeProgress: number;
  currentLocation?: {
    lat: number;
    lng: number;
    timestamp: string;
  };
  eta?: {
    estimatedArrival: string;
    minutesRemaining: number;
    isOnTime: boolean;
  };
  lastEvent?: {
    step: string;
    createdAt: string;
    notes?: string;
  };
  jobTimeline: Array<{
    step: string;
    label: string;
    timestamp: string;
    notes?: string;
  }>;
  trackingPings: Array<{
    lat: number;
    lng: number;
    createdAt: string;
  }>;
  lastUpdated: string;
}

export default function EnhancedTrackingDashboard() {
  const [bookings, setBookings] = useState<TrackingBooking[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedBooking, setSelectedBooking] =
    useState<TrackingBooking | null>(null);
  const [filterStatus, setFilterStatus] = useState<string>('all');
  const [searchQuery, setSearchQuery] = useState('');
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [lastUpdate, setLastUpdate] = useState<Date | null>(null);
  const [viewMode, setViewMode] = useState<'list' | 'map'>('list');

  const toast = useToast();
  const bgColor = useColorModeValue('white', 'gray.800');
  const borderColor = useColorModeValue('gray.200', 'gray.600');
  const intervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const { isOpen, onOpen, onClose } = useDisclosure();

  // Real-time tracking hook
  const { isConnected, connectionStatus } = useAdminRealTimeTracking({
    onUpdate: update => {
      console.log('🔄 Admin dashboard received real-time update:', update);
      
      // Handle different types of updates
      if (update.type === 'location') {
        // Update booking location in real-time
        setBookings(prevBookings => 
          prevBookings.map(booking => {
            if (booking.id === update.bookingId) {
              return {
                ...booking,
                currentLocation: {
                  lat: update.location.lat,
                  lng: update.location.lng,
                  timestamp: update.timestamp.toISOString(),
                },
                lastUpdated: update.timestamp.toISOString(),
              };
            }
            return booking;
          })
        );

        // Show toast for location updates (less frequent)
        toast({
          title: 'Driver Location Updated',
          description: `Driver location updated for booking ${update.data.bookingReference}`,
          status: 'info',
          duration: 2000,
          isClosable: true,
        });
      }
      
      if (update.type === 'status') {
        toast({
          title: 'Status Update',
          description: `Booking ${update.bookingId} status changed`,
          status: 'info',
          duration: 3000,
          isClosable: true,
        });
        
        // Refresh data for status changes
        loadTrackingData();
      }

      if (update.type === 'progress') {
        toast({
          title: 'Progress Update',
          description: `Job progress updated: ${update.data.stepLabel || update.data.step}`,
          status: 'info',
          duration: 3000,
          isClosable: true,
        });
        
        // Refresh data for progress changes
        loadTrackingData();
      }
    },
    onLocationUpdate: location => {
      console.log('📍 Admin dashboard received location update:', location);
    }
  });

  useEffect(() => {
    loadTrackingData();

    // Set up auto-refresh every 30 seconds
    intervalRef.current = setInterval(() => {
      loadTrackingData();
    }, 30000);

    return () => {
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
      }
    };
  }, []);

  const loadTrackingData = async () => {
    try {
      setIsRefreshing(true);

      const response = await fetch('/api/admin/tracking?includeTracking=true');
      if (response.ok) {
        const data = await response.json();
        setBookings(data.bookings || []);
        setLastUpdate(new Date());
      } else {
        throw new Error('Failed to load tracking data');
      }
    } catch (error) {
      console.error('Error loading tracking data:', error);
      toast({
        title: 'Error Loading Data',
        description: 'Failed to load tracking information',
        status: 'error',
        duration: 3000,
        isClosable: true,
      });
    } finally {
      setLoading(false);
      setIsRefreshing(false);
    }
  };

  const filteredBookings = bookings.filter(booking => {
    const matchesStatus =
      filterStatus === 'all' || booking.status === filterStatus;
    const matchesSearch =
      searchQuery === '' ||
      booking.reference.toLowerCase().includes(searchQuery.toLowerCase()) ||
      booking.unifiedBookingId
        ?.toLowerCase()
        .includes(searchQuery.toLowerCase()) ||
      booking.customer.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      booking.customer.email
        .toLowerCase()
        .includes(searchQuery.toLowerCase()) ||
      (booking.driver?.name || '')
        .toLowerCase()
        .includes(searchQuery.toLowerCase());

    return matchesStatus && matchesSearch;
  });

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'CONFIRMED':
        return 'blue';
      case 'IN_PROGRESS':
        return 'orange';
      case 'COMPLETED':
        return 'green';
      case 'CANCELLED':
        return 'red';
      default:
        return 'gray';
    }
  };

  const getStepLabel = (step: string) => {
    switch (step) {
      case 'navigate_to_pickup':
        return 'En Route to Pickup';
      case 'arrived_at_pickup':
        return 'Arrived at Pickup';
      case 'loading_started':
        return 'Loading Started';
      case 'loading_completed':
        return 'Loading Completed';
      case 'en_route_to_dropoff':
        return 'En Route to Delivery';
      case 'arrived_at_dropoff':
        return 'Arrived at Delivery';
      case 'unloading_started':
        return 'Unloading Started';
      case 'unloading_completed':
        return 'Unloading Completed';
      case 'job_completed':
        return 'Job Completed';
      default:
        return step;
    }
  };

  const formatTime = (dateString: string) => {
    return new Date(dateString).toLocaleString('en-GB', {
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
  };

  const openBookingDetails = (booking: TrackingBooking) => {
    setSelectedBooking(booking);
    onOpen();
  };

  if (loading) {
    return (
      <Container maxW="container.xl" py={8}>
        <VStack spacing={8} align="stretch">
          <Heading size="lg">Enhanced Tracking Dashboard</Heading>
          <Flex justify="center" align="center" minH="400px">
            <Spinner size="xl" />
          </Flex>
        </VStack>
      </Container>
    );
  }

  const activeBookings = filteredBookings.filter(
    b => b.status === 'IN_PROGRESS'
  );
  const confirmedBookings = filteredBookings.filter(
    b => b.status === 'CONFIRMED'
  );
  const withLiveTracking = filteredBookings.filter(
    b => b.currentLocation
  ).length;
  const averageProgress =
    filteredBookings.length > 0
      ? Math.round(
          filteredBookings.reduce((sum, b) => sum + b.routeProgress, 0) /
            filteredBookings.length
        )
      : 0;

  return (
    <Container maxW="container.xl" py={8}>
      <VStack spacing={8} align="stretch">
        {/* Header */}
        <Flex justify="space-between" align="center">
          <VStack align="start" spacing={2}>
            <Heading size="lg">Enhanced Tracking Dashboard</Heading>
            <Text color="gray.600">
              Real-time monitoring of all active deliveries with comprehensive
              tracking
            </Text>
          </VStack>
          <HStack spacing={4}>
            <HStack spacing={2}>
              {isConnected ? (
                <FiWifi color="green" />
              ) : (
                <FiWifiOff color="red" />
              )}
              <Text fontSize="sm">
                {isConnected ? 'Real-time connected' : 'Real-time disconnected'}
              </Text>
            </HStack>
            <Text fontSize="sm" color="gray.500">
              <span suppressHydrationWarning>
                Last updated: {lastUpdate?.toLocaleTimeString()}
              </span>
            </Text>
            <Tooltip label="Refresh data">
              <IconButton
                aria-label="Refresh"
                icon={<FiRefreshCw />}
                onClick={loadTrackingData}
                isLoading={isRefreshing}
                size="sm"
              />
            </Tooltip>
          </HStack>
        </Flex>

        {/* Stats Cards */}
        <Grid templateColumns="repeat(auto-fit, minmax(200px, 1fr))" gap={6}>
          <Card>
            <CardBody>
              <Stat>
                <StatLabel>Total Active</StatLabel>
                <StatNumber>{filteredBookings.length}</StatNumber>
                <StatHelpText>Currently being processed</StatHelpText>
              </Stat>
            </CardBody>
          </Card>
          <Card>
            <CardBody>
              <Stat>
                <StatLabel>In Progress</StatLabel>
                <StatNumber>{activeBookings.length}</StatNumber>
                <StatHelpText>Currently being delivered</StatHelpText>
              </Stat>
            </CardBody>
          </Card>
          <Card>
            <CardBody>
              <Stat>
                <StatLabel>Live Tracking</StatLabel>
                <StatNumber>{withLiveTracking}</StatNumber>
                <StatHelpText>With real-time location</StatHelpText>
              </Stat>
            </CardBody>
          </Card>
          <Card>
            <CardBody>
              <Stat>
                <StatLabel>Avg Progress</StatLabel>
                <StatNumber>{averageProgress}%</StatNumber>
                <StatHelpText>Route completion</StatHelpText>
              </Stat>
            </CardBody>
          </Card>
        </Grid>

        {/* Filters and Search */}
        <Card>
          <CardBody>
            <VStack spacing={4} align="stretch">
              <HStack justify="space-between">
                <Text fontWeight="medium">Filters & Search</Text>
                <HStack spacing={2}>
                  <Button
                    size="sm"
                    variant={viewMode === 'list' ? 'solid' : 'outline'}
                    onClick={() => setViewMode('list')}
                    leftIcon={<FiEye />}
                  >
                    List View
                  </Button>
                  <Button
                    size="sm"
                    variant={viewMode === 'map' ? 'solid' : 'outline'}
                    onClick={() => setViewMode('map')}
                    leftIcon={<FiMap />}
                  >
                    Map View
                  </Button>
                </HStack>
              </HStack>

              <HStack spacing={4} wrap="wrap">
                <Box>
                  <Text fontSize="sm" mb={2}>
                    Status Filter
                  </Text>
                  <Select
                    value={filterStatus}
                    onChange={e => setFilterStatus(e.target.value)}
                    size="sm"
                    w="150px"
                  >
                    <option value="all">All Status</option>
                    <option value="CONFIRMED">Confirmed</option>
                    <option value="IN_PROGRESS">In Progress</option>
                  </Select>
                </Box>
                <Box>
                  <Text fontSize="sm" mb={2}>
                    Search
                  </Text>
                  <Input
                    placeholder="Search bookings, IDs, customers..."
                    value={searchQuery}
                    onChange={e => setSearchQuery(e.target.value)}
                    size="sm"
                    w="300px"
                  />
                </Box>
              </HStack>
            </VStack>
          </CardBody>
        </Card>

        {/* Main Content */}
        {viewMode === 'list' ? (
          <VStack spacing={4} align="stretch">
            {filteredBookings.length === 0 ? (
              <Alert status="info">
                <AlertIcon />
                No active bookings found matching your criteria
              </Alert>
            ) : (
              filteredBookings.map(booking => (
                <Card
                  key={booking.id}
                  cursor="pointer"
                  onClick={() => openBookingDetails(booking)}
                  _hover={{ bg: 'gray.50' }}
                  border={`1px solid ${borderColor}`}
                >
                  <CardBody>
                    <Grid
                      templateColumns="1fr auto auto auto"
                      gap={4}
                      alignItems="center"
                    >
                      {/* Booking Info */}
                      <VStack align="start" spacing={2}>
                        <HStack spacing={3}>
                          <Text fontWeight="bold" fontSize="lg">
                            {booking.reference}
                          </Text>
                          {booking.unifiedBookingId && (
                            <Badge colorScheme="purple" variant="outline">
                              {booking.unifiedBookingId}
                            </Badge>
                          )}
                          <Badge colorScheme={getStatusColor(booking.status)}>
                            {booking.status}
                          </Badge>
                        </HStack>

                        <VStack align="start" spacing={1}>
                          <Text fontSize="sm" color="gray.600">
                            <strong>Customer:</strong> {booking.customer.name} (
                            {booking.customer.email})
                          </Text>
                          <Text fontSize="sm" color="gray.600">
                            <strong>Pickup:</strong>{' '}
                            {booking.addresses.pickup.label}
                          </Text>
                          <Text fontSize="sm" color="gray.600">
                            <strong>Delivery:</strong>{' '}
                            {booking.addresses.dropoff.label}
                          </Text>
                        </VStack>
                      </VStack>

                      {/* Driver Info */}
                      <VStack align="center" spacing={1}>
                        <Text fontSize="sm" fontWeight="medium">
                          Driver
                        </Text>
                        {booking.driver ? (
                          <Text fontSize="sm" color="blue.600">
                            {booking.driver.name}
                          </Text>
                        ) : (
                          <Text fontSize="sm" color="gray.500">
                            Unassigned
                          </Text>
                        )}
                      </VStack>

                      {/* Progress */}
                      <VStack align="center" spacing={1}>
                        <Text fontSize="sm" fontWeight="medium">
                          Progress
                        </Text>
                        <Progress
                          value={booking.routeProgress}
                          size="sm"
                          colorScheme="blue"
                          w="80px"
                        />
                        <Text fontSize="xs" color="gray.600">
                          {booking.routeProgress}%
                        </Text>
                      </VStack>

                      {/* ETA & Tracking */}
                      <VStack align="center" spacing={1}>
                        {booking.eta ? (
                          <>
                            <Text fontSize="sm" fontWeight="medium">
                              ETA
                            </Text>
                            <Text fontSize="sm" color="blue.600">
                              {booking.eta.minutesRemaining}m
                            </Text>
                            <Badge
                              colorScheme={
                                booking.eta.isOnTime ? 'green' : 'orange'
                              }
                              size="sm"
                            >
                              {booking.eta.isOnTime ? 'On Time' : 'Delayed'}
                            </Badge>
                          </>
                        ) : (
                          <>
                            <Text fontSize="sm" fontWeight="medium">
                              Scheduled
                            </Text>
                            <Text fontSize="sm" color="gray.600">
                              {formatTime(booking.scheduledAt)}
                            </Text>
                          </>
                        )}

                        {booking.currentLocation && (
                          <Badge colorScheme="green" size="sm">
                            Live Tracking
                          </Badge>
                        )}
                      </VStack>
                    </Grid>
                  </CardBody>
                </Card>
              ))
            )}
          </VStack>
        ) : (
          /* Map View */
          <Card>
            <CardBody>
              <VStack spacing={4} align="stretch">
                <Heading size="md">Live Map View</Heading>
                <Box h="600px" borderRadius="md" overflow="hidden">
                  <LiveMap
                    driverLocations={filteredBookings
                      .filter(b => b.currentLocation)
                      .map(b => ({
                        driverId: b.driver?.id || 'unknown',
                        driverName: b.driver?.name || 'Unknown',
                        lat: b.currentLocation!.lat,
                        lng: b.currentLocation!.lng,
                        label: `${b.driver?.name || 'Unknown'} - ${b.reference}`,
                        lastUpdate: b.currentLocation!.timestamp,
                        status: b.status,
                      }))}
                    pickupLocation={
                      selectedBooking?.currentLocation && selectedBooking.addresses.pickup.coordinates
                        ? {
                            lat: selectedBooking.addresses.pickup.coordinates
                              .lat,
                            lng: selectedBooking.addresses.pickup.coordinates
                              .lng,
                            label: 'Pickup Location',
                          }
                        : {
                            lat: 0,
                            lng: 0,
                            label: 'Pickup Location',
                          }
                    }
                    dropoffLocation={
                      selectedBooking?.currentLocation && selectedBooking.addresses.dropoff.coordinates
                        ? {
                            lat: selectedBooking.addresses.dropoff.coordinates
                              .lat,
                            lng: selectedBooking.addresses.dropoff.coordinates
                              .lng,
                            label: 'Dropoff Location',
                          }
                        : {
                            lat: 0,
                            lng: 0,
                            label: 'Dropoff Location',
                          }
                    }
                  />
                </Box>
              </VStack>
            </CardBody>
          </Card>
        )}

        {/* Booking Details Modal */}
        <Modal isOpen={isOpen} onClose={onClose} size="xl">
          <ModalOverlay />
          <ModalContent>
            <ModalHeader>
              Booking Details: {selectedBooking?.reference}
            </ModalHeader>
            <ModalCloseButton />
            <ModalBody pb={6}>
              {selectedBooking && (
                <VStack spacing={4} align="stretch">
                  {/* Basic Info */}
                  <Grid templateColumns="repeat(2, 1fr)" gap={4}>
                    <Box>
                      <Text fontWeight="bold" mb={2}>
                        Customer
                      </Text>
                      <Text>{selectedBooking.customer.name}</Text>
                      <Text fontSize="sm" color="gray.600">
                        {selectedBooking.customer.email}
                      </Text>
                      <Text fontSize="sm" color="gray.600">
                        {selectedBooking.customer.phone}
                      </Text>
                    </Box>

                    {selectedBooking.driver && (
                      <Box>
                        <Text fontWeight="bold" mb={2}>
                          Driver
                        </Text>
                        <Text>{selectedBooking.driver.name}</Text>
                        <Text fontSize="sm" color="gray.600">
                          {selectedBooking.driver.email}
                        </Text>
                      </Box>
                    )}
                  </Grid>

                  {/* Route Progress */}
                  <Box>
                    <Text fontWeight="bold" mb={2}>
                      Route Progress
                    </Text>
                    <Progress
                      value={selectedBooking.routeProgress}
                      w="100%"
                      colorScheme="blue"
                      mb={2}
                    />
                    <Text fontSize="sm">
                      {selectedBooking.routeProgress}% complete
                    </Text>
                  </Box>

                  {/* ETA */}
                  {selectedBooking.eta && (
                    <Box>
                      <Text fontWeight="bold" mb={2}>
                        Estimated Arrival
                      </Text>
                      <Text>
                        {selectedBooking.eta.minutesRemaining} minutes
                      </Text>
                      <Text fontSize="sm" color="gray.600">
                        {formatTime(selectedBooking.eta.estimatedArrival)}
                      </Text>
                      <Badge
                        colorScheme={
                          selectedBooking.eta.isOnTime ? 'green' : 'orange'
                        }
                        mt={2}
                      >
                        {selectedBooking.eta.isOnTime ? 'On Time' : 'Delayed'}
                      </Badge>
                    </Box>
                  )}

                  {/* Job Timeline */}
                  {selectedBooking.jobTimeline.length > 0 && (
                    <Box>
                      <Text fontWeight="bold" mb={2}>
                        Job Timeline
                      </Text>
                      <List spacing={2}>
                        {selectedBooking.jobTimeline.map((event, index) => (
                          <ListItem key={index}>
                            <HStack spacing={3}>
                              <ListIcon as={FiCheckCircle} color="green.500" />
                              <VStack align="start" spacing={1} flex={1}>
                                <Text fontWeight="medium">{event.label}</Text>
                                <Text fontSize="sm" color="gray.600">
                                  {formatTime(event.timestamp)}
                                </Text>
                                {event.notes && (
                                  <Text
                                    fontSize="sm"
                                    color="gray.500"
                                    fontStyle="italic"
                                  >
                                    {event.notes}
                                  </Text>
                                )}
                              </VStack>
                            </HStack>
                          </ListItem>
                        ))}
                      </List>
                    </Box>
                  )}

                  {/* Live Location */}
                  {selectedBooking.currentLocation && (
                    <Box>
                      <Text fontWeight="bold" mb={2}>
                        Current Location
                      </Text>
                      <Text fontSize="sm">
                        {selectedBooking.currentLocation.lat.toFixed(6)},{' '}
                        {selectedBooking.currentLocation.lng.toFixed(6)}
                      </Text>
                      <Text fontSize="sm" color="gray.600">
                        Last updated:{' '}
                        {formatTime(selectedBooking.currentLocation.timestamp)}
                      </Text>
                    </Box>
                  )}
                </VStack>
              )}
            </ModalBody>
          </ModalContent>
        </Modal>
      </VStack>
    </Container>
  );
}

'use client';

import { useEffect, useState, useRef } from 'react';
import {
  Box,
  Container,
  VStack,
  HStack,
  Text,
  Heading,
  Card,
  CardBody,
  Badge,
  Spinner,
  useToast,
  useColorModeValue,
  Grid,
  GridItem,
  Select,
  Input,
  Button,
  IconButton,
  Tooltip,
  Flex,
  Stat,
  StatLabel,
  StatNumber,
  StatHelpText,
  Progress,
  Divider,
  Alert,
  AlertIcon,
} from '@chakra-ui/react';
import {
  FiMapPin,
  FiClock,
  FiTruck,
  FiRefreshCw,
  FiSearch,
  FiFilter,
  FiEye,
  FiNavigation,
  FiWifi,
  FiWifiOff,
} from 'react-icons/fi';
import dynamic from 'next/dynamic';
import { useAdminRealTimeTracking } from '@/hooks/useRealTimeTracking';

const LiveMap = dynamic(() => import('@/components/Map/MapboxLiveMap'), {
  ssr: false,
});

interface TrackingBooking {
  id: string;
  reference: string;
  status: string;
  addresses: {
    pickup: {
      label: string;
      postcode: string;
      coordinates: { lat: number; lng: number };
    };
    dropoff: {
      label: string;
      postcode: string;
      coordinates: { lat: number; lng: number };
    };
  };
  properties?: {
    pickup?: {
      type: string;
      floors: number;
      hasElevator: boolean;
      buildingTypeDisplay: string;
    };
    dropoff?: {
      type: string;
      floors: number;
      hasElevator: boolean;
      buildingTypeDisplay: string;
    };
  };
  scheduledAt: string;
  driver?: {
    id: string;
    name: string;
    email: string;
  };
  customer: {
    id: string;
    name: string;
    email: string;
  };
  routeProgress: number;
  currentLocation?: {
    lat: number;
    lng: number;
    timestamp: string;
  };
  eta?: {
    estimatedArrival: string;
    minutesRemaining: number;
  };
  lastEvent?: {
    step: string;
    createdAt: string;
    notes?: string;
  };
  trackingPings: Array<{
    id: string;
    lat: number;
    lng: number;
    createdAt: string;
  }>;
}

interface DriverLocation {
  driverId: string;
  driverName: string;
  lat: number;
  lng: number;
  label: string;
  lastUpdate: string;
  status: string;
}

export default function TrackingHub() {
  const [bookings, setBookings] = useState<TrackingBooking[]>([]);
  const [driverLocations, setDriverLocations] = useState<DriverLocation[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedBooking, setSelectedBooking] =
    useState<TrackingBooking | null>(null);
  const [filterStatus, setFilterStatus] = useState<string>('all');
  const [searchQuery, setSearchQuery] = useState('');
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [lastUpdate, setLastUpdate] = useState<Date | null>(null);

  const toast = useToast();
  const bgColor = 'gray.800';
  const borderColor = useColorModeValue('gray.200', 'gray.600');
  const intervalRef = useRef<ReturnType<typeof setInterval> | null>(null);

  // Real-time tracking hook
  const { isConnected } = useAdminRealTimeTracking({
    onUpdate: update => {
      console.log('🔄 Admin tracking received real-time update:', update);
      
      if (update.type === 'location') {
        // Update driver locations in real-time
        setDriverLocations(prevLocations => 
          prevLocations.map(loc => {
            if (loc.driverId === update.driverId) {
              return {
                ...loc,
                lat: update.location.lat,
                lng: update.location.lng,
                lastUpdate: update.timestamp.toISOString(),
              };
            }
            return loc;
          })
        );

        // Update booking locations
        setBookings(prevBookings => 
          prevBookings.map(booking => {
            if (booking.id === update.bookingId) {
              return {
                ...booking,
                currentLocation: {
                  lat: update.location.lat,
                  lng: update.location.lng,
                  timestamp: update.timestamp.toISOString(),
                },
              };
            }
            return booking;
          })
        );
      }
    },
  });

  useEffect(() => {
    loadTrackingData();

    // Set up auto-refresh every 30 seconds
    intervalRef.current = setInterval(() => {
      loadTrackingData();
    }, 30000);

    // Set up Pusher for real-time route updates
    if (typeof window !== 'undefined' && (window as any).Pusher) {
      const PUSHER_KEY = '407cb06c423e6c032e9c';
      const PUSHER_CLUSTER = 'eu';
      const pusher = new (window as any).Pusher(PUSHER_KEY, {
        cluster: PUSHER_CLUSTER,
      });

      const channel = pusher.subscribe('admin-channel');

      // Listen for route accepted events
      channel.bind('route-accepted', (data: any) => {
        console.log('🎉 Route accepted notification:', data);
        toast({
          title: 'New Route Accepted',
          description: `${data.driverName} accepted a route with ${data.dropCount} stops`,
          status: 'success',
          duration: 5000,
          isClosable: true,
        });
        loadTrackingData();
      });

      // Listen for route completed events
      channel.bind('route-completed', (data: any) => {
        console.log('✅ Route completed notification:', data);
        toast({
          title: 'Route Completed',
          description: `${data.driverName} completed a route with ${data.totalDrops} stops`,
          status: 'success',
          duration: 5000,
          isClosable: true,
        });
        loadTrackingData();
      });

      // Listen for drop completed events
      channel.bind('drop-completed', (data: any) => {
        console.log('📦 Drop completed notification:', data);
        loadTrackingData();
      });

      intervalRef.current = setInterval(() => {
        loadTrackingData();
      }, 30000) as any;

      return () => {
        channel.unbind_all();
        channel.unsubscribe();
        if (intervalRef.current) {
          clearInterval(intervalRef.current);
        }
      };
    }

    return () => {
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
      }
    };
  }, [toast]);

  const loadTrackingData = async () => {
    try {
      setIsRefreshing(true);

      // Load real-time dispatch data
      const response = await fetch('/api/admin/dispatch/realtime');
      if (response.ok) {
        const data = await response.json();
        const locations = (data.data.driverLocations || []).map((loc: any) => ({
          ...loc,
          label: `${loc.driverName} - ${loc.status}`,
        }));
        setDriverLocations(locations);
      }

      // Load active bookings with tracking data
      const bookingsResponse = await fetch(
        '/api/admin/orders?status=active&includeTracking=true'
      );
      if (bookingsResponse.ok) {
        const bookingsData = await bookingsResponse.json();
        setBookings(bookingsData.bookings || []);
      }

      setLastUpdate(new Date());
    } catch (error) {
      console.error('Error loading tracking data:', error);
      toast({
        title: 'Error Loading Data',
        description: 'Failed to load tracking information',
        status: 'error',
        duration: 3000,
        isClosable: true,
      });
    } finally {
      setLoading(false);
      setIsRefreshing(false);
    }
  };

  const loadBookingDetails = async (bookingCode: string) => {
    try {
      const response = await fetch(`/api/admin/orders/${bookingCode}/tracking`);
      if (response.ok) {
        const data = await response.json();
        setSelectedBooking(data.booking);
      }
    } catch (error) {
      console.error('Error loading booking details:', error);
      toast({
        title: 'Error Loading Details',
        description: 'Failed to load booking tracking details',
        status: 'error',
        duration: 3000,
        isClosable: true,
      });
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'CONFIRMED':
        return 'blue';
      case 'IN_PROGRESS':
        return 'orange';
      case 'COMPLETED':
        return 'green';
      case 'CANCELLED':
        return 'red';
      default:
        return 'gray';
    }
  };

  const getStepLabel = (step: string) => {
    switch (step) {
      case 'navigate_to_pickup':
        return 'En Route to Pickup';
      case 'arrived_at_pickup':
        return 'Arrived at Pickup';
      case 'loading_started':
        return 'Loading Started';
      case 'loading_completed':
        return 'Loading Completed';
      case 'en_route_to_dropoff':
        return 'En Route to Dropoff';
      case 'arrived_at_dropoff':
        return 'Arrived at Dropoff';
      case 'unloading_started':
        return 'Unloading Started';
      case 'unloading_completed':
        return 'Unloading Completed';
      case 'job_completed':
        return 'Job Completed';
      default:
        return step;
    }
  };

  const filteredBookings = bookings.filter(booking => {
    const matchesStatus =
      filterStatus === 'all' || booking.status === filterStatus;
    const matchesSearch =
      searchQuery === '' ||
      booking.reference.toLowerCase().includes(searchQuery.toLowerCase()) ||
      booking.addresses.pickup.label
        .toLowerCase()
        .includes(searchQuery.toLowerCase()) ||
      booking.addresses.dropoff.label
        .toLowerCase()
        .includes(searchQuery.toLowerCase()) ||
      (booking.driver?.name || '')
        .toLowerCase()
        .includes(searchQuery.toLowerCase());

    return matchesStatus && matchesSearch;
  });

  const activeDrivers = driverLocations.filter(
    driver => driver.status === 'online'
  );
  const totalBookings = bookings.length;
  const inProgressBookings = bookings.filter(
    b => b.status === 'IN_PROGRESS'
  ).length;

  if (loading) {
    return (
      <Container maxW="container.xl" py={8}>
        <VStack spacing={8} align="stretch">
          <Heading size="lg">Live Tracking Hub</Heading>
          <Flex justify="center" align="center" minH="400px">
            <Spinner size="xl" />
          </Flex>
        </VStack>
      </Container>
    );
  }

  return (
    <Container maxW="container.xl" py={8}>
      <VStack spacing={8} align="stretch">
        {/* Header */}
        <Flex justify="space-between" align="center">
          <VStack align="start" spacing={2}>
            <Heading size="lg">Live Tracking Hub</Heading>
            <Text color="gray.600">
              Real-time monitoring of all active deliveries and driver locations
            </Text>
          </VStack>
          <HStack spacing={4}>
            <HStack spacing={2}>
              {isConnected ? (
                <FiWifi color="green" />
              ) : (
                <FiWifiOff color="red" />
              )}
              <Text fontSize="sm">
                {isConnected ? 'Real-time connected' : 'Real-time disconnected'}
              </Text>
            </HStack>
            <Text fontSize="sm" color="gray.500">
              <span suppressHydrationWarning>
                Last updated: {lastUpdate?.toLocaleTimeString()}
              </span>
            </Text>
            <Tooltip label="Refresh data">
              <IconButton
                aria-label="Refresh"
                icon={<FiRefreshCw />}
                onClick={loadTrackingData}
                isLoading={isRefreshing}
                size="sm"
              />
            </Tooltip>
          </HStack>
        </Flex>

        {/* Stats Cards */}
        <Grid templateColumns="repeat(auto-fit, minmax(200px, 1fr))" gap={6}>
          <Card>
            <CardBody>
              <Stat>
                <StatLabel>Active Bookings</StatLabel>
                <StatNumber>{totalBookings}</StatNumber>
                <StatHelpText>Currently being processed</StatHelpText>
              </Stat>
            </CardBody>
          </Card>
          <Card>
            <CardBody>
              <Stat>
                <StatLabel>In Progress</StatLabel>
                <StatNumber>{inProgressBookings}</StatNumber>
                <StatHelpText>Currently being delivered</StatHelpText>
              </Stat>
            </CardBody>
          </Card>
          <Card>
            <CardBody>
              <Stat>
                <StatLabel>Online Drivers</StatLabel>
                <StatNumber>{activeDrivers.length}</StatNumber>
                <StatHelpText>Available for assignments</StatHelpText>
              </Stat>
            </CardBody>
          </Card>
          <Card>
            <CardBody>
              <Stat>
                <StatLabel>Tracking Coverage</StatLabel>
                <StatNumber>
                  {totalBookings > 0
                    ? Math.round(
                        (bookings.filter(b => b.currentLocation).length /
                          totalBookings) *
                          100
                      )
                    : 0}
                  %
                </StatNumber>
                <StatHelpText>With live location data</StatHelpText>
              </Stat>
            </CardBody>
          </Card>
        </Grid>

        {/* Filters */}
        <Card>
          <CardBody>
            <HStack spacing={4} wrap="wrap">
              <Box>
                <Text fontSize="sm" mb={2}>
                  Status Filter
                </Text>
                <Select
                  value={filterStatus}
                  onChange={e => setFilterStatus(e.target.value)}
                  size="sm"
                  w="150px"
                >
                  <option value="all">All Status</option>
                  <option value="CONFIRMED">Confirmed</option>
                  <option value="IN_PROGRESS">In Progress</option>
                  <option value="COMPLETED">Completed</option>
                </Select>
              </Box>
              <Box>
                <Text fontSize="sm" mb={2}>
                  Search
                </Text>
                <Input
                  placeholder="Search bookings..."
                  value={searchQuery}
                  onChange={e => setSearchQuery(e.target.value)}
                  size="sm"
                  w="250px"
                />
              </Box>
            </HStack>
          </CardBody>
        </Card>

        {/* Main Content */}
        <Grid templateColumns="1fr 400px" gap={8}>
          {/* Map */}
          <GridItem>
            <Card>
              <CardBody>
                <VStack spacing={4} align="stretch">
                  <Flex justify="space-between" align="center">
                    <Heading size="md">Live Map</Heading>
                    <Badge colorScheme="green">
                      Real-time tracking enabled
                    </Badge>
                  </Flex>
                  <Box h="600px" borderRadius="md" overflow="hidden">
                    <LiveMap
                      driverLocations={driverLocations}
                      pickupLocation={
                        selectedBooking?.currentLocation
                          ? {
                              lat: selectedBooking.currentLocation.lat,
                              lng: selectedBooking.currentLocation.lng,
                              label: 'Pickup Location',
                            }
                          : {
                              lat: 0,
                              lng: 0,
                              label: 'No Location',
                            }
                      }
                      dropoffLocation={
                        selectedBooking?.currentLocation
                          ? {
                              lat: selectedBooking.currentLocation.lat,
                              lng: selectedBooking.currentLocation.lng,
                              label: 'Dropoff Location',
                            }
                          : {
                              lat: 0,
                              lng: 0,
                              label: 'No Location',
                            }
                      }
                    />
                  </Box>
                </VStack>
              </CardBody>
            </Card>
          </GridItem>

          {/* Bookings List */}
          <GridItem>
            <Card>
              <CardBody>
                <VStack spacing={4} align="stretch">
                  <Heading size="md">Active Bookings</Heading>

                  {filteredBookings.length === 0 ? (
                    <Alert status="info">
                      <AlertIcon />
                      No active bookings found
                    </Alert>
                  ) : (
                    <VStack
                      spacing={3}
                      align="stretch"
                      maxH="600px"
                      overflowY="auto"
                    >
                      {filteredBookings.map(booking => (
                        <Card
                          key={booking.id}
                          size="sm"
                          cursor="pointer"
                          onClick={() => {
                            setSelectedBooking(booking);
                            loadBookingDetails(booking.reference);
                          }}
                          bg={
                            selectedBooking?.id === booking.id
                              ? 'blue.50'
                              : undefined
                          }
                          _hover={{ bg: 'gray.50' }}
                        >
                          <CardBody p={4}>
                            <VStack spacing={2} align="stretch">
                              <Flex justify="space-between" align="center">
                                <Text fontWeight="bold" fontSize="sm">
                                  {booking.reference}
                                </Text>
                                <Badge
                                  colorScheme={getStatusColor(booking.status)}
                                  size="sm"
                                >
                                  {booking.status}
                                </Badge>
                              </Flex>

                              <Text fontSize="xs" color="gray.600">
                                {booking.addresses.pickup.label}
                              </Text>
                              <Text fontSize="xs" color="gray.600">
                                → {booking.addresses.dropoff.label}
                              </Text>

                              {booking.driver && (
                                <Text fontSize="xs" color="blue.600">
                                  Driver: {booking.driver.name}
                                </Text>
                              )}

                              {booking.currentLocation && (
                                <HStack spacing={2}>
                                  <FiMapPin size={12} />
                                  <Text fontSize="xs" color="green.600">
                                    Live location available
                                  </Text>
                                </HStack>
                              )}

                              {booking.routeProgress > 0 && (
                                <Box>
                                  <Text fontSize="xs" mb={1}>
                                    Progress
                                  </Text>
                                  <Progress
                                    value={booking.routeProgress}
                                    size="sm"
                                    colorScheme="blue"
                                  />
                                </Box>
                              )}

                              {booking.eta && (
                                <HStack spacing={2}>
                                  <FiClock size={12} />
                                  <Text fontSize="xs">
                                    ETA: {booking.eta.minutesRemaining} min
                                  </Text>
                                </HStack>
                              )}
                            </VStack>
                          </CardBody>
                        </Card>
                      ))}
                    </VStack>
                  )}
                </VStack>
              </CardBody>
            </Card>
          </GridItem>
        </Grid>

        {/* Selected Booking Details */}
        {selectedBooking && (
          <Card>
            <CardBody>
              <VStack spacing={4} align="stretch">
                <Heading size="md">
                  Booking Details: {selectedBooking.reference}
                </Heading>

                <Grid
                  templateColumns="repeat(auto-fit, minmax(250px, 1fr))"
                  gap={6}
                >
                  <VStack align="start" spacing={2}>
                    <Text fontWeight="bold">Customer</Text>
                    <Text>{selectedBooking.customer.name}</Text>
                    <Text fontSize="sm" color="gray.600">
                      {selectedBooking.customer.email}
                    </Text>
                  </VStack>

                  {selectedBooking.driver && (
                    <VStack align="start" spacing={2}>
                      <Text fontWeight="bold">Driver</Text>
                      <Text>{selectedBooking.driver.name}</Text>
                      <Text fontSize="sm" color="gray.600">
                        {selectedBooking.driver.email}
                      </Text>
                    </VStack>
                  )}

                  {selectedBooking.properties && (
                    <VStack align="start" spacing={2}>
                      <Text fontWeight="bold">Property Details</Text>
                      {selectedBooking.properties.pickup && (
                        <Text fontSize="sm" color="gray.600">
                          Pickup: {selectedBooking.properties.pickup.buildingTypeDisplay} - Floor {selectedBooking.properties.pickup.floors} 
                          {selectedBooking.properties.pickup.hasElevator ? ' (Lift Available)' : ' (No Lift)'}
                        </Text>
                      )}
                      {selectedBooking.properties.dropoff && (
                        <Text fontSize="sm" color="gray.600">
                          Dropoff: {selectedBooking.properties.dropoff.buildingTypeDisplay} - Floor {selectedBooking.properties.dropoff.floors} 
                          {selectedBooking.properties.dropoff.hasElevator ? ' (Lift Available)' : ' (No Lift)'}
                        </Text>
                      )}
                    </VStack>
                  )}

                  <VStack align="start" spacing={2}>
                    <Text fontWeight="bold">Route Progress</Text>
                    <Progress
                      value={selectedBooking.routeProgress}
                      w="100%"
                      colorScheme="blue"
                    />
                    <Text fontSize="sm">
                      {selectedBooking.routeProgress}% complete
                    </Text>
                  </VStack>

                  {selectedBooking.eta && (
                    <VStack align="start" spacing={2}>
                      <Text fontWeight="bold">Estimated Arrival</Text>
                      <Text>
                        {selectedBooking.eta.minutesRemaining} minutes
                      </Text>
                      <Text fontSize="sm" color="gray.600">
                        {new Date(
                          selectedBooking.eta.estimatedArrival
                        ).toLocaleString()}
                      </Text>
                    </VStack>
                  )}
                </Grid>

                {selectedBooking.lastEvent && (
                  <Box>
                    <Text fontWeight="bold" mb={2}>
                      Last Event
                    </Text>
                    <Card size="sm">
                      <CardBody>
                        <VStack align="start" spacing={1}>
                          <Badge colorScheme="blue">
                            {getStepLabel(selectedBooking.lastEvent.step)}
                          </Badge>
                          <Text fontSize="sm">
                            {new Date(
                              selectedBooking.lastEvent.createdAt
                            ).toLocaleString()}
                          </Text>
                          {selectedBooking.lastEvent.notes && (
                            <Text fontSize="sm" color="gray.600">
                              {selectedBooking.lastEvent.notes}
                            </Text>
                          )}
                        </VStack>
                      </CardBody>
                    </Card>
                  </Box>
                )}

                {selectedBooking.trackingPings.length > 0 && (
                  <Box>
                    <Text fontWeight="bold" mb={2}>
                      Recent Location Updates
                    </Text>
                    <VStack
                      spacing={2}
                      align="stretch"
                      maxH="200px"
                      overflowY="auto"
                    >
                      {selectedBooking.trackingPings.slice(0, 5).map(ping => (
                        <HStack key={ping.id} spacing={3}>
                          <FiMapPin />
                          <Text fontSize="sm">
                            {ping.lat.toFixed(6)}, {ping.lng.toFixed(6)}
                          </Text>
                          <Text fontSize="xs" color="gray.500">
                            {new Date(ping.createdAt).toLocaleTimeString()}
                          </Text>
                        </HStack>
                      ))}
                    </VStack>
                  </Box>
                )}
              </VStack>
            </CardBody>
          </Card>
        )}
      </VStack>
    </Container>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import {
  Box,
  Container,
  VStack,
  HStack,
  Heading,
  Text,
  Card,
  CardBody,
  SimpleGrid,
  Badge,
  Table,
  Thead,
  Tbody,
  Tr,
  Th,
  Td,
  Tabs,
  TabList,
  TabPanels,
  Tab,
  TabPanel,
  Stat,
  StatLabel,
  StatNumber,
  StatHelpText,
  StatArrow,
  Button,
  useToast,
  Icon,
  Divider,
  Alert,
  AlertIcon,
  AlertTitle,
  AlertDescription,
  Select,
  Input,
  InputGroup,
  InputLeftElement,
  Progress,
  Tooltip,
  Modal,
  ModalOverlay,
  ModalContent,
  ModalHeader,
  ModalBody,
  ModalCloseButton,
  useDisclosure,
  Image,
  Flex,
  Spacer,
} from '@chakra-ui/react';
import {
  FaUsers,
  FaMapMarkerAlt,
  FaClock,
  FaEye,
  FaMousePointer,
  FaSearch,
  FaDownload,
  FaRedo,
  FaChartBar,
  FaGlobe,
  FaCity,
  FaBuilding,
  FaUser,
  FaCalendarAlt,
  FaMobile,
  FaDesktop,
  FaTablet,
  FaFilter,
  FaSort,
} from 'react-icons/fa';

interface VisitorSession {
  sessionId: string;
  visitorId: string;
  city: string;
  region: string;
  country: string;
  coordinates: { lat: number; lng: number };
  entryTime: Date;
  exitTime?: Date;
  sessionDuration: number;
  pagesVisited: Array<{ page: string; timeSpent: number; timestamp: Date }>;
  actions: Array<{ action: string; timestamp: Date; details?: any }>;
  bookingStarted: boolean;
  bookingCompleted: boolean;
  bookingAbandonedAt?: number;
  deviceInfo: {
    userAgent: string;
    screenResolution: string;
    language: string;
    timezone: string;
  };
}

export default function VisitorsAnalyticsPage() {
  const [visitors, setVisitors] = useState<VisitorSession[]>([]);
  const [filteredVisitors, setFilteredVisitors] = useState<VisitorSession[]>(
    []
  );
  const [isLoading, setIsLoading] = useState(false);
  const [selectedVisitor, setSelectedVisitor] = useState<VisitorSession | null>(
    null
  );
  const [filters, setFilters] = useState({
    city: '',
    region: '',
    country: '',
    deviceType: '',
    dateRange: '7d',
    searchTerm: '',
  });
  const [sortBy, setSortBy] = useState('entryTime');
  const [sortOrder, setSortOrder] = useState<'asc' | 'desc'>('desc');
  const { isOpen, onOpen, onClose } = useDisclosure();
  const toast = useToast();

  // Load visitor data
  useEffect(() => {
    loadVisitorData();
  }, []);

  // Apply filters and sorting
  useEffect(() => {
    let filtered = [...visitors];

    // Apply filters
    if (filters.city) {
      filtered = filtered.filter(v =>
        v.city.toLowerCase().includes(filters.city.toLowerCase())
      );
    }
    if (filters.region) {
      filtered = filtered.filter(v =>
        v.region.toLowerCase().includes(filters.region.toLowerCase())
      );
    }
    if (filters.country) {
      filtered = filtered.filter(v =>
        v.country.toLowerCase().includes(filters.country.toLowerCase())
      );
    }
    if (filters.deviceType) {
      filtered = filtered.filter(v => {
        const userAgent = v.deviceInfo.userAgent.toLowerCase();
        if (filters.deviceType === 'mobile')
          return /mobile|android|iphone|ipad|phone/i.test(userAgent);
        if (filters.deviceType === 'desktop')
          return !/mobile|android|iphone|ipad|phone/i.test(userAgent);
        if (filters.deviceType === 'tablet')
          return /ipad|tablet/i.test(userAgent);
        return true;
      });
    }
    if (filters.searchTerm) {
      filtered = filtered.filter(
        v =>
          v.city.toLowerCase().includes(filters.searchTerm.toLowerCase()) ||
          v.region.toLowerCase().includes(filters.searchTerm.toLowerCase()) ||
          v.visitorId.toLowerCase().includes(filters.searchTerm.toLowerCase())
      );
    }

    // Apply date range filter
    const now = new Date();
    if (filters.dateRange === '24h') {
      filtered = filtered.filter(
        v =>
          now.getTime() - new Date(v.entryTime).getTime() <= 24 * 60 * 60 * 1000
      );
    } else if (filters.dateRange === '7d') {
      filtered = filtered.filter(
        v =>
          now.getTime() - new Date(v.entryTime).getTime() <=
          7 * 24 * 60 * 60 * 1000
      );
    } else if (filters.dateRange === '30d') {
      filtered = filtered.filter(
        v =>
          now.getTime() - new Date(v.entryTime).getTime() <=
          30 * 24 * 60 * 60 * 1000
      );
    }

    // Apply sorting
    filtered.sort((a, b) => {
      let aValue: any, bValue: any;

      switch (sortBy) {
        case 'entryTime':
          aValue = new Date(a.entryTime).getTime();
          bValue = new Date(b.entryTime).getTime();
          break;
        case 'sessionDuration':
          aValue = a.sessionDuration;
          bValue = b.sessionDuration;
          break;
        case 'city':
          aValue = a.city.toLowerCase();
          bValue = b.city.toLowerCase();
          break;
        case 'region':
          aValue = a.region.toLowerCase();
          bValue = b.region.toLowerCase();
          break;
        default:
          aValue = a[sortBy as keyof VisitorSession];
          bValue = b[sortBy as keyof VisitorSession];
      }

      if (sortOrder === 'asc') {
        return aValue > bValue ? 1 : -1;
      } else {
        return aValue < bValue ? 1 : -1;
      }
    });

    setFilteredVisitors(filtered);
  }, [visitors, filters, sortBy, sortOrder]);

  const loadVisitorData = () => {
    try {
      const data = JSON.parse(
        localStorage.getItem('admin-visitor-analytics') || '[]'
      );
      setVisitors(data);
    } catch (error) {
      console.error('Error loading visitor data:', error);
    }
  };

  const refreshData = () => {
    setIsLoading(true);
    loadVisitorData();
    setTimeout(() => setIsLoading(false), 1000);

    toast({
      title: 'Data Refreshed',
      description: 'Visitor analytics data has been updated',
      status: 'success',
      duration: 2000,
      isClosable: true,
    });
  };

  const exportData = () => {
    const filename = `speedy-van-visitors-${new Date().toISOString().split('T')[0]}.json`;
    const blob = new Blob([JSON.stringify(filteredVisitors, null, 2)], {
      type: 'application/json',
    });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    a.click();
    URL.revokeObjectURL(url);

    toast({
      title: 'Data Exported',
      description: 'Visitor data has been downloaded',
      status: 'success',
      duration: 2000,
      isClosable: true,
    });
  };

  const openVisitorDetails = (visitor: VisitorSession) => {
    setSelectedVisitor(visitor);
    onOpen();
  };

  const calculateStats = () => {
    const totalVisitors = visitors.length;
    const uniqueVisitors = new Set(visitors.map(v => v.visitorId)).size;
    const averageSessionDuration =
      visitors.length > 0
        ? visitors.reduce((sum, v) => sum + v.sessionDuration, 0) /
          visitors.length
        : 0;

    const topCities = visitors.reduce(
      (acc, visitor) => {
        const city = visitor.city;
        acc[city] = (acc[city] || 0) + 1;
        return acc;
      },
      {} as Record<string, number>
    );

    const topRegions = visitors.reduce(
      (acc, visitor) => {
        const region = visitor.region;
        acc[region] = (acc[region] || 0) + 1;
        return acc;
      },
      {} as Record<string, number>
    );

    const deviceTypes = visitors.reduce(
      (acc, visitor) => {
        const userAgent = visitor.deviceInfo.userAgent.toLowerCase();
        if (/mobile|android|iphone|ipad|phone/i.test(userAgent)) {
          acc.mobile++;
        } else if (/ipad|tablet/i.test(userAgent)) {
          acc.tablet++;
        } else {
          acc.desktop++;
        }
        return acc;
      },
      { mobile: 0, tablet: 0, desktop: 0 }
    );

    const bookingStats = visitors.reduce(
      (acc, visitor) => {
        if (visitor.bookingStarted) acc.started++;
        if (visitor.bookingCompleted) acc.completed++;
        if (visitor.bookingAbandonedAt) acc.abandoned++;
        return acc;
      },
      { started: 0, completed: 0, abandoned: 0 }
    );

    return {
      totalVisitors,
      uniqueVisitors,
      averageSessionDuration,
      topCities: Object.entries(topCities)
        .sort(([, a], [, b]) => b - a)
        .slice(0, 10)
        .map(([city, count]) => ({
          city,
          count,
          region: visitors.find(v => v.city === city)?.region || 'Unknown',
        })),
      topRegions: Object.entries(topRegions)
        .sort(([, a], [, b]) => b - a)
        .slice(0, 10)
        .map(([region, count]) => ({ region, count })),
      deviceTypes,
      bookingStats,
    };
  };

  const stats = calculateStats();

  const getDeviceIcon = (userAgent: string) => {
    const agent = userAgent.toLowerCase();
    if (/mobile|android|iphone|ipad|phone/i.test(agent)) return FaMobile;
    if (/ipad|tablet/i.test(agent)) return FaTablet;
    return FaDesktop;
  };

  const formatDuration = (seconds: number) => {
    if (seconds < 60) return `${seconds}s`;
    if (seconds < 3600) return `${Math.floor(seconds / 60)}m ${seconds % 60}s`;
    return `${Math.floor(seconds / 3600)}h ${Math.floor((seconds % 3600) / 60)}m`;
  };

  return (
    <Container maxW="container.xl" py={8}>
      <VStack spacing={8} align="stretch">
        {/* Header */}
        <VStack spacing={4} textAlign="center">
          <Heading size="2xl" color="blue.600">
            👥 Visitors Analytics Dashboard
          </Heading>
          <Text fontSize="lg" color="text.secondary">
            Comprehensive insights into visitor behavior, location patterns, and
            engagement metrics
          </Text>
        </VStack>

        {/* Action Buttons */}
        <HStack justify="space-between">
          <HStack spacing={4}>
            <Button
              leftIcon={<FaRedo />}
              onClick={refreshData}
              isLoading={isLoading}
              colorScheme="blue"
            >
              Refresh Data
            </Button>
            <Button
              leftIcon={<FaDownload />}
              onClick={exportData}
              colorScheme="green"
              isDisabled={filteredVisitors.length === 0}
            >
              Export Data
            </Button>
          </HStack>

          <Text fontSize="sm" color="text.secondary">
            <span suppressHydrationWarning>
              Last updated: {new Date().toLocaleString()}
            </span>
          </Text>
        </HStack>

        {/* Key Statistics */}
        <SimpleGrid columns={{ base: 1, md: 2, lg: 4 }} spacing={6}>
          <Card>
            <CardBody textAlign="center">
              <Stat>
                <StatLabel>Total Visitors</StatLabel>
                <StatNumber color="blue.600">{stats.totalVisitors}</StatNumber>
                <StatHelpText>
                  <StatArrow type="increase" />
                  {stats.uniqueVisitors} unique
                </StatHelpText>
              </Stat>
            </CardBody>
          </Card>

          <Card>
            <CardBody textAlign="center">
              <Stat>
                <StatLabel>Avg Session Time</StatLabel>
                <StatNumber color="green.600">
                  {formatDuration(stats.averageSessionDuration)}
                </StatNumber>
                <StatHelpText>Time spent on site</StatHelpText>
              </Stat>
            </CardBody>
          </Card>

          <Card>
            <CardBody textAlign="center">
              <Stat>
                <StatLabel>Booking Started</StatLabel>
                <StatNumber color="orange.600">
                  {stats.bookingStats.started}
                </StatNumber>
                <StatHelpText>
                  {stats.bookingStats.completed} completed
                </StatHelpText>
              </Stat>
            </CardBody>
          </Card>

          <Card>
            <CardBody textAlign="center">
              <Stat>
                <StatLabel>Top City</StatLabel>
                <StatNumber color="purple.600">
                  {stats.topCities[0]?.city || 'N/A'}
                </StatNumber>
                <StatHelpText>
                  {stats.topCities[0]?.count || 0} visitors
                </StatHelpText>
              </Stat>
            </CardBody>
          </Card>
        </SimpleGrid>

        {/* Filters and Search */}
        <Card>
          <CardBody>
            <VStack spacing={4} align="stretch">
              <Heading size="md">Filters & Search</Heading>
              <SimpleGrid columns={{ base: 1, md: 2, lg: 3 }} spacing={4}>
                <InputGroup>
                  <InputLeftElement>
                    <FaSearch />
                  </InputLeftElement>
                  <Input
                    placeholder="Search visitors..."
                    value={filters.searchTerm}
                    onChange={e =>
                      setFilters(prev => ({
                        ...prev,
                        searchTerm: e.target.value,
                      }))
                    }
                  />
                </InputGroup>

                <Select
                  placeholder="Select City"
                  value={filters.city}
                  onChange={e =>
                    setFilters(prev => ({ ...prev, city: e.target.value }))
                  }
                >
                  {Array.from(new Set(visitors.map(v => v.city))).map(city => (
                    <option key={city} value={city}>
                      {city}
                    </option>
                  ))}
                </Select>

                <Select
                  placeholder="Select Region"
                  value={filters.region}
                  onChange={e =>
                    setFilters(prev => ({ ...prev, region: e.target.value }))
                  }
                >
                  {Array.from(new Set(visitors.map(v => v.region))).map(
                    region => (
                      <option key={region} value={region}>
                        {region}
                      </option>
                    )
                  )}
                </Select>

                <Select
                  placeholder="Device Type"
                  value={filters.deviceType}
                  onChange={e =>
                    setFilters(prev => ({
                      ...prev,
                      deviceType: e.target.value,
                    }))
                  }
                >
                  <option value="">All Devices</option>
                  <option value="mobile">Mobile</option>
                  <option value="tablet">Tablet</option>
                  <option value="desktop">Desktop</option>
                </Select>

                <Select
                  placeholder="Date Range"
                  value={filters.dateRange}
                  onChange={e =>
                    setFilters(prev => ({ ...prev, dateRange: e.target.value }))
                  }
                >
                  <option value="24h">Last 24 Hours</option>
                  <option value="7d">Last 7 Days</option>
                  <option value="30d">Last 30 Days</option>
                </Select>

                <Select
                  placeholder="Sort By"
                  value={sortBy}
                  onChange={e => setSortBy(e.target.value)}
                >
                  <option value="entryTime">Entry Time</option>
                  <option value="sessionDuration">Session Duration</option>
                  <option value="city">City</option>
                  <option value="region">Region</option>
                </Select>
              </SimpleGrid>
            </VStack>
          </CardBody>
        </Card>

        {/* Top Cities and Regions */}
        <SimpleGrid columns={{ base: 1, md: 2 }} spacing={6}>
          <Card>
            <CardBody>
              <VStack spacing={4} align="stretch">
                <Heading size="md" color="blue.600">
                  🏙️ Top Cities
                </Heading>
                <VStack spacing={2} align="stretch">
                  {stats.topCities.slice(0, 5).map((city, index) => (
                    <HStack key={city.city} justify="space-between">
                      <HStack>
                        <Badge colorScheme="blue" variant="outline">
                          #{index + 1}
                        </Badge>
                        <VStack align="start" spacing={0}>
                          <Text fontWeight="bold">{city.city}</Text>
                          <Text fontSize="sm" color="text.secondary">
                            {city.region}
                          </Text>
                        </VStack>
                      </HStack>
                      <HStack>
                        <Text fontWeight="bold">{city.count}</Text>
                        <Text fontSize="sm" color="text.secondary">
                          visitors
                        </Text>
                      </HStack>
                    </HStack>
                  ))}
                </VStack>
              </VStack>
            </CardBody>
          </Card>

          <Card>
            <CardBody>
              <VStack spacing={4} align="stretch">
                <Heading size="md" color="green.600">
                  🌍 Top Regions
                </Heading>
                <VStack spacing={2} align="stretch">
                  {stats.topRegions.slice(0, 5).map((region, index) => (
                    <HStack key={region.region} justify="space-between">
                      <HStack>
                        <Badge colorScheme="green" variant="outline">
                          #{index + 1}
                        </Badge>
                        <Text fontWeight="bold">{region.region}</Text>
                      </HStack>
                      <HStack>
                        <Text fontWeight="bold">{region.count}</Text>
                        <Text fontSize="sm" color="text.secondary">
                          visitors
                        </Text>
                      </HStack>
                    </HStack>
                  ))}
                </VStack>
              </VStack>
            </CardBody>
          </Card>
        </SimpleGrid>

        {/* Device and Booking Analytics */}
        <SimpleGrid columns={{ base: 1, md: 2 }} spacing={6}>
          <Card>
            <CardBody>
              <VStack spacing={4} align="stretch">
                <Heading size="md" color="purple.600">
                  📱 Device Distribution
                </Heading>
                <VStack spacing={3} align="stretch">
                  <HStack justify="space-between">
                    <HStack>
                      <Icon as={FaMobile} color="blue.500" />
                      <Text>Mobile</Text>
                    </HStack>
                    <HStack>
                      <Text fontWeight="bold">{stats.deviceTypes.mobile}</Text>
                      <Text fontSize="sm" color="text.secondary">
                        {(
                          (stats.deviceTypes.mobile / stats.totalVisitors) *
                          100
                        ).toFixed(1)}
                        %
                      </Text>
                    </HStack>
                  </HStack>
                  <Progress
                    value={
                      (stats.deviceTypes.mobile / stats.totalVisitors) * 100
                    }
                    colorScheme="blue"
                  />

                  <HStack justify="space-between">
                    <HStack>
                      <Icon as={FaTablet} color="green.500" />
                      <Text>Tablet</Text>
                    </HStack>
                    <HStack>
                      <Text fontWeight="bold">{stats.deviceTypes.tablet}</Text>
                      <Text fontSize="sm" color="text.secondary">
                        {(
                          (stats.deviceTypes.tablet / stats.totalVisitors) *
                          100
                        ).toFixed(1)}
                        %
                      </Text>
                    </HStack>
                  </HStack>
                  <Progress
                    value={
                      (stats.deviceTypes.tablet / stats.totalVisitors) * 100
                    }
                    colorScheme="green"
                  />

                  <HStack justify="space-between">
                    <HStack>
                      <Icon as={FaDesktop} color="purple.500" />
                      <Text>Desktop</Text>
                    </HStack>
                    <HStack>
                      <Text fontWeight="bold">{stats.deviceTypes.desktop}</Text>
                      <Text fontSize="sm" color="text.secondary">
                        {(
                          (stats.deviceTypes.desktop / stats.totalVisitors) *
                          100
                        ).toFixed(1)}
                        %
                      </Text>
                    </HStack>
                  </HStack>
                  <Progress
                    value={
                      (stats.deviceTypes.desktop / stats.totalVisitors) * 100
                    }
                    colorScheme="purple"
                  />
                </VStack>
              </VStack>
            </CardBody>
          </Card>

          <Card>
            <CardBody>
              <VStack spacing={4} align="stretch">
                <Heading size="md" color="orange.600">
                  📊 Booking Conversion
                </Heading>
                <VStack spacing={3} align="stretch">
                  <HStack justify="space-between">
                    <HStack>
                      <Icon as={FaEye} color="blue.500" />
                      <Text>Started Booking</Text>
                    </HStack>
                    <HStack>
                      <Text fontWeight="bold">
                        {stats.bookingStats.started}
                      </Text>
                      <Text fontSize="sm" color="text.secondary">
                        {(
                          (stats.bookingStats.started / stats.totalVisitors) *
                          100
                        ).toFixed(1)}
                        %
                      </Text>
                    </HStack>
                  </HStack>
                  <Progress
                    value={
                      (stats.bookingStats.started / stats.totalVisitors) * 100
                    }
                    colorScheme="blue"
                  />

                  <HStack justify="space-between">
                    <HStack>
                      <Icon as={FaMousePointer} color="green.500" />
                      <Text>Completed</Text>
                    </HStack>
                    <HStack>
                      <Text fontWeight="bold">
                        {stats.bookingStats.completed}
                      </Text>
                      <Text fontSize="sm" color="text.secondary">
                        {(
                          (stats.bookingStats.completed / stats.totalVisitors) *
                          100
                        ).toFixed(1)}
                        %
                      </Text>
                    </HStack>
                  </HStack>
                  <Progress
                    value={
                      (stats.bookingStats.completed / stats.totalVisitors) * 100
                    }
                    colorScheme="green"
                  />

                  <HStack justify="space-between">
                    <HStack>
                      <Icon as={FaClock} color="red.500" />
                      <Text>Abandoned</Text>
                    </HStack>
                    <HStack>
                      <Text fontWeight="bold">
                        {stats.bookingStats.abandoned}
                      </Text>
                      <Text fontSize="sm" color="text.secondary">
                        {(
                          (stats.bookingStats.abandoned / stats.totalVisitors) *
                          100
                        ).toFixed(1)}
                        %
                      </Text>
                    </HStack>
                  </HStack>
                  <Progress
                    value={
                      (stats.bookingStats.abandoned / stats.totalVisitors) * 100
                    }
                    colorScheme="red"
                  />
                </VStack>
              </VStack>
            </CardBody>
          </Card>
        </SimpleGrid>

        {/* Visitors Table */}
        <Card>
          <CardBody>
            <VStack spacing={4} align="stretch">
              <HStack justify="space-between">
                <Heading size="md">Detailed Visitor Data</Heading>
                <Text fontSize="sm" color="text.secondary">
                  {filteredVisitors.length} of {visitors.length} visitors
                </Text>
              </HStack>

              {filteredVisitors.length === 0 ? (
                <Alert status="info">
                  <AlertIcon />
                  <Box>
                    <AlertTitle>No Visitors Found</AlertTitle>
                    <AlertDescription>
                      Try adjusting your filters or refresh the data.
                    </AlertDescription>
                  </Box>
                </Alert>
              ) : (
                <Box overflowX="auto">
                  <Table variant="simple" size="sm">
                    <Thead>
                      <Tr>
                        <Th>Visitor</Th>
                        <Th>Location</Th>
                        <Th>Device</Th>
                        <Th>Entry Time</Th>
                        <Th>Duration</Th>
                        <Th>Actions</Th>
                        <Th>Booking</Th>
                        <Th>Actions</Th>
                      </Tr>
                    </Thead>
                    <Tbody>
                      {filteredVisitors.slice(0, 50).map(visitor => (
                        <Tr key={visitor.sessionId} _hover={{ bg: 'gray.50' }}>
                          <Td>
                            <VStack align="start" spacing={1}>
                              <Text fontWeight="bold" fontSize="sm">
                                {visitor.visitorId.substring(0, 8)}...
                              </Text>
                              <Text fontSize="xs" color="text.secondary">
                                {visitor.deviceInfo.language}
                              </Text>
                            </VStack>
                          </Td>
                          <Td>
                            <VStack align="start" spacing={1}>
                              <HStack>
                                <Icon
                                  as={FaMapMarkerAlt}
                                  color="blue.500"
                                  boxSize={3}
                                />
                                <Text fontSize="sm" fontWeight="medium">
                                  {visitor.city}
                                </Text>
                              </HStack>
                              <Text fontSize="xs" color="text.secondary">
                                {visitor.region}
                              </Text>
                            </VStack>
                          </Td>
                          <Td>
                            <HStack>
                              <Icon
                                as={getDeviceIcon(visitor.deviceInfo.userAgent)}
                                color="purple.500"
                              />
                              <VStack align="start" spacing={0}>
                                <Text fontSize="sm">
                                  {visitor.deviceInfo.screenResolution}
                                </Text>
                                <Text fontSize="xs" color="text.secondary">
                                  {visitor.deviceInfo.timezone}
                                </Text>
                              </VStack>
                            </HStack>
                          </Td>
                          <Td>
                            <VStack align="start" spacing={1}>
                              <Text fontSize="sm">
                                {new Date(
                                  visitor.entryTime
                                ).toLocaleDateString()}
                              </Text>
                              <Text fontSize="xs" color="text.secondary">
                                {new Date(
                                  visitor.entryTime
                                ).toLocaleTimeString()}
                              </Text>
                            </VStack>
                          </Td>
                          <Td>
                            <Text fontSize="sm" fontWeight="medium">
                              {formatDuration(visitor.sessionDuration)}
                            </Text>
                          </Td>
                          <Td>
                            <Text fontSize="sm">
                              {visitor.actions.length} actions
                            </Text>
                          </Td>
                          <Td>
                            <HStack spacing={2}>
                              {visitor.bookingStarted && (
                                <Badge colorScheme="blue" size="sm">
                                  Started
                                </Badge>
                              )}
                              {visitor.bookingCompleted && (
                                <Badge colorScheme="green" size="sm">
                                  Completed
                                </Badge>
                              )}
                              {visitor.bookingAbandonedAt && (
                                <Badge colorScheme="red" size="sm">
                                  Abandoned
                                </Badge>
                              )}
                            </HStack>
                          </Td>
                          <Td>
                            <Button
                              size="sm"
                              variant="outline"
                              colorScheme="blue"
                              onClick={() => openVisitorDetails(visitor)}
                            >
                              View Details
                            </Button>
                          </Td>
                        </Tr>
                      ))}
                    </Tbody>
                  </Table>
                </Box>
              )}
            </VStack>
          </CardBody>
        </Card>
      </VStack>

      {/* Visitor Details Modal */}
      <Modal isOpen={isOpen} onClose={onClose} size="xl">
        <ModalOverlay />
        <ModalContent>
          <ModalHeader>Visitor Details</ModalHeader>
          <ModalCloseButton />
          <ModalBody pb={6}>
            {selectedVisitor && (
              <VStack spacing={6} align="stretch">
                {/* Basic Info */}
                <Card>
                  <CardBody>
                    <VStack spacing={4} align="stretch">
                      <Heading size="md">Basic Information</Heading>
                      <SimpleGrid columns={2} spacing={4}>
                        <VStack align="start">
                          <Text fontWeight="bold">Visitor ID:</Text>
                          <Text fontSize="sm" fontFamily="mono">
                            {selectedVisitor.visitorId}
                          </Text>
                        </VStack>
                        <VStack align="start">
                          <Text fontWeight="bold">Session ID:</Text>
                          <Text fontSize="sm" fontFamily="mono">
                            {selectedVisitor.sessionId}
                          </Text>
                        </VStack>
                        <VStack align="start">
                          <Text fontWeight="bold">Entry Time:</Text>
                          <Text fontSize="sm">
                            {new Date(
                              selectedVisitor.entryTime
                            ).toLocaleString()}
                          </Text>
                        </VStack>
                        <VStack align="start">
                          <Text fontWeight="bold">Duration:</Text>
                          <Text fontSize="sm">
                            {formatDuration(selectedVisitor.sessionDuration)}
                          </Text>
                        </VStack>
                      </SimpleGrid>
                    </VStack>
