// Helper function to parse getAddress.io format
function parseGetAddressFormat(address: string, postcode: string): any {
  const parts = address.split(',').map(p => p.trim());
  
  return {
    street: parts[1] || '',
    city: parts[parts.length - 2] || '',
    postcode: postcode,
    country: 'England',
    houseNumber: parts[0] || '',
    flatNumber: ''
  };
}

