import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';

export const dynamic = 'force-dynamic';

type AlertType = 'info' | 'warning' | 'error';

interface LiveStatAlert {
  id: string;
  type: AlertType;
  message: string;
  timestamp: string;
}

interface RecentActivityItem {
  id: string;
  type: 'booking';
  description: string;
  timestamp: string;
}

export async function GET(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user || (session.user as any).role !== 'admin') {
      return NextResponse.json({ error: 'Unauthorized - Admin access required' }, { status: 401 });
    }

    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const tomorrow = new Date(today);
    tomorrow.setDate(tomorrow.getDate() + 1);

    const [totalBookings, pendingBookings, activeBookings, completedToday] = await Promise.all([
      prisma.booking.count({
        where: {
          createdAt: {
            gte: today,
            lt: tomorrow,
          },
        },
      }),
      prisma.booking.count({
        where: {
          status: 'CONFIRMED',
          driverId: null,
        },
      }),
      prisma.booking.count({
        where: {
          status: 'CONFIRMED',
          driverId: { not: null }, // Active = confirmed with assigned driver
        },
      }),
      prisma.booking.count({
        where: {
          status: 'COMPLETED',
          updatedAt: {
            gte: today,
            lt: tomorrow,
          },
        },
      }),
    ]);

    const [activeDrivers, totalDrivers] = await Promise.all([
      prisma.driver.count({
        where: {
          status: 'active',
        },
      }),
      prisma.driver.count(),
    ]);

    const driversWithBookings = await prisma.booking.groupBy({
      by: ['driverId'],
      where: {
        driverId: { not: null },
        status: 'CONFIRMED',
      },
    });

    const utilizationRate = activeDrivers > 0 ? (driversWithBookings.length / activeDrivers) * 100 : 0;

    const todayCompletedBookings = await prisma.booking.findMany({
      where: {
        status: 'COMPLETED',
        updatedAt: {
          gte: today,
          lt: tomorrow,
        },
      },
      select: {
        totalGBP: true,
      },
    });

    const todayRevenuePence = todayCompletedBookings.reduce<number>(
      (sum, booking) => sum + (booking.totalGBP ?? 0),
      0
    );
    const todayRevenue = todayRevenuePence / 100;

    const alerts: LiveStatAlert[] = [];

    if (pendingBookings > 5) {
      alerts.push({
        id: 'pending-bookings',
        type: 'warning',
        message: `${pendingBookings} bookings are pending driver assignment`,
        timestamp: new Date().toISOString(),
      });
    }

    if (utilizationRate < 30) {
      alerts.push({
        id: 'low-utilization',
        type: 'info',
        message: `Driver utilization is low at ${utilizationRate.toFixed(0)}%`,
        timestamp: new Date().toISOString(),
      });
    }

    if (activeDrivers < 5) {
      alerts.push({
        id: 'low-drivers',
        type: 'error',
        message: `Only ${activeDrivers} drivers are currently active`,
        timestamp: new Date().toISOString(),
      });
    }

    const recentBookings = await prisma.booking.findMany({
      orderBy: { createdAt: 'desc' },
      take: 10,
      include: {
        customer: {
          select: {
            name: true,
            email: true,
          },
        },
        pickupAddress: {
          select: {
            label: true,
            postcode: true,
          },
        },
      },
    });

    const recentActivity: RecentActivityItem[] = recentBookings.map((booking) => ({
      id: booking.id,
      type: 'booking',
      description: `New booking from ${booking.customer?.name ?? 'Unknown'} - ${
        booking.pickupAddress?.label ?? 'Pickup address pending'
      }`,
      timestamp: booking.createdAt.toISOString(),
    }));

    return NextResponse.json({
      totalBookings,
      pendingBookings,
      activeBookings,
      completedToday,
      activeDrivers,
      totalDrivers,
      todayRevenue,
      utilizationRate,
      alerts,
      recentActivity,
    });
  } catch (error) {
    console.error('Live stats API error:', error);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';

export const dynamic = 'force-dynamic';

/**
 * ✅ Get urgent notifications count for admin AI
 * Returns count of issues needing immediate attention
 */
export async function GET(request: NextRequest) {
  try {
    // Check authentication
    const session = await getServerSession(authOptions);
    
    if (!session?.user || (session.user as any).role !== 'admin') {
      return NextResponse.json(
        { error: 'Unauthorized - Admin access required' },
        { status: 401 }
      );
    }

    const now = new Date();
    const twoHoursAgo = new Date(now.getTime() - 2 * 60 * 60 * 1000);

    // Check for urgent issues
    const [
      oldUnassigned,
      pendingDriverApps,
      activeDriverCount,
      upcomingOrders
    ] = await Promise.all([
      // Orders unassigned for >2 hours
      prisma.booking.count({
        where: {
          status: 'CONFIRMED',
          driverId: null,
          createdAt: { lt: twoHoursAgo }
        }
      }),
      
      // Pending driver applications
      prisma.driverApplication.count({
        where: { status: 'pending' }
      }),
      
      // Active driver count
      prisma.driver.count({
        where: {
          status: 'active',
          onboardingStatus: 'approved'
        }
      }),
      
      // Upcoming orders in next 2 hours
      prisma.booking.count({
        where: {
          status: 'CONFIRMED',
          scheduledAt: {
            gte: now,
            lte: new Date(now.getTime() + 2 * 60 * 60 * 1000)
          }
        }
      })
    ]);

    // Calculate total urgent notifications
    let count = 0;
    const notifications = [];

    if (oldUnassigned > 0) {
      count += oldUnassigned;
      notifications.push({
        type: 'unassigned_orders',
        count: oldUnassigned,
        severity: 'high',
        message: `${oldUnassigned} orders unassigned for >2 hours`
      });
    }

    if (pendingDriverApps > 3) {
      count += 1;
      notifications.push({
        type: 'pending_applications',
        count: pendingDriverApps,
        severity: 'medium',
        message: `${pendingDriverApps} driver applications pending review`
      });
    }

    if (activeDriverCount < 5 && upcomingOrders > 10) {
      count += 1;
      notifications.push({
        type: 'driver_shortage',
        count: 1,
        severity: 'critical',
        message: `Driver shortage: ${activeDriverCount} drivers for ${upcomingOrders} upcoming orders`
      });
    }

    return NextResponse.json({
      success: true,
      count,
      notifications,
      timestamp: new Date().toISOString()
    });
  } catch (error: any) {
    console.error('Error fetching AI notifications:', error);
    return NextResponse.json(
      {
        success: false,
        error: error.message || 'Failed to fetch notifications',
        count: 0
      },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { coreOrchestrator } from '@/server/ai/CoreOrchestrator';
import { memorySystem } from '@/server/ai/MemorySystem';

// Force dynamic rendering (uses headers/cookies/getServerSession)
export const dynamic = 'force-dynamic';

/**
 * POST /api/admin/ai
 * Main AI Assistant endpoint with orchestration and memory
 */
export async function POST(req: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user) {
      return NextResponse.json(
        { error: 'غير مصرح' },
        { status: 401 }
      );
    }

    // Check admin role
    if (session.user.role !== 'admin' && session.user.role !== 'superadmin') {
      return NextResponse.json(
        { error: 'صلاحيات غير كافية' },
        { status: 403 }
      );
    }

    const body = await req.json();
    const { input, sessionId, confirmed = false } = body;

    if (!input || typeof input !== 'string') {
      return NextResponse.json(
        { error: 'المدخل مطلوب' },
        { status: 400 }
      );
    }

    // Generate session ID if not provided
    const actualSessionId = sessionId || `session_${Date.now()}`;

    // Get session context and recent entities
    const context = await memorySystem.getSessionContext(session.user.id, actualSessionId);
    const recentEntities = await memorySystem.getRecentEntities(session.user.id, actualSessionId);

    // Enhance input with context if user is referring to previous entities
    let enhancedInput = input;
    if (input.includes('it') || input.includes('this') || input.includes('ه') || input.includes('هذا')) {
      if (context.activeOrderId && !input.includes('order') && !input.includes('طلب')) {
        enhancedInput = `${input} (order #${context.activeOrderId})`;
      }
    }

    // Add conversation turn (user input)
    await memorySystem.addConversationTurn(session.user.id, actualSessionId, {
      role: 'user',
      content: input,
    });

    // Execute with orchestrator
    const result = await coreOrchestrator.orchestrate(enhancedInput, {
      userId: session.user.id,
      userRole: session.user.role,
      sessionId: actualSessionId,
      timestamp: new Date(),
      metadata: {
        confirmed,
        ipAddress: req.headers.get('x-forwarded-for') || req.headers.get('x-real-ip') || 'unknown',
        userAgent: req.headers.get('user-agent') || 'unknown',
      },
    });

    // Handle confirmation requirement
    if (result.error === 'requires_confirmation') {
      return NextResponse.json({
        requiresConfirmation: true,
        intent: result.intent,
        message: 'هذه العملية تتطلب تأكيداً',
        sessionId: actualSessionId,
      });
    }

    // Add conversation turn (assistant response)
    await memorySystem.addConversationTurn(session.user.id, actualSessionId, {
      role: 'assistant',
      content: result.success ? 'تم التنفيذ بنجاح' : result.error || 'حدث خطأ',
      intent: result.intent.type,
      entities: result.intent.entities,
      result: result.result,
    });

    // Learn from this action
    if (result.intent.type !== 'unknown') {
      await memorySystem.learnFromAction(
        result.intent.goal,
        result.tool || result.agent || 'unknown',
        result.success
      );
    }

