function generateMockExportData() {
  const headers = [
    'Date',
    'Revenue',
    'Orders',
    'AOV',
    'Completion Rate',
    'Driver',
  ];
  const data = [];

  for (let i = 30; i >= 0; i--) {
    const date = new Date();
