/**
 * Admin Audit Trail API
 * GET /api/admin/audit-trail
 * Returns all AdminApproval records with filtering options
 */

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';

export const dynamic = 'force-dynamic';

export async function GET(request: NextRequest) {
  try {
    // Authentication check
    const session = await getServerSession(authOptions);
    if (!session?.user || (session.user as any).role !== 'admin') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const { searchParams } = new URL(request.url);
    const type = searchParams.get('type');
    const action = searchParams.get('action');
    const entityType = searchParams.get('entity_type');
    const adminId = searchParams.get('admin_id');
    const dateFrom = searchParams.get('date_from');
    const dateTo = searchParams.get('date_to');
    const limit = parseInt(searchParams.get('limit') || '100');
    const offset = parseInt(searchParams.get('offset') || '0');

    // Build where clause
    const where: any = {};

    if (type) {
      where.type = type;
    }

    if (action) {
      where.action = action;
    }

    if (entityType) {
      where.entityType = entityType;
    }

    if (adminId) {
      where.adminId = adminId;
    }

    if (dateFrom) {
      where.approvedAt = {
        ...where.approvedAt,
        gte: new Date(dateFrom),
      };
    }

    if (dateTo) {
      const toDate = new Date(dateTo);
      toDate.setHours(23, 59, 59, 999);
      where.approvedAt = {
        ...where.approvedAt,
        lte: toDate,
      };
    }

    // Check if AdminApproval model exists
    const hasAdminApprovalModel = (prisma as any).adminApproval !== undefined;

    if (!hasAdminApprovalModel) {
      console.warn('⚠️ AdminApproval model not available yet (prisma generate needed)');
      return NextResponse.json({
        success: true,
        count: 0,
        audits: [],
        message: 'AdminApproval model not available - run prisma generate',
      });
    }

    // Query AdminApproval records
    const [audits, totalCount] = await Promise.all([
      (prisma as any).adminApproval.findMany({
        where,
        orderBy: {
          approvedAt: 'desc',
        },
        take: limit,
        skip: offset,
      }),
      (prisma as any).adminApproval.count({ where }),
    ]);

    // Format response
    const formattedAudits = audits.map((audit: any) => ({
      id: audit.id,
      type: audit.type,
      entityType: audit.entityType,
      entityId: audit.entityId,
      adminId: audit.adminId,
      adminName: audit.adminName || null,
      action: audit.action,
      previousValue: audit.previousValue || null,
      newValue: audit.newValue || null,
      reason: audit.reason || null,
      notes: audit.notes || null,
      approvedAt: audit.approvedAt.toISOString(),
    }));

    console.log(`✅ Retrieved ${formattedAudits.length} audit records (total: ${totalCount})`);

    return NextResponse.json({
      success: true,
      count: formattedAudits.length,
      totalCount,
      audits: formattedAudits,
      pagination: {
        limit,
        offset,
        hasMore: offset + formattedAudits.length < totalCount,
      },
    });
  } catch (error: any) {
    console.error('❌ Error fetching audit trail:', error);
    return NextResponse.json(
      {
        success: false,
        error: 'Failed to fetch audit trail',
        message: error.message,
      },
      { status: 500 }
    );
  }
}

import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';

// Force dynamic rendering (uses headers/cookies/getServerSession)
export const dynamic = 'force-dynamic';

export async function GET(req: Request) {
  const s = await getServerSession(authOptions);
  if (!s?.user || (s.user as any).role !== 'admin')
    return new Response('Unauthorized', { status: 401 });
  const { searchParams } = new URL(req.url);
  const take = Math.min(
    Math.max(Number(searchParams.get('take') || 50), 1),
    200
  );
  const cursor = searchParams.get('cursor') || undefined;
  const items = await prisma.auditLog.findMany({
    orderBy: { createdAt: 'desc' },
    take,
    ...(cursor ? { skip: 1, cursor: { id: cursor } } : {}),
  });
  const nextCursor = items.length === take ? items[items.length - 1].id : null;
  return Response.json({ items, nextCursor });
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
// BookingService removed
import { getPusherServer } from '@/lib/pusher';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

interface AutoAssignmentCriteria {
  maxDistance?: number; // km from booking location
  minRating?: number;
  maxCurrentJobs?: number;
  preferredVehicleType?: string;
  requireOnlineStatus?: boolean;
}

export async function POST(request: NextRequest) {
  try {
    // Check admin authorization
    const session = await getServerSession(authOptions);
    if (!session?.user) {
      return NextResponse.json(
        { error: 'Unauthorized - Please login' },
        { status: 401 }
      );
    }

    const userRole = (session.user as any)?.role;
    if (userRole !== 'admin') {
      return NextResponse.json(
        { error: 'Forbidden - Admin access required' },
        { status: 403 }
      );
    }

    const { bookingId, criteria, forceAuto } = await request.json();

    if (!bookingId) {
      return NextResponse.json(
        { error: 'Booking ID is required' },
        { status: 400 }
      );
    }

    // Check dispatch mode (unless forceAuto is true)
    if (!forceAuto) {
      const dispatchSettings = await prisma.dispatchSettings.findFirst({
        where: { isActive: true },
        orderBy: { createdAt: 'desc' }
      });

      if (dispatchSettings && dispatchSettings.mode === 'manual') {
        return NextResponse.json({
          success: false,
          error: 'Auto-assignment is disabled',
          message: 'Dispatch mode is set to MANUAL. Please assign drivers manually or switch to AUTO mode.',
          currentMode: 'manual'
        }, { status: 400 });
      }
    }

    // Default assignment criteria
    const assignmentCriteria: AutoAssignmentCriteria = {
      maxDistance: 50, // 50km radius
      minRating: 4.0,
      maxCurrentJobs: 2, // Leave room for one more job
      requireOnlineStatus: true,
      ...criteria
    };

    // Get booking details
    const booking = await prisma.booking.findUnique({
      where: { id: bookingId },
      include: {
        pickupAddress: true,
        dropoffAddress: true
      }
    });

    if (!booking) {
      return NextResponse.json(
        { error: 'Booking not found' },
        { status: 404 }
      );
    }

    if (booking.status !== 'CONFIRMED' || booking.driverId) {
      return NextResponse.json(
        { error: 'Booking is not available for assignment' },
        { status: 400 }
      );
    }

    // Find suitable drivers
    const suitableDrivers = await findSuitableDrivers(booking, assignmentCriteria);

    if (suitableDrivers.length === 0) {
      return NextResponse.json({
        success: false,
        message: 'No suitable drivers available',
        criteria: assignmentCriteria,
        availableDriversCount: 0
      });
    }

    // Auto-assign to best driver (highest rated with lowest current load)
    const bestDriver = suitableDrivers[0];

    // Perform assignment
    const assignmentResult = await assignBookingToDriver(bookingId, bestDriver.id, session.user.id);

    // Send notifications
    try {
      // Notify driver
      await getPusherServer().trigger(`driver-${bestDriver.id}`, 'job-assigned', {
        bookingId,
        bookingReference: booking.reference,
        assignmentId: assignmentResult.assignmentId,
        message: 'New job assigned to you!'
      });

      // Notify admin channels
      await getPusherServer().trigger('admin-channel', 'auto-assignment-completed', {
        bookingId,
        bookingReference: booking.reference,
        driverId: bestDriver.id,
        driverName: bestDriver.name,
        assignedAt: new Date()
      });

    } catch (notificationError) {
      console.error('❌ Error sending auto-assignment notifications:', notificationError);
    }

    console.log(`✅ Auto-assignment completed:`, {
      bookingId,
      bookingReference: booking.reference,
      assignedTo: bestDriver.name,
      driverId: bestDriver.id
    });

    return NextResponse.json({
      success: true,
      message: 'Booking automatically assigned successfully',
      data: {
        booking: {
          id: booking.id,
          reference: booking.reference
        },
        driver: {
          id: bestDriver.id,
          name: bestDriver.name,
          rating: bestDriver.rating,
          currentJobs: bestDriver.currentJobs
        },
        assignment: {
          id: assignmentResult.assignmentId,
          assignedAt: assignmentResult.assignedAt
        },
        alternatives: suitableDrivers.slice(1, 3).map(d => ({
          id: d.id,
          name: d.name,
          rating: d.rating
        }))
      }
    });

  } catch (error) {
    console.error('❌ Error in auto-assignment:', error);
    return NextResponse.json(
      {
        error: 'Auto-assignment failed',
        details: error instanceof Error ? error.message : 'Unknown error'
      },
      { status: 500 }
    );
  }
}

/**
 * Find suitable drivers for a booking
 */
async function findSuitableDrivers(
  booking: any, 
  criteria: AutoAssignmentCriteria
) {
  // Get all active drivers
  const drivers = await prisma.driver.findMany({
    where: {
      status: 'active',
      onboardingStatus: 'approved',
      ...(criteria.requireOnlineStatus && {
        availability: {
          status: 'online'
        }
      })
    },
    include: {
      User: {
        select: { id: true, name: true, email: true }
      },
      DriverAvailability: true,
      // ratings: {
      //   select: { overall: true }
      // },
      Booking: {
        where: {
          status: { in: ['CONFIRMED'] }
        }
      }
    }
  });

  // Filter and score drivers
  const suitableDrivers = drivers
    .filter(driver => {
      // Check current job load
      if ((driver as any).Booking?.length >= (criteria.maxCurrentJobs || 2)) {
        return false;
      }

      // Check rating
      const avgRating = driver.rating || 0;
      
      if (avgRating < (criteria.minRating || 4.0) && avgRating > 0) {
        return false;
      }

      return true;
    })
    .map(driver => {
      // Calculate score for ranking
      const avgRating = driver.rating || 5.0; // Default rating for new drivers

      const jobLoadScore = (3 - ((driver as any).Booking?.length || 0)) / 3; // Higher score for less loaded drivers
      const ratingScore = avgRating / 5; // Normalize rating to 0-1
      const availabilityScore = (driver as any).availability?.status === 'online' ? 1 : 0.5;

      const totalScore = (ratingScore * 0.4) + (jobLoadScore * 0.4) + (availabilityScore * 0.2);

      return {
        id: driver.id,
        userId: (driver as any).user?.id || driver.userId,
        name: (driver as any).user?.name || 'Unknown Driver',
        email: (driver as any).user?.email || '',
        rating: avgRating,
        currentJobs: (driver as any).Booking?.length || 0,
        isOnline: (driver as any).availability?.status === 'online',
        score: totalScore
      };
    })
    .sort((a, b) => b.score - a.score); // Sort by score descending

  return suitableDrivers;
}

/**
 * Assign booking to driver
 */
async function assignBookingToDriver(
  bookingId: string, 
  driverId: string, 
  adminId: string
) {
  const assignedAt = new Date();

  const result = await prisma.$transaction(async (tx) => {
    // Update booking
    await tx.booking.update({
      where: { id: bookingId },
      data: {
        driverId,
        updatedAt: assignedAt
      }
    });

    // Check for existing assignment
    const existingAssignment = await tx.assignment.findFirst({
      where: { 
        bookingId,
        status: { in: ['invited', 'claimed'] }
      },
      orderBy: { createdAt: 'desc' }
    });

    let assignment;
    if (existingAssignment) {
      // Update existing assignment
      assignment = await tx.assignment.update({
        where: { id: existingAssignment.id },
        data: {
          driverId,
          status: 'invited',
          expiresAt: new Date(Date.now() + 30 * 60 * 1000), // 30 minutes to accept
          updatedAt: assignedAt
        }
      });
    } else {
      // Create new assignment
      assignment = await tx.assignment.create({
        data: {
          bookingId,
          driverId,
          status: 'invited',
          expiresAt: new Date(Date.now() + 30 * 60 * 1000), // 30 minutes to accept
          updatedAt: assignedAt
        }
      });
    }

    // Create audit log
    await tx.auditLog.create({
      data: {
        actorId: adminId,
        actorRole: 'admin',
        action: 'auto_assignment_completed',
        targetType: 'booking',
        targetId: bookingId,
        details: {
          driverId,
          assignmentId: assignment.id,
          method: 'auto_assignment',
          assignedAt: assignedAt.toISOString()
        }
      }
    });

    return {
      assignmentId: assignment.id,
      assignedAt
    };
  });

  return result;
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
import { logger } from '@/lib/logger';
import Pusher from 'pusher';

// Initialize Pusher
const pusher = new Pusher({
  appId: process.env.PUSHER_APP_ID!,
  key: process.env.PUSHER_KEY!,
  secret: process.env.PUSHER_SECRET!,
  cluster: process.env.PUSHER_CLUSTER!,
  useTLS: true,
});

export const dynamic = 'force-dynamic';

/**
 * POST /api/admin/bonuses/[id]/approve
 * 
 * Approve or reject a bonus request
 * 
 * If approved:
 * - Updates BonusRequest status to 'approved'
 * - Sets approvedAmountPence
 * - Creates AdminApproval audit record
 * - If bonus was blocking job completion, triggers earnings creation
 * - Notifies driver
 * 
 * Only accessible by admin users
 */
export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const { id: bonusRequestId } = await params;

  try {
    const session = await getServerSession(authOptions);
    
    // Admin-only authentication
    if (!session?.user || (session.user as any).role !== 'admin') {
      return NextResponse.json(
        { error: 'Unauthorized - Admin access required' },
        { status: 401 }
      );
    }

    const adminId = (session.user as any).id;
    const adminName = (session.user as any).name || 'Admin';

    const body = await request.json();
    const {
      action = 'approved', // 'approved' or 'rejected'
      approved_amount_pence, // Optional: override requested amount
      admin_notes,
    } = body;

    if (!['approved', 'rejected'].includes(action)) {
      return NextResponse.json(
        { error: 'Invalid action. Must be "approved" or "rejected"' },
        { status: 400 }
      );
    }

    // Get bonus request
    const prismaWithBonusRequest = prisma as any;
    
    if (!prismaWithBonusRequest.bonusRequest) {
      return NextResponse.json(
        { error: 'BonusRequest model not available. Run prisma generate.' },
        { status: 500 }
      );
    }

    const bonusRequest = await prismaWithBonusRequest.bonusRequest.findUnique({
      where: { id: bonusRequestId },
      include: {
        driver: {
          include: {
            user: {
              select: {
                name: true,
                email: true,
              },
            },
          },
        },
        assignment: {
          include: {
            Booking: {
              select: {
                reference: true,
              },
            },
          },
        },
      },
    });

    if (!bonusRequest) {
      return NextResponse.json(
        { error: 'Bonus request not found' },
        { status: 404 }
      );
    }

    if (bonusRequest.status !== 'pending') {
      return NextResponse.json(
        { error: `Bonus request already ${bonusRequest.status}` },
        { status: 409 }
      );
    }

    // Determine final amount
    const finalAmount = action === 'approved' 
      ? (approved_amount_pence || bonusRequest.requestedAmountPence)
      : 0;

    // Update BonusRequest
    const updatedBonus = await prismaWithBonusRequest.bonusRequest.update({
      where: { id: bonusRequestId },
      data: {
        status: action,
        approvedAmountPence: finalAmount,
        reviewedBy: adminId,
        reviewedAt: new Date(),
        adminNotes: admin_notes || undefined,
      },
    });

    // Create AdminApproval audit record
    const prismaWithAdminApproval = prisma as any;
    let adminApprovalId: string | undefined;

    if (prismaWithAdminApproval.adminApproval) {
      const adminApproval = await prismaWithAdminApproval.adminApproval.create({
        data: {
          type: 'bonus_approval',
          entityType: 'bonus_request',
          entityId: bonusRequestId,
          adminId,
          adminName,
          action,
          previousValue: {
            status: 'pending',
            requestedAmount: bonusRequest.requestedAmountPence,
            bonusType: bonusRequest.bonusType,
            reason: bonusRequest.reason,
          },
          newValue: {
            status: action,
            approvedAmount: finalAmount,
            reviewedBy: adminName,
          },
          reason: action === 'approved' 
            ? `Bonus approved: ${bonusRequest.bonusType}`
            : `Bonus rejected: ${bonusRequest.bonusType}`,
          notes: admin_notes || undefined,
          approvedAt: new Date(),
        },
      });
      adminApprovalId = adminApproval.id;
    }

    // If approved, create a DriverEarnings record for the bonus
    if (action === 'approved') {
      // Create bonus earnings record
      await prisma.driverEarnings.create({
        data: {
          driverId: bonusRequest.driverId,
          assignmentId: bonusRequest.assignmentId || null,
          baseAmountPence: 0, // Bonuses don't have base amounts
          surgeAmountPence: 0, // Bonuses don't have surge amounts
          tipAmountPence: 0, // Bonuses don't have tips
          feeAmountPence: 0, // Bonuses don't have platform fees
          netAmountPence: finalAmount,
          currency: 'gbp',
          calculatedAt: new Date(),
          paidOut: false,
        },
      });
    }

    // Notify driver
    const notificationType = action === 'approved' ? 'payout_processed' : 'system_alert';
    const notificationTitle = action === 'approved'
      ? 'Bonus Approved! 🎉'
      : 'Bonus Request Update';
    const notificationMessage = action === 'approved'
      ? `Your ${bonusRequest.bonusType} bonus request for £${(finalAmount / 100).toFixed(2)} has been approved and added to your earnings!`
      : `Your bonus request has been reviewed. ${admin_notes ? `Note: ${admin_notes}` : ''}`;

    await prisma.driverNotification.create({
      data: {
        driverId: bonusRequest.driverId,
        type: notificationType,
        title: notificationTitle,
        message: notificationMessage,
        read: false,
      },
    });

    // Send real-time notification
    try {
      await pusher.trigger(`driver-${bonusRequest.driverId}`, 'bonus-decision', {
        bonusRequestId,
        action,
        amount: finalAmount,
        amountGBP: (finalAmount / 100).toFixed(2),
        bonusType: bonusRequest.bonusType,
        reviewedBy: adminName,
        notes: admin_notes,
        timestamp: new Date().toISOString(),
      });
    } catch (pusherError) {
      logger.error('Failed to send real-time bonus decision notification', pusherError as Error);
    }

    logger.info(`Admin ${action} bonus request`, {
      adminId,
      adminName,
      bonusRequestId,
      driverId: bonusRequest.driverId,
      bonusType: bonusRequest.bonusType,
      requestedAmount: bonusRequest.requestedAmountPence,
      approvedAmount: finalAmount,
      adminNotes: admin_notes,
    });

    return NextResponse.json({
      success: true,
      action,
      message: `Bonus ${action} successfully`,
      data: {
        bonusRequestId,
        driverId: bonusRequest.driverId,
        driverName: bonusRequest.driver.user.name,
        bonusType: bonusRequest.bonusType,
        requestedAmount: bonusRequest.requestedAmountPence,
        approvedAmount: finalAmount,
        reviewedBy: adminName,
        reviewedAt: new Date().toISOString(),
        adminApprovalId,
        assignmentId: bonusRequest.assignmentId,
        bookingReference: bonusRequest.assignment?.Booking?.reference,
      },
    });

  } catch (error) {
    logger.error('Error processing bonus decision', error as Error, {
      service: 'admin-bonus-approve',
      requestId: bonusRequestId,
    });
    
    return NextResponse.json(
      {
        error: 'Failed to process bonus decision',
        details: error instanceof Error ? error.message : 'Unknown error',
      },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
import { logger } from '@/lib/logger';

export const dynamic = 'force-dynamic';

/**
 * GET /api/admin/bonuses/pending
 * 
 * Returns list of bonus requests awaiting admin approval
 * 
 * Only accessible by admin users
 */
export async function GET(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    
    // Admin-only authentication
    if (!session?.user || (session.user as any).role !== 'admin') {
      return NextResponse.json(
        { error: 'Unauthorized - Admin access required' },
        { status: 401 }
      );
    }

    const adminId = (session.user as any).id;

    // Query pending bonus requests
    const prismaWithBonusRequest = prisma as any;
    
    if (!prismaWithBonusRequest.bonusRequest) {
      logger.warn('BonusRequest model not available in Prisma client');
      return NextResponse.json({
        success: true,
        count: 0,
        pendingBonuses: [],
        message: 'BonusRequest model not yet available. Run prisma generate.',
      });
    }

    const pendingBonuses = await prismaWithBonusRequest.bonusRequest.findMany({
      where: {
        status: 'pending',
      },
      include: {
        driver: {
          include: {
            user: {
              select: {
                id: true,
                name: true,
                email: true,
              },
            },
          },
        },
        assignment: {
          include: {
            Booking: {
              select: {
                id: true,
                reference: true,
                customerName: true,
                totalGBP: true,
              },
            },
          },
        },
      },
      orderBy: {
        requestedAt: 'desc',
      },
      take: 100,
    });

    // Get driver performance context
    const driverIds = [...new Set(pendingBonuses.map((b: any) => b.driverId))] as string[];
    
    // Use findMany instead of groupBy to avoid circular reference errors
    const allDriverEarnings = await prisma.driverEarnings.findMany({
      where: {
        driverId: { in: driverIds },
        calculatedAt: {
          gte: new Date(Date.now() - 30 * 24 * 60 * 60 * 1000), // Last 30 days
        },
      },
      select: {
        driverId: true,
        netAmountPence: true,
      },
    });

    // Calculate stats manually
    const driverStatsMap = new Map<string, { completedJobs: number; totalEarnings: number; avgEarnings: number }>();
    for (const earning of allDriverEarnings) {
      const existing = driverStatsMap.get(earning.driverId) || { 
        completedJobs: 0, 
        totalEarnings: 0, 
        avgEarnings: 0 
      };
      existing.completedJobs += 1;
      existing.totalEarnings += earning.netAmountPence;
      driverStatsMap.set(earning.driverId, existing);
    }
    
    // Calculate averages
    for (const [driverId, stats] of driverStatsMap.entries()) {
      stats.avgEarnings = Math.floor(stats.totalEarnings / stats.completedJobs);
    }

    // Format response
    const bonusList = pendingBonuses.map((bonus: any) => {
      const stats = driverStatsMap.get(bonus.driverId) || {
        completedJobs: 0,
        totalEarnings: 0,
        avgEarnings: 0,
      } as { completedJobs: number; totalEarnings: number; avgEarnings: number };

      return {
        bonusRequestId: bonus.id,
        driver: {
          id: bonus.driver.id,
          name: bonus.driver.user.name,
          email: bonus.driver.user.email,
          performance: {
            completedJobs30d: stats.completedJobs,
            totalEarnings30d: stats.totalEarnings,
            avgEarnings30d: stats.avgEarnings,
            totalEarnings30dGBP: (stats.totalEarnings / 100).toFixed(2),
            avgEarnings30dGBP: (stats.avgEarnings / 100).toFixed(2),
          },
        },
        assignment: {
          id: bonus.assignmentId,
          bookingId: bonus.assignment.Booking?.id,
          bookingReference: bonus.assignment.Booking?.reference,
          customerName: bonus.assignment.Booking?.customerName,
          customerPaid: bonus.assignment.Booking?.totalGBP,
        },
        bonusDetails: {
          type: bonus.bonusType,
          requestedAmount: bonus.requestedAmountPence,
          requestedAmountGBP: (bonus.requestedAmountPence / 100).toFixed(2),
          reason: bonus.reason,
          requestedBy: bonus.requestedBy,
          requestedAt: bonus.requestedAt,
        },
        timing: {
          waitingTime: Math.floor(
            (Date.now() - new Date(bonus.requestedAt).getTime()) / 1000 / 60
          ), // Minutes waiting
        },
      };
    });

    logger.info('Admin retrieved pending bonuses list', {
      adminId,
      count: bonusList.length,
      driverCount: driverIds.length,
    });

    return NextResponse.json({
      success: true,
      count: bonusList.length,
      pendingBonuses: bonusList,
      metadata: {
        retrievedAt: new Date().toISOString(),
      },
    });

  } catch (error) {
    logger.error('Error retrieving pending bonuses', error as Error, {
      service: 'admin-pending-bonuses',
    });
    
    return NextResponse.json(
      {
        error: 'Failed to retrieve pending bonuses',
        details: error instanceof Error ? error.message : 'Unknown error',
      },
      { status: 500 }
    );
  }
}

