        { error: 'Unauthorized - Admin access required' },
        { status: 401 }
      );
    }

    const adminId = (session.user as any).id;
    const adminName = (session.user as any).name || 'Admin';

    const body = await request.json();
    const {
      driver_id,
      assignment_id,
      bonus_type = 'manual_admin_bonus',
      requested_amount_pence,
      reason,
      auto_approve = false, // If true, immediately approve
    } = body;

    // Validation
    if (!driver_id) {
      return NextResponse.json(
        { error: 'driver_id is required' },
        { status: 400 }
      );
    }

    if (!assignment_id) {
      return NextResponse.json(
        { error: 'assignment_id is required' },
        { status: 400 }
      );
    }

    if (!requested_amount_pence || requested_amount_pence <= 0) {
      return NextResponse.json(
        { error: 'requested_amount_pence must be positive' },
        { status: 400 }
      );
    }

    if (!reason) {
      return NextResponse.json(
        { error: 'reason is required' },
        { status: 400 }
      );
    }

    // Verify driver exists
    const driver = await prisma.driver.findUnique({
      where: { id: driver_id },
      include: {
        User: {
          select: {
            name: true,
            email: true,
          },
        },
      },
    });

    if (!driver) {
      return NextResponse.json(
        { error: 'Driver not found' },
        { status: 404 }
      );
    }

    // Verify assignment exists
    const assignment = await prisma.assignment.findUnique({
      where: { id: assignment_id },
      include: {
        Booking: {
          select: {
            reference: true,
          },
        },
      },
    });

    if (!assignment) {
      return NextResponse.json(
        { error: 'Assignment not found' },
        { status: 404 }
      );
    }

    if (assignment.driverId !== driver_id) {
      return NextResponse.json(
        { error: 'Assignment does not belong to this driver' },
        { status: 400 }
      );
    }

    // Create BonusRequest
    const prismaWithBonusRequest = prisma as any;
    
    if (!prismaWithBonusRequest.bonusRequest) {
      return NextResponse.json(
        { error: 'BonusRequest model not available. Run prisma generate.' },
        { status: 500 }
      );
    }

    const bonusRequest = await prismaWithBonusRequest.bonusRequest.create({
      data: {
        assignmentId: assignment_id,
        driverId: driver_id,
        bonusType: bonus_type,
        requestedAmountPence: requested_amount_pence,
        approvedAmountPence: auto_approve ? requested_amount_pence : null,
        status: auto_approve ? 'approved' : 'pending',
        reason,
        requestedBy: adminId, // Admin created it
        requestedAt: new Date(),
        reviewedBy: auto_approve ? adminId : null,
        reviewedAt: auto_approve ? new Date() : null,
        adminNotes: `Manually created by ${adminName}`,
      },
    });

    // If auto-approve, create AdminApproval audit record
    let adminApprovalId: string | undefined;

    if (auto_approve) {
      const prismaWithAdminApproval = prisma as any;
      
      if (prismaWithAdminApproval.adminApproval) {
        const adminApproval = await prismaWithAdminApproval.adminApproval.create({
          data: {
            type: 'bonus_approval',
            entityType: 'bonus_request',
            entityId: bonusRequest.id,
            adminId,
            adminName,
            action: 'approved',
            previousValue: null,
            newValue: {
              status: 'approved',
              amount: requested_amount_pence,
              createdAndApprovedBy: adminName,
            },
            reason: `Manual bonus creation: ${bonus_type}`,
            notes: reason,
            approvedAt: new Date(),
          },
        });
        adminApprovalId = adminApproval.id;
      }

      // Notify driver
      await prisma.driverNotification.create({
        data: {
          driverId: driver_id,
          type: 'payout_processed',
          title: 'Bonus Awarded! 🎉',
          message: `You've been awarded a ${bonus_type} bonus of £${(requested_amount_pence / 100).toFixed(2)}! ${reason}`,
          read: false,
        },
      });
    }

    logger.info('Admin created manual bonus request', {
      adminId,
      adminName,
      bonusRequestId: bonusRequest.id,
      driverId: driver_id,
      assignmentId: assignment_id,
      bonusType: bonus_type,
      amount: requested_amount_pence,
      autoApprove: auto_approve,
      reason,
    });

    return NextResponse.json({
      success: true,
      message: auto_approve 
        ? 'Bonus created and automatically approved' 
        : 'Bonus request created successfully',
      data: {
        bonusRequestId: bonusRequest.id,
        driverId: driver_id,
        driverName: driver.User.name,
        assignmentId: assignment_id,
        bookingReference: assignment.Booking?.reference,
        bonusType: bonus_type,
        requestedAmount: requested_amount_pence,
        requestedAmountGBP: (requested_amount_pence / 100).toFixed(2),
        status: bonusRequest.status,
        reason,
        createdBy: adminName,
        createdAt: bonusRequest.requestedAt.toISOString(),
        adminApprovalId: auto_approve ? adminApprovalId : undefined,
      },
    });

  } catch (error) {
    logger.error('Error creating manual bonus request', error as Error, {
      service: 'admin-create-bonus',
    });
    
    return NextResponse.json(
      {
        error: 'Failed to create bonus request',
        details: error instanceof Error ? error.message : 'Unknown error',
      },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

// GET /api/admin/booking-luxury - List all bookings for admin
export async function GET(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user || (session.user as any).role !== 'admin') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const { searchParams } = new URL(request.url);
    const page = parseInt(searchParams.get('page') || '1');
    const limit = parseInt(searchParams.get('limit') || '20');
    const status = searchParams.get('status');
    const search = searchParams.get('search');
    const sortBy = searchParams.get('sortBy') || 'createdAt';
    const sortOrder = searchParams.get('sortOrder') || 'desc';

    const skip = (page - 1) * limit;

    // Build where clause
    const where: any = {};
    
    if (status && status !== 'all') {
      where.status = status;
    }
    
    if (search) {
      where.OR = [
        { reference: { contains: search, mode: 'insensitive' } },
        { customerName: { contains: search, mode: 'insensitive' } },
        { customerEmail: { contains: search, mode: 'insensitive' } },
        { customerPhone: { contains: search, mode: 'insensitive' } },
      ];
    }

    // Get bookings with pagination
    const [bookings, total] = await Promise.all([
      prisma.booking.findMany({
        where,
        include: {
          pickupAddress: true,
          dropoffAddress: true,
          pickupProperty: true,
          dropoffProperty: true,
          BookingItem: true,
          customer: {
            select: {
              id: true,
              name: true,
              email: true,
            },
          },
          driver: {
            include: {
              User: {
                select: {
                  id: true,
                  name: true,
                  email: true,
                },
              },
            },
          },
        },
        orderBy: {
          [sortBy]: sortOrder,
        },
        skip,
        take: limit,
      }),
      prisma.booking.count({ where }),
    ]);

    return NextResponse.json({
      success: true,
      bookings,
      pagination: {
        page,
        limit,
        total,
        totalPages: Math.ceil(total / limit),
      },
    });
  } catch (error) {
    console.error('❌ Error fetching admin bookings:', error);
    return NextResponse.json(
      { error: 'Failed to fetch bookings' },
      { status: 500 }
    );
  }
}

// POST /api/admin/booking-luxury - Create booking on behalf of customer (admin only)
export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user || (session.user as any).role !== 'admin') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    // For admin-created bookings, redirect to the main booking-luxury endpoint
    // but with admin context
    const bookingData = await request.json();
    
    // Add admin context to the booking data
    const adminBookingData = {
      ...bookingData,
      adminCreated: true,
      adminId: session.user.id,
    };

    // Forward to the main booking-luxury endpoint
    const response = await fetch(`${request.nextUrl.origin}/api/booking-luxury`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        // Forward the session cookie for authentication
        'Cookie': request.headers.get('Cookie') || '',
      },
      body: JSON.stringify(adminBookingData),
    });

    const result = await response.json();

    if (!response.ok) {
      return NextResponse.json(result, { status: response.status });
    }

    // Log admin action
    await prisma.auditLog.create({
      data: {
        actorId: session.user.id,
        actorRole: 'admin',
        action: 'admin_booking_created',
        targetType: 'booking',
        targetId: result.booking.id,
        userId: session.user.id,
        details: {
          bookingReference: result.booking.reference,
          customerName: bookingData.customer.name,
          customerEmail: bookingData.customer.email,
          totalAmount: result.booking.pricing.total,
          createdVia: 'admin_panel',
        },
      },
    });

    return NextResponse.json({
      ...result,
      adminCreated: true,
    });
  } catch (error) {
    console.error('❌ Error creating admin booking:', error);
    return NextResponse.json(
      { error: 'Failed to create booking' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
import { sendEmail } from '@/lib/email';
import { generateEmploymentContract } from '@/lib/contractGenerator';

export async function POST(
  request: NextRequest,
  { params }: { params: { id: string } }
) {
  try {
    // Check authentication
    const session = await getServerSession(authOptions);
    if (!session || session.user.role !== 'admin') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const { id } = params;

    // Find application
    const application = await prisma.careerApplication.findUnique({
      where: { id },
    });

    if (!application) {
      return NextResponse.json(
        { success: false, error: 'Application not found' },
        { status: 404 }
      );
    }

    if (application.status === 'approved' || application.status === 'contract_sent') {
      return NextResponse.json(
        { success: false, error: 'Application already approved' },
        { status: 400 }
      );
    }

    // Update application status
    const updatedApplication = await prisma.careerApplication.update({
      where: { id },
      data: {
        status: 'approved',
        reviewedBy: session.user.name || session.user.email,
        reviewedAt: new Date(),
      },
    });

    // Generate employment contract PDF
    const contractPdf = await generateEmploymentContract({
      applicantName: application.fullName,
      applicantEmail: application.email,
      position: application.position,
      startDate: new Date(Date.now() + 14 * 24 * 60 * 60 * 1000), // 2 weeks from now
    });

    // Send contract email to applicant
    await sendEmail({
      to: application.email,
      subject: 'Congratulations! Employment Contract - Speedy Van',
      html: `
        <h2>Congratulations, ${application.fullName}!</h2>
        <p>We are pleased to inform you that your application for the <strong>${application.position}</strong> position has been approved.</p>
        <p>Please find attached your employment contract. Please review it carefully and sign it at your earliest convenience.</p>
        <br>
        <p><strong>Next Steps:</strong></p>
        <ol>
          <li>Review the attached employment contract</li>
          <li>Sign and return the contract within 7 days</li>
          <li>Complete any required onboarding paperwork</li>
        </ol>
        <br>
        <p>If you have any questions, please don't hesitate to contact us at careers@speedy-van.co.uk</p>
        <br>
        <p>We look forward to welcoming you to the Speedy Van team!</p>
        <br>
        <p>Best regards,<br>Speedy Van HR Team</p>
      `,
      attachments: [
        {
          filename: `Employment_Contract_${application.fullName.replace(/\s/g, '_')}.pdf`,
          content: contractPdf,
          contentType: 'application/pdf',
        },
      ],
    });

    // Update contract sent status
    await prisma.careerApplication.update({
      where: { id },
      data: {
        contractSent: true,
        contractSentAt: new Date(),
        status: 'contract_sent',
      },
    });

    return NextResponse.json({
      success: true,
      message: 'Application approved and contract sent successfully',
      data: updatedApplication,
    });
  } catch (error) {
    console.error('Error approving application:', error);
    return NextResponse.json(
      { success: false, error: 'Failed to approve application' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
import { sendEmail } from '@/lib/email';
import { z } from 'zod';

const rejectSchema = z.object({
  reason: z.string().optional(),
});

export async function POST(
  request: NextRequest,
  { params }: { params: { id: string } }
) {
  try {
    // Check authentication
    const session = await getServerSession(authOptions);
    if (!session || session.user.role !== 'admin') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const { id } = params;
    const body = await request.json();
    const { reason } = rejectSchema.parse(body);

    // Find application
    const application = await prisma.careerApplication.findUnique({
      where: { id },
    });

    if (!application) {
      return NextResponse.json(
        { success: false, error: 'Application not found' },
        { status: 404 }
      );
    }

    // Update application status
    const updatedApplication = await prisma.careerApplication.update({
      where: { id },
      data: {
        status: 'rejected',
        reviewedBy: session.user.name || session.user.email,
        reviewedAt: new Date(),
        rejectionReason: reason,
      },
    });

    // Send rejection email to applicant
    await sendEmail({
      to: application.email,
      subject: 'Application Update - Speedy Van Careers',
      html: `
        <h2>Application Update</h2>
        <p>Dear ${application.fullName},</p>
        <p>Thank you for your interest in the <strong>${application.position}</strong> position at Speedy Van.</p>
        <p>After careful consideration, we regret to inform you that we have decided to move forward with other candidates for this position.</p>
        ${reason ? `<p><strong>Feedback:</strong> ${reason}</p>` : ''}
        <p>We appreciate the time you took to apply and wish you the best in your job search.</p>
        <br>
        <p>Please feel free to apply for future opportunities at Speedy Van.</p>
        <br>
        <p>Best regards,<br>Speedy Van HR Team</p>
      `,
    });

    return NextResponse.json({
      success: true,
      message: 'Application rejected successfully',
      data: updatedApplication,
    });
  } catch (error) {
    console.error('Error rejecting application:', error);
    return NextResponse.json(
      { success: false, error: 'Failed to reject application' },
      { status: 500 }
    );
  }
}

