import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { requireAdmin } from '@/lib/auth';
import { getPusherServer } from '@/lib/pusher';

export const dynamic = 'force-dynamic';

export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const authResult = await requireAdmin(request);
    if (authResult instanceof NextResponse) {
      return authResult;
    }

    const { id: conversationId } = await params;

    // Fetch all messages for this chat session
    const messages = await prisma.message.findMany({
      where: {
        sessionId: conversationId,
      },
      include: {
        User: {
          select: {
            id: true,
            name: true,
            role: true,
          },
        },
      },
      orderBy: {
        createdAt: 'asc',
      },
    });

    // Format messages for frontend
    const formattedMessages = messages.map((msg) => ({
      id: msg.id,
      senderId: msg.senderId,
      // ✅ Replace admin name with "Support" for privacy
      senderName: msg.User.role === 'admin' ? 'Support' : (msg.User.name || 'Unknown'),
      senderRole: msg.User.role,
      message: msg.content,
      timestamp: msg.createdAt.toISOString(),
      read: true,
    }));

    return NextResponse.json({
      messages: formattedMessages,
      total: formattedMessages.length,
    });
  } catch (error) {
    console.error('Admin chat messages GET error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const authResult = await requireAdmin(request);
    if (authResult instanceof NextResponse) {
      return authResult;
    }

    const { id: conversationId } = await params;
    const { message } = await request.json();

    if (!message || typeof message !== 'string' || message.trim().length === 0) {
      return NextResponse.json(
        { error: 'Message is required' },
        { status: 400 }
      );
    }

    // Verify chat session exists
    const chatSession = await prisma.chatSession.findUnique({
      where: { id: conversationId },
      include: {
        ChatParticipant: {
          where: { role: 'driver' },
          include: {
            User: true,
          },
        },
      },
    });

    if (!chatSession) {
      return NextResponse.json(
        { error: 'Chat session not found' },
        { status: 404 }
      );
    }

    // Generate unique message ID
    const messageId = `msg_${Date.now()}_${Math.random().toString(36).substring(7)}`;

    // Save message to database
    const newMessage = await prisma.message.create({
      data: {
        id: messageId,
        senderId: authResult.id,
        sessionId: conversationId,
        content: message.trim(),
        type: 'text',
        status: 'sent',
        updatedAt: new Date(),
      },
      include: {
        User: {
          select: {
            id: true,
            name: true,
            role: true,
          },
        },
      },
    });

    // Update session updatedAt
    await prisma.chatSession.update({
      where: { id: conversationId },
      data: { updatedAt: new Date() },
    });

    // Send real-time notification to driver via Pusher
    try {
      const driverParticipant = chatSession.ChatParticipant.find((p) => p.role === 'driver');
      if (driverParticipant && driverParticipant.userId) {
        // ✅ CRITICAL FIX: Get Driver.id (not User.id) for Pusher channel
        const driverRecord = await prisma.driver.findUnique({
          where: { userId: driverParticipant.userId },
          select: { id: true }
        });

        if (driverRecord) {
          const pusher = getPusherServer();
          // ✅ Use Driver.id for channel name (iOS app expects this)
          await pusher.trigger(`driver-${driverRecord.id}`, 'admin_message', {
            id: newMessage.id,
            messageId: newMessage.id,  // ✅ Add messageId for deduplication
            content: newMessage.content,
            message: newMessage.content,  // ✅ Add 'message' field for backward compatibility
            sender: 'admin',
            senderName: 'Support',  // ✅ Always use "Support" for privacy
            timestamp: newMessage.createdAt.toISOString(),
            sessionId: conversationId,
          });

          console.log(`📤 Sent admin message to driver channel: driver-${driverRecord.id}`);
        } else {
          console.error('❌ Driver record not found for userId:', driverParticipant.userId);
        }
      }
    } catch (pusherError) {
      console.error('❌ Pusher notification failed:', pusherError);
      // Don't fail the request if Pusher fails
    }

    return NextResponse.json({
      message: {
        id: newMessage.id,
        senderId: newMessage.senderId,
        senderName: 'Support',  // ✅ Always use "Support" for privacy
        senderRole: 'admin',
        message: newMessage.content,
        timestamp: newMessage.createdAt.toISOString(),
        read: false,
      },
      success: true,
    });
  } catch (error) {
    console.error('Admin chat send message error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { requireAdmin } from '@/lib/auth';

export const dynamic = 'force-dynamic';

export async function GET(request: NextRequest) {
  try {
    const authResult = await requireAdmin(request);
    if (authResult instanceof NextResponse) {
      return authResult;
    }

    // Fetch all active chat sessions with driver-admin conversations
    const chatSessions = await prisma.chatSession.findMany({
      where: {
        type: 'driver_admin',
        isActive: true,
      },
      include: {
        ChatParticipant: {
          include: {
            User: {
              select: {
                id: true,
                name: true,
                role: true,
              },
            },
          },
        },
        Message: {
          orderBy: {
            createdAt: 'desc',
          },
          take: 1,
          include: {
            User: {
              select: {
                id: true,
                name: true,
                role: true,
              },
            },
          },
        },
      },
      orderBy: {
        updatedAt: 'desc',
      },
    });

    // Format conversations for frontend
    const conversations = chatSessions.map((session) => {
      const lastMessage = session.Message[0];
      const participants = session.ChatParticipant.filter((p) => p.User).map((p) => ({
        id: p.User!.id,
        name: p.User!.name || 'Unknown',
        role: p.User!.role,
      }));

      // Count unread messages (messages not read by admin)
      // For now, set to 0 as we don't have read tracking yet
      const unreadCount = 0;

      return {
        id: session.id,
        participants,
        lastMessage: lastMessage
          ? {
              id: lastMessage.id,
              senderId: lastMessage.senderId,
              senderName: lastMessage.User.name || 'Unknown',
              senderRole: lastMessage.User.role,
              message: lastMessage.content,
              timestamp: lastMessage.createdAt.toISOString(),
              read: true,
            }
          : null,
        unreadCount,
        updatedAt: session.updatedAt.toISOString(),
      };
    });

    return NextResponse.json({
      conversations: conversations.filter((c) => c.lastMessage !== null),
      total: conversations.length,
    });
  } catch (error) {
    console.error('Admin chat conversations GET error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { requireAdmin } from '@/lib/auth';
import { getPusherServer } from '@/lib/pusher';

export const dynamic = 'force-dynamic';

// Simple in-memory store for admin online status
const adminStatusStore = new Map<string, { status: 'online' | 'offline'; lastActive: Date }>();

export async function POST(request: NextRequest) {
  try {
    const authResult = await requireAdmin(request);
    if (authResult instanceof NextResponse) {
      return authResult;
    }

    const { status } = await request.json();

    if (!status || !['online', 'offline'].includes(status)) {
      return NextResponse.json(
        { error: 'Invalid status. Must be "online" or "offline"' },
        { status: 400 }
      );
    }

    // Update admin status in memory store
    adminStatusStore.set(authResult.id, {
      status,
      lastActive: new Date()
    });

    // Broadcast admin status to all drivers via Pusher
    try {
      const pusher = getPusherServer();
      
      // Get all active chat sessions to notify their drivers
      const { prisma } = await import('@/lib/prisma');
      const activeSessions = await prisma.chatSession.findMany({
        where: {
          type: 'driver_admin',
          isActive: true
        },
        include: {
          ChatParticipant: {
            where: { role: 'driver' },
            include: {
              User: {
                include: {
                  driver: {
                    select: {
                      id: true
                    }
                  }
                }
              }
            }
          }
        }
      });

      // Notify each driver
      const notifications = activeSessions.map(session => {
        const driverParticipant = session.ChatParticipant.find(p => p.role === 'driver');
        if (driverParticipant?.User?.driver?.id) {
          return pusher.trigger(`driver-${driverParticipant.User.driver.id}`, 'admin_status', {
            status,
            lastActive: new Date().toISOString(),
            adminId: authResult.id
          });
        }
        return Promise.resolve();
      });

      await Promise.all(notifications);
      
      console.log(`✅ Broadcasted admin status (${status}) to ${notifications.length} drivers`);
    } catch (pusherError) {
      console.error('❌ Pusher admin status broadcast failed:', pusherError);
    }

    return NextResponse.json({
      success: true,
      status
    });

  } catch (error) {
    console.error('Admin status update error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

