import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { requireAdmin } from '@/lib/auth';
import { createAuditLog } from '@/lib/audit';

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    // Verify admin role
    const authResult = await requireAdmin(request);
    if (authResult instanceof NextResponse) {
      return authResult;
    }
    const user = authResult;

    const { id: customerId } = await params;
    const body = await request.json();
    const { action, amount, reason, bookingId, notes } = body;

    // Get customer
    const customer = await prisma.user.findUnique({
      where: { id: customerId, role: 'customer' },
    });

    if (!customer) {
      return NextResponse.json(
        { error: 'Customer not found' },
        { status: 404 }
      );
    }

    switch (action) {
      case 'issue_refund':
        return await handleRefund(
          user.id,
          customerId,
          bookingId,
          amount,
          reason,
          notes
        );

      case 'issue_credit':
        return await handleCredit(
          user.id,
          customerId,
          amount,
          reason,
          notes
        );

      case 'add_flag':
        return await handleAddFlag(user.id, customerId, reason, notes);

      case 'remove_flag':
        return await handleRemoveFlag(
          user.id,
          customerId,
          reason,
          notes
        );

      case 'export_data':
        return await handleExportData(user.id, customerId);

      case 'resend_invoice':
        return await handleResendInvoice(
          user.id,
          customerId,
          bookingId
        );

      default:
        return NextResponse.json({ error: 'Invalid action' }, { status: 400 });
    }
  } catch (error) {
    console.error('Error processing customer action:', error);
    return NextResponse.json(
      { error: 'Failed to process action' },
      { status: 500 }
    );
  }
}

async function handleRefund(
  adminId: string,
  customerId: string,
  bookingId: string,
  amount: number,
  reason: string,
  notes: string
) {
  // Get booking
  const booking = await prisma.booking.findFirst({
    where: {
      id: bookingId,
      customerId,
      status: 'COMPLETED',
    },
  });

  if (!booking) {
    return NextResponse.json(
      { error: 'Booking not found or not paid' },
      { status: 404 }
    );
  }

  if (amount > (booking.totalGBP || 0)) {
    return NextResponse.json(
      { error: 'Refund amount cannot exceed booking amount' },
      { status: 400 }
    );
  }

  // TODO: Implement proper refund creation
  // For now, return success without creating refund record
  // const refund = await prisma.refund.create({
  //   data: {
  //     paymentId: booking.stripePaymentIntentId || '',
  //     amount: Math.round(amount * 100),
  //     reason,
  //     status: 'pending'
  //   }
  // });

  // Update booking
  await prisma.booking.update({
    where: { id: bookingId },
    data: {
      status: 'CANCELLED',
    },
  });

  // Create audit log
  await createAuditLog(
    adminId,
    'refund.issued',
    bookingId,
    { amount, reason, notes, refundId: 'pending' }
  );

  return NextResponse.json({
    message: 'Refund issued successfully',
    refund: {
      id: 'pending',
      amount,
      reason,
      status: 'pending',
    },
  });
}

