  bookingId: string
) {
  // Get booking
  const booking = await prisma.booking.findFirst({
    where: {
      id: bookingId,
      customerId,
    },
  });

  if (!booking) {
    return NextResponse.json({ error: 'Booking not found' }, { status: 404 });
  }

  // Create audit log
  await createAuditLog(adminId, 'invoice.resent', bookingId, { targetType: 'Booking', before: null, after: { customerId } });

  return NextResponse.json({
    message: 'Invoice resent successfully',
    booking: {
      id: booking.id,
      code: booking.reference,
      amount: booking.totalGBP || 0,
    },
  });
}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { requireRole } from '@/lib/auth';
import { createAuditLog } from '@/lib/audit';

export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    // Verify admin role
    const authResult = await requireRole(request, 'admin');
    if (authResult instanceof NextResponse) {
      return authResult;
    }
    const user = authResult;

    const { id: customerId } = await params;

    // Get detailed customer information
    const customer = await prisma.user.findUnique({
      where: { id: customerId, role: 'customer' },
      select: {
        id: true,
        name: true,
        email: true,
        createdAt: true,
        emailVerified: true,
        Booking: {
          select: {
            id: true,
            reference: true,
            status: true,
            totalGBP: true,
            pickupAddress: true,
            dropoffAddress: true,
            scheduledAt: true,
            createdAt: true,
            paidAt: true,
            driver: {
              select: {
                id: true,
                User: {
                  select: {
                    name: true,
                  },
                },
              },
            },
          },
          orderBy: { createdAt: 'desc' },
        },
        Address: {
          select: {
            id: true,
            label: true,
            line1: true,
            line2: true,
            city: true,
            postcode: true,
            floor: true,
            flat: true,
            lift: true,
            notes: true,
            isDefault: true,
            createdAt: true,
          },
          orderBy: { createdAt: 'desc' },
        },
        Contact: {
          select: {
            id: true,
            label: true,
            name: true,
            phone: true,
            email: true,
            notes: true,
            isDefault: true,
            createdAt: true,
          },
          orderBy: { createdAt: 'desc' },
        },
        SupportTicket: {
          select: {
            id: true,
            category: true,
            orderRef: true,
            description: true,
            email: true,
            phone: true,
            status: true,
            priority: true,
            attachments: true,
            createdAt: true,
            updatedAt: true,
            SupportTicketResponse: {
              select: {
                id: true,
                message: true,
                isFromSupport: true,
                attachments: true,
                createdAt: true,
              },
              orderBy: { createdAt: 'asc' },
            },
          },
          orderBy: { createdAt: 'desc' },
        },
        CustomerNotificationPreferences: true,
      },
    });

    if (!customer) {
      return NextResponse.json(
        { error: 'Customer not found' },
        { status: 404 }
      );
    }

    // Calculate customer stats
    const totalOrders = customer.Booking.length;
    const completedOrders = customer.Booking.filter(
      (b: any) => b.status === 'completed'
    ).length;
    const cancelledOrders = customer.Booking.filter(
      (b: any) => b.status === 'cancelled'
    ).length;
    const totalLtv =
      customer.Booking
        .filter((b: any) => b.status === 'completed')
        .reduce((sum: number, b: any) => sum + b.amountPence, 0) / 100;

    const openTickets = customer.SupportTicket.filter(
      (t: any) => t.status === 'OPEN'
    ).length;
    const urgentTickets = customer.SupportTicket.filter(
      (t: any) => t.priority === 'URGENT'
    ).length;

    const customerWithStats = {
      ...customer,
      stats: {
        totalOrders,
        completedOrders,
        cancelledOrders,
        totalLtv,
        openTickets,
        urgentTickets,
        addressesCount: customer.Address.length,
        contactsCount: customer.Contact.length,
      },
    };

    return NextResponse.json(customerWithStats);
  } catch (error) {
    console.error('Error fetching customer:', error);
    return NextResponse.json(
      { error: 'Failed to fetch customer' },
      { status: 500 }
    );
  }
}

export async function PUT(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    // Verify admin role
    const authResult = await requireRole(request, 'admin');
    if (authResult instanceof NextResponse) {
      return authResult;
    }
    const user = authResult;

    const { id: customerId } = await params;
    const body = await request.json();
    const { name, email, notes, flags } = body;

    // Get existing customer
    const existingCustomer = await prisma.user.findUnique({
      where: { id: customerId, role: 'customer' },
    });

    if (!existingCustomer) {
      return NextResponse.json(
        { error: 'Customer not found' },
        { status: 404 }
      );
    }

    // Update customer
    const updatedCustomer = await prisma.user.update({
      where: { id: customerId },
      data: {
        name: name || existingCustomer.name,
        email: email || existingCustomer.email,
      },
    });

    // Create audit log
    await createAuditLog(user.id, 'customer.updated', customerId, { targetType: 'User', before: null, after: { name, email, notes, flags } });

    return NextResponse.json(updatedCustomer);
  } catch (error) {
    console.error('Error updating customer:', error);
    return NextResponse.json(
      { error: 'Failed to update customer' },
      { status: 500 }
    );
  }
}

export async function DELETE(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    // Verify admin role
    const authResult = await requireRole(request, 'admin');
    if (authResult instanceof NextResponse) {
      return authResult;
    }
    const user = authResult;

    const { id: customerId } = await params;

    // Check if customer has active bookings
    const activeBookings = await prisma.booking.findFirst({
      where: {
        customerId,
        status: { in: ['DRAFT', 'CONFIRMED'] },
      },
    });

    if (activeBookings) {
      return NextResponse.json(
        { error: 'Cannot delete customer with active bookings' },
        { status: 400 }
      );
    }

    // Soft delete - mark as inactive instead of hard delete
    const deletedCustomer = await prisma.user.update({
      where: { id: customerId },
      data: {
        email: `deleted-${Date.now()}-${customerId}@deleted.com`,
        name: 'Deleted Customer',
      },
    });

    // Create audit log
    await createAuditLog(user.id, 'customer.deleted', customerId, { targetType: 'User', before: null, after: { reason: 'Admin deletion' } });

    return NextResponse.json({ message: 'Customer deleted successfully' });
  } catch (error) {
    console.error('Error deleting customer:', error);
    return NextResponse.json(
      { error: 'Failed to delete customer' },
      { status: 500 }
    );
  }
}

import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
import { NextResponse, NextRequest } from 'next/server';

export const dynamic = 'force-dynamic';

export async function GET(request: NextRequest) {
  const s = await getServerSession(authOptions);
  if (!s?.user || (s.user as any).role !== 'admin') {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  try {
    const { searchParams } = new URL(request.url);
    const format = searchParams.get('format') || 'csv';
    const search = searchParams.get('search');
    const role = searchParams.get('role');

    // Build where clause
    const where: any = {};
    if (role) where.role = role;
    if (search) {
      where.OR = [
        { name: { contains: search, mode: 'insensitive' } },
        { email: { contains: search, mode: 'insensitive' } },
      ];
    }

    // Get all customers for export
    const customers = await prisma.user.findMany({
      where,
      select: {
        id: true,
        name: true,
        email: true,
        role: true,
        createdAt: true,
        lastLogin: true,
        isActive: true,
        emailVerified: true,
        Booking: {
          select: {
            id: true,
            reference: true,
            status: true,
            totalGBP: true,
            createdAt: true,
          },
        },
        SupportTicket: {
          select: {
            id: true,
            description: true,
            status: true,
            createdAt: true,
          },
        },
        Address: {
          select: {
            id: true,
            label: true,
            postcode: true,
          },
        },
        Contact: {
          select: {
            id: true,
            name: true,
            email: true,
            phone: true,
          },
        },
      },
      orderBy: { createdAt: 'desc' },
    });

    // Process customer data for export
    const exportData = customers.map(customer => {
      const totalBookings = customer.Booking.length;
      const totalSpent = customer.Booking.reduce(
        (sum, booking) => sum + (booking.totalGBP || 0),
        0
      );
      const activeTickets = customer.SupportTicket.filter(
        ticket => ticket.status === 'open'
      ).length;
      const completedBookings = customer.Booking.filter(
        booking => booking.status === 'COMPLETED'
      ).length;

      return {
        id: customer.id,
        name: customer.name || 'Unknown',
        email: customer.email,
        role: customer.role,
        createdAt: customer.createdAt.toISOString(),
        lastLogin: customer.lastLogin?.toISOString() || 'Never',
        isActive: customer.isActive,
        emailVerified: customer.emailVerified,
        totalBookings,
        completedBookings,
        totalSpent: (totalSpent / 100).toFixed(2), // Convert from pence to pounds
        activeTickets,
        addressCount: customer.Address.length,
        contactCount: customer.Contact.length,
        primaryAddress: customer.Address[0]?.label || 'No address',
        primaryContact: customer.Contact[0]?.name || 'No contact',
      };
    });

    if (format === 'json') {
      return NextResponse.json({
        customers: exportData,
        total: exportData.length,
        exportedAt: new Date().toISOString(),
      });
    }

    // Generate CSV
    const headers = [
      'ID',
      'Name',
      'Email',
      'Role',
      'Created At',
      'Last Login',
      'Is Active',
      'Email Verified',
      'Total Bookings',
      'Completed Bookings',
      'Total Spent (£)',
      'Active Tickets',
      'Address Count',
      'Contact Count',
      'Primary Address',
      'Primary Contact',
    ];

    const csvRows = [
      headers.join(','),
      ...exportData.map(row =>
        [
          row.id,
          `"${row.name}"`,
          row.email,
          row.role,
          row.createdAt,
          row.lastLogin,
          row.isActive,
          row.emailVerified,
          row.totalBookings,
          row.completedBookings,
          row.totalSpent,
          row.activeTickets,
          row.addressCount,
          row.contactCount,
          `"${row.primaryAddress}"`,
          `"${row.primaryContact}"`,
        ].join(',')
      ),
    ];

    const csv = csvRows.join('\n');

    return new NextResponse(csv, {
      headers: {
        'Content-Type': 'text/csv',
        'Content-Disposition': `attachment; filename="customers-export-${new Date().toISOString().split('T')[0]}.csv"`,
      },
    });
  } catch (error) {
    console.error('Admin customers export API error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

import { NextRequest } from 'next/server';
import { prisma } from '@/lib/prisma';
import { withApiHandler, requireRole, httpJson } from '@/lib/api/guard';
import { parseJson, parseQueryParams } from '@/lib/validation/helpers';
import {
  customerCreate,
  paginationQuery,
  searchQuery,
} from '@/lib/validation/schemas';

export const dynamic = 'force-dynamic';

export const GET = withApiHandler(async (request: NextRequest) => {
  const user = await requireRole(request, 'admin');

  const queryParams = parseQueryParams(
    request.url,
    paginationQuery.merge(searchQuery)
  );
  if (!queryParams.ok) return queryParams.error;

  const { page, limit, search, role } = queryParams.data;
  const pageNum = typeof page === 'number' ? page : (page ? parseInt(String(page), 10) : 1);
  const limitNum = typeof limit === 'number' ? limit : (limit ? parseInt(String(limit), 10) : 20);
  const skip = (pageNum - 1) * limitNum;

  // Build where clause
  const where: any = {};
  if (role) where.role = role;
  if (search) {
    where.OR = [
      { name: { contains: search, mode: 'insensitive' } },
      { email: { contains: search, mode: 'insensitive' } },
    ];
  }

  // Get customers with pagination (simplified version)
  const [customers, total] = await Promise.all([
    prisma.user.findMany({
      where,
      select: {
        id: true,
        name: true,
        email: true,
        role: true,
        createdAt: true,
        lastLogin: true,
        isActive: true,
        emailVerified: true,
      },
      orderBy: { createdAt: 'desc' },
      skip,
      take: limitNum,
    }),
    prisma.user.count({ where }),
  ]);

  // Process customer data (simplified version)
  const processedCustomers = customers.map(customer => ({
    id: customer.id,
    name: customer.name,
    email: customer.email,
    role: customer.role,
    createdAt: customer.createdAt,
    lastLogin: customer.lastLogin,
    isActive: customer.isActive,
    emailVerified: customer.emailVerified,
    stats: {
      totalBookings: 0,
      totalSpent: 0,
      activeTickets: 0,
      addressCount: 0,
      contactCount: 0,
    },
    recentBookings: [],
    recentTickets: [],
    addresses: [],
    contacts: [],
  }));

  return httpJson(200, {
    customers: processedCustomers,
    pagination: {
      page,
      limit,
      total,
      pages: Math.ceil(total / limitNum),
    },
  });
});

export const POST = withApiHandler(async (request: NextRequest) => {
  const user = await requireRole(request, 'admin');

  const parsed = await parseJson(request, customerCreate);
  if (!parsed.ok) return parsed.error;

  const { name, phone, email } = parsed.data;

  // Check if email already exists
  if (email) {
    const existingUser = await prisma.user.findUnique({
      where: { email },
    });

    if (existingUser) {
      return httpJson(409, { error: 'Email already exists' });
    }
  }

  // Create customer
  const customer = await prisma.user.create({
    data: {
      id: `user_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
      name,
      email: (email || `${name.toLowerCase().replace(/\s+/g, '.')}@example.com`).toLowerCase(),
      role: 'customer',
      password: 'temp-password', // Will be reset by customer
      emailVerified: false,
    },
  });

  return httpJson(201, customer);
});

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
import { penceToPounds } from '@/lib/utils/currency';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

export async function GET(request: NextRequest) {
  try {
    // Check admin authorization
    const session = await getServerSession(authOptions);
    if (!session?.user) {
      return NextResponse.json(
        { error: 'Unauthorized - Please login' },
        { status: 401 }
      );
    }

    const userRole = (session.user as any)?.role;
    if (userRole !== 'admin') {
      return NextResponse.json(
        { error: 'Forbidden - Admin access required' },
        { status: 403 }
      );
    }

    // Get date boundaries for today
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const tomorrow = new Date(today);
    tomorrow.setDate(tomorrow.getDate() + 1);

    // Get unassigned bookings (need driver assignment)
    const unassignedBookings = await prisma.booking.findMany({
      where: {
        status: 'CONFIRMED',
        driverId: null,
        scheduledAt: { gte: new Date() } // Future bookings only
      },
      include: {
        pickupAddress: true,
        dropoffAddress: true,
        BookingItem: true,
        customer: {
          select: { id: true, name: true, email: true }
        }
      },
      orderBy: { scheduledAt: 'asc' }
    });

    // Calculate SLA for unassigned bookings
    const unassignedWithSLA = unassignedBookings.map(booking => {
      const confirmedAt = booking.paidAt || booking.updatedAt;
      const waitingMinutes = Math.floor((Date.now() - confirmedAt.getTime()) / (1000 * 60));
      const slaBreached = waitingMinutes > 30; // 30 minute SLA
      
      return {
        ...booking,
        waitingMinutes,
        slaBreached,
        priority: slaBreached ? 'high' : (waitingMinutes > 15 ? 'medium' : 'normal')
      };
    });

    // Get available drivers
    const availableDrivers = await prisma.driver.findMany({
      where: {
        status: 'active',
        onboardingStatus: 'approved'
      },
      include: {
        User: {
          select: { 
            id: true, 
            name: true, 
            email: true,
            role: true,
            createdAt: true,
            isActive: true
          }
        },
        DriverAvailability: true,
        Booking: {
          where: {
            status: { in: ['CONFIRMED'] }
          }
        }
      }
    });

    // Filter truly available drivers (not overloaded)
    const trulyAvailableDrivers = availableDrivers.filter(driver => 
      ((driver as any).Booking?.length || 0) < 3 && // Max 3 concurrent jobs
      (driver as any).DriverAvailability?.status === 'online'
    );

    // Get today's statistics
    const [
      todayRevenue,
      todayBookingsCount,
      activeJobsCount,
      completedTodayCount,
      pendingAssignmentCount
    ] = await Promise.all([
      // Today's revenue
      prisma.booking.aggregate({
        where: {
          paidAt: { gte: today, lt: tomorrow },
          status: 'CONFIRMED'
        },
        _sum: { totalGBP: true }
      }),
      
      // Today's bookings
      prisma.booking.count({
        where: {
          createdAt: { gte: today, lt: tomorrow }
        }
      }),
      
      // Active jobs
      prisma.booking.count({
        where: {
          status: { in: ['CONFIRMED'] }
        }
      }),
      
      // Completed today
      prisma.booking.count({
        where: {
          status: 'COMPLETED',
          updatedAt: { gte: today, lt: tomorrow }
        }
      }),
      
      // Pending assignments
      prisma.booking.count({
        where: {
          status: 'CONFIRMED',
          driverId: null
        }
      })
    ]);

    // Get recent activity
    const recentActivity = await prisma.auditLog.findMany({
      where: {
        action: { in: ['booking_created', 'job_assigned', 'booking_completed'] },
        createdAt: { gte: today }
      },
      orderBy: { createdAt: 'desc' },
      take: 10,
      // include: {
      //   actor: {
      //     select: { name: true, email: true }
      //   }
      // }
    });

    // Get admin users for team display
    const adminUsers = await prisma.user.findMany({
      where: { role: 'admin' },
      select: {
        id: true,
        name: true,
        email: true,
        adminRole: true,
        isActive: true,
        lastLogin: true
      },
      orderBy: { lastLogin: 'desc' },
      take: 5
    });

    // Calculate driver utilization
    const totalDrivers = availableDrivers.length;
    const busyDrivers = availableDrivers.filter(d => ((d as any).Booking?.length || 0) > 0).length;
    const driverUtilization = totalDrivers > 0 ? Math.round((busyDrivers / totalDrivers) * 100) : 0;

    // Format response
    const dashboardData = {
      alerts: {
        unassignedBookings: unassignedWithSLA.length,
        slaBreached: unassignedWithSLA.filter(b => b.slaBreached).length,
        urgentBookings: unassignedWithSLA.filter(b => b.priority === 'high').length
      },
      
      statistics: {
        todayRevenue: penceToPounds(todayRevenue._sum.totalGBP || 0),
        todayBookings: todayBookingsCount,
        activeJobs: activeJobsCount,
        completedToday: completedTodayCount,
        pendingAssignments: pendingAssignmentCount,
        driverUtilization
      },
      
      unassignedBookings: unassignedWithSLA.slice(0, 10).map(booking => ({
        id: booking.id,
        reference: booking.reference,
        customer: booking.customer?.name || booking.customerName,
        customerPhone: booking.customerPhone,
        pickupAddress: booking.pickupAddress?.label || 'Pickup Address',
        dropoffAddress: booking.dropoffAddress?.label || 'Dropoff Address',
        scheduledAt: booking.scheduledAt,
        totalAmount: penceToPounds(booking.totalGBP),
        waitingMinutes: booking.waitingMinutes,
        priority: booking.priority,
        slaBreached: booking.slaBreached,
        itemsCount: booking.BookingItem.length,
        createdAt: booking.createdAt
      })),
      
      availableDrivers: trulyAvailableDrivers.map(driver => ({
        id: driver.id,
        name: (driver as any).user?.name || 'Unknown Driver',
        email: (driver as any).user?.email || '',
        status: driver.status,
        currentJobs: (driver as any).Booking?.length || 0,
        isOnline: (driver as any).availability?.status === 'online',
        lastSeen: (driver as any).availability?.lastSeenAt
      })),
      
      recentActivity: recentActivity.map(activity => ({
        id: activity.id,
        action: activity.action,
        actorName: activity.actorId || 'System',
        targetType: activity.targetType,
        targetId: activity.targetId,
        createdAt: activity.createdAt,
        details: activity.details
      })),
      
      adminUsers: adminUsers.map(admin => ({
        id: admin.id,
        name: admin.name,
        email: admin.email,
        adminRole: admin.adminRole,
        isActive: admin.isActive,
        lastLogin: admin.lastLogin,
        isOnline: admin.lastLogin ? 
          (new Date().getTime() - new Date(admin.lastLogin).getTime()) < (15 * 60 * 1000) : false
      })),
      
      systemHealth: {
        database: 'healthy',
        queue: 'healthy',
        pusher: 'healthy',
        stripeWebhooks: 'healthy'
      }
    };

    console.log('✅ Admin dashboard data loaded:', {
      unassignedBookings: dashboardData.alerts.unassignedBookings,
      slaBreached: dashboardData.alerts.slaBreached,
      availableDrivers: dashboardData.availableDrivers.length,
      todayRevenue: dashboardData.statistics.todayRevenue
    });

    return NextResponse.json({
      success: true,
      data: dashboardData
    });

  } catch (error) {
    console.error('❌ Error loading admin dashboard data:', error);
    return NextResponse.json(
      {
        error: 'Failed to load dashboard data',
        details: error instanceof Error ? error.message : 'Unknown error'
      },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { z } from 'zod';
import { prisma } from '@/lib/prisma';
import { subDays, startOfDay, endOfDay, differenceInMinutes } from 'date-fns';
import { withApiHandler, requireRole, httpJson } from '@/lib/api/guard';
import { logAudit } from '@/lib/audit';
import { AdminDashboardControlsService } from '@/lib/admin-dashboard-controls';

export const dynamic = 'force-dynamic';

// Validation schemas for Admin Dashboard Controls
const EmergencyActionSchema = z.object({
  action: z.enum([
    'pause_assignments',
    'resume_assignments',
    'emergency_broadcast',
    'route_reassignment',
    'acknowledge_alert',
    'system_maintenance'
  ]),
  adminId: z.string().min(1, 'Admin ID is required'),
  reason: z.string().optional(),
  target: z.object({
    routeId: z.string().optional(),
    driverId: z.string().optional(),
    newDriverId: z.string().optional(),
    alertId: z.string().optional(),
    message: z.string().optional(),
    driverIds: z.array(z.string()).optional(),
    broadcastTarget: z.enum(['all_drivers', 'active_drivers', 'specific_drivers']).optional()
  }).optional().default({})
});

const DashboardQuerySchema = z.object({
  section: z.enum([
    'overview',
    'routes',
    'drivers',
    'system_health',
    'alerts',
    'analytics'
  ]).optional().default('overview'),
  timeframe: z.enum(['1h', '24h', '7d', '30d']).optional().default('24h'),
  driverId: z.string().optional(),
  routeId: z.string().optional(),
  includeMetrics: z.boolean().optional().default(true),
  realtime: z.boolean().optional().default(true)
});

// Global dashboard service instance
let dashboardControlsService: AdminDashboardControlsService | null = null;

function getDashboardControlsService(): AdminDashboardControlsService {
  if (!dashboardControlsService) {
    dashboardControlsService = new AdminDashboardControlsService();
  }
  return dashboardControlsService;
}

// Helper functions for dashboard calculations
async function checkSystemHealth() {
  try {
    // Test database connection
    await prisma.$queryRaw`SELECT 1`;
    return {
      db: 'healthy',
      queue: 'healthy',
      pusher: 'healthy',
      stripe: 'healthy',
    };
  } catch (error) {
    return {
      db: 'unhealthy',
      queue: 'unknown',
      pusher: 'unknown',
      stripe: 'unknown',
    };
  }
}

async function calculateAverageEta() {
  try {
    const recentBookings = await prisma.booking.findMany({
      where: {
        status: 'COMPLETED',
        updatedAt: { gte: subDays(new Date(), 7) },
      },
      select: {
        scheduledAt: true,
        updatedAt: true,
      },
    });

    if (recentBookings.length === 0) return '23 min';

    const totalMinutes = recentBookings.reduce((sum, booking) => {
      if (booking.scheduledAt && booking.updatedAt) {
        return (
          sum + differenceInMinutes(booking.updatedAt, booking.scheduledAt)
        );
      }
      return sum;
    }, 0);

    const avgMinutes = Math.round(totalMinutes / recentBookings.length);
    return `${avgMinutes} min`;
  } catch (error) {
    return '23 min';
  }
}

async function calculateFirstResponseTime() {
  try {
    const recentTickets = await prisma.supportTicket.findMany({
      where: {
        createdAt: { gte: subDays(new Date(), 7) },
        SupportTicketResponse: {
          some: {
            isFromSupport: true,
          },
        },
      },
      select: {
        createdAt: true,
        SupportTicketResponse: {
          where: {
            isFromSupport: true,
          },
          select: {
            createdAt: true,
          },
          orderBy: {
            createdAt: 'asc',
          },
          take: 1,
        },
      },
    });

    if (recentTickets.length === 0) return '4.2 min';

    const totalMinutes = recentTickets.reduce((sum, ticket) => {
      const firstResponse = ticket.SupportTicketResponse[0];
      if (!firstResponse) return sum;
      return (
        sum + differenceInMinutes(firstResponse.createdAt, ticket.createdAt)
      );
    }, 0);

    const avgMinutes =
      Math.round((totalMinutes / recentTickets.length) * 10) / 10;
    return `${avgMinutes} min`;
  } catch (error) {
    return '4.2 min';
  }
}

/**
 * Handle Dashboard Controls specific requests
 */
async function handleDashboardControlsRequest(request: NextRequest, section: string): Promise<NextResponse> {
  try {
    const { searchParams } = new URL(request.url);
    const query = DashboardQuerySchema.parse({
      section,
      timeframe: searchParams.get('timeframe') || '24h',
      driverId: searchParams.get('driverId'),
      routeId: searchParams.get('routeId'),
      includeMetrics: searchParams.get('includeMetrics') === 'true',
      realtime: searchParams.get('realtime') !== 'false'
    });

    console.log(`🎛️ Admin Dashboard Controls request: ${query.section} (${query.timeframe})`);

    const service = getDashboardControlsService();
    let responseData: any = {};

    switch (query.section) {
      case 'routes':
        const routeData = query.routeId 
          ? await service.getLiveRouteMonitoring(query.routeId)
          : await service.getLiveRouteMonitoring();
        
        responseData = {
          routes: routeData,
          summary: {
            total: routeData.length,
            active: routeData.filter(r => r.status === 'active').length,
            delayed: routeData.filter(r => r.status === 'delayed').length,
            needingIntervention: routeData.filter(r => r.status === 'intervention_required').length
          }
        };
        break;

      case 'drivers':
        const driverMetrics = query.driverId
          ? await service.getDriverPerformanceMetrics(query.driverId)
          : await service.getDriverPerformanceMetrics();
        
        responseData = {
          drivers: driverMetrics,
          summary: {
            total: driverMetrics.length,
            active: driverMetrics.filter(d => d.status === 'active').length,
            offline: driverMetrics.filter(d => d.status === 'offline').length,
            emergency: driverMetrics.filter(d => d.status === 'emergency').length,
            onBreak: driverMetrics.filter(d => d.status === 'on_break').length
          }
        };
        break;

      case 'system_health':
        const healthMetrics = await service.getSystemHealthMetrics();
        
        responseData = {
          health: healthMetrics,
          status: {
            api: healthMetrics.api.uptime > 99.5 ? 'healthy' : 'degraded',
            database: healthMetrics.database.uptime > 99.5 ? 'healthy' : 'degraded',
            websocket: healthMetrics.websocket.uptime > 99.0 ? 'healthy' : 'degraded',
            infrastructure: healthMetrics.infrastructure.cpuUsage < 80 ? 'healthy' : 'stressed'
          }
        };
        break;

      case 'alerts':
        const dashboardState = await service.getDashboardState();
        
        responseData = {
          alerts: dashboardState.alerts,
          summary: {
            total: dashboardState.alerts.length,
            critical: dashboardState.alerts.filter(a => a.type === 'critical' && !a.acknowledged).length,
            warning: dashboardState.alerts.filter(a => a.type === 'warning' && !a.acknowledged).length,
            acknowledged: dashboardState.alerts.filter(a => a.acknowledged).length
          },
          interventions: dashboardState.interventions.slice(0, 10)
        };
        break;

      case 'analytics':
        const analyticsData = await service.generateDashboardAnalytics(query.timeframe);
        responseData = analyticsData;
        break;
    }

    return NextResponse.json({
      success: true,
      data: responseData,
      timestamp: new Date().toISOString(),
      section: query.section,
      timeframe: query.timeframe
    });

  } catch (error) {
    console.error('Dashboard Controls request failed:', error);

    if (error instanceof z.ZodError) {
      return NextResponse.json({
        success: false,
        error: 'Invalid request parameters',
        details: error.issues
      }, { status: 400 });
    }

    return NextResponse.json({
      success: false,
      error: 'Dashboard Controls request failed',
      message: error instanceof Error ? error.message : 'Unknown error'
    }, { status: 500 });
  }
}

export const GET = withApiHandler(async (request: NextRequest) => {
  const user = await requireRole(request, 'admin');
  
  const { searchParams } = new URL(request.url);
  const section = searchParams.get('section') || 'overview';
  
  // Handle new Dashboard Controls sections
  if (['routes', 'drivers', 'system_health', 'alerts', 'analytics'].includes(section)) {
    return handleDashboardControlsRequest(request, section as any);
  }

  const today = new Date();
  const todayStart = startOfDay(today);
  const todayEnd = endOfDay(today);
  const yesterdayStart = startOfDay(subDays(today, 1));
  const yesterdayEnd = endOfDay(subDays(today, 1));

  // Parallel data fetching for performance
  const [
    todayRevenue,
    yesterdayRevenue,
    activeJobs,
    newOrders,
    driverApplications,
    pendingRefunds,
    disputedPayouts,
    liveOps,
    systemHealth,
    avgEta,
    firstResponseTime,
    openIncidents,
  ] = await Promise.all([
    // Today's revenue
    prisma.booking.aggregate({
      _sum: { totalGBP: true },
      where: {
        status: 'COMPLETED',
        paidAt: { gte: todayStart, lte: todayEnd },
      },
    }),

    // Yesterday's revenue for comparison
    prisma.booking.aggregate({
      _sum: { totalGBP: true },
      where: {
        status: 'COMPLETED',
        paidAt: { gte: yesterdayStart, lte: yesterdayEnd },
      },
    }),

    // Active jobs (assigned and in progress) - exclude test bookings
    prisma.booking.count({
      where: {
        status: { in: ['CONFIRMED'] },
        driverId: { not: null },
        NOT: [
          { reference: { startsWith: 'test_' } },
          { reference: { startsWith: 'TEST_' } },
          { reference: { startsWith: 'demo_' } },
        ],
      },
    }),

    // New orders (pending and unassigned) - exclude test bookings
    prisma.booking.count({
      where: {
        status: { in: ['DRAFT', 'CONFIRMED'] },
        driverId: null,
        NOT: [
          { reference: { startsWith: 'test_' } },
          { reference: { startsWith: 'TEST_' } },
          { reference: { startsWith: 'demo_' } },
        ],
      },
    }),

    // Driver applications pending review
    prisma.driverApplication.count({
      where: {
        status: { in: ['pending', 'under_review', 'requires_additional_info'] },
      },
    }),

    // Pending refunds
    prisma.booking.count({
      where: {
        status: 'CANCELLED',
      },
    }),

    // Disputed payouts (drivers with negative earnings)
    prisma.driverEarnings.aggregate({
      _sum: { netAmountPence: true },
      where: {
        netAmountPence: { lt: 0 },
      },
    }),

    // Live operations - jobs in progress with SLA timers (exclude test bookings)
    prisma.booking.findMany({
      where: {
        status: { in: ['CONFIRMED'] },
        driverId: { not: null },
        NOT: [
          { reference: { startsWith: 'test_' } },
          { reference: { startsWith: 'TEST_' } },
          { reference: { startsWith: 'demo_' } },
        ],
      },
      include: {
        pickupAddress: true,
        dropoffAddress: true,
        driver: {
          select: {
            id: true,
            User: {
              select: {
                name: true,
              },
            },
          },
        },
        Assignment: {
          select: {
            claimedAt: true,
          },
        },
      },
      orderBy: {
        scheduledAt: 'asc',
      },
      take: 10,
    }),

    // System health check
    checkSystemHealth(),

    // Average ETA calculation
    calculateAverageEta(),

    // First response time for support tickets
    calculateFirstResponseTime(),

    // Open incidents
    prisma.driverIncident.count({
      where: {
        status: 'reported',
      },
    }),
  ]);

  // Calculate revenue change percentage
  const todayRevenueAmount = todayRevenue._sum.totalGBP || 0;
  const yesterdayRevenueAmount = yesterdayRevenue._sum.totalGBP || 0;
  const revenueChangePercent =
    yesterdayRevenueAmount > 0
      ? ((todayRevenueAmount - yesterdayRevenueAmount) /
          yesterdayRevenueAmount) *
        100
      : 0;

  // Process live operations data
  const processedLiveOps = liveOps.map(job => {
    const claimedAt = job.Assignment?.[0]?.claimedAt;
    const timeSinceClaimed = claimedAt
      ? differenceInMinutes(new Date(), claimedAt)
      : 0;

    // Calculate ETA based on status and time elapsed
    let eta = 'Unknown';
    if (job.status === 'CONFIRMED') {
      eta = `${Math.max(0, 30 - timeSinceClaimed)} min`;
    }

    // Check if overdue
    if (timeSinceClaimed > 60) {
      eta = 'overdue';
    }

    return {
      id: job.id,
      ref: job.reference,
      status: job.status,
      eta,
      driver: job.driver?.User?.name || 'Unknown',
      pickupAddress: job.pickupAddress,
      dropoffAddress: job.dropoffAddress,
      timeSinceClaimed,
    };
  });

  // Determine overall system health from individual checks
  let overallSystemHealth = 'healthy';
  if (systemHealth.db !== 'healthy') {
    overallSystemHealth = 'error';
  } else if (systemHealth.queue !== 'healthy' || systemHealth.pusher !== 'healthy' || systemHealth.stripe !== 'healthy') {
    overallSystemHealth = 'warning';
  }

  // Get additional metrics for AdminDashboard compatibility
  const totalOrdersCount = await prisma.booking.count();
  const completedOrdersCount = await prisma.booking.count({
    where: { status: 'COMPLETED' }
  });
  const totalCustomersCount = await prisma.user.count({
    where: { role: 'customer' }
  });
  const activeDriversCount = await prisma.driver.count({
    where: { status: 'active' }
  });

  const payload = {
    // Flat structure for AdminDashboard component compatibility
    totalOrders: totalOrdersCount,
    activeOrders: activeJobs,
    completedOrders: completedOrdersCount,
    totalRevenue: todayRevenueAmount,
    revenueChange: Math.round(revenueChangePercent * 100) / 100,
    activeDrivers: activeDriversCount,
    totalCustomers: totalCustomersCount,
    avgResponseTime: firstResponseTime || '4.2 min',
    systemHealth: overallSystemHealth,
    
    // Keep original structure for other components
    kpis: {
      todayRevenue: todayRevenueAmount,
      revenueChangePercent: Math.round(revenueChangePercent * 100) / 100,
      activeJobs,
      newOrders,
      avgEta: avgEta || '23 min',
      firstResponseTime: firstResponseTime || '4.2 min',
      openIncidents,
    },
    liveOps: processedLiveOps,
    queue: {
      driverApplications,
      pendingRefunds,
      disputedPayouts: disputedPayouts._sum?.netAmountPence ? 1 : 0,
    },
    systemHealthDetails: systemHealth, // Keep detailed health info
  };

  return httpJson(200, payload);
});

/**
 * POST /api/admin/dashboard
 * Execute emergency actions and interventions
 */
export const POST = withApiHandler(async (request: NextRequest) => {
  const user = await requireRole(request, 'admin');

  try {
    const body = await request.json();
    const { action, adminId, reason, target } = EmergencyActionSchema.parse(body);

    console.log(`🚨 Admin emergency action: ${action} by ${adminId}`);

    const service = getDashboardControlsService();
    let result: any = { success: false, message: 'Unknown action' };

    switch (action) {
      case 'pause_assignments':
        result = await service.pauseNewAssignments(
          reason || 'Emergency pause initiated by admin',
          adminId
        );
        break;

      case 'resume_assignments':
        result = await service.resumeNewAssignments(adminId);
        break;

      case 'emergency_broadcast':
        if (!target.message) {
          return NextResponse.json({
            success: false,
            error: 'Message is required for emergency broadcast'
          }, { status: 400 });
        }

        result = await service.broadcastEmergencyMessage(
          target.message,
          target.broadcastTarget || 'active_drivers',
          target.driverIds
        );
        break;

      case 'route_reassignment':
        if (!target.routeId || !target.newDriverId) {
          return NextResponse.json({
            success: false,
            error: 'Route ID and new driver ID are required for reassignment'
          }, { status: 400 });
        }

        result = await service.emergencyRouteReassignment(
          target.routeId,
          target.newDriverId,
          reason || 'Emergency reassignment',
          adminId
        );
        break;

      case 'acknowledge_alert':
        if (!target.alertId) {
          return NextResponse.json({
            success: false,
            error: 'Alert ID is required'
          }, { status: 400 });
        }

        result = await service.acknowledgeAlert(target.alertId, adminId);
        break;

      case 'system_maintenance':
        result = await handleSystemMaintenance(adminId, reason);
        break;

      default:
        return NextResponse.json({
          success: false,
          error: 'Invalid action type'
        }, { status: 400 });
    }

    // Log the action for audit purposes
    await logAdminAction({
      action,
      adminId,
      reason,
      target,
      result: result.success,
      timestamp: new Date()
    });

    return NextResponse.json({
      success: true,
      data: {
        action,
        result,
        executedBy: adminId,
        timestamp: new Date().toISOString()
      }
    });

  } catch (error) {
    console.error('Admin emergency action failed:', error);

    if (error instanceof z.ZodError) {
      return NextResponse.json({
        success: false,
        error: 'Invalid action parameters',
        details: error.issues
      }, { status: 400 });
    }

    return NextResponse.json({
      success: false,
      error: 'Emergency action failed',
      message: error instanceof Error ? error.message : 'Unknown error'
    }, { status: 500 });
  }
});

/**
 * Handle system maintenance mode
 */
async function handleSystemMaintenance(adminId: string, reason?: string) {
  console.log(`🔧 System maintenance mode initiated by ${adminId}`);
  
  // In production: enable maintenance mode, gracefully complete routes,
  // prevent new bookings, notify stakeholders
  
  return {
    success: true,
    message: 'System maintenance mode activated. Active routes will complete normally.',
    maintenanceWindow: {
      start: new Date(),
      estimatedDuration: '30 minutes'
    }
  };
}

/**
 * Log admin actions for audit trail
 */
async function logAdminAction(action: any) {
  console.log('📝 Logging admin action:', {
    action: action.action,
    adminId: action.adminId,
    timestamp: action.timestamp,
    result: action.result
  });
  
  // Log to audit system
  await logAudit(
    action.adminId,
    action.action,
    action.target?.routeId || action.target?.driverId || 'system',
    {
      reason: action.reason,
      target: action.target,
      success: action.result,
      timestamp: action.timestamp
    }
  );
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

export async function GET(
  request: NextRequest,
  { params }: { params: { code: string } }
) {
  try {
    const session = await getServerSession(authOptions);
    
    if (!session?.user || (session.user as any).role !== 'admin') {
      return NextResponse.json(
        { error: 'Unauthorized - Admin access required' },
        { status: 401 }
      );
    }

    const { code: reference } = params;

    // Get booking with all related data
    const booking = await prisma.booking.findFirst({
      where: { reference },
      include: {
        pickupAddress: true,
        dropoffAddress: true,
        driver: {
          include: {
            User: {
              select: {
                id: true,
                name: true,
                email: true,
                role: true,
                createdAt: true,
                isActive: true
              }
            }
          }
        },
        Assignment: true
      }
    });

    if (!booking) {
      return NextResponse.json(
        { error: 'Booking not found', reference },
        { status: 404 }
      );
    }

    // Check driver jobs eligibility
    const now = new Date();
    const isConfirmed = booking.status === 'CONFIRMED';
    const hasNoDriver = booking.driverId === null;
    const isInFuture = booking.scheduledAt > now;
    const hasNoAssignment = !booking.Assignment || booking.Assignment.length === 0;

    const shouldAppearInJobs = isConfirmed && hasNoDriver && isInFuture && hasNoAssignment;

    // Count total eligible jobs
    const totalEligibleJobs = await prisma.booking.count({
      where: {
        status: 'CONFIRMED',
        driverId: null,
        scheduledAt: { gte: now }
      }
    });

    // Get recent eligible jobs for comparison
    const recentEligibleJobs = await prisma.booking.findMany({
      where: {
        status: 'CONFIRMED',
        driverId: null,
        scheduledAt: { gte: now }
      },
      select: {
        id: true,
        reference: true,
        customerName: true,
        scheduledAt: true,
        createdAt: true
      },
      orderBy: { createdAt: 'desc' },
      take: 5
    });

    return NextResponse.json({
      booking: {
        id: booking.id,
        reference: booking.reference,
        status: booking.status,
        driverId: booking.driverId,
        scheduledAt: booking.scheduledAt,
        createdAt: booking.createdAt,
        paidAt: booking.paidAt,
        customerName: booking.customerName,
        customerEmail: booking.customerEmail,
        driverName: booking.driver?.User?.name || null,
        hasAssignment: !!booking.Assignment,
        assignmentStatus: booking.Assignment?.[0]?.status || null,
        pickupAddress: booking.pickupAddress?.label,
        dropoffAddress: booking.dropoffAddress?.label
      },
      eligibility: {
        isConfirmed,
        hasNoDriver,
        isInFuture,
        hasNoAssignment,
        shouldAppearInJobs,
        reasons: [
          !isConfirmed && `Status is ${booking.status}, not CONFIRMED`,
          !hasNoDriver && `Already assigned to driver: ${booking.driver?.User?.name}`,
          !isInFuture && `Scheduled time is in the past: ${booking.scheduledAt}`,
          !hasNoAssignment && `Has assignment record with status: ${booking.Assignment?.[0]?.status}`
        ].filter(Boolean)
      },
      context: {
        totalEligibleJobs,
        currentTime: now,
        recentEligibleJobs
      },
      recommendations: shouldAppearInJobs 
        ? ['Booking should appear in driver jobs - check driver dashboard']
        : [
            !isConfirmed && 'Update booking status to CONFIRMED',
            !hasNoDriver && 'Remove driver assignment',
            !isInFuture && 'Update scheduled time to future date',
            !hasNoAssignment && 'Remove assignment record'
          ].filter(Boolean)
    });

  } catch (error) {
    console.error('❌ Diagnostic API error:', error);
    return NextResponse.json(
      { error: 'Diagnostic failed', details: error instanceof Error ? error.message : 'Unknown error' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
import { getPusherServer } from '@/lib/pusher';
import { upsertAssignment } from '@/lib/utils/assignment-helpers';

// Force dynamic rendering (uses headers/cookies/getServerSession)
export const dynamic = 'force-dynamic';

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user || (session.user as any).role !== 'admin') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const { jobId, driverId }: { jobId: string; driverId: string } =
      await request.json();

    if (!jobId) {
      return NextResponse.json(
        { error: 'Job ID is required' },
        { status: 400 }
      );
    }

    // If driverId is 'auto', find the best available driver
    let finalDriverId: string = driverId;
    if (driverId === 'auto') {
      const job = await prisma.booking.findUnique({
        where: { id: jobId },
        include: {
          driver: true,
        },
      });

      if (!job) {
        return NextResponse.json({ error: 'Job not found' }, { status: 404 });
      }

      // Find available drivers within radius (simplified logic)
      const availableDrivers = await prisma.driver.findMany({
        where: {
          status: 'active',
          onboardingStatus: 'approved',
          DriverAvailability: {
            status: 'AVAILABLE',
          },
        },
        include: {
          User: {
            select: {
              id: true,
              name: true,
              email: true,
              role: true,
              createdAt: true,
              isActive: true
            }
          },
          DriverAvailability: true,
          Booking: {
            where: {
              status: {
                in: ['CONFIRMED'],
              },
            },
          },
        },
      });

      // Filter drivers by capacity and rating
      const eligibleDrivers = availableDrivers.filter(driver => {
        const activeJobs = driver.Booking.length;
        const rating = driver.rating || 0;
        return activeJobs < 3 && rating >= 4.0; // Basic filtering
      });

      if (eligibleDrivers.length === 0) {
        return NextResponse.json(
          {
            error: 'No eligible drivers available for auto-assignment',
          },
          { status: 400 }
        );
      }

      // Select the first eligible driver (in a real app, you'd use more sophisticated logic)
      finalDriverId = eligibleDrivers[0].id;
    }

    // Check if driver exists and is available
    const driver = await prisma.driver.findUnique({
      where: { id: finalDriverId },
      include: {
        DriverAvailability: true,
        User: {
          select: {
            id: true,
            name: true,
            email: true,
            role: true,
            createdAt: true,
            isActive: true
          }
        },
      },
    });

    if (!driver) {
      return NextResponse.json({ error: 'Driver not found' }, { status: 404 });
    }

    if (driver.onboardingStatus !== 'approved') {
      return NextResponse.json(
        { error: 'Driver is not approved' },
        { status: 400 }
      );
    }

    // Check if job is already assigned
    const existingJob = await prisma.booking.findUnique({
      where: { id: jobId },
      include: {
        driver: true,
      },
    });

    if (!existingJob) {
      return NextResponse.json({ error: 'Job not found' }, { status: 404 });
    }

    if (existingJob.driverId) {
      return NextResponse.json(
        { error: 'Job is already assigned' },
        { status: 400 }
      );
    }

    // Assign the job to the driver
    const updatedJob = await prisma.booking.update({
      where: { id: jobId },
      data: {
        driverId: finalDriverId,
        status: 'CONFIRMED',
      },
      include: {
        driver: {
          include: {
            User: {
              select: {
                id: true,
                name: true,
                email: true,
                role: true,
                createdAt: true,
                isActive: true
              }
            },
          },
        },
        pickupAddress: {
          select: {
            label: true,
            postcode: true
          }
        },
        dropoffAddress: {
          select: {
            label: true,
            postcode: true
          }
        },
      },
    });

    // Create or update assignment record
    const assignment = await upsertAssignment(prisma, jobId, {
      driverId: finalDriverId,
      status: 'accepted',
      claimedAt: new Date(),
    });
    const assignmentId = assignment.id;

    // Create job event
    const eventId = `event_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
    await prisma.jobEvent.create({
      data: {
        id: eventId,
        assignmentId: assignmentId,
        step: 'navigate_to_pickup',
        payload: {
          assignedBy: 'admin',
          reason: 'Assigned via dispatch panel',
          assignedAt: new Date().toISOString(),
          action: 'job_assigned',
        },
        notes: `Job assigned to driver ${driver.User?.name || 'Unknown'} via dispatch panel`,
        createdBy: (session.user as any).id,
      }
    });

    console.log('✅ Job assigned successfully:', {
      jobId,
      driverId: finalDriverId,
      reference: updatedJob.reference,
      driverName: updatedJob.driver?.User.name
    });

    // ========================================
    // 🚨 CRITICAL: SEND REAL-TIME NOTIFICATIONS
    // ========================================
    try {
      const pusher = getPusherServer();

      // PRIMARY EVENT: Notify driver with "route-matched" event
      console.log('📡 Sending route-matched event to driver channel:', `driver-${finalDriverId}`);
      await pusher.trigger(`driver-${finalDriverId}`, 'route-matched', {
        type: 'single-order',
        bookingId: updatedJob.id,
        bookingReference: updatedJob.reference,
        orderNumber: updatedJob.reference,  // ✅ CRITICAL: Same ID as Admin/Customer sees
        customerName: updatedJob.customerName,
        assignmentId: assignmentId,
        jobCount: 1,
        assignedAt: new Date().toISOString(),
        message: `New order ${updatedJob.reference} assigned to you`,
        from: updatedJob.pickupAddress?.label || 'Pickup location',
        to: updatedJob.dropoffAddress?.label || 'Delivery location',
        scheduledAt: updatedJob.scheduledAt,
      });

      // BACKWARD COMPATIBILITY: Send job-assigned event
      console.log('📡 Sending job-assigned event to driver channel:', `driver-${finalDriverId}`);
      await pusher.trigger(`driver-${finalDriverId}`, 'job-assigned', {
        bookingId: updatedJob.id,
        bookingReference: updatedJob.reference,
        customerName: updatedJob.customerName,
        assignedAt: new Date().toISOString(),
        message: 'You have been assigned a new job',
      });

      // Notify other drivers that job is no longer available
      await pusher.trigger('drivers-channel', 'job-assigned-to-other', {
        bookingId: updatedJob.id,
        bookingReference: updatedJob.reference,
        assignedTo: driver.User?.name || 'Unknown',
        message: 'This job has been assigned to another driver',
      });

      // Notify customer about driver assignment
      await pusher.trigger(`booking-${updatedJob.reference}`, 'driver-assigned', {
        driverName: driver.User?.name || 'Unknown',
        assignedAt: new Date().toISOString(),
        message: 'Your driver has been assigned and will contact you soon',
      });

      // Notify admin dashboard
      await pusher.trigger('admin-notifications', 'driver-assigned', {
        bookingId: updatedJob.id,
        bookingReference: updatedJob.reference,
        driverName: driver.User?.name || 'Unknown',
        assignedAt: new Date().toISOString(),
      });

      console.log('✅ Real-time notifications sent successfully for dispatch assignment');
    } catch (notificationError) {
      console.error('❌ Error sending real-time notifications:', notificationError);
      // Don't fail the request if notifications fail, but log the error
    }
    // ========================================

    // Log the assignment for audit
    await prisma.auditLog.create({
      data: {
        actorId: (session.user as any).id,
        actorRole: (session.user as any).role || 'admin',
        action: 'job_assigned',
        targetType: 'booking',
        targetId: jobId,
        before: undefined,
        after: {
          driverId: finalDriverId,
          status: 'CONFIRMED',
        },
        ip: request.headers.get('x-forwarded-for') || 'unknown',
        userAgent: request.headers.get('user-agent') || 'unknown',
      },
    });

    return NextResponse.json({
      success: true,
      message: 'Job assigned successfully',
      data: {
        jobId,
        driverId: finalDriverId,
        driverName: updatedJob.driver?.User.name,
        bookingReference: updatedJob.reference,
        assignmentId: assignmentId,
      },
    });
  } catch (error) {
    console.error('Dispatch assignment error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

