import { prisma } from '@/lib/prisma';

// Force dynamic rendering (uses headers/cookies/getServerSession)
export const dynamic = 'force-dynamic';

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user || (session.user as any).role !== 'admin') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const { category, description, severity, driverId, jobId } =
      await request.json();

    if (!category || !description || !severity) {
      return NextResponse.json(
        {
          error: 'Category, description, and severity are required',
        },
        { status: 400 }
      );
    }

    // Validate severity
    const validSeverities = ['low', 'medium', 'high', 'critical'];
    if (!validSeverities.includes(severity)) {
      return NextResponse.json(
        {
          error: 'Invalid severity level',
        },
        { status: 400 }
      );
    }

    // Create the incident
    const incident = await prisma.driverIncident.create({
      data: {
        driverId: driverId || null,
        assignmentId: jobId ? await getAssignmentId(jobId) : null,
        type: category,
        title: category,
        description,
        severity,
        status: 'reported',
      },
      include: {
        Driver: {
          include: {
            User: {
              select: {
                id: true,
                name: true,
                email: true,
                role: true,
                createdAt: true,
                isActive: true
              }
            },
          },
        },
        Assignment: {
          include: {
            Booking: true,
          },
        },
      },
    });

    // Log the incident creation for audit
    await prisma.auditLog.create({
      data: {
        actorId: (session.user as any).id,
        actorRole: (session.user as any).role || 'admin',
        action: 'incident_created',
        targetType: 'driverIncident',
        targetId: incident.id,
        before: undefined,
        after: {
          type: category,
          severity,
          status: 'reported',
        },
        ip: request.headers.get('x-forwarded-for') || 'unknown',
        userAgent: request.headers.get('user-agent') || 'unknown',
      },
    });

    return NextResponse.json({
      success: true,
      message: 'Incident created successfully',
      data: incident,
    });
  } catch (error) {
    console.error('Create incident error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

export async function GET(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user || (session.user as any).role !== 'admin') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const { searchParams } = new URL(request.url);
    const status = searchParams.get('status');
    const driverId = searchParams.get('driverId');
    const limit = parseInt(searchParams.get('limit') || '50');

    const where: any = {};
    if (status) where.status = status;
    if (driverId) where.driverId = driverId;

    const incidents = await prisma.driverIncident.findMany({
      where,
      include: {
        Driver: {
          include: {
            User: {
              select: {
                id: true,
                name: true,
                email: true,
                role: true,
                createdAt: true,
                isActive: true
              }
            },
          },
        },
        Assignment: {
          include: {
            Booking: true,
          },
        },
      },
      orderBy: {
        createdAt: 'desc',
      },
      take: limit,
    });

    return NextResponse.json({
      success: true,
      data: incidents,
    });
  } catch (error) {
    console.error('Get incidents error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

async function getAssignmentId(jobId: string): Promise<string | null> {
  try {
    const assignment = await prisma.assignment.findFirst({
      where: { bookingId: jobId },
      orderBy: { createdAt: 'desc' }
    });
    return assignment?.id || null;
  } catch {
    return null;
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { withPrisma } from '@/lib/prisma';
import Pusher from 'pusher';

export const dynamic = 'force-dynamic';

// Initialize Pusher
const pusher = new Pusher({
  appId: process.env.PUSHER_APP_ID || '',
  key: process.env.PUSHER_KEY || '',
  secret: process.env.PUSHER_SECRET || '',
  cluster: process.env.PUSHER_CLUSTER || 'eu',
  useTLS: true,
});

/**
 * GET /api/admin/dispatch/mode
 * Get current dispatch mode (auto or manual)
 */
export async function GET(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    
    if (!session?.user || (session.user as any).role !== 'admin') {
      return NextResponse.json(
        { error: 'Unauthorized - Admin access required' },
        { status: 401 }
      );
    }

    return await withPrisma(async (prisma) => {
      // Get active dispatch settings
      let settings = await prisma.dispatchSettings.findFirst({
        where: { isActive: true },
        orderBy: { createdAt: 'desc' }
      });

      // If no settings exist, create default (manual mode)
      if (!settings) {
        settings = await prisma.dispatchSettings.create({
          data: {
            mode: 'manual',
            isActive: true,
            updatedBy: (session.user as any).id,
            autoAssignRadius: 5000,
            minDriverRating: 4.0,
            maxDriverJobs: 3,
            requireOnlineStatus: true
          }
        });
      }

      return NextResponse.json({
        success: true,
        data: {
          mode: settings.mode,
          isActive: settings.isActive,
          autoAssignRadius: settings.autoAssignRadius,
          minDriverRating: settings.minDriverRating,
          maxDriverJobs: settings.maxDriverJobs,
          requireOnlineStatus: settings.requireOnlineStatus,
          updatedAt: settings.updatedAt
        }
      });
    });

  } catch (error) {
    console.error('❌ Error fetching dispatch mode:', error);
    return NextResponse.json(
      { error: 'Failed to fetch dispatch mode' },
      { status: 500 }
    );
  }
}

/**
 * POST /api/admin/dispatch/mode
 * Set dispatch mode (auto or manual)
 */
export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    
    if (!session?.user || (session.user as any).role !== 'admin') {
      return NextResponse.json(
        { error: 'Unauthorized - Admin access required' },
        { status: 401 }
      );
    }

    const { mode, settings } = await request.json();

    if (!mode || !['auto', 'manual'].includes(mode)) {
      return NextResponse.json(
        { error: 'Invalid mode. Must be "auto" or "manual"' },
        { status: 400 }
      );
    }

    console.log('🔄 Changing dispatch mode:', { mode, adminId: (session.user as any).id });

    return await withPrisma(async (prisma) => {
      // Deactivate all existing settings
      await prisma.dispatchSettings.updateMany({
        where: { isActive: true },
        data: { isActive: false }
      });

      // Create new settings
      const newSettings = await prisma.dispatchSettings.create({
        data: {
          mode: mode,
          isActive: true,
          updatedBy: (session.user as any).id,
          autoAssignRadius: settings?.autoAssignRadius || 5000,
          minDriverRating: settings?.minDriverRating || 4.0,
          maxDriverJobs: settings?.maxDriverJobs || 3,
          requireOnlineStatus: settings?.requireOnlineStatus !== false
        }
      });

      // Send real-time notification to all admins
      try {
        await pusher.trigger('admin-channel', 'dispatch-mode-changed', {
          mode: mode,
          changedBy: (session.user as any).name || 'Admin',
          changedAt: new Date().toISOString(),
          settings: newSettings
        });

        console.log('📡 Dispatch mode change notification sent');
      } catch (pusherError) {
        console.error('⚠️ Failed to send Pusher notification:', pusherError);
      }

      console.log(`✅ Dispatch mode changed to: ${mode}`);

      return NextResponse.json({
        success: true,
        message: `Dispatch mode changed to ${mode}`,
        data: {
          mode: newSettings.mode,
          isActive: newSettings.isActive,
          autoAssignRadius: newSettings.autoAssignRadius,
          minDriverRating: newSettings.minDriverRating,
          maxDriverJobs: newSettings.maxDriverJobs,
          requireOnlineStatus: newSettings.requireOnlineStatus,
          updatedAt: newSettings.updatedAt
        }
      });
    });

  } catch (error) {
    console.error('❌ Error setting dispatch mode:', error);
    return NextResponse.json(
      { error: 'Failed to set dispatch mode' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
import { upsertAssignment } from '@/lib/utils/assignment-helpers';

// Force dynamic rendering (uses headers/cookies/getServerSession)
export const dynamic = 'force-dynamic';

export async function GET(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user || (session.user as any).role !== 'admin') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    // Get real-time data for dispatch
    const [activeJobs, availableDrivers, openIncidents, driverLocations] =
      await Promise.all([
        // Active jobs with recent updates (exclude test bookings)
        prisma.booking.findMany({
          where: {
            status: {
              in: ['DRAFT', 'CONFIRMED'],
            },
            updatedAt: {
              gte: new Date(Date.now() - 5 * 60 * 1000), // Last 5 minutes
            },
            NOT: [
              { reference: { startsWith: 'test_' } },
              { reference: { startsWith: 'TEST_' } },
              { reference: { startsWith: 'demo_' } },
            ],
          },
          include: {
            driver: {
              include: {
                User: {
                  select: {
                    id: true,
                    name: true,
                    email: true,
                    role: true,
                    createdAt: true,
                    isActive: true
                  }
                },
                DriverAvailability: true,
              },
            },
          },
          orderBy: {
            updatedAt: 'desc',
          },
        }),

        // Available drivers with current status
        prisma.driver.findMany({
          where: {
            status: 'active',
            onboardingStatus: 'approved',
            DriverAvailability: {
              status: 'online',
            },
          },
          include: {
            User: {
              select: {
                id: true,
                name: true,
                email: true,
                role: true,
                createdAt: true,
                isActive: true
              }
            },
            DriverAvailability: true,
            DriverVehicle: true,
            Booking: {
              where: {
                status: {
                  in: ['CONFIRMED'],
                },
              },
            },
          },
        }),

        // Open incidents
        prisma.driverIncident.findMany({
          where: {
            status: 'reported',
          },
          include: {
            Driver: {
              include: {
                User: {
                  select: {
                    id: true,
                    name: true,
                    email: true,
                    role: true,
                    createdAt: true,
                    isActive: true
                  }
                },
              },
            },
            Assignment: {
              include: {
                Booking: true,
              },
            },
          },
          orderBy: {
            createdAt: 'desc',
          },
          take: 10,
        }),

        // Recent driver location updates
        prisma.trackingPing.findMany({
          where: {
            createdAt: {
              gte: new Date(Date.now() - 10 * 60 * 1000), // Last 10 minutes
            },
          },
          include: {
            Driver: {
              include: {
                User: {
                  select: {
                    id: true,
                    name: true,
                    email: true,
                    role: true,
                    createdAt: true,
                    isActive: true
                  }
                },
              },
            },
          },
          orderBy: {
            createdAt: 'desc',
          },
        }),
      ]);

    // Process driver locations
    const processedLocations = driverLocations.reduce(
      (acc, ping) => {
        if (!acc[ping.driverId]) {
          acc[ping.driverId] = {
            driverId: ping.driverId,
            driverName: ping.Driver.User.name,
            lat: ping.lat,
            lng: ping.lng,
            lastUpdate: ping.createdAt,
            status: 'offline',
          };
        }
        return acc;
      },
      {} as Record<string, any>
    );

    return NextResponse.json({
      success: true,
      data: {
        activeJobs,
        availableDrivers,
        openIncidents,
        driverLocations: Object.values(processedLocations),
        lastUpdate: new Date().toISOString(),
      },
    });
  } catch (error) {
    console.error('Real-time dispatch data error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user || (session.user as any).role !== 'admin') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const { action, data } = await request.json();

    switch (action) {
      case 'update_job_status':
        const { jobId, status, reason } = data;

        const updatedJob = await prisma.booking.update({
          where: { id: jobId },
          data: {
            status,
            updatedAt: new Date(),
          },
          include: {
            driver: {
              include: {
                User: {
                  select: {
                    id: true,
                    name: true,
                    email: true,
                    role: true,
                    createdAt: true,
                    isActive: true
                  }
                },
              },
            },
          },
        });

        // Log the status change
        await prisma.auditLog.create({
          data: {
            actorId: (session.user as any).id,
            actorRole: (session.user as any).role || 'admin',
            action: 'job_status_updated',
            targetType: 'booking',
            targetId: jobId,
            before: undefined,
            after: {
              status,
              reason: reason || 'Manual update',
            },
            ip: request.headers.get('x-forwarded-for') || 'unknown',
            userAgent: request.headers.get('user-agent') || 'unknown',
          },
        });

        return NextResponse.json({
          success: true,
          data: updatedJob,
        });

      case 'assign_job':
        const { jobId: assignJobId, driverId } = data;

        // Check if job is already assigned
        const existingJob = await prisma.booking.findUnique({
          where: { id: assignJobId },
        });

        if (existingJob?.driverId) {
          return NextResponse.json(
            {
              error: 'Job is already assigned',
            },
            { status: 400 }
          );
        }

        const assignedJob = await prisma.booking.update({
          where: { id: assignJobId },
          data: {
            driverId,
            status: 'CONFIRMED',
            updatedAt: new Date(),
          },
          include: {
            driver: {
              include: {
                User: {
                  select: {
                    id: true,
                    name: true,
                    email: true,
                    role: true,
                    createdAt: true,
                    isActive: true
                  }
                },
              },
            },
          },
        });

        // Create or update assignment record
        await upsertAssignment(prisma, assignJobId, {
          driverId,
          status: 'invited',
        });

        return NextResponse.json({
          success: true,
          data: assignedJob,
        });

      case 'create_incident':
        const {
          category,
          description,
          severity,
          driverId: incidentDriverId,
          jobId: incidentJobId,
        } = data;

        const incident = await prisma.driverIncident.create({
          data: {
            id: `incident_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
            driverId: incidentDriverId || 'unknown',
            assignmentId: incidentJobId
              ? await getAssignmentId(incidentJobId)
              : null,
            type: category as any, // Cast to IncidentType enum
            title: category,
            description,
            severity: severity as any, // Cast to IncidentSeverity enum
            status: 'reported',
            createdAt: new Date(),
            updatedAt: new Date(),
          },
          include: {
            Driver: {
              include: {
                User: {
                  select: {
                    id: true,
                    name: true,
                    email: true,
                    role: true,
                    createdAt: true,
                    isActive: true
                  }
                },
              },
            },
            Assignment: {
              include: {
                Booking: true,
              },
            },
          },
        });

        return NextResponse.json({
          success: true,
          data: incident,
        });

      default:
        return NextResponse.json(
          {
            error: 'Invalid action',
          },
          { status: 400 }
        );
    }
  } catch (error) {
    console.error('Real-time dispatch action error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

async function getAssignmentId(jobId: string): Promise<string | null> {
  try {
    const assignment = await prisma.assignment.findFirst({
      where: { bookingId: jobId },
      orderBy: { createdAt: 'desc' }
    });
    return assignment?.id || null;
  } catch {
    return null;
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
import { upsertAssignment } from '@/lib/utils/assignment-helpers';

// Force dynamic rendering (uses headers/cookies/getServerSession)
export const dynamic = 'force-dynamic';

interface AssignmentRules {
  radius: number;
  vehicleType: string;
  capacity: string;
  loadLimit: string;
  rating: number;
  maxJobs: number;
  distanceWeight: number;
  ratingWeight: number;
  experienceWeight: number;
  loadWeight: number;
  timeWindowPriority: string;
  geographicPreference: string;
}

interface DriverScore {
  driverId: string;
  driver: any;
  score: number;
  factors: {
    distance: number;
    rating: number;
    experience: number;
    currentLoad: number;
    availability: number;
  };
  reasons: string[];
}

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user || (session.user as any).role !== 'admin') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const { jobId, rules } = await request.json();

    if (!jobId) {
      return NextResponse.json(
        { error: 'Job ID is required' },
        { status: 400 }
      );
    }

    // Get job details
    const job = await prisma.booking.findUnique({
      where: { id: jobId },
      include: {
        customer: true,
      },
    });

    if (!job) {
      return NextResponse.json({ error: 'Job not found' }, { status: 404 });
    }

    if (job.driverId) {
      return NextResponse.json(
        { error: 'Job is already assigned' },
        { status: 400 }
      );
    }

    // Get assignment rules (default or from config)
    const assignmentRules: AssignmentRules = {
      radius: 5000, // 5km default
      vehicleType: 'any',
      capacity: 'any',
      loadLimit: 'any',
      rating: 4.0,
      maxJobs: 3,
      distanceWeight: 70,
      ratingWeight: 20,
      experienceWeight: 10,
      loadWeight: 50,
      timeWindowPriority: 'urgent',
      geographicPreference: 'nearest',
      ...rules,
    };

    // Get available drivers
    const availableDrivers = await prisma.driver.findMany({
      where: {
        status: 'active',
        onboardingStatus: 'approved',
        DriverAvailability: {
          status: 'online',
        },
      },
      include: {
        User: {
          select: {
            id: true,
            name: true,
            email: true,
            role: true,
            createdAt: true,
            isActive: true
          }
        },
        DriverAvailability: true,
        DriverVehicle: true,
        Booking: {
          where: {
            status: {
              in: ['CONFIRMED'],
            },
          },
        },
        DriverRating: true,
        DriverPerformance: true,
      },
    });

    // Score and rank drivers
    const driverScores: DriverScore[] = [];

    for (const driver of availableDrivers) {
      const score = await calculateDriverScore(driver, job, assignmentRules);
      if (score.score > 0) {
        driverScores.push(score);
      }
    }

    // Sort by score (highest first)
    driverScores.sort((a, b) => b.score - a.score);

    if (driverScores.length === 0) {
      return NextResponse.json(
        {
          error: 'No eligible drivers found',
          details: {
            totalDrivers: availableDrivers.length,
            filteredDrivers: 0,
            reasons: ['No drivers meet the assignment criteria'],
          },
        },
        { status: 400 }
      );
    }

    // Select the best driver
    const bestDriver = driverScores[0];

    // Assign the job
    const assignedJob = await prisma.booking.update({
      where: { id: jobId },
      data: {
        driverId: bestDriver.driverId,
        status: 'CONFIRMED',
        updatedAt: new Date(),
      },
      include: {
        driver: {
          include: {
            User: {
              select: {
                id: true,
                name: true,
                email: true,
                role: true,
                createdAt: true,
                isActive: true
              }
            },
          },
        },
        customer: true,
      },
    });

    // Create or update assignment record
    await upsertAssignment(prisma, jobId, {
      driverId: bestDriver.driverId,
      status: 'invited',
    });

    // Log the assignment with detailed reasoning
    await prisma.auditLog.create({
      data: {
        actorId: session.user.id,
        actorRole: 'admin',
        action: 'smart_job_assigned',
        targetType: 'booking',
        targetId: jobId,
        after: {
          driverId: bestDriver.driverId,
          status: 'CONFIRMED',
          score: bestDriver.score,
          factors: bestDriver.factors,
          reasons: bestDriver.reasons,
          totalCandidates: driverScores.length,
          assignmentRules: assignmentRules as any,
        },
        ip: request.headers.get('x-forwarded-for') || 'unknown',
        userAgent: request.headers.get('user-agent') || 'unknown',
      },
    });

    return NextResponse.json({
      success: true,
      message: 'Job assigned successfully using smart assignment',
      data: {
        assignedJob,
        selectedDriver: {
          id: bestDriver.driverId,
          name: bestDriver.driver.user.name,
          score: bestDriver.score,
          factors: bestDriver.factors,
          reasons: bestDriver.reasons,
        },
        candidates: driverScores.slice(0, 5).map(ds => ({
          id: ds.driverId,
          name: ds.driver.user.name,
          score: ds.score,
          factors: ds.factors,
        })),
        assignmentRules,
      },
    });
  } catch (error) {
    console.error('Smart assignment error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

async function calculateDriverScore(
  driver: any,
  job: any,
  rules: AssignmentRules
): Promise<DriverScore> {
  const factors = {
    distance: 0,
    rating: 0,
    experience: 0,
    currentLoad: 0,
    availability: 0,
  };
  const reasons: string[] = [];

  // Check basic eligibility
  if (driver.bookings.length >= rules.maxJobs) {
    reasons.push(
      `Driver has ${driver.bookings.length} active jobs (max: ${rules.maxJobs})`
    );
    return { driverId: driver.id, driver, score: 0, factors, reasons };
  }

  if (driver.rating && driver.rating < rules.rating) {
    reasons.push(
      `Driver rating ${driver.rating} below minimum ${rules.rating}`
    );
    return { driverId: driver.id, driver, score: 0, factors, reasons };
  }

  // Calculate distance factor (simplified - in real app, use actual coordinates)
  const distance = calculateDistance(job, driver); // DEPRECATED - internal use only
  if (distance > rules.radius) {
    reasons.push(
      `Driver too far: ${Math.round(distance / 1000)}km (max: ${rules.radius / 1000}km)`
    );
    return { driverId: driver.id, driver, score: 0, factors, reasons };
  }

  // Distance score (closer is better)
  factors.distance = Math.max(0, 100 - (distance / rules.radius) * 100);
  reasons.push(`Distance: ${Math.round(distance / 1000)}km`);

  // Rating score
  if (driver.rating) {
    factors.rating = (driver.rating / 5) * 100;
    reasons.push(`Rating: ${driver.rating}/5`);
  }

  // Experience score (based on completed jobs)
  const completedJobs =
    driver.bookings?.filter((b: any) => b.status === 'completed').length || 0;
  factors.experience = Math.min(100, (completedJobs / 50) * 100); // Cap at 50 jobs
  reasons.push(`Experience: ${completedJobs} completed jobs`);

  // Current load score (fewer jobs is better)
  const currentJobs = driver.bookings.length;
  factors.currentLoad = Math.max(0, 100 - (currentJobs / rules.maxJobs) * 100);
  reasons.push(`Current load: ${currentJobs}/${rules.maxJobs} jobs`);

  // Availability score (online status)
  factors.availability = driver.availability?.status === 'online' ? 100 : 0;

  // Calculate weighted score
  const score =
    (factors.distance * rules.distanceWeight +
      factors.rating * rules.ratingWeight +
      factors.experience * rules.experienceWeight +
      factors.currentLoad * rules.loadWeight +
      factors.availability * 10) /
    (rules.distanceWeight +
      rules.ratingWeight +
      rules.experienceWeight +
      rules.loadWeight +
      10);

  return {
    driverId: driver.id,
    driver,
    score: Math.round(score * 100) / 100,
    factors,
    reasons,
  };
}

function calculateDistance(job: any, driver: any): number { // DEPRECATED - internal use only
  // Simplified distance calculation
  // In a real implementation, you would use actual coordinates
  // For now, return a random distance within reasonable bounds
  return Math.random() * 10000; // 0-10km
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
import { unifiedEmailService } from '@/lib/email/UnifiedEmailService';
import { randomBytes } from 'crypto';

export const dynamic = 'force-dynamic';

export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    console.log('🔧 [APPROVE DEBUG] Starting approval process for ID:', (await params).id);
    
    // Check admin authentication
    const session = await getServerSession(authOptions);
    if (!session?.user || (session.user as any).role !== 'admin') {
      console.log('❌ [APPROVE DEBUG] Unauthorized access attempt');
      return NextResponse.json(
        { error: 'Unauthorized - Admin access required' },
        { status: 401 }
      );
    }

    const { id: applicationId } = await params;
    const adminUserId = (session.user as any).id;
    console.log('🔧 [APPROVE DEBUG] Admin user ID:', adminUserId);

    // Get the application with additional validation
    let application;
    try {
      application = await prisma.driverApplication.findUnique({
        where: { id: applicationId },
      });
    } catch (dbError) {
      console.error('❌ [APPROVE DEBUG] Database error fetching application:', dbError);
      return NextResponse.json(
        { 
          error: 'Database error',
          details: 'Unable to fetch application from database'
        },
        { status: 500 }
      );
    }

    if (!application) {
      console.log('❌ [APPROVE DEBUG] Application not found:', applicationId);
      return NextResponse.json(
        { error: 'Application not found' },
        { status: 404 }
      );
    }

    console.log('🔧 [APPROVE DEBUG] Application found:', {
      id: application.id,
      email: application.email,
      status: application.status,
      firstName: application.firstName,
      lastName: application.lastName,
    });

    if (application.status !== 'pending' && application.status !== 'under_review') {
      console.log('❌ [APPROVE DEBUG] Invalid application status:', application.status);
      return NextResponse.json(
        { 
          error: 'Application cannot be approved',
          details: `Application status is ${application.status}. Only pending or under_review applications can be approved.`
        },
        { status: 400 }
      );
    }

    // Use database transaction to ensure atomicity
    const result = await prisma.$transaction(async (tx) => {
      console.log('🔧 [APPROVE DEBUG] Starting database transaction');

      // Check if user already exists
      const existingUser = await tx.user.findUnique({
        where: { email: application.email },
      });

      let userId: string;
      let user;

      if (existingUser) {
        console.log('🔧 [APPROVE DEBUG] Existing user found:', existingUser.id);
        
        // User exists, check if they're already a driver
        const existingDriver = await tx.driver.findUnique({
          where: { userId: existingUser.id },
        });

        if (existingDriver) {
          console.log('❌ [APPROVE DEBUG] User is already a driver');
          throw new Error('User is already a driver');
        }

        // Update existing user to driver role
        user = await tx.user.update({
          where: { id: existingUser.id },
          data: {
            role: 'driver',
            isActive: true,
          },
        });
        userId = existingUser.id;
        console.log('🔧 [APPROVE DEBUG] Updated existing user to driver role');
      } else {
        console.log('🔧 [APPROVE DEBUG] Creating new user');
        // Create new user
        const tempPassword = randomBytes(8).toString('hex');
        user = await tx.user.create({
          data: {
            email: application.email,
            name: `${application.firstName} ${application.lastName}`,
            role: 'driver',
            password: tempPassword,
            isActive: true,
          },
        });
        userId = user.id;
        console.log('🔧 [APPROVE DEBUG] New user created:', user.id);
      }

      // Create driver record
      console.log('🔧 [APPROVE DEBUG] Creating driver record');
      const driver = await tx.driver.create({
        data: {
          userId: userId,
          status: 'active',
          onboardingStatus: 'approved',
          approvedAt: new Date(),
        },
      });
      console.log('🔧 [APPROVE DEBUG] Driver record created:', driver.id);

      // Create driver availability record
      console.log('🔧 [APPROVE DEBUG] Creating driver availability record');
      await tx.driverAvailability.create({
        data: {
          driverId: driver.id,
          status: 'offline',
          locationConsent: false,
        },
      });
      console.log('🔧 [APPROVE DEBUG] Driver availability record created');

      // Create driver performance record
      console.log('🔧 [APPROVE DEBUG] Creating driver performance record');
      await tx.driverPerformance.create({
        data: {
          driverId: driver.id,
          averageRating: 0,
          totalRatings: 0,
          completionRate: 0,
          acceptanceRate: 0,
          onTimeRate: 0,
          cancellationRate: 0,
          totalJobs: 0,
          completedJobs: 0,
          cancelledJobs: 0,
          lateJobs: 0,
        },
      });
      console.log('🔧 [APPROVE DEBUG] Driver performance record created');

      // Create driver notification preferences
      console.log('🔧 [APPROVE DEBUG] Creating driver notification preferences');
      await tx.driverNotificationPreferences.create({
        data: {
          driverId: driver.id,
          pushJobOffers: true,
          pushJobUpdates: true,
          emailJobOffers: true,
          emailJobUpdates: true,
          smsJobOffers: false,
          smsJobUpdates: false,
        },
      });
      console.log('🔧 [APPROVE DEBUG] Driver notification preferences created');

      // Update application status
      console.log('🔧 [APPROVE DEBUG] Updating application status');
      await tx.driverApplication.update({
        where: { id: applicationId },
        data: {
          status: 'approved',
          reviewedBy: adminUserId,
          reviewedAt: new Date(),
        },
      });
      console.log('🔧 [APPROVE DEBUG] Application status updated');

      // Create driver notification
      console.log('🔧 [APPROVE DEBUG] Creating driver notification');
      await tx.driverNotification.create({
        data: {
          driverId: driver.id,
          type: 'job_offer',
          title: 'Welcome to Speedy Van! 🎉',
          message: 'Your driver application has been approved. You can now start accepting jobs and earning money!',
          read: false,
        },
      });
      console.log('🔧 [APPROVE DEBUG] Driver notification created');

      return { driver, user };
    });

    console.log('✅ Driver application approved successfully:', {
      applicationId,
      driverId: result.driver.id,
      userId: result.user.id,
      email: application.email,
      fullName: `${application.firstName} ${application.lastName}`,
      approvedBy: adminUserId,
    });

    // Send approval email (outside transaction to avoid email failures affecting approval)
    try {
      console.log('🔧 [APPROVE DEBUG] Sending approval email');
      const emailResult = await unifiedEmailService.sendDriverApplicationStatus({
        driverEmail: application.email,
        driverName: `${application.firstName} ${application.lastName}`,
        applicationId: application.id,
        status: 'approved',
        reviewedAt: new Date().toISOString(),
        nextSteps: [
          'You will receive separate login credentials via email',
          'Log in to the driver portal to start working',
          'Download the Speedy Van driver app for easy job management',
          'Begin accepting jobs and earning money immediately',
        ],
      });

      if (emailResult.success) {
