    console.log('❌ Driver application rejected:', {
      applicationId,
      email: application.email,
      fullName: (application as any).fullName || 'Unknown Driver',
      reviewNotes: rejectionReason || 'No reason provided',
      rejectedBy: adminUserId,
    });

