/**
 * POST /api/admin/drivers/[id]/remove-all
 * Remove all orders and routes from a specific driver
 */
export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const session = await getServerSession(authOptions);
    
    if (!session?.user || (session.user as any).role !== 'admin') {
      return NextResponse.json(
        { error: 'Unauthorized - Admin access required' },
        { status: 401 }
      );
    }

    const { id: driverId } = await params;
    const body = await request.json();
    const { reason, type = 'all' } = body; // type can be 'all', 'orders', or 'routes'

    console.log('🔄 Admin removing assignments from driver:', { driverId, type, reason });

    return await withPrisma(async (prisma) => {
      // Find the driver
      const driver = await prisma.driver.findUnique({
        where: { id: driverId },
        include: {
          User: {
            select: { name: true, email: true }
          }
        }
      });

      if (!driver) {
        return NextResponse.json(
          { error: 'Driver not found' },
          { status: 404 }
        );
      }

      const driverName = driver.User?.name || 'Unknown';
      let removedOrders = 0;
      let removedRoutes = 0;

      await prisma.$transaction(async (tx) => {
        // Remove orders if requested
        if (type === 'all' || type === 'orders') {
          // Get all active bookings for this driver
          const bookings = await tx.booking.findMany({
            where: {
              driverId: driverId,
              status: {
                in: ['CONFIRMED', 'PENDING_PAYMENT']
              }
            },
            include: {
              Assignment: true
            }
          });

          removedOrders = bookings.length;

          // Update each booking
          for (const booking of bookings) {
            await tx.booking.update({
              where: { id: booking.id },
              data: {
                driverId: null,
                routeId: null,
                status: 'CONFIRMED'
              }
            });

            // Cancel assignment if exists
            const activeAssignment = getActiveAssignment(booking.Assignment);
            if (activeAssignment) {
              await tx.assignment.update({
                where: { id: activeAssignment.id },
                data: {
                  status: 'cancelled',
                  updatedAt: new Date()
                }
              });
            }
          }
        }

        // Remove routes if requested
        if (type === 'all' || type === 'routes') {
          // Get all active routes for this driver
          const routes = await tx.route.findMany({
            where: {
              driverId: driverId,
              status: {
                in: ['planned', 'assigned', 'pending_assignment', 'in_progress']
              }
            },
            include: {
              Booking: true
            }
          });

          removedRoutes = routes.length;

          // Update each route
          for (const route of routes) {
            await tx.route.update({
              where: { id: route.id },
              data: {
                status: 'pending_assignment',
                updatedAt: new Date()
              }
            });

            // Remove driver from route after setting status
            await tx.route.update({
              where: { id: route.id },
              data: {
                driverId: { set: null }
              }
            });

            // Update all bookings in this route
            if (route.Booking && route.Booking.length > 0) {
              for (const booking of route.Booking) {
                await tx.booking.update({
                  where: { id: booking.id },
                  data: {
                    driverId: null,
                    routeId: null,
                    status: 'CONFIRMED'
                  }
                });

                // Cancel assignment
                const assignment = await tx.assignment.findFirst({
                  where: { bookingId: booking.id },
                  orderBy: { createdAt: 'desc' }
                });

                if (assignment) {
                  await tx.assignment.update({
                    where: { id: assignment.id },
                    data: {
                      status: 'cancelled',
                      updatedAt: new Date()
                    }
                  });
                }
              }
            }
          }
        }

        // Reset driver availability
        const driverAvailability = await tx.driverAvailability.findUnique({
          where: { driverId: driverId }
        });

        if (driverAvailability) {
          await tx.driverAvailability.update({
            where: { driverId: driverId },
            data: {
              currentCapacityUsed: 0,
              status: 'offline' // Set driver offline as a safety measure
            }
          });
        }
      });

      console.log('✅ All assignments removed successfully:', {
        driverId,
        driverName,
        removedOrders,
        removedRoutes,
        type,
        reason
      });

      return NextResponse.json({
        success: true,
        message: `Removed ${removedOrders} orders and ${removedRoutes} routes from ${driverName}`,
        data: {
          driverId,
          driverName,
          removedOrders,
          removedRoutes,
          type,
          reason
        }
      });

    });

  } catch (error) {
    console.error('❌ Error removing driver assignments:', error);
    return NextResponse.json(
      { 
        success: false,
        error: error instanceof Error ? error.message : 'Failed to remove driver assignments'
      },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { requireAdmin } from '@/lib/auth';

export const dynamic = 'force-dynamic';

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    // Check admin authentication
    const authResult = await requireAdmin(request);
    if (authResult instanceof NextResponse) {
      return authResult;
    }
    
    const adminUser = authResult;
    const { reason } = await request.json();
    const { id: driverId } = await params;

    // Get driver with current status
    const driver = await prisma.driver.findUnique({
      where: { id: driverId },
      include: {
        User: {
          select: {
            id: true,
            name: true,
            email: true,
          },
        },
      },
    });

    if (!driver) {
      return NextResponse.json({ error: 'Driver not found' }, { status: 404 });
    }

    // Clear push subscriptions and availability status
    await prisma.pushSubscription.deleteMany({
      where: { driverId: driverId },
    });

    await prisma.driverAvailability.updateMany({
      where: { driverId: driverId },
      data: {
        status: 'offline',
        lastSeenAt: new Date(),
      },
    });

    // Create audit log
    await prisma.auditLog.create({
      data: {
        actorId: adminUser.id,
        actorRole: 'admin',
        action: 'driver_device_reset',
        targetType: 'Driver',
        targetId: driverId,
        after: {
          reason: reason || 'Device reset by admin',
          resetBy: adminUser.email,
          resetAt: new Date().toISOString(),
          actions: [
            'Cleared push subscriptions',
            'Set availability to offline',
            'Reset last seen timestamp',
          ],
        },
        ip:
          request.headers.get('x-forwarded-for') ||
          request.headers.get('x-real-ip') ||
          'unknown',
        userAgent: request.headers.get('user-agent') || 'unknown',
      },
    });

    // Send notification to driver (if notification system is implemented)
    // await sendDriverNotification(driver.userId, 'device_reset', {
    //   driverName: driver.user.name,
    //   resetAt: new Date().toISOString(),
    //   reason: reason || 'Device reset by admin',
    // });

    return NextResponse.json({
      success: true,
      message: 'Driver device reset successfully',
      driver: {
        id: driver.id,
        name: driver.User.name,
        email: driver.User.email,
        deviceResetAt: new Date().toISOString(),
        reason: reason || 'Device reset by admin',
      },
    });
  } catch (error) {
    console.error('Driver device reset error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { requireAdmin } from '@/lib/auth';
import { logAudit } from '@/lib/audit';

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const authResult = await requireAdmin(request);
    if (authResult instanceof NextResponse) {
      return authResult;
    }
    const user = authResult;

    const { id: driverId } = await params;
    const { action, reviewNotes, documentId } = await request.json();

    if (!action || !['approve', 'reject', 'request_changes'].includes(action)) {
      return NextResponse.json({ error: 'Invalid action' }, { status: 400 });
    }

    const driver = await prisma.driver.findUnique({
      where: { id: driverId },
      include: {
        User: {
          select: {
            id: true,
            name: true,
            email: true,
            role: true,
            createdAt: true,
            isActive: true
          }
        },
        Document: true,
        DriverChecks: true,
        DriverVehicle: true,
      },
    });

    if (!driver) {
      return NextResponse.json({ error: 'Driver not found' }, { status: 404 });
    }

    let updateData: any = {};
    let documentUpdateData: any = {};

    switch (action) {
      case 'approve':
        updateData = {
          onboardingStatus: 'approved',
          approvedAt: new Date(),
        };

        if (documentId) {
          documentUpdateData = {
            status: 'verified',
            verifiedAt: new Date(),
            verifiedBy: user.id,
          };
        }
        break;

      case 'reject':
        updateData = {
          onboardingStatus: 'suspended',
        };

        if (documentId) {
          documentUpdateData = {
            status: 'rejected',
            verifiedAt: new Date(),
            verifiedBy: user.id,
          };
        }
        break;

      case 'request_changes':
        updateData = {
          onboardingStatus: 'docs_pending',
        };
        break;
    }

    // Update driver status
    if (Object.keys(updateData).length > 0) {
      await prisma.driver.update({
        where: { id: driverId },
        data: updateData,
      });
    }

    // Update specific document if provided
    if (documentId && Object.keys(documentUpdateData).length > 0) {
      await prisma.document.update({
        where: { id: documentId },
        data: documentUpdateData,
      });
    }

    // Log the review action
    await logAudit(user.id, `driver_${action}`, driverId, { targetType: 'driver', before: { onboardingStatus: driver.onboardingStatus, documents: driver.Document.map(d => ({ id: d.id, status: d.status })) }, after: { onboardingStatus: updateData.onboardingStatus || driver.onboardingStatus, reviewNotes, documentId, reviewedBy: user.id } });

    return NextResponse.json({
      success: true,
      message: `Driver ${action}d successfully`,
      driver: {
        id: driver.id,
        onboardingStatus:
          updateData.onboardingStatus || driver.onboardingStatus,
        approvedAt: updateData.approvedAt || driver.approvedAt,
      },
    });
  } catch (error) {
    console.error('Driver review error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const authResult = await requireAdmin(request);
    if (authResult instanceof NextResponse) {
      return authResult;
    }
    const user = authResult;

    const { id: driverId } = await params;

    const driver = await prisma.driver.findUnique({
      where: { id: driverId },
      include: {
        User: {
          select: {
            id: true,
            name: true,
            email: true,
            role: true,
            createdAt: true,
            isActive: true
          }
        },
        Document: {
          orderBy: { uploadedAt: 'desc' },
        },
        DriverChecks: true,
        DriverVehicle: true,
      },
    });

    if (!driver) {
      return NextResponse.json({ error: 'Driver not found' }, { status: 404 });
    }

    // Check compliance status
    const complianceStatus = {
      personalInfo: !!driver.User.name && !!driver.basePostcode,
      vehicle: driver.DriverVehicle.length > 0,
      license: !!driver.DriverChecks?.licenceCategories?.length,
      insurance: !!driver.DriverChecks?.insurancePolicyNo && !!driver.DriverChecks?.insurer,
      rtw: !!driver.DriverChecks?.rtwMethod,
      dbs: !!driver.DriverChecks?.dbsType,
      documents: {
        rtw: driver.Document.some(
          d => d.category === 'rtw' && d.status === 'verified'
        ),
        licence: driver.Document.some(
          d => d.category === 'licence' && d.status === 'verified'
        ),
        insurance: driver.Document.some(
          d => d.category === 'insurance' && d.status === 'verified'
        ),
        mot: driver.Document.some(
          d => d.category === 'mot' && d.status === 'verified'
        ),
        v5c: driver.Document.some(
          d => d.category === 'v5c' && d.status === 'verified'
        ),
        dbs: driver.Document.some(
          d => d.category === 'dbs' && d.status === 'verified'
        ),
      },
    };

    const allRequiredDocumentsVerified = Object.values(
      complianceStatus.documents
    ).every(Boolean);
    const allInfoComplete = Object.values(complianceStatus).every(Boolean);

    return NextResponse.json({
      driver: {
        id: driver.id,
        name: driver.User.name,
        email: driver.User.email,
        onboardingStatus: driver.onboardingStatus,
        approvedAt: driver.approvedAt,
        createdAt: driver.createdAt,
        updatedAt: driver.updatedAt,
      },
      compliance: {
        ...complianceStatus,
        allRequiredDocumentsVerified,
        allInfoComplete,
        canApprove:
          allInfoComplete &&
          allRequiredDocumentsVerified &&
          driver.onboardingStatus === 'in_review',
      },
      documents: driver.Document,
      checks: driver.DriverChecks,
      vehicles: driver.DriverVehicle,
    });
  } catch (error) {
    console.error('Driver review GET error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { requireAdmin } from '@/lib/auth';

export const dynamic = 'force-dynamic';

export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const authResult = await requireAdmin(request);
    if (authResult instanceof NextResponse) {
      return authResult;
    }
    const user = authResult;

    const { id: driverId } = await params;

    const driver = await prisma.driver.findUnique({
      where: { id: driverId },
      include: {
        User: {
          select: {
            id: true,
            name: true,
            email: true,
            createdAt: true,
          },
        },
        DriverProfile: {
          select: {
            phone: true,
            address: true,
            dob: true,
          },
        },
        DriverVehicle: {
          select: {
            id: true,
            make: true,
            model: true,
            reg: true,
            weightClass: true,
            motExpiry: true,
          },
        },
        DriverChecks: {
          select: {
            rtwMethod: true,
            rtwExpiresAt: true,
            licenceCategories: true,
            points: true,
            licenceExpiry: true,
            dbsType: true,
            dbsCheckedAt: true,
            insurancePolicyNo: true,
            insurer: true,
            policyEnd: true,
          },
        },
        Document: {
          select: {
            id: true,
            category: true,
            fileUrl: true,
            status: true,
            uploadedAt: true,
            expiresAt: true,
            verifiedAt: true,
            verifiedBy: true,
          },
        },
        DriverRating: {
          select: {
            rating: true,
            createdAt: true,
          },
          orderBy: { createdAt: 'desc' },
          take: 50,
        },
        DriverIncident: {
          select: {
            id: true,
            type: true,
            severity: true,
            description: true,
            createdAt: true,
            status: true,
          },
          orderBy: { createdAt: 'desc' },
          take: 20,
        },
        Booking: {
          select: {
            id: true,
            status: true,
            totalGBP: true,
            createdAt: true,
            updatedAt: true,
          },
          orderBy: { createdAt: 'desc' },
          take: 100,
        },
        DriverAvailability: {
          select: {
            status: true,
            lastSeenAt: true,
            lastLat: true,
            lastLng: true,
          },
        },
        DriverPerformance: {
          select: {
            acceptanceRate: true,
            completionRate: true,
            onTimeRate: true,
            averageRating: true,
            totalJobs: true,
            completedJobs: true,
            lateJobs: true,
            totalRatings: true,
          },
        },
      },
    });

    if (!driver) {
      return NextResponse.json({ error: 'Driver not found' }, { status: 404 });
    }

    // Calculate KPIs
    const totalJobs = driver.Booking?.length || 0;
    const completedJobs =
      driver.Booking?.filter(b => b.status === 'COMPLETED').length || 0;
    const onTimeJobs =
      driver.Booking?.filter(b => b.status === 'COMPLETED').length || 0; // Simplified - no completedAt field
    const totalEarnings =
      driver.Booking?.reduce((sum, b) => {
        const value = Number(b.totalGBP || 0);
        return (Number.isFinite(value) && value >= 0 && value <= Number.MAX_SAFE_INTEGER) ? sum + value : sum;
      }, 0) || 0;

    const avgRating =
      driver.DriverRating.length > 0
        ? driver.DriverRating.reduce((sum, r) => sum + r.rating, 0) /
          driver.DriverRating.length
        : 0;

    // Calculate performance metrics
    const acceptanceRate =
      totalJobs > 0 ? Math.round((completedJobs / totalJobs) * 100) : 0;
    const completionRate =
      totalJobs > 0 ? Math.round((completedJobs / totalJobs) * 100) : 0;
    const onTimeRate =
      completedJobs > 0 ? Math.round((onTimeJobs / completedJobs) * 100) : 0;

    // Check compliance issues
    const complianceIssues = [];

    if (
      driver.DriverChecks?.licenceExpiry &&
      new Date(driver.DriverChecks.licenceExpiry) < new Date()
    ) {
      complianceIssues.push('License expired');
    }

    if (
      driver.DriverChecks?.rtwExpiresAt &&
      new Date(driver.DriverChecks.rtwExpiresAt) < new Date()
    ) {
      complianceIssues.push('Right to work expired');
    }

    if (
      driver.DriverChecks?.policyEnd &&
      new Date(driver.DriverChecks.policyEnd) < new Date()
    ) {
      complianceIssues.push('Insurance expired');
    }

    if (
      driver.DriverVehicle[0]?.motExpiry &&
      new Date(driver.DriverVehicle[0].motExpiry) < new Date()
    ) {
      complianceIssues.push('MOT expired');
    }

    if (driver.DriverChecks?.points && driver.DriverChecks.points > 6) {
      complianceIssues.push('Too many license points');
    }

    // Document expiries
    const documentExpiries = {
      license: driver.DriverChecks?.licenceExpiry?.toISOString() || null,
      insurance: driver.DriverChecks?.policyEnd?.toISOString() || null,
      mot: driver.DriverVehicle[0]?.motExpiry?.toISOString() || null,
      rtw: driver.DriverChecks?.rtwExpiresAt?.toISOString() || null,
    };

    const transformedDriver = {
      id: driver.id,
      name: driver.User.name || 'Unknown',
      email: driver.User.email,
      phone: driver.DriverProfile?.phone || 'Not provided',
      onboardingStatus: driver.onboardingStatus,
      status: driver.status,
      approvedAt: driver.approvedAt?.toISOString() || null,
      createdAt: driver.User.createdAt.toISOString(),
      updatedAt: driver.updatedAt.toISOString(),
      basePostcode: driver.basePostcode || 'Not provided',
      vehicleType: driver.vehicleType || 'Unknown',
      rating: avgRating,
      totalJobs,
      completedJobs,
      onTimeJobs,
      totalEarnings,
      DriverAvailability: driver.DriverAvailability?.status || 'offline',
      lastSeen: driver.DriverAvailability?.lastSeenAt?.toISOString() || null,
      complianceIssues,
      documentExpiries,
      kpis: {
        acceptanceRate,
        completionRate,
        onTimeRate,
        avgRating,
      },
      DriverIncident: driver.DriverIncident.map(incident => ({
        id: incident.id,
        type: incident.type,
        severity: incident.severity,
        description: incident.description,
        createdAt: incident.createdAt.toISOString(),
        status: incident.status,
      })),
      DriverPerformance: driver.DriverPerformance || {
        acceptanceRate,
        completionRate,
        onTimeRate,
        averageRating: avgRating,
        totalJobs,
        completedJobs,
        lateJobs: 0,
        totalRatings: driver.DriverRating?.length || 0,
      },
    };

    return NextResponse.json(transformedDriver);
  } catch (error) {
    console.error('Admin driver GET error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

export async function PUT(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const authResult = await requireAdmin(request);
    if (authResult instanceof NextResponse) {
      return authResult;
    }
    const user = authResult;

    const { id: driverId } = await params;
    const { status, autoAssignLimit, notes } = await request.json();

    // Get current driver data for audit
    const currentDriver = await prisma.driver.findUnique({
      where: { id: driverId },
      include: {
        User: {
          select: {
            name: true,
            email: true,
          },
        },
      },
    });

    if (!currentDriver) {
      return NextResponse.json({ error: 'Driver not found' }, { status: 404 });
    }

    // Update driver
    const updateData: any = {};
    if (status) updateData.status = status;
    if (autoAssignLimit !== undefined) {
      // This would typically be stored in a separate table or field
      // For now, we'll just log it
      console.log(
        `Auto-assign limit set to ${autoAssignLimit} for driver ${driverId}`
      );
    }

    await prisma.driver.update({
      where: { id: driverId },
      data: updateData,
    });

    // Create audit log
    await prisma.auditLog.create({
      data: {
        actorId: user.id,
        actorRole: 'admin',
        action: 'driver_updated',
        targetType: 'Driver',
        targetId: driverId,
        after: {
          previousStatus: currentDriver.status,
          newStatus: status,
          autoAssignLimit,
          notes,
          updatedBy: user.email,
          updatedAt: new Date().toISOString(),
        },
        ip:
          request.headers.get('x-forwarded-for') ||
          request.headers.get('x-real-ip') ||
          'unknown',
        userAgent: request.headers.get('user-agent') || 'unknown',
      },
    });

    return NextResponse.json({
      success: true,
      message: 'Driver updated successfully',
      driver: {
        id: driverId,
        status,
        autoAssignLimit,
      },
    });
  } catch (error) {
    console.error('Admin driver PUT error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';

export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const session = await getServerSession(authOptions);

    if (!session || session.user.role !== 'admin') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const { id: driverId } = await params;

    // Get driver info
    const driver = await prisma.driver.findUnique({
      where: { id: driverId },
      include: {
        User: {
          select: {
            name: true,
            email: true,
            phone: true,
          },
        },
      },
    });

    if (!driver) {
      return NextResponse.json({ error: 'Driver not found' }, { status: 404 });
    }

    const now = new Date();
    const todayStart = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    const todayEnd = new Date(todayStart);
    todayEnd.setDate(todayEnd.getDate() + 1);

    // Get routes
    const routes = await prisma.route.findMany({
      where: {
        driverId,
      },
      include: {
        drops: {
          include: {
            Booking: {
              select: {
                totalGBP: true,
              },
            },
          },
        },
      },
      orderBy: {
        createdAt: 'desc',
      },
    });

    // Get single bookings
    const bookings = await prisma.booking.findMany({
      where: {
        driverId,
        routeId: null, // Only single jobs (not part of a route)
      },
      orderBy: {
        scheduledAt: 'desc',
      },
    });

    // Categorize routes
    const today: any[] = [];
    const upcoming: any[] = [];
    const completed: any[] = [];

    routes.forEach((route) => {
      const totalValue = route.drops.reduce(
        (sum: number, drop: any) => sum + (drop.Booking?.totalGBP ? drop.Booking.totalGBP / 100 : 0),
        0
      );

      const item = {
        id: route.id,
        type: 'route',
        reference: route.id,
        status: route.status,
        startTime: route.createdAt,
        endTime: route.endTime,
        drops: route.drops.length,
        value: totalValue,
      };

      if (route.status === 'completed') {
        completed.push(item);
      } else if (route.createdAt >= todayStart && route.createdAt < todayEnd) {
        today.push(item);
      } else if (route.createdAt >= todayEnd) {
        upcoming.push(item);
      } else {
        today.push(item);
      }
    });

    // Categorize bookings
    bookings.forEach((booking) => {
      const item = {
        id: booking.id,
        type: 'booking',
        reference: booking.reference,
        status: booking.status,
        startTime: booking.scheduledAt,
        endTime: booking.status === 'COMPLETED' ? booking.updatedAt : null,
        value: booking.totalGBP / 100,
        pickupAddress: 'N/A',
        dropoffAddress: 'N/A',
      };

      if (booking.status === 'COMPLETED') {
        completed.push(item);
      } else if (booking.scheduledAt >= todayStart && booking.scheduledAt < todayEnd) {
        today.push(item);
      } else if (booking.scheduledAt >= todayEnd) {
        upcoming.push(item);
      } else {
        today.push(item);
      }
    });

    // Sort each category
    today.sort((a, b) => new Date(a.startTime).getTime() - new Date(b.startTime).getTime());
    upcoming.sort((a, b) => new Date(a.startTime).getTime() - new Date(b.startTime).getTime());
    completed.sort((a, b) => new Date(b.startTime).getTime() - new Date(a.startTime).getTime());

    return NextResponse.json({
      driver,
      today,
      upcoming,
      completed,
    });
  } catch (error) {
    console.error('Error fetching driver schedule:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { requireAdmin } from '@/lib/auth';

export const dynamic = 'force-dynamic';

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const authResult = await requireAdmin(request);
    if (authResult instanceof NextResponse) {
      return authResult;
    }
    const user = authResult;

    const { reason } = await request.json();
    const { id: driverId } = await params;

    if (!reason) {
      return NextResponse.json(
        { error: 'Suspension reason is required' },
        { status: 400 }
      );
    }

    // Get driver with current status
    const driver = await prisma.driver.findUnique({
      where: { id: driverId },
      include: {
        User: {
          select: {
            id: true,
            name: true,
            email: true,
          },
        },
      },
    });

    if (!driver) {
      return NextResponse.json({ error: 'Driver not found' }, { status: 404 });
    }

    if (driver.status === 'suspended') {
      return NextResponse.json(
        { error: 'Driver is already suspended' },
        { status: 400 }
      );
    }

    // Update driver status
    await prisma.driver.update({
      where: { id: driverId },
      data: {
        status: 'suspended',
      },
    });

    // Create audit log
    await prisma.auditLog.create({
      data: {
        actorId: user.id,
        actorRole: 'admin',
        action: 'driver_suspended',
        targetType: 'Driver',
        targetId: driverId,
        after: {
          previousStatus: driver.status,
          newStatus: 'suspended',
          reason: reason,
          suspendedBy: user.email,
          suspendedAt: new Date().toISOString(),
        },
        ip:
          request.headers.get('x-forwarded-for') ||
          request.headers.get('x-real-ip') ||
          'unknown',
        userAgent: request.headers.get('user-agent') || 'unknown',
      },
    });

    // Send notification to driver (if notification system is implemented)
    // await sendDriverNotification(driver.userId, 'account_suspended', {
    //   driverName: driver.user.name,
    //   reason: reason,
    //   suspendedAt: new Date().toISOString(),
    // });

    return NextResponse.json({
      success: true,
      message: 'Driver suspended successfully',
      driver: {
        id: driver.id,
        name: driver.User.name,
        email: driver.User.email,
        status: 'suspended',
        suspendedAt: new Date().toISOString(),
        reason: reason,
      },
    });
  } catch (error) {
    console.error('Driver suspension error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

