          status: app.drivingLicenseFrontImage ? 'complete' : 'incomplete',
          url: app.drivingLicenseFrontImage,
        },
        id: {
          status: app.drivingLicenseBackImage ? 'complete' : 'incomplete',
          url: app.drivingLicenseBackImage,
        },
      };

      // Check for compliance issues and warnings
      const complianceIssues = [];
      const complianceWarnings = [];

      if (!app.drivingLicenseFrontImage) {
        complianceIssues.push('License front image missing');
      }

      if (!app.drivingLicenseBackImage) {
        complianceIssues.push('License back image missing');
      }

      if (!app.drivingLicenseNumber) {
        complianceWarnings.push('Driving license number missing');
      }

      if (!app.bankName || !app.accountNumber) {
        complianceWarnings.push('Bank account information missing');
      }

      // Auto-approve eligibility with stricter criteria
      const autoApproveEligible =
        score >= 90 &&
        Object.values(documentStatus)
          .filter(doc => doc.status !== 'not_required')
          .every(doc => doc.status === 'complete') &&
        complianceIssues.length === 0 &&
        complianceWarnings.length === 0;

      // Calculate application age
      const applicationAge = Math.floor(
        (Date.now() - app.applicationDate.getTime()) / (1000 * 60 * 60 * 24)
      );

      return {
        id: app.id,
        name: `${app.firstName} ${app.lastName}`,
        email: app.email,
        phone: app.phone,
        score: Math.min(100, score),
        maxScore,
        scorePercentage: Math.round((score / maxScore) * 100),
        status: app.status,
        documents: documentStatus,

        // Address information
        address: `${app.addressLine1}${app.addressLine2 ? ', ' + app.addressLine2 : ''}, ${app.city}, ${app.postcode}`,
        postcode: app.postcode,

        // Additional information
        bankName: app.bankName,
        accountHolderName: app.accountHolderName,
        sortCode: app.sortCode,
        accountNumber: app.accountNumber,
        nationalInsuranceNumber: app.nationalInsuranceNumber,
        drivingLicenseNumber: app.drivingLicenseNumber,

        // Vehicle information (placeholder for future enhancement)
        vehicle: {
          type: 'Not specified',
          make: 'Not specified',
          model: 'Not specified',
          year: 'Not specified',
          reg: 'Not specified',
        },
        experience: '0 years',
        rating: 0,

        // Application metadata
        appliedAt: app.applicationDate.toISOString(),
        applicationAge,
        basePostcode: app.postcode,
        rightToWorkType: 'Not specified',

        // Compliance information
        complianceIssues,
        complianceWarnings,
        autoApproveEligible,

        // Approval tracking fields
        approvedAt:
          app.reviewedAt && app.status === 'approved'
            ? app.reviewedAt.toISOString()
            : undefined,
        approvedBy:
          app.reviewedBy && app.status === 'approved'
            ? app.reviewedBy
            : undefined,
        reviewedAt: app.reviewedAt ? app.reviewedAt.toISOString() : undefined,
        reviewedBy: app.reviewedBy,

        // User relationship
        userId: app.userId,
        user: app.User,
      };
    });

    return NextResponse.json({
      applications: transformedApplications,
      pagination: {
        page,
        limit,
        total: totalCount,
        pages: Math.ceil(totalCount / limit),
      },
    });
  } catch (error) {
    console.error('Admin driver applications GET error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';

export const dynamic = 'force-dynamic';

export async function GET(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    
    if (!session?.user || (session.user as any).role !== 'admin') {
      return NextResponse.json(
        { error: 'Unauthorized - Admin access required' },
        { status: 401 }
      );
    }

    const { searchParams } = new URL(request.url);
    const location = searchParams.get('location'); // Optional: filter by location
    const limit = parseInt(searchParams.get('limit') || '50');

    console.log('🚗 Admin fetching available drivers:', { location, limit });

    // First, let's check how many drivers we have in total
    const totalDriversCount = await prisma.driver.count({
      where: {
        status: 'active',
        onboardingStatus: 'approved',
      }
    });
    
    const driversWithAvailability = await prisma.driver.count({
      where: {
        status: 'active',
        onboardingStatus: 'approved',
        DriverAvailability: { isNot: null }
      }
    });

    console.log('📊 Driver statistics:', {
      totalActive: totalDriversCount,
      withAvailabilityRecord: driversWithAvailability,
      missingAvailability: totalDriversCount - driversWithAvailability
    });

    // Get active drivers who are available for new assignments
    const availableDrivers = await prisma.driver.findMany({
      where: {
        status: 'active',
        onboardingStatus: 'approved',
        // Removed strict availability requirements - include all approved active drivers
        // The availability status will be checked in the response data
      },
      include: {
        User: {
          select: {
            name: true,
            email: true,
            // phone removed - not in schema
          }
        },
        DriverAvailability: {
          select: {
            lastLat: true,
            lastLng: true,
            lastSeenAt: true,
            status: true,
          }
        },
        Assignment: {
          where: {
            status: {
              in: ['accepted', 'claimed']
            }
          },
          include: {
            Booking: {
              select: {
                reference: true,
                customerName: true,
                pickupAddress: {
                  select: {
                    label: true,
                    postcode: true
                  }
                }
              }
            }
          }
        }
      },
      orderBy: [
        { rating: 'desc' },
        { createdAt: 'asc' }
      ],
      take: limit,
    });

    // Transform the data for frontend
    const transformedDrivers = availableDrivers.map(driver => {
      const activeJobs = driver.Assignment.filter(assignment => 
        assignment.status === 'accepted' || assignment.status === 'claimed'
      );

      // Determine availability based on multiple factors
      const hasAvailabilityRecord = !!driver.DriverAvailability;
      const isOnline = driver.DriverAvailability?.status === 'online';
      const hasNoActiveJobs = activeJobs.length === 0;
      const isRecentlyActive = driver.DriverAvailability?.lastSeenAt 
        ? new Date(driver.DriverAvailability.lastSeenAt).getTime() > Date.now() - (24 * 60 * 60 * 1000) // Within 24 hours
        : false;

      // Driver is available if:
      // 1. No active jobs AND (online OR recently active OR no availability record yet)
      const isAvailableForAssignment = hasNoActiveJobs && (isOnline || isRecentlyActive || !hasAvailabilityRecord);

      return {
        id: driver.id,
        name: driver.User.name || `Driver ${driver.id.slice(-4)}`,
        email: driver.User.email,
        // phone removed - not in schema
        status: driver.status,
        onboardingStatus: driver.onboardingStatus,
        DriverAvailability: {
          status: driver.DriverAvailability?.status || 'unknown',
          lastSeenAt: driver.DriverAvailability?.lastSeenAt,
          location: driver.DriverAvailability?.lastLat && driver.DriverAvailability?.lastLng ? {
            lat: driver.DriverAvailability.lastLat,
            lng: driver.DriverAvailability.lastLng,
          } : null,
          hasRecord: hasAvailabilityRecord,
        },
        activeJobs: activeJobs.map(assignment => ({
          id: assignment.id,
          status: assignment.status,
          claimedAt: assignment.claimedAt,
          booking: {
            reference: assignment.Booking.reference,
            customerName: assignment.Booking.customerName,
            pickupAddress: assignment.Booking.pickupAddress?.label,
            postcode: assignment.Booking.pickupAddress?.postcode,
          }
        })),
        isAvailable: isAvailableForAssignment,
        totalActiveJobs: activeJobs.length,
        availabilityReason: isAvailableForAssignment 
          ? (isOnline ? 'Online' : isRecentlyActive ? 'Recently Active' : 'Ready for Assignment')
          : activeJobs.length > 0 ? `${activeJobs.length} Active Job${activeJobs.length > 1 ? 's' : ''}` : 'Offline',
      };
    });

    // Sort by availability (available drivers first, then by rating)
    const sortedDrivers = transformedDrivers.sort((a, b) => {
      if (a.isAvailable && !b.isAvailable) return -1;
      if (!a.isAvailable && b.isAvailable) return 1;
      return new Date(b.DriverAvailability.lastSeenAt || 0).getTime() - new Date(a.DriverAvailability.lastSeenAt || 0).getTime();
    });

    console.log('✅ Available drivers summary:', {
      totalDrivers: sortedDrivers.length,
      availableCount: sortedDrivers.filter(d => d.isAvailable).length,
      busyCount: sortedDrivers.filter(d => !d.isAvailable).length,
      onlineCount: sortedDrivers.filter(d => d.DriverAvailability.status === 'online').length,
      unknownStatusCount: sortedDrivers.filter(d => d.DriverAvailability.status === 'unknown').length,
      sampleDrivers: sortedDrivers.slice(0, 3).map(d => ({
        name: d.name,
        isAvailable: d.isAvailable,
        status: d.DriverAvailability.status,
        activeJobs: d.totalActiveJobs,
        reason: d.availabilityReason
      }))
    });

    return NextResponse.json({
      success: true,
      data: {
        drivers: sortedDrivers,
        total: sortedDrivers.length,
        available: sortedDrivers.filter(d => d.isAvailable).length,
        busy: sortedDrivers.filter(d => !d.isAvailable).length,
        online: sortedDrivers.filter(d => d.DriverAvailability.status === 'online').length,
        summary: {
          totalActive: sortedDrivers.length,
          readyForAssignment: sortedDrivers.filter(d => d.isAvailable).length,
          currentlyBusy: sortedDrivers.filter(d => !d.isAvailable).length,
        }
      }
    });

  } catch (error) {
    console.error('❌ Error fetching available drivers:', error);
    return NextResponse.json(
      {
        error: 'Failed to fetch available drivers',
        details: error instanceof Error ? error.message : 'Unknown error',
      },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';

export const dynamic = 'force-dynamic';

export async function PATCH(request: NextRequest) {
  try {
    // Check admin authentication
    const session = await getServerSession(authOptions);
    if (!session?.user || (session.user as any).role !== 'admin') {
      return NextResponse.json(
        { error: 'Unauthorized - Admin access required' },
        { status: 401 }
      );
    }

    const { searchParams } = new URL(request.url);
    const earningId = searchParams.get('id');

    if (!earningId) {
      return NextResponse.json({ error: 'Earning ID is required' }, { status: 400 });
    }

    const body = await request.json();
    const { adjustedAmountGBP, adminNotes } = body;

    if (!adjustedAmountGBP || typeof adjustedAmountGBP !== 'number') {
      return NextResponse.json({ error: 'Valid adjusted amount is required' }, { status: 400 });
    }

    // FIXED: Get current earning record with all needed fields (Audit Trail)
    const currentEarning = await prisma.driverEarnings.findUnique({
      where: { id: earningId },
      select: { 
        netAmountPence: true, 
        driverId: true,
        Driver: true 
      },
    });

    if (!currentEarning) {
      return NextResponse.json(
        { error: 'Earning record not found' },
        { status: 404 }
      );
    }
    
    const oldValuePence = currentEarning.netAmountPence;
    const newValuePence = Math.round(adjustedAmountGBP * 100);
    
    // Update the earning with admin adjustment
    const updatedEarning = await prisma.driverEarnings.update({
      where: { id: earningId },
      data: {
        netAmountPence: newValuePence,
      },
    });
    
    // FIXED: Create audit log entry
    await prisma.auditLog.create({
      data: {
        actorId: (session.user as any).id,
        actorRole: 'admin',
        action: 'earnings_adjusted',
        targetType: 'DriverEarnings',
        targetId: earningId,
        before: { 
          netAmountPence: oldValuePence,
          netAmountGBP: (oldValuePence / 100).toFixed(2)
        },
        after: { 
          netAmountPence: newValuePence,
          netAmountGBP: (newValuePence / 100).toFixed(2)
        },
        details: { 
          reason: body.adminNotes || 'No reason provided',
          difference: newValuePence - oldValuePence,
          driverId: currentEarning.driverId,
        },
      },
    });

    return NextResponse.json({
      success: true,
      data: {
        ...updatedEarning,
        adjustedAmountGBP: (updatedEarning.netAmountPence / 100).toFixed(2),
      },
      message: 'Driver earnings adjusted successfully by admin'
    });

  } catch (error) {
    console.error('Error adjusting driver earnings:', error);
    return NextResponse.json(
      {
        success: false,
        error: error instanceof Error ? error.message : 'Internal server error'
      },
      { status: 500 }
    );
  }
}

export async function GET(request: NextRequest) {
  try {
    // Check admin authentication
    const session = await getServerSession(authOptions);
    if (!session?.user || (session.user as any).role !== 'admin') {
      return NextResponse.json(
        { error: 'Unauthorized - Admin access required' },
        { status: 401 }
      );
    }

    const { searchParams } = new URL(request.url);
    const period = searchParams.get('period') || 'today'; // today, week, month
    const driverId = searchParams.get('driverId'); // Optional: filter by specific driver

    // Calculate date range based on period
    const now = new Date();
    let startDate: Date;
    let endDate: Date = now;

    switch (period) {
      case 'today':
        startDate = new Date(now.getFullYear(), now.getMonth(), now.getDate());
        break;
      case 'week':
        const startOfWeek = new Date(now);
        startOfWeek.setDate(now.getDate() - now.getDay());
        startOfWeek.setHours(0, 0, 0, 0);
        startDate = startOfWeek;
        break;
      case 'month':
        startDate = new Date(now.getFullYear(), now.getMonth(), 1);
        break;
      default:
        startDate = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    }

    // Build where clause
    const whereClause: any = {
      calculatedAt: {
        gte: startDate,
        lte: endDate,
      },
    };

    if (driverId) {
      whereClause.driverId = driverId;
    }

    // Get driver earnings with driver and assignment details
    const earnings = await prisma.driverEarnings.findMany({
      where: whereClause,
      include: {
        Assignment: {
          include: {
            Booking: {
              select: {
                id: true,
                reference: true,
                customerName: true,
                totalGBP: true,
                scheduledAt: true,
              },
            },
          },
        },
        Driver: {
          include: {
            User: {
              select: {
                name: true,
                email: true,
              },
            },
          },
        },
      },
      orderBy: {
        calculatedAt: 'desc',
      },
    });

    // Calculate summary statistics
    const totalEarnings = earnings.reduce((sum, earning) => sum + earning.netAmountPence, 0);
    const totalJobs = earnings.length;
    const totalPlatformFees = earnings.reduce((sum, earning) => sum + earning.feeAmountPence, 0);

    // Group by driver for driver-specific stats
    const driverStats = earnings.reduce((acc, earning) => {
      const driverId = earning.driverId;
      const driverName = earning.Driver.User.name || 'Unknown Driver';
      
      if (!acc[driverId]) {
        acc[driverId] = {
          driverId,
          driverName,
          driverEmail: earning.Driver.User.email,
          totalEarnings: 0,
          totalJobs: 0,
          jobs: [],
        };
      }
      
      acc[driverId].totalEarnings += earning.netAmountPence;
      acc[driverId].totalJobs += 1;
      acc[driverId].jobs.push({
        assignmentId: earning.assignmentId,
        bookingReference: earning.assignmentId ? earning.Assignment.Booking.reference : 'Bonus Payment',
        customerName: earning.assignmentId ? earning.Assignment.Booking.customerName : 'Admin Bonus',
        earnings: earning.netAmountPence,
        bonusAmount: (earning as any).bonusAmountPence || 0,
        bonusType: (earning as any).bonusType || null,
        bonusReason: (earning as any).bonusReason || null,
        isBonus: !(earning as any).assignmentId,
        calculatedAt: earning.calculatedAt,
        paidOut: earning.paidOut,
      });
      
      return acc;
    }, {} as Record<string, any>);

    // Convert pence to pounds for display
    const formatCurrency = (pence: number) => (pence / 100).toFixed(2);

    const response = {
      success: true,
      data: {
        period,
        dateRange: {
          start: startDate.toISOString(),
          end: endDate.toISOString(),
        },
        summary: {
          totalEarnings: formatCurrency(totalEarnings),
          totalJobs,
          totalPlatformFees: formatCurrency(totalPlatformFees),
          averageEarningsPerJob: totalJobs > 0 ? formatCurrency(totalEarnings / totalJobs) : '0.00',
        },
        driverStats: Object.values(driverStats).map((driver: any) => ({
          ...driver,
          totalEarnings: formatCurrency(driver.totalEarnings),
          jobs: driver.jobs.map((job: any) => ({
            ...job,
            earnings: formatCurrency(job.earnings),
          })),
        })),
        rawEarnings: earnings.map(earning => ({
          id: earning.id,
          driverId: earning.driverId,
          driverName: earning.Driver.User.name,
          assignmentId: earning.assignmentId,
          bookingReference: earning.Assignment.Booking.reference,
          customerName: earning.Assignment.Booking.customerName,
          baseAmount: formatCurrency(earning.baseAmountPence),
          surgeAmount: formatCurrency(earning.surgeAmountPence),
          tipAmount: formatCurrency(earning.tipAmountPence),
          feeAmount: formatCurrency(earning.feeAmountPence),
          netAmount: formatCurrency(earning.netAmountPence),
          currency: earning.currency,
          calculatedAt: earning.calculatedAt,
          paidOut: earning.paidOut,
        })),
      },
    };

    console.log(`📊 Admin earnings report generated for ${period}:`, {
      totalEarnings: response.data.summary.totalEarnings,
      totalJobs: response.data.summary.totalJobs,
      driversCount: Object.keys(driverStats).length,
    });

    return NextResponse.json(response);

  } catch (error) {
    console.error('❌ Error fetching driver earnings:', error);
    return NextResponse.json(
      {
        error: 'Failed to fetch driver earnings',
        details: error instanceof Error ? error.message : 'Unknown error',
      },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';

export const dynamic = 'force-dynamic';

// POST /api/admin/drivers/fix-availability - Fix missing availability records
export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    
    if (!session?.user || (session.user as any).role !== 'admin') {
      return NextResponse.json(
        { error: 'Unauthorized - Admin access required' },
        { status: 401 }
      );
    }

    console.log('🔧 Starting availability records fix...');

    // Find all drivers without availability records
    const driversWithoutAvailability = await prisma.driver.findMany({
      where: {
        status: 'active',
        onboardingStatus: 'approved',
        DriverAvailability: null, // No availability record
      },
      select: {
        id: true,
        User: {
          select: {
            name: true,
            email: true,
          }
        }
      }
    });

    console.log(`📋 Found ${driversWithoutAvailability.length} drivers without availability records`);

    if (driversWithoutAvailability.length === 0) {
      return NextResponse.json({
        success: true,
        message: 'All drivers already have availability records',
        driversProcessed: 0,
        driversFixed: 0,
      });
    }

    // Create availability records for drivers without them
    const createdRecords = [];
    
    for (const driver of driversWithoutAvailability) {
      try {
        await prisma.driverAvailability.create({
          data: {
            driverId: driver.id,
            status: 'online', // Default to online so they appear in available lists
            locationConsent: true, // Set to true so they appear in assignment lists
            createdAt: new Date(),
            updatedAt: new Date(),
          },
        });

        createdRecords.push({
          driverId: driver.id,
          driverName: driver.User.name,
          driverEmail: driver.User.email,
          status: 'created'
        });

        console.log(`✅ Created availability record for driver ${driver.User.name} (${driver.id})`);
      } catch (error) {
        console.error(`❌ Failed to create availability for driver ${driver.id}:`, error);
        createdRecords.push({
          driverId: driver.id,
          driverName: driver.User.name,
          driverEmail: driver.User.email,
          status: 'failed',
          error: error instanceof Error ? error.message : 'Unknown error'
        });
      }
    }

    const successCount = createdRecords.filter(r => r.status === 'created').length;
    const failCount = createdRecords.filter(r => r.status === 'failed').length;

    console.log(`🎯 Availability fix completed: ${successCount} created, ${failCount} failed`);

    return NextResponse.json({
      success: true,
      message: `Fixed availability records for ${successCount} drivers`,
      driversProcessed: driversWithoutAvailability.length,
      driversFixed: successCount,
      driversFailed: failCount,
      results: createdRecords,
      summary: {
        totalDriversFound: driversWithoutAvailability.length,
        recordsCreated: successCount,
        recordsFailed: failCount,
      }
    });

  } catch (error) {
    console.error('❌ Error fixing driver availability:', error);
    return NextResponse.json(
      { 
        error: 'Failed to fix driver availability records',
        details: error instanceof Error ? error.message : 'Unknown error'
      },
      { status: 500 }
    );
  }
}

// GET /api/admin/drivers/fix-availability - Check which drivers need availability fixes
export async function GET(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    
    if (!session?.user || (session.user as any).role !== 'admin') {
