import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { requireAdmin } from '@/lib/auth';

export const dynamic = 'force-dynamic';

export async function GET(request: NextRequest) {
  try {
    const authResult = await requireAdmin(request);
    if (authResult instanceof NextResponse) {
      return authResult;
    }
    const user = authResult;
    const { searchParams } = new URL(request.url);
    const status = searchParams.get('status');
    const search = searchParams.get('search');
    const page = parseInt(searchParams.get('page') || '1');
    const limit = parseInt(searchParams.get('limit') || '50');
    const offset = (page - 1) * limit;

    // Build where clause
    const where: any = {};

    if (status && status !== 'all') {
      where.status = status;
    }

    if (search) {
      where.OR = [
        { User: { name: { contains: search, mode: 'insensitive' } } },
        { User: { email: { contains: search, mode: 'insensitive' } } },
      ];
    }

    // Get drivers with all related data
    const drivers = await prisma.driver.findMany({
      where,
      include: {
        User: {
          select: {
            id: true,
            name: true,
            email: true,
            createdAt: true,
          },
        },
        DriverProfile: {
          select: {
            phone: true,
            address: true,
            dob: true,
          },
        },
        DriverVehicle: {
          select: {
            id: true,
            make: true,
            model: true,
            reg: true,
            weightClass: true,
            motExpiry: true,
          },
        },
        DriverChecks: {
          select: {
            rtwMethod: true,
            rtwExpiresAt: true,
            licenceCategories: true,
            points: true,
            licenceExpiry: true,
            dbsType: true,
            dbsCheckedAt: true,
            insurancePolicyNo: true,
            insurer: true,
            policyEnd: true,
          },
        },
        DriverRating: {
          select: {
            rating: true,
            createdAt: true,
          },
          orderBy: { createdAt: 'desc' },
          take: 10,
        },
        Booking: {
          select: {
            id: true,
            status: true,
            totalGBP: true,
            createdAt: true,
            updatedAt: true,
          },
          orderBy: { createdAt: 'desc' },
          take: 100,
        },
        DriverAvailability: {
          select: {
            status: true,
            lastSeenAt: true,
            lastLat: true,
            lastLng: true,
          },
        },
        DriverPerformance: {
          select: {
            acceptanceRate: true,
            completionRate: true,
            onTimeRate: true,
            averageRating: true,
            totalJobs: true,
            completedJobs: true,
            lateJobs: true,
            totalRatings: true,
          },
        },
        DriverIncident: {
          select: {
            id: true,
            type: true,
            severity: true,
            description: true,
            createdAt: true,
            status: true,
          },
          orderBy: { createdAt: 'desc' },
          take: 5,
        },
      },
      orderBy: { createdAt: 'desc' },
      skip: offset,
      take: limit,
    });

    // Transform data and calculate metrics
    const transformedDrivers = drivers.map(driver => {
      // Calculate average rating
      const avgRating =
        driver.DriverRating?.length > 0
          ? driver.DriverRating.reduce((sum: number, r: any) => sum + r.rating, 0) /
            driver.DriverRating.length
          : 0;

      // Calculate job metrics
      const totalJobs = driver.Booking?.length || 0;
      const completedJobs =
        driver.Booking?.filter(b => b.status === 'COMPLETED').length || 0;
      const onTimeJobs =
        driver.Booking?.filter(b => b.status === 'COMPLETED').length || 0; // Simplified - no completedAt field
      const totalEarnings =
        driver.Booking?.reduce((sum, b) => {
          const value = Number(b.totalGBP || 0);
          return (Number.isFinite(value) && value >= 0 && value <= Number.MAX_SAFE_INTEGER) ? sum + value : sum;
        }, 0) || 0;

      // Calculate performance metrics
      const acceptanceRate =
        totalJobs > 0 ? Math.round((completedJobs / totalJobs) * 100) : 0;
      const completionRate =
        totalJobs > 0 ? Math.round((completedJobs / totalJobs) * 100) : 0;
      const onTimeRate =
        completedJobs > 0 ? Math.round((onTimeJobs / completedJobs) * 100) : 0;

      // Check for compliance issues
      const complianceIssues = [];

      if (
        driver.DriverChecks?.licenceExpiry &&
        new Date(driver.DriverChecks.licenceExpiry) < new Date()
      ) {
        complianceIssues.push('License expired');
      }

      if (
        driver.DriverChecks?.rtwExpiresAt &&
        new Date(driver.DriverChecks.rtwExpiresAt) < new Date()
      ) {
        complianceIssues.push('Right to work expired');
      }

      if (
        driver.DriverChecks?.policyEnd &&
        new Date(driver.DriverChecks.policyEnd) < new Date()
      ) {
        complianceIssues.push('Insurance expired');
      }

      if (
        driver.DriverVehicle[0]?.motExpiry &&
        new Date(driver.DriverVehicle[0].motExpiry) < new Date()
      ) {
        complianceIssues.push('MOT expired');
      }

      if (driver.DriverChecks?.points && driver.DriverChecks.points > 6) {
        complianceIssues.push('Too many license points');
      }

      // Document expiries
      const documentExpiries = {
        license: driver.DriverChecks?.licenceExpiry?.toISOString() || null,
        insurance: driver.DriverChecks?.policyEnd?.toISOString() || null,
        mot: driver.DriverVehicle[0]?.motExpiry?.toISOString() || null,
        rtw: driver.DriverChecks?.rtwExpiresAt?.toISOString() || null,
      };

      return {
        id: driver.id,
        name: driver.User.name || 'Unknown',
        email: driver.User.email,
        phone: driver.DriverProfile?.phone || 'Not provided',
        onboardingStatus: driver.onboardingStatus,
        status: driver.status,
        approvedAt: driver.approvedAt?.toISOString() || null,
        createdAt: driver.User.createdAt.toISOString(),
        updatedAt: driver.updatedAt.toISOString(),
        basePostcode: driver.basePostcode || 'Not provided',
        vehicleType: driver.vehicleType || 'Unknown',
        rating: avgRating,
        totalJobs,
        completedJobs,
        onTimeJobs,
        totalEarnings,
        DriverAvailability: driver.DriverAvailability?.status || 'offline',
        lastSeen: driver.DriverAvailability?.lastSeenAt?.toISOString() || null,
        complianceIssues,
        documentExpiries,
        kpis: {
          acceptanceRate,
          completionRate,
          onTimeRate,
          avgRating,
        },
        incidents: driver.DriverIncident.map(incident => ({
          id: incident.id,
          type: incident.type,
          severity: incident.severity,
          description: incident.description,
          createdAt: incident.createdAt.toISOString(),
          resolved: incident.status === 'resolved',
        })),
        DriverPerformance: driver.DriverPerformance || {
          acceptanceRate,
          completionRate,
          onTimeRate,
          averageRating: avgRating,
          totalJobs,
          completedJobs,
          lateJobs: 0,
          totalRatings: driver.DriverRating?.length || 0,
        },
      };
    });

    // Get total count for pagination
    const total = await prisma.driver.count({ where });

    return NextResponse.json({
      drivers: transformedDrivers,
      pagination: {
        page,
        limit,
        total,
        pages: Math.ceil(total / limit),
      },
    });
  } catch (error) {
    console.error('Admin drivers GET error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';

export const dynamic = 'force-dynamic';

interface DriverJob {
  id: string;
  reference: string;
  scheduledAt: string;
  status: string;
  customerName: string;
  customerPhone: string;
  pickupAddress: string;
  dropoffAddress: string;
  items: any[];
  totalValue: number;
  duration: number;
  priority: string;
  type: string;
}

interface DeclinedJob {
  id: string;
  reference: string;
  scheduledAt: string;
  declinedAt: string;
  customerName: string;
  customerPhone: string;
  pickupAddress: string;
  dropoffAddress: string;
  items: any[];
  totalValue: number;
  duration: number;
  priority: string;
  reason: string;
}

export async function GET(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user?.id) {
      return NextResponse.json(
        { error: 'Unauthorized' },
        { status: 401 }
      );
    }

    const userRole = (session.user as any)?.role;
    if (userRole !== 'admin') {
      return NextResponse.json(
        { error: 'Forbidden - Admin access required' },
        { status: 403 }
      );
    }

    const { searchParams } = new URL(request.url);
    const selectedDate = searchParams.get('date') || new Date().toISOString().split('T')[0];
    const selectedDriver = searchParams.get('driver') || 'all';

    // Parse the selected date
    const dateFilter = new Date(selectedDate);
    const startOfDay = new Date(dateFilter);
    startOfDay.setHours(0, 0, 0, 0);
    const endOfDay = new Date(dateFilter);
    endOfDay.setHours(23, 59, 59, 999);

    // Build where clause for driver filter
    const driverWhere = selectedDriver !== 'all'
      ? { driverId: selectedDriver }
      : {};

    // Get all assignments for the selected date with driver information
    const assignments = await prisma.assignment.findMany({
      where: {
        Booking: {
          scheduledAt: {
            gte: startOfDay,
            lte: endOfDay,
          },
        },
        ...(selectedDriver !== 'all' && { driverId: selectedDriver }),
      },
      include: {
        Driver: {
          include: {
            User: {
              select: {
                name: true,
                email: true,
              },
            },
          },
        },
        Booking: {
          select: {
            id: true,
            reference: true,
            scheduledAt: true,
            status: true,
            customerName: true,
            customerPhone: true,
            pickupAddress: {
              select: {
                label: true,
              },
            },
            dropoffAddress: {
              select: {
                label: true,
              },
            },
            BookingItem: {
              select: {
                name: true,
                quantity: true,
              },
            },
            totalGBP: true,
            estimatedDurationMinutes: true,
            urgency: true,
          },
        },
      },
    });

    // Get declined assignments for the selected date
    const declinedAssignments = await prisma.assignment.findMany({
      where: {
        status: 'declined',
        Booking: {
          scheduledAt: {
            gte: startOfDay,
            lte: endOfDay,
          },
        },
        ...(selectedDriver !== 'all' && { driverId: selectedDriver }),
      },
      include: {
        Driver: {
          include: {
            User: {
              select: {
                name: true,
                email: true,
              },
            },
          },
        },
        Booking: {
          select: {
            id: true,
            reference: true,
            scheduledAt: true,
            customerName: true,
            customerPhone: true,
            pickupAddress: {
              select: {
                label: true,
              },
            },
            dropoffAddress: {
              select: {
                label: true,
              },
            },
            BookingItem: {
              select: {
                name: true,
                quantity: true,
              },
            },
            totalGBP: true,
            estimatedDurationMinutes: true,
            urgency: true,
          },
        },
      },
      orderBy: {
        createdAt: 'desc',
      },
    });

    // Calculate acceptance rates for each driver
    const driverStats = new Map();

    // Process accepted assignments
    assignments.forEach(assignment => {
      const driverId = assignment.driverId;
      if (!driverStats.has(driverId)) {
        driverStats.set(driverId, {
          driverId,
          driverName: assignment.Driver?.User?.name || 'Driver',
          driverEmail: assignment.Driver?.User?.email || '',
          totalAssignments: 0,
          acceptedAssignments: 0,
          declinedAssignments: 0,
        });
      }
      const stats = driverStats.get(driverId);
      stats.totalAssignments++;
      stats.acceptedAssignments++;
    });

    // Process declined assignments
    declinedAssignments.forEach(assignment => {
      const driverId = assignment.driverId;
      if (!driverStats.has(driverId)) {
        driverStats.set(driverId, {
          driverId,
          driverName: assignment.Driver?.User?.name || 'Driver',
          driverEmail: assignment.Driver?.User?.email || '',
          totalAssignments: 0,
          acceptedAssignments: 0,
          declinedAssignments: 0,
        });
      }
      const stats = driverStats.get(driverId);
      stats.totalAssignments++;
      stats.declinedAssignments++;
    });

    // Group assignments by driver
    const driverMap = new Map();

    assignments.forEach(assignment => {
      const driverId = assignment.driverId;
      if (!driverMap.has(driverId)) {
        const stats = driverStats.get(driverId) || {
          driverId,
          driverName: assignment.Driver?.User?.name || 'Driver',
          driverEmail: assignment.Driver?.User?.email || '',
          totalAssignments: 0,
          acceptedAssignments: 0,
          declinedAssignments: 0,
        };

        driverMap.set(driverId, {
          driverId,
          driverName: stats.driverName,
          driverEmail: stats.driverEmail,
          jobs: [] as DriverJob[],
          declinedJobs: [] as DeclinedJob[],
          totalAssignments: stats.totalAssignments,
          acceptedAssignments: stats.acceptedAssignments,
          declinedAssignments: stats.declinedAssignments,
          acceptanceRate: stats.totalAssignments > 0 ? (stats.acceptedAssignments / stats.totalAssignments) * 100 : 100,
        });
      }

      const driver = driverMap.get(driverId);
      driver.jobs.push({
        id: assignment.bookingId,
        reference: assignment.Booking.reference,
        scheduledAt: assignment.Booking.scheduledAt.toISOString(),
        status: assignment.status.toLowerCase(),
        customerName: assignment.Booking.customerName || 'Customer',
        customerPhone: assignment.Booking.customerPhone || '',
        pickupAddress: assignment.Booking.pickupAddress?.label || 'Pickup Location',
        dropoffAddress: assignment.Booking.dropoffAddress?.label || 'Dropoff Location',
        items: assignment.Booking.BookingItem || [],
        totalValue: assignment.Booking.totalGBP || 0,
        duration: assignment.Booking.estimatedDurationMinutes || 60,
        priority: assignment.Booking.urgency || 'medium',
        type: 'single-drop' as const, // For now, assume single-drop
      });
    });

    // Add declined jobs to drivers
    declinedAssignments.forEach(assignment => {
      const driverId = assignment.driverId;
      if (driverMap.has(driverId)) {
        const driver = driverMap.get(driverId);
        driver.declinedJobs.push({
          id: assignment.bookingId,
          reference: assignment.Booking.reference,
          scheduledAt: assignment.Booking.scheduledAt.toISOString(),
          declinedAt: assignment.createdAt.toISOString(),
          customerName: assignment.Booking.customerName || 'Customer',
          customerPhone: assignment.Booking.customerPhone || '',
          pickupAddress: assignment.Booking.pickupAddress?.label || 'Pickup Location',
          dropoffAddress: assignment.Booking.dropoffAddress?.label || 'Dropoff Location',
          items: assignment.Booking.BookingItem || [],
          totalValue: assignment.Booking.totalGBP || 0,
          duration: assignment.Booking.estimatedDurationMinutes || 60,
          priority: assignment.Booking.urgency || 'medium',
          reason: 'No reason provided', // TODO: Add declinedReason to Assignment model
        });
      }
    });

    // Transform to final format
    const driverSchedules = Array.from(driverMap.values()).map(driver => {
      const completedJobs = driver.jobs.filter((job: DriverJob) => job.status === 'completed').length;
      const upcomingJobs = driver.jobs.filter((job: DriverJob) => job.status === 'confirmed' || job.status === 'in_progress').length;
      const todaysJobs = driver.jobs.length;

      return {
        ...driver,
        totalJobs: todaysJobs,
        completedJobs,
        upcomingJobs,
        todaysJobs,
        jobs: driver.jobs.sort((a: DriverJob, b: DriverJob) => new Date(a.scheduledAt).getTime() - new Date(b.scheduledAt).getTime()),
        declinedJobs: driver.declinedJobs.sort((a: DeclinedJob, b: DeclinedJob) => new Date(b.declinedAt).getTime() - new Date(a.declinedAt).getTime()),
      };
    });

    return NextResponse.json({
      success: true,
      data: driverSchedules,
    });

  } catch (error) {
    console.error('Admin driver schedule error:', error);
    return NextResponse.json(
      {
        success: false,
        error: error instanceof Error ? error.message : 'Internal server error'
      },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';

export const dynamic = 'force-dynamic';

export async function GET(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user || (session.user as any).role !== 'admin') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const { searchParams } = new URL(request.url);
    const page = parseInt(searchParams.get('page') || '1');
    const limit = parseInt(searchParams.get('limit') || '20');
    const search = searchParams.get('search') || '';
    const status = searchParams.get('status') || '';
    const driverId = searchParams.get('driverId') || '';
    const fromDate = searchParams.get('fromDate') || '';
    const toDate = searchParams.get('toDate') || '';

    const skip = (page - 1) * limit;

    // Build where clause
    const where: any = {};

    if (search) {
      where.OR = [
        { booking: { orderRef: { contains: search, mode: 'insensitive' } } },
        {
          driver: { User: { name: { contains: search, mode: 'insensitive' } } },
        },
        {
          booking: {
            customer: {
              User: { name: { contains: search, mode: 'insensitive' } },
            },
          },
        },
      ];
    }

    if (status) {
      where.booking = { ...where.booking, status };
    }

    if (driverId) {
      where.driverId = driverId;
    }

    if (fromDate || toDate) {
      where.booking = {
        ...where.booking,
        scheduledAt: {},
      };
      if (fromDate) where.booking.scheduledAt.gte = new Date(fromDate);
      if (toDate) where.booking.scheduledAt.lte = new Date(toDate);
    }

    // Get earnings with detailed breakdown
    const [earnings, total] = await Promise.all([
      prisma.driverEarnings.findMany({
        where,
        include: {
          Driver: {
            include: {
              User: {
                select: {
                  id: true,
                  name: true,
                  email: true,
                  role: true,
                  createdAt: true,
                  isActive: true
                }
              },
            },
          },
        },
        orderBy: {
          calculatedAt: 'desc',
        },
        skip,
        take: limit,
      }),
      prisma.driverEarnings.count({ where }),
    ]);

    // Get summary statistics
    const summary = await prisma.driverEarnings.aggregate({
      _sum: {
        baseAmountPence: true,
        surgeAmountPence: true,
        tipAmountPence: true,
        feeAmountPence: true,
        netAmountPence: true,
      },
      where: {
        calculatedAt: {
          gte: new Date(Date.now() - 30 * 24 * 60 * 60 * 1000), // Last 30 days
        },
      },
    });

    // Get revenue breakdown
    const revenueBreakdown = await prisma.booking.aggregate({
      _sum: {
        totalGBP: true,
      },
      _count: {
        id: true,
      },
      where: {
        status: 'COMPLETED',
        paidAt: {
          gte: new Date(Date.now() - 30 * 24 * 60 * 60 * 1000), // Last 30 days
        },
      },
    });

    // Get driver earnings breakdown
    const driverBreakdown = await prisma.driverEarnings.groupBy({
      by: ['driverId'],
      _sum: {
        baseAmountPence: true,
        surgeAmountPence: true,
        tipAmountPence: true,
        feeAmountPence: true,
        netAmountPence: true,
      },
      _count: {
        id: true,
      },
      where: {
        calculatedAt: {
          gte: new Date(Date.now() - 30 * 24 * 60 * 60 * 1000), // Last 30 days
        },
      },
      orderBy: {
        _sum: {
          netAmountPence: 'desc',
        },
      },
      take: 10,
    });

    // Get driver details for breakdown
    const driverDetails = await prisma.driver.findMany({
      where: {
        id: { in: driverBreakdown.map(d => d.driverId) },
      },
      include: {
        User: {
          select: {
            id: true,
            name: true,
            email: true,
            role: true,
            createdAt: true,
            isActive: true
          }
        },
      },
    });

    const driverBreakdownWithNames = driverBreakdown.map(driver => {
      const driverDetail = driverDetails.find(d => d.id === driver.driverId);
      return {
        driverId: driver.driverId,
        driverName: driverDetail?.User?.name || 'Unknown',
        driverEmail: driverDetail?.User?.email || 'Unknown',
        baseAmount: driver._sum.baseAmountPence || 0,
        surgeAmount: driver._sum.surgeAmountPence || 0,
        tipAmount: driver._sum.tipAmountPence || 0,
        feeAmount: driver._sum.feeAmountPence || 0,
        netAmount: driver._sum.netAmountPence || 0,
        jobCount: driver._count.id || 0,
      };
    });

    return NextResponse.json({
      ledger: earnings.map(earning => ({
        id: earning.id,
        driver: {
          id: earning.Driver.id,
          name: earning.Driver.User?.name || 'Unknown',
          email: earning.Driver.User?.email || 'Unknown',
        },
        assignmentId: earning.assignmentId,
        breakdown: {
          baseAmountPence: earning.baseAmountPence,
          surgeAmountPence: earning.surgeAmountPence,
          tipAmountPence: earning.tipAmountPence,
          feeAmountPence: earning.feeAmountPence,
          netAmountPence: earning.netAmountPence,
        },
        calculatedAt: earning.calculatedAt,
        paidOut: earning.paidOut,
      })),
      pagination: {
        page,
        limit,
        total,
        pages: Math.ceil(total / limit),
      },
      summary: {
        totalRevenue: revenueBreakdown._sum.totalGBP || 0,
        totalOrders: revenueBreakdown._count.id || 0,
        earningsBreakdown: {
          baseAmount: summary._sum.baseAmountPence || 0,
          surgeAmount: summary._sum.surgeAmountPence || 0,
          tipAmount: summary._sum.tipAmountPence || 0,
          feeAmount: summary._sum.feeAmountPence || 0,
          netAmount: summary._sum.netAmountPence || 0,
        },
        platformMargin:
          (revenueBreakdown._sum.totalGBP || 0) -
          (summary._sum.netAmountPence || 0),
        marginPercentage: revenueBreakdown._sum.totalGBP
          ? (
              ((revenueBreakdown._sum.totalGBP -
                (summary._sum.netAmountPence || 0)) /
                revenueBreakdown._sum.totalGBP) *
              100
            ).toFixed(2)
          : '0',
      },
      driverBreakdown: driverBreakdownWithNames,
    });
  } catch (error) {
    console.error('Ledger API error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
import Stripe from 'stripe';

// Force dynamic rendering (uses headers/cookies/getServerSession)
export const dynamic = 'force-dynamic';

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY!, {
  apiVersion: '2024-04-10',
});

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user || (session.user as any).role !== 'admin') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const { id: payoutId } = await params;

    // Get payout details
    const payout = await prisma.driverPayout.findUnique({
      where: { id: payoutId },
      include: {
        Driver: {
          include: {
            User: {
              select: {
                id: true,
                name: true,
                email: true,
                role: true,
                createdAt: true,
                isActive: true
              }
            },
            DriverPayoutSettings: true,
          },
        },
        DriverEarnings: {
          include: {
            Assignment: {
              include: {
                Booking: true,
              },
            },
          },
        },
      },
    });

    if (!payout) {
      return NextResponse.json({ error: 'Payout not found' }, { status: 404 });
    }

    if (payout.status !== 'pending') {
      return NextResponse.json(
        {
          error: 'Payout is not in pending status',
        },
        { status: 400 }
      );
    }

    // Check if driver has payout settings
    if (!payout.Driver?.DriverPayoutSettings) {
      return NextResponse.json(
        {
          error: 'Driver has no payout settings configured',
        },
        { status: 400 }
      );
    }

    // Process payout through Stripe (if using Stripe Connect)
    let stripeTransferId = null;
    let failureReason = null;

    try {
      if (payout.Driver?.DriverPayoutSettings?.stripeAccountId) {
        // Process through Stripe Connect
        const transfer = await stripe.transfers.create({
          amount: payout.totalAmountPence,
          currency: payout.currency,
          destination: payout.Driver.DriverPayoutSettings.stripeAccountId,
          description: `Payout for ${payout.Driver.User?.name || 'Unknown Driver'}`,
          metadata: {
            payoutId: payout.id,
            driverId: payout.driverId,
            earningsCount: payout.DriverEarnings?.length.toString() || '0',
          },
        });
        stripeTransferId = transfer.id;
      } else {
        // Manual payout processing (bank transfer, etc.)
        // This would integrate with your bank's API or manual process
        console.log(
          `Manual payout processing required for driver ${payout.Driver?.User?.name || 'Unknown Driver'}`
        );
      }
    } catch (stripeError: any) {
      console.error('Stripe transfer error:', stripeError);
      failureReason = `Stripe transfer failed: ${stripeError.message}`;

      // Update payout as failed
      await prisma.driverPayout.update({
        where: { id: payoutId },
        data: {
          status: 'failed',
          failedAt: new Date(),
          failureReason: failureReason,
        },
      });

      // Create audit log
      await prisma.auditLog.create({
        data: {
          actorId: session.user.id,
          actorRole: 'admin',
          action: 'payout_failed',
          targetType: 'driver_payout',
          targetId: payoutId,
          after: {
            previousStatus: 'pending',
            newStatus: 'failed',
            failureReason: failureReason,
            stripeTransferId: stripeTransferId,
          },
          ip:
            request.headers.get('x-forwarded-for') ||
            request.headers.get('x-real-ip') ||
            'unknown',
          userAgent: request.headers.get('user-agent') || 'unknown',
        },
      });

      return NextResponse.json(
        {
          error: failureReason,
        },
        { status: 400 }
      );
    }

    // Update payout as processed
    const updatedPayout = await prisma.driverPayout.update({
      where: { id: payoutId },
      data: {
        status: 'completed',
        processedAt: new Date(),
        stripeTransferId: stripeTransferId,
      },
    });

    // Create audit log
    await prisma.auditLog.create({
      data: {
        actorId: session.user.id,
        actorRole: 'admin',
        action: 'payout_processed',
        targetType: 'driver_payout',
        targetId: payoutId,
        after: {
          previousStatus: 'pending',
          newStatus: 'completed',
          stripeTransferId: stripeTransferId,
          processedAt: updatedPayout.processedAt,
        },
        ip:
          request.headers.get('x-forwarded-for') ||
          request.headers.get('x-real-ip') ||
          'unknown',
        userAgent: request.headers.get('user-agent') || 'unknown',
      },
    });

    // Send notification to driver
    try {
      const { notifyPayoutProcessed } = await import('@/lib/notifications');
      await notifyPayoutProcessed(payout.driverId, {
        id: payout.id,
        amount: payout.totalAmountPence,
      });
    } catch (notificationError) {
      console.error('Failed to send payout notification:', notificationError);
    }

    return NextResponse.json({
      success: true,
      payout: {
        id: updatedPayout.id,
        driverName: payout.Driver?.User?.name || 'Unknown',
        totalAmountPence: updatedPayout.totalAmountPence,
        status: updatedPayout.status,
        processedAt: updatedPayout.processedAt,
        stripeTransferId: updatedPayout.stripeTransferId,
      },
    });
  } catch (error) {
    console.error('Payout processing error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';

// Force dynamic rendering (uses headers/cookies/getServerSession)
export const dynamic = 'force-dynamic';

export async function GET(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user || (session.user as any).role !== 'admin') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const { searchParams } = new URL(request.url);
    const page = parseInt(searchParams.get('page') || '1');
    const limit = parseInt(searchParams.get('limit') || '20');
    const search = searchParams.get('search') || '';
    const status = searchParams.get('status') || '';
    const driverId = searchParams.get('driverId') || '';
    const fromDate = searchParams.get('fromDate') || '';
    const toDate = searchParams.get('toDate') || '';

    const skip = (page - 1) * limit;

    // Build where clause
    const where: any = {};

    if (search) {
      where.OR = [
        {
          driver: { user: { name: { contains: search, mode: 'insensitive' } } },
        },
        {
          driver: {
            user: { email: { contains: search, mode: 'insensitive' } },
          },
        },
      ];
    }

    if (status) {
      where.status = status;
    }

    if (driverId) {
      where.driverId = driverId;
    }

    if (fromDate || toDate) {
      where.createdAt = {};
      if (fromDate) where.createdAt.gte = new Date(fromDate);
      if (toDate) where.createdAt.lte = new Date(toDate);
    }

    // Get payouts with pagination
    const [payouts, total] = await Promise.all([
      prisma.driverPayout.findMany({
        where,
        include: {
          Driver: {
            include: {
              User: {
                select: {
                  id: true,
                  name: true,
                  email: true,
                  role: true,
                  createdAt: true,
                  isActive: true
                }
              },
            },
          },
          DriverEarnings: true,
        },
        orderBy: {
          createdAt: 'desc',
        },
        skip,
        take: limit,
      }),
      prisma.driverPayout.count({ where }),
    ]);

    // Get summary statistics
    const summary = await prisma.driverPayout.aggregate({
      _sum: {
        totalAmountPence: true,
      },
      _count: {
        id: true,
      },
      where: {
        status: {
          in: ['pending', 'processing'],
        },
      },
    });

    // Get status breakdown
    const statusBreakdown = await prisma.driverPayout.groupBy({
      by: ['status'],
      _sum: {
        totalAmountPence: true,
      },
      _count: {
        id: true,
      },
    });

    // Get earnings breakdown for the period
    const earningsBreakdown = await prisma.driverEarnings.aggregate({
      _sum: {
        baseAmountPence: true,
        surgeAmountPence: true,
        tipAmountPence: true,
        feeAmountPence: true,
        netAmountPence: true,
      },
      where: {
        paidOut: false,
        calculatedAt: {
          gte: new Date(Date.now() - 30 * 24 * 60 * 60 * 1000), // Last 30 days
        },
      },
    });

    return NextResponse.json({
      payouts: payouts.map(payout => ({
        id: payout.id,
        driver: {
          id: payout.Driver.id,
          name: payout.Driver.User.name,
          email: payout.Driver.User.email,
        },
        totalAmountPence: payout.totalAmountPence,
        currency: payout.currency,
        status: payout.status,
        processedAt: payout.processedAt,
        failedAt: payout.failedAt,
        failureReason: payout.failureReason,
        stripeTransferId: payout.stripeTransferId,
        bankAccountId: payout.bankAccountId,
        createdAt: payout.createdAt,
        earnings: payout.DriverEarnings.map(earning => ({
          id: earning.id,
          assignmentId: earning.assignmentId,
          baseAmountPence: earning.baseAmountPence,
          surgeAmountPence: earning.surgeAmountPence,
          tipAmountPence: earning.tipAmountPence,
          feeAmountPence: earning.feeAmountPence,
          netAmountPence: earning.netAmountPence,
          calculatedAt: earning.calculatedAt,
        })),
      })),
      pagination: {
        page,
        limit,
        total,
        pages: Math.ceil(total / limit),
      },
      summary: {
        pendingPayouts: summary._sum.totalAmountPence || 0,
        payoutCount: summary._count.id || 0,
        statusBreakdown: statusBreakdown.map(item => ({
          status: item.status,
          amount: item._sum.totalAmountPence || 0,
          count: item._count.id || 0,
        })),
        earningsBreakdown: {
          baseAmount: earningsBreakdown._sum.baseAmountPence || 0,
          surgeAmount: earningsBreakdown._sum.surgeAmountPence || 0,
          tipAmount: earningsBreakdown._sum.tipAmountPence || 0,
          feeAmount: earningsBreakdown._sum.feeAmountPence || 0,
          netAmount: earningsBreakdown._sum.netAmountPence || 0,
        },
      },
    });
  } catch (error) {
    console.error('Payouts API error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user || (session.user as any).role !== 'admin') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const body = await request.json();
    const { driverId, earningsIds, notes } = body;

    if (!driverId || !earningsIds || earningsIds.length === 0) {
      return NextResponse.json(
        {
          error: 'Driver ID and earnings IDs are required',
        },
        { status: 400 }
      );
    }

    // Get driver details
    const driver = await prisma.driver.findUnique({
      where: { id: driverId },
      include: {
        User: {
          select: {
            id: true,
            name: true,
            email: true,
            role: true,
            createdAt: true,
            isActive: true
          }
        },
        DriverPayoutSettings: true,
      },
    });

    if (!driver) {
      return NextResponse.json({ error: 'Driver not found' }, { status: 404 });
    }

    // Get earnings details
    const earnings = await prisma.driverEarnings.findMany({
      where: {
        id: { in: earningsIds },
        driverId: driverId,
        paidOut: false,
      },
      include: {},
    });

    if (earnings.length === 0) {
      return NextResponse.json(
        {
          error: 'No valid earnings found for payout',
        },
        { status: 400 }
      );
    }

    // Calculate total payout amount
    const totalAmountPence = earnings.reduce(
      (sum, earning) => sum + earning.netAmountPence,
      0
    );

    if (totalAmountPence <= 0) {
      return NextResponse.json(
        {
          error: 'Total payout amount must be greater than 0',
        },
        { status: 400 }
      );
    }

    // Check minimum payout amount
    const minPayoutAmount = driver.DriverPayoutSettings?.minPayoutAmountPence || 5000; // £50
    if (totalAmountPence < minPayoutAmount) {
      return NextResponse.json(
        {
          error: `Payout amount must be at least £${(minPayoutAmount / 100).toFixed(2)}`,
        },
        { status: 400 }
      );
    }

    // Create payout record
    const payout = await prisma.driverPayout.create({
      data: {
        driverId: driverId,
        totalAmountPence: totalAmountPence,
        currency: 'gbp',
        status: 'pending',
        DriverEarnings: {
          connect: earningsIds.map((id: string) => ({ id })),
        },
      },
      include: {
        Driver: {
          include: {
            User: {
              select: {
                id: true,
                name: true,
                email: true,
                role: true,
                createdAt: true,
                isActive: true
              }
            },
          },
        },
        DriverEarnings: true,
      },
    });

    // Mark earnings as paid out
    await prisma.driverEarnings.updateMany({
      where: {
        id: { in: earningsIds },
      },
      data: {
        paidOut: true,
      },
    });

    // Create audit log
    await prisma.auditLog.create({
      data: {
        actorId: session.user.id,
        actorRole: 'admin',
        action: 'payout_created',
        targetType: 'driver_payout',
        targetId: payout.id,
        after: {
          driverId: driverId,
          totalAmount: totalAmountPence,
          earningsCount: earnings.length,
          notes: notes || '',
        },
        ip:
          request.headers.get('x-forwarded-for') ||
          request.headers.get('x-real-ip') ||
          'unknown',
        userAgent: request.headers.get('user-agent') || 'unknown',
      },
    });

    return NextResponse.json({
      success: true,
      payout: {
        id: payout.id,
        driverName: payout.Driver.User.name,
        totalAmountPence: payout.totalAmountPence,
        status: payout.status,
        createdAt: payout.createdAt,
        earningsCount: payout.DriverEarnings.length,
      },
    });
  } catch (error) {
    console.error('Payout creation error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

