export async function POST(request: NextRequest) {
  const s = await getServerSession(authOptions);
  if (!s?.user || (s.user as any).role !== 'admin') {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  try {
    const body = await request.json();
    const { paymentId, amount, reason, notes } = body;

    if (!paymentId || !amount || !reason) {
      return NextResponse.json(
        { error: 'Payment ID, amount, and reason are required' },
        { status: 400 }
      );
    }

    // Get payment details
    const payment = await prisma.payment.findUnique({
      where: { id: paymentId },
      include: {
        Booking: true,
        Refund: true,
      },
    });

    if (!payment) {
      return NextResponse.json({ error: 'Payment not found' }, { status: 404 });
    }

    if (payment.status !== 'paid') {
      return NextResponse.json(
        { error: 'Payment is not in paid status' },
        { status: 400 }
      );
    }

    // Check if refund amount is valid
    const totalRefunded = payment.Refund.reduce(
      (sum, refund) => sum + refund.amount,
      0
    );
    const remainingAmount = payment.amount - totalRefunded;

    if (amount > remainingAmount) {
      return NextResponse.json(
        { error: 'Refund amount exceeds remaining payment amount' },
        { status: 400 }
      );
    }

    // Create refund
    const refund = await prisma.refund.create({
      data: {
        id: `refund_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
        paymentId: paymentId,
        amount: amount,
        reason: reason,
        status: 'pending',
        processedAt: new Date(),
        updatedAt: new Date(),
        metadata: {
          notes,
          processedBy: (s.user as any).id,
        },
      },
    });

    // Update booking status if this is a full refund
    if (amount >= remainingAmount) {
      await prisma.booking.update({
        where: { id: payment.bookingId },
        data: { status: 'CANCELLED' },
      });
    }

    return NextResponse.json({
      success: true,
      refund: {
        id: refund.id,
        paymentId: refund.paymentId,
        amount: refund.amount,
        reason: refund.reason,
        status: refund.status,
        processedAt: refund.processedAt,
      },
    });
  } catch (error) {
    console.error('Create refund API error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
import { NextResponse, NextRequest } from 'next/server';

export const dynamic = 'force-dynamic';

export async function GET(request: NextRequest) {
  const s = await getServerSession(authOptions);
  if (!s?.user || (s.user as any).role !== 'admin') {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  try {
    const { searchParams } = new URL(request.url);
    const range = searchParams.get('range') || '30d';

    // Calculate date range
    const now = new Date();
    let startDate: Date;

    switch (range) {
      case '7d':
        startDate = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
        break;
      case '30d':
        startDate = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
        break;
      case '90d':
        startDate = new Date(now.getTime() - 90 * 24 * 60 * 60 * 1000);
        break;
      default:
        startDate = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
    }

    // Get paid invoices
    const paidInvoices = await prisma.payment.aggregate({
      _sum: {
        amount: true,
      },
      _count: {
        id: true,
      },
      where: {
        status: 'paid',
        createdAt: {
          gte: startDate,
        },
      },
    });

    // Get pending invoices
    const pendingInvoices = await prisma.payment.aggregate({
      _sum: {
        amount: true,
      },
      _count: {
        id: true,
      },
      where: {
        status: 'unpaid',
        createdAt: {
          gte: startDate,
        },
      },
    });

    // Get refunds
    const refunds = await prisma.payment.aggregate({
      _sum: {
        amount: true,
      },
      _count: {
        id: true,
      },
      where: {
        status: 'refunded',
        updatedAt: {
          gte: startDate,
        },
      },
    });

    // Get driver payouts
    const payouts = await prisma.driverPayout.aggregate({
      _sum: {
        totalAmountPence: true,
      },
      _count: {
        id: true,
      },
      where: {
        status: {
          in: ['pending', 'processing'],
        },
        createdAt: {
          gte: startDate,
        },
      },
    });

    // Get earnings breakdown
    const earningsBreakdown = await prisma.driverEarnings.aggregate({
      _sum: {
        baseAmountPence: true,
        surgeAmountPence: true,
        tipAmountPence: true,
        feeAmountPence: true,
        netAmountPence: true,
      },
      where: {
        calculatedAt: {
          gte: startDate,
        },
      },
    });

    // Get recent activity
    const recentInvoices = await prisma.payment.findMany({
      where: {
        status: 'paid',
        createdAt: {
          gte: startDate,
        },
      },
      include: {
        Booking: {
          include: {
            customer: true,
          },
        },
      },
      orderBy: {
        createdAt: 'desc',
      },
      take: 5,
    });

    const recentRefunds = await prisma.payment.findMany({
      where: {
        status: 'refunded',
        updatedAt: {
          gte: startDate,
        },
      },
      include: {
        Booking: {
          include: {
            customer: true,
          },
        },
      },
      orderBy: {
        updatedAt: 'desc',
      },
      take: 5,
    });

    // Get top performing drivers
    const topDrivers = await prisma.driverEarnings.groupBy({
      by: ['driverId'],
      _sum: {
        netAmountPence: true,
      },
      _count: {
        id: true,
      },
      where: {
        calculatedAt: {
          gte: startDate,
        },
      },
      orderBy: {
        _sum: {
          netAmountPence: 'desc',
        },
      },
      take: 5,
    });

    // Get driver details for top performers
    const driverDetails = await prisma.driver.findMany({
      where: {
        id: {
          in: topDrivers.map(d => d.driverId),
        },
      },
      include: {
        User: {
          select: {
            name: true,
            email: true,
          },
        },
      },
    });

    const topDriversWithDetails = topDrivers.map(driver => {
      const details = driverDetails.find(d => d.id === driver.driverId);
      return {
        driverId: driver.driverId,
        driverName: details?.User.name || 'Unknown',
        driverEmail: details?.User.email || 'Unknown',
        totalEarnings: driver._sum.netAmountPence || 0,
        jobCount: driver._count.id || 0,
      };
    });

    return NextResponse.json({
      summary: {
        totalRevenue: paidInvoices._sum.amount || 0,
        totalInvoices: paidInvoices._count.id || 0,
        pendingRevenue: pendingInvoices._sum.amount || 0,
        pendingInvoices: pendingInvoices._count.id || 0,
        totalRefunds: refunds._sum.amount || 0,
        refundCount: refunds._count.id || 0,
        totalPayouts: payouts._sum.totalAmountPence || 0,
        payoutCount: payouts._count.id || 0,
      },
      earnings: {
        baseAmount: earningsBreakdown._sum.baseAmountPence || 0,
        surgeAmount: earningsBreakdown._sum.surgeAmountPence || 0,
        tipAmount: earningsBreakdown._sum.tipAmountPence || 0,
        feeAmount: earningsBreakdown._sum.feeAmountPence || 0,
        netAmount: earningsBreakdown._sum.netAmountPence || 0,
      },
      recentActivity: {
        invoices: recentInvoices.map(invoice => ({
          id: invoice.id,
          amount: invoice.amount,
          status: invoice.status,
          createdAt: invoice.createdAt,
          customer: invoice.Booking.customer ? {
            name: invoice.Booking.customer.name,
            email: invoice.Booking.customer.email,
          } : null,
          bookingRef: invoice.Booking.reference,
        })),
        refunds: recentRefunds.map(refund => ({
          id: refund.id,
          amount: refund.amount,
          status: refund.status,
          updatedAt: refund.updatedAt,
          customer: refund.Booking.customer ? {
            name: refund.Booking.customer.name,
            email: refund.Booking.customer.email,
          } : null,
          bookingRef: refund.Booking.reference,
        })),
      },
      topDrivers: topDriversWithDetails,
    });
  } catch (error) {
    console.error('Admin finance API error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

