import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
import { logAudit } from '@/lib/audit';
import { unifiedEmailService, type OrderCancellationData } from '@/lib/email/UnifiedEmailService';

export const dynamic = 'force-dynamic';

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ code: string }> }
) {
  try {
    // Check admin authorization
    const session = await getServerSession(authOptions);
    if (!session?.user || (session.user as any).role !== 'admin') {
      return NextResponse.json(
        { error: 'Unauthorized - Admin access required' },
        { status: 401 }
      );
    }

    const { code } = await params;
    const { reason } = await request.json();

    // Fetch booking before cancellation
    const booking = await prisma.booking.findUnique({
      where: { reference: code },
      include: {
        pickupAddress: true,
        dropoffAddress: true,
        BookingItem: true,
      },
    });

    if (!booking) {
      return NextResponse.json(
        { error: 'Order not found' },
        { status: 404 }
      );
    }

    // Check if order can be cancelled
    if (booking.status === 'CANCELLED') {
      return NextResponse.json(
        { error: 'Order is already cancelled' },
        { status: 400 }
      );
    }

    if (booking.status === 'COMPLETED') {
      return NextResponse.json(
        { error: 'Cannot cancel completed order' },
        { status: 400 }
      );
    }

    // Update booking status to CANCELLED
    const cancelledOrder = await prisma.booking.update({
      where: { reference: code },
      data: {
        status: 'CANCELLED',
        // Add cancellation fields when available in schema
      },
    });

    // Log audit trail
    await logAudit((session.user as any).id, 'cancel_order', booking.id, { targetType: 'booking', before: { status: booking.status }, after: { status: 'CANCELLED', reason } });

    // Send cancellation email to customer
    try {
      const emailData: OrderCancellationData = {
        customerEmail: booking.customerEmail,
        orderNumber: booking.reference,
        customerName: booking.customerName,
        reason: reason || 'Cancelled by admin',
        refundAmount: booking.paidAt ? booking.totalGBP / 100 : undefined,
        currency: 'GBP',
      };

      const emailResult = await unifiedEmailService.sendOrderCancellation(emailData);
      
      if (emailResult.success) {
        console.log('✅ Order cancellation email sent successfully:', {
          orderRef: booking.reference,
          email: booking.customerEmail,
        });
      } else {
        console.error('❌ Failed to send order cancellation email:', emailResult.error);
      }

    } catch (emailError) {
      console.error('❌ Error sending cancellation email:', emailError);
      // Continue with cancellation even if email fails
    }

    // Notify drivers about cancellation
    const pusher = require('@/lib/pusher').default;
    
    try {
      // Notify all drivers about cancellation
      await pusher.trigger('driver-notifications', 'job-cancelled', {
        jobId: booking.id
      });
      
      // If a driver was assigned, send specific notification
      if (booking.driverId) {
        await pusher.trigger(`driver-${booking.driverId}`, 'job-cancelled', {
          jobId: booking.id,
          message: `Job ${booking.reference} has been cancelled by admin. Reason: ${reason || 'No reason provided'}`
        });
      }
      
      console.log('✅ Order cancelled successfully:', {
        reference: booking.reference,
        previousStatus: booking.status,
        reason,
        adminUser: session.user.email,
        notificationSent: true
      });
    } catch (pusherError) {
      console.error('❌ Error sending cancellation notification:', pusherError);
      // Continue even if notification fails
    }

    return NextResponse.json({
      success: true,
      message: 'Order cancelled successfully',
      order: {
        id: cancelledOrder.id,
        reference: cancelledOrder.reference,
        status: cancelledOrder.status,
        customerName: cancelledOrder.customerName,
      },
    });

  } catch (error) {
    console.error('❌ Error cancelling order:', error);
    return NextResponse.json(
      {
        error: 'Failed to cancel order',
        details: error instanceof Error ? error.message : 'Unknown error',
      },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
import Stripe from 'stripe';

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY!, {
  apiVersion: '2024-04-10',
});

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ code: string }> }
) {
  try {
    const session = await getServerSession(authOptions);
    
    if (!session?.user || (session.user as any).role !== 'admin') {
      return NextResponse.json(
        { error: 'Unauthorized - Admin access required' },
        { status: 401 }
      );
    }

    const { code: reference } = await params;

    console.log('🔧 Manual payment confirmation for booking:', reference);

    // Get booking details
    const booking = await prisma.booking.findFirst({
      where: { reference },
      include: {
        pickupAddress: true,
        dropoffAddress: true
      }
    });

    if (!booking) {
      return NextResponse.json(
        { error: 'Booking not found', reference },
        { status: 404 }
      );
    }

    console.log('📋 Booking found:', {
      id: booking.id,
      reference: booking.reference,
      status: booking.status,
      totalGBP: booking.totalGBP,
      stripePaymentIntentId: booking.stripePaymentIntentId,
      paidAt: booking.paidAt
    });

    // Check if already confirmed
    if (booking.status === 'CONFIRMED') {
      return NextResponse.json({
        success: false,
        message: 'Booking is already confirmed',
        booking: {
          reference: booking.reference,
          status: booking.status,
          paidAt: booking.paidAt
        }
      });
    }

    // Check if booking has a Stripe Payment Intent
    let stripePaymentStatus = null;
    let stripePaymentIntent = null;

    if (booking.stripePaymentIntentId) {
      try {
        console.log('💳 Checking Stripe payment intent:', booking.stripePaymentIntentId);
        stripePaymentIntent = await stripe.paymentIntents.retrieve(booking.stripePaymentIntentId);
        stripePaymentStatus = stripePaymentIntent.status;
        
        console.log('💳 Stripe payment intent status:', {
          id: stripePaymentIntent.id,
          status: stripePaymentIntent.status,
          amount: stripePaymentIntent.amount,
          currency: stripePaymentIntent.currency
        });
      } catch (stripeError) {
        console.error('❌ Error fetching Stripe payment intent:', stripeError);
      }
    }

    // Determine if we should confirm the booking
    const shouldConfirm = stripePaymentStatus === 'succeeded' || booking.status === 'PENDING_PAYMENT';

    if (!shouldConfirm) {
      return NextResponse.json({
        success: false,
        message: `Cannot confirm booking with payment status: ${stripePaymentStatus}`,
        booking: {
          reference: booking.reference,
          status: booking.status,
          stripePaymentStatus
        }
      });
    }

    // Manually confirm the booking
    const confirmedBooking = await prisma.$transaction(async (tx) => {
      // Update booking status
      const updatedBooking = await tx.booking.update({
        where: { id: booking.id },
        data: {
          status: 'CONFIRMED',
          paidAt: booking.paidAt || new Date(),
          updatedAt: new Date()
        }
      });

      // Create audit log
      await tx.auditLog.create({
        data: {
          actorId: (session.user as any).id,
          actorRole: 'admin',
          action: 'booking_manually_confirmed',
          targetType: 'booking',
          targetId: booking.id,
          userId: (session.user as any).id,
          details: {
            reference: booking.reference,
            previousStatus: booking.status,
            newStatus: 'CONFIRMED',
            reason: 'Manual confirmation by admin - missed webhook or payment processing issue',
            stripePaymentIntentId: booking.stripePaymentIntentId,
            stripePaymentStatus: stripePaymentStatus,
            confirmedAt: new Date().toISOString(),
            adminUser: (session.user as any).email
          },
        },
      });

      return updatedBooking;
    });

    console.log('✅ Booking manually confirmed:', {
      id: confirmedBooking.id,
      reference: confirmedBooking.reference,
      status: confirmedBooking.status,
      paidAt: confirmedBooking.paidAt
    });

    // Try to notify available drivers
    try {
      const notifyResponse = await fetch(`${process.env.NEXT_PUBLIC_BASE_URL}/api/admin/notify-drivers`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ bookingId: booking.id }),
      });

      if (notifyResponse.ok) {
        console.log('✅ Drivers notified about confirmed booking');
      } else {
        console.error('⚠️ Failed to notify drivers');
      }
    } catch (notifyError) {
      console.error('⚠️ Error notifying drivers:', notifyError);
    }

    return NextResponse.json({
      success: true,
      message: 'Booking manually confirmed successfully',
      booking: {
        id: confirmedBooking.id,
        reference: confirmedBooking.reference,
        status: confirmedBooking.status,
        paidAt: confirmedBooking.paidAt,
        previousStatus: booking.status
      },
      stripeInfo: {
        paymentIntentId: booking.stripePaymentIntentId,
        paymentStatus: stripePaymentStatus
      },
      nextSteps: [
        'Booking should now appear in driver jobs dashboard',
        'Drivers have been notified about the available job',
        'Customer can track the booking status'
      ]
    });

  } catch (error) {
    const { code: reference } = await params;
    console.error('❌ Manual confirmation error:', error);
    return NextResponse.json(
      { 
        error: 'Manual confirmation failed', 
        details: error instanceof Error ? error.message : 'Unknown error',
        reference 
      },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
import { AdditionalPaymentStatus } from '@prisma/client';
import { logAudit } from '@/lib/audit';
import { stripe } from '@/lib/stripe/client';
import { unifiedEmailService } from '@/lib/email/UnifiedEmailService';
import { z } from 'zod';

export const dynamic = 'force-dynamic';

const requestSchema = z.object({
  targetTotalGBP: z.number().int().min(100),
  reason: z.string().trim().max(500).optional(),
});

const APP_URL = process.env.NEXT_PUBLIC_APP_URL || 'https://speedy-van.co.uk';

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ code: string }> }
) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user || (session.user as any).role !== 'admin') {
      return NextResponse.json({ error: 'Unauthorized - Admin access required' }, { status: 401 });
    }

    if (!stripe) {
      return NextResponse.json({ error: 'Stripe is not configured' }, { status: 500 });
    }

    const body = await request.json();
    const parseResult = requestSchema.safeParse(body);
    if (!parseResult.success) {
      return NextResponse.json({ error: 'Invalid payload', details: parseResult.error.format() }, { status: 400 });
    }

    const { targetTotalGBP, reason } = parseResult.data;
    const { code } = await params;

    const booking = await prisma.booking.findUnique({
      where: { reference: code },
      include: {
        customer: true,
        pickupAddress: true,
        dropoffAddress: true,
      },
    });

    if (!booking) {
      return NextResponse.json({ error: 'Order not found' }, { status: 404 });
    }

    if (!booking.paidAt || !booking.amountPaidGBP || booking.amountPaidGBP <= 0) {
      return NextResponse.json({ error: 'No payment recorded for this order. Additional payments can only be requested after an initial payment.' }, { status: 400 });
    }

    if (booking.additionalPaymentStatus === AdditionalPaymentStatus.PENDING) {
      return NextResponse.json({ error: 'There is already a pending additional payment request for this order.' }, { status: 409 });
    }

    const amountPaid = booking.amountPaidGBP;
    const difference = targetTotalGBP - amountPaid;

    if (difference <= 0) {
      return NextResponse.json({ error: 'Target total is not greater than the amount already paid. Use the refund flow for reductions.' }, { status: 400 });
    }

    const checkoutSession = await stripe.checkout.sessions.create({
      mode: 'payment',
      payment_method_types: ['card'],
      customer_email: booking.customerEmail,
      line_items: [
        {
          quantity: 1,
          price_data: {
            currency: 'gbp',
            unit_amount: difference,
            product_data: {
              name: `Additional payment for booking ${booking.reference}`,
              description: 'Adjustment requested by Speedy Van operations team',
            },
          },
        },
      ],
      success_url: `${APP_URL}/payments/additional/success?booking=${encodeURIComponent(booking.reference)}&session_id={CHECKOUT_SESSION_ID}`,
      cancel_url: `${APP_URL}/payments/additional/cancelled?booking=${encodeURIComponent(booking.reference)}`,
      metadata: {
        bookingId: booking.id,
        bookingReference: booking.reference,
        paymentPurpose: 'additional_charge',
        additionalAmount: difference.toString(),
        targetTotalGBP: targetTotalGBP.toString(),
        requestedBy: (session.user as any).email || 'admin',
      },
      payment_intent_data: {
        metadata: {
          bookingId: booking.id,
          bookingReference: booking.reference,
          paymentPurpose: 'additional_charge',
          additionalAmount: difference.toString(),
          targetTotalGBP: targetTotalGBP.toString(),
          requestedBy: (session.user as any).email || 'admin',
        },
      },
    });

    const now = new Date();

    await prisma.booking.update({
      where: { id: booking.id },
      data: {
        totalGBP: targetTotalGBP,
        additionalPaymentStatus: AdditionalPaymentStatus.PENDING,
        additionalPaymentAmountGBP: difference,
        additionalPaymentRequestedAt: now,
        additionalPaymentStripeIntent: checkoutSession.payment_intent?.toString() || null,
        lastPaymentDate: booking.lastPaymentDate ?? booking.paidAt,
      },
    });

    await logAudit((session.user as any).id, 'request_additional_payment', booking.id, {
      targetTotalGBP,
      difference,
      checkoutSessionId: checkoutSession.id,
      paymentIntentId: checkoutSession.payment_intent,
      reason: reason || null,
    });

    try {
      await unifiedEmailService.sendAdditionalPaymentRequest({
        customerEmail: booking.customerEmail,
        customerName: booking.customerName,
        orderNumber: booking.reference,
        amountDue: difference / 100,
        currency: 'GBP',
        paymentLink: checkoutSession.url!,
        reason: reason || 'Additional services or adjustments were added to your booking.',
      });
    } catch (emailError) {
      console.error('❌ Failed to send additional payment email:', emailError);
    }

    return NextResponse.json({
      success: true,
      data: {
        checkoutUrl: checkoutSession.url,
        checkoutSessionId: checkoutSession.id,
        paymentIntentId: checkoutSession.payment_intent,
        differenceGBP: difference,
        targetTotalGBP,
      },
    });
  } catch (error) {
    console.error('❌ Error creating additional payment:', error);
    return NextResponse.json({ error: 'Failed to create additional payment request', details: error instanceof Error ? error.message : 'Unknown error' }, { status: 500 });
  }
}

// POST /api/admin/orders/[code]/fix-coordinates - Fix invalid coordinates for a booking
import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';

const MAPBOX_TOKEN = process.env.NEXT_PUBLIC_MAPBOX_TOKEN || 'pk.eyJ1IjoiYWhtYWRhbHdha2FpIiwiYSI6ImNtZGNsZ3RsZDEzdGsya3F0ODFxeGRzbXoifQ.jfgGW0KNFTwATOShRDtQsg';

async function geocodeAddress(address: string, postcode: string): Promise<{lat: number, lng: number} | null> {
  try {
    const query = `${address}, ${postcode}, UK`;
    const url = `https://api.mapbox.com/geocoding/v5/mapbox.places/${encodeURIComponent(query)}.json?access_token=${MAPBOX_TOKEN}&country=GB&limit=1`;
    
    console.log(`🔍 Geocoding: ${query}`);
    const response = await fetch(url);
    const data = await response.json();
    
    if (data.features && data.features.length > 0) {
      const [lng, lat] = data.features[0].center;
      console.log(`✅ Found coordinates: ${lat}, ${lng}`);
      return { lat, lng };
    } else {
      console.log(`❌ No coordinates found for: ${query}`);
      return null;
    }
  } catch (error) {
    console.error(`❌ Geocoding error for ${address}:`, error);
    return null;
  }
}

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ code: string }> }
) {
  try {
    const { code } = await params;
    console.log(`🔧 Fixing coordinates for booking: ${code}`);

    // Find the booking with its addresses
    const booking = await prisma.booking.findUnique({
      where: { reference: code },
      include: {
        pickupAddress: true,
        dropoffAddress: true,
      }
    });

    if (!booking) {
      return NextResponse.json(
        { error: 'Booking not found' },
        { status: 404 }
      );
    }

    const results = [];

    // Fix pickup address coordinates if invalid
    if (booking.pickupAddress && 
        (booking.pickupAddress.lat === 0 || booking.pickupAddress.lng === 0)) {
      
      console.log('🔧 Fixing pickup address coordinates...');
      const pickupCoords = await geocodeAddress(
        booking.pickupAddress.label,
        booking.pickupAddress.postcode || ''
      );
      
      if (pickupCoords) {
        await prisma.bookingAddress.update({
          where: { id: booking.pickupAddress.id },
          data: {
            lat: pickupCoords.lat,
            lng: pickupCoords.lng,
          }
        });
        
        results.push({
          type: 'pickup',
          address: booking.pickupAddress.label,
          oldCoords: { lat: booking.pickupAddress.lat, lng: booking.pickupAddress.lng },
          newCoords: pickupCoords,
          status: 'updated'
        });
      }
    } else {
      results.push({
        type: 'pickup',
        status: 'already_valid',
        coords: { lat: booking.pickupAddress?.lat, lng: booking.pickupAddress?.lng }
      });
    }

    // Fix dropoff address coordinates if invalid
    if (booking.dropoffAddress && 
        (booking.dropoffAddress.lat === 0 || booking.dropoffAddress.lng === 0)) {
      
      console.log('🔧 Fixing dropoff address coordinates...');
      const dropoffCoords = await geocodeAddress(
        booking.dropoffAddress.label,
        booking.dropoffAddress.postcode || ''
      );
      
      if (dropoffCoords) {
        await prisma.bookingAddress.update({
          where: { id: booking.dropoffAddress.id },
          data: {
            lat: dropoffCoords.lat,
            lng: dropoffCoords.lng,
          }
        });
        
        results.push({
          type: 'dropoff',
          address: booking.dropoffAddress.label,
          oldCoords: { lat: booking.dropoffAddress.lat, lng: booking.dropoffAddress.lng },
          newCoords: dropoffCoords,
          status: 'updated'
        });
      }
    } else {
      results.push({
        type: 'dropoff',
        status: 'already_valid',
        coords: { lat: booking.dropoffAddress?.lat, lng: booking.dropoffAddress?.lng }
      });
    }

    return NextResponse.json({
      success: true,
      booking: code,
      results
    });

  } catch (error) {
    console.error('❌ Error fixing coordinates:', error);
    return NextResponse.json(
      { error: 'Failed to fix coordinates' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
import { logAudit } from '@/lib/audit';
import { stripe } from '@/lib/stripe/client';
import { unifiedEmailService } from '@/lib/email/UnifiedEmailService';
import { AdditionalPaymentStatus } from '@prisma/client';
import { z } from 'zod';

export const dynamic = 'force-dynamic';

const requestSchema = z.object({
  targetTotalGBP: z.number().int().min(0),
  reason: z.string().trim().max(500).optional(),
});

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ code: string }> }
) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user || (session.user as any).role !== 'admin') {
      return NextResponse.json({ error: 'Unauthorized - Admin access required' }, { status: 401 });
    }

    if (!stripe) {
      return NextResponse.json({ error: 'Stripe is not configured' }, { status: 500 });
    }

    const body = await request.json();
    const parseResult = requestSchema.safeParse(body);
    if (!parseResult.success) {
      return NextResponse.json({ error: 'Invalid payload', details: parseResult.error.format() }, { status: 400 });
    }

    const { targetTotalGBP, reason } = parseResult.data;
    const { code } = await params;

    const booking = await prisma.booking.findUnique({
      where: { reference: code },
      include: {
        customer: true,
      },
    });

    if (!booking) {
      return NextResponse.json({ error: 'Order not found' }, { status: 404 });
    }

    const amountPaid = booking.amountPaidGBP ?? 0;
    if (!booking.paidAt || amountPaid <= 0) {
      return NextResponse.json({ error: 'No payment recorded for this order. Refunds cannot be issued.' }, { status: 400 });
    }

    const currentPaid = amountPaid;
    if (targetTotalGBP >= currentPaid) {
      return NextResponse.json({ error: 'Target total must be less than the amount already paid in order to issue a refund.' }, { status: 400 });
    }

    const refundAmount = currentPaid - targetTotalGBP;

    if (refundAmount <= 0) {
      return NextResponse.json({ error: 'Refund amount must be greater than zero.' }, { status: 400 });
    }

    const refunds: string[] = [];
    let remaining = refundAmount;

    const paymentIntents: string[] = [];
    if (booking.additionalPaymentStatus === AdditionalPaymentStatus.PAID && booking.additionalPaymentStripeIntent) {
      paymentIntents.push(booking.additionalPaymentStripeIntent);
    }
    if (booking.stripePaymentIntentId) {
      paymentIntents.push(booking.stripePaymentIntentId);
    }

    for (const paymentIntentId of paymentIntents) {
      if (remaining <= 0) break;
      const paymentIntent = await stripe.paymentIntents.retrieve(paymentIntentId, {
        expand: ['charges']
      }) as any;
      const amountReceived = paymentIntent.amount_received ?? 0;
      // Get amount_refunded from charges (Stripe API supports this with expand)
      const amountRefunded = paymentIntent.charges?.data?.[0]?.amount_refunded ?? 0;
      const refundable = amountReceived - amountRefunded;
      if (refundable <= 0) continue;
      const amountToRefund = Math.min(refundable, remaining);
      if (amountToRefund <= 0) continue;

      const refund = await stripe.refunds.create({
        payment_intent: paymentIntentId,
        amount: amountToRefund,
        metadata: {
          bookingId: booking.id,
          bookingReference: booking.reference,
          paymentPurpose: 'admin_refund',
          refundReason: reason || 'Admin initiated price adjustment',
          requestedBy: (session.user as any).email || 'admin',
        },
      });

      refunds.push(refund.id);
      remaining -= amountToRefund;
    }

    if (remaining > 0) {
      return NextResponse.json({ error: 'Unable to refund the full amount. Please review the captured charges in Stripe.' }, { status: 409 });
    }

    const now = new Date();

    const additionalPaymentAmount = booking.additionalPaymentAmountGBP ?? 0;

    const updatedBooking = await prisma.booking.update({
      where: { id: booking.id },
      data: {
        totalGBP: targetTotalGBP,
        amountPaidGBP: currentPaid - refundAmount,
        additionalPaymentStatus: refundAmount >= additionalPaymentAmount
          ? AdditionalPaymentStatus.REFUNDED
          : booking.additionalPaymentStatus,
        additionalPaymentAmountGBP: refundAmount >= additionalPaymentAmount ? 0 : Math.max(additionalPaymentAmount - refundAmount, 0),
        lastRefundDate: now,
      },
    });

    await logAudit((session.user as any).id, 'issue_refund', booking.id, {
      refundAmount,
      targetTotalGBP,
      refunds,
      reason: reason || null,
    });

    try {
      await unifiedEmailService.sendRefundNotification({
        customerEmail: booking.customerEmail,
        customerName: booking.customerName,
        orderNumber: booking.reference,
        refundAmount: refundAmount / 100,
        newTotal: targetTotalGBP / 100,
        currency: 'GBP',
        reason: reason || 'Price adjustment processed by our operations team.',
      });
    } catch (emailError) {
      console.error('❌ Failed to send refund email:', emailError);
    }

    return NextResponse.json({
      success: true,
      data: {
        refunds,
        refundAmountGBP: refundAmount,
        targetTotalGBP,
        amountPaidGBP: updatedBooking.amountPaidGBP,
      },
    });
  } catch (error) {
    console.error('❌ Error issuing refund:', error);
    return NextResponse.json({ error: 'Failed to issue refund', details: error instanceof Error ? error.message : 'Unknown error' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
import { getActiveAssignment } from '@/lib/utils/assignment-helpers';
import { getPusherServer } from '@/lib/pusher';

export const dynamic = 'force-dynamic';

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ code: string }> }
) {
  try {
    const session = await getServerSession(authOptions);
    
    if (!session?.user || (session.user as any).role !== 'admin') {
      return NextResponse.json(
        { error: 'Unauthorized - Admin access required' },
        { status: 401 }
      );
    }

    const { code } = await params;
    const { reason } = await request.json();

    console.log('🚗 Admin removing driver from order:', { code, reason });

    // Get the booking with current assignment
    const booking = await prisma.booking.findFirst({
      where: { reference: code },
      include: {
        driver: {
          include: {
            User: {
              select: { name: true, email: true, id: true }
            }
          }
        },
        Assignment: {
          include: {
            Driver: {
              include: {
                User: {
                  select: { name: true, email: true, id: true }
                }
              }
            }
          }
        }
      }
    });

    if (!booking) {
      return NextResponse.json(
        { error: 'Booking not found' },
        { status: 404 }
      );
    }

    if (!booking.driverId) {
      return NextResponse.json(
        { error: 'No driver assigned to this booking' },
        { status: 400 }
      );
    }

    const driverName = booking.driver?.User?.name || 'Unknown Driver';
    const driverId = booking.driverId;

    // Use transaction to ensure data consistency
    const result = await prisma.$transaction(async (tx) => {
      // Create job event for removal (only if assignment exists)
      const activeAssignment = getActiveAssignment(booking.Assignment);
      if (activeAssignment) {
        await tx.jobEvent.create({
          data: {
            id: `event_${Date.now()}_removed`,
            assignmentId: activeAssignment.id,
            step: 'job_completed', // ✅ Use valid JobStep enum value
            payload: {
              removedBy: 'admin',
              reason: reason || 'Removed by admin',
              removedAt: new Date().toISOString(),
              action: 'driver_removed',
            },
            notes: `Job removed from driver ${driverName} by admin`,
            createdBy: (session.user as any).id,
            mediaUrls: [],
          }
        });

        // Update assignment status to cancelled
        await tx.assignment.update({
          where: { id: activeAssignment.id },
          data: {
            status: 'cancelled',
            updatedAt: new Date(),
          }
        });
      }

      // Remove driver from booking
      const updatedBooking = await tx.booking.update({
        where: { id: booking.id },
        data: {
          driverId: null,
          status: 'CONFIRMED', // Keep as confirmed but without driver
          updatedAt: new Date(),
        }
      });

      return { updatedBooking };
    });

    // Send real-time notifications
    try {
      const pusher = getPusherServer();

      // Notify the removed driver
      await pusher.trigger(`driver-${driverId}`, 'job-removed', {
        bookingId: booking.id,
        bookingReference: booking.reference,
        reason: reason || 'Removed by admin',
        removedAt: new Date().toISOString(),
        message: 'You have been removed from this job',
      });

      // Notify other drivers that job is available again
      await pusher.trigger('drivers-channel', 'job-available-again', {
        bookingId: booking.id,
        bookingReference: booking.reference,
        customerName: booking.customerName,
        pickupAddress: 'N/A', // pickupAddress not available
        dropoffAddress: 'N/A', // dropoffAddress not available
        availableAt: new Date().toISOString(),
        message: 'This job is now available again',
      });

      // Notify customer about driver removal
      await pusher.trigger(`booking-${booking.reference}`, 'driver-removed', {
        reason: reason || 'Driver removed by admin',
        removedAt: new Date().toISOString(),
        message: 'Your driver has been changed. A new driver will be assigned soon.',
      });

      // Notify admin dashboard
      await pusher.trigger('admin-notifications', 'driver-removed', {
        bookingId: booking.id,
        bookingReference: booking.reference,
        driverName: driverName,
        removedAt: new Date().toISOString(),
      });

      console.log('✅ Real-time notifications sent for driver removal');
    } catch (notificationError) {
      console.error('❌ Error sending real-time notifications:', notificationError);
      // Don't fail the request if notifications fail
    }

    // Create audit log
    await prisma.auditLog.create({
      data: {
        actorId: (session.user as any).id,
        actorRole: 'admin',
        action: 'driver_removed',
        targetType: 'booking',
        targetId: booking.id,
        details: {
          bookingReference: booking.reference,
          driverId: driverId,
          driverName: driverName,
          reason: reason || 'Removed by admin',
          removedAt: new Date().toISOString(),
        }
      }
    });

    return NextResponse.json({
      success: true,
      message: 'Driver removed successfully',
      data: {
        bookingId: booking.id,
        bookingReference: booking.reference,
        removedDriver: {
          id: driverId,
          name: driverName,
        },
        removedAt: new Date().toISOString(),
      }
    });

  } catch (error) {
    console.error('❌ Error removing driver:', error);
    return NextResponse.json(
      {
        error: 'Failed to remove driver',
        details: error instanceof Error ? error.message : 'Unknown error',
      },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
