}

export async function PUT(
  request: NextRequest,
  { params }: { params: Promise<{ code: string }> }
) {
  try {
    // Check admin authorization
    const session = await getServerSession(authOptions);
    if (!session?.user || (session.user as any).role !== 'admin') {
      return NextResponse.json(
        { error: 'Unauthorized - Admin access required' },
        { status: 401 }
      );
    }

    const { code } = await params;
    const updateData = await request.json();

    // Get existing order for comparison and audit
    const existingOrder = await prisma.booking.findUnique({
      where: { reference: code },
      select: {
        id: true,
        totalGBP: true,
        stripePaymentIntentId: true,
        status: true,
        paidAt: true,
        pickupAddress: {
          select: {
            id: true,
            label: true,
            postcode: true,
            lat: true,
            lng: true,
          },
        },
        dropoffAddress: {
          select: {
            id: true,
            label: true,
            postcode: true,
            lat: true,
            lng: true,
          },
        },
        amountPaidGBP: true,
        additionalPaymentStatus: true,
        additionalPaymentAmountGBP: true,
        additionalPaymentStripeIntent: true,
      },
    });

    if (!existingOrder) {
      return NextResponse.json(
        { error: 'Order not found' },
        { status: 404 }
      );
    }

    const nextTotalGBP = typeof updateData.totalGBP === 'number' ? Math.round(updateData.totalGBP) : undefined;
    const priceChanged = typeof nextTotalGBP === 'number' && nextTotalGBP !== existingOrder.totalGBP;
    const priceChangeData = priceChanged
      ? {
          oldPrice: existingOrder.totalGBP,
          newPrice: nextTotalGBP,
          difference: nextTotalGBP - existingOrder.totalGBP,
        }
      : null;

    const existingPaidAmount = existingOrder.amountPaidGBP ?? 0;

    if (priceChanged && (existingOrder.paidAt || existingPaidAmount > 0)) {
      return NextResponse.json(
        {
          error: 'Paid orders cannot be repriced via direct update. Use the payment adjustment actions for additional charges or refunds.',
          code: 'PAID_ORDER_PRICE_CHANGE_BLOCKED',
        },
        { status: 400 }
      );
    }

    const pickupAddressUpdate = buildBookingAddressUpdate(updateData.pickupAddress);
    const dropoffAddressUpdate = buildBookingAddressUpdate(updateData.dropoffAddress);

    // Update the booking
    const updatedOrder = await prisma.booking.update({
      where: { reference: code },
      data: {
        ...(updateData.customerName && { customerName: updateData.customerName }),
        ...(updateData.customerEmail && { customerEmail: updateData.customerEmail }),
        ...(updateData.customerPhone && { customerPhone: updateData.customerPhone }),
        ...(updateData.scheduledAt && { scheduledAt: new Date(updateData.scheduledAt) }),
        ...(updateData.pickupTimeSlot && { pickupTimeSlot: updateData.pickupTimeSlot }),
        ...(typeof nextTotalGBP === 'number' ? { totalGBP: nextTotalGBP } : {}),
        ...(updateData.notes !== undefined && {
          // Handle notes update when available in schema
        }),
        ...(pickupAddressUpdate
          ? {
              pickupAddress: {
                update: pickupAddressUpdate,
              },
            }
          : {}),
        ...(dropoffAddressUpdate
          ? {
              dropoffAddress: {
                update: dropoffAddressUpdate,
              },
            }
          : {}),
        ...(updateData.pickupProperty && {
          pickupProperty: {
            update: {
              ...(typeof updateData.pickupProperty.floors === 'number'
                ? { floors: updateData.pickupProperty.floors }
                : {}),
              ...(updateData.pickupProperty.accessType
                ? { accessType: updateData.pickupProperty.accessType }
                : {}),
            },
          },
        }),
        ...(updateData.dropoffProperty && {
          dropoffProperty: {
            update: {
              ...(typeof updateData.dropoffProperty.floors === 'number'
                ? { floors: updateData.dropoffProperty.floors }
                : {}),
              ...(updateData.dropoffProperty.accessType
                ? { accessType: updateData.dropoffProperty.accessType }
                : {}),
            },
          },
        }),
      },
      include: {
        customer: {
          select: {
            id: true,
            name: true,
            email: true,
          },
        },
        driver: {
          include: {
            User: {
              select: {
                id: true,
                name: true,
                email: true,
              },
            },
          },
        },
        pickupAddress: true,
        dropoffAddress: true,
        pickupProperty: true,
        dropoffProperty: true,
        BookingItem: {
          select: {
            id: true,
            name: true,
            quantity: true,
            volumeM3: true,
          },
        },
      },
    });

    // CRITICAL: Synchronize with Stripe if price changed
    if (priceChanged && existingOrder.stripePaymentIntentId) {
      try {
        const stripe = await import('stripe').then(m => new m.default(process.env.STRIPE_SECRET_KEY!, {
          apiVersion: '2024-04-10',
        }));

        // Check if payment intent is still modifiable
        const paymentIntent = await stripe.paymentIntents.retrieve(existingOrder.stripePaymentIntentId);
        
        if (paymentIntent.status === 'requires_payment_method' || paymentIntent.status === 'requires_confirmation') {
          // Update the payment intent amount
          await stripe.paymentIntents.update(existingOrder.stripePaymentIntentId, {
            amount: nextTotalGBP!, // totalGBP is in pence
            metadata: {
              ...paymentIntent.metadata,
              priceUpdatedBy: 'admin',
              priceUpdatedAt: new Date().toISOString(),
              oldAmount: existingOrder.totalGBP.toString(),
              newAmount: nextTotalGBP!.toString(),
            },
          });

          // Log successful Stripe sync
          await logAudit(
            (session.user as any).id,
            'stripe_payment_updated',
            updatedOrder.id,
            {
              targetType: 'booking',
              before: { totalGBP: existingOrder.totalGBP },
              after: { totalGBP: nextTotalGBP, stripePaymentIntentId: existingOrder.stripePaymentIntentId },
            }
          );
        } else {
          // Payment intent cannot be modified (already paid or processing)
          // Log a warning for manual review
          await logAudit(
            (session.user as any).id, 
            'price_change_after_payment', 
            updatedOrder.id, 
            { 
              targetType: 'booking', 
              before: { totalGBP: existingOrder.totalGBP }, 
              after: { totalGBP: nextTotalGBP },
              warning: `Payment intent ${paymentIntent.status} - requires manual Stripe adjustment (refund/credit)`,
              paymentIntentStatus: paymentIntent.status,
            }
          );
        }
      } catch (stripeError) {
        // Log Stripe sync failure
        await logAudit(
          (session.user as any).id, 
          'stripe_sync_failed', 
          updatedOrder.id, 
          { 
            targetType: 'booking', 
            error: stripeError instanceof Error ? stripeError.message : 'Unknown error',
            priceChange: priceChangeData,
          }
        );
      }
    }

    const auditAfterData = {
      ...updateData,
      ...(typeof nextTotalGBP === 'number' ? { totalGBP: nextTotalGBP } : {}),
    };

    // Log audit trail for order update
    await logAudit(
      (session.user as any).id, 
      'update_order', 
      updatedOrder.id, 
      { 
        targetType: 'booking', 
        before: existingOrder, 
        after: auditAfterData,
        priceChanged: priceChanged ? priceChangeData : null,
      }
    );

    // Transform response similar to GET
    const transformedOrder = {
      id: updatedOrder.id,
      reference: updatedOrder.reference,
      status: updatedOrder.status,
      scheduledAt: updatedOrder.scheduledAt.toISOString(),
      totalGBP: updatedOrder.totalGBP,
      customerName: updatedOrder.customerName,
      customerEmail: updatedOrder.customerEmail,
      customerPhone: updatedOrder.customerPhone,
      pickupAddress: updatedOrder.pickupAddress ? {
        label: updatedOrder.pickupAddress.label,
        postcode: updatedOrder.pickupAddress.postcode,
      } : null,
      dropoffAddress: updatedOrder.dropoffAddress ? {
        label: updatedOrder.dropoffAddress.label,
        postcode: updatedOrder.dropoffAddress.postcode,
      } : null,
      pickupProperty: updatedOrder.pickupProperty ? {
        floors: updatedOrder.pickupProperty.floors,
        accessType: updatedOrder.pickupProperty.accessType,
      } : null,
      dropoffProperty: updatedOrder.dropoffProperty ? {
        floors: updatedOrder.dropoffProperty.floors,
        accessType: updatedOrder.dropoffProperty.accessType,
      } : null,
      driver: updatedOrder.driver ? {
        User: {
          name: updatedOrder.driver.User.name,
          email: updatedOrder.driver.User.email,
        },
      } : null,
      createdAt: updatedOrder.createdAt.toISOString(),
      paidAt: updatedOrder.paidAt?.toISOString(),
      durationSeconds: updatedOrder.estimatedDurationMinutes ? updatedOrder.estimatedDurationMinutes * 60 : null,
      baseDistanceMiles: updatedOrder.baseDistanceMiles,
      notes: null, // Add when available
      pickupTimeSlot: updatedOrder.pickupTimeSlot,
      BookingItem: updatedOrder.BookingItem?.map(item => ({
        id: item.id,
        name: item.name,
        quantity: item.quantity,
        volumeM3: item.volumeM3,
      })) || [],
      amountPaidGBP: updatedOrder.amountPaidGBP,
      additionalPaymentStatus: updatedOrder.additionalPaymentStatus,
      additionalPaymentAmountGBP: updatedOrder.additionalPaymentAmountGBP,
      additionalPaymentRequestedAt: updatedOrder.additionalPaymentRequestedAt?.toISOString(),
      additionalPaymentPaidAt: updatedOrder.additionalPaymentPaidAt?.toISOString(),
      additionalPaymentStripeIntent: updatedOrder.additionalPaymentStripeIntent,
      lastPaymentDate: updatedOrder.lastPaymentDate?.toISOString(),
      lastRefundDate: updatedOrder.lastRefundDate?.toISOString(),
    };

    // Add warnings for price changes requiring manual action
    const response: any = { ...transformedOrder };
    if (priceChanged && existingOrder.paidAt) {
      response.warning = {
        type: 'PRICE_CHANGE_AFTER_PAYMENT',
        message: 'Price changed after payment. Manual Stripe adjustment (refund/credit) may be required.',
        oldPrice: existingOrder.totalGBP,
        newPrice: nextTotalGBP ?? existingOrder.totalGBP,
        difference: priceChangeData?.difference,
      };
    }
    if (priceChangeData) {
      response.priceChange = priceChangeData;
    }

    return NextResponse.json(response);

  } catch (error) {
    console.error('❌ Error updating order:', error);
    return NextResponse.json(
      {
        error: 'Failed to update order',
        details: error instanceof Error ? error.message : 'Unknown error',
      },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
import { logAudit } from '@/lib/audit';
import { unifiedEmailService, type OrderConfirmationData } from '@/lib/email/UnifiedEmailService';

export const dynamic = 'force-dynamic';

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ code: string }> }
) {
  try {
    // Check admin authorization
    const session = await getServerSession(authOptions);
    if (!session?.user || (session.user as any).role !== 'admin') {
      return NextResponse.json(
        { error: 'Unauthorized - Admin access required' },
        { status: 401 }
      );
    }

    const { code } = await params;

    // Fetch booking with all related data
    const booking = await prisma.booking.findUnique({
      where: { reference: code },
      include: {
        pickupAddress: true,
        dropoffAddress: true,
        pickupProperty: true,
        dropoffProperty: true,
        BookingItem: true,
      },
    });

    if (!booking) {
      return NextResponse.json(
        { error: 'Order not found' },
        { status: 404 }
      );
    }

    // Check if order is in a valid state for confirmation email
    if (booking.status === 'CANCELLED') {
      return NextResponse.json(
        { error: 'Cannot send confirmation for cancelled order' },
        { status: 400 }
      );
    }

    // Check for floor number issues
    // Only warn if floors is explicitly 0, null, or undefined
    // If floors > 0, customer provided floor number, so no warning needed
    const pickupFloors = booking.pickupProperty?.floors;
    const dropoffFloors = booking.dropoffProperty?.floors;
    const hasPickupFloorIssue = pickupFloors === null || pickupFloors === undefined || pickupFloors === 0;
    const hasDropoffFloorIssue = dropoffFloors === null || dropoffFloors === undefined || dropoffFloors === 0;

    // Prepare email data
    const confirmedTotalInPounds = booking.totalGBP / 100;
    const emailData: OrderConfirmationData = {
      customerEmail: booking.customerEmail,
      orderNumber: booking.reference,
      customerName: booking.customerName,
      pickupAddress: booking.pickupAddress?.label || 'Address not specified',
      dropoffAddress: booking.dropoffAddress?.label || 'Address not specified',
      scheduledDate: booking.scheduledAt.toLocaleDateString('en-GB', {
        weekday: 'long',
        day: 'numeric',
        month: 'long',
        year: 'numeric'
      }),
      totalAmount: confirmedTotalInPounds,
      currency: 'GBP',
    };

    // Generate invoice PDF to attach to email
    let invoicePDF: Buffer | undefined;
    try {
      const { buildInvoicePDF } = await import('@/lib/pdf');
      invoicePDF = await buildInvoicePDF({
        invoiceNumber: `INV-${booking.reference}`,
        date: booking.createdAt.toISOString().split('T')[0],
        dueDate: booking.createdAt.toISOString().split('T')[0],
        company: {
          name: 'Speedy Van',
          legalName: 'SPEEDY VAN REMOVALS LTD',
          address: 'Office 2.18, 1 Barrack St, Hamilton ML3 0HS',
          email: 'support@speedy-van.co.uk',
        },
        customer: {
          name: booking.customerName,
          email: booking.customerEmail,
          address: booking.pickupAddress?.label || 'Address not specified',
        },
        items: [{
          description: 'Moving Service',
          quantity: 1,
          unitPrice: confirmedTotalInPounds,
          total: confirmedTotalInPounds,
        }],
        subtotal: confirmedTotalInPounds,
        tax: 0,
        total: confirmedTotalInPounds,
        currency: 'GBP',
      });
      console.log('✅ Invoice PDF generated for admin confirmation email');
    } catch (pdfError) {
      console.error('❌ Failed to generate invoice PDF:', pdfError);
      // Continue without PDF
    }

    // Send confirmation email with invoice attached
    const emailResult = await unifiedEmailService.sendOrderConfirmation(emailData, invoicePDF);
    
    if (!emailResult.success) {
      console.error('Email send failed:', emailResult.error);
      return NextResponse.json(
        { 
          error: 'Failed to send confirmation email',
          details: emailResult.error 
        },
        { status: 500 }
      );
    }

    // Send SMS confirmation to customer
    try {
      const { getVoodooSMSService } = await import('@/lib/sms/VoodooSMSService');
      const smsService = getVoodooSMSService();
      
      const smsMessage = `Your Speedy Van booking ${booking.reference} has been confirmed. We'll notify you once your driver is assigned.\n\nTrack your booking: https://speedy-van.co.uk/track\n\nFor assistance, call 01202 129746 or email support@speedy-van.co.uk`;
      
      const smsResult = await smsService.sendSMS({
        to: booking.customerPhone || booking.customerEmail, // Use phone if available, otherwise email
        message: smsMessage
      });

      if (smsResult.success) {
        console.log(`✅ SMS confirmation sent to customer for order ${booking.reference}`);
      } else {
        console.error('❌ SMS confirmation failed:', smsResult.error);
      }
    } catch (smsError) {
      console.error('❌ SMS service error:', smsError);
    }

    // Log audit trail
    await logAudit((session.user as any).id, 'send_confirmation_email', booking.id, { targetType: 'booking', before: null, after: { recipient: booking.customerEmail, hasFloorWarnings: hasPickupFloorIssue || hasDropoffFloorIssue, sentBy: (session.user as any).email } });

    console.log('✅ Manual confirmation email sent successfully:', {
      orderRef: booking.reference,
      email: booking.customerEmail,
      hasFloorWarnings: hasPickupFloorIssue || hasDropoffFloorIssue,
      sentBy: session.user.email,
    });

    return NextResponse.json({
      success: true,
      message: 'Confirmation email sent successfully',
      emailSent: true,
      hasFloorWarnings: hasPickupFloorIssue || hasDropoffFloorIssue,
    });

  } catch (error) {
    console.error('❌ Error sending confirmation email:', error);
    return NextResponse.json(
      {
        error: 'Failed to send confirmation email',
        details: error instanceof Error ? error.message : 'Unknown error',
      },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
import { unifiedEmailService } from '@/lib/email/UnifiedEmailService';

export const dynamic = 'force-dynamic';

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ code: string }> }
) {
  try {
    // Check admin authorization
    const session = await getServerSession(authOptions);
    if (!session?.user || (session.user as any).role !== 'admin') {
      return NextResponse.json(
        { error: 'Unauthorized - Admin access required' },
        { status: 401 }
      );
    }

    const { code } = await params;

    // Fetch booking with property details
    const booking = await prisma.booking.findUnique({
      where: { reference: code },
      include: {
        pickupProperty: true,
        dropoffProperty: true,
      },
    });

    if (!booking) {
      return NextResponse.json(
        { error: 'Order not found' },
        { status: 404 }
      );
    }

    // Check if order needs floor warning
    // Only warn if floors is explicitly 0, null, or undefined
    // If floors > 0, customer provided floor number, so no warning needed
    const pickupFloors = (booking as any).pickupProperty?.floors;
    const dropoffFloors = (booking as any).dropoffProperty?.floors;
    let hasPickupFloorIssue = pickupFloors === null || pickupFloors === undefined || pickupFloors === 0;
    let hasDropoffFloorIssue = dropoffFloors === null || dropoffFloors === undefined || dropoffFloors === 0;

    const preferences = (booking.customerPreferences as any) || {};
    const pickupMeta = preferences?.pickupAddressMeta || {};
    const dropoffMeta = preferences?.dropoffAddressMeta || {};

    const hasPickupFlatNumber = typeof pickupMeta.flatNumber === 'string' && pickupMeta.flatNumber.trim().length > 0;
    const hasDropoffFlatNumber = typeof dropoffMeta.flatNumber === 'string' && dropoffMeta.flatNumber.trim().length > 0;

    const parseFloorValue = (value: unknown): number | undefined => {
      if (typeof value === 'number') {
        return Number.isNaN(value) ? undefined : value;
      }
      if (typeof value === 'string') {
        const parsed = parseInt(value, 10);
        return Number.isNaN(parsed) ? undefined : parsed;
      }
      return undefined;
    };

    const pickupFloorMeta = parseFloorValue(pickupMeta.floorNumber);
    const dropoffFloorMeta = parseFloorValue(dropoffMeta.floorNumber);

    if (pickupFloorMeta && pickupFloorMeta > 0) {
      hasPickupFloorIssue = false;
    }
    if (dropoffFloorMeta && dropoffFloorMeta > 0) {
      hasDropoffFloorIssue = false;
    }

    if (hasPickupFlatNumber) {
      hasPickupFloorIssue = false;
    }
    if (hasDropoffFlatNumber) {
      hasDropoffFloorIssue = false;
    }

    if (!hasPickupFloorIssue && !hasDropoffFloorIssue) {
      return NextResponse.json({
        success: true,
        message: 'No floor warnings needed for this order',
        sent: false,
      });
    }

    // Send floor warning email
    const result = await unifiedEmailService.sendFloorWarningIfNeeded({
      reference: booking.reference,
      customerEmail: booking.customerEmail,
      customerName: booking.customerName,
      pickupProperty: (booking as any).pickupProperty || undefined,
      dropoffProperty: (booking as any).dropoffProperty || undefined,
      pickupAddressMeta: pickupMeta,
      dropoffAddressMeta: dropoffMeta,
    });

    if (result.success && result.sent) {
      console.log('✅ Floor warning email sent successfully:', {
        orderRef: booking.reference,
        email: booking.customerEmail,
        pickupFloorIssue: hasPickupFloorIssue,
        dropoffFloorIssue: hasDropoffFloorIssue,
        sentBy: session.user.email,
      });

      return NextResponse.json({
        success: true,
        message: 'Floor warning email sent successfully',
        sent: true,
        details: {
          pickupFloorIssue: hasPickupFloorIssue,
          dropoffFloorIssue: hasDropoffFloorIssue,
        },
      });
    } else {
      console.error('❌ Failed to send floor warning email:', result.error);

      return NextResponse.json({
        success: false,
        error: result.message || 'Failed to send floor warning email',
        sent: false,
      }, { status: 500 });
    }

  } catch (error) {
    console.error('❌ Error sending floor warning email:', error);
    return NextResponse.json(
      {
        error: 'Failed to send floor warning email',
        details: error instanceof Error ? error.message : 'Unknown error',
      },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { requireRole } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
import { getActiveAssignment } from '@/lib/utils/assignment-helpers';

export const dynamic = 'force-dynamic';

export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ code: string }> }
) {
  try {
    const user = await requireRole(request, 'admin');
    const { code } = await params;

    const { searchParams } = new URL(request.url);
    const since = searchParams.get('since'); // ISO date string for filtering

    // Get booking with tracking data
    const booking = await prisma.booking.findUnique({
      where: { reference: code },
      include: {
        driver: {
          include: {
            User: {
              select: {
                name: true,
                email: true,
              },
            },
          },
        },
        customer: {
          select: {
            id: true,
            name: true,
            email: true,
          },
        },
        pickupAddress: true,
        dropoffAddress: true,
        TrackingPing: {
          orderBy: { createdAt: 'desc' },
          select: {
            id: true,
            lat: true,
            lng: true,
            createdAt: true,
          },
        },
        Assignment: {
          include: {
            JobEvent: {
              orderBy: { createdAt: 'desc' },
              select: {
                step: true,
                createdAt: true,
                notes: true,
              },
            },
          },
        },
      },
    });

    if (!booking) {
      return NextResponse.json({ error: 'Booking not found' }, { status: 404 });
    }

    // Filter tracking pings if since parameter is provided
    let trackingPings = booking.TrackingPing;
    if (since) {
      const sinceDate = new Date(since);
      trackingPings = trackingPings.filter(ping => ping.createdAt >= sinceDate);
    }

    // Calculate route progress and ETA
    let routeProgress = 0;
    let eta = null;
    let currentLocation = null;
    
    // Get active assignment and last event (needed for multiple places)
    const activeAssignment = getActiveAssignment(booking.Assignment);
    const lastEvent = activeAssignment?.JobEvent?.[0];

    if (trackingPings.length > 0) {
      const latestPing = trackingPings[0];
      currentLocation = {
        lat: latestPing.lat,
        lng: latestPing.lng,
        timestamp: latestPing.createdAt,
      };

      // Calculate route progress based on booking status and job events
      if (lastEvent) {
        switch (lastEvent.step) {
          case 'navigate_to_pickup':
            routeProgress = 20;
            break;
          case 'arrived_at_pickup':
            routeProgress = 40;
            break;
          case 'loading_started':
            routeProgress = 50;
            break;
          case 'loading_completed':
            routeProgress = 60;
            break;
          case 'en_route_to_dropoff':
            routeProgress = 80;
            break;
          case 'arrived_at_dropoff':
            routeProgress = 90;
            break;
          case 'unloading_started':
            routeProgress = 95;
            break;
          case 'unloading_completed':
          case 'job_completed':
            routeProgress = 100;
            break;
          default:
            routeProgress = 0;
        }
      }

      // Simple ETA calculation (in production, use proper routing service)
      if (booking.scheduledAt) {
        const now = new Date();
        const scheduledTime = new Date(booking.scheduledAt);
        const timeDiff = scheduledTime.getTime() - now.getTime();

        if (timeDiff > 0) {
          eta = {
            estimatedArrival: scheduledTime,
            minutesRemaining: Math.round(timeDiff / (1000 * 60)),
          };
        }
      }
    }

    return NextResponse.json({
      success: true,
      booking: {
        id: booking.id,
        reference: booking.reference,
        status: booking.status,
        pickupAddress: booking.pickupAddress,
        dropoffAddress: booking.dropoffAddress,
        scheduledAt: booking.scheduledAt,
        driver: booking.driver
          ? {
              id: booking.driver.id,
              name: booking.driver.User.name,
              email: booking.driver.User.email,
            }
          : null,
        customer: booking.customer ? {
          id: booking.customer.id,
          name: booking.customer.name,
          email: booking.customer.email,
        } : null,
        routeProgress,
        currentLocation,
        eta,
        lastEvent: lastEvent || null,
        trackingPings: trackingPings.map(ping => ({
          id: ping.id,
          lat: ping.lat,
          lng: ping.lng,
          createdAt: ping.createdAt,
        })),
      },
    });
  } catch (error) {
    console.error('Error fetching tracking data:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';

export const dynamic = 'force-dynamic';

// POST /api/admin/orders/auto-notify-drivers - Auto notify available drivers about unassigned orders
export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    
    if (!session?.user || (session.user as any).role !== 'admin') {
      return NextResponse.json(
        { error: 'Unauthorized - Admin access required' },
        { status: 401 }
      );
    }

    console.log('🚀 Auto-notifying drivers about unassigned orders...');

    // Get unassigned orders older than 10 minutes
    const unassignedOrders = await prisma.booking.findMany({
      where: {
        status: 'CONFIRMED',
        driverId: null,
        createdAt: {
          lte: new Date(Date.now() - 10 * 60 * 1000) // Older than 10 minutes
        }
      },
      include: {
        pickupAddress: true,
        dropoffAddress: true,
        BookingItem: true,
      },
      orderBy: {
        createdAt: 'asc'
      },
      take: 5 // Limit to 5 orders at a time
    });

    if (unassignedOrders.length === 0) {
      return NextResponse.json({
        success: true,
        message: 'No unassigned orders found',
        ordersProcessed: 0
      });
    }

    console.log(`📢 Processing ${unassignedOrders.length} unassigned orders for driver notifications`);

    const results = [];

    // Process each order
    for (const order of unassignedOrders) {
      try {
        // Call the existing notify-drivers endpoint
        const notifyResponse = await fetch(`${request.nextUrl.origin}/api/admin/notify-drivers`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Cookie': request.headers.get('Cookie') || '',
          },
          body: JSON.stringify({
            bookingId: order.id
          })
        });

        const notifyResult = await notifyResponse.json();
        
        if (notifyResponse.ok) {
          results.push({
            orderId: order.id,
            orderReference: order.reference,
            success: true,
            driversNotified: notifyResult.driversNotified || 0,
            message: `Successfully notified drivers about order ${order.reference}`
          });
          
          console.log(`✅ Notified drivers about order ${order.reference} (${notifyResult.driversNotified || 0} drivers)`);
        } else {
          results.push({
            orderId: order.id,
            orderReference: order.reference,
            success: false,
            error: notifyResult.error || 'Unknown error',
            message: `Failed to notify drivers about order ${order.reference}`
          });
          
          console.error(`❌ Failed to notify drivers about order ${order.reference}:`, notifyResult.error);
        }

        // Small delay between notifications to avoid overwhelming the system
        await new Promise(resolve => setTimeout(resolve, 1000));

      } catch (error) {
        results.push({
          orderId: order.id,
          orderReference: order.reference,
          success: false,
          error: error instanceof Error ? error.message : 'Unknown error',
          message: `Error processing notifications for order ${order.reference}`
        });
        
        console.error(`❌ Error processing order ${order.reference}:`, error);
      }
    }

    const successCount = results.filter(r => r.success).length;
    const failCount = results.filter(r => !r.success).length;

    return NextResponse.json({
      success: true,
      message: `Processed ${unassignedOrders.length} unassigned orders`,
      ordersProcessed: unassignedOrders.length,
      successfulNotifications: successCount,
      failedNotifications: failCount,
      results: results,
      summary: {
        totalOrders: unassignedOrders.length,
        successful: successCount,
        failed: failCount,
        driversNotified: results.reduce((sum, r) => sum + (r.driversNotified || 0), 0)
      }
    });

  } catch (error) {
    console.error('❌ Error in auto-notify-drivers:', error);
    return NextResponse.json(
      { 
        error: 'Failed to auto-notify drivers',
        details: error instanceof Error ? error.message : 'Unknown error'
      },
      { status: 500 }
    );
  }
}

import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
import { NextResponse } from 'next/server';
import { logAudit } from '@/lib/audit';
import { unifiedEmailService } from '@/lib/email/UnifiedEmailService';
import { upsertAssignment } from '@/lib/utils/assignment-helpers';

export const dynamic = 'force-dynamic';

export async function POST(req: Request) {
  const s = await getServerSession(authOptions);
  if (!s?.user || (s.user as any).role !== 'admin') {
    return new Response('Unauthorized', { status: 401 });
  }

  try {
    const { orderIds, action, data } = await req.json();

    if (!orderIds || !Array.isArray(orderIds) || orderIds.length === 0) {
      return NextResponse.json(
        { error: 'Order IDs required' },
        { status: 400 }
      );
    }

    if (!action) {
      return NextResponse.json({ error: 'Action required' }, { status: 400 });
    }

    let errorCount = 0;
    const errors: string[] = [];

    switch (action) {
      case 'export':
        // Export orders to CSV format
        const orders = await prisma.booking.findMany({
          where: {
            id: { in: orderIds },
          },
          include: {
            customer: {
              select: {
                name: true,
                email: true,
              },
            },
            driver: {
              include: {
                User: {
                  select: {
                    name: true,
                  },
                },
              },
            },
            pickupAddress: true,
            dropoffAddress: true,
          },
        });

        const csvData = orders.map(order => ({
          reference: order.reference,
          status: order.status,
          customerName: order.customer?.name || 'Unknown',
          customerEmail: order.customer?.email || 'Unknown',
          pickupAddress: order.pickupAddress?.label || 'Unknown',
          dropoffAddress: order.dropoffAddress?.label || 'Unknown',
          amount: (order.totalGBP / 100).toFixed(2),
          driverName: order.driver?.User.name || 'Unassigned',
          createdAt: order.createdAt,
          scheduledAt: order.scheduledAt,
        }));

        return NextResponse.json({
          success: true,
          message: `Exported ${orders.length} orders`,
          data: csvData,
        });

      case 'email':
        // Send email to customers of selected orders
        const emailOrders = await prisma.booking.findMany({
          where: {
            id: { in: orderIds },
          },
          include: {
            customer: true,
          },
        });

        // Here you would integrate with your email service
        // For now, just return success
        return NextResponse.json({
          success: true,
          message: `Email notifications sent to ${emailOrders.length} customers`,
          count: emailOrders.length,
        });

      case 'assign':
        // Bulk assign orders to drivers
        const { driverId, autoAssign = false, reason } = data || {};

        if (!driverId && !autoAssign) {
          return NextResponse.json(
            { error: 'Driver ID or auto-assign required' },
            { status: 400 }
          );
        }

        for (const orderId of orderIds) {
          try {
            const booking = await prisma.booking.findUnique({
              where: { id: orderId },
              include: { driver: true },
            });

            if (!booking) {
              errorCount++;
              errors.push(`Order ${orderId} not found`);
              continue;
            }

            if (booking.driverId && !autoAssign) {
              errorCount++;
              errors.push(`Order ${booking.reference} already assigned`);
              continue;
            }

            let targetDriverId = driverId;

            // Auto-assign logic
            if (autoAssign || !driverId) {
              const availableDrivers = await prisma.driver.findMany({
                where: {
                  status: 'active',
                  onboardingStatus: 'approved',
                },
                include: {
                  Booking: {
                    where: {
                      status: {
                        in: ['CONFIRMED', 'COMPLETED'],
                      },
                    },
                  },
                },
                orderBy: [{ rating: 'desc' }, { createdAt: 'asc' }],
                take: 10,
              });

              const suitableDrivers = availableDrivers.filter(driver => {
                const activeJobs = driver.Booking.length;
                return activeJobs < 3;
              });

              if (suitableDrivers.length === 0) {
                errorCount++;
                errors.push(
                  `No suitable drivers available for order ${booking.reference}`
                );
                continue;
              }

              targetDriverId = suitableDrivers[0].id;
            }

            // Update booking
            await prisma.booking.update({
              where: { id: orderId },
              data: {
                driverId: targetDriverId,
                status: 'CONFIRMED',
              },
            });

            // Create or update assignment
            await upsertAssignment(prisma, orderId, {
              driverId: targetDriverId,
              status: 'invited',
              round: 1,
            });

            // SMS notification will be sent via individual assignment endpoint
            console.log(`✅ Order ${booking.reference} assigned to driver ${targetDriverId}`);

            // Log audit
            await logAudit((s.user as any).id, 'bulk_assign_driver', orderId, { targetType: 'booking', before: { driverId: booking.driverId, status: booking.status }, after: { driverId: targetDriverId, status: 'CONFIRMED' } });
          } catch (error) {
            errorCount++;
            errors.push(`Error processing order ${orderId}: ${error}`);
          }
        }

        return NextResponse.json({
          success: true,
          message: `Processed ${orderIds.length} orders with ${errorCount} errors`,
          errors: errors.length > 0 ? errors : undefined,
        });

      case 'cancel':
        // Bulk cancel orders
        for (const orderId of orderIds) {
          try {
            const booking = await prisma.booking.findUnique({
              where: { id: orderId },
            });

            if (!booking) {
              errorCount++;
              errors.push(`Order ${orderId} not found`);
              continue;
            }

            if (booking.status === 'CANCELLED') {
              errorCount++;
              errors.push(`Order ${booking.reference} already cancelled`);
              continue;
            }

            await prisma.booking.update({
              where: { id: orderId },
              data: { status: 'CANCELLED' },
            });

            // Log audit
            await logAudit((s.user as any).id, 'bulk_cancel_order', orderId, { targetType: 'booking', before: { status: booking.status }, after: { status: 'CANCELLED' } });
          } catch (error) {
            errorCount++;
            errors.push(`Error cancelling order ${orderId}: ${error}`);
          }
        }

        return NextResponse.json({
          success: true,
          message: `Cancelled ${orderIds.length - errorCount} orders with ${errorCount} errors`,
          errors: errors.length > 0 ? errors : undefined,
        });

      case 'send-floor-warnings':
        // Send floor warning emails to selected orders
        const floorWarningResults = [];
        let floorWarningsSent = 0;
        let floorWarningsSkipped = 0;

        for (const orderId of orderIds) {
          try {
            const booking = await prisma.booking.findUnique({
              where: { id: orderId },
              include: {
                pickupProperty: true,
                dropoffProperty: true,
              },
            });

            if (!booking) {
              errorCount++;
              errors.push(`Order ${orderId} not found`);
              continue;
            }

            const preferences = (booking.customerPreferences as any) || {};
            const pickupMeta = preferences?.pickupAddressMeta || {};
            const dropoffMeta = preferences?.dropoffAddressMeta || {};

            const result = await unifiedEmailService.sendFloorWarningIfNeeded({
              reference: booking.reference,
              customerEmail: booking.customerEmail,
              customerName: booking.customerName,
              pickupProperty: (booking as any).pickupProperty ? {
                floors: (booking as any).pickupProperty.floors,
                accessType: (booking as any).pickupProperty.accessType,
              } : undefined,
              dropoffProperty: (booking as any).dropoffProperty ? {
                floors: (booking as any).dropoffProperty.floors,
                accessType: (booking as any).dropoffProperty.accessType,
              } : undefined,
              pickupAddressMeta: pickupMeta,
              dropoffAddressMeta: dropoffMeta,
            });

            floorWarningResults.push({
              orderId,
              reference: booking.reference,
              sent: result.sent,
              message: result.message,
            });

            if (result.sent) {
              floorWarningsSent++;
              console.log(`✅ Floor warning sent for order ${booking.reference}`);
            } else {
              floorWarningsSkipped++;
              console.log(`⏭️ Skipped order ${booking.reference}: ${result.message}`);
            }
          } catch (error) {
            errorCount++;
            errors.push(`Error sending floor warning for order ${orderId}: ${error}`);
          }
        }

        return NextResponse.json({
          success: true,
          message: `Checked ${orderIds.length} orders. Sent ${floorWarningsSent} floor warnings.`,
          summary: {
            totalChecked: orderIds.length,
            sent: floorWarningsSent,
            skipped: floorWarningsSkipped,
            errors: errorCount,
          },
          results: floorWarningResults,
          errors: errors.length > 0 ? errors : undefined,
        });

      default:
        return NextResponse.json({ error: 'Invalid action' }, { status: 400 });
    }
  } catch (error) {
    console.error('Bulk operations error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

/**
 * GET /api/admin/orders/pending
 * 
 * Get all pending orders (confirmed but not assigned to routes)
 */

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';

export const dynamic = 'force-dynamic';

export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const page = parseInt(searchParams.get('page') || '1');
    const limit = parseInt(searchParams.get('limit') || '50');
    const sortBy = searchParams.get('sortBy') || 'scheduledAt';
    const sortOrder = searchParams.get('sortOrder') || 'asc';
    const filterEligible = searchParams.get('eligible'); // 'true', 'false', or null (all)
    const filterRegion = searchParams.get('region'); // Postcode prefix (e.g., "M1")
    const filterDate = searchParams.get('date'); // ISO date string

    const skip = (page - 1) * limit;

    // Build where clause
    const where: any = {
      status: 'CONFIRMED',
      routeId: null,
    };

    if (filterEligible !== null) {
      where.eligibleForMultiDrop = filterEligible === 'true';
    }

    if (filterDate) {
      const date = new Date(filterDate);
      const nextDay = new Date(date);
      nextDay.setDate(nextDay.getDate() + 1);
      
      where.scheduledAt = {
        gte: date,
        lt: nextDay,
      };
    }

    // Get pending bookings
    const bookings = await prisma.booking.findMany({
      where,
      include: {
        BookingItem: true,
        pickupAddress: true,
        dropoffAddress: true,
        customer: {
          select: {
            id: true,
            name: true,
            email: true,
          },
        },
      },
      orderBy: {
        [sortBy]: sortOrder,
      },
      skip,
      take: limit,
    });

    // Filter by region if specified
    let filteredBookings = bookings;
    if (filterRegion) {
      filteredBookings = bookings.filter(b => 
        b.pickupAddress.postcode.startsWith(filterRegion)
      );
    }

    // Get total count
    const total = await prisma.booking.count({ where });

    // Group by region and time window
    const groupedByRegion = new Map<string, any[]>();
    const groupedByTimeWindow = new Map<string, any[]>();

    for (const booking of filteredBookings) {
      const region = booking.pickupAddress.postcode.split(' ')[0];
      const hour = booking.scheduledAt.getHours();
      const timeWindow = 
        hour < 10 ? 'morning' :
        hour < 14 ? 'midday' :
        hour < 18 ? 'afternoon' : 'evening';

      if (!groupedByRegion.has(region)) {
        groupedByRegion.set(region, []);
      }
      groupedByRegion.get(region)!.push(booking);

      if (!groupedByTimeWindow.has(timeWindow)) {
        groupedByTimeWindow.set(timeWindow, []);
      }
      groupedByTimeWindow.get(timeWindow)!.push(booking);
    }

    // Calculate statistics
    const stats = {
      total,
      eligible: filteredBookings.filter(b => b.eligibleForMultiDrop).length,
      ineligible: filteredBookings.filter(b => !b.eligibleForMultiDrop).length,
      byRegion: Array.from(groupedByRegion.entries()).map(([region, bookings]) => ({
        region,
        count: bookings.length,
        eligible: bookings.filter(b => b.eligibleForMultiDrop).length,
      })),
      byTimeWindow: Array.from(groupedByTimeWindow.entries()).map(([window, bookings]) => ({
        window,
        count: bookings.length,
        eligible: bookings.filter(b => b.eligibleForMultiDrop).length,
      })),
      potentialSavings: filteredBookings
        .filter(b => b.potentialSavings)
        .reduce((sum, b) => sum + (b.potentialSavings || 0), 0),
    };

    return NextResponse.json({
      success: true,
      data: {
        bookings: filteredBookings,
        pagination: {
          page,
          limit,
          total,
          totalPages: Math.ceil(total / limit),
        },
        stats,
      },
    });
  } catch (error) {
    console.error('Error fetching pending orders:', error);
    return NextResponse.json(
      { success: false, error: 'Failed to fetch pending orders' },
      { status: 500 }
    );
  }
}

import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
import { logAudit } from '@/lib/audit';
import { deriveServiceMetadata } from '@/lib/bookings/serviceType';

export const dynamic = 'force-dynamic';

export async function GET(req: Request) {
  // Parse parameters outside try block for error logging
  const { searchParams } = new URL(req.url);
  const q = searchParams.get('q');
  const status = searchParams.get('status') as any;
  const driver = searchParams.get('driver');
  const area = searchParams.get('area');
  const dateRange = searchParams.get('dateRange');
  const includeTracking = searchParams.get('includeTracking') === 'true';
  const take = Math.min(parseInt(searchParams.get('take') || '50'), 500); // Limit to max 500
  const cursor = searchParams.get('cursor');

  try {
    const s = await getServerSession(authOptions);
    if (!s?.user || (s.user as any).role !== 'admin') {
      return new Response('Unauthorized', { status: 401 });
    }

  // Build date filter
  let dateFilter = {};
  if (dateRange) {
    const now = new Date();
    switch (dateRange) {
      case 'today':
        const todayStart = new Date(
          now.getFullYear(),
          now.getMonth(),
          now.getDate()
        );
        dateFilter = {
          createdAt: {
            gte: todayStart,
          },
        };
        break;
      case 'week':
        const weekStart = new Date(
          now.getTime() - now.getDay() * 24 * 60 * 60 * 1000
        );
        dateFilter = {
          createdAt: {
            gte: weekStart,
          },
        };
        break;
      case 'month':
        const monthStart = new Date(now.getFullYear(), now.getMonth(), 1);
        dateFilter = {
          createdAt: {
            gte: monthStart,
          },
        };
        break;
    }
  }

  // Map status parameter to valid BookingStatus values
  let statusFilter = {};
  if (status) {
    switch (status.toLowerCase()) {
      case 'active':
        statusFilter = {
          status: {
            in: ['CONFIRMED'], // Active means confirmed bookings
          },
        };
        break;
      case 'pending':
        statusFilter = {
          status: {
            in: ['DRAFT', 'PENDING_PAYMENT'],
          },
        };
        break;
      case 'completed':
        statusFilter = { status: 'COMPLETED' };
        break;
      case 'cancelled':
        statusFilter = { status: 'CANCELLED' };
        break;
      case 'open':
        statusFilter = {
          status: {
            in: ['DRAFT', 'PENDING_PAYMENT', 'CONFIRMED'], // Open means active bookings
          },
        };
        break;
      default:
        // Invalid status, ignore filter
        statusFilter = {};
        break;
    }
  }

  const orders = await prisma.booking.findMany({
    where: {
      ...statusFilter,
      ...(driver
        ? {
            driver: {
              User: {
                name: { contains: driver, mode: 'insensitive' },
              },
            },
          }
        : {}),
      ...(area
        ? {
            OR: [
              {
                pickupAddress: {
                  label: { contains: area, mode: 'insensitive' as any },
                },
              },
              {
                dropoffAddress: {
                  label: { contains: area, mode: 'insensitive' as any },
                },
              },
            ],
          }
        : {}),
      ...(q
        ? {
            OR: [
              { reference: { contains: q, mode: 'insensitive' as any } },
              {
                pickupAddress: { label: { contains: q, mode: 'insensitive' as any } },
              },
              {
                dropoffAddress: { label: { contains: q, mode: 'insensitive' as any } },
              },
              { customerName: { contains: q, mode: 'insensitive' as any } },
              { customerEmail: { contains: q, mode: 'insensitive' as any } },
            ],
          }
        : {}),
      ...dateFilter,
    },
    include: {
      customer: {
        select: {
          id: true,
          name: true,
          email: true,
        },
      },
      driver: {
        include: {
          User: {
            select: {
              id: true,
              name: true,
              email: true,
            },
          },
        },
      },
      pickupAddress: true,
      dropoffAddress: true,
      pickupProperty: true,
      dropoffProperty: true,
      route: {
        select: {
          id: true,
          reference: true,
          status: true,
          totalDrops: true,
        },
      },
      Assignment: {
        include: {
          Driver: {
            include: {
              User: {
                select: {
                  id: true,
                  name: true,
                  email: true,
                },
              },
            },
          },
          ...(includeTracking && {
            JobEvent: {
              orderBy: {
                createdAt: 'desc',
              },
              take: 10,
            },
          }),
        },
      },
      ...(includeTracking && {
        TrackingPing: {
          orderBy: {
            createdAt: 'desc',
          },
          take: 20,
        },
      }),
    },
    orderBy: { createdAt: 'desc' },
    take: take,
    ...(cursor ? { skip: 1, cursor: { id: cursor } } : {}),
  });

  const ordersWithMeta = orders.map(order => ({
    raw: order,
    meta: deriveServiceMetadata(order),
  }));

  const filteredOrders = ordersWithMeta.filter(({ meta }) => !meta.isEconomy);
  const excludedEconomyCount = ordersWithMeta.length - filteredOrders.length;

  // Log audit action (non-blocking)
  try {
    await logAudit({
      userId: (s.user as any).id,
      action: 'read_orders',
      entityType: 'booking',
      details: {
        count: orders.length,
        q,
        status,
        driver,
        area,
        dateRange,
        take,
        excludedEconomyCount,
      },
    });
  } catch (auditError) {
    // Don't fail the request if audit logging fails
    console.error('Failed to log audit:', auditError);
  }

    const nextCursor =
      orders.length === take ? orders[orders.length - 1].id : null;
    
    console.log('✅ Orders fetched successfully:', {
      count: filteredOrders.length,
      status,
      includeTracking,
      hasNextCursor: !!nextCursor,
      excludedEconomyCount,
    });

    // Transform orders to include serviceType and orderType
    const transformedOrders = filteredOrders.map(({ raw, meta }) => ({
      ...raw,
      serviceType:
        meta.serviceType ||
        (raw.customerPreferences as any)?.serviceType ||
        (raw.customerPreferences as any)?.serviceLevel ||
        'standard',
      orderType: raw.orderType || (raw.isMultiDrop ? 'multi-drop' : 'single'),
      isMultiDrop: raw.isMultiDrop || false,
    }));

    return Response.json({ items: transformedOrders, nextCursor });
  } catch (error) {
    console.error('❌ Error fetching admin orders:', {
      error,
      message: error instanceof Error ? error.message : 'Unknown error',
      stack: error instanceof Error ? error.stack : undefined,
      name: error instanceof Error ? error.name : undefined,
      params: { status, includeTracking, q, driver, area, dateRange, take }
    });
    
    // Return more detailed error in development
    const isDev = process.env.NODE_ENV === 'development';
    return Response.json(
      { 
        error: 'Failed to fetch orders',
        details: error instanceof Error ? error.message : 'Unknown error',
        ...(isDev && error instanceof Error ? { stack: error.stack } : {})
      },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

export async function GET(request: NextRequest) {
  try {
    // Check admin authorization
    const session = await getServerSession(authOptions);
    if (!session?.user) {
      return NextResponse.json(
        { error: 'Unauthorized - Please login' },
        { status: 401 }
      );
    }

    const userRole = (session.user as any)?.role;
    if (userRole !== 'admin') {
      return NextResponse.json(
        { error: 'Forbidden - Admin access required' },
        { status: 403 }
      );
    }

    // Get date boundaries for this month
    const now = new Date();
    const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
    const endOfMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0);

    // Get all people statistics in parallel
    const [
      totalDrivers,
      activeDrivers,
      pendingApplications,
      totalCustomers,
      activeCustomers,
      newCustomersThisMonth,
    ] = await Promise.all([
      // Total drivers
      prisma.driver.count(),
      
      // Active drivers (online in last 24 hours)
      prisma.driver.count({
        where: {
          status: 'active',
          onboardingStatus: 'approved',
        },
      }),
      
      // Pending driver applications
      prisma.driverApplication.count({
        where: {
          status: 'pending',
        },
      }),
      
      // Total customers
      prisma.user.count({
        where: {
          role: 'customer',
        },
      }),
      
      // Active customers (made booking in last 30 days)
      prisma.user.count({
        where: {
          role: 'customer',
          Booking: {
            some: {
              createdAt: {
                gte: new Date(Date.now() - 30 * 24 * 60 * 60 * 1000), // Last 30 days
              },
            },
          },
        },
      }),
      
      // New customers this month
      prisma.user.count({
        where: {
          role: 'customer',
          createdAt: {
            gte: startOfMonth,
            lte: endOfMonth,
          },
        },
      }),
    ]);

    const stats = {
      totalDrivers,
      activeDrivers,
      pendingApplications,
      totalCustomers,
      activeCustomers,
      newCustomersThisMonth,
    };

    console.log('✅ People stats loaded:', stats);

    return NextResponse.json(stats);
  } catch (error) {
    console.error('❌ Error loading people stats:', error);
    return NextResponse.json(
      { error: 'Failed to load people statistics' },
      { status: 500 }
    );
  }
}

import { NextResponse, NextRequest } from 'next/server';
import { requireAdmin } from '@/lib/auth';
import { prisma } from '@/lib/prisma';

export async function GET(request: NextRequest) {
    const authResult = await requireAdmin(request);
    if (authResult instanceof NextResponse) {
      return authResult;
    }
    const user = authResult;

  try {
    const { searchParams } = new URL(request.url);
    const driverId = searchParams.get('driverId');
    const type = searchParams.get('type'); // "ratings" | "incidents" | "performance"

    if (driverId) {
      // Get specific driver data
      const driver = await prisma.driver.findUnique({
        where: { id: driverId },
        include: {
          User: {
            select: {
              id: true,
              name: true,
              email: true,
              role: true,
              createdAt: true,
              isActive: true
            }
          },
          DriverPerformance: true,
          DriverRating: {
            where: { status: 'active' },
            orderBy: { createdAt: 'desc' },
            take: 50,
          },
          DriverIncident: {
            orderBy: { createdAt: 'desc' },
            take: 50,
          },
          Assignment: {
            include: {
              Booking: {
                select: {
                  reference: true,
                  pickupAddress: true,
                  dropoffAddress: true,
                  scheduledAt: true,
                },
              },
            },
            orderBy: { createdAt: 'desc' },
          },
        },
      });

      if (!driver) {
        return NextResponse.json(
          { error: 'Driver not found' },
          { status: 404 }
        );
      }

      return NextResponse.json({
        driver: {
          id: driver.id,
          name: driver.User?.name || '',
          email: driver.User?.email || '',
          status: driver.status,
          onboardingStatus: driver.onboardingStatus,
        },
        performance: driver.DriverPerformance,
        ratings: driver.DriverRating,
        incidents: driver.DriverIncident,
        Assignment: driver.Assignment,
      });
    }

    // Get all drivers with performance data
    const drivers = await prisma.driver.findMany({
      include: {
        User: {
          select: {
            name: true,
            email: true,
          },
        },
        DriverPerformance: true,
        _count: {
          select: {
            DriverRating: {
              where: { status: 'active' },
            },
            DriverIncident: true,
            Assignment: {
              where: { status: 'completed' },
            },
          },
        },
      },
      orderBy: {
        createdAt: 'desc'
      },
    });

    return NextResponse.json({
      drivers: drivers.map(driver => ({
        id: driver.id,
        name: driver.User?.name || '',
        email: driver.User?.email || '',
        status: driver.status,
        onboardingStatus: driver.onboardingStatus,
        performance: driver.DriverPerformance,
        stats: {
          totalRatings: (driver._count as any).DriverRating,
          totalIncidents: (driver._count as any).DriverIncident,
          completedJobs: driver._count.Assignment,
        },
      })),
    });
  } catch (error) {
    console.error('Admin performance API error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

export async function PUT(request: NextRequest) {
    const authResult = await requireAdmin(request);
    if (authResult instanceof NextResponse) {
      return authResult;
    }
    const user = authResult;

  try {
    const body = await request.json();
    const { action, targetId, data } = body;

    switch (action) {
      case 'update_rating_status':
        const { ratingId, status, moderationNotes } = data;
        const updatedRating = await prisma.driverRating.update({
          where: { id: ratingId },
          data: {
            status,
            moderationNotes,
            moderatedAt: new Date(),
            moderatedBy: user.id,
          },
        });

        // Log audit event
        await prisma.auditLog.create({
          data: {
            actorId: user.id,
            actorRole: 'admin',
            action: 'rating_moderated',
            targetType: 'DriverRating',
            targetId: ratingId,
            after: { status, moderationNotes },
          },
        });

        return NextResponse.json({ rating: updatedRating });

      case 'update_incident_status':
        const {
          incidentId,
          status: incidentStatus,
          reviewNotes,
          resolution,
        } = data;
        const updatedIncident = await prisma.driverIncident.update({
          where: { id: incidentId },
          data: {
            status: incidentStatus,
            reviewNotes,
            resolution,
            reviewedAt: new Date(),
            reviewedBy: user.id,
          },
        });

        // Log audit event
        await prisma.auditLog.create({
          data: {
            actorId: user.id,
            actorRole: 'admin',
            action: 'incident_reviewed',
            targetType: 'DriverIncident',
            targetId: incidentId,
            after: { status: incidentStatus, reviewNotes, resolution },
          },
        });

        return NextResponse.json({ incident: updatedIncident });

      default:
        return NextResponse.json({ error: 'Invalid action' }, { status: 400 });
    }
  } catch (error) {
    console.error('Admin performance PUT API error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
import { NextRequest, NextResponse } from 'next/server';
import { logAudit } from '@/lib/audit';

export const dynamic = 'force-dynamic';

export async function GET(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user || (session.user as any).role !== 'admin') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const { searchParams } = new URL(request.url);
    const page = parseInt(searchParams.get('page') || '1');
    const limit = parseInt(searchParams.get('limit') || '50');
    const status = searchParams.get('status');
    const fromDate = searchParams.get('fromDate');
    const toDate = searchParams.get('toDate');
    const reason = searchParams.get('reason');

    const skip = (page - 1) * limit;

    // Build where clause
    const where: any = {};
    if (status) where.status = status;
    if (reason) where.reason = { contains: reason, mode: 'insensitive' };
    if (fromDate || toDate) {
      where.createdAt = {};
      if (fromDate) where.createdAt.gte = new Date(fromDate);
      if (toDate) where.createdAt.lte = new Date(toDate);
    }

    // Get refunds with pagination
    const [refunds, total] = await Promise.all([
      prisma.refund.findMany({
        where,
        include: {
          Payment: {
            include: {
              Booking: true,
            },
          },
        },
        orderBy: {
          createdAt: 'desc',
        },
        skip,
        take: limit,
      }),
      prisma.refund.count({ where }),
    ]);

    // Get summary statistics
    const summary = await prisma.refund.aggregate({
      _sum: {
        amount: true,
      },
      _count: {
        id: true,
      },
      where: {
        status: 'completed',
      },
    });

    // Get refund reasons breakdown
    const reasonsBreakdown = await prisma.refund.groupBy({
      by: ['reason'],
      _sum: {
        amount: true,
      },
      _count: {
        id: true,
      },
      where: {
        status: 'completed',
      },
    });

    return NextResponse.json({
      refunds: refunds.map(refund => ({
        id: refund.id,
        paymentId: refund.paymentId,
        bookingCode: refund.Payment.Booking?.reference,
        customer: {
          name: refund.Payment.Booking?.customerName || 'Unknown',
          email: refund.Payment.Booking?.customerEmail || 'Unknown',
        },
        amount: refund.amount,
        reason: refund.reason,
        status: refund.status,
        processedAt: refund.processedAt,
        createdAt: refund.createdAt,
        metadata: refund.metadata,
      })),
      pagination: {
        page,
        limit,
        total,
        pages: Math.ceil(total / limit),
      },
      summary: {
        totalRefunds: summary._sum.amount || 0,
        refundCount: summary._count.id || 0,
        reasonsBreakdown: reasonsBreakdown.map(item => ({
          reason: item.reason,
          amount: item._sum.amount || 0,
          count: item._count.id || 0,
        })),
      },
    });
  } catch (error) {
    console.error('Refunds API error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user || (session.user as any).role !== 'admin') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const body = await request.json();
    const { paymentId, amount, reason, notes, type = 'full' } = body;

    if (!paymentId || !amount || !reason) {
      return NextResponse.json(
        { error: 'Payment ID, amount, and reason are required' },
        { status: 400 }
      );
    }

    // Get payment details
    const payment = await prisma.payment.findUnique({
      where: { id: paymentId },
      include: {
        Booking: true,
        Refund: true,
      },
    });

    if (!payment) {
      return NextResponse.json({ error: 'Payment not found' }, { status: 404 });
    }

    if (payment.status !== 'paid') {
      return NextResponse.json(
        { error: 'Payment is not in paid status' },
        { status: 400 }
      );
    }

    // Check if refund amount is valid
    const totalRefunded = payment.Refund.reduce(
      (sum, refund) => sum + refund.amount,
      0
    );
    const remainingAmount = payment.amount - totalRefunded;

    if (amount > remainingAmount) {
      return NextResponse.json(
        { error: 'Refund amount exceeds remaining payment amount' },
        { status: 400 }
      );
    }

    // Create refund
    const refund = await prisma.refund.create({
      data: {
        id: `refund_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
        paymentId: paymentId,
        amount: amount,
        reason: reason,
        status: 'pending',
        processedAt: new Date(),
        updatedAt: new Date(),
        metadata: {
          type,
          notes,
          processedBy: (session.user as any).id,
        },
      },
      include: {
        Payment: {
          include: {
            Booking: true,
          },
        },
      },
    });

    // Log audit
    await logAudit((session.user as any).id, 'create_refund', refund.id, { targetType: 'refund', before: null, after: { paymentId, amount, reason, type } });

    return NextResponse.json({
      success: true,
      refund: {
        id: refund.id,
        paymentId: refund.paymentId,
        bookingCode: refund.Payment.Booking?.reference,
        customer: {
          name: refund.Payment.Booking?.customerName || 'Unknown',
          email: refund.Payment.Booking?.customerEmail || 'Unknown',
        },
        amount: refund.amount,
        reason: refund.reason,
        status: refund.status,
        processedAt: refund.processedAt,
        createdAt: refund.createdAt,
      },
    });
  } catch (error) {
    console.error('Create refund API error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

/**
 * Route Analytics API
 * 
 * Provides comprehensive analytics and insights for a specific route:
 * - Performance metrics
 * - Cost analysis
 * - Efficiency scores
 * - Comparison with similar routes
 * - Optimization suggestions
 */

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
import { logger } from '@/lib/logger';

export const dynamic = 'force-dynamic';

/**
 * GET /api/admin/routes/[id]/analytics
 * Get comprehensive analytics for a route
 */
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user || (session.user as any).role !== 'admin') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const { id: routeId } = await params;

    // Get route with all related data
    const route = await prisma.route.findUnique({
      where: { id: routeId },
      include: {
        driver: {
          select: {
            id: true,
            name: true,
            email: true,
          },
        },
        drops: {
          include: {
            Booking: {
              select: {
                id: true,
                reference: true,
                totalGBP: true,
              },
            },
          },
          orderBy: { timeWindowStart: 'asc' },
        },
      },
    });

    if (!route) {
      return NextResponse.json(
        { error: 'Route not found' },
        { status: 404 }
      );
    }

    // Calculate performance metrics
    const performanceMetrics = calculatePerformanceMetrics(route);

    // Calculate cost analysis
    const costAnalysis = calculateCostAnalysis(route);

    // Calculate efficiency scores
    const efficiencyScores = calculateEfficiencyScores(route);

    // Get comparison with similar routes
    const comparison = await getRouteComparison(route);

    // Generate optimization suggestions
    const suggestions = generateOptimizationSuggestions(route, performanceMetrics, efficiencyScores);

    // Calculate timeline
    const timeline = calculateTimeline(route);

    // Calculate drop statistics
    const dropStats = calculateDropStatistics(route);

    logger.info('Route analytics retrieved', {
      routeId,
      adminId: (session.user as any).id,
    });

    return NextResponse.json({
      success: true,
      data: {
        route: {
          id: route.id,
          reference: route.reference,
          status: route.status,
          startTime: route.startTime,
          endTime: route.endTime,
          totalDrops: route.totalDrops,
          completedDrops: route.completedDrops,
        },
        performanceMetrics,
        costAnalysis,
        efficiencyScores,
        comparison,
        suggestions,
        timeline,
        dropStats,
      },
    });

  } catch (error) {
    logger.error('Failed to get route analytics', error as Error);
    return NextResponse.json(
      {
        error: 'Failed to get route analytics',
        details: error instanceof Error ? error.message : 'Unknown error',
      },
      { status: 500 }
    );
  }
}

// Analytics Calculation Functions

function calculatePerformanceMetrics(route: any) {
  const completionRate = route.totalDrops > 0 
    ? (route.completedDrops / route.totalDrops) * 100 
    : 0;

  const onTimeDeliveries = route.drops.filter((drop: any) => {
    if (!drop.completedAt || !drop.timeWindowEnd) return false;
    return new Date(drop.completedAt) <= new Date(drop.timeWindowEnd);
  }).length;

  const onTimeRate = route.completedDrops > 0
    ? (onTimeDeliveries / route.completedDrops) * 100
    : 0;

  const averageDelay = route.drops
    .filter((drop: any) => drop.completedAt && drop.timeWindowEnd)
    .reduce((sum: number, drop: any) => {
      const delay = Math.max(0, 
        (new Date(drop.completedAt).getTime() - new Date(drop.timeWindowEnd).getTime()) / 60000
      );
      return sum + delay;
    }, 0) / (route.completedDrops || 1);

  const estimatedDuration = route.estimatedDuration || 0;
  const actualDuration = route.actualDuration || 
    (route.endTime && route.startTime 
      ? (new Date(route.endTime).getTime() - new Date(route.startTime).getTime()) / 60000
      : 0);

  const durationVariance = estimatedDuration > 0
    ? ((actualDuration - estimatedDuration) / estimatedDuration) * 100
    : 0;

  return {
    completionRate: Math.round(completionRate * 100) / 100,
    onTimeRate: Math.round(onTimeRate * 100) / 100,
    averageDelay: Math.round(averageDelay * 100) / 100,
    estimatedDuration,
    actualDuration: Math.round(actualDuration),
    durationVariance: Math.round(durationVariance * 100) / 100,
    totalDrops: route.totalDrops,
    completedDrops: route.completedDrops,
    failedDrops: route.drops.filter((d: any) => d.status === 'failed').length,
  };
}

function calculateCostAnalysis(route: any) {
  const totalRevenue = route.drops.reduce(
    (sum: number, drop: any) => sum + (Number(drop.quotedPrice) || 0),
    0
  );

  const fuelCost = Number(route.fuelCost) || 0;
  const tollCost = Number(route.tollCost) || 0;
  const driverPayout = Number(route.driverPayout) || 0;
  const bonuses = Number(route.bonusesTotal) || 0;
  const penalties = Number(route.penaltiesTotal) || 0;

  const totalCosts = fuelCost + tollCost + driverPayout + bonuses;
  const netProfit = totalRevenue - totalCosts + penalties;
  const profitMargin = totalRevenue > 0 ? (netProfit / totalRevenue) * 100 : 0;

  const costPerDrop = route.totalDrops > 0 ? totalCosts / route.totalDrops : 0;
  const revenuePerDrop = route.totalDrops > 0 ? totalRevenue / route.totalDrops : 0;

  const distanceKm = route.optimizedDistanceKm || route.actualDistanceKm || 0;
  const costPerKm = distanceKm > 0 ? totalCosts / distanceKm : 0;

  return {
    totalRevenue: Math.round(totalRevenue) / 100,
    totalCosts: Math.round(totalCosts) / 100,
    netProfit: Math.round(netProfit) / 100,
    profitMargin: Math.round(profitMargin * 100) / 100,
    breakdown: {
      fuelCost: Math.round(fuelCost) / 100,
      tollCost: Math.round(tollCost) / 100,
      driverPayout: Math.round(driverPayout) / 100,
      bonuses: Math.round(bonuses) / 100,
      penalties: Math.round(penalties) / 100,
    },
    perDrop: {
      cost: Math.round(costPerDrop) / 100,
      revenue: Math.round(revenuePerDrop) / 100,
    },
    costPerKm: Math.round(costPerKm * 100) / 100,
  };
}

function calculateEfficiencyScores(route: any) {
  // Distance efficiency
  const estimatedDistance = route.optimizedDistanceKm || 0;
  const actualDistance = route.actualDistanceKm || estimatedDistance;
  const distanceEfficiency = estimatedDistance > 0
    ? Math.min(100, (estimatedDistance / actualDistance) * 100)
    : 0;

  // Time efficiency
  const estimatedTime = route.estimatedDuration || 0;
  const actualTime = route.actualDuration || 
    (route.endTime && route.startTime 
      ? (new Date(route.endTime).getTime() - new Date(route.startTime).getTime()) / 60000
      : 0);
  const timeEfficiency = estimatedTime > 0 && actualTime > 0
    ? Math.min(100, (estimatedTime / actualTime) * 100)
    : 0;

  // Drop density (drops per km)
  const dropDensity = actualDistance > 0 ? route.totalDrops / actualDistance : 0;

  // Optimization score
  const optimizationScore = route.optimizationScore 
    ? route.optimizationScore * 100 
    : 0;

  // Overall efficiency (weighted average)
  const overallEfficiency = (
    distanceEfficiency * 0.3 +
    timeEfficiency * 0.3 +
    (route.completedDrops / route.totalDrops) * 100 * 0.4
  );

  return {
    overall: Math.round(overallEfficiency * 100) / 100,
    distance: Math.round(distanceEfficiency * 100) / 100,
    time: Math.round(timeEfficiency * 100) / 100,
    dropDensity: Math.round(dropDensity * 100) / 100,
    optimization: Math.round(optimizationScore * 100) / 100,
    rating: getEfficiencyRating(overallEfficiency),
  };
}

function getEfficiencyRating(score: number): string {
  if (score >= 90) return 'Excellent';
  if (score >= 75) return 'Good';
  if (score >= 60) return 'Average';
  if (score >= 40) return 'Below Average';
  return 'Poor';
}

async function getRouteComparison(route: any) {
  // Get similar routes (same service tier, similar drop count, completed in last 30 days)
  const similarRoutes = await prisma.route.findMany({
    where: {
      serviceTier: route.serviceTier,
      totalDrops: {
        gte: route.totalDrops - 2,
        lte: route.totalDrops + 2,
      },
      status: 'completed',
      startTime: {
        gte: new Date(Date.now() - 30 * 24 * 60 * 60 * 1000),
      },
      id: { not: route.id },
    },
    take: 10,
  });

  if (similarRoutes.length === 0) {
    return {
      available: false,
      message: 'No similar routes found for comparison',
    };
  }

  const avgCompletionRate = similarRoutes.reduce(
    (sum, r) => sum + (r.completedDrops / r.totalDrops) * 100,
    0
  ) / similarRoutes.length;

  const avgDuration = similarRoutes.reduce(
    (sum, r) => sum + (r.actualDuration || 0),
    0
  ) / similarRoutes.length;

  const avgDistance = similarRoutes.reduce(
    (sum, r) => sum + (r.actualDistanceKm || 0),
    0
  ) / similarRoutes.length;

  const currentCompletionRate = (route.completedDrops / route.totalDrops) * 100;
  const currentDuration = route.actualDuration || 0;
  const currentDistance = route.actualDistanceKm || 0;

  return {
    available: true,
    similarRoutesCount: similarRoutes.length,
    averages: {
      completionRate: Math.round(avgCompletionRate * 100) / 100,
      duration: Math.round(avgDuration),
      distance: Math.round(avgDistance * 100) / 100,
    },
    current: {
      completionRate: Math.round(currentCompletionRate * 100) / 100,
      duration: currentDuration,
      distance: currentDistance,
    },
    comparison: {
      completionRate: Math.round((currentCompletionRate - avgCompletionRate) * 100) / 100,
      duration: Math.round(currentDuration - avgDuration),
      distance: Math.round((currentDistance - avgDistance) * 100) / 100,
    },
  };
}

function generateOptimizationSuggestions(route: any, metrics: any, efficiency: any) {
  const suggestions: Array<{ type: string; priority: string; message: string; impact: string }> = [];

  // Completion rate suggestions
  if (metrics.completionRate < 90) {
    suggestions.push({
      type: 'completion',
      priority: 'high',
      message: 'Completion rate is below target. Consider reviewing drop assignments and driver capacity.',
      impact: 'Improve completion rate by 10-15%',
    });
  }

  // On-time delivery suggestions
  if (metrics.onTimeRate < 85) {
    suggestions.push({
      type: 'timing',
      priority: 'high',
      message: 'On-time delivery rate is low. Review time windows and route optimization.',
      impact: 'Reduce average delay by 20-30%',
    });
  }

  // Distance efficiency suggestions
  if (efficiency.distance < 80) {
    suggestions.push({
      type: 'distance',
      priority: 'medium',
      message: 'Route distance is higher than optimal. Consider reordering drops for better efficiency.',
      impact: 'Reduce distance by 10-15%',
    });
  }

  // Drop density suggestions
  if (efficiency.dropDensity < 0.5) {
    suggestions.push({
      type: 'density',
      priority: 'medium',
      message: 'Drop density is low. Consider adding more drops to this route or splitting into smaller routes.',
      impact: 'Improve cost efficiency by 15-20%',
    });
  }

  // Duration variance suggestions
  if (Math.abs(metrics.durationVariance) > 20) {
    suggestions.push({
      type: 'duration',
      priority: 'low',
      message: 'Actual duration varies significantly from estimate. Review time estimates and traffic patterns.',
      impact: 'Improve scheduling accuracy by 15-20%',
    });
  }

  return suggestions;
}

function calculateTimeline(route: any) {
  const events: Array<{ time: Date; event: string; status: string }> = [];

  events.push({
    time: route.createdAt,
    event: 'Route Created',
    status: 'info',
  });

  if (route.acceptedAt) {
    events.push({
      time: route.acceptedAt,
      event: 'Driver Accepted',
      status: 'success',
    });
  }

  events.push({
    time: route.startTime,
    event: 'Scheduled Start',
    status: 'info',
  });

  // Add drop events
  route.drops.forEach((drop: any) => {
    if (drop.completedAt) {
      events.push({
        time: drop.completedAt,
        event: `Drop Completed: ${drop.deliveryAddress}`,
        status: drop.status === 'delivered' ? 'success' : 'error',
      });
    }
  });

  if (route.endTime) {
    events.push({
      time: route.endTime,
      event: 'Route Completed',
      status: 'success',
    });
  }

  return events.sort((a, b) => a.time.getTime() - b.time.getTime());
}

function calculateDropStatistics(route: any) {
  const drops = route.drops;

  const statusCounts = {
    pending: 0,
    assigned_to_route: 0,
    picked_up: 0,
    in_transit: 0,
    delivered: 0,
    failed: 0,
  };

  drops.forEach((drop: any) => {
    if (statusCounts.hasOwnProperty(drop.status)) {
      statusCounts[drop.status as keyof typeof statusCounts]++;
    }
  });

  const totalValue = drops.reduce(
    (sum: number, drop: any) => sum + (Number(drop.quotedPrice) || 0),
    0
  );

  const averageValue = drops.length > 0 ? totalValue / drops.length : 0;

  const totalWeight = drops.reduce(
    (sum: number, drop: any) => sum + (drop.weight || 0),
    0
  );

  const totalVolume = drops.reduce(
    (sum: number, drop: any) => sum + (drop.volume || 0),
    0
  );

  return {
    total: drops.length,
    byStatus: statusCounts,
    totalValue: Math.round(totalValue) / 100,
    averageValue: Math.round(averageValue) / 100,
    totalWeight: Math.round(totalWeight * 100) / 100,
    totalVolume: Math.round(totalVolume * 100) / 100,
  };
}

