            bookingId: booking.id,
            bookingReference: booking.reference,
            assignedTo: driver.User?.name || 'Unknown',
            message: 'This job has been assigned to a route',
            reason: 'route_created',
          });
        }
        console.log(`📡 Notified other drivers about ${bookingsInRoute.length} jobs removed from pool`);

        // Notify admin dashboard
        await pusher.trigger('admin-notifications', 'route-assigned', {
          routeId: result.updatedRoute.id,
          driverName: driver.User?.name || 'Unknown',
          bookingsCount: result.bookingsCount,
          assignedAt: new Date().toISOString(),
        });

        console.log('✅ Real-time notifications sent for route assignment');
      } catch (notificationError) {
        console.error('❌ Error sending real-time notifications:', notificationError);
        console.error('❌ Error stack:', notificationError instanceof Error ? notificationError.stack : 'No stack');
        // Don't fail the request if notifications fail
      }

      // Create audit log
      await prisma.auditLog.create({
        data: {
          actorId: (session.user as any).id,
          actorRole: 'admin',
          action: 'route_assigned',
          targetType: 'route',
          targetId: routeId,
          details: {
            driverId: driverId,
            driverName: driver.User?.name || 'Unknown',
            bookingsCount: result.bookingsCount,
            dropsCount: (result.updatedRoute as any).drops.length,
            reason: reason || 'Assigned by admin',
            assignedAt: new Date().toISOString(),
          }
        }
      });

      return NextResponse.json({
        success: true,
        message: `Route with ${result.bookingsCount} jobs assigned successfully`,
        data: {
          routeId: result.updatedRoute.id,
          driver: {
            id: driver.id,
            name: driver.User?.name || 'Unknown',
            email: driver.User?.email || '',
          },
          bookingsCount: result.bookingsCount,
          dropsCount: (result.updatedRoute as any).drops.length,
          totalDistance: result.updatedRoute.optimizedDistanceKm,
          estimatedDuration: result.updatedRoute.estimatedDuration,
          assignedAt: new Date().toISOString(),
        }
      });
    });

  } catch (error) {
    console.error('❌ Error assigning route to driver:', error);
    return NextResponse.json(
      {
        error: 'Failed to assign route',
        details: error instanceof Error ? error.message : 'Unknown error',
      },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
import { getPusherServer } from '@/lib/pusher';

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user || (session.user as any).role !== 'admin') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const { id: routeId } = await params;

    // Check if route exists
    const route = await prisma.route.findUnique({
      where: { id: routeId },
      include: {
        drops: true,
        Booking: true,
      },
    });

    if (!route) {
      return NextResponse.json({ error: 'Route not found' }, { status: 404 });
    }

    // Cannot cancel completed routes
    if (route.status === 'completed' || route.status === 'closed') {
      return NextResponse.json(
        { error: 'Cannot cancel a completed or closed route' },
        { status: 400 }
      );
    }

    // Update route status to closed
    const updatedRoute = await prisma.route.update({
      where: { id: routeId },
      data: {
        status: 'closed',
        endTime: new Date(),
        adminNotes: `Route cancelled by admin on ${new Date().toISOString()}`,
        isModifiedByAdmin: true,
      },
      include: {
        driver: true,
        drops: true,
        Booking: true,
      },
    });

    // Update all bookings to remove route assignment
    await prisma.booking.updateMany({
      where: {
        routeId: routeId,
      },
      data: {
        routeId: null,
        status: 'CONFIRMED', // Reset to confirmed so they can be reassigned
      },
    });

    // Update all drops to remove route assignment and reset to pending
    // This allows drops to be re-assigned to new routes (blue circle indicator)
    await prisma.drop.updateMany({
      where: {
        routeId: routeId,
      },
      data: {
        routeId: null, // Remove route assignment
        status: 'pending', // Reset to pending so they show with blue circle
      },
    });

    // Send real-time notification to driver
    if (route.driverId) {
      try {
        const pusher = getPusherServer();
        
        await pusher.trigger(`driver-${route.driverId}`, 'route-cancelled', {
          routeId: routeId,
          routeNumber: routeId, // Route ID is the route number
          message: `Route ${routeId} has been cancelled by admin`,
          reason: 'Admin cancelled the route',
          bookingsCount: route.Booking?.length || 0,
          dropsCount: route.drops?.length || 0,
          cancelledAt: new Date().toISOString(),
          // Signal to iOS app to remove route immediately
          action: 'remove_route',
          shouldRemoveFromApp: true,
        });

        console.log(`✅ Route cancellation notification sent to driver ${route.driverId}`);
      } catch (notificationError) {
        console.error('❌ Error sending route cancellation notification:', notificationError);
        // Don't fail the request if notification fails
      }
    }

    return NextResponse.json({
      route: updatedRoute,
      message: 'Route cancelled successfully. Bookings have been reset to pending.',
    });
  } catch (error) {
    console.error('Cancel route error:', error);
    return NextResponse.json(
      { error: 'Failed to cancel route' },
      { status: 500 }
    );
  }
}

