import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';

export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user || (session.user as any).role !== 'admin') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const { id } = await params;

    // Try to find as route first
    let route = await prisma.route.findUnique({
      where: { id },
      include: {
        driver: {
          select: {
            name: true,
            email: true,
            phone: true,
          },
        },
        drops: {
          include: {
            Booking: {
              select: {
                id: true,
                reference: true,
                customerName: true,
                customerPhone: true,
                status: true,
                totalGBP: true,
              },
            },
          },
          orderBy: {
            createdAt: 'asc',
          },
        },
      },
    });

    // If not found as route, try as booking (single job)
    if (!route) {
      const booking = await prisma.booking.findUnique({
        where: { id },
        include: {
          driver: {
            include: {
              User: {
                select: {
                  name: true,
                  email: true,
                  phone: true,
                },
              },
            },
          },
        },
      });

      if (!booking) {
        return NextResponse.json({ error: 'Route not found' }, { status: 404 });
      }

      // Convert booking to route format
      return NextResponse.json({
        id: booking.id,
        routeNumber: booking.reference,
        status: booking.status,
        driver: booking.driver,
        drops: [
          {
            id: booking.id,
            sequence: 1,
            booking: {
              id: booking.id,
              reference: booking.reference,
              customerName: booking.customerName,
              customerPhone: booking.customerPhone,
              status: booking.status,
            },
            status: booking.status,
            estimatedArrival: booking.scheduledAt,
          },
        ],
        totalDistance: 0,
        estimatedDuration: 0,
        totalValue: booking.totalGBP,
        createdAt: booking.createdAt,
        startedAt: booking.scheduledAt,
        completedAt: booking.status === 'COMPLETED' ? booking.updatedAt : null,
      });
    }

    // Calculate total value from drops
    const totalValue = route.drops.reduce(
      (sum, drop) => sum + (drop.Booking?.totalGBP || 0),
      0
    );

    return NextResponse.json({
      ...route,
      totalValue,
    });
  } catch (error) {
    console.error('Error fetching route details:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth/next';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
import { getPusherServer } from '@/lib/pusher';

/**
 * DELETE /api/admin/routes/[id]/drops/[dropId]
 * Remove drop from route (even if route is in progress!)
 */
export async function DELETE(
  request: NextRequest,
  { params }: { params: Promise<{ id: string; dropId: string }> }
): Promise<NextResponse> {
  try {
    // Check authentication and admin role
    const session = await getServerSession(authOptions);
    const user = (session as any)?.user;
    const role = user?.role as string | undefined;
    const userId = user?.id as string | undefined;
    if (!user || !role || role !== 'admin') {
      return NextResponse.json(
        { error: 'Unauthorized' },
        { status: 401 }
      );
    }

    const { id: routeId, dropId } = await params;

    // Get route
    const route = await prisma.route.findUnique({
      where: { id: routeId },
      include: {
        drops: true
      }
    });

    if (!route) {
      return NextResponse.json(
        { error: 'Route not found' },
        { status: 404 }
      );
    }

    // Cannot modify completed or closed routes
    if (route.status === 'completed' || route.status === 'closed') {
      return NextResponse.json(
        { error: 'Cannot remove drops from completed or closed routes' },
        { status: 400 }
      );
    }

    // Get drop
    const drop = await prisma.drop.findUnique({
      where: { id: dropId }
    });

    if (!drop) {
      return NextResponse.json(
        { error: 'Drop not found' },
        { status: 404 }
      );
    }

    // Check if drop belongs to this route
    if (drop.routeId !== routeId) {
      return NextResponse.json(
        { error: 'Drop does not belong to this route' },
        { status: 400 }
      );
    }

    // Cannot remove completed drops
    if (drop.status === 'delivered') {
      return NextResponse.json(
        { error: 'Cannot remove completed drops' },
        { status: 400 }
      );
    }

    // Remove drop from route (set routeId to null and mark as cancelled)
    const updatedDrop = await prisma.drop.update({
      where: { id: dropId },
      data: {
        routeId: null,
        status: 'cancelled'
      }
    });

    // Count remaining drops after removal
    const remainingDropsCount = route.drops.length - 1;

    // Update route to mark as modified by admin and update totalDrops
    const updatedRoute = await prisma.route.update({
      where: { id: routeId },
      data: {
        isModifiedByAdmin: true,
        totalDrops: remainingDropsCount,
        adminNotes: route.adminNotes 
          ? `${route.adminNotes}\nDrop ${dropId} removed by admin on ${new Date().toISOString()}`
          : `Drop ${dropId} removed by admin on ${new Date().toISOString()}`
      },
      include: {
        driver: {
          select: {
            id: true,
            name: true,
            email: true
          }
        },
        drops: {
          include: {
            User: { select: { id: true, name: true, email: true } },
            Booking: { select: { id: true } }
          }
        },
        Booking: {
          include: {
            customer: {
              select: {
                id: true,
                name: true,
                email: true
              }
            }
          }
        }
      }
    });

    // Send real-time notification to driver
    if (route.driverId) {
      try {
        const pusher = getPusherServer();
        
        await pusher.trigger(`driver-${route.driverId}`, 'drop-removed', {
          routeId: routeId,
          routeNumber: routeId, // Route ID is the route number
          dropId: dropId,
          message: `A drop has been removed from route ${routeId} by admin`,
          reason: 'Admin removed drop from route',
          remainingDrops: updatedRoute.drops.length,
          removedAt: new Date().toISOString(),
        });

        console.log(`✅ Drop removal notification sent to driver ${route.driverId}`);
      } catch (notificationError) {
        console.error('❌ Error sending drop removal notification:', notificationError);
        // Don't fail the request if notification fails
      }
    }

    return NextResponse.json({
      route: updatedRoute,
      removedDrop: updatedDrop,
      message: 'Drop removed from route successfully'
    });

  } catch (error) {
    console.error('Error removing drop from route:', error);
    return NextResponse.json(
      { error: 'Failed to remove drop from route' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';

// GET drops for a route
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user || (session.user as any).role !== 'admin') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const { id: routeId } = await params;

    const drops = await prisma.drop.findMany({
      where: { routeId },
      orderBy: { timeWindowStart: 'asc' },
      include: {
        Booking: {
          select: {
            id: true,
            reference: true,
            customerName: true,
            customerPhone: true,
          },
        },
        User: {
          select: {
            name: true,
            email: true,
          },
        },
      },
    });

    return NextResponse.json({ drops });
  } catch (error) {
    console.error('Get drops error:', error);
    return NextResponse.json(
      { error: 'Failed to fetch drops' },
      { status: 500 }
    );
  }
}

// POST - Add drop to route
export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user || (session.user as any).role !== 'admin') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const { id: routeId } = await params;
    const body = await request.json();

    const {
      bookingId,
      customerId,
      pickupAddress,
      deliveryAddress,
      timeWindowStart,
      timeWindowEnd,
      quotedPrice,
      specialInstructions,
    } = body;

    // Validate required fields
    if (!customerId || !pickupAddress || !deliveryAddress || !timeWindowStart || !timeWindowEnd || !quotedPrice) {
      return NextResponse.json(
        { error: 'Missing required fields' },
        { status: 400 }
      );
    }

    // Check if route exists
    const route = await prisma.route.findUnique({
      where: { id: routeId },
    });

    if (!route) {
      return NextResponse.json({ error: 'Route not found' }, { status: 404 });
    }

    // Cannot add drops to completed/closed routes
    if (route.status === 'completed' || route.status === 'closed') {
      return NextResponse.json(
        { error: 'Cannot add drops to completed or closed routes' },
        { status: 400 }
      );
    }

    // Create drop
    const drop = await prisma.drop.create({
      data: {
        Route: { connect: { id: routeId } },
        ...(bookingId ? { Booking: { connect: { id: bookingId } } } : {}),
        User: { connect: { id: customerId } },
        pickupAddress,
        deliveryAddress,
        timeWindowStart: new Date(timeWindowStart),
        timeWindowEnd: new Date(timeWindowEnd),
        quotedPrice: parseFloat(quotedPrice),
        specialInstructions,
        status: 'booked',
      },
      include: {
        Booking: true,
        User: true,
      },
    });

    // Get current drop count and update route
    const currentDropCount = await prisma.drop.count({
      where: { routeId }
    });

    // Mark route as modified by admin and update totalDrops
    await prisma.route.update({
      where: { id: routeId },
      data: {
        isModifiedByAdmin: true,
        totalDrops: currentDropCount,
        adminNotes: `Drop added manually by admin on ${new Date().toISOString()}`,
      },
    });

    return NextResponse.json({
      drop,
      message: 'Drop added successfully',
    });
  } catch (error) {
    console.error('Add drop error:', error);
    return NextResponse.json(
      { error: 'Failed to add drop' },
      { status: 500 }
    );
  }
}

/**
 * PUT /api/admin/routes/[id]/edit
 * 
 * Edit an existing route (add/remove bookings, reorder stops)
 */

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { intelligentRouteOptimizer } from '@/lib/services/intelligent-route-optimizer';

export async function PUT(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { id: routeId } = await params;
    const body = await request.json();
    const { bookingIds, action } = body; // action: 'add', 'remove', 'reorder'

    // Get existing route
    const existingRoute = await prisma.route.findUnique({
      where: { id: routeId },
      include: {
        Booking: {
          include: {
            pickupAddress: true,
            dropoffAddress: true,
          },
        },
      },
    });

    if (!existingRoute) {
      return NextResponse.json(
        { success: false, error: 'Route not found' },
        { status: 404 }
      );
    }

    if (existingRoute.status === 'completed') {
      return NextResponse.json(
        { success: false, error: 'Cannot edit completed route' },
        { status: 400 }
      );
    }

    let updatedBookingIds: string[];

    switch (action) {
      case 'add':
        // Add new bookings to route
        updatedBookingIds = [
          ...existingRoute.Booking.map(b => b.id),
          ...bookingIds.filter((id: string) => !existingRoute.Booking.find(b => b.id === id)),
        ];
        break;

      case 'remove':
        // Remove bookings from route
        updatedBookingIds = existingRoute.Booking
          .map(b => b.id)
          .filter(id => !bookingIds.includes(id));
        break;

      case 'reorder':
        // Reorder bookings
        updatedBookingIds = bookingIds;
        break;

      default:
        return NextResponse.json(
          { success: false, error: 'Invalid action. Must be add, remove, or reorder' },
          { status: 400 }
        );
    }

    if (updatedBookingIds.length === 0) {
      // Delete route if no bookings left
      await prisma.booking.updateMany({
        where: { routeId },
        data: { routeId: null, deliverySequence: null, orderType: 'single' },
      });

      await prisma.route.delete({
        where: { id: routeId },
      });

      return NextResponse.json({
        success: true,
        data: {
          message: 'Route deleted (no bookings remaining)',
          routeId,
        },
      });
    }

    // Get all bookings
    const bookings = await prisma.booking.findMany({
      where: {
        id: { in: updatedBookingIds },
      },
      include: {
        pickupAddress: true,
        dropoffAddress: true,
      },
    });

    // Re-analyze route
    const routeAnalysis = await intelligentRouteOptimizer.analyzeMultiDropEligibility({
      pickup: { coordinates: { lat: bookings[0]?.pickupAddress.lat || 0, lng: bookings[0]?.pickupAddress.lng || 0 } },
      dropoff: { coordinates: { lat: bookings.at(-1)?.dropoffAddress.lat || 0, lng: bookings.at(-1)?.dropoffAddress.lng || 0 } },
      items: [],
      floorLevel: 0,
      hasLift: false,
    } as any);

    // Update route
    await prisma.route.update({
      where: { id: routeId },
      data: {
        optimizedDistanceKm: (routeAnalysis as any).route.distance * 1.609,
        estimatedDuration: Math.round((routeAnalysis as any).route.totalTime),
        totalOutcome: bookings.reduce((sum, b) => {
          const value = Number(b.totalGBP || 0);
          return (Number.isFinite(value) && value >= 0 && value <= Number.MAX_SAFE_INTEGER) ? sum + value : sum;
        }, 0),
        updatedAt: new Date(),
      },
    });

    // Update bookings
    // First, remove old bookings from route
    await prisma.booking.updateMany({
      where: { routeId },
      data: { routeId: null, deliverySequence: null },
    });

    // Then, add updated bookings
    for (let i = 0; i < updatedBookingIds.length; i++) {
      await prisma.booking.update({
        where: { id: updatedBookingIds[i] },
        data: {
          routeId,
          deliverySequence: i + 1,
          orderType: updatedBookingIds.length > 1 ? 'multi-drop' : 'single',
        },
      });
    }

    // Get updated route
    const updatedRoute = await prisma.route.findUnique({
      where: { id: routeId },
      include: {
        Booking: {
          include: {
            pickupAddress: true,
            dropoffAddress: true,
            BookingItem: true,
          },
          orderBy: {
            deliverySequence: 'asc',
          },
        },
      },
    });

    return NextResponse.json({
      success: true,
      data: {
        route: updatedRoute,
        analysis: routeAnalysis,
      },
    });
  } catch (error) {
    console.error('Error editing route:', error);
    return NextResponse.json(
      { success: false, error: 'Failed to edit route' },
      { status: 500 }
    );
  }
}

/**
 * Force Status Change API
 * 
 * Allows admin to change route status to any state regardless of current status
 * This bypasses all validation rules and state machine constraints
 */

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
import { logger } from '@/lib/logger';
import { logAudit } from '@/lib/audit';

export const dynamic = 'force-dynamic';

/**
 * PATCH /api/admin/routes/[id]/force-status
 * Force change route status with admin override
 */
export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user || (session.user as any).role !== 'admin') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const { id: routeId } = await params;
    const body = await request.json();
    const { status, reason, updateDrops = true } = body;

    if (!status) {
      return NextResponse.json(
        { error: 'Status is required' },
        { status: 400 }
      );
    }

    if (!reason) {
      return NextResponse.json(
        { error: 'Reason is required for force status change' },
        { status: 400 }
      );
    }

    // Valid route statuses
    const validStatuses = ['planned', 'pending_assignment', 'assigned', 'active', 'completed', 'cancelled', 'failed'];
    if (!validStatuses.includes(status)) {
      return NextResponse.json(
        { error: `Invalid status. Must be one of: ${validStatuses.join(', ')}` },
        { status: 400 }
      );
    }

    // Get existing route
    const existingRoute = await prisma.route.findUnique({
      where: { id: routeId },
      include: {
        drops: true,
      },
    });

    if (!existingRoute) {
      return NextResponse.json(
        { error: 'Route not found' },
        { status: 404 }
      );
    }

    const previousStatus = existingRoute.status;

    // Update route status
    const updatedRoute = await prisma.route.update({
      where: { id: routeId },
      data: {
        status,
        adminNotes: `${existingRoute.adminNotes || ''}\n[FORCE STATUS CHANGE] ${new Date().toISOString()} - Admin ${session.user.name || session.user.email} changed status from ${previousStatus} to ${status}. Reason: ${reason}`,
        isModifiedByAdmin: true,
        updatedAt: new Date(),
        ...(status === 'completed' && !existingRoute.endTime ? { endTime: new Date() } : {}),
        ...(status === 'active' && !existingRoute.acceptedAt ? { acceptedAt: new Date() } : {}),
      },
      include: {
        driver: {
          select: {
            id: true,
            name: true,
            email: true,
          },
        },
        drops: {
          include: {
            Booking: {
              select: {
                id: true,
                reference: true,
                customerName: true,
              },
            },
          },
        },
      },
    });

    // Update drops status if requested
    if (updateDrops) {
      let dropStatus: string | null = null;
      
      switch (status) {
        case 'planned':
        case 'pending_assignment':
        case 'assigned':
          dropStatus = 'pending';
          break;
        case 'active':
          dropStatus = 'assigned_to_route';
          break;
        case 'completed':
          dropStatus = 'delivered';
          break;
        case 'cancelled':
        case 'failed':
          dropStatus = 'failed';
          break;
      }

      if (dropStatus) {
        await prisma.drop.updateMany({
          where: { routeId },
          data: { status: dropStatus as any },
        });
      }
    }

    // Log comprehensive audit
    await logAudit({
      userId: (session.user as any).id,
      action: 'force_status_change',
      entityType: 'route',
      entityId: routeId,
      details: {
        previousStatus,
        newStatus: status,
        reason,
        updateDrops,
        dropsAffected: existingRoute.drops.length,
        adminName: session.user.name || session.user.email,
        timestamp: new Date().toISOString(),
      },
    });

    logger.warn('Route status force changed', {
      routeId,
      previousStatus,
      newStatus: status,
      reason,
      adminId: (session.user as any).id,
      updateDrops,
    });

    return NextResponse.json({
      success: true,
      data: updatedRoute,
      message: `Route status force changed from ${previousStatus} to ${status}`,
      previousStatus,
      newStatus: status,
      dropsUpdated: updateDrops,
    });

  } catch (error) {
    logger.error('Failed to force change route status', error as Error);
    return NextResponse.json(
      {
        error: 'Failed to force change route status',
        details: error instanceof Error ? error.message : 'Unknown error',
      },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { withPrisma } from '@/lib/prisma';
import { getPusherServer } from '@/lib/pusher';
import { logAudit } from '@/lib/audit';
import { getActiveAssignment } from '@/lib/utils/assignment-helpers';

export const dynamic = 'force-dynamic';
export const maxDuration = 10;

/**
 * POST /api/admin/routes/[id]/reassign
 * Reassign an existing route to a different driver
 */
export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user || (session.user as any).role !== 'admin') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const { id: routeId } = await params;
    const body = await request.json();
    const { driverId, reason } = body;

    if (!driverId) {
      return NextResponse.json(
        { error: 'Driver ID is required' },
        { status: 400 }
      );
    }

    console.log('🔄 Admin reassigning route to different driver:', { routeId, driverId, reason });

    return await withPrisma(async (prisma) => {
      // Check if this is a single booking (starts with "booking-")
      if (routeId.startsWith('booking-')) {
        const bookingId = routeId.replace('booking-', '');
        
        // Handle single booking reassignment
        const booking = await prisma.booking.findUnique({
          where: { id: bookingId },
          include: {
            driver: {
              include: {
                User: { select: { name: true, email: true } }
              }
            }
          }
        });

        if (!booking) {
          return NextResponse.json(
            { error: 'Booking not found' },
            { status: 404 }
          );
        }

        // Update booking driver assignment
        await prisma.booking.update({
          where: { id: bookingId },
          data: { driverId: driverId }
        });

        // Log audit trail
        await logAudit(
          session.user.id,
          'booking_driver_reassigned',
          bookingId,
          {
            targetType: 'booking',
            before: { driverId: booking.driverId, driverName: booking.driver?.User?.name },
            after: { driverId: driverId, reason }
          }
        );

        return NextResponse.json({
          success: true,
          message: 'Booking driver reassigned successfully'
        });
      }

      // Check if route exists (for multi-drop routes)
      const route = await prisma.route.findUnique({
        where: { id: routeId },
        include: {
          driver: {
            select: { 
              id: true,
              name: true,
              email: true
            }
          },
          drops: {
            orderBy: { createdAt: 'asc' }
          },
          Booking: {
            include: {
              Assignment: true
            }
          },
        },
      });

      if (!route) {
        return NextResponse.json({ error: 'Route not found' }, { status: 404 });
      }

      const oldDriverId = route.driverId;
      const oldDriverName = (route as any).driver?.name || 'Unknown';

      // Check if new driver exists
      const newDriver = await prisma.driver.findUnique({
        where: { id: driverId },
        include: {
          User: {
            select: { name: true, email: true }
          },
          DriverAvailability: true
        }
      });

      if (!newDriver) {
        return NextResponse.json({ error: 'Driver not found' }, { status: 404 });
      }

      // Check if driver is available
      if (!newDriver.DriverAvailability) {
        return NextResponse.json(
          { error: 'Driver availability not found' },
          { status: 400 }
        );
      }

      // Check driver status
      const validStatuses = ['AVAILABLE', 'online', 'available'];
      if (!validStatuses.includes(newDriver.DriverAvailability.status)) {
        return NextResponse.json(
          { error: `Driver is not available for assignments (status: ${newDriver.DriverAvailability.status})` },
          { status: 400 }
        );
      }

      // Use transaction to ensure data consistency
      const result = await prisma.$transaction(async (tx) => {
        // Update route with new driver
        const updatedRoute = await tx.route.update({
          where: { id: routeId },
          data: {
            driverId,
            isModifiedByAdmin: true,
            adminNotes: `Driver reassigned from ${oldDriverName} to ${newDriver.User?.name || 'Unknown'} by admin. Reason: ${reason || 'Not specified'}`,
          },
          include: {
            driver: { 
              select: { 
                id: true,
                name: true,
                email: true
              } 
            },
            drops: {
              orderBy: { createdAt: 'asc' }
            },
            Booking: {
              include: {
                Assignment: true
              }
            },
          },
        });

        // Update all bookings in the route
        const bookingIds = route.Booking.map(b => b.id);
        
        if (bookingIds.length > 0) {
          await tx.booking.updateMany({
            where: { id: { in: bookingIds } },
            data: {
              driverId: driverId,
              status: 'CONFIRMED',
              updatedAt: new Date(),
            },
          });

          // Update assignments for all bookings in the route
          for (const booking of route.Booking) {
            // Cancel old assignment (get the active one from the array)
            const activeAssignment = getActiveAssignment(booking.Assignment);
            if (activeAssignment) {
              await tx.assignment.update({
                where: { id: activeAssignment.id },
                data: {
                  status: 'cancelled',
                  updatedAt: new Date(),
                }
              });

              // Disconnect the old assignment from the booking to prevent Prisma relation cache conflict
              await tx.booking.update({
                where: { id: booking.id },
                data: { 
                  Assignment: { 
                    disconnect: { id: activeAssignment.id } 
                  } 
                },
              });

              // Create job event for removal
              const removalEventId = `event_${Date.now()}_${Math.random().toString(36).substr(2, 9)}_removed`;
              await tx.jobEvent.create({
                data: {
                  id: removalEventId,
                  assignmentId: activeAssignment.id,
                  step: 'job_completed',
                  payload: {
                    removedBy: 'admin',
                    reason: reason || 'Route reassigned to different driver',
                    removedAt: new Date().toISOString(),
                    action: 'job_removed',
                  },
                  notes: `Job removed from driver ${oldDriverName} by admin (route reassignment)`,
                  createdBy: session.user.id || 'system',
                }
              });
            }

            // Delete any existing non-cancelled assignments to prevent conflicts
            // This ensures clean state before creating new assignment
            await tx.assignment.deleteMany({
              where: {
                bookingId: booking.id,
                status: { notIn: ['cancelled', 'declined', 'completed'] }
              }
            });

            // Create new assignment for the new driver
            const assignmentId = `assignment_${Date.now()}_${Math.random().toString(36).substr(2, 9)}_${booking.id}`;
            await tx.assignment.create({
              data: {
                id: assignmentId,
                bookingId: booking.id,
                driverId: driverId,
                status: 'invited',
                round: 1,
                expiresAt: new Date(Date.now() + 30 * 60 * 1000), // 30 minutes to accept
                updatedAt: new Date(),
              }
            });

            // Create job event for new assignment
            const assignmentEventId = `event_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
            await tx.jobEvent.create({
              data: {
                id: assignmentEventId,
                assignmentId: assignmentId,
                step: 'navigate_to_pickup',
                payload: {
                  assignedBy: 'admin',
                  reason: reason || 'Reassigned via route',
                  assignedAt: new Date().toISOString(),
                  action: 'job_assigned',
                  routeId: routeId,
                },
                notes: `Job assigned to driver ${newDriver.User?.name || 'Unknown'} as part of reassigned route ${routeId}`,
                createdBy: session.user.id || 'system',
              }
            });
          }
        }

        return { updatedRoute, bookingsCount: bookingIds.length };
      });

      console.log('🎉 Route reassignment completed:', {
        routeId: result.updatedRoute.id,
        oldDriver: oldDriverName,
        newDriver: newDriver.User?.name || 'Unknown',
        bookingsCount: result.bookingsCount
      });

      // Send real-time notifications
      try {
        const pusher = getPusherServer();

        // Notify the old driver about removal
        if (oldDriverId) {
          await pusher.trigger(`driver-${oldDriverId}`, 'route-removed', {
            routeId: result.updatedRoute.id,
            reason: reason || 'Route reassigned to different driver',
            removedAt: new Date().toISOString(),
            message: 'A route has been removed from your assignments',
          });
        }

        // Get route number for display
        const routeNumber = result.updatedRoute.id; // Route ID is the route number (e.g., RT1A2B3C4D)
        const firstBooking = (result.updatedRoute as any).Booking?.[0];
        const displayReference = result.bookingsCount > 1 
          ? routeNumber // For multi-drop, show route number
          : (firstBooking?.reference || routeNumber); // For single order, show booking reference

        // Notify the new driver with "route-matched" event
        await pusher.trigger(`driver-${driverId}`, 'route-matched', {
          type: 'full-route',
          routeId: result.updatedRoute.id,
          routeNumber: routeNumber, // ✅ Route number (RT1A2B3C4D)
          bookingReference: displayReference, // ✅ Display reference
          orderNumber: displayReference, // ✅ Alias for consistency
          bookingsCount: result.bookingsCount,
          dropsCount: (result.updatedRoute as any).drops.length,
          totalDistance: result.updatedRoute.optimizedDistanceKm,
          estimatedDuration: result.updatedRoute.estimatedDuration,
          totalEarnings: result.updatedRoute.driverPayout ? Number(result.updatedRoute.driverPayout) : 0,
          assignedAt: new Date().toISOString(),
          message: `Route ${displayReference} with ${result.bookingsCount} jobs has been reassigned to you`,
          drops: (result.updatedRoute as any).drops.map((drop: any) => ({
            id: drop.id,
            pickupAddress: drop.pickupAddress,
            deliveryAddress: drop.deliveryAddress,
          })),
        });

        // Also send job-assigned event for backward compatibility
        await pusher.trigger(`driver-${driverId}`, 'job-assigned', {
          type: 'route',
          routeId: result.updatedRoute.id,
          bookingsCount: result.bookingsCount,
          assignedAt: new Date().toISOString(),
          message: `You have been assigned a route with ${result.bookingsCount} jobs`,
        });

        // Notify other drivers that these jobs are no longer available
        const bookingsInRoute = await prisma.booking.findMany({
          where: { routeId: result.updatedRoute.id },
          select: { id: true, reference: true },
        });

        for (const booking of bookingsInRoute) {
          await pusher.trigger('drivers-broadcast', 'job-removed', {
            bookingId: booking.id,
            bookingReference: booking.reference,
            assignedTo: newDriver.User?.name || 'Unknown',
            message: 'This job has been assigned to a route',
            reason: 'route_reassigned',
          });
        }
        console.log(`📡 Notified other drivers about ${bookingsInRoute.length} jobs removed from pool`);

        // Notify admin dashboard
        await pusher.trigger('admin-notifications', 'route-reassigned', {
          routeId: result.updatedRoute.id,
          oldDriver: oldDriverName,
          newDriver: newDriver.User?.name || 'Unknown',
          bookingsCount: result.bookingsCount,
          reassignedAt: new Date().toISOString(),
        });

        console.log('✅ Real-time notifications sent for route reassignment');
      } catch (notificationError) {
        console.error('❌ Error sending real-time notifications:', notificationError);
        // Don't fail the request if notifications fail
      }

      // Create audit log
      await prisma.auditLog.create({
        data: {
          actorId: session.user.id || 'system',
          actorRole: 'admin',
          action: 'route_reassigned',
          targetType: 'route',
          targetId: routeId,
          details: {
            oldDriverId: oldDriverId,
            oldDriverName: oldDriverName,
            newDriverId: driverId,
            newDriverName: newDriver.User?.name || 'Unknown',
            bookingsCount: result.bookingsCount,
            reason: reason || 'Reassigned by admin',
            reassignedAt: new Date().toISOString(),
          }
        }
      });

      return NextResponse.json({
        success: true,
        route: result.updatedRoute,
        message: `Route with ${result.bookingsCount} jobs reassigned successfully to ${newDriver.User?.name || 'Unknown'}`,
        data: {
          routeId: result.updatedRoute.id,
          oldDriver: oldDriverName,
          newDriver: {
            id: newDriver.id,
            name: newDriver.User?.name || 'Unknown',
            email: newDriver.User?.email || '',
          },
          bookingsCount: result.bookingsCount,
          dropsCount: (result.updatedRoute as any).drops.length,
          reassignedAt: new Date().toISOString(),
        }
      });
    });
  } catch (error) {
    console.error('❌ Reassign driver error:', error);
    return NextResponse.json(
      { 
        error: 'Failed to reassign driver',
        details: error instanceof Error ? error.message : 'Unknown error'
      },
      { status: 500 }
    );
  }
}

/**
 * Admin Individual Route Management API
 * Update, Delete, Reassign routes
 */

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
import { logAudit } from '@/lib/audit';

export const dynamic = 'force-dynamic';

/**
 * GET /api/admin/routes/[id]
 * Get specific route details
 */
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user || (session.user as any).role !== 'admin') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const { id } = await params;

    const route = await prisma.route.findUnique({
      where: { id },
      include: {
        driver: true,
        drops: {
          include: {
            User: { select: { id: true, name: true, email: true } }
          },
          orderBy: { createdAt: 'asc' }
        },
        Vehicle: true
      }
    });

    if (!route) {
      return NextResponse.json({ error: 'Route not found' }, { status: 404 });
    }

    return NextResponse.json({
      success: true,
      route: {
        ...route,
        progress: route.totalDrops > 0 ? (route.completedDrops / route.totalDrops * 100) : 0,
      }
    });

  } catch (error) {
    console.error('❌ Route GET error:', error);
    return NextResponse.json(
      { error: 'Failed to fetch route', details: error instanceof Error ? error.message : 'Unknown' },
      { status: 500 }
    );
  }
}

/**
 * PATCH /api/admin/routes/[id]
 * Update route (add/remove drops, change driver, etc.)
 */
export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user || (session.user as any).role !== 'admin') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const { id } = await params;
    const body = await request.json();
    const { action } = body;

    const existingRoute = await prisma.route.findUnique({
      where: { id },
      include: { drops: true }
    });

    if (!existingRoute) {
      return NextResponse.json({ error: 'Route not found' }, { status: 404 });
    }

    let updatedRoute;

    switch (action) {
      case 'reassign_driver':
        // Reassign route to different driver (even if active)
        const { newDriverId } = body;
        
        updatedRoute = await prisma.route.update({
          where: { id },
          data: {
            driverId: newDriverId,
            routeNotes: `${existingRoute.routeNotes || ''} | Driver reassigned by admin`,
            isModifiedByAdmin: true,
            adminNotes: `Reassigned from driver ${existingRoute.driverId} to ${newDriverId}`,
          },
          include: {
            driver: true
          }
        });

        await logAudit(
          (session.user as any).id,
          'reassign_route_driver',
          undefined,
          { 
            targetType: 'route', 
            targetId: id,
            before: { driverId: existingRoute.driverId },
            after: { driverId: newDriverId }
          }
        );
        break;

      case 'add_drops':
        // Add drops to existing route (even if active)
        const { dropIdsToAdd } = body;
        
        // Validate drops
        const dropsToAdd = await prisma.drop.findMany({
          where: {
            id: { in: dropIdsToAdd },
            status: 'pending',
          }
        });

        if (dropsToAdd.length !== dropIdsToAdd.length) {
          return NextResponse.json(
            { error: 'Some drops are not available' },
            { status: 400 }
          );
        }

        // Update drops
        await prisma.drop.updateMany({
          where: { id: { in: dropIdsToAdd } },
          data: {
            routeId: id,
            status: 'assigned_to_route',
          }
        });

        // Update route totals (with validation)
        const newTotalOutcome = dropsToAdd.reduce((sum, d) => {
          const price = Number(d.quotedPrice || 0);
          return (Number.isFinite(price) && price >= 0 && price <= Number.MAX_SAFE_INTEGER) ? sum + price : sum;
        }, 0);
        
        updatedRoute = await prisma.route.update({
          where: { id },
          data: {
            totalDrops: existingRoute.totalDrops + dropsToAdd.length,
            totalOutcome: Number(existingRoute.totalOutcome) + newTotalOutcome,
            isModifiedByAdmin: true,
            adminNotes: `${dropsToAdd.length} drops added by admin`,
          },
          include: { drops: true }
        });

        await logAudit(
          (session.user as any).id,
          'add_drops_to_route',
          undefined,
          { 
            targetType: 'route', 
            targetId: id,
            after: { addedDrops: dropIdsToAdd.length }
          }
        );
        break;

      case 'remove_drops':
        // Remove drops from route
        const { dropIdsToRemove } = body;
        
        const dropsToRemove = await prisma.drop.findMany({
          where: {
            id: { in: dropIdsToRemove },
            routeId: id,
          }
        });

        // Update drops back to pending
        await prisma.drop.updateMany({
          where: { id: { in: dropIdsToRemove } },
          data: {
            routeId: null,
            status: 'pending',
          }
        });

        const removedOutcome = dropsToRemove.reduce((sum, d) => {
          const price = Number(d.quotedPrice || 0);
          return (Number.isFinite(price) && price >= 0 && price <= Number.MAX_SAFE_INTEGER) ? sum + price : sum;
        }, 0);
        
        updatedRoute = await prisma.route.update({
          where: { id },
          data: {
            totalDrops: existingRoute.totalDrops - dropsToRemove.length,
            totalOutcome: Number(existingRoute.totalOutcome) - removedOutcome,
            isModifiedByAdmin: true,
            adminNotes: `${dropsToRemove.length} drops removed by admin`,
          },
          include: { drops: true }
        });

        await logAudit(
          (session.user as any).id,
          'remove_drops_from_route',
          undefined,
          { 
            targetType: 'route', 
            targetId: id,
            after: { removedDrops: dropIdsToRemove.length }
          }
        );
        break;

      case 'update_status':
        // Update route status
        const { newStatus } = body;
        
        updatedRoute = await prisma.route.update({
          where: { id },
          data: {
            status: newStatus,
            ...(newStatus === 'completed' && {
              endTime: new Date(),
              actualDuration: existingRoute.startTime ? 
                Math.floor((new Date().getTime() - existingRoute.startTime.getTime()) / 60000) : null
            })
          }
        });

        await logAudit(
          (session.user as any).id,
          'update_route_status',
          undefined,
          { 
            targetType: 'route', 
            targetId: id,
            before: { status: existingRoute.status },
            after: { status: newStatus }
          }
        );
        break;

      default:
        return NextResponse.json(
          { error: 'Invalid action' },
          { status: 400 }
        );
    }

    return NextResponse.json({
      success: true,
      route: updatedRoute,
      message: 'Route updated successfully'
    });

  } catch (error) {
    console.error('❌ Route PATCH error:', error);
    return NextResponse.json(
      { error: 'Failed to update route', details: error instanceof Error ? error.message : 'Unknown' },
      { status: 500 }
    );
  }
}

/**
 * DELETE /api/admin/routes/[id]
 * Cancel/Delete route
 */
export async function DELETE(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user || (session.user as any).role !== 'admin') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const { id } = await params;
    const { searchParams } = new URL(request.url);
    const reason = searchParams.get('reason') || 'Cancelled by admin';

    // Get route before deletion
    const route = await prisma.route.findUnique({
      where: { id },
      include: { drops: true }
    });

    if (!route) {
      return NextResponse.json({ error: 'Route not found' }, { status: 404 });
    }

    // Release all drops back to pending
    if (route.drops.length > 0) {
      await prisma.drop.updateMany({
        where: { routeId: id },
        data: {
          routeId: null,
          status: 'pending',
        }
      });
    }

    // Mark route as cancelled instead of deleting (for audit trail)
    await prisma.route.update({
      where: { id },
      data: {
        status: 'failed',
        adminNotes: `CANCELLED: ${reason}`,
        endTime: new Date(),
      }
    });

    await logAudit(
      (session.user as any).id,
      'cancel_route',
      undefined,
      { 
        targetType: 'route', 
        targetId: id,
        before: { status: route.status, dropCount: route.drops.length },
        after: { status: 'failed', reason }
      }
    );

    return NextResponse.json({
      success: true,
      message: `Route cancelled and ${route.drops.length} drops released back to pending`,
    });

  } catch (error) {
    console.error('❌ Route DELETE error:', error);
    return NextResponse.json(
      { error: 'Failed to cancel route', details: error instanceof Error ? error.message : 'Unknown' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { withPrisma } from '@/lib/prisma';
import { getPusherServer } from '@/lib/pusher';

export const dynamic = 'force-dynamic';

/**
 * Calculate earnings for completed drops only
 */
function calculatePartialRouteEarnings(
  completedDrops: number,
  totalDrops: number,
  totalRouteEarnings: number
): number {
  if (totalDrops === 0) return 0;
  
  // Calculate per-drop earnings
  const perDropEarnings = totalRouteEarnings / totalDrops;
  
  // Return earnings for completed drops only
  return Math.floor(perDropEarnings * completedDrops);
}

/**
 * POST /api/admin/routes/[id]/unassign
 * Unassign driver from a specific route with earnings recalculation
 */
export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const session = await getServerSession(authOptions);
    
    if (!session?.user || (session.user as any).role !== 'admin') {
      return NextResponse.json(
        { error: 'Unauthorized - Admin access required' },
        { status: 401 }
      );
    }

    const { id: routeId } = await params;
    
    // Parse request body safely
    let reason = 'Unassigned by admin';
    try {
      const body = await request.json();
      reason = body.reason || reason;
    } catch (e) {
      console.log('⚠️ No request body provided, using default reason');
    }

    console.log('🔄 Admin unassigning driver from route:', { routeId, reason });

    return await withPrisma(async (prisma) => {
      // Check if this is a single booking (starts with "booking-")
      if (routeId.startsWith('booking-')) {
        const bookingId = routeId.replace('booking-', '');
        
        console.log('🔄 Unassigning single booking:', bookingId);
        
        // Handle single booking unassignment
        const booking = await prisma.booking.findUnique({
          where: { id: bookingId },
          include: {
            driver: {
              include: {
                User: {
                  select: { id: true, name: true, email: true }
                }
              }
            }
          }
        });

        if (!booking) {
          return NextResponse.json(
            { error: 'Booking not found' },
            { status: 404 }
          );
        }

        if (!booking.driverId) {
          return NextResponse.json(
            { error: 'Booking is not assigned to any driver' },
            { status: 400 }
          );
        }

        const oldDriverId = booking.driverId;
        const oldDriverName = (booking as any).driver?.User?.name || (booking as any).driver?.name || 'Unknown';

        // Update booking - remove driver assignment
        await prisma.booking.update({
          where: { id: bookingId },
          data: { 
            driverId: null,
            status: 'CONFIRMED'
          }
        });

        // Cancel active assignment if exists
        const activeAssignment = await prisma.assignment.findFirst({
          where: { 
            bookingId: bookingId,
            status: { in: ['invited', 'claimed', 'accepted'] }
          }
        });

        if (activeAssignment) {
          await prisma.assignment.update({
            where: { id: activeAssignment.id },
            data: { 
              status: 'cancelled',
              updatedAt: new Date()
            }
          });
        }

        // Send Pusher notification to driver
        try {
          const pusher = getPusherServer();
          console.log('📡 Sending job-removed notification to driver:', oldDriverId);
          
          await pusher.trigger(`driver-${oldDriverId}`, 'job-removed', {
            bookingId: bookingId,
            bookingReference: booking.reference,
            reason: reason || 'Removed by admin',
            message: `Job ${booking.reference} has been unassigned by admin`
          });
          console.log('✅ Sent unassign notification to driver');
        } catch (pusherError) {
          console.error('❌ Failed to send Pusher notification:', pusherError);
        }

        console.log('✅ Booking unassigned successfully:', {
          bookingId,
          oldDriver: oldDriverName
        });

        return NextResponse.json({
          success: true,
          message: `Booking ${booking.reference} unassigned from ${oldDriverName} successfully`,
          data: {
            bookingId,
            oldDriver: oldDriverName
          }
        });
      }

      // Find the route with complete details (for multi-drop routes)
      const route = await prisma.route.findUnique({
        where: { id: routeId },
        include: {
          driver: {
            select: { id: true, name: true, email: true }
          },
          Booking: {
            select: {
              id: true,
              reference: true,
              status: true,
              Assignment: {
                select: {
                  id: true,
                  DriverEarnings: true
                }
              }
            }
          }
        }
      });

      if (!route) {
        return NextResponse.json(
          { error: 'Route not found' },
          { status: 404 }
        );
      }

      if (!route.driverId) {
        return NextResponse.json(
          { error: 'Route is not assigned to any driver' },
          { status: 400 }
        );
      }

      const oldDriverName = (route as any).driver?.name || 'Unknown';
      const oldDriverId = route.driverId;
      const completedDrops = route.completedDrops || 0;
      const totalDrops = route.totalDrops || 0;

      // Calculate earnings for completed drops only
      const totalRouteValue = Number(route.totalOutcome || 0);
      const earnedAmount = calculatePartialRouteEarnings(
        completedDrops,
        totalDrops,
        totalRouteValue
      );

      let earningsData: any = null;

      // Unassign the driver using transaction
      await prisma.$transaction(async (tx) => {
        // Update route - remove driver and set back to pending_assignment
        await tx.route.update({
          where: { id: routeId },
          data: {
            status: 'pending_assignment',
            updatedAt: new Date()
          }
        });

        // Then actually remove the driver
        await tx.route.update({
          where: { id: routeId },
          data: {
            driverId: null
          }
        });

        // Recalculate and update earnings for completed drops
        if (completedDrops > 0 && (route as any).Booking && (route as any).Booking.length > 0) {
          for (const booking of (route as any).Booking) {
            if (booking.Assignment && booking.Assignment.DriverEarnings) {
              for (const earning of booking.Assignment.DriverEarnings) {
                // Update earnings to reflect only completed drops
                const adjustedEarnings = Math.floor(
                  (Number(earning.netAmountPence) * completedDrops) / totalDrops
                );

                await tx.driverEarnings.update({
                  where: { id: earning.id },
                  data: {
                    netAmountPence: adjustedEarnings,
                    adminAdjustedAmountPence: adjustedEarnings,
                    adminAdjustedBy: (session.user as any).id,
                    adminAdjustedAt: new Date(),
                    adminNotes: `Route cancelled - Adjusted to ${completedDrops}/${totalDrops} completed drops. Reason: ${reason || 'Route unassigned by admin'}`
                  }
                });

                // Store earnings data for response
                if (!earningsData) {
                  earningsData = {
                    originalAmount: Number(earning.netAmountPence),
                    adjustedAmount: adjustedEarnings,
                    completedDrops,
                    totalDrops
                  };
                }
              }
            }
          }
        }

        // Update all associated bookings - keep them in route but remove driver only
        if ((route as any).Booking && (route as any).Booking.length > 0) {
          for (const booking of (route as any).Booking) {
            await tx.booking.update({
              where: { id: booking.id },
              data: {
                driverId: null,
                // Keep routeId - bookings stay in the route (pending_assignment)
                // routeId: null,  ← Don't remove - keep in route!
                status: 'CONFIRMED'
              }
            });

            // Update assignment if exists
            const assignment = await tx.assignment.findFirst({
              where: { bookingId: booking.id },
              orderBy: { createdAt: 'desc' }
            });

            if (assignment) {
              await tx.assignment.update({
                where: { id: assignment.id },
                data: {
                  status: 'cancelled',
                  updatedAt: new Date()
                }
              });
            }
          }
        }

        // Update driver availability - moved outside transaction to avoid TX issues
        // Will be handled after transaction commits
      });

      // Update driver availability after transaction
      try {
        const driverAvailability = await prisma.driverAvailability.findUnique({
          where: { driverId: oldDriverId }
        });

        if (driverAvailability) {
          const bookingsCount = (route as any).Booking?.length || 0;
          await prisma.driverAvailability.update({
            where: { driverId: oldDriverId },
            data: {
              currentCapacityUsed: Math.max(0, driverAvailability.currentCapacityUsed - bookingsCount)
            }
          });
          console.log('✅ Driver availability updated');
        }
      } catch (availError) {
        console.warn('⚠️ Could not update driver availability (non-critical):', availError);
        // Don't fail the request
      }

      // Send real-time notifications to update schedules
      try {
        const pusher = getPusherServer();
        console.log('📡 Sending route unassign notifications...');
        
        // Notify admin channel
        await pusher.trigger('admin-channel', 'route-unassigned', {
          routeId,
          driverId: oldDriverId,
          driverName: oldDriverName,
          completedDrops,
          totalDrops,
          earningsAdjusted: !!earningsData,
          reason
        });

        // Notify driver channel
        await pusher.trigger(`driver-${oldDriverId}`, 'route-removed', {
          routeId,
          completedDrops,
          totalDrops,
          earnedAmount: earningsData?.adjustedAmount || 0,
          message: `Route removed by admin. ${completedDrops > 0 ? `You earned £${(earningsData?.adjustedAmount / 100).toFixed(2)} for ${completedDrops} completed drops.` : 'No earnings as no drops were completed.'}`,
          reason
        });

        // Notify driver schedule update
        await pusher.trigger(`driver-${oldDriverId}`, 'schedule-updated', {
          type: 'route_removed',
          routeId,
          timestamp: new Date().toISOString()
        });

        // Notify admin schedule update
        await pusher.trigger('admin-schedule', 'schedule-updated', {
          type: 'route_unassigned',
          routeId,
          driverId: oldDriverId,
          timestamp: new Date().toISOString()
        });

        console.log('📡 Real-time notifications sent successfully');
      } catch (pusherError) {
        console.error('⚠️ Failed to send Pusher notifications:', pusherError);
        console.error('⚠️ Error details:', pusherError instanceof Error ? pusherError.message : 'Unknown');
        // Don't fail the request if Pusher fails
      }

      console.log('✅ Route unassigned successfully:', {
        routeId,
        oldDriver: oldDriverName,
        bookingsAffected: (route as any).Booking?.length || 0,
        completedDrops,
        totalDrops,
        earningsAdjusted: !!earningsData,
        reason
      });

      return NextResponse.json({
        success: true,
        message: `Route ${routeId.substring(0, 8)} unassigned from ${oldDriverName}. ${completedDrops > 0 ? `Earnings adjusted for ${completedDrops}/${totalDrops} completed drops.` : ''}`,
        data: {
          routeId,
          previousDriver: oldDriverName,
          bookingsAffected: (route as any).Booking?.length || 0,
          completedDrops,
          totalDrops,
          earningsData,
          reason
        }
      });

    });

  } catch (error) {
    console.error('❌ Error unassigning route:', error);
    console.error('❌ Error name:', error instanceof Error ? error.name : 'Unknown');
    console.error('❌ Error message:', error instanceof Error ? error.message : String(error));
    console.error('❌ Error stack:', error instanceof Error ? error.stack : 'No stack');
    
    return NextResponse.json(
      { 
        success: false,
        error: error instanceof Error ? error.message : 'Failed to unassign route',
        errorType: error instanceof Error ? error.name : 'Unknown',
      },
      { status: 500 }
    );
  }
}

/**
 * GET /api/admin/routes/active
 * 
 * Get all active routes (assigned or in progress)
 */

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';

export const dynamic = 'force-dynamic';

export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const status = searchParams.get('status'); // 'assigned', 'in_progress', 'all'
    const driverId = searchParams.get('driverId');

    // Build where clause
    const where: any = {
      status: { in: ['assigned', 'in_progress'] },
    };

    if (status && status !== 'all') {
      where.status = status;
    }

    if (driverId) {
      where.driverId = driverId;
    }

    // Get active routes
    const routes = await prisma.route.findMany({
      where,
      select: {
        id: true,
        driverId: true,
        vehicleId: true,
        startTime: true,
        endTime: true,
        optimizedDistanceKm: true,
        actualDistanceKm: true,
        totalOutcome: true,
        estimatedDuration: true,
        actualDuration: true,
        status: true,
        completedDrops: true,
        routeNotes: true,
        performanceMultiplier: true,
        bonusesTotal: true,
        penaltiesTotal: true,
        driverPayout: true,
        Booking: {
          select: {
            id: true,
            reference: true,
            status: true,
            deliverySequence: true,
            actualPickupTime: true,
            actualDeliveryTime: true,
            estimatedPickupTime: true,
            pickupAddress: true,
            dropoffAddress: true,
            BookingItem: true,
            customer: {
              select: { id: true, name: true, email: true }
            },
          },
          orderBy: {
            deliverySequence: 'asc',
          },
        },
        driver: {
          select: {
            id: true,
            name: true,
            email: true
          },
        },
      },
      orderBy: {
        createdAt: 'desc',
      },
    });

    // Enrich with real-time tracking data
    const enrichedRoutes = routes.map(route => {
      const completedStops = route.Booking.filter(b => 
        b.actualDeliveryTime !== null
      ).length;
      
      const currentStop = route.Booking.find(b => 
        b.actualPickupTime !== null && b.actualDeliveryTime === null
      );

      const nextStop = route.Booking.find(b => 
        b.actualPickupTime === null
      );

      return {
        ...route,
        progress: {
          completedStops,
          totalStops: route.Booking.length,
          percentage: (completedStops / route.Booking.length) * 100,
          currentStop: currentStop ? {
            bookingId: currentStop.id,
            reference: currentStop.reference,
            pickupAddress: currentStop.pickupAddress,
            dropoffAddress: currentStop.dropoffAddress,
            status: 'in_transit',
          } : null,
          nextStop: nextStop ? {
            bookingId: nextStop.id,
            reference: nextStop.reference,
            pickupAddress: nextStop.pickupAddress,
            estimatedPickupTime: nextStop.estimatedPickupTime,
          } : null,
        },
        driver: (route as any).driver ? {
          id: (route as any).driver.id,
          name: (route as any).driver.name,
          email: (route as any).driver.email,
        } : null,
      };
    });

    // Calculate statistics
    const stats = {
      total: enrichedRoutes.length,
      assigned: enrichedRoutes.filter(r => r.status === 'assigned').length,
      inProgress: enrichedRoutes.filter(r => r.status === 'in_progress').length,
      totalStops: enrichedRoutes.reduce((sum, r: any) => sum + (r.Booking?.length || 0), 0),
      completedStops: enrichedRoutes.reduce((sum, r: any) => sum + (r.progress?.completedStops || 0), 0),
      totalDistance: enrichedRoutes.reduce((sum, r: any) => sum + (r.optimizedDistanceKm || r.actualDistanceKm || 0), 0),
      totalRevenue: enrichedRoutes.reduce((sum, r: any) => {
        const value = Number(r.totalOutcome || 0);
        return (Number.isFinite(value) && value >= 0 && value <= Number.MAX_SAFE_INTEGER) ? sum + value : sum;
      }, 0),
    };

    return NextResponse.json({
      success: true,
      data: {
        routes: enrichedRoutes,
        stats,
      },
    });
  } catch (error) {
    console.error('Error fetching active routes:', error);
    return NextResponse.json(
      { success: false, error: 'Failed to fetch active routes' },
      { status: 500 }
    );
  }
}

/**
 * Automatic Route Creation API
 * System-generated optimized routes
 */

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
import { logAudit } from '@/lib/audit';
import { createUniqueReference } from '@/lib/ref';

export const dynamic = 'force-dynamic';

/**
 * POST /api/admin/routes/auto-create
 * Automatically create optimized routes from pending drops
 */
export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user || (session.user as any).role !== 'admin') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const body = await request.json();
    const { 
      maxDropsPerRoute = 10,
      maxDistanceKm = 50,
      serviceTier = null,
      autoAssignDrivers = false,
    } = body;

    // Get all pending drops
    const pendingDrops = await prisma.drop.findMany({
      where: {
        status: 'pending',
        routeId: null,
        ...(serviceTier && { serviceTier }),
      },
      select: {
        id: true,
        customerId: true,
        pickupAddress: true,
        deliveryAddress: true,
        timeWindowStart: true,
        timeWindowEnd: true,
        quotedPrice: true,
        weight: true,
        volume: true,
        serviceTier: true,
        status: true,
        // Remove estimatedDuration to avoid database error
        Booking: {
          select: {
            customerName: true,
            customerEmail: true,
          }
        }
      },
      orderBy: { timeWindowStart: 'asc' },
      take: 100, // Process in batches
    });

    if (pendingDrops.length === 0) {
      return NextResponse.json({
        success: true,
        message: 'No pending drops available',
        routesCreated: 0,
      });
    }

    // Simple clustering algorithm: group by time window and proximity
    const routes: any[] = [];
    let currentGroup: typeof pendingDrops = [];
    let currentTime = pendingDrops[0].timeWindowStart;

    for (const drop of pendingDrops) {
      // Check if drop fits in current group
      const timeDiff = Math.abs(drop.timeWindowStart.getTime() - currentTime.getTime()) / (1000 * 60 * 60);
      
      if (currentGroup.length >= maxDropsPerRoute || timeDiff > 4) {
        // Time difference > 4 hours, create new group
        if (currentGroup.length > 0) {
          routes.push(currentGroup);
        }
        currentGroup = [drop];
        currentTime = drop.timeWindowStart;
      } else {
        currentGroup.push(drop);
      }
    }

    // Add last group
    if (currentGroup.length > 0) {
      routes.push(currentGroup);
    }

    // Get available drivers if auto-assign is enabled
    let availableDrivers: any[] = [];
    if (autoAssignDrivers) {
      availableDrivers = await prisma.driver.findMany({
        where: {
          status: 'active',
          DriverAvailability: { status: 'online' }
        },
        include: {
          User: { select: { name: true } }
        },
        take: routes.length,
      });
    }

    // Create routes
    const createdRoutes = [];
    for (let i = 0; i < routes.length; i++) {
      const dropGroup = routes[i];
      const totalOutcome = dropGroup.reduce((sum: number, d: any) => {
        const price = Number(d.quotedPrice || 0);
        return (Number.isFinite(price) && price >= 0 && price <= Number.MAX_SAFE_INTEGER) ? sum + price : sum;
      }, 0);
      const totalWeight = dropGroup.reduce((sum: number, d: any) => sum + (d.weight || 0), 0);
      const totalVolume = dropGroup.reduce((sum: number, d: any) => sum + (d.volume || 0), 0);
      const assignedDriver = autoAssignDrivers && availableDrivers[i] ? availableDrivers[i] : null;

      // Generate unified SV reference number
      const routeReference = await createUniqueReference('route');
      
      const route = await prisma.route.create({
        data: {
          reference: routeReference,
          driverId: assignedDriver?.id || null,
          status: assignedDriver ? 'assigned' : 'planned',
          startTime: dropGroup[0].timeWindowStart,
          timeWindowStart: dropGroup[0].timeWindowStart,
          timeWindowEnd: dropGroup[dropGroup.length - 1].timeWindowEnd,
          serviceTier: dropGroup[0].serviceTier || 'standard',
          totalDrops: dropGroup.length,
          completedDrops: 0,
          totalOutcome,
          maxCapacityWeight: totalWeight,
          maxCapacityVolume: totalVolume,
          routeOptimizationVersion: '2.0',
          routeNotes: 'Automatically generated by system',
          routeComplexityScore: Math.min(dropGroup.length, 5),
        }
      });

      // Update drops
      await prisma.drop.updateMany({
        where: { id: { in: dropGroup.map((d: any) => d.id) } },
        data: {
          routeId: route.id,
          status: 'assigned_to_route',
        }
      });

      // Log optimization history
      // Optional: routeOptimizationHistory table may not exist in schema
      /* await prisma.routeOptimizationHistory.create({
        data: {
          routeId: route.id,
          optimizationType: 'initial',
          algorithmVersion: '2.0',
          inputParameters: {
            maxDropsPerRoute,
            maxDistanceKm,
            autoAssignDrivers,
          },
          optimizationResult: {
            dropsCount: dropGroup.length,
            estimatedDuration: dropGroup.length * 30, // 30 min per drop estimate
            totalValue: totalOutcome,
          },
          createdBy: (session.user as any).id,
        }
      }); */

      createdRoutes.push({
        ...route,
        driverName: assignedDriver?.User?.name || 'Unassigned',
        dropCount: dropGroup.length,
      });
    }

    await logAudit(
      (session.user as any).id,
      'auto_create_routes',
      undefined,
      { 
        targetType: 'route', 
        after: { 
          routesCreated: createdRoutes.length,
          totalDrops: pendingDrops.length,
          autoAssignDrivers,
        }
      }
    );

    return NextResponse.json({
      success: true,
      message: `Successfully created ${createdRoutes.length} optimized routes from ${pendingDrops.length} pending drops`,
      routesCreated: createdRoutes.length,
      routes: createdRoutes,
    });

  } catch (error) {
    console.error('❌ Auto-create routes error:', error);
    return NextResponse.json(
      { 
        success: false,
        error: 'Failed to auto-create routes',
        details: error instanceof Error ? error.message : 'Unknown error'
      },
      { status: 500 }
    );
  }
}

/**
 * Bulk Route Operations API
 * 
 * Perform operations on multiple routes simultaneously:
 * - Bulk status change
 * - Bulk assignment/reassignment
 * - Bulk deletion/cancellation
 * - Bulk optimization
 */

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
import { logger } from '@/lib/logger';
import { logAudit } from '@/lib/audit';

export const dynamic = 'force-dynamic';

/**
 * POST /api/admin/routes/bulk
 * Perform bulk operations on routes
 */
export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user || (session.user as any).role !== 'admin') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const adminId = (session.user as any).id;
    const body = await request.json();
    const {
      operation,
      routeIds,
      data,
      forceOperation = false,
    } = body;

    // Validate input
    if (!operation) {
      return NextResponse.json(
        { error: 'Operation is required' },
        { status: 400 }
      );
    }

    if (!routeIds || !Array.isArray(routeIds) || routeIds.length === 0) {
      return NextResponse.json(
        { error: 'Route IDs array is required' },
        { status: 400 }
      );
    }

    if (routeIds.length > 100 && !forceOperation) {
      return NextResponse.json(
        { error: 'Maximum 100 routes per bulk operation (use forceOperation to override)' },
        { status: 400 }
      );
    }

    const results = {
      success: [] as string[],
      failed: [] as { routeId: string; error: string }[],
      total: routeIds.length,
    };

    // Perform bulk operation based on type
    switch (operation) {
      case 'changeStatus':
        await bulkChangeStatus(routeIds, data, results, adminId, session);
        break;

      case 'assignDriver':
        await bulkAssignDriver(routeIds, data, results, adminId, session);
        break;

      case 'unassignDriver':
        await bulkUnassignDriver(routeIds, results, adminId, session);
        break;

      case 'cancel':
        await bulkCancel(routeIds, data, results, adminId, session);
        break;

      case 'delete':
        await bulkDelete(routeIds, data, results, adminId, session, forceOperation);
        break;

      case 'optimize':
        await bulkOptimize(routeIds, results, adminId, session);
        break;

      case 'updateServiceTier':
        await bulkUpdateServiceTier(routeIds, data, results, adminId, session);
        break;

      default:
        return NextResponse.json(
          { error: `Unknown operation: ${operation}` },
          { status: 400 }
        );
    }

    // Log comprehensive audit
    await logAudit({
      userId: adminId,
      action: 'bulk_route_operation',
      entityType: 'route',
      entityId: 'bulk',
      details: {
        operation,
        totalRoutes: routeIds.length,
        successCount: results.success.length,
        failedCount: results.failed.length,
        data,
        forceOperation,
      },
    });

    logger.info('Bulk route operation completed', {
      operation,
      adminId,
      totalRoutes: routeIds.length,
      successCount: results.success.length,
      failedCount: results.failed.length,
    });

    return NextResponse.json({
      success: true,
      message: `Bulk operation completed: ${results.success.length} succeeded, ${results.failed.length} failed`,
      results,
    });

  } catch (error) {
    logger.error('Failed to perform bulk route operation', error as Error);
    return NextResponse.json(
      {
        error: 'Failed to perform bulk route operation',
        details: error instanceof Error ? error.message : 'Unknown error',
      },
      { status: 500 }
    );
  }
}

// Bulk Operation Handlers

async function bulkChangeStatus(
  routeIds: string[],
  data: any,
  results: any,
  adminId: string,
  session: any
) {
  const { status, reason } = data;

  if (!status) {
    throw new Error('Status is required for changeStatus operation');
  }

  for (const routeId of routeIds) {
    try {
      const route = await prisma.route.findUnique({
        where: { id: routeId },
      });

      if (!route) {
        results.failed.push({ routeId, error: 'Route not found' });
        continue;
      }

      await prisma.route.update({
        where: { id: routeId },
        data: {
          status,
          adminNotes: `${route.adminNotes || ''}\n[BULK STATUS CHANGE] ${new Date().toISOString()} - Changed to ${status}${reason ? ` - Reason: ${reason}` : ''}`,
          isModifiedByAdmin: true,
        },
      });

      results.success.push(routeId);
    } catch (error) {
      results.failed.push({
        routeId,
        error: error instanceof Error ? error.message : 'Unknown error',
      });
    }
  }
}

async function bulkAssignDriver(
  routeIds: string[],
  data: any,
  results: any,
  adminId: string,
  session: any
) {
  const { driverId } = data;

  if (!driverId) {
    throw new Error('Driver ID is required for assignDriver operation');
  }

  // Verify driver exists
  const driver = await prisma.driver.findUnique({
    where: { id: driverId },
    include: { User: true }
  });

  if (!driver) {
    throw new Error('Driver not found');
  }

  for (const routeId of routeIds) {
    try {
      const route = await prisma.route.update({
        where: { id: routeId },
        data: {
          driverId,
          status: 'assigned',
          adminNotes: `[BULK ASSIGNMENT] ${new Date().toISOString()} - Assigned to driver ${driverId}`,
          isModifiedByAdmin: true,
        },
        include: {
          drops: {
            include: {
              Booking: true
            }
          }
        }
      });

      // Send SMS notification to driver
      if (driver.User.phone) {
        try {
          const { getVoodooSMSService } = await import('@/lib/sms/VoodooSMSService');
          const smsService = getVoodooSMSService();
          
          const smsMessage = `🚚 New Route Assigned!\n\nRoute: ${route.id}\nStops: ${route.drops.length}\nStart: ${route.startTime.toLocaleString()}\n\nCheck your email for full details.\n\nSpeedy Van`;
          
          const smsResult = await smsService.sendSMS({
            to: driver.User.phone,
            message: smsMessage
          });

          if (smsResult.success) {
            console.log(`✅ SMS sent to driver ${driverId} for route ${routeId}`);
          } else {
            console.error('❌ SMS sending failed:', smsResult.error);
          }
        } catch (smsError) {
          console.error('❌ SMS service error:', smsError);
        }
      } else {
        console.log('ℹ️ No phone number available for driver SMS notification');
      }

      results.success.push(routeId);
    } catch (error) {
      results.failed.push({
        routeId,
        error: error instanceof Error ? error.message : 'Unknown error',
      });
    }
  }
}

async function bulkUnassignDriver(
  routeIds: string[],
  results: any,
  adminId: string,
  session: any
) {
  for (const routeId of routeIds) {
    try {
      await prisma.route.update({
        where: { id: routeId },
        data: {
          driverId: null,
          status: 'pending_assignment',
          adminNotes: `[BULK UNASSIGNMENT] ${new Date().toISOString()} - Driver unassigned`,
          isModifiedByAdmin: true,
        },
      });

      results.success.push(routeId);
    } catch (error) {
      results.failed.push({
        routeId,
        error: error instanceof Error ? error.message : 'Unknown error',
      });
    }
  }
}

async function bulkCancel(
  routeIds: string[],
  data: any,
  results: any,
  adminId: string,
  session: any
) {
  const { reason } = data;

  for (const routeId of routeIds) {
    try {
      await prisma.route.update({
        where: { id: routeId },
        data: {
          status: 'cancelled',
          adminNotes: `[BULK CANCELLATION] ${new Date().toISOString()} - Cancelled${reason ? ` - Reason: ${reason}` : ''}`,
          isModifiedByAdmin: true,
        },
      });

      // Update drops
      await prisma.drop.updateMany({
        where: { routeId },
        data: { status: 'failed' },
      });

      results.success.push(routeId);
    } catch (error) {
      results.failed.push({
        routeId,
        error: error instanceof Error ? error.message : 'Unknown error',
      });
    }
  }
}

async function bulkDelete(
  routeIds: string[],
  data: any,
  results: any,
  adminId: string,
  session: any,
  forceOperation: boolean
) {
  const { hardDelete = false } = data;

  for (const routeId of routeIds) {
    try {
      const route = await prisma.route.findUnique({
        where: { id: routeId },
      });

      if (!route) {
        results.failed.push({ routeId, error: 'Route not found' });
        continue;
      }

      if (!forceOperation && route.status !== 'planned' && hardDelete) {
        results.failed.push({
          routeId,
          error: 'Can only hard delete planned routes',
        });
        continue;
      }

      if (hardDelete) {
        // Delete drops first
        await prisma.drop.deleteMany({
          where: { routeId },
        });

        // Delete route
        await prisma.route.delete({
          where: { id: routeId },
        });
      } else {
        // Soft delete (cancel)
        await prisma.route.update({
          where: { id: routeId },
          data: {
            status: 'cancelled',
            adminNotes: `[BULK DELETION] ${new Date().toISOString()} - Cancelled`,
          },
        });
      }

      results.success.push(routeId);
    } catch (error) {
      results.failed.push({
        routeId,
        error: error instanceof Error ? error.message : 'Unknown error',
      });
    }
  }
}

