export const dynamic = 'force-dynamic';

interface PreviewRequest {
  maxDropsPerRoute: number;
  maxDistanceKm: number;
  optimizeBy: 'distance' | 'time' | 'area';
  autoAssign: boolean;
  driverIds?: string[];
