// GET /api/admin/staff - List all staff
export async function GET(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    const user = (session as any)?.user as { role?: string } | undefined;

    if (!user || user.role !== 'admin') {
      return NextResponse.json({ error: 'Unauthorized - Admin access required' }, { status: 401 });
    }

    const { searchParams } = new URL(request.url);
    const department = searchParams.get('department');
    const status = searchParams.get('status');
    const search = searchParams.get('search');
    const limit = parseInt(searchParams.get('limit') || '50');
    const offset = parseInt(searchParams.get('offset') || '0');

    const where: any = {};

    if (department && department.trim()) {
      where.department = department;
    }

    if (status && status.trim()) {
      where.status = status;
    }

    if (search) {
      where.OR = [
        { employeeId: { contains: search, mode: 'insensitive' } },
        { User: { name: { contains: search, mode: 'insensitive' } } },
        { User: { email: { contains: search, mode: 'insensitive' } } },
      ];
    }

    const [staff, total] = await Promise.all([
      prisma.staff.findMany({
        where,
        include: {
          User: {
            select: {
              id: true,
              email: true,
              name: true,
              phone: true,
              role: true,
              adminRole: true,
            },
          },
        },
        orderBy: { createdAt: 'desc' },
        take: limit,
        skip: offset,
      }),
      prisma.staff.count({ where }),
    ]);

    return NextResponse.json({
      success: true,
      staff,
      pagination: {
        total,
        limit,
        offset,
        hasMore: offset + limit < total,
      },
    });
  } catch (error) {
    console.error('Get staff error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

// POST /api/admin/staff - Create new staff
export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    const user = (session as any)?.user as { role?: string } | undefined;

    if (!user || user.role !== 'admin') {
      return NextResponse.json({ error: 'Unauthorized - Admin access required' }, { status: 401 });
    }

    const body = await request.json();
    const data = createStaffSchema.parse(body);

    // Check if user already exists
    const existingUser = await prisma.user.findUnique({
      where: { email: data.email.toLowerCase() },
    });

    if (existingUser) {
      return NextResponse.json(
        { error: 'User with this email already exists' },
        { status: 400 }
      );
    }

    // Check if employee ID already exists
    const existingStaff = await prisma.staff.findUnique({
      where: { employeeId: data.employeeId },
    });

    if (existingStaff) {
      return NextResponse.json(
        { error: 'Employee ID already exists' },
        { status: 400 }
      );
    }

    // Hash password
    const hashedPassword = await bcrypt.hash(data.password, 10);

    // Create user and staff
    const createdUser = await prisma.user.create({
      data: {
        email: data.email.toLowerCase(),
        name: data.name,
        phone: data.phone,
        password: hashedPassword,
        role: 'staff',
        emailVerified: true,
      },
    });

    const staff = await prisma.staff.create({
      data: {
        userId: createdUser.id,
        employeeId: data.employeeId,
        department: data.department,
        position: data.position,
        employmentType: data.employmentType || 'full_time',
        workSchedule: data.workSchedule || {
          defaultShift: { start: '09:00', end: '17:00' },
          breakMinutes: 60,
          minHours: 8,
        },
        hireDate: new Date(),
      },
      include: {
        User: {
          select: {
            id: true,
            email: true,
            name: true,
            phone: true,
          },
        },
      },
    });

    return NextResponse.json({
      success: true,
      staff,
    });
  } catch (error) {
    console.error('Create staff error:', error);

    if (error instanceof z.ZodError) {
      return NextResponse.json(
        { error: 'Invalid request data', details: error.issues },
        { status: 400 }
      );
    }

    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth/next';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';

// Force dynamic rendering (uses headers/cookies/getServerSession)
export const dynamic = 'force-dynamic';

function pad(num: number, size = 4): string {
  let s = String(num);
  while (s.length < size) s = '0' + s;
  return s;
}

async function generateEmployeeId(): Promise<string> {
  // Generate sequential ADM-XXXX based on count of existing staff with ADM- prefix
  const count = await prisma.staff.count({
    where: { employeeId: { startsWith: 'ADM-' } },
  });
  return `ADM-${pad(count + 1)}`;
}

export async function POST(_request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    const user = (session as any)?.user as { role?: string } | undefined;

    if (!user || user.role !== 'admin') {
      return NextResponse.json({ error: 'Unauthorized - Admin access required' }, { status: 401 });
    }

    // Find all active admin users
    const admins = await prisma.user.findMany({
      where: { role: 'admin', isActive: true },
      select: { id: true, email: true, name: true, phone: true, adminRole: true },
      orderBy: { createdAt: 'asc' },
    });

    if (admins.length === 0) {
      return NextResponse.json({ success: true, created: 0, skipped: 0 });
    }

    let created = 0;
    let skipped = 0;

    const mapRole = (adminRole?: string | null): { department: string; position: string } => {
      switch ((adminRole || '').toLowerCase()) {
        case 'superadmin':
          return { department: 'Administration', position: 'Super Admin' };
        case 'ops':
          return { department: 'Operations', position: 'Operations Admin' };
        case 'support':
          return { department: 'Support', position: 'Support Admin' };
        case 'reviewer':
          return { department: 'Compliance', position: 'Reviewer Admin' };
        case 'finance':
          return { department: 'Finance', position: 'Finance Admin' };
        case 'read_only':
        default:
          return { department: 'Administration', position: 'Admin' };
      }
    };

    for (const admin of admins) {
      const exists = await prisma.staff.findFirst({
        where: { userId: admin.id },
        select: { id: true },
      });

      if (exists) {
        skipped += 1;
        continue;
      }

      const employeeId = await generateEmployeeId();
      const roleMap = mapRole((admin as any).adminRole);

      await prisma.staff.create({
        data: {
          userId: admin.id,
          employeeId,
          department: roleMap.department,
          position: roleMap.position,
          employmentType: 'full_time',
          status: 'active',
          hireDate: new Date(),
          workSchedule: {
            defaultShift: { start: '09:00', end: '17:00' },
            breakMinutes: 60,
            minHours: 8,
            weeklyOverrides: {},
          },
        },
      });
      created += 1;
    }

    return NextResponse.json({ success: true, created, skipped });
  } catch (error) {
    console.error('Sync admins to staff error:', error);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { z } from 'zod';
import { withApiHandler } from '@/lib/api/guard';

// Like/Unlike validation schema
const likeActionSchema = z.object({
  action: z.enum(['like', 'unlike']),
  userId: z.string().min(1, 'User ID is required'),
  userType: z.enum(['driver', 'admin']).default('driver'),
});

// POST /api/admin/stories/[id]/like - Like or unlike a story
async function handleStoryLike(request: NextRequest) {
  try {
    // Extract story ID from URL
    const url = new URL(request.url);
    const storyId = url.pathname.split('/').pop() || '';

    const body = await request.json();
    const validatedData = likeActionSchema.parse(body);

    const { action, userId, userType } = validatedData;

    // Check if story exists
    const story = await prisma.adminStory.findUnique({
      where: { id: storyId },
    });

    if (!story) {
      return NextResponse.json(
        {
          success: false,
          error: 'Story not found',
        },
        { status: 404 }
      );
    }

    if (action === 'like') {
      // Like the story (upsert to avoid duplicates)
      await prisma.storyLike.upsert({
        where: {
          storyId_userId: {
            storyId: storyId,
            userId: userId,
          },
        },
        update: {
          likedAt: new Date(),
        },
        create: {
          storyId: storyId,
          userId: userId,
          userType: userType,
        },
      });

      console.log(`❤️ ${userType} ${userId} liked story ${storyId}`);
    } else if (action === 'unlike') {
      // Unlike the story (delete the like record)
      await prisma.storyLike.deleteMany({
        where: {
          storyId: storyId,
          userId: userId,
        },
      });

      console.log(`💔 ${userType} ${userId} unliked story ${storyId}`);
    }

    // Get updated stats
    const updatedStats = await prisma.adminStory.findUnique({
      where: { id: storyId },
      select: {
        _count: {
          select: {
            views: true,
            likes: true,
            shares: true,
          },
        },
      },
    });

    return NextResponse.json({
      success: true,
      action: action,
      stats: {
        viewCount: updatedStats?._count.views || 0,
        likeCount: updatedStats?._count.likes || 0,
        shareCount: updatedStats?._count.shares || 0,
      },
    });
  } catch (error) {
    if (error instanceof z.ZodError) {
      return NextResponse.json(
        {
          success: false,
          error: 'Validation failed',
          details: error.errors,
        },
        { status: 400 }
      );
    }

    console.error('Error handling story like:', error);
    return NextResponse.json(
      {
        success: false,
        error: 'Failed to process like action',
      },
      { status: 500 }
    );
  }
}

// GET /api/admin/stories/[id]/like - Check if user liked the story
async function checkStoryLike(request: NextRequest) {
  try {
    // Extract story ID from URL
    const url = new URL(request.url);
    const storyId = url.pathname.split('/').pop() || '';

    const { searchParams } = new URL(request.url);
    const userId = searchParams.get('userId');
    const userType = searchParams.get('userType') || 'driver';

    if (!userId) {
      return NextResponse.json(
        {
          success: false,
          error: 'userId parameter is required',
        },
        { status: 400 }
      );
    }

    const like = await prisma.storyLike.findUnique({
      where: {
        storyId_userId: {
          storyId: storyId,
          userId: userId,
        },
      },
    });

    return NextResponse.json({
      success: true,
      isLiked: !!like,
      likedAt: like?.likedAt,
    });
  } catch (error) {
    console.error('Error checking story like:', error);
    return NextResponse.json(
      {
        success: false,
        error: 'Failed to check like status',
      },
      { status: 500 }
    );
  }
}

