          success: false,
          error: 'Validation failed',
          details: error.errors,
        },
        { status: 400 }
      );
    }

    console.error('Error updating story:', error);
    return NextResponse.json(
      {
        success: false,
        error: 'Failed to update story',
      },
      { status: 500 }
    );
  }
}

