    console.error('Error fetching story shares:', error);
    return NextResponse.json(
      {
        success: false,
        error: 'Failed to fetch share data',
      },
      { status: 500 }
    );
  }
}

export const POST = withApiHandler(handleStoryShare);
export const GET = withApiHandler(getStoryShares);

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { withApiHandler } from '@/lib/api/guard';

export const dynamic = 'force-dynamic';

// GET /api/admin/stories/current - Get the current active story for drivers
async function getCurrentStory(request: NextRequest) {
  try {
    // Find the most recent active story with engagement stats
    const currentStory = await prisma.adminStory.findFirst({
      where: {
        isActive: true,
      },
      orderBy: {
        publishedAt: 'desc', // Most recently published first
      },
      include: {
        _count: {
          select: {
            views: true,
            likes: true,
            shares: true,
          },
        },
      },
    });

    if (!currentStory) {
      return NextResponse.json({
        success: true,
        story: null,
      });
    }

    // Track view if this is accessed by a driver (has user-agent and comes from mobile app)
    const userAgent = request.headers.get('user-agent') || '';
    const isMobileApp = userAgent.includes('Expo') || userAgent.includes('React Native');

    if (isMobileApp) {
      // Try to get user ID from headers (assuming we pass it from the mobile app)
      const userId = request.headers.get('x-user-id');
      const userType = request.headers.get('x-user-type') || 'driver';

      if (userId) {
        try {
          // Track the view (upsert to avoid duplicates)
          await prisma.storyView.upsert({
            where: {
              storyId_userId: {
                storyId: currentStory.id,
                userId: userId,
              },
            },
            update: {
              viewedAt: new Date(),
            },
            create: {
              storyId: currentStory.id,
              userId: userId,
              userType: userType,
            },
          });
          console.log(`👁️ Tracked view for story ${currentStory.id} by ${userType} ${userId}`);
        } catch (viewError) {
          console.warn('⚠️ Failed to track story view:', viewError);
          // Don't fail the request if view tracking fails
        }
      }
    } else {
      // Track admin views as well
      const userId = request.headers.get('x-user-id') || 'system';
      const userType = 'admin';

      try {
        await prisma.storyView.upsert({
          where: {
            storyId_userId: {
              storyId: currentStory.id,
              userId: userId,
            },
          },
          update: {
            viewedAt: new Date(),
          },
          create: {
            storyId: currentStory.id,
            userId: userId,
            userType: userType,
          },
        });
        console.log(`👁️ Tracked admin view for story ${currentStory.id}`);
      } catch (viewError) {
        console.warn('⚠️ Failed to track admin story view:', viewError);
        // Don't fail the request if view tracking fails
      }
    }

    return NextResponse.json({
      success: true,
      story: {
        ...currentStory,
        stats: {
          viewCount: currentStory._count.views,
          likeCount: currentStory._count.likes,
          shareCount: currentStory._count.shares,
        },
      },
    });
  } catch (error) {
    console.error('Error fetching current story:', error);
    return NextResponse.json(
      {
        success: false,
        error: 'Failed to fetch current story',
      },
      { status: 500 }
    );
  }
}

export const GET = withApiHandler(getCurrentStory);

import { NextRequest } from 'next/server';
import { prisma } from '@/lib/prisma';
import { z } from 'zod';
import { getPusherServer } from '@/lib/pusher';
import { withApiHandler, requireRole, httpJson } from '@/lib/api/guard';

// Story validation schema
const storySchema = z.object({
  title: z.string().min(1, 'Title is required'),
  content: z.string().min(1, 'Content is required'),
  type: z.enum(['text', 'image', 'video']),
  mediaUrl: z.string().optional(),
  isActive: z.boolean().default(true),
  publishedAt: z.string().datetime().optional().nullable(),
});

// GET /api/admin/stories - List all stories
async function getStories(request: NextRequest) {
  try {
    await requireRole(request, 'admin');

    const stories = await prisma.adminStory.findMany({
      orderBy: {
        createdAt: 'desc',
      },
      include: {
        _count: {
          select: {
            views: true,
            likes: true,
            shares: true,
          },
        },
      },
    });

    // Transform the response to include stats
    const storiesWithStats = stories.map(story => ({
      ...story,
      stats: {
        viewCount: story._count.views,
        likeCount: story._count.likes,
        shareCount: story._count.shares,
      },
      _count: undefined, // Remove the raw _count field
    }));

    return httpJson(200, {
      success: true,
      stories: storiesWithStats,
    });
  } catch (error: any) {
    console.error('Error fetching stories:', error);
    return httpJson(500, {
      success: false,
      error: error.message || 'Failed to fetch stories',
    });
  }
}

// POST /api/admin/stories - Create new story
async function createStory(request: NextRequest) {
  try {
    await requireRole(request, 'admin');

    const body = await request.json();
    const validatedData = storySchema.parse(body);

    const story = await prisma.adminStory.create({
      data: {
        title: validatedData.title,
        content: validatedData.content,
        type: validatedData.type,
        mediaUrl: validatedData.mediaUrl,
        isActive: validatedData.isActive,
        publishedAt: validatedData.publishedAt ? new Date(validatedData.publishedAt) : null,
      },
    });

    // Trigger real-time sync via Pusher
    try {
      const pusher = getPusherServer();
      await pusher.trigger('admin-stories', 'story-created', {
        story,
        action: 'created',
        timestamp: new Date().toISOString(),
      });
      console.log('📡 Pushed story creation event');
    } catch (pusherError) {
      console.warn('⚠️ Failed to push story creation event:', pusherError);
    }

    return httpJson(201, {
      success: true,
      story,
    });
  } catch (error: any) {
    if (error instanceof z.ZodError) {
      return httpJson(400, {
        success: false,
        error: 'Validation failed',
        details: error.errors,
      });
    }

    console.error('Error creating story:', error);
    return httpJson(500, {
      success: false,
      error: error.message || 'Failed to create story',
    });
  }
}

// Export with authentication guards
export const GET = withApiHandler(getStories);
export const POST = withApiHandler(createStory);

// Helper function to trigger story sync
async function triggerStorySync() {
  try {
    // This could trigger Pusher or other real-time mechanisms
    // For now, we'll just log the sync trigger
    console.log('🔄 Story sync triggered');
  } catch (error) {
    console.warn('Failed to trigger story sync:', error);
  }
}

