async function simulateLocationUpdate() {
  try {
    // Find an active booking to simulate update for
    const activeBooking = await prisma.booking.findFirst({
      where: {
        status: 'CONFIRMED',
        driverId: { not: null }
      }
    });

    if (!activeBooking) {
      return NextResponse.json({
        success: false,
        error: 'No active bookings with assigned drivers found'
      });
    }

    // Get driver info separately
    const driver = await prisma.driver.findUnique({
      where: { id: activeBooking.driverId! },
      include: {
        User: {
          select: { name: true, email: true }
        }
      }
    });
    const pusher = getPusherServer();

    // Simulate location update
    await pusher.trigger('admin-tracking', 'location-update', {
      driverId: driver?.id,
      bookingId: activeBooking.id,
      bookingReference: activeBooking.reference,
      lat: 51.5074 + (Math.random() - 0.5) * 0.01, // Small random offset
      lng: -0.1278 + (Math.random() - 0.5) * 0.01,
      timestamp: new Date().toISOString(),
      customerName: activeBooking.customerName,
      simulated: true,
    });

    return NextResponse.json({
      success: true,
      message: 'Simulated location update sent',
      booking: {
        reference: activeBooking.reference,
        driverName: driver?.User?.name,
        customerName: activeBooking.customerName,
      }
    });
  } catch (error) {
    console.error('❌ Location update simulation failed:', error);
    return NextResponse.json(
      { success: false, error: 'Failed to simulate location update' },
      { status: 500 }
    );
  }
}

async function checkActiveDrivers() {
  try {
    const activeDrivers = await prisma.driverAvailability.findMany({
      where: {
        status: 'online',
        lastSeenAt: {
          gte: new Date(Date.now() - 1000 * 60 * 30) // Last 30 minutes
        }
      }
    });

    const driversWithJobs = await prisma.assignment.findMany({
      where: {
        status: 'accepted',
      },
      include: {
        Booking: {
          select: {
            reference: true,
            status: true,
          }
        }
      }
    });

    // Get driver names separately
    const driverIds = [...new Set([...activeDrivers.map((d: any) => d.driverId), ...driversWithJobs.map((a: any) => a.driverId)])];
    const drivers = await prisma.driver.findMany({
      where: { id: { in: driverIds } },
      include: {
        User: {
          select: { name: true, email: true }
        }
      }
    });

    const driverMap = new Map(drivers.map((d: any) => [d.id, d]));

    return NextResponse.json({
      success: true,
      data: {
        onlineDrivers: activeDrivers.length,
        driversWithJobs: driversWithJobs.length,
        activeDriversList: activeDrivers.map((d: any) => {
          const driver = driverMap.get(d.driverId);
          return {
            id: d.driverId,
            name: (driver as any)?.User?.name || 'Unknown',
            lastSeen: d.lastSeenAt,
            hasLocation: !!(d.lastLat && d.lastLng),
            lastLocation: d.lastLat && d.lastLng ? { lat: d.lastLat, lng: d.lastLng } : null,
          };
        }),
        driversWithJobsList: driversWithJobs.map((a: any) => {
          const driver = driverMap.get(a.driverId);
          return {
            driverId: a.driverId,
            driverName: (driver as any)?.User?.name || 'Unknown',
            bookingReference: a.Booking.reference,
            bookingStatus: a.Booking.status,
          };
        }),
      }
    });
  } catch (error) {
    console.error('❌ Active drivers check failed:', error);
    return NextResponse.json(
      { success: false, error: 'Failed to check active drivers' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
import { getActiveAssignment } from '@/lib/utils/assignment-helpers';

export const dynamic = 'force-dynamic';

export async function GET(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user || (session.user as any).role !== 'admin') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const { searchParams } = new URL(request.url);
    const search = searchParams.get('search') || '';
    const status = searchParams.get('status') || '';
    const includeTracking = searchParams.get('includeTracking') === 'true';

    // Build where clause
    const where: any = {
      status: { in: ['CONFIRMED', 'COMPLETED'] }, // Only active bookings
    };

    if (search) {
      where.OR = [
        { reference: { contains: search, mode: 'insensitive' } },
        { unifiedBookingId: { contains: search, mode: 'insensitive' } },
        { customerName: { contains: search, mode: 'insensitive' } },
        { customerEmail: { contains: search, mode: 'insensitive' } },
      ];
    }

    if (status && status !== 'all') {
      where.status = status;
    }

    // Get active bookings with tracking data
    const bookings = await prisma.booking.findMany({
      where,
      include: {
        driver: {
          include: {
            User: {
              select: {
                name: true,
                email: true,
              },
            },
          },
        },
        pickupAddress: true,
        dropoffAddress: true,
        Assignment: {
          include: {
            JobEvent: {
              orderBy: { createdAt: 'desc' },
              take: 5,
              select: {
                step: true,
                createdAt: true,
                notes: true,
              },
            },
          },
        },
        TrackingPing: {
          orderBy: { createdAt: 'desc' },
          take: 10,
          select: {
            lat: true,
            lng: true,
            createdAt: true,
          },
        },
      },
      orderBy: { scheduledAt: 'asc' },
    });

    // Process bookings to include tracking information
    const trackingBookings = bookings.map(booking => {
      // Calculate route progress
      let routeProgress = 0;
      const activeAssignment = getActiveAssignment(booking.Assignment);
      const jobEvents = activeAssignment?.JobEvent || [];
      const currentStep = jobEvents[0]?.step;

      const stepProgress: Record<string, number> = {
        navigate_to_pickup: 20,
        arrived_at_pickup: 30,
        loading_started: 40,
        loading_completed: 50,
        en_route_to_dropoff: 70,
        arrived_at_dropoff: 80,
        unloading_started: 90,
        unloading_completed: 95,
        job_completed: 100,
      };

      if (currentStep && stepProgress[currentStep]) {
        routeProgress = stepProgress[currentStep];
      } else {
        switch (booking.status) {
          case 'CONFIRMED':
            routeProgress = 15;
            break;
          case 'CONFIRMED':
            routeProgress = 50;
            break;
          default:
            routeProgress = 0;
        }
      }

      // Get current location
      let currentLocation = null;
      if (
        includeTracking &&
        booking.TrackingPing &&
        booking.TrackingPing.length > 0
      ) {
        const latestPing = booking.TrackingPing[0];
        currentLocation = {
          lat: latestPing.lat,
          lng: latestPing.lng,
          timestamp: latestPing.createdAt,
        };
      }

      // Calculate ETA
      let eta = null;
      if (booking.scheduledAt) {
        const now = new Date();
        const scheduledTime = new Date(booking.scheduledAt);
        const timeDiff = scheduledTime.getTime() - now.getTime();

        if (timeDiff > 0) {
          eta = {
            estimatedArrival: scheduledTime,
            minutesRemaining: Math.round(timeDiff / (1000 * 60)),
            isOnTime: timeDiff > -15 * 60 * 1000,
          };
        } else if (timeDiff > -60 * 60 * 1000) {
          eta = {
            estimatedArrival: new Date(now.getTime() + 30 * 60 * 1000),
            minutesRemaining: 30,
            isOnTime: false,
          };
        }
      }

      return {
        id: booking.id,
        reference: booking.reference,
        unifiedBookingId: booking.reference, // Using reference as unified ID
        status: booking.status,
        scheduledAt: booking.scheduledAt,
        customer: {
          name: booking.customerName,
          email: booking.customerEmail,
          phone: booking.customerPhone,
        },
        driver: booking.driver
          ? {
              id: booking.driver.id,
              name: booking.driver.User?.name,
              email: booking.driver.User?.email,
            }
          : null,
        addresses: {
          pickup: {
            label: booking.pickupAddress.label,
            postcode: booking.pickupAddress.postcode,
            coordinates: {
              lat: booking.pickupAddress.lat,
              lng: booking.pickupAddress.lng,
            },
          },
          dropoff: {
            label: booking.dropoffAddress.label,
            postcode: booking.dropoffAddress.postcode,
            coordinates: {
              lat: booking.dropoffAddress.lat,
              lng: booking.dropoffAddress.lng,
            },
          },
        },
        routeProgress,
        currentLocation,
        eta,
        lastEvent: jobEvents[0] || null,
        jobTimeline: jobEvents.map(event => ({
          step: event.step,
          label: getStepLabel(event.step),
          timestamp: event.createdAt,
          notes: event.notes,
        })),
        trackingPings: includeTracking ? booking.TrackingPing : [],
        lastUpdated: new Date().toISOString(),
      };
    });

    // Get summary statistics
    const summary = {
      totalBookings: trackingBookings.length,
      confirmedBookings: trackingBookings.filter(b => b.status === 'CONFIRMED')
        .length,
      inProgressBookings: trackingBookings.filter(b => b.status === 'CONFIRMED')
        .length,
      withLiveTracking: trackingBookings.filter(b => b.currentLocation).length,
      averageProgress:
        trackingBookings.length > 0
          ? Math.round(
              trackingBookings.reduce((sum, b) => sum + b.routeProgress, 0) /
                trackingBookings.length
            )
          : 0,
    };

    return NextResponse.json({
      success: true,
      bookings: trackingBookings,
      summary,
      lastUpdated: new Date().toISOString(),
    });
  } catch (error) {
    console.error('❌ Admin tracking API error:', error);
    return NextResponse.json(
      { error: 'Failed to fetch tracking data' },
      { status: 500 }
    );
  }
}

function getStepLabel(step: string): string {
  const stepLabels: Record<string, string> = {
    navigate_to_pickup: 'En Route to Pickup',
    arrived_at_pickup: 'Arrived at Pickup',
    loading_started: 'Loading Started',
    loading_completed: 'Loading Completed',
    en_route_to_dropoff: 'En Route to Delivery',
    arrived_at_dropoff: 'Arrived at Delivery',
    unloading_started: 'Unloading Started',
    unloading_completed: 'Unloading Completed',
    job_completed: 'Job Completed',
    customer_signature: 'Customer Signature',
    damage_notes: 'Damage Notes',
    item_count_verification: 'Item Count Verification',
  };

  return (
    stepLabels[step] ||
    step.replace(/_/g, ' ').replace(/\b\w/g, l => l.toUpperCase())
  );
}

import { NextRequest, NextResponse } from 'next/server';
import { writeFile, mkdir } from 'fs/promises';
import { join } from 'path';
import { randomUUID } from 'crypto';

// POST /api/admin/upload - Upload media files for stories
export async function POST(request: NextRequest) {
  try {
    const formData = await request.formData();
    const file = formData.get('file') as File;

    if (!file) {
      return NextResponse.json(
        {
          success: false,
          error: 'No file provided',
        },
        { status: 400 }
      );
    }

    // Validate file type
    const allowedTypes = ['image/jpeg', 'image/png', 'image/gif', 'image/webp', 'video/mp4', 'video/quicktime'];
    if (!allowedTypes.includes(file.type)) {
      return NextResponse.json(
        {
          success: false,
          error: 'Invalid file type. Only images and videos are allowed.',
        },
        { status: 400 }
      );
    }

    // Validate file size (10MB limit)
    const maxSize = 10 * 1024 * 1024; // 10MB
    if (file.size > maxSize) {
      return NextResponse.json(
        {
          success: false,
          error: 'File too large. Maximum size is 10MB.',
        },
        { status: 400 }
      );
    }

    // Generate unique filename
    const fileExtension = file.name.split('.').pop();
    const fileName = `${randomUUID()}.${fileExtension}`;

    // Create uploads directory if it doesn't exist
    const uploadsDir = join(process.cwd(), 'public', 'uploads', 'stories');
    try {
      await mkdir(uploadsDir, { recursive: true });
    } catch (error) {
      // Directory might already exist, continue
    }

    // Convert file to buffer and save
    const bytes = await file.arrayBuffer();
    const buffer = Buffer.from(bytes);
    const filePath = join(uploadsDir, fileName);

    await writeFile(filePath, new Uint8Array(buffer));

    // Generate public URL
    const url = `/uploads/stories/${fileName}`;

    return NextResponse.json({
      success: true,
      url,
      fileName,
      size: file.size,
      type: file.type,
    });
  } catch (error) {
    console.error('Error uploading file:', error);
    return NextResponse.json(
      {
        success: false,
        error: 'Failed to upload file',
      },
