import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { withApiHandler, requireRole, httpJson } from '@/lib/api/guard';
import { parseJson, parseParams } from '@/lib/validation/helpers';
import { adminUserUpdate, idParam } from '@/lib/validation/schemas';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';

// PUT /api/admin/users/[id] - Update admin user
export const PUT = withApiHandler(
  async (request: NextRequest) => {
  const user = await requireRole(request, 'admin');

    const url = new URL(request.url);
    const id = url.pathname.split('/').pop();
    if (!id) return NextResponse.json({ error: 'Invalid user ID' }, { status: 400 });

    const paramValidation = parseParams({ id }, idParam);
    if (!paramValidation.ok) return paramValidation.error;

    const parsed = await parseJson(request, adminUserUpdate);
    if (!parsed.ok) return parsed.error;

    const userId = paramValidation.data.id;
    const { name, email, adminRole, isActive } = parsed.data;

    // Check if user exists and is an admin
    const existingUser = await prisma.user.findFirst({
      where: {
        id: userId,
        role: 'admin',
      },
    });

    if (!existingUser) {
      return httpJson(404, { error: 'Admin user not found' });
    }

    // Check if email is already taken by another user
    if (email && email !== existingUser.email) {
      const emailExists = await prisma.user.findUnique({
        where: { email },
      });

      if (emailExists) {
        return httpJson(409, { error: 'Email already in use' });
      }
    }

    // Prevent superadmin from being deactivated by non-superadmin
    if (existingUser.adminRole === 'superadmin' && isActive === false) {
      const session = await getServerSession(authOptions);
      const currentUser = await prisma.user.findUnique({
        where: { id: (session?.user as any)?.id },
      });

      if (currentUser?.adminRole !== 'superadmin') {
        return httpJson(403, {
          error: 'Only superadmin can deactivate superadmin accounts',
        });
      }
    }

    // Build update data object, only including fields that are provided
    const updateData: any = {};
    if (name !== undefined) updateData.name = name;
    if (email !== undefined) updateData.email = email;
    if (adminRole !== undefined) updateData.adminRole = adminRole;
    if (isActive !== undefined) updateData.isActive = isActive;

    // Update admin user
    const updatedUser = await prisma.user.update({
      where: { id: userId },
      data: updateData,
      select: {
        id: true,
        name: true,
        email: true,
        adminRole: true,
        isActive: true,
        lastLogin: true,
        twoFactorEnabled: true,
        createdAt: true,
      },
    });

    return NextResponse.json(updatedUser);
  }
);

// DELETE /api/admin/users/[id] - Delete admin user
export const DELETE = withApiHandler(
  async (request: NextRequest) => {
  const user = await requireRole(request, 'admin');

    const url = new URL(request.url);
    const id = url.pathname.split('/').pop();
    if (!id) return NextResponse.json({ error: 'Invalid user ID' }, { status: 400 });

    const paramValidation = parseParams({ id }, idParam);
    if (!paramValidation.ok) return paramValidation.error;

    const userId = paramValidation.data.id;

    // Check if user exists and is an admin
    const existingUser = await prisma.user.findFirst({
      where: {
        id: userId,
        role: 'admin',
      },
    });

    if (!existingUser) {
      return httpJson(404, { error: 'Admin user not found' });
    }

    // Prevent self-deletion
    const session = await getServerSession(authOptions);
    if (userId === (session?.user as any)?.id) {
      return httpJson(400, { error: 'Cannot delete your own account' });
    }

    // Prevent deletion of the last superadmin
    if (existingUser.adminRole === 'superadmin') {
      const superadminCount = await prisma.user.count({
        where: {
          role: 'admin',
          adminRole: 'superadmin',
          isActive: true,
        },
      });

      if (superadminCount <= 1) {
        return httpJson(400, {
          error: 'Cannot delete the last superadmin account',
        });
      }
    }

    // Delete admin user
    await prisma.user.delete({
      where: { id: userId },
    });

    return NextResponse.json({ message: 'Admin user deleted successfully' });
  }
);

import { NextRequest } from 'next/server';
import { prisma } from '@/lib/prisma';
import { Prisma } from '@prisma/client';
import bcrypt from 'bcryptjs';
import { withApiHandler, requireRole, httpJson } from '@/lib/api/guard';
import { parseJson, parseQueryParams } from '@/lib/validation/helpers';
import {
  adminUserCreate,
  paginationQuery,
  searchQuery,
} from '@/lib/validation/schemas';
import { unifiedEmailService } from '@/lib/email/UnifiedEmailService';

// GET /api/admin/users - Get all admin users
export const GET = withApiHandler(async (request: NextRequest) => {
  let user;
  try {
    user = await requireRole(request, 'admin');
  } catch (error: any) {
    return httpJson(401, { error: error.message || 'Authentication required' });
  }

  const queryParams = parseQueryParams(
    request.url,
    paginationQuery.merge(searchQuery)
  );
  if (!queryParams.ok) return queryParams.error;

  const { page, limit, search } = queryParams.data;
  const pageNum = typeof page === 'number' ? page : (page ? parseInt(String(page), 10) : 1);
  const limitNum = typeof limit === 'number' ? limit : (limit ? parseInt(String(limit), 10) : 20);
  const skip = (pageNum - 1) * limitNum;

  // Build where clause
  const where: any = { role: 'admin' };
  if (search) {
    where.OR = [
      { name: { contains: search, mode: 'insensitive' } },
      { email: { contains: search, mode: 'insensitive' } },
      { adminRole: { contains: search, mode: 'insensitive' } },
    ];
  }

  const [users, total] = await Promise.all([
    prisma.user.findMany({
      where,
      select: {
        id: true,
        name: true,
        email: true,
        adminRole: true,
        isActive: true,
        lastLogin: true,
        twoFactorEnabled: true,
        createdAt: true,
      },
      orderBy: { createdAt: 'desc' },
      skip,
      take: limitNum,
    }),
    prisma.user.count({ where }),
  ]);

  return httpJson(200, {
    users,
    pagination: {
      page,
      limit,
      total,
      pages: Math.ceil(total / limitNum),
    },
  });
});

// POST /api/admin/users - Create new admin user
export const POST = withApiHandler(async (request: NextRequest) => {
  let user;
  try {
    user = await requireRole(request, 'admin');
  } catch (error: any) {
    return httpJson(401, { error: error.message || 'Authentication required' });
  }

  const parsed = await parseJson(request, adminUserCreate);
  if (!parsed.ok) {
    return parsed.error;
  }

  const { name, email, password, adminRole, isActive } = parsed.data;

  // Normalize email to lowercase and remove whitespace
  const normalizedEmail = email.trim().toLowerCase();

  // Check if user already exists (case-insensitive)
  const existingUser = await prisma.user.findFirst({
    where: { 
      email: {
        equals: normalizedEmail,
        mode: 'insensitive',
      }
    },
  });

  if (existingUser) {
    return httpJson(409, { error: 'User with this email already exists' });
  }

  // Hash password
  const hashedPassword = await bcrypt.hash(password, 10);

  // Build create data object
  const createData: any = {
    id: `user_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
    name,
    email: normalizedEmail,
    password: hashedPassword,
    role: 'admin',
    twoFactorEnabled: false,
  };
  
  if (adminRole !== undefined) createData.adminRole = adminRole;
  if (isActive !== undefined) createData.isActive = isActive;

  // Create admin user (catch unique-constraint race)
  let newUser;
  try {
    newUser = await prisma.user.create({
      data: createData,
      select: {
        id: true,
        name: true,
        email: true,
        adminRole: true,
        isActive: true,
        lastLogin: true,
        twoFactorEnabled: true,
        createdAt: true,
      },
    });
  } catch (e: any) {
    // Handle Prisma unique constraint (race condition)
    if (e instanceof Prisma.PrismaClientKnownRequestError && e.code === 'P2002') {
      return httpJson(409, { error: 'User with this email already exists' });
    }
    throw e;
  }

  // Send welcome email to the new admin
  try {
    const loginUrl = `${process.env.NEXT_PUBLIC_BASE_URL || 'https://speedy-van.co.uk'}/admin`;
    const welcomeEmailData = {
      adminEmail: normalizedEmail, // Use normalized email for consistency
      adminName: name,
      adminRole: adminRole || 'admin',
      loginUrl: loginUrl,
      createdBy: user.name || user.email || 'System Administrator',
      createdAt: newUser.createdAt.toLocaleDateString('en-GB', {
        weekday: 'long',
        year: 'numeric',
        month: 'long',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit'
      })
    };

    const emailResult = await unifiedEmailService.sendAdminWelcome(welcomeEmailData);
    
    if (emailResult.success) {
      console.log('✅ Admin welcome email sent successfully:', {
        to: normalizedEmail,
        messageId: emailResult.messageId,
        provider: emailResult.provider
      });
    } else {
      console.error('❌ Failed to send admin welcome email:', emailResult.error);
      // Don't fail the user creation if email fails
    }
  } catch (emailError) {
    console.error('❌ Error sending admin welcome email:', emailError);
    // Don't fail the user creation if email fails
  }

  return httpJson(201, newUser);
});

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';

// Force dynamic rendering (uses headers/cookies/getServerSession)
export const dynamic = 'force-dynamic';

/**
 * POST /api/admin/voice/transcribe
 * Transcribe audio to text using OpenAI Whisper API
 */
export async function POST(req: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user) {
      return NextResponse.json(
        { error: 'Unauthorized' },
        { status: 401 }
      );
    }

    if ((session.user as any).role !== 'admin' && (session.user as any).role !== 'superadmin') {
      return NextResponse.json(
        { error: 'Forbidden' },
        { status: 403 }
      );
    }

    const formData = await req.formData();
    const audioFile = formData.get('audio') as File;

    if (!audioFile) {
      return NextResponse.json(
        { error: 'No audio file provided' },
        { status: 400 }
      );
    }

    // Use Groq Whisper API (primary)
    const groqApiKey = process.env.GROQ_API_KEY_ADMIN || process.env.GROQ_API_KEY;
    
    if (!groqApiKey) {
      return NextResponse.json(
        { error: 'API key not configured' },
        { status: 500 }
      );
    }

    // Convert File to FormData for Groq Whisper
    const whisperFormData = new FormData();
    whisperFormData.append('file', audioFile);
    whisperFormData.append('model', 'whisper-large-v3-turbo'); // Groq's Whisper model
    whisperFormData.append('language', 'en'); // Auto-detect if not specified
    whisperFormData.append('response_format', 'json');

    // Try Groq Whisper first
    try {
      const groqResponse = await fetch('https://api.groq.com/openai/v1/audio/transcriptions', {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${groqApiKey}`,
        },
        body: whisperFormData,
      });

      if (groqResponse.ok) {
        const data = await groqResponse.json();
        return NextResponse.json({
          text: data.text,
          language: data.language || 'en',
          duration: data.duration,
        });
      }

      console.error('Groq transcription failed:', await groqResponse.text());
    } catch (groqError) {
      console.error('Groq transcription error:', groqError);
    }

    // Fallback to OpenAI if available
    const openaiApiKey = process.env.OPENAI_API_KEY;
    if (openaiApiKey) {
      try {
        const openaiFormData = new FormData();
        openaiFormData.append('file', audioFile);
        openaiFormData.append('model', 'whisper-1');

        const response = await fetch('https://api.openai.com/v1/audio/transcriptions', {
          method: 'POST',
          headers: {
            'Authorization': `Bearer ${openaiApiKey}`,
          },
          body: openaiFormData,
        });

        if (response.ok) {
          const data = await response.json();
          return NextResponse.json({
            text: data.text,
            language: data.language || 'en',
            duration: data.duration,
          });
        }
      } catch (openaiError) {
        console.error('OpenAI transcription failed:', openaiError);
      }
    }

    throw new Error('All transcription services failed');

  } catch (error) {
    console.error('Transcription error:', error);
    return NextResponse.json(
      { error: error instanceof Error ? error.message : 'Transcription failed' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
