    const date = searchParams.get('date');

    if (!date) {
      return NextResponse.json(
        { error: 'Date parameter is required' },
        { status: 400 }
      );
    }

    // This would check against your database for crew and van availability
    // For demo purposes, we'll return mock availability data

    const availabilityData = generateMockAvailabilityData(date);

    return NextResponse.json(availabilityData);
  } catch (error) {
    console.error('Error checking availability:', error);
    return NextResponse.json(
      { error: 'Failed to check availability' },
      { status: 500 }
    );
  }
}

function generateMockAvailabilityData(date: string): any {
  const moveDate = new Date(date);
  const today = new Date();
  const daysDifference = Math.floor(
    (moveDate.getTime() - today.getTime()) / (1000 * 60 * 60 * 24)
  );

  // Generate realistic availability based on day of week and time
  const dayOfWeek = moveDate.getDay(); // 0 = Sunday, 1 = Monday, etc.
  const isWeekend = dayOfWeek === 0 || dayOfWeek === 6;
  const isPeakDay = dayOfWeek >= 1 && dayOfWeek <= 5; // Monday to Friday

  // Base availability (higher on weekdays, lower on weekends)
  let baseAvailability = isPeakDay ? 0.9 : isWeekend ? 0.7 : 0.8;

  // Reduce availability for very short notice (same day or next day)
  if (daysDifference <= 1) {
    baseAvailability *= 0.6;
  } else if (daysDifference <= 3) {
    baseAvailability *= 0.8;
  }

  // Generate time slots with availability
  const timeSlots = [
    '07:00',
    '08:00',
    '09:00',
    '10:00',
    '11:00',
    '12:00',
    '13:00',
    '14:00',
    '15:00',
    '16:00',
    '17:00',
    '18:00',
    '19:00',
  ];

  const availableSlots: string[] = [];
  const unavailableReasons: Record<string, string> = {};

  timeSlots.forEach(time => {
    const hour = parseInt(time.split(':')[0]);

    // Peak hours (7-9 AM, 4-6 PM) have lower availability
    const isPeakHour = (hour >= 7 && hour <= 9) || (hour >= 16 && hour <= 18);
    let slotAvailability = baseAvailability;

    if (isPeakHour) {
      slotAvailability *= 0.8; // 20% reduction for peak hours
    }

    // Early morning and late evening have lower availability
    if (hour <= 7 || hour >= 19) {
      slotAvailability *= 0.7;
    }

    // Random variation
    const randomFactor = Math.random();

    if (randomFactor <= slotAvailability) {
      availableSlots.push(time);
    } else {
      // Generate realistic reasons for unavailability
      const reasons = [
        'Fully Booked',
        'Crew Unavailable',
        'Van Maintenance',
        'Driver Off Duty',
        'Route Congestion',
      ];

      const randomReason = reasons[Math.floor(Math.random() * reasons.length)];
      unavailableReasons[time] = randomReason;
    }
  });

  return {
    date: date,
    availableSlots: availableSlots,
    unavailableReasons: unavailableReasons,
    totalSlots: timeSlots.length,
    availableCount: availableSlots.length,
    availabilityPercentage: Math.round(
      (availableSlots.length / timeSlots.length) * 100
    ),
    recommendations: {
      bestTimes: availableSlots.slice(0, 3), // Top 3 available times
      alternativeDates: generateAlternativeDates(moveDate),
      peakHourWarning: isPeakDay,
    },
  };
}

function generateAlternativeDates(moveDate: Date): string[] {
  const alternatives: string[] = [];
  const today = new Date();

  // Suggest next 3 available dates
  for (let i = 1; i <= 7; i++) {
    const alternativeDate = new Date(moveDate);
    alternativeDate.setDate(alternativeDate.getDate() + i);

    if (alternativeDate > today) {
      alternatives.push(alternativeDate.toISOString().split('T')[0]);

      if (alternatives.length >= 3) {
        break;
      }
    }
  }

  return alternatives;
}

import { NextRequest, NextResponse } from 'next/server';
import { z } from 'zod';
import { prisma } from '@/lib/prisma';
import { DynamicAvailabilityEngine, type FullStructuredAddress, type BookingCapacity } from '@/lib/availability/dynamic-availability-engine';
import { logger } from '@/lib/logger';
import { v4 as uuidv4 } from 'uuid';
import { assertFullStructuredAddresses, sanitizeAddressForLog, LegacyAddressSchema, convertToFullStructuredAddress } from '@/lib/validation/address-validation';
import { createMetricsMiddleware } from '@/lib/observability/availability-metrics';



/**
 * Booking capacity schema
 */
const BookingCapacitySchema = z.object({
  totalWeightKg: z.number().min(0),
  totalVolumeM3: z.number().min(0),
  estimatedDurationMinutes: z.number().min(0),
  crewRequired: z.number().min(1).max(4)
});

/**
 * GET /api/availability/next
 * 
 * Query parameters (URL encoded JSON):
 * - pickup: FullStructuredAddress
 * - drops: FullStructuredAddress[]
 * - capacity: BookingCapacity
 * 
 * STRICT REQUIREMENT: All addresses must be full structured addresses
 * from autocomplete - NO postcode-only shortcuts allowed
 */
export async function GET(request: NextRequest) {
  const requestId = uuidv4();
  const startTime = Date.now();
  const recordMetrics = createMetricsMiddleware();
  
  try {
    const searchParams = request.nextUrl.searchParams;
    
    // Parse and validate pickup address
    const pickupParam = searchParams.get('pickup');
    if (!pickupParam) {
      return NextResponse.json(
        { 
          error: 'Missing pickup address', 
          code: 'MISSING_PICKUP',
          requestId 
        },
        { status: 400 }
      );
    }

    let pickup: FullStructuredAddress;
    try {
      const pickupData = JSON.parse(pickupParam);
      const validatedPickup = LegacyAddressSchema.parse(pickupData);
      pickup = convertToFullStructuredAddress(validatedPickup, 'pickup') as FullStructuredAddress;
    } catch (error) {
      logger.error('Invalid pickup address structure', error instanceof Error ? error : new Error('Parse error'), { requestId });
      return NextResponse.json(
        { 
          error: error instanceof Error ? error.message : 'Pickup address must include street, number, city, postcode, and coordinates', 
          code: 'INVALID_PICKUP_STRUCTURE',
          requestId 
        },
        { status: 400 }
      );
    }

    // Parse and validate drop addresses
    const dropsParam = searchParams.get('drops');
    if (!dropsParam) {
      return NextResponse.json(
        { 
          error: 'Missing drop addresses', 
          code: 'MISSING_DROPS',
          requestId 
        },
        { status: 400 }
      );
    }

    let drops: FullStructuredAddress[];
    try {
      const dropsData = JSON.parse(dropsParam);
      if (!Array.isArray(dropsData) || dropsData.length === 0) {
        throw new Error('Drops must be a non-empty array');
      }
      const validatedDrops = dropsData.map((drop, index) =>
        LegacyAddressSchema.parse(drop)
      );
      drops = validatedDrops.map((drop, index) =>
        convertToFullStructuredAddress(drop, `drop[${index}]`)
      ) as FullStructuredAddress[];
    } catch (error) {
      logger.error('Invalid drops address structure', error instanceof Error ? error : new Error('Parse error'), { requestId });
      return NextResponse.json(
        { 
          error: error instanceof Error ? error.message : 'All drop addresses must include street, number, city, postcode, and coordinates', 
          code: 'INVALID_DROPS_STRUCTURE',
          requestId 
        },
        { status: 400 }
      );
    }

    // Parse and validate capacity
    const capacityParam = searchParams.get('capacity');
    if (!capacityParam) {
      return NextResponse.json(
        { 
          error: 'Missing capacity information', 
          code: 'MISSING_CAPACITY',
          requestId 
        },
        { status: 400 }
      );
    }

    let capacity: BookingCapacity;
    try {
      const capacityData = JSON.parse(capacityParam);
      capacity = BookingCapacitySchema.parse(capacityData) as BookingCapacity;
    } catch (error) {
      logger.error('Invalid capacity structure', error instanceof Error ? error : new Error('Parse error'), { requestId });
      return NextResponse.json(
        { 
          error: 'Capacity must include totalWeightKg, totalVolumeM3, estimatedDurationMinutes, and crewRequired', 
          code: 'INVALID_CAPACITY_STRUCTURE',
          requestId 
        },
        { status: 400 }
      );
    }

    logger.info('Availability request received', {
      pickup: sanitizeAddressForLog(pickup),
      dropsCount: drops.length,
      capacity
    }, { requestId });

    // Initialize availability engine
    const availabilityEngine = new DynamicAvailabilityEngine(prisma);
    
    // Calculate availability
    const result = await availabilityEngine.calculateAvailability(
      pickup,
      drops,
      capacity,
      requestId
    );

    // Store pricing snapshot for analytics
    await prisma.pricingSnapshot.create({
      data: {
        requestId,
        pickupAddress: JSON.parse(JSON.stringify(pickup)),
        dropAddresses: JSON.parse(JSON.stringify(drops)),
        capacity: JSON.parse(JSON.stringify(capacity)),
        economyAvailable: result.route_type === 'economy',
        economyDate: result.route_type === 'economy' ? new Date(result.next_available_date) : null,
        standardPrice: 0, // Will be filled by pricing API
        expressPrice: 0,  // Will be filled by pricing API
        // corridor field removed - not in schema
      }
    });

    const response = {
      ...result,
      requestId,
      processingTimeMs: Date.now() - startTime
    };

    logger.info('Availability request completed', {
      result: response,
      processingTimeMs: Date.now() - startTime
    }, { requestId });

    // Record API metrics
    recordMetrics(
      '/api/availability/next',
      'GET',
      requestId,
      startTime,
      200,
      1 + drops.length, // pickup + drops
      capacity.totalWeightKg + capacity.totalVolumeM3 // rough items proxy
    );

    return NextResponse.json(response);

  } catch (error) {
    logger.error('Availability API error', error instanceof Error ? error : new Error('Unknown error'), { requestId });
    
    // Record error metrics
    recordMetrics(
      '/api/availability/next',
      'GET',
      requestId,
      startTime,
      500,
      0,
      0,
      error instanceof Error ? error : new Error('Unknown error')
    );
    
    return NextResponse.json(
      { 
        error: 'Internal server error calculating availability', 
        code: 'AVAILABILITY_CALCULATION_ERROR',
        requestId 
      },
      { status: 500 }
    );
  }
}

