        { error: 'Booking not found' },
        { status: 404 }
      );
    }

    // Check authorization
    if (session?.user?.role !== 'admin' && booking.customerId !== session?.user?.id) {
      return NextResponse.json(
        { error: 'Unauthorized' },
        { status: 403 }
      );
    }

    // Update booking status to cancelled instead of deleting
    const cancelledBooking = await prisma.booking.update({
      where: { id: bookingId },
      data: {
        status: 'CANCELLED',
        updatedAt: new Date(),
      },
    });

    return NextResponse.json({
      success: true,
      message: 'Booking cancelled successfully',
      booking: {
        id: cancelledBooking.id,
        reference: cancelledBooking.reference,
        status: cancelledBooking.status,
      },
    });
  } catch (error) {
    console.error('❌ Error cancelling booking:', error);
    return NextResponse.json(
      { error: 'Failed to cancel booking' },
      { status: 500 }
    );
  }
}

// PATCH /api/booking-luxury/[id] - Update booking (for payment confirmation)
export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { id: bookingId } = await params;
    const body = await request.json();

    console.log('📝 [BOOKING UPDATE] Request received:', {
      bookingId,
      updates: body
    });

    // Find the booking first
    const existingBooking = await prisma.booking.findUnique({
      where: { id: bookingId }
    });

    if (!existingBooking) {
      console.error('❌ Booking not found:', bookingId);
      return NextResponse.json(
        { error: 'Booking not found' },
        { status: 404 }
      );
    }

    // Only allow specific fields to be updated
    const allowedUpdates: any = {};
    
    if (body.stripePaymentIntentId) {
      allowedUpdates.stripePaymentIntentId = body.stripePaymentIntentId;
    }
    
    if (body.status === 'CONFIRMED') {
      allowedUpdates.status = 'CONFIRMED';
    }
    
    if (body.paidAt) {
      allowedUpdates.paidAt = new Date(body.paidAt);
    }

    // Update the booking
    const updatedBooking = await prisma.booking.update({
      where: { id: bookingId },
      data: allowedUpdates
    });

    console.log('✅ [BOOKING UPDATE] Booking updated successfully:', {
      bookingId,
      reference: updatedBooking.reference,
      status: updatedBooking.status,
      stripePaymentIntentId: updatedBooking.stripePaymentIntentId
    });

    return NextResponse.json({
      success: true,
      booking: updatedBooking
    });

  } catch (error) {
    console.error('❌ Error updating booking:', error);
    return NextResponse.json(
      { error: 'Failed to update booking' },
      { status: 500 }
    );
  }
}

