import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { authenticateBearerToken } from '@/lib/bearer-auth';
import { getPusherServer } from '@/lib/pusher';
import { prisma } from '@/lib/prisma';

export const dynamic = 'force-dynamic';

export async function POST(
  request: NextRequest,
  { params }: { params: { messageId: string } }
) {
  try {
    // Try Bearer token authentication first (for mobile app)
    const bearerAuth = await authenticateBearerToken(request);
    let userId: string;
    let userRole: string;

    if (bearerAuth.success) {
      userId = bearerAuth.user.id;
      userRole = bearerAuth.user.role;
    } else {
      // Fallback to NextAuth session (for web app)
      const session = await getServerSession(authOptions);
      if (!session?.user) {
        return NextResponse.json(
          { error: 'Unauthorized' },
          { status: 401 }
        );
      }
      userId = session.user.id;
      userRole = (session.user as any).role;
    }

    const { messageId } = params;

    // Find message and its chat session
    const message = await prisma.message.findUnique({
      where: { id: messageId },
      include: {
        ChatSession: {
          include: {
            ChatParticipant: true,
          },
        },
        User: {
          select: {
            id: true,
            role: true,
          },
        },
      },
    });

    if (!message) {
      return NextResponse.json(
        { error: 'Message not found' },
        { status: 404 }
      );
    }

    // Don't mark own messages as read
    if (message.senderId === userId) {
      return NextResponse.json({
        success: true,
        message: 'Own message',
      });
    }

    // Update message status to "read" if it's currently "delivered"
    // Note: In current schema, we don't have "read" status, but we can use metadata
    const updatedMessage = await prisma.message.update({
      where: { id: messageId },
      data: {
        metadata: {
          ...(message.metadata as any),
          readBy: userId,
          readAt: new Date().toISOString(),
        },
      },
    });

    // Send read receipt via Pusher to sender
    try {
      const pusher = getPusherServer();
      const senderRole = message.User.role;
      const senderChannelName =
        senderRole === 'driver'
          ? `driver-${message.senderId}`
          : 'admin-chat';

      await pusher.trigger(senderChannelName, 'message_read', {
        messageId,
        chatId: message.sessionId,
        readBy: userId,
        readByRole: userRole,
        readAt: new Date().toISOString(),
      });

      console.log(`✅ Read receipt sent for message ${messageId}`);
    } catch (pusherError) {
      console.error('❌ Pusher read receipt failed:', pusherError);
    }

    return NextResponse.json({
      success: true,
      message: 'Message marked as read',
    });
  } catch (error) {
    console.error('❌ Error marking message as read:', error);
    return NextResponse.json(
      { error: 'Failed to mark message as read' },
      { status: 500 }
    );
  }
}

/**
 * Chat Messages API
 * 
 * Handles sending and receiving messages in chat sessions
 * Supports text, images, files, and location messages
 */

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { authenticateBearerToken } from '@/lib/bearer-auth';
import { prisma } from '@/lib/prisma';
import { logger } from '@/lib/logger';
import Pusher from 'pusher';

// Initialize Pusher for real-time messaging
const pusher = new Pusher({
  appId: process.env.PUSHER_APP_ID!,
  key: process.env.PUSHER_KEY!,
  secret: process.env.PUSHER_SECRET!,
  cluster: process.env.PUSHER_CLUSTER!,
  useTLS: true,
});

export const dynamic = 'force-dynamic';

/**
 * GET /api/chat/messages?sessionId=xxx
 * Get messages for a chat session
 */
export async function GET(request: NextRequest) {
  try {
    // Try Bearer token authentication first (for mobile apps)
    const bearerAuth = await authenticateBearerToken(request);
    let userId: string;
    
    if (bearerAuth.success) {
      userId = bearerAuth.user.id;
    } else {
      // Fallback to NextAuth session (for web app)
      const session = await getServerSession(authOptions);
      if (!session?.user) {
        return NextResponse.json(
          { error: 'Unauthorized' },
          { status: 401 }
        );
      }
      userId = (session.user as any).id;
    }

    const { searchParams } = new URL(request.url);
    const sessionId = searchParams.get('sessionId');
    const limit = parseInt(searchParams.get('limit') || '50');
    const before = searchParams.get('before'); // Cursor for pagination

    if (!sessionId) {
      return NextResponse.json(
        { error: 'Session ID is required' },
        { status: 400 }
      );
    }

    // Verify user is participant in this session
    const participant = await prisma.chatParticipant.findFirst({
      where: {
        sessionId,
        userId,
      },
    });

    if (!participant) {
      return NextResponse.json(
        { error: 'Not authorized to access this session' },
        { status: 403 }
      );
    }

    // Build where clause for pagination
    const whereClause: any = {
      sessionId,
    };

    if (before) {
      whereClause.createdAt = {
        lt: new Date(before),
      };
    }

    // Get messages
    const messages = await prisma.message.findMany({
      where: whereClause,
      include: {
        User: {
          select: {
            id: true,
            name: true,
            email: true,
            role: true,
          },
        },
      },
      orderBy: {
        createdAt: 'desc',
      },
      take: limit,
    });

    // Update last read timestamp
    await prisma.chatParticipant.update({
      where: {
        id: participant.id,
      },
      data: {
        lastReadAt: new Date(),
      },
    });

    // Mark messages as read
    await prisma.message.updateMany({
      where: {
        sessionId,
        senderId: { not: userId },
        readAt: null,
      },
      data: {
        readAt: new Date(),
        status: 'read',
      },
    });

    logger.info('Chat messages retrieved', {
      userId,
      sessionId,
      messageCount: messages.length,
    });

    return NextResponse.json({
      success: true,
      data: messages.reverse(), // Return in chronological order
      hasMore: messages.length === limit,
      cursor: messages.length > 0 ? messages[messages.length - 1].createdAt.toISOString() : null,
    });

  } catch (error) {
    logger.error('Failed to get chat messages', error as Error);
    return NextResponse.json(
      {
        error: 'Failed to get chat messages',
        details: error instanceof Error ? error.message : 'Unknown error',
      },
      { status: 500 }
    );
  }
}

/**
 * POST /api/chat/messages
 * Send a new message
 */
export async function POST(request: NextRequest) {
  try {
    // Try Bearer token authentication first (for mobile apps)
    const bearerAuth = await authenticateBearerToken(request);
    let userId: string;
    let userName: string;
    
    if (bearerAuth.success) {
      userId = bearerAuth.user.id;
      userName = bearerAuth.user.name || 'Driver';
    } else {
      // Fallback to NextAuth session (for web app)
      const session = await getServerSession(authOptions);
      if (!session?.user) {
        return NextResponse.json(
          { error: 'Unauthorized' },
          { status: 401 }
        );
      }
      userId = (session.user as any).id;
      userName = session.user.name || 'User';
    }

    const body = await request.json();
    const { sessionId, content, type = 'text', metadata } = body;

    // Validate input
    if (!sessionId) {
      return NextResponse.json(
        { error: 'Session ID is required' },
        { status: 400 }
      );
    }

    if (!content || content.trim().length === 0) {
      return NextResponse.json(
        { error: 'Message content is required' },
        { status: 400 }
      );
    }

    if (!['text', 'image', 'file', 'location', 'system'].includes(type)) {
      return NextResponse.json(
        { error: 'Invalid message type' },
        { status: 400 }
      );
    }

    // Verify user is participant in this session
    const participant = await prisma.chatParticipant.findFirst({
      where: {
        sessionId,
        userId,
      },
    });

    if (!participant) {
      return NextResponse.json(
        { error: 'Not authorized to send messages in this session' },
        { status: 403 }
      );
    }

    // Create message
    const message = await prisma.message.create({
      data: {
        sessionId,
        senderId: userId,
        content: content.trim(),
        type: type as any,
        status: 'sent',
        metadata: metadata || {},
      },
      include: {
        User: {
          select: {
            id: true,
            name: true,
            email: true,
            role: true,
          },
        },
      },
    });

    // Update session timestamp
    await prisma.chatSession.update({
      where: { id: sessionId },
      data: { updatedAt: new Date() },
    });

    // Send real-time notification via Pusher
    try {
      await pusher.trigger(`chat-${sessionId}`, 'new-message', {
        message: {
          id: message.id,
          content: message.content,
          type: message.type,
          senderId: message.senderId,
          senderName: userName,
          createdAt: message.createdAt.toISOString(),
          metadata: message.metadata,
        },
      });

      // Get other participants for push notifications
      const otherParticipants = await prisma.chatParticipant.findMany({
        where: {
          sessionId,
          userId: { not: userId },
        },
        include: {
          User: {
            select: {
              id: true,
              name: true,
            },
          },
        },
      });

      // Send push notifications to other participants
      for (const participant of otherParticipants) {
        if (participant.userId) {
          // Create notification in database
          await prisma.driverNotification.create({
            data: {
              driverId: participant.userId,
              type: 'message_received',
              title: `New message from ${userName}`,
              message: content.substring(0, 100),
              read: false,
            },
          }).catch(() => {
            // Ignore if driver notification fails (user might not be a driver)
          });
        }
      }

      logger.info('Real-time notification sent', {
        sessionId,
        messageId: message.id,
      });
    } catch (pusherError) {
      logger.error('Failed to send real-time notification', pusherError as Error);
      // Continue even if Pusher fails
    }

    logger.info('Chat message sent', {
      userId,
      sessionId,
      messageId: message.id,
      type,
    });

    return NextResponse.json({
      success: true,
      data: message,
      message: 'Message sent successfully',
    });

  } catch (error) {
    logger.error('Failed to send chat message', error as Error);
    return NextResponse.json(
      {
        error: 'Failed to send chat message',
        details: error instanceof Error ? error.message : 'Unknown error',
      },
      { status: 500 }
    );
  }
}

/**
 * Chat Sessions API
 * 
 * Handles creation and retrieval of chat sessions between:
 * - Driver ↔ Admin
 * - Customer ↔ Driver
 * - Customer ↔ Admin
 */

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { authenticateBearerToken } from '@/lib/bearer-auth';
import { prisma } from '@/lib/prisma';
import { logger } from '@/lib/logger';

export const dynamic = 'force-dynamic';

/**
 * GET /api/chat/sessions
 * Get all chat sessions for the authenticated user
 */
export async function GET(request: NextRequest) {
  try {
    // Try Bearer token authentication first (for mobile apps)
    const bearerAuth = await authenticateBearerToken(request);
    let userId: string;
    let userRole: string;
    
    if (bearerAuth.success) {
      userId = bearerAuth.user.id;
      userRole = bearerAuth.user.role;
    } else {
      // Fallback to NextAuth session (for web app)
      const session = await getServerSession(authOptions);
      if (!session?.user) {
        return NextResponse.json(
          { error: 'Unauthorized' },
          { status: 401 }
        );
      }
      userId = (session.user as any).id;
      userRole = (session.user as any).role;
    }

    const { searchParams } = new URL(request.url);
    const bookingId = searchParams.get('bookingId');
    const isActive = searchParams.get('isActive');

    // Build where clause
    const whereClause: any = {
      ChatParticipant: {
        some: {
          userId: userId,
        },
      },
    };

    if (bookingId) {
      whereClause.bookingId = bookingId;
    }

    if (isActive !== null) {
      whereClause.isActive = isActive === 'true';
    }

    // Get chat sessions
    const sessions = await prisma.chatSession.findMany({
      where: whereClause,
      include: {
        ChatParticipant: {
          include: {
            User: {
              select: {
                id: true,
                name: true,
                email: true,
                role: true,
              },
            },
          },
        },
        Message: {
          orderBy: { createdAt: 'desc' },
          take: 1,
          select: {
            id: true,
            content: true,
            type: true,
            status: true,
            createdAt: true,
            senderId: true,
            readAt: true,
          },
        },
        Booking: {
          select: {
            id: true,
            reference: true,
            customerName: true,
          },
        },
      },
      orderBy: {
        updatedAt: 'desc',
      },
    });

    // Calculate unread count for each session
    const sessionsWithUnread = await Promise.all(
      sessions.map(async (session) => {
        const participant = session.ChatParticipant.find(p => p.userId === userId);
        const lastReadAt = participant?.lastReadAt;

        const unreadCount = await prisma.message.count({
          where: {
            sessionId: session.id,
            senderId: { not: userId },
            createdAt: lastReadAt ? { gt: lastReadAt } : undefined,
          },
        });

        return {
          ...session,
          unreadCount,
          lastMessage: session.Message[0] || null,
        };
      })
    );

    logger.info('Chat sessions retrieved', {
      userId,
      userRole,
      sessionCount: sessions.length,
    });

    return NextResponse.json({
      success: true,
      data: sessionsWithUnread,
    });

  } catch (error) {
    logger.error('Failed to get chat sessions', error as Error);
    return NextResponse.json(
      {
        error: 'Failed to get chat sessions',
        details: error instanceof Error ? error.message : 'Unknown error',
      },
      { status: 500 }
    );
  }
}

/**
 * POST /api/chat/sessions
 * Create a new chat session
 */
export async function POST(request: NextRequest) {
  try {
    // Try Bearer token authentication first (for mobile apps)
    const bearerAuth = await authenticateBearerToken(request);
    let userId: string;
    let userRole: string;
    
    if (bearerAuth.success) {
      userId = bearerAuth.user.id;
      userRole = bearerAuth.user.role;
    } else {
      // Fallback to NextAuth session (for web app)
      const session = await getServerSession(authOptions);
      if (!session?.user) {
        return NextResponse.json(
          { error: 'Unauthorized' },
          { status: 401 }
        );
      }
      userId = (session.user as any).id;
      userRole = (session.user as any).role;
    }

    const body = await request.json();
    const { type, title, bookingId, participantIds } = body;

    // Validate input
    if (!type || !['customer_driver', 'customer_admin', 'driver_admin', 'support'].includes(type)) {
      return NextResponse.json(
        { error: 'Invalid session type' },
        { status: 400 }
      );
    }

    if (!participantIds || !Array.isArray(participantIds) || participantIds.length === 0) {
      return NextResponse.json(
        { error: 'At least one participant is required' },
        { status: 400 }
      );
    }

    // Check if session already exists for this booking and participants
    if (bookingId) {
      const existingSession = await prisma.chatSession.findFirst({
        where: {
          bookingId,
          type,
          isActive: true,
          ChatParticipant: {
            every: {
              userId: { in: [...participantIds, userId] },
            },
          },
        },
        include: {
          ChatParticipant: true,
        },
      });

      if (existingSession) {
        logger.info('Returning existing chat session', {
          sessionId: existingSession.id,
          bookingId,
        });

        return NextResponse.json({
          success: true,
          data: existingSession,
          message: 'Session already exists',
        });
      }
    }

    // Create new chat session
    const chatSession = await prisma.chatSession.create({
      data: {
        type,
        title: title || `${type.replace('_', ' ')} chat`,
        bookingId,
        createdBy: userId,
        ChatParticipant: {
          create: [
            {
              userId: userId,
              role: userRole as any,
            },
            ...participantIds.map((participantId: string) => ({
              userId: participantId,
              role: 'admin' as any, // Default to admin, can be updated
            })),
          ],
        },
      },
      include: {
        ChatParticipant: {
          include: {
            User: {
              select: {
                id: true,
                name: true,
                email: true,
                role: true,
              },
            },
          },
        },
        Booking: {
          select: {
            id: true,
            reference: true,
            customerName: true,
          },
        },
      },
    });

    logger.info('Chat session created', {
      sessionId: chatSession.id,
      type,
      bookingId,
      createdBy: userId,
    });

    return NextResponse.json({
      success: true,
      data: chatSession,
      message: 'Chat session created successfully',
    });

  } catch (error) {
    logger.error('Failed to create chat session', error as Error);
    return NextResponse.json(
      {
        error: 'Failed to create chat session',
        details: error instanceof Error ? error.message : 'Unknown error',
      },
      { status: 500 }
    );
  }
}

import { NextResponse } from 'next/server';
import crypto from 'crypto';
import { serializeConsentCookie, parseConsentCookie, ConsentCookie } from '@/lib/consent';
import { prisma } from '@/lib/prisma';

type Body = {
  functional?: boolean;
  analytics?: boolean;
  marketing?: boolean;
  preferences?: boolean;
  region?: string | null;
};

function hmacSha256Hex(secret: string, value: string): string {
  return crypto.createHmac('sha256', secret).update(value).digest('hex');
}

export async function POST(req: Request) {
  try {
    const json = (await req.json()) as Body;
    const nowSeconds = Math.floor(Date.now() / 1000);
    const newConsent: ConsentCookie = {
      preferences: {
        necessary: true,
        functional: !!json.functional,
        analytics: !!json.analytics,
        marketing: !!json.marketing,
        preferences: !!json.preferences,
      },
      hasConsent: true,
      timestamp: nowSeconds * 1000,
    };
    const value = serializeConsentCookie(newConsent);
    const res = NextResponse.json({ ok: true, consent: newConsent });
    // Set cookie attributes
    res.cookies.set({
      name: 'sv_consent',
      value,
      path: '/',
      secure: true,
      httpOnly: true,
      sameSite: 'lax',
      maxAge: 60 * 60 * 24 * 180, // ~6 months
    });

    // Log change best-effort
    try {
      const secret = process.env.CONSENT_HMAC_SECRET || 'dev-secret';
      const ip =
        req.headers.get('x-forwarded-for') ||
        req.headers.get('x-real-ip') ||
        '';
      const userAgent = req.headers.get('user-agent') || '';
      const cookieHeader = req.headers.get('cookie');
      const existing = cookieHeader ? parseConsentCookie(
        cookieHeader
          .split(';')
          .find(c => c.trim().startsWith('sv_consent='))
          ?.split('=')[1] || undefined
      ) : null;
      const userId = req.headers.get('x-user-id') || null; // optional: set in app if session present
      await prisma.consentLog.create({
        data: {
          userId: userId || undefined,
          country: json.region || 'UK',
          ipHash: ip ? hmacSha256Hex(secret, ip) : null,
          uaHash: userAgent ? hmacSha256Hex(secret, userAgent) : null,
          value,
          prevValue: existing ? serializeConsentCookie(existing) : undefined,
        },
      });
    } catch (e) {
      console.error('consent_log_error', e);
    }

    return res;
  } catch (e) {
    return NextResponse.json(
      { ok: false, error: 'invalid_request' },
      { status: 400 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { getPusherServer } from '@/lib/pusher';
import { upsertAssignment } from '@/lib/utils/assignment-helpers';

/**
 * Cron Job: Expire Assignments
 * 
 * This endpoint should be called every 1 minute by:
 * - Render Cron Jobs (configured in Render Dashboard)
 * - External cron service (e.g., cron-job.org)
 * - GitHub Actions (scheduled workflow)
 * 
 * It checks for expired assignments and:
 * 1. Marks them as declined
 * 2. Decreases driver acceptance rate by 5%
 * 3. Auto-reassigns to next available driver
 * 4. Sends real-time notifications
 */
export const dynamic = 'force-dynamic';
export const maxDuration = 60; // 60 seconds max execution time

export async function GET(request: NextRequest) {
  const authHeader = request.headers.get('authorization');
  const cronSecret = process.env.CRON_SECRET || 'default-secret-change-in-production';

  // Verify cron secret to prevent unauthorized access
  if (authHeader !== `Bearer ${cronSecret}`) {
    console.error('❌ Unauthorized cron request');
    return NextResponse.json(
      { error: 'Unauthorized' },
      { status: 401 }
    );
  }

  try {
    const now = new Date();
    console.log(`⏰ [${now.toISOString()}] Running assignment expiry check...`);

    // Find all claimed AND invited assignments that have expired
    const expiredAssignments = await prisma.assignment.findMany({
      where: {
        status: { in: ['claimed', 'invited'] }, // Check both statuses
        expiresAt: {
          lt: now,
        },
      },
      include: {
        Booking: true,
        Driver: {
          include: {
            User: true,
            DriverPerformance: true,
          }
        }
      },
    });

    if (expiredAssignments.length === 0) {
      console.log('✅ No expired assignments found');
      return NextResponse.json({
        success: true,
        message: 'No expired assignments found',
        expiredCount: 0,
        timestamp: now.toISOString(),
      });
    }

    console.log(`🔴 Found ${expiredAssignments.length} expired assignment(s)`);

    const pusher = getPusherServer();

    // Process each expired assignment
    const results = await Promise.all(
      expiredAssignments.map(async (assignment) => {
        try {
          console.log(`⏰ Expiring assignment ${assignment.id} for driver ${assignment.driverId}`);
          
          let newAcceptanceRate = 100;
          
          await prisma.$transaction(async (tx) => {
            // Update assignment status to declined
            await tx.assignment.update({
              where: { id: assignment.id },
              data: { 
                status: 'declined',
                updatedAt: now,
              },
            });

            // Reset booking to make it available again
            await tx.booking.update({
              where: { id: assignment.bookingId },
              data: {
                driverId: null,
                status: 'CONFIRMED',
              },
            });

            // Apply acceptance rate penalty (same as manual decline)
            const performance = await tx.driverPerformance.findUnique({
              where: { driverId: assignment.driverId }
            });

            if (performance) {
              const currentRate = performance.acceptanceRate || 100;
              newAcceptanceRate = Math.max(0, currentRate - 5); // Decrease by 5%

              await tx.driverPerformance.update({
                where: { driverId: assignment.driverId },
                data: {
                  acceptanceRate: newAcceptanceRate,
                  lastCalculated: now
                }
              });

              console.log(`📉 Decreased acceptance rate for driver ${assignment.driverId} from ${currentRate}% to ${newAcceptanceRate}%`);
            }
          });

          // Send real-time notifications to driver
          try {
            await pusher.trigger(`driver-${assignment.driverId}`, 'job-removed', {
              jobId: assignment.bookingId,
              assignmentId: assignment.id,
              reason: 'expired',
              message: 'Assignment expired - You did not accept within 30 minutes',
              timestamp: now.toISOString()
            });

            await pusher.trigger(`driver-${assignment.driverId}`, 'acceptance-rate-updated', {
              acceptanceRate: newAcceptanceRate,
              change: -5,
              reason: 'assignment_expired',
              jobId: assignment.bookingId,
              timestamp: now.toISOString()
            });

            // Notify admin dashboard
            await pusher.trigger('admin-orders', 'order-status-changed', {
              jobId: assignment.bookingId,
              status: 'available',
              previousDriver: assignment.driverId,
              driverName: assignment.Driver?.User?.name,
              reason: 'expired',
              timestamp: now.toISOString()
            });
          } catch (pusherError) {
            console.error('⚠️ Failed to send Pusher notifications:', pusherError);
          }

          // Auto-reassign to next available driver
          try {
            const availableDrivers = await prisma.driver.findMany({
              where: {
                id: { not: assignment.driverId },
                status: 'active',
                onboardingStatus: 'approved',
                DriverAvailability: {
                  status: { in: ['online', 'available'] }
                }
              },
              include: {
                User: { select: { name: true, email: true } },
                DriverAvailability: true,
                DriverPerformance: true
              },
              orderBy: {
                DriverPerformance: {
                  acceptanceRate: 'desc'
                }
              },
              take: 5
            });

            if (availableDrivers.length > 0) {
              const nextDriver = availableDrivers[0];
              
              // Create or update assignment for next driver
              await upsertAssignment(prisma, assignment.bookingId, {
                driverId: nextDriver.id,
                status: 'invited',
                round: (assignment.round || 1) + 1,
                expiresAt: new Date(Date.now() + 30 * 60 * 1000), // 30 minutes
              });

              // Notify next driver
              await pusher.trigger(`driver-${nextDriver.id}`, 'route-matched', {
                type: 'single-order',
                matchType: 'order',
                jobCount: 1,
                bookingId: assignment.Booking?.id,
                bookingReference: assignment.Booking?.reference,
                assignmentId: assignment.id,
                message: 'New job offer (auto-reassigned)',
                expiresInSeconds: 1800,
                expiresAt: new Date(Date.now() + 30 * 60 * 1000).toISOString(),
                timestamp: now.toISOString()
              });

              console.log(`✅ Job auto-reassigned to driver: ${nextDriver.User?.name}`);
              
              return {
                assignmentId: assignment.id,
                expired: true,
                reassigned: true,
                reassignedTo: nextDriver.User?.name
              };
            } else {
              console.log('⚠️ No available drivers for auto-reassignment');
              return {
                assignmentId: assignment.id,
                expired: true,
                reassigned: false,
                reason: 'no_available_drivers'
              };
            }
          } catch (reassignError) {
            console.error('❌ Failed to auto-reassign job:', reassignError);
            return {
              assignmentId: assignment.id,
              expired: true,
              reassigned: false,
              error: reassignError instanceof Error ? reassignError.message : 'Unknown error'
            };
          }
        } catch (error) {
          console.error(`❌ Error processing assignment ${assignment.id}:`, error);
          return {
            assignmentId: assignment.id,
            expired: false,
            error: error instanceof Error ? error.message : 'Unknown error'
          };
        }
      })
    );

    const successCount = results.filter(r => r.expired).length;
    const reassignedCount = results.filter(r => r.reassigned).length;

    console.log(`✅ Expired ${successCount}/${expiredAssignments.length} assignments`);
    console.log(`✅ Reassigned ${reassignedCount}/${successCount} assignments`);

    return NextResponse.json({
      success: true,
      message: `Expired ${successCount} assignments, reassigned ${reassignedCount}`,
      expiredCount: successCount,
      reassignedCount,
      results,
      timestamp: now.toISOString(),
    });

  } catch (error) {
    console.error('❌ Error in expiry cron job:', error);
    return NextResponse.json(
      {
        success: false,
        error: 'Internal server error',
        details: error instanceof Error ? error.message : 'Unknown error',
      },
      { status: 500 }
    );
  }
}

