// GET /api/driver/applications - Get driver applications (admin only)
export const GET = withApiHandler(async (request: NextRequest) => {
  const user = await requireRole(request, 'admin');

  const queryParams = parseQueryParams(
    request.url,
    paginationQuery.merge(searchQuery)
  );
  if (!queryParams.ok) return queryParams.error;

  const { page, limit, status } = queryParams.data;
  const pageNum = typeof page === 'number' ? page : (page ? parseInt(String(page), 10) : 1);
  const limitNum = typeof limit === 'number' ? limit : (limit ? parseInt(String(limit), 10) : 20);
  const skip = (pageNum - 1) * limitNum;

  const where = status ? { status: status as any } : {};

  const [applications, total] = await Promise.all([
    prisma.driverApplication.findMany({
      where,
      skip,
      take: limitNum,
      orderBy: { applicationDate: 'desc' },
      include: {
        User: {
          select: {
            id: true,
            name: true,
            email: true,
            isActive: true,
          },
        },
      },
    }),
    prisma.driverApplication.count({ where }),
  ]);

  return httpJson(200, {
    applications,
    pagination: {
      page,
      limit,
      total,
      pages: Math.ceil(total / limitNum),
    },
  });
});

