              </div>
              <div class="footer">
                <p>Speedy Van Driver App</p>
                <p>If you need help, contact us at support@speedy-van.co.uk or call 01202 129746</p>
              </div>
            </div>
          </body>
          </html>
        `;

      // Send email using UnifiedEmailService (handles Resend/SendGrid fallback)
      const emailResult = await UnifiedEmailService.sendCustomEmail(
        newEmail.toLowerCase(),
        'Confirm Your Email Change - Speedy Van',
        htmlContent
      );

      if (!emailResult.success) {
        console.error('❌ Email send failed:', emailResult.error);
        console.error('❌ Email provider used:', emailResult.provider);
        console.error('❌ Detailed error for debugging:', emailResult);
        throw new Error(emailResult.error || 'Failed to send email - check SMTP configuration');
      }

      console.log('✅ Verification email sent to:', newEmail, 'via', emailResult.provider);
    } catch (emailError) {
      console.error('❌ Failed to send verification email:', emailError);
      
      // Delete the request if email fails
      await prisma.emailChangeRequest.delete({
        where: { id: emailChangeRequest.id },
      });
      
      return NextResponse.json(
        { error: 'Failed to send verification email' },
        { status: 500, headers: corsHeaders }
      );
    }

    return NextResponse.json(
      {
        success: true,
        message: 'Verification email sent. Please check your new email inbox.',
        newEmail: newEmail,
        expiresAt: expiresAt.toISOString(),
      },
      { headers: corsHeaders }
    );
  } catch (error) {
    console.error('❌ Email Change Request API error:', error);
    return NextResponse.json(
      { 
        success: false,
        error: 'Internal server error',
        details: error instanceof Error ? error.message : 'Unknown error'
      },
      { status: 500, headers: corsHeaders }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';

// CORS headers for mobile app compatibility
const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
  'Access-Control-Allow-Headers': 'Content-Type, Authorization',
};

// Handle OPTIONS preflight request
export async function OPTIONS() {
  return NextResponse.json({}, { headers: corsHeaders });
}

export async function POST(request: NextRequest) {
  try {
    const { token } = await request.json();

    if (!token || typeof token !== 'string') {
      return NextResponse.json(
        { error: 'Verification token is required' },
        { status: 400, headers: corsHeaders }
      );
    }

    console.log('🔍 Verifying email change token:', token);

    // Find the email change request
    const emailChangeRequest = await prisma.emailChangeRequest.findUnique({
      where: { token: token },
      include: {
        User: {
          select: { id: true, email: true, name: true },
        },
      },
    });

    if (!emailChangeRequest) {
      return NextResponse.json(
        { error: 'Invalid or expired verification link' },
        { status: 404, headers: corsHeaders }
      );
    }

    // Check if already verified
    if (emailChangeRequest.status === 'verified') {
      return NextResponse.json(
        { error: 'This email change has already been confirmed' },
        { status: 400, headers: corsHeaders }
      );
    }

    // Check if cancelled
    if (emailChangeRequest.status === 'cancelled') {
      return NextResponse.json(
        { error: 'This email change request was cancelled' },
        { status: 400, headers: corsHeaders }
      );
    }

    // Check if expired
    if (new Date() > emailChangeRequest.expiresAt) {
      await prisma.emailChangeRequest.update({
        where: { id: emailChangeRequest.id },
        data: { status: 'expired' },
      });

      return NextResponse.json(
        { error: 'Verification link has expired. Please request a new one.' },
        { status: 400, headers: corsHeaders }
      );
    }

    // Check if new email is now taken by another user (double-check at verification time)
    const existingUser = await prisma.user.findUnique({
      where: { email: emailChangeRequest.newEmail },
      include: {
        driver: {
          select: { id: true, status: true },
        },
      },
    });

    if (existingUser && existingUser.id !== emailChangeRequest.userId) {
      console.log('❌ Email now in use by another user during verification:', {
        email: emailChangeRequest.newEmail,
        existingUserId: existingUser.id,
        existingUserRole: existingUser.role,
        isDriver: !!existingUser.driver,
      });

      // Provide specific error message
      let errorMessage = 'This email address was registered by another user while you were verifying';
      
      if (existingUser.driver) {
        errorMessage = 'This email is now registered to another driver. Please request a new email change with a different address.';
      } else if (existingUser.role === 'customer') {
        errorMessage = 'This email is now registered as a customer account. Please request a new email change with a different address.';
      }

      // Mark request as failed
      await prisma.emailChangeRequest.update({
        where: { id: emailChangeRequest.id },
        data: { status: 'failed' },
      });

      return NextResponse.json(
        { 
          error: errorMessage,
          alreadyTaken: true,
          userType: existingUser.driver ? 'driver' : existingUser.role,
        },
        { status: 400, headers: corsHeaders }
      );
    }

    console.log('✅ Email still available at verification time');

    // Perform the email change
    await prisma.$transaction(async (tx) => {
      // Update user email
      await tx.user.update({
        where: { id: emailChangeRequest.userId },
        data: { email: emailChangeRequest.newEmail },
      });

      // Mark request as verified
      await tx.emailChangeRequest.update({
        where: { id: emailChangeRequest.id },
        data: {
          status: 'verified',
          verifiedAt: new Date(),
        },
      });

      console.log('✅ Email changed successfully:', {
        userId: emailChangeRequest.userId,
        oldEmail: emailChangeRequest.oldEmail,
        newEmail: emailChangeRequest.newEmail,
      });
    });

    // Send confirmation email to old address
    try {
      const { default: UnifiedEmailService } = await import('@/lib/email/UnifiedEmailService');
      
      const htmlContent = `
          <!DOCTYPE html>
          <html>
          <head>
            <style>
              body { font-family: Arial, sans-serif; line-height: 1.6; color: #333; }
              .container { max-width: 600px; margin: 0 auto; padding: 20px; }
              .header { background: #28a745; color: white; padding: 20px; text-align: center; border-radius: 8px 8px 0 0; }
              .content { background: #f9f9f9; padding: 30px; border-radius: 0 0 8px 8px; }
              .warning { background: #fff3cd; border-left: 4px solid #ffc107; padding: 12px; margin: 20px 0; }
              .footer { text-align: center; margin-top: 20px; color: #666; font-size: 12px; }
            </style>
          </head>
          <body>
            <div class="container">
              <div class="header">
                <h1>✅ Email Address Changed</h1>
              </div>
              <div class="content">
                <p>Hello <strong>${emailChangeRequest.User.name || 'Driver'}</strong>,</p>
                
                <p>Your email address has been successfully changed.</p>
                
                <p><strong>Old Email:</strong> ${emailChangeRequest.oldEmail}</p>
                <p><strong>New Email:</strong> ${emailChangeRequest.newEmail}</p>
                <p><strong>Changed At:</strong> ${new Date().toLocaleString('en-GB')}</p>
                
                <div class="warning">
                  <strong>⚠️ Security Notice:</strong> If you did not make this change, please contact support immediately at support@speedy-van.co.uk or call 01202 129746
                </div>
              </div>
              <div class="footer">
                <p>Speedy Van Driver App</p>
                <p>This is an automated security notification</p>
              </div>
            </div>
          </body>
          </html>
        `;

      // Send security notification using UnifiedEmailService
      const emailResult = await UnifiedEmailService.sendCustomEmail(
        emailChangeRequest.oldEmail,
        'Email Address Changed - Speedy Van',
        htmlContent
      );

      if (emailResult.success) {
        console.log('✅ Confirmation email sent to old address via', emailResult.provider);
      } else {
        console.error('⚠️ Failed to send security notification:', emailResult.error);
      }
    } catch (emailError) {
      console.error('⚠️ Failed to send confirmation email to old address:', emailError);
      // Don't fail the request if this email fails
    }

    return NextResponse.json(
      {
        success: true,
        message: 'Email address changed successfully',
        newEmail: emailChangeRequest.newEmail,
      },
      { headers: corsHeaders }
    );
  } catch (error) {
    console.error('❌ Email Verify API error:', error);
    return NextResponse.json(
      { 
        success: false,
        error: 'Internal server error',
        details: error instanceof Error ? error.message : 'Unknown error'
      },
      { status: 500, headers: corsHeaders }
    );
  }
}

import { NextResponse, NextRequest } from 'next/server';
import { requireRole } from '@/lib/api/guard';
import { prisma } from '@/lib/prisma';

export const dynamic = 'force-dynamic';

export async function GET(request: NextRequest) {
    const user = await requireRole(request, 'driver');

  const userId = user.id;

  try {
    const driver = await prisma.driver.findUnique({
      where: { userId },
    });

    if (!driver) {
      return NextResponse.json({ error: 'Driver not found' }, { status: 404 });
    }

    // Get all incidents for the driver
    const incidents = await prisma.driverIncident.findMany({
      where: {
        driverId: driver.id,
      },
      include: {
        Assignment: {
          include: {
            Booking: {
              select: {
                reference: true,
                pickupAddress: true,
                dropoffAddress: true,
                scheduledAt: true,
              },
            },
          },
        },
      },
      orderBy: { createdAt: 'desc' },
    });

    return NextResponse.json({
      incidents: incidents.map(incident => ({
        id: incident.id,
        type: incident.type,
        severity: incident.severity,
        title: incident.title,
        description: incident.description,
        location: incident.location,
        photoUrls: incident.photoUrls,
        status: incident.status,
        reportedAt: incident.reportedAt,
        reviewedAt: incident.reviewedAt,
        reviewNotes: incident.reviewNotes,
        resolution: incident.resolution,
        customerImpact: incident.customerImpact,
        propertyDamage: incident.propertyDamage,
        injuryInvolved: incident.injuryInvolved,
        job: incident.Assignment
          ? {
              reference: incident.Assignment.Booking.reference,
              pickupAddress: incident.Assignment.Booking.pickupAddress,
              dropoffAddress: incident.Assignment.Booking.dropoffAddress,
              date: incident.Assignment.Booking.scheduledAt,
            }
          : null,
      })),
    });
  } catch (error) {
    console.error('Incidents GET API error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

export async function POST(request: NextRequest) {
    const user = await requireRole(request, 'driver');

  const userId = user.id;

  try {
    const body = await request.json();
    const {
      type,
      severity,
      title,
      description,
      location,
      lat,
      lng,
      photoUrls,
      assignmentId,
      customerImpact,
      propertyDamage,
      injuryInvolved,
    } = body;

    // Validate required fields
    if (!type || !severity || !title || !description) {
      return NextResponse.json(
        {
          error: 'Missing required fields: type, severity, title, description',
        },
        { status: 400 }
      );
    }

    const driver = await prisma.driver.findUnique({
      where: { userId },
    });

    if (!driver) {
      return NextResponse.json({ error: 'Driver not found' }, { status: 404 });
    }

    // Validate assignmentId if provided
    if (assignmentId) {
      const assignment = await prisma.assignment.findFirst({
        where: {
          id: assignmentId,
          driverId: driver.id,
        },
      });

      if (!assignment) {
        return NextResponse.json(
          { error: 'Invalid assignment ID' },
          { status: 400 }
        );
      }
    }

    // Create incident
    const incident = await prisma.driverIncident.create({
      data: {
        driverId: driver.id,
        assignmentId: assignmentId || null,
        type,
        severity,
        title,
        description,
        location: location || null,
        lat: lat || null,
        lng: lng || null,
        photoUrls: photoUrls || [],
        customerImpact: customerImpact || false,
        propertyDamage: propertyDamage || false,
        injuryInvolved: injuryInvolved || false,
      },
      include: {
        Assignment: {
          include: {
            Booking: {
              select: {
                reference: true,
                pickupAddress: true,
                dropoffAddress: true,
              },
            },
          },
        },
      },
    });

    // Log audit event
    await prisma.auditLog.create({
      data: {
        actorId: driver.id,
        actorRole: 'driver',
        action: 'incident_reported',
        targetType: 'DriverIncident',
        targetId: incident.id,
        after: {
          type,
          severity,
          title,
          assignmentId,
        },
      },
    });

    return NextResponse.json(
      {
        incident: {
          id: incident.id,
          type: incident.type,
          severity: incident.severity,
          title: incident.title,
          status: incident.status,
          reportedAt: incident.reportedAt,
          job: incident.Assignment
            ? {
                reference: incident.Assignment.Booking.reference,
                pickupAddress: incident.Assignment.Booking.pickupAddress,
                dropoffAddress: incident.Assignment.Booking.dropoffAddress,
              }
            : null,
        },
      },
      { status: 201 }
    );
  } catch (error) {
    console.error('Incidents POST API error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
import { authenticateBearerToken } from '@/lib/bearer-auth';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

// CORS headers for mobile app compatibility
const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
  'Access-Control-Allow-Headers': 'Content-Type, Authorization',
};

// Handle OPTIONS preflight request
export async function OPTIONS() {
  return NextResponse.json({}, { headers: corsHeaders });
}

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    // ✅ Await params first (Next.js 15 requirement)
    const { id } = await params;
    console.log('🚗 Driver Job Accept API - Starting request for job:', id);
    
    // Try Bearer token authentication first (for mobile app)
    const bearerAuth = await authenticateBearerToken(request);
    let userId: string;
    
    if (bearerAuth.success) {
      userId = bearerAuth.user.id;
      console.log('🔑 Bearer token authenticated for user:', userId);
    } else {
      // Fallback to NextAuth session (for web app)
      const session = await getServerSession(authOptions);
      if (!session?.user) {
        console.log('❌ Driver Job Accept API - No session found');
        return NextResponse.json(
          { error: 'Unauthorized - Please login' },
          { status: 401 }
        );
      }
      userId = session.user.id;
      console.log('🌐 NextAuth session authenticated for user:', userId);
    }

    // Get user role from bearer auth or session
    const session = bearerAuth.success ? null : await getServerSession(authOptions);
    const userRole = bearerAuth.success ? bearerAuth.user.role : (session?.user as any)?.role;
    if (userRole !== 'driver') {
      console.log('❌ Driver Job Accept API - Invalid role:', userRole);
      return NextResponse.json(
        { error: 'Forbidden - Driver access required' },
        { status: 403 }
      );
    }

    console.log('🚗 Driver Job Accept API - Processing for user:', userId);

    // Get driver record
    const driver = await prisma.driver.findUnique({
      where: { userId },
      select: { id: true, status: true, onboardingStatus: true }
    });

    if (!driver) {
      console.log('❌ Driver Job Accept API - Driver profile not found');
      return NextResponse.json(
        { error: 'Driver profile not found' },
        { status: 404 }
      );
    }

    if (driver.status !== 'active' || driver.onboardingStatus !== 'approved') {
      console.log('❌ Driver Job Accept API - Driver not active or approved');
      return NextResponse.json(
        { error: 'Driver account not active or not approved' },
        { status: 403 }
      );
    }

    const { id: bookingId } = await params;

    // Check if the booking exists and is available
    const booking = await prisma.booking.findUnique({
      where: { id: bookingId },
      include: {
        Assignment: true
      }
    });

    if (!booking) {
      console.log('❌ Driver Job Accept API - Booking not found:', bookingId);
      return NextResponse.json(
        { error: 'Booking not found' },
        { status: 404 }
      );
    }

    if (booking.status !== 'CONFIRMED') {
      console.log('❌ Driver Job Accept API - Booking not confirmed:', booking.status);
      return NextResponse.json(
        { error: 'Booking is not available for acceptance' },
        { status: 400 }
      );
    }

    // Check if there's an invitation for this driver
    const invitation = await prisma.assignment.findFirst({
      where: {
        bookingId: bookingId,
        driverId: driver.id,
        status: 'invited'
      }
    });

    // Check if already assigned to another driver
    const existingAssignment = await prisma.assignment.findFirst({
      where: {
        bookingId: bookingId,
        driverId: { not: driver.id }, // Another driver
        status: { in: ['accepted', 'invited'] }
      }
    });

    if (existingAssignment && !invitation) {
      console.log('❌ Driver Job Accept API - Booking already assigned to another driver');
      return NextResponse.json(
        { error: 'This job has already been assigned to another driver' },
        { status: 400 }
      );
    }

    console.log('✅ Driver Job Accept API - Processing acceptance');

    // Get driver name for notifications
    const driverUser = await prisma.user.findUnique({
      where: { id: userId },
      select: { name: true, email: true }
    });

    // ✅ CHECK: Does driver have any active jobs for today?
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const tomorrow = new Date(today);
    tomorrow.setDate(tomorrow.getDate() + 1);

    const activeJobs = await prisma.assignment.findMany({
      where: {
        driverId: driver.id,
        status: 'accepted',
        Booking: {
          scheduledAt: {
            gte: new Date() // Future or current jobs
          },
          status: { in: ['CONFIRMED'] }
        }
      },
      include: {
        Booking: {
          select: { scheduledAt: true, status: true }
        }
      },
      orderBy: {
        Booking: {
          scheduledAt: 'asc' // Sort by scheduled time
        }
      }
    });

    console.log(`📊 Driver has ${activeJobs.length} active/scheduled job(s)`);

    // Create or update assignment and update booking
    await prisma.$transaction(async (tx) => {
      if (invitation) {
        // Update existing invitation to accepted
        await tx.assignment.update({
          where: { id: invitation.id },
          data: {
            status: 'accepted',
            claimedAt: new Date(),
            updatedAt: new Date()
          }
        });
      } else {
        // Find existing assignment or create new one
        const existingAssignment = await tx.assignment.findFirst({
          where: { bookingId: bookingId }
        });
        
        if (existingAssignment) {
          await tx.assignment.update({
            where: { id: existingAssignment.id },
            data: {
              driverId: driver.id,
              status: 'accepted',
              claimedAt: new Date(),
              updatedAt: new Date()
            }
          });
        } else {
          await tx.assignment.create({
            data: {
              id: `assign_${bookingId}_${driver.id}_${Date.now()}`,
              driverId: driver.id,
              bookingId: bookingId,
              status: 'accepted',
              claimedAt: new Date(),
              updatedAt: new Date()
            }
          });
        }
      }

      // Update the booking to assign it to the driver
      await tx.booking.update({
        where: { id: bookingId },
        data: {
          driverId: driver.id,
          status: 'CONFIRMED'
        }
      });
    });

    console.log('✅ Driver Job Accept API - Successfully accepted job:', bookingId);

    // Send real-time notifications
    try {
      const { getPusherServer } = await import('@/lib/pusher');
      const pusher = getPusherServer();

      const timestamp = new Date().toISOString();

      console.log('📡 Sending admin notifications for job acceptance...');

      // Get booking details for richer notifications
      const fullBooking = await prisma.booking.findUnique({
        where: { id: bookingId },
        include: {
          pickupAddress: true,
          dropoffAddress: true,
        }
      });

      // 1. Notify admin-notifications channel for immediate alert (GREEN NOTIFICATION)
      await pusher.trigger('admin-notifications', 'driver-accepted-job', {
        type: 'job_accepted',
        severity: 'success',
        jobId: bookingId,
        bookingReference: booking.reference,
        driverId: driver.id,
        driverName: driverUser?.name || 'Unknown Driver',
        driverEmail: driverUser?.email,
        estimatedEarnings: fullBooking?.totalGBP ? `£${(fullBooking.totalGBP / 100).toFixed(2)}` : 'N/A',
        pickupAddress: fullBooking?.pickupAddress?.label || 'Unknown',
        dropoffAddress: fullBooking?.dropoffAddress?.label || 'Unknown',
        message: `${driverUser?.name || 'Driver'} accepted job ${booking.reference}`,
        acceptedAt: timestamp,
        timestamp
      });

      // 2. Notify admin-orders channel - order accepted
      await pusher.trigger('admin-orders', 'order-accepted', {
        jobId: bookingId,
        bookingReference: booking.reference,
        driverId: driver.id,
        driverName: driverUser?.name || 'Unknown Driver',
        estimatedEarnings: fullBooking?.totalGBP ? `£${(fullBooking.totalGBP / 100).toFixed(2)}` : 'N/A',
        acceptedAt: timestamp,
        timestamp
      });

      // 3. Notify admin-routes channel (in case job is part of route planning)
      await pusher.trigger('admin-routes', 'job-accepted', {
        jobId: bookingId,
        bookingReference: booking.reference,
        driverId: driver.id,
        driverName: driverUser?.name || 'Unknown Driver',
        timestamp
      });

      // 4. Notify admin drivers panel
      await pusher.trigger('admin-drivers', 'driver-accepted-job', {
        driverId: driver.id,
        driverName: driverUser?.name || 'Unknown Driver',
        jobId: bookingId,
        bookingReference: booking.reference,
        timestamp
      });

      // 5. Notify driver's other devices (sync across devices)
      await pusher.trigger(`driver-${driver.id}`, 'job-accepted-confirmed', {
        jobId: bookingId,
        bookingReference: booking.reference,
        status: 'accepted',
        timestamp
      });

      // 6. Notify customer tracking page
      await pusher.trigger(`booking-${booking.reference}`, 'driver-accepted', {
        driverName: driverUser?.name || 'Unknown Driver',
        acceptedAt: timestamp,
        message: 'Your driver has accepted the job and will contact you soon'
      });

      console.log('✅ Real-time notifications sent for job acceptance');
    } catch (pusherError) {
      console.error('⚠️ Failed to send Pusher notifications:', pusherError);
      console.error('⚠️ Error details:', pusherError instanceof Error ? pusherError.message : 'Unknown');
      // Don't fail the request if Pusher fails
    }

    // ✅ Prepare response message based on job queue
    const isFirstJob = activeJobs.length === 0;
    const queuePosition = activeJobs.length + 1;
    const responseMessage = isFirstJob
      ? `Job accepted! You can start this job now.`
      : `Job accepted and added to your schedule (Position ${queuePosition}). Complete your current job(s) first.`;

    return NextResponse.json({
      success: true,
      message: responseMessage,
      bookingId,
      driverId: driver.id,
      queueInfo: {
        position: queuePosition,
        isQueued: !isFirstJob,
        activeJobs: activeJobs.length,
        canStartNow: isFirstJob
      }
    });

  } catch (error) {
    console.error('❌ Driver Job Accept API - Error:', error);
    return NextResponse.json(
      { 
        error: 'Internal server error',
        details: error instanceof Error ? error.message : 'Unknown error'
      },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { authenticateBearerToken } from '@/lib/bearer-auth';
import { prisma } from '@/lib/prisma';

export const dynamic = 'force-dynamic';

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    // Try Bearer token authentication first (for mobile app)
    const bearerAuth = await authenticateBearerToken(request);
    let userId: string;

    if (bearerAuth.success) {
      userId = bearerAuth.user.id;
      console.log('🔑 Bearer token authenticated for user:', userId);
    } else {
      // Fallback to session auth (for web)
      const session = await getServerSession(authOptions);
      if (!session?.user) {
        return NextResponse.json(
          { error: 'Unauthorized - Login required' },
          { status: 401 }
        );
      }
      userId = (session.user as any).id;
    }

    const { id: jobId } = await params;
    // Get driver data
    const driver = await prisma.driver.findUnique({
      where: { userId },
      include: {
        Document: true,
      },
    });

    if (!driver) {
      return NextResponse.json({ error: 'Driver not found' }, { status: 404 });
    }

    // Check if driver is approved
    if (driver.onboardingStatus !== 'approved') {
      return NextResponse.json(
        {
          error: 'Driver not approved',
          reason: 'onboarding_incomplete',
        },
        { status: 403 }
      );
    }

    // Check for expired documents
    const now = new Date();
    const expiredDocs = driver.Document?.filter(
      doc => doc.expiresAt && doc.expiresAt < now
    ) || [];

    if (expiredDocs.length > 0) {
      return NextResponse.json(
        {
          error: 'Documents expired',
          reason: 'expired_documents',
          expiredDocs: expiredDocs.map(doc => doc.category),
        },
        { status: 403 }
      );
    }

    // Skip checks that don't exist in schema for now
    // TODO: Add proper validation when fields are available

    // Use a transaction to handle race conditions
    const result = await prisma.$transaction(async tx => {
      // Check if job exists and is available
      const job = await tx.booking.findUnique({
        where: { id: jobId },
        include: {
          Assignment: true,
        },
      });

      if (!job) {
        throw new Error('Job not found');
      }

      if (job.status !== 'CONFIRMED') {
        throw new Error('Job is not available for claiming');
      }

      if (job.driverId) {
        throw new Error('Job already has a driver assigned');
      }

      if (job.Assignment) {
        throw new Error('Job already has an assignment');
      }

      // Check if driver already has an active job
      const activeAssignment = await tx.assignment.findFirst({
        where: {
          driverId: driver.id,
          status: {
            in: ['accepted'],
          },
        },
      });

      if (activeAssignment) {
        throw new Error('Driver already has an active job');
      }

      // Find existing assignment or create new one
      const existingAssignment = await tx.assignment.findFirst({
        where: { bookingId: jobId }
      });
      
      let assignment;
      if (existingAssignment) {
        assignment = await tx.assignment.update({
          where: { id: existingAssignment.id },
          data: {
            driverId: driver.id,
            status: 'claimed',
            expiresAt: new Date(Date.now() + 5 * 60 * 1000), // 5 minutes to accept
            score: job.totalGBP, // Store the job amount as score
            updatedAt: new Date(),
          }
        });
      } else {
        assignment = await tx.assignment.create({
          data: {
            id: `assignment_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
            bookingId: jobId,
            driverId: driver.id,
            status: 'claimed',
            expiresAt: new Date(Date.now() + 5 * 60 * 1000), // 5 minutes to accept
            score: job.totalGBP, // Store the job amount as score
            updatedAt: new Date(),
          }
        });
      }

      // Update booking to assign driver
      await tx.booking.update({
        where: { id: jobId },
        data: {
          driverId: driver.id,
          status: 'CONFIRMED',
        },
      });

      return assignment;
    });

    return NextResponse.json({
      success: true,
      assignment: {
        id: result.id,
        status: result.status,
        expiresAt: result.expiresAt,
        jobId: jobId,
      },
      message:
        'Job claimed successfully. You have 5 minutes to accept or decline.',
    });
  } catch (error: any) {
    console.error('Job claim API error:', error);

    if (error.message === 'Job not found') {
      return NextResponse.json({ error: 'Job not found' }, { status: 404 });
    }

    if (error.message === 'Job is not available for claiming') {
      return NextResponse.json(
        { error: 'Job is not available for claiming' },
        { status: 409 }
      );
    }

    if (error.message === 'Job already has a driver assigned') {
      return NextResponse.json(
        { error: 'Job already claimed by another driver' },
        { status: 409 }
      );
    }

    if (error.message === 'Job already has an assignment') {
      return NextResponse.json(
        { error: 'Job already claimed by another driver' },
        { status: 409 }
      );
    }

    if (error.message === 'Driver already has an active job') {
      return NextResponse.json(
        { error: 'You already have an active job' },
        { status: 409 }
      );
    }

    if (error.message === 'Driver must be online to claim jobs') {
      return NextResponse.json(
        { error: 'You must be online to claim jobs' },
        { status: 403 }
      );
    }

    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

/**
 * UK-Compliant Job Completion API
 * 
 * Handles both single orders and multiple drops routes
 * Fully compliant with UK regulations
 * Daily cap enforcement: £500
 */

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { logger } from '@/lib/logger';
import { driverEarningsService } from '@/lib/services/driver-earnings-service';

export const dynamic = 'force-dynamic';

interface CompleteJobRequest {
  assignmentId: string;
  completionNotes?: string;
  customerSignature?: string;
  proofOfDelivery?: string[];
  actualDistance?: number;
  actualDuration?: number;
  tollCosts?: number;
  parkingCosts?: number;
  fuelUsed?: number;
  customerRating?: number;
}

/**
 * POST /api/driver/jobs/[id]/complete-uk
 * Complete a job with UK-compliant earnings calculation
 */
export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { id: assignmentId } = await params;
    const body: CompleteJobRequest = await request.json();

    // 1. Get assignment details
    const assignment = await prisma.assignment.findUnique({
      where: { id: assignmentId },
      include: {
        Booking: {
          include: {
            Drop: true,
          },
        },
        Driver: true,
      },
    });

    if (!assignment) {
      return NextResponse.json(
        { error: 'Assignment not found' },
        { status: 404 }
      );
    }

    if (assignment.status === 'completed') {
      return NextResponse.json(
        { error: 'Assignment already completed' },
        { status: 400 }
      );
    }

    // 2. Determine if single order or multiple drops
    const isMultiDrop = assignment.Booking?.Drop?.length > 1;
    const dropCount = assignment.Booking?.Drop?.length || 1;

    // 3. Calculate distance and duration
    const distanceMiles = body.actualDistance || assignment.Booking?.baseDistanceMiles || 0;
    const durationMinutes = body.actualDuration || assignment.Booking?.estimatedDurationMinutes || 60;

    // 4. Break down time components
    const timeBreakdown = calculateTimeBreakdown(durationMinutes, dropCount);

    // 5. Prepare pricing input
    const pricingInput = {
      assignmentId: assignment.id,
      driverId: assignment.Driver ? assignment.Driver.id : assignment.driverId,
      bookingId: assignment.bookingId,
      distanceMiles,
      durationMinutes,
      dropCount,
      loadingMinutes: timeBreakdown.loading,
      unloadingMinutes: timeBreakdown.unloading,
      drivingMinutes: timeBreakdown.driving,
      waitingMinutes: timeBreakdown.waiting,
      customerPaymentPence: assignment.Booking?.totalGBP || 0,
      urgencyLevel: (assignment.Booking?.urgency as any) || 'standard',
      onTimeDelivery: isOnTime(assignment),
      customerRating: body.customerRating,
      tollCostsPence: body.tollCosts ? Math.round(body.tollCosts * 100) : 0,
      parkingCostsPence: body.parkingCosts ? Math.round(body.parkingCosts * 100) : 0,
      hasHelper: false,
      serviceType: (assignment.Booking?.Drop?.[0]?.serviceTier === 'priority' || assignment.Booking?.Drop?.[0]?.serviceTier === 'economy' || assignment.Booking?.Drop?.[0]?.serviceTier === 'standard')
        ? assignment.Booking.Drop[0].serviceTier
        : 'standard',
    };

    // 6. Calculate UK-compliant earnings
    const earningsResult = await driverEarningsService.calculateEarnings(pricingInput);

    if (!earningsResult.success) {
      return NextResponse.json({ error: 'Failed to calculate earnings' }, { status: 400 });
    }

    const { breakdown, warnings } = earningsResult;

    // 7. Update assignment status
    await prisma.assignment.update({
      where: { id: assignmentId },
      data: {
        status: 'completed',
      },
    });

    // 8. Save earnings using service
    const earningsRecordId = await driverEarningsService.saveEarnings(pricingInput, earningsResult);

    // 9. Update booking status if all assignments completed
    const allAssignments = await prisma.assignment.findMany({
      where: { bookingId: assignment.bookingId },
    });

    const allCompleted = allAssignments.every((a) => a.status === 'completed');

    if (allCompleted) {
      await prisma.booking.update({
        where: { id: assignment.bookingId },
        data: {
          status: 'COMPLETED',
        },
      });
    }

    // 10. Send notifications (if warnings exist)
    const complianceStatus = warnings.length > 0 ? 'warnings' : 'compliant';
    if (warnings.length > 0) {
      logger.warn('Job completed with compliance warnings', {
        assignmentId,
        warnings,
        complianceStatus,
      });
    }

    // 11. Return response
    return NextResponse.json({
      success: true,
      message: 'Job completed successfully',
      earnings: {
        gross: breakdown.grossEarnings / 100,
        net: breakdown.netEarnings / 100,
        currency: 'GBP',
        breakdown: undefined,
        compliance: null,
        driverTier: 'standard',
      },
      warnings,
      earningsRecordId,
    });

  } catch (error) {
    logger.error('Failed to complete job', error as Error);
    return NextResponse.json(
      {
        error: 'Failed to complete job',
        details: error instanceof Error ? error.message : 'Unknown error',
      },
      { status: 500 }
    );
  }
}

/**
 * Calculate time breakdown for different activities
 */
function calculateTimeBreakdown(totalMinutes: number, dropCount: number) {
  // Estimate time allocation
  const loadingPerDrop = 15; // 15 minutes per pickup
  const unloadingPerDrop = 15; // 15 minutes per delivery
  const waitingPerDrop = 5; // 5 minutes waiting per stop
  
  const loading = loadingPerDrop;
  const unloading = unloadingPerDrop * dropCount;
  const waiting = waitingPerDrop * dropCount;
  const driving = Math.max(0, totalMinutes - loading - unloading - waiting);

  return {
    loading,
    unloading,
    waiting,
    driving,
  };
}

/**
 * Check if delivery was on time
 */
function isOnTime(assignment: any): boolean {
  if (!assignment.completedAt || !assignment.booking.scheduledFor) {
    return true; // Assume on time if no schedule
  }

  const scheduled = new Date(assignment.booking.scheduledFor);
  const completed = new Date(assignment.completedAt);
  const delayMinutes = (completed.getTime() - scheduled.getTime()) / (1000 * 60);

  // Allow 15 minutes grace period
  return delayMinutes <= 15;
}

