        crewSize: booking.crewSize || 'TWO',
        // Road warnings
        warnings: []
      },
      
      // Additional info
      metadata: {
        createdAt: booking.createdAt,
        updatedAt: booking.updatedAt,
        baseDistance: booking.baseDistanceMiles,
        isAssignedToYou: isAssignedToDriver,
        isAvailable: isAvailableJob
      },
      
      // Smart suggestions for driver
      smartSuggestions: smartSuggestions,
      
      // Additional driver notes
      notes: {
        customerNotes: (booking as any).notes || null,
        cameraNote: (booking as any).cameraNote || null, // Camera/video notes if available
        specialInstructions: (booking as any).specialRequirements || null
      },
      
      // Comprehensive road warnings
      roadWarnings: {
        warnings: [
          ...((['EC1', 'EC2', 'EC3', 'EC4', 'WC1', 'WC2', 'SE1', 'E1'].some(prefix => 
            pickupAddr?.postcode?.toUpperCase().startsWith(prefix) || 
            dropoffAddr?.postcode?.toUpperCase().startsWith(prefix)
          )) ? ['⚠️ ULEZ Zone - Ultra Low Emission Zone charges may apply'] : []),
          
          ...((['N1', 'E1', 'E2', 'E3', 'E8', 'E9', 'E14', 'SE1', 'SE5', 'SE8', 'SE10', 'SE11', 'SE15', 'SE16', 'SE17'].some(prefix => 
            pickupAddr?.postcode?.toUpperCase().startsWith(prefix) || 
            dropoffAddr?.postcode?.toUpperCase().startsWith(prefix)
          )) ? ['⚠️ LEZ Zone - Low Emission Zone charges may apply for older vehicles'] : []),
          
          ...((['EC1', 'EC2', 'EC3', 'EC4', 'WC1', 'WC2'].some(prefix => 
            pickupAddr?.postcode?.toUpperCase().startsWith(prefix) || 
            dropoffAddr?.postcode?.toUpperCase().startsWith(prefix)
          )) ? ['⚠️ Congestion Charge Zone - £15 daily charge (Mon-Fri 7am-6pm, excluding bank holidays)'] : [])
        ],
        hasWarnings: (
          (['EC1', 'EC2', 'EC3', 'EC4', 'WC1', 'WC2', 'SE1', 'E1'].some(prefix => 
            pickupAddr?.postcode?.toUpperCase().startsWith(prefix) || 
            dropoffAddr?.postcode?.toUpperCase().startsWith(prefix)
          )) ||
          (['N1', 'E1', 'E2', 'E3', 'E8', 'E9', 'E14', 'SE1'].some(prefix => 
            pickupAddr?.postcode?.toUpperCase().startsWith(prefix) || 
            dropoffAddr?.postcode?.toUpperCase().startsWith(prefix)
          )) ||
          (['EC1', 'EC2', 'EC3', 'EC4', 'WC1', 'WC2'].some(prefix => 
            pickupAddr?.postcode?.toUpperCase().startsWith(prefix) || 
            dropoffAddr?.postcode?.toUpperCase().startsWith(prefix)
          ))
        )
      }
    };

    console.log(`✅ Job details loaded for driver ${driver.id}:`, {
      bookingId,
      reference: booking.reference,
      isAssigned: isAssignedToDriver,
      estimatedEarnings: earningsResult.breakdown.netEarnings
    });

    return NextResponse.json({
      success: true,
      data: jobDetails
    });

  } catch (error) {
    console.error('❌ Error loading job details:', error);
    return NextResponse.json(
      {
        error: 'Failed to load job details',
        details: error instanceof Error ? error.message : 'Unknown error'
      },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { auth } from '@/lib/auth';
import { assertDriver } from '@/lib/guards';
import { prisma } from '@/lib/prisma';

export const dynamic = 'force-dynamic';

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const session = await auth();
  try {
    assertDriver(session!);
  } catch (e) {
    const msg = (e as Error).message;
    const status = msg === 'UNAUTHORIZED' ? 401 : 403;
    return new Response(msg, { status });
  }

  const userId = session.user.id;
  const { id: assignmentId } = await params;

  try {
    // Get driver
    const driver = await prisma.driver.findUnique({
      where: { userId },
    });

    if (!driver) {
      return NextResponse.json({ error: 'Driver not found' }, { status: 404 });
    }

    // Verify assignment belongs to driver and is active
    const assignment = await prisma.assignment.findFirst({
      where: {
        id: assignmentId,
        driverId: driver.id,
        status: 'accepted',
      },
    });

    if (!assignment) {
      return NextResponse.json(
        { error: 'Assignment not found or not active' },
        { status: 404 }
      );
    }

    const body = await request.json();
    const { mediaUrls, step, notes } = body;

    if (!mediaUrls || !Array.isArray(mediaUrls) || mediaUrls.length === 0) {
      return NextResponse.json(
        { error: 'Media URLs are required' },
        { status: 400 }
      );
    }

    if (!step) {
      return NextResponse.json({ error: 'Step is required' }, { status: 400 });
    }

    // Validate step
    const validSteps = [
      'navigate_to_pickup',
      'arrived_at_pickup',
      'loading_started',
      'loading_completed',
      'en_route_to_dropoff',
      'arrived_at_dropoff',
      'unloading_started',
      'unloading_completed',
      'job_completed',
      'customer_signature',
      'damage_notes',
      'item_count_verification',
    ];

    if (!validSteps.includes(step)) {
      return NextResponse.json({ error: 'Invalid step' }, { status: 400 });
    }

    // Create job event with media
    const jobEvent = await prisma.jobEvent.create({
      data: {
        id: `event_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
        assignmentId,
        step,
        mediaUrls,
        notes: notes || null,
        createdBy: driver.id,
      },
    });

    // If job is completed, update assignment status
    if (step === 'job_completed') {
      await prisma.assignment.update({
        where: { id: assignmentId },
        data: { status: 'completed' },
      });
    }

    return NextResponse.json({
      success: true,
      event: {
        id: jobEvent.id,
        step: jobEvent.step,
        mediaUrls: jobEvent.mediaUrls,
        notes: jobEvent.notes,
        createdAt: jobEvent.createdAt,
      },
    });
  } catch (error) {
    console.error('Job media API error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
import { authenticateBearerToken } from '@/lib/bearer-auth';
import Pusher from 'pusher';

// Initialize Pusher
const pusher = new Pusher({
  appId: process.env.PUSHER_APP_ID!,
  key: process.env.PUSHER_KEY!,
  secret: process.env.PUSHER_SECRET!,
  cluster: process.env.PUSHER_CLUSTER!,
  useTLS: true,
});

export const dynamic = 'force-dynamic';

export async function PUT(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    // Authenticate - support both bearer token and session
    const bearerAuth = await authenticateBearerToken(request);
    let userId: string;
    
    if (bearerAuth.success) {
      userId = bearerAuth.user.id;
      console.log('✅ Authenticated via bearer token for user:', userId);
    } else {
      console.log('❌ Bearer auth failed, trying session auth');
      const session = await getServerSession(authOptions);
      if (!session?.user || (session.user as any).role !== 'driver') {
        console.log('❌ Session auth failed or not driver role');
        return NextResponse.json(
          { error: 'Unauthorized' },
          { status: 401 }
        );
      }
      userId = (session.user as any).id;
      console.log('✅ Authenticated via session for user:', userId);
    }

    const { id: assignmentId } = await params;

    // Get driver
    const driver = await prisma.driver.findUnique({
      where: { userId },
    });

    if (!driver) {
      return NextResponse.json({ error: 'Driver not found' }, { status: 404 });
    }

    // Verify assignment belongs to driver and is active
    const assignment = await prisma.assignment.findFirst({
      where: {
        id: assignmentId,
        driverId: driver.id,
        status: 'accepted',
      },
    });

    if (!assignment) {
      return NextResponse.json(
        { error: 'Assignment not found or not active' },
        { status: 404 }
      );
    }

    const body = await request.json();
    const { step, payload, mediaUrls, notes } = body;

    // Validate step
    const validSteps = [
      'navigate_to_pickup',
      'arrived_at_pickup',
      'loading_started',
      'loading_completed',
      'en_route_to_dropoff',
      'arrived_at_dropoff',
      'unloading_started',
      'unloading_completed',
      'job_completed',
      'customer_signature',
      'damage_notes',
      'item_count_verification',
    ];

    if (!validSteps.includes(step)) {
      return NextResponse.json({ error: 'Invalid step' }, { status: 400 });
    }

    // Get the latest event to check sequence
    const latestEvent = await prisma.jobEvent.findFirst({
      where: {
        assignmentId,
      },
      orderBy: {
        createdAt: 'desc'
      },
    });
    
    // Define step sequence
    const stepSequence = [
      'navigate_to_pickup',
      'arrived_at_pickup',
      'loading_started',
      'loading_completed',
      'en_route_to_dropoff',
      'arrived_at_dropoff',
      'unloading_started',
      'unloading_completed',
      'job_completed'
    ];

    // Check if step is already completed
    const existingEvent = await prisma.jobEvent.findFirst({
      where: {
        assignmentId,
        step,
      },
    });

    if (existingEvent) {
      return NextResponse.json(
        { error: 'Step already completed' },
        { status: 400 }
      );
    }

    // Check step sequence
    if (latestEvent) {
      const currentIndex = stepSequence.indexOf(latestEvent.step);
      const nextIndex = stepSequence.indexOf(step);

      // Verify this is the next step in sequence
      if (nextIndex !== currentIndex + 1) {
        return NextResponse.json(
          { 
            error: 'Invalid step sequence',
            details: `Expected step ${stepSequence[currentIndex + 1]}, got ${step}`
          },
          { status: 400 }
        );
      }
    } else {
      // If no events yet, only allow first step
      if (step !== stepSequence[0]) {
        return NextResponse.json(
          { 
            error: 'Invalid initial step',
            details: `First step must be ${stepSequence[0]}, got ${step}`
          },
          { status: 400 }
        );
      }
    }

    // Create job event
    const jobEvent = await prisma.jobEvent.create({
      data: {
        id: `event_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
        assignmentId,
        step,
        payload: payload || null,
        mediaUrls: mediaUrls || [],
        notes: notes || null,
        createdBy: driver.id,
      },
    });

    // Get booking details for notifications
    const booking = await prisma.booking.findUnique({
      where: { id: assignment.bookingId },
      select: { 
        id: true, 
        reference: true, 
        customerName: true,
        customerPhone: true 
      }
    });

    // Send real-time notifications to customer
    if (booking) {
      try {
        // Notify customer about progress update
        await pusher.trigger(`tracking-${booking.reference}`, 'progress-update', {
          step: step,
          stepLabel: getStepLabel(step),
          timestamp: new Date().toISOString(),
          driverId: driver.id,
          bookingId: booking.id,
          bookingReference: booking.reference,
          progress: getProgressPercentage(step),
          message: getStepMessage(step),
        });

        // Notify customer about job status change
        await pusher.trigger(`booking-${booking.reference}`, 'job-status-update', {
          step: step,
          stepLabel: getStepLabel(step),
          timestamp: new Date().toISOString(),
          driverId: driver.id,
          bookingId: booking.id,
          bookingReference: booking.reference,
          status: getStatusFromStep(step),
          message: getStepMessage(step),
        });

        // Notify admin dashboard
        await pusher.trigger('admin-tracking', 'progress-update', {
          step: step,
          stepLabel: getStepLabel(step),
          timestamp: new Date().toISOString(),
          driverId: driver.id,
          bookingId: booking.id,
          bookingReference: booking.reference,
          customerName: booking.customerName,
          progress: getProgressPercentage(step),
        });

        console.log('✅ Real-time progress notifications sent:', {
          step,
          bookingReference: booking.reference,
          driverId: driver.id
        });
      } catch (notificationError) {
        console.error('❌ Error sending progress notifications:', notificationError);
        // Don't fail the request if notifications fail
      }
    }

    // If job is completed, update assignment status and booking status
    if (step === 'job_completed') {
      await prisma.assignment.update({
        where: { id: assignmentId },
        data: { status: 'completed' },
      });

      // Update booking status to COMPLETED
      const booking = await prisma.booking.findUnique({
        where: { id: assignment.bookingId },
        select: { id: true, reference: true, customerName: true }
      });

      if (booking) {
        await prisma.booking.update({
          where: { id: booking.id },
          data: { 
            status: 'COMPLETED',
            updatedAt: new Date()
          }
        });

        console.log('✅ Booking marked as COMPLETED via progress API:', {
          bookingId: booking.id,
          bookingReference: booking.reference,
          driverId: driver.id
        });

        // Send admin notification about order completion
        try {
          const { getPusherServer } = await import('@/lib/pusher');
          const pusher = getPusherServer();

          // Get driver details for notification
          const driverDetails = await prisma.driver.findUnique({
            where: { id: driver.id },
            include: { User: { select: { name: true } } }
          });

          // Notify admin dashboard about order completion
          await pusher.trigger('admin-notifications', 'order-completed', {
            bookingId: booking.id,
            bookingReference: booking.reference,
            customerName: booking.customerName,
            driverName: driverDetails?.User?.name || 'Unknown Driver',
            completedAt: new Date().toISOString(),
            message: `Order ${booking.reference} has been completed by driver ${driverDetails?.User?.name || 'Unknown'}`,
          });

          console.log('✅ Admin notification sent for order completion via progress API:', {
            bookingId: booking.id,
            bookingReference: booking.reference,
            driverName: driverDetails?.User?.name
          });
        } catch (notificationError) {
          console.error('❌ Error sending admin notification for order completion via progress API:', notificationError);
          // Don't fail the request if notification fails
        }
      }
    }

    return NextResponse.json({
      success: true,
      event: {
        id: jobEvent.id,
        step: jobEvent.step,
        payload: jobEvent.payload,
        mediaUrls: jobEvent.mediaUrls,
        notes: jobEvent.notes,
        createdAt: jobEvent.createdAt,
      },
    });
  } catch (error) {
    console.error('Job progress API error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

// Helper functions for progress tracking
function getStepLabel(step: string): string {
  const stepLabels: Record<string, string> = {
    navigate_to_pickup: 'En Route to Pickup',
    arrived_at_pickup: 'Arrived at Pickup',
    loading_started: 'Loading Started',
    loading_completed: 'Loading Completed',
    en_route_to_dropoff: 'En Route to Delivery',
    arrived_at_dropoff: 'Arrived at Delivery',
    unloading_started: 'Unloading Started',
    unloading_completed: 'Unloading Completed',
    job_completed: 'Job Completed',
    customer_signature: 'Customer Signature',
    damage_notes: 'Damage Notes',
    item_count_verification: 'Item Count Verification',
  };

  return stepLabels[step] || step.replace(/_/g, ' ').replace(/\b\w/g, l => l.toUpperCase());
}

function getProgressPercentage(step: string): number {
  const stepProgress: Record<string, number> = {
    navigate_to_pickup: 20,
    arrived_at_pickup: 30,
    loading_started: 40,
    loading_completed: 50,
    en_route_to_dropoff: 70,
    arrived_at_dropoff: 80,
    unloading_started: 90,
    unloading_completed: 95,
    job_completed: 100,
  };

  return stepProgress[step] || 0;
}

function getStatusFromStep(step: string): string {
  const statusMap: Record<string, string> = {
    navigate_to_pickup: 'in_progress',
    arrived_at_pickup: 'in_progress',
    loading_started: 'in_progress',
    loading_completed: 'in_progress',
    en_route_to_dropoff: 'in_progress',
    arrived_at_dropoff: 'in_progress',
    unloading_started: 'in_progress',
    unloading_completed: 'in_progress',
    job_completed: 'completed',
  };

  return statusMap[step] || 'in_progress';
}

function getStepMessage(step: string): string {
  const messages: Record<string, string> = {
    navigate_to_pickup: 'Your driver is on the way to pickup location',
    arrived_at_pickup: 'Your driver has arrived at pickup location',
    loading_started: 'Loading has started',
    loading_completed: 'Loading completed, heading to delivery location',
    en_route_to_dropoff: 'Your driver is on the way to delivery location',
    arrived_at_dropoff: 'Your driver has arrived at delivery location',
    unloading_started: 'Unloading has started',
    unloading_completed: 'Unloading completed',
    job_completed: 'Your delivery has been completed successfully',
  };

  return messages[step] || 'Progress update received';
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
import { generateCrewRecommendation } from '@/lib/driver-notifications';
import { authenticateBearerToken } from '@/lib/bearer-auth';
// Fast mobile calculation - removed slow PerformanceTrackingService import
import { penceToPounds } from '@/lib/utils/currency';

// Helper function to derive timeSlot from scheduledAt
function getTimeSlotFromDate(scheduledAt: Date): string {
  const hour = scheduledAt.getHours();
  if (hour < 12) return '09:00-12:00'; // AM slot
  if (hour < 17) return '12:00-17:00'; // PM slot
  return '17:00-21:00'; // Evening slot
}

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    // Try Bearer token authentication first (for mobile app)
    const bearerAuth = await authenticateBearerToken(request);
    let userId: string;

    if (bearerAuth.success) {
      userId = bearerAuth.user.id;
      console.log('🔑 Bearer token authenticated for user:', userId);
    } else {
      // Fallback to session auth (for web)
      const session = await getServerSession(authOptions);
      if (!session?.user) {
        return NextResponse.json(
          { error: 'Unauthorized - Login required' },
          { status: 401 }
        );
      }
      userId = (session.user as any).id;
    }

    const { id: bookingId } = await params;

    // ✅ Get driver record FIRST (needed for earnings calculation)
    const driver = await prisma.driver.findUnique({
      where: { userId },
      select: { id: true }
    });

    if (!driver) {
      return NextResponse.json(
        { error: 'Driver profile not found' },
        { status: 404 }
      );
    }

    // Get the complete booking data
    const booking = await prisma.booking.findUnique({
      where: { id: bookingId },
      include: {
        pickupAddress: true,
        dropoffAddress: true,
        pickupProperty: true,
        dropoffProperty: true,
        BookingItem: true,
        Assignment: {
          include: {
            Driver: {
              include: {
                User: {
                  select: {
                    id: true,
                    name: true,
                    email: true,
                    role: true,
                    createdAt: true,
                    isActive: true
                  }
                },
              },
            },
          },
        },
      },
    });

    if (!booking) {
      return NextResponse.json({ error: 'Job not found' }, { status: 404 });
    }

    // Check if the driver is assigned to this job (Assignment is an array)
    const isAssigned = booking.Assignment?.[0]?.Driver?.User?.id === userId;

    if (!isAssigned) {
      return NextResponse.json(
        { error: 'Access denied - You are not assigned to this job' },
        { status: 403 }
      );
    }

    // Generate crew recommendation (with timeout protection)
    let crewRecommendation = {
      recommendedDrivers: [],
      reasoning: 'Crew recommendation system placeholder',
      jobId: booking.id,
      requirements: null,
    };
    
    try {
      const crewPromise = generateCrewRecommendation(booking.id, booking);
      const crewTimeout = new Promise((_, reject) => {
        setTimeout(() => reject(new Error('Crew recommendation timeout')), 1000);
      });
      crewRecommendation = await Promise.race([crewPromise, crewTimeout]);
    } catch (crewError) {
      console.warn('⚠️ Crew recommendation failed or timed out, using placeholder:', crewError instanceof Error ? crewError.message : String(crewError));
      // Continue with placeholder - don't fail the request
    }

    const pickupAddress = booking.pickupAddress;
    const dropoffAddress = booking.dropoffAddress;
    const pickupProperty = booking.pickupProperty;
    const dropoffProperty = booking.dropoffProperty;

    // Calculate distance for pricing (using proper haversine formula)
    const lat1 = pickupAddress?.lat || 0;
    const lon1 = pickupAddress?.lng || 0;
    const lat2 = dropoffAddress?.lat || 0;
    const lon2 = dropoffAddress?.lng || 0;
    
    const R = 3959; // Radius of Earth in miles
    const dLat = (lat2 - lat1) * Math.PI / 180;
    const dLon = (lon2 - lon1) * Math.PI / 180;
    const a = Math.sin(dLat/2) * Math.sin(dLat/2) +
      Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) *
      Math.sin(dLon/2) * Math.sin(dLon/2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
    const distance = R * c;

    // ✅ Calculate actual earnings using driverEarningsService
    const { driverEarningsService } = await import('@/lib/services/driver-earnings-service');
    const earningsResult = await driverEarningsService.calculateEarnings({
      driverId: driver.id,
      bookingId: booking.id,
      assignmentId: booking.Assignment?.[0]?.id || `temp_${booking.id}`,
      customerPaymentPence: booking.totalGBP,
      distanceMiles: distance,
      durationMinutes: booking.estimatedDurationMinutes || 60,
      dropCount: 1,
      hasHelper: false,
      urgencyLevel: 'standard',
      onTimeDelivery: true,
    });
    const estimatedEarnings = earningsResult.breakdown.netEarnings / 100; // Convert to GBP
    
    console.log('📊 Job retrieved for driver:', {
      bookingId: booking.id,
      reference: booking.reference,
      distance: distance.toFixed(2),
      estimatedEarnings: estimatedEarnings.toFixed(2),
      note: 'Actual earnings calculated on completion',
    });

    // Format the response for the driver (excluding customer email)
    const jobDetails = {
      id: booking.id,
      reference: booking.reference,
      unifiedBookingId: booking.reference, // Using reference as unified ID
      customer: {
        name: booking.customerName,
        phone: booking.customerPhone,
        // Email is intentionally excluded for driver privacy
      },
      addresses: {
        pickup: {
          line1: pickupAddress?.label,
          postcode: pickupAddress?.postcode,
          coordinates: {
            lat: pickupAddress?.lat,
            lng: pickupAddress?.lng,
          },
        },
        dropoff: {
          line1: dropoffAddress?.label,
          postcode: dropoffAddress?.postcode,
          coordinates: {
            lat: dropoffAddress?.lat,
            lng: dropoffAddress?.lng,
          },
        },
      },
      properties: {
        pickup: {
          type: pickupProperty?.propertyType,
          floors: pickupProperty?.floors,
          hasElevator: pickupProperty?.accessType === 'WITH_LIFT',
          hasParking: true, // Default value
          accessType: pickupProperty?.accessType,
          buildingTypeDisplay: pickupProperty?.propertyType?.toLowerCase().replace('_', ' ') || 'house'
        },
        dropoff: {
          type: dropoffProperty?.propertyType,
          floors: dropoffProperty?.floors,
          hasElevator: dropoffProperty?.accessType === 'WITH_LIFT',
          hasParking: true, // Default value
          accessType: dropoffProperty?.accessType,
          buildingTypeDisplay: dropoffProperty?.propertyType?.toLowerCase().replace('_', ' ') || 'house'
        },
      },
      schedule: {
        date: booking.scheduledAt,
        timeSlot: booking.pickupTimeSlot || getTimeSlotFromDate(booking.scheduledAt),
        urgency: booking.urgency || 'scheduled',
        estimatedDuration: booking.estimatedDurationMinutes,
      },
      items: booking.BookingItem.map(item => ({
        name: item.name,
        quantity: item.quantity,
        volumeM3: item.volumeM3,
      })),
      // ✅ Include driver earnings calculated above
      driverPayout: earningsResult.breakdown.netEarnings, // Driver net pay in pence
      pricing: {
        driverPayout: penceToPounds(earningsResult.breakdown.netEarnings),
        driverPayoutPence: earningsResult.breakdown.netEarnings,
        estimatedEarnings: penceToPounds(earningsResult.breakdown.netEarnings),
        currency: 'GBP',
        isEstimate: false, // Using fast calculation
        calculationNote: 'Fast mobile calculation optimized for driver app performance'
      },
      // Pricing information is not exposed to drivers for privacy reasons
      // Drivers only see their earnings, not customer payment amounts
      crewRecommendation: typeof crewRecommendation === 'string' 
        ? crewRecommendation 
        : 'Van with 2 crew',
      specialRequirements: '',
      status: booking.status,
      assignment: booking.Assignment && booking.Assignment[0]
        ? {
            id: booking.Assignment[0].id,
            status: booking.Assignment[0].status,
            claimedAt: booking.Assignment[0].claimedAt,
            driver: {
              id: booking.Assignment[0].Driver?.id,
              name: booking.Assignment[0].Driver?.User?.name || 'Unknown',
            },
          }
        : null,
    };

    return NextResponse.json({
      success: true,
      job: jobDetails,
    });
  } catch (error) {
    console.error('❌ Error fetching driver job details:', error);
    return NextResponse.json(
      { error: 'Failed to fetch job details' },
      { status: 500 }
    );
  }
}

export async function PUT(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    // Try Bearer token authentication first (for mobile app)
    const bearerAuth = await authenticateBearerToken(request);
    let userId: string;

    if (bearerAuth.success) {
      userId = bearerAuth.user.id;
      console.log('🔑 Bearer token authenticated for user:', userId);
    } else {
      // Fallback to session auth (for web)
      const session = await getServerSession(authOptions);
      if (!session?.user) {
        return NextResponse.json(
          { error: 'Unauthorized - Login required' },
          { status: 401 }
        );
      }
      userId = (session.user as any).id;
    }

    const { id: bookingId } = await params;
    const { action } = await request.json();

    // Get the booking and assignment
    const booking = await prisma.booking.findUnique({
      where: { id: bookingId },
      include: {
        Assignment: {
          include: {
            Driver: {
              include: {
                User: {
                  select: {
                    id: true,
                    name: true,
                    email: true,
                    role: true,
                    createdAt: true,
                    isActive: true
                  }
                },
              },
            },
          },
        },
      },
    });

    if (!booking) {
      return NextResponse.json({ error: 'Job not found' }, { status: 404 });
    }

    // Check if the driver is assigned to this job (Assignment is an array)
    const isAssigned = booking.Assignment?.[0]?.Driver?.User?.id === userId;
    if (!isAssigned) {
      return NextResponse.json(
        { error: 'Access denied - You are not assigned to this job' },
        { status: 403 }
      );
    }

    let updateData: any = {};

    switch (action) {
      case 'accept':
        updateData = {
          status: 'claimed',
          claimedAt: new Date(),
        };
        break;

      case 'start':
        updateData = {
          status: 'in_progress',
          startedAt: new Date(),
        };
        break;

      case 'complete':
        updateData = {
          status: 'completed',
          completedAt: new Date(),
        };
        break;

      default:
        return NextResponse.json({ error: 'Invalid action' }, { status: 400 });
    }

    // Update the assignment (Assignment is an array)
    const updatedAssignment = await prisma.assignment.update({
      where: { id: booking.Assignment![0].id },
      data: updateData,
    });

    // Create a job event log
    await prisma.jobEvent.create({
      data: {
        id: `je_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
        assignmentId: booking.Assignment![0].id,
        step:
          action === 'accept'
            ? 'navigate_to_pickup'
            : action === 'start'
              ? 'loading_started'
              : 'job_completed',
        createdBy: userId,
        notes: `Driver ${action}ed the job`,
        payload: {
          action,
          timestamp: new Date().toISOString(),
          driverId: userId,
        },
        mediaUrls: [],
      },
    });

    return NextResponse.json({
      success: true,
      assignment: updatedAssignment,
    });
  } catch (error) {
    console.error('❌ Error updating driver job:', error);
    return NextResponse.json(
      { error: 'Failed to update job' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { authenticateBearerToken } from '@/lib/bearer-auth';
import { prisma } from '@/lib/prisma';
import Pusher from 'pusher';

export const dynamic = 'force-dynamic';

// CORS headers for mobile app compatibility
const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
  'Access-Control-Allow-Headers': 'Content-Type, Authorization',
};

// Handle OPTIONS preflight request
export async function OPTIONS() {
  return NextResponse.json({}, { headers: corsHeaders });
}

// Initialize Pusher
const pusher = new Pusher({
  appId: process.env.PUSHER_APP_ID!,
  key: process.env.PUSHER_KEY!,
  secret: process.env.PUSHER_SECRET!,
  cluster: process.env.PUSHER_CLUSTER!,
  useTLS: true,
});

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    // Try Bearer token authentication first (for mobile app)
    const bearerAuth = await authenticateBearerToken(request);
    let userId: string;
    
    if (bearerAuth.success) {
      userId = bearerAuth.user.id;
      if (bearerAuth.user.role !== 'driver') {
        return NextResponse.json(
          { error: 'Forbidden - Driver access required' },
          { status: 403, headers: corsHeaders }
        );
      }
      console.log('🔑 Bearer token authenticated for user:', userId);
    } else {
      // Fallback to NextAuth session (for web app)
      const session = await getServerSession(authOptions);
      
      if (!session?.user || (session.user as any).role !== 'driver') {
        return NextResponse.json(
          { error: 'Unauthorized - Driver access required' },
          { status: 401, headers: corsHeaders }
        );
      }

      userId = (session.user as any).id;
      console.log('🌐 NextAuth session authenticated for user:', userId);
    }
    const { id: jobId } = await params;

    // Get driver record
    const driver = await prisma.driver.findUnique({
      where: { userId: userId },
      select: { 
        id: true,
        userId: true,
        DriverAvailability: {
          select: {
            status: true,
            locationConsent: true,
          }
        }
      },
    });

    if (!driver) {
      return NextResponse.json(
        { error: 'Driver record not found' },
        { status: 404 }
      );
    }

    // Get the assignment
    const assignment = await prisma.assignment.findFirst({
      where: {
        bookingId: jobId,
        driverId: driver.id,
        status: 'accepted',
      },
      include: {
        Booking: {
          select: {
            reference: true,
            customerName: true,
            customerPhone: true,
          }
        }
      }
    });

    if (!assignment) {
      return NextResponse.json(
        { error: 'Assignment not found or not in accepted status' },
        { status: 404 }
      );
    }

    // Update assignment status (using correct enum)
    const updatedAssignment = await prisma.assignment.update({
      where: { id: assignment.id },
      data: { 
        status: 'accepted', // Keep as accepted since 'in_progress' is not in enum
        updatedAt: new Date(),
      },
    });

    // Update booking status
    await prisma.booking.update({
      where: { id: jobId },
      data: { status: 'CONFIRMED' }, // Keep as CONFIRMED since IN_PROGRESS doesn't exist
    });

    // Create job event for tracking
    await prisma.jobEvent.create({
      data: {
        id: `event-${Date.now()}-start`,
        assignmentId: assignment.id,
        step: 'navigate_to_pickup', // Using correct enum value
        payload: {
          startedAt: new Date().toISOString(),
          location: 'pickup',
        },
        notes: 'Driver has started the job',
        createdAt: new Date(),
        createdBy: driver.id,
      },
    });

    // Create driver notification
    await prisma.driverNotification.create({
      data: {
        driverId: driver.id,
        type: 'job_update', // Using correct enum value
        title: 'Job Started',
        message: `You have started job ${assignment.Booking?.reference}. Safe travels!`,
        read: false,
      },
    });

    console.log('✅ Job started:', {
      jobId,
      driverId: driver.id,
      assignmentId: assignment.id,
      bookingReference: assignment.Booking?.reference,
    });

    // Send real-time notifications
    try {
      const { getPusherServer } = await import('@/lib/pusher');
      const pusher = getPusherServer();
      
      const timestamp = new Date().toISOString();
      
      console.log('📡 Sending admin notifications for job start...');

      // Get driver details
      const driverUser = await prisma.user.findUnique({
        where: { id: driver.userId },
        select: { name: true, email: true }
      });

      // 1. Notify admin-notifications channel (PROGRESS STARTED)
      await pusher.trigger('admin-notifications', 'driver-started-job', {
        type: 'job_started',
        severity: 'info',
        jobId,
        bookingReference: assignment.Booking?.reference,
        driverId: driver.id,
        driverName: driverUser?.name || 'Unknown Driver',
        message: `${driverUser?.name || 'Driver'} started job ${assignment.Booking?.reference}`,
        step: 'navigate_to_pickup',
        timestamp,
      });

      // 2. Notify admin-orders channel
      await pusher.trigger('admin-orders', 'order-started', {
        jobId,
        bookingReference: assignment.Booking?.reference,
        driverId: driver.id,
        driverName: driverUser?.name || 'Unknown Driver',
        status: 'in_progress',
        timestamp,
      });

      // 3. Notify admin-routes channel
      await pusher.trigger('admin-routes', 'job-started', {
        jobId,
        bookingReference: assignment.Booking?.reference,
        driverId: driver.id,
        driverName: driverUser?.name || 'Unknown Driver',
        timestamp,
      });

      // 4. Notify customer that job has started
      await pusher.trigger(`booking-${assignment.Booking?.reference}`, 'job-started', {
        driverId: driver.id,
        assignmentId: assignment.id,
        message: 'Your driver has started the job and is on the way',
        timestamp,
        trackingEnabled: true,
      });

      // 5. Start live tracking channel
      await pusher.trigger(`tracking-${assignment.Booking?.reference}`, 'tracking-started', {
        driverId: driver.id,
        assignmentId: assignment.id,
        status: 'in_progress',
        timestamp,
      });

      console.log('✅ Real-time notifications sent for job start');
    } catch (pusherError) {
      console.error('⚠️ Failed to send real-time notifications:', pusherError);
      console.error('⚠️ Error details:', pusherError instanceof Error ? pusherError.message : 'Unknown');
    }

    return NextResponse.json({
      success: true,
      message: 'Job started successfully',
      data: {
        assignmentId: assignment.id,
        status: 'accepted',
        bookingReference: assignment.Booking?.reference,
        trackingEnabled: true,
      },
    });

  } catch (error) {
    console.error('❌ Error starting job:', error);
    return NextResponse.json(
      {
        error: 'Failed to start job',
        details: error instanceof Error ? error.message : 'Unknown error',
      },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { authenticateBearerToken } from '@/lib/bearer-auth';
import { prisma } from '@/lib/prisma';
import Pusher from 'pusher';
import { DriverEarningsService } from '@/lib/services/driver-earnings-service';

export const dynamic = 'force-dynamic';

// CORS headers for mobile app
const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
  'Access-Control-Allow-Headers': 'Content-Type, Authorization',
};

export async function OPTIONS() {
  return NextResponse.json({}, { headers: corsHeaders });
}

// Initialize Pusher
const pusher = new Pusher({
  appId: process.env.PUSHER_APP_ID!,
  key: process.env.PUSHER_KEY!,
  secret: process.env.PUSHER_SECRET!,
  cluster: process.env.PUSHER_CLUSTER || 'eu',
  useTLS: true,
});

/**
 * POST /api/driver/jobs/[id]/update-progress
 * Update job progress step (for driver tracking)
 */
export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    // Authenticate driver
    const bearerAuth = await authenticateBearerToken(request);
    let userId: string;

    if (bearerAuth.success) {
      userId = bearerAuth.user.id;
    } else {
      const session = await getServerSession(authOptions);
      if (!session?.user) {
        return NextResponse.json(
          { success: false, error: 'Unauthorized' },
          { status: 401, headers: corsHeaders }
        );
      }
      userId = (session.user as any).id;
    }

    const { id: bookingId } = await params;
    const { step, payload } = await request.json();

    console.log('📊 Updating job progress:', { bookingId, step, userId });

    // Get driver
    const driver = await prisma.driver.findUnique({
      where: { userId },
      select: { id: true },
    });

    if (!driver) {
      return NextResponse.json(
        { success: false, error: 'Driver not found' },
        { status: 404, headers: corsHeaders }
      );
    }

    // Get booking with assignment
    const booking = await prisma.booking.findUnique({
      where: { id: bookingId },
      include: {
        Assignment: {
          where: { driverId: driver.id },
          orderBy: { createdAt: 'desc' },
          take: 1,
        },
        pickupAddress: true,
        dropoffAddress: true,
      },
    });

    if (!booking) {
      return NextResponse.json(
        { success: false, error: 'Job not found' },
        { status: 404, headers: corsHeaders }
      );
    }

    // Check if driver is assigned to this job
    const assignment = booking.Assignment[0];
    if (!assignment || assignment.driverId !== driver.id) {
      return NextResponse.json(
        { success: false, error: 'Not assigned to this job' },
        { status: 403, headers: corsHeaders }
      );
    }

    // Create job event
    const jobEvent = await prisma.jobEvent.create({
      data: {
        assignmentId: assignment.id,
        step: step,
        payload: payload || {},
        createdBy: userId, // ✅ Required field
        createdAt: new Date(),
      },
    });

    console.log('✅ Job event created:', { step, eventId: jobEvent.id });

    // Update booking status based on step
    // Don't update status - it's managed by accept/complete actions
    // Progress tracking is separate from booking status
    // The booking stays CONFIRMED until driver completes it
    
    // Only update to COMPLETED when job is finished
    if (step === 'job_completed' && booking.status !== 'COMPLETED') {
      // Update both booking and assignment status
      await prisma.booking.update({
        where: { id: bookingId },
        data: { 
          status: 'COMPLETED',
          actualDeliveryTime: new Date(),
        },
      });

      await prisma.assignment.update({
        where: { id: assignment.id },
        data: {
          status: 'completed',
          // ✅ Remove completedAt - not in schema
        },
      });

      console.log('✅ Booking and Assignment marked as COMPLETED');

      // Calculate and save driver earnings
      console.log('💰 Starting earnings calculation for completed job...');
      try {
        const driverEarningsService = new DriverEarningsService();
        
        const earningsInput = {
          driverId: driver.id,
          bookingId: booking.id,
          assignmentId: assignment.id,
          customerPaymentPence: booking.totalGBP,
          distanceMiles: booking.baseDistanceMiles || 0,
          durationMinutes: booking.estimatedDurationMinutes || 60,
          dropCount: 1,
          urgencyLevel: (booking.urgency as 'standard' | 'express' | 'premium') || 'standard',
          onTimeDelivery: true,
        };

        console.log('📊 Earnings input:', earningsInput);

        const earningsResult = await driverEarningsService.calculateEarnings(earningsInput);
        
        console.log('📊 Earnings calculated:', {
          grossEarnings: earningsResult.breakdown.grossEarnings,
          netEarnings: earningsResult.breakdown.netEarnings,
          netEarningsPounds: (earningsResult.breakdown.netEarnings / 100).toFixed(2),
        });

        // Save earnings to database (needs both input and result)
        const savedEarningsId = await driverEarningsService.saveEarnings(earningsInput, earningsResult);
        
        console.log('✅ Driver earnings SAVED to database:', {
          earningsId: savedEarningsId,
          driverId: driver.id,
          assignmentId: assignment.id,
          netEarnings: earningsResult.breakdown.netEarnings,
          netEarningsPounds: (earningsResult.breakdown.netEarnings / 100).toFixed(2),
        });

      } catch (earningsError: any) {
        console.error('❌ CRITICAL ERROR calculating/saving driver earnings:', {
          error: earningsError.message,
          stack: earningsError.stack,
          driverId: driver.id,
          bookingId: booking.id,
        });
        // Don't fail the entire request - earnings can be recalculated later
      }
    }

    // Send real-time update to customer tracking
    await pusher.trigger(`tracking-${booking.reference}`, 'job-progress-updated', {
      bookingReference: booking.reference,
      step: step,
      timestamp: new Date().toISOString(),
      message: getStepMessage(step),
    });

    console.log('📡 Customer tracking notified:', `tracking-${booking.reference}`);

    return NextResponse.json({
      success: true,
      step: step,
      timestamp: new Date().toISOString(),
      message: getStepMessage(step),
    }, { headers: corsHeaders });

  } catch (error: any) {
    console.error('❌ Error updating job progress:', error);
    return NextResponse.json(
      { success: false, error: error.message || 'Failed to update progress' },
      { status: 500, headers: corsHeaders }
    );
  }
}

function getStepMessage(step: string): string {
  const messages: Record<string, string> = {
    'navigate_to_pickup': 'Driver is heading to pickup location',
    'arrived_at_pickup': 'Driver has arrived at pickup location',
    'loading_started': 'Loading items into vehicle',
    'loading_completed': 'Items loaded - en route to delivery',
    'en_route_to_dropoff': 'On the way to delivery location',
    'arrived_at_dropoff': 'Driver has arrived at delivery location',
    'unloading_started': 'Unloading items',
    'unloading_completed': 'Items unloaded successfully',
    'job_completed': 'Delivery completed successfully',
  };
  return messages[step] || 'Status updated';
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';

export const dynamic = 'force-dynamic';

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    // ✅ Await params first (Next.js 15 requirement)
    const { id } = await params;
    console.log('🔄 Job step update API called:', {
      jobId: id,
      url: request.url
    });

    // Check driver authentication
    const session = await getServerSession(authOptions);
    if (!session?.user) {
      console.log('❌ No session found');
      return NextResponse.json(
        { error: 'Unauthorized - Please login' },
        { status: 401 }
      );
    }

    const userRole = (session.user as any)?.role;
    if (userRole !== 'driver') {
      console.log('❌ User is not a driver:', { userRole, userId: session.user.id });
      return NextResponse.json(
        { error: 'Forbidden - Driver access required' },
        { status: 403 }
      );
    }

    const userId = session.user.id;
    const { id: bookingId } = await params;

    console.log('✅ Driver authenticated:', { userId, userRole, bookingId });

    // Get driver record
    const driver = await prisma.driver.findUnique({
      where: { userId },
      select: { id: true }
    });

    if (!driver) {
      console.log('❌ Driver profile not found for user:', userId);
      return NextResponse.json(
        { error: 'Driver profile not found' },
        { status: 404 }
      );
    }

    // Get booking to verify access
    const booking = await prisma.booking.findUnique({
      where: { id: bookingId },
      include: {
        Assignment: true
      }
    });

    if (!booking) {
      console.log('❌ Booking not found:', bookingId);
      return NextResponse.json(
        { error: 'Job not found' },
        { status: 404 }
      );
    }

    // Check if driver has access to this job (Assignment is an array)
    const isAssignedToDriver = booking.driverId === driver.id;
    const hasAssignment = booking.Assignment && booking.Assignment[0]?.driverId === driver.id;

    if (!isAssignedToDriver && !hasAssignment) {
      console.log('❌ Access denied for job:', bookingId);
      return NextResponse.json(
        { error: 'You do not have access to this job' },
        { status: 403 }
      );
    }

    // Parse JSON body
    const body = await request.json();
    const { step, notes = '' } = body;

    if (!step) {
      return NextResponse.json(
        { error: 'Step is required' },
        { status: 400 }
      );
    }

    console.log('📝 Updating job step:', {
      bookingId,
      driverId: driver.id,
      step,
      notes: notes.substring(0, 50) + (notes.length > 50 ? '...' : '')
    });

    // Get or create assignment (Assignment is an array from Prisma)
    let assignment = booking.Assignment?.[0];
    
    if (!assignment) {
      // ✅ Use findFirst then update/create instead of upsert
      const existingAssignment = await prisma.assignment.findFirst({
        where: { bookingId: bookingId }
      });

      if (existingAssignment) {
        assignment = await prisma.assignment.update({
          where: { id: existingAssignment.id },
          data: {
            driverId: driver.id,
            status: 'accepted',
            claimedAt: new Date(),
            updatedAt: new Date(),
            expiresAt: new Date(Date.now() + 30 * 60 * 1000) // 30 minutes
          }
        });
      } else {
        assignment = await prisma.assignment.create({
          data: {
            id: `assignment_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
            bookingId: bookingId,
            driverId: driver.id,
            status: 'accepted',
            claimedAt: new Date(),
            updatedAt: new Date(),
            expiresAt: new Date(Date.now() + 30 * 60 * 1000) // 30 minutes
          }
        });
      }
    }

    // Create job event
    const jobEvent = await prisma.jobEvent.create({
      data: {
        id: `je_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
        assignmentId: assignment!.id,
        step: step as any, // Cast to JobStep enum
        notes: notes,
        createdBy: driver.id,
        payload: {
          timestamp: new Date().toISOString(),
          driverId: driver.id
        }
      }
    });

    // Update assignment status based on step
    let newStatus = assignment.status;
    if (step === 'job_completed') {
      newStatus = 'completed';
      
      // ✅ Create driver earnings when job is completed using REAL pricing engine
      const booking = await prisma.booking.findUnique({
        where: { id: assignment.bookingId },
        include: {
          BookingItem: true,
          pickupAddress: true,
          dropoffAddress: true,
        }
      });
      
      if (booking) {
        try {
          // ✅ Use unified driver earnings service (100% to driver, daily cap £500)
          const { driverEarningsService } = await import('@/lib/services/driver-earnings-service');
          
          const earningsResult = await driverEarningsService.calculateEarnings({
            driverId: driver.id,
            bookingId: booking.id,
            assignmentId: assignment.id,
            customerPaymentPence: booking.totalGBP,
            distanceMiles: booking.baseDistanceMiles || 0,
            durationMinutes: booking.estimatedDurationMinutes || 0,
            dropCount: 1,
            hasHelper: false,
            urgencyLevel: 'standard',
            onTimeDelivery: true,
          });

          // Save to database
          await driverEarningsService.saveEarnings({
            driverId: driver.id,
            assignmentId: assignment.id,
            bookingId: booking.id,
            distanceMiles: booking.baseDistanceMiles || 0,
            durationMinutes: booking.estimatedDurationMinutes || 0,
            dropCount: 1,
            customerPaymentPence: booking.totalGBP,
            urgencyLevel: 'standard',
            onTimeDelivery: true,
          }, earningsResult);
          
          console.log('✅ Driver earnings created using REAL engine:', {
            driverId: driver.id,
            assignmentId: assignment.id,
            bookingReference: booking.reference,
            customerPaid: booking.totalGBP,
            netEarningsPence: earningsResult.breakdown.netEarnings,
          });
        } catch (earningsError) {
          console.error('❌ Failed to calculate driver earnings on job completion:', earningsError);
          // Don't fail the completion, just log the error
          // Admin will need to manually calculate earnings
        }

        // Update booking status to COMPLETED when driver completes the job
        await prisma.booking.update({
          where: { id: booking.id },
          data: { 
            status: 'COMPLETED',
            updatedAt: new Date()
          }
        });

        console.log('✅ Booking marked as COMPLETED:', {
          bookingId: booking.id,
          bookingReference: booking.reference,
          driverId: driver.id
        });

        // Send admin notification about order completion
        try {
          const { getPusherServer } = await import('@/lib/pusher');
          const pusher = getPusherServer();

          // Get driver details for notification
          const driverDetails = await prisma.driver.findUnique({
            where: { id: driver.id },
            include: { User: { select: { name: true } } }
          });

          // Notify admin dashboard about order completion
          await pusher.trigger('admin-notifications', 'order-completed', {
            bookingId: booking.id,
            bookingReference: booking.reference,
            customerName: booking.customerName,
            driverName: driverDetails?.User?.name || 'Unknown Driver',
            completedAt: new Date().toISOString(),
            message: `Order ${booking.reference} has been completed by driver ${driverDetails?.User?.name || 'Unknown'}`,
          });

          console.log('✅ Admin notification sent for order completion:', {
            bookingId: booking.id,
            bookingReference: booking.reference,
            driverName: driverDetails?.User?.name
          });
        } catch (notificationError) {
          console.error('❌ Error sending admin notification for order completion:', notificationError);
          // Don't fail the request if notification fails
        }
      }
    } else if (step === 'navigate_to_pickup' && assignment.status === 'invited') {
      newStatus = 'accepted';
    }

    if (newStatus !== assignment.status) {
      await prisma.assignment.update({
        where: { id: assignment.id },
        data: { status: newStatus }
      });
    }

    console.log('✅ Job step updated successfully:', {
      bookingId,
      step,
      eventId: jobEvent.id,
      newStatus
    });

    return NextResponse.json({
      success: true,
      data: {
        eventId: jobEvent.id,
        step: jobEvent.step,
        notes: jobEvent.notes,
        createdAt: jobEvent.createdAt,
        assignmentStatus: newStatus
      }
    });

  } catch (error) {
    console.error('❌ Error updating job step:', error);
    return NextResponse.json(
      {
        error: 'Failed to update job step',
        details: error instanceof Error ? error.message : 'Unknown error'
      },
      { status: 500 }
    );
  }
}

import { NextResponse, NextRequest } from 'next/server';
import { requireDriver } from '@/lib/auth';
import { prisma } from '@/lib/prisma';

export const dynamic = 'force-dynamic';

export async function GET(request: NextRequest) {
    const authResult = await requireDriver(request);
    if (authResult instanceof NextResponse) {
        return authResult;
    }
    const user = authResult;

  const userId = user.id;

  try {
    // Get driver
    const driver = await prisma.driver.findUnique({
      where: { userId },
    });

    if (!driver) {
      return NextResponse.json({ error: 'Driver not found' }, { status: 404 });
    }

    // Get active assignment (accepted status)
    const activeAssignment = await prisma.assignment.findFirst({
      where: {
        driverId: driver.id,
        status: 'accepted',
      },
      include: {
        Booking: {
          include: {
            pickupAddress: true,
            dropoffAddress: true,
          },
        },
        JobEvent: {
          orderBy: { createdAt: 'asc' },
        },
      },
    });

    if (!activeAssignment) {
      return NextResponse.json({ activeJob: null });
    }

    // Determine current step based on events
    const events = activeAssignment.JobEvent;
    let currentStep = 'navigate_to_pickup';
    let completedSteps: string[] = [];

    if (events.length > 0) {
      const lastEvent = events[events.length - 1];
      currentStep = lastEvent.step;

      // Build completed steps array
      completedSteps = events.map(event => event.step);
    }

    // Define step order for the stepper
    const stepOrder = [
      'navigate_to_pickup',
      'arrived_at_pickup',
      'loading_started',
      'loading_completed',
      'en_route_to_dropoff',
      'arrived_at_dropoff',
      'unloading_started',
      'unloading_completed',
      'job_completed',
    ];

    // Calculate progress percentage
    const currentStepIndex = stepOrder.indexOf(currentStep);
    const progressPercentage = Math.max(
      0,
      Math.min(100, (currentStepIndex / (stepOrder.length - 1)) * 100)
    );

    return NextResponse.json({
      activeJob: {
        id: activeAssignment.id,
        jobId: activeAssignment.bookingId,
        status: activeAssignment.status,
        currentStep,
        completedSteps,
        progressPercentage,
        stepOrder,
        events: events.map(event => ({
          id: event.id,
          step: event.step,
          payload: event.payload,
          mediaUrls: event.mediaUrls,
          notes: event.notes,
          createdAt: event.createdAt,
        })),
        job: {
          id: activeAssignment.Booking.id,
          reference: activeAssignment.Booking.reference,
          pickupAddress: activeAssignment.Booking.pickupAddress?.label || '',
          dropoffAddress: activeAssignment.Booking.dropoffAddress?.label || '',
          pickupLat: activeAssignment.Booking.pickupAddress?.lat || 0,
          pickupLng: activeAssignment.Booking.pickupAddress?.lng || 0,
          dropoffLat: activeAssignment.Booking.dropoffAddress?.lat || 0,
          dropoffLng: activeAssignment.Booking.dropoffAddress?.lng || 0,
          scheduledAt: activeAssignment.Booking.scheduledAt,
          totalGBP: activeAssignment.Booking.totalGBP,
          customerName: activeAssignment.Booking.customerName,
          customerPhone: activeAssignment.Booking.customerPhone,
          customerEmail: activeAssignment.Booking.customerEmail,
        },
      },
    });
  } catch (error) {
    console.error('Active job API error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

