// Helper function to get distance from saved booking data or use default
function getDistanceFromBooking(booking: any, pickup: any, dropoff: any): string {
  // Priority: saved distance data > default fallback
  if (booking.distanceMeters) {
    return (booking.distanceMeters / 1609.34).toFixed(1); // Convert meters to miles
  }
  if (booking.baseDistanceMiles) {
    return booking.baseDistanceMiles.toFixed(1);
  }
  
  // Fallback: Use a reasonable default distance based on London area
  // This avoids using any distance calculator functions
  return '5.0'; // Default 5 miles for London area jobs
}

export async function GET(request: NextRequest) {
  try {
    console.log('🚗 Driver Jobs API - Starting request');
    
    // Try Bearer token authentication first (for mobile app)
    const bearerAuth = await authenticateBearerToken(request);
    let userId: string;
    let session: any = null;
    
    if (bearerAuth.success) {
      userId = bearerAuth.user.id;
      console.log('🔑 Bearer token authenticated for user:', userId);
    } else {
      // Fallback to NextAuth session (for web app)
      session = await getServerSession(authOptions);
      if (!session?.user) {
        console.log('❌ Driver Jobs API - No session found');
        return NextResponse.json(
          { error: 'Unauthorized - Please login' },
          { status: 401, headers: corsHeaders }
        );
      }
      userId = session.user.id;
      console.log('🌐 NextAuth session authenticated for user:', userId);
    }

    // Get user role from bearer auth or session
    const userRole = bearerAuth.success ? bearerAuth.user.role : (session?.user as any)?.role;
    if (userRole !== 'driver') {
      console.log('❌ Driver Jobs API - Invalid role:', userRole);
      return NextResponse.json(
        { error: 'Forbidden - Driver access required' },
        { status: 403, headers: corsHeaders }
      );
    }
    console.log('🚗 Driver Jobs API - Processing for user:', userId);

    // Use withPrisma for all database operations with connection checking
    const { driver, assignedJobs, availableJobs } = await withPrisma(async (prisma) => {
      // Get driver record
      const driver = await prisma.driver.findUnique({
        where: { userId },
        select: { id: true, status: true, onboardingStatus: true }
      });

      if (!driver) {
        throw new Error('Driver profile not found');
      }

      if (driver.status !== 'active' || driver.onboardingStatus !== 'approved') {
        console.log('❌ Driver Jobs API - Driver not active or approved:', {
          status: driver.status,
          onboardingStatus: driver.onboardingStatus
        });
        throw new Error('Driver account not active or not approved');
      }

      console.log('✅ Driver Jobs API - Driver verified, fetching jobs');

      // Get driver's assigned jobs (accepted/invited)
      // ✅ OPTIMIZED: Only fetch essential data for assigned jobs
      const assignedJobs = await prisma.assignment.findMany({
        where: {
          driverId: driver.id,
          status: { in: ['invited', 'accepted'] }
        },
        select: {
          id: true,
          status: true,
          claimedAt: true,
          Booking: {
            select: {
              id: true,
              reference: true,
              status: true,
              scheduledAt: true,
              pickupAddress: {
                select: {
                  label: true,
                  postcode: true,
                  lat: true,
                  lng: true
                }
              },
              dropoffAddress: {
                select: {
                  label: true,
                  postcode: true,
                  lat: true,
                  lng: true
                }
              },
              customer: {
                select: {
                  name: true,
                  email: true
                }
              }
            }
          }
        },
        orderBy: { createdAt: 'desc' },
        take: 10 // ✅ Limit to 10 most recent jobs
      });

      // ✅ OPTIMIZED: Only fetch essential data for available jobs
      // CRITICAL: Only show jobs with NO assignments at all (not assigned to ANY driver)
      const availableJobs = await prisma.booking.findMany({
        where: {
          status: 'CONFIRMED',
          driverId: null, // Not assigned to any driver
          scheduledAt: {
            gte: new Date() // Future bookings only
          },
          // EXTRA SECURITY: Ensure no assignments exist for this booking
          Assignment: {
            none: {} // No assignments at all
          }
        },
        select: {
          id: true,
          reference: true,
          status: true,
          scheduledAt: true,
          pickupAddress: {
            select: {
              label: true,
              postcode: true,
              lat: true,
              lng: true
            }
          },
          dropoffAddress: {
            select: {
              label: true,
              postcode: true,
              lat: true,
              lng: true
            }
          },
          customer: {
            select: {
              name: true,
              email: true
            }
          }
        },
        orderBy: { scheduledAt: 'asc' },
        take: 20 // ✅ Reduced from 50 to 20
      });

      return { driver, assignedJobs, availableJobs };
    });

    console.log('📊 Driver Jobs API - Found jobs:', {
      assigned: assignedJobs.length,
      available: availableJobs.length
    });

    // Transform assigned jobs
    const transformedAssignedJobs = assignedJobs.map(assignment => {
      const booking = assignment as any; // Type assertion for new fields (distanceMeters, durationSeconds)
      const pickup = booking.pickupAddress;
      const dropoff = booking.dropoffAddress;
      // Map assignment status to display status
      const status = assignment.status === 'accepted' ? 'accepted' : 
                     assignment.status === 'invited' ? 'available' : // Invited jobs show as available with Accept/Decline buttons
                     'assigned';
      
      // ✅ Use saved distance/duration first, fallback to calculation
      const distanceMiles = booking.distanceMeters 
        ? (booking.distanceMeters / 1609.34).toFixed(1)
        : booking.baseDistanceMiles 
          ? booking.baseDistanceMiles.toFixed(1)
          : (pickup && dropoff && pickup.lat && pickup.lng && dropoff.lat && dropoff.lng)
            ? getDistanceFromBooking(booking, pickup, dropoff)
            : '0';
      
      const durationMinutes = booking.durationSeconds 
        ? Math.round(booking.durationSeconds / 60)
        : booking.estimatedDurationMinutes || 120; // Default 2 hours
      
      const durationHours = Math.floor(durationMinutes / 60);
      const durationMins = durationMinutes % 60;
      const durationText = durationHours > 0 
        ? `${durationHours}h ${durationMins}m`
        : `${durationMins}m`;
      
      return {
        id: booking.id,
        reference: booking.reference,
        customer: booking.customer?.name || booking.customerName || 'Unknown Customer',
        customerPhone: booking.customerPhone || booking.customerEmail || 'No contact info',
        date: booking.scheduledAt.toISOString().split('T')[0],
        time: booking.scheduledAt.toTimeString().split(' ')[0].slice(0, 5),
        from: pickup?.label || 'Pickup Address',
        to: dropoff?.label || 'Dropoff Address',
        distance: `${distanceMiles} miles`,
        distanceMeters: booking.distanceMeters || 0,
        durationSeconds: booking.durationSeconds || 0,
        vehicleType: 'Van', // Default vehicle type
        items: booking.BookingItem?.map((item: any) => `${item.quantity || 1}x ${item.name || 'Unknown Item'}`).join(', ') || 'No items',
        estimatedEarnings: penceToPounds(Number(booking.totalGBP) || 0),
        status: status,
        priority: 'normal',
        duration: durationText,
        crew: '1 person'
      };
    });

    // Transform available jobs
    const transformedAvailableJobs = availableJobs.map(bookingData => {
      const booking = bookingData as any; // Type assertion for new fields (distanceMeters, durationSeconds)
      const pickup = booking.pickupAddress;
      const dropoff = booking.dropoffAddress;
      
      // ✅ Use saved distance/duration first, fallback to calculation
      const distanceMiles = booking.distanceMeters 
        ? (booking.distanceMeters / 1609.34).toFixed(1)
        : booking.baseDistanceMiles 
          ? booking.baseDistanceMiles.toFixed(1)
          : (pickup && dropoff && pickup.lat && pickup.lng && dropoff.lat && dropoff.lng)
            ? getDistanceFromBooking(booking, pickup, dropoff)
            : '0';
      
      const durationMinutes = booking.durationSeconds 
        ? Math.round(booking.durationSeconds / 60)
        : booking.estimatedDurationMinutes || 120; // Default 2 hours
      
      const durationHours = Math.floor(durationMinutes / 60);
      const durationMins = durationMinutes % 60;
      const durationText = durationHours > 0 
        ? `${durationHours}h ${durationMins}m`
        : `${durationMins}m`;
      
      return {
        id: booking.id,
        reference: booking.reference,
        customer: booking.customer?.name || booking.customerName || 'Unknown Customer',
        customerPhone: booking.customerPhone || booking.customerEmail || 'No contact info',
        date: booking.scheduledAt.toISOString().split('T')[0],
        time: booking.scheduledAt.toTimeString().split(' ')[0].slice(0, 5),
        from: pickup?.label || 'Pickup Address',
        to: dropoff?.label || 'Dropoff Address',
        distance: `${distanceMiles} miles`,
        distanceMeters: booking.distanceMeters || 0,
        durationSeconds: booking.durationSeconds || 0,
        vehicleType: 'Van', // Default vehicle type
        items: booking.BookingItem?.map((item: any) => `${item.quantity || 1}x ${item.name || 'Unknown Item'}`).join(', ') || 'No items',
        estimatedEarnings: penceToPounds(Number(booking.totalGBP) || 0),
        status: 'available',
        priority: 'normal',
        duration: durationText,
        crew: '1 person'
      };
    });

    // ✅ CRITICAL: Filter out demo data for production accounts
    // Get user email from driver record
    const driverUser = await withPrisma(async (prisma) => {
      return await prisma.user.findUnique({
        where: { id: userId },
        select: { email: true }
      });
    });
    const userEmail = driverUser?.email || null;
    const filteredAssignedJobs = filterDemoData(transformedAssignedJobs, userEmail, driver.id);
    const filteredAvailableJobs = filterDemoData(transformedAvailableJobs, userEmail, driver.id);

    // Log filtering
    if (filteredAssignedJobs.length !== transformedAssignedJobs.length) {
      console.log(`⚠️ DEMO GUARD: Filtered ${transformedAssignedJobs.length - filteredAssignedJobs.length} demo assigned jobs (production account)`);
    }
    if (filteredAvailableJobs.length !== transformedAvailableJobs.length) {
      console.log(`⚠️ DEMO GUARD: Filtered ${transformedAvailableJobs.length - filteredAvailableJobs.length} demo available jobs (production account)`);
    }

    // Combine filtered jobs
    const allJobs = [...filteredAssignedJobs, ...filteredAvailableJobs];

    const responseData = {
      jobs: allJobs,
      total: allJobs.length,
      available: filteredAvailableJobs.length,
      assigned: filteredAssignedJobs.length
    };

    console.log('✅ Driver Jobs API - Successfully processed jobs:', {
      total: responseData.total,
      available: responseData.available,
      assigned: responseData.assigned
    });

    return NextResponse.json({
      success: true,
      data: responseData
