import { NextRequest, NextResponse } from 'next/server';
import { auth } from '@/lib/auth';
import { assertDriver } from '@/lib/guards';
import { logAudit } from '@/lib/audit';
import { prisma } from '@/lib/prisma';

export const dynamic = 'force-dynamic';

export async function POST(request: NextRequest) {
  try {
    const session = await auth();
    assertDriver(session!);
    const formData = await request.json();
    const userId = session.user.id;

    // Get or create driver record
    let driver = await prisma.driver.findUnique({
      where: { userId },
      include: { DriverVehicle: true, DriverChecks: true },
    });

    if (!driver) {
      // Create new driver record
      driver = await prisma.driver.create({
        data: {
          userId,
          onboardingStatus: 'docs_pending',
          basePostcode: formData.postcode,
          vehicleType: formData.vehicleType,
        },
        include: { DriverVehicle: true, DriverChecks: true },
      });

      // Create driver availability record - Default to online
      await prisma.driverAvailability.create({
        data: {
          driverId: driver.id,
          status: 'online',
          locationConsent: false,
        },
      });
    }

    // Update user information
    await prisma.user.update({
      where: { id: userId },
      data: {
        name: `${formData.firstName} ${formData.lastName}`,
      },
    });

    // Create or update vehicle
    if (driver.DriverVehicle.length > 0) {
      await prisma.driverVehicle.update({
        where: { id: driver.DriverVehicle[0].id },
        data: {
          make: formData.vehicleMake,
          model: formData.vehicleModel,
          reg: formData.vehicleReg,
          weightClass: formData.vehicleCapacity,
          motExpiry: formData.motExpiry ? new Date(formData.motExpiry) : null,
        },
      });
    } else {
      await prisma.driverVehicle.create({
        data: {
          driverId: driver.id,
          make: formData.vehicleMake,
          model: formData.vehicleModel,
          reg: formData.vehicleReg,
          weightClass: formData.vehicleCapacity,
          motExpiry: formData.motExpiry ? new Date(formData.motExpiry) : null,
        },
      });
    }

    // Create or update driver checks
    if (driver.DriverChecks) {
      await prisma.driverChecks.update({
        where: { id: driver.DriverChecks.id },
        data: {
          // Add any additional check data here
        },
      });
    } else {
      await prisma.driverChecks.create({
        data: {
          driverId: driver.id,
          // Add any additional check data here
        },
      });
    }

    // Update driver status to docs_pending
    await prisma.driver.update({
      where: { id: driver.id },
      data: {
        onboardingStatus: 'docs_pending',
        basePostcode: formData.postcode,
        vehicleType: formData.vehicleType,
      },
    });

    // Log the onboarding submission
    await logAudit(session.user.id, 'driver_onboarding_submitted', driver.id, { targetType: 'driver', before: null, after: {
        onboardingStatus: 'docs_pending',
        vehicleType: formData.vehicleType,
        basePostcode: formData.postcode,
      },
    });

    return NextResponse.json({
      success: true,
      message: 'Onboarding submitted successfully',
      driver: {
        id: driver.id,
        onboardingStatus: 'docs_pending',
      },
    });
  } catch (error) {
    console.error('Driver onboarding error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';

export const dynamic = 'force-dynamic';

export async function GET(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user?.id || session.user.role !== 'driver') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    // Get driver
    const driver = await prisma.driver.findUnique({
      where: { userId: session.user.id },
    });

    if (!driver) {
      return NextResponse.json({ error: 'Driver not found' }, { status: 404 });
    }

    // Get payout settings
    const settings = await prisma.driverPayoutSettings.findUnique({
      where: { driverId: driver.id },
    });

    if (!settings) {
      return NextResponse.json({
        autoPayout: false,
        minPayoutAmountPence: 5000,
        verified: false,
        hasBankDetails: false,
        hasStripeAccount: false,
      });
    }

    return NextResponse.json({
      autoPayout: settings.autoPayout,
      minPayoutAmountPence: settings.minPayoutAmountPence,
      verified: settings.verified,
      verifiedAt: settings.verifiedAt,
      hasBankDetails: !!(
        settings.accountName &&
        settings.accountNumber &&
        settings.sortCode
      ),
      hasStripeAccount: !!settings.stripeAccountId,
      // Don't return sensitive bank details in GET request
    });
  } catch (error) {
    console.error('Error fetching payout settings:', error);
    return NextResponse.json(
      { error: 'Failed to fetch payout settings' },
      { status: 500 }
    );
  }
}

export async function PUT(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user?.id || session.user.role !== 'driver') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const body = await request.json();
    const {
      autoPayout,
      minPayoutAmountPence,
      accountName,
      accountNumber,
      sortCode,
    } = body;

    // Get driver
    const driver = await prisma.driver.findUnique({
      where: { userId: session.user.id },
    });

    if (!driver) {
      return NextResponse.json({ error: 'Driver not found' }, { status: 404 });
    }

    // Validate inputs
    if (minPayoutAmountPence && minPayoutAmountPence < 1000) {
      return NextResponse.json(
        { error: 'Minimum payout amount must be at least £10' },
        { status: 400 }
      );
    }

    if (accountName && accountNumber && sortCode) {
      // Basic validation for UK bank details
      if (sortCode.length !== 6 || !/^\d{6}$/.test(sortCode)) {
        return NextResponse.json(
          { error: 'Invalid sort code format' },
          { status: 400 }
        );
      }

      if (accountNumber.length !== 8 || !/^\d{8}$/.test(accountNumber)) {
        return NextResponse.json(
          { error: 'Invalid account number format' },
          { status: 400 }
        );
      }
    }

    // Update or create payout settings
    const settings = await prisma.driverPayoutSettings.upsert({
      where: { driverId: driver.id },
      update: {
        autoPayout: autoPayout !== undefined ? autoPayout : undefined,
        minPayoutAmountPence: minPayoutAmountPence || undefined,
        accountName: accountName || undefined,
        accountNumber: accountNumber || undefined,
        sortCode: sortCode || undefined,
        verified: false, // Reset verification when details change
        verifiedAt: null,
      },
      create: {
        driverId: driver.id,
        autoPayout: autoPayout || false,
        minPayoutAmountPence: minPayoutAmountPence || 5000,
        accountName,
        accountNumber,
        sortCode,
        verified: false,
      },
    });

    return NextResponse.json({
      autoPayout: settings.autoPayout,
      minPayoutAmountPence: settings.minPayoutAmountPence,
      verified: settings.verified,
      hasBankDetails: !!(
        settings.accountName &&
        settings.accountNumber &&
        settings.sortCode
      ),
      hasStripeAccount: !!settings.stripeAccountId,
    });
  } catch (error) {
    console.error('Error updating payout settings:', error);
    return NextResponse.json(
      { error: 'Failed to update payout settings' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';

export const dynamic = 'force-dynamic';

export async function GET(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user?.id || session.user.role !== 'driver') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const { searchParams } = new URL(request.url);
    const page = parseInt(searchParams.get('page') || '1');
    const limit = parseInt(searchParams.get('limit') || '20');
    const status = searchParams.get('status');

    // Get driver
    const driver = await prisma.driver.findUnique({
      where: { userId: session.user.id },
    });

    if (!driver) {
      return NextResponse.json({ error: 'Driver not found' }, { status: 404 });
    }

    // Build where clause
    const where: any = { driverId: driver.id };
    if (status) {
      where.status = status;
    }

    // Get payouts with pagination
    const [payouts, total] = await Promise.all([
      prisma.driverPayout.findMany({
        where,
        include: {
          DriverEarnings: {
            include: {
              Assignment: {
                include: {
                  Booking: {
                    select: {
                      reference: true,
                      pickupAddress: true,
                      dropoffAddress: true,
                    },
                  },
                },
              },
            },
          },
        },
        orderBy: {
          createdAt: 'desc',
        },
        skip: (page - 1) * limit,
        take: limit,
      }),
      prisma.driverPayout.count({ where }),
    ]);

    // Calculate totals by status
    const statusTotals = await prisma.driverPayout.groupBy({
      by: ['status'],
      where: { driverId: driver.id },
      _sum: {
        totalAmountPence: true,
      },
      _count: true,
    });

    const totals = statusTotals.reduce(
      (acc, item) => ({
        ...acc,
        [item.status]: {
          amount: item._sum.totalAmountPence || 0,
          count: item._count,
        },
      }),
      {}
    );

    return NextResponse.json({
      payouts: payouts.map(payout => ({
        id: payout.id,
        totalAmountPence: payout.totalAmountPence,
        currency: payout.currency,
        status: payout.status,
        processedAt: payout.processedAt,
        failedAt: payout.failedAt,
        failureReason: payout.failureReason,
        stripeTransferId: payout.stripeTransferId,
        createdAt: payout.createdAt,
        updatedAt: payout.updatedAt,
        earnings: payout.DriverEarnings.map(earning => ({
          id: earning.id,
          assignmentId: earning.assignmentId,
          bookingCode: earning.Assignment.Booking.reference,
          pickupAddress: earning.Assignment.Booking.pickupAddress,
          dropoffAddress: earning.Assignment.Booking.dropoffAddress,
          netAmountPence: earning.netAmountPence,
          calculatedAt: earning.calculatedAt,
        })),
      })),
      pagination: {
        page,
        limit,
        total,
        pages: Math.ceil(total / limit),
      },
      totals,
    });
  } catch (error) {
    console.error('Error fetching payouts:', error);
    return NextResponse.json(
      { error: 'Failed to fetch payouts' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { authenticateBearerToken } from '@/lib/bearer-auth';
import { prisma } from '@/lib/prisma';

export const dynamic = 'force-dynamic';

/**
 * GET /api/driver/performance
 * 
 * Fetch driver performance metrics including:
 * - Acceptance rate
 * - Total jobs (all time)
 * - Completed jobs
 * - Total earnings
 * - Average rating
 * - Jobs this week
 * - Jobs this month
 */
export async function GET(request: NextRequest) {
  try {
    console.log('📊 Driver Performance API - Starting request');
    
    // Try Bearer token authentication first (for mobile app)
    const bearerAuth = await authenticateBearerToken(request);
    let userId: string;
    let userRole: string;
    
    if (bearerAuth.success) {
      userId = bearerAuth.user.id;
      userRole = bearerAuth.user.role;
      console.log('🔑 Bearer token authenticated for user:', userId, 'role:', userRole);
    } else {
      // Fallback to NextAuth session (for web app)
      const session = await getServerSession(authOptions);
      if (!session?.user) {
        console.log('❌ Driver Performance API - Unauthorized access');
        return NextResponse.json(
          { error: 'Unauthorized - Driver access required' },
          { status: 401 }
        );
      }
      userId = (session.user as any).id;
      userRole = (session.user as any).role;
      console.log('🌐 NextAuth session authenticated for user:', userId, 'role:', userRole);
    }
    
    // Check role after getting it from both sources
    if (userRole !== 'driver') {
      console.log('❌ Driver Performance API - Invalid role:', userRole);
      return NextResponse.json(
        { error: 'Forbidden - Driver access required' },
        { status: 403 }
      );
    }

    // Get driver record
    const driver = await prisma.driver.findUnique({
      where: { userId: userId },
      select: { 
        id: true,
        rating: true,
        status: true,
        onboardingStatus: true,
      },
    });

    if (!driver) {
      return NextResponse.json(
        { error: 'Driver record not found' },
        { status: 404 }
      );
    }

    // Get driver performance record
    const performance = await prisma.driverPerformance.findUnique({
      where: { driverId: driver.id },
      select: {
        acceptanceRate: true,
        onTimeRate: true,
        completionRate: true,
        averageRating: true,
        totalJobs: true,
        completedJobs: true,
        cancelledJobs: true,
        lastCalculated: true,
      }
    });

    // Calculate date ranges
    const now = new Date();
    const startOfWeek = new Date(now);
    startOfWeek.setDate(now.getDate() - now.getDay());
    startOfWeek.setHours(0, 0, 0, 0);

    const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);

    // ✅ OPTIMIZED: Single query to get all job counts and earnings
    const [jobsThisWeek, jobsThisMonth, activeJobs, earnings] = await Promise.all([
      prisma.booking.count({
        where: {
          driverId: driver.id,
          status: { in: ['CONFIRMED', 'COMPLETED'] },
          createdAt: { gte: startOfWeek },
        },
      }),
      prisma.booking.count({
        where: {
          driverId: driver.id,
          status: { in: ['CONFIRMED', 'COMPLETED'] },
          createdAt: { gte: startOfMonth },
        },
      }),
      prisma.booking.count({
        where: {
          driverId: driver.id,
          status: 'CONFIRMED',
        },
      }),
      prisma.driverEarnings.aggregate({
        where: {
          driverId: driver.id,
        },
        _sum: {
          netAmountPence: true,
        },
      })
    ]);

    const totalEarningsPence = earnings._sum.netAmountPence || 0;

    // Build response
    const response = {
      success: true,
      data: {
        // Performance metrics
        acceptanceRate: performance?.acceptanceRate || 100,
        onTimeRate: performance?.onTimeRate || 100,
        completionRate: performance?.completionRate || 100,
        averageRating: performance?.averageRating || driver.rating || 5.0,
        
        // Job counts
        totalJobs: performance?.totalJobs || 0,
        completedJobs: performance?.completedJobs || 0,
        cancelledJobs: performance?.cancelledJobs || 0,
        activeJobs: activeJobs,
        jobsThisWeek: jobsThisWeek,
        jobsThisMonth: jobsThisMonth,
        
        // Earnings
        totalEarnings: (totalEarningsPence / 100).toFixed(2), // Convert pence to GBP
        totalEarningsGBP: (totalEarningsPence / 100).toFixed(2),
        
        // Status
        status: driver.status,
        onboardingStatus: driver.onboardingStatus,
        
        // Metadata
        lastCalculated: performance?.lastCalculated || new Date(),
      },
    };

    console.log(`📊 Driver performance fetched for driver ${driver.id}:`, {
      acceptanceRate: response.data.acceptanceRate,
      totalJobs: response.data.totalJobs,
      totalEarnings: response.data.totalEarnings,
    });

    return NextResponse.json(response);

  } catch (error) {
    console.error('❌ Error fetching driver performance:', error);
    return NextResponse.json(
      {
        error: 'Failed to fetch driver performance',
        details: error instanceof Error ? error.message : 'Unknown error',
      },
      { status: 500 }
    );
  }
}

