    const body = await request.json();
    const { reason } = body;

    console.log('🚗 Driver Route Decline API - Request:', { userId, routeId, reason });

    // Get driver record
    const driver = await prisma.driver.findUnique({
      where: { userId },
      select: { 
        id: true,
        User: {
          select: {
            name: true,
            email: true
          }
        }
      }
    });

    if (!driver) {
      return NextResponse.json(
        { error: 'Driver profile not found' },
        { status: 404 }
      );
    }

    // Get route with all details
    const route = await prisma.route.findUnique({
      where: { id: routeId },
      include: {
        drops: {
          include: {
            Booking: true
          }
        }
      }
    });

    if (!route) {
      return NextResponse.json(
        { error: 'Route not found' },
        { status: 404 }
      );
    }

    // Check if route is assigned to this driver
    if (route.driverId !== driver.id && route.status !== 'planned') {
      return NextResponse.json(
        { error: 'You are not assigned to this route' },
        { status: 403 }
      );
    }

    console.log('✅ Driver Route Decline API - Processing decline');

    let newAcceptanceRate = 100;

    // Decline the route and reassign
    await prisma.$transaction(async (tx) => {
      // Update route status back to planned
      await tx.route.update({
        where: { id: routeId },
        data: {
          driverId: { set: null },
          status: 'planned',
          declinedAt: new Date(),
          acceptanceStatus: 'declined',
          updatedAt: new Date()
        }
      });

      // Reset all associated bookings
      const bookingIds = route.drops
        .filter((drop: any) => drop.Booking)
        .map((drop: any) => drop.Booking!.id);

      if (bookingIds.length > 0) {
        await tx.booking.updateMany({
          where: {
            id: { in: bookingIds }
          },
          data: {
            driverId: null,
            updatedAt: new Date()
          }
        });
      }

      // Reset all drops status
      await tx.drop.updateMany({
        where: {
          routeId: routeId
        },
        data: {
          status: 'pending',
        }
      });

      // Update driver performance - decrease acceptance rate by 5%
      const performance = await tx.driverPerformance.findUnique({
        where: { driverId: driver.id }
      });

      if (performance) {
        // Decrease acceptance rate by 5%, but never below 0%
        const currentRate = performance.acceptanceRate || 100;
        newAcceptanceRate = Math.max(0, currentRate - 5);

        await tx.driverPerformance.update({
          where: { driverId: driver.id },
          data: {
            acceptanceRate: newAcceptanceRate,
            lastCalculated: new Date()
          }
        });

        console.log(`📉 Acceptance rate decreased: ${currentRate}% → ${newAcceptanceRate}%`);
      }

      // Update driver's acceptance rate
      // Find total invitations and declines in last 30 days
      const thirtyDaysAgo = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000);
      
      const declinedCount = await tx.auditLog.count({
        where: {
          actorId: driver.id,
          action: { in: ['route_declined', 'job_declined'] },
          createdAt: { gte: thirtyDaysAgo }
        }
      });

      // Create audit log for decline
      await tx.auditLog.create({
        data: {
          actorId: userId,
          actorRole: 'driver',
          action: 'route_declined',
          targetType: 'route',
          targetId: routeId,
          details: {
            driverId: driver.id,
            driverName: driver.User?.name,
            reason: reason || 'Driver declined',
            dropCount: (route as any).drops.length,
            declinedAt: new Date().toISOString(),
            impactOnAcceptanceRate: true,
            totalDeclinesLast30Days: declinedCount + 1,
            acceptanceRateChange: -5,
            newAcceptanceRate
          }
        }
      });
    });

    // Send immediate admin notifications
    try {
      const pusher = getPusherServer();
      
      console.log('📡 Sending admin notifications for route decline...');

      // 1. Notify admin-routes channel about the decline
      await pusher.trigger('admin-routes', 'route-declined', {
        routeId: routeId,
        routeNumber: route.id,
        driverId: driver.id,
        driverName: driver.User?.name || 'Unknown Driver',
        driverEmail: driver.User?.email,
        reason: reason || 'No reason provided',
        dropCount: (route as any).drops.length,
        estimatedEarnings: route.driverPayout ? `£${(Number(route.driverPayout) / 100).toFixed(2)}` : 'N/A',
        declinedAt: new Date().toISOString(),
        acceptanceRate: newAcceptanceRate,
        acceptanceRateChange: -5,
        timestamp: new Date().toISOString(),
      });

      // 2. Notify admin-notifications channel for immediate alert
      await pusher.trigger('admin-notifications', 'driver-declined-route', {
        type: 'route_declined',
        severity: 'warning',
        routeId: routeId,
        driverId: driver.id,
        driverName: driver.User?.name || 'Unknown Driver',
        dropCount: (route as any).drops.length,
        message: `${driver.User?.name || 'Driver'} declined route with ${(route as any).drops.length} stops`,
        reason: reason || 'No reason provided',
        timestamp: new Date().toISOString(),
      });

      // 3. Notify admin-drivers channel about acceptance rate change
      await pusher.trigger('admin-drivers', 'driver-acceptance-rate-updated', {
        driverId: driver.id,
        driverName: driver.User?.name || 'Unknown',
        acceptanceRate: newAcceptanceRate,
        change: -5,
        reason: 'route_declined',
        routeId: routeId,
        timestamp: new Date().toISOString(),
      });

      // 4. Update admin schedule
      await pusher.trigger('admin-schedule', 'schedule-updated', {
        type: 'route_declined',
        routeId: routeId,
        driverId: driver.id,
        driverName: driver.User?.name,
        dropCount: (route as any).drops.length,
        timestamp: new Date().toISOString(),
      });

      console.log('✅ Admin notifications sent successfully for route decline');
    } catch (notificationError) {
      console.error('⚠️ Failed to send admin notifications:', notificationError);
      // Don't fail the request if notifications fail
    }

    // Auto-reassign route to next available driver
    try {
      const availableDrivers = await prisma.driver.findMany({
        where: {
          id: { not: driver.id },
          status: 'active',
          onboardingStatus: 'approved',
          DriverAvailability: {
            status: 'online'
          }
        },
        include: {
          User: {
            select: {
              name: true,
              email: true
            }
          },
          DriverAvailability: true,
          DriverPerformance: true
        },
        orderBy: {
          DriverPerformance: {
            acceptanceRate: 'desc'
          }
        },
        take: 5
      });

      if (availableDrivers.length > 0) {
        // Filter by capacity
        const eligibleDrivers = availableDrivers.filter(d => {
          const availability = d.DriverAvailability;
          return availability && availability.currentCapacityUsed < availability.maxConcurrentDrops;
        });

        if (eligibleDrivers.length > 0) {
          // Assign to the best driver (highest acceptance rate)
          const nextDriver = eligibleDrivers[0];
          
          // Update route assignment
          await prisma.route.update({
            where: { id: routeId },
            data: {
              driverId: nextDriver.id,
              status: 'assigned',
              updatedAt: new Date()
            }
          });

          const pusher = getPusherServer();

          // Notify next driver
          await pusher.trigger(`driver-${nextDriver.id}`, 'route-offer', {
            routeId: routeId,
            dropCount: (route as any).drops.length,
            estimatedEarnings: Number(route.driverPayout || 0) / 100,
            estimatedDuration: route.estimatedDuration,
            message: `New route assigned with ${(route as any).drops.length} stops (auto-reassigned)`,
            timestamp: new Date().toISOString()
          });

          // Notify admin about reassignment
          await pusher.trigger('admin-routes', 'route-reassigned', {
            routeId,
            previousDriver: driver.id,
            previousDriverName: driver.User?.name,
            newDriver: nextDriver.id,
            newDriverName: nextDriver.User?.name,
            dropCount: (route as any).drops.length,
            timestamp: new Date().toISOString()
          });

          console.log(`✅ Route auto-reassigned to driver: ${nextDriver.User?.name}`);
        } else {
          // No eligible drivers with capacity - offer to multiple drivers
          const pusher = getPusherServer();
          for (const altDriver of availableDrivers.slice(0, 3)) {
            try {
              await pusher.trigger(`driver-${altDriver.id}`, 'route-offer', {
                routeId: routeId,
                dropCount: (route as any).drops.length,
                estimatedEarnings: Number(route.driverPayout || 0) / 100,
                estimatedDuration: route.estimatedDuration,
                message: `New route available with ${(route as any).drops.length} stops`
              });
            } catch (e) {
              console.warn(`Failed to notify driver ${altDriver.id}:`, e);
            }
          }
          
          console.log(`✅ Route offered to ${Math.min(3, availableDrivers.length)} drivers`);
        }
      } else {
        console.log('⚠️ No available drivers for reassignment');
      }
    } catch (reassignError) {
      console.warn('⚠️ Failed to reassign route:', reassignError);
      // Continue even if reassignment fails
    }

    // Send real-time notifications
    try {
      const pusher = getPusherServer();
      
      // 1. INSTANT REMOVAL: Remove route from driver's UI
      await pusher.trigger(`driver-${driver.id}`, 'route-removed', {
        routeId,
        reason: 'declined',
        message: 'Route declined and removed from your schedule',
        timestamp: new Date().toISOString()
      });

      // 2. Update acceptance rate
      await pusher.trigger(`driver-${driver.id}`, 'acceptance-rate-updated', {
        acceptanceRate: newAcceptanceRate,
        change: -5,
        reason: 'route_declined',
        routeId,
        timestamp: new Date().toISOString()
      });

      // 3. Notify admin channel
      await pusher.trigger('admin-drivers', 'driver-acceptance-rate-updated', {
        driverId: driver.id,
        driverName: driver.User?.name || 'Unknown',
        acceptanceRate: newAcceptanceRate,
        change: -5,
        reason: 'route_declined',
        routeId,
        timestamp: new Date().toISOString()
      });

      // 4. Update driver schedule
      await pusher.trigger(`driver-${driver.id}`, 'schedule-updated', {
        type: 'route_removed',
        routeId,
        acceptanceRate: newAcceptanceRate,
        timestamp: new Date().toISOString()
      });

      // 5. Update admin schedule
      await pusher.trigger('admin-schedule', 'driver-performance-updated', {
        driverId: driver.id,
        acceptanceRate: newAcceptanceRate,
        type: 'acceptance_rate_decreased',
        timestamp: new Date().toISOString()
      });

      // 6. Update admin/routes panel
      await pusher.trigger('admin-routes', 'route-status-changed', {
        routeId,
        status: 'available',
        previousDriver: driver.id,
        driverName: driver.User?.name,
        reason: 'declined',
        dropCount: (route as any).drops.length,
        timestamp: new Date().toISOString()
      });

      console.log('📡 Real-time notifications sent successfully');
    } catch (pusherError) {
      console.error('⚠️ Failed to send notifications:', pusherError);
    }

    // Final admin notification about decline
    try {
      const pusher = getPusherServer();
      await pusher.trigger('admin-channel', 'route-declined', {
        routeId: routeId,
        driverId: driver.id,
        driverName: driver.User?.name || 'Unknown Driver',
        dropCount: (route as any).drops.length,
        reason: reason || 'Driver declined',
        declinedAt: new Date().toISOString(),
        acceptanceRate: newAcceptanceRate,
        autoReassigned: true,
        message: `Driver ${driver.User?.name} declined route with ${(route as any).drops.length} stops. Acceptance rate: ${newAcceptanceRate}%. Route auto-reassigned.`
      });

      console.log('✅ Admin notification sent via Pusher');
    } catch (pusherError) {
      console.warn('⚠️ Failed to send Pusher notification:', pusherError);
    }

    console.log('✅ Route declined successfully:', {
      routeId,
      driverId: driver.id,
      newAcceptanceRate
    });

    return NextResponse.json({
      success: true,
      message: 'Route declined successfully',
      warning: `Your acceptance rate decreased by 5% to ${newAcceptanceRate}%. Declining jobs affects your performance rating.`,
      data: {
        routeId: routeId,
        reassignedToOtherDrivers: true,
        acceptanceRate: newAcceptanceRate,
        change: -5
      }
    });

  } catch (error) {
    console.error('❌ Error declining route:', error);
    return NextResponse.json(
      {
        error: 'Failed to decline route',
        details: error instanceof Error ? error.message : 'Unknown error'
      },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { authenticateBearerToken } from '@/lib/bearer-auth';
import { prisma } from '@/lib/prisma';

export const dynamic = 'force-dynamic';

export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    // ✅ Await params first (Next.js 15 requirement)
    const { id } = await params;
    // Try Bearer token authentication first (for mobile app)
    const bearerAuth = await authenticateBearerToken(request);
    let userId: string;

    if (bearerAuth.success) {
      userId = bearerAuth.user.id;
      if (bearerAuth.user.role !== 'driver') {
        return NextResponse.json(
          { error: 'Forbidden - Driver access required' },
          { status: 403 }
        );
      }
      console.log('🔑 Bearer token authenticated for user:', userId);
    } else {
      // Fallback to NextAuth session (for web app)
      const session = await getServerSession(authOptions);
      
      if (!session?.user || (session.user as any).role !== 'driver') {
        return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
      }

      userId = session.user.id;
      console.log('🌐 NextAuth session authenticated for user:', userId);
    }

    // Get driver record to find driverId
    const driver = await prisma.driver.findUnique({
      where: { userId },
      select: { id: true }
    });

    if (!driver) {
      return NextResponse.json({ error: 'Driver profile not found' }, { status: 404 });
    }

    const route = await prisma.route.findUnique({
      where: { id: id },
      include: {
        drops: {
          include: {
            Booking: {
              select: {
                id: true,
                reference: true,
                customerName: true,
                crewSize: true,
                BookingItem: {
                  select: {
                    id: true,
                    name: true,
                    quantity: true,
                  }
                }
              }
            }
          },
          orderBy: {
            timeWindowStart: 'asc',
          },
        },
      },
    });

    if (!route) {
      return NextResponse.json({ error: 'Route not found' }, { status: 404 });
    }

    // route.driverId is User.id, not Driver.id - compare with userId
    if (route.driverId !== userId) {
      return NextResponse.json({ error: 'Not authorized for this route' }, { status: 403 });
    }

    const drops = route.drops || [];
    const totalDistance = drops.reduce((sum: number, drop: any) => sum + (drop.distance || 0), 0);
    const totalEarnings = Number(route.driverPayout || route.totalOutcome || 0) / 100;
    const completedDrops = drops.filter((d: any) => d.status === 'delivered').length;

    return NextResponse.json({
      route: {
        id: route.id,
        status: route.status,
        estimatedDuration: route.estimatedDuration || 0,
        estimatedDistance: route.optimizedDistanceKm || totalDistance,
        estimatedEarnings: totalEarnings,
        completedDrops: completedDrops,
        currentDropIndex: completedDrops,
        drops: drops.map((drop: any) => ({
          id: drop.id,
          status: drop.status,
          pickupAddress: drop.pickupAddress,
          deliveryAddress: drop.deliveryAddress,
          timeWindowStart: drop.timeWindowStart,
          timeWindowEnd: drop.timeWindowEnd,
          serviceTier: drop.serviceTier,
          customerName: drop.Booking?.customerName || 'Unknown',
          items: drop.Booking?.BookingItem || [],
        })),
      }
    });

  } catch (error) {
    console.error('Error fetching route:', error);
    return NextResponse.json(
      { error: 'Failed to fetch route' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { withPrisma } from '@/lib/prisma';
import { authenticateBearerToken } from '@/lib/bearer-auth';

export const dynamic = 'force-dynamic';
export const maxDuration = 20; // Increased from 10 to 20 seconds for route operations

// CORS headers for mobile app compatibility
const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'GET, OPTIONS',
  'Access-Control-Allow-Headers': 'Content-Type, Authorization',
};

// Handle OPTIONS preflight request
export async function OPTIONS() {
  return NextResponse.json({}, { headers: corsHeaders });
}

export async function GET(request: NextRequest) {
  const startTime = Date.now();
  try {
    console.log('🚗 Driver Routes API - Starting request');
    
    // Try Bearer token authentication first (for mobile app)
    const bearerAuth = await authenticateBearerToken(request);
    let userId: string;
    
    if (bearerAuth.success) {
      userId = bearerAuth.user.id;
      console.log('🔑 Bearer token authenticated for user:', userId);
    } else {
      // Fallback to NextAuth session (for web app)
      const session = await getServerSession(authOptions);
      if (!session?.user) {
        console.log('❌ Driver Routes API - No session found');
        return NextResponse.json(
          { error: 'Unauthorized - Please login' },
          { status: 401, headers: corsHeaders }
        );
      }
      userId = session.user.id;
      console.log('🌐 NextAuth session authenticated for user:', userId);
    }

    // Get user role from bearer auth or session
    const session = bearerAuth.success ? null : await getServerSession(authOptions);
    const userRole = bearerAuth.success ? bearerAuth.user.role : (session?.user as any)?.role;
    if (userRole !== 'driver') {
      console.log('❌ Driver Routes API - Invalid role:', userRole);
      return NextResponse.json(
        { error: 'Forbidden - Driver access required' },
        { status: 403, headers: corsHeaders }
      );
    }
    console.log('🚗 Driver Routes API - Processing for user:', userId);

    // Use withPrisma for database operations with connection checking
    const { driver, routes } = await withPrisma(async (prisma) => {
      // Get driver record
      const driver = await prisma.driver.findUnique({
        where: { userId },
        select: { id: true, status: true, onboardingStatus: true }
      });

      if (!driver) {
        throw new Error('Driver profile not found');
      }

      console.log('✅ Driver found and verified:', {
        driverId: driver.id,
        status: driver.status,
        onboarding: driver.onboardingStatus
      });

      if (driver.status !== 'active' || driver.onboardingStatus !== 'approved') {
        console.log('❌ Driver not eligible:', {
          status: driver.status,
          onboarding: driver.onboardingStatus
        });
        throw new Error('Driver account not active or not approved');
      }

      // Get routes assigned to this driver with all drops
      // Note: Route.driverId references User.id, not Driver.id
      console.log('🔍 Querying routes for userId:', userId);
      
      const routes = await prisma.route.findMany({
      where: {
        driverId: userId, // Use userId, not driver.id
        status: {
          in: ['planned', 'assigned', 'in_progress']
        }
      },
      select: {
        id: true,
        reference: true,
        driverId: true,
        vehicleId: true,
        startTime: true,
        endTime: true,
        optimizedDistanceKm: true,
        actualDistanceKm: true,
        totalOutcome: true,
        estimatedDuration: true,
        actualDuration: true,
        status: true,
        completedDrops: true,
        routeNotes: true,
        performanceMultiplier: true,
        bonusesTotal: true,
        penaltiesTotal: true,
        driverPayout: true,
        drops: {
          include: {
            User: {
              select: {
                id: true,
                name: true,
                email: true
              }
            }
          }
        }
      },
      orderBy: {
        startTime: 'asc'
      }
    });

      console.log(`📊 Found ${routes.length} route(s) in database`);
      routes.forEach((r, i) => {
        console.log(`  Route ${i + 1}: ${r.id} (${r.status}, ${r.drops?.length || 0} drops)`);
      });

      return { driver, routes };
    });

    // Format routes for frontend
    const formattedRoutes = routes.map(route => {
      // Calculate totals from drops
      const totalDistance = route.optimizedDistanceKm || route.actualDistanceKm || 
        route.drops.reduce((sum, drop) => sum + (drop.distance || 0), 0);
      
      const totalEarnings = route.driverPayout || route.totalOutcome || 
        route.drops.reduce((sum, drop) => {
          const price = Number(drop.quotedPrice || 0);
          return (Number.isFinite(price) && price >= 0 && price <= Number.MAX_SAFE_INTEGER) ? sum + price : sum;
        }, 0);

      // Format drops
      const drops = route.drops.map(drop => ({
        id: drop.id,
        customerName: drop.User?.name || 'Unknown',
        deliveryAddress: drop.deliveryAddress,
        pickupAddress: drop.pickupAddress,
        timeWindowStart: drop.timeWindowStart.toISOString(),
        timeWindowEnd: drop.timeWindowEnd.toISOString(),
        status: drop.status,
        serviceTier: drop.serviceTier,
        specialInstructions: drop.specialInstructions,
        quotedPrice: Number(drop.quotedPrice),
        weight: drop.weight,
        volume: drop.volume,
        distance: drop.distance
      }));

      return {
        id: route.id,
        reference: route.reference || route.id, // Use unified SV reference
        status: route.status,
        drops: drops,
        estimatedDuration: route.estimatedDuration || 
          Math.round((route.drops.length * 30) + (totalDistance * 2.5)), // 30 min per drop + travel time
        estimatedDistance: totalDistance,
        estimatedEarnings: Number(totalEarnings),
        startTime: route.startTime.toISOString(),
        endTime: route.endTime?.toISOString(),
        totalWorkers: 1, // Default, can be enhanced
        hasCameras: false, // Default, can be enhanced from vehicle data
        completedDrops: route.completedDrops,
        routeNotes: route.routeNotes,
        performanceMultiplier: route.performanceMultiplier,
        bonusesTotal: Number(route.bonusesTotal),
        penaltiesTotal: Number(route.penaltiesTotal)
      };
    });

    const duration = Date.now() - startTime;
    console.log(`✅ Driver Routes API - Completed in ${duration}ms`);
    console.log(`📊 Returning ${formattedRoutes.length} routes`);

    return NextResponse.json({
      success: true,
      routes: formattedRoutes,
      totalRoutes: formattedRoutes.length
    }, { headers: corsHeaders });

  } catch (error) {
    const duration = Date.now() - startTime;
    console.error(`❌ Driver Routes API - Failed after ${duration}ms`);
    console.error('Error details:', error);
    console.error('Error stack:', error instanceof Error ? error.stack : 'No stack');
    
    return NextResponse.json(
      { 
        success: false,
        routes: [],
        totalRoutes: 0,
        error: 'Failed to fetch routes', 
        details: error instanceof Error ? error.message : 'Unknown error'
      },
      { status: 500, headers: corsHeaders }
    );
  }
}

import { NextResponse, NextRequest } from 'next/server';
import { auth } from '@/lib/auth';
import { assertDriver } from '@/lib/guards';
import { format } from 'date-fns';
import { prisma } from '@/lib/prisma';

export const dynamic = 'force-dynamic';

export async function GET(request: NextRequest) {
  const session = await auth();
  try {
    assertDriver(session!);
  } catch (e) {
    const msg = (e as Error).message;
    const status = msg === 'UNAUTHORIZED' ? 401 : 403;
    return new Response(msg, { status });
  }

  const { searchParams } = new URL(request.url);
  const startDate = searchParams.get('start') || new Date().toISOString();
  const endDate =
    searchParams.get('end') ||
    new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString(); // 30 days from now

  const userId = session.user.id;

  try {
    const driver = await prisma.driver.findUnique({
      where: { userId },
      include: {
        DriverShift: {
          where: { isActive: true },
          orderBy: { startTime: 'asc' },
        },
        Assignment: {
          where: {
            status: { in: ['accepted'] },
          },
          include: {
            Booking: {
              select: {
                id: true,
                reference: true,
                pickupAddress: true,
                dropoffAddress: true,
                scheduledAt: true,
                totalGBP: true,
                status: true,
              },
            },
          },
          orderBy: { createdAt: 'asc' },
        },
      },
    });

    if (!driver) {
      return NextResponse.json({ error: 'Driver not found' }, { status: 404 });
    }

    // Generate ICS content
    let icsContent = [
      'BEGIN:VCALENDAR',
      'VERSION:2.0',
      'PRODID:-//Speedy Van//Driver Schedule//EN',
      'CALSCALE:GREGORIAN',
      'METHOD:PUBLISH',
    ];

    // Add shifts
    driver.DriverShift.forEach((shift, index) => {
      const start = format(new Date(shift.startTime), "yyyyMMdd'T'HHmmss");
      const end = format(new Date(shift.endTime), "yyyyMMdd'T'HHmmss");
      const created = format(new Date(shift.createdAt), "yyyyMMdd'T'HHmmss");

      icsContent.push(
        'BEGIN:VEVENT',
        `UID:shift-${shift.id}@speedy-van.co.uk`,
        `DTSTAMP:${created}`,
        `DTSTART:${start}`,
        `DTEND:${end}`,
        `SUMMARY:Scheduled Shift`,
        `DESCRIPTION:${shift.isRecurring ? 'Recurring shift' : 'One-time shift'}`,
        `STATUS:CONFIRMED`,
        'END:VEVENT'
      );
    });

    // Add jobs
    driver.Assignment.forEach((assignment, index) => {
      if (!assignment.Booking.scheduledAt) return;

      const start = format(
        new Date(assignment.Booking.scheduledAt),
        "yyyyMMdd'T'HHmmss"
      );
      const end = format(
        new Date(assignment.Booking.scheduledAt.getTime() + 2 * 60 * 60 * 1000),
        "yyyyMMdd'T'HHmmss"
      ); // 2 hours duration
      const created = format(
        new Date(assignment.createdAt),
        "yyyyMMdd'T'HHmmss"
      );

      const description = [
        `Job #${assignment.Booking.reference}`,
        `Pickup: ${assignment.Booking.pickupAddress || 'TBD'}`,
        `Dropoff: ${assignment.Booking.dropoffAddress || 'TBD'}`,
        `Amount: £${(assignment.Booking.totalGBP / 100).toFixed(2)}`,
        `Status: ${assignment.status}`,
      ].join('\\n');

      icsContent.push(
        'BEGIN:VEVENT',
        `UID:job-${assignment.id}@speedy-van.co.uk`,
        `DTSTAMP:${created}`,
        `DTSTART:${start}`,
        `DTEND:${end}`,
        `SUMMARY:Job #${assignment.Booking.reference}`,
        `DESCRIPTION:${description}`,
        `STATUS:CONFIRMED`,
        'END:VEVENT'
      );
    });

    icsContent.push('END:VCALENDAR');

    const icsString = icsContent.join('\r\n');

    return new Response(icsString, {
      headers: {
        'Content-Type': 'text/calendar',
        'Content-Disposition': `attachment; filename="driver-schedule-${format(new Date(), 'yyyy-MM-dd')}.ics"`,
      },
    });
  } catch (error) {
    console.error('Schedule export error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';

export const dynamic = 'force-dynamic';

export async function GET(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user?.id) {
      return NextResponse.json(
        { error: 'Unauthorized' },
        { status: 401 }
      );
    }

    const driverId = session.user.id;
    const now = new Date();

    // Get upcoming jobs (next 30 days)
    const upcomingJobs = await prisma.booking.findMany({
      where: {
        driverId,
        scheduledAt: {
          gte: now,
        },
        status: {
          in: ['CONFIRMED'],
        },
      },
      select: {
        id: true,
        reference: true,
        scheduledAt: true,
        status: true,
        customerName: true,
        customerPhone: true,
        pickupAddress: {
          select: {
            label: true,
            postcode: true,
          },
        },
        dropoffAddress: {
          select: {
            label: true,
            postcode: true,
          },
        },
        BookingItem: {
          select: {
            name: true,
            quantity: true,
          },
        },
        totalGBP: true,
        estimatedDurationMinutes: true,
        urgency: true,
      },
      orderBy: {
        scheduledAt: 'asc',
      },
      take: 20, // Limit to 20 upcoming jobs
    });

    // Get past jobs (last 30 days, completed and declined)
    const thirtyDaysAgo = new Date();
    thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);

    const pastJobs = await prisma.booking.findMany({
      where: {
        driverId,
        scheduledAt: {
          gte: thirtyDaysAgo,
          lt: now,
        },
        status: {
          in: ['COMPLETED', 'CANCELLED'],
        },
      },
      select: {
        id: true,
        reference: true,
        scheduledAt: true,
        status: true,
        customerName: true,
        customerPhone: true,
        pickupAddress: {
          select: {
            label: true,
            postcode: true,
          },
        },
        dropoffAddress: {
          select: {
            label: true,
            postcode: true,
          },
        },
        BookingItem: {
          select: {
            name: true,
            quantity: true,
          },
        },
        totalGBP: true,
        estimatedDurationMinutes: true,
        urgency: true,
      },
      orderBy: {
        scheduledAt: 'desc',
      },
      take: 20, // Limit to 20 past jobs
    });

    // Get declined assignments with details
    const declinedAssignments = await prisma.assignment.findMany({
      where: {
        driverId,
        status: 'declined',
        createdAt: {
          gte: thirtyDaysAgo,
        },
      },
      include: {
        Booking: {
          select: {
            id: true,
            reference: true,
            scheduledAt: true,
            customerName: true,
            customerPhone: true,
            pickupAddress: {
              select: {
                label: true,
                postcode: true,
              },
            },
            dropoffAddress: {
              select: {
                label: true,
                postcode: true,
              },
            },
            BookingItem: {
              select: {
                name: true,
                quantity: true,
              },
            },
            totalGBP: true,
            estimatedDurationMinutes: true,
            urgency: true,
          },
        },
      },
      orderBy: {
        createdAt: 'desc',
      },
      take: 10, // Limit to 10 declined jobs
    });

    const formatJob = (booking: any) => ({
      id: booking.id,
      reference: booking.reference,
      scheduledAt: booking.scheduledAt.toISOString(),
      status: booking.status.toLowerCase(),
      customerName: booking.customerName || 'Customer',
      customerPhone: booking.customerPhone || '',
      pickupAddress: booking.pickupAddress?.label || 'Pickup Location',
      dropoffAddress: booking.dropoffAddress?.label || 'Dropoff Location',
      items: booking.BookingItem || [],
      // Hide customer payment amount from driver
      // Driver will see their earnings separately
      duration: booking.estimatedDurationMinutes || 60,
      priority: booking.urgency || 'medium',
    });

    const formatDeclinedJob = (assignment: any) => ({
      id: assignment.bookingId,
      reference: assignment.Booking.reference,
      scheduledAt: assignment.Booking.scheduledAt.toISOString(),
      declinedAt: assignment.createdAt.toISOString(),
      customerName: assignment.Booking.customerName || 'Customer',
      customerPhone: assignment.Booking.customerPhone || '',
      pickupAddress: assignment.Booking.pickupAddress?.label || 'Pickup Location',
      dropoffAddress: assignment.Booking.dropoffAddress?.label || 'Dropoff Location',
      items: assignment.Booking.BookingItem || [],
      // Hide customer payment amount from driver
      // Driver will see their earnings separately
      duration: assignment.Booking.estimatedDurationMinutes || 60,
      priority: assignment.Booking.urgency || 'medium',
      reason: assignment.declinedReason || 'No reason provided',
    });

    return NextResponse.json({
      success: true,
      data: {
        upcoming: upcomingJobs.map(formatJob),
        past: pastJobs.map(formatJob),
        declined: declinedAssignments.map(formatDeclinedJob),
      },
    });

  } catch (error) {
    console.error('Driver schedule jobs error:', error);
    return NextResponse.json(
      {
        success: false,
        error: error instanceof Error ? error.message : 'Internal server error'
      },
      { status: 500 }
    );
  }
}

import { NextResponse, NextRequest } from 'next/server';
import { auth } from '@/lib/auth';
import { assertDriver } from '@/lib/guards';
import { authenticateBearerToken } from '@/lib/bearer-auth';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import {
  startOfMonth,
  endOfMonth,
  startOfWeek,
  endOfWeek,
  addDays,
  format,
} from 'date-fns';
import { prisma } from '@/lib/prisma';

export const dynamic = 'force-dynamic';

export async function GET(request: NextRequest) {
  try {
    console.log('📅 Driver Schedule API - Starting request');
    
    // Try Bearer token authentication first (for mobile app)
    const bearerAuth = await authenticateBearerToken(request);
    let session: any;
    
    if (bearerAuth.success) {
      session = { user: bearerAuth.user };
      console.log('🔑 Bearer token authenticated for user:', bearerAuth.user.id);
    } else {
      // Fallback to NextAuth session (for web app)
      session = await getServerSession(authOptions);
      if (!session?.user) {
        console.log('❌ Driver Schedule API - No session found');
        return NextResponse.json(
          { error: 'Unauthorized - Please login' },
          { status: 401 }
        );
      }
      console.log('🌐 NextAuth session authenticated for user:', session.user.id);
    }

    try {
      assertDriver(session);
    } catch (e) {
      const msg = (e as Error).message;
      const status = msg === 'UNAUTHORIZED' ? 401 : 403;
      console.log('❌ Driver Schedule API - Auth failed:', msg);
      return NextResponse.json({ error: msg }, { status });
    }

    const { searchParams } = new URL(request.url);
    const view = searchParams.get('view') || 'month'; // month, week, day
    const date = searchParams.get('date') || new Date().toISOString();

    const userId = session.user.id;

    const driver = await prisma.driver.findUnique({
      where: { userId },
      include: {
        DriverShift: {
          where: { isActive: true },
          orderBy: { startTime: 'asc' },
        },
        Assignment: {
          where: {
            status: { in: ['accepted'] },
          },
          include: {
            Booking: {
              select: {
                id: true,
                reference: true,
                pickupAddress: true,
                dropoffAddress: true,
                scheduledAt: true,
                totalGBP: true,
                status: true,
              },
            },
          },
          orderBy: { createdAt: 'asc' },
        },
      },
    });

    if (!driver) {
      return NextResponse.json({ error: 'Driver not found' }, { status: 404 });
    }

    // Calculate date range based on view
    const targetDate = new Date(date);
    let startDate: Date;
    let endDate: Date;

    switch (view) {
      case 'week':
        startDate = startOfWeek(targetDate, { weekStartsOn: 1 }); // Monday start
        endDate = endOfWeek(targetDate, { weekStartsOn: 1 });
        break;
      case 'day':
        startDate = targetDate;
        endDate = addDays(targetDate, 1);
        break;
      default: // month
        startDate = startOfMonth(targetDate);
        endDate = endOfMonth(targetDate);
    }

    // Get upcoming jobs in the date range
    const upcomingJobs = driver.Assignment.filter(assignment => {
      const jobDate = assignment.Booking.scheduledAt;
      return jobDate && jobDate >= startDate && jobDate <= endDate;
    }).map(assignment => ({
      id: assignment.id,
      bookingId: assignment.Booking.id, // ✅ Add booking ID for mobile navigation
      type: 'job',
      title: `Job #${assignment.Booking.reference}`,
      reference: assignment.Booking.reference, // ✅ Add reference
      start: assignment.Booking.scheduledAt,
      end: assignment.Booking.scheduledAt
        ? addDays(assignment.Booking.scheduledAt, 1)
        : null,
      pickup: assignment.Booking.pickupAddress,
      dropoff: assignment.Booking.dropoffAddress,
      amount: assignment.Booking.totalGBP,
      status: assignment.status,
      bookingStatus: assignment.Booking.status, // ✅ Add booking status
    }));

    // Get shifts in the date range
    const shifts = driver.DriverShift
      .filter(shift => {
        // For recurring shifts, check if they fall in the date range
        if (shift.isRecurring) {
          const dayNames = [
            'sunday',
            'monday',
            'tuesday',
            'wednesday',
            'thursday',
            'friday',
            'saturday',
          ];
          const currentDate = new Date(startDate);

          while (currentDate <= endDate) {
            const dayName = dayNames[currentDate.getDay()];
            if (shift.recurringDays.includes(dayName)) {
              return true;
            }
            currentDate.setDate(currentDate.getDate() + 1);
          }
          return false;
        } else {
          return shift.startTime >= startDate && shift.startTime <= endDate;
        }
      })
      .map(shift => ({
        id: shift.id,
        type: 'shift',
        title: 'Scheduled Shift',
        start: shift.startTime,
        end: shift.endTime,
        isRecurring: shift.isRecurring,
        recurringDays: shift.recurringDays,
      }));

    // Generate calendar events for recurring shifts
    const recurringShiftEvents = shifts
      .filter(shift => shift.isRecurring)
      .flatMap(shift => {
        const events = [];
        const dayNames = [
          'sunday',
          'monday',
          'tuesday',
          'wednesday',
          'thursday',
          'friday',
          'saturday',
        ];
        const currentDate = new Date(startDate);

        while (currentDate <= endDate) {
          const dayName = dayNames[currentDate.getDay()];
          if (shift.recurringDays.includes(dayName)) {
            const startTime = new Date(shift.start);
            const endTime = new Date(shift.end);

            const eventStart = new Date(currentDate);
            eventStart.setHours(
              startTime.getHours(),
              startTime.getMinutes(),
              0,
              0
            );

            const eventEnd = new Date(currentDate);
            eventEnd.setHours(endTime.getHours(), endTime.getMinutes(), 0, 0);

            events.push({
              ...shift,
              start: eventStart,
              end: eventEnd,
              isRecurringInstance: true,
            });
          }
          currentDate.setDate(currentDate.getDate() + 1);
        }
        return events;
      });

    // Combine all events
    const allEvents = [
      ...upcomingJobs,
      ...shifts.filter(shift => !shift.isRecurring),
      ...recurringShiftEvents,
    ].sort((a, b) => {
      const aStart = a.start ? new Date(a.start).getTime() : 0;
      const bStart = b.start ? new Date(b.start).getTime() : 0;
      return aStart - bStart;
    });

    // Check for conflicts (overlapping events)
    const conflicts = [];
    for (let i = 0; i < allEvents.length; i++) {
      for (let j = i + 1; j < allEvents.length; j++) {
        const event1 = allEvents[i];
        const event2 = allEvents[j];

        if (
          event1.start &&
          event2.start &&
          event1.end &&
          event2.end &&
          event1.start < event2.end &&
          event2.start < event1.end
        ) {
          conflicts.push({
            event1: event1.title,
            event2: event2.title,
            overlap: {
              start: new Date(
                Math.max(event1.start.getTime(), event2.start.getTime())
              ),
              end: new Date(
                Math.min(event1.end.getTime(), event2.end.getTime())
              ),
            },
          });
        }
      }
    }

    return NextResponse.json({
      events: allEvents,
      conflicts,
      dateRange: {
        start: startDate,
        end: endDate,
        view,
      },
      summary: {
        totalJobs: upcomingJobs.length,
        totalShifts: shifts.length,
        conflicts: conflicts.length,
      },
    });
  } catch (error) {
    console.error('❌ Driver Schedule API - Error:', error);
    return NextResponse.json(
      { error: 'Failed to load schedule' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';

export const dynamic = 'force-dynamic';

export async function GET(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user?.id) {
      return NextResponse.json(
        { error: 'Unauthorized' },
        { status: 401 }
      );
    }

    const driverId = session.user.id;

    // Get current date and week boundaries
    const now = new Date();
    const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    const weekStart = new Date(today);
    weekStart.setDate(today.getDate() - today.getDay()); // Start of week (Sunday)
    const weekEnd = new Date(weekStart);
    weekEnd.setDate(weekStart.getDate() + 6); // End of week (Saturday)

    // Get today's jobs count
    const todayJobs = await prisma.assignment.count({
      where: {
        driverId,
        Booking: {
          scheduledAt: {
            gte: today,
            lt: new Date(today.getTime() + 24 * 60 * 60 * 1000),
          },
          status: {
            in: ['CONFIRMED'],
          },
        },
      },
    });

    // Get this week's jobs count
    const weekJobs = await prisma.assignment.count({
      where: {
        driverId,
        Booking: {
          scheduledAt: {
            gte: weekStart,
            lte: weekEnd,
          },
          status: {
            in: ['CONFIRMED', 'COMPLETED'],
          },
        },
      },
    });

    // Get total earnings this week
    const weekEarnings = await prisma.booking.aggregate({
      _sum: {
        totalGBP: true,
      },
      where: {
        driverId,
        scheduledAt: {
          gte: weekStart,
          lte: weekEnd,
        },
        status: 'COMPLETED',
      },
    });

    // Get next upcoming job
    const nextJob = await prisma.booking.findFirst({
      where: {
        driverId,
        scheduledAt: {
          gte: now,
        },
        status: {
          in: ['CONFIRMED'],
        },
      },
      select: {
        id: true,
        reference: true,
        scheduledAt: true,
        status: true,
        customerName: true,
        customerPhone: true,
        pickupAddress: {
          select: {
            label: true,
          },
        },
        dropoffAddress: {
          select: {
            label: true,
          },
        },
        BookingItem: {
          select: {
            name: true,
            quantity: true,
          },
        },
        totalGBP: true,
        estimatedDurationMinutes: true,
        urgency: true,
      },
      orderBy: {
        scheduledAt: 'asc',
      },
    });

    // Get declined jobs count (last 30 days)
    const thirtyDaysAgo = new Date();
    thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);

    const declinedJobsCount = await prisma.assignment.count({
      where: {
        driverId,
        status: 'declined',
        createdAt: {
          gte: thirtyDaysAgo,
        },
      },
    });

    // Get total assignments (accepted + declined) for acceptance rate calculation
    const totalAssignments = await prisma.assignment.count({
      where: {
        driverId,
        createdAt: {
          gte: thirtyDaysAgo,
        },
      },
    });

    // Calculate acceptance rate (accepted assignments / total assignments)
    const acceptedAssignments = totalAssignments - declinedJobsCount;
    const acceptanceRate = totalAssignments > 0 ? (acceptedAssignments / totalAssignments) * 100 : 100;

    const scheduleStats = {
      todayJobs,
      weekJobs,
      totalEarnings: weekEarnings._sum.totalGBP || 0,
      declinedJobsCount,
      acceptanceRate,
      nextJob: nextJob ? {
        id: nextJob.id,
        reference: nextJob.reference,
        scheduledAt: nextJob.scheduledAt.toISOString(),
        status: nextJob.status.toLowerCase(),
        customerName: nextJob.customerName || 'Customer',
        customerPhone: nextJob.customerPhone || '',
        pickupAddress: nextJob.pickupAddress?.label || 'Pickup Location',
        dropoffAddress: nextJob.dropoffAddress?.label || 'Dropoff Location',
        items: nextJob.BookingItem || [],
        // Hide customer payment amount from driver
        // Driver will see their earnings separately
        duration: nextJob.estimatedDurationMinutes || 60,
        priority: nextJob.urgency || 'medium',
      } : null,
    };

    return NextResponse.json({
      success: true,
      data: scheduleStats,
    });

  } catch (error) {
    console.error('Driver schedule stats error:', error);
    return NextResponse.json(
      {
        success: false,
        error: error instanceof Error ? error.message : 'Internal server error'
      },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
import { generateTOTPSecret, verifyTOTP } from '@/lib/totp';

// Force dynamic rendering (uses headers/cookies/getServerSession)
export const dynamic = 'force-dynamic';

export async function GET(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user?.id) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const driver = await prisma.driver.findUnique({
      where: { userId: session.user.id },
      include: { 
        User: {
          select: {
            id: true,
            name: true,
            email: true,
            role: true,
            createdAt: true,
            isActive: true,
            twoFactorSecret: true,
            backupCodesGenerated: true,
            backupCodes: true
          }
        }
      },
    });

    if (!driver) {
      return NextResponse.json({ error: 'Driver not found' }, { status: 404 });
    }

    // Check if 2FA is already enabled
    const is2FAEnabled = driver.User.twoFactorSecret !== null;

    if (is2FAEnabled) {
      return NextResponse.json({
        enabled: true,
        backupCodesGenerated: driver.User.backupCodesGenerated || false,
      });
    }

    // Generate new secret for setup
    const secret = generateTOTPSecret();
    const qrCodeUrl = `otpauth://totp/SpeedyVan:${driver.User.email}?secret=${secret}&issuer=SpeedyVan`;

    return NextResponse.json({
      enabled: false,
      secret,
      qrCodeUrl,
    });
  } catch (error) {
    console.error('2FA GET error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user?.id) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const { action, token, secret } = await request.json();

    const driver = await prisma.driver.findUnique({
      where: { userId: session.user.id },
      include: { 
        User: {
          select: {
            id: true,
            name: true,
            email: true,
            role: true,
            createdAt: true,
            isActive: true,
            twoFactorSecret: true,
            backupCodesGenerated: true,
            backupCodes: true
          }
        }
      },
    });

    if (!driver) {
      return NextResponse.json({ error: 'Driver not found' }, { status: 404 });
    }

    switch (action) {
      case 'enable':
        if (!token || !secret) {
          return NextResponse.json(
            { error: 'Token and secret required' },
            { status: 400 }
          );
        }

        // Verify the TOTP token
        const isValid = verifyTOTP(secret, token);
        if (!isValid) {
          return NextResponse.json({ error: 'Invalid token' }, { status: 400 });
        }

        // Generate backup codes
        const backupCodes = Array.from({ length: 10 }, () =>
          Math.random().toString(36).substring(2, 8).toUpperCase()
        );

        // Enable 2FA
        await prisma.user.update({
          where: { id: session.user.id },
          data: {
            twoFactorSecret: secret,
            backupCodes: backupCodes,
            backupCodesGenerated: true,
          },
        });

        return NextResponse.json({
          success: true,
          backupCodes,
          message: '2FA enabled successfully',
        });

      case 'disable':
        if (!token) {
          return NextResponse.json(
            { error: 'Token required' },
            { status: 400 }
          );
        }

        // Verify current 2FA token or backup code
        const currentSecret = driver.User.twoFactorSecret;
        if (!currentSecret) {
          return NextResponse.json(
            { error: '2FA not enabled' },
            { status: 400 }
          );
        }

        const isValidToken =
          verifyTOTP(currentSecret, token) ||
          driver.User.backupCodes?.includes(token);

        if (!isValidToken) {
          return NextResponse.json({ error: 'Invalid token' }, { status: 400 });
        }

        // Disable 2FA
        await prisma.user.update({
          where: { id: session.user.id },
          data: {
            twoFactorSecret: null,
            backupCodes: undefined,
            backupCodesGenerated: false,
          },
        });

        return NextResponse.json({
          success: true,
          message: '2FA disabled successfully',
        });

      case 'regenerate-backup-codes':
        if (!token) {
          return NextResponse.json(
            { error: 'Token required' },
            { status: 400 }
          );
        }

        const secretForBackup = driver.User.twoFactorSecret;
        if (!secretForBackup) {
          return NextResponse.json(
            { error: '2FA not enabled' },
            { status: 400 }
          );
        }

        const isValidBackupToken =
          verifyTOTP(secretForBackup, token) ||
          driver.User.backupCodes?.includes(token);

        if (!isValidBackupToken) {
          return NextResponse.json({ error: 'Invalid token' }, { status: 400 });
        }

        // Generate new backup codes
        const newBackupCodes = Array.from({ length: 10 }, () =>
          Math.random().toString(36).substring(2, 8).toUpperCase()
        );

        await prisma.user.update({
          where: { id: session.user.id },
          data: {
            backupCodes: newBackupCodes,
          },
        });

        return NextResponse.json({
          success: true,
          backupCodes: newBackupCodes,
          message: 'Backup codes regenerated successfully',
        });

      default:
        return NextResponse.json({ error: 'Invalid action' }, { status: 400 });
    }
  } catch (error) {
    console.error('2FA POST error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

