        status: driver.DriverAvailability?.status || 'offline',
        locationConsent: driver.DriverAvailability?.locationConsent || false,
        lastSeenAt: driver.DriverAvailability?.lastSeenAt,
      },
      notifications: notificationPreferences,
      vehicle: vehicle || {
        make: '',
        model: '',
        reg: '',
        weightClass: '',
