  }
}

export async function POST(request: NextRequest) {
  const session = await auth();
  try {
    assertDriver(session!);
  } catch (e) {
    const msg = (e as Error).message;
    const status = msg === 'UNAUTHORIZED' ? 401 : 403;
    return new Response(msg, { status });
  }

  const userId = session.user.id;

  try {
    const { startTime, endTime, isRecurring, recurringDays } =
      await request.json();

    // Validate required fields
    if (!startTime || !endTime) {
      return NextResponse.json(
        { error: 'Start time and end time are required' },
        { status: 400 }
      );
    }

    // Validate time format
    const start = new Date(startTime);
    const end = new Date(endTime);

    if (isNaN(start.getTime()) || isNaN(end.getTime())) {
      return NextResponse.json(
        { error: 'Invalid date format' },
        { status: 400 }
      );
    }

    if (start >= end) {
      return NextResponse.json(
        { error: 'End time must be after start time' },
        { status: 400 }
      );
    }

    // Validate recurring days if recurring shift
    if (
      isRecurring &&
      (!recurringDays ||
        !Array.isArray(recurringDays) ||
        recurringDays.length === 0)
    ) {
      return NextResponse.json(
        { error: 'Recurring days are required for recurring shifts' },
        { status: 400 }
      );
    }

    const userId = session.user.id;

    const driver = await prisma.driver.findUnique({
      where: { userId },
    });

    if (!driver) {
      return NextResponse.json({ error: 'Driver not found' }, { status: 404 });
    }

    const shift = await prisma.driverShift.create({
      data: {
        driverId: driver.id,
        startTime: start,
        endTime: end,
        isRecurring: isRecurring || false,
        recurringDays: recurringDays || [],
        isActive: true,
      },
    });

    return NextResponse.json({
      success: true,
      shift,
    });
  } catch (error) {
    console.error('Shifts POST error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { authenticateBearerToken } from '@/lib/bearer-auth';
import { prisma } from '@/lib/prisma';

export const dynamic = 'force-dynamic';
export const maxDuration = 10;

// CORS headers
const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
  'Access-Control-Allow-Headers': 'Content-Type, Authorization',
};

export async function OPTIONS() {
  return NextResponse.json({}, { headers: corsHeaders });
}

export async function POST(request: NextRequest) {
  try {
    console.log('🔄 Driver Status API - Starting request');

    // Try Bearer token authentication first (for mobile app)
    const bearerAuth = await authenticateBearerToken(request);
    let userId: string;

    if (bearerAuth.success) {
      userId = bearerAuth.user.id;
      if (bearerAuth.user.role !== 'driver') {
        return NextResponse.json(
          { error: 'Forbidden - Driver access required' },
          { status: 403, headers: corsHeaders }
        );
      }
      console.log('🔑 Bearer token authenticated for user:', userId);
    } else {
      // Fallback to NextAuth session
      const session = await getServerSession(authOptions);
      if (!session?.user || (session.user as any)?.role !== 'driver') {
        return NextResponse.json(
          { error: 'Unauthorized - Please login' },
          { status: 401, headers: corsHeaders }
        );
      }
      userId = session.user.id;
      console.log('🌐 NextAuth session authenticated for user:', userId);
    }

    // Parse request body
    const body = await request.json();
    const { status } = body;

    // Validate status
    if (!status || !['online', 'offline'].includes(status)) {
      return NextResponse.json(
        { error: 'Invalid status. Must be "online" or "offline"' },
        { status: 400, headers: corsHeaders }
      );
    }

    // Get driver record
    const driver = await prisma.driver.findUnique({
      where: { userId },
      select: { id: true, status: true },
    });

    if (!driver) {
      return NextResponse.json(
        { error: 'Driver profile not found' },
        { status: 404, headers: corsHeaders }
      );
    }

    console.log(`🔄 Updating driver ${driver.id} to ${status}`);

    // ✅ CRITICAL FIX: Update DriverAvailability table (not just Driver.updatedAt)
    const updatedAvailability = await prisma.driverAvailability.upsert({
      where: { driverId: driver.id },
      create: {
        driverId: driver.id,
        status: status,
        locationConsent: status === 'online', // Auto-enable location when online
        lastSeenAt: new Date(),
        createdAt: new Date(),
        updatedAt: new Date(),
      },
      update: {
        status: status,
        locationConsent: status === 'online' ? true : false, // ✅ Explicit false when offline
        lastSeenAt: new Date(),
        updatedAt: new Date(),
      },
    });

    console.log(`✅ Driver ${driver.id} availability updated to ${status}`);

    // ✅ Send Pusher notification to admin dashboard
    try {
      const { default: Pusher } = await import('pusher');
      const pusher = new Pusher({
        appId: process.env.PUSHER_APP_ID!,
        key: process.env.PUSHER_KEY!,
        secret: process.env.PUSHER_SECRET!,
        cluster: process.env.PUSHER_CLUSTER!,
        useTLS: true,
      });

      await pusher.trigger('admin-notifications', 'driver-status-changed', {
        driverId: driver.id,
        status: status,
        timestamp: new Date().toISOString(),
      });

      console.log('✅ Pusher notification sent to admin dashboard');
    } catch (pusherError) {
      console.error('⚠️ Failed to send Pusher notification:', pusherError);
      // Don't fail the request if Pusher fails
    }

    // ✅ If driver went online, trigger job matching
    if (status === 'online') {
      console.log('🔍 Driver went online - will auto-refresh available jobs');
      
      // You can add background job matching here or trigger via queue
      // For now, the dashboard will refresh and show available jobs
    }

    return NextResponse.json(
      {
        success: true,
        message: `Driver is now ${status}`,
        data: {
          driverId: driver.id,
          status: status,
          locationConsent: updatedAvailability.locationConsent,
          lastSeenAt: updatedAvailability.lastSeenAt.toISOString(),
        },
      },
      { headers: corsHeaders }
    );
  } catch (error: any) {
    console.error('❌ Driver Status API Error:', error);
    return NextResponse.json(
      { error: error.message || 'Failed to update driver status' },
      { status: 500, headers: corsHeaders }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';

// Force dynamic rendering (uses headers/cookies/getServerSession)
export const dynamic = 'force-dynamic';

export async function GET(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user?.id || session.user.role !== 'driver') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const { searchParams } = new URL(request.url);
    const page = parseInt(searchParams.get('page') || '1');
    const limit = parseInt(searchParams.get('limit') || '20');
    const status = searchParams.get('status');

    // Get driver
    const driver = await prisma.driver.findUnique({
      where: { userId: session.user.id },
    });

    if (!driver) {
      return NextResponse.json({ error: 'Driver not found' }, { status: 404 });
    }

    // Build where clause
    const where: any = { driverId: driver.id };
    if (status) {
      where.status = status;
    }

    // Get tips with pagination
    const [tips, total] = await Promise.all([
      prisma.driverTip.findMany({
        where,
        include: {
          Assignment: {
            include: {
              Booking: {
                select: {
                  reference: true,
                  pickupAddress: true,
                  dropoffAddress: true,
                },
              },
            },
          },
        },
        orderBy: {
          createdAt: 'desc',
        },
        skip: (page - 1) * limit,
        take: limit,
      }),
      prisma.driverTip.count({ where }),
    ]);

    // Calculate totals by status
    const statusTotals = await prisma.driverTip.groupBy({
      by: ['status'],
      where: { driverId: driver.id },
      _sum: {
        amountPence: true,
      },
      _count: true,
    });

    const totals = statusTotals.reduce(
      (acc, item) => ({
        ...acc,
        [item.status]: {
          amount: item._sum.amountPence || 0,
          count: item._count,
        },
      }),
      {}
    );

    return NextResponse.json({
      tips: tips.map(tip => ({
        id: tip.id,
        assignmentId: tip.assignmentId,
        bookingCode: tip.Assignment.Booking.reference,
        pickupAddress: tip.Assignment.Booking.pickupAddress,
        dropoffAddress: tip.Assignment.Booking.dropoffAddress,
        amountPence: tip.amountPence,
        currency: tip.currency,
        method: tip.method,
        reference: tip.reference,
        status: tip.status,
        reconciledAt: tip.reconciledAt,
        reconciledBy: tip.reconciledBy,
        notes: tip.notes,
        createdAt: tip.createdAt,
        updatedAt: tip.updatedAt,
      })),
      pagination: {
        page,
        limit,
        total,
        pages: Math.ceil(total / limit),
      },
      totals,
    });
  } catch (error) {
    console.error('Error fetching tips:', error);
    return NextResponse.json(
      { error: 'Failed to fetch tips' },
      { status: 500 }
    );
  }
}

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user?.id || session.user.role !== 'driver') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const body = await request.json();
    const { assignmentId, amountPence, method, reference, notes } = body;

    // Get driver
    const driver = await prisma.driver.findUnique({
      where: { userId: session.user.id },
    });

    if (!driver) {
      return NextResponse.json({ error: 'Driver not found' }, { status: 404 });
    }

    // Validate inputs
    if (!assignmentId) {
      return NextResponse.json(
        { error: 'Assignment ID is required' },
        { status: 400 }
      );
    }

    if (!amountPence || amountPence <= 0) {
      return NextResponse.json(
        { error: 'Valid tip amount is required' },
        { status: 400 }
      );
    }

    if (!method) {
      return NextResponse.json(
        { error: 'Tip method is required' },
        { status: 400 }
      );
    }

    // Verify assignment belongs to driver
    const assignment = await prisma.assignment.findFirst({
      where: {
        id: assignmentId,
        driverId: driver.id,
      },
    });

    if (!assignment) {
      return NextResponse.json(
        { error: 'Assignment not found or not authorized' },
        { status: 404 }
      );
    }

    // Check if tip already exists for this assignment
    const existingTip = await prisma.driverTip.findFirst({
      where: {
        assignmentId,
        driverId: driver.id,
      },
    });

    if (existingTip) {
      return NextResponse.json(
        { error: 'Tip already recorded for this assignment' },
        { status: 409 }
      );
    }

    // Create tip
    const tip = await prisma.driverTip.create({
      data: {
        driverId: driver.id,
        assignmentId,
        amountPence,
        method,
        reference,
        notes,
        status: 'pending',
      },
      include: {
        Assignment: {
          include: {
            Booking: {
              select: {
                reference: true,
                pickupAddress: true,
                dropoffAddress: true,
              },
            },
          },
        },
      },
    });

    return NextResponse.json({
      id: tip.id,
      assignmentId: tip.assignmentId,
      bookingCode: tip.Assignment.Booking.reference,
      amountPence: tip.amountPence,
      currency: tip.currency,
      method: tip.method,
      reference: tip.reference,
      status: tip.status,
      notes: tip.notes,
      createdAt: tip.createdAt,
    });
  } catch (error) {
    console.error('Error creating tip:', error);
    return NextResponse.json(
      { error: 'Failed to create tip' },
      { status: 500 }
    );
  }
}

import { NextResponse, NextRequest } from 'next/server';
import { auth } from '@/lib/auth';
import { assertDriver } from '@/lib/guards';
import { prisma } from '@/lib/prisma';

export const dynamic = 'force-dynamic';

export async function POST(request: NextRequest) {
  const session = await auth();
  try {
    assertDriver(session!);
  } catch (e) {
    const msg = (e as Error).message;
    const status = msg === 'UNAUTHORIZED' ? 401 : 403;
    return new Response(msg, { status });
  }

  const userId = session.user.id;

  try {
    const { bookingId, latitude, longitude, accuracy } = await request.json();

    // Validate location data
    if (typeof latitude !== 'number' || typeof longitude !== 'number') {
      return NextResponse.json(
        { error: 'Invalid location coordinates' },
        { status: 400 }
      );
    }

    if (
      latitude < -90 ||
      latitude > 90 ||
      longitude < -180 ||
      longitude > 180
    ) {
      return NextResponse.json(
        { error: 'Location coordinates out of valid range' },
        { status: 400 }
      );
    }

    const userId = session.user.id;

    const driver = await prisma.driver.findUnique({
      where: { userId },
      include: {
        DriverAvailability: true,
        Assignment: {
          where: {
            bookingId: bookingId,
            status: { in: ['claimed', 'accepted'] },
          },
          include: {
            Booking: true,
          },
        },
      },
    });

    if (!driver) {
      return NextResponse.json({ error: 'Driver not found' }, { status: 404 });
    }

    // Check if driver has an active assignment for this booking
    if (!driver.Assignment || driver.Assignment.length === 0) {
      return NextResponse.json(
        { error: 'No active assignment for this booking' },
        { status: 403 }
      );
    }

    // Check or create driver availability
    let driverAvailability = (driver as any).DriverAvailability;
    
    if (!driverAvailability) {
      // Create availability record if it doesn't exist
      driverAvailability = await prisma.driverAvailability.create({
        data: {
          driverId: driver.id,
          status: 'online',
          locationConsent: true, // Default to true for job tracking
          lastSeenAt: new Date(),
        },
      });
    }

    // Update availability to online if driver is tracking a job
    if (driverAvailability.status !== 'online' || !driverAvailability.locationConsent) {
      driverAvailability = await prisma.driverAvailability.update({
        where: { driverId: driver.id },
        data: {
          status: 'online',
          locationConsent: true, // Enable consent when tracking jobs
          lastSeenAt: new Date(),
        },
      });
    }

    // Create tracking ping
    const trackingPing = await prisma.trackingPing.create({
      data: {
        id: `ping_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
        bookingId: bookingId,
        driverId: driver.id,
        lat: latitude,
        lng: longitude,
      },
    });

    // Update driver availability with new location
    await prisma.driverAvailability.update({
      where: { driverId: driver.id },
      data: {
        lastLat: latitude,
        lastLng: longitude,
        lastSeenAt: new Date(),
      },
    });

    // Get booking reference for real-time notifications
    const booking = await prisma.booking.findUnique({
      where: { id: bookingId },
      select: { reference: true, customerName: true }
    });

    // Send real-time location updates to match admin and customer tracking
    try {
      const { getPusherServer } = await import('@/lib/pusher');
      const pusher = getPusherServer();

      // Notify customer tracking
      await pusher.trigger(`tracking-${booking?.reference}`, 'location-update', {
        driverId: driver.id,
        lat: latitude,
        lng: longitude,
        timestamp: new Date().toISOString(),
        accuracy: accuracy || null,
        bookingId: bookingId,
      });

      // Notify admin tracking dashboard
      await pusher.trigger('admin-tracking', 'location-update', {
        driverId: driver.id,
        bookingId: bookingId,
        bookingReference: booking?.reference,
        lat: latitude,
        lng: longitude,
        timestamp: new Date().toISOString(),
        customerName: booking?.customerName,
      });

      console.log('✅ Real-time location updates sent for tracking synchronization');
    } catch (notificationError) {
      console.error('❌ Error sending real-time location updates:', notificationError);
      // Don't fail the request if notifications fail
    }

    return NextResponse.json({
      success: true,
      trackingPingId: trackingPing.id,
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    console.error('Tracking update error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

export async function GET(request: NextRequest) {
  const session = await auth();
  try {
    assertDriver(session!);
  } catch (e) {
    const msg = (e as Error).message;
    const status = msg === 'UNAUTHORIZED' ? 401 : 403;
    return new Response(msg, { status });
  }

  const userId = session.user.id;

  try {
    const { searchParams } = new URL(request.url);
    const bookingId = searchParams.get('bookingId');
    const since = searchParams.get('since'); // ISO date string

    if (!bookingId) {
      return NextResponse.json(
        { error: 'Booking ID required' },
        { status: 400 }
      );
    }

    const userId = session.user.id;

    const driver = await prisma.driver.findUnique({
      where: { userId },
    });

    if (!driver) {
      return NextResponse.json({ error: 'Driver not found' }, { status: 404 });
    }

    // Get tracking pings for this booking
    const whereClause: any = {
      bookingId: bookingId,
      driverId: driver.id,
    };

    if (since) {
      whereClause.createdAt = {
        gte: new Date(since),
      };
    }

    const trackingPings = await prisma.trackingPing.findMany({
      where: whereClause,
      orderBy: { createdAt: 'desc' },
      take: 100, // Limit to last 100 pings
    });

    return NextResponse.json({
      success: true,
      trackingPings: trackingPings.map(ping => ({
        id: ping.id,
        lat: ping.lat,
        lng: ping.lng,
        createdAt: ping.createdAt,
      })),
    });
  } catch (error) {
    console.error('Error fetching tracking data:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

