import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { z } from 'zod';

// Validation schema for promotion code request
const validatePromotionSchema = z.object({
  code: z.string().min(1, 'Promotion code is required'),
  amount: z.number().positive('Amount must be positive'),
  customerEmail: z.string().email('Valid email is required').optional(),
  pickupPostcode: z.string().optional(),
  serviceType: z.string().optional(),
});

export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    
    // Validate request body
    const validationResult = validatePromotionSchema.safeParse(body);
    if (!validationResult.success) {
      return NextResponse.json(
        { 
          error: 'Validation failed', 
          details: validationResult.error.issues.map(issue => ({
            field: issue.path.join('.'),
            message: issue.message
          }))
        },
        { status: 400 }
      );
    }

    const { code, amount, customerEmail, pickupPostcode, serviceType } = validationResult.data;

    // Find promotion by code
    const promotion = await prisma.promotion.findUnique({
      where: { code: code.toUpperCase() },
    });

    if (!promotion) {
      return NextResponse.json(
        { 
          valid: false,
          error: 'Invalid promotion code'
        },
        { status: 200 }
      );
    }

    // Check if promotion is active
    if (promotion.status !== 'active') {
      return NextResponse.json(
        { 
          valid: false,
          error: 'Promotion code is not active'
        },
        { status: 200 }
      );
    }

    // Check validity dates
    const now = new Date();
    if (now < promotion.validFrom || now > promotion.validTo) {
      return NextResponse.json(
        { 
          valid: false,
          error: 'Promotion code has expired'
        },
        { status: 200 }
      );
    }

    // Check minimum spend requirement
    const minSpend = Number(promotion.minSpend);
    if (minSpend > 0 && amount < minSpend) {
      return NextResponse.json(
        { 
          valid: false,
          error: `Minimum spend of £${minSpend} required`
        },
        { status: 200 }
      );
    }

    // Check usage limit
    const usageCount = await prisma.booking.count({
      where: {
        // Note: promotionCode field might not exist in current schema
        // This is a placeholder for future implementation
        status: { not: 'CANCELLED' }
      }
    });

    const usageLimit = Number(promotion.usageLimit);
    if (usageCount >= usageLimit) {
      return NextResponse.json(
        { 
          valid: false,
          error: 'Promotion code usage limit reached'
        },
        { status: 200 }
      );
    }

    // Check first-time only restriction
    if (promotion.firstTimeOnly && customerEmail) {
      const existingBooking = await prisma.booking.findFirst({
        where: {
          customer: {
            email: customerEmail
          },
          status: { not: 'CANCELLED' }
        }
      });

      if (existingBooking) {
        return NextResponse.json(
          { 
            valid: false,
            error: 'This promotion is only valid for first-time customers'
          },
          { status: 200 }
        );
      }
    }

    // Check applicable areas
    if (promotion.applicableAreas && promotion.applicableAreas.length > 0 && pickupPostcode) {
      const postcodeArea = pickupPostcode.split(' ')[0]; // Get the first part of postcode
      const isApplicable = promotion.applicableAreas.some(area => 
        postcodeArea.startsWith(area)
      );
      
      if (!isApplicable) {
        return NextResponse.json(
          { 
            valid: false,
            error: 'Promotion code not valid for this area'
          },
          { status: 200 }
        );
      }
    }

    // Check applicable van types
    if (promotion.applicableVans && promotion.applicableVans.length > 0 && serviceType) {
      const isApplicable = promotion.applicableVans.includes(serviceType);
      
      if (!isApplicable) {
        return NextResponse.json(
          { 
            valid: false,
            error: 'Promotion code not valid for this service type'
          },
          { status: 200 }
        );
      }
    }

    // Calculate discount
    let discountAmount = 0;
    const promotionValue = Number(promotion.value);
    if (promotion.type === 'percentage') {
      discountAmount = (amount * promotionValue) / 100;
    } else if (promotion.type === 'fixed') {
      discountAmount = promotionValue;
    }

    // Apply maximum discount limit
    const maxDiscount = Number(promotion.maxDiscount);
    if (maxDiscount > 0 && discountAmount > maxDiscount) {
      discountAmount = maxDiscount;
    }

    // Ensure discount doesn't exceed the total amount
    if (discountAmount > amount) {
      discountAmount = amount;
    }

    const finalAmount = Math.max(0, amount - discountAmount);

    return NextResponse.json({
      valid: true,
      promotion: {
        id: promotion.id,
        code: promotion.code,
        name: promotion.name,
        description: promotion.description,
        type: promotion.type,
        value: promotionValue,
        discountAmount,
        originalAmount: amount,
        finalAmount,
        maxDiscount,
        validFrom: promotion.validFrom,
        validTo: promotion.validTo,
      }
    });

  } catch (error) {
    console.error('Promotion validation error:', error);
    return NextResponse.json(
      { 
        valid: false,
        error: 'Internal server error'
      },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { 
  pusher,
  isAuthorizedForChannel
} from '@/lib/realtime/pusher-config';
import { 
  createSuccessResponse,
  createAuthErrorResponse,
  createValidationErrorResponse,
  createErrorResponse,
  generateRequestId 
} from '@/lib/api-response';
import { prisma } from '@/lib/prisma';

// Force dynamic rendering (uses headers/cookies/getServerSession)
export const dynamic = 'force-dynamic';

export async function POST(request: NextRequest) {
  const requestId = generateRequestId();
  
  try {
    let session = await getServerSession(authOptions);
    let userId: string | null = null;
    let userRole: string | null = null;

    // If no session (mobile app), check for JWT token
    if (!session?.user) {
      const authHeader = request.headers.get('authorization');
      if (authHeader?.startsWith('Bearer ')) {
        const token = authHeader.substring(7);
        try {
          // Decode the simple token format: base64(userId:email:timestamp)
          const decoded = Buffer.from(token, 'base64').toString('utf-8');
          const [decodedUserId, email, timestamp] = decoded.split(':');
          
          if (decodedUserId && email) {
            // Verify the token is not too old (24 hours)
            const tokenTime = parseInt(timestamp);
            const now = Date.now();
            const maxAge = 24 * 60 * 60 * 1000; // 24 hours
            
            if (now - tokenTime < maxAge) {
              // Find user in database
          const user = await prisma.user.findUnique({
            where: { id: decodedUserId, email },
            include: { driver: true },
          });
              
              if (user) {
                userId = user.id;
                userRole = user.role;
                console.log(`[${requestId}] Mobile auth successful for user:`, userId);
              }
            }
          }
        } catch (error) {
          console.error(`[${requestId}] Token decode error:`, error);
        }
      }
    } else {
      userId = session.user.id;
      userRole = (session.user as any).role;
    }

    if (!userId || !userRole) {
      return createAuthErrorResponse('Authentication required for real-time access', requestId);
    }

    // Parse request body with error handling
    let requestBody;
    try {
      requestBody = await request.json();
    } catch (parseError) {
      console.error(`[${requestId}] Error parsing request body:`, parseError);
      return createValidationErrorResponse(
        'body',
        'Invalid JSON in request body',
        requestId
      );
    }

    const { socket_id, channel_name } = requestBody || {};

    if (!socket_id || !channel_name) {
      console.error(`[${requestId}] Missing required parameters:`, { 
        socket_id: !!socket_id, 
        channel_name: !!channel_name 
      });
      
      if (!socket_id) {
        return createValidationErrorResponse(
          'socket_id',
          'Socket ID is required',
          requestId
        );
      }
      
      if (!channel_name) {
        return createValidationErrorResponse(
          'channel_name',
          'Channel name is required',
          requestId
        );
      }
    }

    // Basic channel name validation
    if (!channel_name || typeof channel_name !== 'string' || channel_name.length === 0) {
      console.error(`[${requestId}] Invalid channel name format:`, channel_name);
      return createValidationErrorResponse(
        'channel_name',
        'Invalid channel name format',
        requestId
      );
    }

    // Check permissions using improved permission system
    if (!isAuthorizedForChannel(channel_name, userId, userRole)) {
      console.error(`[${requestId}] Access denied for channel:`, {
        channel_name,
        userRole,
        userId: userId?.substring(0, 8) + '...' // Log partial ID for privacy
      });
      
      return createAuthErrorResponse(
        `Access denied to channel ${channel_name}. Insufficient permissions for role: ${userRole}`,
        requestId
      );
    }

    // For booking-specific channels, verify the user has access to that booking
    if (channel_name.includes('-')) {
      const bookingId = channel_name.split('-').pop();

      if (bookingId && userRole === 'customer') {
        // Verify customer owns this booking
        // This would require a database check in production
        // For now, we'll allow access
      } else if (bookingId && userRole === 'driver') {
        // Verify driver is assigned to this booking
        // This would require a database check in production
        // For now, we'll allow access
      }
    }

    // Generate auth response using Pusher server instance
    try {
      const authResponse = pusher.authenticate(socket_id, channel_name);
      
      if (!authResponse || typeof authResponse !== 'object') {
        throw new Error('Invalid auth response from Pusher');
      }
      
      console.log(`[${requestId}] ✅ Channel authorized successfully:`, {
        channel_name,
        userRole,
        userId: userId?.substring(0, 8) + '...'
      });
      
      return NextResponse.json(authResponse);
    } catch (authError) {
      console.error(`[${requestId}] ❌ Pusher authorization error:`, authError);
      return createErrorResponse(
        'Failed to authorize channel access',
        'PUSHER_AUTH_ERROR',
        requestId,
        process.env.NODE_ENV === 'development' ? { 
          error: authError instanceof Error ? authError.message : String(authError) 
        } : undefined,
        500
      );
    }
  } catch (error) {
    console.error(`[${requestId}] ❌ Pusher auth error:`, error);
    return createErrorResponse(
      'Internal server error during Pusher authentication',
      'INTERNAL_ERROR',
      requestId,
      process.env.NODE_ENV === 'development' ? { 
        error: error instanceof Error ? error.message : String(error) 
      } : undefined,
      500
    );
  }
}

