import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth/next';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
import { generateAttendanceStatus, getTodayShift } from '@/lib/staffAttendance';
import { notifyLateCheckIn } from '@/lib/staffNotifications';
import { z } from 'zod';

// Force dynamic rendering (uses headers/cookies/getServerSession)
export const dynamic = 'force-dynamic';

const checkInSchema = z.object({
  notes: z.string().optional(),
});

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    const user = (session as any)?.user as { id?: string; role?: string } | undefined;

    if (!user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const userId = user.id as string;
    const role = user.role;

    // Check if user is staff
    if (role !== 'staff' && role !== 'admin') {
      return NextResponse.json({ error: 'Forbidden - Staff access required' }, { status: 403 });
    }

    // Find staff record
    const staff = await prisma.staff.findUnique({
      where: { userId },
    });

    if (!staff) {
      return NextResponse.json({ error: 'Staff record not found' }, { status: 404 });
    }

    // Parse request body
    const body = await request.json().catch(() => ({}));
    const { notes } = checkInSchema.parse(body);

    const today = new Date();
    today.setHours(0, 0, 0, 0);

    // Check if already checked in today
    const existingAttendance = await prisma.staffAttendance.findUnique({
      where: {
        staffId_date: {
          staffId: staff.id,
          date: today,
        },
      },
    });

    if (existingAttendance?.checkIn) {
      return NextResponse.json(
        { error: 'Already checked in today' },
        { status: 400 }
      );
    }

    const checkInTime = new Date();

    // Get today's shift
    const shift = await getTodayShift(staff.id);

    // Calculate attendance status
    const attendanceData = await generateAttendanceStatus(
      staff.id,
      checkInTime,
      null,
      today
    );

    // Create or update attendance record
    const attendance = await prisma.staffAttendance.upsert({
      where: {
        staffId_date: {
          staffId: staff.id,
          date: today,
        },
      },
      create: {
        staffId: staff.id,
        date: today,
        checkIn: checkInTime,
        status: attendanceData.status,
        lateMinutes: attendanceData.lateMinutes,
        earlyLeaveMinutes: 0,
        totalHours: 0,
        breakMinutes: shift?.breakMinutes || 0,
        notes: notes || null,
      },
      update: {
        checkIn: checkInTime,
        status: attendanceData.status,
        lateMinutes: attendanceData.lateMinutes,
        notes: notes || null,
      },
    });

    // Send notification if late
    if (attendanceData.lateMinutes > 15 && role !== 'admin') {
      await notifyLateCheckIn(staff.id, attendanceData.lateMinutes);
    }

    return NextResponse.json({
      success: true,
      attendance: {
        id: attendance.id,
        checkIn: attendance.checkIn,
        status: attendance.status,
        lateMinutes: attendance.lateMinutes,
      },
    });
  } catch (error) {
    console.error('Check-in error:', error);

    if (error instanceof z.ZodError) {
      return NextResponse.json(
        { error: 'Invalid request data', details: error.issues },
        { status: 400 }
      );
    }

    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth/next';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
import { generateAttendanceStatus, getTodayShift } from '@/lib/staffAttendance';
import { notifyEarlyCheckOut } from '@/lib/staffNotifications';
import { z } from 'zod';

// Force dynamic rendering (uses headers/cookies/getServerSession)
export const dynamic = 'force-dynamic';

const checkOutSchema = z.object({
  notes: z.string().optional(),
});

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    const user = (session as any)?.user as { id?: string; role?: string } | undefined;

    if (!user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const userId = user.id as string;
    const role = user.role;

    // Check if user is staff
    if (role !== 'staff' && role !== 'admin') {
      return NextResponse.json({ error: 'Forbidden - Staff access required' }, { status: 403 });
    }

    // Find staff record
    const staff = await prisma.staff.findUnique({
      where: { userId },
    });

    if (!staff) {
      return NextResponse.json({ error: 'Staff record not found' }, { status: 404 });
    }

    // Parse request body
    const body = await request.json().catch(() => ({}));
    const { notes } = checkOutSchema.parse(body);

    const today = new Date();
    today.setHours(0, 0, 0, 0);

    // Check if checked in today
    const attendance = await prisma.staffAttendance.findUnique({
      where: {
        staffId_date: {
          staffId: staff.id,
          date: today,
        },
      },
    });

    if (!attendance || !attendance.checkIn) {
      return NextResponse.json(
        { error: 'Must check in before checking out' },
        { status: 400 }
      );
    }

    if (attendance.checkOut) {
      return NextResponse.json(
        { error: 'Already checked out today' },
        { status: 400 }
      );
    }

    const checkOutTime = new Date();

    // Recalculate attendance status with check-out
    const attendanceData = await generateAttendanceStatus(
      staff.id,
      attendance.checkIn,
      checkOutTime,
      today
    );

    // Update attendance record
    const updatedAttendance = await prisma.staffAttendance.update({
      where: { id: attendance.id },
      data: {
        checkOut: checkOutTime,
        status: attendanceData.status,
        lateMinutes: attendanceData.lateMinutes,
        earlyLeaveMinutes: attendanceData.earlyLeaveMinutes,
        totalHours: attendanceData.totalHours,
        notes: notes || attendance.notes,
      },
    });

    // Send notification if early leave
    if (attendanceData.earlyLeaveMinutes > 60 && role !== 'admin') {
      await notifyEarlyCheckOut(staff.id, attendanceData.earlyLeaveMinutes);
    }

    return NextResponse.json({
      success: true,
      attendance: {
        id: updatedAttendance.id,
        checkIn: updatedAttendance.checkIn,
        checkOut: updatedAttendance.checkOut,
        status: updatedAttendance.status,
        lateMinutes: updatedAttendance.lateMinutes,
        earlyLeaveMinutes: updatedAttendance.earlyLeaveMinutes,
        totalHours: updatedAttendance.totalHours,
      },
    });
  } catch (error) {
    console.error('Check-out error:', error);

    if (error instanceof z.ZodError) {
      return NextResponse.json(
        { error: 'Invalid request data', details: error.issues },
        { status: 400 }
      );
    }

    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

/**
 * STRIPE PAYMENT INTENTS API - PRODUCTION GRADE
 * 
 * Create and manage Payment Intents for bookings.
 * 
 * Features:
 * - Payment Intent creation with GBP currency
 * - Automatic confirmation and capture
 * - Idempotency key handling
 * - Customer association
 * - Comprehensive metadata
 * - Structured logging
 */

import { NextRequest, NextResponse } from 'next/server';
import { z } from 'zod';
import { 
  createPaymentIntent, 
  retrievePaymentIntent, 
  confirmPaymentIntent,
  cancelPaymentIntent,
  generateIdempotencyKey,
  formatGbpMinor
} from '@/lib/stripe/client';
import { createRequestId } from '@/lib/pricing/schemas';

// Request schemas
const CreatePaymentIntentRequestSchema = z.object({
  amountGbpMinor: z.number().int().min(50).max(100000000), // 50p to £1M
  description: z.string().min(1).max(500),
  bookingId: z.string().min(1),
  customerId: z.string().optional(),
  customerEmail: z.string().email().optional(),
  metadata: z.object({
    bookingId: z.string(),
    serviceName: z.string().optional(),
    pickupAddress: z.string().optional(),
    dropoffAddress: z.string().optional(),
    scheduledDate: z.string().optional()
  }),
  setupFutureUsage: z.enum(['on_session', 'off_session']).optional(),
  generateIdempotencyKey: z.boolean().default(true)
});

const ConfirmPaymentIntentRequestSchema = z.object({
  paymentIntentId: z.string().min(1),
  paymentMethodId: z.string().optional()
});

const CancelPaymentIntentRequestSchema = z.object({
  paymentIntentId: z.string().min(1),
  reason: z.string().optional()
});

/**
 * POST /api/stripe/payment-intents
 * Create a new Payment Intent
 */
export async function POST(request: NextRequest): Promise<NextResponse> {
  const correlationId = `PI-CREATE-${createRequestId()}`;
  const startTime = Date.now();

  console.log(`[PAYMENT INTENT API] ${correlationId} - Create request received`);

  try {
    const body = await request.json();
    
    // Validate request
    const validationResult = CreatePaymentIntentRequestSchema.safeParse(body);
    if (!validationResult.success) {
      return NextResponse.json({
        success: false,
        error: 'Invalid request data',
        details: validationResult.error.issues,
        correlationId
      }, { status: 400 });
    }

    const {
      amountGbpMinor,
      description,
      bookingId,
      customerId,
      customerEmail,
      metadata,
      setupFutureUsage,
      generateIdempotencyKey: shouldGenerateIdempotencyKey
    } = validationResult.data;

    console.log(`[PAYMENT INTENT API] ${correlationId} - Creating Payment Intent`, {
      amountGbpMinor,
      amountGbpFormatted: formatGbpMinor(amountGbpMinor),
      bookingId,
      hasCustomerId: !!customerId,
      hasCustomerEmail: !!customerEmail
    });

    // Generate idempotency key if requested
    const idempotencyKey = shouldGenerateIdempotencyKey 
      ? generateIdempotencyKey(`booking_${bookingId}`)
      : undefined;

    // Create Payment Intent
    const paymentIntent = await createPaymentIntent({
      amountGbpMinor,
      automaticPaymentMethods: true,
      captureMethod: 'manual',
      description,
      customerId,
      metadata: {
        correlationId: correlationId,
        customerEmail: customerEmail || '',
        ...Object.fromEntries(
          Object.entries(metadata).map(([key, value]) => [key, String(value)])
        )
      },
      setupFutureUsage,
      idempotencyKey
    }, correlationId);

    const processingTime = Date.now() - startTime;

    console.log(`[PAYMENT INTENT API] ${correlationId} - Payment Intent created successfully`, {
      paymentIntentId: paymentIntent.id,
      status: paymentIntent.status,
      processingTimeMs: processingTime
    });

    return NextResponse.json({
      success: true,
      data: {
        ...paymentIntent,
        idempotencyKey: idempotencyKey || null,
        amountGbpFormatted: formatGbpMinor(paymentIntent.amountGbpMinor)
      },
      metadata: {
        correlationId,
        processingTimeMs: processingTime,
        timestamp: new Date().toISOString()
      }
    });

  } catch (error) {
    const processingTime = Date.now() - startTime;
    
    console.error(`[PAYMENT INTENT API] ${correlationId} - Creation failed`, {
      error: error instanceof Error ? error.message : 'Unknown error',
      stack: error instanceof Error ? error.stack : undefined,
      processingTimeMs: processingTime
    });

    return NextResponse.json({
      success: false,
      error: 'Failed to create Payment Intent',
      message: error instanceof Error ? error.message : 'Unknown error',
      correlationId
    }, { status: 500 });
  }
}

/**
 * GET /api/stripe/payment-intents?id=pi_xxx
 * Retrieve a Payment Intent by ID
 */
export async function GET(request: NextRequest): Promise<NextResponse> {
  const correlationId = `PI-GET-${createRequestId()}`;
  const startTime = Date.now();

  console.log(`[PAYMENT INTENT API] ${correlationId} - Retrieve request received`);

