import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';

interface VisitorTrackingData {
  sessionId: string;
  visitorId?: string;
  page: string;
  referrer?: string;
  userAgent: string;
  ipAddress: string;
  country?: string;
  city?: string;
  region?: string;
  latitude?: number;
  longitude?: number;
  browserName?: string;
  browserVersion?: string;
  osName?: string;
  osVersion?: string;
  deviceType?: string;
  screenResolution?: string;
  language?: string;
  timezone?: string;
  action?: string;
  actionData?: any;
}

export async function POST(request: NextRequest) {
  try {
    // Safely parse JSON body; handle empty/invalid bodies gracefully
    const raw = await request.text();
    if (!raw || raw.trim().length === 0) {
      // No content to process (can happen on aborted beacons or network hiccups)
      return new Response(null, { status: 204 });
    }

    let body: VisitorTrackingData;
    try {
      body = JSON.parse(raw) as VisitorTrackingData;
    } catch {
      // Invalid JSON - avoid noisy errors and just ignore
      return NextResponse.json({ success: false, error: 'Invalid JSON' }, { status: 400 });
    }

    // Minimal required fields to proceed
    if (!body.sessionId || !body.page) {
      return new Response(null, { status: 204 });
    }

    // Get IP address from various possible headers
    const ipAddress =
      request.headers.get('x-forwarded-for')?.split(',')[0] ||
      request.headers.get('x-real-ip') ||
      request.headers.get('cf-connecting-ip') ||
      body.ipAddress ||
      'unknown';

    // Get geolocation data from Cloudflare headers (if available)
    const cfCountry = request.headers.get('cf-ipcountry');
    const cfCity = request.headers.get('cf-ipcity');
    const cfRegion = request.headers.get('cf-region');
    const cfLatitude = request.headers.get('cf-latitude');
    const cfLongitude = request.headers.get('cf-longitude');

    // Parse user agent for device info
    const userAgent = body.userAgent || request.headers.get('user-agent') || 'unknown';
    const deviceInfo = parseUserAgent(userAgent);

    // Get geolocation from IP if not provided
    let locationData = {
      country: body.country || cfCountry || null,
      city: body.city || cfCity || null,
      region: body.region || cfRegion || null,
      latitude: body.latitude || (cfLatitude ? parseFloat(cfLatitude) : null),
      longitude: body.longitude || (cfLongitude ? parseFloat(cfLongitude) : null),
    };

    // If no location data, try to get from IP using a geolocation service
    if (!locationData.country && ipAddress !== 'unknown') {
      try {
        const geoData = await getLocationFromIP(ipAddress);
        locationData = { ...locationData, ...geoData };
      } catch (error) {
        console.warn('Failed to get location from IP:', error);
      }
    }

    // Create or update visitor session
    const visitorSession = await prisma.visitorSession.upsert({
      where: { sessionId: body.sessionId },
      create: {
        id: `session-${body.sessionId}-${Date.now()}-${Math.random().toString(36).substr(2, 9)}-${performance.now()}`,
        sessionId: body.sessionId,
        visitorId: body.visitorId,
        ipAddress,
        country: locationData.country,
        city: locationData.city,
        region: locationData.region,
        latitude: locationData.latitude,
        longitude: locationData.longitude,
        userAgent,
        browserName: deviceInfo.browserName,
        browserVersion: deviceInfo.browserVersion,
        osName: deviceInfo.osName,
        osVersion: deviceInfo.osVersion,
        deviceType: deviceInfo.deviceType,
        screenResolution: body.screenResolution,
        language: body.language,
        timezone: body.timezone,
        entryPage: body.page,
        entryTime: new Date(),
        lastSeenAt: new Date(),
        updatedAt: new Date(),
      },
      update: {
        lastSeenAt: new Date(),
        updatedAt: new Date(),
      },
    });

    // Track page view
    await prisma.pageView.create({
      data: {
        id: `pageview-${body.sessionId}-${Date.now()}-${Math.random().toString(36).substr(2, 9)}-${performance.now()}`,
        sessionId: body.sessionId,
        page: body.page,
        referrer: body.referrer,
        timestamp: new Date(),
      },
    });

    // Track action if provided
    if (body.action) {
      await prisma.visitorAction.create({
        data: {
          id: `action-${body.sessionId}-${Date.now()}-${Math.random().toString(36).substr(2, 9)}-${performance.now()}`,
          sessionId: body.sessionId,
          action: body.action,
          actionData: body.actionData || {},
          timestamp: new Date(),
        },
      });
    }

    return NextResponse.json({
      success: true,
      sessionId: body.sessionId,
      location: locationData,
    });
  } catch (error) {
    console.error('Visitor tracking error:', error);
    return NextResponse.json(
      {
        success: false,
        error: error instanceof Error ? error.message : 'Internal server error',
      },
      { status: 500 }
    );
  }
}

// Parse user agent to extract device information
function parseUserAgent(userAgent: string) {
  const ua = userAgent.toLowerCase();

  // Detect browser
  let browserName = 'Unknown';
  let browserVersion = '';

  if (ua.includes('firefox')) {
    browserName = 'Firefox';
    const match = ua.match(/firefox\/(\d+\.\d+)/);
    browserVersion = match ? match[1] : '';
  } else if (ua.includes('edg')) {
    browserName = 'Edge';
    const match = ua.match(/edg\/(\d+\.\d+)/);
    browserVersion = match ? match[1] : '';
  } else if (ua.includes('chrome')) {
    browserName = 'Chrome';
    const match = ua.match(/chrome\/(\d+\.\d+)/);
    browserVersion = match ? match[1] : '';
  } else if (ua.includes('safari')) {
    browserName = 'Safari';
    const match = ua.match(/version\/(\d+\.\d+)/);
    browserVersion = match ? match[1] : '';
  }

  // Detect OS
  let osName = 'Unknown';
  let osVersion = '';

  if (ua.includes('windows nt 10')) {
    osName = 'Windows';
    osVersion = '10/11';
  } else if (ua.includes('windows nt')) {
    osName = 'Windows';
    const match = ua.match(/windows nt (\d+\.\d+)/);
    osVersion = match ? match[1] : '';
  } else if (ua.includes('mac os x')) {
    osName = 'macOS';
    const match = ua.match(/mac os x (\d+[._]\d+)/);
    osVersion = match ? match[1].replace('_', '.') : '';
  } else if (ua.includes('android')) {
    osName = 'Android';
    const match = ua.match(/android (\d+\.\d+)/);
    osVersion = match ? match[1] : '';
  } else if (ua.includes('iphone') || ua.includes('ipad')) {
    osName = 'iOS';
    const match = ua.match(/os (\d+[._]\d+)/);
    osVersion = match ? match[1].replace('_', '.') : '';
  } else if (ua.includes('linux')) {
    osName = 'Linux';
  }

  // Detect device type
  let deviceType = 'Desktop';
  if (ua.includes('mobile')) {
    deviceType = 'Mobile';
  } else if (ua.includes('tablet') || ua.includes('ipad')) {
    deviceType = 'Tablet';
  }

  return {
    browserName,
    browserVersion,
    osName,
    osVersion,
    deviceType,
  };
}

// Get location from IP address (using ipapi.co - free tier)
async function getLocationFromIP(ipAddress: string) {
  try {
    // Skip for local/private IPs
    if (
      ipAddress === 'unknown' ||
      ipAddress.startsWith('127.') ||
      ipAddress.startsWith('192.168.') ||
      ipAddress.startsWith('10.') ||
      ipAddress === '::1'
    ) {
      return {
        country: 'Local',
        city: 'Local',
        region: 'Local',
        latitude: null,
        longitude: null,
      };
    }

    const response = await fetch(`https://ipapi.co/${ipAddress}/json/`, {
      next: { revalidate: 3600 }, // Cache for 1 hour
    });

    if (!response.ok) {
      throw new Error('Geolocation API failed');
    }

    const data = await response.json();

    return {
      country: data.country_name || null,
      city: data.city || null,
      region: data.region || null,
      latitude: data.latitude || null,
      longitude: data.longitude || null,
    };
  } catch (error) {
    console.error('IP geolocation error:', error);
    return {
      country: null,
      city: null,
      region: null,
      latitude: null,
      longitude: null,
    };
  }
}

// GET endpoint to retrieve visitor analytics
export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const limit = parseInt(searchParams.get('limit') || '100');
    const skip = parseInt(searchParams.get('skip') || '0');

    const sessions = await prisma.visitorSession.findMany({
      take: limit,
      skip: skip,
      orderBy: { entryTime: 'desc' },
      include: {
        PageView: true,
        VisitorAction: true,
      },
    });

    const total = await prisma.visitorSession.count();

    return NextResponse.json({
      success: true,
      data: sessions,
      pagination: {
        total,
        limit,
        skip,
        hasMore: skip + limit < total,
      },
    });
  } catch (error) {
    console.error('Get visitors error:', error);
    return NextResponse.json(
      {
        success: false,
        error: 'Internal server error',
      },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';

export const dynamic = 'force-dynamic';

export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const lat = searchParams.get('lat');
    const lng = searchParams.get('lng');
    const date = searchParams.get('date');

    if (!lat || !lng) {
      return NextResponse.json(
        { error: 'Latitude and longitude are required' },
        { status: 400 }
      );
    }

    // Get weather API key from environment (server-side only)
    const weatherApiKey = process.env.WEATHER_API_KEY;

    if (!weatherApiKey) {
      return NextResponse.json(
        { error: 'Weather API key not configured' },
        { status: 500 }
      );
    }

    // Call OpenWeatherMap API for current weather
    const weatherResponse = await fetch(
      `https://api.openweathermap.org/data/2.5/weather?lat=${lat}&lon=${lng}&appid=${weatherApiKey}&units=metric`
    );

    if (!weatherResponse.ok) {
      throw new Error(`Weather API error: ${weatherResponse.status}`);
    }

    const weatherData = await weatherResponse.json();

    // Get 5-day forecast
    const forecastResponse = await fetch(
      `https://api.openweathermap.org/data/2.5/forecast?lat=${lat}&lon=${lng}&appid=${weatherApiKey}&units=metric`
    );

    if (!forecastResponse.ok) {
      throw new Error(`Forecast API error: ${forecastResponse.status}`);
    }

    const forecastData = await forecastResponse.json();

    // Process current weather
    const currentWeather = {
      condition: weatherData.weather[0]?.main || 'Unknown',
      temperature: Math.round(weatherData.main?.temp || 0),
      precipitation: weatherData.rain?.['1h'] || 0,
      windSpeed: Math.round(weatherData.wind?.speed || 0),
      visibility: Math.round((weatherData.visibility || 10000) / 1000), // Convert to km
      humidity: weatherData.main?.humidity || 0,
      pressure: weatherData.main?.pressure || 0,
    };

    // Process forecast for specific date if provided
    let targetForecast = null;
    if (date) {
      const targetDate = new Date(date);
      const targetForecastData = forecastData.list.find((item: any) => {
        const itemDate = new Date(item.dt * 1000);
        return itemDate.toDateString() === targetDate.toDateString();
      });

      if (targetForecastData) {
        targetForecast = {
          condition: targetForecastData.weather[0]?.main || 'Unknown',
          temperature: Math.round(targetForecastData.main?.temp || 0),
          precipitation: targetForecastData.rain?.['3h'] || 0,
          windSpeed: Math.round(targetForecastData.wind?.speed || 0),
          visibility: Math.round(
            (targetForecastData.visibility || 10000) / 1000
          ),
          humidity: targetForecastData.main?.humidity || 0,
          pressure: targetForecastData.main?.pressure || 0,
        };
      }
    }

    // Generate weather recommendations
    const recommendations = generateWeatherRecommendations(
      targetForecast || currentWeather
    );

    const response = {
      current: currentWeather,
      forecast: targetForecast,
      recommendations,
      timestamp: new Date().toISOString(),
    };

    return NextResponse.json(response);
  } catch (error) {
    console.error('❌ Weather forecast API error:', error);

    // Return mock data as fallback
    return NextResponse.json({
      current: {
        condition: 'Clear',
        temperature: 18,
        precipitation: 0,
        windSpeed: 5,
        visibility: 10,
        humidity: 65,
        pressure: 1013,
      },
      forecast: null,
      recommendations: ['Good weather conditions for travel'],
      timestamp: new Date().toISOString(),
      fallback: true,
    });
  }
}

function generateWeatherRecommendations(weather: any): string[] {
  const recommendations = [];

  if (weather.precipitation > 5) {
    recommendations.push('Heavy rain expected - allow extra travel time');
    recommendations.push('Use windshield wipers and maintain safe distance');
  } else if (weather.precipitation > 2) {
    recommendations.push('Light rain expected - drive carefully');
  }

  if (weather.visibility < 5) {
    recommendations.push('Poor visibility - use headlights and drive slowly');
  } else if (weather.visibility < 8) {
    recommendations.push('Reduced visibility - drive with caution');
  }

  if (weather.windSpeed > 20) {
    recommendations.push(
      'High winds - secure loose items and drive cautiously'
    );
  } else if (weather.windSpeed > 15) {
    recommendations.push('Moderate winds - be aware of gusts');
  }

  if (weather.temperature < 5) {
    recommendations.push(
      'Cold weather - check vehicle fluids and tire pressure'
    );
  } else if (weather.temperature > 30) {
    recommendations.push('Hot weather - ensure proper vehicle cooling');
  }

  if (recommendations.length === 0) {
    recommendations.push('Good weather conditions for travel');
  }

  return recommendations;
}

import { NextRequest, NextResponse } from 'next/server';
import { z } from 'zod';

// Weather data interfaces
interface WeatherCondition {
  temperature: number; // Celsius
  feelsLike: number;
  humidity: number; // percentage
  pressure: number; // hPa
  visibility: number; // meters
  uvIndex: number;
  windSpeed: number; // km/h
  windDirection: number; // degrees
  windGust?: number; // km/h
  precipitation: {
    type: 'none' | 'rain' | 'snow' | 'sleet' | 'hail';
    intensity: 'light' | 'moderate' | 'heavy' | 'extreme';
    amount?: number; // mm/hour
    probability: number; // 0-100
  };
  conditions: {
    main: string; // 'Clear', 'Clouds', 'Rain', etc.
    description: string; // 'clear sky', 'few clouds', etc.
    icon: string; // weather icon code
  };
  airQuality?: {
    aqi: number; // 1-5 (good to very poor)
    pm25: number;
    pm10: number;
    no2: number;
    o3: number;
    so2: number;
    co: number;
  };
}

interface RoadCondition {
  temperature: number;
  condition: 'dry' | 'wet' | 'icy' | 'snowy' | 'flooded';
  friction: number; // coefficient 0-1 (1 = perfect grip)
  visibility: 'excellent' | 'good' | 'poor' | 'very_poor';
  hazards: string[]; // ['black_ice', 'flooding', 'strong_wind', etc.]
}

interface WeatherData {
  location: {
    lat: number;
    lng: number;
    name?: string;
  };
  current: WeatherCondition;
  forecast: WeatherCondition[]; // Next 12 hours, hourly
  alerts: WeatherAlert[];
  roadCondition: RoadCondition;
  lastUpdated: string;
  dataSource: 'openweather' | 'accuweather' | 'weatherapi' | 'cached';
  coverage: number; // percentage confidence
}

interface WeatherAlert {
  id: string;
  type: 'warning' | 'watch' | 'advisory';
  severity: 'minor' | 'moderate' | 'severe' | 'extreme';
  title: string;
  description: string;
  startTime: string;
  endTime: string;
  areas: string[];
  instructions?: string;
}

