'use client';

import {
  Box,
  Container,
  VStack,
  Heading,
  Text,
  FormControl,
  FormLabel,
  Input,
  Button,
  useToast,
  Link as ChakraLink,
} from '@chakra-ui/react';
import { useState } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import NextLink from 'next/link';

const forgotPasswordSchema = z.object({
  email: z.string().email('Please enter a valid email address'),
});

type ForgotPasswordFormData = z.infer<typeof forgotPasswordSchema>;

export default function ForgotPasswordPage() {
  const [isLoading, setIsLoading] = useState(false);
  const toast = useToast();

  const {
    register,
    handleSubmit,
    formState: { errors },
  } = useForm<ForgotPasswordFormData>({
    resolver: zodResolver(forgotPasswordSchema),
  });

  const onSubmit = async (data: ForgotPasswordFormData) => {
    setIsLoading(true);
    try {
      const response = await fetch('/api/auth/forgot', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ email: data.email }),
      });

      const result = await response.json();

      if (!response.ok) {
        toast({
          title: 'Error',
          description: result.error || 'An error occurred. Please try again.',
          status: 'error',
          duration: 5000,
          isClosable: true,
        });
      } else {
        toast({
          title: 'Reset link sent',
          description:
            result.message ||
            "If an account with that email exists, we've sent a password reset link.",
          status: 'success',
          duration: 5000,
          isClosable: true,
        });
      }
    } catch (error) {
      toast({
        title: 'Error',
        description: 'An error occurred. Please try again.',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <Container maxW="md" py={16}>
      <VStack spacing={8}>
        <VStack spacing={4} textAlign="center">
          <Heading size="lg">Forgot your password?</Heading>
          <Text color="gray.600">
            Enter your email address and we'll send you a link to reset your
            password.
          </Text>
        </VStack>

        <Box as="form" w="full" onSubmit={handleSubmit(onSubmit)}>
          <VStack spacing={6}>
            <FormControl isInvalid={!!errors.email}>
              <FormLabel>Email address</FormLabel>
              <Input
                type="email"
                placeholder="Enter your email"
                {...register('email')}
              />
              {errors.email && (
                <Text color="red.500" fontSize="sm" mt={1}>
                  {errors.email.message}
                </Text>
              )}
            </FormControl>

            <Button
              type="submit"
              variant="primary"
              w="full"
              isLoading={isLoading}
              loadingText="Sending reset link..."
            >
              Send reset link
            </Button>
          </VStack>
        </Box>

        <Text fontSize="sm" color="gray.600" textAlign="center">
          Remember your password?{' '}
          <ChakraLink as={NextLink} href="/" color="teal.500">
            Sign in
          </ChakraLink>
        </Text>
      </VStack>
    </Container>
  );
}

'use client';
import { signIn, useSession } from 'next-auth/react';
import { useState, useEffect } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import {
  Box,
  Container,
  Flex,
  Heading,
  Text,
  Stack,
  FormControl,
  FormLabel,
  Input,
  InputGroup,
  InputRightElement,
  Button,
  Link as ChakraLink,
  Alert,
  AlertIcon,
  useToast,
} from '@chakra-ui/react';
import { keyframes as emotionKeyframes } from '@emotion/react';
import NextLink from 'next/link';
import { ROUTES } from '@/lib/routing';

export default function LoginPage() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const router = useRouter();
  const searchParams = useSearchParams();
  const { data: session, status, update } = useSession();
  const toast = useToast();
  
  // Get role from URL parameters
  const role = searchParams?.get('role');
  const isAdminLogin = role === 'admin';

  // Handle redirect after session is established
  useEffect(() => {
    if (session?.user && !isLoading) {
      const userRole = (session.user as any).role;
      switch (userRole) {
        case 'admin':
          router.push('/admin');
          break;
        case 'driver':
          router.push('/driver');
          break;
        case 'customer':
          router.push('/customer');
          break;
        default:
          router.push('/');
      }
    }
  }, [session, isLoading, router]);

  async function onSubmit(e: React.FormEvent) {
    e.preventDefault();
    setErr(null);
    setIsLoading(true);

    try {
      const signInPromise = signIn('credentials', {
        redirect: false,
        email,
        password,
        role: role || undefined,
      });
      const timeoutPromise = new Promise((_, reject) =>
        setTimeout(() => reject(new Error('SignIn timeout')), 10000)
      );

      const res = (await Promise.race([signInPromise, timeoutPromise])) as any;

      if (res?.ok) {
        try {
          await update();
        } catch {
          // ignore
        }
        await new Promise(resolve => setTimeout(resolve, 500));
        toast({
          title: 'Signed in successfully',
          status: 'success',
          duration: 2000,
          isClosable: true,
        });
      } else {
        setErr('Invalid email or password');
      }
    } catch {
      setErr('Login failed. Please try again.');
    } finally {
      setIsLoading(false);
    }
  }

  // Loading state
  if (status === 'loading') {
    return (
      <Container maxW="6xl" py={{ base: 16, md: 24 }}>
        <Heading size="lg">Login</Heading>
        <Text mt={4}>Signing you in...</Text>
      </Container>
    );
  }

  // Animated background
  const moveGradient = emotionKeyframes`
    0% { background-position: 0% 50%; }
    50% { background-position: 100% 50%; }
    100% { background-position: 0% 50%; }
  `;

  const shimmer = emotionKeyframes`
    0% { background-position: 0% 50%; }
    100% { background-position: 200% 50%; }
  `;

  return (
    <Box position="relative" minH="100vh" overflow="hidden">
      {/* Moving gradient background */}
      <Box
        position="absolute"
        inset={0}
        zIndex={0}
        bg="linear-gradient(120deg, rgba(5,10,18,1) 0%, rgba(7,13,23,1) 30%, rgba(10,20,35,1) 60%, rgba(7,13,23,1) 100%)"
      />
      <Box
        position="absolute"
        inset={0}
        zIndex={0}
        bg="linear-gradient(90deg, rgba(0,194,255,0.16), rgba(147,51,234,0.16), rgba(236,72,153,0.16), rgba(16,185,129,0.16))"
        style={{ backgroundSize: '300% 300%' }}
        animation={`${moveGradient} 18s ease-in-out infinite`}
        mixBlendMode="screen"
      />

    <Container maxW="6xl" py={{ base: 12, md: 24 }} position="relative" zIndex={1}>
      <Stack direction="row" spacing={10} align="stretch" flexWrap="wrap">
        {/* Brand / context */}
        <Box
          flex="1"
          bgGradient="linear(to-br, rgba(0,194,255,0.12), transparent)"
          border="1px solid"
          borderColor="whiteAlpha.200"
          rounded="xl"
          p={{ base: 8, md: 10 }}
          minW={{ base: '380px', md: '460px' }}
          maxW={{ base: '100%', md: '520px' }}
        >
          <Heading size="xl" color="primary.300">
            {isAdminLogin ? 'Admin Sign In' : 'Sign In'}
          </Heading>
          <Text mt={3} color="whiteAlpha.800" fontSize="md">
            Enter your credentials to access your dashboard.
          </Text>
          <Box mt={8} color="whiteAlpha.700" fontSize="sm">
            <Text fontWeight="semibold">Need help?</Text>
            <Text mt={1}>
              Email: support@speedy-van.co.uk
            </Text>
            <Text>Phone: 01202 129746</Text>
          </Box>
        </Box>

        {/* Form */}
        <Box
          as="form"
          onSubmit={onSubmit}
          flex="1"
          bg="rgba(7,13,23,0.75)"
          border="1px solid"
          borderColor="whiteAlpha.200"
          rounded="xl"
          p={{ base: 8, md: 10 }}
          boxShadow="0 8px 30px rgba(0,0,0,0.35)"
          minW={{ base: '380px', md: '520px' }}
          maxW={{ base: '100%', md: '560px' }}
        >
          <Heading size="lg">
            {isAdminLogin ? 'Welcome back, Admin' : 'Welcome back'}
          </Heading>
          <Text mt={1} color="whiteAlpha.700" fontSize="sm">
            Please sign in to continue
          </Text>

          {err && (
            <Alert status="error" mt={4} rounded="md">
              <AlertIcon />
              {err}
            </Alert>
          )}

          <FormControl mt={6} isRequired>
            <FormLabel>Email</FormLabel>
            <Input
              type="email"
              value={email}
              onChange={e => setEmail(e.target.value)}
              placeholder="you@example.com"
              disabled={isLoading}
              data-testid="email-input"
            />
          </FormControl>

          <FormControl mt={4} isRequired>
            <FormLabel>Password</FormLabel>
            <InputGroup>
              <Input
                type={showPassword ? 'text' : 'password'}
                value={password}
                onChange={e => setPassword(e.target.value)}
                placeholder="Your password"
                disabled={isLoading}
                data-testid="password-input"
              />
              <InputRightElement width="4.5rem">
                <Button
                  h="1.75rem"
                  size="sm"
                  variant="ghost"
                  onClick={() => setShowPassword(v => !v)}
                >
                  {showPassword ? 'Hide' : 'Show'}
                </Button>
              </InputRightElement>
            </InputGroup>
          </FormControl>

          <Button
            type="submit"
            colorScheme="cyan"
            mt={8}
            w="full"
            isLoading={isLoading}
            loadingText="Signing in"
            data-testid="login-button"
          >
            Sign in
          </Button>

          <Flex mt={5} justify="space-between" align="center">
            <ChakraLink as={NextLink} href={ROUTES.FORGOT_PASSWORD}>
              Forgot password?
            </ChakraLink>
          </Flex>
        </Box>
      </Stack>

      <Box textAlign="center" mt={10}>
        <Text
          fontSize={{ base: 'xl', md: '3xl' }}
          fontWeight="extrabold"
          bgGradient="linear(to-r, cyan.300, purple.300, pink.300, teal.300)"
          bgClip="text"
          style={{ backgroundSize: '200% 100%' }}
          animation={`${shimmer} 5s linear infinite`}
          letterSpacing="wide"
        >
          Speedy Van Management System
        </Text>
      </Box>
    </Container>
    </Box>
  );
}

'use client';

import {
  Box,
  Container,
  VStack,
  Heading,
  Text,
  Button,
  Alert,
  AlertIcon,
  Card,
  CardBody,
  useToast,
} from '@chakra-ui/react';
import { useState, useEffect } from 'react';
import { useSearchParams, useRouter } from 'next/navigation';
import NextLink from 'next/link';

export default function EmailVerificationPage() {
  const searchParams = useSearchParams();
  const router = useRouter();
  const token = searchParams?.get('token');
  const [isLoading, setIsLoading] = useState(false);
  const [verificationStatus, setVerificationStatus] = useState<
    'pending' | 'success' | 'error'
  >('pending');
  const [errorMessage, setErrorMessage] = useState('');
  const toast = useToast();

  useEffect(() => {
    if (token) {
      verifyEmail(token);
    }
  }, [token]);

  const verifyEmail = async (verificationToken: string) => {
    setIsLoading(true);
    try {
      const response = await fetch('/api/auth/verify-email', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ token: verificationToken }),
      });

      const result = await response.json();

      if (!response.ok) {
        setVerificationStatus('error');
        setErrorMessage(
          result.error || 'An error occurred during verification.'
        );
        toast({
          title: 'Verification failed',
          description: result.error || 'An error occurred during verification.',
          status: 'error',
          duration: 5000,
          isClosable: true,
        });
      } else {
        setVerificationStatus('success');
        toast({
          title: 'Email verified!',
          description: 'Your email has been verified successfully.',
          status: 'success',
          duration: 5000,
          isClosable: true,
        });
      }
    } catch (error) {
      setVerificationStatus('error');
      setErrorMessage('An error occurred during verification.');
      toast({
        title: 'Verification failed',
        description: 'An error occurred during verification.',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setIsLoading(false);
    }
  };

  if (!token) {
    return (
      <Container maxW="md" py={12}>
        <VStack spacing={8}>
          <Box textAlign="center">
            <Heading size="lg" mb={2}>
              Invalid Verification Link
            </Heading>
            <Text color="gray.600">
              This email verification link is invalid or has expired.
            </Text>
          </Box>
          <Button as={NextLink} href="/" variant="primary" size="lg" w="full">
            Go to Home
          </Button>
        </VStack>
      </Container>
    );
  }

  return (
    <Container maxW="md" py={12}>
      <VStack spacing={8}>
        <Box textAlign="center">
          <Heading size="lg" mb={2}>
            Email Verification
          </Heading>
          <Text color="gray.600">
            {verificationStatus === 'pending' &&
              'Verifying your email address...'}
            {verificationStatus === 'success' &&
              'Your email has been verified successfully!'}
            {verificationStatus === 'error' && 'Email verification failed.'}
          </Text>
        </Box>

        <Card w="full">
          <CardBody>
            {verificationStatus === 'pending' && (
              <VStack spacing={4}>
                <Alert status="info">
                  <AlertIcon />
                  Please wait while we verify your email address...
                </Alert>
                <Button
                  isLoading={isLoading}
                  loadingText="Verifying..."
                  variant="primary"
                  size="lg"
                  w="full"
                  isDisabled
                >
                  Verifying Email
                </Button>
              </VStack>
            )}

            {verificationStatus === 'success' && (
              <VStack spacing={4}>
                <Alert status="success">
                  <AlertIcon />
                  Your email has been verified successfully!
                </Alert>
                <Button
                  as={NextLink}
                  href="/"
                  variant="primary"
                  size="lg"
                  w="full"
                >
                  Continue to Home
                </Button>
              </VStack>
            )}

            {verificationStatus === 'error' && (
              <VStack spacing={4}>
                <Alert status="error">
                  <AlertIcon />
                  {errorMessage}
                </Alert>
                <Button
                  as={NextLink}
                  href="/"
                  variant="primary"
                  size="lg"
                  w="full"
                >
                  Go to Home
                </Button>
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => router.push('/auth/forgot')}
                >
                  Need help? Contact support
                </Button>
              </VStack>
            )}
          </CardBody>
        </Card>
      </VStack>
    </Container>
  );
}

