'use client';

import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import {
  Alert,
  AlertIcon,
  Badge,
  Box,
  Button,
  Card,
  CardBody,
  HStack,
  Icon,
  Spinner,
  Stack,
  Text,
  Textarea,
  VStack,
  useColorModeValue,
} from '@chakra-ui/react';
import { FaPaperPlane, FaRobot, FaUser } from 'react-icons/fa';

import type { PropertyType } from './PropertyTypeSelector';
import type { RemovalItem } from '@/lib/uk-removal-items-data';

export type AiAddedItemPayload = {
  item: RemovalItem;
  quantity: number;
  room: string;
  size?: string | null;
  itemType?: string;
  source?: string;
};

export type PendingQuestionPayload = {
  id: string;
  question: string;
  field: string;
  itemName: string;
};

interface Message {
  id: string;
  role: 'assistant' | 'user';
  content: string;
}

interface AIItemExtractionAssistantProps {
  propertyType?: PropertyType;
  selectedItems: { id: string; name: string; quantity: number }[];
  onAddItems: (items: AiAddedItemPayload[]) => void;
}

const INITIAL_MESSAGE =
  'I can organise everything for you in seconds. Just tell me what you need to move.';
const FALLBACK_ASSISTANT_RESPONSE =
  "I've added the items you requested. Tell me if you want to add more, or you can move to the next step.";

function uniqueId() {
  return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
}

export default function AIItemExtractionAssistant({
  propertyType,
  selectedItems,
  onAddItems,
}: AIItemExtractionAssistantProps) {
  console.log('🤖 AIItemExtractionAssistant RENDERED', { propertyType, selectedItemsCount: selectedItems.length });
  
  const [messages, setMessages] = useState<Message[]>([{ id: uniqueId(), role: 'assistant', content: INITIAL_MESSAGE }]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [pendingQuestions, setPendingQuestions] = useState<PendingQuestionPayload[]>([]);

  const scrollRef = useRef<HTMLDivElement | null>(null);
  const chatBg = useColorModeValue('white', 'whiteAlpha.200');
  const assistantBg = useColorModeValue('blue.50', 'whiteAlpha.200');
  const userBg = useColorModeValue('gray.100', 'whiteAlpha.300');

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isLoading]);

  const handleSubmit = useCallback(
    async (event?: React.FormEvent) => {
      event?.preventDefault();
      if (!input.trim()) return;

      const userMessage: Message = { id: uniqueId(), role: 'user', content: input.trim() };
      const nextMessages = [...messages, userMessage];
      setMessages(nextMessages);
      setInput('');
      setError(null);
      setIsLoading(true);

      try {
        const response = await fetch('/api/booking/ai-items', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            message: userMessage.content,
            propertyType,
            conversation: nextMessages.map(({ role, content }) => ({ role, content })),
            selectedItems,
          }),
        });

        const payload = await response.json();
        if (!response.ok || !payload?.success) {
          throw new Error(payload?.error || 'Unable to process your request. Please try again.');
        }

        const added: AiAddedItemPayload[] = payload.data?.addedItems || [];
        if (added.length > 0) {
          onAddItems(added);
        }

        const assistantText = payload.data?.assistantSummary || FALLBACK_ASSISTANT_RESPONSE;

        const assistantMessage: Message = {
          id: uniqueId(),
          role: 'assistant',
          content: assistantText.trim(),
        };

        setMessages((prev) => [...prev, assistantMessage]);
        setPendingQuestions(payload.data?.pendingQuestions || []);
      } catch (err) {
        const message = err instanceof Error ? err.message : 'Something went wrong. Please try again.';
        setError(message);
      } finally {
        setIsLoading(false);
      }
    },
    [input, messages, onAddItems, propertyType, selectedItems]
  );

  const pendingSummary = useMemo(() => {
    if (pendingQuestions.length === 0) return null;
    return pendingQuestions.map((question) => ({
      id: question.id,
      label: question.itemName,
      text: question.question,
    }));
  }, [pendingQuestions]);

  return (
    <Card
      bgGradient="linear(to-br, rgba(16, 185, 129, 0.12), rgba(5, 150, 105, 0.08))"
      backdropFilter="blur(20px)"
      border="2px solid"
      borderColor="green.400"
      borderRadius="3xl"
      boxShadow="0 25px 50px -12px rgba(16, 185, 129, 0.25), 0 0 0 1px rgba(16, 185, 129, 0.1)"
      position="relative"
      overflow="hidden"
      _before={{
        content: '""',
        position: 'absolute',
        top: 0,
        left: 0,
        right: 0,
        height: '4px',
        bgGradient: 'linear(to-r, green.400, teal.400, green.400)',
        animation: 'shimmer 3s infinite',
      }}
      sx={{
        '@keyframes shimmer': {
          '0%, 100%': { opacity: 1 },
          '50%': { opacity: 0.6 },
        },
      }}
    >
      <CardBody p={{ base: 5, md: 8 }}>
        <VStack align="stretch" spacing={6}>
          {/* Header */}
          <HStack spacing={4} align="center" justify="space-between">
            <HStack spacing={3}>
              <Box
                p={3}
                bgGradient="linear(to-br, green.400, teal.500)"
                borderRadius="xl"
                boxShadow="0 8px 16px rgba(16, 185, 129, 0.4)"
              >
                <Icon as={FaRobot} color="white" boxSize={6} />
              </Box>
              <VStack align="start" spacing={0}>
                <Text 
                  fontWeight="800" 
                  fontSize="xl"
                  bgGradient="linear(to-r, green.300, teal.400)"
                  bgClip="text"
                  letterSpacing="tight"
                >
                  AI Assistant
                </Text>
                <Text fontSize="xs" color="whiteAlpha.700" fontWeight="500">
                  Powered by Groq AI
                </Text>
              </VStack>
            </HStack>
            <Badge 
              colorScheme="green" 
              borderRadius="full" 
              px={3} 
              py={1}
              fontSize="xs"
              fontWeight="bold"
              textTransform="uppercase"
            >
              Beta
            </Badge>
          </HStack>

          {/* Chat Messages */}
          <Box
            ref={scrollRef}
            bg="rgba(0, 0, 0, 0.3)"
            backdropFilter="blur(10px)"
            borderRadius="2xl"
            p={4}
            maxH="300px"
            minH="200px"
            overflowY="auto"
            border="1px solid"
            borderColor="whiteAlpha.200"
            css={{
              '&::-webkit-scrollbar': {
                width: '8px',
              },
              '&::-webkit-scrollbar-track': {
                background: 'rgba(255, 255, 255, 0.05)',
                borderRadius: '10px',
              },
              '&::-webkit-scrollbar-thumb': {
                background: 'rgba(16, 185, 129, 0.5)',
                borderRadius: '10px',
              },
              '&::-webkit-scrollbar-thumb:hover': {
                background: 'rgba(16, 185, 129, 0.7)',
              },
            }}
          >
            <VStack align="stretch" spacing={3}>
              {messages.map((message) => (
                <HStack
                  key={message.id}
                  align="flex-start"
                  spacing={3}
                  bg={message.role === 'assistant' 
                    ? 'linear-gradient(135deg, rgba(16, 185, 129, 0.15), rgba(5, 150, 105, 0.1))' 
                    : 'rgba(255, 255, 255, 0.08)'}
                  borderRadius="xl"
                  p={4}
                  border="1px solid"
                  borderColor={message.role === 'assistant' ? 'green.400' : 'whiteAlpha.200'}
                  transition="all 0.2s"
                  _hover={{
                    transform: 'translateY(-2px)',
                    boxShadow: message.role === 'assistant' 
                      ? '0 8px 16px rgba(16, 185, 129, 0.2)' 
                      : '0 8px 16px rgba(0, 0, 0, 0.2)',
                  }}
                >
                  <Box
                    p={2}
                    bg={message.role === 'assistant' ? 'green.500' : 'whiteAlpha.200'}
                    borderRadius="lg"
                    flexShrink={0}
                  >
                    <Icon 
                      as={message.role === 'assistant' ? FaRobot : FaUser} 
                      color="white" 
                      boxSize={4}
                    />
                  </Box>
                  <Text 
                    fontSize="sm" 
                    color="white"
                    fontWeight="500"
                    lineHeight="1.6"
                  >
                    {message.content}
                  </Text>
                </HStack>
              ))}
              {isLoading && (
                <HStack 
                  spacing={3} 
                  bg="linear-gradient(135deg, rgba(16, 185, 129, 0.15), rgba(5, 150, 105, 0.1))"
                  borderRadius="xl" 
                  p={4}
                  border="1px solid"
                  borderColor="green.400"
                >
                  <Spinner size="sm" color="green.400" thickness="3px" speed="0.8s" />
                  <Text fontSize="sm" color="green.300" fontWeight="600">
                    Analyzing your items...
                  </Text>
                </HStack>
              )}
            </VStack>
          </Box>

          {/* Pending Questions */}
          {pendingSummary && pendingSummary.length > 0 && (
            <Box 
              bgGradient="linear(to-br, rgba(251, 146, 60, 0.15), rgba(234, 88, 12, 0.1))"
              borderRadius="2xl" 
              p={4} 
              border="2px solid"
              borderColor="orange.400"
            >
              <HStack spacing={2} mb={3}>
                <Icon as={FaRobot} color="orange.300" boxSize={4} />
                <Text fontSize="sm" fontWeight="bold" color="orange.200">
                  Need more details:
                </Text>
              </HStack>
              <VStack align="stretch" spacing={2}>
                {pendingSummary.map((question) => (
                  <Box 
                    key={question.id} 
                    bg="rgba(0,0,0,0.2)" 
                    borderRadius="lg" 
                    p={3}
                    border="1px solid"
                    borderColor="orange.500"
                  >
                    <Text color="white" fontWeight="semibold" fontSize="sm" mb={1}>
                      {question.label}
                    </Text>
                    <Text color="orange.100" fontSize="xs">
                      {question.text}
                    </Text>
                  </Box>
                ))}
              </VStack>
            </Box>
          )}

          {/* Error */}
          {error && (
            <Alert 
              status="error" 
              borderRadius="xl" 
              variant="left-accent"
              bg="rgba(239, 68, 68, 0.1)"
              border="1px solid"
              borderColor="red.500"
            >
              <AlertIcon />
              <Text fontSize="sm" color="white">{error}</Text>
            </Alert>
          )}

          {/* Input Form */}
          <form onSubmit={handleSubmit}>
            <VStack spacing={3} align="stretch">
              <Textarea
                value={input}
                onChange={(event) => setInput(event.target.value)}
                placeholder="e.g., I have 6 three-seater sofas, 2 king beds, and 10 medium boxes..."
                bg="rgba(0, 0, 0, 0.3)"
                backdropFilter="blur(10px)"
                color="white"
                borderColor="green.400"
                borderWidth="2px"
                _placeholder={{ color: 'whiteAlpha.600' }}
                _hover={{ borderColor: 'green.300' }}
                _focus={{ 
                  borderColor: 'green.300',
                  boxShadow: '0 0 0 3px rgba(16, 185, 129, 0.2)',
                }}
                minH={{ base: "100px", md: "90px" }}
                resize="vertical"
                borderRadius="xl"
                fontSize="sm"
                fontWeight="500"
              />
              <Button
                type="submit"
                bgGradient="linear(to-r, green.400, teal.500)"
                color="white"
                isLoading={isLoading}
                leftIcon={<FaPaperPlane />}
                w="full"
                size="lg"
                borderRadius="xl"
                fontWeight="bold"
                boxShadow="0 8px 16px rgba(16, 185, 129, 0.3)"
                _hover={{
                  bgGradient: 'linear(to-r, green.500, teal.600)',
                  transform: 'translateY(-2px)',
                  boxShadow: '0 12px 24px rgba(16, 185, 129, 0.4)',
                }}
                _active={{
                  transform: 'translateY(0)',
                }}
                transition="all 0.2s"
              >
                Ask AI
              </Button>
            </VStack>
          </form>
        </VStack>
      </CardBody>
    </Card>
  );
}

'use client';

/**
 * Step 1: Pickup and Drop-off Addresses
 * Luxury Booking Design
 */

import React, { useMemo, useRef, useCallback } from 'react';
import {
  Box,
  VStack,
  HStack,
  Heading,
  Text,
  Button,
  FormControl,
  FormErrorMessage,
  FormLabel,
  Card,
  CardBody,
  Icon,
  Divider,
  Spinner,
} from '@chakra-ui/react';
import {
  FaArrowRight,
  FaArrowLeft,
} from 'react-icons/fa';
import { UKAddressAutocomplete } from '@/components/address/UKAddressAutocomplete';
import type { FormData } from '../hooks/useBookingForm';


interface AddressesStepProps {
  formData: FormData;
  updateFormData: (step: keyof FormData, data: Partial<FormData[keyof FormData]>) => void;
  errors: Record<string, string>;
  onNext?: () => void;
  onBack?: () => void;
}

export default function AddressesStep({
  formData,
  updateFormData,
  errors,
  onNext,
  onBack,
}: AddressesStepProps) {
  // Track which address card to show
  const [showingDropoff, setShowingDropoff] = React.useState(false);
  
  // Card border radius - use responsive values instead of useBreakpointValue
  const cardBorderRadius = { base: '2xl', md: '3xl' };

  // Validate if can proceed
  const canProceed = formData.step1.pickupAddress && formData.step1.dropoffAddress;
  
  // Ref for smooth scroll to dropoff
  const dropoffRef = useRef<HTMLDivElement>(null);

  const currentPickupProperty = useMemo(() => formData.step1.pickupProperty ?? {}, [formData.step1.pickupProperty]);
  const currentDropoffProperty = useMemo(() => formData.step1.dropoffProperty ?? {}, [formData.step1.dropoffProperty]);

  const parseFloorNumber = (value?: string | number | null): number => {
    if (value === null || value === undefined) {
      return 0;
    }

    if (typeof value === 'number') {
      return Number.isFinite(value) ? Math.max(0, Math.trunc(value)) : 0;
    }

    const trimmed = value.trim().toLowerCase();

    if (!trimmed) {
      return 0;
    }

    if (trimmed === 'ground' || trimmed === 'g' || trimmed === 'gf' || trimmed === 'ground floor') {
      return 0;
    }

    const match = trimmed.match(/(-?\d+)/);
    if (!match) {
      return 0;
    }

    const parsed = parseInt(match[1], 10);
    if (Number.isNaN(parsed)) {
      return 0;
    }

    return Math.max(0, parsed);
  };

  const buildPropertyUpdate = (address: any, existing: any) => {
    const floorFromBuildingDetails = address?.buildingDetails?.floorNumber;
    const floorFromFormatted = address?.formatted?.floor;
    const combinedFloor = floorFromBuildingDetails ?? floorFromFormatted;
    const flatNumber = address?.buildingDetails?.apartmentNumber || address?.formatted?.flatNumber;

    return {
      ...existing,
      floors: parseFloorNumber(combinedFloor),
      hasLift: typeof address?.buildingDetails?.hasElevator === 'boolean'
        ? address.buildingDetails.hasElevator
        : existing?.hasLift ?? false,
      type: address?.buildingDetails?.type || existing?.type || 'house',
      flatNumber: flatNumber || existing?.flatNumber,
    };
  };

  return (
    <Box w="full" pb={8}>
      <VStack spacing={10} w="full" align="stretch">
        {/* Enterprise Header Card */}
        {/* Pickup Card - Enhanced Design */}
        {!showingDropoff && (
          <Card
            bg="linear-gradient(135deg, rgba(15, 23, 42, 0.98) 0%, rgba(30, 41, 59, 0.95) 100%)"
            border="2px solid"
            borderColor="rgba(34, 197, 94, 0.4)"
            borderRadius="3xl"
            backdropFilter="blur(24px)"
            boxShadow="0 25px 60px rgba(0,0,0,0.6), 0 0 80px rgba(34, 197, 94, 0.15)"
            position="relative"
            overflow="hidden"
            transition="all 0.4s cubic-bezier(0.4, 0, 0.2, 1)"
            _hover={{
              borderColor: "rgba(34, 197, 94, 0.6)",
              boxShadow: "0 30px 75px rgba(0,0,0,0.7), 0 0 100px rgba(34, 197, 94, 0.25)",
              transform: "translateY(-4px)",
            }}
            _before={{
              content: '""',
              position: 'absolute',
              top: 0,
              left: 0,
              right: 0,
              height: '4px',
              bgGradient: 'linear(to-r, green.400, emerald.500, teal.400)',
              opacity: 0.8,
            }}
          >
            <CardBody p={{ base: 8, md: 10 }}>
              <VStack spacing={6} align="stretch">
                {/* Header with Enhanced Icon */}
                <HStack spacing={4} mb={2}>
                  <Box
                    w={{ base: "56px", md: "64px" }}
                    h={{ base: "56px", md: "64px" }}
                    borderRadius="2xl"
                    bg="linear-gradient(135deg, rgba(34, 197, 94, 0.2), rgba(16, 185, 129, 0.2))"
                    border="2px solid"
                    borderColor="rgba(34, 197, 94, 0.4)"
                    display="flex"
                    alignItems="center"
                    justifyContent="center"
                    position="relative"
                    boxShadow="0 8px 32px rgba(34, 197, 94, 0.3), inset 0 0 20px rgba(34, 197, 94, 0.1)"
                    _before={{
                      content: '""',
                      position: 'absolute',
                      inset: '-3px',
                      borderRadius: '2xl',
                      padding: '3px',
                      background: 'linear-gradient(135deg, rgba(34, 197, 94, 0.5), rgba(16, 185, 129, 0.5))',
                      WebkitMask: 'linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0)',
                      WebkitMaskComposite: 'xor',
                      maskComposite: 'exclude',
                    }}
                  >
                    <Box 
                      w={{ base: "24px", md: "28px" }} 
                      h={{ base: "24px", md: "28px" }} 
                      borderRadius="full" 
                      bg="linear-gradient(135deg, #22c55e, #10b981)"
                      boxShadow="0 4px 16px rgba(34, 197, 94, 0.6)"
                    />
                  </Box>
                  <VStack spacing={1} align="flex-start" flex={1}>
                    <Text 
                      color="white" 
                      fontWeight="800" 
                      fontSize={{ base: "xl", md: "2xl" }}
                      letterSpacing="tight"
                      bgGradient="linear(to-r, green.300, emerald.400)"
                      bgClip="text"
                    >
                      Pickup Location
                    </Text>
                    <Text 
                      color="whiteAlpha.700" 
                      fontSize={{ base: "sm", md: "md" }}
                      fontWeight="500"
                    >
                      Where should we collect from?
                    </Text>
                  </VStack>
                </HStack>

                {/* Address Input - Enhanced */}
                <Box>
                  <FormControl isInvalid={!!errors['step1.pickupAddress']}>
                    <UKAddressAutocomplete
                      id="pickup-address"
                      label="Pickup Address"
                      value={formData.step1.pickupAddress as any}
                      onChange={(address) => {
                        if (address) {
                          updateFormData('step1', {
                            pickupAddress: address as any,
                            pickupProperty: buildPropertyUpdate(address, currentPickupProperty) as any,
                          });
                        } else {
                          updateFormData('step1', {
                            pickupAddress: {
                              address: '',
                              city: '',
                              postcode: '',
                              coordinates: { lat: 0, lng: 0 },
                              houseNumber: '',
                              flatNumber: '',
                              formatted_address: '',
                              place_name: ''
                            } as any,
                            pickupProperty: {
                              ...currentPickupProperty,
                              floors: 0,
                              hasLift: false,
                              type: currentPickupProperty?.type || 'house',
                            } as any,
                          });
                        }
                      }}
                      placeholder="Enter pickup address, postcode, or location"
                      isRequired={true}
                    />
                    {errors['step1.pickupAddress'] && (
                      <FormErrorMessage color="red.300" mt={2}>
                        {errors['step1.pickupAddress']}
                      </FormErrorMessage>
                    )}
                  </FormControl>
                </Box>

                {/* Next to Dropoff Button */}
                {formData.step1.pickupAddress && (
                  <Button
                    onClick={() => {
                      setShowingDropoff(true);
                    }}
                    bgGradient="linear(to-r, blue.500, purple.500)"
                    color="white"
                    size="lg"
                    w="full"
                    py={6}
                    fontSize="md"
                    fontWeight="600"
                    borderRadius="xl"
                    rightIcon={<Icon as={FaArrowRight} />}
                    boxShadow="0 15px 35px rgba(59, 130, 246, 0.4)"
                    transition="all 0.3s"
                    _hover={{
                      bgGradient: "linear(to-r, blue.600, purple.600)",
                      transform: "translateY(-2px)",
                      boxShadow: "0 20px 45px rgba(59, 130, 246, 0.5)",
                    }}
                    _active={{
                      transform: "translateY(0)",
                    }}
                  >
                    Next: Drop-off Location
                  </Button>
                )}
              </VStack>
            </CardBody>
          </Card>
        )}

        {/* Dropoff Card - Show only when showingDropoff is true */}
        {showingDropoff && (
          <Card
            bg="rgba(15, 23, 42, 0.95)"
            border="2px solid"
            borderColor="rgba(236, 72, 153, 0.4)"
            borderRadius="3xl"
            backdropFilter="blur(20px)"
            boxShadow="0 25px 60px rgba(236, 72, 153, 0.25)"
            transition="all 0.4s cubic-bezier(0.4, 0, 0.2, 1)"
            position="relative"
            overflow="hidden"
            _before={{
              content: '""',
              position: 'absolute',
              top: 0,
              left: 0,
              right: 0,
              height: '3px',
              bgGradient: 'linear(to-r, pink.400, purple.400, blue.400)',
              opacity: 0.8,
            }}
            _hover={{
              borderColor: "rgba(236, 72, 153, 0.6)",
              boxShadow: "0 30px 70px rgba(236, 72, 153, 0.35)",
              transform: "translateY(-2px)",
            }}
          >
            <CardBody p={{ base: 6, md: 8 }}>
              <VStack spacing={5} align="stretch">
                {/* Back to Pickup Button */}
                <Button
                  onClick={() => setShowingDropoff(false)}
                  variant="ghost"
                  color="whiteAlpha.700"
                  size="sm"
                  alignSelf="flex-start"
                  leftIcon={<Icon as={FaArrowLeft} />}
                  borderRadius="lg"
                  _hover={{
                    color: "white",
                    bg: "rgba(236, 72, 153, 0.15)",
                    transform: "translateX(-3px)",
                  }}
                  transition="all 0.2s"
                >
                  Back to Pickup
                </Button>

                {/* Enhanced Header */}
                <HStack spacing={4} mb={2}>
                  <Box
                    position="relative"
                    w="56px"
                    h="56px"
                    borderRadius="2xl"
                    bg="rgba(236, 72, 153, 0.15)"
                    border="2px solid rgba(236, 72, 153, 0.4)"
                    display="flex"
                    alignItems="center"
                    justifyContent="center"
                    _before={{
                      content: '""',
                      position: 'absolute',
                      inset: '-3px',
                      borderRadius: '2xl',
                      padding: '2px',
                      background: 'linear-gradient(135deg, rgba(236, 72, 153, 0.5), rgba(168, 85, 247, 0.5))',
                      mask: 'linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0)',
                      WebkitMask: 'linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0)',
                      maskComposite: 'exclude',
                      WebkitMaskComposite: 'xor',
                    }}
                    _after={{
                      content: '""',
                      position: 'absolute',
                      inset: '-8px',
                      borderRadius: '2xl',
                      background: 'radial-gradient(circle, rgba(236, 72, 153, 0.2) 0%, transparent 70%)',
                      animation: 'pulse 2s ease-in-out infinite',
                    }}
                  >
                    <Box 
                      w="20px" 
                      h="20px" 
                      borderRadius="full" 
                      bg="pink.400"
                      boxShadow="0 0 20px rgba(236, 72, 153, 0.6)"
                    />
                  </Box>
                  <VStack spacing={1} align="flex-start" flex={1}>
                    <Text 
                      color="white" 
                      fontWeight="800" 
                      fontSize="xl"
                      letterSpacing="tight"
                    >
                      Drop-off Location
                    </Text>
                    <Text 
                      color="whiteAlpha.600" 
                      fontSize="sm"
                      fontWeight="500"
                    >
                      Where should we deliver to?
                    </Text>
                  </VStack>
                </HStack>

                {/* Address Input - Enhanced */}
                <Box>
                  <FormControl isInvalid={!!errors['step1.dropoffAddress']}>
                    <UKAddressAutocomplete
                      id="dropoff-address"
                      label="Dropoff Address"
                      value={formData.step1.dropoffAddress as any}
                      onChange={(address) => {
                        if (address) {
                          updateFormData('step1', {
                            dropoffAddress: address as any,
                            dropoffProperty: buildPropertyUpdate(address, currentDropoffProperty) as any,
                          });
                        } else {
                          updateFormData('step1', {
                            dropoffAddress: {
                              address: '',
                              city: '',
                              postcode: '',
                              coordinates: { lat: 0, lng: 0 },
                              houseNumber: '',
                              flatNumber: '',
                              formatted_address: '',
                              place_name: ''
                            } as any,
                            dropoffProperty: {
                              ...currentDropoffProperty,
                              floors: 0,
                              hasLift: false,
                              type: currentDropoffProperty?.type || 'house',
                            } as any,
                          });
                        }
                      }}
                      placeholder="Enter delivery address, postcode, or location"
                      isRequired={true}
                    />
                    {errors['step1.dropoffAddress'] && (
                      <FormErrorMessage color="red.300" mt={2}>
                        {errors['step1.dropoffAddress']}
                      </FormErrorMessage>
                    )}
                  </FormControl>
                </Box>
              </VStack>
            </CardBody>
          </Card>
        )}
      </VStack>

      {/* Continue Button - Always visible when addresses are complete */}
      {onNext && (
        <Button
          onClick={onNext}
          isDisabled={!canProceed}
          bgGradient={canProceed ? "linear(to-r, blue.500, purple.500)" : "linear(to-r, gray.600, gray.700)"}
          color="white"
          size="lg"
          w="full"
          mt={6}
          py={7}
          fontSize="md"
          fontWeight="600"
          borderRadius="xl"
          rightIcon={<Icon as={FaArrowRight} />}
          boxShadow={canProceed ? "0 15px 35px rgba(59, 130, 246, 0.4)" : "none"}
          transition="all 0.3s"
          _hover={canProceed ? {
            bgGradient: "linear(to-r, blue.600, purple.600)",
            transform: "translateY(-2px)",
            boxShadow: "0 20px 45px rgba(59, 130, 246, 0.5)",
          } : {}}
          _active={canProceed ? {
            transform: "translateY(0)",
          } : {}}
          _disabled={{
            opacity: 0.5,
            cursor: 'not-allowed',
            transform: 'none',
          }}
        >
          {canProceed ? 'Continue to Items & Time' : 'Please Enter Both Addresses'}
        </Button>
      )}
    </Box>
  );
}

/**
 * Home Size Selector Component
 * 
 * Provides a user-friendly interface for selecting home size (1-6+ bedrooms)
 * and automatically suggests typical items for that home size.
 */

'use client';

import React, { useState, useEffect } from 'react';
import {
  Box,
  VStack,
  HStack,
  Button,
  Text,
  Badge,
  Card,
  CardBody,
  Icon,
  SimpleGrid,
  Collapse,
  useDisclosure,
  Flex,
  Circle,
  Divider
} from '@chakra-ui/react';
import { FaHome, FaBed, FaUsers, FaChevronDown, FaChevronUp, FaPlus } from 'react-icons/fa';

import { 
  HOME_SIZE_PRESETS, 
  HomeSizePreset, 
  HomeSizeItem,
  getRecommendedItemsWithFallback 
} from '../../../lib/items/home-size-presets';

import type { Item } from '../../../lib/booking/utils';

interface HomeSizeSelectorProps {
  selectedHomeSize?: string;
  onHomeSizeChange: (homeSizeId: string | null) => void;
  onAddPresetItems: (items: Item[]) => void;
  availableItems: Item[];
  selectedItems: Item[];
}

export default function HomeSizeSelector({
  selectedHomeSize,
  onHomeSizeChange,
  onAddPresetItems,
  availableItems,
  selectedItems
}: HomeSizeSelectorProps) {
  const [showPresetItems, setShowPresetItems] = useState(false);
  const { isOpen: isPreviewOpen, onToggle: togglePreview } = useDisclosure();

  // Get current preset
  const currentPreset = selectedHomeSize 
    ? HOME_SIZE_PRESETS.find(preset => preset.id === selectedHomeSize)
    : null;

  // Get recommended items for current home size
  const recommendedItems = currentPreset 
    ? getRecommendedItemsWithFallback(currentPreset.id, availableItems, 20)
    : [];

  // Separate items by priority for better UX
  const essentialItems = recommendedItems.filter(item => item.priority === 1);
  const commonItems = recommendedItems.filter(item => item.priority === 2);
  const optionalItems = recommendedItems.filter(item => item.priority === 3);

  // Handle home size selection
  const handleHomeSizeSelect = (preset: HomeSizePreset) => {
    if (selectedHomeSize === preset.id) {
      // Deselect if clicking the same preset
      onHomeSizeChange(null);
      setShowPresetItems(false);
    } else {
      onHomeSizeChange(preset.id);
      setShowPresetItems(true);
    }
  };

  // Handle adding preset items
  const handleAddPresetItems = (priority?: number) => {
    if (!currentPreset) return;

    const itemsToAdd = priority 
      ? recommendedItems.filter(item => item.priority === priority)
      : essentialItems; // Default to essential items

    const processedItems: Item[] = itemsToAdd.map(item => ({
      id: item.id,
      name: item.name,
      category: item.category,
      description: item.description || `${item.name} for ${currentPreset.name.toLowerCase()}`,
      size: item.size || 'medium',
      weight: item.weight || 25,
      volume: item.volume || 1.0,
      unitPrice: item.unitPrice || 25,
      quantity: item.suggestedQuantity || 1,
      totalPrice: (item.unitPrice || 25) * (item.suggestedQuantity || 1),
      image: item.image || ''
    }));

    onAddPresetItems(processedItems);
  };

  return (
    <Card bg="white" borderRadius="xl" p={6} shadow="md" borderWidth="2px" borderColor="blue.200">
      <VStack spacing={6} align="stretch">
        {/* Header */}
        <VStack spacing={3} align="center">
          <HStack spacing={3}>
            <Circle size="50px" bg="blue.500" color="white">
              <Icon as={FaHome} boxSize={6} />
            </Circle>
            <VStack align="start" spacing={1}>
              <Text fontSize="xl" fontWeight="bold" color="gray.800">
                🏠 Select Your Home Size
              </Text>
              <Text fontSize="sm" color="gray.600">
                Get personalized item suggestions for your move
              </Text>
            </VStack>
          </HStack>
          
          <Text fontSize="sm" color="blue.600" textAlign="center" bg="blue.50" px={4} py={2} borderRadius="md">
            💡 Choose your home size to see typical items you might need to move
          </Text>
        </VStack>

        {/* Home Size Selection Grid */}
        <SimpleGrid columns={{ base: 2, md: 3, lg: 6 }} spacing={3}>
          {HOME_SIZE_PRESETS.map((preset) => (
            <Button
              key={preset.id}
              variant={selectedHomeSize === preset.id ? 'solid' : 'outline'}
              colorScheme={selectedHomeSize === preset.id ? 'blue' : 'gray'}
              size="lg"
              h="80px"
              flexDirection="column"
              onClick={() => handleHomeSizeSelect(preset)}
              _hover={{
                bg: selectedHomeSize === preset.id ? 'blue.600' : 'gray.50',
                transform: 'translateY(-2px)',
                shadow: 'lg'
              }}
              _active={{
                transform: 'translateY(0px)',
                shadow: 'md'
              }}
              transition="all 0.2s ease"
              borderWidth="2px"
              borderRadius="xl"
              position="relative"
            >
              <VStack spacing={1}>
                <Text fontSize="2xl">{preset.icon}</Text>
                <Text fontSize="xs" fontWeight="bold" textAlign="center" lineHeight="1.2">
                  {preset.name}
                </Text>
              </VStack>
              
              {selectedHomeSize === preset.id && (
                <Badge
                  position="absolute"
                  top="-8px"
                  right="-8px"
                  colorScheme="green"
                  variant="solid"
                  borderRadius="full"
                  fontSize="xs"
                >
                  ✓
                </Badge>
              )}
            </Button>
          ))}
        </SimpleGrid>

        {/* Selected Home Size Info & Actions */}
        {currentPreset && (
          <VStack spacing={4} align="stretch">
            <Divider />
            
            <Card bg="blue.50" borderColor="blue.200" borderWidth="1px">
              <CardBody>
                <VStack spacing={4} align="stretch">
                  <HStack justify="space-between" align="start">
                    <VStack align="start" spacing={2} flex="1">
                      <HStack spacing={3}>
                        <Text fontSize="2xl">{currentPreset.icon}</Text>
                        <VStack align="start" spacing={0}>
                          <Text fontSize="lg" fontWeight="bold" color="blue.800">
                            {currentPreset.name} Selected
                          </Text>
                          <Text fontSize="sm" color="blue.600">
                            {currentPreset.description}
                          </Text>
                        </VStack>
                      </HStack>

                      <HStack spacing={4} wrap="wrap">
                        <Badge colorScheme="blue" variant="subtle">
                          <HStack spacing={1}>
                            <Icon as={FaBed} boxSize={3} />
                            <Text>{currentPreset.bedrooms} bedroom{currentPreset.bedrooms > 1 ? 's' : ''}</Text>
                          </HStack>
                        </Badge>
                        <Badge colorScheme="green" variant="subtle">
                          <HStack spacing={1}>
                            <Icon as={FaPlus} boxSize={3} />
                            <Text>{essentialItems.length} essential items</Text>
                          </HStack>
                        </Badge>
                        <Badge colorScheme="purple" variant="subtle">
                          <HStack spacing={1}>
                            <Icon as={FaUsers} boxSize={3} />
                            <Text>{recommendedItems.length} total suggestions</Text>
                          </HStack>
                        </Badge>
                      </HStack>
                    </VStack>

                    <Button
                      size="sm"
                      variant="ghost"
                      colorScheme="blue"
                      onClick={togglePreview}
                      rightIcon={<Icon as={isPreviewOpen ? FaChevronUp : FaChevronDown} />}
                    >
                      {isPreviewOpen ? 'Hide' : 'Preview'} Items
                    </Button>
                  </HStack>

                  {/* Quick Add Buttons */}
                  <HStack spacing={3} wrap="wrap">
                    <Button
                      size="md"
                      colorScheme="green"
                      variant="solid"
                      onClick={() => handleAddPresetItems(1)}
                      leftIcon={<Icon as={FaPlus} />}
                      _hover={{ bg: 'green.600', transform: 'translateY(-1px)' }}
                      borderRadius="lg"
                    >
                      Add Essential Items ({essentialItems.length})
                    </Button>
                    
                    {commonItems.length > 0 && (
                      <Button
                        size="md"
                        colorScheme="blue"
                        variant="outline"
                        onClick={() => handleAddPresetItems(2)}
                        leftIcon={<Icon as={FaPlus} />}
                        _hover={{ bg: 'blue.50' }}
                        borderRadius="lg"
                      >
                        Add Common Items ({commonItems.length})
                      </Button>
                    )}
                  </HStack>

                  {/* Item Preview */}
                  <Collapse in={isPreviewOpen} animateOpacity>
                    <VStack spacing={4} align="stretch" mt={4}>
                      <Divider />
                      
                      {/* Essential Items */}
                      {essentialItems.length > 0 && (
                        <VStack spacing={3} align="stretch">
                          <HStack spacing={2}>
                            <Badge colorScheme="green" variant="solid" fontSize="xs">
                              Essential
                            </Badge>
                            <Text fontSize="sm" fontWeight="medium" color="gray.700">
                              Must-have items for {currentPreset.name.toLowerCase()}
                            </Text>
                          </HStack>
                          
                          <SimpleGrid columns={{ base: 1, md: 2 }} spacing={2}>
                            {essentialItems.slice(0, 6).map((item) => (
                              <HStack 
                                key={item.id} 
                                spacing={2} 
                                p={2} 
                                bg="green.50" 
                                borderRadius="md"
                                fontSize="sm"
                              >
                                <Badge size="sm" colorScheme="green" variant="outline">
                                  {item.suggestedQuantity || 1}x
                                </Badge>
                                <Text flex="1" fontSize="sm" color="gray.700">
                                  {item.name}
                                </Text>
                                {item.room && (
                                  <Text fontSize="xs" color="gray.500">
                                    {item.room}
                                  </Text>
                                )}
                              </HStack>
                            ))}
                            {essentialItems.length > 6 && (
                              <Text fontSize="xs" color="gray.500" textAlign="center" gridColumn="1 / -1">
                                +{essentialItems.length - 6} more essential items
                              </Text>
                            )}
                          </SimpleGrid>
                        </VStack>
                      )}

                      {/* Common Items */}
                      {commonItems.length > 0 && (
                        <VStack spacing={3} align="stretch">
                          <HStack spacing={2}>
                            <Badge colorScheme="blue" variant="solid" fontSize="xs">
                              Common
                            </Badge>
                            <Text fontSize="sm" fontWeight="medium" color="gray.700">
                              Typical additional items
                            </Text>
                          </HStack>
                          
                          <SimpleGrid columns={{ base: 1, md: 2 }} spacing={2}>
                            {commonItems.slice(0, 4).map((item) => (
                              <HStack 
                                key={item.id} 
                                spacing={2} 
                                p={2} 
                                bg="blue.50" 
                                borderRadius="md"
                                fontSize="sm"
                              >
                                <Badge size="sm" colorScheme="blue" variant="outline">
                                  {item.suggestedQuantity || 1}x
                                </Badge>
                                <Text flex="1" fontSize="sm" color="gray.700">
                                  {item.name}
                                </Text>
                              </HStack>
                            ))}
                            {commonItems.length > 4 && (
                              <Text fontSize="xs" color="gray.500" textAlign="center" gridColumn="1 / -1">
                                +{commonItems.length - 4} more common items
                              </Text>
                            )}
                          </SimpleGrid>
                        </VStack>
                      )}

                      <Text fontSize="xs" color="gray.500" textAlign="center" fontStyle="italic">
                        💡 You can always add, remove, or adjust quantities after adding preset items
                      </Text>
                    </VStack>
                  </Collapse>
                </VStack>
              </CardBody>
            </Card>
          </VStack>
        )}

        {/* Help Text */}
        <Text fontSize="xs" color="gray.500" textAlign="center" fontStyle="italic">
          Can't find your home size? Choose the closest match or use "All Items" to browse manually
        </Text>
      </VStack>
    </Card>
  );
}

/**
 * Natural Language Processing Results Display
 * Shows parsed items from natural language input with bulk add functionality
 */

import React from 'react';
import {
  Box,
  VStack,
  HStack,
  Text,
  Button,
  Badge,
  Flex,
  Icon,
  Divider,
  Alert,
  AlertIcon,
  AlertDescription,
  IconButton
} from '@chakra-ui/react';
import { FaPlus, FaCheckCircle, FaBrain, FaTimes } from 'react-icons/fa';
import { parseNaturalLanguage, type ParseResult, type ParsedItem } from '../../../lib/search/natural-language-parser';
import type { Item } from '../hooks/useBookingForm';

interface NLPResultsDisplayProps {
  query: string;
  onAddItems: (items: Item[]) => void;
  onAddSingleItem: (item: Item) => void;
  onClose: () => void; // New prop to close the analysis
  selectedItems: Item[];
}

export const NLPResultsDisplay: React.FC<NLPResultsDisplayProps> = ({
  query,
  onAddItems,
  onAddSingleItem,
  onClose,
  selectedItems
}) => {
  const parseResult = parseNaturalLanguage(query);
  
  if (parseResult.items.length === 0) {
    return null;
  }

  // Convert parsed items to Item format
  const convertToItems = (parsedItems: ParsedItem[]): Item[] => {
    return parsedItems.map(parsed => ({
      id: parsed.item.id,
      name: parsed.item.name,
      description: `${parsed.item.name} - ${parsed.item.keywords[0]}`,
      category: parsed.item.category as any,
      size: parsed.item.volume > 1.5 ? 'large' : parsed.item.volume > 0.5 ? 'medium' : 'small',
      quantity: parsed.quantity,
      unitPrice: Math.round(parsed.item.volume * 20 + parsed.item.weight * 0.5),
      totalPrice: Math.round((parsed.item.volume * 20 + parsed.item.weight * 0.5) * parsed.quantity),
      weight: parsed.item.weight,
      volume: parsed.item.volume,
      image: `/items/${parsed.item.category}/${parsed.item.id}.png`,
    }));
  };

  const itemsToAdd = convertToItems(parseResult.items);
  const totalItems = parseResult.items.reduce((sum, item) => sum + item.quantity, 0);
  const averageConfidence = parseResult.totalConfidence;

  // Check which items are already selected
  const getItemStatus = (itemId: string): { isSelected: boolean; currentQuantity: number } => {
    const existing = selectedItems.find(item => item.id === itemId);
    return {
      isSelected: !!existing,
      currentQuantity: existing?.quantity || 0
    };
  };

  const handleAddAllItems = () => {
    onAddItems(itemsToAdd);
  };

  const handleAddSingleItem = (parsedItem: ParsedItem) => {
    const item = convertToItems([parsedItem])[0];
    onAddSingleItem(item);
  };

  return (
    <Box
      bg="white"
      border="2px solid"
      borderColor="blue.200"
      borderRadius="xl"
      p={4}
      boxShadow="lg"
      w="90%"
      mx="auto"
      mt={2}
    >
      {/* Header */}
      <HStack spacing={2} mb={3} justify="space-between">
        <HStack spacing={2}>
          <Icon as={FaBrain} color="blue.500" />
          <Text fontWeight="bold" color="blue.700" fontSize="sm">
            Smart Text Analysis
          </Text>
          <Badge colorScheme="blue" variant="subtle">
            {Math.round(averageConfidence)}% confidence
          </Badge>
        </HStack>
        
        <IconButton
          size="xs"
          aria-label="Close analysis"
          icon={<Icon as={FaTimes} />}
          colorScheme="gray"
          variant="ghost"
          onClick={onClose}
          _hover={{ bg: "gray.100" }}
        />
      </HStack>

      {/* Confidence Alert */}
      {averageConfidence > 80 ? (
        <Alert status="success" size="sm" borderRadius="md" mb={3}>
          <AlertIcon />
          <AlertDescription fontSize="xs">
            Found {parseResult.items.length} items ({totalItems} total pieces) in your message
          </AlertDescription>
        </Alert>
      ) : (
        <Alert status="info" size="sm" borderRadius="md" mb={3}>
          <AlertIcon />
          <AlertDescription fontSize="xs">
            Found {parseResult.items.length} possible items - please review before adding
          </AlertDescription>
        </Alert>
      )}

      {/* Parsed Items */}
      <VStack spacing={2} align="stretch">
        {parseResult.items.map((parsedItem, index) => {
          const status = getItemStatus(parsedItem.item.id);
          
          return (
            <Box
              key={`${parsedItem.item.id}-${index}`}
              p={2}
              bg={status.isSelected ? "green.50" : "gray.50"}
              borderRadius="md"
              border="1px solid"
              borderColor={status.isSelected ? "green.200" : "gray.200"}
            >
              <Flex justify="space-between" align="center">
                <HStack spacing={2} flex={1}>
                  <Text fontSize="sm" fontWeight="medium" color="gray.800">
                    {parsedItem.quantity}× {parsedItem.item.name}
                  </Text>
                  <Badge
                    size="sm"
                    colorScheme={
                      parsedItem.confidence > 90 ? 'green' :
                      parsedItem.confidence > 75 ? 'blue' : 'yellow'
                    }
                    variant="subtle"
                  >
                    {Math.round(parsedItem.confidence)}%
                  </Badge>
                  <Badge size="sm" colorScheme="gray" variant="outline">
                    {parsedItem.item.category}
                  </Badge>
                  {status.isSelected && (
                    <Badge size="sm" colorScheme="green">
                      <Icon as={FaCheckCircle} mr={1} />
                      Selected ({status.currentQuantity})
                    </Badge>
                  )}
                </HStack>
                
                <Button
                  size="xs"
                  colorScheme={status.isSelected ? "green" : "blue"}
                  variant={status.isSelected ? "outline" : "solid"}
                  leftIcon={<Icon as={FaPlus} />}
                  onClick={() => handleAddSingleItem(parsedItem)}
                >
                  {status.isSelected ? 'Add More' : 'Add'}
                </Button>
              </Flex>
              
              {/* Item Details */}
              <HStack spacing={2} mt={1}>
                <Text fontSize="xs" color="gray.500">
                  Matched: "{parsedItem.matchedText}"
                </Text>
                <Text fontSize="xs" color="gray.500">
                  {parsedItem.item.weight}kg • {parsedItem.item.volume}m³
                </Text>
              </HStack>
            </Box>
          );
        })}
      </VStack>

      <Divider my={3} />

      {/* Bulk Actions */}
      <Flex justify="space-between" align="center">
        <VStack align="start" spacing={0}>
          <Text fontSize="sm" fontWeight="medium" color="gray.700">
            Total: {totalItems} items
          </Text>
          <Text fontSize="xs" color="gray.500">
            From: "{parseResult.originalText.substring(0, 50)}..."
          </Text>
        </VStack>
        
        <HStack spacing={2}>
          <Button
            colorScheme="gray"
            size="sm"
            variant="outline"
            onClick={onClose}
          >
            Done
          </Button>
          <Button
            colorScheme="blue"
            size="sm"
            leftIcon={<Icon as={FaPlus} />}
            onClick={handleAddAllItems}
            isDisabled={parseResult.items.length === 0}
          >
            Add All Items
          </Button>
        </HStack>
      </Flex>
    </Box>
  );
};

