    'shower': 102,
    'shower enclosure': 102,
    'toilet': 103,
    'sink': 104,
    'basin': 104,
    'vanity': 105,
    'bathroom cabinet': 106,
    'medicine cabinet': 107,
    'towel rack': 108,
    'towel rail': 108,
    
    // Office items (121-140)
    'desk': 121,
    'office desk': 121,
    'workstation': 121,
    'office chair': 122,
    'filing cabinet': 124,
    'file cabinet': 124,
    'drawer unit': 125,
    'computer': 128,
    'monitor': 129,
    'printer': 130,
    'scanner': 131,
    'shredder': 132,
    
    // Garden/Outdoor items (141-160)
    'patio set': 141,
    'patio': 141,
    'garden furniture': 142,
    'garden': 142,
    'outdoor table': 143,
    'outdoor chair': 144,
    'bbq': 145,
    'grill': 145,
    'barbecue': 145,
    'outdoor furniture': 146,
    'sun lounger': 147,
    'parasol': 148,
    'umbrella': 148,
    'bike': 149,
    'bicycle': 149,
    'lawnmower': 150,
    'lawn mower': 150,
    'shed': 151,
    'plant pot': 152,
    'planter': 152,
    
    // Boxes & Packaging (161-180)
    'box': 161,
    'small box': 161,
    'medium box': 162,
    'large box': 163,
    'wardrobe box': 164,
    'container': 165,
    'storage box': 166,
    'crate': 167,
    'packing': 168,
  };

  // Get item type order based on name
  const getItemType = (itemName: string): number => {
    const nameLower = itemName.toLowerCase();
    
    // Sort type keys by length (longest first) for better matching
    const sortedTypeKeys = Object.keys(ITEM_TYPE_HIERARCHY).sort((a, b) => b.length - a.length);
    
    for (const typeKey of sortedTypeKeys) {
      if (nameLower.includes(typeKey)) {
        return ITEM_TYPE_HIERARCHY[typeKey];
      }
    }
    
    // Default order for unknown types
    return 9999;
  };

  // Map items to rooms based on their category
  const getItemsForRoom = useCallback((roomId: string): RemovalItem[] => {
    const categoryMap: Record<string, string[]> = {
      'bedroom': ['Bedroom', 'Wardrobes'],
      'living': ['Living Room'],
      'dining': ['Dining Room'],
      'kitchen': ['Kitchen'],
      'bathroom': ['Bathroom'],
      'garden': ['Garden & Outdoor'],
      'office': ['Office', 'Electronics'],
      'boxes': ['Boxes & Packaging', 'Miscellaneous'],
    };

    const categories = categoryMap[roomId] || [];
    const filteredItems = availableItems.filter(item => 
      categories.some(cat => item.category.toLowerCase().includes(cat.toLowerCase()))
    );

    // Sort items by type first, then by size within each type
    const sortedItems = filteredItems.sort((a, b) => {
      // First: Sort by item type
      const typeA = getItemType(a.name);
      const typeB = getItemType(b.name);
      
      if (typeA !== typeB) {
        return typeA - typeB;
      }
      
      // Second: Sort by size within the same type
      const sizeA = getSizeOrder(a.name);
      const sizeB = getSizeOrder(b.name);
      
      if (sizeA !== 999 && sizeB !== 999) {
        return sizeA - sizeB;
      }
      
      // If only one has a size order, prioritize it
      if (sizeA !== 999) return -1;
      if (sizeB !== 999) return 1;
      
      // Third: Sort alphabetically as final fallback
      return a.name.localeCompare(b.name);
    });

    console.log(`🔄 Sorted ${roomId} items:`, sortedItems.map((item, idx) => ({
      position: idx + 1,
      name: item.name,
      type: getItemType(item.name),
      size: getSizeOrder(item.name)
    })));

    return sortedItems;
  }, [availableItems]);

  // Size hierarchy - determines ordering from smallest to largest
  const SIZE_HIERARCHY: Record<string, number> = {
    // Beds & Mattresses (smallest to largest)
    'cot': 0,
    'toddler bed': 0.5,
    'single bed': 1,
    'single': 1,
    'small single': 1.5,
    'twin bed': 2,
    'twin': 2,
    'double bed': 3,
    'double': 3,
    'queen bed': 3.5,
    'queen': 3.5,
    'king bed': 4,
    'king size bed': 4,
    'king size': 4,
    'king': 4,
    'super king bed': 5,
    'super king size bed': 5,
    'super king size': 5,
    'super king': 5,
    'california king': 5.5,
    'bunk bed': 6,
    'bunk': 6,
    
    // Sofas & Seating
    '1 seat': 1,
    '2 seat': 2,
    '3 seat': 3,
    '4 seat': 4,
    'corner': 5,
    'corner sofa': 5,
    'l-shaped': 5,
    
    // Fridges & Appliances
    'small': 1,
    'compact': 1,
    'medium': 2,
    'standard': 2,
    'large': 3,
    'american': 4,
    'american style': 4,
    'american size': 4,
    
    // Tables
    '2 seater': 1,
    '4 seater': 2,
    '6 seater': 3,
    '8 seater': 4,
    
    // Boxes
    'box - small': 1,
    'box small': 1,
    'box - medium': 2,
    'box medium': 2,
    'box - large': 3,
    'box large': 3,
  };

  // Common items - prioritize these in search results
  const COMMON_ITEMS = [
    'sofa', 'couch', 'chair', 'table', 'bed', 'mattress', 'tv', 'desk',
    'wardrobe', 'drawer', 'box', 'fridge', 'washing machine', 'bookcase',
    'dining table', 'mirror', 'lamp', 'shelving unit', 'coffee table'
  ];

  // Get size order for an item
  const getSizeOrder = (itemName: string): number => {
    const nameLower = itemName.toLowerCase();
    
    // Sort size keys by length (longest first) to match "super king size" before "king"
    const sortedSizeKeys = Object.keys(SIZE_HIERARCHY).sort((a, b) => b.length - a.length);
    
    // Check for exact matches or partial matches in SIZE_HIERARCHY
    for (const sizeKey of sortedSizeKeys) {
      if (nameLower.includes(sizeKey)) {
        return SIZE_HIERARCHY[sizeKey];
      }
    }
    
    // Default order for items without explicit size
    return 999;
  };

  // Filter items by search query - Smart search with synonyms and relevance scoring
  const filterItemsBySearch = useCallback((items: RemovalItem[]): RemovalItem[] => {
    if (!searchQuery.trim()) {
      return items;
    }
    
    const query = searchQuery.toLowerCase().trim();
    
    // Expand query with synonyms for better matching
    const synonyms: Record<string, string[]> = {
      'sofa': ['couch', 'settee', 'divan', 'lounger'],
      'couch': ['sofa', 'settee'],
      'tv': ['television', 'telly', 'screen'],
      'fridge': ['refrigerator', 'freezer', 'cooler'],
      'desk': ['table', 'workstation', 'bureau'],
      'chair': ['seat', 'stool'],
      'bed': ['mattress', 'cot', 'bunk'],
      'wardrobe': ['closet', 'armoire', 'cupboard'],
      'drawer': ['chest', 'dresser', 'cabinet'],
      'lamp': ['light', 'lighting', 'fixture'],
      'box': ['container', 'crate', 'storage'],
      'table': ['desk', 'surface'],
      'mirror': ['glass'],
      'curtain': ['drape', 'blind'],
      'rug': ['carpet', 'mat'],
      'shelf': ['shelving', 'bookcase', 'rack'],
      'bike': ['bicycle', 'cycle'],
      'computer': ['pc', 'laptop', 'desktop'],
    };
    
    // Get all search terms (original + synonyms)
    const searchTerms = new Set<string>([query]);
    const queryWords = query.split(/\s+/);
    
    queryWords.forEach(word => {
      searchTerms.add(word);
      // Add synonyms
      Object.entries(synonyms).forEach(([key, syns]) => {
        if (key === word || syns.includes(word)) {
          searchTerms.add(key);
          syns.forEach(syn => searchTerms.add(syn));
        }
      });
    });
    
    // Score each item
    const scoredItems = items.map(item => {
      let score = 0;
      const itemName = item.name.toLowerCase();
      const itemCategory = item.category.toLowerCase();
      const itemId = item.id.toLowerCase();
      const itemType = getItemType(item.name);
      
      // Check if this is a common item - boost score significantly
      const isCommonItem = COMMON_ITEMS.some(common => 
        itemName.includes(common) || itemId.includes(common.replace(/\s+/g, '-'))
      );
      if (isCommonItem) score += 2000;
      
      // Check each search term
      Array.from(searchTerms).forEach(term => {
        // Exact match in name (highest priority)
        if (itemName === term) score += 1000;
        
        // Contains full query
        if (itemName.includes(query)) score += 500;
        if (itemCategory.includes(query)) score += 300;
        
        // Word match
        const nameWords = itemName.split(/\s+/);
        if (nameWords.includes(term)) score += 100;
        if (itemName.includes(term)) score += 50;
        if (itemCategory.includes(term)) score += 30;
        if (itemId.includes(term)) score += 20;
        
        // Starts with
        if (itemName.startsWith(term)) score += 60;
        if (nameWords.some(w => w.startsWith(term))) score += 40;
      });
      
      return { item, score, itemType: getItemType(item.name), sizeOrder: getSizeOrder(item.name) };
    });
    
    // Filter items with score > 0, then sort by score DESC, type, and size order ASC
    return scoredItems
      .filter(({ score }) => score > 0)
      .sort((a, b) => {
        // First sort by relevance score (higher is better)
        if (b.score !== a.score) {
          return b.score - a.score;
        }
        // Then sort by item type
        if (a.itemType !== b.itemType) {
          return a.itemType - b.itemType;
        }
        // Then sort by size order (smaller first)
        return a.sizeOrder - b.sizeOrder;
      })
      .map(({ item }) => item);
  }, [searchQuery]);

  // Get quantity for an item
  const getItemQuantity = (itemId: string): number => {
    const selected = selectedItems.find(i => i.id === itemId);
    return selected?.quantity || 0;
  };

  // Calculate total items per room
  const getRoomItemCount = (roomId: string): number => {
    return selectedItems.filter(item => item.room === roomId).length;
  };

  // Get readable type name for grouping
  const getTypeName = (item: RemovalItem): string => {
    const nameLower = item.name.toLowerCase();
    
    // Bedroom types
    if (nameLower.includes('bed') && !nameLower.includes('bedside')) return 'Beds & Mattresses';
    if (nameLower.includes('mattress')) return 'Beds & Mattresses';
    if (nameLower.includes('wardrobe') || nameLower.includes('closet') || nameLower.includes('armoire')) return 'Wardrobes & Storage';
    if (nameLower.includes('dresser') || nameLower.includes('chest')) return 'Dressers & Drawers';
    if (nameLower.includes('nightstand') || nameLower.includes('bedside')) return 'Bedside Tables';
    
    // Living Room types
    if (nameLower.includes('sofa') || nameLower.includes('couch') || nameLower.includes('sectional') || nameLower.includes('loveseat')) return 'Sofas & Couches';
    if (nameLower.includes('chair') && !nameLower.includes('dining')) return 'Chairs & Seating';
    if (nameLower.includes('table') && !nameLower.includes('dining')) return 'Tables';
    if (nameLower.includes('tv') || nameLower.includes('television') || nameLower.includes('entertainment')) return 'TV & Entertainment';
    if (nameLower.includes('bookcase') || nameLower.includes('bookshelf') || nameLower.includes('shelving')) return 'Shelving & Storage';
    
    // Dining Room types
    if (nameLower.includes('dining table')) return 'Dining Tables';
    if (nameLower.includes('dining chair') || (nameLower.includes('chair') && item.category.toLowerCase().includes('dining'))) return 'Dining Chairs';
    if (nameLower.includes('sideboard') || nameLower.includes('buffet') || nameLower.includes('china cabinet')) return 'Storage & Display';
    
    // Kitchen types
    if (nameLower.includes('fridge') || nameLower.includes('refrigerator') || nameLower.includes('freezer')) return 'Refrigeration';
    if (nameLower.includes('oven') || nameLower.includes('stove') || nameLower.includes('range') || nameLower.includes('cooker')) return 'Cooking Appliances';
    if (nameLower.includes('washing') || nameLower.includes('washer') || nameLower.includes('dryer') || nameLower.includes('dishwasher')) return 'Laundry & Cleaning';
    if (nameLower.includes('mixer') || nameLower.includes('blender') || nameLower.includes('toaster') || nameLower.includes('kettle')) return 'Small Appliances';
    
    // Bathroom types
    if (nameLower.includes('bath') || nameLower.includes('shower')) return 'Bath & Shower';
    if (nameLower.includes('toilet') || nameLower.includes('sink') || nameLower.includes('basin')) return 'Sanitary Fixtures';
    if (nameLower.includes('vanity') || nameLower.includes('cabinet')) return 'Storage & Vanity';
    
    // Office types
    if (nameLower.includes('desk')) return 'Desks & Workstations';
    if (nameLower.includes('chair') && item.category.toLowerCase().includes('office')) return 'Office Chairs';
    if (nameLower.includes('filing') || nameLower.includes('cabinet')) return 'Filing & Storage';
    if (nameLower.includes('computer') || nameLower.includes('monitor') || nameLower.includes('printer')) return 'Electronics';
    
    // Garden types
    if (nameLower.includes('patio') || nameLower.includes('garden') || nameLower.includes('outdoor')) return 'Outdoor Furniture';
    if (nameLower.includes('bbq') || nameLower.includes('grill')) return 'BBQ & Grills';
    if (nameLower.includes('bike') || nameLower.includes('bicycle') || nameLower.includes('lawnmower')) return 'Garden Equipment';
    
    // Boxes
    if (nameLower.includes('box') || nameLower.includes('container') || nameLower.includes('crate')) return 'Boxes & Containers';
    
    // Default
    return 'Other Items';
  };

  // Group items by type
  const groupItemsByType = (items: RemovalItem[]): Map<string, RemovalItem[]> => {
    const grouped = new Map<string, RemovalItem[]>();
    
    items.forEach(item => {
      const typeName = getTypeName(item);
      if (!grouped.has(typeName)) {
        grouped.set(typeName, []);
      }
      grouped.get(typeName)!.push(item);
    });
    
    return grouped;
  };

  const currentRoomItems = useMemo(() => {
    // If there's a search query, search across ALL items, not just current room
    if (searchQuery.trim()) {
      return filterItemsBySearch(availableItems);
    }
    
    // Otherwise, show only items for the current room
    const roomItems = getItemsForRoom(selectedRoom);
    return roomItems;
  }, [selectedRoom, searchQuery, getItemsForRoom, filterItemsBySearch, availableItems]);

  const groupedCurrentRoomItems = useMemo(() => {
    return groupItemsByType(currentRoomItems);
  }, [currentRoomItems]);

  // Toggle category open/close
  const toggleCategory = (categoryKey: string) => {
    setOpenCategories(prev => {
      const newSet = new Set(prev);
      if (newSet.has(categoryKey)) {
        newSet.delete(categoryKey);
      } else {
        newSet.add(categoryKey);
      }
      return newSet;
    });
  };

  // Check if category is open
  const isCategoryOpen = (categoryKey: string): boolean => {
    return openCategories.has(categoryKey);
  };

  // Expand all categories
  const expandAllCategories = () => {
    const allCategories = Array.from(groupedCurrentRoomItems.keys()).map(
      typeName => `${selectedRoom}-${typeName}`
    );
    setOpenCategories(new Set(allCategories));
  };

  // Collapse all categories
  const collapseAllCategories = () => {
    setOpenCategories(new Set());
  };

  const selectionStats = useMemo(() => {
    if (!selectedItems.length) {
      return { totalItems: 0, totalWeight: 0, roomBreakdown: [] as Array<{ roomId: string; quantity: number }> };
    }

    const roomMap = new Map<string, number>();
    let totalItems = 0;
    let totalWeight = 0;

    selectedItems.forEach((item) => {
      totalItems += item.quantity;
      totalWeight += item.quantity * item.weight;
      roomMap.set(item.room, (roomMap.get(item.room) || 0) + item.quantity);
    });

    const roomBreakdown = Array.from(roomMap.entries())
      .map(([roomId, quantity]) => ({ roomId, quantity }))
      .sort((a, b) => b.quantity - a.quantity);

    return { totalItems, totalWeight, roomBreakdown };
  }, [selectedItems]);

  const getRoomLabel = useCallback((roomId: string) => {
    const room = ROOM_CATEGORY_LOOKUP[roomId];
    if (!room) return roomId;
    return room.name;
  }, []);

  return (
    <Box position="relative">
      <VStack spacing={6} align="stretch">
        {/* Floating Green Button for Selected Items */}
        {selectedItems.length > 0 && (
          <>
            <Box
              position="fixed"
              bottom={{ base: '180px', md: '200px' }}
              right={{ base: '20px', md: '30px' }}
              zIndex={1500}
            >
              <VStack
                as="button"
                onClick={toggleSummary}
                bg="black"
                color="white"
                borderRadius="2xl"
                w={{ base: '85px', md: '95px' }}
                h={{ base: '85px', md: '95px' }}
                spacing={1}
                justify="center"
                cursor="pointer"
                boxShadow="0 8px 24px rgba(0, 0, 0, 0.5), 0 0 0 2px white"
                transition="all 0.3s cubic-bezier(0.4, 0, 0.2, 1)"
                border="3px solid white"
                _hover={{
                  transform: 'scale(1.1)',
                  boxShadow: '0 12px 32px rgba(0, 0, 0, 0.7), 0 0 0 3px white'
                }}
                _active={{
                  transform: 'scale(1.05)'
                }}
              >
                {/* Toggle Icon */}
                <Icon 
                  as={isSummaryExpanded ? FaTimes : FaChevronUp} 
                  boxSize={{ base: 6, md: 7 }} 
                  color="white"
                  filter="drop-shadow(0 2px 4px rgba(0,0,0,0.3))"
                />
                
                {/* Items Count */}
                <HStack spacing={1}>
                  <Icon as={FaBox} boxSize={{ base: 3, md: 4 }} />
                  <Text fontSize={{ base: '2xl', md: '3xl' }} fontWeight="black" lineHeight="1">
                    {selectionStats.totalItems}
                  </Text>
                </HStack>
                
                {/* Label */}
                <Text 
                  fontSize={{ base: 'xs', md: 'sm' }} 
                  fontWeight="black" 
                  letterSpacing="wider"
                  textTransform="uppercase"
                  color="white"
                  textShadow="0 2px 4px rgba(0,0,0,0.4)"
                >
                  {isSummaryExpanded ? '✕ CLOSE' : '👁 VIEW'}
                </Text>
              </VStack>
            </Box>

            {/* Expanded Details Panel */}
            <Box
              position="fixed"
              bottom="0"
              left="0"
              right="0"
              zIndex={1400}
              pointerEvents={isSummaryExpanded ? 'auto' : 'none'}
            >
              <Collapse in={isSummaryExpanded} animateOpacity>
                <Box 
                  bg={summaryPanelBg} 
                  color="white" 
                  p={{ base: 4, md: 6 }}
                  maxH="70vh"
                  overflowY="auto"
                  boxShadow="0 -4px 20px rgba(0, 0, 0, 0.5)"
                >
                <SimpleGrid columns={{ base: 2, md: 2, lg: 3 }} spacing={{ base: 3, md: 4 }} w="full">
                  {selectedItems.map((item, index) => {
                    const fullItem = availableItems.find(i => i.id === item.id);
                    const roomLabel = getRoomLabel(item.room);
                    const RoomIcon = ROOM_CATEGORY_LOOKUP[item.room]?.icon ?? FaBox;
                    return (
                      <Box
                        key={`summary-${item.id}-${item.room}-${index}`}
                        bg="rgba(15, 23, 42, 0.8)"
                        borderRadius="xl"
                        overflow="hidden"
                        borderWidth="1px"
                        borderColor="rgba(168, 85, 247, 0.2)"
                        transition="all 0.3s"
                        _hover={{ 
                          borderColor: 'rgba(168, 85, 247, 0.5)',
                          transform: 'translateY(-2px)',
                          boxShadow: '0 8px 20px rgba(168, 85, 247, 0.2)'
                        }}
                      >
                        <VStack spacing={0} align="stretch" h="100%">
                          {/* Image Section - Fixed Aspect Ratio */}
                          <Box
                            w="100%"
                            position="relative"
                            h="220px"
                            bg="white"
                            overflow="hidden"
                            borderRadius="md"
                          >
                            {fullItem?.image ? (
                              <NextImage
                                src={fullItem.image}
                                alt={item.name}
                                fill
                                sizes="(max-width: 768px) 50vw, (max-width: 1200px) 33vw, 25vw"
                                style={{
                                  objectFit: 'contain',
                                  objectPosition: 'center',
                                }}
                              />
                            ) : (
                              <Box
                                position="absolute"
                                top="0"
                                left="0"
                                right="0"
                                bottom="0"
                                display="flex"
                                alignItems="center"
                                justifyContent="center"
                                bg="rgba(0, 0, 0, 0.3)"
                              >
                                <Icon as={FaBox} boxSize={8} color="whiteAlpha.400" />
                              </Box>
                            )}
                            
                            {/* Quantity Badge */}
                            <Badge
                              position="absolute"
                              top={2}
                              right={2}
                              colorScheme="purple"
                              fontSize="xs"
                              borderRadius="full"
                              px={2}
                              py={1}
                            >
                              {item.quantity}x
                            </Badge>
                          </Box>

                          {/* Content Section */}
                          <VStack spacing={2} align="stretch" p={3} flex="1">
                            {/* Room Label */}
                            <HStack spacing={1.5}>
                              <Icon as={RoomIcon} color="purple.300" boxSize={3} />
                              <Text fontSize="2xs" fontWeight="600" color="purple.200" textTransform="uppercase" letterSpacing="wide">
                                {roomLabel}
                              </Text>
                            </HStack>

                            {/* Item Name */}
                            <Text fontSize="sm" fontWeight="700" color="white" noOfLines={2} lineHeight="1.3" minH="2.6em">
                              {item.name}
                            </Text>

                            {/* Weight Info */}
                            <Text fontSize="2xs" color="whiteAlpha.600">
                              {item.weight}kg each · {item.quantity * item.weight}kg total
                            </Text>

                            {/* Quantity Controls */}
                            <HStack spacing={2} justify="center" w="full" py={2}>
                              <button
                                onClick={(e) => {
                                  e.stopPropagation();
                                  if (item.quantity > 1) {
                                    onUpdateQuantity(item.id, item.quantity - 1);
                                  } else {
                                    onRemoveItem(item.id);
                                  }
                                }}
                                style={{
                                  background: 'rgba(168, 85, 247, 0.2)',
                                  border: '1px solid rgba(168, 85, 247, 0.3)',
                                  borderRadius: '8px',
                                  color: 'white',
                                  fontSize: '20px',
                                  fontWeight: 'bold',
                                  cursor: 'pointer',
                                  padding: '4px 12px',
                                  width: 'auto',
                                  height: '32px',
                                  minWidth: '32px',
                                  lineHeight: '1',
                                  outline: 'none',
                                  transition: 'all 0.2s',
                                }}
                                onMouseEnter={(e) => {
                                  e.currentTarget.style.background = 'rgba(168, 85, 247, 0.3)';
                                  e.currentTarget.style.borderColor = 'rgba(168, 85, 247, 0.5)';
                                }}
                                onMouseLeave={(e) => {
                                  e.currentTarget.style.background = 'rgba(168, 85, 247, 0.2)';
                                  e.currentTarget.style.borderColor = 'rgba(168, 85, 247, 0.3)';
                                }}
                              >
                                −
                              </button>
                              <Text
                                color="white"
                                fontSize="lg"
                                fontWeight="700"
                                minW="36px"
                                textAlign="center"
                              >
                                {item.quantity}
                              </Text>
                              <button
                                onClick={(e) => {
                                  e.stopPropagation();
                                  onUpdateQuantity(item.id, item.quantity + 1);
                                }}
                                style={{
                                  background: 'rgba(168, 85, 247, 0.2)',
                                  border: '1px solid rgba(168, 85, 247, 0.3)',
                                  borderRadius: '8px',
                                  color: 'white',
                                  fontSize: '20px',
                                  fontWeight: 'bold',
                                  cursor: 'pointer',
                                  padding: '4px 12px',
                                  width: 'auto',
                                  height: '32px',
                                  minWidth: '32px',
                                  lineHeight: '1',
                                  outline: 'none',
                                  transition: 'all 0.2s',
                                }}
                                onMouseEnter={(e) => {
                                  e.currentTarget.style.background = 'rgba(168, 85, 247, 0.3)';
                                  e.currentTarget.style.borderColor = 'rgba(168, 85, 247, 0.5)';
                                }}
                                onMouseLeave={(e) => {
                                  e.currentTarget.style.background = 'rgba(168, 85, 247, 0.2)';
                                  e.currentTarget.style.borderColor = 'rgba(168, 85, 247, 0.3)';
                                }}
                              >
                                +
                              </button>
                            </HStack>

                            {/* Delete Icon - Positioned directly above Replace button */}
                            <Box display="flex" justifyContent="center" pt={2}>
                              <IconButton
                                aria-label="Delete item"
                                icon={<Icon as={FaTrash} boxSize={3.5} />}
                                size="sm"
                                variant="ghost"
                                color="whiteAlpha.600"
                                onClick={(e) => {
                                  e.stopPropagation();
                                  onRemoveItem(item.id);
                                }}
                                _hover={{ 
                                  color: 'red.400',
                                  transform: 'scale(1.1)',
                                  bg: 'transparent'
                                }}
                                transition="all 0.2s"
                              />
                            </Box>

                            {/* Replace Button */}
                            <Button
                              size="sm"
                              variant="ghost"
                              color="purple.300"
                              fontSize="xs"
                              w="full"
                              onClick={(e) => {
                                e.stopPropagation();
                                onRemoveItem(item.id);
                                setSelectedRoom(item.room);
                                if (isSummaryExpanded) {
                                  toggleSummary();
                                }
                                setTimeout(() => {
                                  const tabsElement = document.querySelector('[role="tablist"]');
                                  if (tabsElement) {
                                    tabsElement.scrollIntoView({ behavior: 'smooth', block: 'start' });
                                  }
                                }, 300);
                              }}
                              _hover={{ bg: 'rgba(168,85,247,0.2)', color: 'purple.200' }}
                            >
                              Replace
                            </Button>
                          </VStack>
                        </VStack>
                      </Box>
                    );
                  })}
                </SimpleGrid>
                </Box>
              </Collapse>
            </Box>
          </>
        )}

        {/* Header - Enhanced Typography */}
        <VStack spacing={3} align="stretch" mb={2}>
          <Heading 
            size={{ base: "lg", md: "xl" }}
            color="white"
            fontWeight="800"
            letterSpacing="tight"
            bgGradient="linear(to-r, purple.300, blue.400)"
            bgClip="text"
            textShadow="0 0 20px rgba(168, 85, 247, 0.2)"
            fontFamily="'Inter', 'Segoe UI', system-ui, -apple-system, sans-serif"
          >
            Select Items by Room
          </Heading>
          <Text 
            fontSize={{ base: "md", md: "lg" }}
            color="whiteAlpha.800"
            fontWeight="500"
            letterSpacing="wide"
            lineHeight="1.6"
          >
            Navigate between rooms and add the items you want to move
          </Text>
        </VStack>

        {/* Back Button */}
        {onBack && (
          <Button
            leftIcon={<FaArrowLeft />}
            onClick={onBack}
            variant="ghost"
            color="white"
            size="lg"
            _hover={{ bg: 'whiteAlpha.200' }}
          >
            Back to Property Size
          </Button>
        )}

        {/* Search */}
        <Input
          size="lg"
          placeholder="Search for an item..."
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          bg={bgColor}
          borderColor={borderColor}
        />

        {/* Room Tabs - Enhanced Design (Hidden during search) */}
        {!searchQuery.trim() && (
        <Tabs
          variant="unstyled"
          index={relevantRooms.findIndex(r => r.id === selectedRoom)}
          onChange={(index) => setSelectedRoom(relevantRooms[index].id)}
        >
          <TabList 
            flexWrap="wrap" 
            gap={3}
            justifyContent={{ base: 'center', md: 'flex-start' }}
          >
            {relevantRooms.map((room) => {
              const itemCount = getRoomItemCount(room.id);
              const isSelected = room.id === selectedRoom;
              return (
                <Tab 
                  key={room.id} 
                  position="relative"
                  bg={isSelected ? `${room.color}.500` : 'whiteAlpha.100'}
                  color={isSelected ? 'white' : 'whiteAlpha.800'}
                  borderRadius="xl"
                  px={{ base: 4, md: 6 }}
                  py={{ base: 3, md: 4 }}
                  minH={{ base: '60px', md: '70px' }}
                  border="2px solid"
                  borderColor={isSelected ? `${room.color}.400` : 'transparent'}
                  boxShadow={isSelected ? `0 0 20px ${room.color}.400` : 'none'}
                  transition="all 0.3s cubic-bezier(0.4, 0, 0.2, 1)"
                  _hover={{
                    bg: isSelected ? `${room.color}.600` : 'whiteAlpha.200',
                    transform: 'translateY(-2px)',
                    boxShadow: isSelected ? `0 0 25px ${room.color}.400` : '0 4px 12px rgba(0,0,0,0.3)',
                  }}
                  _active={{
                    transform: 'translateY(0)',
                  }}
                >
                  <VStack spacing={1.5}>
                    <HStack spacing={2}>
                      <Icon 
                        as={room.icon} 
                        boxSize={{ base: 5, md: 6 }}
                        filter={isSelected ? 'drop-shadow(0 2px 4px rgba(0,0,0,0.3))' : 'none'}
                      />
                      <Text 
                        fontSize={{ base: 'sm', md: 'md' }}
                        fontWeight={isSelected ? '700' : '600'}
                        letterSpacing="0.3px"
                      >
                        {room.name}
                      </Text>
                    </HStack>
                    {itemCount > 0 && (
                      <Badge 
                        colorScheme={isSelected ? 'whiteAlpha' : room.color}
                        borderRadius="full"
                        px={2.5}
                        py={0.5}
                        fontSize="xs"
                        fontWeight="bold"
                        bg={isSelected ? 'whiteAlpha.300' : `${room.color}.100`}
                        color={isSelected ? 'white' : `${room.color}.700`}
                      >
                        {itemCount}
                      </Badge>
                    )}
                  </VStack>
                </Tab>
              );
            })}
          </TabList>

          <TabPanels>
            {relevantRooms.map((room) => (
              <TabPanel key={room.id} px={0}>
                <VStack spacing={6} align="stretch">
                  {/* Items by Category */}
                  {currentRoomItems.length === 0 ? (
                    <Card variant="outline">
                      <CardBody>
                        <Text textAlign="center" color="gray.500">
                          No items available in this category
                        </Text>
                      </CardBody>
                    </Card>
                  ) : searchQuery.trim() ? (
                    // If searching, show flat list without grouping
                    <Box>
                      <SimpleGrid 
                        columns={{ base: 2, sm: 2, md: 2, lg: 3, xl: 4 }} 
                        spacing={{ base: 3, md: 4 }}
                        w="full"
                      >
                        {currentRoomItems.map((item, index) => {
                          const quantity = getItemQuantity(item.id);
                          const isSelected = quantity > 0;

                        return (
                          <Card
                            key={`${item.id}-${index}`}
                            variant="outline"
                            borderWidth="2px"
                            borderColor={isSelected ? 'green.500' : borderColor}
                            bg={isSelected ? 'green.50' : bgColor}
                            transition="all 0.15s ease-in-out"
                            minH="90px"
                            h="auto"
                            display="flex"
                            boxShadow={isSelected ? '0 0 0 1px var(--chakra-colors-green-500)' : 'none'}
                            sx={{
                              WebkitMinContent: 'min-content',
                              minHeight: '90px !important',
                              height: 'auto !important',
                            }}
                          >
                            <CardBody p={3}>
                              <VStack spacing={3} align="stretch">
                                {/* Item Image */}
                                <Box
                                  h="160px"
                                  minH="160px"
                                  bg="white"
                                  borderRadius="md"
                                  overflow="hidden"
                                  position="relative"
                                  flexShrink={0}
                                  sx={{
                                    minHeight: '160px !important',
                                    height: '160px !important',
                                  }}
                                >
                                  {item.image ? (
                                    <NextImage
                                      src={item.image}
                                      alt={item.name}
                                      fill
                                      sizes="(max-width: 600px) 50vw, (max-width: 1024px) 33vw, 25vw"
                                      style={{
                                        objectFit: 'contain',
                                      }}
                                    />
                                  ) : (
                                    <Box
                                      w="100%"
                                      h="100%"
                                      display="flex"
                                      alignItems="center"
                                      justifyContent="center"
                                      bg="gray.100"
                                    >
                                      <Icon as={room.icon} boxSize={8} color="gray.400" />
                                    </Box>
                                  )}
                                </Box>

                                {/* Item Name */}
                                <Text fontSize="sm" fontWeight="semibold" noOfLines={2} minH="40px">
                                  {item.name}
                                </Text>

                                {/* Weight Badge */}
                                <Badge colorScheme="gray" fontSize="xs">
                                  {item.weight}kg
                                </Badge>

                                {/* Quantity Controls */}
                                <VStack align="stretch" spacing={2}>
                                  <Tooltip
                                    label={
                                      isSelected
                                        ? 'Tap to add one more'
                                        : 'Add this item to your move'
                                    }
                                    hasArrow
                                  >
                                    <Button
                                      leftIcon={<FaPlus />}
                                      size="sm"
                                      colorScheme={isSelected ? 'green' : room.color}
                                      variant={isSelected ? 'solid' : 'outline'}
                                      onClick={() =>
                                        isSelected
                                          ? onUpdateQuantity(item.id, quantity + 1)
                                          : onAddItem(item, room.id, 1)
                                      }
                                    >
                                      {isSelected ? `Added (${quantity})` : 'Add'}
                                    </Button>
                                  </Tooltip>
                                  {isSelected && (
                                    <Button
                                      size="xs"
                                      variant="ghost"
                                      colorScheme="red"
                                      onClick={() => onRemoveItem(item.id)}
                                    >
                                      Remove
                                    </Button>
                                  )}
                                </VStack>
                              </VStack>
                            </CardBody>
                          </Card>
                        );
                      })}
                    </SimpleGrid>
                    </Box>
                  ) : (
                    // If not searching, show grouped by type
                    <>
                      {/* Expand/Collapse All Buttons */}
                      <HStack spacing={2} justify="flex-end" mb={4}>
                        <Button
                          size="sm"
                          variant="outline"
                          colorScheme={room.color}
                          onClick={expandAllCategories}
                          leftIcon={<FaChevronDown />}
                        >
                          Expand All
                        </Button>
                        <Button
                          size="sm"
                          variant="outline"
                          colorScheme={room.color}
                          onClick={collapseAllCategories}
                          leftIcon={<FaChevronUp />}
                        >
                          Collapse All
                        </Button>
                      </HStack>

                      {Array.from(groupedCurrentRoomItems.entries()).map(([typeName, items], groupIndex) => {
                        const categoryKey = `${room.id}-${typeName}`;
                        const isOpen = isCategoryOpen(categoryKey);
                        
                        return (
                        <Box key={`${room.id}-${typeName}-${groupIndex}`}>
                          {/* Type Header - Clickable */}
                          <HStack 
                            spacing={3} 
                            mb={isOpen ? 0 : 3}
                            pb={2}
                            borderBottom="2px solid"
                            borderColor={isOpen ? `${room.color}.400` : `${room.color}.200`}
                            cursor="pointer"
                            onClick={() => toggleCategory(categoryKey)}
                            transition="all 0.3s"
                            bg={isOpen ? `${room.color}.50` : 'transparent'}
                            _dark={{
                              bg: isOpen ? `${room.color}.900` : 'transparent'
                            }}
                            _hover={{
                              bg: `${room.color}.50`,
                              _dark: { bg: `${room.color}.900` },
                              borderColor: `${room.color}.400`
                            }}
                            p={3}
                            borderRadius="md"
                            boxShadow={isOpen ? 'sm' : 'none'}
                          >
                            <Icon 
                              as={isOpen ? FaChevronUp : FaChevronDown}
                              boxSize={4}
                              color={`${room.color}.500`}
                              transition="transform 0.2s"
                            />
                            <Icon 
                              as={room.icon} 
                              boxSize={5} 
                              color={`${room.color}.500`}
                            />
                            <Text 
                              fontSize="lg" 
                              fontWeight="bold" 
                              color={`${room.color}.600`}
                              _dark={{ color: `${room.color}.300` }}
                              flex={1}
                            >
                              {typeName}
                            </Text>
                            <Badge 
                              colorScheme={room.color} 
                              borderRadius="full"
                              px={2}
                              fontSize="xs"
                            >
                              {items.length}
                            </Badge>
                          </HStack>

                          {/* Items Grid for this type - Collapsible */}
                          <Collapse in={isOpen} animateOpacity>
                            <SimpleGrid 
                              columns={{ base: 2, sm: 2, md: 2, lg: 3, xl: 4 }} 
                              spacing={{ base: 3, md: 4 }}
                              w="full"
                              mt={3}
                            >
                              {items.map((item, index) => {
                              const quantity = getItemQuantity(item.id);
                              const isSelected = quantity > 0;

                              return (
                                <Card
                                  key={`${item.id}-${index}`}
                                  variant="outline"
                                  borderWidth="2px"
                                  borderColor={isSelected ? 'green.500' : borderColor}
                                  bg={isSelected ? 'green.50' : bgColor}
                                  transition="all 0.15s ease-in-out"
                                  minH="90px"
                                  h="auto"
                                  display="flex"
                                  boxShadow={isSelected ? '0 0 0 1px var(--chakra-colors-green-500)' : 'none'}
                                  sx={{
                                    WebkitMinContent: 'min-content',
                                    minHeight: '90px !important',
                                    height: 'auto !important',
                                  }}
                                >
                                  <CardBody p={3}>
                                    <VStack spacing={3} align="stretch">
                                      {/* Item Image */}
                                      <Box
                                        h="160px"
                                        minH="160px"
                                        bg="white"
                                        borderRadius="md"
                                        overflow="hidden"
                                        position="relative"
                                        flexShrink={0}
                                        sx={{
                                          minHeight: '160px !important',
                                          height: '160px !important',
                                        }}
                                      >
                                        {item.image ? (
                                          <NextImage
                                            src={item.image}
                                            alt={item.name}
                                            fill
                                            sizes="(max-width: 600px) 50vw, (max-width: 1024px) 33vw, 25vw"
                                            style={{
                                              objectFit: 'contain',
                                            }}
                                          />
                                        ) : (
                                          <Box
                                            w="100%"
                                            h="100%"
                                            display="flex"
                                            alignItems="center"
                                            justifyContent="center"
                                            bg="gray.100"
                                          >
                                            <Icon as={room.icon} boxSize={8} color="gray.400" />
                                          </Box>
                                        )}
                                      </Box>

                                      {/* Item Name */}
                                      <Text fontSize="sm" fontWeight="semibold" noOfLines={2} minH="40px">
                                        {item.name}
                                      </Text>

                                      {/* Weight Badge */}
                                      <Badge colorScheme="gray" fontSize="xs">
                                        {item.weight}kg
                                      </Badge>

                                      {/* Quantity Controls */}
                                      <VStack align="stretch" spacing={2}>
                                        <Tooltip
                                          label={
                                            isSelected
                                              ? 'Tap to add one more'
                                              : 'Add this item to your move'
                                          }
                                          hasArrow
                                        >
                                          <Button
                                            leftIcon={<FaPlus />}
                                            size="sm"
                                            colorScheme={isSelected ? 'green' : room.color}
                                            variant={isSelected ? 'solid' : 'outline'}
                                            onClick={() =>
                                              isSelected
                                                ? onUpdateQuantity(item.id, quantity + 1)
                                                : onAddItem(item, room.id, 1)
                                            }
                                          >
                                            {isSelected ? `Added (${quantity})` : 'Add'}
                                          </Button>
                                        </Tooltip>
                                        {isSelected && (
                                          <Button
                                            size="xs"
                                            variant="ghost"
                                            colorScheme="red"
                                            onClick={() => onRemoveItem(item.id)}
                                          >
                                            Remove
                                          </Button>
                                        )}
                                      </VStack>
                                    </VStack>
                                  </CardBody>
                                </Card>
                              );
                              })}
                            </SimpleGrid>
                          </Collapse>
                        </Box>
                        );
                      })}
                    </>
                  )}

                  {/* Add Custom Item Section */}
                  <Box>
                    <Button
                      leftIcon={isCustomItemOpen ? <FaChevronUp /> : <FaChevronDown />}
                      variant="ghost"
                      size="sm"
                      onClick={toggleCustomItem}
                    >
                      Add Custom Item
                    </Button>
                    <Collapse in={isCustomItemOpen}>
                      <Card variant="outline" mt={2}>
                        <CardBody>
                          <Text fontSize="sm" color="gray.600">
                            To add items not in the list, please use the search field or contact us
                          </Text>
                        </CardBody>
                      </Card>
                    </Collapse>
                  </Box>
                </VStack>
              </TabPanel>
            ))}
          </TabPanels>
        </Tabs>
        )}

        {/* Search Results - Show when searching */}
        {searchQuery.trim() && (
          <VStack spacing={4} align="stretch" mt={6}>
            <Text fontSize="sm" color="whiteAlpha.700">
              Found {currentRoomItems.length} item(s) for "{searchQuery}"
            </Text>
            {currentRoomItems.length === 0 ? (
              <Card variant="outline">
                <CardBody>
                  <Text textAlign="center" color="gray.500">
                    No items found matching your search
                  </Text>
                </CardBody>
              </Card>
            ) : (
              <SimpleGrid 
                columns={{ base: 2, sm: 2, md: 2, lg: 3, xl: 4 }} 
                spacing={{ base: 3, md: 4 }} 
                w="full"
              >
                {currentRoomItems.map((item, index) => {
                  const quantity = getItemQuantity(item.id);
                  const isSelected = quantity > 0;
                  const isTopResult = index < 3;

                  return (
                    <Box 
                      key={`search-${item.id}-${index}`}
                      p={3}
                      borderRadius="lg"
                      bg="rgba(255, 255, 255, 0.05)"
                      borderWidth="1px"
                      borderColor="rgba(255, 255, 255, 0.1)"
                      transition="all 0.2s"
                      _hover={{ 
                        bg: 'rgba(255, 255, 255, 0.08)',
                        borderColor: 'rgba(255, 255, 255, 0.2)'
                      }}
                    >
                      <VStack spacing={3} align="stretch">
                        <Box>
                          <HStack spacing={1} w="full" mb={1}>
                            <Text
                              fontSize="xs"
                              fontWeight="600"
                              color="white"
                              noOfLines={2}
                              lineHeight="1.3"
                              flex={1}
                            >
                              {item.name}
                            </Text>
                            {isTopResult && (
                              <Text fontSize="xs">⭐</Text>
                            )}
                          </HStack>
                          {item.category && (
                            <Text fontSize="2xs" color="whiteAlpha.600">
                              {item.category}
                            </Text>
                          )}
                        </Box>

                        <HStack spacing={3} justify="center" w="full">
                          <button
                            onClick={() => {
                              if (isSelected) {
                                onUpdateQuantity(item.id, Math.max(0, quantity - 1));
                              }
                            }}
                            disabled={!isSelected}
                            style={{
                              background: 'none',
                              border: 'none',
                              color: 'white',
                              fontSize: '28px',
                              fontWeight: 'normal',
                              cursor: isSelected ? 'pointer' : 'not-allowed',
                              padding: '0',
                              margin: '0',
                              width: 'auto',
                              height: 'auto',
                              minWidth: '24px',
                              lineHeight: '1',
                              outline: 'none',
                              WebkitTapHighlightColor: 'transparent',
                              opacity: isSelected ? 1 : 0.3
                            }}
                          >
                            −
                          </button>
                          <span
                            style={{
                              color: 'white',
                              fontSize: '18px',
                              fontWeight: '600',
                              minWidth: '24px',
                              textAlign: 'center',
                              lineHeight: '1'
                            }}
                          >
                            {quantity}
                          </span>
                          <button
                            onClick={() => {
                              if (isSelected) {
                                onUpdateQuantity(item.id, quantity + 1);
                              } else {
                                onAddItem(item, 'unknown', 1);
                              }
                            }}
                            style={{
                              background: 'none',
                              border: 'none',
                              color: 'white',
                              fontSize: '24px',
                              fontWeight: 'normal',
                              cursor: 'pointer',
                              padding: '0',
                              margin: '0',
                              width: 'auto',
                              height: 'auto',
                              minWidth: '24px',
                              lineHeight: '1',
                              outline: 'none',
                              WebkitTapHighlightColor: 'transparent',
                              opacity: 1
                            }}
                          >
                            +
                          </button>
                        </HStack>

                        {isSelected && (
                          <Text
                            fontSize="2xs"
                            color="red.300"
                            textAlign="center"
                            cursor="pointer"
                            onClick={() => onRemoveItem(item.id)}
                            _hover={{ color: 'red.400' }}
                          >
                            Remove
                          </Text>
                        )}
                      </VStack>
                    </Box>
                  );
                })}
              </SimpleGrid>
            )}
          </VStack>
        )}

      </VStack>
    </Box>
  );
}

/**
 * Smart Search Box Component
 * Advanced search with autocomplete, real-time suggestions, and +/- controls
 */

import React, { useState, useEffect, useRef, useCallback } from 'react';
import {
  Box,
  Input,
  InputGroup,
  InputLeftElement,
  InputRightElement,
  VStack,
  HStack,
  Text,
  Button,
  IconButton,
  Flex,
  Badge,
  Portal,
  useOutsideClick,
  Icon,
  Divider
} from '@chakra-ui/react';
import { FaSearch, FaTimes, FaPlus, FaMinus, FaBrain, FaCouch, FaBed, FaUtensils, FaTv, FaBox, FaCar, FaBicycle, FaMusic, FaBook, FaHome, FaChair } from 'react-icons/fa';
import { getAutocomplete, getSuggestions, type SearchSuggestion } from '../../../lib/search/smart-search';
import { isNaturalLanguageQuery, parseNaturalLanguage } from '../../../lib/search/natural-language-parser';
import { convertPopularToItem } from '../../../lib/items/popular-items';
import { COMPREHENSIVE_CATALOG } from '../../../lib/pricing/catalog-dataset';
import NLPResultsDisplay from './NLPResultsDisplay';
import type { Item } from '../hooks/useBookingForm';

interface SmartSearchBoxProps {
  value: string;
  onChange: (value: string) => void;
  onItemAdd: (item: Item) => void;
  onItemUpdate: (itemId: string, quantity: number) => void;
  onAddItems: (items: Item[]) => void; // For bulk adding from NLP
  selectedItems: Item[];
  placeholder?: string;
}

export const SmartSearchBox: React.FC<SmartSearchBoxProps> = ({
  value,
  onChange,
  onItemAdd,
  onItemUpdate,
  onAddItems,
  selectedItems,
  placeholder = "Search for furniture, appliances, boxes... (e.g., 'sofa', 'heavy items', 'kitchen')"
}) => {
  const [isFocused, setIsFocused] = useState(false);
  const [suggestions, setSuggestions] = useState<SearchSuggestion[]>([]);
  const [autocompleteSuggestions, setAutocompleteSuggestions] = useState<SearchSuggestion[]>([]);
  const [highlightedIndex, setHighlightedIndex] = useState(-1);
  const [showNLPAnalysis, setShowNLPAnalysis] = useState(true); // State to control NLP display
  const [catalogItems, setCatalogItems] = useState<any[]>([]); // Loaded catalog items
  
  const inputRef = useRef<HTMLInputElement>(null);
  const suggestionsRef = useRef<HTMLDivElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  
  // Close suggestions when clicking outside
  useOutsideClick({
    ref: containerRef,
    handler: () => {
      // Add delay to prevent immediate closing when clicking inside suggestions
      setTimeout(() => {
        setIsFocused(false);
        setHighlightedIndex(-1);
      }, 100);
    }
  });

  // Load catalog items on component mount
  useEffect(() => {
    const loadCatalogItems = async () => {
      try {
        console.log('🔄 Loading Home Furniture Pricing Catalog...');
        
        // Try to load from COMPREHENSIVE_CATALOG first
        if (COMPREHENSIVE_CATALOG.length > 0) {
          setCatalogItems(COMPREHENSIVE_CATALOG);
          console.log('✅ Loaded catalog from COMPREHENSIVE_CATALOG:', COMPREHENSIVE_CATALOG.length, 'items');
          console.log('📋 Sample items:', COMPREHENSIVE_CATALOG.slice(0, 3).map(item => ({
            name: item.name,
            category: item.category,
            keywords: item.keywords
          })));
          return;
        }

        // Fallback: Try to load via API
        console.log('🔄 COMPREHENSIVE_CATALOG empty, trying API...');
        const response = await fetch('/api/catalog/items');
        if (response.ok) {
          const data = await response.json();
          setCatalogItems(data.items || []);
          console.log('✅ Loaded catalog via API:', data.items?.length || 0, 'items');
        } else {
          console.log('❌ API failed, using empty catalog');
          setCatalogItems([]);
        }
      } catch (error) {
        console.error('❌ Failed to load catalog:', error);
        setCatalogItems([]);
      }
    };

    loadCatalogItems();
  }, []);

  // Handle keyboard events for better mobile experience
  const handleKeyDown = useCallback((e: React.KeyboardEvent) => {
    if (e.key === 'Escape') {
      setIsFocused(false);
      setHighlightedIndex(-1);
      inputRef.current?.blur();
    } else if (e.key === 'ArrowDown') {
      e.preventDefault();
      const totalSuggestions = suggestions.length;
      setHighlightedIndex(prev => Math.min(prev + 1, totalSuggestions - 1));
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setHighlightedIndex(prev => Math.max(prev - 1, -1));
    } else if (e.key === 'Enter' && highlightedIndex >= 0) {
      e.preventDefault();
      // Handle selection based on highlighted index
      const suggestion = suggestions[highlightedIndex];
      if (suggestion.item) {
        const item = convertCatalogToItem(suggestion.item);
        onItemAdd(item);
        onChange('');
      }
      setIsFocused(false);
      setHighlightedIndex(-1);
    }
  }, [highlightedIndex, suggestions, onChange, onItemAdd]);

  // Handle mobile keyboard behavior
  useEffect(() => {
    const handleResize = () => {
      // Recalculate position when viewport changes (keyboard open/close)
      if (isFocused && suggestionsRef.current) {
        const inputRect = inputRef.current?.getBoundingClientRect();
        if (inputRect) {
          const viewportHeight = window.innerHeight;
          const suggestionsHeight = 200;
          const spaceBelow = viewportHeight - inputRect.bottom;
          const spaceAbove = inputRect.top;
          
          if (spaceBelow < suggestionsHeight && spaceAbove > spaceBelow) {
            // Show above if keyboard is open and there's more space above
            suggestionsRef.current.style.top = `${Math.max(8, inputRect.top - suggestionsHeight - 4)}px`;
          } else {
            // Show below
            suggestionsRef.current.style.top = `${inputRect.bottom + 4}px`;
          }
        }
      }
    };

    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, [isFocused]);

  // Reset NLP analysis visibility when value changes
  useEffect(() => {
    if (value && isNaturalLanguageQuery(value)) {
      setShowNLPAnalysis(true);
    }
  }, [value]);

  // Local search function using loaded catalog items
  const searchLocalItems = (query: string, limit: number = 12) => {
    console.log('🔍 Searching in catalog:', {
      query,
      catalogLength: catalogItems.length,
      firstItem: catalogItems[0]
    });

    if (!query || query.length < 1) {
      // Return popular items when no query
      return catalogItems.slice(0, limit).map(item => ({
        id: item.id,
        text: item.name,
        type: 'item' as const,
        popularity: 100,
        matchedKeywords: item.keywords || [],
        item: item
      }));
    }

    const queryLower = query.toLowerCase();
    const results = catalogItems.filter(item => {
      if (!item) return false;
      
      // ✅ Search in NAME (Home Furniture items)
      if (item.name?.toLowerCase?.()?.includes(queryLower)) {
        console.log('✅ Found by name:', item.name);
        return true;
      }
      
      // ✅ Search in KEYWORDS (Home Furniture keywords)
      if (item.keywords && Array.isArray(item.keywords)) {
        const keywordMatch = item.keywords.some((keyword: string) => 
          keyword?.toLowerCase?.()?.includes(queryLower)
        );
        if (keywordMatch) {
          console.log('✅ Found by keyword:', item.name, item.keywords);
        }
        return keywordMatch;
      }
      
      // ✅ Search in CATEGORY (Home Furniture categories)
      if (item.category?.toLowerCase?.()?.includes(queryLower)) {
        console.log('✅ Found by category:', item.name, item.category);
        return true;
      }
      
      return false;
    }).slice(0, limit);

    console.log('🎯 Search results:', results.length, 'items found');

    return results.map(item => ({
      id: item.id,
      text: item.name,
      type: 'item' as const,
      popularity: 100,
      matchedKeywords: item.keywords || [],
      item: item
    }));
  };

  // Update suggestions when query changes - NOW TRIGGERS ON SINGLE CHARACTER!
  useEffect(() => {
    const updateSuggestions = async () => {
      // Use local search with loaded catalog items
      const searchSuggestions = searchLocalItems(value, 12);
      
      setAutocompleteSuggestions([]); // No autocomplete suggestions
      setSuggestions(searchSuggestions);
      
      // Inline completion removed
    };

    const debounceTimer = setTimeout(updateSuggestions, 50); // Faster response
    return () => clearTimeout(debounceTimer);
  }, [value, catalogItems]);


  // Handle suggestion click - ONE CLICK SELECTION
  const handleSuggestionClick = (suggestion: SearchSuggestion) => {
    // ALWAYS fill the search field first
    onChange(suggestion.text);
    
    // If it's an item suggestion, also add it to the cart
    if (suggestion.type === 'item' && suggestion.item) {
      const item = convertCatalogToItem(suggestion.item);
      onItemAdd(item);
    }
    
    // Keep focus and suggestions for continuous searching - NO SCROLL
    setTimeout(() => {
      inputRef.current?.focus({ preventScroll: true });
      setIsFocused(true);
    }, 100);
  };

  // Handle mouse enter/leave to maintain focus
  const handleSuggestionsMouseEnter = () => {
    setIsFocused(true);
  };

  const handleSuggestionsMouseLeave = () => {
    // Don't close immediately, let user click
  };

  // Text highlighting function for search matches
  const highlightMatchedText = (text: string, query: string) => {
    if (!query || query.length === 0) return text;
    
    const regex = new RegExp(`(${query})`, 'gi');
    const parts = text.split(regex);
    
    return parts.map((part, index) => {
      if (part.toLowerCase() === query.toLowerCase()) {
        return <Text as="span" key={index} fontWeight="bold" color="blue.300">{part}</Text>;
      }
      return part;
    });
  };

  // Convert catalog item to Item format
  const convertCatalogToItem = (catalogItem: any): Item => {
    return {
      id: catalogItem.id,
      name: catalogItem.name,
      description: `${catalogItem.name} - ${Array.isArray(catalogItem.keywords) ? catalogItem.keywords[0] : catalogItem.keywords}`,
      category: catalogItem.category,
      size: catalogItem.volume > 1.5 ? 'large' : catalogItem.volume > 0.5 ? 'medium' : 'small',
      quantity: 1,
      unitPrice: Math.round(catalogItem.volume * 20 + catalogItem.weight * 0.5),
      totalPrice: Math.round(catalogItem.volume * 20 + catalogItem.weight * 0.5),
      weight: catalogItem.weight,
      volume: catalogItem.volume,
      image: '', // No default image - use icons instead
    };
  };

  // Get current quantity for an item
  const getItemQuantity = (itemId: string): number => {
    return selectedItems.find(item => item.id === itemId)?.quantity || 0;
  };

  // Get icon for category
  const getCategoryIcon = (category: string) => {
    const categoryLower = category.toLowerCase();
    
    if (categoryLower.includes('sofa') || categoryLower.includes('couch') || categoryLower.includes('living')) {
      return FaCouch;
    }
    if (categoryLower.includes('bed') || categoryLower.includes('bedroom')) {
      return FaBed;
    }
    if (categoryLower.includes('kitchen') || categoryLower.includes('dining') || categoryLower.includes('cook')) {
      return FaUtensils;
    }
    if (categoryLower.includes('tv') || categoryLower.includes('electronic') || categoryLower.includes('audio')) {
      return FaTv;
    }
    if (categoryLower.includes('bike') || categoryLower.includes('bicycle')) {
      return FaBicycle;
    }
    if (categoryLower.includes('car') || categoryLower.includes('vehicle')) {
      return FaCar;
    }
    if (categoryLower.includes('music') || categoryLower.includes('instrument')) {
      return FaMusic;
    }
    if (categoryLower.includes('book') || categoryLower.includes('study') || categoryLower.includes('office')) {
      return FaBook;
    }
    if (categoryLower.includes('chair') || categoryLower.includes('seating')) {
      return FaChair;
    }
    if (categoryLower.includes('antique') || categoryLower.includes('collectible')) {
      return FaHome;
    }
    // Default icon for boxes and general items
    return FaBox;
  };

  // Handle item quantity change
  const handleQuantityChange = (itemId: string, change: number) => {
    const currentQuantity = getItemQuantity(itemId);
    const newQuantity = Math.max(0, currentQuantity + change);
    onItemUpdate(itemId, newQuantity);
  };

  return (
    <Box ref={containerRef} position="relative" w="100%">
      {/* Search Input with Inline Completion */}
      <InputGroup size="lg">
        <Box position="relative" flex="1">
          <Input
            ref={inputRef}
            value={value}
            onChange={(e) => {
              onChange(e.target.value);
            }}
            onFocus={() => {
              setIsFocused(true);
              setHighlightedIndex(-1);
            }}
            onBlur={(e) => {
              // Only close if not clicking inside suggestions
              if (!suggestionsRef.current?.contains(e.relatedTarget as Node)) {
                setTimeout(() => setIsFocused(false), 150);
              }
            }}
            onKeyDown={handleKeyDown}
            placeholder={placeholder}
            bg="white"
            border="2px solid"
            borderColor={isFocused ? "blue.300" : "gray.200"}
            borderRadius="xl"
            fontSize="md"
            position="relative"
            zIndex={2}
            px={4}
            overflow="hidden"
            textOverflow="ellipsis"
            whiteSpace="nowrap"
            _hover={{ borderColor: "blue.200" }}
            _focus={{ 
              borderColor: "blue.400", 
              boxShadow: "0 0 0 1px var(--chakra-colors-blue-400)" 
            }}
            _placeholder={{
              textOverflow: "ellipsis",
              whiteSpace: "nowrap",
              overflow: "hidden",
            }}
            inputMode="search"
            enterKeyHint="search"
            autoComplete="off"
            autoCorrect="off"
            autoCapitalize="off"
            spellCheck="false"
          />
        </Box>
        {value && (
          <InputRightElement>
            <IconButton
              size="sm"
              variant="ghost"
              aria-label="Clear search"
              icon={<FaTimes />}
              onClick={() => {
                onChange('');
                inputRef.current?.focus({ preventScroll: true });
              }}
              color="gray.400"
              _hover={{ color: "gray.600" }}
            />
          </InputRightElement>
        )}
      </InputGroup>

      {/* Search Suggestions Dropdown - PREMIUM DARK THEME */}
      {isFocused && (autocompleteSuggestions.length > 0 || suggestions.length > 0) && (
        <Portal>
          <Box
            ref={suggestionsRef}
            position="fixed"
            bg="rgba(31, 41, 55, 0.95)" // Dark glass effect
            backdropFilter="blur(12px)"
            borderRadius="xl"
            border="2px solid"
            borderColor="rgba(255, 255, 255, 0.1)"
            boxShadow="0 25px 50px -12px rgba(0, 0, 0, 0.5)"
            zIndex={9999}
            maxH={{ base: "300px", md: "400px" }}
            overflowY="auto"
            onMouseEnter={handleSuggestionsMouseEnter}
            onMouseLeave={handleSuggestionsMouseLeave}
            sx={{
              '&::-webkit-scrollbar': {
                width: '6px',
              },
              '&::-webkit-scrollbar-track': {
                background: 'rgba(255, 255, 255, 0.1)',
                borderRadius: '3px',
              },
              '&::-webkit-scrollbar-thumb': {
                background: 'rgba(255, 255, 255, 0.3)',
                borderRadius: '3px',
                '&:hover': {
                  background: 'rgba(255, 255, 255, 0.5)',
                }
              }
            }}
            style={{
              top: inputRef.current ? (() => {
                const inputRect = inputRef.current.getBoundingClientRect();
                const viewportHeight = window.innerHeight;
                const suggestionsHeight = 200; // Base height for mobile
                const spaceBelow = viewportHeight - inputRect.bottom;
                const spaceAbove = inputRect.top;
                
                // If there's enough space below, show below
                if (spaceBelow >= suggestionsHeight) {
                  return inputRect.bottom + window.scrollY + 4;
                }
                // If there's more space above, show above
                else if (spaceAbove > spaceBelow) {
                  return Math.max(8, inputRect.top + window.scrollY - suggestionsHeight - 4);
                }
                // Otherwise, show below but limit height
                else {
                  return inputRect.bottom + window.scrollY + 4;
                }
              })() : 0,
              left: inputRef.current ? (() => {
                const inputRect = inputRef.current.getBoundingClientRect();
                return inputRect.left + window.scrollX;
              })() : 0,
              width: inputRef.current ? (() => {
                const inputRect = inputRef.current.getBoundingClientRect();
                return inputRect.width;
              })() : undefined,
            }}
          >
            {/* Individual Items Search Results */}

            {/* Search Results with +/- Controls - PREMIUM DARK THEME */}
            {suggestions.length > 0 && (
              <VStack spacing={0} align="stretch">
                <Box p={3} bg="rgba(34, 197, 94, 0.1)">
                  <Text fontSize="xs" fontWeight="semibold" color="green.300">
                    ⚡ Click to Add Items Instantly
                  </Text>
                </Box>
                {suggestions.slice(0, 8).map((suggestion, index) => {
                  const adjustedIndex = index; // No autocomplete suggestions anymore
                  const currentQuantity = suggestion.item ? getItemQuantity(suggestion.item.id) : 0;
                  
                  return (
                    <Box
                      key={suggestion.id}
                      p={3}
                      bg={highlightedIndex === adjustedIndex ? "rgba(34, 197, 94, 0.15)" : "transparent"}
                      _hover={{ 
                        bg: "rgba(34, 197, 94, 0.1)",
                        transform: "translateX(4px)",
                      }}
                      transition="all 0.2s ease"
                      borderLeft="2px solid"
                      borderColor={highlightedIndex === adjustedIndex ? "green.400" : "transparent"}
                      borderBottomRadius={index === Math.min(suggestions.length - 1, 3) ? "xl" : "none"}
                    >
                      {/* TABLE FORMAT: Icon + Names with +/- controls */}
                      <Flex justify="space-between" align="center" w="full">
                        {/* Icon + Item Name (Left) */}
                        <HStack spacing={3} flex={1}>
                          {/* Category Icon */}
                          {suggestion.item && (
                            <Icon
                              as={getCategoryIcon(suggestion.item.category)}
                              color="blue.300"
                              boxSize={5}
                              flexShrink={0}
                            />
                          )}
                          <VStack align="start" spacing={0} flex={1}>
                            <Text fontSize="sm" fontWeight="medium" color="white">
                              {highlightMatchedText(suggestion.text, value)}
                            </Text>
                            {suggestion.item && (
                              <Text fontSize="xs" color="gray.400">
                                {suggestion.item.category}
                              </Text>
                            )}
                          </VStack>
                        </HStack>
                        
                        {/* Quantity Controls (Right) */}
                        {suggestion.item && (
                          <HStack spacing={1}>
                            {currentQuantity > 0 && (
                              <>
                                <IconButton
                                  size="xs"
                                  variant="ghost"
                                  colorScheme="red"
                                  aria-label="Remove"
                                  icon={<FaMinus />}
                                  onClick={(e) => {
                                    e.preventDefault();
                                    e.stopPropagation();
                                    handleQuantityChange(suggestion.item!.id, -1);
                                  }}
                                />
                                <Text 
                                  fontSize="sm" 
                                  fontWeight="bold" 
                                  color="white" 
                                  minW="20px" 
                                  textAlign="center"
                                >
                                  {currentQuantity}
                                </Text>
                              </>
                            )}
                            
                            <IconButton
                              size="xs"
                              variant="ghost"
                              colorScheme="green"
                              aria-label="Add"
                              icon={<FaPlus />}
                              onClick={(e) => {
                                e.preventDefault();
                                e.stopPropagation();
                                if (currentQuantity === 0) {
                                  const item = convertCatalogToItem(suggestion.item!);
                                  onItemAdd(item);
                                } else {
                                  handleQuantityChange(suggestion.item!.id, 1);
                                }
                              }}
                            />
                          </HStack>
                        )}
                      </Flex>
                    </Box>
                  );
                })}
                
                {/* Done Button */}
                {suggestions.length > 0 && (
                  <Box p={3} bg="rgba(59, 130, 246, 0.1)" borderTop="1px solid rgba(59, 130, 246, 0.2)">
                    <Button
                      size="sm"
                      colorScheme="blue"
                      variant="solid"
                      w="full"
                      onClick={() => {
                        setIsFocused(false);
                        setHighlightedIndex(-1);
                      }}
                      _hover={{
                        bg: "blue.600",
                        transform: "translateY(-1px)",
                      }}
                      transition="all 0.2s ease"
                    >
                      Done
                    </Button>
                  </Box>
                )}
              </VStack>
            )}
          </Box>
        </Portal>
      )}

      {/* Search Results Count - Removed */}

      {/* Natural Language Processing Results */}
      {value && isNaturalLanguageQuery(value) && showNLPAnalysis && (
        <NLPResultsDisplay
          query={value}
          onAddItems={onAddItems}
          onAddSingleItem={onItemAdd}
          onClose={() => setShowNLPAnalysis(false)}
          selectedItems={selectedItems}
        />
      )}

      {/* Show button to reopen NLP analysis if hidden */}
      {value && isNaturalLanguageQuery(value) && !showNLPAnalysis && (
        <Box textAlign="center" mt={2}>
          <Button
            size="sm"
            colorScheme="blue"
            variant="outline"
            leftIcon={<Icon as={FaBrain} />}
            onClick={() => setShowNLPAnalysis(true)}
          >
            Show Smart Analysis
          </Button>
        </Box>
      )}
    </Box>
  );
};

export default SmartSearchBox;

/**
 * Smart Search Engine with Autocomplete
 * 
 * Provides intelligent search with partial word matching,
 * synonym support, and real-time autocomplete suggestions
 */

'use client';

import React, { useState, useEffect, useMemo, useRef } from 'react';
import {
  Box,
  VStack,
  HStack,
  Input,
  Text,
  Card,
  Badge,
  Icon,
  InputGroup,
  InputLeftElement,
  useDisclosure,
  Collapse,
  Button,
  Flex
} from '@chakra-ui/react';
import { FaSearch, FaBolt, FaClock, FaFire } from 'react-icons/fa';

import type { Item } from '../../../lib/booking/utils';

// Enhanced synonym mapping for better search results
const SEARCH_SYNONYMS: Record<string, string[]> = {
  // Furniture synonyms
  'sofa': ['couch', 'settee', 'loveseat', 'sectional'],
  'couch': ['sofa', 'settee', 'loveseat'],
