  'dining table': ['kitchen table', 'eating table', 'dinner table'],
  'bedside table': ['nightstand', 'night table', 'bedside cabinet'],
  'nightstand': ['bedside table', 'night table'],
  'bookshelf': ['bookcase', 'shelf unit', 'book storage'],
  'tv stand': ['television stand', 'tv unit', 'media unit', 'entertainment center'],
  
  // Appliances synonyms
  'refrigerator': ['fridge', 'icebox', 'cooler'],
  'fridge': ['refrigerator', 'icebox'],
  'washing machine': ['washer', 'laundry machine'],
  'washer': ['washing machine', 'laundry machine'],
  'tumble dryer': ['dryer', 'clothes dryer', 'tumbler'],
  'dryer': ['tumble dryer', 'clothes dryer'],
  'dishwasher': ['dish washer', 'kitchen dishwasher'],
  'microwave': ['microwave oven', 'micro'],
  'vacuum cleaner': ['vacuum', 'hoover', 'carpet cleaner'],
  'vacuum': ['vacuum cleaner', 'hoover'],
  
  // Electronics synonyms
  'television': ['tv', 'telly', 'screen'],
  'tv': ['television', 'telly', 'screen'],
  'computer': ['pc', 'desktop', 'laptop'],
  'laptop': ['notebook', 'computer', 'pc'],
  'desktop': ['computer', 'pc', 'tower'],
  
  // Bedroom synonyms
  'bed': ['mattress', 'sleeping', 'bedroom furniture'],
  'mattress': ['bed', 'sleeping mat', 'bedding'],
  'pillow': ['cushion', 'head rest'],
  'blanket': ['duvet', 'cover', 'bedding'],
  
  // Storage & boxes
  'box': ['container', 'carton', 'package', 'crate'],
  'container': ['box', 'storage', 'bin'],
  'storage': ['container', 'box', 'organizer'],
  
  // Kitchen synonyms
  'stove': ['cooker', 'oven', 'hob'],
  'oven': ['cooker', 'stove', 'range'],
  'sink': ['basin', 'wash basin'],
  
  // General synonyms
  'chair': ['seat', 'seating'],
  'table': ['desk', 'surface'],
  'lamp': ['light', 'lighting', 'illumination'],
  'mirror': ['glass', 'reflection'],
  'plant': ['flower', 'greenery', 'decoration'],
  'picture': ['photo', 'artwork', 'frame', 'painting'],
  'carpet': ['rug', 'mat', 'flooring'],
  'curtain': ['drapes', 'window covering', 'blinds']
};

// Recent searches storage key
const RECENT_SEARCHES_KEY = 'speedyvan_recent_searches';

interface SmartSearchEngineProps {
  items: Item[];
  onSearch: (searchTerm: string) => void;
  onItemSelect?: (item: Item) => void;
  placeholder?: string;
  showTrending?: boolean;
}

interface SearchSuggestion {
  text: string;
  type: 'item' | 'category' | 'recent' | 'synonym';
  item?: Item;
  count?: number;
}

export default function SmartSearchEngine({
  items,
  onSearch,
  onItemSelect,
  placeholder = "Search items (e.g., 'bed', 'wardrobe', 'TV')...",
  showTrending = true
}: SmartSearchEngineProps) {
  const [searchTerm, setSearchTerm] = useState('');
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [recentSearches, setRecentSearches] = useState<string[]>([]);
  const inputRef = useRef<HTMLInputElement>(null);
  const { isOpen: suggestionsOpen, onOpen, onClose } = useDisclosure();

  // Load recent searches from localStorage on mount
  useEffect(() => {
    try {
      const stored = localStorage.getItem(RECENT_SEARCHES_KEY);
      if (stored) {
        setRecentSearches(JSON.parse(stored));
      }
    } catch (error) {
      console.error('Error loading recent searches:', error);
    }
  }, []);

  // Generate search suggestions based on input
  const searchSuggestions = useMemo((): SearchSuggestion[] => {
    if (!searchTerm.trim()) {
      // Show recent searches and trending when no input
      const suggestions: SearchSuggestion[] = [];
      
      // Add recent searches
      recentSearches.slice(0, 3).forEach(recent => {
        suggestions.push({
          text: recent,
          type: 'recent'
        });
      });
      
      // Add trending categories if enabled
      if (showTrending) {
        ['bedroom', 'living room', 'kitchen', 'appliances'].forEach(category => {
          suggestions.push({
            text: category,
            type: 'category'
          });
        });
      }
      
      return suggestions;
    }

    const suggestions: SearchSuggestion[] = [];
    const searchLower = searchTerm.toLowerCase().trim();
    const words = searchLower.split(/\s+/);
    
    // Direct item matches
    items.forEach(item => {
      const itemNameLower = item.name.toLowerCase();
      const itemWords = itemNameLower.split(/\s+/);
      
      // Exact match
      if (itemNameLower.includes(searchLower)) {
        suggestions.push({
          text: item.name,
          type: 'item',
          item: item
        });
        return;
      }
      
      // Partial word matching
      const hasPartialMatch = words.some(searchWord => 
        itemWords.some(itemWord => 
          itemWord.startsWith(searchWord) || searchWord.startsWith(itemWord)
        )
      );
      
      if (hasPartialMatch) {
        suggestions.push({
          text: item.name,
          type: 'item',
          item: item
        });
      }
    });
    
    // Synonym matching
    Object.entries(SEARCH_SYNONYMS).forEach(([key, synonyms]) => {
      if (key.includes(searchLower) || synonyms.some(syn => syn.includes(searchLower))) {
        // Find items that match the key or synonyms
        const matchingItems = items.filter(item => {
          const itemName = item.name.toLowerCase();
          return itemName.includes(key) || 
                 synonyms.some(syn => itemName.includes(syn));
        });
        
        matchingItems.forEach(item => {
          // Avoid duplicates
          if (!suggestions.some(s => s.item?.id === item.id)) {
            suggestions.push({
              text: item.name,
              type: 'synonym',
              item: item
            });
          }
        });
      }
    });
    
    // Category suggestions
    const categories = ['bedroom', 'living', 'kitchen', 'bathroom', 'appliances', 'electronics'];
    categories.forEach(category => {
      if (category.includes(searchLower)) {
        suggestions.push({
          text: `${category} items`,
          type: 'category'
        });
      }
    });
    
    // Remove duplicates and limit results
    const uniqueSuggestions = suggestions.filter((suggestion, index, self) => 
      index === self.findIndex(s => s.text === suggestion.text)
    );
    
    return uniqueSuggestions.slice(0, 8);
  }, [searchTerm, items, recentSearches, showTrending]);

  // Handle search execution
  const handleSearch = (term: string) => {
    const trimmedTerm = term.trim();
    if (!trimmedTerm) return;
    
    // Add to recent searches
    const newRecentSearches = [trimmedTerm, ...recentSearches.filter(s => s !== trimmedTerm)].slice(0, 5);
    setRecentSearches(newRecentSearches);
    
    // Save to localStorage
    try {
      localStorage.setItem(RECENT_SEARCHES_KEY, JSON.stringify(newRecentSearches));
    } catch (error) {
      console.error('Error saving recent searches:', error);
    }
    
    setSearchTerm(trimmedTerm);
    onSearch(trimmedTerm);
    onClose();
  };

  // Handle suggestion click
  const handleSuggestionClick = (suggestion: SearchSuggestion) => {
    if (suggestion.item && onItemSelect) {
      onItemSelect(suggestion.item);
    } else {
      handleSearch(suggestion.text.replace(' items', ''));
    }
  };

  // Handle input changes
  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    setSearchTerm(value);
    
    if (value.trim()) {
      onOpen();
    } else {
      onClose();
    }
  };

  // Handle key events
  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      handleSearch(searchTerm);
    } else if (e.key === 'Escape') {
      onClose();
    }
  };

  // Trending items based on frequency (mock data for now)
  const trendingItems = useMemo(() => {
    const trending = [
      'Double Bed',
      'Wardrobe',
      'Sofa',
      'Dining Table',
      'Refrigerator',
      'Washing Machine',
      'TV',
      'Chest of Drawers'
    ];
    
    return items.filter(item => 
      trending.some(trend => item.name.toLowerCase().includes(trend.toLowerCase()))
    ).slice(0, 4);
  }, [items]);

  return (
    <Box position="relative" w="full">
      <VStack spacing={3} align="stretch">
        {/* Search Input */}
        <InputGroup size="lg">
          <InputLeftElement pointerEvents="none">
            <Icon as={FaSearch} color="gray.400" boxSize={5} />
          </InputLeftElement>
          <Input
            ref={inputRef}
            value={searchTerm}
            onChange={handleInputChange}
            onKeyDown={handleKeyDown}
            onFocus={onOpen}
            placeholder={placeholder}
            borderRadius="xl"
            borderWidth="2px"
            borderColor="purple.200"
            bg="white"
            _focus={{
              borderColor: 'purple.400',
              boxShadow: '0 0 0 1px rgba(128, 90, 213, 0.4)'
            }}
            _hover={{
              borderColor: 'purple.300'
            }}
            fontSize="md"
            pl={12}
          />
        </InputGroup>

        {/* Search Suggestions Dropdown */}
        <Collapse in={suggestionsOpen && searchSuggestions.length > 0} animateOpacity>
          <Card
            bg="white"
            borderRadius="xl"
            shadow="xl"
            borderWidth="1px"
            borderColor="gray.200"
            maxH="300px"
            overflowY="auto"
          >
            <VStack spacing={0} align="stretch" p={2}>
              {searchSuggestions.map((suggestion, index) => (
                <Button
                  key={`${suggestion.type}-${suggestion.text}-${index}`}
                  variant="ghost"
                  justifyContent="flex-start"
                  onClick={() => handleSuggestionClick(suggestion)}
                  p={3}
                  h="auto"
                  borderRadius="lg"
                  _hover={{ bg: 'purple.50' }}
                  textAlign="left"
                >
                  <HStack spacing={3} w="full">
                    <Icon
                      as={
                        suggestion.type === 'recent' ? FaClock :
                        suggestion.type === 'category' ? FaBolt :
                        suggestion.type === 'synonym' ? FaBolt :
                        FaSearch
                      }
                      color={
                        suggestion.type === 'recent' ? 'gray.400' :
                        suggestion.type === 'category' ? 'purple.500' :
                        'blue.500'
                      }
                      boxSize={4}
                      flexShrink={0}
                    />
                    
                    <VStack align="start" spacing={0} flex="1">
                      <Text fontSize="sm" fontWeight="medium" color="gray.800">
                        {suggestion.text}
                      </Text>
                      {suggestion.item && (
                        <Text fontSize="xs" color="gray.500">
                          {suggestion.item.category} • £{suggestion.item.unitPrice}
                        </Text>
                      )}
                    </VStack>
                    
                    <Badge
                      size="sm"
                      colorScheme={
                        suggestion.type === 'recent' ? 'gray' :
                        suggestion.type === 'category' ? 'purple' :
                        suggestion.type === 'synonym' ? 'blue' :
                        'green'
                      }
                      variant="subtle"
                    >
                      {suggestion.type === 'recent' ? 'Recent' :
                       suggestion.type === 'category' ? 'Category' :
                       suggestion.type === 'synonym' ? 'Similar' :
                       'Item'}
                    </Badge>
                  </HStack>
                </Button>
              ))}
            </VStack>
          </Card>
        </Collapse>

        {/* Trending Items Section */}
        {showTrending && !searchTerm && trendingItems.length > 0 && (
          <Card bg="gradient-to-r from-orange.50 to-red.50" borderRadius="xl" p={4}>
            <VStack spacing={3} align="stretch">
              <HStack spacing={2}>
                <Icon as={FaFire} color="orange.500" boxSize={4} />
                <Text fontSize="sm" fontWeight="bold" color="orange.700">
                  Trending Items
                </Text>
                <Badge colorScheme="orange" variant="subtle" fontSize="xs">
                  Popular this week
                </Badge>
              </HStack>
              
              <Flex wrap="wrap" gap={2}>
                {trendingItems.map((item) => (
                  <Button
                    key={item.id}
                    size="sm"
                    variant="outline"
                    colorScheme="orange"
                    onClick={() => onItemSelect?.(item)}
                    borderRadius="full"
                    _hover={{
                      bg: 'orange.100',
                      transform: 'translateY(-1px)',
                      shadow: 'md'
                    }}
                    transition="all 0.2s"
                  >
                    {item.name}
                  </Button>
                ))}
              </Flex>
            </VStack>
          </Card>
        )}

        {/* Quick Search Suggestions */}
        {!searchTerm && (
          <Card bg="purple.50" borderRadius="xl" p={4}>
            <VStack spacing={3} align="stretch">
              <HStack spacing={2}>
                <Icon as={FaBolt} color="purple.500" boxSize={4} />
                <Text fontSize="sm" fontWeight="bold" color="purple.700">
                  Quick Search
                </Text>
              </HStack>
              
              <Flex wrap="wrap" gap={2}>
                {['bedroom furniture', 'kitchen appliances', 'living room', 'electronics', 'storage boxes', 'bathroom items'].map((suggestion) => (
                  <Button
                    key={suggestion}
                    size="sm"
                    variant="solid"
                    colorScheme="purple"
                    onClick={() => handleSearch(suggestion)}
                    borderRadius="full"
                    _hover={{
                      bg: 'purple.600',
                      transform: 'translateY(-1px)',
                      shadow: 'md'
                    }}
                    transition="all 0.2s"
                  >
                    {suggestion}
                  </Button>
                ))}
              </Flex>
            </VStack>
          </Card>
        )}
      </VStack>
    </Box>
  );
}

'use client';

import { useState } from 'react';
import {
  Button,
  VStack,
  HStack,
  Text,
  Spinner,
  Alert,
  AlertIcon,
  AlertTitle,
  AlertDescription,
  Badge,
  Box,
  useToast,
} from '@chakra-ui/react';
import { FaCreditCard, FaLock, FaShieldAlt } from 'react-icons/fa';

interface CustomerData {
  name: string;
  email: string;
  phone: string;
}

interface AddressData {
  address?: string;
  city?: string;
  postcode?: string;
  coordinates?: {
    lat?: number;
    lng?: number;
  };
  houseNumber?: string;
  flatNumber?: string;
  floorNumber?: string;
  formatted_address?: string;
  place_name?: string;
  street?: string;
  full?: string;
  line1?: string;
  number?: string;
  buildingDetails?: {
    flatNumber?: string;
    apartmentNumber?: string;
    floorNumber?: string;
    hasElevator?: boolean;
    type?: string;
  };
}

interface ItemData {
  id?: string;
  name?: string;
  description?: string;
  category?: string;
  size?: 'small' | 'medium' | 'large';
  quantity?: number;
  unitPrice?: number;
  totalPrice?: number;
  weight?: number;
  volume?: number;
  image?: string;
}

interface PropertyDetails {
  type?: 'house' | 'apartment' | 'office' | 'warehouse' | 'other';
  floors?: number;
  hasLift?: boolean;
  hasParking?: boolean;
  accessNotes?: string;
  requiresPermit?: boolean;
  flatNumber?: string;
}

interface PricingData {
  baseFee?: number;
  distanceFee?: number;
  volumeFee?: number;
  serviceFee?: number;
  urgencyFee?: number;
  vat?: number;
  total?: number;
  distance?: number;
}

interface BookingData {
  customer: CustomerData;
  pickupAddress: AddressData;
  dropoffAddress: AddressData;
  items: ItemData[];
  pricing: PricingData;
  serviceType: string;
  scheduledDate: string;
  scheduledTime?: string;
  pickupDetails: PropertyDetails;
  dropoffDetails: PropertyDetails;
  notes?: string;
  bookingId?: string;
  // Three-tier pricing support
  economyPrice?: number;
  standardPrice?: number;
  priorityPrice?: number;
  // Promotion code support
  promotionCode?: string;
  promotionDetails?: {
    id?: string;
    code?: string;
    name?: string;
    description?: string;
    type?: 'percentage' | 'fixed';
    value?: number;
    discountAmount?: number;
    originalAmount?: number;
    finalAmount?: number;
  };
}

const normaliseFlatNumber = (address?: AddressData): string | undefined => {
  if (!address) return undefined;

  const candidates = [
    address.flatNumber,
    address.buildingDetails?.flatNumber,
    address.buildingDetails?.apartmentNumber,
    address.line1?.startsWith('Flat ') ? address.line1 : undefined,
    address.line1?.startsWith('Apartment ') ? address.line1 : undefined,
    address.full?.startsWith('Flat ') ? address.full : undefined,
    address.full?.startsWith('Apartment ') ? address.full : undefined,
  ];

  for (const value of candidates) {
    if (typeof value === 'string' && value.trim().length > 0) {
      const trimmed = value.trim();
      if (/^flat\s+/i.test(trimmed)) {
        const withoutPrefix = trimmed.replace(/^flat\s+/i, '').trim();
        return withoutPrefix.length > 0 ? withoutPrefix : trimmed;
      }
      if (/^apartment\s+/i.test(trimmed)) {
        const withoutApartment = trimmed.replace(/^apartment\s+/i, '').trim();
        return withoutApartment.length > 0 ? withoutApartment : trimmed;
      }
      return trimmed;
    }
  }

  return undefined;
};

const normaliseFloorNumber = (address?: AddressData): string | undefined => {
  if (!address) return undefined;

  const candidates = [
    address.floorNumber,
    address.buildingDetails?.floorNumber,
  ];

  for (const value of candidates) {
    if (typeof value === 'string' && value.trim().length > 0) {
      return value.trim();
    }
  }

  return undefined;
};

// Helper functions for three-tier pricing
const getCorrectTotal = (bookingData: BookingData): number => {
  const serviceType = bookingData.serviceType;
  const baseTotal = bookingData.pricing.total || 0;

  // If promotion is applied, use the final amount from promotion details
  if (bookingData.promotionDetails?.finalAmount) {
    return bookingData.promotionDetails.finalAmount;
  }

  // Otherwise use three-tier pricing
  switch (serviceType) {
    case 'standard':
      return bookingData.economyPrice || (baseTotal * 0.85); // 15% discount for economy
    case 'premium':
      return bookingData.standardPrice || baseTotal; // Standard price
    case 'white-glove':
      return bookingData.priorityPrice || (baseTotal * 1.5); // 50% premium for priority
    default:
      return baseTotal;
  }
};

const getCorrectSubtotal = (bookingData: BookingData): number => {
  const total = getCorrectTotal(bookingData);
  const vat = getCorrectVAT(bookingData);
  return total - vat;
};

const getCorrectVAT = (bookingData: BookingData): number => {
  const total = getCorrectTotal(bookingData);
  // Calculate VAT correctly: VAT = (Total / 1.2) * 0.2
  // This extracts the VAT from a total that already includes VAT
  const subtotal = total / 1.2;
  const vat = subtotal * 0.2;
  return Math.round(vat * 100) / 100; // Round to 2 decimal places
};

interface StripePaymentButtonProps {
  amount: number;
  bookingData: BookingData;
  onSuccess: (sessionId: string, paymentIntentId?: string) => void;
  onError: (error: string) => void;
  disabled?: boolean;
}

export default function StripePaymentButton({
  amount,
  bookingData,
  onSuccess,
  onError,
  disabled = false,
}: StripePaymentButtonProps) {
  const [isProcessing, setIsProcessing] = useState(false);
  const [paymentStatus, setPaymentStatus] = useState<'idle' | 'processing' | 'success' | 'error'>('idle');
  const toast = useToast();

  const handlePayment = async () => {
    if (disabled || isProcessing) return;

    // CRITICAL: Save scroll position before payment processing (mobile only)
    const isMobile = window.innerWidth < 768;
    const scrollY = isMobile ? window.scrollY : undefined;

    setIsProcessing(true);
    setPaymentStatus('processing');

    try {
      // Validate required data
      if (!bookingData.customer.email || !bookingData.customer.name) {
        throw new Error('Customer email and name are required');
      }
      
      // Validate amount (must be in pounds with max 2 decimal places)
      if (!amount || amount <= 0) {
        throw new Error('Valid amount is required');
      }

      // Restore scroll position immediately (mobile only)
      if (isMobile && scrollY !== undefined) {
        requestAnimationFrame(() => {
          window.scrollTo(0, scrollY);
        });
      }

      // Ensure amount has at most 2 decimal places
      const formattedAmount = Math.round(amount * 100) / 100;
      if (formattedAmount !== amount) {
        console.error('❌ Amount has more than 2 decimal places:', {
          original: amount,
          formatted: formattedAmount
        });
        throw new Error('Amount cannot have more than 2 decimal places');
      }

      let bookingId = bookingData.bookingId;

      // Create booking if it doesn't exist yet
      if (!bookingId) {
        // Transform the data to match the API schema
        const pickupFlatNumber = normaliseFlatNumber(bookingData.pickupAddress);
        const dropoffFlatNumber = normaliseFlatNumber(bookingData.dropoffAddress);
        const pickupFloorNumber = normaliseFloorNumber(bookingData.pickupAddress);
        const dropoffFloorNumber = normaliseFloorNumber(bookingData.dropoffAddress);

        const bookingRequest = {
          customer: {
            name: bookingData.customer.name || '',
            email: bookingData.customer.email || '',
            phone: bookingData.customer.phone || '',
          },
          pickupAddress: {
            // Extract street from multiple possible sources
            street: bookingData.pickupAddress.street || 
                   bookingData.pickupAddress.address || 
                   bookingData.pickupAddress.formatted_address ||
                   bookingData.pickupAddress.full ||
                   bookingData.pickupAddress.line1 ||
                   '',
            city: bookingData.pickupAddress.city || 'Unknown City',
            postcode: bookingData.pickupAddress.postcode || '',
            country: 'UK',
            flatNumber: pickupFlatNumber,
            floorNumber: pickupFloorNumber,
            buildingDetails: {
              flatNumber: pickupFlatNumber,
              floorNumber: pickupFloorNumber,
              hasElevator: bookingData.pickupAddress.buildingDetails?.hasElevator,
              type: bookingData.pickupAddress.buildingDetails?.type,
            },
          },
          dropoffAddress: {
            // Extract street from multiple possible sources
            street: bookingData.dropoffAddress.street || 
                   bookingData.dropoffAddress.address || 
                   bookingData.dropoffAddress.formatted_address ||
                   bookingData.dropoffAddress.full ||
                   bookingData.dropoffAddress.line1 ||
                   '',
            city: bookingData.dropoffAddress.city || 'Unknown City',
            postcode: bookingData.dropoffAddress.postcode || '',
            country: 'UK',
            flatNumber: dropoffFlatNumber,
            floorNumber: dropoffFloorNumber,
            buildingDetails: {
              flatNumber: dropoffFlatNumber,
              floorNumber: dropoffFloorNumber,
              hasElevator: bookingData.dropoffAddress.buildingDetails?.hasElevator,
              type: bookingData.dropoffAddress.buildingDetails?.type,
            },
          },
          pickupDetails: {
            type: bookingData.pickupDetails?.type || 'house',
            floors: bookingData.pickupDetails?.floors || 0,
            hasLift: bookingData.pickupDetails?.hasLift
              ?? bookingData.pickupAddress.buildingDetails?.hasElevator
              ?? false,
            hasParking: bookingData.pickupDetails?.hasParking !== false, // Default true
            accessNotes: bookingData.pickupDetails?.accessNotes || '',
            requiresPermit: bookingData.pickupDetails?.requiresPermit || false,
            flatNumber: bookingData.pickupDetails?.flatNumber || pickupFlatNumber,
          },
          dropoffDetails: {
            type: bookingData.dropoffDetails?.type || 'house',
            floors: bookingData.dropoffDetails?.floors || 0,
            hasLift: bookingData.dropoffDetails?.hasLift
              ?? bookingData.dropoffAddress.buildingDetails?.hasElevator
              ?? false,
            hasParking: bookingData.dropoffDetails?.hasParking !== false, // Default true
            accessNotes: bookingData.dropoffDetails?.accessNotes || '',
            requiresPermit: bookingData.dropoffDetails?.requiresPermit || false,
            flatNumber: bookingData.dropoffDetails?.flatNumber || dropoffFlatNumber,
          },
          items: bookingData.items.map(item => ({
            id: item.id || `item-${Date.now()}-${Math.random()}`,
            name: item.name || 'Unknown Item',
            quantity: item.quantity || 1,
            category: item.category || 'furniture',
            volumeFactor: item.volume || 0.1,
            requiresTwoPerson: false,
            isFragile: false,
            requiresDisassembly: false,
          })),
          pickupDate: bookingData.scheduledDate ? new Date(bookingData.scheduledDate).toISOString() : undefined,
          pickupTimeSlot: bookingData.scheduledTime || 'flexible',
          urgency: 'scheduled' as const,
          notes: bookingData.notes || '',
          pricing: {
            subtotal: Math.round(getCorrectSubtotal(bookingData) * 100) / 100,
            vat: Math.round(getCorrectVAT(bookingData) * 100) / 100,
            total: Math.round(getCorrectTotal(bookingData) * 100) / 100,
            currency: 'GBP',
          },
        };

        // Validate all required fields before sending
        const requiredFields = [
          { field: 'customer.name', value: bookingRequest.customer.name },
          { field: 'customer.email', value: bookingRequest.customer.email },
          { field: 'customer.phone', value: bookingRequest.customer.phone },
          { field: 'pickupAddress.street', value: bookingRequest.pickupAddress.street },
          { field: 'dropoffAddress.street', value: bookingRequest.dropoffAddress.street },
          { field: 'items', value: bookingRequest.items.length > 0 },
          { field: 'pricing.total', value: bookingRequest.pricing.total > 0 }
        ];

        const missingFields = requiredFields.filter(field => !field.value);
        if (missingFields.length > 0) {
          const missingFieldNames = missingFields.map(f => f.field).join(', ');
          throw new Error(`Missing required fields: ${missingFieldNames}`);
        }

        console.log('🔍 Sending booking request:', {
          customer: bookingRequest.customer.name,
          pickup: bookingRequest.pickupAddress.street,
          dropoff: bookingRequest.dropoffAddress.street,
          items: bookingRequest.items.length,
          pricing: `£${bookingRequest.pricing.total}`
        });

        const bookingResponse = await fetch('/api/booking-luxury', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify(bookingRequest),
        });

        if (!bookingResponse.ok) {
          const errorData = await bookingResponse.json();
          console.error('❌ Booking API error:', {
            status: bookingResponse.status,
            error: errorData.error,
            details: errorData.details,
            validationErrors: errorData.validationErrors
          });
          
          if (errorData.validationErrors && Array.isArray(errorData.validationErrors)) {
            const errorMessages = errorData.validationErrors.map((err: any) => `${err.field}: ${err.message}`).join(', ');
            throw new Error(`Validation failed: ${errorMessages}`);
          }
          
          throw new Error(errorData.error || `Failed to create booking (${bookingResponse.status})`);
        }

        const bookingResponseData = await bookingResponse.json();
        bookingId = bookingResponseData.booking.id;
      }

      const requestData = {
        amount: formattedAmount,
        currency: 'gbp',
        customerEmail: bookingData.customer.email,
        customerName: bookingData.customer.name,
        bookingData: {
          ...bookingData,
          bookingId: bookingId, // Use the booking ID
        },
        successUrl: `${window.location.origin}/booking-luxury/success?session_id={CHECKOUT_SESSION_ID}`,
        cancelUrl: `${window.location.origin}/booking-luxury?step=1&payment=cancelled`,
      };
      
      // Create Stripe checkout session
      const response = await fetch('/api/payment/create-checkout-session', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(requestData),
      });

      if (!response.ok) {
        const errorData = await response.json();
        console.error('❌ Server response:', errorData);
        throw new Error(errorData.error || 'Failed to create checkout session');
      }

      const { sessionUrl, sessionId } = await response.json();
      
      // Redirect to Stripe Checkout
      window.location.href = sessionUrl;
      
    } catch (error) {
      console.error('❌ Payment error:', error);
      setPaymentStatus('error');
      const errorMessage = error instanceof Error ? error.message : 'Payment failed';
      onError(errorMessage);
      
      toast({
        title: 'Payment Error',
        description: errorMessage,
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <VStack spacing={4} align="stretch" w="full">
      <Box position="relative" w="full">
        <Button
          size="xl"
          h={{ base: "64px", md: "72px" }}
          fontSize={{ base: "xl", md: "2xl" }}
          fontWeight="700"
          letterSpacing="0.5px"
          w="full"
          bg="linear-gradient(135deg, #10B981 0%, #059669 50%, #047857 100%)"
          color="white"
          onClick={(e) => {
            e.preventDefault();
            e.stopPropagation();
            handlePayment();
          }}
          isDisabled={disabled || isProcessing}
          leftIcon={
            isProcessing ? (
              <Spinner size="md" color="white" thickness="3px" speed="0.8s" />
            ) : (
              <Box
                as={FaCreditCard}
                fontSize="24px"
                filter="drop-shadow(0 2px 4px rgba(0, 0, 0, 0.3))"
              />
            )
          }
          borderRadius="xl"
          border="2px solid"
          borderColor="rgba(16, 185, 129, 0.5)"
          boxShadow="0 8px 32px rgba(16, 185, 129, 0.4), 0 0 60px rgba(16, 185, 129, 0.2), inset 0 1px 0 rgba(255, 255, 255, 0.2)"
          _hover={{
            transform: "translateY(-4px) scale(1.02)",
            shadow: "0 12px 40px rgba(16, 185, 129, 0.5), 0 0 80px rgba(16, 185, 129, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.3)",
            bg: "linear-gradient(135deg, #059669 0%, #047857 50%, #065F46 100%)",
            borderColor: "rgba(16, 185, 129, 0.7)",
          }}
          _active={{
            transform: "translateY(-2px) scale(0.98)",
            shadow: "0 4px 20px rgba(16, 185, 129, 0.4), inset 0 1px 0 rgba(255, 255, 255, 0.2)",
          }}
          _disabled={{
            opacity: 0.6,
            cursor: "not-allowed",
            transform: "none",
            bg: "linear-gradient(135deg, #6B7280 0%, #4B5563 100%)",
            borderColor: "rgba(107, 114, 128, 0.5)",
            boxShadow: "none",
          }}
          transition="all 0.3s cubic-bezier(0.4, 0, 0.2, 1)"
          position="relative"
          overflow="hidden"
          _before={{
            content: '""',
            position: "absolute",
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            background: "linear-gradient(135deg, rgba(255, 255, 255, 0.15) 0%, rgba(255, 255, 255, 0.05) 100%)",
            opacity: 0.6,
            zIndex: 0,
            pointerEvents: "none",
          }}
          _after={{
            content: '""',
            position: "absolute",
            top: 0,
            left: "-100%",
            width: "100%",
            height: "100%",
            background: "linear-gradient(90deg, transparent, rgba(255,255,255,0.3), transparent)",
            animation: !disabled && !isProcessing ? "shineAnimation 3s infinite" : "none",
            zIndex: 1,
            pointerEvents: "none",
          }}
          sx={{
            "@keyframes shineAnimation": {
              "0%": { left: "-100%" },
              "50%": { left: "100%" },
              "100%": { left: "100%" },
            },
            "& > *": {
              position: "relative",
              zIndex: 2,
            },
          }}
        >
          {isProcessing ? (
            <HStack spacing={2}>
              <Text>Processing Payment...</Text>
            </HStack>
          ) : (
            <HStack spacing={3} align="center">
              <Text fontSize={{ base: "xl", md: "2xl" }} fontWeight="700" letterSpacing="0.5px">
                Pay Now
              </Text>
              <Box
                as={FaLock}
                fontSize="16px"
                opacity={0.9}
                filter="drop-shadow(0 1px 2px rgba(0, 0, 0, 0.2))"
              />
            </HStack>
          )}
        </Button>
      </Box>

      {paymentStatus === 'error' && (
        <Alert status="error">
          <AlertIcon />
          <Box>
            <AlertTitle>Payment Failed</AlertTitle>
            <AlertDescription>
              Please try again or contact support if the problem persists.
            </AlertDescription>
          </Box>
        </Alert>
      )}

      <VStack spacing={4} align="center" pt={2}>
        <HStack justify="center" spacing={6} fontSize="sm" color="rgba(255, 255, 255, 0.7)">
          <HStack spacing={2} align="center">
            <Box
              as={FaLock}
              color="#10B981"
              fontSize="16px"
              filter="drop-shadow(0 2px 4px rgba(16, 185, 129, 0.4))"
            />
            <Text fontWeight="600" letterSpacing="0.2px">Secure Payment</Text>
          </HStack>
          <HStack spacing={2} align="center">
            <Box
              as={FaShieldAlt}
              color="#10B981"
              fontSize="16px"
              filter="drop-shadow(0 2px 4px rgba(16, 185, 129, 0.4))"
            />
            <Text fontWeight="600" letterSpacing="0.2px">Protected by Stripe</Text>
          </HStack>
        </HStack>

        <HStack spacing={4} align="center" flexWrap="wrap" justify="center">
          <Badge
            bg="linear-gradient(135deg, rgba(16, 185, 129, 0.3) 0%, rgba(5, 150, 105, 0.2) 100%)"
            color="white"
            px={5}
            py={2.5}
            borderRadius="full"
            fontSize="2xs"
            fontWeight="600"
            letterSpacing="0.2px"
            border="2px solid"
            borderColor="rgba(16, 185, 129, 0.4)"
            boxShadow="0 4px 12px rgba(16, 185, 129, 0.2), inset 0 1px 0 rgba(255, 255, 255, 0.2)"
          >
            🔒 Bank-level Security
          </Badge>
          <Badge
            bg="linear-gradient(135deg, rgba(59, 130, 246, 0.3) 0%, rgba(37, 99, 235, 0.2) 100%)"
            color="white"
            px={5}
            py={2.5}
            borderRadius="full"
            fontSize="2xs"
            fontWeight="600"
            letterSpacing="0.2px"
            border="2px solid"
            borderColor="rgba(59, 130, 246, 0.4)"
            boxShadow="0 4px 12px rgba(59, 130, 246, 0.2), inset 0 1px 0 rgba(255, 255, 255, 0.2)"
          >
            ⚡ Instant Processing
          </Badge>
        </HStack>

        <Text fontSize="xs" color="rgba(255, 255, 255, 0.6)" textAlign="center" maxW="400px" fontWeight="500" letterSpacing="0.2px" lineHeight="1.6">
          Your payment information is encrypted and secure. We never store your card details.
        </Text>
      </VStack>
    </VStack>
  );
}

'use client';

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import {
  Box,
  VStack,
  HStack,
  Heading,
  Text,
  Button,
  Input,
  InputGroup,
  InputLeftElement,
  IconButton,
  useToast,
  Divider,
  Icon,
  SimpleGrid,
  Select,
  NumberInput,
  NumberInputField,
  NumberInputStepper,
  NumberIncrementStepper,
  NumberDecrementStepper,
  Switch,
  FormLabel,
  FormControl,
  FormErrorMessage,
  Badge,
  Flex,
  Card,
  CardBody,
  Circle,
  useDisclosure,
  Progress,
  Container,
  Tooltip,
  Image,
  Grid,
  Portal,
  Drawer,
  DrawerOverlay,
  DrawerContent,
  DrawerHeader,
  DrawerBody,
  DrawerCloseButton,
} from '@chakra-ui/react';

import {
  FaMapMarkerAlt,
  FaBolt,
  FaTrash,
  FaBuilding,
  FaParking,
  FaTags,
  FaCalendarAlt,
  FaClock,
  FaSearch,
  FaPlus,
  FaMinus,
  FaCheck,
  FaCheckCircle,
  FaArrowUp,
  FaArrowDown,
  FaHome,
  FaCouch,
  FaBed,
  FaTv,
  FaUtensils,
  FaTshirt,
  FaFire,
  FaCoffee,
  FaChair,
  FaBoxOpen,
  FaArrowLeft,
  FaArrowRight,
  FaEye,
} from 'react-icons/fa';
import { MdElevator, MdKitchen, MdLocalLaundryService, MdTv } from 'react-icons/md';

import type { FormData } from '../hooks/useBookingForm';
import { 
  ALL_REMOVAL_ITEMS, 
  getAllCategories, 
  filterItemsByCategory, 
  searchItems,
  getSubcategories,
  filterItemsByWeight,
  sortItems,
  getPopularItems,
  getItemPackages
} from '@/lib/uk-removal-items-data';

interface WhereAndWhatStepProps {
  formData: FormData;
  updateFormData: (step: keyof FormData, data: Partial<FormData[keyof FormData]>) => void;
  errors: Record<string, string>;
  onNext?: () => void;
  onBack?: () => void;
  calculatePricing?: () => void;
  pricingTiers?: any;
  availabilityData?: any;
  isLoadingAvailability?: boolean;
}

export default function WhereAndWhatStep({
  formData,
  updateFormData,
  errors,
  onNext,
  onBack,
  calculatePricing,
  pricingTiers,
  availabilityData,
  isLoadingAvailability,
}: WhereAndWhatStepProps) {
  
  // State for item selection mode
  const [itemSelectionMode, setItemSelectionMode] = useState<'smart' | 'choose' | 'packages'>('choose');
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('Bedroom');
  
  // ✅ NEW: Advanced filtering and sorting
  const [selectedSubcategory, setSelectedSubcategory] = useState('All');
  const [sortBy, setSortBy] = useState<'popular' | 'weight-asc' | 'weight-desc' | 'name-asc' | 'name-desc'>('popular');
  const [minWeight, setMinWeight] = useState<number | undefined>(undefined);
  const [maxWeight, setMaxWeight] = useState<number | undefined>(undefined);
  const [showPopularFirst, setShowPopularFirst] = useState(true);
  
  const { step1 } = formData;
  const toast = useToast();
  const {
    isOpen: isSelectedItemsPanelOpen,
    onOpen: onSelectedItemsPanelOpen,
    onClose: onSelectedItemsPanelClose,
  } = useDisclosure();

  useEffect(() => {
    if (step1.items.length === 0 && isSelectedItemsPanelOpen) {
      onSelectedItemsPanelClose();
    }
  }, [step1.items.length, isSelectedItemsPanelOpen, onSelectedItemsPanelClose]);

  // Get all categories and subcategories
  const categories = getAllCategories();
  const subcategories = useMemo(() => 
    getSubcategories(selectedCategory),
    [selectedCategory]
  );
  
  // ✅ Get predefined packages
  const packages = useMemo(() => getItemPackages(), []);

  // ✅ ENHANCED: Filtered items with advanced sorting and filtering
  const displayedItems = useMemo(() => {
    let items: any[] = [];
    
    // Step 1: Get base items based on mode
    if (itemSelectionMode === 'smart' && searchQuery) {
      items = searchItems(searchQuery);
    } else if (itemSelectionMode === 'choose' && selectedCategory) {
      items = filterItemsByCategory(selectedCategory);
      
      // Apply subcategory filter if selected
      if (selectedSubcategory && selectedSubcategory !== 'All') {
        const subcategoryLower = selectedSubcategory.toLowerCase();
        items = items.filter(item => 
          item.name.toLowerCase().includes(subcategoryLower) ||
          item.name.toLowerCase().includes(subcategoryLower.slice(0, -1)) // Remove 's' for singular
        );
      }
    } else if (itemSelectionMode === 'packages') {
      // Show popular items for package mode
      items = getPopularItems(50);
    } else {
      items = ALL_REMOVAL_ITEMS;
    }
    
    // Step 2: Apply weight filter if set
    if (minWeight !== undefined || maxWeight !== undefined) {
      items = filterItemsByWeight(items, minWeight, maxWeight);
    }
    
    // Step 3: Apply sorting
    items = sortItems(items, sortBy);
    
    return items;
  }, [itemSelectionMode, searchQuery, selectedCategory, selectedSubcategory, sortBy, minWeight, maxWeight]);

  const bedroomPackages = [
    { id: '1bedroom', name: '1 Bedroom', packageKey: '1bedroom', image: '/items/one%20bedroom.png' },
    { id: '2bedroom', name: '2 Bedrooms', packageKey: '2bedroom', image: '/items/2%20bedroom.png' },
    { id: '3bedroom', name: '3 Bedrooms', packageKey: '3bedroom', image: '/items/3%20bed%20rooms.png' },
    { id: '4bedroom', name: '4 Bedrooms', packageKey: '4bedroom', image: '/items/one%20bedroom.png' },
    { id: '5bedroom', name: '5 Bedrooms', packageKey: '5bedroom', image: '/items/one%20bedroom.png' },
  ];

  // Handlers
  const addItem = (item: any) => {
    // Save scroll position before update (mobile only)
    const isMobile = window.innerWidth < 768;
    const scrollY = isMobile ? window.scrollY : undefined;
    
    const currentItems = step1.items || [];
    const existingItem = currentItems.find((i: any) => i.id === item.id);
    if (existingItem) {
      const updatedItems = currentItems.map((i: any) => 
        i.id === item.id ? { ...i, quantity: (i.quantity || 0) + 1 } : i
      );
      // Force update by creating a new array reference
      updateFormData('step1', {
        items: [...updatedItems]
      });
    } else {
      const newItem = { ...item, quantity: 1 };
      updateFormData('step1', {
        items: [...currentItems, newItem]
      });
    }
    
    // Restore scroll position after update (mobile only)
    if (isMobile && scrollY !== undefined) {
      requestAnimationFrame(() => {
        window.scrollTo(0, scrollY);
      });
    }
  };

  const removeItem = (itemId: any) => {
    // Save scroll position before update (mobile only)
    const isMobile = window.innerWidth < 768;
    const scrollY = isMobile ? window.scrollY : undefined;
    
    const currentItems = step1.items || [];
    const filteredItems = currentItems.filter((i: any) => i.id !== itemId);
    // Force update by creating a new array reference
    updateFormData('step1', {
      items: [...filteredItems]
    });
    
    // Restore scroll position after update (mobile only)
    if (isMobile && scrollY !== undefined) {
      requestAnimationFrame(() => {
        window.scrollTo(0, scrollY);
      });
    }
  };

  const updateQuantity = (itemId: any, quantity: number, item?: any) => {
    // Save scroll position before update (mobile only)
    const isMobile = window.innerWidth < 768;
    const scrollY = isMobile ? window.scrollY : undefined;
    
    if (quantity === 0) {
      removeItem(itemId);
    } else {
      const currentItems = step1.items || [];
      const existingItem = currentItems.find((i: any) => i.id === itemId);
      
      if (existingItem) {
        // Update existing item - create new array to ensure change detection
        const updatedItems = currentItems.map((i: any) =>
          i.id === itemId ? { ...i, quantity } : i
        );
        // Force update by creating a new array reference
        updateFormData('step1', {
          items: [...updatedItems]
        });
      } else if (item) {
        // Add new item if it doesn't exist
        const newItem = { ...item, quantity };
        updateFormData('step1', {
          items: [...currentItems, newItem]
        });
      } else {
        // Fallback: try to find item from displayed items
        console.warn(`Item ${itemId} not found in current items and no item provided`);
        // Don't add item without proper data - log warning only
      }
    }
    
    // Restore scroll position after update (mobile only)
    if (isMobile && scrollY !== undefined) {
      requestAnimationFrame(() => {
        window.scrollTo(0, scrollY);
      });
    }
  };

  const getItemQuantity = (itemId: any) => {
    const item = step1.items.find(i => i.id === itemId);
    return item ? item.quantity : 0;
  };

  const renderSelectedItemsContent = (options?: { includeHeading?: boolean }) => {
    if (step1.items.length === 0) {
      return null;
    }

    const includeHeading = options?.includeHeading ?? true;

    return (
      <VStack spacing={4}>
        {includeHeading && (
          <Heading size={{ base: "sm", md: "md" }} color="white">
            ✅ Selected Items ({step1.items.length})
          </Heading>
        )}

        <VStack
          spacing={3}
          w="full"
          className="selected-items-cart"
          style={{ display: 'flex', flexDirection: 'column' } as React.CSSProperties}
        >
          {step1.items.map((item) => (
            <Box
              key={item.id}
              w="full"
              p={{ base: 2, md: 3 }}
              bg="rgba(17, 24, 39, 0.95)"
              borderRadius="xl"
              border="1px solid"
              borderColor="rgba(16, 185, 129, 0.2)"
              _hover={{
                borderColor: "rgba(16, 185, 129, 0.4)",
                boxShadow: "0 4px 12px rgba(16, 185, 129, 0.15)",
              }}
              transition="all 0.2s"
            >
              {/* Item Image */}
              <HStack spacing={3} mb={2}>
                {item.image && (
                  <Image
                    src={item.image}
                    alt={item.name}
                    w={{ base: "60px", md: "70px" }}
                    h={{ base: "60px", md: "70px" }}
                    objectFit="cover"
                    flexShrink={0}
                    border="none"
                    borderRadius="0"
                    boxShadow="none"
                    display="block"
                  />
                )}
                
                {/* Item Name & Weight */}
                <VStack align="start" spacing={1} flex={1}>
                  <Text
                    color="white"
                    fontWeight="bold"
                    fontSize={{ base: "md", md: "lg" }}
                    noOfLines={2}
                  >
                    {item.name}
                  </Text>
                  {item.weight && (
                    <HStack spacing={1}>
                      <Text fontSize="xs" color="gray.400">Weight:</Text>
                      <Text fontSize="sm" color="green.400" fontWeight="semibold">
                        {item.weight}kg
                      </Text>
                    </HStack>
                  )}
                </VStack>
              </HStack>

              {/* Quantity Controls */}
              <HStack 
                justify="space-between" 
                bg="rgba(31, 41, 55, 0.6)"
                p={2}
                borderRadius="lg"
              >
                <Text fontSize="sm" color="gray.300" fontWeight="medium">
                  Quantity:
                </Text>
                <HStack spacing={2}>
                  <IconButton
                    size="sm"
                    icon={<FaMinus />}
                    onClick={() => updateQuantity(item.id, item.quantity - 1, item)}
                    bg="rgba(107, 114, 128, 0.6)"
                    color="white"
                    _hover={{ bg: "rgba(107, 114, 128, 0.8)" }}
                    aria-label="Decrease quantity"
                    borderRadius="md"
                    minW="32px"
                    h="32px"
                  />
                  <Text 
                    color="white" 
                    fontWeight="bold" 
                    fontSize="lg"
                    minW="40px"
                    textAlign="center"
                    bg="rgba(16, 185, 129, 0.1)"
                    px={3}
                    py={1}
                    borderRadius="md"
                  >
                    {item.quantity}
                  </Text>
                  <IconButton
                    size="sm"
                    icon={<FaPlus />}
                    onClick={() => updateQuantity(item.id, item.quantity + 1, item)}
                    bg="linear-gradient(135deg, #10b981 0%, #059669 100%)"
                    color="white"
                    _hover={{ bg: "linear-gradient(135deg, #059669 0%, #047857 100%)" }}
                    aria-label="Increase quantity"
                    borderRadius="md"
                    minW="32px"
                    h="32px"
                  />
                </HStack>
              </HStack>
            </Box>
          ))}
        </VStack>

        {pricingTiers && (
          <VStack spacing={2} w="full" mt={4}>
            <Divider borderColor="rgba(16, 185, 129, 0.3)" />
            <Heading size="sm" color="white" textAlign="center">
              💰 Enterprise Engine Pricing
            </Heading>
            <SimpleGrid columns={{ base: 1, md: 3 }} spacing={3} w="full">
              {pricingTiers.economy && (
                <Box p={3} bg="rgba(59, 130, 246, 0.2)" borderRadius="lg" border="1px solid" borderColor="rgba(59, 130, 246, 0.3)">
                  <Text fontSize="xs" color="gray.400" mb={1}>Economy</Text>
                  <Text fontSize="lg" color="white" fontWeight="bold">
                    £{pricingTiers.economy.price?.toFixed(2) || '0.00'}
                  </Text>
                </Box>
              )}
              {pricingTiers.standard && (
                <Box p={3} bg="rgba(16, 185, 129, 0.2)" borderRadius="lg" border="1px solid" borderColor="rgba(16, 185, 129, 0.3)">
                  <Text fontSize="xs" color="gray.400" mb={1}>Standard</Text>
                  <Text fontSize="lg" color="white" fontWeight="bold">
                    £{pricingTiers.standard.price?.toFixed(2) || '0.00'}
                  </Text>
                </Box>
              )}
              {pricingTiers.express && (
                <Box p={3} bg="rgba(239, 68, 68, 0.2)" borderRadius="lg" border="1px solid" borderColor="rgba(239, 68, 68, 0.3)">
                  <Text fontSize="xs" color="gray.400" mb={1}>Express</Text>
                  <Text fontSize="lg" color="white" fontWeight="bold">
                    £{pricingTiers.express.price?.toFixed(2) || '0.00'}
                  </Text>
                </Box>
              )}
            </SimpleGrid>
          </VStack>
        )}
        {!pricingTiers && (
          <Text fontSize="sm" color="gray.400" textAlign="center" fontStyle="italic">
            Final price calculated by Enterprise Engine based on route optimization
          </Text>
        )}
      </VStack>
    );
  };

  return (
    <Container maxW={{ base: "full", md: "6xl" }} px={{ base: 4, md: 8 }} py={{ base: 6, md: 8 }}>
      <VStack
        spacing={{ base: 6, md: 8 }}
        align="stretch"
        pb={{ base: step1.items.length > 0 ? 140 : 0, lg: 0 }}
      >
        
        {/* Header */}
        <VStack spacing={{ base: 3, md: 4 }} textAlign="center">
          <Heading 
            size={{ base: "lg", md: "xl" }} 
            color="white"
            bgGradient="linear(to-r, #10b981, #3b82f6, #a855f7)"
            bgClip="text"
            fontWeight="800"
            letterSpacing="tight"
          >
            🚚 What needs moving?
          </Heading>
          <Text color="gray.300" fontSize={{ base: "md", md: "lg" }} maxW="700px" lineHeight="1.6">
            Select your moving date and choose items - Enterprise Engine will calculate the best price
          </Text>
        </VStack>

        {/* Date & Time Selection */}
        <Card 
          bg="linear-gradient(135deg, rgba(31, 41, 55, 0.98) 0%, rgba(26, 32, 44, 0.95) 100%)"
          backdropFilter="blur(20px)"
          borderRadius="xl"
          border="2px solid"
          borderColor="rgba(168, 85, 247, 0.4)"
          boxShadow="0 8px 32px rgba(168, 85, 247, 0.3)"
        >
          <CardBody p={{ base: 4, md: 6 }}>
            <VStack spacing={{ base: 4, md: 6 }} align="stretch">
              
              {/* Header */}
              <VStack spacing={2} textAlign="center">
                <Heading size={{ base: "md", md: "lg" }} color="white">
                  📅 When do you need the move?
                </Heading>
                <Text color="gray.300" fontSize={{ base: "sm", md: "md" }}>
                  Select your preferred date and time
                </Text>
              </VStack>

              <SimpleGrid columns={{ base: 1, md: 2 }} spacing={{ base: 3, md: 4 }}>
                {/* Date */}
                <FormControl isInvalid={!!errors['step1.pickupDate']}>
                  <FormLabel color="white" fontSize={{ base: "sm", md: "md" }}>📅 Select Date</FormLabel>
                  <Input
                    type="date"
                    value={step1.pickupDate || ''}
                    onChange={(e) => updateFormData('step1', { pickupDate: e.target.value })}
                    min={(() => {
                      const tomorrow = new Date();
                      tomorrow.setDate(tomorrow.getDate() + 1);
                      return tomorrow.toISOString().split('T')[0];
                    })()}
                    bg="rgba(26, 26, 26, 0.8)"
                    borderColor="rgba(59, 130, 246, 0.3)"
                    color="white"
                    size="lg"
                    borderRadius="xl"
                    borderWidth="1px"
                    fontWeight="500"
                    _hover={{
                      borderColor: "rgba(59, 130, 246, 0.5)",
                      bg: "rgba(26, 26, 26, 0.9)",
                    }}
                    _focus={{
                      borderColor: "blue.500",
                      boxShadow: "0 0 0 1px rgba(59, 130, 246, 0.3)",
                      bg: "rgba(26, 26, 26, 0.95)",
                    }}
                    sx={{
                      colorScheme: 'dark',
                      '&::-webkit-calendar-picker-indicator': {
                        filter: 'invert(1)',
                        cursor: 'pointer',
                      },
                      '&::-webkit-datetime-edit': {
                        color: 'white',
                      },
                      '&::-webkit-datetime-edit-fields-wrapper': {
                        color: 'white',
                      },
                      '&::-webkit-datetime-edit-text': {
                        color: 'gray.400',
                      },
                      '&::-webkit-datetime-edit-month-field': {
                        color: 'white',
                      },
                      '&::-webkit-datetime-edit-day-field': {
                        color: 'white',
                      },
                      '&::-webkit-datetime-edit-year-field': {
                        color: 'white',
                      },
                    }}
                  />
                  {errors['step1.pickupDate'] && (
                    <FormErrorMessage>{errors['step1.pickupDate']}</FormErrorMessage>
                  )}
                </FormControl>

                {/* Time */}
                <FormControl isInvalid={!!errors['step1.pickupTime']}>
                  <FormLabel color="white" fontSize={{ base: "sm", md: "md" }}>⏰ Select Time</FormLabel>
                  <Select
                    mb={4}
                    value={step1.pickupTimeSlot || ''}
                    onChange={(e) => updateFormData('step1', { pickupTimeSlot: e.target.value })}
                    bg="white"
                    borderColor="rgba(59, 130, 246, 0.4)"
                    color="gray.900"
                    size="lg"
                    borderRadius="xl"
                    borderWidth="2px"
                    fontWeight="600"
                    cursor="pointer"
                    placeholder="Choose a time"
                    _placeholder={{
                      color: 'gray.500',
                      fontWeight: '500',
                    }}
                    _hover={{
                      borderColor: "rgba(59, 130, 246, 0.7)",
                      boxShadow: "0 4px 12px rgba(59, 130, 246, 0.15)"
                    }}
                    _focus={{
                      borderColor: "blue.500",
                      boxShadow: "0 0 0 3px rgba(59, 130, 246, 0.25)",
                      outline: "none",
                    }}
                    transition="all 0.2s ease"
                    iconColor="gray.700"
                    sx={{
                      '& option': {
                        backgroundColor: 'white',
                        color: '#111827',
                        padding: '14px',
                        fontSize: '15px',
                        fontWeight: '600',
                        lineHeight: '1.5',
                      },
                      '& option:hover': {
                        backgroundColor: '#f3f4f6',
                      },
                      '& option:checked': {
                        backgroundColor: '#3b82f6',
                        color: 'white',
                      },
                    }}
                  >
                    <option value="08:00-12:00">8 AM - 12 PM 🌅</option>
                    <option value="12:00-16:00">12 PM - 4 PM ☀️</option>
                    <option value="16:00-18:00">4 PM - 6 PM 🌆</option>
                    <option value="flexible">Flexible ⏰</option>
                  </Select>
                  {errors['step1.pickupTime'] && (
                    <FormErrorMessage>{errors['step1.pickupTime']}</FormErrorMessage>
                  )}
                </FormControl>
              </SimpleGrid>
            </VStack>
          </CardBody>
        </Card>

        {/* Item Selection */}
        <Card 
          bg="linear-gradient(135deg, rgba(31, 41, 55, 0.98) 0%, rgba(26, 32, 44, 0.95) 100%)"
          backdropFilter="blur(20px)"
          borderRadius="xl"
          border="2px solid"
          borderColor="rgba(59, 130, 246, 0.4)"
          boxShadow="0 8px 32px rgba(59, 130, 246, 0.3)"
        >
          <CardBody p={{ base: 4, md: 6 }}>
            <VStack spacing={{ base: 4, md: 6 }}>
              
              {/* Header */}
              <VStack spacing={2} textAlign="center">
                <Heading 
                  size={{ base: "md", md: "lg" }} 
                  color="white"
                  bgGradient="linear(to-r, #3b82f6, #a855f7, #10b981)"
                  bgClip="text"
                >
                  📦 Select Your Items
                </Heading>
                <Text color="gray.300" fontSize={{ base: "sm", md: "md" }}>
                  Choose how you'd like to add items
                </Text>
              </VStack>

              {/* Stats */}
              <SimpleGrid columns={{ base: 2, md: 3 }} spacing={4} w="full">
                <VStack spacing={1} bg="rgba(59, 130, 246, 0.1)" p={3} borderRadius="lg" border="1px solid" borderColor="rgba(59, 130, 246, 0.3)">
                  <Text fontSize={{ base: "lg", md: "xl" }} fontWeight="bold" color="blue.400">
                    {ALL_REMOVAL_ITEMS.length}
                  </Text>
                  <Text fontSize={{ base: "xs", md: "sm" }} color="gray.300" textAlign="center">
                    Total Items
                  </Text>
                </VStack>
                
                <VStack spacing={1} bg="rgba(168, 85, 247, 0.1)" p={3} borderRadius="lg" border="1px solid" borderColor="rgba(168, 85, 247, 0.3)">
                  <Text fontSize={{ base: "lg", md: "xl" }} fontWeight="bold" color="purple.400">
                    {categories.length - 1}
                  </Text>
                  <Text fontSize={{ base: "xs", md: "sm" }} color="gray.300" textAlign="center">
                    Categories
                  </Text>
                </VStack>
                
                <VStack spacing={1} bg="rgba(16, 185, 129, 0.1)" p={3} borderRadius="lg" border="1px solid" borderColor="rgba(16, 185, 129, 0.3)">
                  <Text fontSize={{ base: "lg", md: "xl" }} fontWeight="bold" color="green.400">
                    {bedroomPackages.length}
                  </Text>
                  <Text fontSize={{ base: "xs", md: "sm" }} color="gray.300" textAlign="center">
                    Packages
                  </Text>
                </VStack>
              </SimpleGrid>

              {/* Selection Modes - Vertical on Mobile, Horizontal on Desktop */}
              <SimpleGrid columns={{ base: 2, md: 3 }} spacing={{ base: 2, md: 3 }} w="full">
                <Button 
                  className="booking-luxury-selection-button"
                  size={{ base: "xs", md: "lg" }}
                  fontSize={{ base: "3px", sm: "2xs", md: "sm" }}
                  px={{ base: 2, md: 4 }}
                  py={{ base: 2, md: 2 }}
                  bg={itemSelectionMode === 'smart' 
                    ? 'linear-gradient(135deg, #a855f7 0%, #9333ea 100%)' 
                    : 'rgba(31, 41, 55, 0.6)'}
                  color="white"
                  border="2px solid"
                  borderColor={itemSelectionMode === 'smart' ? 'rgba(168, 85, 247, 0.5)' : 'rgba(255, 255, 255, 0.1)'}
                  onClick={() => setItemSelectionMode('smart')}
                  _hover={{
                    bg: itemSelectionMode === 'smart'
                      ? 'linear-gradient(135deg, #9333ea 0%, #7c3aed 100%)'
                      : 'rgba(168, 85, 247, 0.2)'
                  }}
                  transition="all 0.3s"
                  flexDirection="column"
                  alignItems="center"
                  justifyContent="flex-start"
                  pt={{ base: 0, md: 1 }}
                >
                  <VStack spacing={0} lineHeight="1" mt={-3}>
                    <Text fontSize={{ base: "3px", sm: "2xs", md: "sm" }}>Search</Text>
                    <Text fontSize={{ base: "3px", sm: "2xs", md: "sm" }}>Item</Text>
                  </VStack>
                </Button>
                
                {/* ✅ Packages Button */}
                <Button 
                  className="booking-luxury-selection-button"
                  size={{ base: "xs", md: "lg" }}
                  fontSize={{ base: "3px", sm: "2xs", md: "sm" }}
                  px={{ base: 2, md: 4 }}
                  py={{ base: 2, md: 2 }}
                  bg={itemSelectionMode === 'packages' 
                    ? 'linear-gradient(135deg, #f59e0b 0%, #d97706 100%)' 
                    : 'rgba(31, 41, 55, 0.6)'}
                  color="white"
                  border="2px solid"
                  borderColor={itemSelectionMode === 'packages' ? 'rgba(245, 158, 11, 0.5)' : 'rgba(255, 255, 255, 0.1)'}
                  onClick={() => setItemSelectionMode('packages')}
                  _hover={{
                    bg: itemSelectionMode === 'packages'
                      ? 'linear-gradient(135deg, #d97706 0%, #b45309 100%)'
                      : 'rgba(245, 158, 11, 0.2)'
                  }}
                  transition="all 0.3s"
                  flexDirection="column"
                  alignItems="center"
                  justifyContent="flex-start"
                  pt={{ base: 0, md: 1 }}
                >
                  <VStack spacing={0} lineHeight="1" mt={-3}>
                    <Text fontSize={{ base: "3px", sm: "2xs", md: "sm" }}>Curated</Text>
                    <Text fontSize={{ base: "3px", sm: "2xs", md: "sm" }}>Packages</Text>
                  </VStack>
                </Button>
                
                <Button 
                  className="booking-luxury-selection-button"
                  size={{ base: "xs", md: "lg" }}
                  fontSize={{ base: "3px", sm: "2xs", md: "sm" }}
                  px={{ base: 2, md: 4 }}
                  py={{ base: 2, md: 2 }}
                  bg={itemSelectionMode === 'choose' 
                    ? 'linear-gradient(135deg, #10b981 0%, #059669 100%)' 
                    : 'rgba(31, 41, 55, 0.6)'}
                  color="white"
                  border="2px solid"
                  borderColor={itemSelectionMode === 'choose' ? 'rgba(16, 185, 129, 0.5)' : 'rgba(255, 255, 255, 0.1)'}
                  onClick={() => setItemSelectionMode('choose')}
                  _hover={{
                    bg: itemSelectionMode === 'choose'
                      ? 'linear-gradient(135deg, #059669 0%, #047857 100%)'
                      : 'rgba(16, 185, 129, 0.2)'
                  }}
                  transition="all 0.3s"
                  flexDirection="column"
                  alignItems="center"
                  justifyContent="flex-start"
                  pt={{ base: 0, md: 1 }}
                >
                  <VStack spacing={0} lineHeight="1" mt={-3}>
                    <Text fontSize={{ base: "3px", sm: "2xs", md: "sm" }}>Individual</Text>
                    <Text fontSize={{ base: "3px", sm: "2xs", md: "sm" }}>Items</Text>
                  </VStack>
                </Button>
              </SimpleGrid>

              {/* ✅ Packages Mode */}
              {itemSelectionMode === 'packages' && (
                <VStack spacing={6} w="full">
                  <VStack spacing={2} textAlign="center">
                    <Heading size={{ base: "md", md: "lg" }} color="white">
                      📦 Curated Packages
                    </Heading>
                    <Text color="gray.300" fontSize={{ base: "sm", md: "md" }}>
                      Choose a complete room bundle or one of our featured collections to add multiple items in one tap.
                    </Text>
                  </VStack>

                  <VStack spacing={4} w="full" align="stretch" sx={{ overflow: 'visible' }}>
                    <VStack align="start" spacing={2}>
                      <Text fontSize={{ base: "md", md: "lg" }} color="white" fontWeight="semibold">
                        🏠 Home Size Bundles
                      </Text>
                      <Text fontSize="sm" color="gray.400">
                        Click + to add all items from a package - customize them below
                      </Text>
                    </VStack>
                    <SimpleGrid columns={[2, 2, 2, 3, 5]} spacing={{ base: 2, md: 3 }} w="full" sx={{ overflow: 'visible' }}>
                      {bedroomPackages.map((pkg) => {
                        const packageData = packages[pkg.packageKey as keyof typeof packages];
                        
                        return (
                          <VStack key={pkg.id} spacing={2} align="stretch" w="full">
                            {/* Package Card */}
                            <Box
                              borderRadius="xl"
                              overflow="hidden"
                              border="2px solid"
                              borderColor="rgba(245, 158, 11, 0.3)"
                              bg="rgba(31, 41, 55, 0.6)"
                              transition="all 0.3s"
                              _hover={{
                                borderColor: "orange.400",
                                boxShadow: "0 4px 12px rgba(245, 158, 11, 0.3)"
                              }}
                            >
                              <VStack spacing={2} align="center" p={3}>
                                <Box 
                                  w="100%" 
                                  h={{ base: "80px", sm: "100px", md: "120px" }} 
                                  borderRadius="lg" 
                                  overflow="hidden" 
                                  bg="rgba(17, 24, 39, 0.6)"
                                  display="flex" 
                                  alignItems="center" 
                                  justifyContent="center"
                                >
                                  <Image 
                                    src={pkg.image} 
                                    alt={pkg.name} 
                                    w="100%" 
                                    h="100%" 
                                    objectFit="cover"
                                    fallbackSrc="/placeholder-house.png"
                                  />
                                </Box>
                                <Text fontSize={{ base: "xs", sm: "sm", md: "md" }} color="white" fontWeight="bold" textAlign="center">
                                  {pkg.name}
                                </Text>
                                <Badge colorScheme="orange" fontSize="xs">
                                  {packageData?.items.length || 0} items
                                </Badge>
                                <button
                                  onClick={(e) => {
                                    e.stopPropagation();
                                    if (packageData) {
                                      const currentItems = step1.items || [];
                                      const newItems = packageData.items.map((item: any) => {
                                        const existingItem = currentItems.find((i: any) => i.id === item.id);
                                        if (existingItem) {
                                          return { ...existingItem, quantity: existingItem.quantity + 1 };
                                        } else {
                                          return { ...item, quantity: 1 };
                                        }
                                      });
                                      const existingItemIds = new Set(packageData.items.map((i: any) => i.id));
                                      const remainingItems = currentItems.filter((i: any) => !existingItemIds.has(i.id));
                                      updateFormData('step1', {
                                        items: [...remainingItems, ...newItems]
                                      });
                                      toast({
                                        title: `${pkg.name} Added!`,
                                        description: `${packageData.items.length} items added`,
                                        status: 'success',
                                        duration: 2000,
                                      });
                                    }
                                  }}
                                  style={{
                                    cursor: 'pointer',
                                    padding: 0,
                                    margin: 0,
                                    background: 'transparent',
                                    border: 'none',
                                    width: '100%',
                                    display: 'flex',
                                    justifyContent: 'center',
                                  }}
                                >
                                  <svg width="44" height="44" viewBox="0 0 24 24" fill="none">
                                    <path d="M12 5V19M5 12H19" stroke="#fb923c" strokeWidth="3" strokeLinecap="round"/>
                                  </svg>
                                </button>
                              </VStack>
                            </Box>
                          </VStack>
                        );
                      })}
                    </SimpleGrid>
                  </VStack>

                </VStack>
              )}

              {/* Search Mode */}
              {itemSelectionMode === 'smart' && (
                <VStack spacing={4} w="full">
                  <Input
                    size="lg"
                    placeholder="Search from 666 items (e.g., 'sofa', 'bed', 'kitchen')"
                    bg="rgba(17, 24, 39, 0.8)"
                    border="2px solid"
                    borderColor="rgba(168, 85, 247, 0.3)"
                    color="white"
                    _placeholder={{ color: "gray.400" }}
                    _hover={{ borderColor: 'rgba(168, 85, 247, 0.5)' }}
                    _focus={{ 
                      borderColor: 'rgba(168, 85, 247, 0.6)',
                      boxShadow: "0 0 0 3px rgba(168, 85, 247, 0.2)"
                    }}
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                  />
                  
                  <Text fontSize="sm" color="gray.400">
                    Found {displayedItems.length} items
                  </Text>

                  {/* Items Grid - 2 Columns on Mobile */}
                  <SimpleGrid columns={[2, 2, 2, 4, 5]} spacing={{ base: 2, md: 3 }} w="full">
                    {displayedItems.slice(0, 50).map((item) => {
                      const quantity = getItemQuantity(item.id);
                      return (
                        <VStack key={item.id} spacing={2} align="center" w="full">
                          <Box 
                            w="100%" 
                            h={{ base: "120px", sm: "140px", md: "160px" }} 
                            borderRadius="lg" 
                            overflow="hidden" 
                            bg="rgba(17, 24, 39, 0.6)"
                            display="flex" 
                            alignItems="center" 
                            justifyContent="center"
                          >
                            <Image 
                              src={item.image} 
                              alt={item.name} 
                              w="100%" 
                              h="100%" 
                              objectFit="cover"
                              loading="lazy"
                            />
                          </Box>
                          <Text fontSize={{ base: "xs", sm: "sm", md: "md" }} color="white" fontWeight="medium" lineHeight="1.2" noOfLines={2} minH={{ base: "32px", md: "40px" }} textAlign="center">
                            {item.name}
                          </Text>
                          <Text fontSize={{ base: "2xs", sm: "xs" }} color="gray.400" textAlign="center">
                            {item.weight}kg
                          </Text>
                          {/* Plus/Minus Icons - Horizontal on All Screens */}
                          <Box
                            display="flex"
                            flexDirection="row"
                            justifyContent="center"
                            alignItems="center"
                            width="100%"
                            gap={{ base: "4px", sm: "8px" }}
                            sx={{
                              flexDirection: 'row',
                              gap: '8px',
                            }}
                          >
                            <Box
                              as="button"
                              cursor={quantity > 0 ? "pointer" : "not-allowed"}
                              opacity={quantity > 0 ? 1 : 0.3}
                              onClick={(e: React.MouseEvent) => {
                                e.stopPropagation();
                                if (quantity > 0) {
                                  updateQuantity(item.id, quantity - 1, item);
                                }
                              }}
                              sx={{
                                cursor: quantity > 0 ? "pointer" : "not-allowed",
                                opacity: quantity > 0 ? 1 : 0.3,
                                background: "transparent",
                                border: "none",
                                padding: "0",
                                margin: "0",
                                display: "flex",
                                alignItems: "center",
                                justifyContent: "center",
                                transition: "transform 0.2s",
                                '&:hover': quantity > 0 ? {
                                  transform: "scale(1.2)",
                                } : {},
                              }}
                            >
                              <Icon as={FaMinus} fontSize={{ base: "lg", sm: "lg", md: "lg" }} color="white" />
                            </Box>
                            <Text 
                              fontSize={{ base: "xs", sm: "sm" }} 
                              color="white" 
                              fontWeight="bold"
                              textAlign="center"
                              sx={{
                                '@media (max-width: 767px)': {
                                  minWidth: 'auto',
                                  padding: '0',
                                },
                                '@media (min-width: 768px)': {
                                  minWidth: '24px',
                                  padding: '0 4px',
                                },
                              }}
                            >
                              {quantity}
                            </Text>
                            <Box
                              as="button"
                              cursor="pointer"
                              onClick={(e: React.MouseEvent) => {
                                e.stopPropagation();
                                updateQuantity(item.id, quantity + 1, item);
                              }}
                              sx={{
                                cursor: "pointer",
                                background: "transparent",
                                border: "none",
                                padding: "0",
                                margin: "0",
                                display: "flex",
                                alignItems: "center",
                                justifyContent: "center",
                                transition: "transform 0.2s",
                                '&:hover': {
                                  transform: "scale(1.2)",
                                },
                              }}
                            >
                              <Icon as={FaPlus} fontSize={{ base: "lg", sm: "lg", md: "lg" }} color="white" />
                            </Box>
                          </Box>
                        </VStack>
                      );
                    })}
                  </SimpleGrid>

                  {displayedItems.length > 50 && (
                    <Text fontSize="sm" color="gray.500" textAlign="center">
                      Showing first 50 results. Refine your search for more specific items.
                    </Text>
                  )}
                </VStack>
              )}

              {/* Individual Items Mode - All 666 Items with Category Filter */}
              {itemSelectionMode === 'choose' && (
                <VStack spacing={4} w="full">
                  
                  {/* Category Filter */}
                  <HStack spacing={3} w="full" justify="space-between" flexWrap="wrap">
                    <Text fontSize={{ base: "md", md: "lg" }} color="white" fontWeight="semibold">
                      Browse by Category
                    </Text>
                    <Select
                      mb={4}
                      value={selectedCategory}
                      onChange={(e) => {
                        setSelectedCategory(e.target.value);
                        setSelectedSubcategory('All'); // Reset subcategory when category changes
                      }}
                      bg="white"
                      borderColor="rgba(59, 130, 246, 0.4)"
                      color="gray.900"
                      w={{ base: "full", md: "300px" }}
                      size="lg"
                      borderRadius="xl"
                      borderWidth="2px"
                      fontWeight="600"
                      cursor="pointer"
                      _hover={{ 
                        borderColor: 'rgba(59, 130, 246, 0.7)',
                        boxShadow: "0 4px 14px rgba(59, 130, 246, 0.2)"
                      }}
                      _focus={{ 
                        borderColor: '#3b82f6',
                        boxShadow: "0 0 0 4px rgba(59, 130, 246, 0.25)",
                        outline: "none"
                      }}
                      _active={{
                        borderColor: '#2563eb',
                      }}
                      transition="all 0.2s ease"
                      iconColor="gray.700"
                      sx={{
                        '& option': {
                          backgroundColor: 'white',
                          color: '#111827',
                          padding: '14px',
                          fontSize: '15px',
                          fontWeight: '600',
                          lineHeight: '1.5',
                        },
                        '& option:hover': {
                          backgroundColor: '#f3f4f6',
                        },
                        '& option:checked': {
                          backgroundColor: '#3b82f6',
                          color: 'white',
                          fontWeight: '700',
                        }
                      }}
                    >
                      {categories.map((cat) => (
                        <option key={cat} value={cat}>
                          {cat} {cat === 'All' ? `(${ALL_REMOVAL_ITEMS.length})` : `(${filterItemsByCategory(cat).length})`}
                        </option>
                      ))}
                    </Select>
                  </HStack>
                  
                  {/* ✅ NEW: Advanced Filters Panel */}
                  <Card bg="rgba(31, 41, 55, 0.5)" borderColor="rgba(59, 130, 246, 0.3)" borderWidth="1px" borderRadius="lg">
                    <CardBody p={4}>
                      <VStack spacing={4} align="stretch">
                        
                        {/* Subcategory + Sort Row */}
                        <SimpleGrid columns={{ base: 1, md: 2 }} spacing={3}>
                          {/* Subcategory Filter */}
                          <FormControl>
                            <FormLabel color="white" fontSize="sm" mb={2} fontWeight="600">🔍 Subcategory</FormLabel>
                            <Select
                              mb={3}
                              value={selectedSubcategory}
                              onChange={(e) => setSelectedSubcategory(e.target.value)}
                              bg="white"
                              borderColor="rgba(168, 85, 247, 0.4)"
                              color="gray.900"
                              size="md"
                              borderRadius="lg"
                              borderWidth="2px"
                              fontWeight="600"
                              cursor="pointer"
                              _hover={{
                                borderColor: "rgba(168, 85, 247, 0.7)",
                                boxShadow: "0 3px 10px rgba(168, 85, 247, 0.15)"
                              }}
                              _focus={{
                                borderColor: "#a855f7",
                                boxShadow: "0 0 0 3px rgba(168, 85, 247, 0.2)",
                                outline: "none",
                              }}
                              transition="all 0.2s ease"
                              iconColor="gray.700"
                              sx={{
                                '& option': {
                                  backgroundColor: 'white',
                                  color: '#111827',
                                  padding: '12px',
                                  fontSize: '14px',
                                  fontWeight: '600',
                                  lineHeight: '1.5',
                                },
                                '& option:hover': {
                                  backgroundColor: '#f3f4f6',
                                },
                                '& option:checked': {
                                  backgroundColor: '#a855f7',
                                  color: 'white',
                                  fontWeight: '700',
                                }
                              }}
                            >
                              {subcategories.map((subcat) => (
                                <option key={subcat} value={subcat}>
                                  {subcat}
                                </option>
                              ))}
                            </Select>
                          </FormControl>
                          
                          {/* Sort By */}
                          <FormControl>
                            <FormLabel color="white" fontSize="sm" mb={2} fontWeight="600">📊 Sort By</FormLabel>
                            <Select
                              mb={3}
                              value={sortBy}
                              onChange={(e) => setSortBy(e.target.value as any)}
                              bg="white"
                              borderColor="rgba(16, 185, 129, 0.4)"
                              color="gray.900"
                              size="md"
                              borderRadius="lg"
                              borderWidth="2px"
                              fontWeight="600"
                              cursor="pointer"
                              _hover={{
                                borderColor: "rgba(16, 185, 129, 0.7)",
                                boxShadow: "0 3px 10px rgba(16, 185, 129, 0.15)"
                              }}
                              _focus={{
                                borderColor: "#10b981",
                                boxShadow: "0 0 0 3px rgba(16, 185, 129, 0.2)",
                                outline: "none",
                              }}
                              transition="all 0.2s ease"
                              iconColor="gray.700"
                              sx={{
                                '& option': {
                                  backgroundColor: 'white',
                                  color: '#111827',
                                  padding: '12px',
                                  fontSize: '14px',
                                  fontWeight: '600',
                                  lineHeight: '1.5',
                                },
                                '& option:hover': {
                                  backgroundColor: '#f3f4f6',
                                },
                                '& option:checked': {
                                  backgroundColor: '#10b981',
                                  color: 'white',
                                  fontWeight: '700',
                                }
                              }}
                            >
                              <option value="popular">⭐ Popular First</option>
                              <option value="weight-asc">⚖️ Lightest First</option>
                              <option value="weight-desc">💪 Heaviest First</option>
                              <option value="name-asc">🔤 A→Z</option>
                              <option value="name-desc">🔤 Z→A</option>
                            </Select>
                          </FormControl>
                        </SimpleGrid>
                        
                        {/* Weight Range Filter */}
                        <FormControl>
                          <FormLabel color="white" fontSize="sm" mb={2}>⚖️ Weight Range (kg)</FormLabel>
                          <HStack spacing={3}>
                            <NumberInput
                              value={minWeight || ''}
                              onChange={(_, val) => setMinWeight(isNaN(val) ? undefined : val)}
                              min={0}
                              max={maxWeight || 500}
                              size="sm"
                            >
                              <NumberInputField
                                placeholder="Min"
                                bg="rgba(17, 24, 39, 0.8)"
                                borderColor="rgba(59, 130, 246, 0.3)"
                                color="white"
                              />
                            </NumberInput>
                            <Text color="gray.400">to</Text>
                            <NumberInput
                              value={maxWeight || ''}
                              onChange={(_, val) => setMaxWeight(isNaN(val) ? undefined : val)}
                              min={minWeight || 0}
                              max={500}
                              size="sm"
                            >
                              <NumberInputField
                                placeholder="Max"
                                bg="rgba(17, 24, 39, 0.8)"
                                borderColor="rgba(59, 130, 246, 0.3)"
                                color="white"
                              />
                            </NumberInput>
                          </HStack>
                        </FormControl>
                        
                        {/* Reset Filters */}
                        {(minWeight || maxWeight || selectedSubcategory !== 'All' || sortBy !== 'popular') && (
                          <Button
                            size="sm"
                            variant="ghost"
                            color="gray.400"
                            onClick={() => {
                              setSelectedSubcategory('All');
                              setSortBy('popular');
                              setMinWeight(undefined);
                              setMaxWeight(undefined);
                            }}
                            _hover={{ color: 'white', bg: 'rgba(59, 130, 246, 0.1)' }}
                          >
                            🔄 Reset Filters
                          </Button>
                        )}
                      </VStack>
                    </CardBody>
                  </Card>

                  <Text fontSize="sm" color="gray.400">
                    Showing {displayedItems.length} items
                  </Text>
                  
                  {/* Items Grid - 2 Columns on Mobile */}
                  <SimpleGrid columns={[2, 2, 2, 4, 5]} spacing={{ base: 2, md: 3 }} w="full">
                    {displayedItems.slice(0, 100).map((item) => {
                      const quantity = getItemQuantity(item.id);
                      return (
                        <VStack key={item.id} spacing={2} align="center" w="full">
                          <Box 
                            w="100%" 
                            h={{ base: "120px", sm: "140px", md: "160px" }} 
                            borderRadius="lg" 
                            overflow="hidden" 
                            bg="rgba(17, 24, 39, 0.6)"
                            display="flex" 
                            alignItems="center" 
                            justifyContent="center"
                          >
                            <Image 
                              src={item.image} 
                              alt={item.name} 
                              w="100%" 
                              h="100%" 
                              objectFit="cover"
                              loading="lazy"
                            />
                          </Box>
                          <Text fontSize={{ base: "xs", sm: "sm", md: "md" }} color="white" fontWeight="medium" lineHeight="1.2" noOfLines={2} minH={{ base: "32px", md: "40px" }} textAlign="center">
                            {item.name}
                          </Text>
                          <Text fontSize={{ base: "2xs", sm: "xs" }} color="gray.400" textAlign="center">
                            {item.weight}kg
                          </Text>
                          {/* Plus/Minus Icons - Horizontal on All Screens */}
                          <Box
                            display="flex"
                            flexDirection="row"
                            justifyContent="center"
                            alignItems="center"
                            width="100%"
                            gap={{ base: "4px", sm: "8px" }}
                            sx={{
                              flexDirection: 'row',
                              gap: '8px',
                            }}
                          >
                            <Box
                              as="button"
                              cursor={quantity > 0 ? "pointer" : "not-allowed"}
                              opacity={quantity > 0 ? 1 : 0.3}
                              onClick={(e: React.MouseEvent) => {
                                e.stopPropagation();
                                if (quantity > 0) {
                                  updateQuantity(item.id, quantity - 1, item);
                                }
                              }}
                              sx={{
                                cursor: quantity > 0 ? "pointer" : "not-allowed",
                                opacity: quantity > 0 ? 1 : 0.3,
                                background: "transparent",
                                border: "none",
                                padding: "0",
                                margin: "0",
                                display: "flex",
                                alignItems: "center",
                                justifyContent: "center",
                                transition: "transform 0.2s",
                                '&:hover': quantity > 0 ? {
                                  transform: "scale(1.2)",
                                } : {},
                              }}
                            >
                              <Icon as={FaMinus} fontSize={{ base: "lg", sm: "lg", md: "lg" }} color="white" />
                            </Box>
                            <Text 
                              fontSize={{ base: "xs", sm: "sm" }} 
                              color="white" 
                              fontWeight="bold"
                              textAlign="center"
                              sx={{
                                '@media (max-width: 767px)': {
                                  minWidth: 'auto',
                                  padding: '0',
                                },
                                '@media (min-width: 768px)': {
                                  minWidth: '24px',
                                  padding: '0 4px',
                                },
                              }}
                            >
                              {quantity}
                            </Text>
                            <Box
                              as="button"
                              cursor="pointer"
                              onClick={(e: React.MouseEvent) => {
                                e.stopPropagation();
                                updateQuantity(item.id, quantity + 1, item);
                              }}
                              sx={{
                                cursor: "pointer",
                                background: "transparent",
                                border: "none",
                                padding: "0",
                                margin: "0",
                                display: "flex",
                                alignItems: "center",
                                justifyContent: "center",
                                transition: "transform 0.2s",
                                '&:hover': {
                                  transform: "scale(1.2)",
                                },
                              }}
                            >
                              <Icon as={FaPlus} fontSize={{ base: "lg", sm: "lg", md: "lg" }} color="white" />
                            </Box>
                          </Box>
                        </VStack>
                      );
                    })}
                  </SimpleGrid>

                  {displayedItems.length > 100 && (
                    <Button
                      variant="outline"
                      color="white"
                      borderColor="rgba(16, 185, 129, 0.3)"
                      onClick={() => {
                        // Load more functionality can be added here
                        toast({
                          title: 'Showing 100 items',
                          description: `${displayedItems.length - 100} more items available. Use category filter to narrow down.`,
                          status: 'info',
                          duration: 3000,
                        });
                      }}
                    >
                      {displayedItems.length - 100} more items available - Filter by category
                    </Button>
                  )}
                </VStack>
              )}

            </VStack>
          </CardBody>
        </Card>

        {/* Selected Items summary rendered via responsive floating surfaces */}

        {/* Navigation Buttons */}
        <Card 
          bg="linear-gradient(135deg, rgba(31, 41, 55, 0.8) 0%, rgba(26, 32, 44, 0.6) 100%)" 
          borderRadius="xl" 
          border="1px solid" 
          borderColor="rgba(255, 255, 255, 0.1)"
          backdropFilter="blur(10px)"
        >
          <CardBody p={6}>
            <VStack w="full" spacing={3}>
              {step1.items.length > 0 && (
                <Badge bg="green.600" color="white" p={3} borderRadius="lg" fontSize="md" w="full" textAlign="center">
                  ✅ {step1.items.length} Items Selected
                </Badge>
              )}

              {onNext && (
                <Button
                  rightIcon={<Icon as={FaArrowRight} />}
                  onClick={onNext}
                  isDisabled={step1.items.length === 0 || !step1.pickupDate || !step1.pickupTimeSlot}
                  bg="linear-gradient(135deg, #10b981 0%, #059669 100%)"
                  color="white"
                  size="lg"
                  w="full"
                  _hover={{
                    bg: 'linear-gradient(135deg, #059669 0%, #047857 100%)',
                    boxShadow: '0 8px 20px rgba(16, 185, 129, 0.4)',
                  }}
                  _disabled={{
                    opacity: 0.4,
                    cursor: 'not-allowed',
                    _hover: {
                      transform: 'none',
                      boxShadow: 'none',
                    },
                  }}
                  transition="all 0.3s"
                >
                  Next Step
                </Button>
              )}

              {onBack && (
                <Button
                  leftIcon={<Icon as={FaArrowLeft} />}
                  onClick={onBack}
                  variant="outline"
                  borderColor="rgba(255, 255, 255, 0.2)"
                  color="white"
                  size="lg"
                  w="full"
                  _hover={{
                    bg: 'rgba(255, 255, 255, 0.1)',
                    borderColor: 'rgba(255, 255, 255, 0.3)',
                  }}
                >
                  Back
                </Button>
              )}
            </VStack>
          </CardBody>
        </Card>

      </VStack>
      {step1.items.length > 0 && (
        <>
          {!isSelectedItemsPanelOpen && (
            <Portal>
              <Box
                position="fixed"
                bottom={{ base: '96px', md: '40px' }}
                right={{ base: '20px', md: '40px' }}
                zIndex={1500}
                pointerEvents="none"
                sx={{
                  contain: 'layout style paint',
                  willChange: 'transform',
                }}
              >
                <Button
                  aria-label="View selected items"
                  onClick={onSelectedItemsPanelOpen}
                  bg="linear-gradient(135deg, #10b981 0%, #059669 100%)"
                  color="white"
                  borderRadius="full"
                  px={{ base: 4, md: 5 }}
                  py={{ base: 5, md: 6 }}
                  boxShadow="0 18px 32px rgba(16, 185, 129, 0.35)"
                  _hover={{ bg: 'linear-gradient(135deg, #059669 0%, #047857 100%)', transform: 'translateY(-3px)' }}
                  _active={{ bg: 'linear-gradient(135deg, #047857 0%, #03634f 100%)', transform: 'translateY(-1px)' }}
                  fontWeight="700"
                  pointerEvents="auto"
                  transition="all 0.25s ease"
                  minW={{ base: 'auto', md: '280px' }}
                >
                  <HStack spacing={4}>
                    <Circle size={{ base: '42px', md: '48px' }} bg="rgba(255,255,255,0.12)">
                      <Icon as={FaBoxOpen} color="white" boxSize={{ base: 5, md: 6 }} />
                    </Circle>
                    <Box textAlign="left">
                      <Text fontSize={{ base: 'sm', md: 'md' }} fontWeight="800">
                        Selected Items
                      </Text>
                      <Text fontSize={{ base: 'xs', md: 'sm' }} color="whiteAlpha.800">
                        View list ({step1.items.length})
                      </Text>
                    </Box>
                    <Circle size={{ base: '36px', md: '42px' }} bg="white" color="#059669">
                      <Text fontWeight="900" fontSize="md">
                        {step1.items.length}
                      </Text>
                    </Circle>
                  </HStack>
                </Button>
              </Box>
            </Portal>
          )}

          <Drawer
            placement="bottom"
            isOpen={isSelectedItemsPanelOpen}
            onClose={onSelectedItemsPanelClose}
          >
            <DrawerOverlay bg="rgba(15, 23, 42, 0.75)" backdropFilter="blur(10px)" />
            <DrawerContent
              borderTopRadius="2xl"
              bg="linear-gradient(135deg, rgba(31, 41, 55, 0.98) 0%, rgba(26, 32, 44, 0.95) 100%)"
              border="1px solid rgba(16, 185, 129, 0.4)"
              maxH="85vh"
              pb={4}
              mx="auto"
              w="calc(100% - 32px)"
              maxW="720px"
              boxShadow="0 -12px 40px rgba(16, 185, 129, 0.25)"
            >
              <DrawerCloseButton color="white" _focus={{ boxShadow: '0 0 0 3px rgba(16, 185, 129, 0.4)' }} />
              <DrawerHeader
                borderBottomWidth="1px"
                borderColor="rgba(255, 255, 255, 0.08)"
                color="white"
                fontWeight="900"
              >
                ✅ Selected Items ({step1.items.length})
              </DrawerHeader>
              <DrawerBody px={{ base: 4, md: 6 }} pt={4} pb={0}>
                {renderSelectedItemsContent({ includeHeading: false })}
              </DrawerBody>
            </DrawerContent>
          </Drawer>
        </>
      )}
    </Container>
  );
}

'use client';

/**
 * Hierarchical Items Selection - Enterprise Grade
 * Updated: 2025-11-20 - Enhanced toggle button UX
 * 
 * 3-Level Hierarchy:
 * 1. Property Type (House/Office/Storage/Single Items)
 * 2. Property Size (Studio/1-5 Bedrooms for houses, etc.)
 * 3. Room-Based Inventory with pre-populated lists
 */

import React, { useState, useEffect } from 'react';
import {
  Box,
  VStack,
  HStack,
  Button,
  Text,
  Card,
  CardBody,
  Badge,
  Alert,
  AlertIcon,
  Fade,
  Progress,
  useToast,
  FormControl,
  FormLabel,
  FormErrorMessage,
  Input,
  Select,
  SimpleGrid,
  Heading,
  Icon,
  useDisclosure,
  Collapse,
} from '@chakra-ui/react';
import { FaArrowLeft, FaArrowRight, FaBox, FaTimes, FaChevronUp, FaPlus, FaMinus, FaTrash } from 'react-icons/fa';
import NextImage from 'next/image';

import type { FormData } from '../hooks/useBookingForm';
import PropertyTypeSelector, { PropertyType } from './PropertyTypeSelector';
import PropertySizeSelector from './PropertySizeSelector';
import RoomBasedInventory from './RoomBasedInventory';
import AIItemExtractionAssistant, { type AiAddedItemPayload } from './AIItemExtractionAssistant';
import { getPrePopulatedItems, filterByPriority } from '@/lib/pre-populated-inventory';
import { ALL_REMOVAL_ITEMS, type RemovalItem } from '@/lib/uk-removal-items-data';

interface WhereAndWhatStepHierarchicalProps {
  formData: FormData;
  updateFormData: (step: keyof FormData, data: Partial<FormData[keyof FormData]>) => void;
  errors: Record<string, string>;
  onNext?: () => void;
  onBack?: () => void;
  calculatePricing?: () => void;
}

export default function WhereAndWhatStepHierarchical({
  formData,
  updateFormData,
  errors,
  onNext,
  onBack,
  calculatePricing,
}: WhereAndWhatStepHierarchicalProps) {
  const toast = useToast();
  const { isOpen: isSummaryExpanded, onToggle: toggleSummary } = useDisclosure({ defaultIsOpen: false });
  
  // Hierarchical state
  const [currentLevel, setCurrentLevel] = useState<1 | 2 | 3>(1);
  const [propertyType, setPropertyType] = useState<PropertyType | undefined>();
  const [propertySize, setPropertySize] = useState<string | undefined>();
  const [prePopulatedApplied, setPrePopulatedApplied] = useState(false);
  
  const { step1 } = formData;

  // Transform selected items to include room information
  interface SelectedItemWithRoom {
    id: string;
    name: string;
    category: string;
    weight: number;
    quantity: number;
    room: string;
  }

  const [selectedItemsWithRooms, setSelectedItemsWithRooms] = useState<SelectedItemWithRoom[]>([]);

  // Sync with formData - always keep in sync
  useEffect(() => {
    if (step1.items.length > 0) {
      // Create a map of existing items for quick lookup
      const existingMap = new Map(selectedItemsWithRooms.map(i => [i.id, i]));
      
      // Check if items need to be synced
      const needsSync = step1.items.length !== selectedItemsWithRooms.length ||
        step1.items.some(item => {
          const localItem = existingMap.get(item.id);
          return !localItem || localItem.quantity !== item.quantity;
        });

      if (needsSync) {
        // Sync from formData, preserving room info
        const itemsWithRooms = step1.items.map(item => {
          const existing = existingMap.get(item.id);
          return {
            id: item.id,
            name: item.name,
            category: item.category,
            weight: item.weight,
            quantity: item.quantity,
            room: existing?.room || 'unknown',
          };
        });
        setSelectedItemsWithRooms(itemsWithRooms);
      }
    } else if (selectedItemsWithRooms.length > 0) {
      // Clear local state if formData is empty
      setSelectedItemsWithRooms([]);
    }
  }, [step1.items]);

  // Handle property type selection
  const handlePropertyTypeSelect = (type: PropertyType) => {
    setPropertyType(type);
    
    // Skip size selection for single items
    if (type === 'single-items') {
      setCurrentLevel(3);
      setPropertySize(undefined);
    } else {
      setCurrentLevel(2);
    }
  };

  // Handle property size selection
  const handlePropertySizeSelect = (size: string) => {
    setPropertySize(size);
    
    // Auto-apply pre-populated items
    if (!prePopulatedApplied) {
      applyPrePopulatedItems(size);
    }
    
    setCurrentLevel(3);
  };

  // Apply pre-populated items based on property type and size
  const applyPrePopulatedItems = (size: string) => {
    if (!propertyType) return;
    
    const prePopItems = getPrePopulatedItems(propertyType, size);
    const essentialItems = filterByPriority(prePopItems, 3); // Include ALL items (priority 1, 2, and 3)
    
    const newItems: SelectedItemWithRoom[] = essentialItems.map(preItem => {
      // Find matching item from ALL_REMOVAL_ITEMS
      const matchedItem = ALL_REMOVAL_ITEMS.find(item => 
        item.name.toLowerCase().includes(preItem.name.toLowerCase()) ||
        preItem.name.toLowerCase().includes(item.name.toLowerCase().split(' ')[0])
      );

      return {
        id: matchedItem?.id || `custom-${preItem.name}-${Date.now()}-${Math.random()}`,
        name: preItem.name,
        category: preItem.category,
        weight: preItem.weight,
        quantity: preItem.suggestedQuantity,
        room: preItem.room,
      };
    });

    console.log('🎯 Pre-populated items being added:', {
      propertyType,
      size,
      totalItems: essentialItems.length,
      totalQuantity: newItems.reduce((sum, item) => sum + item.quantity, 0),
      items: newItems.map(i => ({ name: i.name, quantity: i.quantity }))
    });

    setSelectedItemsWithRooms(newItems);
    setPrePopulatedApplied(true);

    // Update formData
    updateFormData('step1', {
      items: newItems.map(item => ({
        id: item.id,
        name: item.name,
        category: item.category,
        weight: item.weight,
        quantity: item.quantity,
        size: 'medium',
        volume: 1.0,
        unitPrice: 25,
        totalPrice: 25 * item.quantity,
        description: `${item.name} from ${item.room}`,
      })),
    });

    const totalQuantity = newItems.reduce((sum, item) => sum + item.quantity, 0);
    const uniqueItems = newItems.length;
    
    toast({
      title: 'Pre-populated list applied',
      description: `Added ${totalQuantity} items (${uniqueItems} unique ${uniqueItems === 1 ? 'item' : 'items'}). You can now customize them.`,
      status: 'success',
      duration: 3000,
    });
  };

  // Handle adding item
  const handleAddItem = (item: RemovalItem, room: string, quantity: number) => {
    console.log('🔍 DEBUG handleAddItem - Item received:', {
      id: item.id,
      name: item.name,
      category: item.category,
      weight: item.weight,
      room
    });

    // Check if item already exists
    const existingItemIndex = selectedItemsWithRooms.findIndex(i => i.id === item.id);
    
    let updated: SelectedItemWithRoom[];
    
    if (existingItemIndex >= 0) {
      // Item exists - update quantity
      updated = selectedItemsWithRooms.map((i, idx) =>
        idx === existingItemIndex
          ? { ...i, quantity: i.quantity + quantity }
          : i
      );
    } else {
      // New item - add it
      const newItem: SelectedItemWithRoom = {
        id: item.id,
        name: item.name,
        category: item.category,
        weight: item.weight,
        quantity,
        room,
      };
      updated = [...selectedItemsWithRooms, newItem];
      console.log('🔍 DEBUG handleAddItem - New item created:', newItem);
    }

    setSelectedItemsWithRooms(updated);

    // Update formData
    updateFormData('step1', {
      items: updated.map(i => ({
        id: i.id,
        name: i.name,
        category: i.category,
        weight: i.weight,
        quantity: i.quantity,
        size: 'medium',
        volume: 1.0,
        unitPrice: 25,
        totalPrice: 25 * i.quantity,
        description: `${i.name} from ${i.room}`,
      })),
    });

    // Auto-calculate pricing if available
    if (calculatePricing) {
      setTimeout(() => calculatePricing(), 500);
    }
  };

  // Handle AI-added items
  const handleAiAddItems = (aiItems: AiAddedItemPayload[]) => {
    let updated = [...selectedItemsWithRooms];
    
    aiItems.forEach(({ item, quantity, room }) => {
      const existingIndex = updated.findIndex(i => i.id === item.id);
      
      if (existingIndex >= 0) {
        // Update quantity
        updated[existingIndex] = {
          ...updated[existingIndex],
          quantity: updated[existingIndex].quantity + quantity,
        };
      } else {
        // Add new item
        updated.push({
          id: item.id,
          name: item.name,
          category: item.category,
          weight: item.weight,
          quantity,
          room,
        });
      }
    });
    
    setSelectedItemsWithRooms(updated);
    
    // Update formData
    updateFormData('step1', {
      items: updated.map(i => ({
        id: i.id,
        name: i.name,
        category: i.category,
        weight: i.weight,
        quantity: i.quantity,
        size: 'medium',
        volume: 1.0,
        unitPrice: 25,
        totalPrice: 25 * i.quantity,
        description: `${i.name} from ${i.room}`,
      })),
    });
    
    // Auto-calculate pricing
    if (calculatePricing) {
      setTimeout(() => calculatePricing(), 500);
    }
    
    toast({
      title: 'Items added by AI',
      description: `Added ${aiItems.length} item(s) successfully`,
      status: 'success',
      duration: 3000,
    });
  };

  // Handle removing item
  const handleRemoveItem = (itemId: string) => {
    const updated = selectedItemsWithRooms.filter(item => item.id !== itemId);
    setSelectedItemsWithRooms(updated);

    updateFormData('step1', {
      items: updated.map(i => ({
        id: i.id,
        name: i.name,
        category: i.category,
        weight: i.weight,
        quantity: i.quantity,
        size: 'medium',
        volume: 1.0,
        unitPrice: 25,
        totalPrice: 25 * i.quantity,
        description: `${i.name} from ${i.room}`,
      })),
    });

    if (calculatePricing) {
      setTimeout(() => calculatePricing(), 500);
    }
  };

  // Handle updating quantity
  const handleUpdateQuantity = (itemId: string, quantity: number) => {
    const updated = selectedItemsWithRooms.map(item =>
      item.id === itemId ? { ...item, quantity } : item
    );
    setSelectedItemsWithRooms(updated);

    updateFormData('step1', {
      items: updated.map(i => ({
        id: i.id,
        name: i.name,
        category: i.category,
        weight: i.weight,
        quantity: i.quantity,
        size: 'medium',
        volume: 1.0,
        unitPrice: 25,
        totalPrice: 25 * i.quantity,
        description: `${i.name} from ${i.room}`,
      })),
    });

    if (calculatePricing) {
      setTimeout(() => calculatePricing(), 500);
    }
  };

  // Calculate totals
  const totalItems = selectedItemsWithRooms.reduce((sum, item) => sum + item.quantity, 0);
  const totalWeight = selectedItemsWithRooms.reduce((sum, item) => sum + (item.weight * item.quantity), 0);

  return (
    <Box>
      <VStack spacing={8} align="stretch">
        {/* AI Assistant - Always visible in all levels */}
        <AIItemExtractionAssistant
          propertyType={propertyType}
          selectedItems={selectedItemsWithRooms.map(item => ({
            id: item.id,
            name: item.name,
            quantity: item.quantity,
          }))}
          onAddItems={handleAiAddItems}
        />

        {/* Level 1: Property Type Selection */}
        {currentLevel === 1 && (
          <Fade in={currentLevel === 1}>
            <PropertyTypeSelector
              selectedType={propertyType}
              onSelectType={handlePropertyTypeSelect}
            />
          </Fade>
        )}

        {/* Level 2: Property Size Selection */}
        {currentLevel === 2 && propertyType && (
          <Fade in={currentLevel === 2}>
            <VStack spacing={6} align="stretch">
              <Button
                leftIcon={<FaArrowLeft />}
                variant="ghost"
                size="sm"
                onClick={() => {
                  setCurrentLevel(1);
                  setPropertySize(undefined);
                }}
                alignSelf="flex-start"
              >
                Change property type
              </Button>

              <PropertySizeSelector
                propertyType={propertyType}
                selectedSize={propertySize}
                onSelectSize={handlePropertySizeSelect}
              />
            </VStack>
          </Fade>
        )}

        {/* Level 3: Room-Based Item Selection */}
        {currentLevel === 3 && propertyType && (
          <Fade in={currentLevel === 3}>
            <VStack spacing={6} align="stretch">
              
              {/* Room-Based Inventory */}
              <RoomBasedInventory
                propertyType={propertyType}
                availableItems={ALL_REMOVAL_ITEMS}
                selectedItems={selectedItemsWithRooms}
                onAddItem={handleAddItem}
                onRemoveItem={handleRemoveItem}
                onUpdateQuantity={handleUpdateQuantity}
                onBack={() => setCurrentLevel(2)}
              />

            </VStack>
          </Fade>
        )}

        {currentLevel === 3 && !propertyType && (
          <Alert status="warning">
            <AlertIcon />
            Please select a property type to continue.
          </Alert>
        )}

        {/* Error Display */}
        {errors.items && (
          <Alert status="error">
            <AlertIcon />
            {errors.items}
          </Alert>
        )}
      </VStack>

      {/* Floating Black Button for Selected Items - Show in ALL levels when items exist */}
      {selectedItemsWithRooms.length > 0 && (
        <>
          <Box
            position="fixed"
            bottom={{ base: '180px', md: '200px' }}
            right={{ base: '20px', md: '30px' }}
            zIndex={1500}
          >
            <VStack
              as="button"
              onClick={toggleSummary}
              bgGradient={isSummaryExpanded 
                ? "linear(to-br, #dc2626, #991b1b)" 
                : "linear(to-br, #10b981, #059669)"}
              color="white"
              borderRadius="2xl"
              w={{ base: '90px', md: '100px' }}
              h={{ base: '90px', md: '100px' }}
              spacing={1}
              justify="center"
              cursor="pointer"
              boxShadow={isSummaryExpanded 
                ? "0 10px 30px rgba(239, 68, 68, 0.6), 0 0 20px rgba(16, 185, 129, 0.4), inset 0 1px 0 rgba(255,255,255,0.2)" 
                : "0 10px 30px rgba(16, 185, 129, 0.6), 0 0 20px rgba(16, 185, 129, 0.4), inset 0 1px 0 rgba(255,255,255,0.2)"}
              transition="all 0.4s cubic-bezier(0.4, 0, 0.2, 1)"
              border="3px solid"
              borderColor={isSummaryExpanded ? "#ef4444" : "#10b981"}
              position="relative"
              overflow="visible"
              _before={{
                content: '""',
                position: 'absolute',
                inset: '-4px',
                borderRadius: '2xl',
                padding: '4px',
                background: isSummaryExpanded 
                  ? 'linear-gradient(135deg, #ef4444, #dc2626, #991b1b)' 
                  : 'linear-gradient(135deg, #10b981, #059669, #047857)',
                WebkitMask: 'linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0)',
                WebkitMaskComposite: 'xor',
                maskComposite: 'exclude',
                opacity: 0.6,
                animation: 'pulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite'
              }}
              _hover={{
                transform: 'scale(1.12) rotate(2deg)',
                boxShadow: isSummaryExpanded 
                  ? '0 15px 40px rgba(239, 68, 68, 0.8), 0 0 30px rgba(239, 68, 68, 0.6), inset 0 1px 0 rgba(255,255,255,0.3)' 
                  : '0 15px 40px rgba(16, 185, 129, 0.8), 0 0 30px rgba(16, 185, 129, 0.6), inset 0 1px 0 rgba(255,255,255,0.3)',
                borderWidth: '4px'
              }}
              _active={{
                transform: 'scale(1.05) rotate(0deg)',
                boxShadow: isSummaryExpanded
                  ? '0 5px 15px rgba(239, 68, 68, 0.5), inset 0 2px 4px rgba(0,0,0,0.2)'
                  : '0 5px 15px rgba(16, 185, 129, 0.5), inset 0 2px 4px rgba(0,0,0,0.2)'
              }}
            >
              {/* Toggle Icon - Premium Design */}
              <Icon 
                as={isSummaryExpanded ? FaTimes : FaChevronUp} 
                boxSize={{ base: 7, md: 8 }} 
                color="white"
                filter="drop-shadow(0 3px 6px rgba(0,0,0,0.4))"
                transition="all 0.3s"
                _groupHover={{ transform: 'scale(1.1)' }}
              />
              
              {/* Items Count with Premium Badge */}
              <HStack 
                spacing={1} 
                bg="rgba(255,255,255,0.2)" 
                px={2} 
                py={0.5} 
                borderRadius="full"
                backdropFilter="blur(10px)"
              >
                <Icon as={FaBox} boxSize={{ base: 4, md: 5 }} />
                <Text 
                  fontSize={{ base: '2xl', md: '3xl' }} 
                  fontWeight="black" 
                  lineHeight="1"
                  textShadow="0 2px 4px rgba(0,0,0,0.3)"
                >
                  {selectedItemsWithRooms.reduce((sum, item) => sum + item.quantity, 0)}
                </Text>
              </HStack>
              
              {/* Premium Label with Enhanced Typography */}
              <Text 
                fontSize={{ base: '2xs', md: 'xs' }} 
                fontWeight="black" 
                letterSpacing="widest"
                textTransform="uppercase"
                color="white"
                textShadow="0 2px 6px rgba(0,0,0,0.5)"
                mt={-0.5}
              >
                {isSummaryExpanded ? '✕ CLOSE' : '👁 VIEW'}
              </Text>
            </VStack>
          </Box>

          {/* Expanded Details Panel */}
          <Box
            position="fixed"
            bottom="0"
            left="0"
            right="0"
            zIndex={1400}
            pointerEvents={isSummaryExpanded ? 'auto' : 'none'}
          >
            <Collapse in={isSummaryExpanded} animateOpacity>
              <Box
                bg="#050505"
                backdropFilter="blur(20px)"
                borderTop="2px solid"
                borderColor="rgba(168, 85, 247, 0.4)"
                boxShadow="0 -8px 32px rgba(0, 0, 0, 0.8)"
                maxH="60vh"
                overflowY="auto"
                p={{ base: 4, md: 6 }}
              >
                <VStack spacing={4} align="stretch">
                  <HStack justify="space-between">
                    <VStack align="flex-start" spacing={1}>
                      <Heading size="md" color="white">
                        Selected Items
                      </Heading>
                      <Text color="whiteAlpha.600" fontSize="sm">
                        {selectedItemsWithRooms.reduce((sum, item) => sum + item.quantity, 0)} total items • {selectedItemsWithRooms.length} unique
                      </Text>
                    </VStack>
                    <Button
                      size="sm"
                      variant="ghost"
                      colorScheme="red"
                      onClick={toggleSummary}
                      rightIcon={<FaTimes />}
                    >
                      Close
                    </Button>
                  </HStack>

                  <SimpleGrid columns={{ base: 1, md: 2, lg: 3 }} spacing={4}>
                    {selectedItemsWithRooms.map((item, index) => {
                      const fullItem = ALL_REMOVAL_ITEMS.find(i => i.id === item.id);
                      
                      console.log('🔍 DEBUG Card Display:', {
                        index,
                        itemId: item.id,
                        itemName: item.name,
                        fullItemFound: !!fullItem,
                        fullItemName: fullItem?.name,
                        fullItemImage: fullItem?.image,
                        matches: item.id === fullItem?.id && item.name === fullItem?.name
                      });

                      return (
                        <Card
                          key={`${item.id}-${item.room}-${index}`}
                          bg="rgba(15, 15, 18, 0.95)"
                          border="2px solid"
                          borderColor="rgba(168, 85, 247, 0.5)"
                          borderRadius="xl"
                          overflow="hidden"
                          boxShadow="0 4px 12px rgba(168, 85, 247, 0.3)"
                          transition="all 0.3s"
                          _hover={{
                            borderColor: "rgba(168, 85, 247, 0.8)",
                            boxShadow: "0 6px 16px rgba(168, 85, 247, 0.5)",
                            transform: "translateY(-2px)"
                          }}
                        >
                          <CardBody p={3}>
                            <VStack spacing={3} align="stretch">
                              {/* Item Image */}
                              <Box
                                position="relative"
                                w="100%"
                                h="140px"
                                bg="white"
                                borderRadius="lg"
                                overflow="hidden"
                              >
                                {fullItem?.image ? (
                                  <NextImage
                                    src={fullItem.image}
                                    alt={fullItem.name}
                                    fill
                                    sizes="(max-width: 768px) 100vw, (max-width: 1200px) 50vw, 33vw"
                                    style={{
                                      objectFit: 'contain',
                                      objectPosition: 'center',
                                    }}
                                  />
                                ) : (
                                  <Box
                                    w="100%"
                                    h="100%"
                                    display="flex"
                                    alignItems="center"
                                    justifyContent="center"
                                  >
                                    <Icon as={FaBox} boxSize={8} color="gray.400" />
                                  </Box>
                                )}
                              </Box>

                              {/* Item Details */}
                              <VStack align="stretch" spacing={2}>
                                <Text color="white" fontWeight="bold" fontSize="sm" noOfLines={2}>
                                  {fullItem?.name || item.name}
                                </Text>
                                <HStack justify="space-between">
                                  <Badge colorScheme="purple" fontSize="xs">
                                    {item.room}
                                  </Badge>
                                  <Text color="whiteAlpha.600" fontSize="xs" fontWeight="medium">
                                    {fullItem?.weight || item.weight}kg
                                  </Text>
                                </HStack>
                              </VStack>

                              {/* Quantity Controls */}
                              <HStack spacing={2} justify="space-between">
                                <HStack spacing={1} flex={1}>
                                  <Button
                                    size="sm"
                                    colorScheme="red"
                                    variant="ghost"
                                    onClick={() => {
                                      if (item.quantity > 1) {
                                        const updated = selectedItemsWithRooms.map((i, idx) =>
                                          idx === index ? { ...i, quantity: i.quantity - 1 } : i
                                        );
                                        setSelectedItemsWithRooms(updated);
                                        updateFormData('step1', {
                                          items: updated.map(({ id, quantity, room }) => {
                                            const fullItem = ALL_REMOVAL_ITEMS.find(item => item.id === id);
                                            const name = fullItem?.name || '';
                                            const weight = fullItem?.weight || 0;
                                            const estimatedVolume = weight * 0.05; // تقدير الحجم بناء على الوزن
                                            const basePrice = 25;
                                            return {
                                              id,
                                              quantity,
                                              name,
                                              description: `${name} from ${room}`,
                                              category: fullItem?.category || '',
                                              size: 'medium' as const,
                                              weight,
                                              volume: estimatedVolume,
                                              unitPrice: basePrice,
                                              totalPrice: basePrice * quantity,
                                              image: fullItem?.image,
                                              room
                                            };
                                          })
                                        });
                                      }
                                    }}
                                    isDisabled={item.quantity <= 1}
                                  >
                                    <Icon as={FaMinus} />
                                  </Button>
                                  
                                  <Text 
                                    color="white" 
                                    fontWeight="black" 
                                    fontSize="xl"
                                    minW="40px"
                                    textAlign="center"
                                  >
                                    {item.quantity}
                                  </Text>
                                  
                                  <Button
                                    size="sm"
                                    colorScheme="green"
                                    variant="ghost"
                                    onClick={() => {
                                      const updated = selectedItemsWithRooms.map((i, idx) =>
                                        idx === index ? { ...i, quantity: i.quantity + 1 } : i
                                      );
                                      setSelectedItemsWithRooms(updated);
                                      updateFormData('step1', {
                                        items: updated.map(({ id, quantity, room }) => {
                                          const fullItem = ALL_REMOVAL_ITEMS.find(item => item.id === id);
                                          const name = fullItem?.name || '';
                                          const weight = fullItem?.weight || 0;
                                          const estimatedVolume = weight * 0.05; // تقدير الحجم بناء على الوزن
                                          const basePrice = 25;
                                          return {
                                            id,
                                            quantity,
                                            name,
                                            description: `${name} from ${room}`,
                                            category: fullItem?.category || '',
                                            size: 'medium' as const,
                                            weight,
                                            volume: estimatedVolume,
                                            unitPrice: basePrice,
                                            totalPrice: basePrice * quantity,
                                            image: fullItem?.image,
                                            room
                                          };
                                        })
                                      });
                                    }}
                                  >
                                    <Icon as={FaPlus} />
                                  </Button>
                                </HStack>

                                <Button
                                  size="sm"
                                  colorScheme="red"
                                  onClick={() => {
                                    const updated = selectedItemsWithRooms.filter((_, idx) => idx !== index);
                                    setSelectedItemsWithRooms(updated);
                                    updateFormData('step1', {
                                      items: updated.map(({ id, quantity, room }) => {
                                        const fullItem = ALL_REMOVAL_ITEMS.find(item => item.id === id);
                                        const name = fullItem?.name || '';
                                        const weight = fullItem?.weight || 0;
                                        const estimatedVolume = weight * 0.05; // تقدير الحجم بناء على الوزن
                                        const basePrice = 25;
                                        return {
                                          id,
                                          quantity,
                                          name,
                                          description: `${name} from ${room}`,
                                          category: fullItem?.category || '',
                                          size: 'medium' as const,
                                          weight,
                                          volume: estimatedVolume,
                                          unitPrice: basePrice,
                                          totalPrice: basePrice * quantity,
                                          image: fullItem?.image,
                                          room
                                        };
                                      })
                                    });
                                    toast({
                                      title: 'Item removed',
                                      status: 'success',
                                      duration: 2000,
                                    });
                                  }}
                                >
                                  <Icon as={FaTrash} />
                                </Button>
                              </HStack>
                            </VStack>
                          </CardBody>
                        </Card>
                      );
                    })}
                  </SimpleGrid>
                </VStack>
              </Box>
            </Collapse>
          </Box>
        </>
      )}
    </Box>
  );
}

'use client';

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import {
  Box,
  VStack,
  HStack,
  Heading,
  Text,
  Button,
  Input,
  InputGroup,
  InputLeftElement,
  IconButton,
  useToast,
  Divider,
  Icon,
  SimpleGrid,
  Select,
  NumberInput,
  NumberInputField,
  NumberInputStepper,
  NumberIncrementStepper,
  NumberDecrementStepper,
  Switch,
  FormLabel,
  FormControl,
  FormErrorMessage,
  Badge,
  Flex,
  Card,
  CardBody,
  Circle,
  Collapse,
  useDisclosure,
  Progress,
  Container,
  Tooltip,
  Image,
  Grid,
} from '@chakra-ui/react';

import {
  FaMapMarkerAlt,
  FaBolt,
  FaTrash,
  FaBuilding,
  FaParking,
  FaTags,
  FaCalendarAlt,
  FaClock,
  FaSearch,
  FaPlus,
  FaMinus,
  FaCheck,
  FaCheckCircle,
  FaArrowUp,
  FaArrowDown,
  FaHome,
  FaCouch,
  FaBed,
  FaTv,
  FaUtensils,
  FaTshirt,
  FaFire,
  FaCoffee,
  FaChair,
  FaBoxOpen,
  FaArrowLeft,
  FaArrowRight,
  FaEye,
} from 'react-icons/fa';
import { MdElevator, MdKitchen, MdLocalLaundryService, MdTv } from 'react-icons/md';

import type { FormData } from '../hooks/useBookingForm';

interface WhereAndWhatStepProps {
  formData: FormData;
  updateFormData: (step: keyof FormData, data: Partial<FormData[keyof FormData]>) => void;
  errors: Record<string, string>;
  onNext?: () => void;
}

export default function WhereAndWhatStep({
  formData,
  updateFormData,
  errors,
  onNext,
}: WhereAndWhatStepProps) {
  
  // State for item selection mode
  const [itemSelectionMode, setItemSelectionMode] = useState<'bedroom' | 'smart' | 'choose'>('choose');
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('All');
  const [showImages, setShowImages] = useState(false);
  
  const { step1 } = formData;
  const toast = useToast();

  // Simplified furniture items
  const furnitureItems = [
    { id: 1, name: 'Sofa', price: '35', category: 'Living Room', icon: '🛋️' },
    { id: 2, name: 'Bed', price: '30', category: 'Bedroom', icon: '🛏️' },
    { id: 3, name: 'Dining Table', price: '25', category: 'Dining', icon: '🍽️' },
    { id: 4, name: 'Wardrobe', price: '40', category: 'Bedroom', icon: '👕' },
    { id: 5, name: 'TV', price: '25', category: 'Electronics', icon: '📺' },
    { id: 6, name: 'Washing Machine', price: '45', category: 'Appliances', icon: '🧺' },
    { id: 7, name: 'Fridge', price: '50', category: 'Kitchen', icon: '🥶' },
    { id: 8, name: 'Microwave', price: '15', category: 'Kitchen', icon: '🔥' },
  ];

  const applianceItems = [
    { id: 9, name: 'Dishwasher', price: '45', category: 'Kitchen', icon: '🍽️' },
    { id: 10, name: 'Oven', price: '40', category: 'Kitchen', icon: '🔥' },
    { id: 11, name: 'Dryer', price: '35', category: 'Appliances', icon: '🧺' },
  ];

  const bedroomPackages = [
  { id: 1, name: '1 Bedroom', items: 15, price: '350', image: '/items/one%20bedroom.png' },
  { id: 2, name: '2 Bedroom', items: 25, price: '550', image: '/items/2%20bedroom.png' },
  { id: 3, name: '3 Bedroom', items: 35, price: '750', image: '/items/3%20bed%20rooms.png' },
  ];

  // Handlers
  const addItem = (item: any) => {
    const existingItem = step1.items.find(i => i.id === item.id);
    if (existingItem) {
      updateFormData('step1', {
        items: step1.items.map(i => 
          i.id === item.id ? { ...i, quantity: i.quantity + 1 } : i
        )
      });
    } else {
      updateFormData('step1', {
        items: [...step1.items, { ...item, quantity: 1 }]
      });
    }
  };

  const removeItem = (itemId: number) => {
    updateFormData('step1', {
      items: step1.items.filter(i => parseInt(i.id) !== itemId)
    });
  };

  const updateQuantity = (itemId: number, quantity: number) => {
    if (quantity === 0) {
      removeItem(itemId);
    } else {
      updateFormData('step1', {
        items: step1.items.map(i =>
          parseInt(i.id) === itemId ? { ...i, quantity } : i
        )
      });
    }
  };

  const calculateTotal = () => {
    return step1.items.reduce((total, item) => {
      return total + (item.unitPrice * item.quantity);
    }, 0);
  };

  return (
    <Container maxW="6xl" py={8}>
      <VStack spacing={8} align="stretch">
        
        {/* Header */}
        <VStack spacing={4} textAlign="center">
          <Heading size="xl" color="white">
            What needs moving?
          </Heading>
          <Text color="gray.400" fontSize="lg" maxW="600px">
            Select the items you need to move. You can choose individual items or complete house packages.
          </Text>
        </VStack>

        {/* Address Summary */}
        <Card bg="gray.800" borderRadius="lg" border="1px solid" borderColor="gray.600">
          <CardBody p={4}>
            <HStack justify="space-between" align="center">
              <VStack align="start" spacing={1}>
                <Text fontSize="sm" color="gray.400">Moving From</Text>
                <Text color="white" fontWeight="medium">
                  {step1.pickupAddress?.address || 'Not selected'}
                </Text>
              </VStack>
              <Icon as={FaArrowRight} color="gray.400" />
              <VStack align="end" spacing={1}>
                <Text fontSize="sm" color="gray.400">Moving To</Text>
                <Text color="white" fontWeight="medium">
                  {step1.dropoffAddress?.address || 'Not selected'}
                </Text>
              </VStack>
            </HStack>
          </CardBody>
        </Card>

        {/* Item Selection */}
        <Card bg="gray.800" borderRadius="lg" border="1px solid" borderColor="gray.600">
          <CardBody p={6}>
            <VStack spacing={6}>
              
              {/* Header */}
              <VStack spacing={2} textAlign="center">
                <Heading size="md" color="white">
                  Select Your Items
                </Heading>
                <Text color="gray.400" fontSize="md">
                  Choose how you'd like to add items
                </Text>
              </VStack>

              {/* Stats */}
              <HStack spacing={6} justify="center">
                <VStack spacing={1}>
                  <Text fontSize="xl" fontWeight="bold" color="blue.400">
                    {furnitureItems.length + applianceItems.length}
                  </Text>
                  <Text fontSize="sm" color="gray.400">
                    Individual Items
                  </Text>
                </VStack>
                
                <VStack spacing={1}>
                  <Text fontSize="xl" fontWeight="bold" color="green.400">
                    {bedroomPackages.length}
                  </Text>
                  <Text fontSize="sm" color="gray.400">
                    House Packages
                  </Text>
                </VStack>
              </HStack>

              {/* Selection Modes */}
              <HStack spacing={3} flexWrap="wrap" justify="center">
                <Button 
                  variant={itemSelectionMode === 'bedroom' ? 'solid' : 'outline'}
                  bg={itemSelectionMode === 'bedroom' ? 'blue.600' : 'gray.700'}
                  color="white"
                  borderColor="gray.600"
                  onClick={() => setItemSelectionMode('bedroom')}
                  leftIcon={<FaHome />}
                  _hover={{ bg: 'blue.700' }}
                >
                  House Packages
                </Button>
                <Button 
                  variant={itemSelectionMode === 'smart' ? 'solid' : 'outline'}
                  bg={itemSelectionMode === 'smart' ? 'purple.600' : 'gray.700'}
                  color="white"
                  borderColor="gray.600"
                  onClick={() => setItemSelectionMode('smart')}
                  leftIcon={<FaSearch />}
                  _hover={{ bg: 'purple.700' }}
                >
                  Search Items
                </Button>
                <Button 
                  variant={itemSelectionMode === 'choose' ? 'solid' : 'outline'}
                  bg={itemSelectionMode === 'choose' ? 'green.600' : 'gray.700'}
                  color="white"
                  borderColor="gray.600"
                  onClick={() => setItemSelectionMode('choose')}
                  leftIcon={<FaCouch />}
                  _hover={{ bg: 'green.700' }}
                >
                  Individual Items
                </Button>
              </HStack>

              <Divider borderColor="gray.600" />

              {/* House Packages Mode */}
              {itemSelectionMode === 'bedroom' && (
                <SimpleGrid columns={{ base: 1, md: 3 }} spacing={4} w="full">
                  {bedroomPackages.map((pkg) => (
                    <Card
                      key={pkg.id}
                      bg="gray.700"
                      borderRadius="lg"
                      border="1px solid"
                      borderColor="gray.600"
                      cursor="pointer"
                      _hover={{ borderColor: "blue.500" }}
                      onClick={() => addItem(pkg)}
                    >
                      <CardBody p={4} textAlign="center">
                        <VStack spacing={3}>
                          <Box w="100%" h="120px" borderRadius="md" overflow="hidden" bg="gray.900" display="flex" alignItems="center" justifyContent="center">
                            <Image src={pkg.image} alt={pkg.name} w="100%" h="100%" objectFit="cover" />
                          </Box>
                          <VStack spacing={1}>
                            <Text fontSize="lg" color="white" fontWeight="bold">
                              {pkg.name}
                            </Text>
                            <Text fontSize="sm" color="gray.400">
                              ~{pkg.items} items
                            </Text>
                            <Text fontSize="xl" color="green.400" fontWeight="bold">
                              £{pkg.price}
                            </Text>
                          </VStack>
                        </VStack>
                      </CardBody>
                    </Card>
                  ))}
                </SimpleGrid>
              )}

              {/* Search Mode */}
              {itemSelectionMode === 'smart' && (
                <VStack spacing={4} w="full">
                  <InputGroup size="lg">
                    <InputLeftElement>
                      <Icon as={FaSearch} color="gray.400" />
                    </InputLeftElement>
                    <Input
                      placeholder="Search for items (e.g., 'sofa', 'kitchen appliances')"
                      bg="gray.700"
                      border="1px solid"
                      borderColor="gray.600"
                      color="white"
                      _placeholder={{ color: "gray.400" }}
                      _focus={{ borderColor: 'purple.500' }}
                      value={searchQuery}
                      onChange={(e) => setSearchQuery(e.target.value)}
                    />
                  </InputGroup>
                  
                  {/* Quick Categories */}
                  <HStack spacing={2} wrap="wrap" justify="center">
                    {['Living Room', 'Bedroom', 'Kitchen', 'Appliances'].map((category) => (
                      <Button
                        key={category}
                        size="sm"
                        variant="outline"
                        bg="gray.700"
                        borderColor="gray.600"
                        color="white"
                        _hover={{ bg: "purple.700" }}
                        onClick={() => setSearchQuery(category.toLowerCase())}
                      >
                        {category}
                      </Button>
                    ))}
                  </HStack>
                </VStack>
              )}

              {/* Individual Items Mode */}
              {itemSelectionMode === 'choose' && (
                <VStack spacing={4} w="full">
                  <Text fontSize="lg" color="white" fontWeight="semibold" textAlign="center">
                    Choose Individual Items
                  </Text>
                  
                  <SimpleGrid columns={{ base: 2, md: 4 }} spacing={3} w="full">
                    {[...furnitureItems, ...applianceItems]
                      .filter(item => 
                        searchQuery === '' || 
                        item.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
                        item.category.toLowerCase().includes(searchQuery.toLowerCase())
                      )
                      .map((item) => (
                      <Card
                        key={item.id}
                        bg="gray.700"
                        borderRadius="lg"
                        border="1px solid"
                        borderColor="gray.600"
                        cursor="pointer"
                        _hover={{ borderColor: "green.500" }}
                        onClick={() => addItem(item)}
                      >
                        <CardBody p={3} textAlign="center">
                          <VStack spacing={2}>
                            <Text fontSize="2xl">{item.icon}</Text>
                            <Text fontSize="sm" color="white" fontWeight="medium">
                              {item.name}
                            </Text>
                            <Text fontSize="xs" color="gray.400">
                              {item.category}
                            </Text>
                            <Text fontSize="lg" color="green.400" fontWeight="bold">
                              £{item.price}
                            </Text>
                          </VStack>
                        </CardBody>
                      </Card>
                    ))}
                  </SimpleGrid>
                </VStack>
              )}

            </VStack>
          </CardBody>
        </Card>

        {/* Selected Items */}
        {step1.items.length > 0 && (
          <Card bg="gray.800" borderRadius="lg" border="1px solid" borderColor="green.600">
            <CardBody p={6}>
              <VStack spacing={4}>
                <Heading size="md" color="white">
                  Selected Items ({step1.items.length})
                </Heading>
                
                <VStack spacing={3} w="full">
                  {step1.items.map((item) => (
                    <HStack key={item.id} justify="space-between" w="full" p={3} bg="gray.700" borderRadius="lg">
                      <HStack spacing={3}>
                        <VStack align="start" spacing={0}>
                          <Text color="white" fontWeight="medium">{item.name}</Text>
                          <Text fontSize="sm" color="gray.400">£{item.unitPrice} each</Text>
                        </VStack>
                      </HStack>
                      
                      <HStack spacing={2}>
                        <IconButton
                          size="sm"
                          icon={<FaMinus />}
                          onClick={() => updateQuantity(parseInt(item.id), item.quantity - 1)}
                          bg="gray.600"
                          color="white"
                          _hover={{ bg: "gray.500" }}
                          aria-label="Decrease quantity"
                        />
                        <Text color="white" fontWeight="bold" minW="40px" textAlign="center">
                          {item.quantity}
                        </Text>
                        <IconButton
                          size="sm"
                          icon={<FaPlus />}
                          onClick={() => updateQuantity(parseInt(item.id), item.quantity + 1)}
                          bg="green.600"
                          color="white"
                          _hover={{ bg: "green.500" }}
                          aria-label="Increase quantity"
                        />
                        <IconButton
                          size="sm"
                          icon={<FaTrash />}
                          onClick={() => removeItem(parseInt(item.id))}
                          bg="red.600"
                          color="white"
                          _hover={{ bg: "red.500" }}
                          aria-label="Remove item"
                        />
                      </HStack>
                    </HStack>
                  ))}
                </VStack>

                {/* Total */}
                <HStack justify="space-between" w="full" pt={4} borderTop="1px solid" borderColor="gray.600">
                  <Text fontSize="lg" color="white" fontWeight="bold">
                    Total Estimated Cost:
                  </Text>
                  <Text fontSize="xl" color="green.400" fontWeight="bold">
                    £{calculateTotal().toFixed(2)}
                  </Text>
                </HStack>
              </VStack>
            </CardBody>
          </Card>
        )}

        {/* Continue Button */}
        <Card bg="gray.800" borderRadius="lg" border="1px solid" borderColor="gray.600">
          <CardBody p={6}>
            <HStack justify="space-between" w="full">
              <Badge bg="green.600" color="white" p={3} borderRadius="lg">
                ✅ {step1.items.length} Items Selected
              </Badge>

              {onNext && (
                <Button
                  colorScheme="blue"
                  size="lg"
                  isDisabled={step1.items.length === 0}
                  onClick={onNext}
                  rightIcon={<Icon as={FaArrowRight} />}
                  _disabled={{
                    opacity: 0.5,
                    cursor: "not-allowed"
                  }}
                >
                  Continue
                </Button>
              )}
            </HStack>
          </CardBody>
        </Card>

      </VStack>
    </Container>
  );
}

