                borderColor="rgba(168, 85, 247, 0.5)"
                transition="all 0.3s"
                _hover={{
                  transform: "scale(1.1) rotate(5deg)",
                  boxShadow: "0 6px 30px rgba(168, 85, 247, 0.6), inset 0 1px 0 rgba(255, 255, 255, 0.3)",
