                      const hasDropoffAddress = formData.step1.dropoffAddress?.full || formData.step1.dropoffAddress?.line1 || formData.step1.dropoffAddress?.address || formData.step1.dropoffAddress?.formatted_address;
                      const hasValidPickupCoordinates = !!(formData.step1.pickupAddress?.coordinates?.lat && formData.step1.pickupAddress?.coordinates?.lng &&
                                                          (formData.step1.pickupAddress.coordinates.lat !== 0 || formData.step1.pickupAddress.coordinates.lng !== 0));
                      const hasValidDropoffCoordinates = !!(formData.step1.dropoffAddress?.coordinates?.lat && formData.step1.dropoffAddress?.coordinates?.lng &&
                                                           (formData.step1.dropoffAddress.coordinates.lat !== 0 || formData.step1.dropoffAddress.coordinates.lng !== 0));

                      console.log('🔍 Enhanced pricing error diagnosis:', {
                        hasItems,
                        hasPickupAddress: !!hasPickupAddress,
                        hasDropoffAddress: !!hasDropoffAddress,
                        hasValidPickupCoordinates,
                        hasValidDropoffCoordinates,
                        isCalculatingPricing,
                        pricingTotal: formData.step1.pricing.total,
                        pickupCoords: formData.step1.pickupAddress?.coordinates,
                        dropoffCoords: formData.step1.dropoffAddress?.coordinates
                      });

                      if (!hasItems) {
                        return 'Please add items to your booking to see pricing details.';
                      } else if (!hasPickupAddress || !hasDropoffAddress) {
                        return 'Please complete Step 1 with pickup and dropoff addresses to see pricing details.';
                      } else if (!hasValidPickupCoordinates || !hasValidDropoffCoordinates) {
                        return 'Please wait for address coordinates to be resolved to calculate pricing.';
                      } else if (isCalculatingPricing) {
                        return 'Calculating pricing... Please wait a moment.';
                      } else {
                        return 'Pricing calculation in progress. If this persists, please click "Calculate Pricing" below.';
                      }
                    })()}
                  </Text>
                </VStack>
              </VStack>
            </Box>
          )}
        </VStack>
      </Card>

      {/* Back to Step 1 Button - Separate row */}
      <Box w="full" mt={{ base: 6, sm: 8 }} mb={3}>
        <Button
          size={{ base: "md", sm: "lg" }}
          minH={{ base: "48px", sm: "44px" }}
          w={{ base: "full", sm: "auto" }}
          colorScheme="gray"
          variant="outline"
          onClick={() => window.history.back()}
          leftIcon={<Icon as={FaBolt} fontSize={{ base: "16px", sm: "18px" }} />}
          borderWidth="2px"
          fontSize={{ base: "sm", sm: "md" }}
          fontWeight="600"
          letterSpacing="0.3px"
          _hover={{ bg: 'gray.700', borderColor: 'gray.500' }}
        >
          {formData.step1.items.length === 0 
            ? 'Add Items'
            : 'Back to Step 1'
          }
        </Button>
      </Box>

      {/* Payment Button - Centered */}
      <Flex w="full" justify="center" mt={{ base: 4, sm: 6 }} mb={{ base: 3, sm: 4 }}>
        {/* Stripe Payment Button */}
        {!paymentSuccess ? (
          <Box maxW={{ base: "full", md: "500px" }} w="full">
            <StripePaymentButton
            amount={step2.promotionDetails?.finalAmount || formData.step1.pricing.total}
            bookingData={{
              customer: {
                name: `${step2.customerDetails.firstName || ''} ${step2.customerDetails.lastName || ''}`.trim(),
                email: step2.customerDetails.email || '',
                phone: step2.customerDetails.phone || '',
              },
              pickupAddress: {
                ...formData.step1.pickupAddress,
                // Ensure street field is populated from multiple sources
                street: (formData.step1.pickupAddress as any)?.street || 
                       formData.step1.pickupAddress?.formatted?.street ||
                       formData.step1.pickupAddress?.line1 || 
                       formData.step1.pickupAddress?.address || 
                       (formData.step1.pickupAddress as any)?.formatted_address ||
                       formData.step1.pickupAddress?.full ||
                       '',
              },
              dropoffAddress: {
                ...formData.step1.dropoffAddress,
                // Ensure street field is populated from multiple sources
                street: (formData.step1.dropoffAddress as any)?.street || 
                       formData.step1.dropoffAddress?.formatted?.street ||
                       formData.step1.dropoffAddress?.line1 || 
                       formData.step1.dropoffAddress?.address || 
                       (formData.step1.dropoffAddress as any)?.formatted_address ||
                       formData.step1.dropoffAddress?.full ||
                       '',
              },
              items: formData.step1.items,
              pricing: formData.step1.pricing,
              serviceType: formData.step1.serviceType,
              scheduledDate: formData.step1.pickupDate,
              scheduledTime: formData.step1.pickupTimeSlot,
              pickupDetails: formData.step1.pickupProperty,
              dropoffDetails: formData.step1.dropoffProperty,
              notes: step2.specialInstructions || '',
              bookingId: step2.bookingId,
              economyPrice,
              standardPrice,
              priorityPrice,
            }}
            onSuccess={(sessionId, paymentIntentId) => {
              updatePaymentStatus('success');
              updateFormData('step2', {
                paymentMethod: {
                  type: 'stripe',
                  stripeDetails: {
                    sessionId,
                    paymentIntentId,
                  },
                },
              });
            }}
            onError={(error) => {
              console.error('❌ Payment failed:', error);
              updatePaymentStatus('failed');
            }}
            disabled={
              !step2.termsAccepted || 
              !step2.privacyAccepted || 
              !step2.customerDetails.firstName ||
              !step2.customerDetails.lastName ||
              !step2.customerDetails.email ||
              !formData.step1.pricing.total ||
              formData.step1.pricing.total <= 0
            }
          />
          </Box>
        ) : (
          <Alert status="success" borderRadius="xl" p={4} maxW={{ base: "full", md: "500px" }} w="full">
            <AlertIcon />
            <Box>
              <AlertTitle fontSize="lg">🎉 Payment Successful!</AlertTitle>
              <AlertDescription fontSize="md">
                Your payment has been processed successfully. You will be redirected to the confirmation page.
              </AlertDescription>
            </Box>
          </Alert>
        )}
      </Flex>

    </VStack>
  );
}

﻿'use client';

/**
 * Step 3: Customer Details & Payment - Simplified Version
 * Updated: 2025-11-20 - Enhanced toggle button UX
 * Clean, modern design like Uber/Airbnb
 */

import React, { useState, useCallback, useMemo } from 'react';
import NextImage from 'next/image';
import {
  Box,
  VStack,
  HStack,
  Text,
  Input,
  Textarea,
  Checkbox,
  Card,
  CardBody,
  Divider,
  Badge,
  useToast,
  FormControl,
  FormLabel,
  FormErrorMessage,
  Icon,
  SimpleGrid,
  IconButton,
  Image,
  Collapse,
  useDisclosure,
} from '@chakra-ui/react';
import {
  FaCreditCard,
  FaPlus,
  FaMinus,
  FaTrash,
  FaBox,
  FaChevronUp,
  FaTimes,
} from 'react-icons/fa';
import { FormData, CustomerDetails } from '../hooks/useBookingForm';
import StripePaymentButton from './StripePaymentButton';

interface WhoAndPaymentStepProps {
  formData: FormData;
  updateFormData: (step: keyof FormData, data: Partial<FormData[keyof FormData]>) => void;
  errors: Record<string, string>;
  paymentSuccess?: boolean;
  isCalculatingPricing?: boolean;
  economyPrice?: number;
  standardPrice?: number;
  priorityPrice?: number;
  calculatePricing?: () => Promise<boolean>;
  validatePromotionCode?: (code: string) => Promise<{ success: boolean; error?: string; promotion?: any }>;
  applyPromotionCode?: (code: string) => Promise<{ success: boolean; error?: string; promotion?: any }>;
  removePromotionCode?: () => void;
}

export default function WhoAndPaymentStepSimple({
  formData,
  updateFormData,
  errors,
  economyPrice = 0,
  standardPrice = 0,
  priorityPrice = 0,
}: WhoAndPaymentStepProps) {
  const [selectedService, setSelectedService] = useState<'economy' | 'standard' | 'express'>('standard');
  const [acceptedTerms, setAcceptedTerms] = useState(false);
  const [acceptedPrivacy, setAcceptedPrivacy] = useState(false);
  const { isOpen: isSummaryExpanded, onToggle: toggleSummary } = useDisclosure({ defaultIsOpen: false });
  const [isIPhoneLayout, setIsIPhoneLayout] = React.useState(false);
  const toast = useToast();

  // Detect iPhone 14/15/16/17 screen width
  React.useEffect(() => {
    const checkScreenSize = () => {
      const width = window.innerWidth;
      const isTargetIPhone = width >= 375 && width <= 430;
      setIsIPhoneLayout(isTargetIPhone);
    };
    
    checkScreenSize();
    window.addEventListener('resize', checkScreenSize);
    return () => window.removeEventListener('resize', checkScreenSize);
  }, []);
  
  // REMOVED: This useEffect was causing auto-scroll on desktop on every render
  // Mobile scroll position is now handled properly in individual event handlers
  
  const sanitizePrice = (value: number | undefined | null) => {
    if (typeof value === 'number') {
      if (!Number.isNaN(value)) {
        if (value > 0) {
          const fixed = value.toFixed(2);
          return parseFloat(fixed);
        }
      }
    }
    return undefined;
  };

  let safeStandardPrice = sanitizePrice(standardPrice);
  if (safeStandardPrice === undefined) {
    const fallbackStandard = sanitizePrice(formData.step1.pricing?.total);
    if (fallbackStandard !== undefined) {
      safeStandardPrice = fallbackStandard;
    } else {
      safeStandardPrice = 0;
    }
  }

  let safeEconomyPrice = sanitizePrice(economyPrice);
  if (safeEconomyPrice === undefined) {
    if (safeStandardPrice > 0) {
      const computedEconomy = (safeStandardPrice * 0.85).toFixed(2);
      safeEconomyPrice = parseFloat(computedEconomy);
    } else {
      safeEconomyPrice = 0;
    }
  }

  let safeExpressPrice = sanitizePrice(priorityPrice);
  if (safeExpressPrice === undefined) {
    if (safeStandardPrice > 0) {
      const computedExpress = (safeStandardPrice * 1.5).toFixed(2);
      safeExpressPrice = parseFloat(computedExpress);
    } else {
      safeExpressPrice = 0;
    }
  }

  const actualPrice = selectedService === 'economy'
    ? safeEconomyPrice
    : selectedService === 'express'
    ? safeExpressPrice
    : safeStandardPrice;

  console.log('💰 Step 3 Pricing Sanity Check:', {
    economyFromProps: economyPrice,
    standardFromProps: standardPrice,
    expressFromProps: priorityPrice,
    safeEconomyPrice,
    safeStandardPrice,
    safeExpressPrice,
    selectedService,
    actualPrice
  });

  const selectedItems = formData.step1.items || [];

  const selectionStats = useMemo(() => {
    if (!selectedItems.length) {
      return { totalItems: 0, totalWeight: 0 };
    }

    let totalItems = 0;
    let totalWeight = 0;

    selectedItems.forEach((item) => {
      totalItems += item.quantity;
      totalWeight += item.quantity * item.weight;
    });

    return { totalItems, totalWeight };
  }, [selectedItems]);

  const applyItemUpdates = useCallback(
    (items: typeof selectedItems) => {
      // Save scroll position before update (mobile only)
      const isMobile = window.innerWidth < 768;
      const scrollY = isMobile ? window.scrollY : undefined;
      
      const sanitizedItems = (items || [])
        .map((item) => ({
          ...item,
          quantity: Math.max(0, item.quantity ?? 0),
        }))
        .filter((item) => item.quantity > 0);

      updateFormData('step1', {
        items: sanitizedItems.map((item) => ({ ...item })),
      });
      
      // Restore scroll position after update (mobile only)
      if (isMobile && scrollY !== undefined) {
        requestAnimationFrame(() => {
          window.scrollTo(0, scrollY);
        });
      }
    },
    [updateFormData]
  );

  const incrementItem = useCallback(
    (itemId: string) => {
      const currentItems = formData.step1.items || [];
      const nextItems = currentItems.map((item) =>
        item.id === itemId
          ? { ...item, quantity: Math.min((item.quantity || 0) + 1, 99) }
          : item
      );
      applyItemUpdates(nextItems);
    },
    [formData.step1.items, applyItemUpdates]
  );

  const decrementItem = useCallback(
    (itemId: string) => {
      const currentItems = formData.step1.items || [];
      const target = currentItems.find((item) => item.id === itemId);
      if (!target) {
        return;
      }

      if ((target.quantity || 0) <= 1) {
        const nextItems = currentItems.filter((item) => item.id !== itemId);
        applyItemUpdates(nextItems);
      } else {
        const nextItems = currentItems.map((item) =>
          item.id === itemId
            ? { ...item, quantity: Math.max((item.quantity || 0) - 1, 1) }
            : item
        );
        applyItemUpdates(nextItems);
      }
    },
    [formData.step1.items, applyItemUpdates]
  );

  const removeItem = useCallback(
    (itemId: string) => {
      const currentItems = formData.step1.items || [];
      const nextItems = currentItems.filter((item) => item.id !== itemId);
      applyItemUpdates(nextItems);
    },
    [formData.step1.items, applyItemUpdates]
  );

  const updateCustomerDetails = useCallback((field: keyof CustomerDetails, value: string) => {
    // Save scroll position before update (mobile only)
    const isMobile = window.innerWidth < 768;
    const scrollY = isMobile ? window.scrollY : undefined;
    
    updateFormData('step2', {
      customerDetails: {
        ...formData.step2.customerDetails,
        [field]: value
      }
    });
    
    // Restore scroll position after update (mobile only)
    if (isMobile && scrollY !== undefined) {
      requestAnimationFrame(() => {
        window.scrollTo(0, scrollY);
      });
    }
  }, [formData.step2.customerDetails, updateFormData]);
  
  // Handle service selection change - just update selected service (no price recalculation)
  const handleServiceChange = useCallback((serviceId: 'economy' | 'standard' | 'express') => {
    // Save scroll position before update (mobile only)
    const isMobile = window.innerWidth < 768;
    const scrollY = isMobile ? window.scrollY : undefined;
    
    setSelectedService(serviceId);
    
    // Get price for selected service (from Step 2 calculation)
    const newTotal = serviceId === 'economy'
      ? safeEconomyPrice
      : serviceId === 'express'
      ? safeExpressPrice
      : safeStandardPrice;
    
    console.log(`🔄 Service changed to ${serviceId} - price: £${newTotal.toFixed(2)} (from Step 2)`);
    
    // Restore scroll position after update (mobile only)
    if (isMobile && scrollY !== undefined) {
      requestAnimationFrame(() => {
        window.scrollTo(0, scrollY);
      });
    }
  }, [safeEconomyPrice, safeStandardPrice, safeExpressPrice]);

  // CRITICAL: Use calculated prices (not static props)
  const services = [
    {
      id: 'economy' as const,
      name: 'Economy',
      price: safeEconomyPrice,
      description: 'Shared route, 7 days delivery',
      icon: '🚐',
      discount: '15% off',
    },
    {
      id: 'standard' as const,
      name: 'Standard',
      price: safeStandardPrice,
      description: 'Direct service, flexible scheduling',
      icon: '🚚',
      popular: true,
    },
    {
      id: 'express' as const,
      name: 'Express',
      price: safeExpressPrice,
      description: 'Same-day or next-day delivery',
      icon: '⚡',
      premium: '50% premium',
    },
  ];

  return (
    <Box w="full">
      <VStack spacing={6} align="stretch">
        {/* Floating Green Button for Selected Items */}
        {selectedItems.length > 0 && (
          <>
            <Box
              position="fixed"
              bottom={{ base: '180px', md: '200px' }}
              right={{ base: '20px', md: '30px' }}
              zIndex={1500}
            >
              <VStack
                as="button"
                onClick={toggleSummary}
                bg="black"
                color="white"
                borderRadius="2xl"
                w={{ base: '85px', md: '95px' }}
                h={{ base: '85px', md: '95px' }}
                spacing={1}
                justify="center"
                cursor="pointer"
                boxShadow={isSummaryExpanded 
                  ? "0 8px 24px rgba(239, 68, 68, 0.5), 0 0 0 2px white" 
                  : "0 8px 24px rgba(16, 185, 129, 0.5), 0 0 0 2px white"}
                transition="all 0.3s cubic-bezier(0.4, 0, 0.2, 1)"
                border="3px solid white"
                _hover={{
                  transform: 'scale(1.1)',
                  boxShadow: isSummaryExpanded 
                    ? '0 12px 32px rgba(239, 68, 68, 0.7), 0 0 0 3px white' 
                    : '0 12px 32px rgba(16, 185, 129, 0.7), 0 0 0 3px white'
                }}
                _active={{
                  transform: 'scale(1.05)'
                }}
              >
                {/* Toggle Icon - Very Clear */}
                <Icon 
                  as={isSummaryExpanded ? FaTimes : FaChevronUp} 
                  boxSize={{ base: 6, md: 7 }} 
                  color="white"
                  filter="drop-shadow(0 2px 4px rgba(0,0,0,0.3))"
                />
                
                {/* Items Count with Box Icon */}
                <HStack spacing={1}>
                  <Icon as={FaBox} boxSize={{ base: 3, md: 4 }} />
                  <Text fontSize={{ base: '2xl', md: '3xl' }} fontWeight="black" lineHeight="1">
                    {selectionStats.totalItems}
                  </Text>
                </HStack>
                
                {/* Clear Label Text */}
                <Text 
                  fontSize={{ base: 'xs', md: 'sm' }} 
                  fontWeight="black" 
                  letterSpacing="wider"
                  textTransform="uppercase"
                  color="white"
                  textShadow="0 2px 4px rgba(0,0,0,0.4)"
                >
                  {isSummaryExpanded ? '✕ CLOSE' : '👁 VIEW'}
                </Text>
              </VStack>
            </Box>

            {/* Expanded Details Panel */}
            <Box
              position="fixed"
              bottom="0"
              left="0"
              right="0"
              zIndex={1400}
              pointerEvents={isSummaryExpanded ? 'auto' : 'none'}
            >
              <Collapse in={isSummaryExpanded} animateOpacity>
                <Box 
                  bg="#050505" 
                  color="white" 
