                            </Badge>
                          </HStack>

                          <Box
                            h="80px"
                            position="relative"
                            overflow="hidden"
                            border="none"
                            borderRadius="0"
                            bg="transparent"
                            boxShadow="none"
                          >
                            {item.image ? (
                              <NextImage
                                src={item.image}
                                alt={item.name}
                                fill
                                sizes="50vw"
                                style={{
                                  objectFit: 'cover',
                                }}
                              />
                            ) : (
                              <Box
                                w="100%"
                                h="100%"
                                display="flex"
                                alignItems="center"
                                justifyContent="center"
                                bg="transparent"
                              >
                                <Icon as={FaBox} boxSize={6} color="gray.500" />
                              </Box>
                            )}
                          </Box>

                          <Box>
                            <Text fontSize="xs" fontWeight="bold" noOfLines={2} lineHeight="1.3" mb={1}>
                              {item.name}
                            </Text>
                            <Text fontSize="2xs" color="whiteAlpha.600">
                              {item.weight}kg each · {item.quantity * item.weight}kg total
                            </Text>
                          </Box>

                          <HStack spacing={3} justify="center" w="full">
                            <button
                              onClick={(e) => {
                                e.stopPropagation();
                                decrementItem(item.id);
                              }}
                              style={{
                                background: 'none',
                                border: 'none',
                                color: 'white',
                                fontSize: '28px',
                                fontWeight: 'normal',
                                cursor: 'pointer',
                                padding: '0',
                                margin: '0',
                                width: 'auto',
                                height: 'auto',
                                minWidth: '24px',
                                lineHeight: '1',
                                outline: 'none',
                                WebkitTapHighlightColor: 'transparent',
                                opacity: item.quantity <= 1 ? 0.5 : 1
                              }}
                              disabled={item.quantity <= 1}
                            >
                              −
                            </button>
                            <span
                              style={{
                                color: 'white',
                                fontSize: '18px',
                                fontWeight: '600',
                                minWidth: '24px',
                                textAlign: 'center',
                                lineHeight: '1'
                              }}
                            >
                              {item.quantity}
                            </span>
                            <button
                              onClick={(e) => {
                                e.stopPropagation();
                                incrementItem(item.id);
                              }}
                              style={{
                                background: 'none',
                                border: 'none',
                                color: 'white',
                                fontSize: '24px',
                                fontWeight: 'normal',
                                cursor: 'pointer',
                                padding: '0',
                                margin: '0',
                                width: 'auto',
                                height: 'auto',
                                minWidth: '24px',
                                lineHeight: '1',
                                outline: 'none',
                                WebkitTapHighlightColor: 'transparent',
                                opacity: 1
                              }}
                            >
                              +
                            </button>
                          </HStack>

                          <button
                            onClick={(e) => {
                              e.stopPropagation();
                              removeItem(item.id);
                            }}
                            style={{
                              background: 'none',
                              border: 'none',
                              color: '#f87171',
                              fontSize: '12px',
                              cursor: 'pointer',
                              padding: '4px 0',
                              textAlign: 'center',
                              outline: 'none',
                              WebkitTapHighlightColor: 'transparent',
                            }}
                          >
                            Remove
                          </button>
                        </VStack>
                      </Box>
                    ))}
                  </SimpleGrid>
                </Box>
              </Collapse>
            </Box>
          </>
        )}

        {/* CARD 1: Service Selection - Simplified Tabs */}
        <Card
          bg="rgba(26, 26, 26, 0.6)"
          border="1px solid"
          borderColor="rgba(59, 130, 246, 0.2)"
          borderRadius="2xl"
          backdropFilter="blur(10px)"
        >
          <CardBody p={{ base: 6, md: 8 }}>
            <VStack spacing={6} align="stretch">
              <Text fontSize="lg" fontWeight="600" color="white">
                Choose Your Service
              </Text>

              {/* iPhone 14/15/16/17 Layout: Economy full width, then Standard + Express side by side */}
              {isIPhoneLayout && (
              <Box>
                <Box
                  p={{ base: 4 }}
                  borderRadius="xl"
                  border="2px solid"
                  borderColor={selectedService === 'economy' ? 'blue.500' : 'rgba(59, 130, 246, 0.2)'}
                  bg={selectedService === 'economy' ? 'rgba(59, 130, 246, 0.1)' : 'transparent'}
                  cursor="pointer"
                  onClick={() => handleServiceChange('economy')}
                  transition="all 0.2s"
                  _hover={{
                    borderColor: 'blue.500',
                    bg: 'rgba(59, 130, 246, 0.05)',
                  }}
                  position="relative"
                  mb={3}
                >
                  <Badge
                    position="absolute"
                    top={-1}
                    left={-1}
                    bg="green.500"
                    color="white"
                    fontSize="3xs"
                    px={1.5}
                    py={0.5}
                    borderRadius="full"
                  >
                    Save 15%
                  </Badge>
                  <VStack spacing={2} align="center" w="full">
                    <Text fontSize="3xl">💰</Text>
                    <Box textAlign="center" w="full">
                      <Text fontSize="sm" fontWeight="bold" color="white">
                        Economy
                      </Text>
                      <Text fontSize="2xs" color="gray.400" noOfLines={2} lineHeight="1.3">
                        Next available slot (3-7 days)
                      </Text>
                    </Box>
                    <Text fontSize="xl" fontWeight="bold" color="white">
                      £{safeEconomyPrice.toFixed(2)}
                    </Text>
                  </VStack>
                </Box>

                {/* Standard and Express Side by Side */}
                <Box display="grid" gridTemplateColumns="1fr 1fr" gap={3}>
                  <Box
                    p={{ base: 4 }}
                    borderRadius="xl"
                    border="2px solid"
                    borderColor={selectedService === 'standard' ? 'blue.500' : 'rgba(59, 130, 246, 0.2)'}
                    bg={selectedService === 'standard' ? 'rgba(59, 130, 246, 0.1)' : 'transparent'}
                    cursor="pointer"
                    onClick={() => handleServiceChange('standard')}
                    transition="all 0.2s"
                    _hover={{
                      borderColor: 'blue.500',
                      bg: 'rgba(59, 130, 246, 0.05)',
                    }}
                    position="relative"
                  >
                    <Badge
                      position="absolute"
                      top={-1}
                      right={-1}
                      bg="blue.500"
                      color="white"
                      fontSize="3xs"
                      px={1.5}
                      py={0.5}
                      borderRadius="full"
                    >
                      Popular
                    </Badge>
                    <VStack spacing={2} align="center" w="full">
                      <Text fontSize="3xl">🚚</Text>
                      <Box textAlign="center" w="full">
                        <Text fontSize="sm" fontWeight="bold" color="white">
                          Standard
                        </Text>
                        <Text fontSize="2xs" color="gray.400" noOfLines={2} lineHeight="1.3">
                          Choose your date
                        </Text>
                      </Box>
                      <Text fontSize="xl" fontWeight="bold" color="white">
                        £{safeStandardPrice.toFixed(2)}
                      </Text>
                    </VStack>
                  </Box>

                  <Box
                    p={{ base: 4 }}
                    borderRadius="xl"
                    border="2px solid"
                    borderColor={selectedService === 'express' ? 'blue.500' : 'rgba(59, 130, 246, 0.2)'}
                    bg={selectedService === 'express' ? 'rgba(59, 130, 246, 0.1)' : 'transparent'}
                    cursor="pointer"
                    onClick={() => handleServiceChange('express')}
                    transition="all 0.2s"
                    _hover={{
                      borderColor: 'blue.500',
                      bg: 'rgba(59, 130, 246, 0.05)',
                    }}
                    position="relative"
                  >
                    <Badge
                      position="absolute"
                      top={-1}
                      left={-1}
                      bg="orange.500"
                      color="white"
                      fontSize="3xs"
                      px={1.5}
                      py={0.5}
                      borderRadius="full"
                    >
                      50% premium
                    </Badge>
                    <VStack spacing={2} align="center" w="full">
                      <Text fontSize="3xl">⚡</Text>
                      <Box textAlign="center" w="full">
                        <Text fontSize="sm" fontWeight="bold" color="white">
                          Express
                        </Text>
                        <Text fontSize="2xs" color="gray.400" noOfLines={2} lineHeight="1.3">
                          Same-day or next-day delivery
                        </Text>
                      </Box>
                      <Text fontSize="xl" fontWeight="bold" color="white">
                        £{safeExpressPrice.toFixed(2)}
                      </Text>
                    </VStack>
                  </Box>
                </Box>
              </Box>
              )}

              {/* Normal Grid Layout: All devices except iPhone 14/15/16/17 */}
              {!isIPhoneLayout && (
              <Box
                display="grid"
                gridTemplateColumns="repeat(3, 1fr)"
                gap={{ base: 2, sm: 3, md: 4 }}
                w="full"
              >
                {services.map((service) => (
                  <Box
                    key={service.id}
                    p={{ base: 3, sm: 4, md: 5 }}
                    borderRadius="xl"
                    border="2px solid"
                    borderColor={selectedService === service.id ? 'blue.500' : 'rgba(59, 130, 246, 0.2)'}
                    bg={selectedService === service.id ? 'rgba(59, 130, 246, 0.1)' : 'transparent'}
                    cursor="pointer"
                    onClick={() => handleServiceChange(service.id)}
                    transition="all 0.2s"
                    _hover={{
                      borderColor: 'blue.500',
                      bg: 'rgba(59, 130, 246, 0.05)',
                    }}
                    position="relative"
                    minH={{ base: "160px", sm: "180px", md: "auto" }}
                  >
                    {service.popular && (
                      <Badge
                        position="absolute"
                        top={{ base: -1, md: -2 }}
                        right={{ base: -1, md: -2 }}
                        bg="blue.500"
                        color="white"
                        fontSize="3xs"
                        px={{ base: 1.5, md: 2 }}
                        py={{ base: 0.5, md: 1 }}
                        borderRadius="full"
                      >
                        Popular
                      </Badge>
                    )}
                    {service.discount && (
                      <Badge
                        position="absolute"
                        top={{ base: -1, md: -2 }}
                        left={{ base: -1, md: -2 }}
                        bg="green.500"
                        color="white"
                        fontSize="3xs"
                        px={{ base: 1.5, md: 2 }}
                        py={{ base: 0.5, md: 1 }}
                        borderRadius="full"
                      >
                        {service.discount}
                      </Badge>
                    )}
                    {service.premium && (
                      <Badge
                        position="absolute"
                        top={{ base: -1, md: -2 }}
                        left={{ base: -1, md: -2 }}
                        bg="orange.500"
                        color="white"
                        fontSize="3xs"
                        px={{ base: 1.5, md: 2 }}
                        py={{ base: 0.5, md: 1 }}
                        borderRadius="full"
                      >
                        {service.premium}
                      </Badge>
                    )}
                    <VStack spacing={{ base: 2, md: 3 }} align="center" w="full">
                      <Text fontSize={{ base: "3xl", md: "2xl" }}>{service.icon}</Text>
                      <Box textAlign="center" w="full">
                        <Text 
                          fontSize={{ base: "sm", md: "md" }} 
                          fontWeight="bold" 
                          color="white"
                          noOfLines={1}
                        >
                          {service.name}
                        </Text>
                        <Text 
                          fontSize={{ base: "2xs", sm: "xs" }} 
                          color="gray.400"
                          noOfLines={2}
                          lineHeight="1.3"
                        >
                          {service.description}
                        </Text>
                      </Box>
                      <Text 
                        fontSize={{ base: "xl", md: "2xl" }} 
                        fontWeight="bold" 
                        color="white"
                      >
                        £{service.price.toFixed(2)}
                      </Text>
                    </VStack>
                  </Box>
                ))}
              </Box>
              )}
            </VStack>
          </CardBody>
        </Card>

        {/* CARD 2: Customer Information - Single Clean Card */}
        <Card
          bg="rgba(26, 26, 26, 0.6)"
          border="1px solid"
          borderColor="rgba(59, 130, 246, 0.2)"
          borderRadius="2xl"
          backdropFilter="blur(10px)"
        >
          <CardBody p={{ base: 6, md: 8 }}>
            <VStack spacing={6} align="stretch">
              <Text fontSize="lg" fontWeight="600" color="white">
                Your Information
              </Text>

              <SimpleGrid columns={{ base: 1, md: 2 }} spacing={4}>
                <FormControl isInvalid={!!errors['step2.customerDetails.firstName']}>
                  <FormLabel color="white" fontSize="sm">First Name</FormLabel>
                  <Input
                    placeholder="John"
                    value={formData.step2.customerDetails.firstName || ''}
                    onChange={(e) => updateCustomerDetails('firstName', e.target.value)}
                    bg="rgba(0, 0, 0, 0.3)"
                    border="1px solid"
                    borderColor="rgba(59, 130, 246, 0.3)"
                    color="white"
                    size="lg"
                    _hover={{ borderColor: 'rgba(59, 130, 246, 0.5)' }}
                    _focus={{ borderColor: 'blue.500', boxShadow: '0 0 0 1px rgba(59, 130, 246, 0.3)' }}
                  />
                  {errors['step2.customerDetails.firstName'] && (
                    <FormErrorMessage>{errors['step2.customerDetails.firstName']}</FormErrorMessage>
                  )}
                </FormControl>

                <FormControl isInvalid={!!errors['step2.customerDetails.lastName']}>
                  <FormLabel color="white" fontSize="sm">Last Name</FormLabel>
                  <Input
                    placeholder="Doe"
                    value={formData.step2.customerDetails.lastName || ''}
                    onChange={(e) => updateCustomerDetails('lastName', e.target.value)}
                    bg="rgba(0, 0, 0, 0.3)"
                    border="1px solid"
                    borderColor="rgba(59, 130, 246, 0.3)"
                    color="white"
                    size="lg"
                    _hover={{ borderColor: 'rgba(59, 130, 246, 0.5)' }}
                    _focus={{ borderColor: 'blue.500', boxShadow: '0 0 0 1px rgba(59, 130, 246, 0.3)' }}
                  />
                  {errors['step2.customerDetails.lastName'] && (
                    <FormErrorMessage>{errors['step2.customerDetails.lastName']}</FormErrorMessage>
                  )}
                </FormControl>
              </SimpleGrid>

              <FormControl isInvalid={!!errors['step2.customerDetails.email']}>
                <FormLabel color="white" fontSize="sm">Email Address</FormLabel>
                <Input
                  type="email"
                  placeholder="john.doe@example.com"
                  value={formData.step2.customerDetails.email || ''}
                  onChange={(e) => updateCustomerDetails('email', e.target.value)}
                  bg="rgba(0, 0, 0, 0.3)"
                  border="1px solid"
                  borderColor="rgba(59, 130, 246, 0.3)"
                  color="white"
                  size="lg"
                  _hover={{ borderColor: 'rgba(59, 130, 246, 0.5)' }}
                  _focus={{ borderColor: 'blue.500', boxShadow: '0 0 0 1px rgba(59, 130, 246, 0.3)' }}
                />
                {errors['step2.customerDetails.email'] && (
                  <FormErrorMessage>{errors['step2.customerDetails.email']}</FormErrorMessage>
                )}
              </FormControl>

              <FormControl isInvalid={!!errors['step2.customerDetails.phone']}>
                <FormLabel color="white" fontSize="sm">Phone Number</FormLabel>
                <Input
                  type="tel"
                  placeholder="+44 1234 567890"
                  value={formData.step2.customerDetails.phone || ''}
                  onChange={(e) => updateCustomerDetails('phone', e.target.value)}
                  bg="rgba(0, 0, 0, 0.3)"
                  border="1px solid"
                  borderColor="rgba(59, 130, 246, 0.3)"
                  color="white"
                  size="lg"
                  _hover={{ borderColor: 'rgba(59, 130, 246, 0.5)' }}
                  _focus={{ borderColor: 'blue.500', boxShadow: '0 0 0 1px rgba(59, 130, 246, 0.3)' }}
                />
                {errors['step2.customerDetails.phone'] && (
                  <FormErrorMessage>{errors['step2.customerDetails.phone']}</FormErrorMessage>
                )}
              </FormControl>

              <FormControl>
                <FormLabel color="white" fontSize="sm">Company Name (Optional)</FormLabel>
                <Input
                  placeholder="Your Company Ltd"
                  value={formData.step2.customerDetails.company || ''}
                  onChange={(e) => updateCustomerDetails('company', e.target.value)}
                  bg="rgba(0, 0, 0, 0.3)"
                  border="1px solid"
                  borderColor="rgba(59, 130, 246, 0.3)"
                  color="white"
                  size="lg"
                  _hover={{ borderColor: 'rgba(59, 130, 246, 0.5)' }}
                  _focus={{ borderColor: 'blue.500', boxShadow: '0 0 0 1px rgba(59, 130, 246, 0.3)' }}
                />
              </FormControl>

              <FormControl>
                <FormLabel color="white" fontSize="sm">Special Instructions (Optional)</FormLabel>
                <Textarea
                  placeholder="Any special instructions or requests for your move..."
                  value={formData.step2.specialInstructions || ''}
                  onChange={(e) => updateFormData('step2', { specialInstructions: e.target.value })}
                  bg="rgba(0, 0, 0, 0.3)"
                  border="1px solid"
                  borderColor="rgba(59, 130, 246, 0.3)"
                  color="white"
                  rows={3}
                  _hover={{ borderColor: 'rgba(59, 130, 246, 0.5)' }}
                  _focus={{ borderColor: 'blue.500', boxShadow: '0 0 0 1px rgba(59, 130, 246, 0.3)' }}
                />
              </FormControl>
            </VStack>
          </CardBody>
        </Card>

        {/* CARD 3: Payment & Confirmation - Final Step */}
        <Card
          bg="rgba(26, 26, 26, 0.6)"
          border="1px solid"
          borderColor="rgba(59, 130, 246, 0.2)"
          borderRadius="2xl"
          backdropFilter="blur(10px)"
        >
          <CardBody p={{ base: 6, md: 8 }}>
            <VStack spacing={6} align="stretch">
              <HStack justify="space-between" align="center">
                <Text fontSize="lg" fontWeight="600" color="white">
                  Complete Your Booking
                </Text>
                <Badge 
                  bg="green.500" 
                  color="white" 
                  px={4} 
                  py={2} 
                  borderRadius="full"
                  fontSize="xl"
                  fontWeight="bold"
                >
                  £{actualPrice.toFixed(2)}
                </Badge>
              </HStack>

              <Divider borderColor="rgba(59, 130, 246, 0.2)" />

              {/* Booking Summary */}
              <VStack spacing={3} align="stretch">
                <HStack justify="space-between">
                  <Text color="gray.400" fontSize="sm">Pickup</Text>
                  <Text color="white" fontSize="sm" fontWeight="500">
                    {formData.step1.pickupAddress?.city || 'Not set'}
                  </Text>
                </HStack>
                <HStack justify="space-between">
                  <Text color="gray.400" fontSize="sm">Dropoff</Text>
                  <Text color="white" fontSize="sm" fontWeight="500">
                    {formData.step1.dropoffAddress?.city || 'Not set'}
                  </Text>
                </HStack>
                <HStack justify="space-between">
                  <Text color="gray.400" fontSize="sm">Items</Text>
                  <Text color="white" fontSize="sm" fontWeight="500">
                    {formData.step1.items.length} items
                  </Text>
                </HStack>
                <HStack justify="space-between">
                  <Text color="gray.400" fontSize="sm">Service</Text>
                  <Text color="white" fontSize="sm" fontWeight="500" textTransform="capitalize">
                    {selectedService}
                  </Text>
                </HStack>
              </VStack>

              <Divider borderColor="rgba(59, 130, 246, 0.2)" />

              {/* Terms & Conditions */}
              <VStack spacing={3} align="start">
                <Checkbox
                  isChecked={acceptedTerms}
                  onChange={(e) => {
                    const isMobile = window.innerWidth < 768;
                    const scrollY = isMobile ? window.scrollY : undefined;
                    setAcceptedTerms(e.target.checked);
                    if (isMobile && scrollY !== undefined) {
                      requestAnimationFrame(() => {
                        window.scrollTo(0, scrollY);
                      });
                    }
                  }}
                  colorScheme="blue"
                  color="gray.300"
                  fontSize="sm"
                >
                  I accept the{' '}
                  <Text 
                    as="span" 
                    color="blue.400" 
                    textDecoration="underline" 
                    cursor="pointer"
                    onClick={(e) => {
                      e.preventDefault();
                      e.stopPropagation();
                      window.open('/terms', '_blank');
                    }}
                  >
                    Terms and Conditions
                  </Text>
                </Checkbox>

                <Checkbox
                  isChecked={acceptedPrivacy}
                  onChange={(e) => {
                    const isMobile = window.innerWidth < 768;
                    const scrollY = isMobile ? window.scrollY : undefined;
                    setAcceptedPrivacy(e.target.checked);
                    if (isMobile && scrollY !== undefined) {
                      requestAnimationFrame(() => {
                        window.scrollTo(0, scrollY);
                      });
                    }
                  }}
                  colorScheme="blue"
                  color="gray.300"
                  fontSize="sm"
                >
                  I have read the{' '}
                  <Text 
                    as="span" 
                    color="blue.400" 
                    textDecoration="underline" 
                    cursor="pointer"
                    onClick={(e) => {
                      e.preventDefault();
                      e.stopPropagation();
                      window.open('/privacy', '_blank');
                    }}
                  >
                    Privacy Policy
                  </Text>
                </Checkbox>
              </VStack>

              {/* Stripe Payment Button - Use actual component */}
              <StripePaymentButton
                bookingData={{
                  customer: {
                    name: `${formData.step2.customerDetails.firstName} ${formData.step2.customerDetails.lastName}`,
                    email: formData.step2.customerDetails.email,
                    phone: formData.step2.customerDetails.phone,
                  },
                  pickupAddress: formData.step1.pickupAddress as any,
                  dropoffAddress: formData.step1.dropoffAddress as any,
                  items: formData.step1.items,
                  pricing: formData.step1.pricing as any,
                  serviceType: selectedService,
                  scheduledDate: formData.step1.pickupDate || new Date().toISOString().split('T')[0],
                  scheduledTime: formData.step1.pickupTimeSlot,
                  pickupDetails: formData.step1.pickupProperty as any,
                  dropoffDetails: formData.step1.dropoffProperty as any,
                  notes: formData.step2.specialInstructions,
                }}
                amount={actualPrice}
                disabled={
                  !formData.step2.customerDetails.firstName ||
                  !formData.step2.customerDetails.lastName ||
                  !formData.step2.customerDetails.email ||
                  !formData.step2.customerDetails.phone
                }
                onSuccess={(sessionId) => {
                  console.log('✅ Payment successful:', sessionId);
                  window.location.href = `/booking-luxury/success?session_id=${sessionId}`;
                }}
                onError={(error) => {
                  console.error('❌ Payment error:', error);
                  toast({
                    title: 'Payment Failed',
                    description: error,
                    status: 'error',
                    duration: 5000,
                  });
                }}
              />

              {/* Security Badge */}
              <HStack justify="center" spacing={2} color="gray.400" fontSize="xs">
                <Icon as={FaCreditCard} />
                <Text>Secure payment processed by Stripe</Text>
              </HStack>
            </VStack>
          </CardBody>
        </Card>
      </VStack>
    </Box>
  );
}

'use client';

import { useState, useCallback } from 'react';
import { z } from 'zod';
// import {
//   addressSchema,
//   customerSchema,
//   propertyDetailsSchema,
//   bookingItemSchema,
// } from '@/lib/schemas/booking-schemas';

// Use shared property details schema (imported above)
// Local property details schema for frontend compatibility
const frontendPropertyDetailsSchema = z.object({
  type: z.enum(['house', 'apartment', 'office', 'warehouse', 'other']).default('house'),
  floors: z.number().int().min(0).max(50).optional().default(0),
  hasLift: z.boolean().optional().default(false),
  hasParking: z.boolean().optional().default(true),
  accessNotes: z.string().max(1000).optional(),
  requiresPermit: z.boolean().optional().default(false),
  flatNumber: z.string().max(50).optional(),
});

// Item schema
const itemSchema = z.object({
  id: z.string(),
  name: z.string(),
  description: z.string(),
  category: z.string(),
  size: z.enum(['small', 'medium', 'large']),
  quantity: z.number().min(1, 'Quantity must be at least 1'),
  unitPrice: z.number().min(0),
  totalPrice: z.number().min(0),
  weight: z.number().min(0),
  volume: z.number().min(0),
  image: z.string().optional(),
  workers_required: z.number().optional(),
  dismantling_required: z.string().optional(),
  fragility_level: z.string().optional(),
  dismantling_time_minutes: z.number().optional(),
  reassembly_time_minutes: z.number().optional(),
  special_handling_notes: z.string().optional(),
});

// Service type schema - Luxury service levels
const serviceTypeSchema = z.enum(['signature', 'premium', 'white-glove', 'standard'] as const);

// Customer details schema
const customerDetailsSchema = z.object({
  firstName: z.string()
    .min(1, 'First name is required')
    .max(50, 'First name too long')
    .regex(/^[a-zA-Z\s\-']+$/, 'First name can only contain letters, spaces, hyphens and apostrophes')
    .transform(s => s.trim()),
  lastName: z.string()
    .min(1, 'Last name is required')
    .max(50, 'Last name too long')
    .regex(/^[a-zA-Z\s\-']+$/, 'Last name can only contain letters, spaces, hyphens and apostrophes')
    .transform(s => s.trim()),
  email: z.string()
    .min(1, 'Email is required')
    .email('Invalid email address')
    .transform(s => s.toLowerCase().trim()),
  phone: z.string()
    .min(1, 'Phone number is required')
    .regex(/^(?:(?:\+44)|(?:0))(?:\d\s?){9,10}$/, 'Please enter a valid UK phone number')
    .transform(s => s.replace(/\s+/g, '').replace(/^0/, '+44')),
  company: z.string()
    .max(100, 'Company name too long')
    .optional()
    .transform(s => s ? s.trim() : s),
});

// Payment method schema - Stripe only
const paymentMethodSchema = z.object({
  type: z.enum(['stripe']).default('stripe'),
  stripeDetails: z.object({
    paymentIntentId: z.string().optional(),
    sessionId: z.string().optional(),
  }).optional(),
});

// Pricing breakdown schema
const pricingBreakdownSchema = z.object({
  baseFee: z.number().min(0),
  distanceFee: z.number().min(0),
  volumeFee: z.number().min(0),
  serviceFee: z.number().min(0),
  urgencyFee: z.number().min(0).default(0),
  vat: z.number().min(0),
  total: z.number().min(0),
  distance: z.number().min(0), // Distance in kilometers
});

// CompleteAddress-compatible schema to match UKAddressAutocomplete
const frontendAddressSchema = z.object({
  // Legacy fields for backward compatibility
  address: z.string().optional(),
  formatted_address: z.string().optional(),
  place_name: z.string().optional(),
  houseNumber: z.string().optional(),
  flatNumber: z.string().optional(),
  
  // CompleteAddress fields from UKAddressAutocomplete
  full: z.string().optional(),
  line1: z.string().optional(),
  line2: z.string().optional(),
  city: z.string().optional(),
  postcode: z.string().optional(),
  country: z.string().optional(),
  
  coordinates: z.object({
    lat: z.number().min(-90).max(90).optional(),
    lng: z.number().min(-180).max(180).optional(),
  }).optional(),
  
  // CompleteAddress nested formatted object
  formatted: z.object({
    street: z.string().optional(),
    houseNumber: z.string().optional(),
    flatNumber: z.string().optional(),
    floor: z.string().optional(),
    businessName: z.string().optional(),
  }).optional(),
  
  // Additional metadata
  isPostcodeValidated: z.boolean().optional(),
  stepCompletedAt: z.string().optional(),
  buildingDetails: z.object({
    type: z.string().optional(),
    hasElevator: z.boolean().optional(),
    floorNumber: z.string().optional(),
    apartmentNumber: z.string().optional(),
    flatNumber: z.string().optional(),
  }).optional(),
});

const step1Schema = z.object({
  pickupAddress: frontendAddressSchema,
  dropoffAddress: frontendAddressSchema,
  pickupProperty: frontendPropertyDetailsSchema,
  dropoffProperty: frontendPropertyDetailsSchema,
  items: z.array(itemSchema).min(1, 'Please select at least one item'),
  serviceType: serviceTypeSchema,
  pickupDate: z.string()
    .min(1, 'Please select a pickup date')
    .refine((date) => {
      const selectedDate = new Date(date);
      const today = new Date();
      today.setHours(0, 0, 0, 0);
      return !isNaN(selectedDate.getTime()) && selectedDate >= today;
    }, 'Please select a valid future date'),
  pickupTimeSlot: z.string().optional(),
  urgency: z.enum(['same-day', 'next-day', 'scheduled'])
    .default('scheduled'),
  distance: z.number().min(0),
  estimatedDuration: z.number().min(0),
  pricing: pricingBreakdownSchema,
});

const step2Schema = z.object({
  customerDetails: customerDetailsSchema,
  paymentMethod: paymentMethodSchema,
  termsAccepted: z.boolean().refine(val => val === true, 'You must accept the terms and conditions'),
  privacyAccepted: z.boolean().refine(val => val === true, 'You must accept the privacy policy'),
  marketingOptIn: z.boolean().optional(),
  specialInstructions: z.string().optional(),
  bookingId: z.string().optional(),
  promotionCode: z.string().optional(),
  promotionDetails: z.object({
    id: z.string().optional(),
    code: z.string().optional(),
    name: z.string().optional(),
    description: z.string().optional(),
    type: z.enum(['percentage', 'fixed']).optional(),
    value: z.number().optional(),
    discountAmount: z.number().optional(),
    originalAmount: z.number().optional(),
    finalAmount: z.number().optional(),
  }).optional(),
});

// Complete form schema (2 steps unified)
const formSchema = z.object({
  step1: step1Schema,
  step2: step2Schema,
});

export type Address = z.infer<typeof frontendAddressSchema>;
export type PropertyDetails = z.infer<typeof frontendPropertyDetailsSchema>;
export type Item = z.infer<typeof itemSchema>;
export type ServiceType = z.infer<typeof serviceTypeSchema>;
export type CustomerDetails = z.infer<typeof customerDetailsSchema>;
export type PaymentMethod = z.infer<typeof paymentMethodSchema>;
export type PricingBreakdown = z.infer<typeof pricingBreakdownSchema>;
export type FormData = z.infer<typeof formSchema>;

const initialFormData: FormData = {
  step1: {
    pickupAddress: {
      address: '',
