      type: 'house',
      floors: 0,
      hasLift: false,
      hasParking: false,
      requiresPermit: false,
      accessNotes: '',
    },
    items: [],
    serviceType: 'standard',
    pickupDate: '',
    pickupTimeSlot: undefined,
    urgency: 'scheduled',
    distance: 0,
