      }
    }
    if (!street) street = 'Main Street'; // Final fallback
    
    // Extract city
    const city = 
      addr.city || 
      components.city || 
      components.locality || 
      components.post_town || 
      'London';
    
    // Extract postcode
    const postcode = 
      addr.postcode || 
