        // Prevent scroll jump on re-render
        scrollBehavior: 'auto',
        overflowAnchor: 'none',
      }}
    >
      <Container 
        maxW={{ base: "full", md: "6xl" }} 
        px={{ base: 2, md: 6 }}
        pt={{ base: 2, md: 0 }}
      >
