                paddingTop: '0.5rem',
              },
            }}
          >
            <VStack spacing={4} w="full" data-booking-header>
              {/* Top Row: Brand Logo & Call Button */}
              <Flex 
                justify="space-between" 
                align="center" 
                px={{ base: 3, md: 6 }}
                w="full"
              >
                {/* Left: Brand */}
