                      cursor={step.id <= currentStep ? 'pointer' : 'default'}
                      onClick={() => step.id <= currentStep && handleStepClick(step.id)}
                      transition="all 0.3s cubic-bezier(0.4, 0, 0.2, 1)"
                      border="3px solid"
                      borderColor={
                        step.id === currentStep 
                          ? `${step.color}.400`
                          : step.id < currentStep 
                          ? 'green.400'
