export default function ContactPage() {
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    service: '',
    message: ''
  });
  const [isSubmitting, setIsSubmitting] = useState(false);
  
  const bgColor = '#0D0D0D';
  const cardBg = 'rgba(26, 26, 26, 0.95)';
  const toast = useToast();

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);

    try {
      // Simulate form submission
      await new Promise(resolve => setTimeout(resolve, 2000));
      
      // Track Google Ads conversion for lead form submission
      if (typeof window !== 'undefined' && (window as any).gtag) {
        try {
          (window as any).gtag('event', 'conversion', {
            'send_to': 'AW-17715630822/Submit_lead_form_Website',
            'value': 1.0,
            'currency': 'GBP'
          });
          console.log('✅ Google Ads conversion tracked: Contact form submission');
        } catch (gtagError) {
          console.error('❌ Google Ads conversion tracking failed:', gtagError);
        }
      }
      
      toast({
        title: 'Message Sent!',
        description: 'We\'ll get back to you within 2 hours.',
        status: 'success',
        duration: 5000,
        isClosable: true,
      });
      
      setFormData({
        name: '',
        email: '',
        phone: '',
        service: '',
        message: ''
      });
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to send message. Please try again.',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <Box bg={bgColor} minH="100vh" pt={20}>
      <Container maxW="container.xl" py={16}>
        <VStack spacing={16}>
          {/* Hero Section */}
          <MotionBox
            initial={{ opacity: 0, y: 30 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            transition="0.6s ease-out"
            textAlign="center"
            maxW="4xl"
          >
            <HStack justify="center" mb={6}>
              <Box
                p={4}
                bg="rgba(59, 130, 246, 0.2)"
                color="blue.400"
                borderRadius="xl"
                border="1px solid"
                borderColor="rgba(59, 130, 246, 0.3)"
              >
                <Icon as={FiMessageCircle} boxSize={12} />
              </Box>
            </HStack>
            <Heading
              size="2xl"
              mb={6}
              bgGradient="linear(to-r, blue.400, blue.600)"
              bgClip="text"
            >
              Get in Touch
            </Heading>
            <Text fontSize="xl" color="text.secondary" lineHeight="tall">
              Have questions about our moving services? Need a quote? We're here to help! 
              Contact us through any of the methods below and we'll get back to you promptly.
            </Text>
          </MotionBox>

          {/* Contact Methods */}
          <SimpleGrid columns={{ base: 1, md: 2, lg: 4 }} spacing={6} w="full">
            {contactMethods.map((method, index) => (
              <Card
                as={motion.div}
                key={index}
                initial={{ opacity: 0, y: 20 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true }}
                transition={`0.5s ease-out ${index * 0.1}s`}
                bg={cardBg}
                borderRadius="xl"
                boxShadow="lg"
                _hover={{
                  transform: 'translateY(-4px)',
                  boxShadow: 'xl',
                }}
                cursor="pointer"
                onClick={method.action}
              >
                <CardBody p={6} textAlign="center">
                  <VStack spacing={4}>
                    <Box
                      p={3}
                      bg={`rgba(59, 130, 246, 0.2)`}
                      color={`${method.color}.400`}
                      borderRadius="lg"
                      border="1px solid"
                      borderColor={`rgba(59, 130, 246, 0.3)`}
                    >
                      <Icon as={method.icon} boxSize={6} />
                    </Box>
                    <Heading size="md" color="text.primary">
                      {method.title}
                    </Heading>
                    <Text fontSize="sm" color="text.secondary" textAlign="center">
                      {method.description}
                    </Text>
                    <VStack spacing={2}>
                      <Text fontSize="lg" fontWeight="bold" color={`${method.color}.500`}>
                        {method.contact}
                      </Text>
                      <Text fontSize="xs" color="text.secondary">
                        {method.availability}
                      </Text>
                    </VStack>
                  </VStack>
                </CardBody>
              </Card>
            ))}
          </SimpleGrid>

          {/* Contact Form and Info */}
          <SimpleGrid columns={{ base: 1, lg: 2 }} spacing={12} w="full">
            {/* Contact Form */}
            <Card
              as={motion.div}
              initial={{ opacity: 0, x: -30 }}
