                whileInView={{ opacity: 1, x: 0 }}
                viewport={{ once: true }}
                transition="0.6s ease-out 0.6s"
                bg={cardBg}
                borderRadius="xl"
                boxShadow="xl"
              >
                <CardBody p={8}>
                  <VStack spacing={6} align="start">
                    <HStack spacing={4}>
                      <Box
                        p={3}
                        bg="rgba(251, 191, 36, 0.2)"
