  Center,
} from '@chakra-ui/react';

interface UserProfile {
  id: string;
  name: string;
  email: string;
  phone: string;
  role: string;
}

export default function ProfilePage() {
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [name, setName] = useState('');
  const [phone, setPhone] = useState('');
  const toast = useToast();

  useEffect(() => {
    fetchProfile();
  }, []);

  async function fetchProfile() {
    try {
      const res = await fetch('/api/customer/me');
      if (!res.ok) throw new Error('Failed to fetch profile');
      const data = await res.json();
      setProfile(data.user);
      setName(data.user.name || '');
      setPhone(data.user.phone || '');
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to load profile',
        status: 'error',
        duration: 3000,
      });
    } finally {
      setIsLoading(false);
    }
  }

  async function handleSave() {
    setIsSaving(true);
    try {
      const res = await fetch('/api/customer/settings/profile', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name, phone }),
      });

      if (!res.ok) throw new Error('Failed to update profile');

      toast({
        title: 'Success',
        description: 'Profile updated successfully',
        status: 'success',
        duration: 3000,
      });

      await fetchProfile();
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to update profile',
        status: 'error',
        duration: 3000,
      });
    } finally {
      setIsSaving(false);
    }
  }

  if (isLoading) {
    return (
      <Center h="400px">
        <Spinner size="xl" color="brand.500" />
      </Center>
    );
  }

  if (!profile) {
    return (
      <Container maxW="container.md" py={8}>
        <Text>Failed to load profile</Text>
      </Container>
    );
  }

  return (
    <Container maxW="container.md" py={8}>
      <VStack align="stretch" spacing={6}>
        <Heading size="lg">Profile</Heading>

        <Card>
          <CardBody>
            <VStack align="stretch" spacing={6}>
              <HStack spacing={6}>
                <Avatar size="xl" name={profile.name} />
                <VStack align="start" spacing={1}>
                  <Heading size="md">{profile.name}</Heading>
                  <Text color="gray.600">{profile.email}</Text>
                </VStack>
              </HStack>

              <Divider />

              <FormControl>
                <FormLabel>Name</FormLabel>
                <Input
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  placeholder="Enter your name"
                />
              </FormControl>

              <FormControl>
                <FormLabel>Phone Number</FormLabel>
                <Input
                  value={phone}
                  onChange={(e) => setPhone(e.target.value)}
                  placeholder="Enter your phone number"
                  dir="ltr"
                />
              </FormControl>

              <FormControl>
                <FormLabel>Email</FormLabel>
                <Input value={profile.email} isReadOnly bg="gray.50" />
                <Text fontSize="sm" color="gray.500" mt={1}>
                  Email cannot be changed
                </Text>
              </FormControl>

              <Button
                colorScheme="brand"
                onClick={handleSave}
                isLoading={isSaving}
                loadingText="Saving..."
              >
                Save Changes
              </Button>
            </VStack>
          </CardBody>
        </Card>
      </VStack>
    </Container>
  );
}

'use client';

import { useState } from 'react';
import {
  Box,
  Container,
  Heading,
  Text,
  VStack,
  HStack,
  Button,
  Card,
  CardBody,
  FormControl,
  FormLabel,
  Input,
  Switch,
  useToast,
  Divider,
  Tabs,
  TabList,
  TabPanels,
  Tab,
  TabPanel,
} from '@chakra-ui/react';

export default function SettingsPage() {
  const [currentPassword, setCurrentPassword] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [isChangingPassword, setIsChangingPassword] = useState(false);
  const [emailNotifications, setEmailNotifications] = useState(true);
  const [smsNotifications, setSmsNotifications] = useState(true);
  const toast = useToast();

  async function handlePasswordChange() {
    if (newPassword !== confirmPassword) {
      toast({
        title: 'Error',
        description: 'Passwords do not match',
        status: 'error',
        duration: 3000,
      });
      return;
    }

    if (newPassword.length < 6) {
      toast({
        title: 'Error',
        description: 'Password must be at least 6 characters',
        status: 'error',
        duration: 3000,
      });
      return;
    }

    setIsChangingPassword(true);
    try {
      const res = await fetch('/api/customer/settings/password', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          currentPassword,
          newPassword,
        }),
      });

      if (!res.ok) {
        const data = await res.json();
        throw new Error(data.error || 'Failed to change password');
      }

      toast({
        title: 'Success',
        description: 'Password changed successfully',
        status: 'success',
        duration: 3000,
      });

      setCurrentPassword('');
      setNewPassword('');
      setConfirmPassword('');
    } catch (error: any) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to change password',
        status: 'error',
        duration: 3000,
      });
    } finally {
      setIsChangingPassword(false);
    }
  }

  async function handleNotificationUpdate() {
    try {
      const res = await fetch('/api/customer/settings/notifications', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          email: emailNotifications,
          sms: smsNotifications,
        }),
      });

      if (!res.ok) throw new Error('Failed to update notifications');

      toast({
        title: 'Success',
        description: 'Notification settings updated',
        status: 'success',
        duration: 3000,
      });
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to update notification settings',
        status: 'error',
        duration: 3000,
      });
    }
  }

  return (
    <Container maxW="container.md" py={8}>
      <VStack align="stretch" spacing={6}>
        <Heading size="lg">Settings</Heading>

        <Tabs colorScheme="brand">
          <TabList>
            <Tab>Security</Tab>
            <Tab>Notifications</Tab>
          </TabList>

          <TabPanels>
            {/* Security Tab */}
            <TabPanel px={0}>
              <Card>
                <CardBody>
                  <VStack align="stretch" spacing={6}>
                    <Heading size="md">Change Password</Heading>

                    <FormControl>
                      <FormLabel>Current Password</FormLabel>
                      <Input
                        type="password"
                        value={currentPassword}
                        onChange={(e) => setCurrentPassword(e.target.value)}
                        placeholder="Enter current password"
                      />
                    </FormControl>

                    <FormControl>
                      <FormLabel>New Password</FormLabel>
                      <Input
                        type="password"
                        value={newPassword}
                        onChange={(e) => setNewPassword(e.target.value)}
                        placeholder="Enter new password"
                      />
                    </FormControl>

                    <FormControl>
                      <FormLabel>Confirm New Password</FormLabel>
                      <Input
                        type="password"
                        value={confirmPassword}
                        onChange={(e) => setConfirmPassword(e.target.value)}
                        placeholder="Re-enter new password"
                      />
                    </FormControl>

                    <Button
                      colorScheme="brand"
                      onClick={handlePasswordChange}
                      isLoading={isChangingPassword}
                      loadingText="Changing..."
                    >
                      Change Password
                    </Button>
                  </VStack>
                </CardBody>
              </Card>
            </TabPanel>

            {/* Notifications Tab */}
            <TabPanel px={0}>
              <Card>
                <CardBody>
                  <VStack align="stretch" spacing={6}>
                    <Heading size="md">Notification Settings</Heading>

                    <FormControl display="flex" alignItems="center">
                      <FormLabel mb={0} flex={1}>
                        Email Notifications
                      </FormLabel>
                      <Switch
                        colorScheme="brand"
                        isChecked={emailNotifications}
                        onChange={(e) => setEmailNotifications(e.target.checked)}
                      />
                    </FormControl>

                    <Divider />

                    <FormControl display="flex" alignItems="center">
                      <FormLabel mb={0} flex={1}>
                        SMS Notifications
                      </FormLabel>
                      <Switch
                        colorScheme="brand"
                        isChecked={smsNotifications}
                        onChange={(e) => setSmsNotifications(e.target.checked)}
                      />
                    </FormControl>

                    <Button colorScheme="brand" onClick={handleNotificationUpdate}>
                      Save Settings
                    </Button>
                  </VStack>
                </CardBody>
              </Card>
            </TabPanel>
          </TabPanels>
        </Tabs>
      </VStack>
    </Container>
  );
}

