    password: '',
    confirmPassword: '',
    phone: '',
    dateOfBirth: '',
    nationalInsuranceNumber: '',
    addressLine1: '',
    addressLine2: '',
    city: '',
    postcode: '',
    county: '',
    drivingLicenseNumber: '',
    drivingLicenseExpiry: '',
    drivingLicenseFront: null,
    drivingLicenseBack: null,
    insuranceProvider: '',
    insurancePolicyNumber: '',
    insuranceExpiry: '',
    insuranceDocument: null,
    bankName: '',
    accountHolderName: '',
    sortCode: '',
    accountNumber: '',
    rightToWorkShareCode: '',
    rightToWorkDocument: null,
    emergencyContactName: '',
    emergencyContactPhone: '',
    emergencyContactRelationship: '',
    agreeToTerms: false,
    agreeToDataProcessing: false,
    agreeToBackgroundCheck: false,
  });

  const steps = [
    {
      number: 1,
      title: 'Personal Information',
      description: 'Basic details and contact information',
      icon: FiUser,
    },
    {
      number: 2,
      title: 'Address & Identity',
      description: 'Address verification and national insurance',
      icon: FiMapPin,
    },
    {
      number: 3,
      title: 'Driving License',
      description: 'Driving license details and photos',
      icon: FiTruck,
    },
    {
      number: 4,
      title: 'Insurance & Banking',
      description: 'Insurance details and bank account information',
      icon: FiCreditCard,
    },
    {
      number: 5,
      title: 'Right to Work',
      description: 'UK work authorization and documents',
      icon: FiShield,
    },
    {
      number: 6,
      title: 'Emergency Contact',
      description: 'Emergency contact information',
      icon: FiPhone,
    },
    {
      number: 7,
      title: 'Terms & Submit',
      description: 'Review and submit application',
      icon: FiCheckCircle,
    },
  ];

  // Address autocomplete functionality
  const handleAddressSearch = async (query: string) => {
    if (query.length < 3) {
      setAddressSuggestions([]);
      setShowAddressSuggestions(false);
      return;
    }

    try {
      // Using UK Postcodes API for address lookup
      const response = await fetch(
        `https://api.postcodes.io/postcodes/${query}/autocomplete`
      );
      const data = await response.json();

      if (data.result) {
        setAddressSuggestions(data.result);
        setShowAddressSuggestions(true);
      }
    } catch (error) {
      console.error('Address lookup error:', error);
    }
  };

  const handleAddressSelect = async (postcode: string) => {
    try {
      const response = await fetch(
        `https://api.postcodes.io/postcodes/${postcode}`
      );
      const data = await response.json();

      if (data.result) {
        setFormData(prev => ({
          ...prev,
          addressLine1: data.result.premises || data.result.street,
          city: data.result.admin_district,
          postcode: data.result.postcode,
          county: data.result.admin_county,
        }));
      }
    } catch (error) {
      console.error('Address details error:', error);
    }

    setShowAddressSuggestions(false);
  };

  const handleFileUpload = (field: keyof DriverApplication, file: File) => {
    // Validate file type and size
    const allowedTypes = [
      'image/jpeg',
      'image/png',
      'image/jpg',
      'application/pdf',
    ];
    const maxSize = 5 * 1024 * 1024; // 5MB

    if (!allowedTypes.includes(file.type)) {
      toast({
        title: 'Invalid file type',
        description: 'Please upload JPEG, PNG, or PDF files only',
        status: 'error',
      });
      return;
    }

    if (file.size > maxSize) {
      toast({
        title: 'File too large',
        description: 'Please upload files smaller than 5MB',
        status: 'error',
      });
      return;
    }

    setFormData(prev => ({ ...prev, [field]: file }));
  };

  const validateStep = (step: number): boolean => {
    switch (step) {
      case 1:
        return !!(
          formData.firstName &&
          formData.lastName &&
          formData.email &&
          formData.password &&
          formData.confirmPassword &&
          formData.phone &&
          formData.dateOfBirth &&
          formData.password === formData.confirmPassword
        );
      case 2:
        return !!(
          formData.addressLine1 &&
          formData.city &&
          formData.postcode &&
          formData.nationalInsuranceNumber
        );
      case 3:
        return !!(
          formData.drivingLicenseNumber &&
          formData.drivingLicenseExpiry &&
          formData.drivingLicenseFront &&
          formData.drivingLicenseBack
        );
      case 4:
        return !!(
          formData.insuranceProvider &&
          formData.insurancePolicyNumber &&
          formData.insuranceExpiry &&
          formData.bankName &&
          formData.sortCode &&
          formData.accountNumber
        );
      case 5:
        return !!(
          formData.rightToWorkShareCode && formData.rightToWorkDocument
        );
      case 6:
        return !!(
          formData.emergencyContactName &&
          formData.emergencyContactPhone &&
          formData.emergencyContactRelationship
        );
      case 7:
        return !!(
          formData.agreeToTerms &&
          formData.agreeToDataProcessing &&
          formData.agreeToBackgroundCheck
        );
      default:
        return false;
    }
  };

  const handleSubmit = async () => {
    if (!validateStep(7)) {
      toast({
        title: 'Please complete all required fields',
        status: 'error',
      });
      return;
    }

    setIsSubmitting(true);

    try {
      const formDataToSend = new FormData();

      // Append all form data
      Object.entries(formData).forEach(([key, value]) => {
        if (value instanceof File) {
          formDataToSend.append(key, value);
        } else if (typeof value === 'boolean') {
          formDataToSend.append(key, value.toString());
        } else {
          formDataToSend.append(key, value || '');
        }
      });

      const response = await fetch('/api/driver/applications', {
        method: 'POST',
        body: formDataToSend,
      });

      if (response.ok) {
        toast({
          title: 'Application submitted successfully',
          description:
            'We will review your application and contact you within 3-5 business days',
          status: 'success',
          duration: 5000,
        });
        router.push('/driver-application/success');
      } else {
        const error = await response.json();
        throw new Error(error.message || 'Failed to submit application');
      }
    } catch (error) {
      toast({
        title: 'Submission failed',
        description:
          error instanceof Error ? error.message : 'Please try again',
        status: 'error',
      });
    } finally {
      setIsSubmitting(false);
    }
  };

  const renderStepContent = () => {
    switch (currentStep) {
      case 1:
        return (
          <VStack spacing={6} align="stretch">
            <HStack spacing={3} mb={4}>
              <Icon as={FiUser} color="neon.500" boxSize={6} />
              <Heading size="lg" color="neon.500">
                Personal Information
              </Heading>
            </HStack>

            <Grid templateColumns="repeat(2, 1fr)" gap={6}>
              <FormControl isRequired>
                <FormLabel
                  fontSize="md"
                  fontWeight="semibold"
                  color="text.primary"
                >
                  First Name
                </FormLabel>
                <Input
                  value={formData.firstName}
                  onChange={e =>
                    setFormData(prev => ({
                      ...prev,
                      firstName: e.target.value,
                    }))
                  }
                  placeholder="Enter your first name"
                  size="lg"
                  borderRadius="xl"
                  borderWidth="2px"
                  borderColor="border.primary"
                  bg="bg.surface"
                  _focus={{
                    borderColor: 'neon.400',
                    boxShadow: '0 0 0 1px rgba(0,194,255,0.2)',
                  }}
                  _hover={{
                    borderColor: 'neon.300',
                  }}
                  transition="all 0.2s"
                />
              </FormControl>

              <FormControl isRequired>
                <FormLabel
                  fontSize="md"
                  fontWeight="semibold"
                  color="text.primary"
                >
                  Last Name
                </FormLabel>
                <Input
                  value={formData.lastName}
                  onChange={e =>
                    setFormData(prev => ({ ...prev, lastName: e.target.value }))
                  }
                  placeholder="Enter your last name"
                  size="lg"
                  borderRadius="xl"
                  borderWidth="2px"
                  borderColor="border.primary"
                  bg="bg.surface"
                  _focus={{
                    borderColor: 'neon.400',
                    boxShadow: '0 0 0 1px rgba(0,194,255,0.2)',
                  }}
                  _hover={{
                    borderColor: 'neon.300',
                  }}
                  transition="all 0.2s"
                />
              </FormControl>
            </Grid>

            <FormControl isRequired>
              <FormLabel
                fontSize="md"
                fontWeight="semibold"
                color="text.primary"
              >
                Email Address
              </FormLabel>
              <Input
                type="email"
                value={formData.email}
                onChange={e =>
                  setFormData(prev => ({ ...prev, email: e.target.value }))
                }
                placeholder="Enter your email address"
                size="lg"
                borderRadius="xl"
                borderWidth="2px"
                borderColor="border.primary"
                bg="bg.surface"
                _focus={{
                  borderColor: 'neon.400',
                  boxShadow: '0 0 0 1px rgba(0,194,255,0.2)',
                }}
                _hover={{
                  borderColor: 'neon.300',
                }}
                transition="all 0.2s"
              />
            </FormControl>

            <Grid templateColumns="repeat(2, 1fr)" gap={6}>
              <FormControl isRequired>
                <FormLabel
                  fontSize="md"
                  fontWeight="semibold"
                  color="text.primary"
                >
                  Password
                </FormLabel>
                <InputGroup>
                  <Input
                    type={showPassword ? 'text' : 'password'}
                    value={formData.password}
                    onChange={e =>
                      setFormData(prev => ({
                        ...prev,
                        password: e.target.value,
                      }))
                    }
                    placeholder="Create a password"
                    size="lg"
                    borderRadius="xl"
                    borderWidth="2px"
                    borderColor="border.primary"
                    bg="bg.surface"
                    _focus={{
                      borderColor: 'neon.400',
                      boxShadow: '0 0 0 1px rgba(0,194,255,0.2)',
                    }}
                    _hover={{
                      borderColor: 'neon.300',
                    }}
                    transition="all 0.2s"
                  />
                  <InputRightElement>
                    <IconButton
                      aria-label={
                        showPassword ? 'Hide password' : 'Show password'
                      }
                      icon={<Icon as={showPassword ? FiEyeOff : FiEye} />}
                      variant="ghost"
                      size="md"
                      onClick={() => setShowPassword(!showPassword)}
                      color="neon.400"
                      _hover={{ bg: 'rgba(0,194,255,0.1)' }}
                    />
                  </InputRightElement>
                </InputGroup>
              </FormControl>

              <FormControl isRequired>
                <FormLabel
                  fontSize="md"
                  fontWeight="semibold"
                  color="text.primary"
                >
                  Confirm Password
                </FormLabel>
                <InputGroup>
                  <Input
                    type={showConfirmPassword ? 'text' : 'password'}
                    value={formData.confirmPassword}
                    onChange={e =>
                      setFormData(prev => ({
                        ...prev,
                        confirmPassword: e.target.value,
                      }))
                    }
                    placeholder="Confirm your password"
                    size="lg"
                    borderRadius="xl"
                    borderWidth="2px"
                    borderColor="border.primary"
                    bg="bg.surface"
                    _focus={{
                      borderColor: 'neon.400',
                      boxShadow: '0 0 0 1px rgba(0,194,255,0.2)',
                    }}
                    _hover={{
                      borderColor: 'neon.300',
                    }}
                    transition="all 0.2s"
                  />
                  <InputRightElement>
                    <IconButton
                      aria-label={
                        showConfirmPassword ? 'Hide password' : 'Show password'
                      }
                      icon={
                        <Icon as={showConfirmPassword ? FiEyeOff : FiEye} />
                      }
                      variant="ghost"
                      size="md"
                      onClick={() =>
                        setShowConfirmPassword(!showConfirmPassword)
                      }
                      color="neon.400"
                      _hover={{ bg: 'rgba(0,194,255,0.1)' }}
                    />
                  </InputRightElement>
                </InputGroup>
              </FormControl>
            </Grid>

            <Grid templateColumns="repeat(2, 1fr)" gap={6}>
              <FormControl isRequired>
                <FormLabel
                  fontSize="md"
                  fontWeight="semibold"
                  color="text.primary"
                >
                  Phone Number
                </FormLabel>
                <Input
                  type="tel"
                  value={formData.phone}
                  onChange={e =>
                    setFormData(prev => ({ ...prev, phone: e.target.value }))
                  }
                  placeholder="Enter your phone number"
                  size="lg"
                  borderRadius="xl"
                  borderWidth="2px"
                  borderColor="border.primary"
                  bg="bg.surface"
                  _focus={{
                    borderColor: 'neon.400',
                    boxShadow: '0 0 0 1px rgba(0,194,255,0.2)',
                  }}
                  _hover={{
                    borderColor: 'neon.300',
                  }}
                  transition="all 0.2s"
                />
              </FormControl>

              <FormControl isRequired>
                <FormLabel
                  fontSize="md"
                  fontWeight="semibold"
                  color="text.primary"
                >
                  Date of Birth
                </FormLabel>
                <Input
                  type="date"
                  value={formData.dateOfBirth}
                  onChange={e =>
                    setFormData(prev => ({
                      ...prev,
                      dateOfBirth: e.target.value,
                    }))
                  }
                  size="lg"
                  borderRadius="xl"
                  borderWidth="2px"
                  borderColor="border.primary"
                  bg="bg.surface"
                  _focus={{
                    borderColor: 'neon.400',
                    boxShadow: '0 0 0 1px rgba(0,194,255,0.2)',
                  }}
                  _hover={{
                    borderColor: 'neon.300',
                  }}
                  transition="all 0.2s"
                />
              </FormControl>
            </Grid>
          </VStack>
        );

      case 2:
        return (
          <VStack spacing={6} align="stretch">
            <Heading size="md" color="blue.600">
              Address & Identity
            </Heading>

            <FormControl isRequired>
              <FormLabel>National Insurance Number</FormLabel>
              <Input
                value={formData.nationalInsuranceNumber}
                onChange={e =>
                  setFormData(prev => ({
                    ...prev,
                    nationalInsuranceNumber: e.target.value,
                  }))
                }
                placeholder="e.g., AB123456C"
                maxLength={9}
              />
              <FormHelperText>
                Format: 2 letters, 6 numbers, 1 letter (e.g., AB123456C)
              </FormHelperText>
            </FormControl>

            <FormControl isRequired>
              <FormLabel>Postcode</FormLabel>
              <Input
                value={formData.postcode}
                onChange={e => {
                  setFormData(prev => ({ ...prev, postcode: e.target.value }));
                  handleAddressSearch(e.target.value);
                }}
                placeholder="Enter your postcode"
                onBlur={() =>
                  setTimeout(() => setShowAddressSuggestions(false), 200)
                }
              />
              {showAddressSuggestions && (
                <Box position="relative">
                  <Box
                    position="absolute"
                    top="100%"
                    left={0}
                    width="100%"
                    bg="#1F2937"
                    border="1px solid"
                    borderColor="#374151"
                    borderRadius="md"
                    boxShadow="lg"
                    zIndex={10}
                    maxH="200px"
                    overflowY="auto"
                  >
                    {addressSuggestions.map((suggestion, index) => (
                      <Box
                        key={index}
                        px={4}
                        py={2}
                        cursor="pointer"
                        _hover={{ bg: 'gray.100' }}
                        onClick={() => handleAddressSelect(suggestion)}
                      >
                        {suggestion}
                      </Box>
                    ))}
                  </Box>
                </Box>
              )}
            </FormControl>

            <FormControl isRequired>
              <FormLabel>Address Line 1</FormLabel>
              <Input
                value={formData.addressLine1}
                onChange={e =>
                  setFormData(prev => ({
                    ...prev,
                    addressLine1: e.target.value,
                  }))
                }
                placeholder="House number and street name"
              />
            </FormControl>

            <FormControl>
              <FormLabel>Address Line 2</FormLabel>
              <Input
                value={formData.addressLine2}
                onChange={e =>
                  setFormData(prev => ({
                    ...prev,
                    addressLine2: e.target.value,
                  }))
                }
                placeholder="Flat, suite, etc. (optional)"
              />
            </FormControl>

            <Grid templateColumns="repeat(2, 1fr)" gap={4}>
              <FormControl isRequired>
                <FormLabel>City</FormLabel>
                <Input
                  value={formData.city}
                  onChange={e =>
                    setFormData(prev => ({ ...prev, city: e.target.value }))
                  }
                  placeholder="Enter your city"
                />
              </FormControl>

              <FormControl isRequired>
                <FormLabel>County</FormLabel>
                <Input
                  value={formData.county}
                  onChange={e =>
                    setFormData(prev => ({ ...prev, county: e.target.value }))
                  }
                  placeholder="Enter your county"
                />
              </FormControl>
            </Grid>
          </VStack>
        );

      case 3:
        return (
          <VStack spacing={6} align="stretch">
            <Heading size="md" color="blue.600">
              Driving License
            </Heading>

            <Grid templateColumns="repeat(2, 1fr)" gap={4}>
              <FormControl isRequired>
                <FormLabel>Driving License Number</FormLabel>
                <Input
                  value={formData.drivingLicenseNumber}
                  onChange={e =>
                    setFormData(prev => ({
                      ...prev,
                      drivingLicenseNumber: e.target.value,
                    }))
                  }
                  placeholder="Enter your driving license number"
                />
              </FormControl>

              <FormControl isRequired>
                <FormLabel>Expiry Date</FormLabel>
                <Input
                  type="date"
                  value={formData.drivingLicenseExpiry}
                  onChange={e =>
                    setFormData(prev => ({
                      ...prev,
                      drivingLicenseExpiry: e.target.value,
                    }))
                  }
                />
              </FormControl>
            </Grid>

            <Grid templateColumns="repeat(2, 1fr)" gap={4}>
              <FormControl isRequired>
                <FormLabel>Driving License Front</FormLabel>
                <Box
                  border="2px dashed"
                  borderColor="gray.300"
                  borderRadius="md"
                  p={4}
                  textAlign="center"
                  position="relative"
                >
                  <Input
                    type="file"
                    accept="image/*,.pdf"
                    onChange={e => {
                      const file = e.target.files?.[0];
                      if (file) handleFileUpload('drivingLicenseFront', file);
                    }}
                    position="absolute"
                    top={0}
                    left={0}
                    width="100%"
                    height="100%"
                    opacity={0}
                    cursor="pointer"
                  />
                  <VStack spacing={2}>
                    <Icon as={FiCamera} boxSize={6} color="gray.400" />
                    <Text fontSize="sm" color="gray.500">
                      Click to upload front of driving license
                    </Text>
                    <Text fontSize="xs" color="gray.400">
                      JPEG, PNG, or PDF (max 5MB)
                    </Text>
                  </VStack>
                </Box>
                {formData.drivingLicenseFront && (
                  <Text fontSize="sm" color="green.500" mt={2}>
                    ✓ {formData.drivingLicenseFront.name}
                  </Text>
                )}
              </FormControl>

              <FormControl isRequired>
                <FormLabel>Driving License Back</FormLabel>
                <Box
                  border="2px dashed"
                  borderColor="gray.300"
                  borderRadius="md"
                  p={4}
                  textAlign="center"
                  position="relative"
                >
                  <Input
                    type="file"
                    accept="image/*,.pdf"
                    onChange={e => {
                      const file = e.target.files?.[0];
                      if (file) handleFileUpload('drivingLicenseBack', file);
                    }}
                    position="absolute"
                    top={0}
                    left={0}
                    width="100%"
                    height="100%"
                    opacity={0}
                    cursor="pointer"
                  />
                  <VStack spacing={2}>
                    <Icon as={FiCamera} boxSize={6} color="gray.400" />
                    <Text fontSize="sm" color="gray.500">
                      Click to upload back of driving license
                    </Text>
                    <Text fontSize="xs" color="gray.400">
                      JPEG, PNG, or PDF (max 5MB)
                    </Text>
                  </VStack>
                </Box>
                {formData.drivingLicenseBack && (
                  <Text fontSize="sm" color="green.500" mt={2}>
                    ✓ {formData.drivingLicenseBack.name}
                  </Text>
                )}
              </FormControl>
            </Grid>
          </VStack>
        );

      case 4:
        return (
          <VStack spacing={6} align="stretch">
            <Heading size="md" color="blue.600">
              Insurance & Banking
            </Heading>

            <Grid templateColumns="repeat(2, 1fr)" gap={4}>
              <FormControl isRequired>
                <FormLabel>Insurance Provider</FormLabel>
                <Input
                  value={formData.insuranceProvider}
                  onChange={e =>
                    setFormData(prev => ({
                      ...prev,
                      insuranceProvider: e.target.value,
                    }))
                  }
                  placeholder="Enter insurance provider name"
                />
              </FormControl>

              <FormControl isRequired>
                <FormLabel>Policy Number</FormLabel>
                <Input
                  value={formData.insurancePolicyNumber}
                  onChange={e =>
                    setFormData(prev => ({
                      ...prev,
                      insurancePolicyNumber: e.target.value,
                    }))
                  }
                  placeholder="Enter policy number"
                />
              </FormControl>
            </Grid>

            <Grid templateColumns="repeat(2, 1fr)" gap={4}>
              <FormControl isRequired>
                <FormLabel>Insurance Expiry Date</FormLabel>
                <Input
                  type="date"
                  value={formData.insuranceExpiry}
                  onChange={e =>
                    setFormData(prev => ({
                      ...prev,
                      insuranceExpiry: e.target.value,
                    }))
                  }
                />
              </FormControl>

              <FormControl isRequired>
                <FormLabel>Insurance Document</FormLabel>
                <Box
                  border="2px dashed"
                  borderColor="gray.300"
                  borderRadius="md"
                  p={4}
                  textAlign="center"
                  position="relative"
                >
                  <Input
                    type="file"
                    accept="image/*,.pdf"
                    onChange={e => {
                      const file = e.target.files?.[0];
                      if (file) handleFileUpload('insuranceDocument', file);
                    }}
                    position="absolute"
                    top={0}
                    left={0}
                    width="100%"
                    height="100%"
                    opacity={0}
                    cursor="pointer"
                  />
                  <VStack spacing={2}>
                    <Icon as={FiFileText} boxSize={6} color="gray.400" />
                    <Text fontSize="sm" color="gray.500">
                      Upload insurance certificate
                    </Text>
                    <Text fontSize="xs" color="gray.400">
                      JPEG, PNG, or PDF (max 5MB)
                    </Text>
                  </VStack>
                </Box>
                {formData.insuranceDocument && (
                  <Text fontSize="sm" color="green.500" mt={2}>
                    ✓ {formData.insuranceDocument.name}
                  </Text>
                )}
              </FormControl>
            </Grid>

            <Divider />

            <Heading size="sm" color="blue.600">
              Banking Information
            </Heading>

            <Grid templateColumns="repeat(2, 1fr)" gap={4}>
              <FormControl isRequired>
                <FormLabel>Bank Name</FormLabel>
                <Input
                  value={formData.bankName}
                  onChange={e =>
                    setFormData(prev => ({ ...prev, bankName: e.target.value }))
                  }
                  placeholder="Enter your bank name"
                />
              </FormControl>

              <FormControl isRequired>
                <FormLabel>Account Holder Name</FormLabel>
                <Input
                  value={formData.accountHolderName}
                  onChange={e =>
                    setFormData(prev => ({
                      ...prev,
                      accountHolderName: e.target.value,
                    }))
                  }
                  placeholder="Name on bank account"
                />
              </FormControl>
            </Grid>

            <Grid templateColumns="repeat(2, 1fr)" gap={4}>
              <FormControl isRequired>
                <FormLabel>Sort Code</FormLabel>
                <Input
                  value={formData.sortCode}
                  onChange={e =>
                    setFormData(prev => ({ ...prev, sortCode: e.target.value }))
                  }
                  placeholder="e.g., 12-34-56"
                  maxLength={8}
                />
                <FormHelperText>Format: XX-XX-XX</FormHelperText>
              </FormControl>

              <FormControl isRequired>
                <FormLabel>Account Number</FormLabel>
                <Input
                  value={formData.accountNumber}
                  onChange={e =>
                    setFormData(prev => ({
                      ...prev,
                      accountNumber: e.target.value,
                    }))
                  }
                  placeholder="8-digit account number"
                  maxLength={8}
                />
              </FormControl>
            </Grid>
          </VStack>
        );

      case 5:
        return (
          <VStack spacing={6} align="stretch">
            <Heading size="md" color="blue.600">
              Right to Work
            </Heading>

            <Alert status="info">
              <AlertIcon />
              <Box>
                <Text fontWeight="bold">UK Right to Work Verification</Text>
                <Text fontSize="sm">
                  You must provide proof of your right to work in the UK. This
                  can be done through a share code from the UK government.
                </Text>
              </Box>
            </Alert>

            <FormControl isRequired>
              <FormLabel>Right to Work Share Code</FormLabel>
              <Input
                value={formData.rightToWorkShareCode}
                onChange={e =>
                  setFormData(prev => ({
                    ...prev,
                    rightToWorkShareCode: e.target.value,
                  }))
                }
                placeholder="Enter your 9-character share code"
                maxLength={9}
              />
              <FormHelperText>
                Get your share code from{' '}
                <Link
                  href="https://www.gov.uk/prove-right-to-work"
                  isExternal
                  color="blue.500"
                >
                  gov.uk/prove-right-to-work
                </Link>
              </FormHelperText>
            </FormControl>

            <FormControl isRequired>
              <FormLabel>Right to Work Document</FormLabel>
              <Box
                border="2px dashed"
                borderColor="gray.300"
                borderRadius="md"
                p={4}
                textAlign="center"
                position="relative"
              >
                <Input
                  type="file"
                  accept="image/*,.pdf"
                  onChange={e => {
                    const file = e.target.files?.[0];
                    if (file) handleFileUpload('rightToWorkDocument', file);
                  }}
                  position="absolute"
                  top={0}
                  left={0}
                  width="100%"
                  height="100%"
                  opacity={0}
                  cursor="pointer"
                />
                <VStack spacing={2}>
                  <Icon as={FiShield} boxSize={6} color="gray.400" />
                  <Text fontSize="sm" color="gray.500">
                    Upload right to work document
                  </Text>
                  <Text fontSize="xs" color="gray.400">
                    Passport, BRP, or other valid document (max 5MB)
                  </Text>
                </VStack>
              </Box>
              {formData.rightToWorkDocument && (
                <Text fontSize="sm" color="green.500" mt={2}>
                  ✓ {formData.rightToWorkDocument.name}
                </Text>
              )}
            </FormControl>
          </VStack>
        );

      case 6:
        return (
          <VStack spacing={6} align="stretch">
            <Heading size="md" color="blue.600">
              Emergency Contact
            </Heading>

            <FormControl isRequired>
              <FormLabel>Emergency Contact Name</FormLabel>
              <Input
                value={formData.emergencyContactName}
                onChange={e =>
                  setFormData(prev => ({
                    ...prev,
                    emergencyContactName: e.target.value,
                  }))
                }
                placeholder="Full name of emergency contact"
              />
            </FormControl>

            <Grid templateColumns="repeat(2, 1fr)" gap={4}>
              <FormControl isRequired>
                <FormLabel>Emergency Contact Phone</FormLabel>
                <Input
                  type="tel"
                  value={formData.emergencyContactPhone}
                  onChange={e =>
                    setFormData(prev => ({
                      ...prev,
                      emergencyContactPhone: e.target.value,
                    }))
                  }
                  placeholder="Phone number"
                />
              </FormControl>

              <FormControl isRequired>
                <FormLabel>Relationship</FormLabel>
                <Select
                  value={formData.emergencyContactRelationship}
                  onChange={e =>
                    setFormData(prev => ({
                      ...prev,
                      emergencyContactRelationship: e.target.value,
                    }))
                  }
                  placeholder="Select relationship"
                >
                  <option value="spouse">Spouse/Partner</option>
                  <option value="parent">Parent</option>
                  <option value="sibling">Sibling</option>
                  <option value="friend">Friend</option>
                  <option value="other">Other</option>
                </Select>
              </FormControl>
            </Grid>
          </VStack>
        );

      case 7:
        return (
          <VStack spacing={6} align="stretch">
            <Heading size="md" color="blue.600">
              Terms & Conditions
            </Heading>

            <Alert status="warning">
              <AlertIcon />
              <Text>
                Please review all information before submitting. You will not be
                able to edit your application after submission.
              </Text>
            </Alert>

            <Box
              p={4}
              border="1px solid"
              borderColor="gray.200"
              borderRadius="md"
              maxH="300px"
              overflowY="auto"
            >
              <Text fontSize="sm" lineHeight="tall">
                <strong>Application Summary:</strong>
                <br />
                Name: {formData.firstName} {formData.lastName}
                <br />
                Email: {formData.email}
                <br />
                Phone: {formData.phone}
                <br />
                Address: {formData.addressLine1}, {formData.city},{' '}
                {formData.postcode}
                <br />
                Driving License: {formData.drivingLicenseNumber}
                <br />
                Insurance: {formData.insuranceProvider}
                <br />
                Bank: {formData.bankName}
                <br />
                Emergency Contact: {formData.emergencyContactName} (
                {formData.emergencyContactRelationship})
              </Text>
            </Box>

            <VStack spacing={4} align="stretch">
              <Checkbox
                isChecked={formData.agreeToTerms}
                onChange={e =>
                  setFormData(prev => ({
                    ...prev,
                    agreeToTerms: e.target.checked,
                  }))
                }
              >
                I agree to the{' '}
                <Link href="/terms" isExternal color="blue.500">
                  Terms and Conditions
                </Link>
              </Checkbox>

              <Checkbox
                isChecked={formData.agreeToDataProcessing}
                onChange={e =>
                  setFormData(prev => ({
                    ...prev,
                    agreeToDataProcessing: e.target.checked,
                  }))
                }
              >
                I consent to the processing of my personal data for employment
                purposes
              </Checkbox>

              <Checkbox
                isChecked={formData.agreeToBackgroundCheck}
                onChange={e =>
                  setFormData(prev => ({
                    ...prev,
                    agreeToBackgroundCheck: e.target.checked,
                  }))
                }
              >
                I authorize Speedy Van to conduct background checks and verify
                all provided information
              </Checkbox>
            </VStack>

            <Alert status="info">
              <AlertIcon />
              <Text fontSize="sm">
                After submission, your application will be reviewed by our team.
                You will receive an email confirmation and updates on your
                application status.
              </Text>
            </Alert>
          </VStack>
        );

      default:
        return null;
    }
  };

  return (
    <Box
      minH="100vh"
      bg="#111827"
      py={{ base: 8, md: 12 }}
      position="relative"
      overflow="hidden"
    >
      {/* Background Pattern */}
      <Box
        position="absolute"
        top={0}
        left={0}
        width="100%"
        height="100%"
        opacity={0.02}
        background="radial-gradient(circle at 20% 80%, rgba(0,194,255,0.1) 0%, transparent 50%), radial-gradient(circle at 80% 20%, rgba(0,209,143,0.1) 0%, transparent 50%)"
        pointerEvents="none"
      />

      <Container maxW="6xl" position="relative" zIndex={1}>
        <MotionBox
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
viewport={{ once: true }}
          transition="0.5s ease-out"
        >
          <VStack spacing={{ base: 8, md: 12 }} align="stretch">
            {/* Header */}
            <Box textAlign="center" py={{ base: 4, md: 6 }}>
              <VStack spacing={6}>
                <Box
                  p={6}
                  borderRadius="2xl"
                  bg="linear-gradient(135deg, rgba(0,194,255,0.1), rgba(0,209,143,0.1))"
                  borderWidth="2px"
                  borderColor="neon.400"
                  display="inline-block"
                >
                  <Icon as={FiTruck} color="neon.500" boxSize={12} />
                </Box>
                <Heading
                  size={{ base: 'xl', md: '2xl' }}
                  color="neon.500"
                  fontWeight="extrabold"
                >
                  🚚 Driver Application
                </Heading>
                <Text
                  color="text.secondary"
                  fontSize={{ base: 'md', md: 'lg' }}
                  maxW="3xl"
                  mx="auto"
                  lineHeight="1.6"
                >
                  Join our team of professional drivers and start earning with
                  Speedy Van. Complete your application below to begin your
                  journey.
                </Text>
              </VStack>
            </Box>

            {/* Progress Bar */}
            <Box>
              <HStack justify="space-between" mb={4}>
                <Text fontSize="lg" fontWeight="semibold" color="text.primary">
                  Step {currentStep} of {steps.length}
                </Text>
                <Badge
                  colorScheme="neon"
                  variant="solid"
                  size="lg"
                  px={4}
                  py={2}
                  borderRadius="full"
                  fontSize="md"
                  fontWeight="bold"
                  boxShadow="0 4px 15px rgba(0,194,255,0.3)"
                >
                  {Math.round((currentStep / steps.length) * 100)}% Complete
                </Badge>
              </HStack>
              <Progress
                value={(currentStep / steps.length) * 100}
                colorScheme="neon"
                size="lg"
                borderRadius="full"
                bg="bg.surface"
                sx={{
                  '& > div': {
                    background:
                      'linear-gradient(90deg, #00C2FF 0%, #00D18F 100%)',
                    boxShadow: '0 0 20px rgba(0,194,255,0.4)',
                  },
                }}
              />
            </Box>

            {/* Steps Navigation */}
            <Box overflowX="auto" pb={4}>
              <HStack spacing={4} minW="max-content">
                {steps.map((step, index) => (
                  <Box
                    key={step.number}
                    p={4}
                    borderRadius="xl"
                    borderWidth="2px"
                    borderColor={
                      currentStep === step.number
                        ? 'neon.400'
                        : 'border.primary'
                    }
                    bg={
                      currentStep === step.number
                        ? 'rgba(0,194,255,0.1)'
                        : 'bg.surface'
                    }
                    cursor={
                      index + 1 < currentStep || validateStep(index + 1)
                        ? 'pointer'
                        : 'default'
                    }
                    onClick={() => {
                      if (index + 1 < currentStep || validateStep(index + 1)) {
                        setCurrentStep(step.number);
                      }
                    }}
                    opacity={
                      index + 1 < currentStep || validateStep(index + 1)
                        ? 1
                        : 0.5
                    }
                    transition="all 0.3s ease"
                    _hover={
                      index + 1 < currentStep || validateStep(index + 1)
                        ? {
                            borderColor: 'neon.400',
                            bg: 'rgba(0,194,255,0.15)',
                            transform: 'translateY(-2px)',
                            boxShadow: '0 8px 25px rgba(0,194,255,0.2)',
                          }
                        : {}
                    }
                    minW="200px"
                  >
                    <VStack spacing={3} align="center">
                      <Box
                        p={3}
                        borderRadius="lg"
                        bg={
                          currentStep === step.number ? 'neon.500' : 'gray.500'
                        }
                        color="white"
                        boxSize="50px"
                        display="flex"
                        alignItems="center"
                        justifyContent="center"
                        boxShadow={
                          currentStep === step.number
                            ? '0 4px 15px rgba(0,194,255,0.3)'
                            : 'none'
                        }
                      >
                        <Icon as={step.icon} boxSize={5} />
                      </Box>
                      <VStack spacing={1} align="center">
                        <Text
                          fontWeight="bold"
                          color={
                            currentStep === step.number
                              ? 'neon.500'
                              : 'text.primary'
                          }
                          fontSize="md"
                        >
                          {step.number}. {step.title}
                        </Text>
                        <Text
                          fontSize="sm"
                          color="text.secondary"
                          textAlign="center"
                        >
                          {step.description}
                        </Text>
                      </VStack>
                    </VStack>
                  </Box>
                ))}
              </HStack>
            </Box>

            {/* Step Content */}
            <Card
              bg={cardBg}
              borderWidth="2px"
              borderColor="border.primary"
              borderRadius="2xl"
              boxShadow="xl"
              overflow="hidden"
              position="relative"
              _before={{
                content: '""',
                position: 'absolute',
                top: 0,
                left: 0,
                right: 0,
                bottom: 0,
                background:
                  'linear-gradient(135deg, rgba(0,194,255,0.05), rgba(0,209,143,0.05))',
                pointerEvents: 'none',
              }}
            >
              <CardBody p={{ base: 6, md: 8 }} position="relative" zIndex={1}>
                {renderStepContent()}
              </CardBody>
            </Card>

            {/* Navigation Buttons */}
            <HStack justify="space-between" spacing={6}>
              <Button
                variant="outline"
                size="lg"
                onClick={() => setCurrentStep(Math.max(1, currentStep - 1))}
                isDisabled={currentStep === 1}
                leftIcon={<Icon as={FiArrowLeft} />}
                borderColor="border.primary"
                color="text.secondary"
                _hover={{
                  borderColor: 'neon.400',
                  color: 'neon.400',
                  bg: 'rgba(0,194,255,0.05)',
                }}
                transition="all 0.2s"
                borderRadius="xl"
                px={8}
                py={6}
              >
                Previous
              </Button>

              <Spacer />

              {currentStep < steps.length ? (
                <Button
                  variant="solid"
                  size="lg"
                  onClick={() => {
                    if (validateStep(currentStep)) {
                      setCurrentStep(currentStep + 1);
                    } else {
                      toast({
                        title: 'Please complete all required fields',
                        status: 'error',
                      });
                    }
                  }}
                  isDisabled={!validateStep(currentStep)}
                  rightIcon={<Icon as={FiArrowRight} />}
                  bg="linear-gradient(135deg, #00C2FF, #00D18F)"
                  color="white"
                  _hover={{
                    bg: 'linear-gradient(135deg, #00D18F, #00C2FF)',
                    transform: 'translateY(-2px)',
                    boxShadow: '0 8px 25px rgba(0,194,255,0.4)',
                  }}
                  _active={{
                    bg: 'linear-gradient(135deg, #00B8E6, #00C2FF)',
                  }}
                  transition="all 0.3s ease"
                  borderRadius="xl"
                  px={8}
                  py={6}
                  fontWeight="bold"
                >
                  Next
                </Button>
              ) : (
                <Button
                  variant="solid"
                  size="lg"
                  onClick={handleSubmit}
                  isLoading={isSubmitting}
                  loadingText="Submitting..."
                  isDisabled={!validateStep(currentStep)}
                  rightIcon={<Icon as={FiCheckCircle} />}
                  bg="linear-gradient(135deg, #00C2FF, #00D18F)"
                  color="white"
                  _hover={{
                    bg: 'linear-gradient(135deg, #00D18F, #00C2FF)',
                    transform: 'translateY(-2px)',
                    boxShadow: '0 8px 25px rgba(0,194,255,0.4)',
                  }}
                  _active={{
                    bg: 'linear-gradient(135deg, #00B8E6, #00C2FF)',
                  }}
                  transition="all 0.3s ease"
                  borderRadius="xl"
                  px={8}
                  py={6}
                  fontWeight="bold"
                >
                  Submit Application
                </Button>
              )}
            </HStack>
          </VStack>
        </MotionBox>
      </Container>
    </Box>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import {
  Box,
  Container,
  VStack,
  Heading,
  Text,
  FormControl,
  FormLabel,
  Input,
  Button,
  Alert,
  AlertIcon,
  Card,
  CardBody,
  Link as ChakraLink,
  IconButton,
  HStack,
  Icon,
  Badge,
  Divider,
  useColorModeValue,
} from '@chakra-ui/react';
import { signIn, getCsrfToken, useSession } from 'next-auth/react';
import { useRouter } from 'next/navigation';
import NextLink from 'next/link';
import { ChevronLeftIcon } from '@chakra-ui/icons';
import {
  FaTruck,
  FaShieldAlt,
  FaUser,
  FaLock,
  FaSignInAlt,
  FaArrowRight,
  FaMapMarkerAlt,
  FaClock,
  FaStar,
  FaHome,
} from 'react-icons/fa';
import { useRoleBasedRedirect } from '@/hooks/useRoleBasedRedirect';

export default function DriverLogin() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');
  const [csrfToken, setCsrfToken] = useState('');
  const [showApplyButton, setShowApplyButton] = useState(false);
  const router = useRouter();
  const { data: session, status } = useSession();
  const { userRole } = useRoleBasedRedirect();

  const bgColor = useColorModeValue('white', 'gray.800');
  const cardBg = useColorModeValue('white', 'gray.700');

  // Get CSRF token on component mount
  React.useEffect(() => {
    const fetchCsrfToken = async () => {
      try {
        const token = await getCsrfToken();
        setCsrfToken(token || '');
      } catch (error) {
        console.error('Failed to fetch CSRF token:', error);
      }
    };
    fetchCsrfToken();
  }, []);

  // Monitor session and redirect if already authenticated
  useEffect(() => {
    if (status === 'loading') return; // Still loading

    if (session?.user && (session.user as any).role === 'driver') {
      console.log('✅ Driver session detected, redirecting to dashboard');
      // The useRoleBasedRedirect hook will handle the redirect automatically
    }
  }, [session, status]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError('');
    setShowApplyButton(false);

    try {
      console.log('🚚 Driver login attempt:', { email });

      // Check if user exists and their status
      const checkResponse = await fetch('/api/driver/auth/login', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ email, password }),
      });

      const checkResult = await checkResponse.json();

      if (!checkResponse.ok) {
        // Case 3: Not registered/never applied -> redirect to application
        if (checkResult.error === 'Invalid email or password') {
          console.log('❌ Driver not found - redirecting to application form');
          router.replace('/driver-application');
          return;
        } else {
          setError(checkResult.error || 'Invalid credentials');
          return;
        }
      }

      // User exists as driver - check status
      const driverStatus = checkResult.user.driver?.onboardingStatus;

      if (driverStatus === 'approved') {
        // Case 1: Approved driver -> sign in and redirect to portal
        console.log('✅ Approved driver - proceeding with sign in');
        
        const result = await signIn('credentials', {
          email,
          password,
          csrfToken,
          userType: 'driver',
          redirect: false,
        });

        if (result?.error) {
          setError(result.error);
        } else if (result?.ok) {
          console.log('✅ Driver session created, redirecting to driver portal...');
          window.location.href = '/driver';
        } else {
          setError('Authentication failed. Please try again.');
        }
      } else {
        // Case 2: Pending/under review -> show message
        console.log('⏳ Driver application pending - showing review message');
        const statusMessages = {
          'pending': 'Your driver application is currently being reviewed by our team.',
          'under_review': 'Your application is currently being reviewed by our team.',
          'requires_additional_info': 'Your application requires additional information. Please check your email.',
          'rejected': 'Your driver application was not approved. Please contact support for more information.',
        };
        
        const message = (statusMessages as any)[driverStatus] || 'Your driver application is currently being reviewed by our team.';
        setError(message);
        return;
      }

    } catch (error) {
      console.error('Driver sign in error:', error);
      setError('An error occurred. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleBackClick = () => {
    router.push('/');
  };

  return (
    <Box
      minH="100vh"
      bg={bgColor}
      py={{ base: 8, md: 12 }}
      position="relative"
      overflow="hidden"
    >
      {/* Background Pattern */}
      <Box
        position="absolute"
        top={0}
        left={0}
        width="100%"
        height="100%"
        opacity={0.02}
        background="radial-gradient(circle at 20% 80%, rgba(0,194,255,0.1) 0%, transparent 50%), radial-gradient(circle at 80% 20%, rgba(0,209,143,0.1) 0%, transparent 50%)"
        pointerEvents="none"
      />

      <Container maxW="6xl" position="relative" zIndex={1}>
        <VStack spacing={{ base: 8, md: 12 }}>
          {/* Back Button */}
          <HStack w="full" justify="flex-start">
            <IconButton
              aria-label="Back to main page"
              icon={<FaHome />}
              variant="ghost"
              onClick={handleBackClick}
              data-testid="back-button"
              size="lg"
              color="text.secondary"
              _hover={{
                bg: 'rgba(0,194,255,0.1)',
                color: 'neon.400',
              }}
              transition="all 0.2s"
            />
          </HStack>

          {/* Header Section */}
          <Box textAlign="center" w="full">
            <VStack spacing={6}>
              {/* Logo and Title */}
              <Box
                p={6}
                borderRadius="2xl"
                bg="linear-gradient(135deg, rgba(0,194,255,0.1), rgba(0,209,143,0.1))"
                borderWidth="2px"
                borderColor="neon.400"
                display="inline-block"
              >
                <Icon as={FaTruck} color="neon.500" boxSize={12} />
              </Box>

              <VStack spacing={3}>
                <Heading
                  size={{ base: 'xl', md: '2xl' }}
                  color="neon.500"
                  mb={2}
                  textShadow="0 0 20px rgba(0,194,255,0.3)"
                  fontWeight="extrabold"
                >
                  🚚 Driver Login
                </Heading>
                <Text
                  color="text.secondary"
                  fontSize={{ base: 'md', md: 'lg' }}
                  maxW="2xl"
                  mx="auto"
                  lineHeight="1.6"
                >
                  Sign in to your driver account and access your dashboard
                </Text>
                {status === 'loading' && (
                  <Badge
                    colorScheme="blue"
                    variant="solid"
                    size="md"
                    px={4}
                    py={2}
                    borderRadius="full"
                    fontSize="sm"
                    fontWeight="semibold"
                    boxShadow="0 4px 15px rgba(0,194,255,0.3)"
                  >
                    <Icon as={FaClock} mr={2} />
                    Checking authentication status...
                  </Badge>
                )}
              </VStack>

              {/* Trust Badges */}
              <HStack spacing={4} justify="center" flexWrap="wrap">
                <Badge
                  colorScheme="green"
                  variant="solid"
                  size="lg"
                  px={4}
                  py={2}
                  borderRadius="full"
                  fontSize="sm"
                  fontWeight="semibold"
                  boxShadow="0 4px 15px rgba(0,209,143,0.3)"
                >
                  <Icon as={FaShieldAlt} mr={2} />
                  Secure Access
                </Badge>
                <Badge
                  colorScheme="blue"
                  variant="solid"
                  size="lg"
                  px={4}
                  py={2}
                  borderRadius="full"
                  fontSize="sm"
                  fontWeight="semibold"
                  boxShadow="0 4px 15px rgba(0,194,255,0.3)"
                >
                  <Icon as={FaClock} mr={2} />
                  24/7 Available
                </Badge>
                <Badge
                  colorScheme="purple"
                  variant="solid"
                  size="lg"
                  px={4}
                  py={2}
                  borderRadius="full"
                  fontSize="sm"
                  fontWeight="semibold"
                  boxShadow="0 4px 15px rgba(128,90,213,0.3)"
                >
                  <Icon as={FaStar} mr={2} />
                  Professional
                </Badge>
              </HStack>
            </VStack>
          </Box>

          {/* Main Content Grid */}
          <Box w="full">
            <Box
              maxW="4xl"
              mx="auto"
              display="grid"
              gridTemplateColumns={{ base: '1fr', lg: '1fr 1fr' }}
              gap={{ base: 8, lg: 12 }}
              alignItems="center"
            >
              {/* Login Form */}
              <Box>
                <Card
                  w="full"
                  borderRadius="2xl"
                  borderWidth="2px"
                  borderColor="border.primary"
                  bg={cardBg}
                  boxShadow="xl"
                  overflow="hidden"
                  position="relative"
                  _before={{
                    content: '""',
                    position: 'absolute',
                    top: 0,
                    left: 0,
                    right: 0,
                    bottom: 0,
                    borderRadius: '2xl',
                    background:
                      'linear-gradient(135deg, rgba(0,194,255,0.05), rgba(0,209,143,0.05))',
                    pointerEvents: 'none',
                  }}
                >
                  <CardBody
                    p={{ base: 6, md: 8 }}
                    position="relative"
                    zIndex={1}
                  >
                    <VStack spacing={6}>
                      {/* Form Header */}
                      <VStack spacing={3} textAlign="center">
                        <Box
                          p={4}
                          borderRadius="xl"
                          bg="neon.500"
                          color="white"
                          boxSize="60px"
                          display="flex"
                          alignItems="center"
                          justifyContent="center"
                          mx="auto"
                          boxShadow="0 8px 25px rgba(0,194,255,0.3)"
                        >
                          <Icon as={FaSignInAlt} boxSize={6} />
                        </Box>
                        <Heading size="lg" color="text.primary">
                          Welcome Back
                        </Heading>
                        <Text color="text.secondary" fontSize="md">
                          Sign in to your driver account
                        </Text>
                      </VStack>

                      <form onSubmit={handleSubmit} style={{ width: '100%' }}>
                        <VStack spacing={5}>
                          {error && (
                            <VStack spacing={3} w="full">
                              <Alert
                                data-testid="error-message"
                                status="error"
                                borderRadius="xl"
                                borderWidth="1px"
                                borderColor="red.400"
                              >
                                <AlertIcon />
                                {error}
                              </Alert>
                              
                              {showApplyButton && (
                                <Button
                                  as={NextLink}
                                  href="/driver-application"
                                  colorScheme="blue"
                                  size="md"
                                  w="full"
                                  leftIcon={<FaTruck />}
                                  borderRadius="xl"
                                >
                                  Apply to Become Driver
                                </Button>
                              )}
                            </VStack>
                          )}

                          {/* Hidden CSRF token field */}
                          <input
                            type="hidden"
                            name="csrfToken"
                            value={csrfToken}
                          />

                          <FormControl isRequired>
                            <FormLabel
                              fontSize="md"
                              fontWeight="semibold"
                              color="text.primary"
                              display="flex"
                              alignItems="center"
                              gap={2}
                            >
                              <Icon as={FaUser} color="neon.400" />
                              Email Address
                            </FormLabel>
                            <Input
                              data-testid="email-input"
                              type="email"
                              name="email"
                              value={email}
                              onChange={e => setEmail(e.target.value)}
                              placeholder="Enter your email address"
                              size="lg"
                              borderRadius="xl"
                              borderWidth="2px"
                              borderColor="border.primary"
                              bg="bg.surface"
                              _focus={{
                                borderColor: 'neon.400',
                                boxShadow: '0 0 0 1px rgba(0,194,255,0.2)',
                              }}
                              _hover={{
                                borderColor: 'neon.300',
                              }}
                              transition="all 0.2s"
                            />
                          </FormControl>

                          <FormControl isRequired>
                            <FormLabel
                              fontSize="md"
                              fontWeight="semibold"
                              color="text.primary"
                              display="flex"
                              alignItems="center"
                              gap={2}
                            >
                              <Icon as={FaLock} color="neon.400" />
                              Password
                            </FormLabel>
                            <Input
                              data-testid="password-input"
                              type="password"
                              name="password"
                              value={password}
                              onChange={e => setPassword(e.target.value)}
                              placeholder="Enter your password"
                              size="lg"
                              borderRadius="xl"
                              borderWidth="2px"
                              borderColor="border.primary"
                              bg="bg.surface"
                              _focus={{
                                borderColor: 'neon.400',
                                boxShadow: '0 0 0 1px rgba(0,194,255,0.2)',
                              }}
                              _hover={{
                                borderColor: 'neon.300',
                              }}
                              transition="all 0.2s"
                            />
                          </FormControl>

                          <Button
                            data-testid="login-button"
                            type="submit"
                            size="lg"
                            w="full"
                            isLoading={isLoading}
                            bg="linear-gradient(135deg, #00C2FF, #00D18F)"
                            color="white"
                            borderRadius="xl"
                            py={7}
                            fontSize="lg"
                            fontWeight="bold"
                            _hover={{
                              bg: 'linear-gradient(135deg, #00D18F, #00C2FF)',
                              transform: 'translateY(-2px)',
                              boxShadow: '0 8px 25px rgba(0,194,255,0.4)',
                            }}
                            _active={{
                              bg: 'linear-gradient(135deg, #00B8E6, #00C2FF)',
                            }}
                            transition="all 0.3s ease"
                            rightIcon={<FaArrowRight />}
                          >
                            Sign In to Dashboard
                          </Button>
                        </VStack>
                      </form>

                      {/* Additional Links */}
                      <VStack spacing={3} w="full">
                        <Divider borderColor="border.primary" />
                        <Text
                          fontSize="sm"
                          color="text.tertiary"
                          textAlign="center"
                        >
                          <ChakraLink
                            data-testid="forgot-password-link"
                            as={NextLink}
                            href="/driver/forgot"
                            color="neon.400"
                            fontWeight="semibold"
                            _hover={{
                              textDecoration: 'underline',
                              color: 'neon.300',
                            }}
                          >
                            Forgot your password?
                          </ChakraLink>
                        </Text>
                        <Text
                          fontSize="sm"
                          color="text.tertiary"
                          textAlign="center"
                        >
                          Don't have a driver account?{' '}
                          <ChakraLink
                            color="neon.400"
                            fontWeight="semibold"
                            _hover={{
                              textDecoration: 'underline',
                              color: 'neon.300',
                            }}
                          >
                            Contact support
                          </ChakraLink>{' '}
                          to get started.
                        </Text>
                      </VStack>
                    </VStack>
                  </CardBody>
                </Card>
              </Box>

              {/* Benefits Section */}
              <Box>
                <VStack spacing={8} align="start">
                  <VStack spacing={6} align="start">
                    <Heading size="lg" color="text.primary">
                      Why Choose Speedy Van?
                    </Heading>
                    <Text color="text.secondary" fontSize="md" lineHeight="1.6">
                      Join our network of professional drivers and enjoy
                      flexible hours, competitive pay, and the support you need
                      to succeed.
                    </Text>
                  </VStack>

                  <VStack spacing={4} align="start" w="full">
                    {[
                      {
                        icon: FaTruck,
                        title: 'Flexible Scheduling',
                        description:
                          'Choose your own hours and work when it suits you',
                      },
                      {
                        icon: FaMapMarkerAlt,
                        title: 'Nationwide Coverage',
                        description: 'Access to jobs across the entire UK',
                      },
                      {
                        icon: FaClock,
                        title: 'Quick Payments',
                        description:
                          'Get paid within 48 hours of job completion',
                      },
                      {
                        icon: FaShieldAlt,
                        title: 'Full Support',
                        description:
                          '24/7 customer service and technical support',
                      },
                    ].map((benefit, index) => (
                      <Box
                        key={index}
                        p={4}
                        borderRadius="xl"
                        borderWidth="1px"
                        borderColor="border.primary"
                        bg="bg.surface"
                        w="full"
                        _hover={{
                          borderColor: 'neon.400',
                          transform: 'translateX(4px)',
                          boxShadow: '0 4px 20px rgba(0,194,255,0.1)',
                        }}
                        transition="all 0.3s ease"
                      >
                        <HStack spacing={4}>
                          <Box
                            p={3}
                            borderRadius="lg"
                            bg="neon.500"
                            color="white"
                            boxSize="50px"
                            display="flex"
                            alignItems="center"
                            justifyContent="center"
                            flexShrink={0}
                          >
                            <Icon as={benefit.icon} boxSize={5} />
                          </Box>
                          <VStack align="start" spacing={1}>
                            <Text
                              fontWeight="semibold"
                              color="text.primary"
                              fontSize="md"
                            >
                              {benefit.title}
                            </Text>
                            <Text
                              color="text.secondary"
                              fontSize="sm"
                              lineHeight="1.4"
                            >
                              {benefit.description}
                            </Text>
                          </VStack>
                        </HStack>
                      </Box>
                    ))}
                  </VStack>
                </VStack>
              </Box>
            </Box>
          </Box>
        </VStack>
      </Container>
    </Box>
  );
}

'use client';

import React, { useState } from 'react';
import {
  Box,
  Container,
  VStack,
  HStack,
  Heading,
  Text,
  Card,
  CardBody,
  CardHeader,
  FormControl,
  FormLabel,
  Input,
  Textarea,
  Button,
  useToast,
  Spinner,
  Alert,
  AlertIcon,
  SimpleGrid,
  Select,
  Image,
  IconButton,
  Divider,
  Badge,
  Progress,
  Step,
  StepIndicator,
  StepStatus,
  StepIcon,
  StepNumber,
  StepTitle,
  StepDescription,
  Stepper,
  useSteps,
  useBreakpointValue,
  Stack,
  Flex,
} from '@chakra-ui/react';
import { FiUpload, FiX, FiCheck, FiUser, FiTruck, FiCreditCard, FiFileText } from 'react-icons/fi';

interface ApplicationData {
  // Personal Information
  fullName: string;
  email: string;
  phone: string;
  address: string;
  postcode: string;
  
  // Documents
  licenseImage: File | null;
  idImage: File | null;
  
  // Vehicle Information
  vehicleMake: string;
  vehicleModel: string;
  vehicleReg: string;
  vehicleType: string;
  vehicleYear: string;
  
  // Bank Account
  accountHolderName: string;
  bankName: string;
  bankSortCode: string;
  bankAccountNumber: string;
  
  // Tax Information
  utr: string;
  vatNumber: string;
}

const initialData: ApplicationData = {
  fullName: '',
  email: '',
  phone: '',
  address: '',
  postcode: '',
  licenseImage: null,
  idImage: null,
  vehicleMake: '',
  vehicleModel: '',
  vehicleReg: '',
  vehicleType: '',
  vehicleYear: '',
    accountHolderName: '',
  bankName: '',
  bankSortCode: '',
  bankAccountNumber: '',
  utr: '',
  vatNumber: '',
};

const steps = [
  { title: 'Personal Info', description: 'Basic information', icon: FiUser },
  { title: 'Vehicle Details', description: 'Vehicle information', icon: FiTruck },
  { title: 'Bank Details', description: 'Payment information', icon: FiCreditCard },
  { title: 'Documents', description: 'Upload documents', icon: FiFileText },
  { title: 'Review', description: 'Review & submit', icon: FiCheck },
];

export default function DriverApplicationPage() {
  const [formData, setFormData] = useState<ApplicationData>(initialData);
  const [currentStep, setCurrentStep] = useState(0);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [uploadedImages, setUploadedImages] = useState<{ [key: string]: string }>({});
  
  const toast = useToast();
  const isMobile = useBreakpointValue({ base: true, md: false });
  const { activeStep, setActiveStep } = useSteps({
    index: currentStep,
    count: steps.length,
  });

  const handleInputChange = (field: keyof ApplicationData, value: string) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  const handleFileUpload = (field: 'licenseImage' | 'idImage', file: File) => {
    if (file) {
      // In a real app, you'd upload to a file storage service
      const reader = new FileReader();
      reader.onload = (e) => {
        const result = e.target?.result as string;
        setUploadedImages(prev => ({ ...prev, [field]: result }));
        setFormData(prev => ({ ...prev, [field]: file }));
      };
      reader.readAsDataURL(file);
    }
  };

  const removeImage = (field: 'licenseImage' | 'idImage') => {
    setFormData(prev => ({ ...prev, [field]: null }));
    setUploadedImages(prev => {
      const newImages = { ...prev };
      delete newImages[field];
      return newImages;
    });
  };

  const nextStep = () => {
    if (currentStep < steps.length - 1) {
      setCurrentStep(currentStep + 1);
      setActiveStep(currentStep + 1);
    }
  };

  const prevStep = () => {
    if (currentStep > 0) {
      setCurrentStep(currentStep - 1);
      setActiveStep(currentStep - 1);
    }
  };

  const validateStep = (step: number): boolean => {
    switch (step) {
      case 0: // Personal Info
        return !!(formData.fullName && formData.email && formData.phone && formData.address && formData.postcode);
      case 1: // Vehicle Details
        return !!(formData.vehicleMake && formData.vehicleModel && formData.vehicleReg && formData.vehicleType);
      case 2: // Bank Details
        return !!(formData.accountHolderName && formData.bankName && formData.bankSortCode && formData.bankAccountNumber);
      case 3: // Documents
        return !!(formData.licenseImage && formData.idImage);
      case 4: // Review
        return true;
      default:
        return false;
    }
  };

  const handleSubmit = async () => {
    try {
      setIsSubmitting(true);
      
      // Prepare form data for submission
      const submitData = {
        ...formData,
        vehicleInfo: {
          make: formData.vehicleMake,
          model: formData.vehicleModel,
          reg: formData.vehicleReg,
          type: formData.vehicleType,
          year: formData.vehicleYear,
        },
        bankAccount: {
          accountName: formData.accountHolderName,
          bankName: formData.bankName,
          sortCode: formData.bankSortCode,
          accountNumber: formData.bankAccountNumber,
        },
        taxInfo: {
          utr: formData.utr,
          vatNumber: formData.vatNumber,
        },
      };

      const response = await fetch('/api/driver/apply', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(submitData),
      });

      if (!response.ok) {
        throw new Error('Failed to submit application');
      }

      toast({
        title: 'Application Submitted! 🎉',
        description: 'Your driver application has been submitted successfully. We will review it and get back to you soon.',
        status: 'success',
        duration: 5000,
        isClosable: true,
      });

      // Reset form
      setFormData(initialData);
      setCurrentStep(0);
      setActiveStep(0);
      setUploadedImages({});

    } catch (error) {
      console.error('Driver Application Error:', error);
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';
      toast({
        title: 'Application Submission Failed',
        description: `Failed to submit application: ${errorMessage}`,
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setIsSubmitting(false);
    }
  };

  const renderStepContent = () => {
    switch (currentStep) {
      case 0: // Personal Information
        return (
          <VStack spacing={6} align="stretch">
            <Heading size="md">Personal Information</Heading>
            <SimpleGrid columns={{ base: 1, md: 2 }} spacing={4}>
              <FormControl isRequired>
                <FormLabel>Full Name</FormLabel>
                <Input
                  value={formData.fullName}
                  onChange={(e) => handleInputChange('fullName', e.target.value)}
                  placeholder="Enter your full name"
                />
              </FormControl>
              <FormControl isRequired>
                <FormLabel>Email Address</FormLabel>
                <Input
                  type="email"
                  value={formData.email}
                  onChange={(e) => handleInputChange('email', e.target.value)}
                  placeholder="Enter your email"
                />
              </FormControl>
              <FormControl isRequired>
                <FormLabel>Phone Number</FormLabel>
                <Input
                  value={formData.phone}
                  onChange={(e) => handleInputChange('phone', e.target.value)}
                  placeholder="Enter your phone number"
                />
              </FormControl>
              <FormControl isRequired>
                <FormLabel>Postcode</FormLabel>
                <Input
                  value={formData.postcode}
                  onChange={(e) => handleInputChange('postcode', e.target.value)}
                  placeholder="Enter your postcode"
                />
              </FormControl>
            </SimpleGrid>
            <FormControl isRequired>
              <FormLabel>Address</FormLabel>
              <Textarea
                value={formData.address}
                onChange={(e) => handleInputChange('address', e.target.value)}
                placeholder="Enter your full address"
                rows={3}
              />
            </FormControl>
          </VStack>
        );

      case 1: // Vehicle Details
        return (
          <VStack spacing={6} align="stretch">
            <Heading size="md">Vehicle Information</Heading>
            <SimpleGrid columns={{ base: 1, md: 2 }} spacing={4}>
              <FormControl isRequired>
                <FormLabel>Vehicle Make</FormLabel>
                <Input
                  value={formData.vehicleMake}
                  onChange={(e) => handleInputChange('vehicleMake', e.target.value)}
                  placeholder="e.g., Ford, Mercedes"
                />
              </FormControl>
              <FormControl isRequired>
                <FormLabel>Vehicle Model</FormLabel>
                <Input
                  value={formData.vehicleModel}
                  onChange={(e) => handleInputChange('vehicleModel', e.target.value)}
                  placeholder="e.g., Transit, Sprinter"
                />
              </FormControl>
              <FormControl isRequired>
                <FormLabel>Registration Number</FormLabel>
                <Input
                  value={formData.vehicleReg}
                  onChange={(e) => handleInputChange('vehicleReg', e.target.value)}
                  placeholder="e.g., AB12 CDE"
                />
              </FormControl>
              <FormControl isRequired>
                <FormLabel>Vehicle Type</FormLabel>
                <Select
                  value={formData.vehicleType}
                  onChange={(e) => handleInputChange('vehicleType', e.target.value)}
                  placeholder="Select vehicle type"
                >
                  <option value="van">Van</option>
                  <option value="truck">Truck</option>
                  <option value="car">Car</option>
                </Select>
              </FormControl>
              <FormControl>
                <FormLabel>Year</FormLabel>
                <Input
                  value={formData.vehicleYear}
                  onChange={(e) => handleInputChange('vehicleYear', e.target.value)}
                  placeholder="e.g., 2020"
                />
              </FormControl>
            </SimpleGrid>
          </VStack>
        );

      case 2: // Bank Details
        return (
          <VStack spacing={6} align="stretch">
            <Heading size="md">Bank Account Details</Heading>
            <Alert status="info">
              <AlertIcon />
              <Text fontSize="sm">
                Your bank details are encrypted and secure. We use them only for processing your earnings.
              </Text>
            </Alert>
            <SimpleGrid columns={{ base: 1, md: 2 }} spacing={4}>
              <FormControl isRequired>
                <FormLabel>Account Holder Name</FormLabel>
                <Input
                  value={formData.accountHolderName}
                  onChange={(e) => handleInputChange('accountHolderName', e.target.value)}
                  placeholder="Name on bank account"
                />
              </FormControl>
              <FormControl isRequired>
                <FormLabel>Bank Name</FormLabel>
                <Input
                  value={formData.bankName}
                  onChange={(e) => handleInputChange('bankName', e.target.value)}
                  placeholder="e.g., Barclays, HSBC"
                />
              </FormControl>
              <FormControl isRequired>
                <FormLabel>Sort Code</FormLabel>
                <Input
                  value={formData.bankSortCode}
                  onChange={(e) => handleInputChange('bankSortCode', e.target.value)}
                  placeholder="e.g., 12-34-56"
                />
              </FormControl>
              <FormControl isRequired>
                <FormLabel>Account Number</FormLabel>
                <Input
                  value={formData.bankAccountNumber}
                  onChange={(e) => handleInputChange('bankAccountNumber', e.target.value)}
                  placeholder="8-digit account number"
                />
              </FormControl>
            </SimpleGrid>
            <Divider />
            <Heading size="sm">Tax Information (Optional)</Heading>
            <SimpleGrid columns={{ base: 1, md: 2 }} spacing={4}>
              <FormControl>
                <FormLabel>UTR (Unique Tax Reference)</FormLabel>
                <Input
                  value={formData.utr}
                  onChange={(e) => handleInputChange('utr', e.target.value)}
                  placeholder="10-digit UTR"
                />
              </FormControl>
              <FormControl>
                <FormLabel>VAT Number</FormLabel>
                <Input
                  value={formData.vatNumber}
                  onChange={(e) => handleInputChange('vatNumber', e.target.value)}
                  placeholder="9-digit VAT number"
                />
              </FormControl>
            </SimpleGrid>
          </VStack>
        );

      case 3: // Documents
        return (
          <VStack spacing={6} align="stretch">
            <Heading size="md">Required Documents</Heading>
            <Alert status="warning">
              <AlertIcon />
              <Text fontSize="sm">
                Please upload clear, high-quality images of your documents. All documents must be valid and not expired.
              </Text>
            </Alert>
            <SimpleGrid columns={{ base: 1, md: 2 }} spacing={6}>
              <Box>
                <FormLabel>Driving License</FormLabel>
                <Box
                  border="2px dashed"
                  borderColor="gray.300"
                  borderRadius="md"
                  p={4}
                  textAlign="center"
                >
                  {uploadedImages.licenseImage ? (
                    <VStack spacing={2}>
                      <Image
                        src={uploadedImages.licenseImage}
                        alt="Driving License"
                        maxH="200px"
                        borderRadius="md"
                      />
                      <HStack>
                        <Badge colorScheme="green">Uploaded</Badge>
                        <IconButton
                          aria-label="Remove image"
                          icon={<FiX />}
                          size="sm"
                          colorScheme="red"
                          variant="ghost"
                          onClick={() => removeImage('licenseImage')}
                        />
                      </HStack>
                    </VStack>
                  ) : (
                    <VStack spacing={2}>
                      <FiUpload size={24} />
                      <Text fontSize="sm">Click to upload driving license</Text>
                      <Input
                        type="file"
                        accept="image/*"
                        onChange={(e) => {
                          const file = e.target.files?.[0];
                          if (file) handleFileUpload('licenseImage', file);
                        }}
                        display="none"
                        id="license-upload"
                      />
                      <Button
                        as="label"
                        htmlFor="license-upload"
                        size="sm"
                        colorScheme="blue"
                        variant="outline"
                      >
                        Choose File
                      </Button>
                    </VStack>
                  )}
                </Box>
              </Box>
              <Box>
                <FormLabel>ID Document (Passport/ID Card)</FormLabel>
                <Box
                  border="2px dashed"
                  borderColor="gray.300"
                  borderRadius="md"
                  p={4}
                  textAlign="center"
                >
                  {uploadedImages.idImage ? (
                    <VStack spacing={2}>
                      <Image
                        src={uploadedImages.idImage}
                        alt="ID Document"
                        maxH="200px"
                        borderRadius="md"
                      />
                      <HStack>
                        <Badge colorScheme="green">Uploaded</Badge>
                        <IconButton
                          aria-label="Remove image"
                          icon={<FiX />}
                          size="sm"
                          colorScheme="red"
                          variant="ghost"
                          onClick={() => removeImage('idImage')}
                        />
                      </HStack>
                    </VStack>
                  ) : (
                    <VStack spacing={2}>
                      <FiUpload size={24} />
                      <Text fontSize="sm">Click to upload ID document</Text>
                      <Input
                        type="file"
                        accept="image/*"
                        onChange={(e) => {
                          const file = e.target.files?.[0];
                          if (file) handleFileUpload('idImage', file);
                        }}
                        display="none"
                        id="id-upload"
                      />
                      <Button
                        as="label"
                        htmlFor="id-upload"
                        size="sm"
                        colorScheme="blue"
                        variant="outline"
                      >
                        Choose File
                      </Button>
                    </VStack>
                  )}
                </Box>
              </Box>
            </SimpleGrid>
          </VStack>
        );

      case 4: // Review
        return (
          <VStack spacing={6} align="stretch">
            <Heading size="md">Review Your Application</Heading>
            <Text color="gray.600">
              Please review all your information before submitting your application.
            </Text>
            
            <Card>
              <CardHeader>
                <Heading size="sm">Personal Information</Heading>
              </CardHeader>
              <CardBody>
                <SimpleGrid columns={{ base: 1, md: 2 }} spacing={2}>
                  <Text><strong>Name:</strong> {formData.fullName}</Text>
                  <Text><strong>Email:</strong> {formData.email}</Text>
                  <Text><strong>Phone:</strong> {formData.phone}</Text>
                  <Text><strong>Postcode:</strong> {formData.postcode}</Text>
                  <Box gridColumn="span 2">
                    <Text><strong>Address:</strong> {formData.address}</Text>
                  </Box>
                </SimpleGrid>
              </CardBody>
            </Card>

            <Card>
              <CardHeader>
                <Heading size="sm">Vehicle Information</Heading>
              </CardHeader>
              <CardBody>
                <SimpleGrid columns={{ base: 1, md: 2 }} spacing={2}>
                  <Text><strong>Make:</strong> {formData.vehicleMake}</Text>
                  <Text><strong>Model:</strong> {formData.vehicleModel}</Text>
                  <Text><strong>Registration:</strong> {formData.vehicleReg}</Text>
                  <Text><strong>Type:</strong> {formData.vehicleType}</Text>
                  {formData.vehicleYear && <Text><strong>Year:</strong> {formData.vehicleYear}</Text>}
                </SimpleGrid>
              </CardBody>
            </Card>

            <Card>
              <CardHeader>
                <Heading size="sm">Bank Account</Heading>
              </CardHeader>
              <CardBody>
                <SimpleGrid columns={{ base: 1, md: 2 }} spacing={2}>
                  <Text><strong>Account Name:</strong> {formData.accountHolderName}</Text>
                  <Text><strong>Bank:</strong> {formData.bankName}</Text>
                  <Text><strong>Sort Code:</strong> {formData.bankSortCode}</Text>
                  <Text><strong>Account Number:</strong> {formData.bankAccountNumber}</Text>
                </SimpleGrid>
              </CardBody>
            </Card>

            <Card>
              <CardHeader>
                <Heading size="sm">Documents</Heading>
              </CardHeader>
              <CardBody>
                <HStack spacing={4}>
                  <VStack>
                    <Text fontSize="sm">Driving License</Text>
                    {uploadedImages.licenseImage ? (
                      <Badge colorScheme="green">Uploaded</Badge>
                    ) : (
                      <Badge colorScheme="red">Missing</Badge>
                    )}
                  </VStack>
                  <VStack>
                    <Text fontSize="sm">ID Document</Text>
                    {uploadedImages.idImage ? (
                      <Badge colorScheme="green">Uploaded</Badge>
                    ) : (
                      <Badge colorScheme="red">Missing</Badge>
                    )}
                  </VStack>
                </HStack>
              </CardBody>
            </Card>
          </VStack>
        );

      default:
        return null;
    }
  };

  return (
    <Container maxW="container.lg" py={{ base: 4, md: 8 }}>
      <VStack spacing={{ base: 6, md: 8 }} align="stretch">
        <Box textAlign="center">
          <Heading size={{ base: "md", md: "lg" }} mb={2}>Become a Speedy Van Driver</Heading>
          <Text color="gray.600" fontSize={{ base: "sm", md: "md" }}>
            Join our team of professional drivers and start earning today
          </Text>
        </Box>

        <Card>
          <CardBody p={{ base: 4, md: 6 }}>
            <Stepper 
              index={activeStep} 
              colorScheme="blue"
              size={{ base: "sm", md: "md" }}
            >
              {steps.map((step, index) => (
                <Step key={index}>
                  <StepIndicator>
                    <StepStatus
                      complete={<StepIcon />}
                      incomplete={<StepNumber />}
                      active={<StepNumber />}
                    />
                  </StepIndicator>
                  <Box flexShrink="0">
                    <StepTitle fontSize={{ base: "sm", md: "md" }}>{step.title}</StepTitle>
                    <StepDescription fontSize={{ base: "xs", md: "sm" }}>{step.description}</StepDescription>
                  </Box>
                </Step>
              ))}
            </Stepper>
          </CardBody>
        </Card>

        <Card>
          <CardBody p={{ base: 4, md: 6 }}>
            {renderStepContent()}
          </CardBody>
        </Card>

        <Stack direction={{ base: "column", md: "row" }} spacing={{ base: 3, md: 4 }} justify="space-between">
          <Button
            onClick={prevStep}
            isDisabled={currentStep === 0}
            variant="outline"
            size={{ base: "md", md: "lg" }}
            width={{ base: "full", md: "auto" }}
          >
            Previous
          </Button>
          
          {currentStep === steps.length - 1 ? (
            <Button
              onClick={handleSubmit}
              colorScheme="blue"
              isLoading={isSubmitting}
              loadingText="Submitting..."
              isDisabled={!validateStep(currentStep)}
              size={{ base: "md", md: "lg" }}
              width={{ base: "full", md: "auto" }}
            >
              Submit Application
            </Button>
          ) : (
            <Button
              onClick={nextStep}
              colorScheme="blue"
              isDisabled={!validateStep(currentStep)}
              size={{ base: "md", md: "lg" }}
              width={{ base: "full", md: "auto" }}
            >
              Next
            </Button>
            )}
          </Stack>
      </VStack>
    </Container>
  );
}

'use client';

import React, { useEffect, useState } from 'react';
import {
  Box,
  VStack,
  HStack,
  Button,
  Text,
  Alert,
  AlertIcon,
  AlertTitle,
  AlertDescription,
  Card,
  CardHeader,
  CardBody,
  Heading,
  Badge,
  Code,
  useToast,
  Spinner,
} from '@chakra-ui/react';
import { FaPlay, FaCheckCircle, FaExclamationTriangle, FaVolumeUp } from 'react-icons/fa';
import { useSession } from 'next-auth/react';
import { useAudioNotification } from '@/components/driver/AudioNotification';

interface FixResult {
  success: boolean;
  message: string;
  details?: any;
}

export default function AudioNotificationFixPage() {
  const { data: session } = useSession();
  const [driverId, setDriverId] = useState<string>('');
  const [isFixing, setIsFixing] = useState(false);
  const [audioReady, setAudioReady] = useState(false);
  const [fixResults, setFixResults] = useState<FixResult[]>([]);

  const audioNotification = useAudioNotification();
  const toast = useToast();

  // Get driver ID from session
  useEffect(() => {
    const fetchDriverData = async () => {
      if (session?.user) {
        try {
          const response = await fetch('/api/driver/profile');
          if (response.ok) {
            const data = await response.json();
            setDriverId(data.driver?.id || '');
          }
        } catch (error) {
          console.error('Failed to fetch driver data:', error);
        }
      }
    };
    fetchDriverData();
  }, [session]);

  const addFixResult = (result: FixResult) => {
    setFixResults(prev => [result, ...prev.slice(0, 9)]);
  };

  const prepareAudio = async () => {
    try {
      addFixResult({ success: false, message: 'Preparing audio system...' });
      
      await audioNotification.prepareAudio();
      setAudioReady(true);
      
      addFixResult({ 
        success: true, 
        message: '✅ Audio system prepared successfully - now try playing a test sound' 
      });
      
      toast({
        title: 'Audio Prepared',
        description: 'You can now test audio notifications',
        status: 'success',
        duration: 3000,
      });
    } catch (error) {
      addFixResult({ 
        success: false, 
        message: `❌ Failed to prepare audio: ${(error as Error).message}` 
      });
    }
  };

  const testBasicAudio = async () => {
    try {
      addFixResult({ success: false, message: '🔊 Testing basic audio...' });
      
      await audioNotification.play('job-notification');
      
      addFixResult({ 
        success: true, 
        message: '✅ Audio played successfully! Did you hear the sound?' 
      });
      
      toast({
        title: 'Audio Played',
        description: 'If you didn\'t hear a sound, check browser settings',
        status: 'info',
        duration: 5000,
      });
    } catch (error) {
      const errorMsg = (error as Error).message;
      addFixResult({ 
        success: false, 
        message: `❌ Failed to play audio: ${errorMsg}` 
      });

      // Show specific instructions based on error type
      if (errorMsg.includes('user interaction required')) {
        toast({
          title: 'User Interaction Required',
          description: 'Click anywhere on the page first, then try again',
          status: 'warning',
          duration: 7000,
        });
      } else if (errorMsg.includes('not supported')) {
        toast({
          title: 'Browser Does Not Support Audio',
          description: 'Try another browser like Chrome or Firefox',
          status: 'error',
          duration: 7000,
        });
      }
    }
  };

  const testFullNotification = async () => {
    if (!driverId) {
      toast({
        title: 'Error',
        description: 'Cannot find driver ID',
        status: 'error',
        duration: 3000,
      });
      return;
    }

    try {
      setIsFixing(true);
      addFixResult({ success: false, message: '📡 Sending full test notification...' });

      const response = await fetch('/api/admin/fix-driver-audio', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'send-test-job',
          driverId: driverId
        }),
      });

      const result = await response.json();

      if (result.success) {
        addFixResult({ 
          success: true, 
          message: '✅ Full test notification sent! You should see a notification and hear a sound' 
        });
        
        toast({
          title: 'Sent',
          description: 'You will receive a test notification in a few seconds',
          status: 'success',
          duration: 5000,
        });
      } else {
        addFixResult({ 
          success: false, 
          message: `❌ Failed to send notification: ${result.error}` 
        });
      }
    } catch (error) {
      addFixResult({ 
        success: false, 
        message: `❌ Network error: ${(error as Error).message}` 
      });
    } finally {
      setIsFixing(false);
    }
  };

  const checkConfiguration = async () => {
    try {
      addFixResult({ success: false, message: '🔍 Checking system settings...' });

      const response = await fetch('/api/admin/fix-driver-audio', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'check-config' }),
      });

      const result = await response.json();

      if (result.success && result.isConfigured) {
        addFixResult({ 
          success: true, 
          message: '✅ All system settings are correct',
          details: result.config
        });
      } else {
        addFixResult({ 
          success: false, 
          message: `⚠️ Settings issues: ${result.config?.recommendations?.join(', ')}`,
          details: result.config
        });
      }
    } catch (error) {
      addFixResult({ 
        success: false, 
        message: `❌ Failed to check settings: ${(error as Error).message}` 
      });
    }
  };

  const requestNotificationPermission = async () => {
    try {
      addFixResult({ success: false, message: '🔔 Requesting notification permission...' });

      if ('Notification' in window) {
        const permission = await Notification.requestPermission();
        
        if (permission === 'granted') {
          addFixResult({ 
            success: true, 
            message: '✅ Notification permission granted successfully' 
          });

          // Test notification
          new Notification('🎉 Notifications Enabled!', {
            body: 'You will receive notifications when new jobs arrive',
            icon: '/favicon.ico',
          });
        } else {
          addFixResult({ 
            success: false, 
            message: `❌ Notification permission denied: ${permission}` 
          });
        }
      } else {
        addFixResult({ 
          success: false, 
          message: '❌ Browser does not support notifications' 
        });
      }
    } catch (error) {
      addFixResult({ 
        success: false, 
        message: `❌ Error requesting permission: ${(error as Error).message}` 
      });
    }
  };

  if (!session) {
    return (
      <Box p={8}>
        <Alert status="warning">
          <AlertIcon />
          <AlertTitle>Unauthorized</AlertTitle>
          <AlertDescription>
            You must log in as a driver to use this tool.
          </AlertDescription>
        </Alert>
      </Box>
    );
  }

  return (
    <Box p={6} maxW="4xl" mx="auto">
      <VStack spacing={6} align="stretch">
        <Card>
          <CardHeader>
            <HStack spacing={3}>
              <FaVolumeUp size="24px" color="blue" />
              <Heading size="lg">🔧 Driver Audio Notifications Fix</Heading>
            </HStack>
          </CardHeader>
          <CardBody>
            <VStack spacing={4} align="stretch">
              <Alert status="info">
                <AlertIcon />
                <Box>
                  <AlertTitle>Quick Fix Guide</AlertTitle>
                  <AlertDescription>
                    Follow these steps in order to fix audio notification issues
                  </AlertDescription>
                </Box>
              </Alert>

              {/* Status indicators */}
              <HStack spacing={4} wrap="wrap">
                <Badge colorScheme={audioNotification.isSupported ? 'green' : 'red'}>
                  {audioNotification.isSupported ? 'Audio Supported' : 'Audio Not Supported'}
                </Badge>
                <Badge colorScheme={audioReady ? 'green' : 'yellow'}>
                  {audioReady ? 'Audio Ready' : 'Audio Not Ready'}
                </Badge>
                <Badge colorScheme={driverId ? 'green' : 'red'}>
                  {driverId ? `Driver: ${driverId.slice(0, 8)}...` : 'Driver not found'}
                </Badge>
              </HStack>

              {/* Fix steps */}
              <VStack spacing={3} align="stretch">
                <HStack spacing={3}>
                  <Text fontWeight="bold" minW="20px">1.</Text>
                  <Button
                    leftIcon={<FaCheckCircle />}
                    colorScheme="blue"
                    onClick={prepareAudio}
                    isDisabled={!audioNotification.isSupported}
                    size="sm"
                  >
                    Prepare Audio System
                  </Button>
                  <Text fontSize="sm" color="gray.600">
                    (Click here first to enable audio)
                  </Text>
                </HStack>

                <HStack spacing={3}>
                  <Text fontWeight="bold" minW="20px">2.</Text>
                  <Button
                    leftIcon={<FaPlay />}
                    colorScheme="green"
                    onClick={testBasicAudio}
                    isDisabled={!audioReady}
                    size="sm"
                  >
                    Test Basic Audio
                  </Button>
                  <Text fontSize="sm" color="gray.600">
                    (You should hear a notification sound)
                  </Text>
                </HStack>

                <HStack spacing={3}>
                  <Text fontWeight="bold" minW="20px">3.</Text>
                  <Button
                    leftIcon={<FaCheckCircle />}
                    colorScheme="orange"
                    onClick={requestNotificationPermission}
                    size="sm"
                  >
                    Request Notification Permission
                  </Button>
                  <Text fontSize="sm" color="gray.600">
                    (Allow browser to show notifications)
                  </Text>
                </HStack>

                <HStack spacing={3}>
                  <Text fontWeight="bold" minW="20px">4.</Text>
                  <Button
                    leftIcon={isFixing ? <Spinner size="sm" /> : <FaExclamationTriangle />}
                    colorScheme="purple"
                    onClick={testFullNotification}
                    isLoading={isFixing}
                    isDisabled={!driverId}
                    size="sm"
                  >
                    Test Full Notification
                  </Button>
                  <Text fontSize="sm" color="gray.600">
                    (Simulate new job)
                  </Text>
                </HStack>

                <HStack spacing={3}>
                  <Text fontWeight="bold" minW="20px">5.</Text>
                  <Button
                    leftIcon={<FaCheckCircle />}
                    colorScheme="teal"
                    onClick={checkConfiguration}
                    size="sm"
                  >
                    Check Server Settings
                  </Button>
                  <Text fontSize="sm" color="gray.600">
                    (Verify Pusher configuration)
                  </Text>
                </HStack>
              </VStack>
            </VStack>
          </CardBody>
        </Card>

        {/* Results */}
        {fixResults.length > 0 && (
          <Card>
            <CardHeader>
              <Heading size="md">Fix Results</Heading>
            </CardHeader>
            <CardBody>
              <VStack spacing={2} align="stretch">
                {fixResults.map((result, index) => (
                  <Alert
                    key={index}
                    status={result.success ? 'success' : 'error'}
                    variant="left-accent"
                  >
                    <AlertIcon />
                    <Box flex="1">
                      <Text fontSize="sm">{result.message}</Text>
                      {result.details && (
                        <Code fontSize="xs" mt={1} display="block">
                          {JSON.stringify(result.details, null, 2)}
                        </Code>
                      )}
                    </Box>
                  </Alert>
                ))}
              </VStack>
            </CardBody>
          </Card>
        )}

        {/* Instructions */}
        <Card>
          <CardHeader>
            <Heading size="md">Additional Instructions</Heading>
          </CardHeader>
          <CardBody>
            <VStack spacing={3} align="start">
              <Text fontWeight="bold">If the problem persists:</Text>
              <Text>• Make sure system volume is turned up</Text>
              <Text>• Try a different browser (Chrome works best)</Text>
              <Text>• Ensure the browser is not blocking automatic sounds</Text>
              <Text>• Reload the page and try again</Text>
              <Text>• Make sure the site is added to trusted sites</Text>
            </VStack>
          </CardBody>
        </Card>
      </VStack>
    </Box>
  );
}

'use client';

import React, { useEffect, useState } from 'react';
import {
  Box,
  VStack,
  HStack,
  Button,
  Text,
  Badge,
  Switch,
  FormControl,
  FormLabel,
  Alert,
  AlertIcon,
  AlertTitle,
  AlertDescription,
  Card,
  CardHeader,
  CardBody,
  Heading,
  Divider,
  useColorModeValue,
  IconButton,
  Tooltip,
  Code,
} from '@chakra-ui/react';
import { FaPlay, FaStop, FaVolumeUp, FaVolumeMute, FaBell } from 'react-icons/fa';
import { useSession } from 'next-auth/react';
import { useDriverNotifications } from '@/services/driverNotifications';
import { useAudioNotification, showJobNotificationWithSound } from '@/components/driver/AudioNotification';

export default function DriverAudioTestPage() {
  const { data: session } = useSession();
  const [audioEnabled, setAudioEnabled] = useState(true);
  const [testResults, setTestResults] = useState<string[]>([]);
  const [driverId, setDriverId] = useState<string>('');

  const audioNotification = useAudioNotification();
  const driverNotifications = useDriverNotifications(driverId);

  const bg = useColorModeValue('white', 'gray.800');
  const borderColor = useColorModeValue('gray.200', 'gray.600');

  // Get driver ID from session
  useEffect(() => {
    const fetchDriverData = async () => {
      if (session?.user) {
        try {
          const response = await fetch('/api/driver/profile');
          if (response.ok) {
            const data = await response.json();
            setDriverId(data.driver?.id || '');
          }
        } catch (error) {
          console.error('Failed to fetch driver data:', error);
        }
      }
    };

    fetchDriverData();
  }, [session]);

  const addTestResult = (result: string) => {
    const timestamp = new Date().toLocaleTimeString('ar-SA');
    setTestResults(prev => [`[${timestamp}] ${result}`, ...prev.slice(0, 9)]);
  };

  const testBasicAudio = async () => {
    try {
      addTestResult('🔊 Testing basic audio...');
      await audioNotification.play('job-notification');
      addTestResult('✅ Basic audio played successfully');
    } catch (error) {
      addTestResult('❌ Failed to play basic audio: ' + (error as Error).message);
    }
  };

  const testJobNotification = async () => {
    try {
      addTestResult('🔔 Testing job notification...');
      await showJobNotificationWithSound(
        'New Job Available',
        'From Riyadh to Jeddah\nPrice: £45.00 | Distance: 15km',
        { urgent: false }
      );
      addTestResult('✅ Job notification played successfully');
    } catch (error) {
      addTestResult('❌ Failed to play job notification: ' + (error as Error).message);
    }
  };

  const testUrgentNotification = async () => {
    try {
      addTestResult('🚨 Testing urgent notification...');
      await showJobNotificationWithSound(
        '🚨 Urgent Job',
        'From Airport to Hospital\nPrice: £25.00 | Customer: Ahmad Mohammed',
        { urgent: true, requireInteraction: true }
      );
      addTestResult('✅ Urgent notification played successfully');
    } catch (error) {
      addTestResult('❌ Failed urgent notification: ' + (error as Error).message);
    }
  };

  const testServiceNotification = async () => {
    try {
      addTestResult('📡 Testing notification service...');
      await driverNotifications.testNotification();
      addTestResult('✅ Notification service tested successfully');
    } catch (error) {
      addTestResult('❌ Failed notification service: ' + (error as Error).message);
    }
  };

  const stopAudio = () => {
    audioNotification.stop();
    addTestResult('⏹️ Audio stopped');
  };

  const clearResults = () => {
    setTestResults([]);
  };

  const toggleAudio = (enabled: boolean) => {
    setAudioEnabled(enabled);
    driverNotifications.setAudioEnabled(enabled);
    addTestResult(`🔊 Audio notifications ${enabled ? 'enabled' : 'disabled'}`);
  };

  if (!session) {
    return (
      <Box p={8}>
        <Alert status="warning">
          <AlertIcon />
          <AlertTitle>Unauthorized</AlertTitle>
          <AlertDescription>Please log in to access the notification test page</AlertDescription>
        </Alert>
      </Box>
    );
  }

  return (
    <Box p={6} minH="100vh" bg={useColorModeValue('gray.50', 'gray.900')}>
      <VStack spacing={6} maxW="800px" mx="auto">
        
        {/* Header */}
        <Card w="100%" bg={bg} borderColor={borderColor}>
          <CardHeader>
            <HStack justify="space-between">
              <Heading size="md">Driver Audio Notifications Test</Heading>
              <Badge colorScheme={audioEnabled ? 'green' : 'red'}>
                {audioEnabled ? 'Enabled' : 'Disabled'}
              </Badge>
            </HStack>
          </CardHeader>
          <CardBody pt={0}>
            <VStack spacing={4} align="stretch">
              <HStack justify="space-between">
                <Text>Audio Status:</Text>
                <Badge colorScheme={audioNotification.isSupported ? 'green' : 'red'}>
                  {audioNotification.isSupported ? 'Supported' : 'Not supported'}
                </Badge>
              </HStack>
              
              <HStack justify="space-between">
                <Text>Driver ID:</Text>
                <Code>{driverId || 'Not specified'}</Code>
              </HStack>

              <FormControl display="flex" alignItems="center">
                <FormLabel htmlFor="audio-toggle" mb="0">
                  Enable Audio Notifications
                </FormLabel>
                <Switch
                  id="audio-toggle"
                  isChecked={audioEnabled}
                  onChange={(e) => toggleAudio(e.target.checked)}
                />
              </FormControl>
            </VStack>
          </CardBody>
        </Card>

        {/* Test Controls */}
        <Card w="100%" bg={bg} borderColor={borderColor}>
          <CardHeader>
            <Heading size="sm">Notification Tests</Heading>
          </CardHeader>
          <CardBody>
            <VStack spacing={4}>
              <HStack spacing={4} wrap="wrap" justify="center">
                <Button
                  leftIcon={<FaPlay />}
                  colorScheme="blue"
                  onClick={testBasicAudio}
                  isDisabled={!audioNotification.isSupported || !audioEnabled}
                >
                  Test Basic Audio
                </Button>
                
                <Button
                  leftIcon={<FaBell />}
                  colorScheme="green"
                  onClick={testJobNotification}
                  isDisabled={!audioNotification.isSupported || !audioEnabled}
                >
                  Normal Job Notification
                </Button>

                <Button
                  leftIcon={<FaBell />}
                  colorScheme="red"
                  onClick={testUrgentNotification}
                  isDisabled={!audioNotification.isSupported || !audioEnabled}
                >
                  Urgent Notification
                </Button>

                <Button
                  leftIcon={<FaBell />}
                  colorScheme="purple"
                  onClick={testServiceNotification}
                  isDisabled={!audioEnabled}
                >
                  Test Service
                </Button>
              </HStack>

              <Divider />

              <HStack spacing={4}>
                <Tooltip label="Stop all sounds">
                  <IconButton
                    aria-label="Stop audio"
                    icon={<FaStop />}
                    colorScheme="gray"
                    onClick={stopAudio}
                    isDisabled={!audioNotification.isPlaying}
                  />
                </Tooltip>

                <Tooltip label="Clear results">
                  <Button size="sm" onClick={clearResults}>
                    Clear Results
                  </Button>
                </Tooltip>

                <Badge colorScheme={audioNotification.isPlaying ? 'green' : 'gray'}>
                  {audioNotification.isPlaying ? 'Playing' : 'Stopped'}
                </Badge>
              </HStack>
            </VStack>
          </CardBody>
        </Card>

        {/* Audio Support Info */}
        {!audioNotification.isSupported && (
          <Alert status="error">
            <AlertIcon />
            <AlertTitle>Audio Not Supported</AlertTitle>
            <AlertDescription>
              The current browser does not support audio playback. Please use a modern browser like Chrome or Safari.
            </AlertDescription>
          </Alert>
        )}

        {/* Test Results */}
        <Card w="100%" bg={bg} borderColor={borderColor}>
          <CardHeader>
            <HStack justify="space-between">
              <Heading size="sm">Test Results</Heading>
              <Badge>{testResults.length}/10</Badge>
            </HStack>
          </CardHeader>
          <CardBody>
            <VStack spacing={2} align="stretch" maxH="300px" overflowY="auto">
              {testResults.length === 0 ? (
                <Text color="gray.500" textAlign="center">
                  No test results yet
                </Text>
              ) : (
                testResults.map((result, index) => (
                  <Code
                    key={index}
                    p={2}
                    fontSize="sm"
                    borderRadius="md"
                    whiteSpace="pre-wrap"
                  >
                    {result}
                  </Code>
                ))
              )}
            </VStack>
          </CardBody>
        </Card>

        {/* Instructions */}
        <Card w="100%" bg={bg} borderColor={borderColor}>
          <CardHeader>
            <Heading size="sm">Usage Instructions</Heading>
          </CardHeader>
          <CardBody>
            <VStack spacing={3} align="stretch" fontSize="sm">
              <Text>• <strong>Test Basic Audio:</strong> Plays the audio file only without browser notifications</Text>
              <Text>• <strong>Normal Job Notification:</strong> Plays audio with normal browser notification</Text>
              <Text>• <strong>Urgent Notification:</strong> Plays audio with urgent browser notification and vibration</Text>
              <Text>• <strong>Test Service:</strong> Tests the complete notification service with Pusher</Text>
              <Text color="orange.500">
                <strong>Note:</strong> The browser may request permission to play sounds and notifications the first time
              </Text>
            </VStack>
          </CardBody>
        </Card>

      </VStack>
    </Box>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import {
  Box,
  Heading,
  VStack,
  HStack,
  Text,
  Card,
  CardBody,
  Button,
  Badge,
  Flex,
  useToast,
  Spinner,
