'use client';

import React, { useState } from 'react';
import {
  Box,
  Container,
  VStack,
  Heading,
  Text,
  FormControl,
  FormLabel,
  Input,
  Button,
  Alert,
  AlertIcon,
  Card,
  CardBody,
  Link as ChakraLink,
  IconButton,
  HStack,
  Icon,
  useColorModeValue,
  useToast,
} from '@chakra-ui/react';
import { useRouter } from 'next/navigation';
import NextLink from 'next/link';
import {
  FaTruck,
  FaArrowLeft,
  FaEnvelope,
  FaShieldAlt,
  FaCheckCircle,
} from 'react-icons/fa';

export default function DriverForgotPasswordPage() {
  const [email, setEmail] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState(false);
  const router = useRouter();
  const toast = useToast();

  const bgColor = useColorModeValue('white', 'gray.800');
  const cardBg = useColorModeValue('white', 'gray.700');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError('');
    setSuccess(false);

    try {
      console.log('🔐 Submitting password reset request for:', email);
      
      const response = await fetch('/api/driver/auth/forgot', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ email }),
      });

      const result = await response.json();
      console.log('📧 Password reset response:', result);

      if (response.ok) {
        setSuccess(true);
        toast({
          title: 'Reset Link Sent',
          description: 'If an account with that email exists, a password reset link has been sent.',
          status: 'success',
          duration: 5000,
          isClosable: true,
        });
      } else {
        setError(result.error || 'An error occurred. Please try again.');
        toast({
          title: 'Error',
          description: result.error || 'An error occurred. Please try again.',
          status: 'error',
          duration: 5000,
          isClosable: true,
        });
      }
    } catch (error) {
      console.error('❌ Password reset error:', error);
      setError('An error occurred. Please try again.');
      toast({
        title: 'Error',
        description: 'An error occurred. Please try again.',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setIsLoading(false);
    }
  };

  const handleBackClick = () => {
    router.push('/driver-auth');
  };

  if (success) {
    return (
      <Box minH="100vh" bg="gray.50" display="flex" alignItems="center" justifyContent="center" px={4}>
        <Container maxW="md">
          <VStack spacing={6} textAlign="center">
            <Box color="green.500" fontSize="4xl">
              <FaCheckCircle />
            </Box>
            <VStack spacing={2}>
              <Heading size="lg" color="gray.700">
                Check Your Email
              </Heading>
              <Text color="gray.600" fontSize={{ base: "sm", md: "md" }} px={4}>
                If an account with that email exists, a password reset link has been sent to <strong>{email}</strong>.
              </Text>
              <Text color="gray.500" fontSize="sm">
                Please check your inbox and spam folder. The link will expire in 1 hour.
              </Text>
            </VStack>
            
            <VStack spacing={3} w="full">
              <Button
                colorScheme="blue"
                onClick={handleBackClick}
                size={{ base: "md", md: "lg" }}
                w={{ base: "full", md: "auto" }}
              >
                Back to Login
              </Button>
              
              <Button
                variant="outline"
                onClick={() => {
                  setSuccess(false);
                  setEmail('');
                }}
                size={{ base: "md", md: "lg" }}
                w={{ base: "full", md: "auto" }}
              >
                Try Different Email
              </Button>
            </VStack>
          </VStack>
        </Container>
      </Box>
    );
  }

  return (
    <Box minH="100vh" bg="gray.50" display="flex" alignItems="center" justifyContent="center" px={4}>
      <Container maxW="md">
        <VStack spacing={6} textAlign="center">
          <VStack spacing={2}>
            <Box color="blue.500" fontSize="3xl">
              <FaTruck />
            </Box>
            <Heading size="lg" color="gray.700">
              Reset Driver Password
            </Heading>
            <Text color="gray.600" fontSize={{ base: "sm", md: "md" }}>
              Enter your driver email address and we'll send you a password reset link.
            </Text>
          </VStack>

          <Card w="full" bg={cardBg} boxShadow="lg">
            <CardBody p={6}>
              <form onSubmit={handleSubmit}>
                <VStack spacing={5}>
                  {error && (
                    <Alert status="error" borderRadius="lg">
                      <AlertIcon />
                      {error}
                    </Alert>
                  )}

                  <FormControl isRequired>
                    <FormLabel
                      fontSize="md"
                      fontWeight="semibold"
                      color="text.primary"
                      display="flex"
                      alignItems="center"
                      gap={2}
                    >
                      <Icon as={FaEnvelope} color="blue.500" />
                      Driver Email Address
                    </FormLabel>
                    <Input
                      type="email"
                      name="email"
                      value={email}
                      onChange={e => setEmail(e.target.value)}
                      placeholder="Enter your driver email address"
                      size="lg"
                      borderRadius="xl"
                      borderWidth="2px"
                      borderColor="border.primary"
                      bg="bg.surface"
                      _focus={{
                        borderColor: 'blue.500',
                        boxShadow: '0 0 0 1px rgba(59, 130, 246, 0.2)',
                      }}
                      _hover={{
                        borderColor: 'blue.400',
                      }}
                      transition="all 0.2s"
                    />
                  </FormControl>

                  <Button
                    type="submit"
                    colorScheme="blue"
                    size="lg"
                    w="full"
                    isLoading={isLoading}
                    loadingText="Sending Reset Link..."
                    leftIcon={<Icon as={FaShieldAlt} />}
                    borderRadius="xl"
                    fontWeight="semibold"
                    py={6}
                  >
                    Send Reset Link
                  </Button>
                </VStack>
              </form>
            </CardBody>
          </Card>

          <HStack spacing={4} flexWrap="wrap" justify="center">
            <Button
              variant="ghost"
              leftIcon={<Icon as={FaArrowLeft} />}
              onClick={handleBackClick}
              size={{ base: "sm", md: "md" }}
            >
              Back to Login
            </Button>
            
            <ChakraLink as={NextLink} href="/driver-auth" color="blue.500" fontSize="sm">
              Remember your password? Sign in
            </ChakraLink>
          </HStack>

          <Text color="gray.500" fontSize="xs" textAlign="center" maxW="sm">
            If you don't receive an email within a few minutes, check your spam folder or contact support.
          </Text>
        </VStack>
      </Container>
    </Box>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import { 
  Container, 
  Heading, 
  Text, 
  Box, 
  VStack, 
  HStack, 
  Button, 
  useToast,
  Spinner,
  Alert,
  AlertIcon,
  AlertDescription,
  useBreakpointValue,
  Stack,
  Flex,
  SimpleGrid,
  Badge,
  Divider,
  Icon,
  Progress,
  AlertTitle,
  Card,
  CardBody,
  CardHeader,
  Tooltip,
  Link as ChakraLink,
  IconButton,
} from '@chakra-ui/react';
import {
  FaMapMarkerAlt,
  FaUser,
  FaPhone,
  FaClock,
  FaBox,
  FaTruck,
  FaMap,
  FaPhoneAlt,
  FaCheckCircle,
  FaExclamationTriangle,
  FaArrowLeft,
  FaDirections,
  FaCalendar,
  FaMoneyBillWave,
} from 'react-icons/fa';
import Link from 'next/link';
import { DriverShell } from '@/components/driver';
import JobProgressTracker from '@/components/driver/JobProgressTracker';
import MediaUploader from '@/components/driver/MediaUploader';
import MobileJobActions from '@/components/driver/MobileJobActions';
import MobileJobProgress from '@/components/driver/MobileJobProgress';
import SmartNotifications, { createProximityAlert, createStatusUpdateAlert } from '@/components/driver/SmartNotifications';
import useAutoStatusUpdates from '@/hooks/useAutoStatusUpdates';

interface JobDetails {
  id: string;
  reference: string;
  customer: string;
  customerPhone: string;
  customerEmail: string;
  date: string;
  time: string;
  from: string;
  to: string;
  distance: string;
  vehicleType: string;
  items: string;
  estimatedEarnings?: number;
  status: string;
  priority?: string;
  duration?: string;
  crew?: string;
  notes?: string;
  specialInstructions?: string;
  // Multi-drop enhancements
  type?: 'single-drop' | 'multi-drop';
  stops?: Array<{
    type: 'pickup' | 'dropoff';
    address: string;
    time: string;
    contact: string;
    phone: string;
    items: Array<{
      name: string;
      quantity: number;
      weight: number;
      volume: number;
      category: string;
    }>;
    capacityUsed: {
      weight: number;
      volume: number;
      items: number;
    };
  }>;
  vehicle?: {
    type: string;
    capacity: { maxWeight: number; maxVolume: number; maxItems: number };
    currentLoad: { weight: number; volume: number; items: number };
  };
  route?: {
    totalDistance: number;
    totalDuration: number;
    optimization: {
      efficiencyScore: number;
      recommendations: string[];
    };
  };
}

export default function JobDetailsPage({ params }: { params: { id: string } }) {
  const [jobDetails, setJobDetails] = useState<JobDetails | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [isAccepting, setIsAccepting] = useState(false);
  const [currentStep, setCurrentStep] = useState<string>('navigate_to_pickup');
  const [smartAlerts, setSmartAlerts] = useState<any[]>([]);
  const toast = useToast();
  const isMobile = useBreakpointValue({ base: true, md: false });

  // Always call the hook with default values to maintain hooks order
  // This prevents "Hooks called in wrong order" error
  const autoStatusHook = useAutoStatusUpdates({
    jobId: params.id,
    currentStep: currentStep,
    driverId: jobDetails?.id || 'pending', // Safe fallback
    enableGeoTracking: !!jobDetails, // Only enable if job details are loaded
    enableProximityDetection: !!jobDetails,
    proximityRadius: 100, // 100 meters
    autoAdvanceSteps: false, // Manual control for now
    notificationEnabled: !!jobDetails,
  });

  // Load job details
  useEffect(() => {
    if (params.id) {
      loadJobDetails();
    }
  }, [params.id]);

  // Reload job details when page regains focus to ensure latest status
  useEffect(() => {
    const handleFocus = () => {
      if (params.id && jobDetails) {
        console.log('📍 Page refocused, reloading job details...');
        loadJobDetails();
      }
    };

    window.addEventListener('focus', handleFocus);
    return () => window.removeEventListener('focus', handleFocus);
  }, [params.id, jobDetails]);

  const loadJobDetails = async () => {
    try {
      setIsLoading(true);
      setError(null);

      const response = await fetch(`/api/driver/jobs/${params.id}/details`);
      
      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || 'Failed to load job details');
      }

      const data = await response.json();
      
      // Map the API response to the component's expected format
      const mappedJobDetails = {
        id: data.data.id,
        reference: data.data.reference,
        customer: data.data.customer?.name || 'Customer name not available',
        customerPhone: data.data.customer?.phone || 'Phone not available',
        customerEmail: data.data.customer?.email || 'Email not available',
        date: data.data.schedule?.scheduledAt ? new Date(data.data.schedule.scheduledAt).toLocaleDateString() : 'Date not available',
        time: data.data.schedule?.pickupTimeSlot || 'Time not available',
        from: data.data.addresses?.pickup?.line1 || 'Address not available',
        to: data.data.addresses?.dropoff?.line1 || 'Address not available',
        distance: data.data.logistics?.distance ? `${data.data.logistics.distance} miles` : 'Distance not available',
        vehicleType: data.data.logistics?.crewSize || 'Vehicle type not specified',
        items: data.data.items?.map((item: any) => `${item.name} (${item.quantity})`).join(', ') || 'Items not specified',
        estimatedEarnings: (() => {
          // Try multiple sources for earnings
          if (data.data.pricing?.estimatedEarnings && !isNaN(Number(data.data.pricing.estimatedEarnings))) {
            return Number(data.data.pricing.estimatedEarnings);
          }
          if (data.data.pricing?.total && !isNaN(Number(data.data.pricing.total))) {
            return Number(data.data.pricing.total) / 100; // Convert from pence to pounds
          }
          if (data.data.totalGBP && !isNaN(Number(data.data.totalGBP))) {
            return Number(data.data.totalGBP) / 100; // Convert from pence to pounds
          }
          return 0; // Fallback
        })(),
        status: data.data.status || 'UNKNOWN',
        priority: data.data.schedule?.urgency || 'normal',
        duration: data.data.schedule?.estimatedDuration ? `${data.data.schedule.estimatedDuration} minutes` : 'Duration not specified',
        crew: data.data.logistics?.crewSize || 'Crew not specified',
        notes: data.data.metadata?.notes || '',
        specialInstructions: data.data.metadata?.specialInstructions || '',
        // Multi-drop enhancements (mock data for now - will come from API)
        type: data.data.type || 'multi-drop',
        stops: data.data.stops || [
          {
            type: 'pickup',
            address: data.data.addresses?.pickup?.line1 || '123 High Street, London SW1A 1AA',
            time: data.data.schedule?.pickupTimeSlot || '14:00 - 16:00',
            contact: data.data.customer?.name || 'Jane Doe',
            phone: data.data.customer?.phone || '+44 7700 900456',
            items: data.data.items || [
              { name: 'Sofa', quantity: 1, weight: 80, volume: 2.5, category: 'Living Room' },
              { name: 'Dining Table', quantity: 1, weight: 70, volume: 2.0, category: 'Dining' }
            ],
            capacityUsed: { weight: 150, volume: 4.5, items: 2 }
          },
          {
            type: 'dropoff',
            address: data.data.addresses?.dropoff?.line1 || '456 Oxford Street, London W1C 1AP',
            time: '16:00 - 18:00',
            contact: 'Bob Wilson',
            phone: '+44 7700 900789',
            items: [
              { name: 'Sofa', quantity: 1, weight: 80, volume: 2.5, category: 'Living Room' }
            ],
            capacityUsed: { weight: 80, volume: 2.5, items: 1 }
          },
          {
            type: 'dropoff',
            address: '789 Park Lane, London W1K 7AA',
            time: '18:00 - 19:00',
            contact: 'Alice Brown',
            phone: '+44 7700 900111',
            items: [
              { name: 'Dining Table', quantity: 1, weight: 70, volume: 2.0, category: 'Dining' }
            ],
            capacityUsed: { weight: 70, volume: 2.0, items: 1 }
          }
        ],
        vehicle: data.data.vehicle || {
          type: 'Luton Van',
          capacity: { maxWeight: 3500, maxVolume: 14.5, maxItems: 150 },
          currentLoad: { weight: 300, volume: 8.5, items: 4 }
        },
        route: data.data.route || {
          totalDistance: 24.5,
          totalDuration: 185,
          optimization: {
            efficiencyScore: 92,
            recommendations: ['Route optimized for LIFO unloading efficiency']
          }
        }
      };
      
      setJobDetails(mappedJobDetails);
      
      // Set current step from assignment or default
      if (data.data.assignment && data.data.assignment.currentStep) {
        setCurrentStep(data.data.assignment.currentStep);
        console.log('✅ Current step set from assignment:', data.data.assignment.currentStep);
      } else if (data.data.assignment && data.data.assignment.events && data.data.assignment.events.length > 0) {
        const latestEvent = data.data.assignment.events[data.data.assignment.events.length - 1];
        setCurrentStep(latestEvent.step || 'navigate_to_pickup');
        console.log('✅ Current step set from latest event:', latestEvent.step);
      } else {
        setCurrentStep('navigate_to_pickup');
        console.log('✅ Current step set to default: navigate_to_pickup');
      }
      
      console.log('✅ Job details loaded:', data.data);

    } catch (error) {
      console.error('Driver Job Details Error:', error);
      const errorMessage = error instanceof Error ? error.message : 'Failed to load job details';
      setError(errorMessage);
      
      toast({
        title: 'Error Loading Job',
        description: `Failed to load job details: ${errorMessage}`,
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setIsLoading(false);
    }
  };

  const handleAcceptJob = async () => {
    try {
      setIsAccepting(true);
      const response = await fetch(`/api/driver/jobs/${params.id}/accept`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' }
      });

      if (response.ok) {
        toast({
          title: 'Job Accepted!',
          description: 'You have successfully accepted this job.',
          status: 'success',
          duration: 3000,
          isClosable: true,
        });
        
        // Redirect to dashboard after a short delay
        setTimeout(() => {
          window.location.href = '/driver';
        }, 1500);
      } else {
        throw new Error('Failed to accept job');
      }
    } catch (error) {
      console.error('Driver Accept Job Error:', error);
      const errorMessage = error instanceof Error ? error.message : 'Failed to accept job';
      toast({
        title: 'Job Acceptance Failed',
        description: `Failed to accept job: ${errorMessage}`,
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setIsAccepting(false);
    }
  };

  const handleCallCustomer = () => {
    try {
      if (jobDetails?.customerPhone) {
        window.open(`tel:${jobDetails.customerPhone}`, '_self');
      } else {
        toast({
          title: 'No Phone Number',
          description: 'Customer phone number is not available.',
          status: 'warning',
          duration: 3000,
          isClosable: true,
        });
      }
    } catch (error) {
      console.error('Driver Call Customer Error:', error);
      toast({
        title: 'Call Failed',
        description: 'Failed to initiate call. Please try again.',
        status: 'error',
        duration: 3000,
        isClosable: true,
      });
    }
  };

  const handleOpenMap = (address: string) => {
    try {
      if (!address || address.trim() === '') {
        toast({
          title: 'No Address',
          description: 'Address is not available.',
          status: 'warning',
          duration: 3000,
          isClosable: true,
        });
        return;
      }
      
      const encodedAddress = encodeURIComponent(address);
      window.open(`https://maps.google.com/maps?q=${encodedAddress}`, '_blank');
    } catch (error) {
      console.error('Driver Open Map Error:', error);
      toast({
        title: 'Map Failed',
        description: 'Failed to open map. Please try again.',
        status: 'error',
        duration: 3000,
        isClosable: true,
      });
    }
  };

  const handleGetDirections = (from: string, to: string) => {
    try {
      if (!from || from.trim() === '' || !to || to.trim() === '') {
        toast({
          title: 'Missing Addresses',
          description: 'Pickup or dropoff address is not available.',
          status: 'warning',
          duration: 3000,
          isClosable: true,
        });
        return;
      }
      
      const encodedFrom = encodeURIComponent(from);
      const encodedTo = encodeURIComponent(to);
      window.open(`https://maps.google.com/maps/dir/${encodedFrom}/${encodedTo}`, '_blank');
    } catch (error) {
      console.error('Driver Get Directions Error:', error);
      toast({
        title: 'Directions Failed',
        description: 'Failed to get directions. Please try again.',
        status: 'error',
        duration: 3000,
        isClosable: true,
      });
    }
  };

  const handleStepUpdate = async (step: string, notes?: string) => {
    try {
      console.log('🔄 Updating job step:', { jobId: params.id, step, notes });
      
      const response = await fetch(`/api/driver/jobs/${params.id}/update-step`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ step, notes }),
      });

      if (!response.ok) {
        const errorData = await response.json();
        console.error('❌ Step update failed:', errorData);
        throw new Error(errorData.error || 'Failed to update step');
      }

      const result = await response.json();
      console.log('✅ Step update successful:', { step, result });
      
      // Update local state immediately
      setCurrentStep(step);
      
      // Reload job details to ensure we have the latest data
      await loadJobDetails();
      
      // Add smart notification
      const alert = createStatusUpdateAlert(step, false);
      setSmartAlerts(prev => [alert, ...prev.slice(0, 4)]); // Keep last 5 alerts

      // Show success toast
      toast({
        title: 'Step Updated',
        description: `Successfully updated to: ${step.replace(/_/g, ' ').replace(/\b\w/g, l => l.toUpperCase())}`,
        status: 'success',
        duration: 3000,
      });

      return result;
    } catch (error) {
      console.error('❌ Step update error:', error);
      toast({
        title: 'Update Failed',
        description: 'Failed to update job step. Please try again.',
        status: 'error',
        duration: 5000,
      });
      throw error;
    }
  };

  const handleCustomerTrackingUpdate = async (dropId: string, status: string) => {
    try {
      console.log('📍 Updating customer tracking:', { jobId: params.id, dropId, status });

      const response = await fetch(`/api/driver/jobs/${params.id}/tracking`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ dropId, status }),
      });

      if (!response.ok) {
        const errorData = await response.json();
        console.error('❌ Customer tracking update failed:', errorData);
        throw new Error(errorData.error || 'Failed to update customer tracking');
      }

      const result = await response.json();
      console.log('✅ Customer tracking update successful:', { dropId, status, result });

      // Refresh job details to get updated tracking information
      await loadJobDetails();

    } catch (error) {
      console.error('❌ Customer tracking update error:', error);
      toast({
        title: 'Tracking Update Failed',
        description: error instanceof Error ? error.message : 'Failed to update customer tracking',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    }
  };

  const handleNotificationAction = (alertId: string, action: string) => {
    console.log('Notification action:', { alertId, action });
    
    // Remove the alert after action
    setSmartAlerts(prev => prev.filter(alert => alert.id !== alertId));
  };

  const handleDismissNotification = (alertId: string) => {
    setSmartAlerts(prev => prev.filter(alert => alert.id !== alertId));
  };

  if (isLoading) {
    return (
      <Box minH="100vh" bg="gray.50">
        <Container maxW="7xl" py={{ base: 6, md: 8 }}>
          <VStack spacing={{ base: 6, md: 8 }} align="center">
            <Spinner size="xl" color="blue.500" />
            <Text fontSize={{ base: "md", md: "lg" }}>Loading job details...</Text>
          </VStack>
        </Container>
      </Box>
    );
  }

  if (error) {
    return (
      <Box minH="100vh" bg="gray.50">
        <Container maxW="7xl" py={{ base: 6, md: 8 }}>
          <Alert status="error" borderRadius="lg">
            <AlertIcon />
            <Box>
              <AlertDescription fontSize={{ base: "sm", md: "md" }}>{error}</AlertDescription>
              <Button mt={3} size={{ base: "sm", md: "md" }} onClick={loadJobDetails}>
                Try Again
              </Button>
            </Box>
          </Alert>
        </Container>
      </Box>
    );
  }

  if (!jobDetails) {
    return (
      <Box minH="100vh" bg="gray.50">
        <Container maxW="7xl" py={{ base: 6, md: 8 }}>
          <Alert status="warning" borderRadius="lg">
            <AlertIcon />
            <AlertDescription fontSize={{ base: "sm", md: "md" }}>Job details not found.</AlertDescription>
          </Alert>
        </Container>
      </Box>
    );
  }

  return (
    <DriverShell
      title={`Job ${jobDetails?.reference || 'Details'}`}
      subtitle={`Status: ${jobDetails?.status?.toUpperCase() || 'Loading...'}`}
      actions={
        <HStack spacing={2}>
          <Text fontSize="sm" color="text.secondary">
            Last updated: {new Date().toLocaleTimeString()}
          </Text>
          <Tooltip label="Back to jobs list">
            <Link href="/driver/jobs">
              <IconButton
                size="sm"
                variant="outline"
                icon={<FaArrowLeft />}
                aria-label="Back to jobs"
              />
            </Link>
          </Tooltip>
        </HStack>
      }
    >
      <VStack spacing={{ base: 6, md: 8 }} align="stretch">

          {/* Job Header */}
          <Card
            bg="bg.card"
            border="1px solid"
            borderColor="border.primary"
            borderRadius="xl"
            boxShadow="md"
            overflow="hidden"
            _before={{
              content: '""',
              position: 'absolute',
              inset: 0,
              borderRadius: 'xl',
              padding: '1px',
              background: 'linear-gradient(135deg, rgba(0,194,255,0.2), rgba(0,209,143,0.2))',
              WebkitMask: 'linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0)',
              WebkitMaskComposite: 'xor',
              maskComposite: 'exclude',
              pointerEvents: 'none',
            }}
          >
            <CardHeader bg="bg.surface" borderBottom="1px solid" borderColor="border.primary" p={{ base: 4, md: 6 }}>
              <Flex 
                justify="space-between" 
                align={{ base: "start", md: "center" }} 
                direction={{ base: "column", md: "row" }}
                gap={4}
              >
                <VStack align="start" spacing={2} flex="1">
                  <Heading size={{ base: "md", md: "lg" }} color="text.primary" noOfLines={2}>
                    {jobDetails.reference || 'Job Reference Not Available'}
                  </Heading>
                  <HStack spacing={2} wrap="wrap">
                    <Badge colorScheme="blue" size={{ base: "md", md: "lg" }} px={3} py={1}>
                      {jobDetails.status?.toUpperCase() || 'UNKNOWN'}
                    </Badge>
                    {jobDetails.priority && (
                      <Badge 
                        colorScheme={jobDetails.priority === 'urgent' ? 'red' : jobDetails.priority === 'high' ? 'orange' : 'green'} 
                        size={{ base: "md", md: "lg" }} 
                        px={3} 
                        py={1}
                      >
                        {jobDetails.priority?.toUpperCase() || 'NORMAL'}
                      </Badge>
                    )}
                  </HStack>
                </VStack>
                <VStack align={{ base: "start", md: "end" }} spacing={1}>
                  <Text fontSize={{ base: "2xl", md: "3xl" }} fontWeight="bold" color="brand.500">
                    £{isNaN(Number(jobDetails.estimatedEarnings)) ? '0.00' : Number(jobDetails.estimatedEarnings).toFixed(2)}
                  </Text>
                  <Text fontSize="sm" color="text.secondary">
                    Estimated Earnings
                  </Text>
                </VStack>
              </Flex>
            </CardHeader>
            <CardBody p={6}>
              <SimpleGrid columns={{ base: 1, md: 2 }} spacing={6}>
                {/* Customer Information */}
                <Box>
                  <Heading size="md" mb={4} color="blue.600" display="flex" alignItems="center" gap={2}>
                    <Icon as={FaUser} />
                    Customer Information
                  </Heading>
                  <VStack align="stretch" spacing={3}>
                    <HStack>
                      <Icon as={FaUser} color="blue.500" boxSize={4} />
                      <Text fontWeight="medium">{jobDetails.customer || 'Customer name not available'}</Text>
                    </HStack>
                    <HStack>
                      <Icon as={FaPhone} color="blue.500" boxSize={4} />
                      <Text>{jobDetails.customerPhone || 'Phone not available'}</Text>
                      <Tooltip label="Call Customer">
                        <IconButton
                          aria-label="Call customer"
                          icon={<FaPhoneAlt />}
                          size="sm"
                          colorScheme="blue"
                          variant="ghost"
                          onClick={handleCallCustomer}
                        />
                      </Tooltip>
                    </HStack>
                    <HStack>
                      <Icon as={FaUser} color="blue.500" boxSize={4} />
                      <Text fontSize="sm" color="gray.600">{jobDetails.customerEmail || 'Email not available'}</Text>
                    </HStack>
                  </VStack>
                </Box>

                {/* Job Schedule */}
                <Box>
                  <Heading size="md" mb={4} color="purple.600" display="flex" alignItems="center" gap={2}>
                    <Icon as={FaCalendar} />
                    Schedule
                  </Heading>
                  <VStack align="stretch" spacing={3}>
                    <HStack>
                      <Icon as={FaClock} color="purple.500" boxSize={4} />
                      <Text>{jobDetails.date || 'Date not available'} at {jobDetails.time || 'Time not available'}</Text>
                    </HStack>
                    {jobDetails.duration && (
                      <HStack>
                        <Icon as={FaClock} color="purple.500" boxSize={4} />
                        <Text>Duration: {jobDetails.duration || 'Not specified'}</Text>
                      </HStack>
                    )}
                    {jobDetails.crew && (
                      <HStack>
                        <Icon as={FaUser} color="purple.500" boxSize={4} />
                        <Text>Crew: {jobDetails.crew || 'Not specified'}</Text>
                      </HStack>
                    )}
                  </VStack>
                </Box>
              </SimpleGrid>
            </CardBody>
          </Card>

          {/* Locations */}
          {!isMobile && (
            <SimpleGrid columns={{ base: 1, lg: 2 }} spacing={6}>
              {/* Pickup Location */}
              <Card borderRadius="xl" boxShadow="lg" overflow="hidden">
                <CardHeader bg="green.50" borderBottom="1px solid" borderColor="green.100">
                  <Heading size="md" color="green.600" display="flex" alignItems="center" gap={2}>
                    <Icon as={FaMapMarkerAlt} />
                    Pickup Location
                  </Heading>
                </CardHeader>
                <CardBody p={6}>
                <VStack align="stretch" spacing={4}>
                  <Text fontWeight="medium" fontSize="lg">
                    {jobDetails.from || 'Address not available'}
                  </Text>
                  <HStack spacing={2}>
                    <Button
                      size="sm"
                      colorScheme="green"
                      leftIcon={<FaMap />}
                      onClick={() => handleOpenMap(jobDetails.from)}
                    >
                      View on Map
                    </Button>
                    <Button
                      size="sm"
                      variant="outline"
                      colorScheme="green"
                      leftIcon={<FaDirections />}
                      onClick={() => handleGetDirections("Current Location", jobDetails.from)}
                    >
                      Get Directions
                    </Button>
                  </HStack>
                </VStack>
              </CardBody>
            </Card>

            {/* Dropoff Location */}
            <Card borderRadius="xl" boxShadow="lg" overflow="hidden">
              <CardHeader bg="red.50" borderBottom="1px solid" borderColor="red.100">
                <Heading size="md" color="red.600" display="flex" alignItems="center" gap={2}>
                  <Icon as={FaMapMarkerAlt} />
                  Dropoff Location
                </Heading>
              </CardHeader>
              <CardBody p={6}>
                <VStack align="stretch" spacing={4}>
                  <Text fontWeight="medium" fontSize="lg">
                    {jobDetails.to || 'Address not available'}
                  </Text>
                  <HStack spacing={2}>
                    <Button
                      size="sm"
                      colorScheme="red"
                      leftIcon={<FaMap />}
                      onClick={() => handleOpenMap(jobDetails.to)}
                    >
                      View on Map
                    </Button>
                    <Button
                      size="sm"
                      variant="outline"
                      colorScheme="red"
                      leftIcon={<FaDirections />}
                      onClick={() => handleGetDirections(jobDetails.from, jobDetails.to)}
                    >
                      Get Directions
                    </Button>
                  </HStack>
                </VStack>
              </CardBody>
            </Card>
            </SimpleGrid>
          )}

          {/* Job Details */}
          <Card borderRadius="xl" boxShadow="lg" overflow="hidden">
            <CardHeader bg="purple.50" borderBottom="1px solid" borderColor="purple.100">
              <Heading size="md" color="purple.600" display="flex" alignItems="center" gap={2}>
                <Icon as={FaTruck} />
                Job Details
              </Heading>
            </CardHeader>
            <CardBody p={6}>
              <SimpleGrid columns={{ base: 1, md: 2 }} spacing={6}>
                <VStack align="stretch" spacing={4}>
                  <HStack>
                    <Icon as={FaTruck} color="purple.500" boxSize={4} />
                    <Text>Vehicle: {jobDetails.vehicleType || 'Not specified'}</Text>
                  </HStack>
                  <HStack>
                    <Icon as={FaBox} color="purple.500" boxSize={4} />
                    <Text>Items: {jobDetails.items || 'Not specified'}</Text>
                  </HStack>
                  <HStack>
                    <Icon as={FaMapMarkerAlt} color="purple.500" boxSize={4} />
                    <Text>Distance: {jobDetails.distance || 'Not specified'}</Text>
                  </HStack>
                </VStack>
                <VStack align="stretch" spacing={4}>
                  {jobDetails.notes && (
                    <Box>
                      <Text fontWeight="medium" mb={2}>Notes:</Text>
                      <Text fontSize="sm" color="gray.600">{jobDetails.notes || 'No notes available'}</Text>
                    </Box>
                  )}
                  {jobDetails.specialInstructions && (
                    <Box>
                      <Text fontWeight="medium" mb={2}>Special Instructions:</Text>
                      <Text fontSize="sm" color="gray.600">{jobDetails.specialInstructions || 'No special instructions'}</Text>
                    </Box>
                  )}
                </VStack>
              </SimpleGrid>
            </CardBody>
          </Card>

          {/* Smart Notifications */}
          {smartAlerts.length > 0 && (
            <SmartNotifications
              alerts={smartAlerts}
              onActionClick={handleNotificationAction}
              onDismiss={handleDismissNotification}
              maxVisible={3}
              compactMode={isMobile}
            />
          )}

          {/* Mobile Job Progress Tracker */}
          {isMobile && (
            <MobileJobProgress
              currentStep={currentStep}
              jobId={params.id}
              onStepUpdate={handleStepUpdate}
              isCompact={false}
              showEstimates={true}
            />
          )}
          
          {/* Debug info for development */}
          {process.env.NODE_ENV === 'development' && (
            <Card bg="gray.50" borderRadius="md" p={3}>
              <Text fontSize="sm" color="gray.600">
                Debug: Current Step = <strong>{currentStep}</strong> | Job Status = <strong>{jobDetails?.status}</strong>
              </Text>
            </Card>
          )}

          {/* Multi-Drop Route Summary */}
          {jobDetails.type === 'multi-drop' && jobDetails.stops && jobDetails.stops.length > 1 && (
            <Card borderRadius="xl" boxShadow="lg" overflow="hidden">
              <CardHeader bg="purple.50" borderBottom="1px solid" borderColor="purple.100">
                <Flex justify="space-between" align="center">
                  <Heading size="md" color="purple.800">📍 Multi-Stop Route Summary</Heading>
                  <Badge colorScheme="purple" variant="subtle">
                    {jobDetails.stops.length} stops
                  </Badge>
                </Flex>
              </CardHeader>
              <CardBody>
                <VStack spacing={4} align="stretch">
                  {/* Route Overview */}
                  <SimpleGrid columns={{ base: 1, md: 3 }} spacing={4}>
                    <Box textAlign="center" p={3} bg="blue.50" borderRadius="lg">
                      <Icon as={FaMapMarkerAlt} boxSize={6} color="blue.500" mb={2} />
                      <Text fontSize="2xl" fontWeight="bold" color="blue.700">
                        {jobDetails.route?.totalDistance.toFixed(1) || '24.5'} km
                      </Text>
                      <Text fontSize="sm" color="blue.600">Total Distance</Text>
                    </Box>
                    <Box textAlign="center" p={3} bg="green.50" borderRadius="lg">
                      <Icon as={FaClock} boxSize={6} color="green.500" mb={2} />
                      <Text fontSize="2xl" fontWeight="bold" color="green.700">
                        {jobDetails.route ? Math.round(jobDetails.route.totalDuration / 60) : 3}h
                      </Text>
                      <Text fontSize="sm" color="green.600">Estimated Duration</Text>
                    </Box>
                    <Box textAlign="center" p={3} bg="orange.50" borderRadius="lg">
                      <Icon as={FaTruck} boxSize={6} color="orange.500" mb={2} />
                      <Text fontSize="2xl" fontWeight="bold" color="orange.700">
                        {jobDetails.vehicle?.currentLoad.items || 4}
                      </Text>
                      <Text fontSize="sm" color="orange.600">Items Loaded</Text>
                    </Box>
                  </SimpleGrid>

                  {/* Capacity Utilization */}
                  <Box>
                    <Text fontWeight="semibold" mb={3}>Vehicle Capacity</Text>
                    <VStack spacing={3}>
                      <Flex justify="space-between" align="center" w="full">
                        <Text fontSize="sm">Weight:</Text>
                        <HStack spacing={2}>
                          <Text fontSize="sm">
                            {jobDetails.vehicle?.currentLoad.weight || 300}kg /
                            {jobDetails.vehicle?.capacity.maxWeight || 3500}kg
                          </Text>
                          <Progress
                            value={((jobDetails.vehicle?.currentLoad.weight || 300) / (jobDetails.vehicle?.capacity.maxWeight || 3500)) * 100}
                            size="sm"
                            colorScheme="blue"
                            w="60px"
                          />
                        </HStack>
                      </Flex>
                      <Flex justify="space-between" align="center" w="full">
                        <Text fontSize="sm">Volume:</Text>
                        <HStack spacing={2}>
                          <Text fontSize="sm">
                            {jobDetails.vehicle?.currentLoad.volume || 8.5}m³ /
                            {jobDetails.vehicle?.capacity.maxVolume || 14.5}m³
                          </Text>
                          <Progress
                            value={((jobDetails.vehicle?.currentLoad.volume || 8.5) / (jobDetails.vehicle?.capacity.maxVolume || 14.5)) * 100}
                            size="sm"
                            colorScheme="green"
                            w="60px"
                          />
                        </HStack>
                      </Flex>
                    </VStack>
                  </Box>

                  {/* Stop-by-Stop Breakdown */}
                  <Box>
                    <Text fontWeight="semibold" mb={3}>Route Stops</Text>
                    <VStack spacing={3} align="stretch">
                      {jobDetails.stops.map((stop, index) => (
                        <Box key={index} p={3} border="1px solid" borderColor="gray.200" borderRadius="lg" bg={stop.type === 'pickup' ? 'blue.50' : 'green.50'}>
                          <Flex justify="space-between" align="center" mb={2}>
                            <HStack>
                              <Badge colorScheme={stop.type === 'pickup' ? 'blue' : 'green'} variant="solid">
                                {stop.type === 'pickup' ? 'Pickup' : `Drop ${index}`}
                              </Badge>
                              <Text fontWeight="medium">{stop.contact}</Text>
                            </HStack>
                            <Text fontSize="sm" color="gray.600">{stop.time}</Text>
                          </Flex>
                          <Text fontSize="sm" color="gray.700" mb={2}>{stop.address}</Text>
                          <HStack spacing={4}>
                            <Text fontSize="xs" color="gray.600">
                              📦 {stop.capacityUsed.items} items
                            </Text>
                            <Text fontSize="xs" color="gray.600">
                              ⚖️ {stop.capacityUsed.weight}kg
                            </Text>
                            <Text fontSize="xs" color="gray.600">
                              📏 {stop.capacityUsed.volume}m³
                            </Text>
                          </HStack>
                          {stop.items && stop.items.length > 0 && (
                            <HStack spacing={1} mt={2} flexWrap="wrap">
                              {stop.items.slice(0, 3).map((item, itemIndex) => (
                                <Badge key={itemIndex} size="sm" variant="outline" fontSize="xs">
                                  {item.name} (x{item.quantity})
                                </Badge>
                              ))}
                              {stop.items.length > 3 && (
                                <Badge size="sm" variant="outline" fontSize="xs">
                                  +{stop.items.length - 3} more
                                </Badge>
                              )}
                            </HStack>
                          )}
                        </Box>
                      ))}
                    </VStack>
                  </Box>

                  {/* Route Recommendations */}
                  {jobDetails.route?.optimization.recommendations && jobDetails.route.optimization.recommendations.length > 0 && (
                    <Alert status="info" borderRadius="lg">
                      <AlertIcon />
                      <Box>
                        <AlertTitle>Route Optimization Tips</AlertTitle>
                        <VStack align="start" spacing={1} mt={2}>
                          {jobDetails.route.optimization.recommendations.map((rec, index) => (
                            <Text key={index} fontSize="sm">• {rec}</Text>
                          ))}
                        </VStack>
                      </Box>
                    </Alert>
                  )}
                </VStack>
              </CardBody>
            </Card>
          )}

          {/* Desktop Job Progress Tracker */}
          {!isMobile && (
            <JobProgressTracker
              currentStep={currentStep}
              completedSteps={[]} // Steps before currentStep are automatically marked as completed
              onStepComplete={handleStepUpdate}
              onCustomerTrackingUpdate={handleCustomerTrackingUpdate}
              jobId={params.id}
              route={{
                id: params.id,
                drops: (jobDetails.stops || []).map((stop: any, index: number) => ({
                  id: stop.id || `drop-${index + 1}`,
                  sequence: index + 1,
                  pickupAddress: stop.address,
                  dropoffAddress: stop.address,
                  customerName: stop.contact,
                  customerPhone: stop.phone,
                  items: stop.items || [],
                  status: stop.type === 'pickup' ? 'loading' : 'unloading',
                })),
                totalDrops: jobDetails.stops?.length || 1,
              }}
            />
          )}

          {/* Action Buttons */}
          {jobDetails.status === 'available' && (
            <Card borderRadius="xl" boxShadow="lg" overflow="hidden">
              <CardBody p={6}>
                <VStack spacing={4}>
                  <Button
                    colorScheme="green"
                    size="xl"
                    width="full"
                    leftIcon={<FaCheckCircle />}
                    onClick={handleAcceptJob}
                    isLoading={isAccepting}
                    loadingText="Accepting Job..."
                    borderRadius="xl"
                    fontWeight="bold"
                    py={8}
                    _hover={{
                      transform: 'translateY(-2px)',
                      boxShadow: 'xl',
                    }}
                  >
                    Accept This Job
                  </Button>
                  <Text fontSize="sm" color="gray.600" textAlign="center">
                    By accepting this job, you agree to complete the delivery as scheduled.
                  </Text>
                </VStack>
              </CardBody>
            </Card>
          )}
        </VStack>
      </DriverShell>
  );
}

﻿'use client';

import React, { useState, useEffect, useMemo } from 'react';
import {
  Container,
  Heading,
  Text,
  Box,
  VStack,
  HStack,
  Button,
  useToast,
  Spinner,
  Alert,
  AlertIcon,
  AlertDescription,
  useBreakpointValue,
  Stack,
  Flex,
  SimpleGrid,
  Badge,
  Input,
  InputGroup,
  InputLeftElement,
  Select,
  IconButton,
  Tooltip,
} from '@chakra-ui/react';
import { FaSearch, FaFilter } from 'react-icons/fa';
import { FiRefreshCw } from 'react-icons/fi';
import { EnhancedJobCard } from '@/components/driver/EnhancedJobCard';
import { NoJobsMessage } from '@/components/driver/NoJobsMessage';
import { RouteCard, Route } from '@/components/driver/RouteCard';
import { DriverShell } from '@/components/driver';
import { useOptimizedDataLoader } from '@/hooks/useOptimizedDataLoader';
import { useDebounce } from '@/hooks/useDebounce';

interface Job {
  id: string;
  reference: string;
  customer: string;
  customerPhone: string;
  date: string;
  time: string;
  from: string;
  to: string;
  distance: string;
  vehicleType: string;
  items: string;
  estimatedEarnings: number;
  status: string;
  priority?: string;
  duration?: string;
  crew?: string;
}

interface JobsData {
  jobs: Job[];
  total: number;
  available: number;
  assigned: number;
}

interface RoutesData {
  routes: Route[];
  metadata: {
    total: number;
  };
}

export default function DriverJobsPage() {
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState('all');
  const toast = useToast();
  const isMobile = useBreakpointValue({ base: true, md: false });

  // Debounced search term
  const debouncedSearchTerm = useDebounce(searchTerm, 300);

  // Use optimized data loader for jobs
  const { data: jobsData, loading: isLoading, error, refetch } = useOptimizedDataLoader<JobsData>({
    endpoint: '/api/driver/jobs',
    debounceMs: 300,
    cacheKey: 'driver-jobs',
    enabled: true
  });

  // Use optimized data loader for routes
  const { data: routesData, loading: isLoadingRoutes, error: routesError, refetch: refetchRoutes } = useOptimizedDataLoader<RoutesData>({
    endpoint: '/api/driver/routes',
    debounceMs: 300,
    cacheKey: 'driver-routes',
    enabled: true
  });

  // Optimized filtering with useMemo
  const filteredJobs = useMemo(() => {
    if (!jobsData?.jobs || !Array.isArray(jobsData.jobs)) return [];

    let filtered = jobsData.jobs;

    // Filter by search term
    if (debouncedSearchTerm) {
      filtered = filtered.filter(job => 
        job.customer.toLowerCase().includes(debouncedSearchTerm.toLowerCase()) ||
        job.reference.toLowerCase().includes(debouncedSearchTerm.toLowerCase()) ||
        job.from.toLowerCase().includes(debouncedSearchTerm.toLowerCase()) ||
        job.to.toLowerCase().includes(debouncedSearchTerm.toLowerCase())
      );
    }

    // Filter by status
    if (statusFilter !== 'all') {
      filtered = filtered.filter(job => job.status === statusFilter);
    }

    return filtered;
  }, [jobsData?.jobs, debouncedSearchTerm, statusFilter]);

  // Show toast for errors
  useEffect(() => {
    if (error) {
      console.error('Driver Jobs Error:', error);
      toast({
        title: 'Error Loading Jobs',
        description: 'Failed to load jobs data. Please try again.',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    }
  }, [error, toast]);

  const handleAcceptJob = async (jobId: string) => {
    try {
      const response = await fetch(`/api/driver/jobs/${jobId}/accept`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' }
      });

      if (response.ok) {
        toast({
          title: 'Job Accepted!',
          description: 'You have successfully accepted this job.',
          status: 'success',
          duration: 3000,
          isClosable: true,
        });
        
        // Refresh jobs data
        refetch();
      } else {
        throw new Error('Failed to accept job');
      }
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to accept job. Please try again.',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    }
  };

  const handleDeclineJob = async (jobId: string) => {
    try {
      const response = await fetch(`/api/driver/jobs/${jobId}/decline`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ reason: 'Driver declined' })
      });

      if (response.ok) {
        toast({
          title: 'Job Declined',
          description: 'You have declined this job.',
          status: 'info',
          duration: 3000,
          isClosable: true,
        });
        
        // Refresh jobs data
        refetch();
      } else {
        throw new Error('Failed to decline job');
      }
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to decline job. Please try again.',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    }
  };

  const handleAcceptRoute = async (routeId: string) => {
    try {
      const response = await fetch(`/api/driver/routes/${routeId}/accept`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' }
      });

      if (response.ok) {
        const data = await response.json();
        toast({
          title: 'Route Accepted!',
          description: `You have accepted a route with ${data.data?.dropCount || 0} stops.`,
          status: 'success',
          duration: 4000,
          isClosable: true,
        });
        
        // Refresh both jobs and routes data
        refetch();
        refetchRoutes();
        
        // Trigger schedule refresh event
        window.dispatchEvent(new Event('jobAccepted'));
        
        // Redirect to schedule/progress page after 1 second
        setTimeout(() => {
          window.location.href = `/driver/routes/${routeId}/progress`;
        }, 1000);
      } else {
        const errorData = await response.json();
        throw new Error(errorData.error || 'Failed to accept route');
      }
    } catch (error) {
      toast({
        title: 'Error',
        description: error instanceof Error ? error.message : 'Failed to accept route. Please try again.',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    }
  };

  const handleDeclineRoute = async (routeId: string) => {
    try {
      const response = await fetch(`/api/driver/routes/${routeId}/decline`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ reason: 'Driver declined' })
      });

      if (response.ok) {
        const data = await response.json();
        toast({
          title: 'Route Declined',
          description: data.warning || 'Route declined and offered to other drivers.',
          status: 'warning',
          duration: 5000,
          isClosable: true,
        });
        
        // Refresh both jobs and routes data
        refetch();
        refetchRoutes();
      } else {
        throw new Error('Failed to decline route');
      }
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to decline route. Please try again.',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    }
  };

  if (isLoading) {
    return (
      <DriverShell title="All Jobs" subtitle="Loading...">
        <Flex justify="center" align="center" height="400px">
          <VStack spacing={4}>
            <Spinner size="xl" />
            <Text fontSize="lg">Loading jobs...</Text>
          </VStack>
        </Flex>
      </DriverShell>
    );
  }

  if (error) {
    return (
      <DriverShell title="All Jobs" subtitle="Error loading data">
        <Alert status="error" borderRadius="lg">
          <AlertIcon />
          <Box>
            <AlertDescription fontSize="md">{error}</AlertDescription>
            <Button mt={3} size="md" onClick={refetch}>
              Try Again
            </Button>
          </Box>
        </Alert>
      </DriverShell>
    );
  }

  if (!jobsData) {
    return (
      <DriverShell title="All Jobs" subtitle="No data available">
        <Alert status="warning" borderRadius="lg">
          <AlertIcon />
          <AlertDescription fontSize="md">No jobs data available.</AlertDescription>
        </Alert>
      </DriverShell>
    );
  }

  return (
    <DriverShell
      title="All Jobs"
      subtitle="Manage and track all your jobs in one place"
      actions={
        <HStack spacing={2}>
          <Text fontSize="sm" color="text.secondary">
            Last updated: {new Date().toLocaleTimeString()}
          </Text>
          <Tooltip label="Refresh jobs data">
            <IconButton
              size="sm"
              variant="outline"
              icon={<FiRefreshCw />}
              onClick={refetch}
              isLoading={isLoading}
              aria-label="Refresh"
            />
          </Tooltip>
        </HStack>
      }
    >
      {/* Enhanced Stats */}
      <HStack spacing={4} mb={6} flexWrap="wrap">
        <Badge
          bg="neon.500"
          color="dark.900"
          size="lg"
          px={4}
          py={2}
          fontWeight="600"
          borderRadius="lg"
          position="relative"
          overflow="hidden"
          boxShadow="0 0 15px rgba(59, 130, 246, 0.6), 0 0 30px rgba(59, 130, 246, 0.3)"
          transition="all 0.3s"
          _hover={{
            boxShadow: "0 0 20px rgba(59, 130, 246, 0.8), 0 0 40px rgba(59, 130, 246, 0.4)",
            transform: "scale(1.05)",
            _before: {
              content: '""',
              position: "absolute",
              top: "50%",
              left: "50%",
              width: "0",
              height: "0",
              borderRadius: "50%",
              background: "rgba(255, 255, 255, 0.5)",
              transform: "translate(-50%, -50%)",
              animation: "ripple-badge 0.5s ease-out"
            }
          }}
          sx={{
            "@keyframes ripple-badge": {
              "0%": { width: "0", height: "0", opacity: 1 },
              "100%": { width: "150px", height: "150px", opacity: 0 }
            }
          }}
        >
          Total: {jobsData.total}
        </Badge>
        <Badge
          bg="brand.500"
          color="white"
          size="lg"
          px={4}
          py={2}
          fontWeight="600"
          borderRadius="lg"
          position="relative"
          overflow="hidden"
          boxShadow="0 0 15px rgba(34, 197, 94, 0.6), 0 0 30px rgba(34, 197, 94, 0.3)"
          transition="all 0.3s"
          _hover={{
            boxShadow: "0 0 20px rgba(34, 197, 94, 0.8), 0 0 40px rgba(34, 197, 94, 0.4)",
            transform: "scale(1.05)",
            _before: {
              content: '""',
              position: "absolute",
              top: "50%",
              left: "50%",
              width: "0",
              height: "0",
              borderRadius: "50%",
              background: "rgba(255, 255, 255, 0.5)",
              transform: "translate(-50%, -50%)",
              animation: "ripple-badge 0.5s ease-out"
            }
          }}
          sx={{
            "@keyframes ripple-badge": {
              "0%": { width: "0", height: "0", opacity: 1 },
              "100%": { width: "150px", height: "150px", opacity: 0 }
            }
          }}
        >
          Available: {jobsData.available}
        </Badge>
        <Badge
          bg="warning.500"
          color="white"
          size="lg"
          px={4}
          py={2}
          fontWeight="600"
          borderRadius="lg"
          position="relative"
          overflow="hidden"
          boxShadow="0 0 15px rgba(251, 191, 36, 0.6), 0 0 30px rgba(251, 191, 36, 0.3)"
          transition="all 0.3s"
          _hover={{
            boxShadow: "0 0 20px rgba(251, 191, 36, 0.8), 0 0 40px rgba(251, 191, 36, 0.4)",
            transform: "scale(1.05)",
            _before: {
              content: '""',
              position: "absolute",
              top: "50%",
              left: "50%",
              width: "0",
              height: "0",
              borderRadius: "50%",
              background: "rgba(255, 255, 255, 0.5)",
              transform: "translate(-50%, -50%)",
              animation: "ripple-badge 0.5s ease-out"
            }
          }}
          sx={{
            "@keyframes ripple-badge": {
              "0%": { width: "0", height: "0", opacity: 1 },
              "100%": { width: "150px", height: "150px", opacity: 0 }
            }
          }}
        >
          Assigned: {jobsData.assigned}
        </Badge>
      </HStack>

      {/* Enhanced Search and Filter - Separated Design */}
      <VStack spacing={4} align="stretch">
        {/* Search Box - Standalone */}
        <Box
          bg="bg.card"
          border="1px solid"
          borderColor="border.primary"
          p={4}
          borderRadius="xl"
          position="sticky"
          top={{ base: "76px", md: "80px" }}
          zIndex={10}
          boxShadow="0 0 20px rgba(59, 130, 246, 0.4), 0 0 40px rgba(59, 130, 246, 0.2)"
          transition="all 0.3s"
          _hover={{
            boxShadow: "0 0 25px rgba(59, 130, 246, 0.6), 0 0 50px rgba(59, 130, 246, 0.3)"
          }}
        >
          <InputGroup>
            <InputLeftElement
              pointerEvents="none"
              pl={4}
            >
              <FaSearch color="#E5E5E5" size="16px" />
            </InputLeftElement>
            <Input
              placeholder="Search by customer, reference, location..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              borderRadius="lg"
              bg="bg.input"
              border="2px solid"
              borderColor="border.primary"
              color="text.primary"
              pl={12}
              fontSize="16px"
              h="52px"
              _focus={{
                borderColor: "neon.500",
                boxShadow: "neon.glow",
                bg: "bg.surface"
              }}
              _placeholder={{
                color: "text.tertiary"
              }}
            />
          </InputGroup>
        </Box>

        {/* Filter Badges - Separate Row */}
        <HStack spacing={3} flexWrap="wrap">
          <Text 
            fontSize="sm" 
            color="white" 
            fontWeight="medium"
            textShadow="0 0 8px rgba(255, 255, 255, 0.5)"
          >
            Filter:
          </Text>
          <HStack spacing={2} flexWrap="wrap">
            <Badge
              bg={statusFilter === 'all' ? 'neon.500' : 'bg.surface'}
              color={statusFilter === 'all' ? 'dark.900' : 'white'}
              size="lg"
              px={4}
              py={2}
              borderRadius="full"
              cursor="pointer"
              onClick={() => setStatusFilter('all')}
              position="relative"
              overflow="hidden"
              boxShadow={statusFilter === 'all' ? "0 0 15px rgba(59, 130, 246, 0.6)" : "none"}
              _hover={{
                transform: 'scale(1.05)',
                bg: statusFilter === 'all' ? 'neon.400' : 'bg.surface.hover',
                boxShadow: "0 0 15px rgba(59, 130, 246, 0.6)",
                _before: {
                  content: '""',
                  position: "absolute",
                  top: "50%",
                  left: "50%",
                  width: "0",
                  height: "0",
                  borderRadius: "50%",
                  background: "rgba(255, 255, 255, 0.5)",
                  transform: "translate(-50%, -50%)",
                  animation: "ripple-filter 0.5s ease-out"
                }
              }}
              transition="all 0.3s"
              border={statusFilter === 'all' ? 'none' : '1px solid'}
              borderColor="border.primary"
              sx={{
                "@keyframes ripple-filter": {
                  "0%": { width: "0", height: "0", opacity: 1 },
                  "100%": { width: "120px", height: "120px", opacity: 0 }
                }
              }}
            >
              All Status
            </Badge>
            <Badge
              bg={statusFilter === 'available' ? 'brand.500' : 'bg.surface'}
              color="white"
              size="lg"
              px={4}
              py={2}
              borderRadius="full"
              cursor="pointer"
              onClick={() => setStatusFilter('available')}
              position="relative"
              overflow="hidden"
              boxShadow={statusFilter === 'available' ? "0 0 15px rgba(34, 197, 94, 0.6)" : "none"}
              _hover={{
                transform: 'scale(1.05)',
                bg: statusFilter === 'available' ? 'brand.400' : 'bg.surface.hover',
                boxShadow: "0 0 15px rgba(34, 197, 94, 0.6)",
                _before: {
                  content: '""',
                  position: "absolute",
                  top: "50%",
                  left: "50%",
                  width: "0",
                  height: "0",
                  borderRadius: "50%",
                  background: "rgba(255, 255, 255, 0.5)",
                  transform: "translate(-50%, -50%)",
                  animation: "ripple-filter 0.5s ease-out"
                }
              }}
              transition="all 0.3s"
              border={statusFilter === 'available' ? 'none' : '1px solid'}
              borderColor="border.primary"
              sx={{
                "@keyframes ripple-filter": {
                  "0%": { width: "0", height: "0", opacity: 1 },
                  "100%": { width: "120px", height: "120px", opacity: 0 }
                }
              }}
            >
              Available
            </Badge>
            <Badge
              bg={statusFilter === 'assigned' ? 'warning.500' : 'bg.surface'}
              color="white"
              size="lg"
              px={4}
              py={2}
              borderRadius="full"
              cursor="pointer"
              onClick={() => setStatusFilter('assigned')}
              position="relative"
              overflow="hidden"
              boxShadow={statusFilter === 'assigned' ? "0 0 15px rgba(251, 191, 36, 0.6)" : "none"}
              _hover={{
                transform: 'scale(1.05)',
                bg: statusFilter === 'assigned' ? 'warning.400' : 'bg.surface.hover',
                boxShadow: "0 0 15px rgba(251, 191, 36, 0.6)",
                _before: {
                  content: '""',
                  position: "absolute",
                  top: "50%",
                  left: "50%",
                  width: "0",
                  height: "0",
                  borderRadius: "50%",
                  background: "rgba(255, 255, 255, 0.5)",
                  transform: "translate(-50%, -50%)",
                  animation: "ripple-filter 0.5s ease-out"
                }
              }}
              transition="all 0.3s"
              border={statusFilter === 'assigned' ? 'none' : '1px solid'}
              borderColor="border.primary"
              sx={{
                "@keyframes ripple-filter": {
                  "0%": { width: "0", height: "0", opacity: 1 },
                  "100%": { width: "120px", height: "120px", opacity: 0 }
                }
              }}
            >
              Assigned
            </Badge>
            <Badge
              bg={statusFilter === 'accepted' ? 'info.500' : 'bg.surface'}
              color="white"
              size="lg"
              px={4}
              py={2}
              borderRadius="full"
              cursor="pointer"
              onClick={() => setStatusFilter('accepted')}
              position="relative"
              overflow="hidden"
              boxShadow={statusFilter === 'accepted' ? "0 0 15px rgba(59, 130, 246, 0.6)" : "none"}
              _hover={{
                transform: 'scale(1.05)',
                bg: statusFilter === 'accepted' ? 'info.400' : 'bg.surface.hover',
                boxShadow: "0 0 15px rgba(59, 130, 246, 0.6)",
                _before: {
                  content: '""',
                  position: "absolute",
                  top: "50%",
                  left: "50%",
                  width: "0",
                  height: "0",
                  borderRadius: "50%",
                  background: "rgba(255, 255, 255, 0.5)",
                  transform: "translate(-50%, -50%)",
                  animation: "ripple-filter 0.5s ease-out"
                }
              }}
              transition="all 0.3s"
              border={statusFilter === 'accepted' ? 'none' : '1px solid'}
              borderColor="border.primary"
              sx={{
                "@keyframes ripple-filter": {
                  "0%": { width: "0", height: "0", opacity: 1 },
                  "100%": { width: "120px", height: "120px", opacity: 0 }
                }
              }}
            >
              Accepted
            </Badge>
            <Badge
              bg={statusFilter === 'completed' ? 'success.500' : 'bg.surface'}
              color="white"
              size="lg"
              px={4}
              py={2}
              borderRadius="full"
              cursor="pointer"
              onClick={() => setStatusFilter('completed')}
              position="relative"
              overflow="hidden"
              boxShadow={statusFilter === 'completed' ? "0 0 15px rgba(34, 197, 94, 0.6)" : "none"}
              _hover={{
                transform: 'scale(1.05)',
                bg: statusFilter === 'completed' ? 'success.400' : 'bg.surface.hover',
                boxShadow: "0 0 15px rgba(34, 197, 94, 0.6)",
                _before: {
                  content: '""',
                  position: "absolute",
                  top: "50%",
                  left: "50%",
                  width: "0",
                  height: "0",
                  borderRadius: "50%",
                  background: "rgba(255, 255, 255, 0.5)",
                  transform: "translate(-50%, -50%)",
                  animation: "ripple-filter 0.5s ease-out"
                }
              }}
              transition="all 0.3s"
              border={statusFilter === 'completed' ? 'none' : '1px solid'}
              borderColor="border.primary"
              sx={{
                "@keyframes ripple-filter": {
                  "0%": { width: "0", height: "0", opacity: 1 },
                  "100%": { width: "120px", height: "120px", opacity: 0 }
                }
              }}
            >
              Completed
            </Badge>
          </HStack>
        </HStack>
      </VStack>

      {/* Multi-Drop Routes Section */}
      {routesData?.routes && routesData.routes.length > 0 && (
        <Box mt={6}>
          <Heading 
            size="md" 
            mb={4}
            color="white"
            textShadow="0 0 15px rgba(168, 85, 247, 0.9), 0 0 30px rgba(168, 85, 247, 0.6)"
          >
            🚛 Multi-Drop Routes ({routesData.routes.length})
          </Heading>
          <VStack spacing={6} align="stretch">
            {routesData.routes.map((route) => (
              <RouteCard
                key={route.id}
                route={route}
                onAccept={route.status === 'planned' ? handleAcceptRoute : undefined}
                onReject={route.status === 'planned' ? handleDeclineRoute : undefined}
                onViewDetails={(routeId) => console.log('View details:', routeId)}
                onStartRoute={route.status === 'assigned' ? (routeId) => window.location.href = `/driver/routes/${routeId}/progress` : undefined}
                isLoading={isLoadingRoutes}
              />
            ))}
          </VStack>
        </Box>
      )}

      {/* Individual Jobs List */}
      {filteredJobs.length > 0 ? (
        <Box mt={6}>
          <Heading 
            size="md" 
            mb={4}
            color="white"
            textShadow="0 0 15px rgba(34, 197, 94, 0.9), 0 0 30px rgba(34, 197, 94, 0.6)"
          >
            📦 Individual Jobs ({filteredJobs.length})
          </Heading>
          <VStack spacing={6} align="stretch">
            {filteredJobs.map((job) => (
              <EnhancedJobCard
                key={job.id}
                job={job}
                variant={job.status === 'assigned' ? 'assigned' : 'available'}
                onAccept={job.status === 'available' ? handleAcceptJob : undefined}
                onDecline={job.status === 'available' ? handleDeclineJob : undefined}
                onViewDetails={(jobId) => window.location.href = `/driver/jobs/${jobId}`}
                isAccepting={isLoading}
                isDeclining={isLoading}
              />
            ))}
          </VStack>
        </Box>
      ) : !routesData?.routes || routesData.routes.length === 0 ? (
        <NoJobsMessage
          onRefresh={() => {
            refetch();
            refetchRoutes();
          }}
          isRefreshing={isLoading || isLoadingRoutes}
          message={searchTerm || statusFilter !== 'all' ? "No jobs match your filters" : "No jobs available"}
          subMessage={searchTerm || statusFilter !== 'all' ? "Try adjusting your search or filter criteria" : "New jobs will appear here when customers place orders"}
        />
      ) : null}
    </DriverShell>
  );
}

import React from 'react';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { redirect } from 'next/navigation';
import { UnifiedNavigation } from '@/components/shared/UnifiedNavigation';
import UnifiedErrorBoundary from '@/components/shared/UnifiedErrorBoundary';

// CRITICAL: Force dynamic rendering because we use getServerSession() which requires cookies()
// This prevents DYNAMIC_SERVER_USAGE error in production builds
export const dynamic = 'force-dynamic';
export const revalidate = 0;

export default async function DriverLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  const session = await getServerSession(authOptions);

  console.log('🚗 Driver Layout - Session check:', {
    hasSession: !!session,
    userRole: (session?.user as any)?.role,
    email: session?.user?.email,
  });

  // Simple check: require driver session for all driver pages
  if (!session?.user) {
    console.log('❌ Driver Layout - No session, redirecting to auth');
    redirect('/driver-auth');
  }

  if ((session.user as any).role !== 'driver') {
    console.log('❌ Driver Layout - User is not driver, redirecting to auth');
    redirect('/driver-auth');
  }

  console.log('✅ Driver Layout - Access granted for approved driver');

  return (
    <>
      <UnifiedNavigation role="driver" isAuthenticated={true}>
        <UnifiedErrorBoundary role="driver">{children}</UnifiedErrorBoundary>
      </UnifiedNavigation>
    </>
  );
}

'use client';

import React, { useEffect, useState } from 'react';
import {
  Box,
  Container,
  VStack,
  Heading,
  Text,
  Spinner,
  Alert,
  AlertIcon,
  Button,
  useToast,
} from '@chakra-ui/react';
import { useRouter } from 'next/navigation';
import { signOut } from 'next-auth/react';
import { FaSignOutAlt, FaCheckCircle } from 'react-icons/fa';

export default function DriverLogoutPage() {
  const [isLoggingOut, setIsLoggingOut] = useState(true);
  const [error, setError] = useState('');
  const router = useRouter();
  const toast = useToast();

  useEffect(() => {
    handleLogout();
  }, []);

  const handleLogout = async () => {
    try {
      setIsLoggingOut(true);
      setError('');

      // Call the logout API to log the event
      try {
        const response = await fetch('/api/driver/auth/logout', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
        });

        if (!response.ok) {
          console.warn('Logout API call failed, but continuing with sign out');
        }
      } catch (apiError) {
        console.warn('Logout API error:', apiError);
        // Continue with sign out even if API fails
      }

      // Sign out from NextAuth
      await signOut({
        redirect: false,
        callbackUrl: '/driver-auth'
      });

      // Show success message
      toast({
        title: 'Logged Out Successfully',
        description: 'You have been signed out of the driver portal.',
        status: 'success',
        duration: 3000,
        isClosable: true,
      });

      // Redirect to login page
      setTimeout(() => {
        router.push('/driver-auth');
      }, 1500);

    } catch (error) {
      console.error('Driver logout error:', error);
      setError('An error occurred during logout. Please try again.');
      
      toast({
        title: 'Logout Error',
        description: 'Failed to sign out properly. Please try again.',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setIsLoggingOut(false);
    }
  };

  const handleManualRedirect = () => {
    router.push('/driver-auth');
  };

  if (error) {
    return (
      <Box minH="100vh" bg="gray.50" display="flex" alignItems="center" justifyContent="center" px={4}>
        <Container maxW="md">
          <VStack spacing={6} textAlign="center">
            <Alert status="error" borderRadius="lg">
              <AlertIcon />
              {error}
            </Alert>
            
            <Button
              colorScheme="blue"
              onClick={handleManualRedirect}
              size={{ base: "md", md: "lg" }}
              w={{ base: "full", md: "auto" }}
            >
              Go to Login Page
            </Button>
          </VStack>
        </Container>
      </Box>
    );
  }

  return (
    <Box minH="100vh" bg="gray.50" display="flex" alignItems="center" justifyContent="center" px={4}>
      <Container maxW="md">
        <VStack spacing={6} textAlign="center">
          {isLoggingOut ? (
            <>
              <Spinner size="xl" color="blue.500" thickness="4px" />
              <VStack spacing={2}>
                <Heading size={{ base: "md", md: "lg" }} color="gray.700">
                  Signing Out...
                </Heading>
                <Text color="gray.600" fontSize={{ base: "sm", md: "md" }} px={4}>
                  Please wait while we sign you out of the driver portal.
                </Text>
              </VStack>
            </>
          ) : (
            <>
              <Box color="green.500" fontSize={{ base: "3xl", md: "4xl" }}>
                <FaCheckCircle />
              </Box>
              <VStack spacing={2}>
                <Heading size={{ base: "md", md: "lg" }} color="gray.700">
                  Successfully Signed Out
                </Heading>
                <Text color="gray.600" fontSize={{ base: "sm", md: "md" }} px={4}>
                  You have been signed out of the driver portal.
                </Text>
              </VStack>
            </>
          )}
        </VStack>
      </Container>
    </Box>
  );
}

'use client';

import React, { useState, useEffect, useRef } from 'react';
import {
  Container,
  Heading,
  Text,
  Box,
  VStack,
  HStack,
  Button,
  useToast,
  Spinner,
  Alert,
  AlertIcon,
  AlertDescription,
  useBreakpointValue,
  Stack,
  Flex,
  SimpleGrid,
  IconButton,
  Tooltip,
  Modal,
  ModalOverlay,
  ModalContent,
  ModalHeader,
  ModalBody,
  ModalFooter,
  useDisclosure,
} from '@chakra-ui/react';
import { FiRefreshCw, FiTruck, FiTrendingUp, FiBell } from 'react-icons/fi';
import Link from 'next/link';
import { ROUTES } from '@/lib/routing';

import { EnhancedJobCard } from '@/components/driver/EnhancedJobCard';
import { NoJobsMessage } from '@/components/driver/NoJobsMessage';
import { DriverStatsCard } from '@/components/driver/DriverStatsCard';
import { DriverShell } from '@/components/driver';
import { useOptimizedDataLoader } from '@/hooks/useOptimizedDataLoader';
import { useRouter } from 'next/navigation';
import { useSession } from 'next-auth/react';

interface DashboardData {
  driver: {
    id: string;
    status: string;
    onboardingStatus: string;
  };
  jobs: {
    assigned: any[];
    available: any[];
  };
  statistics: {
    assignedJobs: number;
    availableJobs: number;
    completedToday: number;
    totalCompleted: number;
    earningsToday: number;
    totalEarnings: number;
    averageRating: number;
  };
}

export default function DriverDashboard() {
  const toast = useToast();
  const router = useRouter();
  const isMobile = useBreakpointValue({ base: true, md: false });
  const { data: session } = useSession();
  const pusherRef = useRef<any>(null);
  const { isOpen: isNotificationOpen, onOpen: onNotificationOpen, onClose: onNotificationClose } = useDisclosure();
  const [notificationData, setNotificationData] = useState<any>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  // Logout handler
  const handleLogout = () => {
    router.push('/driver/logout');
  };

  // Use optimized data loader
  const { data: dashboardData, loading: isLoading, error, refetch } = useOptimizedDataLoader<DashboardData>({
    endpoint: '/api/driver/dashboard',
    debounceMs: 300,
    cacheKey: 'driver-dashboard',
    enabled: true
  });

  // Initialize Pusher for real-time notifications
  useEffect(() => {
    if (typeof window === 'undefined' || !session?.user) return;

    const initPusher = async () => {
      try {
        const Pusher = (await import('pusher-js')).default;
        
        const driverId = (session.user as any).driver?.id || (session.user as any).id;
        if (!driverId) return;

        console.log('🔌 Initializing Pusher for driver dashboard:', driverId);

        const PUSHER_KEY = '407cb06c423e6c032e9c';
        const PUSHER_CLUSTER = 'eu';
        pusherRef.current = new Pusher(PUSHER_KEY, {
          cluster: PUSHER_CLUSTER,
          forceTLS: true,
        });

        const channel = pusherRef.current.subscribe(`driver-${driverId}`);

        // 🎯 Listen for route-matched event (PRIMARY)
        channel.bind('route-matched', (data: any) => {
          console.log('🎯🎯🎯 ROUTE MATCHED via Pusher (Web):', data);
          
          // Play notification sound
          playNotificationSound();
          
          // Show notification modal
          setNotificationData(data);
          onNotificationOpen();
          
          // Refresh dashboard data
          refetch();
          
          // Show toast
          toast({
            title: 'New Route Matched!',
            description: data.type === 'single-order' 
              ? `New job: ${data.bookingReference}`
              : `New route with ${data.bookingsCount} jobs assigned to you`,
            status: 'success',
            duration: 10000,
            isClosable: true,
            position: 'top-right',
          });
        });

        // 📦 Listen for job-assigned event (SECONDARY)
        channel.bind('job-assigned', (data: any) => {
          console.log('📦 JOB ASSIGNED via Pusher (Web):', data);
          
          // Play notification sound
          playNotificationSound();
          
          // Refresh dashboard data
          refetch();
          
          // Show toast
          toast({
            title: 'New Job Assigned!',
            description: `Job ${data.bookingReference || data.routeId} assigned to you`,
            status: 'info',
            duration: 8000,
            isClosable: true,
            position: 'top-right',
          });
        });

        // ❌ Listen for route-removed event
        channel.bind('route-removed', (data: any) => {
          console.log('❌ ROUTE REMOVED via Pusher (Web):', data);
          
          // Refresh dashboard data
          refetch();
          
          // Show toast
          toast({
            title: 'Route Removed',
            description: data.reason || 'A route has been removed from your assignments',
            status: 'warning',
            duration: 8000,
            isClosable: true,
            position: 'top-right',
          });
        });

        // 🚫 Listen for route-cancelled event (admin cancelled route)
        channel.bind('route-cancelled', (data: any) => {
          console.log('🚫 ROUTE CANCELLED by Admin (Web):', data);
          
          // Play notification sound
          playNotificationSound();
          
          // Refresh dashboard data
          refetch();
          
          // Show toast
          toast({
            title: 'Route Cancelled',
            description: data.message || `Route ${data.routeNumber || data.routeId} has been cancelled by admin`,
            status: 'error',
            duration: 10000,
            isClosable: true,
            position: 'top-right',
          });
        });

        // 📦 Listen for drop-removed event (admin removed drop from route)
        channel.bind('drop-removed', (data: any) => {
          console.log('📦 DROP REMOVED by Admin (Web):', data);
          
          // Refresh dashboard data
          refetch();
          
          // Show toast
          toast({
            title: 'Route Updated',
            description: `A drop has been removed from route ${data.routeNumber || data.routeId}. ${data.remainingDrops || 0} drops remaining.`,
            status: 'info',
            duration: 8000,
            isClosable: true,
            position: 'top-right',
          });
        });

        // 📬 Listen for notification event
        channel.bind('notification', (data: any) => {
          console.log('📬 NOTIFICATION via Pusher (Web):', data);
          
          toast({
            title: data.title || 'Notification',
            description: data.message,
            status: 'info',
            duration: 6000,
            isClosable: true,
            position: 'top-right',
          });
        });

        console.log('✅ Pusher initialized successfully for web driver portal');
      } catch (error) {
        console.error('❌ Failed to initialize Pusher:', error);
      }
    };

    initPusher();

    return () => {
      if (pusherRef.current) {
        console.log('🔌 Disconnecting Pusher...');
        pusherRef.current.disconnect();
      }
    };
  }, [session, refetch, toast, onNotificationOpen]);

  // Play notification sound
  const playNotificationSound = () => {
    try {
      if (!audioRef.current) {
        audioRef.current = new Audio('/sounds/notification.mp3');
      }
      audioRef.current.play().catch(err => {
        console.warn('Could not play notification sound:', err);
      });
    } catch (error) {
      console.error('Error playing sound:', error);
    }
  };

  // Show toast for errors
  useEffect(() => {
    if (error) {
      console.error('Driver Dashboard Error:', error);
      toast({
        title: 'Error Loading Dashboard',
        description: 'Failed to load your dashboard data. Please try again.',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    }
  }, [error, toast]);

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'completed': return 'green';
      case 'accepted': return 'blue';
      case 'invited': return 'yellow';
      case 'available': return 'green';
      default: return 'gray';
    }
  };

  const handleAcceptJob = async (jobId: string) => {
    try {
      const response = await fetch(`/api/driver/jobs/${jobId}/accept`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' }
      });

      if (response.ok) {
        toast({
          title: 'Job Accepted!',
          description: 'You have successfully accepted this job. Redirecting to job details...',
          status: 'success',
          duration: 3000,
          isClosable: true,
        });
        
        // Redirect to job details page after a short delay
        setTimeout(() => {
          window.location.href = `/driver/jobs/${jobId}`;
        }, 1500);
      } else {
        throw new Error('Failed to accept job');
      }
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to accept job. Please try again.',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    }
  };

  if (isLoading) {
    return (
      <Container maxW="7xl" py={{ base: 4, md: 8 }}>
        <VStack spacing={{ base: 6, md: 8 }} align="center">
          <Spinner size="xl" color="blue.500" />
          <Text fontSize={{ base: "md", md: "lg" }}>Loading your dashboard...</Text>
        </VStack>
      </Container>
    );
  }

  if (error) {
    return (
      <Container maxW="7xl" py={{ base: 4, md: 8 }}>
        <Alert status="error" borderRadius="lg">
          <AlertIcon />
          <Box>
            <AlertDescription fontSize={{ base: "sm", md: "md" }}>{error}</AlertDescription>
            <Button mt={3} size={{ base: "sm", md: "md" }} onClick={refetch}>
              Try Again
            </Button>
          </Box>
        </Alert>
      </Container>
    );
  }

  if (!dashboardData) {
    return (
      <Container maxW="7xl" py={{ base: 4, md: 8 }}>
        <Alert status="warning" borderRadius="lg">
          <AlertIcon />
          <AlertDescription fontSize={{ base: "sm", md: "md" }}>No dashboard data available.</AlertDescription>
        </Alert>
      </Container>
    );
  }

  const { driver, jobs, statistics } = dashboardData;

  return (
    <DriverShell
      title="Driver Dashboard"
      subtitle="Manage your jobs and track your performance"
      actions={
        <HStack spacing={2}>
          <Text fontSize="sm" color="text.secondary">
            Last updated: {new Date().toLocaleTimeString()}
          </Text>
          <Tooltip label="Refresh dashboard data">
            <IconButton
              size="sm"
              variant="outline"
              icon={<FiRefreshCw />}
              onClick={refetch}
              isLoading={isLoading}
              aria-label="Refresh"
            />
          </Tooltip>
        </HStack>
      }
    >
      <Box>
        {/* Enhanced Stats Card */}
        <DriverStatsCard
          stats={statistics}
          title="Your Performance Dashboard"
          description="Track your jobs, earnings, and performance metrics"
        />

        {/* Jobs Grid */}
        <SimpleGrid columns={{ base: 1, lg: 2 }} spacing={6} mt={8}>
          {/* Assigned Jobs */}
          <Box>
            <Flex justify="space-between" align="center" mb={4}>
              <Heading 
                size="md" 
                color="white"
                textShadow="0 0 12px rgba(59, 130, 246, 0.8), 0 0 24px rgba(59, 130, 246, 0.4)"
              >
                Your Assigned Jobs
              </Heading>
              <Text 
                fontSize="sm" 
                color="white"
                textShadow="0 0 8px rgba(255, 255, 255, 0.6)"
              >
                {jobs.assigned.length} active
              </Text>
            </Flex>
            <VStack spacing={4} align="stretch">
              {jobs.assigned.length === 0 ? (
                <Text 
                  color="white" 
                  textAlign="center" 
                  py={8}
                  textShadow="0 0 8px rgba(255, 255, 255, 0.5)"
                >
                  No assigned jobs at the moment
                </Text>
              ) : (
                jobs.assigned.map((job) => (
                  <EnhancedJobCard
                    key={job.id}
                    job={{
                      id: job.id,
                      reference: job.reference,
                      customer: job.customer,
                      customerPhone: job.customerPhone || "01202 129746",
                      date: job.date,
                      time: job.time,
                      from: job.from,
                      to: job.to,
                      distance: job.distance,
                      vehicleType: job.vehicleType,
                      items: job.items,
                      estimatedEarnings: job.estimatedEarnings,
                      status: job.assignmentStatus,
                      duration: job.duration,
                      crew: job.crew,
                    }}
                    variant="assigned"
                    onAccept={job.assignmentStatus === 'invited' ? handleAcceptJob : undefined}
                    onViewDetails={(jobId) => window.location.href = `/driver/jobs/${jobId}`}
                    isAccepting={isLoading}
                  />
                ))
              )}
            </VStack>
          </Box>

          {/* Available Jobs */}
          <Box>
            <Flex justify="space-between" align="center" mb={4}>
              <Heading 
                size="md" 
                color="white"
                textShadow="0 0 12px rgba(34, 197, 94, 0.8), 0 0 24px rgba(34, 197, 94, 0.4)"
              >
                Available Jobs
              </Heading>
              <Text 
                fontSize="sm" 
                color="white"
                textShadow="0 0 8px rgba(255, 255, 255, 0.6)"
              >
                {jobs.available.length} ready to accept
              </Text>
            </Flex>
            <VStack spacing={4} align="stretch">
              {jobs.available.length === 0 ? (
                <Text 
                  color="white" 
                  textAlign="center" 
                  py={8}
                  textShadow="0 0 8px rgba(255, 255, 255, 0.5)"
                >
                  No available jobs at the moment
                </Text>
              ) : (
                jobs.available.map((job) => (
                  <EnhancedJobCard
                    key={job.id}
                    job={{
                      id: job.id,
                      reference: job.reference,
                      customer: job.customer,
                      customerPhone: job.customerPhone || "01202 129746",
                      date: job.date,
                      time: job.time,
                      from: job.from,
                      to: job.to,
                      distance: job.distance,
                      vehicleType: job.vehicleType,
                      items: job.items,
                      estimatedEarnings: job.estimatedEarnings,
                      status: "available",
                      duration: job.duration,
                      crew: job.crew,
                    }}
                    variant="available"
                    onAccept={handleAcceptJob}
                    onViewDetails={(jobId) => window.location.href = `/driver/jobs/${jobId}`}
                    isAccepting={isLoading}
                  />
                ))
              )}
            </VStack>
          </Box>
        </SimpleGrid>

        {/* No Jobs Message */}
        {jobs.assigned.length === 0 && jobs.available.length === 0 && (
          <NoJobsMessage
            onRefresh={refetch}
            isRefreshing={isLoading}
            message="No available jobs at the moment"
            subMessage="New jobs will appear here when customers place orders"
          />
        )}

        {/* Quick Actions */}
        <Box mt={8}>
          <Heading 
            size="md" 
            mb={6} 
            color="white"
            textShadow="0 0 12px rgba(59, 130, 246, 0.8), 0 0 24px rgba(59, 130, 246, 0.4)"
          >
            Quick Actions
          </Heading>
          <Stack direction={{ base: "column", md: "row" }} spacing={4}>
            <Button
              colorScheme="blue"
              onClick={refetch}
              isLoading={isLoading}
              size="lg"
              width={{ base: "full", md: "auto" }}
              leftIcon={<FiRefreshCw />}
              position="relative"
              overflow="hidden"
              boxShadow="0 0 15px rgba(59, 130, 246, 0.6), 0 0 30px rgba(59, 130, 246, 0.3)"
              _hover={{
                boxShadow: "0 0 20px rgba(59, 130, 246, 0.8), 0 0 40px rgba(59, 130, 246, 0.4)",
                transform: "scale(1.05)",
                _before: {
                  content: '""',
                  position: "absolute",
                  top: "50%",
                  left: "50%",
                  width: "0",
                  height: "0",
                  borderRadius: "50%",
                  background: "rgba(255, 255, 255, 0.5)",
                  transform: "translate(-50%, -50%)",
                  animation: "ripple-quick 0.6s ease-out"
                }
              }}
              sx={{
                "@keyframes ripple-quick": {
                  "0%": { width: "0", height: "0", opacity: 1 },
                  "100%": { width: "200px", height: "200px", opacity: 0 }
                }
              }}
            >
              Refresh Dashboard
            </Button>
            <Link href={ROUTES.DRIVER.JOBS}>
              <Button
                variant="outline"
                size="lg"
                width={{ base: "full", md: "auto" }}
                leftIcon={<FiTruck />}
                position="relative"
                overflow="hidden"
                borderColor="neon.500"
                color="white"
                boxShadow="0 0 10px rgba(34, 197, 94, 0.5)"
                _hover={{
                  bg: "rgba(34, 197, 94, 0.1)",
                  boxShadow: "0 0 15px rgba(34, 197, 94, 0.7), 0 0 30px rgba(34, 197, 94, 0.4)",
                  transform: "scale(1.05)",
                  _before: {
                    content: '""',
                    position: "absolute",
                    top: "50%",
                    left: "50%",
                    width: "0",
                    height: "0",
                    borderRadius: "50%",
                    background: "rgba(255, 255, 255, 0.4)",
                    transform: "translate(-50%, -50%)",
                    animation: "ripple-quick 0.6s ease-out"
                  }
                }}
                sx={{
                  "@keyframes ripple-quick": {
                    "0%": { width: "0", height: "0", opacity: 1 },
                    "100%": { width: "200px", height: "200px", opacity: 0 }
                  }
                }}
              >
                View All Jobs
              </Button>
            </Link>
            <Button
              variant="outline"
              size="lg"
              width={{ base: "full", md: "auto" }}
              leftIcon={<FiTrendingUp />}
              position="relative"
              overflow="hidden"
              borderColor="neon.500"
              color="white"
              boxShadow="0 0 10px rgba(251, 191, 36, 0.5)"
              _hover={{
                bg: "rgba(251, 191, 36, 0.1)",
                boxShadow: "0 0 15px rgba(251, 191, 36, 0.7), 0 0 30px rgba(251, 191, 36, 0.4)",
                transform: "scale(1.05)",
                _before: {
                  content: '""',
                  position: "absolute",
                  top: "50%",
                  left: "50%",
                  width: "0",
                  height: "0",
                  borderRadius: "50%",
                  background: "rgba(255, 255, 255, 0.4)",
                  transform: "translate(-50%, -50%)",
                  animation: "ripple-quick 0.6s ease-out"
                }
              }}
              sx={{
                "@keyframes ripple-quick": {
                  "0%": { width: "0", height: "0", opacity: 1 },
                  "100%": { width: "200px", height: "200px", opacity: 0 }
                }
              }}
            >
              Update Availability
            </Button>
          </Stack>
        </Box>

        {/* Route Match Notification Modal */}
        <Modal isOpen={isNotificationOpen} onClose={onNotificationClose} size="lg" isCentered>
          <ModalOverlay bg="blackAlpha.700" backdropFilter="blur(10px)" />
          <ModalContent 
            bg="linear-gradient(135deg, #667eea 0%, #764ba2 100%)"
            borderRadius="xl"
            boxShadow="0 0 50px rgba(102, 126, 234, 0.6)"
          >
            <ModalHeader color="white" fontSize="2xl" fontWeight="bold">
              <Flex align="center" gap={3}>
                <FiBell size={28} />
                🎯 New Route Matched!
              </Flex>
            </ModalHeader>
            <ModalBody color="white">
              {notificationData && (
                <VStack spacing={4} align="stretch">
                  <Box>
                    <Text fontSize="lg" fontWeight="semibold">
                      {notificationData.type === 'single-order' 
                        ? '📦 Single Order' 
                        : '🚚 Multi-Drop Route'}
                    </Text>
                    <Text mt={2} fontWeight="bold" color="cyan.300">
                      {notificationData.type === 'single-order'
                        ? `Order #${notificationData.orderNumber || notificationData.bookingReference}`
                        : `Route #${notificationData.routeNumber || notificationData.orderNumber}`}
                    </Text>
                    {notificationData.type !== 'single-order' && (
                      <Text mt={1} fontSize="sm">
                        {notificationData.bookingsCount} jobs assigned to you
                      </Text>
                    )}
                  </Box>
                  {notificationData.totalEarnings && (
                    <Box bg="whiteAlpha.200" p={3} borderRadius="md">
                      <Text fontSize="sm" opacity={0.9}>Estimated Earnings</Text>
                      <Text fontSize="2xl" fontWeight="bold">
                        £{(notificationData.totalEarnings / 100).toFixed(2)}
                      </Text>
                    </Box>
                  )}
                  <Text fontSize="sm" opacity={0.8}>
                    {notificationData.message}
                  </Text>
                </VStack>
              )}
            </ModalBody>
            <ModalFooter>
              <Button 
                colorScheme="whiteAlpha" 
                variant="solid"
                onClick={() => {
                  onNotificationClose();
                  router.push(ROUTES.DRIVER.JOBS);
                }}
                mr={3}
              >
                View Details
              </Button>
              <Button variant="ghost" color="white" onClick={onNotificationClose}>
                Later
              </Button>
            </ModalFooter>
          </ModalContent>
        </Modal>
      </Box>
    </DriverShell>
  );
}

'use client';

import React, { useState, useEffect, useCallback } from 'react';
import {
  Box,
  Container,
  VStack,
  HStack,
  Flex,
  Heading,
  Text,
  Card,
  CardBody,
  CardHeader,
  SimpleGrid,
  Stat,
  StatLabel,
  StatNumber,
  StatHelpText,
  Avatar,
  Badge,
  Button,
  FormControl,
  FormLabel,
  Input,
  Textarea,
  Select,
  Switch,
  Progress,
  Divider,
  Alert,
  AlertIcon,
  Spinner,
  useToast,
  IconButton,
  Tooltip,
  Modal,
  ModalOverlay,
  ModalContent,
  ModalHeader,
  ModalFooter,
  ModalBody,
  ModalCloseButton,
  useDisclosure,
  Table,
  Thead,
  Tbody,
  Tr,
  Th,
  Td,
} from '@chakra-ui/react';
import { 
  FiUser, 
  FiStar, 
  FiTruck, 
  FiEdit,
  FiSave,
  FiX,
  FiRefreshCw,
  FiMapPin,
  FiPhone,
  FiMail,
  FiCalendar,
  FiTrendingUp,
  FiCheck,
  FiClock,
  FiTarget,
} from 'react-icons/fi';
import { formatDistanceToNow, format } from 'date-fns';
import { DriverShell } from '@/components/driver';

interface DriverProfileData {
  id: string;
  email: string;
  firstName: string;
  lastName: string;
  phone: string;
  driverId: string;
  basePostcode: string;
  vehicleType: string;
  onboardingStatus: string;
  rating: number;
  strikes: number;
  status: string;
  bio: string;
  profileImage: string;
  profileCompleteness: number;
  totalJobs: number;
  averageScore: number;
  averageRating: number;
  completionRate: number;
  onTimeRate: number;
  isOnline: boolean;
  lastSeenAt?: string;
  locationConsent: boolean;
  hasActiveOrders?: boolean;
  recentRatings: Array<{
    id: string;
    rating: number;
    review: string;
    category: string;
    bookingReference: string;
    customerName: string;
    createdAt: string;
  }>;
  joinedAt: string;
  lastLogin?: string;
  applicationStatus: string;
  applicationDate?: string;
}

export default function DriverProfile() {
  const [data, setData] = useState<DriverProfileData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [isEditing, setIsEditing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [refreshing, setRefreshing] = useState(false);
  const { isOpen, onOpen, onClose } = useDisclosure();
  const toast = useToast();

  // Edit form state
  const [editForm, setEditForm] = useState({
    firstName: '',
    lastName: '',
    phone: '',
    email: '',
    basePostcode: '',
    vehicleType: '',
    bio: '',
    profileImage: '',
  });

  const fetchProfileData = useCallback(async (showRefreshToast = false) => {
    try {
      setRefreshing(true);
      const response = await fetch('/api/driver/profile');
      
      if (!response.ok) {
        throw new Error('Failed to fetch profile data');
      }

      const result = await response.json();
      setData(result.data);
      setError(null);

      // Initialize edit form
      setEditForm({
        firstName: result.data.firstName,
        lastName: result.data.lastName,
        phone: result.data.phone,
        email: result.data.email,
        basePostcode: result.data.basePostcode,
        vehicleType: result.data.vehicleType,
        bio: result.data.bio,
        profileImage: result.data.profileImage,
      });

      if (showRefreshToast) {
        toast({
          title: 'Profile Refreshed',
          description: 'Profile data has been updated',
          status: 'success',
          duration: 2000,
          isClosable: true,
        });
      }
    } catch (error) {
      console.error('Error fetching profile:', error);
      setError(error instanceof Error ? error.message : 'Failed to load profile');
      toast({
        title: 'Error',
        description: 'Failed to load profile data',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  }, [toast]);

  useEffect(() => {
    fetchProfileData();
  }, [fetchProfileData]);

  const handleEditStart = useCallback(() => {
    setIsEditing(true);
  }, []);

  const handleEditCancel = useCallback(() => {
    setIsEditing(false);
    // Reset form to original data
    if (data) {
      setEditForm({
        firstName: data.firstName,
        lastName: data.lastName,
        phone: data.phone,
        email: data.email,
        basePostcode: data.basePostcode,
        vehicleType: data.vehicleType,
        bio: data.bio,
        profileImage: data.profileImage,
      });
    }
  }, [data]);

  const handleEditSave = useCallback(async () => {
    try {
      setIsSaving(true);
      const response = await fetch('/api/driver/profile', {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(editForm),
      });

      if (!response.ok) {
        const result = await response.json();
        throw new Error(result.error || 'Failed to update profile');
      }

      setIsEditing(false);
      toast({
        title: 'Profile Updated',
        description: 'Your profile has been updated successfully',
        status: 'success',
        duration: 3000,
        isClosable: true,
      });

      // Refresh data
      fetchProfileData();
    } catch (error) {
      console.error('Error updating profile:', error);
      toast({
        title: 'Update Failed',
        description: error instanceof Error ? error.message : 'Failed to update profile',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setIsSaving(false);
    }
  }, [editForm, fetchProfileData, toast]);

  const createSampleProfile = useCallback(async () => {
    try {
      const response = await fetch('/api/debug/create-sample-profile', {
        method: 'POST',
      });
      
      if (response.ok) {
        const result = await response.json();
        toast({
          title: 'Sample Profile Created',
          description: 'Sample profile data has been added to your account.',
          status: 'success',
          duration: 3000,
          isClosable: true,
        });
        // Refresh data
        fetchProfileData();
      } else {
        const result = await response.json();
        toast({
          title: 'Failed to create sample profile',
          description: result.error || 'Unknown error',
          status: 'error',
          duration: 5000,
          isClosable: true,
        });
      }
    } catch (error) {
      console.error('Error creating sample profile:', error);
      toast({
        title: 'Error',
        description: 'Failed to create sample profile',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    }
  }, [fetchProfileData, toast]);

  const getStatusColor = useCallback((status: string) => {
    switch (status.toLowerCase()) {
      case 'approved': return 'green';
      case 'pending': return 'yellow';
      case 'active': return 'green';
      case 'offline': return 'gray';
      default: return 'gray';
    }
  }, []);

  const getCompletionColor = useCallback((percentage: number) => {
    if (percentage >= 80) return 'green';
    if (percentage >= 60) return 'yellow';
    return 'red';
  }, []);

  const renderStars = useCallback((rating: number) => {
    return Array.from({ length: 5 }, (_, i) => (
      <Box
        key={i}
        as={FiStar}
        color={i < rating ? 'yellow.400' : 'gray.300'}
        fill={i < rating ? 'yellow.400' : 'transparent'}
      />
    ));
  }, []);

  if (loading) {
    return (
      <DriverShell title="Driver Profile" subtitle="Loading...">
        <Flex justify="center" align="center" height="400px">
          <VStack spacing={4}>
            <Spinner size="xl" />
            <Text fontSize="lg">Loading your profile...</Text>
          </VStack>
        </Flex>
      </DriverShell>
    );
  }

  if (error || !data) {
    const isDriverRecordError = error?.includes('Driver record not found');

    return (
      <DriverShell title="Driver Profile" subtitle="Error loading data">
        <Alert status="error" borderRadius="lg">
          <AlertIcon />
          <VStack align="start" spacing={3}>
            <Text fontWeight="bold">Failed to load profile data</Text>
            <Text fontSize="sm">{error}</Text>
            <HStack spacing={3}>
              <Button size="md" onClick={() => fetchProfileData()}>
                Try Again
              </Button>
              {isDriverRecordError && (
                <Button
                  size="md"
                  colorScheme="blue"
                  onClick={async () => {
                    try {
                      const response = await fetch('/api/debug/create-driver-record', {
                        method: 'POST',
                      });
                      if (response.ok) {
                        toast({
                          title: 'Driver Record Created',
                          description: 'Driver record created. Refreshing profile...',
                          status: 'success',
                          duration: 2000,
                        });
                        fetchProfileData();
                      }
                    } catch (error) {
                      console.error('Error creating driver record:', error);
                    }
                  }}
                >
                  Create Driver Record
                </Button>
              )}
              <Button
                size="md"
                colorScheme="green"
                onClick={createSampleProfile}
              >
                Create Sample Data
              </Button>
            </HStack>
          </VStack>
        </Alert>
      </DriverShell>
    );
  }

  return (
    <DriverShell
      title="Driver Profile"
      subtitle="Manage your profile information and track your performance metrics"
      actions={
        <HStack spacing={2}>
          <Text fontSize="sm" color="text.secondary">
            Last updated: {new Date().toLocaleTimeString()}
          </Text>
          <Tooltip label="Refresh profile data">
            <IconButton
              size="sm"
              variant="outline"
              icon={<FiRefreshCw />}
              onClick={() => fetchProfileData(true)}
              isLoading={refreshing}
              aria-label="Refresh"
            />
          </Tooltip>
        </HStack>
      }
    >
      <VStack spacing={8} align="stretch">
        {/* Action Buttons */}
        <Flex justify="center" gap={4} flexWrap="wrap">
          {data.profileCompleteness < 50 && (
            <Button
              variant="outline"
              colorScheme="green"
              size="lg"
              onClick={createSampleProfile}
            >
              Add Sample Data
            </Button>
          )}
          {!isEditing ? (
            <Button
              leftIcon={<FiEdit />}
              onClick={handleEditStart}
              colorScheme="blue"
              size="lg"
            >
              Edit Profile
            </Button>
          ) : (
            <HStack spacing={3}>
              <Button
                leftIcon={<FiSave />}
                onClick={handleEditSave}
                isLoading={isSaving}
                colorScheme="green"
                size="lg"
              >
                Save Changes
              </Button>
              <Button
                leftIcon={<FiX />}
                onClick={handleEditCancel}
                variant="outline"
                colorScheme="red"
                size="lg"
              >
                Cancel
              </Button>
            </HStack>
          )}
        </Flex>

        {/* Profile Overview */}
        <Card
          bg="bg.card"
          border="1px solid"
          borderColor="border.primary"
          borderRadius="xl"
          position="relative"
          overflow="hidden"
          boxShadow="0 0 30px rgba(59, 130, 246, 0.5), 0 0 60px rgba(59, 130, 246, 0.3)"
          transition="all 0.3s"
          animation="pulse-profile-main 4s ease-in-out infinite"
          _hover={{
            boxShadow: "0 0 40px rgba(59, 130, 246, 0.7), 0 0 80px rgba(59, 130, 246, 0.4)",
            _before: {
              content: '""',
              position: "absolute",
              top: "0",
              left: "-100%",
              width: "100%",
              height: "100%",
              background: "linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.2), transparent)",
              animation: "wave-main-profile 1.2s ease-out",
              zIndex: 1
            }
          }}
          sx={{
            "@keyframes pulse-profile-main": {
              "0%, 100%": { boxShadow: "0 0 25px rgba(59, 130, 246, 0.4), 0 0 50px rgba(59, 130, 246, 0.2)" },
              "50%": { boxShadow: "0 0 35px rgba(59, 130, 246, 0.6), 0 0 70px rgba(59, 130, 246, 0.35)" }
            },
            "@keyframes wave-main-profile": {
              "0%": { left: "-100%" },
              "100%": { left: "100%" }
            }
          }}
          _after={{
            content: '""',
            position: 'absolute',
            inset: 0,
            borderRadius: 'xl',
            padding: '1px',
            background: 'linear-gradient(135deg, rgba(0,194,255,0.2), rgba(0,209,143,0.2))',
            WebkitMask: 'linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0)',
            WebkitMaskComposite: 'xor',
            maskComposite: 'exclude',
            pointerEvents: 'none',
          }}
        >
          <CardBody p={8} position="relative" zIndex={2}>
            <VStack spacing={8} align="stretch">
              {/* Main Profile Info */}
              <Flex direction={{ base: "column", md: "row" }} align={{ base: "center", md: "start" }} gap={8}>
                <VStack spacing={4}>
                  <Avatar
                    size="2xl"
                    src={data.profileImage}
                    name={`${data.firstName} ${data.lastName}`}
                    bg="blue.500"
                    color="white"
                    fontWeight="bold"
                    fontSize="2xl"
                    boxShadow="0 0 20px rgba(59, 130, 246, 0.7), 0 0 40px rgba(59, 130, 246, 0.4)"
                  />
                  <VStack spacing={2}>
                    <Badge 
                      colorScheme={getStatusColor(data.onboardingStatus)} 
                      fontSize="md"
                      px={4}
                      py={1}
                      borderRadius="full"
                      textTransform="uppercase"
                      fontWeight="bold"
                    >
                      {data.onboardingStatus}
                    </Badge>
                    <Badge 
                      colorScheme={data.isOnline ? 'green' : 'gray'} 
                      fontSize="sm"
                      px={3}
                      py={1}
                      borderRadius="full"
                    >
                      {data.isOnline ? '🟢 Online' : '⚫ Offline'}
                    </Badge>
                  </VStack>
                </VStack>

                <VStack align={{ base: "center", md: "start" }} spacing={6} flex={1}>
                  <VStack align={{ base: "center", md: "start" }} spacing={3}>
                    <Heading 
                      size="2xl" 
                      color="white" 
                      textAlign={{ base: "center", md: "left" }}
                      textShadow="0 0 15px rgba(59, 130, 246, 0.9), 0 0 30px rgba(59, 130, 246, 0.6)"
                    >
                      {data.firstName} {data.lastName}
                    </Heading>
                    
                    <Text 
                      fontSize="lg" 
                      color="white" 
                      maxW="2xl" 
                      textAlign={{ base: "center", md: "left" }}
                      opacity={0.9}
                      textShadow="0 0 8px rgba(255, 255, 255, 0.5)"
                    >
                      Driver ID: {data.driverId}
                    </Text>
                  </VStack>
                  
                  <VStack spacing={4} align={{ base: "center", md: "start" }}>
                    <HStack spacing={6} flexWrap="wrap" justify={{ base: "center", md: "start" }}>
                      <HStack spacing={3}>
                        <Box as={FiMail} color="blue.500" size="18px" />
                        <Text fontSize="lg" color="white" fontWeight="medium" textShadow="0 0 6px rgba(255, 255, 255, 0.4)">{data.email}</Text>
                      </HStack>
                      <HStack spacing={3}>
                        <Box as={FiPhone} color="green.500" size="18px" />
                        <Text fontSize="lg" color="white" fontWeight="medium" textShadow="0 0 6px rgba(255, 255, 255, 0.4)">{data.phone}</Text>
                      </HStack>
                    </HStack>
                    
                    <HStack spacing={3}>
                      <Box as={FiMapPin} color="purple.500" size="18px" />
                      <Text fontSize="lg" color="white" fontWeight="medium" textShadow="0 0 6px rgba(255, 255, 255, 0.4)">Base: {data.basePostcode}</Text>
                    </HStack>

                    {data.bio && (
                      <Box p={4} bg="rgba(59, 130, 246, 0.1)" borderRadius="lg" maxW="2xl" border="1px solid" borderColor="border.secondary">
                        <Text fontSize="md" color="white" lineHeight="1.6" textShadow="0 0 6px rgba(255, 255, 255, 0.4)">
                          {data.bio}
                        </Text>
                      </Box>
                    )}
                  </VStack>
                </VStack>

                {/* Profile Completion */}
                <VStack spacing={4} align="center" minW="200px">
                  <VStack spacing={2} align="center">
                    <Text 
                      fontSize="4xl" 
                      fontWeight="bold" 
                      color="white"
                      textShadow={
                        getCompletionColor(data.profileCompleteness) === 'green' 
                          ? "0 0 20px rgba(34, 197, 94, 0.9), 0 0 40px rgba(34, 197, 94, 0.6)"
                          : getCompletionColor(data.profileCompleteness) === 'yellow' 
                          ? "0 0 20px rgba(251, 191, 36, 0.9), 0 0 40px rgba(251, 191, 36, 0.6)"
                          : "0 0 20px rgba(239, 68, 68, 0.9), 0 0 40px rgba(239, 68, 68, 0.6)"
                      }
                    >
                      {data.profileCompleteness}%
                    </Text>
                    <Text 
                      fontSize="lg" 
                      color="white" 
                      fontWeight="medium"
                      textShadow="0 0 8px rgba(255, 255, 255, 0.5)"
                    >
                      Profile Complete
                    </Text>
                  </VStack>
                  <Progress
                    value={data.profileCompleteness}
                    size="lg"
                    width="150px"
                    colorScheme={getCompletionColor(data.profileCompleteness)}
                    borderRadius="full"
                  />
                  {data.profileCompleteness < 100 && (
                    <Text 
                      fontSize="sm" 
                      color="white" 
                      textAlign="center"
                      opacity={0.8}
                      textShadow="0 0 6px rgba(255, 255, 255, 0.4)"
                    >
                      Complete your profile to get more job opportunities
                    </Text>
                  )}
                </VStack>
              </Flex>

              {/* Member Info */}
              <Divider />
              <SimpleGrid columns={{ base: 1, md: 2, lg: 3 }} spacing={6}>
                <VStack spacing={2} align="start">
                  <Text fontSize="sm" color="white" fontWeight="semibold" textTransform="uppercase" opacity={0.7}>Member Since</Text>
                  <HStack spacing={2}>
                    <Box as={FiCalendar} color="blue.500" />
                    <Text fontSize="lg" fontWeight="medium" color="white" textShadow="0 0 6px rgba(255, 255, 255, 0.4)">
                      {format(new Date(data.joinedAt), 'MMMM yyyy')}
                    </Text>
                  </HStack>
                </VStack>
                
                {data.lastLogin && (
                  <VStack spacing={2} align="start">
                    <Text fontSize="sm" color="white" fontWeight="semibold" textTransform="uppercase" opacity={0.7}>Last Login</Text>
                    <HStack spacing={2}>
                      <Box as={FiClock} color="green.500" />
                      <Text fontSize="lg" fontWeight="medium" color="white" textShadow="0 0 6px rgba(255, 255, 255, 0.4)">
                        {formatDistanceToNow(new Date(data.lastLogin), { addSuffix: true })}
                      </Text>
                    </HStack>
                  </VStack>
                )}
                
                <VStack spacing={2} align="start">
                  <Text fontSize="sm" color="white" fontWeight="semibold" textTransform="uppercase" opacity={0.7}>Vehicle Type</Text>
                  <HStack spacing={2}>
                    <Box as={FiTruck} color="purple.500" />
                    <Text fontSize="lg" fontWeight="medium" color="white" textTransform="capitalize" textShadow="0 0 6px rgba(255, 255, 255, 0.4)">
                      {data.vehicleType}
                    </Text>
                  </HStack>
                </VStack>
              </SimpleGrid>
            </VStack>
          </CardBody>
        </Card>

        {/* Performance Stats */}
        <VStack spacing={4} align="stretch">
          <Heading 
            size="lg" 
            color="white" 
            textAlign="center"
            textShadow="0 0 15px rgba(59, 130, 246, 0.9), 0 0 30px rgba(59, 130, 246, 0.6)"
          >
            Performance Overview
          </Heading>
          
          <SimpleGrid columns={{ base: 1, md: 2, lg: 4 }} spacing={8}>
            {/* Average Rating Card */}
            <Card 
              bg="yellow.50" 
              borderLeft="4px solid" 
              borderLeftColor="yellow.500" 
              position="relative"
              overflow="hidden"
              boxShadow="0 0 20px rgba(251, 191, 36, 0.5), 0 0 40px rgba(251, 191, 36, 0.3)"
              transition="all 0.3s"
              animation="pulse-rating 3s ease-in-out infinite"
              _hover={{
                transform: "translateY(-4px)",
                boxShadow: "0 0 30px rgba(251, 191, 36, 0.7), 0 0 60px rgba(251, 191, 36, 0.4)",
                _before: {
                  content: '""',
                  position: "absolute",
                  top: "0",
                  left: "-100%",
                  width: "100%",
                  height: "100%",
                  background: "linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.3), transparent)",
                  animation: "wave-profile 0.8s ease-out",
                  zIndex: 1
                }
              }}
              sx={{
                "@keyframes pulse-rating": {
                  "0%, 100%": { boxShadow: "0 0 15px rgba(251, 191, 36, 0.4), 0 0 30px rgba(251, 191, 36, 0.2)" },
                  "50%": { boxShadow: "0 0 25px rgba(251, 191, 36, 0.7), 0 0 50px rgba(251, 191, 36, 0.4)" }
                },
                "@keyframes wave-profile": {
                  "0%": { left: "-100%" },
                  "100%": { left: "100%" }
                }
              }}
            >
              <CardBody p={6} position="relative" zIndex={2}>
                <VStack spacing={4} align="center">
                  <Box as={FiStar} size="32px" color="yellow.500" />
                  <Stat textAlign="center">
                    <StatLabel fontSize="md" fontWeight="semibold" color="white" textShadow="0 0 8px rgba(255, 255, 255, 0.5)">Average Rating</StatLabel>
                    {data.totalJobs > 0 ? (
                      <>
                        <StatNumber 
                          fontSize="3xl" 
                          fontWeight="bold" 
                          color="white"
                          textShadow="0 0 15px rgba(251, 191, 36, 0.9), 0 0 30px rgba(251, 191, 36, 0.6)"
                        >
                          <HStack spacing={2} justify="center">
                            <Text>{data.averageRating.toFixed(1)}</Text>
                            <Box as={FiStar} fill="currentColor" />
                          </HStack>
                        </StatNumber>
                        <StatHelpText fontSize="md" color="white" opacity={0.8}>
                          From {data.totalJobs} completed jobs
                        </StatHelpText>
                      </>
                    ) : (
                      <>
                        <StatNumber fontSize="2xl" fontWeight="bold" color="white" opacity={0.7}>
                          No ratings yet
                        </StatNumber>
                        <StatHelpText fontSize="md" color="white" opacity={0.7}>
                          Complete jobs to earn ratings
                        </StatHelpText>
                      </>
                    )}
                  </Stat>
                </VStack>
              </CardBody>
            </Card>

            {/* Total Jobs Card */}
            <Card 
              bg="blue.50" 
              borderLeft="4px solid" 
              borderLeftColor="blue.500" 
              position="relative"
              overflow="hidden"
              boxShadow="0 0 20px rgba(59, 130, 246, 0.5), 0 0 40px rgba(59, 130, 246, 0.3)"
              transition="all 0.3s"
              animation="pulse-jobs 3s ease-in-out infinite"
              _hover={{
                transform: "translateY(-4px)",
                boxShadow: "0 0 30px rgba(59, 130, 246, 0.7), 0 0 60px rgba(59, 130, 246, 0.4)",
                _before: {
                  content: '""',
                  position: "absolute",
                  top: "0",
                  left: "-100%",
                  width: "100%",
                  height: "100%",
                  background: "linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.3), transparent)",
                  animation: "wave-profile 0.8s ease-out",
                  zIndex: 1
                }
              }}
              sx={{
                "@keyframes pulse-jobs": {
                  "0%, 100%": { boxShadow: "0 0 15px rgba(59, 130, 246, 0.4), 0 0 30px rgba(59, 130, 246, 0.2)" },
                  "50%": { boxShadow: "0 0 25px rgba(59, 130, 246, 0.7), 0 0 50px rgba(59, 130, 246, 0.4)" }
                },
                "@keyframes wave-profile": {
                  "0%": { left: "-100%" },
                  "100%": { left: "100%" }
                }
              }}
            >
              <CardBody p={6} position="relative" zIndex={2}>
                <VStack spacing={4} align="center">
                  <Box as={FiTruck} size="32px" color="blue.500" />
                  <Stat textAlign="center">
                    <StatLabel fontSize="md" fontWeight="semibold" color="white" textShadow="0 0 8px rgba(255, 255, 255, 0.5)">Total Jobs</StatLabel>
                    <StatNumber 
                      fontSize="3xl" 
                      fontWeight="bold" 
                      color="white"
                      textShadow="0 0 15px rgba(59, 130, 246, 0.9), 0 0 30px rgba(59, 130, 246, 0.6)"
                    >
                      {data.totalJobs}
                    </StatNumber>
                    <StatHelpText fontSize="md" color="white" opacity={0.8}>
                      Completed successfully
                    </StatHelpText>
                  </Stat>
                </VStack>
              </CardBody>
            </Card>

            {/* Completion Rate Card */}
            <Card 
              bg="green.50" 
              borderLeft="4px solid" 
              borderLeftColor="green.500" 
              position="relative"
              overflow="hidden"
              boxShadow="0 0 20px rgba(34, 197, 94, 0.5), 0 0 40px rgba(34, 197, 94, 0.3)"
              transition="all 0.3s"
              animation="pulse-completion 3s ease-in-out infinite"
              _hover={{
                transform: "translateY(-4px)",
                boxShadow: "0 0 30px rgba(34, 197, 94, 0.7), 0 0 60px rgba(34, 197, 94, 0.4)",
                _before: {
                  content: '""',
                  position: "absolute",
                  top: "0",
                  left: "-100%",
                  width: "100%",
                  height: "100%",
                  background: "linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.3), transparent)",
                  animation: "wave-profile 0.8s ease-out",
                  zIndex: 1
                }
              }}
              sx={{
                "@keyframes pulse-completion": {
                  "0%, 100%": { boxShadow: "0 0 15px rgba(34, 197, 94, 0.4), 0 0 30px rgba(34, 197, 94, 0.2)" },
                  "50%": { boxShadow: "0 0 25px rgba(34, 197, 94, 0.7), 0 0 50px rgba(34, 197, 94, 0.4)" }
                },
                "@keyframes wave-profile": {
                  "0%": { left: "-100%" },
                  "100%": { left: "100%" }
                }
              }}
            >
              <CardBody p={6} position="relative" zIndex={2}>
                <VStack spacing={4} align="center">
                  <Box as={FiCheck} size="32px" color="green.500" />
                  <Stat textAlign="center">
                    <StatLabel fontSize="md" fontWeight="semibold" color="white" textShadow="0 0 8px rgba(255, 255, 255, 0.5)">Completion Rate</StatLabel>
                    <StatNumber 
                      fontSize="3xl" 
                      fontWeight="bold" 
                      color="white"
                      textShadow="0 0 15px rgba(34, 197, 94, 0.9), 0 0 30px rgba(34, 197, 94, 0.6)"
                    >
                      {data.totalJobs > 0 ? `${(data.completionRate * 100).toFixed(1)}%` : 'N/A'}
                    </StatNumber>
                    <StatHelpText fontSize="md" color="white" opacity={0.8}>
                      Jobs completed on time
                    </StatHelpText>
                  </Stat>
                </VStack>
              </CardBody>
            </Card>

            {/* On-Time Rate Card */}
            <Card 
              bg="purple.50" 
              borderLeft="4px solid" 
              borderLeftColor="purple.500" 
              position="relative"
              overflow="hidden"
              boxShadow="0 0 20px rgba(168, 85, 247, 0.5), 0 0 40px rgba(168, 85, 247, 0.3)"
              transition="all 0.3s"
              animation="pulse-ontime 3s ease-in-out infinite"
              _hover={{
                transform: "translateY(-4px)",
                boxShadow: "0 0 30px rgba(168, 85, 247, 0.7), 0 0 60px rgba(168, 85, 247, 0.4)",
                _before: {
                  content: '""',
                  position: "absolute",
                  top: "0",
                  left: "-100%",
                  width: "100%",
                  height: "100%",
                  background: "linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.3), transparent)",
                  animation: "wave-profile 0.8s ease-out",
                  zIndex: 1
                }
              }}
              sx={{
                "@keyframes pulse-ontime": {
                  "0%, 100%": { boxShadow: "0 0 15px rgba(168, 85, 247, 0.4), 0 0 30px rgba(168, 85, 247, 0.2)" },
                  "50%": { boxShadow: "0 0 25px rgba(168, 85, 247, 0.7), 0 0 50px rgba(168, 85, 247, 0.4)" }
                },
                "@keyframes wave-profile": {
                  "0%": { left: "-100%" },
                  "100%": { left: "100%" }
                }
              }}
            >
              <CardBody p={6} position="relative" zIndex={2}>
                <VStack spacing={4} align="center">
                  <Box as={FiClock} size="32px" color="purple.500" />
                  <Stat textAlign="center">
                    <StatLabel fontSize="md" fontWeight="semibold" color="white" textShadow="0 0 8px rgba(255, 255, 255, 0.5)">Punctuality Rate</StatLabel>
                    <StatNumber 
                      fontSize="3xl" 
                      fontWeight="bold" 
                      color="white"
                      textShadow="0 0 15px rgba(168, 85, 247, 0.9), 0 0 30px rgba(168, 85, 247, 0.6)"
                    >
                      {data.totalJobs > 0 ? `${(data.onTimeRate * 100).toFixed(1)}%` : 'N/A'}
                    </StatNumber>
                    <StatHelpText fontSize="md" color="white" opacity={0.8}>
                      On-time deliveries
                    </StatHelpText>
                  </Stat>
                </VStack>
              </CardBody>
            </Card>
          </SimpleGrid>

          {/* Performance Summary */}
          {data.totalJobs === 0 && (
            <Card 
              bg="blue.50" 
              borderRadius="lg"
              position="relative"
              overflow="hidden"
              boxShadow="0 0 25px rgba(59, 130, 246, 0.5), 0 0 50px rgba(59, 130, 246, 0.3)"
              transition="all 0.3s"
              animation="pulse-summary 4s ease-in-out infinite"
              _hover={{
                boxShadow: "0 0 35px rgba(59, 130, 246, 0.7), 0 0 70px rgba(59, 130, 246, 0.4)",
                _before: {
                  content: '""',
                  position: "absolute",
                  top: "0",
                  left: "-100%",
                  width: "100%",
                  height: "100%",
                  background: "linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.3), transparent)",
                  animation: "wave-summary 1s ease-out",
                  zIndex: 1
                }
              }}
              sx={{
                "@keyframes pulse-summary": {
                  "0%, 100%": { boxShadow: "0 0 20px rgba(59, 130, 246, 0.4), 0 0 40px rgba(59, 130, 246, 0.2)" },
                  "50%": { boxShadow: "0 0 30px rgba(59, 130, 246, 0.7), 0 0 60px rgba(59, 130, 246, 0.4)" }
                },
                "@keyframes wave-summary": {
                  "0%": { left: "-100%" },
                  "100%": { left: "100%" }
                }
              }}
            >
              <CardBody p={6} position="relative" zIndex={2}>
                <VStack spacing={4} textAlign="center">
                  <Box as={FiTrendingUp} size="48px" color="blue.500" />
                  <Heading 
                    size="md" 
                    color="white"
                    textShadow="0 0 15px rgba(59, 130, 246, 0.9), 0 0 30px rgba(59, 130, 246, 0.6)"
                  >
                    Ready to Start Your Journey?
                  </Heading>
                  <Text 
                    fontSize="lg" 
                    color="white"
                    textShadow="0 0 10px rgba(255, 255, 255, 0.6)"
                  >
                    Complete your first job to see your performance metrics here. 
                    Your ratings and statistics will be displayed as you build your reputation.
                  </Text>
                </VStack>
              </CardBody>
            </Card>
          )}
        </VStack>

        {/* Profile Details */}
        <VStack spacing={4} align="stretch">
          <Heading 
            size="lg" 
            color="white" 
            textAlign="center"
            textShadow="0 0 15px rgba(34, 197, 94, 0.9), 0 0 30px rgba(34, 197, 94, 0.6)"
          >
            Profile Details
          </Heading>
          
          <SimpleGrid columns={{ base: 1, lg: 2 }} spacing={8}>
          {/* Personal Information */}
          <Card
            position="relative"
            overflow="hidden"
            boxShadow="0 0 20px rgba(59, 130, 246, 0.5), 0 0 40px rgba(59, 130, 246, 0.3)"
            transition="all 0.3s"
            _hover={{
              boxShadow: "0 0 30px rgba(59, 130, 246, 0.7), 0 0 60px rgba(59, 130, 246, 0.4)",
              _before: {
                content: '""',
                position: "absolute",
                top: "0",
                left: "-100%",
                width: "100%",
                height: "100%",
                background: "linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.2), transparent)",
                animation: "wave-card 1s ease-out",
                zIndex: 1
              }
            }}
            sx={{
              "@keyframes wave-card": {
                "0%": { left: "-100%" },
                "100%": { left: "100%" }
              }
            }}
          >
            <CardHeader position="relative" zIndex={2}>
              <Heading 
                size="md"
                color="white"
                textShadow="0 0 12px rgba(59, 130, 246, 0.8), 0 0 24px rgba(59, 130, 246, 0.4)"
              >
                <FiUser style={{ display: 'inline', marginRight: '8px' }} />
                Personal Information
              </Heading>
            </CardHeader>
            <CardBody position="relative" zIndex={2}>
              <VStack spacing={4} align="stretch">
                <FormControl>
                  <FormLabel color="white" opacity={0.9}>First Name</FormLabel>
                  <Input
                    value={isEditing ? editForm.firstName : data.firstName}
                    onChange={(e) => setEditForm({ ...editForm, firstName: e.target.value })}
                    isReadOnly={!isEditing}
                    variant={isEditing ? 'outline' : 'filled'}
                  />
                </FormControl>

                <FormControl>
                  <FormLabel color="white" opacity={0.9}>Last Name</FormLabel>
                  <Input
                    value={isEditing ? editForm.lastName : data.lastName}
                    onChange={(e) => setEditForm({ ...editForm, lastName: e.target.value })}
                    isReadOnly={!isEditing}
                    variant={isEditing ? 'outline' : 'filled'}
                  />
                </FormControl>

                <FormControl>
                  <FormLabel color="white" opacity={0.9}>Phone Number</FormLabel>
                  <Input
                    value={isEditing ? editForm.phone : data.phone}
                    onChange={(e) => setEditForm({ ...editForm, phone: e.target.value })}
                    isReadOnly={!isEditing}
                    variant={isEditing ? 'outline' : 'filled'}
                  />
                </FormControl>

                <FormControl>
                  <FormLabel color="white" opacity={0.9}>Email Address</FormLabel>
                  <Input
                    value={isEditing ? editForm.email : data.email}
                    onChange={(e) => setEditForm({ ...editForm, email: e.target.value })}
                    isReadOnly={!isEditing}
                    variant={isEditing ? 'outline' : 'filled'}
                  />
                </FormControl>

                <FormControl>
                  <FormLabel color="white" opacity={0.9}>Bio</FormLabel>
                  <Textarea
                    value={isEditing ? editForm.bio : data.bio}
                    onChange={(e) => setEditForm({ ...editForm, bio: e.target.value })}
                    isReadOnly={!isEditing}
                    variant={isEditing ? 'outline' : 'filled'}
                    placeholder="Tell us about yourself..."
                    rows={3}
                  />
                </FormControl>
              </VStack>
            </CardBody>
          </Card>

          {/* Driver Information */}
          <Card
            position="relative"
            overflow="hidden"
            boxShadow="0 0 20px rgba(34, 197, 94, 0.5), 0 0 40px rgba(34, 197, 94, 0.3)"
            transition="all 0.3s"
            _hover={{
              boxShadow: "0 0 30px rgba(34, 197, 94, 0.7), 0 0 60px rgba(34, 197, 94, 0.4)",
              _before: {
                content: '""',
                position: "absolute",
                top: "0",
                left: "-100%",
                width: "100%",
                height: "100%",
                background: "linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.2), transparent)",
                animation: "wave-card 1s ease-out",
                zIndex: 1
              }
            }}
            sx={{
              "@keyframes wave-card": {
                "0%": { left: "-100%" },
                "100%": { left: "100%" }
              }
            }}
          >
            <CardHeader position="relative" zIndex={2}>
              <Heading 
                size="md"
                color="white"
                textShadow="0 0 12px rgba(34, 197, 94, 0.8), 0 0 24px rgba(34, 197, 94, 0.4)"
              >
                <FiTruck style={{ display: 'inline', marginRight: '8px' }} />
                Driver Information
              </Heading>
            </CardHeader>
            <CardBody position="relative" zIndex={2}>
              <VStack spacing={4} align="stretch">
                <FormControl>
                  <FormLabel color="white" opacity={0.9}>Base Postcode</FormLabel>
                  <Input
                    value={isEditing ? editForm.basePostcode : data.basePostcode}
                    onChange={(e) => setEditForm({ ...editForm, basePostcode: e.target.value })}
                    isReadOnly={!isEditing}
                    variant={isEditing ? 'outline' : 'filled'}
                  />
                </FormControl>

                <FormControl>
                  <FormLabel color="white" opacity={0.9}>Vehicle Type</FormLabel>
                  {isEditing ? (
                    <Select
                      value={editForm.vehicleType}
                      onChange={(e) => setEditForm({ ...editForm, vehicleType: e.target.value })}
                    >
                      <option value="">Select vehicle type</option>
                      <option value="small_van">Small Van</option>
                      <option value="large_van">Large Van</option>
                      <option value="truck">Truck</option>
                      <option value="bike">Bike</option>
                    </Select>
                  ) : (
                    <Input
                      value={data.vehicleType || 'Not specified'}
                      isReadOnly
                      variant="filled"
                    />
                  )}
                </FormControl>

                <FormControl>
                  <FormLabel color="white" opacity={0.9}>Driver Status</FormLabel>
                  <Input
                    value={data.status}
                    isReadOnly
                    variant="filled"
                  />
                </FormControl>

                <FormControl>
                  <FormLabel color="white" opacity={0.9}>Strikes</FormLabel>
                  <Input
                    value={data.strikes}
                    isReadOnly
                    variant="filled"
                  />
                </FormControl>

                <FormControl>
                  <VStack align="stretch" spacing={3}>
                    <HStack justify="space-between">
                      <VStack align="start" spacing={0}>
                        <FormLabel htmlFor="location-consent" mb="0" fontWeight="semibold">
                          Location Sharing
                        </FormLabel>
                        <Text fontSize="sm" color="gray.600">
                          {data.hasActiveOrders 
                            ? 'Required while you have active orders' 
                            : 'Allow customers to track your location'
                          }
                        </Text>
                      </VStack>
                      <Switch
                        id="location-consent"
                        size="lg"
                        colorScheme="green"
                        isChecked={data.locationConsent}
                        isDisabled={data.hasActiveOrders && data.locationConsent}
                        onChange={async (e) => {
                          if (data.hasActiveOrders && data.locationConsent) {
                            toast({
                              title: 'Cannot Disable Location Sharing',
                              description: 'You cannot disable location sharing while you have active orders.',
                              status: 'warning',
                              duration: 5000,
                              isClosable: true,
                            });
                            return;
                          }
                          
                          try {
                            const response = await fetch('/api/driver/profile', {
                              method: 'PUT',
                              headers: { 'Content-Type': 'application/json' },
                              body: JSON.stringify({ locationConsent: e.target.checked }),
                            });

                            if (response.ok) {
                              setData((prev: any) => ({ ...prev, locationConsent: e.target.checked }));
                              toast({
                                title: 'Location Sharing Updated',
                                description: `Location sharing has been ${e.target.checked ? 'enabled' : 'disabled'}.`,
                                status: 'success',
                                duration: 3000,
                                isClosable: true,
                              });
                            } else {
                              const error = await response.json();
                              throw new Error(error.error || 'Failed to update location sharing');
                            }
                          } catch (error) {
                            console.error('Location sharing update error:', error);
                            toast({
                              title: 'Error',
                              description: error instanceof Error ? error.message : 'Failed to update location sharing',
                              status: 'error',
                              duration: 5000,
                              isClosable: true,
                            });
                          }
                        }}
                      />
                    </HStack>
                    
                    {data.hasActiveOrders && (
                      <Text fontSize="xs" color="orange.600" fontWeight="medium">
                        🚨 Location sharing is mandatory while you have active orders
                      </Text>
                    )}
                    
                    <Text fontSize="xs" color="gray.500">
                      • Automatically enabled when you go online<br/>
                      • Required for customer order tracking<br/>
                      • Cannot be disabled during active deliveries
                    </Text>
                  </VStack>
                </FormControl>
              </VStack>
            </CardBody>
          </Card>
        </SimpleGrid>

        {/* Recent Reviews */}
        {data.recentRatings.length > 0 && (
          <Card>
            <CardHeader>
              <Heading size="md">
                <FiStar style={{ display: 'inline', marginRight: '8px' }} />
                Recent Customer Reviews
              </Heading>
            </CardHeader>
            <CardBody>
              <Table variant="simple">
                <Thead>
                  <Tr>
                    <Th>Customer</Th>
                    <Th>Rating</Th>
                    <Th>Review</Th>
                    <Th>Job</Th>
                    <Th>Date</Th>
                  </Tr>
                </Thead>
                <Tbody>
                  {data.recentRatings.map((rating) => (
                    <Tr key={rating.id}>
                      <Td>{rating.customerName}</Td>
                      <Td>
                        <HStack spacing={1}>
                          {renderStars(rating.rating)}
                          <Text fontSize="sm" ml={2}>
                            ({rating.rating}/5)
                          </Text>
                        </HStack>
                      </Td>
                      <Td>
                        <Text fontSize="sm" noOfLines={2} maxW="300px">
                          {rating.review || 'No review provided'}
                        </Text>
                      </Td>
                      <Td>
                        <Text fontSize="sm" fontFamily="mono">
                          {rating.bookingReference}
                        </Text>
                      </Td>
                      <Td>
                        <Text fontSize="sm">
                          {formatDistanceToNow(new Date(rating.createdAt), { addSuffix: true })}
                        </Text>
                      </Td>
                    </Tr>
                  ))}
                </Tbody>
              </Table>
            </CardBody>
          </Card>
        )}

        {/* Account Status */}
        <Card>
          <CardHeader>
            <Heading size="md">
              <FiTarget style={{ display: 'inline', marginRight: '8px' }} />
              Account Status
            </Heading>
          </CardHeader>
          <CardBody>
            <SimpleGrid columns={{ base: 1, md: 3 }} spacing={6}>
              <VStack spacing={2}>
                <Text fontSize="sm" color="gray.500">Application Status</Text>
                <Badge colorScheme={getStatusColor(data.applicationStatus)} size="lg">
                  {data.applicationStatus}
                </Badge>
                {data.applicationDate && (
                  <Text fontSize="xs" color="gray.500">
                    Applied {formatDistanceToNow(new Date(data.applicationDate), { addSuffix: true })}
                  </Text>
                )}
              </VStack>

              <VStack spacing={2}>
                <Text fontSize="sm" color="gray.500">Account Status</Text>
                <Badge colorScheme={getStatusColor(data.status)} size="lg">
                  {data.status}
                </Badge>
                {data.lastSeenAt && (
                  <Text fontSize="xs" color="gray.500">
                    Last seen {formatDistanceToNow(new Date(data.lastSeenAt), { addSuffix: true })}
                  </Text>
                )}
              </VStack>

              <VStack spacing={2}>
                <Text fontSize="sm" color="gray.500">Online Status</Text>
                <Badge colorScheme={data.isOnline ? 'green' : 'gray'} size="lg">
                  {data.isOnline ? 'Online' : 'Offline'}
                </Badge>
                <Text fontSize="xs" color="gray.500">
                  Location consent: {data.locationConsent ? 'Granted' : 'Not granted'}
                </Text>
              </VStack>
            </SimpleGrid>
          </CardBody>
        </Card>
        </VStack>
      </VStack>
    </DriverShell>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import {
  Box,
  Container,
  VStack,
  Heading,
  Text,
  FormControl,
  FormLabel,
  Input,
  Button,
  Alert,
  AlertIcon,
  Card,
  CardBody,
  Link as ChakraLink,
  IconButton,
  HStack,
  Icon,
  InputGroup,
  InputRightElement,
  useColorModeValue,
  useToast,
} from '@chakra-ui/react';
import { useRouter, useSearchParams } from 'next/navigation';
import NextLink from 'next/link';
import {
  FaTruck,
  FaArrowLeft,
  FaLock,
  FaShieldAlt,
  FaCheckCircle,
  FaEye,
  FaEyeSlash,
} from 'react-icons/fa';

export default function DriverResetPasswordPage() {
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState(false);
  const [token, setToken] = useState('');
  const router = useRouter();
  const searchParams = useSearchParams();
  const toast = useToast();

  const bgColor = useColorModeValue('white', 'gray.800');
  const cardBg = useColorModeValue('white', 'gray.700');

  useEffect(() => {
    const tokenParam = searchParams?.get('token');
    if (tokenParam) {
      setToken(tokenParam);
      console.log('🔐 Reset token received:', tokenParam.substring(0, 8) + '...');
    } else {
      setError('Invalid or missing reset token. Please request a new password reset.');
    }
  }, [searchParams]);

  const validatePassword = (password: string): string[] => {
    const errors = [];
    if (password.length < 8) {
      errors.push('Password must be at least 8 characters long');
    }
    if (!/(?=.*[a-z])/.test(password)) {
      errors.push('Password must contain at least one lowercase letter');
    }
    if (!/(?=.*[A-Z])/.test(password)) {
      errors.push('Password must contain at least one uppercase letter');
    }
    if (!/(?=.*\d)/.test(password)) {
      errors.push('Password must contain at least one number');
    }
    return errors;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError('');

    // Validate passwords
    const passwordErrors = validatePassword(password);
    if (passwordErrors.length > 0) {
      setError(passwordErrors.join('. '));
      setIsLoading(false);
      return;
    }

    if (password !== confirmPassword) {
      setError('Passwords do not match');
      setIsLoading(false);
      return;
    }

    try {
      console.log('🔐 Submitting password reset for token:', token.substring(0, 8) + '...');
      
      const response = await fetch('/api/driver/auth/reset', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ token, password }),
      });

      const result = await response.json();
      console.log('🔐 Password reset response:', result);

      if (response.ok) {
        setSuccess(true);
        toast({
          title: 'Password Reset Successful',
          description: 'Your password has been reset successfully.',
          status: 'success',
          duration: 5000,
          isClosable: true,
        });
        
        // Redirect to login after 3 seconds
        setTimeout(() => {
          router.push('/driver-auth');
        }, 3000);
      } else {
        setError(result.error || 'An error occurred. Please try again.');
        toast({
          title: 'Reset Failed',
          description: result.error || 'An error occurred. Please try again.',
          status: 'error',
          duration: 5000,
          isClosable: true,
        });
      }
    } catch (error) {
      console.error('❌ Driver Reset Password Error:', error);
      const errorMessage = error instanceof Error ? error.message : 'An error occurred';
      setError(errorMessage);
      toast({
        title: 'Error',
        description: errorMessage,
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setIsLoading(false);
    }
  };

  const handleBackClick = () => {
    router.push('/driver-auth');
  };

  if (success) {
    return (
      <Box minH="100vh" bg="gray.50" display="flex" alignItems="center" justifyContent="center" px={4}>
        <Container maxW="md">
          <VStack spacing={6} textAlign="center">
            <Box color="green.500" fontSize="4xl">
              <FaCheckCircle />
            </Box>
            <VStack spacing={2}>
              <Heading size="lg" color="gray.700">
                Password Reset Successful
              </Heading>
              <Text color="gray.600" fontSize={{ base: "sm", md: "md" }} px={4}>
                Your password has been reset successfully. You will be redirected to the login page shortly.
              </Text>
            </VStack>
            
            <Button
              colorScheme="blue"
              onClick={handleBackClick}
              size={{ base: "md", md: "lg" }}
              w={{ base: "full", md: "auto" }}
            >
              Go to Login
            </Button>
          </VStack>
        </Container>
      </Box>
    );
  }

  return (
    <Box minH="100vh" bg="gray.50" display="flex" alignItems="center" justifyContent="center" px={4}>
      <Container maxW="md">
        <VStack spacing={6} textAlign="center">
          <VStack spacing={2}>
            <Box color="blue.500" fontSize="3xl">
              <FaTruck />
            </Box>
            <Heading size="lg" color="gray.700">
              Set New Password
            </Heading>
            <Text color="gray.600" fontSize={{ base: "sm", md: "md" }}>
              Enter your new password below.
            </Text>
          </VStack>

          <Card w="full" bg={cardBg} boxShadow="lg">
            <CardBody p={6}>
              <form onSubmit={handleSubmit}>
                <VStack spacing={5}>
                  {error && (
                    <Alert status="error" borderRadius="lg">
                      <AlertIcon />
                      {error}
                    </Alert>
                  )}

                  <FormControl isRequired>
                    <FormLabel
                      fontSize="md"
                      fontWeight="semibold"
                      color="text.primary"
                      display="flex"
                      alignItems="center"
                      gap={2}
                    >
                      <Icon as={FaLock} color="blue.500" />
                      New Password
                    </FormLabel>
                    <InputGroup>
                      <Input
                        type={showPassword ? 'text' : 'password'}
                        name="password"
                        value={password}
                        onChange={e => setPassword(e.target.value)}
                        placeholder="Enter your new password"
                        size="lg"
                        borderRadius="xl"
                        borderWidth="2px"
                        borderColor="border.primary"
                        bg="bg.surface"
                        _focus={{
                          borderColor: 'blue.500',
                          boxShadow: '0 0 0 1px rgba(59, 130, 246, 0.2)',
                        }}
                        _hover={{
                          borderColor: 'blue.400',
                        }}
                        transition="all 0.2s"
                      />
                      <InputRightElement h="full" pr={3}>
                        <IconButton
                          aria-label={showPassword ? 'Hide password' : 'Show password'}
                          icon={<Icon as={showPassword ? FaEyeSlash : FaEye} />}
                          variant="ghost"
                          size="sm"
                          onClick={() => setShowPassword(!showPassword)}
                        />
                      </InputRightElement>
                    </InputGroup>
                  </FormControl>

                  <FormControl isRequired>
                    <FormLabel
                      fontSize="md"
                      fontWeight="semibold"
                      color="text.primary"
                      display="flex"
                      alignItems="center"
                      gap={2}
                    >
                      <Icon as={FaLock} color="blue.500" />
                      Confirm Password
                    </FormLabel>
                    <InputGroup>
                      <Input
                        type={showConfirmPassword ? 'text' : 'password'}
                        name="confirmPassword"
                        value={confirmPassword}
                        onChange={e => setConfirmPassword(e.target.value)}
                        placeholder="Confirm your new password"
                        size="lg"
                        borderRadius="xl"
                        borderWidth="2px"
                        borderColor="border.primary"
                        bg="bg.surface"
                        _focus={{
                          borderColor: 'blue.500',
                          boxShadow: '0 0 0 1px rgba(59, 130, 246, 0.2)',
                        }}
                        _hover={{
                          borderColor: 'blue.400',
                        }}
                        transition="all 0.2s"
                      />
                      <InputRightElement h="full" pr={3}>
                        <IconButton
                          aria-label={showConfirmPassword ? 'Hide password' : 'Show password'}
                          icon={<Icon as={showConfirmPassword ? FaEyeSlash : FaEye} />}
                          variant="ghost"
                          size="sm"
                          onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                        />
                      </InputRightElement>
                    </InputGroup>
                  </FormControl>

                  <Button
                    type="submit"
                    colorScheme="blue"
                    size="lg"
                    w="full"
                    isLoading={isLoading}
                    loadingText="Resetting Password..."
                    leftIcon={<Icon as={FaShieldAlt} />}
                    borderRadius="xl"
                    fontWeight="semibold"
                    py={6}
                  >
                    Reset Password
                  </Button>
                </VStack>
              </form>
            </CardBody>
          </Card>

          <HStack spacing={4} flexWrap="wrap" justify="center">
            <Button
              variant="ghost"
              leftIcon={<Icon as={FaArrowLeft} />}
              onClick={handleBackClick}
              size={{ base: "sm", md: "md" }}
            >
              Back to Login
            </Button>
            
            <ChakraLink as={NextLink} href="/driver/forgot" color="blue.500" fontSize="sm">
              Need a new reset link?
            </ChakraLink>
          </HStack>

          <Text color="gray.500" fontSize="xs" textAlign="center" maxW="sm">
            Password must be at least 8 characters long and contain uppercase, lowercase, and numbers.
          </Text>
        </VStack>
      </Container>
    </Box>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import {
  Container,
  Heading,
  Text,
  Box,
  VStack,
  HStack,
  Button,
  useToast,
  Spinner,
  Progress,
  Card,
  CardHeader,
  CardBody,
  Badge,
  Icon,
  Flex,
  Circle,
  Divider,
  Alert,
  AlertIcon,
  AlertTitle,
  AlertDescription,
  SimpleGrid
} from '@chakra-ui/react';
import { 
  FaMapMarkerAlt, 
  FaClock, 
  FaRoute, 
  FaPoundSign, 
  FaCheckCircle,
  FaTruck,
  FaBox,
  FaUser,
  FaArrowRight
} from 'react-icons/fa';
import { DriverShell } from '@/components/driver';
import { useRouter } from 'next/navigation';

interface Drop {
  id: string;
  deliveryAddress: string;
  pickupAddress: string;
  status: string;
  customerName: string;
  timeWindowStart: string;
  timeWindowEnd: string;
  serviceTier: string;
  items?: Array<{
    id: string;
    name: string;
    quantity: number;
  }>;
}

interface RouteData {
  id: string;
  status: string;
  drops: Drop[];
  estimatedDuration: number;
  estimatedDistance: number;
  estimatedEarnings: number;
  completedDrops: number;
  currentDropIndex?: number;
}

export default function RouteProgressPage({ params }: { params: { id: string } }) {
  const [route, setRoute] = useState<RouteData | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [completingDropId, setCompletingDropId] = useState<string | null>(null);
  const toast = useToast();
  const router = useRouter();

  const loadRouteData = async () => {
    try {
      setIsLoading(true);
      const response = await fetch(`/api/driver/routes/${params.id}`);
      
      if (response.ok) {
        const data = await response.json();
        setRoute(data.route);
      } else {
        throw new Error('Failed to load route');
      }
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to load route data',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    loadRouteData();
    
    // Auto-refresh every 30 seconds
    const interval = setInterval(loadRouteData, 30000);
    return () => clearInterval(interval);
  }, [params.id]);

  const handleCompleteDrop = async (dropId: string) => {
    try {
      setCompletingDropId(dropId);
      const response = await fetch(`/api/driver/routes/${params.id}/complete-drop`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ 
          dropId,
          proofOfDelivery: 'Delivered successfully',
          notes: 'Completed via driver app'
        })
      });

      if (response.ok) {
        const data = await response.json();
        toast({
          title: 'Drop Completed!',
          description: `Earnings added: £${data.data?.earningsAdded?.toFixed(2) || '0.00'}`,
          status: 'success',
          duration: 4000,
          isClosable: true,
        });
        
        // Reload route data
        await loadRouteData();
        
        // If all drops completed, redirect to earnings
        if (data.data?.routeCompleted) {
          setTimeout(() => {
            router.push('/driver/earnings');
          }, 2000);
        }
      } else {
        throw new Error('Failed to complete drop');
      }
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to complete drop. Please try again.',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setCompletingDropId(null);
    }
  };

  if (isLoading) {
    return (
      <DriverShell title="Route Progress" subtitle="Loading...">
        <Flex justify="center" align="center" height="400px">
          <VStack spacing={4}>
            <Spinner size="xl" color="neon.500" thickness="4px" />
            <Text color="white">Loading route data...</Text>
          </VStack>
        </Flex>
      </DriverShell>
    );
  }

  if (!route) {
    return (
      <DriverShell title="Route Progress" subtitle="Error">
        <Alert status="error">
          <AlertIcon />
          <AlertDescription>Route not found</AlertDescription>
        </Alert>
      </DriverShell>
    );
  }

  const progressPercentage = (route.completedDrops / route.drops.length) * 100;

  return (
    <DriverShell title="Route Progress" subtitle={`Route #${params.id.slice(-8)}`}>
      <VStack spacing={6} align="stretch">
        {/* Progress Overview Card */}
        <Card
          bg="bg.card"
          borderColor="border.primary"
          borderWidth="1px"
          position="relative"
          overflow="hidden"
          boxShadow="0 0 20px rgba(59, 130, 246, 0.6), 0 0 40px rgba(59, 130, 246, 0.3)"
          animation="pulse-route-blue 3s ease-in-out infinite"
          sx={{
            "@keyframes pulse-route-blue": {
              "0%, 100%": { boxShadow: "0 0 15px rgba(59, 130, 246, 0.5), 0 0 30px rgba(59, 130, 246, 0.2)" },
              "50%": { boxShadow: "0 0 25px rgba(59, 130, 246, 0.8), 0 0 50px rgba(59, 130, 246, 0.4)" }
            }
          }}
        >
          <CardHeader>
            <Heading 
              size="md" 
              color="white"
              textShadow="0 0 15px rgba(59, 130, 246, 0.9)"
            >
              <Icon as={FaRoute} mr={2} />
              Route Progress
            </Heading>
          </CardHeader>
          <CardBody>
            <VStack spacing={4} align="stretch">
              <SimpleGrid columns={{ base: 2, md: 4 }} spacing={4}>
                <Box>
                  <Text fontSize="sm" color="white" opacity={0.7}>Status</Text>
                  <Badge 
                    colorScheme={route.status === 'in_progress' ? 'green' : 'blue'}
                    fontSize="md"
                    mt={1}
                  >
                    {route.status}
                  </Badge>
                </Box>
                <Box>
                  <Text fontSize="sm" color="white" opacity={0.7}>Total Stops</Text>
                  <Text 
                    fontSize="2xl" 
                    fontWeight="bold" 
                    color="white"
                    textShadow="0 0 10px rgba(59, 130, 246, 0.8)"
                  >
                    {route.drops.length}
                  </Text>
                </Box>
                <Box>
                  <Text fontSize="sm" color="white" opacity={0.7}>Completed</Text>
                  <Text 
                    fontSize="2xl" 
                    fontWeight="bold" 
                    color="white"
                    textShadow="0 0 10px rgba(34, 197, 94, 0.8)"
                  >
                    {route.completedDrops}
                  </Text>
                </Box>
                <Box>
                  <Text fontSize="sm" color="white" opacity={0.7}>Earnings</Text>
                  <Text 
                    fontSize="2xl" 
                    fontWeight="bold" 
                    color="white"
                    textShadow="0 0 10px rgba(34, 197, 94, 0.8)"
                  >
                    £{route.estimatedEarnings.toFixed(2)}
                  </Text>
                </Box>
              </SimpleGrid>

              <Box>
                <Flex justify="space-between" mb={2}>
                  <Text fontSize="sm" fontWeight="medium" color="white">
                    Progress: {route.completedDrops}/{route.drops.length}
                  </Text>
                  <Text fontSize="sm" color="white" opacity={0.8}>
                    {progressPercentage.toFixed(0)}%
                  </Text>
                </Flex>
                <Progress 
                  value={progressPercentage} 
                  colorScheme="green" 
                  size="lg" 
                  borderRadius="full"
                  bg="rgba(59, 130, 246, 0.2)"
                  sx={{
                    '& > div': {
                      boxShadow: '0 0 15px rgba(34, 197, 94, 0.8)'
                    }
                  }}
                />
              </Box>
            </VStack>
          </CardBody>
        </Card>

        {/* Drops List */}
        <Heading 
          size="md" 
          color="white"
          textShadow="0 0 12px rgba(255, 255, 255, 0.8)"
        >
          📍 Delivery Stops
        </Heading>

        {route.drops.map((drop, index) => {
          const isCompleted = drop.status === 'delivered';
          const isNext = !isCompleted && index === route.completedDrops;
          
          return (
            <Card
              key={drop.id}
              bg="bg.card"
              borderColor={isNext ? 'green.400' : 'border.primary'}
              borderWidth="2px"
              position="relative"
              overflow="hidden"
              opacity={isCompleted ? 0.7 : 1}
              boxShadow={
                isCompleted 
                  ? "0 0 10px rgba(34, 197, 94, 0.3)" 
                  : isNext 
                    ? "0 0 20px rgba(34, 197, 94, 0.6), 0 0 40px rgba(34, 197, 94, 0.3)"
                    : "0 0 10px rgba(59, 130, 246, 0.4)"
              }
            >
              <CardBody>
                <VStack align="stretch" spacing={4}>
                  <HStack justify="space-between">
                    <HStack>
                      <Circle 
                        size="12" 
                        bg={isCompleted ? 'green.500' : isNext ? 'green.400' : 'gray.600'}
                        color="white" 
                        fontWeight="bold"
                        boxShadow={isNext ? "0 0 15px rgba(34, 197, 94, 0.8)" : "none"}
                      >
                        {isCompleted ? <Icon as={FaCheckCircle} /> : index + 1}
                      </Circle>
                      <VStack align="start" spacing={0}>
                        <Text 
                          fontWeight="bold" 
                          color="white"
                          textShadow="0 0 8px rgba(255, 255, 255, 0.6)"
                          fontSize="lg"
                        >
                          Stop {index + 1} - {drop.customerName}
                        </Text>
                        <Badge 
                          colorScheme={isCompleted ? 'green' : isNext ? 'yellow' : 'blue'}
                          mt={1}
                        >
                          {isCompleted ? 'Completed' : isNext ? 'Next Stop' : 'Pending'}
                        </Badge>
                      </VStack>
                    </HStack>
                  </HStack>

                  <Divider borderColor="border.primary" />

                  <VStack align="stretch" spacing={3}>
                    <HStack>
                      <Icon as={FaMapMarkerAlt} color="green.400" />
                      <VStack align="start" spacing={0} flex={1}>
                        <Text fontSize="xs" color="white" opacity={0.7}>Pickup:</Text>
                        <Text fontSize="sm" color="white" fontWeight="medium">
                          {drop.pickupAddress}
                        </Text>
                      </VStack>
                    </HStack>

                    <HStack>
                      <Icon as={FaMapMarkerAlt} color="red.400" />
                      <VStack align="start" spacing={0} flex={1}>
                        <Text fontSize="xs" color="white" opacity={0.7}>Delivery:</Text>
                        <Text fontSize="sm" color="white" fontWeight="medium">
                          {drop.deliveryAddress}
                        </Text>
                      </VStack>
                    </HStack>

                    {drop.items && drop.items.length > 0 && (
                      <Box 
                        p={3} 
                        bg="rgba(59, 130, 246, 0.1)" 
                        borderRadius="md"
                        border="1px solid"
                        borderColor="rgba(59, 130, 246, 0.3)"
                      >
                        <Text 
                          fontSize="sm" 
                          fontWeight="semibold" 
                          color="white" 
                          mb={2}
                        >
                          <Icon as={FaBox} mr={2} color="amber.400" />
                          Items ({drop.items.length}):
                        </Text>
                        <VStack align="stretch" spacing={1}>
                          {drop.items.map((item) => (
                            <Text key={item.id} fontSize="sm" color="white" opacity={0.9}>
                              • {item.name} x{item.quantity}
                            </Text>
                          ))}
                        </VStack>
                      </Box>
                    )}
                  </VStack>

                  {isNext && !isCompleted && (
                    <Button
                      colorScheme="green"
                      size="lg"
                      onClick={() => handleCompleteDrop(drop.id)}
                      isLoading={completingDropId === drop.id}
                      loadingText="Completing..."
                      position="relative"
                      overflow="hidden"
                      boxShadow="0 0 15px rgba(34, 197, 94, 0.6), 0 0 30px rgba(34, 197, 94, 0.3)"
                      _hover={{
                        boxShadow: "0 0 20px rgba(34, 197, 94, 0.8), 0 0 40px rgba(34, 197, 94, 0.4)",
                        transform: "scale(1.02)"
                      }}
                    >
                      ✅ Complete This Drop
                    </Button>
                  )}

                  {isCompleted && (
                    <Box 
                      p={3} 
                      bg="rgba(34, 197, 94, 0.1)" 
                      borderRadius="md"
                      border="1px solid"
                      borderColor="rgba(34, 197, 94, 0.3)"
                    >
                      <Text fontSize="sm" color="white" textAlign="center">
                        ✅ Completed Successfully
                      </Text>
                    </Box>
                  )}
                </VStack>
              </CardBody>
            </Card>
          );
        })}

        {/* Summary at bottom */}
        {route.completedDrops === route.drops.length && (
          <Alert 
            status="success"
            bg="rgba(34, 197, 94, 0.2)"
            borderColor="green.500"
            borderWidth="2px"
            borderRadius="lg"
          >
            <AlertIcon color="green.500" />
            <Box flex={1}>
              <AlertTitle color="white">All Drops Completed! 🎉</AlertTitle>
              <AlertDescription color="white" opacity={0.9}>
                Great job! All deliveries have been completed successfully.
              </AlertDescription>
            </Box>
          </Alert>
        )}
      </VStack>
    </DriverShell>
  );
}

'use client';

import React, { useState, useEffect, useCallback } from 'react';
import {
  Box,
  VStack,
  HStack,
  Text,
  Heading,
  Card,
  CardBody,
  CardHeader,
  Badge,
  Button,
  SimpleGrid,
  Stat,
  StatLabel,
  StatNumber,
  StatHelpText,
  useToast,
  Spinner,
  Alert,
  AlertIcon,
  AlertTitle,
  AlertDescription,
  Divider,
  Icon,
  useBreakpointValue,
  Flex,
  Tabs,
  TabList,
  TabPanels,
  Tab,
  TabPanel,
  Avatar,
  Progress,
  Circle,
} from '@chakra-ui/react';
import {
  FaCalendarAlt,
  FaClock,
  FaMapMarkerAlt,
  FaTruck,
  FaCheckCircle,
  FaExclamationTriangle,
  FaArrowRight,
  FaSync,
  FaCalendarCheck,
  FaCalendarTimes,
} from 'react-icons/fa';
import DriverShell from '@/components/driver/DriverShell';

interface ScheduledJob {
  id: string;
  reference: string;
  scheduledAt: string;
  status: 'confirmed' | 'in_progress' | 'completed' | 'cancelled';
  customerName: string;
  customerPhone: string;
  pickupAddress: string;
  dropoffAddress: string;
  items: Array<{
    name: string;
    quantity: number;
  }>;
  duration: number;
  priority: 'low' | 'medium' | 'high';
}

interface ScheduleStats {
  todayJobs: number;
  weekJobs: number;
  totalEarnings: number;
  declinedJobsCount: number;
  acceptanceRate: number;
  nextJob?: ScheduledJob;
}

export default function DriverSchedulePage() {
  const [scheduleData, setScheduleData] = useState<ScheduleStats | null>(null);
  const [upcomingJobs, setUpcomingJobs] = useState<ScheduledJob[]>([]);
  const [pastJobs, setPastJobs] = useState<ScheduledJob[]>([]);
  const [declinedJobs, setDeclinedJobs] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const toast = useToast();

  const isMobile = useBreakpointValue({ base: true, md: false });

  // Load schedule data
  const loadScheduleData = useCallback(async () => {
    try {
      setRefreshing(true);

      const [scheduleResponse, jobsResponse] = await Promise.all([
        fetch('/api/driver/schedule/stats'),
        fetch('/api/driver/schedule/jobs'),
      ]);

      if (scheduleResponse.ok) {
        const scheduleStats = await scheduleResponse.json();
        setScheduleData(scheduleStats.data);
      }

      if (jobsResponse.ok) {
        const jobsData = await jobsResponse.json();
        setUpcomingJobs(jobsData.data.upcoming || []);
        setPastJobs(jobsData.data.past || []);
        setDeclinedJobs(jobsData.data.declined || []);
      }

    } catch (error) {
      console.error('Error loading schedule data:', error);
      toast({
        title: 'Error',
        description: 'Failed to load schedule data',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  }, [toast]);

  useEffect(() => {
    loadScheduleData();

    // Listen for job acceptance events
    const handleJobAccepted = () => {
      console.log('📅 Job accepted - refreshing schedule');
      loadScheduleData();
    };

    window.addEventListener('jobAccepted', handleJobAccepted);

    return () => {
      window.removeEventListener('jobAccepted', handleJobAccepted);
    };
  }, [loadScheduleData]);

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'confirmed': return 'blue';
      case 'in_progress': return 'orange';
      case 'completed': return 'green';
      case 'cancelled': return 'red';
      default: return 'gray';
    }
  };

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'confirmed': return FaCalendarCheck;
      case 'in_progress': return FaTruck;
      case 'completed': return FaCheckCircle;
      case 'cancelled': return FaCalendarTimes;
      default: return FaExclamationTriangle;
    }
  };

  const getPriorityColor = (priority: string) => {
    switch (priority) {
      case 'high': return 'red';
      case 'medium': return 'orange';
      case 'low': return 'green';
      default: return 'gray';
    }
  };

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('en-GB', {
      style: 'currency',
      currency: 'GBP',
    }).format(amount / 100);
  };

  const formatTime = (dateString: string) => {
    return new Date(dateString).toLocaleTimeString('en-GB', {
      hour: '2-digit',
      minute: '2-digit',
    });
  };

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('en-GB', {
      weekday: 'short',
      day: 'numeric',
      month: 'short',
    });
  };

  if (loading) {
    return (
      <DriverShell
        title="My Schedule"
        subtitle="View your upcoming jobs and work schedule"
      >
        <VStack spacing={8} py={8}>
          <Spinner size="xl" />
          <Text>Loading your schedule...</Text>
        </VStack>
      </DriverShell>
    );
  }

  return (
    <DriverShell
      title="My Schedule"
      subtitle="View your upcoming jobs and work schedule"
      actions={
        <Button
          leftIcon={<FaSync />}
          onClick={loadScheduleData}
          isLoading={refreshing}
          loadingText="Refreshing..."
          size="sm"
          colorScheme="brand"
        >
          Refresh
        </Button>
      }
    >
      <VStack spacing={6} align="stretch">
        {/* Schedule Overview Cards */}
        {scheduleData && (
          <SimpleGrid columns={{ base: 1, md: 2, lg: 4 }} spacing={4}>
            <Card
              bg="bg.card"
              border="1px solid"
              borderColor="border.primary"
              borderRadius="xl"
              position="relative"
              overflow="hidden"
              boxShadow="0 0 20px rgba(251, 191, 36, 0.5), 0 0 40px rgba(251, 191, 36, 0.3)"
              transition="all 0.3s"
              _hover={{
                boxShadow: "0 0 25px rgba(251, 191, 36, 0.7), 0 0 50px rgba(251, 191, 36, 0.4)",
                transform: "translateY(-4px)",
                _before: {
                  content: '""',
                  position: "absolute",
                  top: "0",
                  left: "-100%",
                  width: "100%",
                  height: "100%",
                  background: "linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.3), transparent)",
                  animation: "wave-today 0.8s ease-out",
                  zIndex: 1
                }
              }}
              sx={{
                "@keyframes wave-today": {
                  "0%": { left: "-100%" },
                  "100%": { left: "100%" }
                }
              }}
              _after={{
                content: '""',
                position: 'absolute',
                inset: 0,
                borderRadius: 'xl',
                padding: '1px',
                background: 'linear-gradient(135deg, rgba(0,194,255,0.3), rgba(0,209,143,0.3))',
                WebkitMask: 'linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0)',
                WebkitMaskComposite: 'xor',
                maskComposite: 'exclude',
                pointerEvents: 'none',
              }}
            >
              <CardBody position="relative" zIndex={2}>
                <Stat>
                  <StatLabel color="white">
                    <HStack>
                      <Icon as={FaCalendarAlt} />
                      <Text>Today's Jobs</Text>
                    </HStack>
                  </StatLabel>
                  <StatNumber 
                    color="white" 
                    fontSize="2xl"
                    textShadow="0 0 15px rgba(251, 191, 36, 0.8), 0 0 30px rgba(251, 191, 36, 0.5)"
                  >
                    {scheduleData.todayJobs}
                  </StatNumber>
                  <StatHelpText 
                    color="white"
                    textShadow="0 0 8px rgba(255, 255, 255, 0.4)"
                  >
                    Scheduled for today
                  </StatHelpText>
                </Stat>
              </CardBody>
            </Card>

            <Card
              bg="bg.card"
              border="1px solid"
              borderColor="border.primary"
              borderRadius="xl"
              position="relative"
              overflow="hidden"
              boxShadow="0 0 20px rgba(168, 85, 247, 0.5), 0 0 40px rgba(168, 85, 247, 0.3)"
              transition="all 0.3s"
              _hover={{
                boxShadow: "0 0 25px rgba(168, 85, 247, 0.7), 0 0 50px rgba(168, 85, 247, 0.4)",
                transform: "translateY(-4px)",
                _before: {
                  content: '""',
                  position: "absolute",
                  top: "0",
                  left: "-100%",
                  width: "100%",
                  height: "100%",
                  background: "linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.3), transparent)",
                  animation: "wave-week 0.8s ease-out",
                  zIndex: 1
                }
              }}
              sx={{
                "@keyframes wave-week": {
                  "0%": { left: "-100%" },
                  "100%": { left: "100%" }
                }
              }}
              _after={{
                content: '""',
                position: 'absolute',
                inset: 0,
                borderRadius: 'xl',
                padding: '1px',
                background: 'linear-gradient(135deg, rgba(0,194,255,0.3), rgba(0,209,143,0.3))',
                WebkitMask: 'linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0)',
                WebkitMaskComposite: 'xor',
                maskComposite: 'exclude',
                pointerEvents: 'none',
              }}
            >
              <CardBody position="relative" zIndex={2}>
                <Stat>
                  <StatLabel color="white">
                    <HStack>
                      <Icon as={FaCalendarCheck} />
                      <Text>This Week</Text>
                    </HStack>
                  </StatLabel>
                  <StatNumber 
                    color="white" 
                    fontSize="2xl"
                    textShadow="0 0 15px rgba(168, 85, 247, 0.8), 0 0 30px rgba(168, 85, 247, 0.5)"
                  >
                    {scheduleData.weekJobs}
                  </StatNumber>
                  <StatHelpText 
                    color="white"
                    textShadow="0 0 8px rgba(255, 255, 255, 0.4)"
                  >
                    Jobs this week
                  </StatHelpText>
                </Stat>
              </CardBody>
            </Card>

            <Card
              bg="bg.card"
              border="1px solid"
              borderColor="border.primary"
              borderRadius="xl"
              position="relative"
              overflow="hidden"
              boxShadow="0 0 20px rgba(34, 197, 94, 0.5), 0 0 40px rgba(34, 197, 94, 0.3)"
              transition="all 0.3s"
              _hover={{
                boxShadow: "0 0 25px rgba(34, 197, 94, 0.7), 0 0 50px rgba(34, 197, 94, 0.4)",
                transform: "translateY(-4px)",
                _before: {
                  content: '""',
                  position: "absolute",
                  top: "0",
                  left: "-100%",
                  width: "100%",
                  height: "100%",
                  background: "linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.3), transparent)",
                  animation: "wave-earnings 0.8s ease-out",
                  zIndex: 1
                }
              }}
              sx={{
                "@keyframes wave-earnings": {
                  "0%": { left: "-100%" },
                  "100%": { left: "100%" }
                }
              }}
              _after={{
                content: '""',
                position: 'absolute',
                inset: 0,
                borderRadius: 'xl',
                padding: '1px',
                background: 'linear-gradient(135deg, rgba(0,194,255,0.3), rgba(0,209,143,0.3))',
                WebkitMask: 'linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0)',
                WebkitMaskComposite: 'xor',
                maskComposite: 'exclude',
                pointerEvents: 'none',
              }}
            >
              <CardBody position="relative" zIndex={2}>
                <Stat>
                  <StatLabel color="white">
                    <HStack>
                      <Icon as={FaTruck} />
                      <Text>Total Earnings</Text>
                    </HStack>
                  </StatLabel>
                  <StatNumber 
                    color="white" 
                    fontSize="2xl"
                    textShadow="0 0 15px rgba(34, 197, 94, 0.8), 0 0 30px rgba(34, 197, 94, 0.5)"
                  >
                    {formatCurrency(scheduleData.totalEarnings)}
                  </StatNumber>
                  <StatHelpText 
                    color="white"
                    textShadow="0 0 8px rgba(255, 255, 255, 0.4)"
                  >
                    This week
                  </StatHelpText>
                </Stat>
              </CardBody>
            </Card>

            <Card
              bg="bg.card"
              border="1px solid"
              borderColor="border.primary"
              borderRadius="xl"
              position="relative"
              overflow="hidden"
              boxShadow="0 0 20px rgba(59, 130, 246, 0.5), 0 0 40px rgba(59, 130, 246, 0.3)"
              transition="all 0.3s"
              _hover={{
                boxShadow: "0 0 25px rgba(59, 130, 246, 0.7), 0 0 50px rgba(59, 130, 246, 0.4)",
                transform: "translateY(-4px)",
                _before: {
                  content: '""',
                  position: "absolute",
                  top: "0",
                  left: "-100%",
                  width: "100%",
                  height: "100%",
                  background: "linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.3), transparent)",
                  animation: "wave-nextjob 0.8s ease-out",
                  zIndex: 1
                }
              }}
              sx={{
                "@keyframes wave-nextjob": {
                  "0%": { left: "-100%" },
                  "100%": { left: "100%" }
                }
              }}
              _after={{
                content: '""',
                position: 'absolute',
                inset: 0,
                borderRadius: 'xl',
                padding: '1px',
                background: 'linear-gradient(135deg, rgba(0,194,255,0.3), rgba(0,209,143,0.3))',
                WebkitMask: 'linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0)',
                WebkitMaskComposite: 'xor',
                maskComposite: 'exclude',
                pointerEvents: 'none',
              }}
            >
              <CardBody position="relative" zIndex={2}>
                <Stat>
                  <StatLabel color="white">
                    <HStack>
                      <Icon as={FaClock} />
                      <Text>Next Job</Text>
                    </HStack>
                  </StatLabel>
                  <StatNumber 
                    color="white" 
                    fontSize="lg"
                    textShadow="0 0 15px rgba(59, 130, 246, 0.8), 0 0 30px rgba(59, 130, 246, 0.5)"
                  >
                    {scheduleData.nextJob
                      ? formatTime(scheduleData.nextJob.scheduledAt)
                      : 'No jobs'
                    }
                  </StatNumber>
                  <StatHelpText 
                    color="white"
                    textShadow="0 0 8px rgba(255, 255, 255, 0.4)"
                  >
                    {scheduleData.nextJob
                      ? formatDate(scheduleData.nextJob.scheduledAt)
                      : 'scheduled'
                    }
                  </StatHelpText>
                </Stat>
              </CardBody>
            </Card>
          </SimpleGrid>
        )}

        {/* Acceptance Rate Progress */}
        {scheduleData && (
          <SimpleGrid columns={{ base: 1, md: 2 }} spacing={4}>
            <Card
              bg="bg.card"
              border="1px solid"
              borderColor="border.primary"
              borderRadius="xl"
              position="relative"
              overflow="hidden"
              transition="all 0.3s"
              animation={scheduleData.acceptanceRate >= 80 
                ? "pulse-green 3s ease-in-out infinite"
                : scheduleData.acceptanceRate >= 60 
                ? "pulse-amber 3s ease-in-out infinite"
                : "pulse-red-acceptance 3s ease-in-out infinite"}
              _hover={{
                transform: "translateY(-4px)",
                animation: scheduleData.acceptanceRate >= 80 
                  ? "pulse-green-hover 2s ease-in-out infinite"
                  : scheduleData.acceptanceRate >= 60 
                  ? "pulse-amber-hover 2s ease-in-out infinite"
                  : "pulse-red-acceptance-hover 2s ease-in-out infinite",
                _before: {
                  content: '""',
                  position: "absolute",
                  top: "0",
                  left: "-100%",
                  width: "100%",
                  height: "100%",
                  background: "linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.3), transparent)",
                  animation: "wave-schedule 0.8s ease-out",
                  zIndex: 1
                }
              }}
              sx={{
                "@keyframes pulse-green": {
                  "0%, 100%": {
                    boxShadow: "0 0 15px rgba(34, 197, 94, 0.4), 0 0 30px rgba(34, 197, 94, 0.2)"
                  },
                  "50%": {
                    boxShadow: "0 0 30px rgba(34, 197, 94, 0.7), 0 0 60px rgba(34, 197, 94, 0.4)"
                  }
                },
                "@keyframes pulse-green-hover": {
                  "0%, 100%": {
                    boxShadow: "0 0 25px rgba(34, 197, 94, 0.6), 0 0 50px rgba(34, 197, 94, 0.3)"
                  },
                  "50%": {
                    boxShadow: "0 0 40px rgba(34, 197, 94, 0.9), 0 0 80px rgba(34, 197, 94, 0.5)"
                  }
                },
                "@keyframes pulse-amber": {
                  "0%, 100%": {
                    boxShadow: "0 0 15px rgba(251, 191, 36, 0.4), 0 0 30px rgba(251, 191, 36, 0.2)"
                  },
                  "50%": {
                    boxShadow: "0 0 30px rgba(251, 191, 36, 0.7), 0 0 60px rgba(251, 191, 36, 0.4)"
                  }
                },
                "@keyframes pulse-amber-hover": {
                  "0%, 100%": {
                    boxShadow: "0 0 25px rgba(251, 191, 36, 0.6), 0 0 50px rgba(251, 191, 36, 0.3)"
                  },
                  "50%": {
                    boxShadow: "0 0 40px rgba(251, 191, 36, 0.9), 0 0 80px rgba(251, 191, 36, 0.5)"
                  }
                },
                "@keyframes pulse-red-acceptance": {
                  "0%, 100%": {
                    boxShadow: "0 0 15px rgba(239, 68, 68, 0.4), 0 0 30px rgba(239, 68, 68, 0.2)"
                  },
                  "50%": {
                    boxShadow: "0 0 30px rgba(239, 68, 68, 0.7), 0 0 60px rgba(239, 68, 68, 0.4)"
                  }
                },
                "@keyframes pulse-red-acceptance-hover": {
                  "0%, 100%": {
                    boxShadow: "0 0 25px rgba(239, 68, 68, 0.6), 0 0 50px rgba(239, 68, 68, 0.3)"
                  },
                  "50%": {
                    boxShadow: "0 0 40px rgba(239, 68, 68, 0.9), 0 0 80px rgba(239, 68, 68, 0.5)"
                  }
                },
                "@keyframes wave-schedule": {
                  "0%": { left: "-100%" },
                  "100%": { left: "100%" }
                }
              }}
              _after={{
                content: '""',
                position: 'absolute',
                inset: 0,
                borderRadius: 'xl',
                padding: '1px',
                background: 'linear-gradient(135deg, rgba(0,194,255,0.3), rgba(0,209,143,0.3))',
                WebkitMask: 'linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0)',
                WebkitMaskComposite: 'xor',
                maskComposite: 'exclude',
                pointerEvents: 'none',
              }}
            >
              <CardBody>
                <VStack spacing={3} align="stretch">
                  <HStack justify="space-between">
                    <Text 
                      fontSize="sm" 
                      fontWeight="semibold" 
                      color="white"
                      textShadow="0 0 10px rgba(255, 255, 255, 0.5)"
                    >
                      Acceptance Rate (30 days)
                    </Text>
                    <Text 
                      fontSize="lg" 
                      fontWeight="bold" 
                      color="white"
                      textShadow={scheduleData.acceptanceRate >= 80 
                        ? "0 0 15px rgba(34, 197, 94, 0.8), 0 0 30px rgba(34, 197, 94, 0.5)"
                        : scheduleData.acceptanceRate >= 60 
                        ? "0 0 15px rgba(251, 191, 36, 0.8), 0 0 30px rgba(251, 191, 36, 0.5)"
                        : "0 0 15px rgba(239, 68, 68, 0.8), 0 0 30px rgba(239, 68, 68, 0.5)"}
                    >
                      {scheduleData.acceptanceRate.toFixed(1)}%
                    </Text>
                  </HStack>
                  <Progress
                    value={scheduleData.acceptanceRate}
                    colorScheme={scheduleData.acceptanceRate >= 80 ? 'green' : scheduleData.acceptanceRate >= 60 ? 'yellow' : 'red'}
                    size="lg"
                    borderRadius="md"
                  />
                  <Text 
                    fontSize="xs" 
                    color="white"
                    textShadow="0 0 8px rgba(255, 255, 255, 0.4)"
                  >
                    Each declined job reduces rate by 5%
                  </Text>
                </VStack>
              </CardBody>
            </Card>

            <Card
              bg="bg.card"
              border="1px solid"
              borderColor="border.primary"
              borderRadius="xl"
              position="relative"
              overflow="hidden"
              transition="all 0.3s"
              animation="pulse-red 3s ease-in-out infinite"
              _hover={{
                transform: "translateY(-4px)",
                animation: "pulse-red-hover 2s ease-in-out infinite",
                _before: {
                  content: '""',
                  position: "absolute",
                  top: "0",
                  left: "-100%",
                  width: "100%",
                  height: "100%",
                  background: "linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.3), transparent)",
                  animation: "wave-declined 0.8s ease-out",
                  zIndex: 1
                }
              }}
              sx={{
                "@keyframes pulse-red": {
                  "0%, 100%": {
                    boxShadow: "0 0 15px rgba(239, 68, 68, 0.4), 0 0 30px rgba(239, 68, 68, 0.2)"
                  },
                  "50%": {
                    boxShadow: "0 0 30px rgba(239, 68, 68, 0.7), 0 0 60px rgba(239, 68, 68, 0.4)"
                  }
                },
                "@keyframes pulse-red-hover": {
                  "0%, 100%": {
                    boxShadow: "0 0 25px rgba(239, 68, 68, 0.6), 0 0 50px rgba(239, 68, 68, 0.3)"
                  },
                  "50%": {
                    boxShadow: "0 0 40px rgba(239, 68, 68, 0.9), 0 0 80px rgba(239, 68, 68, 0.5)"
                  }
                },
                "@keyframes wave-declined": {
                  "0%": { left: "-100%" },
                  "100%": { left: "100%" }
                }
              }}
              _after={{
                content: '""',
                position: 'absolute',
                inset: 0,
                borderRadius: 'xl',
                padding: '1px',
                background: 'linear-gradient(135deg, rgba(0,194,255,0.3), rgba(0,209,143,0.3))',
                WebkitMask: 'linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0)',
                WebkitMaskComposite: 'xor',
                maskComposite: 'exclude',
                pointerEvents: 'none',
              }}
            >
              <CardBody position="relative" zIndex={2}>
                <Stat>
                  <StatLabel color="white">
                    <HStack>
                      <Icon as={FaCalendarTimes} />
                      <Text>Declined Jobs (30 days)</Text>
                    </HStack>
                  </StatLabel>
                  <StatNumber 
                    color="white" 
                    fontSize="2xl"
                    textShadow="0 0 15px rgba(239, 68, 68, 0.8), 0 0 30px rgba(239, 68, 68, 0.5)"
                  >
                    {scheduleData.declinedJobsCount}
                  </StatNumber>
                  <StatHelpText 
                    color="white"
                    textShadow="0 0 8px rgba(255, 255, 255, 0.4)"
                  >
                    Recent job declines
                  </StatHelpText>
                </Stat>
              </CardBody>
            </Card>
          </SimpleGrid>
        )}

        {/* Schedule Tabs */}
        <Card
          bg="bg.card"
          border="1px solid"
          borderColor="border.primary"
          borderRadius="xl"
          _before={{
            content: '""',
            position: 'absolute',
            inset: 0,
            borderRadius: 'xl',
            padding: '1px',
            background: 'linear-gradient(135deg, rgba(0,194,255,0.3), rgba(0,209,143,0.3))',
            WebkitMask: 'linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0)',
            WebkitMaskComposite: 'xor',
            maskComposite: 'exclude',
            pointerEvents: 'none',
          }}
        >
          <CardBody>
            <Tabs colorScheme="blue" variant="enclosed">
              <TabList>
                <Tab 
                  color="white" 
                  fontWeight="semibold"
                  position="relative"
                  overflow="hidden"
                  _selected={{ 
                    color: 'neon.500', 
                    bg: 'bg.surface',
                    boxShadow: "0 0 15px rgba(59, 130, 246, 0.6), 0 0 30px rgba(59, 130, 246, 0.3)"
                  }}
                  _hover={{
                    _before: {
                      content: '""',
                      position: "absolute",
                      top: "0",
                      left: "-100%",
                      width: "100%",
                      height: "100%",
                      background: "linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.3), transparent)",
                      animation: "wave-tab 0.6s ease-out",
                      zIndex: 1
                    }
                  }}
                  sx={{
                    "@keyframes wave-tab": {
                      "0%": { left: "-100%" },
                      "100%": { left: "100%" }
                    }
                  }}
                >
                  Upcoming Jobs ({upcomingJobs.length})
                </Tab>
                <Tab 
                  color="white" 
                  fontWeight="semibold"
                  position="relative"
                  overflow="hidden"
                  _selected={{ 
                    color: 'neon.500', 
                    bg: 'bg.surface',
                    boxShadow: "0 0 15px rgba(34, 197, 94, 0.6), 0 0 30px rgba(34, 197, 94, 0.3)"
                  }}
                  _hover={{
                    _before: {
                      content: '""',
                      position: "absolute",
                      top: "0",
                      left: "-100%",
                      width: "100%",
                      height: "100%",
                      background: "linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.3), transparent)",
                      animation: "wave-tab 0.6s ease-out",
                      zIndex: 1
                    }
                  }}
                  sx={{
                    "@keyframes wave-tab": {
                      "0%": { left: "-100%" },
                      "100%": { left: "100%" }
                    }
                  }}
                >
                  Past Jobs ({pastJobs.length})
                </Tab>
                <Tab 
                  color="white" 
                  fontWeight="semibold"
                  position="relative"
                  overflow="hidden"
                  _selected={{ 
                    color: 'neon.500', 
                    bg: 'bg.surface',
                    boxShadow: "0 0 15px rgba(239, 68, 68, 0.6), 0 0 30px rgba(239, 68, 68, 0.3)"
                  }}
                  _hover={{
                    _before: {
                      content: '""',
                      position: "absolute",
                      top: "0",
                      left: "-100%",
                      width: "100%",
                      height: "100%",
                      background: "linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.3), transparent)",
                      animation: "wave-tab 0.6s ease-out",
                      zIndex: 1
                    }
                  }}
                  sx={{
                    "@keyframes wave-tab": {
                      "0%": { left: "-100%" },
                      "100%": { left: "100%" }
                    }
                  }}
                >
                  Declined Jobs ({declinedJobs.length})
                </Tab>
              </TabList>

              <TabPanels>
                <TabPanel>
                  {upcomingJobs.length === 0 ? (
                    <Alert 
                      status="info" 
                      borderRadius="lg"
                      position="relative"
                      overflow="hidden"
                      boxShadow="0 0 20px rgba(59, 130, 246, 0.5), 0 0 40px rgba(59, 130, 246, 0.3)"
                      transition="all 0.3s"
                      _hover={{
                        boxShadow: "0 0 25px rgba(59, 130, 246, 0.7), 0 0 50px rgba(59, 130, 246, 0.4)",
                        _before: {
                          content: '""',
                          position: "absolute",
                          top: "0",
                          left: "-100%",
                          width: "100%",
                          height: "100%",
                          background: "linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.4), transparent)",
                          animation: "wave-alert 0.8s ease-out",
                          zIndex: 1
                        }
                      }}
                      sx={{
                        "@keyframes wave-alert": {
                          "0%": { left: "-100%" },
                          "100%": { left: "100%" }
                        }
                      }}
                    >
                      <AlertIcon />
                      <Box position="relative" zIndex={2}>
                        <AlertTitle 
                          color="white"
                          textShadow="0 0 10px rgba(59, 130, 246, 0.8)"
                        >
                          No upcoming jobs!
                        </AlertTitle>
                        <AlertDescription
                          color="white"
                          textShadow="0 0 8px rgba(255, 255, 255, 0.5)"
                        >
                          You don't have any jobs scheduled. Check back later or update your availability.
                        </AlertDescription>
                      </Box>
                    </Alert>
                  ) : (
                    <VStack spacing={4} align="stretch">
                      {upcomingJobs.map((job) => (
                        <Card
                          key={job.id}
                          bg="bg.surface"
                          border="1px solid"
                          borderColor="border.secondary"
                          borderRadius="lg"
                        >
                          <CardBody>
                            <VStack spacing={3} align="stretch">
                              <HStack justify="space-between" align="start">
                                <VStack align="start" spacing={1}>
                                  <HStack>
                                    <Badge bg="neon.500" color="dark.900">
                                      {job.reference}
                                    </Badge>
                                    <Badge bg={getPriorityColor(job.priority)} color="white" size="sm">
                                      {job.priority.toUpperCase()}
                                    </Badge>
                                    <Badge bg={getStatusColor(job.status)} color="white" size="sm">
                                      {job.status.replace('_', ' ').toUpperCase()}
                                    </Badge>
                                  </HStack>
                                  <HStack spacing={2}>
                                    <Icon as={FaCalendarAlt} color="text.secondary" boxSize={4} />
                                    <Text fontSize="sm" color="text.secondary">
                                      {formatDate(job.scheduledAt)} at {formatTime(job.scheduledAt)}
                                    </Text>
                                  </HStack>
                                </VStack>
                                <VStack align="end" spacing={1}>
                                  <Text fontSize="sm" color="text.tertiary">
                                    {job.duration} minutes
                                  </Text>
                                  <Badge bg="neon.500" color="dark.900" size="sm">
                                    {job.priority.toUpperCase()}
                                  </Badge>
                                </VStack>
                              </HStack>

                              <Divider />

                              <SimpleGrid columns={{ base: 1, md: 2 }} spacing={3}>
                                <Box>
                                  <HStack spacing={2} mb={1}>
                                    <Icon as={FaMapMarkerAlt} color="green.500" boxSize={3} />
                                    <Text fontSize="xs" fontWeight="semibold" color="green.600">
                                      Pickup
                                    </Text>
                                  </HStack>
                                  <Text fontSize="sm" color="text.secondary">
                                    {job.pickupAddress}
                                  </Text>
                                  <Text fontSize="xs" color="text.tertiary">
                                    {job.customerName} • {job.customerPhone}
                                  </Text>
                                </Box>

                                <Box>
                                  <HStack spacing={2} mb={1}>
                                    <Icon as={FaMapMarkerAlt} color="red.500" boxSize={3} />
                                    <Text fontSize="xs" fontWeight="semibold" color="red.600">
                                      Dropoff
                                    </Text>
                                  </HStack>
                                  <Text fontSize="sm" color="text.secondary">
                                    {job.dropoffAddress}
                                  </Text>
                                  {job.items.length > 0 && (
                                    <Text fontSize="xs" color="text.tertiary">
                                      {job.items.map((item: any) => `${item.name} (${item.quantity})`).join(', ')}
                                    </Text>
                                  )}
                                </Box>
                              </SimpleGrid>

                              <HStack justify="space-between" pt={2}>
                                <HStack spacing={2}>
                                  <Circle size="8px" bg={getStatusColor(job.status)} />
                                  <Text fontSize="xs" color="text.secondary">
                                    Status: {job.status.replace('_', ' ')}
                                  </Text>
                                </HStack>
                                <Button
                                  size="sm"
                                  colorScheme="brand"
                                  rightIcon={<FaArrowRight />}
                                  onClick={() => window.location.href = `/driver/jobs/${job.id}`}
                                >
                                  View Details
                                </Button>
                              </HStack>
                            </VStack>
                          </CardBody>
                        </Card>
                      ))}
                    </VStack>
                  )}
                </TabPanel>

                <TabPanel>
                  {pastJobs.length === 0 ? (
                    <Alert status="info" borderRadius="lg">
                      <AlertIcon />
                      <Box>
                        <AlertTitle>No past jobs</AlertTitle>
                        <AlertDescription>
                          Your completed jobs will appear here.
                        </AlertDescription>
                      </Box>
                    </Alert>
                  ) : (
                    <VStack spacing={4} align="stretch">
                      {pastJobs.slice(0, 10).map((job) => (
                        <Card
                          key={job.id}
                          bg="bg.surface"
                          border="1px solid"
                          borderColor="border.secondary"
                          borderRadius="lg"
                          opacity={0.8}
                        >
                          <CardBody>
                            <HStack justify="space-between" align="start">
                              <VStack align="start" spacing={1}>
                                <HStack>
                                  <Badge bg="success.500" color="white">
                                    {job.reference}
                                  </Badge>
                                  <Icon as={FaCheckCircle} color="success.500" />
                                  <Text fontSize="sm" color="success.600">
                                    Completed
                                  </Text>
                                </HStack>
                                <Text fontSize="sm" color="text.secondary">
                                  {formatDate(job.scheduledAt)} at {formatTime(job.scheduledAt)}
                                </Text>
                              </VStack>
                              <VStack align="end" spacing={1}>
                                <Icon as={FaCheckCircle} color="success.500" boxSize={5} />
                                <Button
                                  size="xs"
                                  variant="outline"
                                  onClick={() => window.location.href = `/driver/jobs/${job.id}`}
                                >
                                  View
                                </Button>
                              </VStack>
                            </HStack>
                          </CardBody>
                        </Card>
                      ))}
                    </VStack>
                  )}
                </TabPanel>

                <TabPanel>
                  {declinedJobs.length === 0 ? (
                    <Alert status="success" borderRadius="lg">
                      <AlertIcon />
                      <Box>
                        <AlertTitle>Great job!</AlertTitle>
                        <AlertDescription>
                          You haven't declined any jobs recently. Keep up the good work!
                        </AlertDescription>
                      </Box>
                    </Alert>
                  ) : (
                    <VStack spacing={4} align="stretch">
                      {declinedJobs.map((job) => (
                        <Card
                          key={job.id}
                          bg="bg.surface"
                          border="1px solid"
                          borderColor="border.secondary"
                          borderRadius="lg"
                          opacity={0.9}
                        >
                          <CardBody>
                            <VStack spacing={3} align="stretch">
                              <HStack justify="space-between" align="start">
                                <VStack align="start" spacing={1}>
                                  <HStack>
                                    <Badge bg="error.500" color="white">
                                      {job.reference}
                                    </Badge>
                                    <Badge bg="error.500" color="white" size="sm">
                                      DECLINED
                                    </Badge>
                                    <Badge bg={getPriorityColor(job.priority)} color="white" size="sm">
                                      {job.priority.toUpperCase()}
                                    </Badge>
                                  </HStack>
                                  <HStack spacing={2}>
                                    <Icon as={FaCalendarAlt} color="text.secondary" boxSize={4} />
                                    <Text fontSize="sm" color="text.secondary">
                                      Declined: {new Date(job.declinedAt).toLocaleString('en-GB')}
                                    </Text>
                                  </HStack>
                                  <HStack spacing={2}>
                                    <Icon as={FaClock} color="text.secondary" boxSize={4} />
                                    <Text fontSize="sm" color="text.secondary">
                                      Scheduled: {formatDate(job.scheduledAt)} at {formatTime(job.scheduledAt)}
                                    </Text>
                                  </HStack>
                                </VStack>
                                <VStack align="end" spacing={1}>
                                  <Badge bg="error.500" color="white" size="sm">
                                    DECLINED
                                  </Badge>
                                  <Text fontSize="xs" color="text.tertiary">
                                    {job.duration} minutes
                                  </Text>
                                </VStack>
                              </HStack>

                              <Divider />

                              <SimpleGrid columns={{ base: 1, md: 2 }} spacing={3}>
                                <Box>
                                  <HStack spacing={2} mb={1}>
                                    <Icon as={FaMapMarkerAlt} color="green.500" boxSize={3} />
                                    <Text fontSize="xs" fontWeight="semibold" color="green.600">
                                      Pickup
                                    </Text>
                                  </HStack>
                                  <Text fontSize="sm" color="text.secondary">
                                    {job.pickupAddress}
                                  </Text>
                                  <Text fontSize="xs" color="text.tertiary">
                                    {job.customerName} • {job.customerPhone}
                                  </Text>
                                </Box>

                                <Box>
                                  <HStack spacing={2} mb={1}>
                                    <Icon as={FaMapMarkerAlt} color="red.500" boxSize={3} />
                                    <Text fontSize="xs" fontWeight="semibold" color="red.600">
                                      Dropoff
                                    </Text>
                                  </HStack>
                                  <Text fontSize="sm" color="text.secondary">
                                    {job.dropoffAddress}
                                  </Text>
                                  {job.items.length > 0 && (
                                    <Text fontSize="xs" color="text.tertiary">
                                      {job.items.map((item: any) => `${item.name} (${item.quantity})`).join(', ')}
                                    </Text>
                                  )}
                                </Box>
                              </SimpleGrid>

                              <Box>
                                <Text fontSize="xs" fontWeight="semibold" color="text.secondary" mb={1}>
                                  Reason for Decline:
                                </Text>
                                <Text fontSize="sm" color="error.600" fontStyle="italic">
                                  {job.reason}
                                </Text>
                              </Box>

                              <Alert status="warning" size="sm" borderRadius="md">
                                <AlertIcon />
                                <Box>
                                  <Text fontSize="xs">
                                    This decline reduced your acceptance rate by 5%
                                  </Text>
                                </Box>
                              </Alert>
                            </VStack>
                          </CardBody>
                        </Card>
                      ))}
                    </VStack>
                  )}
                </TabPanel>
              </TabPanels>
            </Tabs>
          </CardBody>
        </Card>
      </VStack>
    </DriverShell>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import {
  Box,
  Container,
  VStack,
  Heading,
  Text,
  Card,
  CardBody,
  CardHeader,
  SimpleGrid,
  Switch,
  FormControl,
  FormLabel,
  Button,
  Divider,
  HStack,
  Badge,
  useBreakpointValue,
  Stack,
  Input,
  Select,
  Textarea,
  useToast,
  Modal,
  ModalOverlay,
  ModalContent,
  ModalHeader,
  ModalFooter,
  ModalBody,
  ModalCloseButton,
  useDisclosure,
  Avatar,
  Icon,
  IconButton,
  Tooltip,
  Spinner,
  Alert,
  AlertIcon,
  AlertDescription,
  Tabs,
  TabList,
  TabPanels,
  Tab,
  TabPanel,
  Flex,
  Stat,
  StatLabel,
  StatNumber,
  StatHelpText,
  Progress,
} from '@chakra-ui/react';
import { 
  FiSettings, 
  FiBell, 
  FiShield, 
  FiMail, 
  FiUser, 
  FiTruck, 
  FiPhone, 
  FiEdit3,
  FiSave,
  FiLock,
  FiEye,
  FiEyeOff,
  FiDownload,
  FiUpload,
  FiTrash2,
  FiRefreshCw
} from 'react-icons/fi';
import { DriverShell } from '@/components/driver';

export default function DriverSettings() {
  const isMobile = useBreakpointValue({ base: true, md: false });
  const toast = useToast();
  
  // State management
  const [isLoading, setIsLoading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [activeTab, setActiveTab] = useState(0);
  const [lastUpdated, setLastUpdated] = useState<string>('');
  
  // Profile data
  const [profileData, setProfileData] = useState({
    name: 'Ahmed Mohammed',
    email: 'ahmed@speedyvan.com', 
    phone: '01202 129746',
    address: '123 Glasgow Street, Glasgow, UK',
    emergencyContact: '01202 129746',
    drivingLicense: 'DRIVE123456789012',
    vehicleReg: 'SV21 ABC'
  });
  
  // Notifications settings
  const [notifications, setNotifications] = useState({
    jobAlerts: true,
    emailNotifications: true,
    smsNotifications: false,
    pushNotifications: true,
    marketingEmails: false,
    weeklyReports: true
  });
  
  
  // Vehicle settings
  const [vehicleSettings, setVehicleSettings] = useState({
    vehicleType: 'van',
    maxWeight: '1000',
    specialEquipment: ['trolley', 'straps'],
    insuranceExpiry: '2025-12-31',
    motExpiry: '2025-06-15'
  });
  
  // Modals
  const { isOpen: isPasswordOpen, onOpen: onPasswordOpen, onClose: onPasswordClose } = useDisclosure();
  const { isOpen: isDeleteOpen, onOpen: onDeleteOpen, onClose: onDeleteClose } = useDisclosure();
  
  // Password change
  const [passwordData, setPasswordData] = useState({
    current: '',
    new: '',
    confirm: ''
  });
  const [showPasswords, setShowPasswords] = useState({
    current: false,
    new: false,
    confirm: false
  });

  // Client-side only: Update time to avoid hydration mismatch
  useEffect(() => {
    setLastUpdated(new Date().toLocaleTimeString());
  }, []);

  // Save functions
  const handleSaveProfile = async () => {
    setIsSaving(true);
    try {
      // Simulate API call
      await new Promise(resolve => setTimeout(resolve, 1000));
      
      toast({
        title: 'Profile Updated',
        description: 'Your profile has been successfully updated.',
        status: 'success',
        duration: 3000,
        isClosable: true,
      });
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to update profile. Please try again.',
        status: 'error',
        duration: 3000,
        isClosable: true,
      });
    } finally {
      setIsSaving(false);
    }
  };

  const handleSaveNotifications = async () => {
    setIsSaving(true);
    try {
      await new Promise(resolve => setTimeout(resolve, 800));
      
      toast({
        title: 'Notifications Updated',
        description: 'Your notification preferences have been saved.',
        status: 'success',
        duration: 3000,
        isClosable: true,
      });
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to update notifications.',
        status: 'error',
        duration: 3000,
        isClosable: true,
      });
    } finally {
      setIsSaving(false);
    }
  };

  const handleChangePassword = async () => {
    if (passwordData.new !== passwordData.confirm) {
      toast({
        title: 'Error',
        description: 'New passwords do not match.',
        status: 'error',
        duration: 3000,
        isClosable: true,
      });
      return;
    }

    setIsSaving(true);
    try {
      await new Promise(resolve => setTimeout(resolve, 1200));
      
      toast({
        title: 'Password Changed',
        description: 'Your password has been successfully updated.',
        status: 'success',
        duration: 3000,
        isClosable: true,
      });
      
      setPasswordData({ current: '', new: '', confirm: '' });
      onPasswordClose();
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to change password.',
        status: 'error',
        duration: 3000,
        isClosable: true,
      });
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <DriverShell
      title="Driver Settings"
      subtitle="Manage your profile, notifications, and preferences"
      actions={
        <HStack spacing={2}>
          {lastUpdated && (
            <Text fontSize="sm" color="text.secondary">
              Last updated: {lastUpdated}
            </Text>
          )}
          <Tooltip label="Refresh settings">
            <IconButton
              size="sm"
              variant="outline"
              icon={<FiRefreshCw />}
              onClick={() => window.location.reload()}
              aria-label="Refresh"
            />
          </Tooltip>
        </HStack>
      }
    >
      <VStack spacing={{ base: 6, md: 8 }} align="stretch">

        {/* Account Status Overview */}
        <Card
          bg="bg.card"
          border="1px solid"
          borderColor="border.primary"
          borderRadius="xl"
          position="relative"
          overflow="hidden"
          boxShadow="0 0 30px rgba(59, 130, 246, 0.5), 0 0 60px rgba(59, 130, 246, 0.3)"
          transition="all 0.3s"
          animation="pulse-account 4s ease-in-out infinite"
          _hover={{
            boxShadow: "0 0 40px rgba(59, 130, 246, 0.7), 0 0 80px rgba(59, 130, 246, 0.4)",
            _before: {
              content: '""',
              position: "absolute",
              top: "0",
              left: "-100%",
              width: "100%",
              height: "100%",
              background: "linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.2), transparent)",
              animation: "wave-settings 1s ease-out",
              zIndex: 1
            }
          }}
          sx={{
            "@keyframes pulse-account": {
              "0%, 100%": { boxShadow: "0 0 25px rgba(59, 130, 246, 0.4), 0 0 50px rgba(59, 130, 246, 0.2)" },
              "50%": { boxShadow: "0 0 35px rgba(59, 130, 246, 0.6), 0 0 70px rgba(59, 130, 246, 0.35)" }
            },
            "@keyframes wave-settings": {
              "0%": { left: "-100%" },
              "100%": { left: "100%" }
            }
          }}
          _after={{
            content: '""',
            position: 'absolute',
            inset: 0,
            borderRadius: 'xl',
            padding: '1px',
            background: 'linear-gradient(135deg, rgba(0,194,255,0.2), rgba(0,209,143,0.2))',
            WebkitMask: 'linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0)',
            WebkitMaskComposite: 'xor',
            maskComposite: 'exclude',
            pointerEvents: 'none',
          }}
        >
          <CardBody p={{ base: 4, md: 6 }} position="relative" zIndex={2}>
            <VStack spacing={4}>
              <Flex align="center" justify="space-between" w="full" direction={{ base: "column", md: "row" }}>
                <HStack spacing={4}>
                  <Avatar 
                    size="lg" 
                    name={profileData.name}
                    boxShadow="0 0 20px rgba(59, 130, 246, 0.7), 0 0 40px rgba(59, 130, 246, 0.4)"
                  />
                  <VStack align="start" spacing={1}>
                    <Text 
                      fontSize="xl" 
                      fontWeight="bold" 
                      color="white"
                      textShadow="0 0 12px rgba(59, 130, 246, 0.8), 0 0 24px rgba(59, 130, 246, 0.4)"
                    >
                      {profileData.name}
                    </Text>
                    <Text 
                      color="white" 
                      opacity={0.9}
                      textShadow="0 0 6px rgba(255, 255, 255, 0.4)"
                    >
                      {profileData.email}
                    </Text>
                    <Badge 
                      colorScheme="brand"
                      boxShadow="0 0 10px rgba(34, 197, 94, 0.6)"
                    >
                      Active Driver
                    </Badge>
                  </VStack>
                </HStack>
                
                <SimpleGrid columns={{ base: 2, md: 4 }} spacing={4} mt={{ base: 4, md: 0 }}>
                  <Stat textAlign="center">
                    <StatLabel color="white" opacity={0.7}>Status</StatLabel>
                    <StatNumber 
                      fontSize="md" 
                      color="white"
                      textShadow="0 0 10px rgba(34, 197, 94, 0.8)"
                    >
                      Active
                    </StatNumber>
                  </Stat>
                  <Stat textAlign="center">
                    <StatLabel color="white" opacity={0.7}>Rating</StatLabel>
                    <StatNumber 
                      fontSize="md" 
                      color="white"
                      textShadow="0 0 10px rgba(251, 191, 36, 0.8)"
                    >
                      4.8
                    </StatNumber>
                    <StatHelpText color="white" opacity={0.7}>
                      <HStack spacing={1} justify="center">
                        {[0, 1, 2, 3, 4].map((index) => (
                          <Box
                            key={index}
                            as="span"
                            animation={`flash-star 5s ease-in-out infinite`}
                            sx={{
                              animationDelay: `${index * 1}s`,
                              "@keyframes flash-star": {
                                "0%, 19%, 100%": { 
                                  opacity: 0.7,
                                  transform: "scale(1)",
                                  textShadow: "0 0 5px rgba(251, 191, 36, 0.5)"
                                },
                                "10%": { 
                                  opacity: 1,
                                  transform: "scale(1.3)",
                                  textShadow: "0 0 20px rgba(251, 191, 36, 1), 0 0 40px rgba(251, 191, 36, 0.8)"
                                }
                              }
                            }}
                          >
                            ⭐
                          </Box>
                        ))}
                      </HStack>
                    </StatHelpText>
                  </Stat>
                  <Stat textAlign="center">
                    <StatLabel color="white" opacity={0.7}>Completed</StatLabel>
                    <StatNumber 
                      fontSize="md" 
                      color="white"
                      textShadow="0 0 10px rgba(59, 130, 246, 0.8)"
                    >
                      247
                    </StatNumber>
                    <StatHelpText color="white" opacity={0.7}>Jobs</StatHelpText>
                  </Stat>
                  <Stat textAlign="center">
                    <StatLabel color="white" opacity={0.7}>Earnings</StatLabel>
                    <StatNumber 
                      fontSize="md" 
                      color="white"
                      textShadow="0 0 10px rgba(34, 197, 94, 0.8)"
                    >
                      £2,340
                    </StatNumber>
                    <StatHelpText color="white" opacity={0.7}>This month</StatHelpText>
                  </Stat>
                </SimpleGrid>
              </Flex>
            </VStack>
          </CardBody>
        </Card>

        {/* Settings Tabs */}
        <Card
          bg="bg.card"
          border="1px solid"
          borderColor="border.primary"
          borderRadius="xl"
          position="relative"
          overflow="hidden"
          boxShadow="0 0 25px rgba(34, 197, 94, 0.5), 0 0 50px rgba(34, 197, 94, 0.3)"
          transition="all 0.3s"
          _hover={{
            boxShadow: "0 0 35px rgba(34, 197, 94, 0.7), 0 0 70px rgba(34, 197, 94, 0.4)",
            _before: {
              content: '""',
              position: "absolute",
              top: "0",
              left: "-100%",
              width: "100%",
              height: "100%",
              background: "linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.2), transparent)",
              animation: "wave-settings-main 1s ease-out",
              zIndex: 1
            }
          }}
          sx={{
            "@keyframes wave-settings-main": {
              "0%": { left: "-100%" },
              "100%": { left: "100%" }
            }
          }}
          _after={{
            content: '""',
            position: 'absolute',
            inset: 0,
            borderRadius: 'xl',
            padding: '1px',
            background: 'linear-gradient(135deg, rgba(0,194,255,0.2), rgba(0,209,143,0.2))',
            WebkitMask: 'linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0)',
            WebkitMaskComposite: 'xor',
            maskComposite: 'exclude',
            pointerEvents: 'none',
          }}
        >
          <Tabs index={activeTab} onChange={setActiveTab} variant="enclosed">
            <TabList position="relative" zIndex={2}>
              <Tab 
                color="white"
                _selected={{ 
                  color: "neon.500", 
                  bg: "bg.surface",
                  boxShadow: "0 0 15px rgba(59, 130, 246, 0.6)"
                }}
              >
                <Icon as={FiUser} mr={2} />Profile
              </Tab>
              <Tab 
                color="white"
                _selected={{ 
                  color: "neon.500", 
                  bg: "bg.surface",
                  boxShadow: "0 0 15px rgba(251, 191, 36, 0.6)"
                }}
              >
                <Icon as={FiBell} mr={2} />Notifications
              </Tab>
              <Tab 
                color="white"
