                    Personal Information
                  </Heading>
                  
                  <SimpleGrid columns={{ base: 1, md: 2 }} spacing={4}>
                  <FormControl>
                    <FormLabel color="white" opacity={0.9}>Full Name</FormLabel>
                      <Input 
                        value={profileData.name}
