                    Save Profile
                  </Button>
                </VStack>
              </TabPanel>

              {/* Notifications Tab */}
              <TabPanel p={{ base: 4, md: 6 }}>
                <VStack spacing={6} align="stretch">
                  <Heading 
                    size="md" 
                    color="white"
                    textShadow="0 0 12px rgba(251, 191, 36, 0.8), 0 0 24px rgba(251, 191, 36, 0.4)"
                  >
                    Notification Preferences
                  </Heading>
                  
                  <VStack spacing={4} align="stretch">
                    <FormControl display="flex" alignItems="center" justifyContent="space-between">
                      <VStack align="start" spacing={1}>
                        <FormLabel mb="0" color="white" opacity={0.95}>Job Alerts</FormLabel>
                        <Text fontSize="sm" color="white" opacity={0.7}>Receive notifications for new job opportunities</Text>
                      </VStack>
                      <Switch 
                        colorScheme="blue" 
                        isChecked={notifications.jobAlerts}
                        onChange={(e) => setNotifications({...notifications, jobAlerts: e.target.checked})}
                      />
                    </FormControl>
                    
                    <FormControl display="flex" alignItems="center" justifyContent="space-between">
                      <VStack align="start" spacing={1}>
                        <FormLabel mb="0" color="white" opacity={0.95}>Push Notifications</FormLabel>
                        <Text fontSize="sm" color="white" opacity={0.7}>Instant notifications on your device</Text>
                      </VStack>
                      <Switch 
                        colorScheme="blue" 
                        isChecked={notifications.pushNotifications}
                        onChange={(e) => setNotifications({...notifications, pushNotifications: e.target.checked})}
                      />
                    </FormControl>
                    
                    <FormControl display="flex" alignItems="center" justifyContent="space-between">
                      <VStack align="start" spacing={1}>
                        <FormLabel mb="0">Email Notifications</FormLabel>
                        <Text fontSize="sm" color="gray.600">Job updates and important information via email</Text>
                      </VStack>
                      <Switch 
                        colorScheme="blue" 
                        isChecked={notifications.emailNotifications}
                        onChange={(e) => setNotifications({...notifications, emailNotifications: e.target.checked})}
                      />
                    </FormControl>
                    
                    <FormControl display="flex" alignItems="center" justifyContent="space-between">
                      <VStack align="start" spacing={1}>
                        <FormLabel mb="0">SMS Notifications</FormLabel>
                        <Text fontSize="sm" color="gray.600">Text messages for urgent job updates</Text>
                      </VStack>
                      <Switch 
                        colorScheme="blue" 
                        isChecked={notifications.smsNotifications}
                        onChange={(e) => setNotifications({...notifications, smsNotifications: e.target.checked})}
                      />
                    </FormControl>
                    
                    <FormControl display="flex" alignItems="center" justifyContent="space-between">
                      <VStack align="start" spacing={1}>
                        <FormLabel mb="0">Weekly Reports</FormLabel>
                        <Text fontSize="sm" color="gray.600">Summary of your weekly performance and earnings</Text>
                      </VStack>
                      <Switch 
                        colorScheme="blue" 
                        isChecked={notifications.weeklyReports}
                        onChange={(e) => setNotifications({...notifications, weeklyReports: e.target.checked})}
                      />
                    </FormControl>
                    
                    <FormControl display="flex" alignItems="center" justifyContent="space-between">
                      <VStack align="start" spacing={1}>
                        <FormLabel mb="0">Marketing Emails</FormLabel>
                        <Text fontSize="sm" color="gray.600">Promotional offers and updates</Text>
                      </VStack>
                      <Switch 
                        colorScheme="blue" 
                        isChecked={notifications.marketingEmails}
                        onChange={(e) => setNotifications({...notifications, marketingEmails: e.target.checked})}
                      />
                    </FormControl>
                  </VStack>
                  
                  <Button 
                    colorScheme="blue" 
                    onClick={handleSaveNotifications}
                    isLoading={isSaving}
                    leftIcon={<FiSave />}
                    alignSelf="start"
                  >
                    Save Preferences
                  </Button>
                </VStack>
              </TabPanel>

              {/* Vehicle Tab */}
              <TabPanel p={{ base: 4, md: 6 }}>
                <VStack spacing={6} align="stretch">
                  <Heading 
                    size="md" 
                    color="white"
                    textShadow="0 0 12px rgba(168, 85, 247, 0.8), 0 0 24px rgba(168, 85, 247, 0.4)"
                  >
                    Vehicle Information
                  </Heading>
                  
                  <SimpleGrid columns={{ base: 1, md: 2 }} spacing={4}>
                    <FormControl>
                      <FormLabel>Vehicle Type</FormLabel>
                      <Select 
                        value={vehicleSettings.vehicleType}
                        onChange={(e) => setVehicleSettings({...vehicleSettings, vehicleType: e.target.value})}
                      >
                        <option value="van">Standard Van</option>
                        <option value="large-van">Large Van</option>
                        <option value="truck">Small Truck</option>
                      </Select>
                    </FormControl>
                    
                    <FormControl>
                      <FormLabel>Maximum Weight (kg)</FormLabel>
                      <Input 
                        type="number"
                        value={vehicleSettings.maxWeight}
                        onChange={(e) => setVehicleSettings({...vehicleSettings, maxWeight: e.target.value})}
                      />
                    </FormControl>
                    
                    <FormControl>
                      <FormLabel>Insurance Expiry</FormLabel>
                      <Input 
                        type="date"
                        value={vehicleSettings.insuranceExpiry}
                        onChange={(e) => setVehicleSettings({...vehicleSettings, insuranceExpiry: e.target.value})}
                      />
                    </FormControl>
                    
                    <FormControl>
                      <FormLabel>MOT Expiry</FormLabel>
                      <Input 
                        type="date"
                        value={vehicleSettings.motExpiry}
                        onChange={(e) => setVehicleSettings({...vehicleSettings, motExpiry: e.target.value})}
                      />
                    </FormControl>
                  </SimpleGrid>
                  
                  <Alert status="info">
                    <AlertIcon />
                    <AlertDescription>
                      Keep your vehicle documents up to date to maintain your driver status and continue receiving jobs.
                    </AlertDescription>
                  </Alert>
                </VStack>
              </TabPanel>

              {/* Security Tab */}
              <TabPanel p={{ base: 4, md: 6 }}>
                <VStack spacing={6} align="stretch">
                  <Heading 
                    size="md" 
                    color="white"
                    textShadow="0 0 12px rgba(239, 68, 68, 0.8), 0 0 24px rgba(239, 68, 68, 0.4)"
                  >
                    Security & Privacy
                  </Heading>
                  
                  <VStack spacing={4} align="stretch">
                    <Card 
                      variant="outline"
                      position="relative"
                      overflow="hidden"
                      boxShadow="0 0 15px rgba(59, 130, 246, 0.5), 0 0 30px rgba(59, 130, 246, 0.3)"
                      transition="all 0.3s"
                      _hover={{
                        boxShadow: "0 0 20px rgba(59, 130, 246, 0.7), 0 0 40px rgba(59, 130, 246, 0.4)",
                        _before: {
                          content: '""',
                          position: "absolute",
                          top: "0",
                          left: "-100%",
                          width: "100%",
                          height: "100%",
                          background: "linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.2), transparent)",
                          animation: "wave-sec 0.8s ease-out",
                          zIndex: 1
                        }
                      }}
                      sx={{
                        "@keyframes wave-sec": {
                          "0%": { left: "-100%" },
                          "100%": { left: "100%" }
                        }
                      }}
                    >
                      <CardBody position="relative" zIndex={2}>
                        <VStack spacing={3} align="stretch">
                          <Text fontWeight="semibold" color="white" textShadow="0 0 10px rgba(59, 130, 246, 0.8)">Password & Authentication</Text>
                          <Button 
                            variant="outline" 
                            leftIcon={<FiLock />}
                            onClick={onPasswordOpen}
                            size="lg"
                            color="white"
                            borderColor="neon.500"
                            _hover={{
                              boxShadow: "0 0 15px rgba(59, 130, 246, 0.6)",
                              bg: "rgba(59, 130, 246, 0.1)"
                            }}
                          >
                            Change Password
                          </Button>
                          <Text fontSize="sm" color="white" opacity={0.7}>
                            Last changed: Never (Please update your password)
                          </Text>
                        </VStack>
                      </CardBody>
                    </Card>
                    
                    <Card 
                      variant="outline"
                      position="relative"
                      overflow="hidden"
                      boxShadow="0 0 15px rgba(34, 197, 94, 0.5), 0 0 30px rgba(34, 197, 94, 0.3)"
                      transition="all 0.3s"
                      _hover={{
                        boxShadow: "0 0 20px rgba(34, 197, 94, 0.7), 0 0 40px rgba(34, 197, 94, 0.4)",
                        _before: {
                          content: '""',
                          position: "absolute",
                          top: "0",
                          left: "-100%",
                          width: "100%",
                          height: "100%",
                          background: "linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.2), transparent)",
                          animation: "wave-privacy 0.8s ease-out",
                          zIndex: 1
                        }
                      }}
                      sx={{
                        "@keyframes wave-privacy": {
                          "0%": { left: "-100%" },
                          "100%": { left: "100%" }
                        }
                      }}
                    >
                      <CardBody position="relative" zIndex={2}>
                        <VStack spacing={3} align="stretch">
                          <Text fontWeight="semibold" color="white" textShadow="0 0 10px rgba(34, 197, 94, 0.8)">Data & Privacy</Text>
                          <HStack spacing={3}>
                            <Button 
                              variant="outline" 
                              leftIcon={<FiDownload />}
                              size="md"
                              color="white"
                              borderColor="neon.500"
                              _hover={{
                                boxShadow: "0 0 15px rgba(34, 197, 94, 0.6)",
                                bg: "rgba(34, 197, 94, 0.1)"
                              }}
                            >
                              Download My Data
                            </Button>
                            <Button 
                              variant="outline" 
                              leftIcon={<FiRefreshCw />}
                              size="md"
                              color="white"
                              borderColor="neon.500"
                              _hover={{
                                boxShadow: "0 0 15px rgba(34, 197, 94, 0.6)",
                                bg: "rgba(34, 197, 94, 0.1)"
                              }}
                            >
                              Privacy Settings
                            </Button>
                          </HStack>
                          <Text fontSize="sm" color="white" opacity={0.7}>
                            Manage your personal data and privacy preferences
                          </Text>
                        </VStack>
                      </CardBody>
                    </Card>
                    
                    <Card 
                      variant="outline" 
                      borderColor="red.200"
                      position="relative"
                      overflow="hidden"
                      boxShadow="0 0 15px rgba(239, 68, 68, 0.5), 0 0 30px rgba(239, 68, 68, 0.3)"
                      transition="all 0.3s"
                      animation="pulse-danger 3s ease-in-out infinite"
                      _hover={{
                        boxShadow: "0 0 25px rgba(239, 68, 68, 0.8), 0 0 50px rgba(239, 68, 68, 0.5)",
                        _before: {
                          content: '""',
                          position: "absolute",
                          top: "0",
                          left: "-100%",
                          width: "100%",
                          height: "100%",
                          background: "linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.2), transparent)",
                          animation: "wave-danger 0.8s ease-out",
                          zIndex: 1
                        }
                      }}
                      sx={{
                        "@keyframes pulse-danger": {
                          "0%, 100%": { boxShadow: "0 0 10px rgba(239, 68, 68, 0.4), 0 0 20px rgba(239, 68, 68, 0.2)" },
                          "50%": { boxShadow: "0 0 20px rgba(239, 68, 68, 0.6), 0 0 40px rgba(239, 68, 68, 0.3)" }
                        },
                        "@keyframes wave-danger": {
                          "0%": { left: "-100%" },
                          "100%": { left: "100%" }
                        }
                      }}
                    >
                      <CardBody position="relative" zIndex={2}>
                        <VStack spacing={3} align="stretch">
                          <Text 
                            fontWeight="semibold" 
                            color="white"
                            textShadow="0 0 10px rgba(239, 68, 68, 0.9), 0 0 20px rgba(239, 68, 68, 0.6)"
                          >
                            Danger Zone
                          </Text>
                          <Button 
                            colorScheme="red" 
                            variant="outline"
                            leftIcon={<FiTrash2 />}
                            onClick={onDeleteOpen}
                            size="lg"
                            boxShadow="0 0 10px rgba(239, 68, 68, 0.5)"
                            _hover={{
                              boxShadow: "0 0 20px rgba(239, 68, 68, 0.8)",
                              transform: "scale(1.02)"
                            }}
                          >
                            Delete Account
                          </Button>
                          <Text 
                            fontSize="sm" 
                            color="white"
                            textShadow="0 0 6px rgba(239, 68, 68, 0.8)"
                          >
                            Permanently delete your account and all associated data
                          </Text>
                        </VStack>
                      </CardBody>
                    </Card>
                  </VStack>
                </VStack>
              </TabPanel>
            </TabPanels>
          </Tabs>
        </Card>

        {/* Password Change Modal */}
        <Modal isOpen={isPasswordOpen} onClose={onPasswordClose}>
          <ModalOverlay />
          <ModalContent>
            <ModalHeader>Change Password</ModalHeader>
            <ModalCloseButton />
            <ModalBody>
              <VStack spacing={4}>
                <FormControl>
                  <FormLabel>Current Password</FormLabel>
                  <HStack>
                    <Input 
                      type={showPasswords.current ? "text" : "password"}
                      value={passwordData.current}
                      onChange={(e) => setPasswordData({...passwordData, current: e.target.value})}
                    />
                    <Button
                      size="sm"
                      onClick={() => setShowPasswords({...showPasswords, current: !showPasswords.current})}
                    >
                      {showPasswords.current ? <FiEyeOff /> : <FiEye />}
                    </Button>
                  </HStack>
                </FormControl>
                
                <FormControl>
                  <FormLabel>New Password</FormLabel>
                  <HStack>
                    <Input 
                      type={showPasswords.new ? "text" : "password"}
                      value={passwordData.new}
                      onChange={(e) => setPasswordData({...passwordData, new: e.target.value})}
                    />
                    <Button
                      size="sm"
                      onClick={() => setShowPasswords({...showPasswords, new: !showPasswords.new})}
                    >
                      {showPasswords.new ? <FiEyeOff /> : <FiEye />}
                    </Button>
                  </HStack>
                </FormControl>
                
                <FormControl>
                  <FormLabel>Confirm New Password</FormLabel>
                  <HStack>
                    <Input 
                      type={showPasswords.confirm ? "text" : "password"}
                      value={passwordData.confirm}
                      onChange={(e) => setPasswordData({...passwordData, confirm: e.target.value})}
                    />
                    <Button
                      size="sm"
                      onClick={() => setShowPasswords({...showPasswords, confirm: !showPasswords.confirm})}
                    >
                      {showPasswords.confirm ? <FiEyeOff /> : <FiEye />}
                    </Button>
                  </HStack>
                </FormControl>
              </VStack>
            </ModalBody>
            <ModalFooter>
              <Button variant="ghost" mr={3} onClick={onPasswordClose}>
                Cancel
              </Button>
              <Button 
                colorScheme="blue" 
                onClick={handleChangePassword}
                isLoading={isSaving}
              >
                Change Password
              </Button>
            </ModalFooter>
          </ModalContent>
        </Modal>

        {/* Delete Account Modal */}
        <Modal isOpen={isDeleteOpen} onClose={onDeleteClose}>
          <ModalOverlay />
          <ModalContent>
            <ModalHeader color="red.600">Delete Account</ModalHeader>
            <ModalCloseButton />
            <ModalBody>
              <VStack spacing={4} align="stretch">
                <Alert status="warning">
                  <AlertIcon />
                  <AlertDescription>
                    This action cannot be undone. Your account and all data will be permanently deleted.
                  </AlertDescription>
                </Alert>
                <Text>
                  Are you sure you want to delete your account? This will:
                </Text>
                <VStack align="start" spacing={2} pl={4}>
                  <Text>• Delete all your personal information</Text>
                  <Text>• Remove your job history</Text>
                  <Text>• Cancel any pending jobs</Text>
                  <Text>• Permanently disable your driver account</Text>
                </VStack>
              </VStack>
            </ModalBody>
            <ModalFooter>
              <Button variant="ghost" mr={3} onClick={onDeleteClose}>
                Cancel
              </Button>
              <Button colorScheme="red">
                Yes, Delete My Account
              </Button>
            </ModalFooter>
          </ModalContent>
        </Modal>
      </VStack>
    </DriverShell>
  );
}

import type { Metadata } from 'next';
import { Box, Container, Heading, Text, Button, VStack, SimpleGrid, Link as ChakraLink } from '@chakra-ui/react';
import { FaTruck } from 'react-icons/fa';
import Link from 'next/link';
import { locations } from '@/data/locations';

export const metadata: Metadata = {
  title: 'Man and Van Services UK | 24/7 Removals | Speedy Van',
  description: 'Professional man and van services across the UK. 24/7 online booking, instant quotes, fully insured. From £25/hour. Same-day service available.',
  keywords: 'man and van uk, removals uk, van hire uk, delivery service uk',
};

export default function ManAndVanIndexPage() {
  // Group locations by first letter
  const groupedLocations = locations.reduce((acc, location) => {
    const firstLetter = location.name[0].toUpperCase();
    if (!acc[firstLetter]) {
      acc[firstLetter] = [];
    }
    acc[firstLetter].push(location);
    return acc;
  }, {} as Record<string, typeof locations>);

  const sortedLetters = Object.keys(groupedLocations).sort();

  return (
    <Box>
      {/* Hero */}
      <Box bg="brand.500" color="white" py={{ base: 12, md: 20 }}>
        <Container maxW="container.xl">
          <VStack spacing={6} align="start">
            <Heading as="h1" size="2xl" fontWeight="bold">
              Man and Van Services Across the UK
            </Heading>
            <Text fontSize="xl" maxW="2xl">
              Professional removal and delivery service available 24/7 in {locations.length}+ UK locations.
              Instant online booking, fully insured, from just £25/hour.
            </Text>
            <Link href="/booking-luxury">
              <Button
                size="lg"
                bg="white"
                color="brand.500"
                _hover={{ bg: 'gray.100' }}
                leftIcon={<FaTruck />}
              >
                Get Instant Quote
              </Button>
            </Link>
          </VStack>
        </Container>
      </Box>

      {/* Locations Directory */}
      <Container maxW="container.xl" py={{ base: 12, md: 16 }}>
        <Heading size="xl" mb={8}>Find Man and Van Services in Your Area</Heading>
        
        {sortedLetters.map((letter) => (
          <Box key={letter} mb={8}>
            <Heading size="md" mb={4} color="brand.500">{letter}</Heading>
            <SimpleGrid columns={{ base: 2, md: 3, lg: 4 }} spacing={4}>
              {groupedLocations[letter].map((location) => (
                <ChakraLink
                  key={location.slug}
                  as={Link}
                  href={`/man-and-van/${location.slug}`}
                  color="gray.700"
                  _hover={{ color: 'brand.500', textDecoration: 'underline' }}
                >
                  {location.name}
                </ChakraLink>
              ))}
            </SimpleGrid>
          </Box>
        ))}

        {/* CTA */}
        <Box mt={16} textAlign="center" bg="gray.50" p={8} borderRadius="lg">
          <Heading size="lg" mb={4}>Don't See Your Location?</Heading>
          <Text mb={6}>We serve the entire UK. Get an instant quote for your area.</Text>
          <Link href="/booking-luxury">
            <Button size="lg" colorScheme="brand" leftIcon={<FaTruck />}>
              Get Instant Quote
            </Button>
          </Link>
        </Box>
      </Container>
    </Box>
  );
}

'use client';

import React, { useEffect, useState } from 'react';
import { motion } from 'framer-motion';
import {
  Box,
  VStack,
  HStack,
  Heading,
  Text,
  Button,
  Icon,
  Container,
  Image,
  Badge,
  Alert,
  AlertIcon,
  AlertTitle,
  AlertDescription,
  useToast,
} from '@chakra-ui/react';
import {
  FaWifi,
  FaExclamationTriangle,
  FaRedo,
  FaHome,
  FaPhone,
  FaEnvelope,
  FaMapMarkerAlt,
  FaClock,
  FaCheckCircle,
} from 'react-icons/fa';

const OfflinePage: React.FC = () => {
  const [isOnline, setIsOnline] = useState(false);
  const [retryCount, setRetryCount] = useState(0);
  const toast = useToast();

  useEffect(() => {
    const handleOnline = () => {
      setIsOnline(true);
      toast({
        title: 'Connection Restored!',
        description: 'You are back online. You can now continue with your luxury booking.',
        status: 'success',
        duration: 5000,
        isClosable: true,
      });
    };

    const handleOffline = () => {
      setIsOnline(false);
    };

    // Check initial online status
    setIsOnline(navigator.onLine);

    // Listen for online/offline events
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, [toast]);

  const handleRetry = () => {
    setRetryCount(prev => prev + 1);
    
    if (navigator.onLine) {
      window.location.reload();
    } else {
      toast({
        title: 'Still Offline',
        description: 'Please check your internet connection and try again.',
        status: 'warning',
        duration: 3000,
        isClosable: true,
      });
    }
  };

  const handleGoHome = () => {
    window.location.href = '/';
  };

  return (
    <Box minH="100vh" bg="bg.canvas" py={8}>
      <Container maxW="md" px={4}>
        <VStack spacing={8} textAlign="center">
          {/* Header */}
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
viewport={{ once: true }}
            transition={{ duration: 0.6, ease: "easeOut" }}
          >
            <VStack spacing={4}>
              <Box
                p={6}
                borderRadius="full"
                bg="linear-gradient(135deg, rgba(0,194,255,0.1), rgba(0,209,143,0.1))"
                borderWidth="2px"
                borderColor="border.neon"
              >
                <Icon
                  as={isOnline ? FaWifi : FaExclamationTriangle}
                  boxSize={16}
                  color={isOnline ? 'green.500' : 'red.500'}
                />
              </Box>
              
              <Heading
                size="xl"
                color="text.primary"
                bg="linear-gradient(135deg, #00C2FF, #00D18F)"
                bgClip="text"
                fontWeight="bold"
              >
                {isOnline ? 'Connection Restored!' : 'You\'re Offline'}
              </Heading>
              
              <Text fontSize="lg" color="text.secondary" maxW="md">
                {isOnline 
                  ? 'Great! Your internet connection is back. You can now continue with your booking.'
                  : 'It looks like you\'re not connected to the internet. Don\'t worry, we\'ve saved your progress!'
                }
              </Text>
            </VStack>
          </motion.div>

          {/* Status Badge */}
          <motion.div
            initial={{ opacity: 0, scale: 0.8 }}
            whileInView={{ opacity: 1, scale: 1 }}
viewport={{ once: true }}
            transition={{ duration: 0.4, ease: "easeOut", delay: 0.2 }}
          >
            <Badge
              colorScheme={isOnline ? 'green' : 'red'}
              size="lg"
              px={4}
              py={2}
              borderRadius="full"
              fontSize="sm"
              fontWeight="bold"
            >
              <HStack spacing={2}>
                <Icon as={isOnline ? FaCheckCircle : FaExclamationTriangle} />
                <Text>
                  {isOnline ? 'Online' : 'Offline'}
                </Text>
              </HStack>
            </Badge>
          </motion.div>

          {/* Offline Features */}
          {!isOnline && (
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              whileInView={{ opacity: 1, y: 0 }}
viewport={{ once: true }}
              transition={{ duration: 0.6, ease: "easeOut", delay: 0.4 }}
            >
              <VStack spacing={6} w="full">
                <Alert status="info" borderRadius="lg">
                  <AlertIcon />
                  <Box>
                    <AlertTitle>Offline Mode Active</AlertTitle>
                    <AlertDescription>
                      Your luxury booking progress has been saved locally. You can continue when you're back online.
                    </AlertDescription>
                  </Box>
                </Alert>

                <VStack spacing={4} w="full">
                  <Heading size="md" color="text.primary">
                    What you can do offline:
                  </Heading>
                  
                  <VStack spacing={3} w="full">
                    <HStack spacing={3} w="full" p={3} bg="gray.50" borderRadius="lg">
                      <Icon as={FaClock} color="blue.500" />
                      <Text fontSize="sm" color="text.secondary">
                        Review your booking details
                      </Text>
                    </HStack>
                    
                    <HStack spacing={3} w="full" p={3} bg="gray.50" borderRadius="lg">
                      <Icon as={FaCheckCircle} color="green.500" />
                      <Text fontSize="sm" color="text.secondary">
                        Edit item selections
                      </Text>
                    </HStack>
                    
                    <HStack spacing={3} w="full" p={3} bg="gray.50" borderRadius="lg">
                      <Icon as={FaClock} color="orange.500" />
                      <Text fontSize="sm" color="text.secondary">
                        Modify pickup/dropoff addresses
                      </Text>
                    </HStack>
                  </VStack>
                </VStack>
              </VStack>
            </motion.div>
          )}

          {/* Action Buttons */}
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
viewport={{ once: true }}
            transition={{ duration: 0.6, ease: "easeOut", delay: 0.6 }}
          >
            <VStack spacing={4} w="full">
              <Button
                colorScheme="neon"
                size="lg"
                w="full"
                leftIcon={<FaRedo />}
                onClick={handleRetry}
                isLoading={retryCount > 0 && !isOnline}
                loadingText="Checking Connection..."
              >
                {isOnline ? 'Continue Booking' : 'Try Again'}
              </Button>

              <Button
                variant="outline"
                size="lg"
                w="full"
                leftIcon={<FaHome />}
                onClick={handleGoHome}
              >
                Go to Homepage
              </Button>
            </VStack>
          </motion.div>

          {/* Contact Information */}
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
viewport={{ once: true }}
            transition={{ duration: 0.6, ease: "easeOut", delay: 0.8 }}
          >
            <VStack spacing={4} w="full" p={6} bg="gray.50" borderRadius="xl">
              <Heading size="sm" color="text.primary">
                Need Help?
              </Heading>
              
              <VStack spacing={3} w="full">
                <HStack spacing={3} w="full">
                  <Icon as={FaPhone} color="neon.500" />
                  <Text fontSize="sm" color="text.secondary">
                    01202 129746
                  </Text>
                </HStack>
                
                <HStack spacing={3} w="full">
                  <Icon as={FaEnvelope} color="neon.500" />
                  <Text fontSize="sm" color="text.secondary">
                    support@speedy-van.co.uk
                  </Text>
                </HStack>
                
                <HStack spacing={3} w="full">
                  <Icon as={FaMapMarkerAlt} color="neon.500" />
                  <Text fontSize="sm" color="text.secondary" textAlign="center">
                    Office 2.18 1 Barrack St, Hamilton ML3 0HS
                  </Text>
                </HStack>
              </VStack>
            </VStack>
          </motion.div>

          {/* Footer */}
          <motion.div
            initial={{ opacity: 0 }}
            whileInView={{ opacity: 1 }}
viewport={{ once: true }}
            transition={{ duration: 0.6, ease: "easeOut", delay: 1.0 }}
          >
            <Text fontSize="xs" color="text.tertiary" textAlign="center">
              Speedy Van - Professional Moving Services
              <br />
              Your booking progress is automatically saved
            </Text>
          </motion.div>
        </VStack>
      </Container>
    </Box>
  );
};

