export default function StaffDashboardPage() {
  const [todayAttendance, setTodayAttendance] = useState<TodayAttendance | null>(null);
  const [recentAttendance, setRecentAttendance] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [checkingIn, setCheckingIn] = useState(false);
  const [checkingOut, setCheckingOut] = useState(false);
  const [isLeaveModalOpen, setIsLeaveModalOpen] = useState(false);
  const toast = useToast();

  useEffect(() => {
    fetchTodayAttendance();
    fetchRecentAttendance();
  }, []);

  const fetchTodayAttendance = async () => {
    try {
      const response = await fetch('/api/staff/attendance/today');
      const data = await response.json();

      if (data.success) {
        setTodayAttendance(data.attendance);
      }
    } catch (error) {
      console.error('Error fetching today attendance:', error);
    } finally {
      setLoading(false);
    }
  };

  const fetchRecentAttendance = async () => {
    try {
      const response = await fetch('/api/staff/attendance?limit=10');
      const data = await response.json();

      if (data.success) {
        setRecentAttendance(data.attendances);
      }
    } catch (error) {
      console.error('Error fetching recent attendance:', error);
    }
  };

  const handleCheckIn = async () => {
    try {
      setCheckingIn(true);
      const response = await fetch('/api/staff/check-in', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({}),
      });

      const data = await response.json();

      if (data.success) {
        toast({
          title: 'Success',
          description: 'Checked in successfully',
          status: 'success',
          duration: 3000,
        });
        fetchTodayAttendance();
      } else {
        throw new Error(data.error);
      }
    } catch (error: any) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to check in',
        status: 'error',
        duration: 3000,
      });
    } finally {
      setCheckingIn(false);
    }
  };

  const handleCheckOut = async () => {
    try {
      setCheckingOut(true);
      const response = await fetch('/api/staff/check-out', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({}),
      });

      const data = await response.json();

      if (data.success) {
        toast({
          title: 'Success',
          description: 'Checked out successfully',
          status: 'success',
          duration: 3000,
        });
        fetchTodayAttendance();
        fetchRecentAttendance();
      } else {
        throw new Error(data.error);
      }
    } catch (error: any) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to check out',
        status: 'error',
        duration: 3000,
      });
    } finally {
      setCheckingOut(false);
    }
  };

  const getStatusBadge = (status: string) => {
    const colors: Record<string, string> = {
      present: 'green',
      absent: 'red',
      late: 'orange',
      early_leave: 'yellow',
      half_day: 'purple',
      pending: 'gray',
    };

    return (
      <Badge colorScheme={colors[status] || 'gray'} textTransform="capitalize">
        {status.replace('_', ' ')}
      </Badge>
    );
  };

  const formatTime = (time: string | null) => {
    if (!time) return 'N/A';
    return new Date(time).toLocaleTimeString('en-GB', {
      hour: '2-digit',
      minute: '2-digit',
    });
  };

  if (loading) {
    return (
      <Box p={6}>
        <Flex justify="center" align="center" minH="400px">
          <Spinner size="xl" />
        </Flex>
      </Box>
    );
  }

  const canCheckIn = !todayAttendance || !todayAttendance.checkIn;
  const canCheckOut = todayAttendance?.checkIn && !todayAttendance?.checkOut;

  return (
    <Box p={6}>
      <Heading size="lg" mb={6}>
        Staff Dashboard
      </Heading>

      {/* Today's Attendance Card */}
      <Card mb={6}>
        <CardBody>
          <VStack spacing={4} align="stretch">
            <Heading size="md">Today's Attendance</Heading>
            {todayAttendance ? (
              <Grid templateColumns={{ base: '1fr', md: 'repeat(3, 1fr)' }} gap={4}>
                <Stat>
                  <StatLabel>Check In</StatLabel>
                  <StatNumber fontSize="2xl">
                    {formatTime(todayAttendance.checkIn)}
                  </StatNumber>
                  {todayAttendance.lateMinutes > 0 && (
                    <StatHelpText color="orange.500">
                      {todayAttendance.lateMinutes} minutes late
