/**
 * Luxury Booking Postcode-First Address Autocomplete Component
 * Implements the exact requirements: Postcode → Address Selection → Validation
 * Uses Google Places API (primary) with Mapbox fallback
 */

'use client';

import React, { useState, useCallback, useEffect, useRef } from 'react';
import {
  Box,
  VStack,
  HStack,
  Text,
  Button,
  Icon,
  Alert,
  AlertIcon,
  AlertDescription,
  FormControl,
  FormLabel,
  FormErrorMessage,
  Input,
  Select,
  useToast,
  Collapse,
  Badge,
  Spinner,
  Divider,
} from '@chakra-ui/react';
import { 
  FaArrowRight, 
  FaArrowLeft,
  FaMapMarkerAlt,
  FaCheck,
  FaExclamationTriangle,
  FaInfoCircle,
} from 'react-icons/fa';

import { PostcodeValidator } from '@/lib/postcode-validator';
import type { AddressSuggestion, CompleteAddress } from '@/types/dual-provider-address';

type AddressStep = 'postcode' | 'address' | 'complete';

interface LuxuryPostcodeAddressAutocompleteProps {
  id: string;
  label: string;
  value?: CompleteAddress | null;
  onChange: (address: CompleteAddress | null) => void;
  error?: string;
  required?: boolean;
  disabled?: boolean;
  placeholder?: string;
}

interface AddressResult {
  id: string;
  displayText: string;
  fullAddress: string;
  coordinates: {
    lat: number;
    lng: number;
  };
  components: {
    street?: string;
    city?: string;
    postcode: string;
    country: string;
    houseNumber?: string;
    flatNumber?: string;
    buildingName?: string;
  };
  propertyDetails?: {
    houseNumber?: string;
    flatNumber?: string;
    buildingName?: string;
  };
  provider: 'google' | 'mapbox' | 'uk-postcode' | 'getaddress' | 'ideal-postcodes';
  confidence: number;
}

export const LuxuryPostcodeAddressAutocomplete: React.FC<LuxuryPostcodeAddressAutocompleteProps> = ({
  id,
  label,
  value,
  onChange,
  error,
  required = false,
  disabled = false,
  placeholder = "Enter your postcode first (e.g., G31 1DZ)",
}) => {
  const [currentStep, setCurrentStep] = useState<AddressStep>('postcode');
  const [postcode, setPostcode] = useState('');
  const [postcodeValidation, setPostcodeValidation] = useState<any>(null);
  const [availableAddresses, setAvailableAddresses] = useState<AddressResult[]>([]);
  const [selectedAddress, setSelectedAddress] = useState<AddressResult | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [apiError, setApiError] = useState<string | null>(null);
  const [currentProvider, setCurrentProvider] = useState<'google' | 'mapbox'>('google');
  const toast = useToast();
  const abortControllerRef = useRef<AbortController | null>(null);

  // Check if we can proceed from postcode step
  const canProceedFromPostcode = postcode.length >= 5 && !isLoading;

  // Handle postcode submission with enhanced validation
  const handlePostcodeSubmit = useCallback(async () => {
    if (!postcode.trim()) return;

    // Cancel any ongoing request
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
    }
    abortControllerRef.current = new AbortController();

    const validation = PostcodeValidator.validateUKPostcode(postcode);
    setPostcodeValidation(validation);
    setApiError(null);

    if (validation.isValid) {
      setIsLoading(true);
      
      try {
        // Normalize postcode for API call
        const normalizedPostcode = PostcodeValidator.normalizeForAPI(validation.formatted);
        console.log(`🔍 Starting PAF-based address search for postcode: ${normalizedPostcode} (original: ${validation.formatted})`);
        
        // Use the postcode-specific API endpoint for better results
        const apiUrl = `/api/address/postcode?postcode=${encodeURIComponent(normalizedPostcode)}&limit=50&includeSubPremises=true`;
        console.log(`📡 API Request URL: ${apiUrl}`);
        
        const response = await fetch(apiUrl, { 
          signal: abortControllerRef.current.signal,
          headers: {
            'Content-Type': 'application/json',
            'Accept': 'application/json'
          }
        });
        
        console.log(`📡 API Response Status: ${response.status} ${response.statusText}`);
        
        if (!response.ok) {
          const errorText = await response.text();
          console.error(`❌ API Error Response: ${errorText}`);
          throw new Error(`HTTP ${response.status}: ${response.statusText} - ${errorText}`);
        }
        
        const result = await response.json();
        console.log(`📋 API Response Data:`, {
          success: result.success,
          addressCount: result.data?.addresses?.length || 0,
          provider: result.data?.provider,
          postcode: result.data?.postcode
        });
        
        if (result.success && result.data && result.data.addresses && result.data.addresses.length > 0) {
          console.log(`✅ Received ${result.data.addresses.length} addresses from PAF-based API`);
          console.log('Sample addresses:', result.data.addresses.slice(0, 2));
          
          // Accept all valid addresses from PAF providers without additional filtering
          // PAF APIs already return verified, accurate addresses for the postcode
          const validAddresses = result.data.addresses.filter((addr: AddressResult) => {
            return addr.displayText && 
                   addr.coordinates && 
                   addr.coordinates.lat !== 0 && 
                   addr.coordinates.lng !== 0;
          });
          
          console.log(`✅ Using ${validAddresses.length} PAF-verified addresses`);

          if (validAddresses.length > 0) {
            setAvailableAddresses(validAddresses);
            setCurrentProvider(result.data.provider);
            setCurrentStep('address');
            
            toast({
              title: 'Addresses Found',
              description: `Found ${validAddresses.length} verified address${validAddresses.length === 1 ? '' : 'es'} for ${normalizedPostcode}`,
              status: 'success',
              duration: 2000,
              isClosable: true,
            });
          } else {
            console.error(`❌ PAF API returned empty addresses for ${normalizedPostcode}`);
            
            toast({
              title: 'No Addresses Found',
              description: `No verified addresses found for ${normalizedPostcode}. Please check the postcode.`,
              status: 'warning',
              duration: 4000,
              isClosable: true,
            });
          }
        } else {
          // Fallback to general autocomplete API
          try {
            const fallbackResponse = await fetch(
              `/api/address/autocomplete?query=${encodeURIComponent(validation.formatted)}&limit=20&types=address`,
              { signal: abortControllerRef.current.signal }
            );
            const fallbackResult = await fallbackResponse.json();
            
            if (fallbackResult.success && fallbackResult.data.suggestions.length > 0) {
              const fallbackAddresses: AddressResult[] = fallbackResult.data.suggestions.map((suggestion: any) => ({
                id: suggestion.id,
                displayText: suggestion.displayText,
                fullAddress: suggestion.fullAddress,
                coordinates: suggestion.coordinates,
                components: suggestion.components,
                provider: suggestion.provider,
                confidence: suggestion.confidence,
              }));
              
              setAvailableAddresses(fallbackAddresses);
              setCurrentProvider(fallbackResult.data.provider);
              setCurrentStep('address');
              
              toast({
                title: '✓ Postcode Verified',
                description: `Found ${fallbackAddresses.length} address${fallbackAddresses.length === 1 ? '' : 'es'} in ${validation.formatted}. Select yours below.`,
                status: 'success',
                duration: 3000,
                isClosable: true,
              });
            } else {
              toast({
                title: 'No addresses found',
                description: `No addresses found for ${validation.formatted}. Please try a different postcode.`,
                status: 'warning',
                duration: 4000,
                isClosable: true,
              });
            }
          } catch (fallbackError) {
            console.error('Fallback search failed:', fallbackError);
            setApiError('Unable to search for addresses. Please try again.');
            toast({
              title: 'Search failed',
              description: 'Unable to search for addresses. Please try again.',
              status: 'error',
              duration: 4000,
              isClosable: true,
            });
          }
        }
      } catch (error: any) {
        if (error.name !== 'AbortError') {
          console.error('❌ Failed to fetch addresses for postcode:', {
            postcode: validation.formatted,
            error: error.message,
            stack: error.stack
          });
          setApiError(error.message || 'Network error occurred');
          toast({
            title: 'Search Failed',
            description: `Unable to search for addresses for ${validation.formatted}. Please try again.`,
            status: 'error',
            duration: 4000,
            isClosable: true,
          });
        }
      } finally {
        setIsLoading(false);
      }
    } else {
      toast({
        title: 'Invalid Postcode',
        description: 'Please enter a valid UK postcode (e.g., SW1A 1AA, M1 1AA, B1 1BB)',
        status: 'error',
        duration: 3000,
        isClosable: true,
      });
    }
  }, [postcode, toast]);

  // Address selection
  const handleAddressSelect = useCallback((addressId: string) => {
    const selected = availableAddresses.find(addr => addr.id === addressId);
    if (selected) {
      setSelectedAddress(selected);
      
      // Convert to CompleteAddress format
      const completeAddress: CompleteAddress = {
        ...selected,
        mainText: selected.displayText.split(',')[0],
        secondaryText: selected.displayText.split(',').slice(1).join(','),
        type: 'address',
        components: {
          street: selected.components?.street || '',
          city: selected.components?.city || '',
          postcode: selected.components.postcode,
          country: selected.components.country,
          houseNumber: selected.components?.houseNumber || '',
          flatNumber: selected.components?.flatNumber || '',
        },
        propertyDetails: {
          houseNumber: selected.components?.houseNumber || '',
          flatNumber: selected.components?.flatNumber || '',
          buildingName: '',
          floor: '',
          businessName: '',
        },
        isPostcodeValidated: true,
        stepCompletedAt: new Date().toISOString(),
      };
      
      setCurrentStep('complete');
      onChange(completeAddress);
      
      toast({
        title: '✓ Verified Address Selected',
        description: `Genuine address confirmed: ${selected.displayText}`,
        status: 'success',
        duration: 2000,
        isClosable: true,
      });
    }
  }, [availableAddresses, onChange, toast]);

  // Reset to postcode step
  const handleChangePostcode = useCallback(() => {
    setCurrentStep('postcode');
    setSelectedAddress(null);
    setAvailableAddresses([]);
    setApiError(null);
    onChange(null);
  }, [onChange]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (abortControllerRef.current) {
        abortControllerRef.current.abort();
      }
    };
  }, []);

  return (
    <Box w="full">
      {/* PREMIUM HEADER - MATCHING BOOKING-LUXURY DESIGN */}
      <Box 
        bg="rgba(255, 255, 255, 0.95)" 
        backdropFilter="blur(10px)"
        shadow="0 8px 32px rgba(0, 0, 0, 0.12)" 
        borderRadius="2xl" 
        border="1px solid rgba(255, 255, 255, 0.2)"
        p={{ base: 4, md: 6 }}
        mb={6}
      >
        <HStack spacing={4} justify="space-between" align="center">
          {/* LEFT: Brand */}
          <HStack spacing={4}>
            <Icon as={FaMapMarkerAlt} boxSize={8} color="blue.600" />
            <VStack align="start" spacing={1}>
              <Text fontSize="lg" fontWeight="bold" color="gray.800">Address Lookup</Text>
              <HStack spacing={3}>
                <Badge colorScheme="blue" variant="subtle" fontSize="xs">
                  <Icon as={FaCheck} mr={1} />
                  Official UK Data
                </Badge>
                <Badge colorScheme="green" variant="subtle" fontSize="xs">
                  <Icon as={FaInfoCircle} mr={1} />
                  Postcode First
                </Badge>
              </HStack>
            </VStack>
          </HStack>

          {/* RIGHT: Status */}
          {selectedAddress && (
            <Badge colorScheme="green" variant="solid" fontSize="sm" p={2} borderRadius="lg">
              <Icon as={FaCheck} mr={2} />
              Address Validated
            </Badge>
          )}
        </HStack>
      </Box>

      <FormControl isInvalid={!!error} isRequired={required}>

        {/* MAIN CONTENT CARD - MATCHING BOOKING-LUXURY STYLE */}
        <Box 
          bg="rgba(255, 255, 255, 0.95)" 
          backdropFilter="blur(10px)"
          shadow="0 4px 20px rgba(0, 0, 0, 0.08)" 
          borderRadius="xl" 
          border="1px solid rgba(255, 255, 255, 0.2)"
          overflow="hidden"
        >
          <Box p={{ base: 6, md: 8 }}>
            <VStack spacing={6} align="stretch">
              
              {/* Step 1: Postcode Entry */}
              <Collapse in={currentStep === 'postcode'} animateOpacity>
                <VStack spacing={6} align="stretch">
                  <Box textAlign="center">
                    <Text fontSize="xl" fontWeight="bold" color="gray.800" mb={2}>
                      Enter your postcode first
                    </Text>
                    <Text fontSize="md" color="green.600" fontWeight="medium">
                      🔒 All addresses are sourced from official UK address databases - 100% genuine data
                    </Text>
                  </Box>
              
              <Input
                value={postcode}
                onChange={(e) => setPostcode(e.target.value.toUpperCase())}
                placeholder={placeholder}
                maxLength={8}
                disabled={disabled}
                size="lg"
                fontSize="md"
                bg="white"
                border="2px solid"
                borderColor="gray.300"
                borderRadius="lg"
                _focus={{ 
                  borderColor: 'blue.500',
                  boxShadow: '0 0 0 1px #3182ce'
                }}
                _placeholder={{ color: 'gray.400' }}
                onKeyPress={(e) => {
                  if (e.key === 'Enter' && canProceedFromPostcode) {
                    handlePostcodeSubmit();
                  }
                }}
              />
              
              <Button
                onClick={handlePostcodeSubmit}
                size="lg"
                bg="blue.600"
                color="white"
                _hover={{ bg: 'blue.700' }}
                _active={{ bg: 'blue.800' }}
                rightIcon={<FaArrowRight />}
                isLoading={isLoading}
                loadingText="Finding addresses"
                isDisabled={!canProceedFromPostcode || disabled}
                borderRadius="lg"
                fontWeight="semibold"
              >
                Find addresses
              </Button>

              {/* Postcode validation feedback */}
              {postcodeValidation && !postcodeValidation.isValid && postcode.length > 0 && (
                <Alert status="error" borderRadius="md" bg="red.50" borderColor="red.200">
                  <AlertIcon color="red.500" />
                  <AlertDescription color="red.700">
                    Please enter a valid UK postcode
                  </AlertDescription>
                </Alert>
              )}
            </VStack>
          </Collapse>

          {/* Step 2: Address Selection */}
          <Collapse in={currentStep === 'address'} animateOpacity>
            <VStack spacing={6} align="stretch">
              {/* Postcode display with change option */}
              <VStack spacing={4} align="stretch">
                <HStack justify="space-between" align="center">
                  <VStack align="start" spacing={1}>
                    <Text fontSize="md" color="gray.700">
                      Postcode: <Text as="span" fontWeight="bold">{postcodeValidation?.formatted}</Text>
                    </Text>
                    <HStack spacing={2}>
                      <Badge 
                        colorScheme={
                          currentProvider === 'google' ? 'blue' : 'green'
                        } 
                        size="sm"
                      >
                        {currentProvider === 'google' ? '🟦 Google Places' :
                         '🟢 Mapbox'}
                      </Badge>
                      <Text fontSize="xs" color="gray.500">
                        {availableAddresses.length} addresses found
                      </Text>
                    </HStack>
                  </VStack>
                  <Button 
                    variant="link" 
                    color="blue.600" 
                    fontSize="sm"
                    textDecoration="underline"
                    p={0}
                    h="auto"
                    onClick={handleChangePostcode}
                  >
                    Change postcode
                  </Button>
                </HStack>
              </VStack>

              <Divider />

              {/* Address Selection Dropdown */}
              {availableAddresses.length > 0 && (
                <VStack spacing={4} align="stretch">
                  <Text fontSize="md" fontWeight="semibold" color="gray.800">
                    Select your exact address:
                  </Text>
                  <VStack spacing={2} align="start">
                    <Text fontSize="sm" color="green.600" fontWeight="medium">
                      ✅ All addresses below are verified from official UK sources
                    </Text>
                    <HStack spacing={4} fontSize="xs" color="gray.600">
                      <HStack spacing={1}>
                        <Text>🏠</Text>
                        <Text>House</Text>
                      </HStack>
                      <HStack spacing={1}>
                        <Text>🏢</Text>
                        <Text>Flat</Text>
                      </HStack>
                      <HStack spacing={1}>
                        <Text>📍</Text>
                        <Text>Exact Location</Text>
                      </HStack>
                    </HStack>
                  </VStack>
                  
                  <FormControl isRequired>
                    <Select 
                      placeholder="Please select your address..."
                      size="lg"
                      fontSize="md"
                      value={selectedAddress?.id || ''}
                      onChange={(e) => {
                        if (e.target.value) {
                          handleAddressSelect(e.target.value);
                        }
                      }}
                      bg="white"
                      border="2px solid"
                      borderColor="gray.300"
                      borderRadius="lg"
                      _hover={{ borderColor: 'blue.400' }}
                      _focus={{ 
                        borderColor: 'blue.500', 
                        boxShadow: '0 0 0 1px #3182ce' 
                      }}
                    >
                      {availableAddresses.map((address, index) => {
                        // Enhanced display format with full details
                        const components = address.components;
                        const propertyDetails = address.propertyDetails;
                        
                        let fullDisplay = address.displayText;
                        
                        // If we have detailed components, create more complete display
                        if (components) {
                          const parts = [];
                          
                          // Add flat/unit if present
                          if (propertyDetails?.flatNumber || components.flatNumber) {
                            parts.push(`Flat ${propertyDetails?.flatNumber || components.flatNumber}`);
                          }
                          
                          // Add house number if present
                          if (propertyDetails?.houseNumber || components.houseNumber) {
                            parts.push(propertyDetails?.houseNumber || components.houseNumber);
                          }
                          
                          // Add street
                          if (components.street) {
                            parts.push(components.street);
                          }
                          
                          // Add city
                          if (components.city) {
                            parts.push(components.city);
                          }
                          
                          // Add postcode for clarity
                          if (components.postcode) {
                            parts.push(components.postcode);
                          }
                          
                          if (parts.length > 2) { // Only use enhanced format if we have good data
                            fullDisplay = parts.join(', ');
                          }
                        }
                        
                        return (
                          <option key={address.id || index} value={address.id}>
                            {fullDisplay}
                          </option>
                        );
                      })}
                    </Select>
                  </FormControl>
                </VStack>
              )}

              {/* API Error Display */}
              {apiError && (
                <Alert status="error" borderRadius="md">
                  <AlertIcon />
                  <AlertDescription>{apiError}</AlertDescription>
                </Alert>
              )}
            </VStack>
          </Collapse>

          {/* Step 3: Confirmation */}
          <Collapse in={currentStep === 'complete'} animateOpacity>
            <VStack spacing={4} align="stretch">
              <Alert status="success" borderRadius="md" bg="green.50" borderColor="green.200">
                <AlertIcon color="green.500" />
                <VStack align="start" spacing={1} flex="1">
                  <Text fontWeight="bold" color="green.800">
                    ✓ Address Selected
                  </Text>
                  <Text color="green.700" fontSize="sm">
                    {selectedAddress?.displayText}
                  </Text>
                  <HStack spacing={2} mt={2}>
                    <Badge 
                      colorScheme={
                        currentProvider === 'google' ? 'blue' : 'green'
                      } 
                      variant="subtle" 
                      fontSize="xs"
                    >
                      {currentProvider === 'google' ? '🟦 Google' :
                       '🟢 Mapbox'}
                    </Badge>
                    <Badge colorScheme="blue" variant="subtle" fontSize="xs">
                      Verified
                    </Badge>
                  </HStack>
                </VStack>
              </Alert>
              
              <Button
                leftIcon={<FaArrowLeft />}
                onClick={handleChangePostcode}
                variant="outline"
                colorScheme="blue"
                size="md"
                alignSelf="flex-start"
              >
                Change Address
              </Button>
            </VStack>
          </Collapse>
        </VStack>

        {error && (
          <FormErrorMessage fontSize="sm" mt={2}>
            <HStack spacing={1}>
              <Icon as={FaExclamationTriangle} color="red.500" boxSize={3} />
              <Text>{error}</Text>
            </HStack>
          </FormErrorMessage>
        )}
          </Box>
        </Box>
      </FormControl>
    </Box>
  );
};

export default LuxuryPostcodeAddressAutocomplete;

/**
 * UK Address Autocomplete Component - Premium UI
 * Google Places API (Primary) + Mapbox (Fallback)
 * Professional design with enhanced UX for luxury booking platform
 */

import React, { useState, useCallback, useRef, useEffect, useMemo } from 'react';
import {
  Box,
  Input,
  VStack,
  HStack,
  Text,
  Spinner,
  Alert,
  AlertIcon,
  useToast,
  IconButton,
  Fade,
  Icon,
  InputGroup,
  InputRightElement,
  Select,
  Switch,
  SimpleGrid,
  FormLabel,
  Portal,
} from '@chakra-ui/react';
import { 
  CheckIcon, 
  CloseIcon,
  Search2Icon
} from '@chakra-ui/icons';
import { FaMapMarkerAlt, FaCheckCircle } from 'react-icons/fa';
import { PostcodeValidator } from '@/lib/postcode-validator';
// CompleteAddress type definition with building details
interface CompleteAddress {
  full: string;
  line1: string;
  line2?: string;
  city: string;
  postcode: string;
  country: string;
  coordinates: {
    lat: number;
    lng: number;
  };
  formatted: {
    street: string;
    houseNumber: string;
    flatNumber?: string;
    floor?: string;
    businessName?: string;
  };
  isPostcodeValidated: boolean;
  stepCompletedAt: string;
  buildingDetails?: {
    type?: string;
    hasElevator?: boolean;
    floorNumber?: string;
    apartmentNumber?: string;
  };
}

interface AddressSuggestion {
  id: string;
  displayText: string;
  mainText?: string;
  secondaryText?: string;
  provider: 'google' | 'mapbox';
  confidence: number;
  sessionToken?: string;
  coordinates?: {
    lat: number;
    lng: number;
  };
  components?: {
    houseNumber?: string;
    street?: string;
    city?: string;
    postcode?: string;
    country?: string;
    flatNumber?: string;
  };
}

interface UKAddressAutocompleteProps {
  id: string;
  label: string;
  value: CompleteAddress | null;
  onChange: (address: CompleteAddress | null) => void;
  placeholder?: string;
  isRequired?: boolean;
  helperText?: string;
  size?: 'sm' | 'md' | 'lg';
}

interface AddressDetails {
  floorNumber?: string;
  apartmentNumber?: string;
  hasElevator?: boolean;
}

const isScrollDebugEnabled = process.env.NODE_ENV !== 'production';

export const UKAddressAutocomplete: React.FC<UKAddressAutocompleteProps> = ({
  id,
  label,
  value,
  onChange,
  placeholder = "Start typing your address...",
  isRequired = false,
  helperText,
  size = 'md'
}) => {
  const [inputValue, setInputValue] = useState(value?.full || '');
  const [suggestions, setSuggestions] = useState<AddressSuggestion[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [selectedIndex, setSelectedIndex] = useState(-1);
  const [sessionToken, setSessionToken] = useState<string>('');
  const [apiError, setApiError] = useState<string>('');
  const [currentProvider, setCurrentProvider] = useState<string>('');
  
  // Additional address details state
  const [floorNumber, setFloorNumber] = useState(value?.buildingDetails?.floorNumber || value?.formatted?.floor || '');
const [apartmentNumber, setApartmentNumber] = useState(value?.buildingDetails?.apartmentNumber || value?.formatted?.flatNumber || '');
  const [hasElevator, setHasElevator] = useState(value?.buildingDetails?.hasElevator || false);
  
  const floorOptions = useMemo(() => {
    const options: Array<{ value: string; label: string }> = [
      { value: '', label: 'Select floor' },
      { value: '-1', label: 'Basement (-1)' },
      { value: '0', label: 'Ground (0)' },
    ];

    const getOrdinal = (n: number) => {
      if (n === 1) return '1st';
      if (n === 2) return '2nd';
      if (n === 3) return '3rd';
      return `${n}th`;
    };

    for (let i = 1; i <= 30; i += 1) {
      options.push({ value: i.toString(), label: `${getOrdinal(i)} Floor` });
    }

    options.push({ value: '40+', label: '41st Floor or higher' });
    return options;
  }, []);

  const flatOptions = useMemo(() => {
    const options: Array<{ value: string; label: string }> = [
      { value: '', label: 'Select flat' },
    ];

    for (let i = 1; i <= 60; i += 1) {
      options.push({ value: i.toString(), label: `Flat ${i}` });
    }

    const suffixes = ['A', 'B', 'C', 'D'];
    for (let i = 1; i <= 20; i += 1) {
      suffixes.forEach((suffix) => {
        options.push({ value: `${i}${suffix}`, label: `Flat ${i}${suffix}` });
      });
    }

    options.push({ value: 'PH', label: 'Penthouse' });
    options.push({ value: 'GF', label: 'Garden Flat' });

    return options;
  }, []);

  const abortControllerRef = useRef<AbortController | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const dropdownRef = useRef<HTMLDivElement>(null);
  const isSelectingRef = useRef(false); // Prevent double selection
  const justSelectedRef = useRef(false); // Prevent search after selection
  const toast = useToast();
  const [dropdownStyle, setDropdownStyle] = useState<{ top: number; left: number; width: number }>({ top: 0, left: 0, width: 0 });

  const scrollDebug = useCallback((phase: string, payload?: Record<string, unknown>) => {
    if (!isScrollDebugEnabled) {
      return;
    }
    console.log(`[UKAddressAutocomplete][${id}][${phase}]`, payload ?? {});
  }, [id]);


  // Generate session token on mount
  useEffect(() => {
    const token = Math.random().toString(36).substring(2, 15) + 
                  Math.random().toString(36).substring(2, 15);
    setSessionToken(token);
  }, []);

  // CRITICAL FIX: Sync inputValue with value prop changes
  // This ensures that when navigating back from step 2 to step 1,
  // the address fields are restored with the previously entered values
  useEffect(() => {
    if (value?.full && value.full !== inputValue) {
      console.log(`✅ [${id}] Restoring address from formData:`, value.full);
      setInputValue(value.full);
    }
    // Also sync building details
    if (value?.buildingDetails?.floorNumber !== undefined) {
      setFloorNumber(value.buildingDetails.floorNumber || value?.formatted?.floor || '');
    }
    if (value?.buildingDetails?.apartmentNumber !== undefined) {
      setApartmentNumber(value.buildingDetails.apartmentNumber || value?.formatted?.flatNumber || '');
    }
    if (value?.buildingDetails?.hasElevator !== undefined) {
      setHasElevator(value.buildingDetails.hasElevator);
    }
  }, [value, inputValue, id]);

  // Debounced search function - Now starts at 2 characters
  const searchAddresses = useCallback(async (query: string) => {
    if (!query || query.trim().length < 2) {
      setSuggestions([]);
      setShowSuggestions(false);
      return;
    }

    // Cancel previous request
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
    }
    abortControllerRef.current = new AbortController();

    setIsLoading(true);
    setApiError('');

    try {
      console.log(`🔍 Searching UK addresses for: "${query}"`);
      console.log(`📡 Session Token: ${sessionToken}`);

      const url = `/api/address/autocomplete-uk?query=${encodeURIComponent(query)}&sessionToken=${encodeURIComponent(sessionToken)}`;
      console.log(`📡 Request URL: ${url}`);

      const response = await fetch(url, {
        signal: abortControllerRef.current.signal,
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json'
        }
      });

      console.log(`📡 Response Status: ${response.status} ${response.statusText}`);

      if (!response.ok) {
        const errorText = await response.text();
        console.error(`❌ API Error Response:`, {
          status: response.status,
          statusText: response.statusText,
          body: errorText
        });
        throw new Error(`API request failed: ${response.status}`);
      }

      const result = await response.json();
      console.log(`📋 API Response:`, {
        success: result.success,
        suggestionCount: result.data?.suggestions?.length || 0,
        provider: result.data?.provider,
        fallbackAttempted: result.data?.fallbackAttempted,
        responseTime: result.responseTime
      });

      if (result.success && result.data && result.data.suggestions) {
        setSuggestions(result.data.suggestions);
        setCurrentProvider(result.data.provider);
        setShowSuggestions(true);
        setSelectedIndex(result.data.suggestions.length > 0 ? 0 : -1); // Auto-highlight first suggestion

        console.log(`✅ Found ${result.data.suggestions.length} suggestions from ${result.data.provider}`);
      } else {
        console.warn('❌ Invalid API response:', result);
        setSuggestions([]);
        setShowSuggestions(false);
        
        toast({
          title: 'Search Failed',
          description: result.error || 'Unable to search for addresses. Please try again.',
          status: 'error',
          duration: 4000,
          isClosable: true,
        });
      }
    } catch (error: any) {
      if (error.name !== 'AbortError') {
        console.error('❌ Address search failed:', {
          query,
          error: error.message,
          timestamp: new Date().toISOString()
        });

        setApiError(error.message);
        setSuggestions([]);
        setShowSuggestions(false);

        toast({
          title: 'Search Error',
          description: 'Network error occurred. Please check your connection and try again.',
          status: 'error',
          duration: 4000,
          isClosable: true,
        });
      }
    } finally {
      setIsLoading(false);
    }
  }, [sessionToken, toast]);

  // Debounce search calls - Now triggers at 2 characters
  useEffect(() => {
    // CRITICAL: Don't search if user just selected a suggestion
    if (justSelectedRef.current) {
      console.log('⏭️ Skipping search - user just selected an address');
      return;
    }
    
    // Don't search if dropdown is already closed (user selected something)
    if (!showSuggestions && inputValue === value?.full) {
      console.log('⏭️ Skipping search - address already selected');
      return; // Skip search if user just selected an address
    }

    const timer = setTimeout(() => {
      if (inputValue.trim().length >= 2 && !justSelectedRef.current) {
        searchAddresses(inputValue);
      } else {
        setSuggestions([]);
        setShowSuggestions(false);
      }
    }, 250); // Slightly faster response

    return () => clearTimeout(timer);
  }, [inputValue, searchAddresses, showSuggestions, value?.full]);


  // Handle suggestion selection - IMMEDIATE single-click selection
  const selectSuggestion = useCallback(async (suggestion: AddressSuggestion) => {
    // Prevent double selection - CRITICAL FIX
    if (isSelectingRef.current) {
      console.log('⚠️ Selection already in progress - ignoring duplicate call');
      return;
    }
    
    isSelectingRef.current = true; // Lock selection
    justSelectedRef.current = true; // Mark that we just selected (prevent search)
    
    console.log(`✅ Selected suggestion:`, {
      id: suggestion.id,
      text: suggestion.displayText,
      provider: suggestion.provider
    });

    // IMMEDIATE UI updates - CLOSE DROPDOWN FIRST to prevent any re-opening
    setShowSuggestions(false);  // Close dropdown FIRST
    setSuggestions([]);         // Clear suggestions IMMEDIATELY
    setSelectedIndex(-1);       // Reset selection
    
    // Then update input value
    setInputValue(suggestion.displayText);

    setIsLoading(true);
    setApiError('');

    try {
      let fullAddressData = suggestion;

      // Get full details for Google Places suggestions
      if (suggestion.provider === 'google' && suggestion.id.startsWith('place_id:') === false) {
        console.log(`🔍 Fetching place details for: ${suggestion.id}`);

        const detailsResponse = await fetch('/api/address/autocomplete-uk', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({
            placeId: suggestion.id,
            sessionToken: suggestion.sessionToken || sessionToken
          })
        });

        if (detailsResponse.ok) {
          const detailsResult = await detailsResponse.json();
          if (detailsResult.success) {
            fullAddressData = detailsResult.data;
            console.log(`✅ Got place details:`, fullAddressData);
          }
        }
      }

      // Convert to CompleteAddress format with additional details
      const completeAddress: CompleteAddress = {
        full: fullAddressData.displayText,
        line1: [
          fullAddressData.components?.houseNumber,
          fullAddressData.components?.street
        ].filter(Boolean).join(' ') || '',
        line2: apartmentNumber ? `Flat ${apartmentNumber}` : (fullAddressData.components?.flatNumber ? `Flat ${fullAddressData.components.flatNumber}` : ''),
        city: fullAddressData.components?.city || '',
        postcode: fullAddressData.components?.postcode || '',
        country: 'United Kingdom',
        coordinates: fullAddressData.coordinates ? {
          lat: fullAddressData.coordinates.lat,
          lng: fullAddressData.coordinates.lng
        } : { lat: 0, lng: 0 },
        formatted: {
          street: fullAddressData.components?.street || '',
          houseNumber: fullAddressData.components?.houseNumber || '',
          flatNumber: apartmentNumber || fullAddressData.components?.flatNumber || '',
          floor: floorNumber,
          businessName: ''
        },
        isPostcodeValidated: !!fullAddressData.components?.postcode,
        stepCompletedAt: new Date().toISOString(),
        // Add new fields to the address object
        buildingDetails: {
          hasElevator: hasElevator,
          floorNumber: floorNumber,
          apartmentNumber: apartmentNumber
        }
      };

      onChange(completeAddress);

      // Brief success indication without toast (cleaner UX)
      console.log(`✅ Address selected from ${fullAddressData.provider}:`, completeAddress.full);

    } catch (error) {
      console.error('❌ Error fetching address details:', error);
      
      toast({
        title: 'Selection Error',
        description: 'Failed to get full address details. Please try selecting again.',
        status: 'error',
        duration: 4000,
        isClosable: true,
      });
      
      // Unlock selection after error
      isSelectingRef.current = false;
    } finally {
      setIsLoading(false);
      // Unlock selection after completion
      setTimeout(() => {
        isSelectingRef.current = false;
        // Keep justSelectedRef true for a bit longer to prevent search trigger
        setTimeout(() => {
          justSelectedRef.current = false;
        }, 500); // Keep for 500ms to ensure useEffect doesn't trigger search
      }, 100); // Small delay to prevent rapid double-clicks
    }
  }, [onChange, sessionToken, toast, floorNumber, apartmentNumber, hasElevator]);

  // Handle input changes - prevent search when address is already selected
  const handleInputChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const newValue = e.target.value;
    
    // If user is typing (not programmatic update), clear the justSelected flag
    justSelectedRef.current = false;
    
    setInputValue(newValue);
    
    // Only trigger search if this is actual user typing, not programmatic setting
    if (newValue !== value?.full) {
      onChange(null); // Clear selection when input changes
      setApiError(''); // Clear any errors
      setShowSuggestions(false); // Hide suggestions when user starts typing
      setSuggestions([]); // Clear suggestions
    }
  }, [onChange, value?.full]);

  // Handle keyboard navigation
  const handleKeyDown = useCallback((e: React.KeyboardEvent) => {
    if (!showSuggestions || suggestions.length === 0) return;

    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault();
        setSelectedIndex(prev => 
          prev < suggestions.length - 1 ? prev + 1 : 0
        );
        break;
      case 'ArrowUp':
        e.preventDefault();
        setSelectedIndex(prev => 
          prev > 0 ? prev - 1 : suggestions.length - 1
        );
        break;
      case 'Enter':
        e.preventDefault();
        if (selectedIndex >= 0) {
          selectSuggestion(suggestions[selectedIndex]);
        }
        break;
      case 'Escape':
        setShowSuggestions(false);
        setSelectedIndex(-1);
        break;
    }
  }, [showSuggestions, suggestions, selectedIndex, selectSuggestion]);

  // Clear address
  const handleClear = useCallback(() => {
    setInputValue('');
    setSuggestions([]);
    setShowSuggestions(false);
    onChange(null);
    
    // Focus input without causing scroll
    if (inputRef.current) {
      inputRef.current.focus({ preventScroll: true });
    }
  }, [onChange]);

  // Click outside to close dropdown - use mousedown to avoid interfering with onClick
  useEffect(() => {
    if (!showSuggestions) {
      return;
    }

    const handleMouseDownOutside = (event: MouseEvent) => {
      const target = event.target as Node;
      if (
        (dropdownRef.current && dropdownRef.current.contains(target)) ||
        (inputRef.current && inputRef.current.contains(target))
      ) {
        return;
      }
      setShowSuggestions(false);
    };

    const reposition = () => {
      const rect = inputRef.current?.getBoundingClientRect();
      if (rect) {
        setDropdownStyle({
          top: Math.round(rect.top + rect.height + 8),
          left: Math.round(rect.left),
          width: Math.round(rect.width),
        });
      }
    };

    reposition();
    document.addEventListener('mousedown', handleMouseDownOutside);
    window.addEventListener('resize', reposition);

    return () => {
      document.removeEventListener('mousedown', handleMouseDownOutside);
      window.removeEventListener('resize', reposition);
    };
  }, [showSuggestions]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (abortControllerRef.current) {
        abortControllerRef.current.abort();
      }
    };
  }, []);

  // Helper function to highlight matched text
  const highlightMatch = (text: string, query: string) => {
    if (!query || query.length < 2) return text;
    
    const regex = new RegExp(`(${query.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')})`, 'gi');
    const parts = text.split(regex);
    
    return (
      <>
        {parts.map((part, index) => 
          regex.test(part) ? (
            <Text as="span" key={index} fontWeight="bold" color="blue.600">
              {part}
            </Text>
          ) : (
            part
          )
        )}
      </>
    );
  };

  return (
    <Box position="relative" w="full" overflow="visible">
      <VStack align="stretch" spacing={3}>
        {/* Label */}
        <Text fontSize="sm" fontWeight="semibold" color="white" mb={1}>
          {label} {isRequired && <Text as="span" color="red.400">*</Text>}
        </Text>
        
        {/* Clean Input Field - No Icons */}
        <Box position="relative" overflow="visible">
          <InputGroup size={size}>
            <Input
              ref={inputRef}
              id={id}
              value={inputValue}
              onChange={handleInputChange}
              onKeyDown={handleKeyDown}
              placeholder={placeholder}
              pl="1rem"
              pr={value || isLoading ? "2.5rem" : "1rem"}
              bg="rgba(255, 255, 255, 0.05)"
              border="1px solid"
              borderColor={value ? "green.400" : "rgba(255, 255, 255, 0.1)"}
              borderRadius="xl"
              color="white"
              fontSize="sm"
              fontWeight="medium"
              _placeholder={{
                color: "rgba(255, 255, 255, 0.6)",
                fontSize: "sm"
              }}
              _hover={{
                borderColor: value ? "green.300" : "rgba(255, 255, 255, 0.2)",
                bg: "rgba(255, 255, 255, 0.08)"
              }}
              _focus={{
                borderColor: value ? "green.400" : "blue.400",
                bg: "rgba(255, 255, 255, 0.1)",
                boxShadow: "0 0 0 3px rgba(66, 153, 225, 0.1)"
              }}
              transition="all 0.2s"
            />
            
            <InputRightElement>
              {isLoading ? (
                <Spinner size="sm" color="blue.400" thickness="2px" />
              ) : value ? (
                <IconButton
                  aria-label="Clear address"
                  icon={<CloseIcon />}
                  size="xs"
                  variant="ghost"
                  color="gray.400"
                  _hover={{ color: "white", bg: "rgba(255, 255, 255, 0.1)" }}
                  onClick={handleClear}
                />
              ) : null}
            </InputRightElement>
          </InputGroup>
          
          {/* Helper Text */}
          {helperText && (
            <Text fontSize="xs" color="rgba(255, 255, 255, 0.7)" mt={2}>
              {helperText}
            </Text>
          )}
        </Box>

        {/* API Error Alert */}
        {apiError && (
          <Fade in={true}>
            <Alert 
              status="error" 
              size="sm" 
              borderRadius="lg"
              bg="rgba(245, 101, 101, 0.1)"
              border="1px solid rgba(245, 101, 101, 0.2)"
            >
              <AlertIcon color="red.400" />
              <Text fontSize="sm" color="red.300">{apiError}</Text>
            </Alert>
          </Fade>
        )}

        {/* Premium Suggestions Dropdown */}
        {showSuggestions && suggestions.length > 0 && (
          <Portal>
            <Box
              ref={dropdownRef}
              position="fixed"
              top={`${dropdownStyle.top}px`}
              left={`${dropdownStyle.left}px`}
              width={`${dropdownStyle.width}px`}
              zIndex={1400}
              bg="rgba(26, 32, 44, 0.98)"
              backdropFilter="blur(10px)"
              border="1px solid rgba(255, 255, 255, 0.1)"
              borderRadius="xl"
              boxShadow="0 20px 25px -5px rgba(0, 0, 0, 0.3), 0 10px 10px -5px rgba(0, 0, 0, 0.2)"
              maxH="320px"
              overflowY="auto"
              py={2}
              pointerEvents={isSelectingRef.current ? "none" : "auto"}
              css={{
                '&::-webkit-scrollbar': {
                  width: '6px',
                },
                '&::-webkit-scrollbar-track': {
                  background: 'rgba(255, 255, 255, 0.05)',
                  borderRadius: '3px',
                },
                '&::-webkit-scrollbar-thumb': {
                  background: 'rgba(255, 255, 255, 0.2)',
                  borderRadius: '3px',
                },
                WebkitOverflowScrolling: 'touch',
                willChange: 'transform',
                transform: 'translateZ(0)',
              }}
            >
              {suggestions.map((suggestion, index) => (
                <Box
                  key={suggestion.id}
                  px={4}
                  py={3}
                  mx={2}
                  cursor="pointer"
                  borderRadius="lg"
                  bg={selectedIndex === index ? "rgba(66, 153, 225, 0.15)" : "transparent"}
                  border={selectedIndex === index ? "1px solid rgba(66, 153, 225, 0.3)" : "1px solid transparent"}
                  _hover={{ 
                    bg: "rgba(66, 153, 225, 0.1)",
                    borderColor: "rgba(66, 153, 225, 0.2)"
                  }}
                  transition="all 0.2s"
                  onClick={(e) => {
                    e.stopPropagation();
                    console.log('🖱️ onClick fired for suggestion:', suggestion.displayText);
                    selectSuggestion(suggestion);
                  }}
                >
                  <HStack align="start" spacing={3}>
                    <Icon 
                      as={FaMapMarkerAlt} 
                      color="blue.400" 
                      boxSize={4} 
                      mt={0.5}
                      opacity={0.8}
                    />
                    
                    <VStack align="start" spacing={1} flex={1} minW={0}>
                      <Text 
                        fontSize="sm" 
                        fontWeight="semibold" 
                        color="white"
                        lineHeight="1.35"
                        whiteSpace="normal"
                        wordBreak="break-word"
                      >
                        {highlightMatch(suggestion.mainText || suggestion.displayText, inputValue)}
                      </Text>
                      
                      {suggestion.secondaryText && (
                        <Text 
                          fontSize="xs" 
                          color="rgba(255, 255, 255, 0.8)"
                          lineHeight="1.25"
                          whiteSpace="normal"
                          wordBreak="break-word"
                        >
                          {suggestion.secondaryText}
                        </Text>
                      )}
                    </VStack>
                    
                    {/* Confidence indicator */}
                    {suggestion.confidence && suggestion.confidence > 0.9 && (
                      <Box
                        w={2}
                        h={2}
                        bg="green.400"
                        borderRadius="full"
                        mt={1.5}
                        opacity={0.8}
                      />
                    )}
                  </HStack>
                </Box>
              ))}
              
              {/* Powered by footer */}
              <Box
                px={4}
                py={2}
                mt={2}
                borderTop="1px solid rgba(255, 255, 255, 0.05)"
              >
                <HStack justify="space-between" align="center">
                  <Text fontSize="10px" color="rgba(255, 255, 255, 0.4)" fontWeight="medium">
                    Powered by {currentProvider === 'google' ? 'Google Places' : 'Mapbox'}
                  </Text>
                  <Text fontSize="10px" color="rgba(255, 255, 255, 0.3)">
                    {suggestions.length} result{suggestions.length !== 1 ? 's' : ''}
                  </Text>
                </HStack>
              </Box>
            </Box>
          </Portal>
        )}
        
        {/* No results message */}
        {showSuggestions && suggestions.length === 0 && !isLoading && inputValue.length >= 2 && (
          <Fade in={true}>
            <Portal>
            <Box
              position="fixed"
              top={`${dropdownStyle.top}px`}
              left={`${dropdownStyle.left}px`}
              width={`${dropdownStyle.width}px`}
              zIndex={1400}
              bg="rgba(26, 32, 44, 0.98)"
              backdropFilter="blur(10px)"
              border="1px solid rgba(255, 255, 255, 0.1)"
              borderRadius="xl"
              boxShadow="0 20px 25px -5px rgba(0, 0, 0, 0.3)"
              p={4}
            >
              <VStack spacing={2}>
                <Icon as={Search2Icon} color="gray.500" boxSize={5} />
                <Text fontSize="sm" color="rgba(255, 255, 255, 0.7)" textAlign="center">
                  No verified addresses found. Please check the address or try a nearby postcode.
                </Text>
              </VStack>
            </Box>
            </Portal>
          </Fade>
        )}

        {/* Additional Address Details - Only show when address is selected */}
        {value && (
          <Fade in={true}>
            <VStack align="stretch" spacing={4} mt={4} position="relative" zIndex={1}>
              <Text fontSize="sm" fontWeight="semibold" color="white">
                Additional Details (Optional)
              </Text>
              

      {/* Floor and Flat Numbers */}
              <SimpleGrid columns={2} spacing={3}>
                <Box>
                  <FormLabel fontSize="xs" color="#ffffff" mb={1}>
                    Floor Number
                  </FormLabel>
                  <Input
                    value={floorNumber}
                    onChange={(e) => {
                      const inputValue = e.target.value;
                      setFloorNumber(inputValue);
                      if (value) {
                        const updatedAddress = {
                          ...value,
                          formatted: {
                            ...value.formatted,
                            floor: inputValue
                          },
                          buildingDetails: {
                            ...value.buildingDetails,
                            floorNumber: inputValue
                          }
                        };
                        onChange(updatedAddress);
                      }
                    }}
                    placeholder="e.g., Ground, 1, 2..."
                    size="sm"
                    bg="white"
                    borderRadius="lg"
                    color="black"
                    fontWeight="600"
                    border="1px solid rgba(203, 213, 225, 0.8)"
                    _hover={{
                      borderColor: "rgba(59, 130, 246, 0.6)",
                    }}
                    _focus={{
                      borderColor: "rgba(59, 130, 246, 0.9)",
                      boxShadow: "0 0 0 3px rgba(59, 130, 246, 0.2)",
                      outline: "none",
                    }}
                  />
                </Box>

                <Box>
                  <FormLabel fontSize="xs" color="#ffffff" mb={1}>
                    Flat Number
                  </FormLabel>
                  <Input
                    value={apartmentNumber}
                    onChange={(e) => {
                      const inputValue = e.target.value;
                      setApartmentNumber(inputValue);
                      if (value) {
                        const line2Value = inputValue ? `Flat ${inputValue}` : '';
                        const updatedAddress = {
                          ...value,
                          line2: line2Value,
                          formatted: {
                            ...value.formatted,
                            flatNumber: inputValue
                          },
                          buildingDetails: {
                            ...value.buildingDetails,
                            apartmentNumber: inputValue
                          }
                        };
                        onChange(updatedAddress);
                      }
                    }}
                    placeholder="e.g., 1A, 2B, 10..."
                    size="sm"
                    bg="white"
                    borderRadius="lg"
                    color="black"
                    fontWeight="600"
                    border="1px solid rgba(203, 213, 225, 0.8)"
                    _hover={{
                      borderColor: "rgba(59, 130, 246, 0.6)",
                    }}
                    _focus={{
                      borderColor: "rgba(59, 130, 246, 0.9)",
                      boxShadow: "0 0 0 3px rgba(59, 130, 246, 0.2)",
                      outline: "none",
                    }}
                  />
                </Box>
              </SimpleGrid>

              {/* Lift Toggle */}
              <HStack justify="space-between" align="center">
                <Box>
                  <Text fontSize="sm" color="white" fontWeight="medium">
                    Lift Available
                  </Text>
                  <Text fontSize="xs" color="rgba(255, 255, 255, 0.7)">
                    Is there a lift in the building?
                  </Text>
                </Box>
                <Switch
                  isChecked={hasElevator}
                  onChange={(e) => {
                    setHasElevator(e.target.checked);
                    // Update address immediately
                    if (value) {
                      const updatedAddress = {
                        ...value,
                        buildingDetails: {
                          ...value.buildingDetails,
                          hasElevator: e.target.checked
                        }
                      };
                      onChange(updatedAddress);
                    }
                  }}
                  colorScheme="blue"
                  size="md"
                />
              </HStack>
            </VStack>
          </Fade>
        )}
      </VStack>
    </Box>
  );
};

'use client';

import { useState, useEffect, useRef } from 'react';
import {
  Modal,
  ModalOverlay,
  ModalContent,
  ModalBody,
  Input,
  VStack,
  HStack,
  Text,
  Box,
  Icon,
  Badge,
  Spinner,
  useToast,
  Kbd,
} from '@chakra-ui/react';
import { FiCommand, FiSearch, FiZap, FiAlertTriangle, FiCheckCircle } from 'react-icons/fi';
import { ConfirmationModal } from './ConfirmationModal';

interface CommandSuggestion {
  id: string;
  text: string;
  description: string;
  category: 'orders' | 'drivers' | 'finance' | 'analytics';
  riskLevel: 'low' | 'medium' | 'high';
  shortcut?: string;
}

interface AICommandPaletteProps {
  isOpen: boolean;
  onClose: () => void;
}

const COMMAND_SUGGESTIONS: CommandSuggestion[] = [
  {
    id: 'unassigned_orders',
    text: 'عرض الطلبات غير المعينة',
    description: 'Get all orders without assigned drivers',
    category: 'orders',
    riskLevel: 'low',
  },
  {
    id: 'available_drivers',
    text: 'الحصول على السائقين المتاحين',
    description: 'List all drivers currently available',
    category: 'drivers',
    riskLevel: 'low',
  },
  {
    id: 'daily_summary',
    text: 'ملخص اليوم',
    description: 'Get comprehensive daily operations summary',
    category: 'analytics',
    riskLevel: 'low',
  },
  {
    id: 'revenue_report',
    text: 'تقرير الإيرادات لهذا الشهر',
    description: 'Generate revenue report for current month',
    category: 'finance',
    riskLevel: 'low',
  },
  {
    id: 'kpis',
    text: 'مؤشرات الأداء الرئيسية',
    description: 'View key performance indicators',
    category: 'analytics',
    riskLevel: 'low',
  },
  {
    id: 'driver_performance',
    text: 'تحليل أداء السائقين',
    description: 'Analyze driver performance metrics',
    category: 'drivers',
    riskLevel: 'low',
  },
  {
    id: 'outstanding_payments',
    text: 'المدفوعات المعلقة',
    description: 'Show orders with outstanding payments',
    category: 'finance',
    riskLevel: 'low',
  },
  {
    id: 'order_trends',
    text: 'اتجاهات الطلبات',
    description: 'Analyze order patterns and trends',
    category: 'analytics',
    riskLevel: 'low',
  },
];

export function AICommandPalette({ isOpen, onClose }: AICommandPaletteProps) {
  const [query, setQuery] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [selectedIndex, setSelectedIndex] = useState(0);
  const [suggestions, setSuggestions] = useState<CommandSuggestion[]>(COMMAND_SUGGESTIONS);
  const [pendingPlan, setPendingPlan] = useState<any>(null);
  const [showConfirmation, setShowConfirmation] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);
  const toast = useToast();

  // Focus input when opened
  useEffect(() => {
    if (isOpen && inputRef.current) {
      inputRef.current.focus();
    }
  }, [isOpen]);

  // Filter suggestions based on query
  useEffect(() => {
    if (query.trim() === '') {
      setSuggestions(COMMAND_SUGGESTIONS);
      setSelectedIndex(0);
      return;
    }

    const filtered = COMMAND_SUGGESTIONS.filter(
      cmd =>
        cmd.text.toLowerCase().includes(query.toLowerCase()) ||
        cmd.description.toLowerCase().includes(query.toLowerCase())
    );

    setSuggestions(filtered);
    setSelectedIndex(0);
  }, [query]);

  // Handle keyboard navigation
  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      setSelectedIndex(prev => (prev + 1) % suggestions.length);
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setSelectedIndex(prev => (prev - 1 + suggestions.length) % suggestions.length);
    } else if (e.key === 'Enter') {
      e.preventDefault();
      if (suggestions[selectedIndex]) {
        executeCommand(suggestions[selectedIndex].text);
      } else if (query.trim()) {
        executeCommand(query);
      }
    } else if (e.key === 'Escape') {
      onClose();
    }
  };

  const executeCommand = async (command: string) => {
    setIsLoading(true);

    try {
      const response = await fetch('/api/admin/ai-assistant/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          message: command,
          autoExecute: false, // Changed to false to always get plan first
        }),
      });

      const data = await response.json();

      if (data.requiresConfirmation) {
        // Show confirmation modal
        setPendingPlan({
          ...data.plan,
          originalCommand: command,
        });
        setShowConfirmation(true);
        setIsLoading(false);
        return;
      }

      if (data.success) {
        toast({
          title: 'نجح التنفيذ',
          description: data.message || data.summary,
          status: 'success',
          duration: 5000,
          isClosable: true,
        });

        // Emit custom event with results
        window.dispatchEvent(
          new CustomEvent('ai-command-executed', {
            detail: { command, results: data.results },
          })
        );

        onClose();
      } else {
        toast({
          title: 'فشل التنفيذ',
          description: data.message || 'حدث خطأ أثناء تنفيذ الأمر',
          status: 'error',
          duration: 5000,
          isClosable: true,
        });
      }
    } catch (error) {
      console.error('Command execution error:', error);
      toast({
        title: 'خطأ',
        description: 'فشل الاتصال بالخادم',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setIsLoading(false);
    }
  };

  const handleConfirm = async (otp?: string) => {
    setShowConfirmation(false);
    setIsLoading(true);

    try {
      const response = await fetch('/api/admin/ai-assistant/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          message: pendingPlan.originalCommand,
          autoExecute: true,
          otp,
        }),
      });

      const data = await response.json();

      if (data.success) {
        toast({
          title: 'نجح التنفيذ',
          description: data.message || data.summary,
          status: 'success',
          duration: 5000,
          isClosable: true,
        });

        window.dispatchEvent(
          new CustomEvent('ai-command-executed', {
            detail: { command: pendingPlan.originalCommand, results: data.results },
          })
        );

        onClose();
      } else {
        toast({
          title: 'فشل التنفيذ',
          description: data.message || 'حدث خطأ أثناء تنفيذ الأمر',
          status: 'error',
          duration: 5000,
          isClosable: true,
        });
      }
    } catch (error) {
      console.error('Command execution error:', error);
      toast({
        title: 'خطأ',
        description: 'فشل الاتصال بالخادم',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setIsLoading(false);
      setPendingPlan(null);
    }
  };

  const getRiskBadge = (riskLevel: string) => {
    switch (riskLevel) {
      case 'high':
        return <Badge colorScheme="red">عالي</Badge>;
      case 'medium':
        return <Badge colorScheme="orange">متوسط</Badge>;
      case 'low':
        return <Badge colorScheme="green">منخفض</Badge>;
      default:
        return null;
    }
  };

  const getCategoryColor = (category: string) => {
    switch (category) {
      case 'orders':
        return 'blue.500';
      case 'drivers':
        return 'purple.500';
      case 'finance':
        return 'green.500';
      case 'analytics':
        return 'orange.500';
      default:
        return 'gray.500';
    }
  };

  return (
    <>
      <Modal isOpen={isOpen} onClose={onClose} size="2xl">
        <ModalOverlay bg="blackAlpha.700" backdropFilter="blur(10px)" />
      <ModalContent
        bg="white"
        borderRadius="xl"
        boxShadow="2xl"
        mt="20vh"
        dir="rtl"
      >
        <ModalBody p={0}>
          <VStack spacing={0} align="stretch">
            {/* Search Input */}
            <HStack
              p={4}
              borderBottom="1px solid"
              borderColor="gray.200"
              spacing={3}
            >
              <Icon as={FiCommand} color="purple.500" boxSize={5} />
              <Input
                ref={inputRef}
                placeholder="اكتب أمرك بلغة طبيعية..."
                value={query}
                onChange={e => setQuery(e.target.value)}
                onKeyDown={handleKeyDown}
                variant="unstyled"
                fontSize="lg"
                disabled={isLoading}
              />
              {isLoading && <Spinner size="sm" color="purple.500" />}
              <HStack spacing={1}>
                <Kbd>Esc</Kbd>
                <Text fontSize="xs" color="gray.500">
                  إلغاء
                </Text>
              </HStack>
            </HStack>

            {/* Suggestions List */}
            <VStack
              spacing={0}
              align="stretch"
              maxH="60vh"
              overflowY="auto"
              py={2}
            >
              {suggestions.length === 0 && (
                <Box p={8} textAlign="center">
                  <Icon as={FiSearch} boxSize={10} color="gray.400" mb={2} />
                  <Text color="gray.500">
                    {query
                      ? 'لم يتم العثور على نتائج. اضغط Enter لتنفيذ الأمر مباشرة.'
                      : 'ابدأ بكتابة أمرك...'}
                  </Text>
                </Box>
              )}

              {suggestions.map((suggestion, index) => (
                <HStack
                  key={suggestion.id}
                  p={3}
                  px={4}
                  spacing={3}
                  cursor="pointer"
                  bg={index === selectedIndex ? 'purple.50' : 'transparent'}
                  borderRight={
                    index === selectedIndex ? '3px solid' : 'none'
                  }
                  borderColor="purple.500"
                  _hover={{ bg: 'gray.50' }}
                  onClick={() => executeCommand(suggestion.text)}
                  transition="all 0.2s"
                >
                  <Icon
                    as={
                      suggestion.riskLevel === 'high'
                        ? FiAlertTriangle
                        : suggestion.riskLevel === 'medium'
                        ? FiZap
                        : FiCheckCircle
                    }
                    color={getCategoryColor(suggestion.category)}
                    boxSize={5}
                  />
                  <VStack align="start" flex={1} spacing={0}>
                    <Text fontWeight="medium" fontSize="md">
                      {suggestion.text}
                    </Text>
                    <Text fontSize="sm" color="gray.600">
                      {suggestion.description}
                    </Text>
                  </VStack>
                  <HStack spacing={2}>
                    {getRiskBadge(suggestion.riskLevel)}
                    {suggestion.shortcut && <Kbd>{suggestion.shortcut}</Kbd>}
                  </HStack>
                </HStack>
              ))}
            </VStack>

            {/* Footer */}
            <HStack
              p={3}
              px={4}
              borderTop="1px solid"
              borderColor="gray.200"
              justify="space-between"
              bg="gray.50"
              fontSize="xs"
              color="gray.600"
            >
              <HStack spacing={4}>
                <HStack>
                  <Kbd>↑↓</Kbd>
                  <Text>التنقل</Text>
                </HStack>
                <HStack>
                  <Kbd>Enter</Kbd>
                  <Text>تنفيذ</Text>
                </HStack>
              </HStack>
              <Text>
                مدعوم بالذكاء الاصطناعي <Icon as={FiZap} />
              </Text>
            </HStack>
          </VStack>
        </ModalBody>
      </ModalContent>
    </Modal>

      {/* Confirmation Modal */}
      {pendingPlan && (
        <ConfirmationModal
          isOpen={showConfirmation}
          onClose={() => {
            setShowConfirmation(false);
            setPendingPlan(null);
          }}
          onConfirm={handleConfirm}
          plan={pendingPlan}
          confirmationType={
            pendingPlan.riskLevel === 'high' ? 'dual' : 'single'
          }
        />
      )}
    </>
  );
}

// Hook to open command palette with Cmd+K or Ctrl+K
export function useCommandPalette() {
  const [isOpen, setIsOpen] = useState(false);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
        e.preventDefault();
        setIsOpen(prev => !prev);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, []);

  return {
    isOpen,
    onOpen: () => setIsOpen(true),
    onClose: () => setIsOpen(false),
  };
}

'use client';

import { useState, useEffect } from 'react';
import {
  Box,
  VStack,
  HStack,
  Text,
  Grid,
  GridItem,
  Card,
  CardBody,
  Stat,
  StatLabel,
  StatNumber,
  StatHelpText,
  StatArrow,
  Icon,
  Badge,
  Button,
  Spinner,
  useToast,
} from '@chakra-ui/react';
import {
  FiTrendingUp,
  FiTrendingDown,
  FiDollarSign,
  FiPackage,
  FiUsers,
  FiTruck,
  FiAlertCircle,
  FiCheckCircle,
} from 'react-icons/fi';
import { AICommandPalette, useCommandPalette } from './AICommandPalette';

interface DashboardMetrics {
  orders: {
    total: number;
    completed: number;
    pending: number;
    growth: number;
  };
  revenue: {
    total: number;
    growth: number;
  };
  drivers: {
    active: number;
    available: number;
  };
  customers: {
    new: number;
    total: number;
  };
}

interface AIInsight {
  id: string;
  type: 'warning' | 'success' | 'info';
  title: string;
  description: string;
  action?: {
    label: string;
    command: string;
  };
}

export function AdaptiveDashboard() {
  const [metrics, setMetrics] = useState<DashboardMetrics | null>(null);
  const [insights, setInsights] = useState<AIInsight[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const { isOpen, onOpen, onClose } = useCommandPalette();
  const toast = useToast();

  useEffect(() => {
    loadDashboardData();

    // Listen for AI command execution
    const handleAICommand = (event: CustomEvent) => {
      loadDashboardData(); // Refresh dashboard after AI action
    };

    window.addEventListener('ai-command-executed', handleAICommand as EventListener);

    // Auto-refresh every 30 seconds
    const interval = setInterval(loadDashboardData, 30000);

    return () => {
      window.removeEventListener('ai-command-executed', handleAICommand as EventListener);
      clearInterval(interval);
    };
  }, []);

  const loadDashboardData = async () => {
    try {
      // Load KPIs
      const kpiResponse = await fetch('/api/admin/ai-assistant/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          message: 'get kpis with comparison',
          autoExecute: true,
        }),
      });

      const kpiData = await kpiResponse.json();

      if (kpiData.success && kpiData.results && kpiData.results[0]?.data) {
        const data = kpiData.results[0].data;
        const metrics = data.metrics;
        const comparison = data.comparison || {};

        setMetrics({
          orders: {
            total: metrics.totalOrders || 0,
            completed: metrics.completedOrders || 0,
            pending: metrics.totalOrders - metrics.completedOrders || 0,
            growth: comparison.ordersGrowth || 0,
          },
          revenue: {
            total: metrics.revenue || 0,
            growth: comparison.revenueGrowth || 0,
          },
          drivers: {
            active: metrics.activeDrivers || 0,
            available: metrics.activeDrivers || 0,
          },
          customers: {
            new: metrics.newCustomers || 0,
            total: metrics.newCustomers || 0,
          },
        });

        // Generate AI insights
        const newInsights: AIInsight[] = [];

        if (comparison.ordersGrowth && comparison.ordersGrowth < -10) {
          newInsights.push({
            id: 'orders_decline',
            type: 'warning',
            title: 'انخفاض في الطلبات',
            description: `انخفضت الطلبات بنسبة ${Math.abs(comparison.ordersGrowth).toFixed(1)}% مقارنة بالفترة السابقة`,
            action: {
              label: 'تحليل الاتجاهات',
              command: 'get order trends',
            },
          });
        }

        if (metrics.activeDrivers < 5) {
          newInsights.push({
            id: 'low_drivers',
            type: 'warning',
            title: 'عدد قليل من السائقين',
            description: `فقط ${metrics.activeDrivers} سائقين نشطين حالياً`,
            action: {
              label: 'عرض السائقين',
              command: 'get available drivers',
            },
          });
        }

        if (metrics.completionRate > 90) {
          newInsights.push({
            id: 'high_completion',
            type: 'success',
            title: 'معدل إنجاز ممتاز',
            description: `معدل إنجاز الطلبات ${metrics.completionRate.toFixed(1)}%`,
          });
        }

        if (comparison.revenueGrowth && comparison.revenueGrowth > 15) {
          newInsights.push({
            id: 'revenue_growth',
            type: 'success',
            title: 'نمو قوي في الإيرادات',
            description: `زيادة في الإيرادات بنسبة ${comparison.revenueGrowth.toFixed(1)}%`,
          });
        }

        setInsights(newInsights);
      }
    } catch (error) {
      console.error('Failed to load dashboard data:', error);
    } finally {
      setIsLoading(false);
    }
  };

  const executeCommand = async (command: string) => {
    try {
      const response = await fetch('/api/admin/ai-assistant/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          message: command,
          autoExecute: true,
        }),
      });

      const data = await response.json();

      if (data.success) {
        toast({
          title: 'نجح التنفيذ',
          status: 'success',
          duration: 3000,
        });
      }
    } catch (error) {
      toast({
        title: 'فشل التنفيذ',
        status: 'error',
        duration: 3000,
      });
    }
  };

  if (isLoading) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" h="400px">
        <Spinner size="xl" color="purple.500" />
      </Box>
    );
  }

  return (
    <>
      <VStack spacing={6} align="stretch" dir="rtl">
        {/* AI Command Button */}
        <HStack justify="space-between">
          <Box>
            <Text fontSize="2xl" fontWeight="bold">
              لوحة التحكم الذكية
            </Text>
            <Text color="gray.600">مدعومة بالذكاء الاصطناعي</Text>
          </Box>
          <Button
            leftIcon={<Icon as={FiTrendingUp} />}
            colorScheme="purple"
            onClick={onOpen}
            size="lg"
          >
            افتح مساعد الذكاء الاصطناعي (Ctrl+K)
          </Button>
        </HStack>

        {/* AI Insights */}
        {insights.length > 0 && (
          <Grid templateColumns="repeat(auto-fit, minmax(300px, 1fr))" gap={4}>
            {insights.map(insight => (
              <Card
                key={insight.id}
                bg={
                  insight.type === 'warning'
                    ? 'orange.50'
                    : insight.type === 'success'
                    ? 'green.50'
                    : 'blue.50'
                }
                borderRight="4px solid"
                borderColor={
                  insight.type === 'warning'
                    ? 'orange.500'
                    : insight.type === 'success'
                    ? 'green.500'
                    : 'blue.500'
                }
              >
                <CardBody>
                  <VStack align="start" spacing={2}>
                    <HStack>
                      <Icon
                        as={
                          insight.type === 'warning'
                            ? FiAlertCircle
                            : FiCheckCircle
                        }
                        color={
                          insight.type === 'warning'
                            ? 'orange.500'
                            : insight.type === 'success'
                            ? 'green.500'
                            : 'blue.500'
                        }
                      />
                      <Text fontWeight="bold">{insight.title}</Text>
                    </HStack>
                    <Text fontSize="sm" color="gray.600">
                      {insight.description}
                    </Text>
                    {insight.action && (
                      <Button
                        size="sm"
                        variant="outline"
                        onClick={() => executeCommand(insight.action!.command)}
                      >
                        {insight.action.label}
                      </Button>
                    )}
                  </VStack>
                </CardBody>
              </Card>
            ))}
          </Grid>
        )}

        {/* Metrics Grid */}
        <Grid templateColumns="repeat(auto-fit, minmax(250px, 1fr))" gap={6}>
          {/* Orders */}
          <Card>
            <CardBody>
              <Stat>
                <StatLabel>إجمالي الطلبات</StatLabel>
                <StatNumber>
                  <HStack>
                    <Icon as={FiPackage} color="blue.500" />
                    <Text>{metrics?.orders.total || 0}</Text>
                  </HStack>
                </StatNumber>
                <StatHelpText>
                  <StatArrow
                    type={
                      metrics && metrics.orders.growth >= 0 ? 'increase' : 'decrease'
                    }
                  />
                  {Math.abs(metrics?.orders.growth || 0).toFixed(1)}%
                </StatHelpText>
              </Stat>
              <HStack mt={4} spacing={3}>
                <Badge colorScheme="green">
                  مكتمل: {metrics?.orders.completed || 0}
                </Badge>
                <Badge colorScheme="orange">
                  معلق: {metrics?.orders.pending || 0}
                </Badge>
              </HStack>
            </CardBody>
          </Card>

          {/* Revenue */}
          <Card>
            <CardBody>
              <Stat>
                <StatLabel>الإيرادات</StatLabel>
                <StatNumber>
                  <HStack>
                    <Icon as={FiDollarSign} color="green.500" />
                    <Text>{metrics?.revenue.total.toFixed(2) || 0} ر.س</Text>
                  </HStack>
                </StatNumber>
                <StatHelpText>
                  <StatArrow
                    type={
                      metrics && metrics.revenue.growth >= 0 ? 'increase' : 'decrease'
                    }
                  />
                  {Math.abs(metrics?.revenue.growth || 0).toFixed(1)}%
                </StatHelpText>
              </Stat>
            </CardBody>
          </Card>

          {/* Drivers */}
          <Card>
            <CardBody>
              <Stat>
                <StatLabel>السائقون النشطون</StatLabel>
                <StatNumber>
                  <HStack>
                    <Icon as={FiTruck} color="purple.500" />
                    <Text>{metrics?.drivers.active || 0}</Text>
                  </HStack>
                </StatNumber>
                <StatHelpText>
                  متاح: {metrics?.drivers.available || 0}
                </StatHelpText>
              </Stat>
            </CardBody>
          </Card>

          {/* Customers */}
          <Card>
            <CardBody>
              <Stat>
                <StatLabel>عملاء جدد</StatLabel>
                <StatNumber>
                  <HStack>
                    <Icon as={FiUsers} color="orange.500" />
                    <Text>{metrics?.customers.new || 0}</Text>
                  </HStack>
                </StatNumber>
                <StatHelpText>هذا الشهر</StatHelpText>
              </Stat>
            </CardBody>
          </Card>
        </Grid>
      </VStack>

      {/* AI Command Palette */}
      <AICommandPalette isOpen={isOpen} onClose={onClose} />
    </>
  );
}

'use client';

import React, { useEffect, useMemo, useRef, useState } from 'react';
import {
  Box,
  Grid,
  GridItem,
  VStack,
  HStack,
  Text,
  Button,
  IconButton,
  Input,
  Textarea,
  Badge,
  Avatar,
  Divider,
  Select,
  useToast,
  Tag,
  TagLabel,
  TagLeftIcon,
  Tooltip,
  Progress,
  Modal,
  ModalOverlay,
  ModalContent,
  ModalHeader,
  ModalBody,
  ModalCloseButton,
  ModalFooter,
  FormControl,
  FormLabel,
  RadioGroup,
  Radio,
  Stack,
} from '@chakra-ui/react';
import { 
  FiX, 
  FiSend, 
  FiPlus, 
  FiZap, 
  FiDownload, 
  FiBarChart2, 
  FiClock, 
  FiRefreshCw, 
  FiMic, 
  FiMicOff,
  FiVolume2,
  FiVolumeX,
  FiSettings,
  FiImage,
  FiMaximize2,
  FiDownloadCloud,
  FiCopy,
  FiCheck,
} from 'react-icons/fi';

type Lang = 'en' | 'ar';

interface Message {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  ts: Date;
  audioUrl?: string; // For voice messages
  isTranscribed?: boolean; // Was this transcribed from audio?
  imageUrl?: string; // For generated images
  imageMetadata?: {
    prompt: string;
    revisedPrompt?: string;
    model: string;
    size: string;
    quality: string;
  };
}

interface AssistantMetadata {
  requestId: string;
  processingTimeMs?: number;
  references?: { orders: string[]; routes: string[] };
  liveStats?: any;
  driverAvailability?: any;
  predictiveAnalytics?: any;
  proactiveSuggestions?: { suggestions: string[]; isClear?: boolean };
}

export default function AdminAIOverlay({
  adminName = 'Admin',
  adminEmail = '',
}: {
  adminName?: string;
  adminEmail?: string;
}) {
  const [open, setOpen] = useState(false);
  const [lang, setLang] = useState<Lang>('en');
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [messages, setMessages] = useState<Message[]>([]);
  const [metadata, setMetadata] = useState<AssistantMetadata | null>(null);
  const [liveLane, setLiveLane] = useState<Array<{ id: string; title: string; createdAt: string }>>([]);
  const [history, setHistory] = useState<Array<{ id: string; title: string; createdAt: string }>>([]);
  const [isRecording, setIsRecording] = useState(false);
  const [mediaRecorder, setMediaRecorder] = useState<MediaRecorder | null>(null);
  const [ttsVoice, setTtsVoice] = useState<'alloy' | 'echo' | 'fable' | 'onyx' | 'nova' | 'shimmer'>('nova'); // Default female
  const [playingAudio, setPlayingAudio] = useState<string | null>(null);
  const [audioRefs, setAudioRefs] = useState<Map<string, HTMLAudioElement>>(new Map());
  const [copiedMessageId, setCopiedMessageId] = useState<string | null>(null);
  
  // Image generation states
  const [aiSettingsOpen, setAiSettingsOpen] = useState(false);
  const [imageModel, setImageModel] = useState<'dall-e-3' | 'dall-e-2'>('dall-e-3');
  const [imageSize, setImageSize] = useState<string>('1024x1024');
  const [imageQuality, setImageQuality] = useState<'standard' | 'hd'>('standard');
  const [imageSafetyMode, setImageSafetyMode] = useState<'strict' | 'moderate' | 'permissive'>('strict');
  const [imageModalOpen, setImageModalOpen] = useState(false);
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [generatingImage, setGeneratingImage] = useState(false);
  
  const endRef = useRef<HTMLDivElement>(null);
  const toast = useToast();

  useEffect(() => {
    const onOpen = () => setOpen(true);
    const onClose = () => setOpen(false);
    window.addEventListener('sv-ai-open', onOpen as EventListener);
    window.addEventListener('sv-ai-close', onClose as EventListener);
    return () => {
      window.removeEventListener('sv-ai-open', onOpen as EventListener);
      window.removeEventListener('sv-ai-close', onClose as EventListener);
    };
  }, []);

  useEffect(() => {
    endRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, loading]);

  // Live lane polling
  useEffect(() => {
    let cancelled = false;
    const load = async () => {
      try {
        const res = await fetch('/api/admin/ai/notifications');
        if (!res.ok) return;
        const data = await res.json();
        if (!cancelled) {
          const items = Array.isArray(data.items)
            ? data.items.map((x: any) => ({
                id: String(x.id || x._id || x.createdAt || Math.random()),
                title: x.title || x.message || x.text || 'Notification',
                createdAt: x.createdAt || new Date().toISOString(),
              }))
            : [];
          setLiveLane(items.slice(0, 20));
        }
      } catch {
        // ignore
      }
    };
    load();
    const t = setInterval(load, 30000);
    return () => {
      cancelled = true;
      clearInterval(t);
    };
  }, []);

  const placeholder = useMemo(
    () => (lang === 'ar' ? 'اكتب رسالتك...' : 'Type your message...'),
    [lang]
  );

  const newConversation = () => {
    setMessages([]);
    setMetadata(null);
    setInput('');
  };

  const exportTxt = () => {
    const txt = messages
      .map((m) => `[${m.ts.toLocaleString()}] ${m.role === 'user' ? adminName : 'Speedy AI'}:\n${m.content}\n`)
      .join('\n---\n\n');
    const blob = new Blob([txt], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `speedy-ai-${new Date().toISOString().slice(0, 10)}.txt`;
    a.click();
    URL.revokeObjectURL(url);
  };

  // Image Generation Function
  const generateImage = async (prompt: string) => {
    if (generatingImage || !prompt.trim()) return;
    
    setGeneratingImage(true);
    
    // Add user message
    const userMsg: Message = {
      id: String(Date.now()),
      role: 'user',
      content: `🎨 ${prompt}`,
      ts: new Date(),
    };
    
    // Add placeholder for image
    const imageId = String(Date.now() + 1);
    const imageMsg: Message = {
      id: imageId,
      role: 'assistant',
      content: lang === 'ar' ? 'جاري إنشاء الصورة...' : 'Generating image...',
      ts: new Date(),
    };
    
    setMessages((prev) => [...prev, userMsg, imageMsg]);
    
    try {
      toast({
        title: lang === 'ar' ? 'جاري إنشاء الصورة...' : 'Generating image...',
        description: lang === 'ar' ? 'قد يستغرق هذا 10-30 ثانية' : 'This may take 10-30 seconds',
        status: 'info',
        duration: 3000,
      });
      
      const res = await fetch('/api/admin/ai/generate-image', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          prompt,
          model: imageModel,
          size: imageSize,
          quality: imageQuality,
          safetyMode: imageSafetyMode,
        }),
      });
      
      if (!res.ok) {
        const error = await res.json();
        throw new Error(error.error || 'Image generation failed');
      }
      
      const data = await res.json();
      
      // Update message with generated image
      setMessages((prev) =>
        prev.map((m) =>
          m.id === imageId
            ? {
                ...m,
                content: data.revisedPrompt || prompt,
                imageUrl: data.publicUrl,
                imageMetadata: {
                  prompt,
                  revisedPrompt: data.revisedPrompt,
                  model: data.model,
                  size: data.size,
                  quality: data.quality,
                },
              }
            : m
        )
      );
      
      toast({
        title: lang === 'ar' ? 'تم إنشاء الصورة' : 'Image generated',
        description: lang === 'ar' ? 'انقر على الصورة لعرضها بالحجم الكامل' : 'Click image to view full size',
        status: 'success',
        duration: 3000,
      });
      
    } catch (error: any) {
      console.error('Image generation error:', error);
      
      setMessages((prev) =>
        prev.map((m) =>
          m.id === imageId
            ? {
                ...m,
                content: `❌ ${error.message || (lang === 'ar' ? 'فشل إنشاء الصورة' : 'Image generation failed')}`,
              }
            : m
        )
      );
      
      toast({
        title: lang === 'ar' ? 'خطأ' : 'Error',
        description: error.message || (lang === 'ar' ? 'فشل إنشاء الصورة' : 'Image generation failed'),
        status: 'error',
        duration: 5000,
      });
    } finally {
      setGeneratingImage(false);
    }
  };

  const send = async () => {
    if (loading || !input.trim()) return;
    const content = input.trim();
    setInput('');
    
    // Detect image generation commands
    const imageKeywords = [
      'generate image', 'create image', 'draw', 'picture of', 'image of',
      'generate a picture', 'create a picture', 'make an image', 'make a picture',
      'أنشئ صورة', 'ارسم', 'صورة ل', 'اصنع صورة'
    ];
    
    const isImageRequest = imageKeywords.some(keyword => 
      content.toLowerCase().includes(keyword.toLowerCase())
    );
    
    if (isImageRequest) {
      // Extract prompt (remove command keywords)
      let imagePrompt = content;
      imageKeywords.forEach(keyword => {
        const regex = new RegExp(keyword, 'gi');
        imagePrompt = imagePrompt.replace(regex, '').trim();
      });
      
      // Clean up common artifacts
      imagePrompt = imagePrompt.replace(/^(of|for|:|-)\s*/i, '').trim();
      
      if (imagePrompt.length < 10) {
        toast({
          title: lang === 'ar' ? 'وصف قصير جداً' : 'Prompt too short',
          description: lang === 'ar' ? 'يرجى تقديم وصف أطول للصورة' : 'Please provide a longer description',
          status: 'warning',
          duration: 3000,
        });
        return;
      }
      
      await generateImage(imagePrompt);
      return;
    }

    const userMsg: Message = { id: String(Date.now()), role: 'user', content, ts: new Date() };
    const streamId = String(Date.now() + 1);
    const aiMsg: Message = { id: streamId, role: 'assistant', content: '', ts: new Date() };
    setMessages((prev) => [...prev, userMsg, aiMsg]);
    setLoading(true);
    setMetadata(null);

    try {
      const res = await fetch('/api/admin/ai/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          message: content,
          conversationHistory: [...messages, userMsg].map((m) => ({
            role: m.role,
            content: m.content,
            message: m.content,
          })),
          language: lang,
          mode: 'stream',
        }),
      });
      if (!res.ok || !res.body) throw new Error('Chat API error');
      const reader = res.body.getReader();
      const decoder = new TextDecoder();
      let buffer = '';
      let aggregate = '';
      let meta: AssistantMetadata | null = null;
      let finalLang: Lang = lang;

      const apply = (content: string) => {
        setMessages((prev) => prev.map((m) => (m.id === streamId ? { ...m, content } : m)));
      };

      const handleLine = (line: string) => {
        try {
          const payload = JSON.parse(line);
          if (payload.event === 'token') {
            const token = typeof payload.data === 'string' ? payload.data : '';
            aggregate += token;
            apply(aggregate);
          } else if (payload.event === 'final') {
            const data = payload.data || {};
            if (typeof data.response === 'string') {
              aggregate = data.response;
              apply(aggregate);
            }
            if (data.language === 'en' || data.language === 'ar') {
              finalLang = data.language;
              setLang(finalLang);
            }
            if (data.metadata) {
              meta = {
                ...(data.metadata as AssistantMetadata),
                processingTimeMs:
                  typeof data.processingTimeMs === 'number'
                    ? data.processingTimeMs
                    : undefined,
              };
            }
          }
        } catch {
          // ignore malformed lines
        }
      };

      while (true) {
        const { value, done } = await reader.read();
        if (done) break;
        buffer += decoder.decode(value, { stream: true });
        let idx: number;
        while ((idx = buffer.indexOf('\n')) >= 0) {
          const line = buffer.slice(0, idx).trim();
          buffer = buffer.slice(idx + 1);
          if (line) handleLine(line);
        }
      }
      if (buffer.trim()) handleLine(buffer.trim());
      if (!aggregate) {
        const fallback = finalLang === 'ar' ? 'تمت المعالجة.' : 'Processed.';
        apply(fallback);
      }
      if (meta) setMetadata(meta);
    } catch (e: any) {
      const err = lang === 'ar' ? 'حدث خطأ. حاول لاحقاً.' : 'An error occurred. Please try again.';
      setMessages((prev) => prev.map((m) => (m.id === streamId ? { ...m, content: err } : m)));
      toast({ title: 'Error', description: e?.message || err, status: 'error' });
    } finally {
      setLoading(false);
    }
  };

  // Voice recording with full transcription
  const startRecording = async () => {
    try {
      if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
        toast({
          title: lang === 'ar' ? 'غير مدعوم' : 'Not supported',
          description: lang === 'ar' ? 'المتصفح لا يدعم التسجيل الصوتي' : 'Browser does not support audio recording',
          status: 'error',
          duration: 3000,
        });
        return;
      }

      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const recorder = new MediaRecorder(stream);
      const chunks: Blob[] = [];

      recorder.ondataavailable = (e) => chunks.push(e.data);
      recorder.onstop = async () => {
        const blob = new Blob(chunks, { type: 'audio/webm' });
        stream.getTracks().forEach(track => track.stop());
        
        // Upload and transcribe immediately
        toast({
          title: lang === 'ar' ? 'جاري المعالجة...' : 'Processing...',
          description: lang === 'ar' ? 'جاري تحويل الصوت إلى نص...' : 'Transcribing audio to text...',
          status: 'info',
          duration: 2000,
        });

        try {
          // Upload audio
          const uploadFormData = new FormData();
          uploadFormData.append('audio', blob, 'voice.webm');
          
          const uploadRes = await fetch('/api/admin/voice/upload', {
            method: 'POST',
            body: uploadFormData,
          });

          if (!uploadRes.ok) throw new Error('Upload failed');
          const { url: audioUrl } = await uploadRes.json();

          // Transcribe audio
          const transcribeFormData = new FormData();
          transcribeFormData.append('audio', blob, 'voice.webm');

          const transcribeRes = await fetch('/api/admin/voice/transcribe', {
            method: 'POST',
            body: transcribeFormData,
          });

          if (!transcribeRes.ok) throw new Error('Transcription failed');
          const { text } = await transcribeRes.json();

          // Set transcribed text as input
          setInput(text);

          // Add user message with audio
          const userMsg: Message = {
            id: String(Date.now()),
            role: 'user',
            content: text,
            ts: new Date(),
            audioUrl,
            isTranscribed: true,
          };

          setMessages((prev) => [...prev, userMsg]);
          
          // Auto-send to AI
          setTimeout(() => sendTranscribedMessage(text, userMsg), 100);

          toast({
            title: lang === 'ar' ? 'تم التحويل' : 'Transcription complete',
            description: lang === 'ar' ? 'تم إرسال الرسالة إلى SpeedyAI' : 'Message sent to SpeedyAI',
            status: 'success',
            duration: 2000,
          });
        } catch (error: any) {
          console.error('Voice processing error:', error);
          toast({
            title: lang === 'ar' ? 'خطأ' : 'Error',
            description: error?.message || (lang === 'ar' ? 'فشل معالجة الصوت' : 'Voice processing failed'),
            status: 'error',
            duration: 3000,
          });
        }
      };

      recorder.start();
      setMediaRecorder(recorder);
      setIsRecording(true);
      
      toast({
        title: lang === 'ar' ? 'جاري التسجيل...' : 'Recording...',
        status: 'info',
        duration: 1000,
      });
    } catch (error: any) {
      console.error('Microphone error:', error);
      const errorMessage = error?.name === 'NotAllowedError' 
        ? (lang === 'ar' ? 'لم يتم السماح بالوصول للميكروفون' : 'Microphone access denied')
        : (lang === 'ar' ? 'خطأ في الوصول للميكروفون' : 'Microphone access error');
      
      toast({
        title: lang === 'ar' ? 'خطأ' : 'Error',
        description: errorMessage,
        status: 'error',
        duration: 5000,
      });
    }
  };

  const stopRecording = () => {
    if (mediaRecorder && isRecording) {
      mediaRecorder.stop();
      setIsRecording(false);
      setMediaRecorder(null);
    }
  };

  // Send transcribed message to AI
  const sendTranscribedMessage = async (content: string, userMsg: Message) => {
    const streamId = String(Date.now() + 1);
    const aiMsg: Message = { id: streamId, role: 'assistant', content: '', ts: new Date() };
    setMessages((prev) => [...prev, aiMsg]);
    setLoading(true);
    setMetadata(null);

    try {
      const res = await fetch('/api/admin/ai/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          message: content,
          conversationHistory: [...messages, userMsg].map((m) => ({
            role: m.role,
            content: m.content,
          })),
          language: lang,
          mode: 'stream',
        }),
      });

      if (!res.ok || !res.body) throw new Error('Chat API error');
      
      const reader = res.body.getReader();
      const decoder = new TextDecoder();
      let buffer = '';
      let aggregate = '';

      const apply = (content: string) => {
        setMessages((prev) => prev.map((m) => (m.id === streamId ? { ...m, content } : m)));
      };

      const handleLine = (line: string) => {
        try {
          const payload = JSON.parse(line);
          if (payload.event === 'token') {
            aggregate += typeof payload.data === 'string' ? payload.data : '';
            apply(aggregate);
          } else if (payload.event === 'final') {
            const data = payload.data || {};
            if (typeof data.response === 'string') {
              aggregate = data.response;
              apply(aggregate);
            }
          }
        } catch {}
      };

      while (true) {
        const { value, done } = await reader.read();
        if (done) break;
        buffer += decoder.decode(value, { stream: true });
        let idx: number;
        while ((idx = buffer.indexOf('\n')) >= 0) {
          const line = buffer.slice(0, idx).trim();
          buffer = buffer.slice(idx + 1);
          if (line) handleLine(line);
        }
      }
      if (buffer.trim()) handleLine(buffer.trim());
      if (!aggregate) apply(lang === 'ar' ? 'تمت المعالجة.' : 'Processed.');
    } catch (e: any) {
      const err = lang === 'ar' ? 'حدث خطأ' : 'An error occurred';
      setMessages((prev) => prev.map((m) => (m.id === streamId ? { ...m, content: err } : m)));
    } finally {
      setLoading(false);
    }
  };

  // Text-to-Speech for AI messages
  const playTTS = async (messageId: string, text: string) => {
    try {
      // Stop any currently playing audio
      if (playingAudio) {
        const currentAudio = audioRefs.get(playingAudio);
        if (currentAudio) {
          currentAudio.pause();
          currentAudio.currentTime = 0;
        }
        setPlayingAudio(null);
      }

      setPlayingAudio(messageId);

      toast({
        title: lang === 'ar' ? 'جاري التحويل...' : 'Converting...',
        description: lang === 'ar' ? 'جاري تحويل النص إلى صوت...' : 'Converting text to speech...',
        status: 'info',
        duration: 1000,
      });

      const res = await fetch('/api/admin/voice/tts', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ text, voice: ttsVoice }),
      });

      // Check if response is audio or JSON (fallback instruction)
      const contentType = res.headers.get('content-type');
      
      // If service unavailable (503) or JSON response, use browser TTS
      if (!res.ok || contentType?.includes('application/json')) {
        try {
          const data = await res.json();
          if (data.fallback === 'browser-tts' || res.status === 503) {
            useBrowserTTS(messageId, text);
            return;
          }
        } catch {
          // If parsing fails, fallback to browser TTS anyway
          useBrowserTTS(messageId, text);
          return;
        }
      }

      const audioBlob = await res.blob();
      const audioUrl = URL.createObjectURL(audioBlob);
      
      const audio = new Audio(audioUrl);
      audio.onended = () => {
        setPlayingAudio(null);
        URL.revokeObjectURL(audioUrl);
      };
      audio.onerror = () => {
        setPlayingAudio(null);
        URL.revokeObjectURL(audioUrl);
        toast({
          title: lang === 'ar' ? 'خطأ' : 'Error',
          description: lang === 'ar' ? 'فشل تشغيل الصوت' : 'Audio playback failed',
          status: 'error',
          duration: 2000,
        });
      };

      audioRefs.set(messageId, audio);
      await audio.play();

    } catch (error: any) {
      console.error('TTS error (using browser fallback):', error);
      setPlayingAudio(null);
      
      // Always try browser TTS as fallback
      if ('speechSynthesis' in window) {
        useBrowserTTS(messageId, text);
      } else {
        toast({
          title: lang === 'ar' ? 'خطأ' : 'Error',
          description: lang === 'ar' ? 'المتصفح لا يدعم قراءة النصوص' : 'Browser does not support speech',
          status: 'error',
          duration: 3000,
        });
      }
    }
  };

  // Browser TTS fallback (free, works offline)
  const useBrowserTTS = (messageId: string, text: string) => {
    if (!('speechSynthesis' in window)) {
      setPlayingAudio(null);
      toast({
        title: lang === 'ar' ? 'غير مدعوم' : 'Not supported',
        description: lang === 'ar' ? 'المتصفح لا يدعم قراءة النصوص' : 'Browser does not support speech synthesis',
        status: 'error',
        duration: 3000,
      });
      return;
    }

    // Load voices if not loaded yet
    let voices = window.speechSynthesis.getVoices();
    if (voices.length === 0) {
      // Wait for voices to load
      window.speechSynthesis.addEventListener('voiceschanged', () => {
        voices = window.speechSynthesis.getVoices();
      });
    }

    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = lang === 'ar' ? 'ar-SA' : 'en-US';
    utterance.rate = 1.0;
    utterance.pitch = 1.0;

    // Try to match voice gender
    const preferredVoice = voices.find(v => {
      const isCorrectLang = lang === 'ar' ? v.lang.startsWith('ar') : v.lang.startsWith('en');
      const matchesGender = ttsVoice === 'nova' 
        ? v.name.toLowerCase().includes('female') || v.name.toLowerCase().includes('zira') || v.name.toLowerCase().includes('samantha')
        : v.name.toLowerCase().includes('male') || v.name.toLowerCase().includes('david') || v.name.toLowerCase().includes('alex');
      return isCorrectLang && matchesGender;
    });

    if (preferredVoice) {
      utterance.voice = preferredVoice;
    }

    utterance.onend = () => setPlayingAudio(null);
    utterance.onerror = (e) => {
      console.error('Browser TTS error:', e);
      setPlayingAudio(null);
      toast({
        title: lang === 'ar' ? 'خطأ' : 'Error',
        description: lang === 'ar' ? 'فشلت القراءة' : 'Speech failed',
        status: 'error',
        duration: 2000,
      });
    };

    window.speechSynthesis.cancel(); // Stop any ongoing speech
    window.speechSynthesis.speak(utterance);
    setPlayingAudio(messageId);
  };

  const stopTTS = (messageId: string) => {
    const audio = audioRefs.get(messageId);
    if (audio) {
      audio.pause();
      audio.currentTime = 0;
    }
    
    // Stop browser TTS if active
    if ('speechSynthesis' in window) {
      window.speechSynthesis.cancel();
    }
    
    setPlayingAudio(null);
  };

  // Play recorded audio
  const playRecordedAudio = (audioUrl: string, messageId: string) => {
    if (playingAudio === messageId) {
      stopTTS(messageId);
      return;
    }

    // Stop any currently playing
    if (playingAudio) {
      stopTTS(playingAudio);
    }

    const audio = new Audio(audioUrl);
    audio.onended = () => setPlayingAudio(null);
    audio.onerror = () => {
      setPlayingAudio(null);
      toast({
        title: lang === 'ar' ? 'خطأ' : 'Error',
        description: lang === 'ar' ? 'فشل تشغيل التسجيل' : 'Audio playback failed',
        status: 'error',
        duration: 2000,
      });
    };

    audioRefs.set(messageId, audio);
    setPlayingAudio(messageId);
    audio.play();
  };

  // Toggle voice gender
  const toggleVoiceGender = () => {
    const newVoice = ttsVoice === 'nova' ? 'onyx' : 'nova';
    setTtsVoice(newVoice);
    toast({
      title: lang === 'ar' ? 'تم التغيير' : 'Voice changed',
      description: newVoice === 'nova' 
        ? (lang === 'ar' ? 'صوت أنثوي' : 'Female voice')
        : (lang === 'ar' ? 'صوت ذكري' : 'Male voice'),
      status: 'success',
      duration: 1500,
    });
  };

  if (!open) return null;

  return (
    <Box 
      position="fixed" 
      top="0" 
      left="0" 
      right="0" 
      bottom="80px" 
      zIndex={1000} 
      bg="#0b0e14"
    >
      {/* Header Bar */}
      <HStack justify="space-between" px={5} py={3} borderBottom="1px solid #232735" bg="#0b0e14">
        <HStack spacing={3}>
          {/* Video Avatar */}
          <Box
            as="video"
            autoPlay
            loop
            muted
            playsInline
            w="40px"
            h="40px"
            borderRadius="full"
            overflow="hidden"
            border="2px solid #2563eb"
            boxShadow="0 0 10px rgba(37, 99, 235, 0.5)"
            objectFit="cover"
            src="/speedy-ai-header.mp4"
          />
          <VStack align="start" spacing={0}>
            <HStack>
              <Text color="#ECECF1" fontWeight="bold">Speedy AI</Text>
              <Badge colorScheme="green" borderRadius="full">{lang === 'ar' ? 'متصل' : 'Online'}</Badge>
            </HStack>
            <Text color="#9aa0b4" fontSize="xs">{lang === 'ar' ? 'مساعدك الذكي' : 'Your AI assistant'}</Text>
          </VStack>
        </HStack>
        <HStack>
          <Tooltip label={ttsVoice === 'nova' ? (lang === 'ar' ? 'صوت أنثوي' : 'Female voice') : (lang === 'ar' ? 'صوت ذكري' : 'Male voice')}>
            <Button
              size="sm"
              variant="ghost"
              color="#ECECF1"
              onClick={toggleVoiceGender}
              leftIcon={ttsVoice === 'nova' ? <Text>♀</Text> : <Text>♂</Text>}
              _hover={{ bg: 'rgba(16, 185, 129, 0.1)' }}
            >
              {ttsVoice === 'nova' ? (lang === 'ar' ? 'أنثى' : 'Female') : (lang === 'ar' ? 'ذكر' : 'Male')}
            </Button>
          </Tooltip>
          <Tooltip label={lang === 'ar' ? 'لغة' : 'Language'}>
            <Select
              size="sm"
              value={lang}
              onChange={(e) => setLang(e.target.value as Lang)}
              width="80px"
              bg="#0f1420"
              color="#ECECF1"
              borderColor="#2a2f3a"
            >
              <option value="en" style={{ background: '#0b0e14', color: '#fff' }}>EN</option>
              <option value="ar" style={{ background: '#0b0e14', color: '#fff' }}>AR</option>
            </Select>
          </Tooltip>
          <Tooltip label={lang === 'ar' ? 'إعدادات الصور' : 'Image Settings'}>
            <IconButton 
              aria-label="AI Settings" 
              icon={<FiImage />} 
              size="sm" 
              variant="ghost" 
              color="#ECECF1" 
              onClick={() => setAiSettingsOpen(true)}
              _hover={{ bg: 'rgba(16, 185, 129, 0.1)', color: '#10b981' }}
            />
          </Tooltip>
          <Tooltip label={lang === 'ar' ? 'تصدير' : 'Export'}>
            <IconButton aria-label="Export" icon={<FiDownload />} size="sm" variant="ghost" color="#ECECF1" onClick={exportTxt} isDisabled={messages.length === 0} />
          </Tooltip>
          <Tooltip label={lang === 'ar' ? 'تحديث' : 'Refresh'}>
            <IconButton aria-label="Refresh" icon={<FiRefreshCw />} size="sm" variant="ghost" color="#ECECF1" onClick={() => window.location.reload()} />
          </Tooltip>
          <IconButton aria-label="Close" icon={<FiX />} size="sm" variant="ghost" color="#ECECF1" onClick={() => setOpen(false)} />
        </HStack>
      </HStack>

      {/* Enterprise Grid */}
      <Grid templateColumns={{ base: '1fr', lg: '280px 1fr 360px' }} templateRows={{ base: '1fr auto', lg: '1fr auto' }} gap={0} h="calc(100vh - 56px)">
        {/* Sidebar - History */}
        <GridItem display={{ base: 'none', lg: 'block' }} borderRight="1px solid #232735" bg="#0b0e14">
          <VStack align="stretch" spacing={3} p={4}>
            <Button leftIcon={<FiPlus />} size="sm" colorScheme="blue" onClick={newConversation}>
              {lang === 'ar' ? 'محادثة جديدة' : 'New chat'}
            </Button>
            <Divider borderColor="#232735" />
            <VStack align="stretch" spacing={2} maxH="calc(100vh - 140px)" overflowY="auto">
              {history.length === 0 ? (
                <Text fontSize="sm" color="#9aa0b4">{lang === 'ar' ? 'لا يوجد محفوظات.' : 'No history yet.'}</Text>
              ) : (
                history.map((h) => (
                  <HStack key={h.id} justify="space-between" p={2} border="1px solid #232735" borderRadius="md" bg="#0f1420" _hover={{ bg: '#111625' }}>
                    <Text color="#ECECF1" fontSize="sm" noOfLines={1}>{h.title}</Text>
                    <Text color="#9aa0b4" fontSize="xs">{new Date(h.createdAt).toLocaleDateString()}</Text>
                  </HStack>
                ))
              )}
            </VStack>
          </VStack>
        </GridItem>

        {/* Chat - Center */}
        <GridItem bg="#0b0e14" borderRight={{ base: 'none', lg: '1px solid #232735' }}>
          <VStack align="stretch" spacing={0} h="100%">
            <Box flex={1} overflowY="auto" p={{ base: 3, md: 5 }}>
              <VStack align="stretch" spacing={4}>
                {messages.map((m) => (
                  <HStack key={m.id} justify={m.role === 'user' ? 'flex-end' : 'flex-start'} align="flex-start">
                    {m.role === 'assistant' && <Avatar size="sm" bg="#2563eb" icon={<FiZap />} />}
                    <VStack align={m.role === 'user' ? 'flex-end' : 'flex-start'} spacing={1}>
                      <Box
                        maxW="80%"
                        bg={m.role === 'user' ? '#111625' : '#0f1420'}
                        border="1px solid #232735"
                        borderRadius="lg"
                        px={4}
                        py={3}
                      >
                        {/* Generated Image Display */}
                        {m.imageUrl && (
                          <Box
                            position="relative"
                            mb={2}
                            borderRadius="md"
                            overflow="hidden"
                            cursor="pointer"
                            onClick={() => {
                              setSelectedImage(m.imageUrl!);
                              setImageModalOpen(true);
                            }}
                            _hover={{
                              transform: 'scale(1.02)',
                              transition: 'transform 0.2s',
                            }}
                          >
                            {generatingImage && m.content.includes('جاري إنشاء') || m.content.includes('Generating') ? (
                              <Box
                                w="300px"
                                h="300px"
                                bg="linear-gradient(90deg, #1a1d29 0%, #232735 50%, #1a1d29 100%)"
                                backgroundSize="200% 100%"
                                animation="shimmer 1.5s infinite"
                                sx={{
                                  '@keyframes shimmer': {
                                    '0%': { backgroundPosition: '200% 0' },
                                    '100%': { backgroundPosition: '-200% 0' },
                                  },
                                }}
                                display="flex"
                                alignItems="center"
                                justifyContent="center"
                              >
                                <VStack spacing={2}>
                                  <Progress size="xs" colorScheme="blue" isIndeterminate w="200px" />
                                  <Text color="#9aa0b4" fontSize="xs">
                                    {lang === 'ar' ? 'جاري إنشاء الصورة...' : 'Generating image...'}
                                  </Text>
                                </VStack>
                              </Box>
                            ) : (
                              <Box
                                as="img"
                                src={m.imageUrl}
                                alt={m.imageMetadata?.prompt || 'Generated image'}
                                maxW="400px"
                                maxH="400px"
                                objectFit="contain"
                                borderRadius="md"
                                border="2px solid transparent"
                                _hover={{ borderColor: '#10b981' }}
                                transition="all 0.2s"
                              />
                            )}
                            {m.imageMetadata && (
                              <HStack
                                position="absolute"
                                bottom="8px"
                                right="8px"
                                bg="rgba(0,0,0,0.7)"
                                px={2}
                                py={1}
                                borderRadius="md"
                                spacing={1}
                              >
                                <Badge colorScheme="blue" fontSize="9px">{m.imageMetadata.model}</Badge>
                                <Badge colorScheme="green" fontSize="9px">{m.imageMetadata.size}</Badge>
                                {m.imageMetadata.quality === 'hd' && (
                                  <Badge colorScheme="purple" fontSize="9px">HD</Badge>
                                )}
                              </HStack>
                            )}
                          </Box>
                        )}
                        
                        <Text color="#ECECF1" fontSize="sm" whiteSpace="pre-wrap">{m.content}</Text>
                        <HStack justify="space-between" mt={1}>
                          <HStack spacing={2}>
                            <Text color="#9aa0b4" fontSize="xs">
                              {m.ts.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                            </Text>
                            {m.isTranscribed && (
                              <Badge colorScheme="purple" fontSize="9px" px={2}>
                                {lang === 'ar' ? 'صوتي' : 'Voice'}
                              </Badge>
                            )}
                          </HStack>
                          <HStack spacing={1}>
                            {/* Copy message */}
                            {m.role === 'assistant' && m.content && (
                              <Tooltip label={copiedMessageId === m.id ? (lang === 'ar' ? 'تم النسخ!' : 'Copied!') : (lang === 'ar' ? 'نسخ الرد' : 'Copy answer')}>
                                <IconButton
                                  aria-label="Copy message"
                                  icon={copiedMessageId === m.id ? <FiCheck /> : <FiCopy />}
                                  size="xs"
                                  variant="ghost"
                                  color={copiedMessageId === m.id ? '#10b981' : '#6B7280'}
                                  _hover={{ color: '#10b981' }}
                                  onClick={async () => {
                                    try {
                                      await navigator.clipboard.writeText(m.content);
                                      setCopiedMessageId(m.id);
                                      setTimeout(() => setCopiedMessageId(null), 2000);
                                      toast({
                                        title: lang === 'ar' ? 'تم النسخ' : 'Copied',
                                        description: lang === 'ar' ? 'تم نسخ الرد إلى الحافظة' : 'Answer copied to clipboard',
                                        status: 'success',
                                        duration: 2000,
                                      });
                                    } catch (err) {
                                      toast({
                                        title: lang === 'ar' ? 'خطأ' : 'Error',
                                        description: lang === 'ar' ? 'فشل النسخ' : 'Failed to copy',
                                        status: 'error',
                                        duration: 2000,
                                      });
                                    }
                                  }}
                                />
                              </Tooltip>
                            )}
                            {/* Play recorded audio if available */}
                            {m.audioUrl && (
                              <Tooltip label={playingAudio === m.id ? (lang === 'ar' ? 'إيقاف' : 'Stop') : (lang === 'ar' ? 'تشغيل التسجيل' : 'Play recording')}>
                                <IconButton
                                  aria-label="Play audio"
                                  icon={playingAudio === m.id ? <FiMicOff /> : <FiMic />}
                                  size="xs"
                                  variant="ghost"
                                  color={playingAudio === m.id ? '#10b981' : '#6B7280'}
                                  _hover={{ color: '#10b981' }}
                                  onClick={() => playRecordedAudio(m.audioUrl!, m.id)}
                                />
                              </Tooltip>
                            )}
                            {/* TTS for AI messages */}
                            {m.role === 'assistant' && m.content && (
                              <Tooltip label={playingAudio === m.id ? (lang === 'ar' ? 'إيقاف القراءة' : 'Stop reading') : (lang === 'ar' ? 'قراءة الرسالة' : 'Read message')}>
                                <IconButton
                                  aria-label="Text to speech"
                                  icon={playingAudio === m.id ? <FiMicOff /> : <FiZap />}
                                  size="xs"
                                  variant="ghost"
                                  color={playingAudio === m.id ? '#10b981' : '#6B7280'}
                                  _hover={{ color: '#10b981' }}
                                  onClick={() => playingAudio === m.id ? stopTTS(m.id) : playTTS(m.id, m.content)}
                                  isLoading={playingAudio === m.id}
                                />
                              </Tooltip>
                            )}
                          </HStack>
                        </HStack>
                      </Box>
                    </VStack>
                    {m.role === 'user' && <Avatar size="sm" bg="#4b5563" />}
                  </HStack>
                ))}
                {loading && (
                  <HStack spacing={3} align="center">
                    <Box
                      as="img"
                      src="/ai-typing-avatar.svg"
                      w="32px"
                      h="32px"
                      borderRadius="full"
                      animation="pulse 1.5s ease-in-out infinite"
                      sx={{
                        '@keyframes pulse': {
                          '0%, 100%': { opacity: 1, transform: 'scale(1)' },
                          '50%': { opacity: 0.7, transform: 'scale(0.95)' },
                        },
                      }}
                    />
                    <VStack align="flex-start" spacing={1}>
                      <Progress size="xs" colorScheme="blue" isIndeterminate w="160px" />
                      <Text color="#9aa0b4" fontSize="xs">{lang === 'ar' ? 'جاري الكتابة...' : 'Typing...'}</Text>
                    </VStack>
                  </HStack>
                )}
                <div ref={endRef} />
              </VStack>
            </Box>

            {/* Input */}
            <Box borderTop="1px solid #232735" p={3} bg="#0f1420">
              <Box
                bg="#1a1d29"
                border="1px solid #232735"
                borderRadius="lg"
                p={2}
                _focusWithin={{
                  borderColor: '#10b981',
                  boxShadow: '0 0 0 1px #10b981',
                }}
                transition="all 0.2s"
              >
                <HStack align="flex-end" spacing={2}>
                  <Textarea
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    onKeyDown={(e) => {
                      if (e.key === 'Enter' && !e.shiftKey) {
                        e.preventDefault();
                        send();
                      }
                    }}
                    placeholder={placeholder}
                    rows={3}
                    resize="none"
                    bg="#1a1d29 !important"
                    color="#FFFFFF !important"
                    border="none"
                    _placeholder={{ color: '#6B7280' }}
                    _focus={{ 
                      bg: '#1a1d29 !important',
                      boxShadow: 'none',
                      color: '#FFFFFF !important',
                      outline: 'none'
                    }}
                    _active={{
                      bg: '#1a1d29 !important',
                      color: '#FFFFFF !important'
                    }}
                    _hover={{
                      bg: '#1a1d29 !important'
                    }}
                    fontSize="sm"
                    sx={{
                      caretColor: '#10b981',
                      '&:focus': {
                        bg: '#1a1d29 !important',
                        color: '#FFFFFF !important'
                      },
                      '&:active': {
                        bg: '#1a1d29 !important',
                        color: '#FFFFFF !important'
                      },
                      '&::selection': {
                        bg: 'rgba(16, 185, 129, 0.3)',
                        color: '#FFFFFF'
                      }
                    }}
                  />
                  <VStack spacing={2} flexShrink={0}>
                    <Tooltip label={isRecording ? (lang === 'ar' ? 'إيقاف التسجيل' : 'Stop recording') : (lang === 'ar' ? 'تسجيل صوتي' : 'Voice message')}>
                      <IconButton
                        aria-label="Voice message"
                        icon={isRecording ? <FiMicOff /> : <FiMic />}
                        size="md"
                        bg={isRecording ? '#ef4444' : 'transparent'}
                        color={isRecording ? 'white' : '#6B7280'}
                        onClick={isRecording ? stopRecording : startRecording}
                        _hover={{
                          bg: isRecording ? '#dc2626' : 'rgba(255,255,255,0.05)',
                          color: isRecording ? 'white' : '#10b981',
                        }}
                        borderRadius="md"
                        transition="all 0.2s"
                        animation={isRecording ? 'pulse 1.5s cubic-bezier(0.4, 0, 0.6, 1) infinite' : 'none'}
                      />
                    </Tooltip>
                    <IconButton
                      aria-label="Send"
                      icon={<FiSend />}
                      size="md"
                      bg={input.trim() && !loading ? '#10b981' : 'transparent'}
                      color={input.trim() && !loading ? 'white' : '#6B7280'}
                      onClick={send}
                      isDisabled={!input.trim() || loading}
                      _hover={{
                        bg: input.trim() && !loading ? '#059669' : 'rgba(255,255,255,0.05)',
                      }}
                      borderRadius="md"
                      transition="all 0.2s"
                    />
                  </VStack>
                </HStack>
              </Box>
            </Box>
          </VStack>
        </GridItem>

        {/* Insights - Right */}
        <GridItem display={{ base: 'none', lg: 'block' }} bg="#0b0e14">
          <VStack align="stretch" spacing={4} p={4} h="100%" overflowY="auto">
            <HStack>
              <FiBarChart2 color="#9aa0b4" />
              <Text color="#ECECF1" fontWeight="bold">{lang === 'ar' ? 'الرؤى' : 'Insights'}</Text>
            </HStack>
            <Divider borderColor="#232735" />
            {!metadata ? (
              <Text color="#9aa0b4" fontSize="sm">
                {lang === 'ar' ? 'اطلب نظرة عامة للحصول على رؤى فورية.' : 'Ask for an overview to get real-time insights.'}
              </Text>
            ) : (
              <VStack align="stretch" spacing={3}>
                <HStack>
                  <Badge colorScheme="purple">#{metadata.requestId?.slice(0, 8)}</Badge>
                  {typeof metadata.processingTimeMs === 'number' && (
                    <Badge colorScheme="green">{metadata.processingTimeMs}ms</Badge>
                  )}
                </HStack>
                {metadata.references && (metadata.references.orders?.length || metadata.references.routes?.length) ? (
                  <Box border="1px solid #232735" borderRadius="md" p={3} bg="#0f1420">
                    <Text color="#9aa0b4" fontSize="xs" mb={2}>{lang === 'ar' ? 'مراجع' : 'References'}</Text>
                    <HStack spacing={2} wrap="wrap">
                      {metadata.references.orders?.map((o: string) => (
                        <Tag key={`o-${o}`} size="sm" colorScheme="blue"><TagLabel>{lang === 'ar' ? `طلب ${o}` : `Order ${o}`}</TagLabel></Tag>
                      ))}
                      {metadata.references.routes?.map((r: string) => (
                        <Tag key={`r-${r}`} size="sm" colorScheme="purple"><TagLabel>{lang === 'ar' ? `مسار ${r}` : `Route ${r}`}</TagLabel></Tag>
                      ))}
                    </HStack>
                  </Box>
                ) : null}
                {metadata.proactiveSuggestions?.suggestions?.length ? (
                  <Box border="1px solid #232735" borderRadius="md" p={3} bg="#0f1420">
                    <Text color="#9aa0b4" fontSize="xs" mb={2}>{lang === 'ar' ? 'اقتراحات' : 'Suggestions'}</Text>
                    <VStack align="stretch" spacing={1}>
                      {metadata.proactiveSuggestions.suggestions.map((s, i) => (
                        <Text key={i} color="#ECECF1" fontSize="sm">• {s}</Text>
                      ))}
                    </VStack>
                  </Box>
                ) : null}
              </VStack>
            )}

            <Divider borderColor="#232735" />
            <Box position="relative" py={2}>
              <HStack spacing={3} position="relative">
                <Text 
                  color="#10b981" 
                  fontWeight="bold" 
                  fontSize="xs"
                  letterSpacing="wider"
                  animation={loading ? 'pulse 1.5s cubic-bezier(0.4, 0, 0.6, 1) infinite' : 'none'}
                >
                  LIVE
                </Text>
                <Box flex="1" position="relative" h="2px">
                  <Box
                    position="absolute"
                    top="0"
                    left="0"
                    right="0"
                    h="2px"
                    bg="#1a1d29"
                  />
                  <Box
                    position="absolute"
                    top="0"
                    left="0"
                    h="2px"
                    bg="linear-gradient(90deg, #10b981 0%, #059669 100%)"
                    animation="slideRight 2s ease-in-out infinite"
                    sx={{
                      '@keyframes slideRight': {
                        '0%': { width: '0%' },
                        '50%': { width: '100%' },
                        '100%': { width: '0%' },
                      },
                    }}
                  />
                </Box>
                <Badge 
                  colorScheme="green" 
                  fontSize="9px" 
                  borderRadius="full"
                  px={2}
                  bg="rgba(16, 185, 129, 0.15)"
                  color="#10b981"
                >
                  {liveLane.length}
                </Badge>
              </HStack>
            </Box>
            <VStack 
              align="stretch" 
              spacing={2} 
              maxH="400px" 
              overflowY="auto"
              css={{
                '&::-webkit-scrollbar': { width: '6px' },
                '&::-webkit-scrollbar-track': { background: '#0b0e14' },
                '&::-webkit-scrollbar-thumb': {
                  background: '#232735',
                  borderRadius: '3px',
                },
                '&::-webkit-scrollbar-thumb:hover': { background: '#2d3548' },
              }}
            >
              {liveLane.length === 0 ? (
                <Box 
                  textAlign="center" 
                  py={8}
                  color="#6B7280"
                >
                  <FiClock size={32} style={{ margin: '0 auto 12px' }} />
                  <Text fontSize="sm">
                    {lang === 'ar' ? 'لا توجد إشعارات جديدة' : 'No new notifications'}
                  </Text>
                </Box>
              ) : (
                liveLane.map((it, index) => (
                  <Box
                    key={it.id}
                    p={3}
                    border="1px solid"
                    borderColor={index === 0 ? '#10b981' : '#232735'}
                    borderRadius="lg"
                    bg={index === 0 ? 'rgba(16, 185, 129, 0.05)' : '#0f1420'}
                    _hover={{ 
                      borderColor: '#10b981',
                      bg: 'rgba(16, 185, 129, 0.08)',
                      transform: 'translateX(-2px)',
                    }}
                    transition="all 0.2s"
                    cursor="pointer"
                    position="relative"
                  >
                    {index === 0 && (
                      <Box
                        position="absolute"
                        top="12px"
                        left="-6px"
                        w="3px"
                        h="20px"
                        bg="#10b981"
                        borderRadius="full"
                      />
                    )}
                    <VStack align="stretch" spacing={1}>
                      <Text 
                        color="#ECECF1" 
                        fontSize="sm" 
                        fontWeight={index === 0 ? '600' : '400'}
                        noOfLines={2}
                      >
                        {it.title}
                      </Text>
                      <HStack justify="space-between">
                        <Text color="#6B7280" fontSize="xs">
                          {new Date(it.createdAt).toLocaleTimeString()}
                        </Text>
                        {index === 0 && (
                          <Badge 
                            colorScheme="green" 
                            fontSize="9px" 
                            borderRadius="full"
                          >
                            NEW
                          </Badge>
                        )}
                      </HStack>
                    </VStack>
                  </Box>
                ))
              )}
            </VStack>
          </VStack>
        </GridItem>
      </Grid>
      
      {/* Image Preview Modal */}
      <Modal 
        isOpen={imageModalOpen} 
        onClose={() => setImageModalOpen(false)} 
        size="6xl"
        isCentered
      >
        <ModalOverlay bg="rgba(0,0,0,0.8)" />
        <ModalContent bg="#0b0e14" border="1px solid #232735">
          <ModalHeader color="#ECECF1">
            {lang === 'ar' ? 'معاينة الصورة' : 'Image Preview'}
          </ModalHeader>
          <ModalCloseButton color="#ECECF1" />
          <ModalBody>
            {selectedImage && (
              <Box
                as="img"
                src={selectedImage}
                alt="Full size preview"
                w="100%"
                h="auto"
                maxH="80vh"
                objectFit="contain"
                borderRadius="md"
              />
            )}
          </ModalBody>
          <ModalFooter>
            <Button
              leftIcon={<FiDownloadCloud />}
              colorScheme="blue"
              variant="outline"
              onClick={() => {
                if (selectedImage) {
                  const link = document.createElement('a');
                  link.href = selectedImage;
                  link.download = `speedy-ai-${Date.now()}.png`;
                  link.click();
                }
              }}
            >
              {lang === 'ar' ? 'تحميل' : 'Download'}
            </Button>
          </ModalFooter>
        </ModalContent>
      </Modal>

      {/* AI Tools Settings Modal */}
      <Modal 
        isOpen={aiSettingsOpen} 
        onClose={() => setAiSettingsOpen(false)} 
        size="lg"
      >
        <ModalOverlay />
        <ModalContent bg="#0b0e14" border="1px solid #232735">
          <ModalHeader color="#ECECF1">
            <HStack>
              <FiSettings />
              <Text>{lang === 'ar' ? 'إعدادات توليد الصور' : 'Image Generation Settings'}</Text>
            </HStack>
          </ModalHeader>
          <ModalCloseButton color="#ECECF1" />
          <ModalBody>
            <VStack spacing={4} align="stretch">
              <FormControl>
                <FormLabel color="#ECECF1" fontSize="sm">
                  {lang === 'ar' ? 'نموذج الصورة' : 'Image Model'}
                </FormLabel>
                <RadioGroup value={imageModel} onChange={(val) => setImageModel(val as any)}>
                  <Stack spacing={2}>
                    <Radio value="dall-e-3" colorScheme="green">
                      <VStack align="start" spacing={0}>
                        <Text color="#ECECF1" fontSize="sm">DALL-E 3</Text>
                        <Text color="#9aa0b4" fontSize="xs">
                          {lang === 'ar' ? 'جودة عالية، أبطأ قليلاً' : 'Higher quality, slightly slower'}
                        </Text>
                      </VStack>
                    </Radio>
                    <Radio value="dall-e-2" colorScheme="green">
                      <VStack align="start" spacing={0}>
                        <Text color="#ECECF1" fontSize="sm">DALL-E 2</Text>
                        <Text color="#9aa0b4" fontSize="xs">
                          {lang === 'ar' ? 'أسرع، جودة جيدة' : 'Faster, good quality'}
                        </Text>
                      </VStack>
                    </Radio>
                  </Stack>
                </RadioGroup>
              </FormControl>

              <FormControl>
                <FormLabel color="#ECECF1" fontSize="sm">
                  {lang === 'ar' ? 'حجم الصورة' : 'Image Size'}
                </FormLabel>
                <Select
                  value={imageSize}
                  onChange={(e) => setImageSize(e.target.value)}
                  bg="#0f1420"
                  color="#ECECF1"
                  borderColor="#2a2f3a"
                >
                  {imageModel === 'dall-e-3' ? (
                    <>
                      <option value="1024x1024">1024x1024 (Square)</option>
                      <option value="1024x1792">1024x1792 (Portrait)</option>
                      <option value="1792x1024">1792x1024 (Landscape)</option>
                    </>
                  ) : (
                    <>
                      <option value="256x256">256x256 (Small)</option>
                      <option value="512x512">512x512 (Medium)</option>
                      <option value="1024x1024">1024x1024 (Large)</option>
                    </>
                  )}
                </Select>
              </FormControl>

              <FormControl>
                <FormLabel color="#ECECF1" fontSize="sm">
                  {lang === 'ar' ? 'جودة الصورة' : 'Image Quality'}
                </FormLabel>
                <RadioGroup value={imageQuality} onChange={(val) => setImageQuality(val as any)}>
                  <Stack spacing={2}>
                    <Radio value="standard" colorScheme="green">
                      <Text color="#ECECF1" fontSize="sm">
                        {lang === 'ar' ? 'قياسي' : 'Standard'}
                      </Text>
                    </Radio>
                    <Radio value="hd" colorScheme="green">
                      <VStack align="start" spacing={0}>
                        <Text color="#ECECF1" fontSize="sm">HD</Text>
                        <Text color="#9aa0b4" fontSize="xs">
                          {lang === 'ar' ? 'جودة عالية، يستغرق وقتاً أطول' : 'Higher quality, takes longer'}
                        </Text>
                      </VStack>
                    </Radio>
                  </Stack>
                </RadioGroup>
              </FormControl>

              <FormControl>
                <FormLabel color="#ECECF1" fontSize="sm">
                  {lang === 'ar' ? 'وضع الأمان' : 'Safety Mode'}
                </FormLabel>
                <RadioGroup value={imageSafetyMode} onChange={(val) => setImageSafetyMode(val as any)}>
                  <Stack spacing={2}>
                    <Radio value="strict" colorScheme="green">
                      <VStack align="start" spacing={0}>
                        <Text color="#ECECF1" fontSize="sm">
                          {lang === 'ar' ? 'صارم' : 'Strict'}
                        </Text>
                        <Text color="#9aa0b4" fontSize="xs">
                          {lang === 'ar' ? 'فلترة محتوى قوية' : 'Strong content filtering'}
                        </Text>
                      </VStack>
                    </Radio>
                    <Radio value="moderate" colorScheme="green">
                      <Text color="#ECECF1" fontSize="sm">
                        {lang === 'ar' ? 'متوسط' : 'Moderate'}
                      </Text>
                    </Radio>
                    <Radio value="permissive" colorScheme="green">
                      <Text color="#ECECF1" fontSize="sm">
                        {lang === 'ar' ? 'متساهل' : 'Permissive'}
                      </Text>
                    </Radio>
                  </Stack>
                </RadioGroup>
              </FormControl>

              <Box bg="#0f1420" p={3} borderRadius="md" border="1px solid #232735">
                <VStack align="start" spacing={1}>
                  <Text color="#10b981" fontSize="xs" fontWeight="bold">
                    {lang === 'ar' ? 'كيفية الاستخدام:' : 'How to use:'}
                  </Text>
                  <Text color="#9aa0b4" fontSize="xs">
                    {lang === 'ar' 
                      ? 'اكتب "أنشئ صورة..." أو "generate image..." في الشات'
                      : 'Type "generate image..." or "create image..." in chat'}
                  </Text>
                  <Text color="#9aa0b4" fontSize="xs">
                    {lang === 'ar'
                      ? 'مثال: "أنشئ صورة لشاحنة توصيل بعلامة Speedy ليلاً"'
                      : 'Example: "generate image of a delivery van with Speedy branding at night"'}
                  </Text>
                </VStack>
              </Box>
            </VStack>
          </ModalBody>
          <ModalFooter>
            <Button 
              colorScheme="blue" 
              onClick={() => setAiSettingsOpen(false)}
            >
              {lang === 'ar' ? 'حفظ' : 'Save'}
            </Button>
          </ModalFooter>
        </ModalContent>
      </Modal>
    </Box>
  );
}

'use client';

import React, { useEffect, useMemo, useRef, useState } from 'react';
import {
  Box,
  Card,
  CardBody,
  HStack,
  VStack,
  Text,
  IconButton,
  Textarea,
  Button,
  Badge,
  Select,
  Avatar,
  Drawer,
  DrawerOverlay,
  DrawerContent,
  DrawerHeader,
  DrawerBody,
  useToast,
} from '@chakra-ui/react';
import { FiMessageCircle, FiSend, FiX, FiZap, FiDownload, FiBarChart2 } from 'react-icons/fi';

type Lang = 'en' | 'ar';

interface Message {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  ts: Date;
}

interface AssistantMetadata {
  requestId: string;
  processingTimeMs?: number;
  liveStats?: any;
  driverAvailability?: any;
  predictiveAnalytics?: any;
  proactiveSuggestions?: any;
  references?: { orders: string[]; routes: string[] };
}

export default function AdminChatWidgetMinimal({
  adminName = 'Admin',
  adminEmail = '',
}: {
  adminName?: string;
  adminEmail?: string;
}) {
  const [open, setOpen] = useState(false);
  const [fullscreen, setFullscreen] = useState(false);
  const [lang, setLang] = useState<Lang>('en');
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [messages, setMessages] = useState<Message[]>([]);
  const [metadata, setMetadata] = useState<AssistantMetadata | null>(null);
  const [showInsights, setShowInsights] = useState(false);
  const [liveFeed, setLiveFeed] = useState<Array<{ id: string; title: string; createdAt: string }>>([]);
  const endRef = useRef<HTMLDivElement>(null);
  const toast = useToast();

  useEffect(() => {
    endRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, loading]);

  // Global open/close events so header button can control the widget
  useEffect(() => {
    const onOpen = () => {
      setOpen(true);
      setFullscreen(true); // Always open in fullscreen when triggered from header
    };
    const onClose = () => {
      setOpen(false);
      setFullscreen(false);
    };
    window.addEventListener('sv-ai-open', onOpen as EventListener);
    window.addEventListener('sv-ai-close', onClose as EventListener);
    return () => {
      window.removeEventListener('sv-ai-open', onOpen as EventListener);
      window.removeEventListener('sv-ai-close', onClose as EventListener);
    };
  }, []);

  // Poll live notifications as "Live Lane"
  useEffect(() => {
    let cancelled = false;
    const load = async () => {
      try {
        const res = await fetch('/api/admin/ai/notifications');
        if (!res.ok) return;
        const data = await res.json();
        if (!cancelled) {
          const items = Array.isArray(data.items)
            ? data.items.map((x: any) => ({
                id: String(x.id || x._id || x.createdAt || Math.random()),
                title: x.title || x.message || x.text || 'Notification',
                createdAt: x.createdAt || new Date().toISOString(),
              }))
            : [];
          setLiveFeed(items.slice(0, 10));
        }
      } catch {
        // ignore
      }
    };
    load();
    const t = setInterval(load, 30000);
    return () => {
      cancelled = true;
      clearInterval(t);
    };
  }, []);

  const placeholder = useMemo(
    () => (lang === 'ar' ? 'اكتب رسالتك...' : 'Type your message...'),
    [lang]
  );

  const send = async () => {
    if (loading || !input.trim()) return;
    const content = input.trim();
    setInput('');

    const userMsg: Message = { id: String(Date.now()), role: 'user', content, ts: new Date() };
    const streamId = String(Date.now() + 1);
    const aiMsg: Message = { id: streamId, role: 'assistant', content: '', ts: new Date() };
    setMessages((prev) => [...prev, userMsg, aiMsg]);
    setLoading(true);
    setMetadata(null);

    try {
      const body = JSON.stringify({
        message: content,
        conversationHistory: [...messages, userMsg].map((m) => ({
          role: m.role,
          content: m.content,
          message: m.content,
        })),
        language: lang,
        mode: 'stream',
      });
      const res = await fetch('/api/admin/ai/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body,
      });
      if (!res.ok || !res.body) throw new Error('Chat API error');

      const reader = res.body.getReader();
      const decoder = new TextDecoder();
      let buffer = '';
      let aggregate = '';
      let meta: AssistantMetadata | null = null;
      let finalLang: Lang = lang;

      const apply = (content: string) => {
        setMessages((prev) => prev.map((m) => (m.id === streamId ? { ...m, content } : m)));
      };

      const handleLine = (line: string) => {
        if (!line) return;
        try {
          const payload = JSON.parse(line);
          if (payload.event === 'token') {
            const token = typeof payload.data === 'string' ? payload.data : '';
            aggregate += token;
            apply(aggregate);
          } else if (payload.event === 'final') {
            const data = payload.data || {};
            if (typeof data.response === 'string') {
              aggregate = data.response;
              apply(aggregate);
            }
            if (data.language === 'en' || data.language === 'ar') {
              finalLang = data.language;
              setLang(finalLang);
            }
            if (data.metadata) {
              meta = {
                ...(data.metadata as AssistantMetadata),
                processingTimeMs:
                  typeof data.processingTimeMs === 'number'
                    ? data.processingTimeMs
                    : undefined,
              };
            }
          }
        } catch {
          // ignore malformed chunks
        }
      };

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;
        buffer += decoder.decode(value, { stream: true });
        let idx: number;
        while ((idx = buffer.indexOf('\n')) >= 0) {
          const line = buffer.slice(0, idx).trim();
          buffer = buffer.slice(idx + 1);
          if (line) handleLine(line);
        }
      }
      if (buffer.trim()) handleLine(buffer.trim());
      if (!aggregate) {
        aggregate = finalLang === 'ar' ? 'تمت المعالجة.' : 'Processed.';
        apply(aggregate);
      }
      if (meta) setMetadata(meta);
    } catch (e: any) {
      const err = lang === 'ar' ? 'حدث خطأ. حاول لاحقاً.' : 'An error occurred. Please try again.';
      setMessages((prev) => prev.map((m) => (m.id === streamId ? { ...m, content: err } : m)));
      toast({ title: 'Error', description: e?.message || err, status: 'error' });
    } finally {
      setLoading(false);
    }
  };

  const exportTxt = () => {
    const txt = messages
      .map((m) => `[${m.ts.toLocaleString()}] ${m.role === 'user' ? adminName : 'Speedy AI'}:\n${m.content}\n`)
      .join('\n---\n\n');
    const blob = new Blob([txt], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `speedy-ai-${new Date().toISOString().slice(0, 10)}.txt`;
    a.click();
    URL.revokeObjectURL(url);
  };

  if (!open) {
    // No floating opener; controlled by header button via events
    return null;
  }

  return (
    <>
      {fullscreen && (
        <Box
          position="fixed"
          top={0}
          left={0}
          right={0}
          bottom={0}
          bg="rgba(0,0,0,0.6)"
          zIndex={999}
        />
      )}
      <Card
        position="fixed"
        {...(fullscreen
          ? { top: 0, left: 0, right: 0, bottom: 0, width: '100vw', height: '100vh' }
          : { bottom: '20px', right: '20px', width: '360px', height: '520px' })}
        zIndex={1000}
        borderRadius={fullscreen ? '0' : 'lg'}
        bg="#1b1e27"
        border={fullscreen ? 'none' : '1px solid #2a2f3a'}
        boxShadow={fullscreen ? 'none' : '0 20px 50px rgba(0,0,0,0.55)'}
        display="flex"
        flexDirection="column"
        overflow="hidden"
      >
        <CardBody p={0} borderBottom="1px solid #2a2f3a" bg="#171923">
          <HStack justify="space-between" p={3}>
            <HStack>
              <Avatar size="sm" bg="#2563eb" icon={<FiZap />} />
              <VStack align="start" spacing={0}>
                <HStack>
                  <Text fontSize="sm" fontWeight="bold" color="#ECECF1">
                    Speedy AI
                  </Text>
                  <Badge colorScheme="green" borderRadius="full">
                    {lang === 'ar' ? 'متصل' : 'Online'}
                  </Badge>
                </HStack>
                <Text fontSize="xs" color="#9ca3af">
                  {lang === 'ar' ? 'مساعدك الذكي' : 'Your assistant'}
                </Text>
              </VStack>
            </HStack>
            <HStack>
              <Select
                size="xs"
                value={lang}
                onChange={(e) => setLang(e.target.value as Lang)}
                width="70px"
                bg="#232735"
                color="#ECECF1"
                borderColor="#2a2f3a"
              >
                <option value="en" style={{ background: '#1b1e27', color: '#fff' }}>
                  EN
                </option>
                <option value="ar" style={{ background: '#1b1e27', color: '#fff' }}>
                  AR
                </option>
              </Select>
              <IconButton
                aria-label="Insights"
                icon={<FiBarChart2 />}
                size="sm"
                variant="ghost"
                color="#ECECF1"
                onClick={() => setShowInsights(true)}
              />
              <IconButton
                aria-label="Export"
                icon={<FiDownload />}
                size="sm"
                variant="ghost"
                color="#ECECF1"
                onClick={exportTxt}
                isDisabled={messages.length === 0}
              />
              <IconButton
                aria-label="Close"
                icon={<FiX />}
                size="sm"
                variant="ghost"
                color="#ECECF1"
                onClick={() => {
                  setOpen(false);
                  setFullscreen(false);
                }}
              />
            </HStack>
          </HStack>
        </CardBody>

        <Box flex={1} overflowY="auto" p={3} bg="#1b1e27">
          <VStack align="stretch" spacing={3}>
            {messages.map((m) => (
              <HStack key={m.id} justify={m.role === 'user' ? 'flex-end' : 'flex-start'}>
                {m.role === 'assistant' && <Avatar size="xs" bg="#2563eb" icon={<FiZap />} />}
                <Box
                  maxW="80%"
                  bg={m.role === 'user' ? '#2a2f3a' : '#242836'}
                  color="#ECECF1"
                  borderRadius="md"
                  px={3}
                  py={2}
                  border="1px solid #2a2f3a"
                >
                  <Text fontSize="sm" whiteSpace="pre-wrap">
                    {m.content}
                  </Text>
                </Box>
                {m.role === 'user' && <Avatar size="xs" bg="#4b5563" />}
              </HStack>
            ))}
            {loading && (
              <Text fontSize="xs" color="#9ca3af">
                {lang === 'ar' ? 'جاري الكتابة...' : 'Typing...'}
              </Text>
            )}
            <div ref={endRef} />
          </VStack>
        </Box>

        <CardBody p={3} borderTop="1px solid #2a2f3a" bg="#171923">
          <HStack align="flex-end">
            <Textarea
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter' && !e.shiftKey) {
                  e.preventDefault();
                  send();
                }
              }}
              placeholder={placeholder}
              rows={2}
              resize="none"
              bg="#000000"
              color="#FFFFFF"
              borderColor="#333333"
              _placeholder={{ color: '#9AA0B4' }}
              fontSize="sm"
              css={{ caretColor: '#FFFFFF' }}
            />
            <IconButton
              aria-label="Send"
              icon={<FiSend color="#fff" />}
              bg="#10b981"
              color="#fff"
              onClick={send}
              isDisabled={!input.trim() || loading}
              _hover={{ bg: '#059669' }}
            />
          </HStack>
        </CardBody>
      </Card>

      <Drawer isOpen={showInsights} placement="right" onClose={() => setShowInsights(false)}>
        <DrawerOverlay />
        <DrawerContent bg="#1b1e27" borderLeft="1px solid #2a2f3a">
          <DrawerHeader color="#ECECF1" borderBottom="1px solid #2a2f3a">
            {lang === 'ar' ? 'رؤى الذكاء الاصطناعي' : 'AI Insights'}
          </DrawerHeader>
          <DrawerBody>
            {metadata ? (
              <VStack align="stretch" spacing={3} color="#ECECF1">
                <Text fontSize="sm">
                  {lang === 'ar' ? 'رقم الطلب' : 'Request'}: {metadata.requestId?.slice(0, 8)}
                </Text>
                {typeof metadata.processingTimeMs === 'number' && (
                  <Text fontSize="sm">
                    {lang === 'ar' ? 'زمن المعالجة' : 'Processing'}: {metadata.processingTimeMs} ms
                  </Text>
                )}
                <Text fontSize="sm" color="#9ca3af">
                  {lang === 'ar'
                    ? 'اعرض نظرة عامة من البوت للحصول على تفاصيل النظام والسائقين والتوقعات.'
                    : 'Ask the bot for an overview to populate system, drivers and forecast details.'}
                </Text>
                <Box mt={2}>
                  <Text fontSize="sm" fontWeight="bold" mb={2}>
                    {lang === 'ar' ? 'تغذية مباشرة' : 'Live Lane'}
                  </Text>
                  <VStack align="stretch" spacing={1}>
                    {liveFeed.length === 0 ? (
                      <Text fontSize="xs" color="#9ca3af">
                        {lang === 'ar' ? 'لا يوجد عناصر حالياً.' : 'No items yet.'}
                      </Text>
                    ) : (
                      liveFeed.map((it) => (
                        <HStack key={it.id} justify="space-between">
                          <Text fontSize="sm">{it.title}</Text>
                          <Text fontSize="xs" color="#9ca3af">
                            {new Date(it.createdAt).toLocaleTimeString()}
                          </Text>
                        </HStack>
                      ))
                    )}
                  </VStack>
                </Box>
              </VStack>
            ) : (
              <Text fontSize="sm" color="#9ca3af">
                {lang === 'ar' ? 'لا توجد بيانات حالياً.' : 'No data yet.'}
              </Text>
            )}
          </DrawerBody>
        </DrawerContent>
      </Drawer>
    </>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import {
  Box,
  VStack,
  HStack,
  Text,
  Button,
  Card,
  CardBody,
  CardHeader,
  Heading,
  Badge,
  SimpleGrid,
  Stat,
  StatLabel,
  StatNumber,
  StatHelpText,
  useToast,
  useColorModeValue,
  Spinner,
  Alert,
  AlertIcon,
  Progress,
  Container,
} from '@chakra-ui/react';
import FallingText from '@/components/shared/FallingText';
import {
  FiTruck,
  FiDollarSign,
  FiUsers,
  FiClock,
  FiTrendingUp,
  FiTrendingDown,
  FiRefreshCw,
  FiAlertTriangle,
  FiCheckCircle,
} from 'react-icons/fi';

interface DashboardStats {
  totalOrders: number;
  activeOrders: number;
  completedOrders: number;
  totalRevenue: number;
  revenueChange: number;
  activeDrivers: number;
  totalCustomers: number;
  avgResponseTime: string;
  systemHealth: 'healthy' | 'warning' | 'error';
}

interface AdminDashboardProps {
  data?: any;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ data }) => {
  const [stats, setStats] = useState<DashboardStats | null>(null);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const toast = useToast();
  
  // Match booking-luxury design - dark theme
  const bgGradient = 'linear(to-br, gray.900, blue.900)';
  const cardBg = useColorModeValue('whiteAlpha.100', 'whiteAlpha.50');
  const borderColor = useColorModeValue('whiteAlpha.200', 'whiteAlpha.100');
  const textColor = useColorModeValue('white', 'white');

  useEffect(() => {
    fetchDashboardStats();
  }, []);

  const fetchDashboardStats = async (showRefreshing = false) => {
    if (showRefreshing) {
      setRefreshing(true);
    }
    try {
      const response = await fetch('/api/admin/dashboard');
      if (!response.ok) {
        throw new Error('Failed to fetch dashboard stats');
      }
      const data = await response.json();
      setStats(data);
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to load dashboard data',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  };

  const getHealthColor = (health: string) => {
    switch (health) {
      case 'healthy':
        return 'green';
      case 'warning':
        return 'yellow';
      case 'error':
        return 'red';
      default:
        return 'gray';
    }
  };

  const getHealthIcon = (health: string) => {
    switch (health) {
      case 'healthy':
        return FiCheckCircle;
      case 'warning':
        return FiAlertTriangle;
      case 'error':
        return FiAlertTriangle;
      default:
        return FiAlertTriangle;
    }
  };

  if (loading) {
    return (
      <Box
        minH="100vh"
        bgGradient={bgGradient}
        display="flex"
        justifyContent="center"
        alignItems="center"
      >
        <VStack spacing={4}>
          <Spinner size="xl" color="blue.400" thickness="4px" />
          <Text color="white" fontSize="lg">Loading Dashboard...</Text>
        </VStack>
      </Box>
    );
  }

  if (!stats) {
    return (
      <Box minH="100vh" bgGradient={bgGradient} py={8}>
        <Container maxW="container.xl">
          <Alert
            status="error"
            bg="red.900"
            color="white"
            borderRadius="lg"
            borderWidth="1px"
            borderColor="red.700"
          >
            <AlertIcon color="red.300" />
            Failed to load dashboard data. Please try refreshing.
          </Alert>
        </Container>
      </Box>
    );
  }

  return (
    <Box minH="100vh" bgGradient={bgGradient}>
      <Container maxW="container.xl" py={8}>
        {/* Header */}
        <HStack justify="space-between" mb={8} align="center">
          <VStack align="start" spacing={1}>
            <FallingText text="Speedy Van Admin Panel" />
            <Text color="whiteAlpha.800">Overview of system performance and operations</Text>
          </VStack>
          <Button
            leftIcon={<FiRefreshCw />}
            onClick={() => fetchDashboardStats(true)}
            isLoading={refreshing}
            size="md"
            colorScheme="blue"
            variant="solid"
            bg="blue.500"
            _hover={{ bg: 'blue.600' }}
          >
            Refresh
          </Button>
        </HStack>

        {/* System Health Alert */}
        {stats?.systemHealth && stats.systemHealth !== 'healthy' && (
          <Alert
            status={stats.systemHealth === 'error' ? 'error' : 'warning'}
            mb={6}
            bg={stats.systemHealth === 'error' ? 'red.900' : 'yellow.900'}
            color="white"
            borderRadius="lg"
            borderWidth="1px"
            borderColor={stats.systemHealth === 'error' ? 'red.700' : 'yellow.700'}
          >
            <AlertIcon color={stats.systemHealth === 'error' ? 'red.300' : 'yellow.300'} />
            <Box>
              <Text fontWeight="medium">
                System Health: {(stats.systemHealth || 'unknown').toUpperCase()}
              </Text>
              <Text fontSize="sm">
                {stats.systemHealth === 'error' 
                  ? 'Critical issues detected. Immediate attention required.'
                  : 'Some services may be experiencing issues.'
                }
              </Text>
            </Box>
          </Alert>
        )}

        {/* Stats Grid */}
        <SimpleGrid columns={{ base: 1, md: 2, lg: 4 }} spacing={6} mb={8}>
          <Card bg={cardBg} backdropFilter="blur(10px)" borderWidth="1px" borderColor={borderColor}>
            <CardBody>
              <Stat>
                <StatLabel color="whiteAlpha.800">Total Orders</StatLabel>
                <StatNumber color="white" fontSize="3xl">{(stats?.totalOrders || 0).toLocaleString()}</StatNumber>
                <StatHelpText color="whiteAlpha.700">
                  <HStack spacing={1}>
                    <FiTruck />
                    <Text>All time</Text>
                  </HStack>
                </StatHelpText>
              </Stat>
            </CardBody>
          </Card>

          <Card bg={cardBg} backdropFilter="blur(10px)" borderWidth="1px" borderColor={borderColor}>
            <CardBody>
              <Stat>
                <StatLabel color="whiteAlpha.800">Active Orders</StatLabel>
                <StatNumber color="blue.300" fontSize="3xl">{stats?.activeOrders || 0}</StatNumber>
                <StatHelpText color="whiteAlpha.700">
                  <HStack spacing={1}>
                    <FiClock />
                    <Text>In progress</Text>
                  </HStack>
                </StatHelpText>
              </Stat>
            </CardBody>
          </Card>

          <Card bg={cardBg} backdropFilter="blur(10px)" borderWidth="1px" borderColor={borderColor}>
            <CardBody>
              <Stat>
                <StatLabel color="whiteAlpha.800">Total Revenue</StatLabel>
                <StatNumber color="white" fontSize="3xl">£{(stats?.totalRevenue || 0).toLocaleString()}</StatNumber>
                <StatHelpText color="whiteAlpha.700">
                  <HStack spacing={1}>
                    {(stats?.revenueChange || 0) >= 0 ? (
                      <FiTrendingUp color="lightgreen" />
                    ) : (
                      <FiTrendingDown color="salmon" />
                    )}
                    <Text color={(stats?.revenueChange || 0) >= 0 ? 'green.300' : 'red.300'}>
                      {(stats?.revenueChange || 0) >= 0 ? '+' : ''}{stats?.revenueChange || 0}%
                    </Text>
                  </HStack>
                </StatHelpText>
              </Stat>
            </CardBody>
          </Card>

          <Card bg={cardBg} backdropFilter="blur(10px)" borderWidth="1px" borderColor={borderColor}>
            <CardBody>
              <Stat>
                <StatLabel color="whiteAlpha.800">Active Drivers</StatLabel>
                <StatNumber color="white" fontSize="3xl">{stats?.activeDrivers || 0}</StatNumber>
                <StatHelpText color="whiteAlpha.700">
                  <HStack spacing={1}>
                    <FiUsers />
                    <Text>Online now</Text>
                  </HStack>
                </StatHelpText>
              </Stat>
            </CardBody>
          </Card>
        </SimpleGrid>

        {/* Additional Stats */}
        <SimpleGrid columns={{ base: 1, md: 2, lg: 3 }} spacing={6} mb={8}>
          <Card bg={cardBg} backdropFilter="blur(10px)" borderWidth="1px" borderColor={borderColor}>
            <CardBody>
              <Stat>
                <StatLabel color="whiteAlpha.800">Completed Orders</StatLabel>
                <StatNumber color="green.300" fontSize="2xl">{stats?.completedOrders || 0}</StatNumber>
                <StatHelpText color="whiteAlpha.700">
                  <HStack spacing={1}>
                    <FiCheckCircle />
                    <Text>Successfully delivered</Text>
                  </HStack>
                </StatHelpText>
              </Stat>
            </CardBody>
          </Card>

          <Card bg={cardBg} backdropFilter="blur(10px)" borderWidth="1px" borderColor={borderColor}>
            <CardBody>
              <Stat>
                <StatLabel color="whiteAlpha.800">Total Customers</StatLabel>
                <StatNumber color="white" fontSize="2xl">{(stats?.totalCustomers || 0).toLocaleString()}</StatNumber>
                <StatHelpText color="whiteAlpha.700">
                  <HStack spacing={1}>
                    <FiUsers />
                    <Text>Registered users</Text>
                  </HStack>
                </StatHelpText>
              </Stat>
            </CardBody>
          </Card>

          <Card bg={cardBg} backdropFilter="blur(10px)" borderWidth="1px" borderColor={borderColor}>
            <CardBody>
              <Stat>
                <StatLabel color="whiteAlpha.800">Avg Response Time</StatLabel>
                <StatNumber color="white" fontSize="2xl">{stats?.avgResponseTime || 'N/A'}</StatNumber>
                <StatHelpText color="whiteAlpha.700">
                  <HStack spacing={1}>
                    <FiClock />
                    <Text>Support tickets</Text>
                  </HStack>
                </StatHelpText>
              </Stat>
            </CardBody>
          </Card>
        </SimpleGrid>

        {/* System Health Status */}
        <Card bg={cardBg} backdropFilter="blur(10px)" borderWidth="1px" borderColor={borderColor}>
          <CardHeader>
            <HStack justify="space-between">
              <Heading size="md" color="white">System Health</Heading>
              <HStack spacing={2}>
                <Box as={getHealthIcon(stats?.systemHealth || 'unknown')} color="green.300" />
                <Badge colorScheme={getHealthColor(stats?.systemHealth || 'unknown')} fontSize="sm" px={3} py={1}>
                  {(stats?.systemHealth || 'unknown').toUpperCase()}
                </Badge>
              </HStack>
            </HStack>
          </CardHeader>
          <CardBody>
            <VStack spacing={4} align="stretch">
              <HStack justify="space-between" p={3} bg="gray.700" borderRadius="md">
                <Text color="white">Database</Text>
                <Badge colorScheme="green">Healthy</Badge>
              </HStack>
              <HStack justify="space-between" p={3} bg="gray.700" borderRadius="md">
                <Text color="white">API Services</Text>
                <Badge colorScheme="green">Healthy</Badge>
              </HStack>
              <HStack justify="space-between" p={3} bg="gray.700" borderRadius="md">
                <Text color="white">Payment Processing</Text>
                <Badge colorScheme="green">Healthy</Badge>
              </HStack>
              <HStack justify="space-between" p={3} bg="gray.700" borderRadius="md">
                <Text color="white">Real-time Tracking</Text>
                <Badge colorScheme="green">Healthy</Badge>
              </HStack>
            </VStack>
          </CardBody>
        </Card>
      </Container>
    </Box>
  );
};

export default AdminDashboard;

/**
 * Admin Dashboard Controls Component
 * 
 * Real-time monitoring interface with emergency controls,
 * route intervention capabilities, and system health monitoring
 */

'use client';

import React, { useState, useEffect, useCallback } from 'react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';

import { 
  AlertTriangle, 
  Play, 
  Pause, 
  Radio, 
  Route, 
  Users, 
  Activity,
  RefreshCw,
  Bell,
  Shield,
  Zap,
  CheckCircle,
  XCircle,
  Clock,
  MapPin,
  TrendingUp,
  Settings
} from 'lucide-react';

interface AdminDashboardControlsProps {
  adminId: string;
  onEmergencyAction?: (action: string, result: any) => void;
}

interface RouteMonitoring {
  id: string;
  status: 'active' | 'delayed' | 'intervention_required';
  driverId: string;
  pickupLocation: string;
  dropoffLocation: string;
  estimatedArrival: Date;
  actualProgress: number;
  delayMinutes: number;
}

interface DriverMetrics {
  driverId: string;
  name: string;
  status: 'active' | 'offline' | 'emergency' | 'on_break';
  currentLocation: string;
  activeRoute: string | null;
  todayEarnings: number;
  todayDeliveries: number;
  avgDeliveryTime: number;
  customerRating: number;
  lastActive: Date;
}

interface SystemAlert {
  id: string;
  type: 'critical' | 'warning' | 'info';
  message: string;
  acknowledged: boolean;
  timestamp: Date;
}

interface SystemHealthMetrics {
  api: { status: string; uptime: number; responseTime: number };
  database: { status: string; uptime: number; queryTime: number };
  websocket: { status: string; uptime: number; connections: number };
  infrastructure: { cpuUsage: number; memoryUsage: number; diskSpace: number };
}

const AdminDashboardControls: React.FC<AdminDashboardControlsProps> = ({
  adminId,
  onEmergencyAction
}) => {
  // State management
  const [activeSection, setActiveSection] = useState<string>('overview');
  const [routes, setRoutes] = useState<RouteMonitoring[]>([]);
  const [drivers, setDrivers] = useState<DriverMetrics[]>([]);
  const [alerts, setAlerts] = useState<SystemAlert[]>([]);
  const [systemHealth, setSystemHealth] = useState<SystemHealthMetrics | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [emergencyMode, setEmergencyMode] = useState(false);
  const [lastUpdate, setLastUpdate] = useState<Date | null>(null);

  // Emergency action states
  const [showEmergencyControls, setShowEmergencyControls] = useState(false);
  const [emergencyAction, setEmergencyAction] = useState('');
  const [actionInProgress, setActionInProgress] = useState(false);
  const [emergencyMessage, setEmergencyMessage] = useState('');
  const [broadcastTarget, setBroadcastTarget] = useState('all_drivers');
  const [selectedRoute, setSelectedRoute] = useState('');
  const [selectedDriver, setSelectedDriver] = useState('');
  const [showEmergencyDialog, setShowEmergencyDialog] = useState(false);

  // Fetch dashboard data
  const fetchDashboardData = useCallback(async (section: string = 'overview') => {
    setIsLoading(true);
    try {
      const response = await fetch(`/api/admin/dashboard?section=${section}&realtime=true`);
      const data = await response.json();
      
      if (data.success) {
        switch (section) {
          case 'routes':
            setRoutes(data.data.routes || []);
            break;
          case 'drivers':
            setDrivers(data.data.drivers || []);
            break;
          case 'alerts':
            setAlerts(data.data.alerts || []);
            break;
          case 'system_health':
            setSystemHealth(data.data.health);
            break;
        }
        setLastUpdate(new Date());
      }
    } catch (error) {
      console.error('Failed to fetch dashboard data:', error);
    } finally {
      setIsLoading(false);
    }
  }, []);

  // Execute emergency action
  const executeEmergencyAction = async () => {
    if (!emergencyAction) return;

    const payload: any = {
      action: emergencyAction,
      adminId,
      reason: `Emergency action executed from dashboard`,
      target: {}
    };

    // Build target based on action type
    switch (emergencyAction) {
      case 'emergency_broadcast':
        if (!emergencyMessage) {
          alert('Message is required for emergency broadcast');
          return;
        }
        payload.target = {
          message: emergencyMessage,
          broadcastTarget
        };
        break;
      
      case 'route_reassignment':
        if (!selectedRoute || !selectedDriver) {
          alert('Route ID and driver are required for reassignment');
          return;
        }
        payload.target = {
          routeId: selectedRoute,
          newDriverId: selectedDriver
        };
        break;
    }

    setIsLoading(true);
    try {
      const response = await fetch('/api/admin/dashboard', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });

      const result = await response.json();
      
      if (result.success) {
        setShowEmergencyDialog(false);
        setEmergencyMessage('');
        setSelectedRoute('');
        setSelectedDriver('');
        
        if (onEmergencyAction) {
          onEmergencyAction(emergencyAction, result.data);
        }
        
        // Refresh relevant section
        if (emergencyAction === 'route_reassignment') {
          fetchDashboardData('routes');
        }
        fetchDashboardData('alerts');
      } else {
        alert(`Emergency action failed: ${result.error}`);
      }
    } catch (error) {
      console.error('Emergency action failed:', error);
      alert('Emergency action failed. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  // Auto-refresh data
  useEffect(() => {
    fetchDashboardData(activeSection);
    
    // Set up auto-refresh every 30 seconds for real-time monitoring
    const interval = setInterval(() => {
      fetchDashboardData(activeSection);
    }, 30000);

    return () => clearInterval(interval);
  }, [activeSection, fetchDashboardData]);

  // Emergency Controls Panel
  const EmergencyControlsPanel = () => (
    <Card className="border-red-200 bg-red-50">
      <CardHeader>
        <CardTitle className="flex items-center gap-2 text-red-700">
          <Shield className="w-5 h-5" />
          Emergency Controls
        </CardTitle>
        <CardDescription className="text-red-600">
          Critical system controls for emergency interventions
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-4">
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          <Button 
            variant={emergencyMode ? "destructive" : "outline"}
            className="w-full"
            onClick={() => executeEmergencyAction()}
          >
            <Pause className="w-4 h-4 mr-2" />
            {emergencyMode ? 'Resume' : 'Pause'} System
          </Button>

          <Button 
            variant="outline" 
            onClick={() => executeEmergencyAction()}
          >
            <Radio className="w-4 h-4 mr-2" />
            Broadcast
          </Button>
          
          <Button 
            variant="outline"
            onClick={() => fetchDashboardData(activeSection)}
            disabled={isLoading}
          >
            {isLoading ? (
              <RefreshCw className="w-4 h-4 mr-2 animate-spin" />
            ) : (
              <RefreshCw className="w-4 h-4 mr-2" />
            )}
            Refresh
          </Button>

          <Button variant="outline">
            <Settings className="w-4 h-4 mr-2" />
            Settings
          </Button>
        </div>

        {lastUpdate && (
          <p className="text-sm text-gray-500">
            Last updated: {lastUpdate.toLocaleTimeString()}
          </p>
        )}
      </CardContent>
    </Card>
  );

  // Route Monitoring View
  const RouteMonitoringView = () => (
    <div className="space-y-4">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium">Active Routes</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-green-600">
              {routes.filter(r => r.status === 'active').length}
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium">Delayed Routes</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-orange-600">
              {routes.filter(r => r.status === 'delayed').length}
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium">Need Intervention</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-red-600">
              {routes.filter(r => r.status === 'intervention_required').length}
            </div>
          </CardContent>
        </Card>
      </div>

      <Card>
        <CardHeader>
          <CardTitle>Live Route Monitoring</CardTitle>
          <CardDescription>Real-time tracking of all active routes</CardDescription>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            {routes.map(route => (
              <div 
                key={route.id}
                className={`p-4 border rounded-lg ${
                  route.status === 'intervention_required' ? 'border-red-300 bg-red-50' :
                  route.status === 'delayed' ? 'border-orange-300 bg-orange-50' :
                  'border-green-300 bg-green-50'
                }`}
              >
                <div className="flex justify-between items-start">
                  <div className="space-y-2">
                    <div className="flex items-center gap-2">
                      <Badge 
                        variant={
                          route.status === 'active' ? 'default' :
                          route.status === 'delayed' ? 'secondary' : 'destructive'
                        }
                      >
                        {route.status.replace('_', ' ').toUpperCase()}
                      </Badge>
                      {route.delayMinutes > 0 && (
                        <Badge variant="outline" className="text-orange-600">
                          <Clock className="w-3 h-3 mr-1" />
                          {route.delayMinutes}min delay
                        </Badge>
                      )}
                    </div>
                    
                    <div className="flex items-center gap-2 text-sm text-gray-600">
                      <MapPin className="w-4 h-4" />
                      {route.pickupLocation} → {route.dropoffLocation}
                    </div>
                    
                    <div className="text-sm text-gray-500">
                      Driver: {route.driverId} | Progress: {route.actualProgress}%
                    </div>
                  </div>

                  {route.status === 'intervention_required' && (
                    <Button 
                      size="sm" 
                      variant="destructive"
                      onClick={() => {
                        setSelectedRoute(route.id);
                        setEmergencyAction('route_reassignment');
                        setShowEmergencyDialog(true);
                      }}
                    >
                      <AlertTriangle className="w-4 h-4 mr-2" />
                      Intervene
                    </Button>
                  )}
                </div>
              </div>
            ))}
          </div>
        </CardContent>
      </Card>
    </div>
  );

  // Driver Performance View
  const DriverPerformanceView = () => (
    <div className="space-y-4">
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium">Active Drivers</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-green-600">
              {drivers.filter(d => d.status === 'active').length}
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium">Offline</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-gray-600">
              {drivers.filter(d => d.status === 'offline').length}
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium">On Break</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-blue-600">
              {drivers.filter(d => d.status === 'on_break').length}
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium">Emergency Status</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-red-600">
              {drivers.filter(d => d.status === 'emergency').length}
            </div>
          </CardContent>
        </Card>
      </div>

      <Card>
        <CardHeader>
          <CardTitle>Driver Performance Metrics</CardTitle>
          <CardDescription>Real-time driver status and performance</CardDescription>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            {drivers.map(driver => (
              <div 
                key={driver.driverId}
                className={`p-4 border rounded-lg ${
                  driver.status === 'emergency' ? 'border-red-300 bg-red-50' :
                  driver.status === 'active' ? 'border-green-300 bg-green-50' :
                  'border-gray-300 bg-gray-50'
                }`}
              >
                <div className="flex justify-between items-start">
                  <div className="space-y-2">
                    <div className="flex items-center gap-2">
                      <span className="font-medium">{driver.name}</span>
                      <Badge 
                        variant={
                          driver.status === 'active' ? 'default' :
                          driver.status === 'emergency' ? 'destructive' :
                          driver.status === 'on_break' ? 'secondary' : 'outline'
                        }
                      >
                        {driver.status.replace('_', ' ').toUpperCase()}
                      </Badge>
                    </div>
                    
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-sm">
                      <div>
                        <span className="text-gray-500">Today Earnings:</span>
                        <div className="font-medium">£{driver.todayEarnings.toFixed(2)}</div>
                      </div>
                      <div>
                        <span className="text-gray-500">Deliveries:</span>
                        <div className="font-medium">{driver.todayDeliveries}</div>
                      </div>
                      <div>
                        <span className="text-gray-500">Avg Time:</span>
                        <div className="font-medium">{driver.avgDeliveryTime}min</div>
                      </div>
                      <div>
                        <span className="text-gray-500">Rating:</span>
                        <div className="font-medium">⭐ {driver.customerRating.toFixed(1)}</div>
                      </div>
                    </div>
                    
                    <div className="text-sm text-gray-500">
                      Location: {driver.currentLocation} | 
                      Last Active: {new Date(driver.lastActive).toLocaleTimeString()}
                    </div>
                  </div>

                  {driver.status === 'emergency' && (
                    <Button 
                      size="sm" 
                      variant="destructive"
                      onClick={() => {
                        setEmergencyAction('emergency_broadcast');
                        setBroadcastTarget('specific_drivers');
                        setShowEmergencyDialog(true);
                      }}
                    >
                      <Bell className="w-4 h-4 mr-2" />
                      Contact
                    </Button>
                  )}
                </div>
              </div>
            ))}
          </div>
        </CardContent>
      </Card>
    </div>
  );

  // System Health View
  const SystemHealthView = () => (
    <div className="space-y-4">
      {systemHealth && (
        <>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <Card>
              <CardHeader className="pb-2">
                <CardTitle className="text-sm font-medium flex items-center gap-2">
                  <Activity className="w-4 h-4" />
                  API Health
                </CardTitle>
              </CardHeader>
              <CardContent>
                <div className="space-y-2">
                  <div className="flex items-center gap-2">
                    {systemHealth.api.uptime > 99.5 ? (
                      <CheckCircle className="w-4 h-4 text-green-600" />
                    ) : (
                      <XCircle className="w-4 h-4 text-red-600" />
                    )}
                    <span className="font-medium">
                      {systemHealth.api.uptime > 99.5 ? 'Healthy' : 'Issues Detected'}
                    </span>
                  </div>
                  <div className="text-sm text-gray-500">
                    Uptime: {systemHealth.api.uptime}% | Response: {systemHealth.api.responseTime}ms
                  </div>
                </div>
              </CardContent>
            </Card>

            <Card>
              <CardHeader className="pb-2">
                <CardTitle className="text-sm font-medium flex items-center gap-2">
                  <Activity className="w-4 h-4" />
                  Database
                </CardTitle>
              </CardHeader>
              <CardContent>
                <div className="space-y-2">
                  <div className="flex items-center gap-2">
                    {systemHealth.database.uptime > 99.5 ? (
                      <CheckCircle className="w-4 h-4 text-green-600" />
                    ) : (
                      <XCircle className="w-4 h-4 text-red-600" />
                    )}
                    <span className="font-medium">
                      {systemHealth.database.uptime > 99.5 ? 'Healthy' : 'Issues Detected'}
                    </span>
                  </div>
                  <div className="text-sm text-gray-500">
                    Uptime: {systemHealth.database.uptime}% | Query: {systemHealth.database.queryTime}ms
                  </div>
                </div>
              </CardContent>
            </Card>

            <Card>
              <CardHeader className="pb-2">
                <CardTitle className="text-sm font-medium flex items-center gap-2">
                  <TrendingUp className="w-4 h-4" />
                  Infrastructure
                </CardTitle>
              </CardHeader>
              <CardContent>
                <div className="space-y-2">
                  <div className="flex items-center gap-2">
                    {systemHealth.infrastructure.cpuUsage < 80 ? (
                      <CheckCircle className="w-4 h-4 text-green-600" />
                    ) : (
                      <AlertTriangle className="w-4 h-4 text-orange-600" />
                    )}
                    <span className="font-medium">
                      {systemHealth.infrastructure.cpuUsage < 80 ? 'Healthy' : 'High Load'}
                    </span>
                  </div>
                  <div className="text-sm text-gray-500">
                    CPU: {systemHealth.infrastructure.cpuUsage}% | 
                    Memory: {systemHealth.infrastructure.memoryUsage}%
                  </div>
                </div>
              </CardContent>
            </Card>
          </div>
        </>
      )}
    </div>
  );

  // Alerts View
  const AlertsView = () => (
    <div className="space-y-4">
      <Card>
        <CardHeader>
          <CardTitle>System Alerts</CardTitle>
          <CardDescription>Active alerts and notifications requiring attention</CardDescription>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            {alerts.length === 0 ? (
              <div className="text-center py-8 text-gray-500">
                <CheckCircle className="w-8 h-8 mx-auto mb-2" />
                No active alerts
              </div>
            ) : (
              alerts.map(alert => (
                <Card 
                  key={alert.id}
                  className={
                    alert.type === 'critical' ? 'border-red-300 bg-red-50' :
                    alert.type === 'warning' ? 'border-orange-300 bg-orange-50' :
                    'border-blue-300 bg-blue-50'
                  }
                >
                  <CardContent className="pt-4">
                    <div className="flex justify-between items-center">
                      <div className="flex items-center gap-2">
                        <AlertTriangle className="h-4 w-4" />
                        <span>{alert.message}</span>
                      </div>
                      <div className="flex items-center gap-2">
                        <Badge 
                          variant={
                            alert.type === 'critical' ? 'destructive' :
                            alert.type === 'warning' ? 'secondary' : 'default'
                          }
                        >
                          {alert.type.toUpperCase()}
                        </Badge>
                        {!alert.acknowledged && (
                          <Button 
                            size="sm" 
                            variant="outline"
                            onClick={() => {
                              // Acknowledge alert logic
                            }}
                          >
                            Acknowledge
                          </Button>
                        )}
                      </div>
                    </div>
                  </CardContent>
                </Card>
              ))
            )}
          </div>
        </CardContent>
      </Card>
    </div>
  );

  return (
    <div className="space-y-6">
      {/* Emergency Controls Panel */}
      <EmergencyControlsPanel />

      {/* Main Dashboard Tabs */}
      <Tabs defaultValue={activeSection}>
        <TabsList className="grid w-full grid-cols-5">
          <TabsTrigger value="overview">Overview</TabsTrigger>
          <TabsTrigger value="routes">
            <Route className="w-4 h-4 mr-2" />
            Routes
          </TabsTrigger>
          <TabsTrigger value="drivers">
            <Users className="w-4 h-4 mr-2" />
            Drivers
          </TabsTrigger>
          <TabsTrigger value="system_health">
            <Activity className="w-4 h-4 mr-2" />
            System
          </TabsTrigger>
          <TabsTrigger value="alerts">
            <Bell className="w-4 h-4 mr-2" />
            Alerts
          </TabsTrigger>
        </TabsList>

        <TabsContent value="overview" className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            <RouteMonitoringView />
          </div>
        </TabsContent>

        <TabsContent value="routes">
          <RouteMonitoringView />
        </TabsContent>

        <TabsContent value="drivers">
          <DriverPerformanceView />
        </TabsContent>

        <TabsContent value="system_health">
          <SystemHealthView />
        </TabsContent>

        <TabsContent value="alerts">
          <AlertsView />
        </TabsContent>
      </Tabs>
    </div>
  );
};

export default AdminDashboardControls;

/**
 * Admin Dashboard Controls - Simplified Version
 * 
 * Real-time monitoring interface with emergency controls,
 * route intervention capabilities, and system health monitoring
 */

'use client';

import React, { useState, useEffect, useCallback } from 'react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { 
  AlertTriangle, 
  Pause, 
  Radio, 
  Route, 
  Users, 
  Activity,
  RefreshCw,
  Bell,
  Shield,
  CheckCircle,
  XCircle,
  Clock,
  MapPin,
  TrendingUp,
  Settings
} from 'lucide-react';

interface AdminDashboardControlsProps {
  adminId: string;
  onEmergencyAction?: (action: string, result: any) => void;
}

interface RouteMonitoring {
  id: string;
  status: 'active' | 'delayed' | 'intervention_required';
  driverId: string;
  pickupLocation: string;
  dropoffLocation: string;
  estimatedArrival: Date;
  actualProgress: number;
  delayMinutes: number;
}

interface DriverMetrics {
  driverId: string;
  name: string;
  status: 'active' | 'offline' | 'emergency' | 'on_break';
  currentLocation: string;
  activeRoute: string | null;
  todayEarnings: number;
  todayDeliveries: number;
  avgDeliveryTime: number;
  customerRating: number;
  lastActive: Date;
}

interface SystemAlert {
  id: string;
  type: 'critical' | 'warning' | 'info';
  message: string;
  acknowledged: boolean;
  timestamp: Date;
}

interface SystemHealthMetrics {
  api: { status: string; uptime: number; responseTime: number };
  database: { status: string; uptime: number; queryTime: number };
  websocket: { status: string; uptime: number; connections: number };
  infrastructure: { cpuUsage: number; memoryUsage: number; diskSpace: number };
}

const AdminDashboardControls: React.FC<AdminDashboardControlsProps> = ({
  adminId,
  onEmergencyAction
}) => {
  // State management
  const [activeSection, setActiveSection] = useState<string>('overview');
  const [routes, setRoutes] = useState<RouteMonitoring[]>([]);
  const [drivers, setDrivers] = useState<DriverMetrics[]>([]);
  const [alerts, setAlerts] = useState<SystemAlert[]>([]);
  const [systemHealth, setSystemHealth] = useState<SystemHealthMetrics | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [emergencyMode, setEmergencyMode] = useState(false);
  const [lastUpdate, setLastUpdate] = useState<Date | null>(null);

  // Fetch dashboard data
  const fetchDashboardData = useCallback(async (section: string = 'overview') => {
    setIsLoading(true);
    try {
      const response = await fetch(`/api/admin/dashboard?section=${section}&realtime=true`);
      const data = await response.json();
      
      if (data.success) {
        switch (section) {
          case 'routes':
            setRoutes(data.data.routes || []);
            break;
          case 'drivers':
            setDrivers(data.data.drivers || []);
            break;
          case 'alerts':
            setAlerts(data.data.alerts || []);
            break;
          case 'system_health':
            setSystemHealth(data.data.health);
            break;
        }
        setLastUpdate(new Date());
      }
    } catch (error) {
      console.error('Failed to fetch dashboard data:', error);
    } finally {
      setIsLoading(false);
    }
  }, []);

  // Execute emergency action (simplified)
  const executeEmergencyAction = async (action: string) => {
    setIsLoading(true);
    
    try {
      const response = await fetch('/api/admin/dashboard', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action,
          adminId,
          reason: `Emergency action executed from dashboard`
        })
      });

      const result = await response.json();
      
      if (result.success) {
        if (onEmergencyAction) {
          onEmergencyAction(action, result.data);
        }
        
        // Refresh data
        fetchDashboardData(activeSection);
        fetchDashboardData('alerts');
      } else {
        alert(`Emergency action failed: ${result.error}`);
      }
    } catch (error) {
      console.error('Emergency action failed:', error);
      alert('Emergency action failed. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  // Auto-refresh data
  useEffect(() => {
    fetchDashboardData(activeSection);
    
    // Set up auto-refresh every 30 seconds for real-time monitoring
    const interval = setInterval(() => {
      fetchDashboardData(activeSection);
    }, 30000);

    return () => clearInterval(interval);
  }, [activeSection, fetchDashboardData]);

  // Emergency Controls Panel
  const EmergencyControlsPanel = () => (
    <Card className="border-red-200 bg-red-50">
      <CardHeader>
        <CardTitle className="flex items-center gap-2 text-red-700">
          <Shield className="w-5 h-5" />
          Emergency Controls
        </CardTitle>
        <CardDescription className="text-red-600">
          Critical system controls for emergency interventions
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-4">
        <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
          <Button 
            variant={emergencyMode ? "destructive" : "outline"}
            className="w-full"
            onClick={() => executeEmergencyAction(emergencyMode ? 'resume_assignments' : 'pause_assignments')}
            disabled={isLoading}
          >
            <Pause className="w-4 h-4 mr-2" />
            {emergencyMode ? 'Resume' : 'Pause'} System
          </Button>
          
          <Button 
            variant="outline" 
            onClick={() => executeEmergencyAction('emergency_broadcast')}
            disabled={isLoading}
          >
            <Radio className="w-4 h-4 mr-2" />
            Broadcast
          </Button>
          
          <Button 
            variant="outline"
            onClick={() => fetchDashboardData(activeSection)}
            disabled={isLoading}
          >
            {isLoading ? (
              <RefreshCw className="w-4 h-4 mr-2 animate-spin" />
            ) : (
              <RefreshCw className="w-4 h-4 mr-2" />
            )}
            Refresh
          </Button>

          <Button 
            variant="outline"
            onClick={() => executeEmergencyAction('system_maintenance')}
            disabled={isLoading}
          >
            <Settings className="w-4 h-4 mr-2" />
            Maintenance
          </Button>

          <Button variant="outline" disabled>
            <Bell className="w-4 h-4 mr-2" />
            Alerts ({alerts.filter(a => !a.acknowledged).length})
          </Button>
        </div>

        {lastUpdate && (
          <p className="text-sm text-gray-500">
            Last updated: {lastUpdate.toLocaleTimeString()}
          </p>
        )}
      </CardContent>
    </Card>
  );

  // Route Monitoring View
  const RouteMonitoringView = () => (
    <div className="space-y-4">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium">Active Routes</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-green-600">
              {routes.filter(r => r.status === 'active').length}
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium">Delayed Routes</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-orange-600">
              {routes.filter(r => r.status === 'delayed').length}
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium">Need Intervention</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-red-600">
              {routes.filter(r => r.status === 'intervention_required').length}
            </div>
          </CardContent>
        </Card>
      </div>

      <Card>
        <CardHeader>
          <CardTitle>Live Route Monitoring</CardTitle>
          <CardDescription>Real-time tracking of all active routes</CardDescription>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            {routes.length === 0 ? (
              <div className="text-center py-8 text-gray-500">
                No active routes at the moment
              </div>
            ) : (
              routes.map(route => (
                <div 
                  key={route.id}
                  className={`p-4 border rounded-lg ${
                    route.status === 'intervention_required' ? 'border-red-300 bg-red-50' :
                    route.status === 'delayed' ? 'border-orange-300 bg-orange-50' :
                    'border-green-300 bg-green-50'
                  }`}
                >
                  <div className="flex justify-between items-start">
                    <div className="space-y-2">
                      <div className="flex items-center gap-2">
                        <Badge 
                          variant={
                            route.status === 'active' ? 'default' :
                            route.status === 'delayed' ? 'secondary' : 'destructive'
                          }
                        >
                          {route.status.replace('_', ' ').toUpperCase()}
                        </Badge>
                        {route.delayMinutes > 0 && (
                          <Badge variant="outline" className="text-orange-600">
                            <Clock className="w-3 h-3 mr-1" />
                            {route.delayMinutes}min delay
                          </Badge>
                        )}
                      </div>
                      
                      <div className="flex items-center gap-2 text-sm text-gray-600">
                        <MapPin className="w-4 h-4" />
                        {route.pickupLocation} → {route.dropoffLocation}
                      </div>
                      
                      <div className="text-sm text-gray-500">
                        Driver: {route.driverId} | Progress: {route.actualProgress}%
                      </div>
                    </div>

                    {route.status === 'intervention_required' && (
                      <Button 
                        size="sm" 
                        variant="destructive"
                        onClick={() => executeEmergencyAction('route_reassignment')}
                        disabled={isLoading}
                      >
                        <AlertTriangle className="w-4 h-4 mr-2" />
                        Intervene
                      </Button>
                    )}
                  </div>
                </div>
              ))
            )}
          </div>
        </CardContent>
      </Card>
    </div>
  );

  // Driver Performance View
  const DriverPerformanceView = () => (
    <div className="space-y-4">
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium">Active Drivers</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-green-600">
              {drivers.filter(d => d.status === 'active').length}
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium">Offline</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-gray-600">
              {drivers.filter(d => d.status === 'offline').length}
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium">On Break</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-blue-600">
              {drivers.filter(d => d.status === 'on_break').length}
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium">Emergency Status</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-red-600">
              {drivers.filter(d => d.status === 'emergency').length}
            </div>
          </CardContent>
        </Card>
      </div>

      <Card>
        <CardHeader>
          <CardTitle>Driver Performance Metrics</CardTitle>
          <CardDescription>Real-time driver status and performance</CardDescription>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            {drivers.length === 0 ? (
              <div className="text-center py-8 text-gray-500">
                No driver data available
              </div>
            ) : (
              drivers.map(driver => (
                <div 
                  key={driver.driverId}
                  className={`p-4 border rounded-lg ${
                    driver.status === 'emergency' ? 'border-red-300 bg-red-50' :
                    driver.status === 'active' ? 'border-green-300 bg-green-50' :
                    'border-gray-300 bg-gray-50'
                  }`}
                >
                  <div className="flex justify-between items-start">
                    <div className="space-y-2">
                      <div className="flex items-center gap-2">
                        <span className="font-medium">{driver.name}</span>
                        <Badge 
                          variant={
                            driver.status === 'active' ? 'default' :
                            driver.status === 'emergency' ? 'destructive' :
                            driver.status === 'on_break' ? 'secondary' : 'outline'
                          }
                        >
                          {driver.status.replace('_', ' ').toUpperCase()}
                        </Badge>
                      </div>
                      
                      <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-sm">
                        <div>
                          <span className="text-gray-500">Today Earnings:</span>
                          <div className="font-medium">£{driver.todayEarnings.toFixed(2)}</div>
                        </div>
                        <div>
                          <span className="text-gray-500">Deliveries:</span>
                          <div className="font-medium">{driver.todayDeliveries}</div>
                        </div>
                        <div>
                          <span className="text-gray-500">Avg Time:</span>
                          <div className="font-medium">{driver.avgDeliveryTime}min</div>
                        </div>
                        <div>
                          <span className="text-gray-500">Rating:</span>
                          <div className="font-medium">⭐ {driver.customerRating.toFixed(1)}</div>
                        </div>
                      </div>
                      
                      <div className="text-sm text-gray-500">
                        Location: {driver.currentLocation} | 
                        Last Active: {new Date(driver.lastActive).toLocaleTimeString()}
                      </div>
                    </div>

                    {driver.status === 'emergency' && (
                      <Button 
                        size="sm" 
                        variant="destructive"
                        onClick={() => executeEmergencyAction('emergency_broadcast')}
                        disabled={isLoading}
                      >
                        <Bell className="w-4 h-4 mr-2" />
                        Contact
                      </Button>
                    )}
                  </div>
                </div>
              ))
            )}
          </div>
        </CardContent>
      </Card>
    </div>
  );

  // System Health View
  const SystemHealthView = () => (
    <div className="space-y-4">
      {systemHealth ? (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <Card>
            <CardHeader className="pb-2">
              <CardTitle className="text-sm font-medium flex items-center gap-2">
                <Activity className="w-4 h-4" />
                API Health
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="space-y-2">
                <div className="flex items-center gap-2">
                  {systemHealth.api.uptime > 99.5 ? (
                    <CheckCircle className="w-4 h-4 text-green-600" />
                  ) : (
                    <XCircle className="w-4 h-4 text-red-600" />
                  )}
                  <span className="font-medium">
                    {systemHealth.api.uptime > 99.5 ? 'Healthy' : 'Issues Detected'}
                  </span>
                </div>
                <div className="text-sm text-gray-500">
                  Uptime: {systemHealth.api.uptime}% | Response: {systemHealth.api.responseTime}ms
                </div>
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardHeader className="pb-2">
              <CardTitle className="text-sm font-medium flex items-center gap-2">
                <Activity className="w-4 h-4" />
                Database
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="space-y-2">
                <div className="flex items-center gap-2">
                  {systemHealth.database.uptime > 99.5 ? (
                    <CheckCircle className="w-4 h-4 text-green-600" />
                  ) : (
                    <XCircle className="w-4 h-4 text-red-600" />
                  )}
                  <span className="font-medium">
                    {systemHealth.database.uptime > 99.5 ? 'Healthy' : 'Issues Detected'}
                  </span>
                </div>
                <div className="text-sm text-gray-500">
                  Uptime: {systemHealth.database.uptime}% | Query: {systemHealth.database.queryTime}ms
                </div>
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardHeader className="pb-2">
              <CardTitle className="text-sm font-medium flex items-center gap-2">
                <TrendingUp className="w-4 h-4" />
                Infrastructure
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="space-y-2">
                <div className="flex items-center gap-2">
                  {systemHealth.infrastructure.cpuUsage < 80 ? (
                    <CheckCircle className="w-4 h-4 text-green-600" />
                  ) : (
                    <AlertTriangle className="w-4 h-4 text-orange-600" />
                  )}
                  <span className="font-medium">
                    {systemHealth.infrastructure.cpuUsage < 80 ? 'Healthy' : 'High Load'}
                  </span>
                </div>
                <div className="text-sm text-gray-500">
                  CPU: {systemHealth.infrastructure.cpuUsage}% | 
                  Memory: {systemHealth.infrastructure.memoryUsage}%
                </div>
              </div>
            </CardContent>
          </Card>
        </div>
      ) : (
        <Card>
          <CardContent className="text-center py-8 text-gray-500">
            Loading system health metrics...
          </CardContent>
        </Card>
      )}
    </div>
  );

  // Alerts View
  const AlertsView = () => (
    <div className="space-y-4">
      <Card>
        <CardHeader>
          <CardTitle>System Alerts</CardTitle>
          <CardDescription>Active alerts and notifications requiring attention</CardDescription>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            {alerts.length === 0 ? (
              <div className="text-center py-8 text-gray-500">
                <CheckCircle className="w-8 h-8 mx-auto mb-2 text-green-500" />
                No active alerts
              </div>
            ) : (
              alerts.map(alert => (
                <div 
                  key={alert.id}
                  className={`p-4 border rounded-lg ${
                    alert.type === 'critical' ? 'border-red-300 bg-red-50' :
                    alert.type === 'warning' ? 'border-orange-300 bg-orange-50' :
                    'border-blue-300 bg-blue-50'
                  }`}
                >
                  <div className="flex justify-between items-center">
                    <div className="flex items-center gap-2">
                      <AlertTriangle className="h-4 w-4" />
                      <span>{alert.message}</span>
                    </div>
                    <div className="flex items-center gap-2">
                      <Badge 
                        variant={
                          alert.type === 'critical' ? 'destructive' :
                          alert.type === 'warning' ? 'secondary' : 'default'
                        }
                      >
                        {alert.type.toUpperCase()}
                      </Badge>
                      {!alert.acknowledged && (
                        <Button 
                          size="sm" 
                          variant="outline"
                          onClick={() => executeEmergencyAction('acknowledge_alert')}
                          disabled={isLoading}
                        >
                          Acknowledge
                        </Button>
                      )}
                    </div>
                  </div>
                </div>
              ))
            )}
          </div>
        </CardContent>
      </Card>
    </div>
  );

  return (
    <div className="space-y-6">
      {/* Emergency Controls Panel */}
      <EmergencyControlsPanel />

      {/* Main Dashboard Navigation */}
      <Card>
        <CardHeader>
          <div className="flex flex-wrap gap-2">
            {[
              { key: 'overview', label: 'Overview', icon: Activity },
              { key: 'routes', label: 'Routes', icon: Route },
              { key: 'drivers', label: 'Drivers', icon: Users },
              { key: 'system_health', label: 'System Health', icon: Activity },
              { key: 'alerts', label: 'Alerts', icon: Bell }
            ].map(({ key, label, icon: Icon }) => (
              <Button
                key={key}
                variant={activeSection === key ? "default" : "outline"}
                size="sm"
                onClick={() => setActiveSection(key)}
                className="flex items-center gap-2"
              >
                <Icon className="w-4 h-4" />
                {label}
                {key === 'alerts' && alerts.filter(a => !a.acknowledged).length > 0 && (
                  <Badge variant="destructive" className="ml-1">
                    {alerts.filter(a => !a.acknowledged).length}
                  </Badge>
                )}
              </Button>
            ))}
          </div>
        </CardHeader>
      </Card>

      {/* Dashboard Content */}
      <div className="space-y-4">
        {activeSection === 'overview' && (
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            <div>
              <h3 className="text-lg font-medium mb-4">Route Summary</h3>
              <RouteMonitoringView />
            </div>
            <div>
              <h3 className="text-lg font-medium mb-4">Driver Summary</h3>
              <DriverPerformanceView />
            </div>
          </div>
        )}

        {activeSection === 'routes' && <RouteMonitoringView />}
        {activeSection === 'drivers' && <DriverPerformanceView />}
        {activeSection === 'system_health' && <SystemHealthView />}
        {activeSection === 'alerts' && <AlertsView />}
      </div>
    </div>
  );
};

export default AdminDashboardControls;

'use client';

import React, { useState, useEffect } from 'react';
import {
  Box,
  VStack,
  HStack,
  Text,
  Button,
  Card,
  CardBody,
  CardHeader,
  Heading,
  Badge,
  Avatar,
  Table,
  Thead,
  Tbody,
  Tr,
  Th,
  Td,
  Input,
  InputGroup,
  InputLeftElement,
  Select,
  useToast,
  useColorModeValue,
  Spinner,
  Alert,
  AlertIcon,
  Menu,
  MenuButton,
  MenuList,
  MenuItem,
  IconButton,
  useDisclosure,
  Modal,
  ModalOverlay,
  ModalContent,
  ModalHeader,
  ModalBody,
  ModalCloseButton,
} from '@chakra-ui/react';
import {
  FiPlus,
  FiEdit,
  FiTrash2,
  FiMoreVertical,
  FiUser,
  FiMail,
  FiShield,
  FiSearch,
  FiFilter,
} from 'react-icons/fi';

interface AdminUser {
  id: string;
  name: string;
  email: string;
  role: 'admin' | 'manager' | 'support';
  status: 'active' | 'inactive' | 'pending';
  lastLogin?: string;
  createdAt: string;
  permissions: string[];
}

interface AdminManagerProps {
  currentUserId?: string;
}

const AdminManager: React.FC<AdminManagerProps> = ({ currentUserId }) => {
  const [users, setUsers] = useState<AdminUser[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [roleFilter, setRoleFilter] = useState('');
  const [statusFilter, setStatusFilter] = useState('');
  const [selectedUser, setSelectedUser] = useState<AdminUser | null>(null);
  const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);

  const toast = useToast();
  const bgColor = useColorModeValue('white', 'gray.800');
  const borderColor = useColorModeValue('gray.200', 'gray.600');

  useEffect(() => {
    fetchUsers();
  }, []);

  const fetchUsers = async (showLoading = true) => {
    if (showLoading) {
      setLoading(true);
    }
    try {
      const response = await fetch('/api/admin/users');
      if (!response.ok) {
        throw new Error('Failed to fetch users');
      }
      const result = await response.json();
      setUsers(result.users || []);
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to load users',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setLoading(false);
    }
  };

  const filteredUsers = (users || []).filter(user => {
    const matchesSearch = user.name?.toLowerCase().includes(searchQuery.toLowerCase()) ||
                         user.email?.toLowerCase().includes(searchQuery.toLowerCase());
    const matchesRole = !roleFilter || user.role === roleFilter;
    const matchesStatus = !statusFilter || user.status === statusFilter;
    return matchesSearch && matchesRole && matchesStatus;
  });

  const getRoleColor = (role: string) => {
    switch (role) {
      case 'admin':
        return 'red';
      case 'manager':
        return 'blue';
      case 'support':
        return 'green';
      default:
        return 'gray';
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'active':
        return 'green';
      case 'inactive':
        return 'red';
      case 'pending':
        return 'yellow';
      default:
        return 'gray';
    }
  };

  const handleCreateUser = () => {
    setSelectedUser(null);
    setIsCreateModalOpen(true);
  };

  const handleEditUser = (user: AdminUser) => {
    setSelectedUser(user);
    setIsEditModalOpen(true);
  };

  const handleDeleteUser = async (userId: string) => {
    if (userId === currentUserId) {
      toast({
        title: 'Error',
        description: 'Cannot delete your own account',
        status: 'error',
        duration: 3000,
        isClosable: true,
      });
      return;
    }

    try {
      const response = await fetch(`/api/admin/users/${userId}`, {
        method: 'DELETE',
      });

      if (response.ok) {
        toast({
          title: 'Success',
          description: 'User deleted successfully',
          status: 'success',
          duration: 3000,
          isClosable: true,
        });
        fetchUsers(false); // Don't show loading when refreshing after delete
      } else {
        throw new Error('Failed to delete user');
      }
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to delete user',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    }
  };

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" py={8}>
        <Spinner size="xl" />
      </Box>
    );
  }

  return (
    <Box>
      {/* Header */}
      <HStack justify="space-between" mb={6}>
        <VStack align="start" spacing={1}>
          <Heading size="lg">Admin Users</Heading>
          <Text color="gray.600">Manage admin users and permissions</Text>
        </VStack>
        <Button
          leftIcon={<FiPlus />}
          colorScheme="blue"
          onClick={handleCreateUser}
        >
          Add User
        </Button>
      </HStack>

      {/* Filters */}
      <Card mb={6}>
        <CardBody>
          <HStack spacing={4} wrap="wrap">
            <InputGroup maxW="300px">
              <InputLeftElement>
                <FiSearch />
              </InputLeftElement>
              <Input
                placeholder="Search users..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
              />
            </InputGroup>
            <Select
              placeholder="All Roles"
              value={roleFilter}
              onChange={(e) => setRoleFilter(e.target.value)}
              maxW="150px"
            >
              <option value="admin">Admin</option>
              <option value="manager">Manager</option>
              <option value="support">Support</option>
            </Select>
            <Select
              placeholder="All Status"
              value={statusFilter}
              onChange={(e) => setStatusFilter(e.target.value)}
              maxW="150px"
            >
              <option value="active">Active</option>
              <option value="inactive">Inactive</option>
              <option value="pending">Pending</option>
            </Select>
          </HStack>
        </CardBody>
      </Card>

      {/* Users Table */}
      <Card>
        <CardBody p={0}>
          <Table variant="simple">
            <Thead>
              <Tr>
                <Th>User</Th>
                <Th>Role</Th>
                <Th>Status</Th>
                <Th>Last Login</Th>
                <Th>Created</Th>
                <Th>Actions</Th>
              </Tr>
            </Thead>
            <Tbody>
              {filteredUsers.map((user) => (
                <Tr key={user.id}>
                  <Td>
                    <HStack spacing={3}>
                      <Avatar
                        size="sm"
                        name={user.name}
                        src={`/avatars/${user.name.toLowerCase().replace(' ', '-')}.jpg`}
                      />
                      <VStack align="start" spacing={0}>
                        <Text fontWeight="medium">{user.name}</Text>
                        <Text fontSize="sm" color="gray.600">
                          {user.email}
                        </Text>
                      </VStack>
                    </HStack>
                  </Td>
                  <Td>
                    <Badge colorScheme={getRoleColor(user.role)}>
                      {user.role}
                    </Badge>
                  </Td>
                  <Td>
                    <Badge colorScheme={getStatusColor(user.status)}>
                      {user.status}
                    </Badge>
                  </Td>
                  <Td>
                    <Text fontSize="sm" color="gray.600">
                      {user.lastLogin
                        ? new Date(user.lastLogin).toLocaleDateString()
                        : 'Never'}
                    </Text>
                  </Td>
                  <Td>
                    <Text fontSize="sm" color="gray.600">
                      {new Date(user.createdAt).toLocaleDateString()}
                    </Text>
                  </Td>
                  <Td>
                    <Menu>
                      <MenuButton
                        as={IconButton}
                        icon={<FiMoreVertical />}
                        variant="ghost"
                        size="sm"
                      />
                      <MenuList>
                        <MenuItem
                          icon={<FiEdit />}
                          onClick={() => handleEditUser(user)}
                        >
                          Edit User
                        </MenuItem>
                        <MenuItem
                          icon={<FiTrash2 />}
                          onClick={() => handleDeleteUser(user.id)}
                          color="red.500"
                        >
                          Delete User
                        </MenuItem>
                      </MenuList>
                    </Menu>
                  </Td>
                </Tr>
              ))}
            </Tbody>
          </Table>
        </CardBody>
      </Card>

      {/* Create/Edit Modal */}
      <Modal
        isOpen={isCreateModalOpen || isEditModalOpen}
        onClose={() => {
          setIsCreateModalOpen(false);
          setIsEditModalOpen(false);
        }}
      >
        <ModalOverlay />
        <ModalContent>
          <ModalHeader>
            {isCreateModalOpen ? 'Create New User' : 'Edit User'}
          </ModalHeader>
          <ModalCloseButton />
          <ModalBody pb={6}>
            <VStack spacing={4}>
              <Text color="gray.500">
                User management form would go here
              </Text>
              <Button
                colorScheme="blue"
                onClick={() => {
                  setIsCreateModalOpen(false);
                  setIsEditModalOpen(false);
                }}
              >
                Close
              </Button>
            </VStack>
          </ModalBody>
        </ModalContent>
      </Modal>
    </Box>
  );
};

export default AdminManager;

/**
 * Admin Dashboard Multi-Drop Route Management Enhancement
 *
 * Comprehensive admin interface for monitoring and managing the Multi-Drop Route system.
 * Provides real-time insights, route optimization controls, and driver management tools.
 *
 * Key Features:
 * - Live route monitoring with interactive maps
 * - Real-time performance metrics and analytics
 * - Driver fleet management and status tracking
 * - Route optimization controls and manual overrides
 * - Customer service tools and delivery tracking
 * - System health monitoring and alert management
 * - Revenue analytics and operational insights
 */

'use client';

import React, { useState, useEffect } from 'react';
import {
  Box,
  Grid,
  Card,
  CardBody,
  CardHeader,
  Heading,
  Text,
  Badge,
  Button,
  Flex,
  Stack,
  Progress,
  Stat,
  StatLabel,
  StatNumber,
  StatHelpText,
  StatArrow,
  Table,
  Thead,
  Tbody,
  Tr,
  Th,
  Td,
  Select,
  Input,
  InputGroup,
  InputLeftElement,
  Modal,
  ModalOverlay,
  ModalContent,
  ModalHeader,
  ModalCloseButton,
  ModalBody,
  ModalFooter,
  useDisclosure,
  Alert,
  AlertIcon,
  AlertTitle,
  AlertDescription,
  Tabs,
  TabList,
  TabPanels,
  Tab,
  TabPanel,
  IconButton,
  useToast
} from '@chakra-ui/react';
import {
  FaRoute,
  FaTruck,
  FaMapMarkedAlt,
  FaClock,
  FaSearch,
  FaSync,
  FaPause,
  FaPlay,
  FaStop,
  FaExclamationTriangle,
  FaChartLine,
  FaUsers,
  FaBoxOpen,
  FaMoneyBillWave,
  FaCheckCircle,
  FaTimesCircle,
  FaBell,
  FaFilter,
  FaDownload,
  FaCog,
  FaEye
} from 'react-icons/fa';

interface RouteMetrics {
  totalRoutes: number;
  activeRoutes: number;
  completedToday: number;
  avgDeliveryTime: number;
  onTimeRate: number;
  totalRevenue: number;
  efficiency: number;
}

interface DriverStatus {
  id: string;
  name: string;
  status: 'available' | 'en_route' | 'delivering' | 'offline';
  currentRoute?: string;
  location: { lat: number; lng: number };
  todayEarnings: number;
  todayDeliveries: number;
  rating: number;
  lastUpdate: Date;
}

interface RouteData {
  id: string;
  driverId?: string;
  driverName?: string;
  status: 'pending_assignment' | 'assigned' | 'active' | 'completed' | 'failed';
  serviceTier: string;
  totalDrops: number;
  completedDrops: number;
  estimatedDuration: number;
  actualDuration?: number;
  totalDistance: number;
  totalValue: number;
  timeWindowStart: Date;
  timeWindowEnd: Date;
  createdAt: Date;
  progress: number;
}

interface SystemAlert {
  id: string;
  type: 'warning' | 'error' | 'info' | 'success';
  priority: 'low' | 'medium' | 'high' | 'critical';
  title: string;
  message: string;
  timestamp: Date;
  acknowledged: boolean;
}

const AdminRoutesDashboard: React.FC = () => {
  const [metrics, setMetrics] = useState<RouteMetrics>({
    totalRoutes: 0,
    activeRoutes: 0,
    completedToday: 0,
    avgDeliveryTime: 0,
    onTimeRate: 0,
    totalRevenue: 0,
    efficiency: 0
  });

  const [drivers, setDrivers] = useState<DriverStatus[]>([]);
  const [routes, setRoutes] = useState<RouteData[]>([]);
  const [alerts, setAlerts] = useState<SystemAlert[]>([]);
  const [selectedRoute, setSelectedRoute] = useState<RouteData | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState('all');

  // Calculate live progress percentage based on completed drops
  const getProgressPercentage = (route: RouteData): number => {
    if (route.status === 'completed') return 100;
    if (route.status === 'pending_assignment') return 0;

    const { completedDrops, totalDrops } = route;
    if (totalDrops === 0) return 0;

    return Math.round((completedDrops / totalDrops) * 100);
  };

  // Get color scheme based on route status
  const getProgressColorScheme = (route: RouteData): string => {
    if (route.status === 'completed') return 'green';
    if (route.status === 'failed') return 'gray';
    if (route.progress > 75) return 'green';
    if (route.progress > 50) return 'blue';
    if (route.progress > 25) return 'orange';
    return 'yellow';
  };

  const [dateFilter, setDateFilter] = useState('today');
  
  const { isOpen: isRouteModalOpen, onOpen: onRouteModalOpen, onClose: onRouteModalClose } = useDisclosure();
  const toast = useToast();

  useEffect(() => {
    loadDashboardData();
    
    // Set up real-time updates
    const interval = setInterval(() => {
      loadDashboardData();
    }, 30000); // Update every 30 seconds

    return () => clearInterval(interval);
  }, []);

  const loadDashboardData = async () => {
    try {
      // TODO: Replace with actual API calls
      await Promise.all([
        loadMetrics(),
        loadDrivers(),
        loadRoutes(),
        loadAlerts()
      ]);
    } catch (error) {
      console.error('Failed to load dashboard data:', error);
      toast({
        title: 'Error',
        description: 'Failed to load dashboard data',
        status: 'error',
        duration: 5000
      });
    } finally {
      setIsLoading(false);
    }
  };

  const loadMetrics = async () => {
    try {
      const response = await fetch('/api/admin/analytics');
      const data = await response.json();
      
      // Map analytics data to metrics format
      setMetrics({
        totalRoutes: data.totalRoutes || 0,
        activeRoutes: data.activeRoutes || 0,
        completedToday: data.completedToday || 0,
        avgDeliveryTime: data.avgDeliveryTime || 0,
        onTimeRate: data.onTimeRate || 0,
        totalRevenue: data.totalRevenue || 0,
        efficiency: data.efficiency || 0
      });
    } catch (error) {
      console.error('Error loading metrics:', error);
      toast({
        title: 'Error',
        description: 'Failed to load metrics',
        status: 'error',
        duration: 3000
      });
    }
  };

  const loadDrivers = async () => {
    try {
      const response = await fetch('/api/admin/analytics');
      const data = await response.json();
      
      // Map driver metrics to driver status format
      if (data.driverMetrics) {
        const mappedDrivers: DriverStatus[] = data.driverMetrics.map((driver: any) => ({
          id: driver.id,
          name: driver.name,
          status: driver.status || 'available',
          currentRoute: driver.currentRouteId,
          location: driver.location || { lat: 0, lng: 0 },
          todayEarnings: driver.earnings || 0,
          todayDeliveries: driver.assignmentsToday || 0,
          rating: driver.averageRating || 0,
          lastUpdate: new Date()
        }));
        setDrivers(mappedDrivers);
      }
    } catch (error) {
      console.error('Error loading drivers:', error);
      toast({
        title: 'Error',
        description: 'Failed to load drivers',
        status: 'error',
        duration: 3000
      });
    }
  };

  const loadRoutes = async () => {
    try {
      const response = await fetch('/api/admin/routes?status=all');
      const data = await response.json();
      
      if (data.routes) {
        // Map routes to RouteData format
        const mappedRoutes: RouteData[] = data.routes.map((route: any) => {
          const completedDrops = route.drops?.filter((d: any) => d.status === 'completed').length || 0;
          const totalDrops = route.drops?.length || 0;
          const progress = totalDrops > 0 ? (completedDrops / totalDrops) * 100 : 0;
          
          return {
            id: route.id,
            driverId: route.driverId,
            driverName: route.driver?.name || 'N/A',
            status: route.status,
            serviceTier: route.serviceTier || 'standard',
            totalDrops,
            completedDrops,
            estimatedDuration: route.estimatedDuration || 0,
            totalDistance: route.optimizedDistanceKm || 0,
            totalValue: route.totalOutcome || 0,
            timeWindowStart: route.startTime ? new Date(route.startTime) : new Date(),
            timeWindowEnd: route.endTime ? new Date(route.endTime) : new Date(),
            createdAt: route.createdAt ? new Date(route.createdAt) : new Date(),
            progress
          };
        });
        setRoutes(mappedRoutes);
      }
    } catch (error) {
      console.error('Error loading routes:', error);
      toast({
        title: 'Error',
        description: 'Failed to load routes',
        status: 'error',
        duration: 3000
      });
    }
  };

  const loadAlerts = async () => {
    // Mock data - replace with API call
    const mockAlerts: SystemAlert[] = [
      {
        id: 'alert_1',
        type: 'warning',
        priority: 'medium',
        title: 'Route Optimization Delayed',
        message: 'Route route_456 is running 15 minutes behind schedule',
        timestamp: new Date(Date.now() - 900000),
        acknowledged: false
      },
      {
        id: 'alert_2',
        type: 'success',
        priority: 'low',
        title: 'High Efficiency Route',
        message: 'Route route_789 completed 20% faster than estimated',
        timestamp: new Date(Date.now() - 1800000),
        acknowledged: true
      }
    ];
    setAlerts(mockAlerts);
  };

  const handleRouteAction = async (routeId: string, action: 'pause' | 'resume' | 'cancel' | 'reassign') => {
    try {
      if (action === 'cancel') {
        await handleCancelRoute(routeId);
      } else if (action === 'reassign') {
        // This will be handled by a modal with driver selection
        console.log('Reassign action - open modal');
      } else {
        console.log(`${action} route:`, routeId);
      }
      
      await loadRoutes();
    } catch (error) {
      toast({
        title: 'Error', 
        description: `Failed to ${action} route`,
        status: 'error',
        duration: 5000
      });
    }
  };

  const handleReassignDriver = async (routeId: string, newDriverId: string) => {
    try {
      const response = await fetch(`/api/admin/routes/${routeId}/reassign`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ driverId: newDriverId })
      });

      if (!response.ok) throw new Error('Failed to reassign driver');

      toast({
        title: 'Success',
        description: 'Driver reassigned successfully',
        status: 'success',
        duration: 3000
      });

      await loadRoutes();
      await loadDrivers();
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to reassign driver',
        status: 'error',
        duration: 5000
      });
    }
  };

  const handleCancelRoute = async (routeId: string) => {
    try {
      const response = await fetch(`/api/admin/routes/${routeId}/cancel`, {
        method: 'POST'
      });

      if (!response.ok) throw new Error('Failed to cancel route');

      toast({
        title: 'Success',
        description: 'Route cancelled successfully. Bookings have been reset.',
        status: 'success',
        duration: 3000
      });

      await loadRoutes();
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to cancel route',
        status: 'error',
        duration: 5000
      });
    }
  };

  const handleAddDrop = async (routeId: string, dropData: any) => {
    try {
      const response = await fetch(`/api/admin/routes/${routeId}/drops`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(dropData)
      });

      if (!response.ok) throw new Error('Failed to add drop');

      toast({
        title: 'Success',
        description: 'Drop added to route successfully',
        status: 'success',
        duration: 3000
      });

      await loadRoutes();
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to add drop',
        status: 'error',
        duration: 5000
      });
    }
  };

  const handleRemoveDrop = async (routeId: string, dropId: string) => {
    try {
      const response = await fetch(`/api/admin/routes/${routeId}/drops/${dropId}`, {
        method: 'DELETE'
      });

      if (!response.ok) throw new Error('Failed to remove drop');

      toast({
        title: 'Success',
        description: 'Drop removed from route successfully',
        status: 'success',
        duration: 3000
      });

      await loadRoutes();
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to remove drop',
        status: 'error',
        duration: 5000
      });
    }
  };

  const handleDriverAction = async (driverId: string, action: 'assign' | 'reassign' | 'offline') => {
    try {
      console.log(`${action} driver:`, driverId);
      
      toast({
        title: 'Success',
        description: `Driver ${action} successful`,
        status: 'success',
        duration: 3000
      });
      
      await loadDrivers();
    } catch (error) {
      toast({
        title: 'Error',
        description: `Failed to ${action} driver`,
        status: 'error', 
        duration: 5000
      });
    }
  };

  const acknowledgeAlert = async (alertId: string) => {
    try {
      setAlerts(prev => prev.map(alert => 
        alert.id === alertId ? { ...alert, acknowledged: true } : alert
      ));
      
      toast({
        title: 'Alert Acknowledged',
        status: 'info',
        duration: 2000
      });
    } catch (error) {
      console.error('Failed to acknowledge alert:', error);
    }
  };

  const exportData = async (type: 'routes' | 'drivers' | 'metrics') => {
    try {
      // TODO: Implement export functionality
      console.log(`Exporting ${type} data`);
      
      toast({
        title: 'Export Started',
        description: `${type} data export will be ready shortly`,
        status: 'info',
        duration: 3000
      });
    } catch (error) {
      console.error('Export failed:', error);
    }
  };

  const filteredRoutes = routes.filter(route => {
    const matchesSearch = route.driverName?.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         route.id.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesStatus = statusFilter === 'all' || route.status === statusFilter;
    return matchesSearch && matchesStatus;
  });

  const getStatusBadge = (status: string) => {
    const statusColors = {
      'pending_assignment': 'yellow',
      'assigned': 'blue', 
      'active': 'green',
      'completed': 'gray',
      'failed': 'red',
      'available': 'green',
      'en_route': 'blue',
      'delivering': 'orange',
      'offline': 'gray'
    };
    return <Badge colorScheme={statusColors[status as keyof typeof statusColors] || 'gray'}>{status}</Badge>;
  };

  const getPriorityColor = (priority: string) => {
    const colors = { low: 'green', medium: 'yellow', high: 'orange', critical: 'red' };
    return colors[priority as keyof typeof colors] || 'gray';
  };

  return (
    <Box p={6} minH="100vh">
      <Flex justify="space-between" align="center" mb={6}>
        <Heading size="lg">Multi-Drop Routes Dashboard</Heading>
        <Flex gap={3}>
          <Button leftIcon={<FaSync />} onClick={loadDashboardData} isLoading={isLoading}>
            Refresh
          </Button>
          <Button leftIcon={<FaDownload />} onClick={() => exportData('routes')}>
            Export
          </Button>
          <Button leftIcon={<FaCog />} variant="outline">
            Settings
          </Button>
        </Flex>
      </Flex>

      {/* Key Metrics Cards */}
      <Grid templateColumns="repeat(auto-fit, minmax(200px, 1fr))" gap={6} mb={6}>
        <Card>
          <CardBody>
            <Stat>
              <StatLabel>Active Routes</StatLabel>
              <StatNumber>{metrics.activeRoutes}</StatNumber>
              <StatHelpText>
                <StatArrow type="increase" />
                {metrics.totalRoutes} total
              </StatHelpText>
            </Stat>
          </CardBody>
        </Card>

        <Card>
          <CardBody>
            <Stat>
              <StatLabel>Completed Today</StatLabel>
              <StatNumber>{metrics.completedToday}</StatNumber>
              <StatHelpText>
                <StatArrow type="increase" />
                {metrics.onTimeRate}% on time
              </StatHelpText>
            </Stat>
          </CardBody>
        </Card>

        <Card>
          <CardBody>
            <Stat>
              <StatLabel>Revenue Today</StatLabel>
              <StatNumber>£{metrics.totalRevenue.toFixed(2)}</StatNumber>
              <StatHelpText>
                <StatArrow type="increase" />
                {metrics.efficiency}% efficiency
              </StatHelpText>
            </Stat>
          </CardBody>
        </Card>

        <Card>
          <CardBody>
            <Stat>
              <StatLabel>Avg Delivery Time</StatLabel>
              <StatNumber>{metrics.avgDeliveryTime}min</StatNumber>
              <StatHelpText>
                <StatArrow type="decrease" />
                5min improvement
              </StatHelpText>
            </Stat>
          </CardBody>
        </Card>
      </Grid>

      <Tabs>
        <TabList>
          <Tab><FaRoute /> Routes</Tab>
          <Tab><FaTruck /> Drivers</Tab>
          <Tab><FaBell /> Alerts</Tab>
          <Tab><FaChartLine /> Analytics</Tab>
        </TabList>

        <TabPanels>
          {/* Routes Tab */}
          <TabPanel p={0} mt={4}>
            <Card>
              <CardHeader>
                <Flex justify="space-between" align="center">
                  <Heading size="md">Route Management</Heading>
                  <Flex gap={3}>
                    <InputGroup maxW="300px">
                      <InputLeftElement>
                        <FaSearch />
                      </InputLeftElement>
                      <Input 
                        placeholder="Search routes..."
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                      />
                    </InputGroup>
                    <Select maxW="150px" value={statusFilter} onChange={(e) => setStatusFilter(e.target.value)}>
                      <option value="all">All Status</option>
                      <option value="pending_assignment">Pending</option>
                      <option value="active">Active</option>
                      <option value="completed">Completed</option>
                    </Select>
                  </Flex>
                </Flex>
              </CardHeader>
              <CardBody>
                <Table variant="simple">
                  <Thead>
                    <Tr>
                      <Th>Route ID</Th>
                      <Th>Driver</Th>
                      <Th>Status</Th>
                      <Th>Progress</Th>
                      <Th>Drops</Th>
                      <Th>Value</Th>
                      <Th>Duration</Th>
                      <Th>Actions</Th>
                    </Tr>
                  </Thead>
                  <Tbody>
                    {filteredRoutes.map((route) => (
                      <Tr key={route.id}>
                        <Td>{route.id}</Td>
                        <Td>{route.driverName || 'Unassigned'}</Td>
                        <Td>{getStatusBadge(route.status)}</Td>
                        <Td>
                          <Box>
                            <Progress 
                              value={getProgressPercentage(route)} 
                              size="sm" 
                              colorScheme={getProgressColorScheme(route)} 
                            />
                            <Text fontSize="xs" mt={1}>
                              {route.completedDrops}/{route.totalDrops} drops ({getProgressPercentage(route)}%)
                            </Text>
                          </Box>
                        </Td>
                        <Td>{route.totalDrops}</Td>
                        <Td>£{route.totalValue.toFixed(2)}</Td>
                        <Td>{route.estimatedDuration}min</Td>
                        <Td>
                          <Flex gap={2}>
                            <IconButton
                              aria-label="View route"
                              icon={<FaEye />}
                              size="sm"
                              onClick={() => {
                                setSelectedRoute(route);
                                onRouteModalOpen();
                              }}
                            />
                            {route.status === 'active' && (
                              <IconButton
                                aria-label="Pause route"
                                icon={<FaPause />}
                                size="sm"
                                colorScheme="yellow"
                                onClick={() => handleRouteAction(route.id, 'pause')}
                              />
                            )}
                            {route.status === 'assigned' && (
                              <IconButton
                                aria-label="Start route"
                                icon={<FaPlay />}
                                size="sm"
                                colorScheme="green"
                                onClick={() => handleRouteAction(route.id, 'resume')}
                              />
                            )}
                          </Flex>
                        </Td>
                      </Tr>
                    ))}
                  </Tbody>
                </Table>
              </CardBody>
            </Card>
          </TabPanel>

          {/* Drivers Tab */}
          <TabPanel p={0} mt={4}>
            <Grid templateColumns="repeat(auto-fill, minmax(300px, 1fr))" gap={6}>
              {drivers.map((driver) => (
                <Card key={driver.id}>
                  <CardHeader>
                    <Flex justify="space-between" align="center">
                      <Heading size="sm">{driver.name}</Heading>
                      {getStatusBadge(driver.status)}
                    </Flex>
                  </CardHeader>
                  <CardBody>
                    <Stack spacing={3}>
                      <Flex justify="space-between">
                        <Text fontSize="sm">Today's Earnings:</Text>
                        <Text fontWeight="bold">£{driver.todayEarnings.toFixed(2)}</Text>
                      </Flex>
                      <Flex justify="space-between">
                        <Text fontSize="sm">Deliveries:</Text>
                        <Text>{driver.todayDeliveries}</Text>
                      </Flex>
                      <Flex justify="space-between">
                        <Text fontSize="sm">Rating:</Text>
                        <Text>{driver.rating}/5.0</Text>
                      </Flex>
                      {driver.currentRoute && (
                        <Flex justify="space-between">
                          <Text fontSize="sm">Current Route:</Text>
                          <Text fontSize="sm">{driver.currentRoute}</Text>
                        </Flex>
                      )}
                      <Flex gap={2} mt={4}>
                        <Button size="sm" flex={1} onClick={() => handleDriverAction(driver.id, 'assign')}>
                          Assign Route
                        </Button>
                        <Button size="sm" variant="outline" onClick={() => handleDriverAction(driver.id, 'offline')}>
                          Set Offline
                        </Button>
                      </Flex>
                    </Stack>
                  </CardBody>
                </Card>
              ))}
            </Grid>
          </TabPanel>

          {/* Alerts Tab */}
          <TabPanel p={0} mt={4}>
            <Card>
              <CardHeader>
                <Heading size="md">System Alerts</Heading>
              </CardHeader>
              <CardBody>
                <Stack spacing={4}>
                  {alerts.map((alert) => (
                    <Alert 
                      key={alert.id} 
                      status={alert.type}
                      variant={alert.acknowledged ? 'subtle' : 'left-accent'}
                    >
                      <AlertIcon />
                      <Box flex="1">
                        <AlertTitle>{alert.title}</AlertTitle>
                        <AlertDescription>{alert.message}</AlertDescription>
                        <Text fontSize="xs" color="gray.500" mt={1}>
                          {alert.timestamp.toLocaleString()}
                        </Text>
                      </Box>
                      {!alert.acknowledged && (
                        <Button size="sm" onClick={() => acknowledgeAlert(alert.id)}>
                          Acknowledge
                        </Button>
                      )}
                    </Alert>
                  ))}
                </Stack>
              </CardBody>
            </Card>
          </TabPanel>

          {/* Analytics Tab */}
          <TabPanel p={0} mt={4}>
            <Grid templateColumns="repeat(auto-fit, minmax(400px, 1fr))" gap={6}>
              <Card>
                <CardHeader>
                  <Heading size="md">Performance Overview</Heading>
                </CardHeader>
                <CardBody>
                  <Text>Analytics charts and graphs would go here</Text>
                  <Text fontSize="sm" color="gray.500">
                    Integration with charting library needed
                  </Text>
                </CardBody>
              </Card>
            </Grid>
          </TabPanel>
        </TabPanels>
      </Tabs>

      {/* Route Details Modal */}
      <Modal isOpen={isRouteModalOpen} onClose={onRouteModalClose} size="xl">
        <ModalOverlay />
        <ModalContent>
          <ModalHeader>Route Details: {selectedRoute?.id}</ModalHeader>
          <ModalCloseButton />
          <ModalBody>
            {selectedRoute && (
              <Stack spacing={4}>
                <Flex justify="space-between">
                  <Text fontWeight="bold">Driver:</Text>
                  <Text>{selectedRoute.driverName || 'Unassigned'}</Text>
                </Flex>
                <Flex justify="space-between">
                  <Text fontWeight="bold">Status:</Text>
                  {getStatusBadge(selectedRoute.status)}
                </Flex>
                <Flex justify="space-between">
                  <Text fontWeight="bold">Progress:</Text>
                  <Text>{selectedRoute.completedDrops}/{selectedRoute.totalDrops} drops</Text>
                </Flex>
                <Box>
                  <Text fontWeight="bold" mb={2}>Route Progress:</Text>
                  <Progress value={selectedRoute.progress} colorScheme="green" />
                </Box>
                <Flex justify="space-between">
                  <Text fontWeight="bold">Total Distance:</Text>
                  <Text>{selectedRoute.totalDistance.toFixed(1)} km</Text>
                </Flex>
                <Flex justify="space-between">
                  <Text fontWeight="bold">Total Value:</Text>
                  <Text>£{selectedRoute.totalValue.toFixed(2)}</Text>
                </Flex>
                <Flex justify="space-between">
                  <Text fontWeight="bold">Time Window:</Text>
                  <Text>
                    {selectedRoute.timeWindowStart.toLocaleTimeString()} - {selectedRoute.timeWindowEnd.toLocaleTimeString()}
                  </Text>
                </Flex>
              </Stack>
            )}
          </ModalBody>
          <ModalFooter>
            <Button colorScheme="blue" mr={3} onClick={onRouteModalClose}>
              Close
            </Button>
            <Button variant="ghost">View on Map</Button>
          </ModalFooter>
        </ModalContent>
      </Modal>
    </Box>
  );
};

export default AdminRoutesDashboard;

'use client';

import { useState, useEffect } from 'react';
import {
  Box,
  VStack,
  HStack,
  Text,
  Table,
  Thead,
  Tbody,
  Tr,
  Th,
  Td,
  Badge,
  Button,
  Input,
  InputGroup,
  InputLeftElement,
  Select,
  Icon,
  useToast,
  Spinner,
  Menu,
  MenuButton,
  MenuList,
  MenuItem,
  IconButton,
} from '@chakra-ui/react';
import {
  FiDownload,
  FiFilter,
  FiSearch,
  FiMoreVertical,
  FiEye,
  FiAlertCircle,
  FiCheckCircle,
} from 'react-icons/fi';

interface AuditLog {
  id: string;
  userId: string;
  action: string;
  resource: string;
  resourceId?: string;
  details: any;
  createdAt: string;
  User?: {
    name: string;
    email: string;
  };
}

export function AuditTrailViewer() {
  const [logs, setLogs] = useState<AuditLog[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [filterAction, setFilterAction] = useState('');
  const [filterUser, setFilterUser] = useState('');
  const [dateFrom, setDateFrom] = useState('');
  const [dateTo, setDateTo] = useState('');
  const toast = useToast();

  useEffect(() => {
    loadAuditLogs();
  }, [filterAction, filterUser, dateFrom, dateTo]);

  const loadAuditLogs = async () => {
    setIsLoading(true);
    try {
      const params = new URLSearchParams();
      if (filterAction) params.append('action', filterAction);
      if (filterUser) params.append('userId', filterUser);
      if (dateFrom) params.append('dateFrom', dateFrom);
      if (dateTo) params.append('dateTo', dateTo);

      const response = await fetch(`/api/admin/audit-logs?${params}`);
      const data = await response.json();

      if (data.success) {
        setLogs(data.logs);
      } else {
        throw new Error(data.message);
      }
    } catch (error) {
      console.error('Failed to load audit logs:', error);
      toast({
        title: 'خطأ',
        description: 'فشل تحميل سجلات المراجعة',
        status: 'error',
        duration: 3000,
      });
    } finally {
      setIsLoading(false);
    }
  };

  const exportLogs = async (format: 'csv' | 'json') => {
    try {
      const params = new URLSearchParams();
      params.append('format', format);
      if (filterAction) params.append('action', filterAction);
      if (filterUser) params.append('userId', filterUser);
      if (dateFrom) params.append('dateFrom', dateFrom);
      if (dateTo) params.append('dateTo', dateTo);

      const response = await fetch(`/api/admin/audit-logs/export?${params}`);
      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `audit-logs-${new Date().toISOString()}.${format}`;
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      document.body.removeChild(a);

      toast({
        title: 'نجح التصدير',
        description: `تم تصدير ${logs.length} سجل`,
        status: 'success',
        duration: 3000,
      });
    } catch (error) {
      console.error('Export failed:', error);
      toast({
        title: 'فشل التصدير',
        status: 'error',
        duration: 3000,
      });
    }
  };

  const getActionBadge = (action: string) => {
    if (action.includes('CREATE') || action.includes('CONFIRMED')) {
      return <Badge colorScheme="green">{action}</Badge>;
    }
    if (action.includes('DELETE') || action.includes('CANCEL')) {
      return <Badge colorScheme="red">{action}</Badge>;
    }
    if (action.includes('UPDATE') || action.includes('EDIT')) {
      return <Badge colorScheme="blue">{action}</Badge>;
    }
    if (action.includes('AI_')) {
      return <Badge colorScheme="purple">{action}</Badge>;
    }
    return <Badge colorScheme="gray">{action}</Badge>;
  };

  const filteredLogs = logs.filter(log => {
    if (!searchQuery) return true;
    const search = searchQuery.toLowerCase();
    return (
      log.action.toLowerCase().includes(search) ||
      log.resource.toLowerCase().includes(search) ||
      log.User?.name.toLowerCase().includes(search) ||
      log.User?.email.toLowerCase().includes(search)
    );
  });

  return (
    <VStack spacing={6} align="stretch" dir="rtl">
      {/* Header */}
      <HStack justify="space-between">
        <Box>
          <Text fontSize="2xl" fontWeight="bold">
            سجل المراجعة والامتثال
          </Text>
          <Text color="gray.600">جميع العمليات والإجراءات المسجلة</Text>
        </Box>
        <HStack spacing={3}>
          <Menu>
            <MenuButton
              as={Button}
              leftIcon={<Icon as={FiDownload} />}
              colorScheme="purple"
              variant="outline"
            >
              تصدير
            </MenuButton>
            <MenuList>
              <MenuItem onClick={() => exportLogs('csv')}>تصدير CSV</MenuItem>
              <MenuItem onClick={() => exportLogs('json')}>تصدير JSON</MenuItem>
            </MenuList>
          </Menu>
          <Button
            leftIcon={<Icon as={FiFilter} />}
            variant="outline"
            onClick={loadAuditLogs}
          >
            تحديث
          </Button>
        </HStack>
      </HStack>

      {/* Filters */}
      <HStack spacing={4}>
        <Box flex={1}>
          <InputGroup>
            <InputLeftElement>
              <Icon as={FiSearch} color="gray.400" />
            </InputLeftElement>
            <Input
              placeholder="بحث في السجلات..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </InputGroup>
        </Box>
        <Select
          placeholder="نوع العملية"
          value={filterAction}
          onChange={(e) => setFilterAction(e.target.value)}
          w="200px"
        >
          <option value="AI_TOOL_">عمليات الذكاء الاصطناعي</option>
          <option value="CREATE">إنشاء</option>
          <option value="UPDATE">تحديث</option>
          <option value="DELETE">حذف</option>
          <option value="CONFIRMED">تأكيد</option>
        </Select>
        <Input
          type="date"
          placeholder="من تاريخ"
          value={dateFrom}
          onChange={(e) => setDateFrom(e.target.value)}
          w="200px"
        />
        <Input
          type="date"
          placeholder="إلى تاريخ"
          value={dateTo}
          onChange={(e) => setDateTo(e.target.value)}
          w="200px"
        />
      </HStack>

      {/* Stats */}
      <HStack spacing={4} p={4} bg="gray.50" borderRadius="lg">
        <Box flex={1} textAlign="center">
          <Text fontSize="2xl" fontWeight="bold" color="purple.600">
            {logs.length}
          </Text>
          <Text fontSize="sm" color="gray.600">
            إجمالي السجلات
          </Text>
        </Box>
        <Box flex={1} textAlign="center">
          <Text fontSize="2xl" fontWeight="bold" color="green.600">
            {logs.filter(l => l.action.includes('AI_TOOL_')).length}
          </Text>
          <Text fontSize="sm" color="gray.600">
            عمليات AI
          </Text>
        </Box>
        <Box flex={1} textAlign="center">
          <Text fontSize="2xl" fontWeight="bold" color="blue.600">
            {new Set(logs.map(l => l.userId)).size}
          </Text>
          <Text fontSize="sm" color="gray.600">
            مستخدمون نشطون
          </Text>
        </Box>
      </HStack>

      {/* Table */}
      <Box borderWidth="1px" borderRadius="lg" overflowX="auto">
        {isLoading ? (
          <Box py={12} textAlign="center">
            <Spinner size="xl" color="purple.500" />
            <Text mt={4} color="gray.600">
              جاري التحميل...
            </Text>
          </Box>
        ) : filteredLogs.length === 0 ? (
          <Box py={12} textAlign="center">
            <Icon as={FiAlertCircle} boxSize={12} color="gray.400" mb={4} />
            <Text color="gray.600">لا توجد سجلات</Text>
          </Box>
        ) : (
          <Table variant="simple">
            <Thead bg="gray.50">
              <Tr>
                <Th>الوقت</Th>
                <Th>المستخدم</Th>
                <Th>العملية</Th>
                <Th>المورد</Th>
                <Th>التفاصيل</Th>
                <Th>الحالة</Th>
                <Th></Th>
              </Tr>
            </Thead>
            <Tbody>
              {filteredLogs.map((log) => (
                <Tr key={log.id} _hover={{ bg: 'gray.50' }}>
                  <Td>
                    <Text fontSize="sm">
                      {new Date(log.createdAt).toLocaleString('ar-SA')}
                    </Text>
                  </Td>
                  <Td>
                    <VStack align="start" spacing={0}>
                      <Text fontSize="sm" fontWeight="medium">
                        {log.User?.name || 'غير معروف'}
                      </Text>
                      <Text fontSize="xs" color="gray.600">
                        {log.User?.email}
                      </Text>
                    </VStack>
                  </Td>
                  <Td>{getActionBadge(log.action)}</Td>
                  <Td>
                    <Text fontSize="sm">{log.resource}</Text>
                    {log.resourceId && (
                      <Text fontSize="xs" color="gray.600">
                        {log.resourceId}
                      </Text>
                    )}
                  </Td>
                  <Td>
                    <Text fontSize="xs" noOfLines={2}>
                      {typeof log.details === 'object'
                        ? JSON.stringify(log.details).substring(0, 50) + '...'
                        : log.details}
                    </Text>
                  </Td>
                  <Td>
                    <Icon
                      as={FiCheckCircle}
                      color="green.500"
                      boxSize={5}
                    />
                  </Td>
                  <Td>
                    <Menu>
                      <MenuButton
                        as={IconButton}
                        icon={<Icon as={FiMoreVertical} />}
                        variant="ghost"
                        size="sm"
                      />
                      <MenuList>
                        <MenuItem icon={<Icon as={FiEye} />}>
                          عرض التفاصيل الكاملة
                        </MenuItem>
                      </MenuList>
                    </Menu>
                  </Td>
                </Tr>
              ))}
            </Tbody>
          </Table>
        )}
      </Box>
    </VStack>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import {
  Box,
  HStack,
  VStack,
  Text,
  Switch,
  Badge,
  Tooltip,
  useToast,
  Spinner,
  Icon,
  Flex,
} from '@chakra-ui/react';
import { FiZap, FiUser, FiInfo } from 'react-icons/fi';

interface DispatchModeToggleProps {
  showLabel?: boolean;
  size?: 'sm' | 'md' | 'lg';
}

export default function DispatchModeToggle({ 
  showLabel = true, 
  size = 'md' 
}: DispatchModeToggleProps) {
  const [mode, setMode] = useState<'auto' | 'manual'>('manual');
  const [isLoading, setIsLoading] = useState(true);
  const [isSwitching, setIsSwitching] = useState(false);
  const toast = useToast();

  useEffect(() => {
    fetchCurrentMode();
  }, []);

  const fetchCurrentMode = async () => {
    try {
      const response = await fetch('/api/admin/dispatch/mode');
      const data = await response.json();

      if (data.success) {
        setMode(data.data.mode);
      }
    } catch (error) {
      console.error('Error fetching dispatch mode:', error);
      // Default to manual on error
      setMode('manual');
    } finally {
      setIsLoading(false);
    }
  };

  const handleToggle = async () => {
    if (isSwitching) return;

    const newMode = mode === 'auto' ? 'manual' : 'auto';
    setIsSwitching(true);

    try {
      const response = await fetch('/api/admin/dispatch/mode', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ mode: newMode })
      });

      const data = await response.json();

      if (data.success) {
        setMode(newMode);
        toast({
          title: 'Dispatch Mode Updated',
          description: `Switched to ${newMode === 'auto' ? 'Automatic' : 'Manual'} assignment mode`,
          status: 'success',
          duration: 4000,
          isClosable: true,
        });
      } else {
        throw new Error(data.error || 'Failed to update mode');
      }
    } catch (error) {
      toast({
        title: 'Update Failed',
        description: error instanceof Error ? error.message : 'Failed to update dispatch mode',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setIsSwitching(false);
    }
  };

  if (isLoading) {
    return (
      <HStack spacing={2} bg="#111111" px={3} py={2} borderRadius="lg" border="1px solid" borderColor="#333333">
        <Spinner size="sm" color="#2563eb" />
        <Text fontSize="sm" color="#9ca3af">Loading...</Text>
      </HStack>
    );
  }

  return (
    <Tooltip
      label={
        mode === 'auto'
          ? 'Auto mode: Orders are automatically assigned to the best available driver'
          : 'Manual mode: You manually assign orders to drivers'
      }
      placement="bottom"
      hasArrow
    >
      <Flex
        align="center"
        gap={3}
        px={4}
        py={2.5}
        borderRadius="lg"
        bg={mode === 'auto' 
          ? 'linear-gradient(135deg, #10b981 0%, #059669 100%)' 
          : 'linear-gradient(135deg, #2563eb 0%, #1d4ed8 100%)'}
        borderWidth="2px"
        borderColor={mode === 'auto' ? '#10b981' : '#2563eb'}
        boxShadow={mode === 'auto'
          ? '0 4px 16px rgba(16, 185, 129, 0.4), 0 0 20px rgba(16, 185, 129, 0.2)'
          : '0 4px 16px rgba(37, 99, 235, 0.4), 0 0 20px rgba(37, 99, 235, 0.2)'}
        transition="all 0.3s cubic-bezier(0.4, 0, 0.2, 1)"
        cursor="pointer"
        position="relative"
        overflow="hidden"
        _before={{
          content: '""',
          position: 'absolute',
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          background: mode === 'auto'
            ? 'linear-gradient(135deg, rgba(16, 185, 129, 0.1) 0%, rgba(5, 150, 105, 0.1) 100%)'
            : 'linear-gradient(135deg, rgba(37, 99, 235, 0.1) 0%, rgba(29, 78, 216, 0.1) 100%)',
          pointerEvents: 'none',
        }}
        _hover={{
          transform: 'translateY(-2px)',
          boxShadow: mode === 'auto'
            ? '0 6px 24px rgba(16, 185, 129, 0.6), 0 0 30px rgba(16, 185, 129, 0.3)'
            : '0 6px 24px rgba(37, 99, 235, 0.6), 0 0 30px rgba(37, 99, 235, 0.3)',
        }}
        _active={{
          transform: 'translateY(0)',
        }}
      >
        <Icon 
          as={mode === 'auto' ? FiZap : FiUser} 
          color="#FFFFFF"
          boxSize={size === 'lg' ? 6 : size === 'sm' ? 4 : 5}
          position="relative"
          zIndex={1}
          filter="drop-shadow(0 2px 4px rgba(0, 0, 0, 0.3))"
        />
        
        {showLabel && (
          <VStack align="start" spacing={0.5} position="relative" zIndex={1}>
            <Text 
              fontSize={size === 'lg' ? 'md' : 'sm'} 
              fontWeight="bold"
              color="#FFFFFF"
              letterSpacing="0.3px"
              textShadow="0 2px 8px rgba(0, 0, 0, 0.3)"
            >
              Dispatch Mode
            </Text>
            <Text 
              fontSize={size === 'lg' ? 'sm' : 'xs'} 
              color="rgba(255, 255, 255, 0.9)"
              fontWeight="semibold"
              letterSpacing="0.5px"
            >
              {mode === 'auto' ? 'Automatic' : 'Manual'}
            </Text>
          </VStack>
        )}

        <Badge
          bg="rgba(255, 255, 255, 0.2)"
          color="#FFFFFF"
          fontSize={size === 'lg' ? 'sm' : 'xs'}
          px={3}
          py={1}
          borderRadius="full"
          fontWeight="bold"
          letterSpacing="0.5px"
          border="1px solid rgba(255, 255, 255, 0.3)"
          backdropFilter="blur(10px)"
          boxShadow="0 2px 8px rgba(0, 0, 0, 0.2)"
          position="relative"
          zIndex={1}
        >
          {mode.toUpperCase()}
        </Badge>

        <Box position="relative" zIndex={1}>
          <Switch
            isChecked={mode === 'auto'}
            onChange={handleToggle}
            isDisabled={isSwitching}
            colorScheme={mode === 'auto' ? 'green' : 'blue'}
            size={size === 'lg' ? 'lg' : size === 'sm' ? 'sm' : 'md'}
            sx={{
              'span[data-checked]': {
                bg: '#FFFFFF',
              },
            }}
          />
        </Box>

        {isSwitching && (
          <Spinner 
            size="sm" 
            color="#FFFFFF"
            position="absolute"
            right={2}
            top="50%"
            transform="translateY(-50%)"
            zIndex={2}
          />
        )}
      </Flex>
    </Tooltip>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import {
  Box,
  Container,
  VStack,
  HStack,
  Heading,
  Text,
  Button,
  Card,
  CardBody,
  CardHeader,
  SimpleGrid,
  Stat,
  StatLabel,
  StatNumber,
  StatHelpText,
  Badge,
  Alert,
  AlertIcon,
  AlertTitle,
  AlertDescription,
  Table,
  Thead,
  Tbody,
  Tr,
  Th,
  Td,
  useToast,
  Spinner,
  Progress,
  Divider,
  Icon,
  Select,
  ButtonGroup,
} from '@chakra-ui/react';
import {
  FaExclamationTriangle,
  FaClock,
  FaUserTie,
  FaMoneyBillWave,
  FaTruck,
  FaCheckCircle,
  FaSync,
  FaBell,
  FaUsers,
  FaMapMarkerAlt,
} from 'react-icons/fa';

interface EnhancedAdminDashboardProps {
  refreshInterval?: number;
}

export default function EnhancedAdminDashboard({ 
  refreshInterval = 30000 // 30 seconds
}: EnhancedAdminDashboardProps) {
  const [dashboardData, setDashboardData] = useState<any>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [selectedDriver, setSelectedDriver] = useState<string>('');
  const toast = useToast();

  // Load dashboard data
  useEffect(() => {
    loadDashboardData();
    
    // Set up auto-refresh
    const interval = setInterval(() => {
      loadDashboardData(true); // Silent refresh
    }, refreshInterval);

    return () => clearInterval(interval);
  }, [refreshInterval]);

  const loadDashboardData = async (silent = false) => {
    try {
      if (!silent) setIsLoading(true);
      else setIsRefreshing(true);
      
      setError(null);

      const response = await fetch('/api/admin/dashboard-enhanced');
      
      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || 'Failed to load dashboard data');
      }

      const data = await response.json();
      setDashboardData(data.data);
      
      console.log('✅ Admin dashboard data loaded:', data.data.statistics);

    } catch (error) {
      console.error('❌ Error loading dashboard data:', error);
      setError(error instanceof Error ? error.message : 'Failed to load data');
      
      if (!silent) {
        toast({
          title: 'Error Loading Dashboard',
          description: 'Failed to load dashboard data. Please try again.',
          status: 'error',
          duration: 5000,
          isClosable: true,
        });
      }
    } finally {
      setIsLoading(false);
      setIsRefreshing(false);
    }
  };

  const handleQuickAssign = async (bookingId: string, driverId?: string) => {
    try {
      const targetDriverId = driverId || selectedDriver;
      
      if (!targetDriverId) {
        toast({
          title: 'No Driver Selected',
          description: 'Please select a driver to assign the job.',
          status: 'warning',
          duration: 3000,
          isClosable: true,
        });
        return;
      }

      const response = await fetch('/api/admin/dispatch/assign', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          jobId: bookingId,
          driverId: targetDriverId
        })
      });

      if (response.ok) {
        toast({
          title: 'Job Assigned!',
          description: 'The job has been successfully assigned to the driver.',
          status: 'success',
          duration: 3000,
          isClosable: true,
        });
        
        // Reload dashboard data
        await loadDashboardData();
      } else {
        const errorData = await response.json();
        throw new Error(errorData.error || 'Assignment failed');
      }
    } catch (error) {
      toast({
        title: 'Assignment Failed',
        description: error instanceof Error ? error.message : 'Failed to assign job.',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    }
  };

  const getPriorityColor = (priority: string) => {
    switch (priority) {
      case 'high': return 'red';
      case 'medium': return 'orange';
      default: return 'green';
    }
  };

  const formatWaitingTime = (minutes: number) => {
    if (minutes < 60) return `${minutes}m`;
    const hours = Math.floor(minutes / 60);
    const remainingMinutes = minutes % 60;
    return `${hours}h ${remainingMinutes}m`;
  };

  if (isLoading) {
    return (
      <Container maxW="7xl" py={8}>
        <VStack spacing={8} align="center">
          <Spinner size="xl" color="blue.500" />
          <Text>Loading admin dashboard...</Text>
        </VStack>
      </Container>
    );
  }

  if (error) {
    return (
      <Container maxW="7xl" py={8}>
        <Alert status="error" borderRadius="lg">
          <AlertIcon />
          <Box>
            <AlertTitle>Dashboard Error</AlertTitle>
            <AlertDescription>{error}</AlertDescription>
            <Button mt={3} size="sm" onClick={() => loadDashboardData()}>
              Try Again
            </Button>
          </Box>
        </Alert>
      </Container>
    );
  }

  if (!dashboardData) {
    return (
      <Container maxW="7xl" py={8}>
        <Alert status="warning" borderRadius="lg">
          <AlertIcon />
          <AlertDescription>No dashboard data available.</AlertDescription>
        </Alert>
      </Container>
    );
  }

  const { alerts, statistics, unassignedBookings, availableDrivers, recentActivity } = dashboardData;

  return (
    <Container maxW="7xl" py={8}>
      <VStack spacing={8} align="stretch">
        {/* Header with Refresh */}
        <HStack justify="space-between">
          <Box>
            <Heading size="lg" mb={2}>
              Admin Dashboard
            </Heading>
            <Text color="gray.600">
              Real-time overview of bookings, assignments, and operations
            </Text>
          </Box>
          <Button
            leftIcon={<FaSync />}
            onClick={() => loadDashboardData()}
            isLoading={isRefreshing}
            loadingText="Refreshing..."
            variant="outline"
          >
            Refresh
          </Button>
        </HStack>

        {/* Alerts Section */}
        {alerts.unassignedBookings > 0 && (
          <Alert 
            status={alerts.slaBreached > 0 ? 'error' : 'warning'} 
            borderRadius="lg"
          >
            <AlertIcon />
            <Box>
              <AlertTitle>
                {alerts.unassignedBookings} Booking{alerts.unassignedBookings > 1 ? 's' : ''} Need Driver Assignment
              </AlertTitle>
              <AlertDescription>
                {alerts.slaBreached > 0 && (
                  <Text color="red.600" fontWeight="bold">
                    🚨 {alerts.slaBreached} booking{alerts.slaBreached > 1 ? 's' : ''} have breached SLA (30+ minutes)
                  </Text>
                )}
                {alerts.urgentBookings > 0 && (
                  <Text color="orange.600">
                    ⚠️ {alerts.urgentBookings} urgent booking{alerts.urgentBookings > 1 ? 's' : ''} require immediate attention
                  </Text>
                )}
              </AlertDescription>
            </Box>
          </Alert>
        )}

        {/* Statistics Grid */}
        <SimpleGrid columns={{ base: 1, md: 2, lg: 6 }} spacing={6}>
          <Card>
            <CardBody>
              <Stat>
                <StatLabel>Today's Revenue</StatLabel>
                <StatNumber>£{statistics.todayRevenue.toFixed(2)}</StatNumber>
                <StatHelpText>
                  <Icon as={FaMoneyBillWave} color="green.500" />
                </StatHelpText>
              </Stat>
            </CardBody>
          </Card>

          <Card>
            <CardBody>
              <Stat>
                <StatLabel>Active Jobs</StatLabel>
                <StatNumber>{statistics.activeJobs}</StatNumber>
                <StatHelpText>
                  <Icon as={FaTruck} color="blue.500" />
                </StatHelpText>
              </Stat>
            </CardBody>
          </Card>

          <Card>
            <CardBody>
              <Stat>
                <StatLabel>Pending Assignments</StatLabel>
                <StatNumber color={statistics.pendingAssignments > 0 ? 'red.500' : 'green.500'}>
                  {statistics.pendingAssignments}
                </StatNumber>
                <StatHelpText>
                  <Icon as={FaExclamationTriangle} color={statistics.pendingAssignments > 0 ? 'red.500' : 'green.500'} />
                </StatHelpText>
              </Stat>
            </CardBody>
          </Card>

          <Card>
            <CardBody>
              <Stat>
                <StatLabel>Completed Today</StatLabel>
                <StatNumber>{statistics.completedToday}</StatNumber>
                <StatHelpText>
                  <Icon as={FaCheckCircle} color="green.500" />
                </StatHelpText>
              </Stat>
            </CardBody>
          </Card>

          <Card>
            <CardBody>
              <Stat>
                <StatLabel>Driver Utilization</StatLabel>
                <StatNumber>{statistics.driverUtilization}%</StatNumber>
                <StatHelpText>
                  <Icon as={FaUsers} color="blue.500" />
                </StatHelpText>
              </Stat>
            </CardBody>
          </Card>

          <Card>
            <CardBody>
              <Stat>
                <StatLabel>Today's Bookings</StatLabel>
                <StatNumber>{statistics.todayBookings}</StatNumber>
                <StatHelpText>
                  <Icon as={FaBell} color="purple.500" />
                </StatHelpText>
              </Stat>
            </CardBody>
          </Card>
        </SimpleGrid>

        {/* Unassigned Bookings Section */}
        {unassignedBookings.length > 0 && (
          <Card>
            <CardHeader>
              <HStack justify="space-between">
                <Heading size="md">
                  🚨 Bookings Awaiting Driver Assignment
                </Heading>
                <HStack>
                  <Select
                    placeholder="Select driver for quick assign"
                    value={selectedDriver}
                    onChange={(e) => setSelectedDriver(e.target.value)}
                    size="sm"
                    maxW="200px"
                  >
                    {availableDrivers.map((driver: any) => (
                      <option key={driver.id} value={driver.id}>
                        {driver.name} ({driver.currentJobs} jobs)
                      </option>
                    ))}
                  </Select>
                </HStack>
              </HStack>
            </CardHeader>
            <CardBody>
              <Table size="sm">
                <Thead>
                  <Tr>
                    <Th>Booking</Th>
                    <Th>Customer</Th>
                    <Th>Route</Th>
                    <Th>Scheduled</Th>
                    <Th>Amount</Th>
                    <Th>Waiting</Th>
                    <Th>Priority</Th>
                    <Th>Actions</Th>
                  </Tr>
                </Thead>
                <Tbody>
                  {unassignedBookings.map((booking: any) => (
                    <Tr key={booking.id}>
                      <Td>
                        <Text fontFamily="mono" fontSize="sm">
                          {booking.reference}
                        </Text>
                      </Td>
                      <Td>
                        <VStack align="start" spacing={0}>
                          <Text fontSize="sm" fontWeight="medium">
                            {booking.customer}
                          </Text>
                          <Text fontSize="xs" color="gray.500">
                            {booking.customerPhone}
                          </Text>
                        </VStack>
                      </Td>
                      <Td>
                        <VStack align="start" spacing={0}>
                          <Text fontSize="xs">
                            From: {booking.pickupAddress}
                          </Text>
                          <Text fontSize="xs">
                            To: {booking.dropoffAddress}
                          </Text>
                        </VStack>
                      </Td>
                      <Td>
                        <Text fontSize="sm">
                          {new Date(booking.scheduledAt).toLocaleDateString()}
                        </Text>
                        <Text fontSize="xs" color="gray.500">
                          {new Date(booking.scheduledAt).toLocaleTimeString('en-GB', {
                            hour: '2-digit',
                            minute: '2-digit'
                          })}
                        </Text>
                      </Td>
                      <Td>
                        <Text fontWeight="bold">
                          £{booking.totalAmount.toFixed(2)}
                        </Text>
                      </Td>
                      <Td>
                        <Badge 
                          colorScheme={booking.slaBreached ? 'red' : 'yellow'}
                          size="sm"
                        >
                          {formatWaitingTime(booking.waitingMinutes)}
                        </Badge>
                      </Td>
                      <Td>
                        <Badge 
                          colorScheme={getPriorityColor(booking.priority)}
                          size="sm"
                        >
                          {booking.priority}
                        </Badge>
                      </Td>
                      <Td>
                        <ButtonGroup size="xs" spacing={1}>
                          <Button
                            colorScheme="blue"
                            onClick={() => handleQuickAssign(booking.id)}
                            isDisabled={!selectedDriver}
                          >
                            Assign
                          </Button>
                          <Button variant="outline">
                            View
                          </Button>
                        </ButtonGroup>
                      </Td>
                    </Tr>
                  ))}
                </Tbody>
              </Table>
            </CardBody>
          </Card>
        )}

        {/* Available Drivers Section */}
        <Card>
          <CardHeader>
            <Heading size="md">
              🚛 Available Drivers ({availableDrivers.length})
            </Heading>
          </CardHeader>
          <CardBody>
            <SimpleGrid columns={{ base: 1, md: 2, lg: 3 }} spacing={4}>
              {availableDrivers.map((driver: any) => (
                <Card key={driver.id} size="sm" variant="outline">
                  <CardBody>
                    <VStack align="start" spacing={2}>
                      <HStack justify="space-between" w="100%">
                        <Text fontWeight="medium">{driver.name}</Text>
                        <Badge 
                          colorScheme={driver.isOnline ? 'green' : 'gray'}
                          size="sm"
                        >
                          {driver.isOnline ? 'Online' : 'Offline'}
                        </Badge>
                      </HStack>
                      <Text fontSize="sm" color="gray.600">
                        Current jobs: {driver.currentJobs}/3
                      </Text>
                      <Progress 
                        value={(driver.currentJobs / 3) * 100} 
                        size="sm" 
                        colorScheme={driver.currentJobs >= 3 ? 'red' : 'green'}
                        w="100%"
                      />
                    </VStack>
                  </CardBody>
                </Card>
              ))}
            </SimpleGrid>
          </CardBody>
        </Card>

        {/* Recent Activity */}
        <Card>
          <CardHeader>
            <Heading size="md">Recent Activity</Heading>
          </CardHeader>
          <CardBody>
            <VStack align="stretch" spacing={3}>
              {recentActivity.slice(0, 5).map((activity: any) => (
                <HStack key={activity.id} justify="space-between" p={3} bg="gray.50" borderRadius="md">
                  <HStack>
                    <Icon as={getActivityIcon(activity.action)} color="blue.500" />
                    <VStack align="start" spacing={0}>
                      <Text fontSize="sm" fontWeight="medium">
                        {formatActivityMessage(activity.action)}
                      </Text>
                      <Text fontSize="xs" color="gray.600">
                        by {activity.actorName}
                      </Text>
                    </VStack>
                  </HStack>
                  <Text fontSize="xs" color="gray.500">
                    {new Date(activity.createdAt).toLocaleTimeString()}
                  </Text>
                </HStack>
              ))}
            </VStack>
          </CardBody>
        </Card>
      </VStack>
    </Container>
  );
}

// Helper functions
function getActivityIcon(action: string) {
  switch (action) {
    case 'booking_created': return FaBell;
    case 'job_assigned': return FaUserTie;
    case 'booking_completed': return FaCheckCircle;
    default: return FaBell;
  }
}

function formatActivityMessage(action: string) {
  switch (action) {
    case 'booking_created': return 'New booking created';
    case 'job_assigned': return 'Job assigned to driver';
    case 'booking_completed': return 'Booking completed';
    default: return action.replace('_', ' ');
  }
}

