// Flashing animation for priority indicators
const pulseAnimation = keyframes`
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.6; transform: scale(1.1); }
`;

const fastPulseAnimation = keyframes`
  0%, 100% { opacity: 1; transform: scale(1); box-shadow: 0 0 0 0 rgba(239, 68, 68, 0.7); }
  50% { opacity: 0.7; transform: scale(1.15); box-shadow: 0 0 0 10px rgba(239, 68, 68, 0); }
`;

// Priority calculation based on start time
function calculateRoutePriority(startTime: Date): {
  level: 'urgent' | 'high' | 'medium' | 'low' | 'future';
  color: string;
  bgColor: string;
  label: string;
  animation: string;
  sortOrder: number;
} {
  const now = new Date();
  const start = new Date(startTime);
  const hoursUntil = differenceInHours(start, now);
  const daysUntil = differenceInDays(start, now);

  // Tomorrow (within 24-48 hours)
  if (hoursUntil >= 0 && hoursUntil <= 48) {
    return {
      level: 'urgent',
      color: 'red.500',
      bgColor: 'red.50',
      label: 'Tomorrow',
      animation: `${fastPulseAnimation} 1.5s ease-in-out infinite`,
      sortOrder: 1
    };
  }
  
  // Day after tomorrow (48-72 hours)
  if (hoursUntil > 48 && hoursUntil <= 72) {
    return {
      level: 'high',
      color: 'orange.500',
      bgColor: 'orange.50',
      label: 'Day After',
      animation: `${pulseAnimation} 2s ease-in-out infinite`,
      sortOrder: 2
    };
  }
  
  // This week (3-7 days)
  if (daysUntil > 3 && daysUntil <= 7) {
    return {
      level: 'medium',
      color: 'yellow.500',
      bgColor: 'yellow.50',
      label: 'This Week',
      animation: `${pulseAnimation} 2.5s ease-in-out infinite`,
      sortOrder: 3
    };
  }
  
  // Next week (7-14 days)
  if (daysUntil > 7 && daysUntil <= 14) {
    return {
      level: 'low',
      color: 'green.400',
      bgColor: 'green.50',
      label: 'Next Week',
      animation: `${pulseAnimation} 3s ease-in-out infinite`,
      sortOrder: 4
    };
  }
  
  // Future (14+ days)
  return {
    level: 'future',
    color: 'green.600',
    bgColor: 'green.50',
    label: 'Future',
    animation: `${pulseAnimation} 3.5s ease-in-out infinite`,
    sortOrder: 5
  };
}

interface Route {
  id: string;
  reference?: string;
  status: string;
  driverId: string | null;
  driverName: string;
  totalDrops: number;
  completedDrops: number;
  startTime: Date;
  totalOutcome: number;
  progress: number;
  optimizedDistanceKm: number | null;
  serviceTier: string;
  drops: any[];
  acceptedAt?: Date | null;
  declinedAt?: Date | null;
  acceptanceStatus?: string | null;
  delayStatus?: string | null;
}

type RouteGenerationMode = 'manual' | 'semi' | 'automatic';

interface EnhancedAdminRoutesDashboardProps {
  declinedNotifications?: string[];
  acceptedNotifications?: string[];
  inProgressNotifications?: string[];
}

const EnhancedAdminRoutesDashboard = ({ 
  declinedNotifications = [],
  acceptedNotifications = [],
  inProgressNotifications = []
}: EnhancedAdminRoutesDashboardProps) => {
  const [routes, setRoutes] = useState<Route[]>([]);
  const [drivers, setDrivers] = useState<any[]>([]);
  const [metrics, setMetrics] = useState<any>({});
  const [isLoading, setIsLoading] = useState(true);
  const [selectedRoute, setSelectedRoute] = useState<Route | null>(null);
  const [statusFilter, setStatusFilter] = useState('all');
  const [activeTab, setActiveTab] = useState(0);
  const [refreshInterval, setRefreshInterval] = useState(30000);
  const [schedulerStats, setSchedulerStats] = useState<any>(null);
  const [routeGenerationMode, setRouteGenerationMode] = useState<RouteGenerationMode>('semi');
  const [isSwitchingMode, setIsSwitchingMode] = useState(false);
  const [isTriggering, setIsTriggering] = useState(false);
  const [isReassigning, setIsReassigning] = useState(false);
  const [loadError, setLoadError] = useState<string | null>(null);
  
  const { isOpen: isCreateOpen, onOpen: onCreateOpen, onClose: onCreateClose } = useDisclosure();
  const { isOpen: isEditOpen, onOpen: onEditOpen, onClose: onEditClose } = useDisclosure();
  const { isOpen: isReassignOpen, onOpen: onReassignOpen, onClose: onReassignClose } = useDisclosure();
  const { isOpen: isAutoCreateOpen, onOpen: onAutoCreateOpen, onClose: onAutoCreateClose } = useDisclosure();
  const { isOpen: isRemoveOpen, onOpen: onRemoveOpen, onClose: onRemoveClose } = useDisclosure();
  const { isOpen: isRemoveDropOpen, onOpen: onRemoveDropOpen, onClose: onRemoveDropClose } = useDisclosure();
  const { isOpen: isDriversListOpen, onOpen: onDriversListOpen, onClose: onDriversListClose } = useDisclosure();
  const { isOpen: isDistancesOpen, onOpen: onDistancesOpen, onClose: onDistancesClose } = useDisclosure();
  
  const [selectedRouteForRemoval, setSelectedRouteForRemoval] = useState<Route | null>(null);
  const [removalType, setRemovalType] = useState<'single' | 'all'>('single');
  const [removalReason, setRemovalReason] = useState('');
  
  const toast = useToast();

  // Listen for driver selection from map
  useEffect(() => {
    const handleMessage = (event: MessageEvent) => {
      if (event.data.type === 'selectDriver' && event.data.driverId) {
        const driverSelect = document.getElementById('driver-select') as HTMLSelectElement;
        if (driverSelect) {
          driverSelect.value = event.data.driverId;
          // Trigger change event
          driverSelect.dispatchEvent(new Event('change', { bubbles: true }));
        }
      }
    };

    window.addEventListener('message', handleMessage);
    return () => window.removeEventListener('message', handleMessage);
  }, []);

  useEffect(() => {
    loadData();
    const interval = setInterval(loadData, refreshInterval);

    // Set up Pusher for real-time route updates
    if (typeof window !== 'undefined' && (window as any).Pusher) {
      const PUSHER_KEY = '407cb06c423e6c032e9c';
      const PUSHER_CLUSTER = 'eu';
      const pusher = new (window as any).Pusher(PUSHER_KEY, {
        cluster: PUSHER_CLUSTER,
      });

      const channel = pusher.subscribe('admin-channel');

      // Listen for route accepted events
      channel.bind('route-accepted', (data: any) => {
        console.log('🎉 Route accepted notification:', data);
        toast({
          title: '✅ Route Accepted',
          description: `${data.driverName} accepted a route with ${data.dropCount} stops`,
          status: 'success',
          duration: 5000,
          isClosable: true,
          position: 'top-right',
        });
        loadData(); // Reload routes
      });

      // Listen for route completed events
      channel.bind('route-completed', (data: any) => {
        console.log('✅ Route completed notification:', data);
        toast({
          title: 'Route Completed',
          description: `${data.driverName} completed route with ${data.totalDrops} stops`,
          status: 'success',
          duration: 4000,
          isClosable: true,
        });
        loadData(); // Reload routes
      });

      return () => {
        channel.unbind_all();
        channel.unsubscribe();
        clearInterval(interval);
      };
    }

    return () => clearInterval(interval);
  }, [refreshInterval, statusFilter, toast]);

  // Set initial mode based on scheduler status (only once)
  useEffect(() => {
    if (schedulerStats && routeGenerationMode === 'semi') {
      if (schedulerStats.enabled) {
        setRouteGenerationMode('automatic');
      }
      // If not enabled, keep the default 'semi' mode
    }
  }, [schedulerStats]);

  const loadData = async () => {
    try {
      const params = new URLSearchParams();
      if (statusFilter !== 'all') params.append('status', statusFilter);

      const [routesRes, schedulerRes] = await Promise.all([
        fetch(`/api/admin/routes?${params}`),
        fetch('/api/admin/routes/scheduler'),
      ]);

      const routesData = await routesRes.json();
      const schedulerData = await schedulerRes.json();

      if (routesData.success) {
        // Fix totalDrops to use actual drops.length
        const routesWithCorrectCounts = routesData.routes.map((route: any) => ({
          ...route,
          totalDrops: route.drops?.length || route.totalDrops || 0,
        }));
        setRoutes(routesWithCorrectCounts);
        setDrivers(routesData.drivers);
        setMetrics(routesData.metrics);
        setLoadError(null);
      } else {
        setLoadError(routesData.error || 'Failed to load routes');
      }

      if (schedulerData.success) {
        setSchedulerStats(schedulerData.scheduler);
      }
    } catch (error) {
      console.error('Failed to load routes:', error);
      const message = error instanceof Error ? error.message : 'Unknown error';
      setLoadError(message);
      if (!loadError) {
        toast({
          title: 'Failed to load operations data',
          description: message,
          status: 'error',
          duration: 5000,
          isClosable: true,
        });
      }
    } finally {
      setIsLoading(false);
    }
  };

  // handleAutoCreate removed - now handled by SmartRouteGeneratorModal

  const handleReassignDriver = async (routeId: string, newDriverId: string, reason?: string) => {
    if (isReassigning) {
      return;
    }

    setIsReassigning(true);

    try {
      // Use the new reassign API endpoint
      const response = await fetch(`/api/admin/routes/${routeId}/reassign`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          driverId: newDriverId,
          reason: reason || 'Reassigned by admin'
        })
      });

      const data = await response.json();

      if (response.ok && data.success) {
        toast({
          title: 'Driver Reassigned',
          description: data.message || 'Driver reassigned successfully',
          status: 'success',
          duration: 5000,
          isClosable: true,
        });
        loadData();
        onReassignClose();
      } else {
        throw new Error(data.error || 'Failed to reassign driver');
      }
    } catch (error) {
      toast({
        title: 'Reassignment Failed',
        description: error instanceof Error ? error.message : 'Failed to reassign driver',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setIsReassigning(false);
    }
  };

  const handleAssignDriver = async (routeId: string, driverId: string, reason?: string) => {
    if (isReassigning) {
      return;
    }

    setIsReassigning(true);

    try {
      // Use the new assign API endpoint for first-time assignment
      const response = await fetch(`/api/admin/routes/${routeId}/assign`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          driverId: driverId,
          reason: reason || 'Assigned by admin'
        })
      });

      const data = await response.json();

      if (response.ok && data.success) {
        toast({
          title: 'Driver Assigned',
          description: data.message || 'Driver assigned successfully',
          status: 'success',
          duration: 5000,
          isClosable: true,
        });
        loadData();
        onReassignClose();
      } else {
        throw new Error(data.error || 'Failed to assign driver');
      }
    } catch (error) {
      toast({
        title: 'Assignment Failed',
        description: error instanceof Error ? error.message : 'Failed to assign driver',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setIsReassigning(false);
    }
  };

  const handleCancelRoute = async (routeId: string, reason: string) => {
    try {
      const response = await fetch(`/api/admin/routes/${routeId}?reason=${encodeURIComponent(reason)}`, {
        method: 'DELETE',
      });

      const data = await response.json();

      if (data.success) {
        toast({
          title: 'Success',
          description: 'Route cancelled successfully',
          status: 'success',
          duration: 3000,
        });
        loadData();
      }
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to cancel route',
        status: 'error',
        duration: 5000,
      });
    }
  };

  const handleModeSwitch = async (newMode: RouteGenerationMode) => {
    // Prevent double clicks
    if (isSwitchingMode || routeGenerationMode === newMode) {
      return;
    }

    setIsSwitchingMode(true);

    try {
      let action = '';

      switch (newMode) {
        case 'manual':
          action = 'stop';
          break;
        case 'semi':
          action = 'stop'; // Semi mode means admin triggers manually
          break;
        case 'automatic':
          action = 'start';
          break;
      }

      if (action) {
        const response = await fetch('/api/admin/routes/scheduler', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ action })
        });

        const data = await response.json();

        if (data.success) {
          setRouteGenerationMode(newMode);
          toast({
            title: 'Success',
            description: `Route generation mode switched to ${newMode}`,
            status: 'success',
            duration: 3000,
          });
          loadData();
        }
      } else {
        setRouteGenerationMode(newMode);
      }
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to switch route generation mode',
        status: 'error',
        duration: 5000,
      });
    } finally {
      setIsSwitchingMode(false);
    }
  };

  const handleOpenRemoveModal = (route: Route) => {
    setSelectedRouteForRemoval(route);
    setRemovalType('single');
    setRemovalReason('');
    onRemoveOpen();
  };

  const handleRemoveRoute = async () => {
    if (!selectedRouteForRemoval) return;

    try {
      if (removalType === 'single') {
        // Remove single route
        const response = await fetch(
          `/api/admin/routes/${selectedRouteForRemoval.id}/unassign`,
          {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              reason: removalReason || 'Removed by admin'
            })
          }
        );

        const data = await response.json();

        if (data.success) {
          toast({
            title: 'Route Removed',
            description: data.message,
            status: 'success',
            duration: 5000,
            isClosable: true,
          });
          loadData();
          onRemoveClose();
        } else {
          throw new Error(data.error || 'Failed to remove route');
        }
      } else if (removalType === 'all' && selectedRouteForRemoval.driverId) {
        // Remove all routes from driver
        const response = await fetch(
          `/api/admin/drivers/${selectedRouteForRemoval.driverId}/remove-all`,
          {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              type: 'routes',
              reason: removalReason || 'Removed all routes by admin'
            })
          }
        );

        const data = await response.json();

        if (data.success) {
          toast({
            title: 'All Routes Removed',
            description: data.message,
            status: 'success',
            duration: 5000,
            isClosable: true,
          });
          loadData();
          onRemoveClose();
        } else {
          throw new Error(data.error || 'Failed to remove all routes');
        }
      }
    } catch (error) {
      toast({
        title: 'Removal Failed',
        description: error instanceof Error ? error.message : 'Failed to remove route',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'active': return 'green';
      case 'planned': return 'blue';
      case 'assigned': return 'cyan';
      case 'completed': return 'gray';
      case 'failed': return 'red';
      default: return 'gray';
    }
  };

  // Filter routes based on active tab
  const getFilteredRoutes = () => {
    let filtered: Route[];
    
    switch (activeTab) {
      case 0: // All Routes
        filtered = routes;
        break;
      case 1: // Active Now
        filtered = routes.filter(r => r.status === 'active');
        break;
      case 2: // In Progress
        filtered = routes.filter(r => r.status === 'active' && r.driverId);
        break;
      case 3: // Completed
        filtered = routes.filter(r => r.status === 'completed');
        break;
      default:
        filtered = routes;
    }
    
    // ✅ Sort by priority (urgent first) then by start time
    return filtered.sort((a, b) => {
      const priorityA = calculateRoutePriority(a.startTime);
      const priorityB = calculateRoutePriority(b.startTime);
      
      // Sort by priority level first (urgent → future)
      if (priorityA.sortOrder !== priorityB.sortOrder) {
        return priorityA.sortOrder - priorityB.sortOrder;
      }
      
      // Then by start time (earliest first)
      return new Date(a.startTime).getTime() - new Date(b.startTime).getTime();
    });
  };

  if (isLoading) {
    return (
      <Flex justify="center" align="center" h="400px">
        <Spinner size="xl" color="blue.500" />
      </Flex>
    );
  }

  return (
    <Box>
      {/* Header with Actions */}
      <Flex justify="space-between" align="center" mb={6}>
        <Box>
          <Heading size="md">Routes Management</Heading>
          <Text color="gray.400" fontSize="sm">
            Real-time route monitoring and control
          </Text>
        </Box>
        <HStack spacing={3}>
          {/* Cleanup Button */}
          <Button
            leftIcon={<FiTrash />}
            colorScheme="red"
            variant="outline"
            size="sm"
            onClick={async () => {
              if (window.confirm('⚠️ Delete ALL orders & routes?\n\nThis will permanently delete:\n• All bookings/orders\n• All routes\n• All assignments\n• All tracking data\n\nThis cannot be undone!')) {
                try {
                  const response = await fetch('/api/admin/cleanup', { method: 'DELETE' });
                  const data = await response.json();
                  if (data.success) {
                    toast({
                      title: 'Cleanup Successful',
                      description: `Deleted ${data.deleted.bookings} bookings, ${data.deleted.routes} routes`,
                      status: 'success',
                      duration: 5000,
                      isClosable: true,
                    });
                    window.location.reload();
                  } else {
                    throw new Error(data.error);
                  }
                } catch (error: any) {
                  toast({
                    title: 'Cleanup Failed',
                    description: error.message,
                    status: 'error',
                    duration: 5000,
                    isClosable: true,
                  });
                }
              }
            }}
            _hover={{ bg: 'red.900', borderColor: 'red.500' }}
          >
            Cleanup All
          </Button>
          
          {/* Dispatch Mode Toggle */}
          <DispatchModeToggle />
          <Select
            value={statusFilter}
            onChange={(e) => setStatusFilter(e.target.value)}
            w="150px"
            bg="gray.800"
            borderColor="gray.600"
          >
            <option value="all">All Status</option>
            <option value="planned">Planned</option>
            <option value="assigned">Assigned</option>
            <option value="active">Active</option>
            <option value="completed">Completed</option>
          </Select>

          {/* Route Generation Mode Switch */}
          <VStack spacing={1} align="end">
            <Text fontSize="xs" color="gray.400">Route Generation</Text>
            <ButtonGroup size="sm" isAttached variant="outline">
              <Button
                leftIcon={<FiSettings />}
                colorScheme={routeGenerationMode === 'manual' ? 'blue' : 'gray'}
                variant={routeGenerationMode === 'manual' ? 'solid' : 'outline'}
                onClick={() => handleModeSwitch('manual')}
                bg={routeGenerationMode === 'manual' ? 'blue.600' : 'gray.800'}
                borderColor="gray.600"
                _hover={{ bg: routeGenerationMode === 'manual' ? 'blue.700' : 'gray.700' }}
                isDisabled={isSwitchingMode}
                isLoading={isSwitchingMode && routeGenerationMode !== 'manual'}
                loadingText=""
              >
                Manual
              </Button>
              <Button
                leftIcon={<FiPlay />}
                colorScheme={routeGenerationMode === 'semi' ? 'purple' : 'gray'}
                variant={routeGenerationMode === 'semi' ? 'solid' : 'outline'}
                onClick={() => handleModeSwitch('semi')}
                bg={routeGenerationMode === 'semi' ? 'purple.600' : 'gray.800'}
                borderColor="gray.600"
                _hover={{ bg: routeGenerationMode === 'semi' ? 'purple.700' : 'gray.700' }}
                isDisabled={isSwitchingMode}
                isLoading={isSwitchingMode && routeGenerationMode !== 'semi'}
                loadingText=""
              >
                Semi
              </Button>
              <Button
                leftIcon={<FiZap />}
                colorScheme={routeGenerationMode === 'automatic' ? 'green' : 'gray'}
                variant={routeGenerationMode === 'automatic' ? 'solid' : 'outline'}
                onClick={() => handleModeSwitch('automatic')}
                bg={routeGenerationMode === 'automatic' ? 'green.600' : 'gray.800'}
                borderColor="gray.600"
                _hover={{ bg: routeGenerationMode === 'automatic' ? 'green.700' : 'gray.700' }}
                isDisabled={isSwitchingMode}
                isLoading={isSwitchingMode && routeGenerationMode !== 'automatic'}
                loadingText=""
              >
                Auto
              </Button>
            </ButtonGroup>
          </VStack>

          <Button
            leftIcon={<FiZap />}
            colorScheme="purple"
            onClick={onAutoCreateOpen}
            isDisabled={routeGenerationMode === 'manual'}
          >
            Auto Create Routes
          </Button>
          <Button
            leftIcon={<FiPlus />}
            colorScheme="blue"
            onClick={onCreateOpen}
          >
            Create Manual Route
          </Button>
          <IconButton
            aria-label="Refresh"
            icon={<FiRefreshCw />}
            onClick={loadData}
            variant="ghost"
          />
        </HStack>
      </Flex>

      {loadError && (
        <Alert status="error" borderRadius="md" mb={6}>
          <AlertIcon />
          <Box>
            <AlertTitle fontSize="sm">Unable to load routes</AlertTitle>
            <AlertDescription fontSize="sm">
              {loadError}
            </AlertDescription>
          </Box>
          <Button
            size="sm"
            ml="auto"
            onClick={() => {
              setIsLoading(true);
              loadData();
            }}
          >
            Retry
          </Button>
        </Alert>
      )}

      {/* Route Generation Status */}
      {schedulerStats && (
        <Card bg="gray.800" borderColor={
          routeGenerationMode === 'automatic' ? 'green.500' :
          routeGenerationMode === 'semi' ? 'purple.500' : 'blue.500'
        } mb={4}>
          <CardBody>
            <Flex justify="space-between" align="center">
              <Box>
                <Flex align="center" gap={2} mb={2}>
                  <FiZap
                    color={
                      routeGenerationMode === 'automatic' ? '#48BB78' :
                      routeGenerationMode === 'semi' ? '#9F7AEA' : '#3182CE'
                    }
                    size={20}
                  />
                  <Heading size="sm" color="white">
                    Route Generation Mode: {
                      routeGenerationMode === 'automatic' ? 'Automatic' :
                      routeGenerationMode === 'semi' ? 'Semi-Automatic' : 'Manual'
                    }
                  </Heading>
                  <Badge colorScheme={
                    routeGenerationMode === 'automatic' ? 'green' :
                    routeGenerationMode === 'semi' ? 'purple' : 'blue'
                  }>
                    {routeGenerationMode.toUpperCase()}
                  </Badge>
                </Flex>
                <Text fontSize="sm" color="gray.400">
                  {routeGenerationMode === 'automatic'
                    ? 'System automatically creates routes every 15 minutes from pending drops'
                    : routeGenerationMode === 'semi'
                    ? 'Admin can manually trigger route creation from pending drops'
                    : 'Only manual route creation is allowed'}
                </Text>
                {schedulerStats.stats && (
                  <HStack spacing={4} mt={2}>
                    <Text fontSize="xs" color="gray.500">
                      Total Runs: {schedulerStats.stats.totalRuns}
                    </Text>
                    <Text fontSize="xs" color="gray.500">
                      Routes Created: {schedulerStats.stats.routesCreated}
                    </Text>
                    <Text fontSize="xs" color="gray.500">
                      Drops Processed: {schedulerStats.stats.dropsProcessed}
                    </Text>
                    {schedulerStats.stats.lastRun && (
                      <Text fontSize="xs" color="gray.500">
                        Last Run: {new Date(schedulerStats.stats.lastRun).toLocaleTimeString()}
                      </Text>
                    )}
                  </HStack>
                )}
              </Box>
              {routeGenerationMode === 'semi' && (
                <Button
                  size="sm"
                  colorScheme="purple"
                  isDisabled={isTriggering}
                  isLoading={isTriggering}
                  loadingText="Triggering..."
                  onClick={async () => {
                    if (isTriggering) {
                      return;
                    }

                    setIsTriggering(true);

                    try {
                      const response = await fetch('/api/admin/routes/scheduler', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({ action: 'trigger' })
                      });
                      const data = await response.json();
                      if (data.success) {
                        toast({
                          title: 'Success',
                          description: 'Route creation triggered manually',
                          status: 'success',
                          duration: 3000,
                        });
                        loadData();
                      }
                    } catch (error) {
                      toast({
                        title: 'Error',
                        description: 'Failed to trigger route creation',
                        status: 'error',
                        duration: 5000,
                      });
                    } finally {
                      setIsTriggering(false);
                    }
                  }}
                >
                  Trigger Now
                </Button>
              )}
            </Flex>
          </CardBody>
        </Card>
      )}

      {/* Metrics Grid */}
      <Grid templateColumns="repeat(4, 1fr)" gap={4} mb={6}>
        <Card bg="gray.800" borderColor="gray.700">
          <CardBody>
            <Stat>
              <StatLabel color="gray.400">Total Routes</StatLabel>
              <StatNumber color="white">{metrics.totalRoutes || 0}</StatNumber>
              <StatHelpText color="gray.500">
                <FiTrendingUp style={{ display: 'inline', marginRight: 4 }} />
                All time
              </StatHelpText>
            </Stat>
          </CardBody>
        </Card>

        <Card bg="gray.800" borderColor="gray.700">
          <CardBody>
            <Stat>
              <StatLabel color="gray.400">Active Now</StatLabel>
              <StatNumber color="green.400">
                {routes.filter(r => r.status === 'active').length}
              </StatNumber>
              <StatHelpText color="gray.500">
                In progress
              </StatHelpText>
            </Stat>
          </CardBody>
        </Card>

        <Card 
          bg="gray.800" 
          borderColor="gray.700"
          cursor="pointer"
          transition="all 0.2s"
          _hover={{ 
            transform: 'translateY(-2px)',
            boxShadow: 'lg',
            borderColor: 'blue.500'
          }}
          onClick={onDistancesOpen}
        >
          <CardBody>
            <Stat>
              <StatLabel color="gray.400">Avg Distance</StatLabel>
              <StatNumber color="white">
                {((metrics.avgDistance || 0) * 0.621371).toFixed(1)} miles
              </StatNumber>
              <StatHelpText color="gray.500">
                Per route • Click to view all
              </StatHelpText>
            </Stat>
          </CardBody>
        </Card>

        <Card 
          bg="gray.800" 
          borderColor="gray.700"
          cursor="pointer"
          onClick={onDriversListOpen}
          _hover={{ 
            bg: 'gray.750', 
            borderColor: 'cyan.500',
            transform: 'translateY(-2px)',
            shadow: 'lg'
          }}
          transition="all 0.2s"
        >
          <CardBody>
            <Stat>
              <StatLabel color="gray.400">Available Drivers</StatLabel>
              <StatNumber color="cyan.400">
                {drivers.filter(d => d.status === 'online').length}
              </StatNumber>
              <StatHelpText color="gray.500">
                Online now • Click to view
              </StatHelpText>
            </Stat>
          </CardBody>
        </Card>
      </Grid>

      {/* Routes Table */}
      <Card bg="gray.800" borderColor="gray.700" overflow="visible">
        <CardHeader>
          <Tabs variant="enclosed" colorScheme="blue" onChange={(index) => setActiveTab(index)}>
            <TabList>
              <Tab color="white">All Routes</Tab>
              <Tab color="white">Active Now</Tab>
              <Tab color="white">In Progress</Tab>
              <Tab color="white">Completed</Tab>
            </TabList>
            
          </Tabs>
        </CardHeader>
        <CardBody p={0}>
          <Box p={4} borderBottom="1px" borderColor="gray.700">
            <Heading size="sm" color="white">
              {activeTab === 0 && `All Routes (${routes.length})`}
              {activeTab === 1 && `Active Now (${routes.filter(r => r.status === 'active').length})`}
              {activeTab === 2 && `In Progress (${routes.filter(r => r.status === 'active' && r.driverId).length})`}
              {activeTab === 3 && `Completed (${routes.filter(r => r.status === 'completed').length})`}
            </Heading>
          </Box>
          <Box overflowX="auto" overflowY="visible">
            <Table variant="simple">
              <Thead>
                <Tr>
                  <Th color="gray.400">Route ID</Th>
                  <Th color="gray.400">Driver</Th>
                  <Th color="gray.400">Status</Th>
                  <Th color="gray.400">Progress</Th>
                  <Th color="gray.400">Drops</Th>
                  <Th color="gray.400">Start Time</Th>
                  <Th color="gray.400">Value</Th>
                  <Th color="gray.400">Actions</Th>
                </Tr>
              </Thead>
              <Tbody>
                {getFilteredRoutes().map((route) => {
                  const isDeclined = declinedNotifications.includes(route.id);
                  const isAccepted = acceptedNotifications.includes(route.id);
                  const isInProgress = inProgressNotifications.includes(route.id);
                  
                  return (
                  <Tr 
                    key={route.id} 
                    _hover={{ 
                      bg: isDeclined ? 'red.800' :
                          isInProgress ? 'blue.800' :
                          isAccepted ? 'green.800' :
                          'gray.750' 
                    }}
                    bg={
                      isDeclined ? 'red.900' :
                      isInProgress ? 'blue.900' :
                      isAccepted ? 'green.900' :
                      'transparent'
                    }
                    borderLeft={
                      isDeclined || isAccepted || isInProgress ? '4px solid' : 'none'
                    }
                    borderLeftColor={
                      isDeclined ? 'red.500' :
                      isInProgress ? 'blue.500' :
                      isAccepted ? 'green.500' :
                      'transparent'
                    }
                  >
                    <Td color="white" fontFamily="mono" fontSize="sm">
                      <HStack spacing={2}>
                        <Circle
                          size="12px"
                          bg={
                            isDeclined ? '#E53E3E' :
                            isInProgress ? '#3B82F6' :
                            isAccepted ? '#10B981' :
                            calculateRoutePriority(route.startTime).color
                          }
                          animation={
                            isDeclined ? `${fastPulseAnimation} 1s ease-in-out infinite` :
                            isInProgress ? `${pulseAnimation} 2s ease-in-out infinite` :
                            isAccepted ? `${pulseAnimation} 2s ease-in-out infinite` :
                            calculateRoutePriority(route.startTime).animation
                          }
                        />
                        <Text>{route.reference || route.id.substring(0, 8)}</Text>
                      </HStack>
                    </Td>
                    <Td>
                      <Flex align="center" gap={2}>
                        <FiUsers color={route.driverId ? '#48BB78' : '#A0AEC0'} />
                        <Text color={route.driverId ? 'white' : 'gray.400'}>
                          {route.driverName || 'Unassigned'}
                        </Text>
                      </Flex>
                    </Td>
                    <Td>
                      <Flex gap={2} align="center">
                        <Badge colorScheme={getStatusColor(route.status)}>
                          {route.status}
                        </Badge>
                        {/* Show RED DECLINED badge if recently declined */}
                        {isDeclined && (
                          <Badge 
                            colorScheme="red" 
                            variant="solid" 
                            animation={`${pulseAnimation} 2s ease-in-out infinite`}
                            fontSize="xs"
                            fontWeight="bold"
                          >
                            🚨 DECLINED
                          </Badge>
                        )}
                        {/* Show GREEN ACCEPTED badge if recently accepted */}
                        {isAccepted && (
                          <Badge 
                            colorScheme="green" 
                            variant="solid" 
                            animation={`${pulseAnimation} 2s ease-in-out infinite`}
                            fontSize="xs"
                            fontWeight="bold"
                          >
                            ✅ ACCEPTED
                          </Badge>
                        )}
                        {/* Show BLUE IN PROGRESS badge if driver started */}
                        {isInProgress && (
                          <Badge 
                            colorScheme="blue" 
                            variant="solid" 
                            animation={`${pulseAnimation} 2s ease-in-out infinite`}
                            fontSize="xs"
                            fontWeight="bold"
                          >
                            🚀 IN PROGRESS
                          </Badge>
                        )}
                        {route.delayStatus && (
                          <Text fontSize="lg">
                            {route.delayStatus === 'on_time' ? '🟢' : route.delayStatus === 'slight_delay' ? '🟡' : '🔴'}
                          </Text>
                        )}
                        {route.acceptanceStatus && route.acceptanceStatus !== 'pending' && (
                          <Text fontSize="sm">
                            {route.acceptanceStatus === 'accepted' ? '✅' : route.acceptanceStatus === 'declined' ? '🚨' : '❌'}
                          </Text>
                        )}
                      </Flex>
                    </Td>
                    <Td>
                      <Box>
                        <Progress
                          value={route.progress}
                          size="sm"
                          colorScheme="blue"
                          borderRadius="full"
                          mb={1}
                        />
                        <Text fontSize="xs" color="gray.400">
                          {route.completedDrops}/{route.totalDrops} drops
                        </Text>
                      </Box>
                    </Td>
                    <Td color="white">{route.totalDrops}</Td>
                    <Td color="gray.300" fontSize="sm">
                      {format(new Date(route.startTime), 'MMM dd, HH:mm')}
                    </Td>
                    <Td color="white" fontWeight="bold">
                      £{(Number(route.totalOutcome) / 100).toFixed(2)}
                    </Td>
                    <Td>
                      <HStack spacing={2}>
                        {/* Quick Assign/Reassign Button */}
                        <Button
                          size="sm"
                          colorScheme={route.driverId ? 'orange' : 'green'}
                          variant="solid"
                          leftIcon={route.driverId ? <FiEdit /> : <FiUser />}
                          onClick={() => {
                            setSelectedRoute(route);
                            onReassignOpen();
                          }}
                        >
                          {route.driverId ? 'Reassign' : 'Assign'}
                        </Button>
                        
                        {/* More Actions Menu */}
                      <Menu>
                        <MenuButton
                          as={IconButton}
                          icon={<FiMoreVertical />}
                          variant="outline"
                          colorScheme="whiteAlpha"
                          size="sm"
                          borderColor="gray.600"
                          _hover={{ bg: 'gray.700', borderColor: 'blue.400' }}
                        />
                        <Portal>
                          <MenuList bg="gray.800" borderColor="gray.600" zIndex={9999}>
                            <MenuItem
                              icon={<FiMapPin />}
                              onClick={() => {
                                setSelectedRoute(route);
                                window.location.href = `/admin/routes/${route.id}`;
                              }}
                              bg="gray.800"
                              _hover={{ bg: 'gray.700' }}
                              color="cyan.400"
                            >
                              View Route Details
                            </MenuItem>
                            <MenuItem
                              icon={<FiEdit />}
                              onClick={() => {
                                setSelectedRoute(route);
                                onEditOpen();
                              }}
                              bg="gray.800"
                              _hover={{ bg: 'gray.700' }}
                            >
                              Edit Drops
                            </MenuItem>
                            <MenuItem
                              icon={<FiPackage />}
                              onClick={() => {
                                setSelectedRoute(route);
                                onRemoveDropOpen();
                              }}
                              bg="gray.800"
                              _hover={{ bg: 'gray.700' }}
                              color="orange.400"
                            >
                              Remove Drop
                            </MenuItem>
                            {route.driverId && (
                              <>
                                <MenuItem
                                  icon={<FiUserX />}
                                  onClick={() => handleOpenRemoveModal(route)}
                                  bg="gray.800"
                                  _hover={{ bg: 'gray.700' }}
                                  color="orange.400"
                                >
                                  Remove Assignment
                                </MenuItem>
                                <MenuItem
                                  icon={<FiClock />}
                                  onClick={() => {
                                    window.location.href = `/admin/drivers/${route.driverId}/schedule`;
                                  }}
                                  bg="gray.800"
                                  _hover={{ bg: 'gray.700' }}
                                  color="purple.400"
                                >
                                  View Driver Schedule
                                </MenuItem>
                                <MenuItem
                                  icon={<FiTrendingUp />}
                                  onClick={() => {
                                    window.location.href = `/admin/drivers/${route.driverId}/earnings`;
                                  }}
                                  bg="gray.800"
                                  _hover={{ bg: 'gray.700' }}
                                  color="green.400"
                                >
                                  View Driver Earnings
                                </MenuItem>
                              </>
                            )}
                            <MenuItem
                              icon={<FiTrash />}
                              onClick={() => handleCancelRoute(route.id, 'Cancelled by admin')}
                              bg="gray.800"
                              _hover={{ bg: 'red.900' }}
                              color="red.400"
                            >
                              Cancel Route
                            </MenuItem>
                          </MenuList>
                        </Portal>
                        </Menu>
                      </HStack>
                    </Td>
                  </Tr>
                  );
                })}
              </Tbody>
            </Table>
          </Box>
        </CardBody>
      </Card>

      {/* Smart Route Generator Modal */}
      <SmartRouteGeneratorModal
        isOpen={isAutoCreateOpen}
        onClose={onAutoCreateClose}
        onSuccess={() => {
          loadData();
          toast({
            title: 'Success',
            description: 'Routes created successfully',
            status: 'success',
            duration: 5000,
          });
        }}
      />

      {/* Create Manual Route Modal */}
      <Modal isOpen={isCreateOpen} onClose={onCreateClose} size="2xl">
        <ModalOverlay />
        <ModalContent bg="gray.800">
          <ModalHeader color="white">Create Manual Route</ModalHeader>
          <ModalCloseButton />
          <ModalBody>
            <VStack spacing={4} align="stretch">
              <Alert status="info" borderRadius="md">
                <AlertIcon />
                <Box>
                  <Text fontSize="sm" fontWeight="bold" mb={1}>Manual Route Creation</Text>
                  <Text fontSize="xs">
                    Select confirmed bookings to create a custom route. You can assign a driver immediately or leave it for later assignment.
                  </Text>
                </Box>
              </Alert>

              <FormControl>
                <FormLabel color="gray.400">Route Name (Optional)</FormLabel>
                <Input 
                  placeholder="e.g., Central London Deliveries"
                  bg="gray.700"
                  color="white"
                  borderColor="gray.600"
                  _hover={{ borderColor: 'gray.500' }}
                />
              </FormControl>

              <FormControl>
                <FormLabel color="gray.400">Select Driver (Optional)</FormLabel>
                <Select 
                  placeholder="Assign driver later"
                  bg="gray.700"
                  color="white"
                  borderColor="gray.600"
                  _hover={{ borderColor: 'gray.500' }}
                >
                  {drivers.filter(d => d.status === 'online').map(driver => (
                    <option key={driver.id} value={driver.id}>
                      {driver.name} - {driver.status}
                    </option>
                  ))}
                </Select>
              </FormControl>

              <Divider borderColor="gray.700" />

              <Box>
                <Text color="white" fontSize="sm" fontWeight="bold" mb={3}>
                  Quick Actions
                </Text>
                <Grid templateColumns="repeat(2, 1fr)" gap={3}>
                  <Button
                    leftIcon={<FiPackage />}
                    variant="outline"
                    colorScheme="blue"
                    size="sm"
                    onClick={() => {
                      onCreateClose();
                      // Navigate to booking selection page
                      window.location.href = '/admin/routes/create';
                    }}
                  >
                    Select from Bookings
                  </Button>
                  <Button
                    leftIcon={<FiMapPin />}
                    variant="outline"
                    colorScheme="purple"
                    size="sm"
                    onClick={() => {
                      onCreateClose();
                      onAutoCreateOpen();
                    }}
                  >
                    Use Smart Generator
                  </Button>
                </Grid>
              </Box>

              <Alert status="warning" borderRadius="md" fontSize="sm">
                <AlertIcon />
                <Text>
                  For advanced route creation with multiple bookings, use the dedicated route creation page or the Smart Route Generator.
                </Text>
              </Alert>
            </VStack>
          </ModalBody>
          <ModalFooter>
            <Button variant="ghost" mr={3} onClick={onCreateClose}>
              Cancel
            </Button>
            <Button
              colorScheme="blue"
              onClick={() => {
                window.location.href = '/admin/routes/create';
              }}
            >
              Go to Route Builder
            </Button>
          </ModalFooter>
        </ModalContent>
      </Modal>

      {/* Assign/Reassign Driver Modal */}
      <Modal isOpen={isReassignOpen} onClose={onReassignClose} size="xl">
        <ModalOverlay />
        <ModalContent bg="gray.800" maxW="900px">
          <ModalHeader color="white">
            {selectedRoute?.driverId ? 'Reassign Driver' : 'Assign Driver'}
          </ModalHeader>
          <ModalCloseButton />
          <ModalBody>
            <Stack spacing={4}>
              {selectedRoute?.driverId && (
                <Box>
                  <Text color="gray.400" fontSize="sm" mb={2}>
                    Current Driver: <Text as="span" color="white" fontWeight="bold">{selectedRoute.driverName}</Text>
                  </Text>
                </Box>
              )}
              
              {/* Interactive Driver Location Map */}
              {selectedRoute && drivers.filter(d => 
                (d.status === 'online' || d.status === 'available') && 
                d.DriverAvailability?.lastLat && 
                d.DriverAvailability?.lastLng
              ).length > 0 && (
                <Box 
                  h="450px" 
                  bg="gray.900" 
                  borderRadius="md" 
                  border="1px solid" 
                  borderColor="gray.700"
                  position="relative"
                  overflow="hidden"
                >
                  <iframe
                    srcDoc={`
                      <!DOCTYPE html>
                      <html>
                      <head>
                        <meta charset="utf-8">
                        <meta name="viewport" content="width=device-width, initial-scale=1">
                        <link href='https://api.mapbox.com/mapbox-gl-js/v2.15.0/mapbox-gl.css' rel='stylesheet' />
                        <script src='https://api.mapbox.com/mapbox-gl-js/v2.15.0/mapbox-gl.js'></script>
                        <style>
                          body { margin: 0; padding: 0; background: #1a202c; }
                          #map { position: absolute; top: 0; bottom: 0; width: 100%; }
                        </style>
                      </head>
                      <body>
                        <div id='map'></div>
                        <script>
                          mapboxgl.accessToken = 'pk.eyJ1IjoiYWhtYWRhbHdha2FpIiwiYSI6ImNtZGNsZ3RsZDEzdGsya3F0ODFxeGRzbXoifQ.jfgGW0KNFTwATOShRDtQsg';
                          
                          // Get all driver locations
                          const drivers = ${JSON.stringify(
                            drivers
                              .filter(d => 
                                (d.status === 'online' || d.status === 'available') &&
                                d.DriverAvailability?.lastLat && 
                                d.DriverAvailability?.lastLng &&
                                !isNaN(Number(d.DriverAvailability.lastLat)) &&
                                !isNaN(Number(d.DriverAvailability.lastLng))
                              )
                              .map(d => ({
                                id: d.id,
                                name: d.name,
                                lat: Number(d.DriverAvailability.lastLat),
                                lng: Number(d.DriverAvailability.lastLng),
                                status: 'online',
                                activeRoutes: d.activeRoutes || 0
                              }))
                          )};
                          
                          if (drivers.length === 0) {
                            document.body.innerHTML = '<div style="display: flex; align-items: center; justify-content: center; height: 100%; color: #9CA3AF; font-family: system-ui;">No online drivers with location data</div>';
                          } else {
                            // Calculate center from all drivers
                            const avgLat = drivers.reduce((sum, d) => sum + d.lat, 0) / drivers.length;
                            const avgLng = drivers.reduce((sum, d) => sum + d.lng, 0) / drivers.length;
                            
                            const map = new mapboxgl.Map({
                              container: 'map',
                              style: 'mapbox://styles/mapbox/dark-v11',
                              center: [avgLng, avgLat],
                              zoom: 11,
                              interactive: true
                            });
                            
                            // Add zoom and rotation controls
                            map.addControl(new mapboxgl.NavigationControl(), 'top-right');
                            
                            // Add fullscreen control
                            map.addControl(new mapboxgl.FullscreenControl(), 'top-right');
                            
                            // Add driver markers with tooltips
                            drivers.forEach(driver => {
                              const el = document.createElement('div');
                              el.innerHTML = '<div style="background: #10B981; width: 34px; height: 34px; border-radius: 50%; display: flex; align-items: center; justify-content: center; border: 3px solid #1a202c; box-shadow: 0 0 15px rgba(16, 185, 129, 0.6); font-size: 18px; transition: all 0.2s; cursor: pointer;">🚗</div>';
                              
                              // Hover effect
                              el.onmouseenter = function() {
                                this.firstChild.style.transform = 'scale(1.3)';
                                this.firstChild.style.boxShadow = '0 0 20px rgba(16, 185, 129, 0.9)';
                              };
                              el.onmouseleave = function() {
                                this.firstChild.style.transform = 'scale(1)';
                                this.firstChild.style.boxShadow = '0 0 15px rgba(16, 185, 129, 0.6)';
                              };
                              
                              const popup = new mapboxgl.Popup({ 
                                offset: 25,
                                closeButton: false,
                                maxWidth: '280px'
                              }).setHTML(
                                '<div style="padding: 14px; font-family: system-ui, -apple-system, sans-serif; background: #1a202c; color: white;">' +
                                '<div style="font-size: 15px; font-weight: 600; margin-bottom: 10px; color: #10B981;">🚗 ' + driver.name + '</div>' +
                                '<div style="display: flex; align-items: center; gap: 8px; margin-bottom: 6px;">' +
                                '<span style="width: 10px; height: 10px; border-radius: 50%; background: #10B981; box-shadow: 0 0 10px rgba(16, 185, 129, 0.8);"></span>' +
                                '<span style="font-size: 13px; font-weight: 500; color: #10B981;">ONLINE & AVAILABLE</span>' +
                                '</div>' +
                                '<div style="font-size: 12px; color: #9CA3AF; margin-bottom: 4px;">Active Routes: <strong style="color: white;">' + driver.activeRoutes + '</strong></div>' +
                                '<div style="font-size: 11px; color: #6B7280; margin-top: 8px; padding-top: 8px; border-top: 1px solid #374151;">Click to select this driver</div>' +
                                '</div>'
                              );
                              
                              const marker = new mapboxgl.Marker(el)
                                .setLngLat([driver.lng, driver.lat])
                                .setPopup(popup)
                                .addTo(map);
                              
                              // Click to select driver
                              el.onclick = function() {
                                window.parent.postMessage({type: 'selectDriver', driverId: driver.id}, '*');
                              };
                            });
                            
                            // Fit bounds to show all markers
                            setTimeout(() => {
                              if (drivers.length > 0) {
                                const bounds = new mapboxgl.LngLatBounds();
                                drivers.forEach(d => bounds.extend([d.lng, d.lat]));
                                map.fitBounds(bounds, { padding: 70, duration: 1000, maxZoom: 13 });
                              }
                            }, 100);
                          }
                        </script>
                      </body>
                      </html>
                    `}
                    width="100%"
                    height="100%"
                    style={{ border: 0 }}
                  />
                  <Box 
                    position="absolute" 
                    bottom={3} 
                    left={3} 
                    bg="gray.800" 
                    px={3} 
                    py={2} 
                    borderRadius="md"
                    fontSize="xs"
                    boxShadow="xl"
                    border="1px solid"
                    borderColor="gray.600"
                  >
                    <VStack align="start" spacing={1}>
                      <HStack spacing={2}>
                        <Box w={2} h={2} borderRadius="full" bg="green.400" boxShadow="0 0 8px rgba(16, 185, 129, 0.6)" />
                        <Text fontSize="11px" color="green.400" fontWeight="medium">Online Drivers</Text>
                      </HStack>
                      <Text fontSize="9px" color="gray.400" fontStyle="italic">
                        💡 Hover for info • Click marker to select driver
                      </Text>
                    </VStack>
                  </Box>
                </Box>
              )}
              
              <FormControl isRequired>
                <FormLabel color="gray.400">Select {selectedRoute?.driverId ? 'New' : ''} Driver</FormLabel>
                <Select
                  placeholder="Choose driver"
                  bg="gray.700"
                  color="white"
                  isDisabled={isReassigning}
                  id="driver-select"
                >
                  {drivers
                    .filter(d => d.status === 'online' || d.status === 'available')
                    .map(driver => {
                      const statusEmoji = driver.status === 'online' ? '🟢' : '🟡';
                      const hasLocation = driver.DriverAvailability?.lastLat && driver.DriverAvailability?.lastLng;
                      return (
                        <option key={driver.id} value={driver.id}>
                          {statusEmoji} {driver.name} - {driver.activeRoutes || 0} active routes {hasLocation ? '📍' : ''}
                        </option>
                      );
                    })}
                </Select>
              </FormControl>
              <FormControl>
                <FormLabel color="gray.400">Reason (Optional)</FormLabel>
                <Textarea
                  placeholder="Enter reason for assignment..."
                  bg="gray.700"
                  color="white"
                  isDisabled={isReassigning}
                  id="reason-textarea"
                  rows={3}
                />
              </FormControl>
            </Stack>
          </ModalBody>
          <ModalFooter>
            <Button 
              variant="ghost" 
              onClick={onReassignClose} 
              isDisabled={isReassigning}
              mr={3}
            >
              Cancel
            </Button>
            <Button
              colorScheme="blue"
              isLoading={isReassigning}
              loadingText={selectedRoute?.driverId ? 'Reassigning...' : 'Assigning...'}
              onClick={() => {
                if (!selectedRoute) return;
                
                const driverSelect = document.getElementById('driver-select') as HTMLSelectElement;
                const reasonTextarea = document.getElementById('reason-textarea') as HTMLTextAreaElement;
                
                const newDriverId = driverSelect?.value;
                const reason = reasonTextarea?.value || undefined;
                
                if (!newDriverId) {
                  toast({
                    title: 'No Driver Selected',
                    description: 'Please select a driver',
                    status: 'warning',
                    duration: 3000,
                    isClosable: true,
                  });
                  return;
                }
                
                if (selectedRoute.driverId) {
                  // Route already has a driver - reassign
                  handleReassignDriver(selectedRoute.id, newDriverId, reason);
                } else {
                  // Route has no driver - assign for first time
                  handleAssignDriver(selectedRoute.id, newDriverId, reason);
                }
              }}
            >
              {selectedRoute?.driverId ? 'Reassign Driver' : 'Assign Driver'}
            </Button>
          </ModalFooter>
        </ModalContent>
      </Modal>

      {/* Remove Assignment Modal */}
      <Modal isOpen={isRemoveOpen} onClose={onRemoveClose} size="lg">
        <ModalOverlay />
        <ModalContent bg="gray.800" color="white">
          <ModalHeader>Remove Driver Assignment</ModalHeader>
          <ModalCloseButton />
          <ModalBody>
            <VStack spacing={4} align="stretch">
              <Alert status="warning" bg="orange.900" borderRadius="md">
                <AlertIcon color="orange.200" />
                <Box color="orange.100">
                  This will remove the driver assignment from the route and free it up for reassignment.
                </Box>
              </Alert>

              {selectedRouteForRemoval && (
                <Box>
                  <Text fontWeight="bold" mb={2}>Route Details:</Text>
                  <Text>Route ID: {selectedRouteForRemoval.id.substring(0, 8)}</Text>
                  <Text>Drops: {selectedRouteForRemoval.totalDrops}</Text>
                  <Text>Value: £{(Number(selectedRouteForRemoval.totalOutcome) / 100).toFixed(2)}</Text>
                  {selectedRouteForRemoval.driverName && (
                    <Text>Current Driver: {selectedRouteForRemoval.driverName}</Text>
                  )}
                </Box>
              )}

              <Divider borderColor="gray.600" />

              <Box>
                <Text fontWeight="bold" mb={2}>Removal Options:</Text>
                <VStack align="stretch" spacing={2}>
                  <Button
                    variant={removalType === 'single' ? 'solid' : 'outline'}
                    colorScheme={removalType === 'single' ? 'blue' : 'gray'}
                    onClick={() => setRemovalType('single')}
                    justifyContent="flex-start"
                  >
                    Remove this route only ({selectedRouteForRemoval?.id.substring(0, 8)})
                  </Button>
                  {selectedRouteForRemoval?.driverId && (
                    <Button
                      variant={removalType === 'all' ? 'solid' : 'outline'}
                      colorScheme={removalType === 'all' ? 'red' : 'gray'}
                      onClick={() => setRemovalType('all')}
                      justifyContent="flex-start"
                    >
                      Remove ALL routes from {selectedRouteForRemoval.driverName}
                    </Button>
                  )}
                </VStack>
              </Box>

              <Box>
                <Text fontWeight="bold" mb={2}>Reason (Optional):</Text>
                <Textarea
                  placeholder="e.g., Van breakdown, driver unavailable, etc."
                  value={removalReason}
                  onChange={(e) => setRemovalReason(e.target.value)}
                  rows={3}
                  bg="gray.700"
                  borderColor="gray.600"
                  _hover={{ borderColor: 'gray.500' }}
                  _focus={{ borderColor: 'blue.500', bg: 'gray.700' }}
                />
              </Box>
            </VStack>
          </ModalBody>
          <ModalFooter>
            <Button variant="ghost" mr={3} onClick={onRemoveClose}>
              Cancel
            </Button>
            <Button 
              colorScheme="red" 
              onClick={handleRemoveRoute}
            >
              {removalType === 'all' ? 'Remove All Routes' : 'Remove Route'}
            </Button>
          </ModalFooter>
        </ModalContent>
      </Modal>

      {/* Available Drivers List Modal */}
      <Modal isOpen={isDriversListOpen} onClose={onDriversListClose} size="3xl">
        <ModalOverlay />
        <ModalContent bg="gray.800">
          <ModalHeader color="white">
            <HStack spacing={3}>
              <Icon as={FiUsers} color="cyan.400" boxSize={6} />
              <Box>
                <Text fontSize="xl" fontWeight="bold">Available Drivers</Text>
                <Text fontSize="sm" fontWeight="normal" color="gray.400">
                  {drivers.filter(d => d.status === 'online').length} drivers currently online
                </Text>
              </Box>
            </HStack>
          </ModalHeader>
          <ModalCloseButton />
          <ModalBody pb={6}>
            {drivers.filter(d => d.status === 'online').length === 0 ? (
              <Alert status="warning" borderRadius="md">
                <AlertIcon />
                <Box>
                  <Text fontWeight="bold" mb={1}>No Drivers Online</Text>
                  <Text fontSize="sm">
                    There are currently no drivers available. Routes created will be unassigned until a driver comes online.
                  </Text>
                </Box>
              </Alert>
            ) : (
              <Grid templateColumns="repeat(auto-fill, minmax(300px, 1fr))" gap={4}>
                {drivers
                  .filter(d => d.status === 'online')
                  .map((driver) => (
                    <Card 
                      key={driver.id}
                      bg="gray.700"
                      borderWidth="2px"
                      borderColor="cyan.700"
                      _hover={{ 
                        borderColor: 'cyan.400',
                        transform: 'translateY(-2px)',
                        shadow: 'lg'
                      }}
                      transition="all 0.2s"
                    >
                      <CardBody>
                        <VStack align="stretch" spacing={3}>
                          <HStack justify="space-between">
                            <HStack>
                              <Icon as={FiUser} color="cyan.400" boxSize={5} />
                              <Text color="white" fontWeight="bold" fontSize="lg">
                                {driver.name}
                              </Text>
                            </HStack>
                            <Badge colorScheme="green" fontSize="sm">
                              Online
                            </Badge>
                          </HStack>

                          <Divider borderColor="gray.600" />

                          <VStack align="stretch" spacing={2} fontSize="sm">
                            <HStack justify="space-between">
                              <Text color="gray.400">Email:</Text>
                              <Text color="white">{driver.email || 'N/A'}</Text>
                            </HStack>

                            <HStack justify="space-between">
                              <Text color="gray.400">Active Routes:</Text>
                              <Badge colorScheme="blue">
                                {routes.filter(r => r.driverId === driver.id && r.status === 'active').length}
                              </Badge>
                            </HStack>

                            <HStack justify="space-between">
                              <Text color="gray.400">Status:</Text>
                              <Badge 
                                colorScheme={
                                  driver.status === 'online' ? 'green' : 
                                  driver.status === 'offline' ? 'gray' : 
                                  'orange'
                                }
                              >
                                {driver.status}
                              </Badge>
                            </HStack>
                          </VStack>

                          <Button
                            size="sm"
                            colorScheme="cyan"
                            variant="outline"
                            onClick={() => {
                              onDriversListClose();
                              // Navigate to driver details or assign route
                              window.location.href = `/admin/drivers/${driver.id}`;
                            }}
                          >
                            View Details
                          </Button>
                        </VStack>
                      </CardBody>
                    </Card>
                  ))}
              </Grid>
            )}

            {/* Show offline drivers count */}
            {drivers.filter(d => d.status !== 'online').length > 0 && (
              <Alert status="info" borderRadius="md" mt={4}>
                <AlertIcon />
                <Text fontSize="sm">
                  {drivers.filter(d => d.status !== 'online').length} driver(s) currently offline
                </Text>
              </Alert>
            )}
          </ModalBody>
          <ModalFooter borderTopWidth="1px" borderColor="gray.700">
            <Button variant="ghost" onClick={onDriversListClose}>
              Close
            </Button>
          </ModalFooter>
        </ModalContent>
      </Modal>

      {/* Route Distances Modal */}
      <Modal isOpen={isDistancesOpen} onClose={onDistancesClose} size="2xl">
        <ModalOverlay />
        <ModalContent bg="gray.800" borderColor="gray.600" borderWidth="1px">
          <ModalHeader borderBottomWidth="1px" borderColor="gray.700">
            <HStack spacing={3}>
              <Icon as={FiMapPin} color="blue.400" boxSize={6} />
              <Box>
                <Heading size="md" color="white">Route Distances</Heading>
                <Text fontSize="sm" color="gray.400" fontWeight="normal" mt={1}>
                  All routes with their optimized distances
                </Text>
              </Box>
            </HStack>
          </ModalHeader>
          <ModalCloseButton />
          <ModalBody pb={6}>
            {routes.length === 0 ? (
              <Alert status="info" borderRadius="md">
                <AlertIcon />
                <Box>
                  <Text fontWeight="bold" mb={1}>No Routes Found</Text>
                  <Text fontSize="sm">
                    There are currently no routes in the system.
                  </Text>
                </Box>
              </Alert>
            ) : (
              <VStack spacing={3} align="stretch">
                {routes.map((route) => (
                  <Card 
                    key={route.id}
                    bg="gray.700"
                    borderWidth="1px"
                    borderColor="gray.600"
                    _hover={{ 
                      borderColor: 'blue.400',
                      transform: 'translateY(-1px)',
                      shadow: 'md'
                    }}
                    transition="all 0.2s"
                  >
                    <CardBody p={4}>
                      <HStack justify="space-between" align="start" mb={3}>
                        <VStack align="start" spacing={1} flex={1}>
                          <HStack>
                            <Text color="white" fontWeight="bold" fontFamily="mono" fontSize="sm">
                              {route.reference || route.id.substring(0, 12)}
                            </Text>
                            <Badge colorScheme={getStatusColor(route.status)}>
                              {route.status}
                            </Badge>
                          </HStack>
                          
                          <HStack spacing={3} fontSize="sm">
                            <HStack color="gray.400">
                              <Icon as={FiUsers} boxSize={3} />
                              <Text>
                                {route.driverName || 'Unassigned'}
                              </Text>
                            </HStack>
                            
                            <HStack color="gray.400">
                              <Icon as={FiPackage} boxSize={3} />
                              <Text>{route.totalDrops} drops</Text>
                            </HStack>
                          </HStack>
                        </VStack>

                        <HStack spacing={2}>
                          <VStack align="end" spacing={1}>
                            <HStack>
                              <Icon as={FiNavigation} color="blue.400" boxSize={4} />
                              <Text color="white" fontSize="xl" fontWeight="bold">
                                {((route.optimizedDistanceKm || 0) * 0.621371).toFixed(1)} mi
                              </Text>
                            </HStack>
                            <Text fontSize="xs" color="gray.400">
                              {(route.optimizedDistanceKm || 0).toFixed(1)} km
                            </Text>
                          </VStack>
                          
                          {/* Action Menu */}
                          <Menu>
                            <MenuButton
                              as={IconButton}
                              icon={<FiMoreVertical />}
                              variant="ghost"
                              colorScheme="whiteAlpha"
                              size="sm"
                              aria-label="Route actions"
                            />
                            <Portal>
                              <MenuList bg="gray.700" borderColor="gray.600" zIndex={9999}>
                              {route.driverId ? (
                                <>
                                  <MenuItem
                                    icon={<FiEdit />}
                                    onClick={() => {
                                      setSelectedRoute(route);
                                      onReassignOpen();
                                    }}
                                    bg="gray.700"
                                    _hover={{ bg: 'gray.600' }}
                                    color="white"
                                  >
                                    Reassign Driver
                                  </MenuItem>
                                  <MenuItem
                                    icon={<FiUserX />}
                                    onClick={() => {
                                      setSelectedRouteForRemoval(route);
                                      onRemoveOpen();
                                    }}
                                    bg="gray.700"
                                    _hover={{ bg: 'gray.600' }}
                                    color="white"
                                  >
                                    Remove Driver
                                  </MenuItem>
                                </>
                              ) : (
                                <MenuItem
                                  icon={<FiUser />}
                                  onClick={() => {
                                    setSelectedRoute(route);
                                    onReassignOpen();
                                  }}
                                  bg="gray.700"
                                  _hover={{ bg: 'gray.600' }}
                                  color="white"
                                >
                                  Assign Driver
                                </MenuItem>
                              )}
                              <MenuItem
                                icon={<FiMapPin />}
                                onClick={() => {
                                  setSelectedRoute(route);
                                  onEditOpen();
                                }}
                                bg="gray.700"
                                _hover={{ bg: 'gray.600' }}
                                color="white"
                              >
                                View Details
                              </MenuItem>
                              <MenuItem
                                icon={<FiTrash />}
                                onClick={() => {
                                  setSelectedRouteForRemoval(route);
                                  setRemovalType('all');
                                  onRemoveDropOpen();
                                }}
                                bg="gray.700"
                                _hover={{ bg: 'red.600' }}
                                color="red.300"
                              >
                                Delete Route
                              </MenuItem>
                            </MenuList>
                            </Portal>
                          </Menu>
                        </HStack>
                      </HStack>
                    </CardBody>
                  </Card>
                ))}
              </VStack>
            )}

            {/* Summary Stats */}
            {routes.length > 0 && (
              <Card bg="blue.900" borderColor="blue.600" borderWidth="1px" mt={4}>
                <CardBody p={4}>
                  <Grid templateColumns="repeat(3, 1fr)" gap={4}>
                    <VStack spacing={1}>
                      <Text fontSize="xs" color="blue.200">Total Routes</Text>
                      <Text fontSize="2xl" fontWeight="bold" color="white">
                        {routes.length}
                      </Text>
                    </VStack>
                    
                    <VStack spacing={1}>
                      <Text fontSize="xs" color="blue.200">Total Distance</Text>
                      <Text fontSize="2xl" fontWeight="bold" color="white">
                        {(routes.reduce((sum, r) => sum + ((r.optimizedDistanceKm || 0) * 0.621371), 0)).toFixed(1)} mi
                      </Text>
                    </VStack>
                    
                    <VStack spacing={1}>
                      <Text fontSize="xs" color="blue.200">Average Distance</Text>
                      <Text fontSize="2xl" fontWeight="bold" color="white">
                        {((metrics.avgDistance || 0) * 0.621371).toFixed(1)} mi
                      </Text>
                    </VStack>
                  </Grid>
                </CardBody>
              </Card>
            )}
          </ModalBody>
          <ModalFooter borderTopWidth="1px" borderColor="gray.700">
            <Button variant="ghost" onClick={onDistancesClose}>
              Close
            </Button>
          </ModalFooter>
        </ModalContent>
      </Modal>

      {/* Remove Drop Modal */}
      <Modal isOpen={isRemoveDropOpen} onClose={onRemoveDropClose} size="xl">
        <ModalOverlay />
        <ModalContent bg="gray.800" borderColor="gray.600" borderWidth="1px">
          <ModalHeader borderBottomWidth="1px" borderColor="gray.700">
            <HStack spacing={3}>
              <Icon as={FiPackage} color="orange.400" boxSize={6} />
              <Box>
                <Heading size="md" color="white">Remove Drop from Route</Heading>
                <Text fontSize="sm" color="gray.400" fontWeight="normal" mt={1}>
                  Select a drop to remove from route {selectedRoute?.id.substring(0, 12)}...
                </Text>
              </Box>
            </HStack>
          </ModalHeader>
          <ModalCloseButton />
          <ModalBody pb={6}>
            {selectedRoute && selectedRoute.drops && selectedRoute.drops.length > 0 ? (
              <VStack spacing={3} align="stretch">
                {selectedRoute.drops.map((drop: any, index: number) => (
                  <Card 
                    key={drop.id}
                    bg="gray.700"
                    borderWidth="1px"
                    borderColor="gray.600"
                    _hover={{ 
                      borderColor: 'orange.400',
                      transform: 'translateY(-1px)',
                      shadow: 'md'
                    }}
                    transition="all 0.2s"
                  >
                    <CardBody p={4}>
                      <HStack justify="space-between" align="start">
                        <VStack align="start" spacing={2} flex={1}>
                          <HStack>
                            <Badge colorScheme="blue">Drop #{index + 1}</Badge>
                            <Badge colorScheme={drop.status === 'pending' ? 'yellow' : 'green'}>
                              {drop.status}
                            </Badge>
                          </HStack>
                          
                          <VStack align="start" spacing={1} fontSize="sm">
                            <HStack color="gray.300">
                              <Icon as={FiMapPin} boxSize={3} />
                              <Text fontWeight="bold">Pickup:</Text>
                              <Text>{drop.pickupAddress || 'N/A'}</Text>
                            </HStack>
                            
                            <HStack color="gray.300">
                              <Icon as={FiMapPin} boxSize={3} />
                              <Text fontWeight="bold">Delivery:</Text>
                              <Text>{drop.deliveryAddress || 'N/A'}</Text>
                            </HStack>
                          </VStack>
                        </VStack>

                        <Button
                          size="sm"
                          colorScheme="orange"
                          leftIcon={<FiTrash />}
                          onClick={async (e) => {
                            e.preventDefault();
                            e.stopPropagation();
                            
                            console.log('Remove button clicked for drop:', drop.id);
                            
                            const confirmed = window.confirm(`Are you sure you want to remove Drop #${index + 1}?\n\nPickup: ${drop.pickupAddress}\nDelivery: ${drop.deliveryAddress}\n\nThe driver will be notified immediately.`);
                            
                            if (!confirmed) {
                              console.log('User cancelled drop removal');
                              return;
                            }

                            try {
                              console.log('Sending DELETE request to:', `/api/admin/routes/${selectedRoute.id}/drops/${drop.id}`);
                              
                              const response = await fetch(`/api/admin/routes/${selectedRoute.id}/drops/${drop.id}`, {
                                method: 'DELETE',
                                headers: {
                                  'Content-Type': 'application/json',
                                },
                              });

                              console.log('Response status:', response.status);

                              if (response.ok) {
                                const result = await response.json();
                                console.log('Drop removed successfully:', result);
                                
                                toast({
                                  title: 'Drop Removed',
                                  description: `Drop #${index + 1} has been removed successfully`,
                                  status: 'success',
                                  duration: 5000,
                                });
                                
                                // Refresh data
                                await loadData();
                                onRemoveDropClose();
                              } else {
                                const error = await response.json();
                                console.error('Error response:', error);
                                throw new Error(error.error || 'Failed to remove drop');
                              }
                            } catch (error) {
                              console.error('Error removing drop:', error);
                              toast({
                                title: 'Error',
                                description: error instanceof Error ? error.message : 'Failed to remove drop',
                                status: 'error',
                                duration: 5000,
                              });
                            }
                          }}
                        >
                          Remove
                        </Button>
                      </HStack>
                    </CardBody>
                  </Card>
                ))}
              </VStack>
            ) : (
              <Alert status="info" borderRadius="md">
                <AlertIcon />
                <Box>
                  <Text fontWeight="bold" mb={1}>No Drops Found</Text>
                  <Text fontSize="sm">
                    This route has no drops to remove.
                  </Text>
                </Box>
              </Alert>
            )}
          </ModalBody>
          <ModalFooter borderTopWidth="1px" borderColor="gray.700">
            <Button variant="ghost" onClick={onRemoveDropClose}>
              Close
            </Button>
          </ModalFooter>
        </ModalContent>
      </Modal>
    </Box>
  );
};

export default EnhancedAdminRoutesDashboard;

/**
 * Enterprise Admin Dashboard
 * 
 * Advanced admin dashboard with real-time analytics and management capabilities
 */

'use client';

import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Progress } from '@/components/ui/progress';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { 
  TrendingUp, 
  TrendingDown,
  Users, 
  Route,
  DollarSign,
  Package,
  AlertCircle,
  CheckCircle,
  Clock,
  BarChart3,
  Settings,
  RefreshCw
} from 'lucide-react';

interface DashboardStats {
  totalRevenue: number;
  totalDrops: number;
  activeDrivers: number;
  activeRoutes: number;
  avgPerformanceScore: number;
  customerSatisfaction: number;
  revenueGrowth: number;
  dropsGrowth: number;
}

interface RouteStatus {
  id: string;
  driverId: string;
  driverName: string;
  status: 'planned' | 'assigned' | 'in_progress' | 'completed' | 'closed';
  dropsCount: number;
  estimatedEarnings: number;
  progress: number;
  currentLocation?: string;
}

interface PerformanceMetric {
  driverId: string;
  driverName: string;
  performanceScore: number;
  avgCsat: number;
  onTimeRate: number;
  completionRate: number;
  totalEarnings: number;
  trend: 'up' | 'down' | 'stable';
}

export default function EnterpriseAdminDashboard() {
  const [stats, setStats] = useState<DashboardStats>({
    totalRevenue: 0,
    totalDrops: 0,
    activeDrivers: 0,
    activeRoutes: 0,
    avgPerformanceScore: 0,
    customerSatisfaction: 0,
    revenueGrowth: 0,
    dropsGrowth: 0
  });

  const [activeRoutes, setActiveRoutes] = useState<RouteStatus[]>([]);
  const [topPerformers, setTopPerformers] = useState<PerformanceMetric[]>([]);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Load initial data
  useEffect(() => {
    refreshDashboard();
  }, []);

  // Set up real-time data updates
  useEffect(() => {
    const interval = setInterval(() => {
      refreshDashboard();
    }, 30000); // Update every 30 seconds

    return () => clearInterval(interval);
  }, []);

  const handleOptimizeRoutes = async () => {
    setIsRefreshing(true);
    try {
      const response = await fetch('/api/routes', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'optimize' })
      });
      
      if (response.ok) {
        // Refresh dashboard data
        await refreshDashboard();
      }
    } catch (error) {
      console.error('Error optimizing routes:', error);
    } finally {
      setIsRefreshing(false);
    }
  };

  const refreshDashboard = async () => {
    setIsRefreshing(true);
    setError(null);
    
    try {
      // Calculate date range for last 30 days
      const endDate = new Date();
      const startDate = new Date();
      startDate.setDate(startDate.getDate() - 30);

      // Fetch analytics data in parallel
      const [operationalData, driversData] = await Promise.all([
        fetch(`/api/analytics/operational?startDate=${startDate.toISOString()}&endDate=${endDate.toISOString()}`),
        fetch(`/api/analytics/drivers?startDate=${startDate.toISOString()}&endDate=${endDate.toISOString()}&limit=10`)
      ]);

      if (!operationalData.ok || !driversData.ok) {
        throw new Error('Failed to fetch analytics data');
      }

      const operational = await operationalData.json();
      const drivers = await driversData.json();

      // Update stats with real data
      if (operational.success) {
        const data = operational.data;
        setStats({
          totalRevenue: data.totalRevenue,
          totalDrops: data.totalBookings,
          activeDrivers: data.activeDrivers,
          activeRoutes: Math.floor(data.activeDrivers * 0.6), // Estimate 60% of drivers on routes
          avgPerformanceScore: data.driverPerformanceScore,
          customerSatisfaction: data.customerSatisfaction,
          revenueGrowth: 12.5, // TODO: Calculate actual growth from previous period
          dropsGrowth: 8.3 // TODO: Calculate actual growth from previous period
        });
      }

      // Update top performers with real driver data
      if (drivers.success && drivers.data.length > 0) {
        setTopPerformers(
          drivers.data.slice(0, 5).map((driver: any, index: number) => ({
            driverId: driver.driverId,
            driverName: driver.driverName,
            performanceScore: driver.averageRating * 20, // Convert 0-5 rating to 0-100 score
            avgCsat: driver.averageRating,
            onTimeRate: driver.completionRate / 100,
            completionRate: driver.completionRate / 100,
            totalEarnings: driver.totalRevenue,
            trend: index < 2 ? 'up' : 'stable' // Mock trend for now
          }))
        );
      }

      // Mock active routes data for now (would come from route tracking system)
      setActiveRoutes([
        {
          id: 'route-001',
          driverId: 'driver-001',
          driverName: 'John Smith',
          status: 'in_progress',
          dropsCount: 6,
          estimatedEarnings: 145.50,
          progress: 67,
          currentLocation: 'Central London'
        },
        {
          id: 'route-002',
          driverId: 'driver-002',
          driverName: 'Sarah Johnson',
          status: 'assigned',
          dropsCount: 4,
          estimatedEarnings: 98.20,
          progress: 0,
          currentLocation: 'Awaiting start'
        }
      ]);

    } catch (error) {
      console.error('Error refreshing dashboard:', error);
      setError('Failed to load dashboard data. Please try again.');
    } finally {
      setIsRefreshing(false);
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'completed': return 'bg-green-500';
      case 'in_progress': return 'bg-blue-500';
      case 'assigned': return 'bg-yellow-500';
      case 'planned': return 'bg-gray-500';
      default: return 'bg-gray-300';
    }
  };

  const getTrendIcon = (trend: string) => {
    switch (trend) {
      case 'up': return <TrendingUp className="h-4 w-4 text-green-500" />;
      case 'down': return <TrendingDown className="h-4 w-4 text-red-500" />;
      default: return <div className="h-4 w-4" />;
    }
  };

  return (
    <div className="p-6 space-y-6">
      {/* Header */}
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-3xl font-bold">Enterprise Operations Dashboard</h1>
          <p className="text-muted-foreground mt-1">
            Real-time monitoring and analytics for Speedy Van operations
          </p>
        </div>
        <div className="flex gap-2">
          <Button 
            variant="outline" 
            onClick={refreshDashboard}
            disabled={isRefreshing}
          >
            <RefreshCw className={`h-4 w-4 mr-2 ${isRefreshing ? 'animate-spin' : ''}`} />
            Refresh
          </Button>
          <Button 
            onClick={handleOptimizeRoutes}
            disabled={isRefreshing}
          >
            <Route className="h-4 w-4 mr-2" />
            Optimize Routes
          </Button>
        </div>
      </div>

      {/* Error Display */}
      {error && (
        <Card className="border-red-200 bg-red-50">
          <CardContent className="pt-6">
            <div className="flex items-center gap-2 text-red-800">
              <AlertCircle className="h-4 w-4" />
              <span className="font-medium">Error:</span>
              <span>{error}</span>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Key Metrics Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Total Revenue</CardTitle>
            <DollarSign className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">£{stats.totalRevenue.toLocaleString()}</div>
            <p className="text-xs text-muted-foreground">
              <span className="text-green-600">+{stats.revenueGrowth}%</span> from last month
            </p>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Total Drops</CardTitle>
            <Package className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{stats.totalDrops.toLocaleString()}</div>
            <p className="text-xs text-muted-foreground">
              <span className="text-green-600">+{stats.dropsGrowth}%</span> from last month
            </p>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Active Drivers</CardTitle>
            <Users className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{stats.activeDrivers}</div>
            <p className="text-xs text-muted-foreground">
              {stats.activeRoutes} currently on routes
            </p>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Avg Performance</CardTitle>
            <BarChart3 className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{stats.avgPerformanceScore.toFixed(1)}</div>
            <div className="w-full bg-gray-200 rounded-full h-2 mt-2">
              <div 
                className="bg-blue-600 h-2 rounded-full" 
                style={{ width: `${stats.avgPerformanceScore}%` }}
              ></div>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Main Dashboard Tabs */}
      <Tabs defaultValue="routes" className="space-y-4">
        <TabsList>
          <TabsTrigger value="routes">Active Routes</TabsTrigger>
          <TabsTrigger value="performance">Driver Performance</TabsTrigger>
          <TabsTrigger value="analytics">Analytics</TabsTrigger>
          <TabsTrigger value="settings">Settings</TabsTrigger>
        </TabsList>

        {/* Active Routes Tab */}
        <TabsContent value="routes" className="space-y-4">
          <Card>
            <CardHeader>
              <CardTitle>Active Routes</CardTitle>
              <CardDescription>
                Real-time monitoring of all active delivery routes
              </CardDescription>
            </CardHeader>
            <CardContent>
              <div className="space-y-4">
                {activeRoutes.map((route) => (
                  <div key={route.id} className="flex items-center justify-between p-4 border rounded-lg">
                    <div className="flex items-center space-x-4">
                      <div className={`w-3 h-3 rounded-full ${getStatusColor(route.status)}`}></div>
                      <div>
                        <p className="font-medium">{route.driverName}</p>
                        <p className="text-sm text-muted-foreground">
                          {route.dropsCount} drops • Est. earnings: £{route.estimatedEarnings.toFixed(2)}
                        </p>
                      </div>
                    </div>
                    <div className="flex items-center space-x-4">
                      <div className="text-right">
                        <p className="text-sm font-medium">{route.status.replace('_', ' ').toUpperCase()}</p>
                        <p className="text-sm text-muted-foreground">{route.currentLocation}</p>
                      </div>
                      {route.status === 'in_progress' && (
                        <div className="w-24">
                          <Progress value={route.progress} />
                          <p className="text-xs text-center mt-1">{route.progress}%</p>
                        </div>
                      )}
                    </div>
                  </div>
                ))}
                {activeRoutes.length === 0 && (
                  <div className="text-center py-8 text-muted-foreground">
                    No active routes at the moment
                  </div>
                )}
              </div>
            </CardContent>
          </Card>
        </TabsContent>

        {/* Performance Tab */}
        <TabsContent value="performance" className="space-y-4">
          <Card>
            <CardHeader>
              <CardTitle>Top Performing Drivers</CardTitle>
              <CardDescription>
                Performance metrics based on CSAT, on-time delivery, and completion rates
              </CardDescription>
            </CardHeader>
            <CardContent>
              <div className="space-y-4">
                {topPerformers.map((driver, index) => (
                  <div key={driver.driverId} className="flex items-center justify-between p-4 border rounded-lg">
                    <div className="flex items-center space-x-4">
                      <div className="flex items-center justify-center w-8 h-8 bg-blue-100 rounded-full">
                        <span className="text-sm font-bold">#{index + 1}</span>
                      </div>
                      <div>
                        <p className="font-medium">{driver.driverName}</p>
                        <div className="flex space-x-4 text-sm text-muted-foreground">
                          <span>CSAT: {driver.avgCsat.toFixed(1)}⭐</span>
                          <span>On-time: {(driver.onTimeRate * 100).toFixed(0)}%</span>
                          <span>Completion: {(driver.completionRate * 100).toFixed(0)}%</span>
                        </div>
                      </div>
                    </div>
                    <div className="flex items-center space-x-4">
                      <div className="text-right">
                        <p className="text-lg font-bold">{driver.performanceScore.toFixed(1)}</p>
                        <p className="text-sm text-muted-foreground">Performance Score</p>
                      </div>
                      <div className="text-right">
                        <p className="text-lg font-bold">£{driver.totalEarnings.toLocaleString()}</p>
                        <p className="text-sm text-muted-foreground">Total Earnings</p>
                      </div>
                      {getTrendIcon(driver.trend)}
                    </div>
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>
        </TabsContent>

        {/* Analytics Tab */}
        <TabsContent value="analytics" className="space-y-4">
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
            <Card>
              <CardHeader>
                <CardTitle>Customer Satisfaction</CardTitle>
                <CardDescription>Average rating across all completed drops</CardDescription>
              </CardHeader>
              <CardContent>
                <div className="flex items-center space-x-2">
                  <div className="text-3xl font-bold">{stats.customerSatisfaction.toFixed(1)}</div>
                  <div className="text-yellow-500">⭐</div>
                </div>
                <div className="mt-2 space-y-2">
                  {[5, 4, 3, 2, 1].map((stars) => (
                    <div key={stars} className="flex items-center space-x-2">
                      <span className="text-sm w-4">{stars}⭐</span>
                      <Progress value={Math.random() * 100} className="flex-1" />
                      <span className="text-sm text-muted-foreground w-8">
                        {Math.floor(Math.random() * 50)}%
                      </span>
                    </div>
                  ))}
                </div>
              </CardContent>
            </Card>

            <Card>
              <CardHeader>
                <CardTitle>Route Efficiency</CardTitle>
                <CardDescription>Optimization metrics for route planning</CardDescription>
              </CardHeader>
              <CardContent>
                <div className="space-y-4">
                  <div className="flex justify-between">
                    <span>Average drops per route</span>
                    <span className="font-medium">5.2</span>
                  </div>
                  <div className="flex justify-between">
                    <span>Route completion rate</span>
                    <span className="font-medium">94.3%</span>
                  </div>
                  <div className="flex justify-between">
                    <span>Avg distance optimization</span>
                    <span className="font-medium text-green-600">-12.7%</span>
                  </div>
                  <div className="flex justify-between">
                    <span>Fuel efficiency improvement</span>
                    <span className="font-medium text-green-600">+8.9%</span>
                  </div>
                </div>
              </CardContent>
            </Card>
          </div>
        </TabsContent>

        {/* Settings Tab */}
        <TabsContent value="settings" className="space-y-4">
          <Card>
            <CardHeader>
              <CardTitle>System Configuration</CardTitle>
              <CardDescription>
                Configure pricing engine and operational parameters
              </CardDescription>
            </CardHeader>
            <CardContent>
              <div className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="text-sm font-medium">Base Rate per KM</label>
                    <input 
                      type="number" 
                      className="w-full mt-1 p-2 border rounded" 
                      defaultValue="1.50"
                      step="0.01"
                    />
                  </div>
                  <div>
                    <label className="text-sm font-medium">Base Rate per Minute</label>
                    <input 
                      type="number" 
                      className="w-full mt-1 p-2 border rounded" 
                      defaultValue="0.50"
                      step="0.01"
                    />
                  </div>
                </div>
                
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="text-sm font-medium">Route Excellence Bonus</label>
                    <input 
                      type="number" 
                      className="w-full mt-1 p-2 border rounded" 
                      defaultValue="25.00"
                      step="1"
                    />
                  </div>
                  <div>
                    <label className="text-sm font-medium">Max Performance Multiplier</label>
                    <input 
                      type="number" 
                      className="w-full mt-1 p-2 border rounded" 
                      defaultValue="1.50"
                      step="0.1"
                    />
                  </div>
                </div>

                <Button className="mt-4">
                  <Settings className="h-4 w-4 mr-2" />
                  Save Configuration
                </Button>
              </div>
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import {
  Box,
  VStack,
  HStack,
  Text,
  Badge,
  Spinner,
  Icon,
  Progress,
  Divider,
  Tooltip,
} from '@chakra-ui/react';
import {
  FiTruck,
  FiPackage,
  FiDollarSign,
  FiAlertCircle,
  FiTrendingUp,
  FiClock,
  FiMapPin,
} from 'react-icons/fi';

interface SystemStats {
  totalBookings: number;
  pendingBookings: number;
  activeBookings: number;
  completedToday: number;
  activeDrivers: number;
  totalDrivers: number;
  todayRevenue: number;
  utilizationRate: number;
  alerts: Alert[];
  recentActivity: Activity[];
}

interface Alert {
  id: string;
  type: 'warning' | 'error' | 'info';
  message: string;
  timestamp: Date;
}

interface Activity {
  id: string;
  type: 'booking' | 'driver' | 'payment';
  description: string;
  timestamp: Date;
}

export const LiveStatusDashboard: React.FC<{ isOpen: boolean }> = ({ isOpen }) => {
  const [stats, setStats] = useState<SystemStats | null>(null);
  const [loading, setLoading] = useState(true);
  const [lastUpdate, setLastUpdate] = useState<Date>(new Date());

  // Fetch live stats
  const fetchStats = async () => {
    try {
      const response = await fetch('/api/admin/ai/live-stats');
      if (response.ok) {
        const data = await response.json();
        setStats(data);
        setLastUpdate(new Date());
      }
    } catch (error) {
      console.error('Failed to fetch live stats:', error);
    } finally {
      setLoading(false);
    }
  };

  // Auto-refresh every 30 seconds
  useEffect(() => {
    if (isOpen) {
      fetchStats();
      const interval = setInterval(fetchStats, 30000);
      return () => clearInterval(interval);
    }
  }, [isOpen]);

  if (!isOpen) return null;

  if (loading) {
    return (
      <Box
        position="fixed"
        right={0}
        top="60px"
        bottom={0}
        width="320px"
        bg="#1a1a1a"
        borderLeft="1px solid #333"
        p={4}
        overflowY="auto"
        zIndex={1000}
      >
        <VStack spacing={4} align="center" justify="center" height="100%">
          <Spinner size="lg" color="#10b981" />
          <Text color="#9ca3af">Loading live stats...</Text>
        </VStack>
      </Box>
    );
  }

  if (!stats) {
    return (
      <Box
        position="fixed"
        right={0}
        top="60px"
        bottom={0}
        width="320px"
        bg="#1a1a1a"
        borderLeft="1px solid #333"
        p={4}
        zIndex={1000}
      >
        <Text color="#ef4444">Failed to load stats</Text>
      </Box>
    );
  }

  return (
    <Box
      position="fixed"
      right={0}
      top="60px"
      bottom={0}
      width="320px"
      bg="#1a1a1a"
      borderLeft="1px solid #333"
      overflowY="auto"
      zIndex={1000}
      css={{
        '&::-webkit-scrollbar': {
          width: '8px',
        },
        '&::-webkit-scrollbar-track': {
          background: '#0a0a0a',
        },
        '&::-webkit-scrollbar-thumb': {
          background: '#333',
          borderRadius: '4px',
        },
        '&::-webkit-scrollbar-thumb:hover': {
          background: '#444',
        },
      }}
    >
      <VStack spacing={4} p={4} align="stretch">
        {/* Header */}
        <HStack justify="space-between">
          <Text fontSize="lg" fontWeight="bold" color="#ECECF1">
            Live Status
          </Text>
          <Tooltip label={`Last updated: ${lastUpdate.toLocaleTimeString()}`}>
            <Badge colorScheme="green" fontSize="xs">
              LIVE
            </Badge>
          </Tooltip>
        </HStack>

        <Divider borderColor="#333" />

        {/* Bookings Overview */}
        <Box bg="#0a0a0a" p={3} borderRadius="md" border="1px solid #333">
          <HStack mb={2}>
            <Icon as={FiPackage} color="#10b981" />
            <Text fontSize="sm" fontWeight="bold" color="#ECECF1">
              Bookings
            </Text>
          </HStack>
          <VStack spacing={2} align="stretch">
            <HStack justify="space-between">
              <Text fontSize="xs" color="#9ca3af">
                Total Today
              </Text>
              <Text fontSize="sm" fontWeight="bold" color="#ECECF1">
                {stats.totalBookings}
              </Text>
            </HStack>
            <HStack justify="space-between">
              <Text fontSize="xs" color="#9ca3af">
                Pending
              </Text>
              <Badge colorScheme="yellow" fontSize="xs">
                {stats.pendingBookings}
              </Badge>
            </HStack>
            <HStack justify="space-between">
              <Text fontSize="xs" color="#9ca3af">
                Active
              </Text>
              <Badge colorScheme="blue" fontSize="xs">
                {stats.activeBookings}
              </Badge>
            </HStack>
            <HStack justify="space-between">
              <Text fontSize="xs" color="#9ca3af">
                Completed
              </Text>
              <Badge colorScheme="green" fontSize="xs">
                {stats.completedToday}
              </Badge>
            </HStack>
          </VStack>
        </Box>

        {/* Drivers Overview */}
        <Box bg="#0a0a0a" p={3} borderRadius="md" border="1px solid #333">
          <HStack mb={2}>
            <Icon as={FiTruck} color="#3b82f6" />
            <Text fontSize="sm" fontWeight="bold" color="#ECECF1">
              Drivers
            </Text>
          </HStack>
          <VStack spacing={2} align="stretch">
            <HStack justify="space-between">
              <Text fontSize="xs" color="#9ca3af">
                Active / Total
              </Text>
              <Text fontSize="sm" fontWeight="bold" color="#ECECF1">
                {stats.activeDrivers} / {stats.totalDrivers}
              </Text>
            </HStack>
            <Box>
              <HStack justify="space-between" mb={1}>
                <Text fontSize="xs" color="#9ca3af">
                  Utilization
                </Text>
                <Text fontSize="xs" fontWeight="bold" color="#ECECF1">
                  {stats.utilizationRate.toFixed(0)}%
                </Text>
              </HStack>
              <Progress
                value={stats.utilizationRate}
                size="sm"
                colorScheme={stats.utilizationRate > 70 ? 'green' : stats.utilizationRate > 40 ? 'yellow' : 'red'}
                borderRadius="full"
              />
            </Box>
          </VStack>
        </Box>

        {/* Revenue Overview */}
        <Box bg="#0a0a0a" p={3} borderRadius="md" border="1px solid #333">
          <HStack mb={2}>
            <Icon as={FiDollarSign} color="#10b981" />
            <Text fontSize="sm" fontWeight="bold" color="#ECECF1">
              Revenue
            </Text>
          </HStack>
          <VStack spacing={2} align="stretch">
            <HStack justify="space-between">
              <Text fontSize="xs" color="#9ca3af">
                Today
              </Text>
              <Text fontSize="lg" fontWeight="bold" color="#10b981">
                £{stats.todayRevenue.toFixed(2)}
              </Text>
            </HStack>
            <HStack>
              <Icon as={FiTrendingUp} color="#10b981" boxSize={3} />
              <Text fontSize="xs" color="#10b981">
                +12% vs yesterday
              </Text>
            </HStack>
          </VStack>
        </Box>

        {/* Alerts */}
        {stats.alerts.length > 0 && (
          <>
            <Divider borderColor="#333" />
            <Box>
              <HStack mb={2}>
                <Icon as={FiAlertCircle} color="#ef4444" />
                <Text fontSize="sm" fontWeight="bold" color="#ECECF1">
                  Alerts
                </Text>
                <Badge colorScheme="red" fontSize="xs">
                  {stats.alerts.length}
                </Badge>
              </HStack>
              <VStack spacing={2} align="stretch">
                {stats.alerts.map((alert) => (
                  <Box
                    key={alert.id}
                    bg={
                      alert.type === 'error'
                        ? 'rgba(239, 68, 68, 0.1)'
                        : alert.type === 'warning'
                        ? 'rgba(245, 158, 11, 0.1)'
                        : 'rgba(59, 130, 246, 0.1)'
                    }
                    p={2}
                    borderRadius="md"
                    border="1px solid"
                    borderColor={
                      alert.type === 'error'
                        ? '#ef4444'
                        : alert.type === 'warning'
                        ? '#f59e0b'
                        : '#3b82f6'
                    }
                  >
                    <Text fontSize="xs" color="#ECECF1">
                      {alert.message}
                    </Text>
                    <Text fontSize="xs" color="#6b7280" mt={1}>
                      {new Date(alert.timestamp).toLocaleTimeString()}
                    </Text>
                  </Box>
                ))}
              </VStack>
            </Box>
          </>
        )}

        {/* Recent Activity */}
        <Divider borderColor="#333" />
        <Box>
          <HStack mb={2}>
            <Icon as={FiClock} color="#9ca3af" />
            <Text fontSize="sm" fontWeight="bold" color="#ECECF1">
              Recent Activity
            </Text>
          </HStack>
          <VStack spacing={2} align="stretch">
            {stats.recentActivity.slice(0, 5).map((activity) => (
              <HStack key={activity.id} spacing={2}>
                <Icon
                  as={
                    activity.type === 'booking'
                      ? FiPackage
                      : activity.type === 'driver'
                      ? FiTruck
                      : FiDollarSign
                  }
                  color="#6b7280"
                  boxSize={3}
                />
                <VStack align="start" spacing={0} flex={1}>
                  <Text fontSize="xs" color="#ECECF1" noOfLines={2}>
                    {activity.description}
                  </Text>
                  <Text fontSize="xs" color="#6b7280">
                    {new Date(activity.timestamp).toLocaleTimeString()}
                  </Text>
                </VStack>
              </HStack>
            ))}
          </VStack>
        </Box>

        {/* Footer */}
        <Divider borderColor="#333" />
        <Text fontSize="xs" color="#6b7280" textAlign="center">
          Auto-refreshes every 30 seconds
        </Text>
      </VStack>
    </Box>
  );
};

'use client';

import React, { useState, useEffect, useCallback } from 'react';
import {
  Box,
  VStack,
  HStack,
  Heading,
  Text,
  Button,
  Card,
  CardBody,
  CardHeader,
  Badge,
  Progress,
  SimpleGrid,
  Table,
  Thead,
  Tbody,
  Tr,
  Th,
  Td,
  TableContainer,
  IconButton,
  Tooltip,
  useToast,
  Modal,
  ModalOverlay,
  ModalContent,
  ModalHeader,
  Stat,
  StatLabel,
  StatNumber,
  StatHelpText,
  ModalBody,
  ModalFooter,
  ModalCloseButton,
  useDisclosure,
  FormControl,
  FormLabel,
  Select,
  Input,
  Textarea,
  Divider,
  Alert,
  AlertIcon,
  AlertTitle,
  AlertDescription,
  Spinner,
  Flex,
  Avatar,
  Tag,
  TagLabel,
  TagCloseButton,
  useColorModeValue,
} from '@chakra-ui/react';
import {
  FiTruck,
  FiMapPin,
  FiClock,
  FiUser,
  FiCheck,
  FiX,
  FiEye,
  FiEdit,
  FiTrash2,
  FiPlus,
  FiRefreshCw,
  FiNavigation,
  FiPhone,
  FiMail,
  FiAlertCircle,
  FiCheckCircle,
  FiXCircle,
} from 'react-icons/fi';

interface Drop {
  id: string;
  reference: string;
  pickupAddress: string;
  dropoffAddress: string;
  status: 'pending' | 'assigned_to_route' | 'picked_up' | 'in_transit' | 'delivered' | 'failed';
  scheduledAt: string;
  totalAmount: number;
  itemsCount: number;
  estimatedDuration: number;
  priority: 'low' | 'medium' | 'high';
  booking?: {
    customerName: string;
    customerPhone: string;
  };
  User?: {
    name: string;
    email: string;
  };
}

interface Route {
  id: string;
  status: 'pending_assignment' | 'assigned' | 'active' | 'completed' | 'failed';
  driverId?: string;
  driverName?: string;
  driverPhone?: string;
  serviceTier: string;
  totalDrops: number;
  completedDrops: number;
  estimatedDuration: number;
  totalDistance: number;
  totalValue: number;
  progress: number;
  timeWindowStart: string;
  timeWindowEnd: string;
  createdAt: string;
  drops: Drop[];
  // Add editable fields for admin control
  adminAdjustedPrice?: number;
  adminNotes?: string;
  isModifiedByAdmin?: boolean;
}

interface Driver {
  id: string;
  name: string;
  email: string;
  phone: string;
  status: 'offline' | 'available' | 'on_route' | 'break';
  currentRoutes: number;
  maxRoutes: number;
  rating: number;
  completedJobs: number;
  isOnline: boolean;
  lastSeen: string;
}

interface DriverResponse {
  driverId: string;
  response: 'accept' | 'decline' | 'view_details' | 'pending';
  responseTime: string;
  reason?: string;
}

export const MultipleDropsRouteManager: React.FC = () => {
  const [routes, setRoutes] = useState<Route[]>([]);
  const [availableDrops, setAvailableDrops] = useState<Drop[]>([]);
  const [availableDrivers, setAvailableDrivers] = useState<Driver[]>([]);
  const [driverResponses, setDriverResponses] = useState<Record<string, DriverResponse>>({});
  const [isLoading, setIsLoading] = useState(true);
  const [selectedRoute, setSelectedRoute] = useState<Route | null>(null);
  const [selectedDrops, setSelectedDrops] = useState<string[]>([]);
  const [isCreatingRoute, setIsCreatingRoute] = useState(false);
  const [editingRoute, setEditingRoute] = useState<Route | null>(null);
  const [editedPrice, setEditedPrice] = useState<number>(0);
  const [editedDrops, setEditedDrops] = useState<string[]>([]);
  const [editedNotes, setEditedNotes] = useState<string>('');

  const { isOpen: isRouteModalOpen, onOpen: onRouteModalOpen, onClose: onRouteModalClose } = useDisclosure();
  const { isOpen: isDriverModalOpen, onOpen: onDriverModalOpen, onClose: onDriverModalClose } = useDisclosure();
  const { isOpen: isEditModalOpen, onOpen: onEditModalOpen, onClose: onEditModalClose } = useDisclosure();
  
  const toast = useToast();
  const cardBg = useColorModeValue('white', 'gray.800');
  const borderColor = useColorModeValue('gray.200', 'gray.700');

  // Load data on component mount
  useEffect(() => {
    loadData();
    
    // Set up real-time updates
    const interval = setInterval(loadData, 30000); // Refresh every 30 seconds
    return () => clearInterval(interval);
  }, []);

  const loadData = useCallback(async () => {
    try {
      setIsLoading(true);
      
      // Load routes
      const routesResponse = await fetch('/api/admin/routes');
      const routesData = await routesResponse.json();
      
      // Load available drops (not assigned to routes)
      const dropsResponse = await fetch('/api/admin/drops?status=pending');
      const dropsData = await dropsResponse.json();
      
      // Load available drivers
      const driversResponse = await fetch('/api/admin/drivers?status=available');
      const driversData = await driversResponse.json();
      
      if (routesData.success) setRoutes(routesData.data.routes || []);
      if (dropsData.success) setAvailableDrops(dropsData.data.drops || []);
      if (driversData.success) setAvailableDrivers(driversData.data.drivers || []);
      
    } catch (error) {
      console.error('Error loading data:', error);
      toast({
        title: 'Error Loading Data',
        description: 'Failed to load routes and drops data',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setIsLoading(false);
    }
  }, [toast]);

  const createRoute = useCallback(async (routeData: {
    dropIds: string[];
    serviceTier: string;
    timeWindowStart: string;
    timeWindowEnd: string;
    priority: string;
  }) => {
    try {
      setIsCreatingRoute(true);
      
      const response = await fetch('/api/admin/routes', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(routeData),
      });
      
      const result = await response.json();
      
      if (result.success) {
        toast({
          title: 'Route Created',
          description: `Route ${result.data.route.id} created with ${routeData.dropIds.length} drops`,
          status: 'success',
          duration: 5000,
          isClosable: true,
        });
        
        // Refresh data
        await loadData();
        setSelectedDrops([]);
        onRouteModalClose();
      } else {
        throw new Error(result.error || 'Failed to create route');
      }
      
    } catch (error) {
      console.error('Error creating route:', error);
      toast({
        title: 'Error Creating Route',
        description: error instanceof Error ? error.message : 'Unknown error occurred',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setIsCreatingRoute(false);
    }
  }, [toast, loadData, onRouteModalClose]);

  const editRoute = useCallback((route: Route) => {
    setEditingRoute(route);
    setEditedPrice(route.adminAdjustedPrice || route.totalValue);
    setEditedDrops(route.drops.map(d => d.id));
    setEditedNotes(route.adminNotes || '');
    onEditModalOpen();
  }, [onEditModalOpen]);

  const saveRouteEdits = useCallback(async () => {
    if (!editingRoute) return;

    try {
      const response = await fetch(`/api/admin/routes/${editingRoute.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          adminAdjustedPrice: editedPrice,
          adminNotes: editedNotes,
          dropIds: editedDrops,
          isModifiedByAdmin: true
        }),
      });

      const result = await response.json();

      if (result.success) {
        toast({
          title: 'Route Updated',
          description: `Route ${editingRoute.id} has been updated successfully`,
          status: 'success',
          duration: 5000,
          isClosable: true,
        });

        await loadData();
        onEditModalClose();
      } else {
        throw new Error(result.error || 'Failed to update route');
      }
    } catch (error) {
      console.error('Error updating route:', error);
      toast({
        title: 'Error Updating Route',
        description: error instanceof Error ? error.message : 'Unknown error occurred',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    }
  }, [editingRoute, editedPrice, editedNotes, editedDrops, toast, loadData, onEditModalClose]);

  const assignDriverToRoute = useCallback(async (routeId: string, driverId: string) => {
    try {
      const response = await fetch(`/api/admin/routes/${routeId}/assign`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ driverId }),
      });
      
      const result = await response.json();
      
      if (result.success) {
        toast({
          title: 'Driver Assigned',
          description: `Driver assigned to route ${routeId}. 5-minute response window started.`,
          status: 'success',
          duration: 5000,
          isClosable: true,
        });
        
        // Start monitoring driver response
        monitorDriverResponse(routeId, driverId);
        await loadData();
      } else {
        throw new Error(result.error || 'Failed to assign driver');
      }
      
    } catch (error) {
      console.error('Error assigning driver:', error);
      toast({
        title: 'Error Assigning Driver',
        description: error instanceof Error ? error.message : 'Unknown error occurred',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    }
  }, [toast, loadData]);

  const monitorDriverResponse = useCallback((routeId: string, driverId: string) => {
    // Set initial pending response
    setDriverResponses(prev => ({
      ...prev,
      [routeId]: {
        driverId,
        response: 'pending',
        responseTime: new Date().toISOString(),
      }
    }));

    // Start 5-minute countdown
    const timeout = setTimeout(() => {
      setDriverResponses(prev => ({
        ...prev,
        [routeId]: {
          ...prev[routeId],
          response: 'decline',
          reason: 'No response within 5 minutes',
        }
      }));
      
      toast({
        title: 'Driver Response Timeout',
        description: `Driver did not respond within 5 minutes for route ${routeId}`,
        status: 'warning',
        duration: 5000,
        isClosable: true,
      });
    }, 5 * 60 * 1000); // 5 minutes

    // Clean up timeout if component unmounts
    return () => clearTimeout(timeout);
  }, [toast]);

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'pending_assignment': return 'orange';
      case 'assigned': return 'blue';
      case 'active': return 'green';
      case 'completed': return 'gray';
      case 'failed': return 'red';
      default: return 'gray';
    }
  };

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'pending_assignment': return FiClock;
      case 'assigned': return FiUser;
      case 'active': return FiTruck;
      case 'completed': return FiCheck;
      case 'failed': return FiX;
      default: return FiClock;
    }
  };

  const formatDuration = (minutes: number) => {
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    return hours > 0 ? `${hours}h ${mins}m` : `${mins}m`;
  };

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('en-GB', {
      style: 'currency',
      currency: 'GBP',
    }).format(amount);
  };

  if (isLoading) {
    return (
      <Box p={6} textAlign="center">
        <Spinner size="xl" />
        <Text mt={4}>Loading multiple drops routes...</Text>
      </Box>
    );
  }

  return (
    <Box p={6}>
      <VStack spacing={6} align="stretch">
        {/* Header */}
        <Flex justify="space-between" align="center">
          <VStack align="start" spacing={1}>
            <Heading size="lg">Multiple Drops Route Management</Heading>
            <Text color="gray.600">
              Manage multi-drop routes, assign drivers, and monitor progress
            </Text>
          </VStack>
          <HStack spacing={3}>
            <Button
              leftIcon={<FiRefreshCw />}
              onClick={loadData}
              variant="outline"
              isLoading={isLoading}
            >
              Refresh
            </Button>
            <Button
              leftIcon={<FiPlus />}
              colorScheme="blue"
              onClick={onRouteModalOpen}
              isDisabled={availableDrops.length === 0}
            >
              Create Route
            </Button>
          </HStack>
        </Flex>

        {/* Statistics Cards */}
        <SimpleGrid columns={{ base: 1, md: 2, lg: 4 }} spacing={4}>
          <Card bg={cardBg} borderColor={borderColor}>
            <CardBody>
              <Stat>
                <StatLabel>Active Routes</StatLabel>
                <StatNumber>{routes.filter(r => r.status === 'active').length}</StatNumber>
                <StatHelpText>Currently in progress</StatHelpText>
              </Stat>
            </CardBody>
          </Card>
          
          <Card bg={cardBg} borderColor={borderColor}>
            <CardBody>
              <Stat>
                <StatLabel>Pending Assignment</StatLabel>
                <StatNumber>{routes.filter(r => r.status === 'pending_assignment').length}</StatNumber>
                <StatHelpText>Awaiting driver assignment</StatHelpText>
              </Stat>
            </CardBody>
          </Card>
          
          <Card bg={cardBg} borderColor={borderColor}>
            <CardBody>
              <Stat>
                <StatLabel>Available Drops</StatLabel>
                <StatNumber>{availableDrops.length}</StatNumber>
                <StatHelpText>Ready for routing</StatHelpText>
              </Stat>
            </CardBody>
          </Card>
          
          <Card bg={cardBg} borderColor={borderColor}>
            <CardBody>
              <Stat>
                <StatLabel>Available Drivers</StatLabel>
                <StatNumber>{availableDrivers.filter(d => d.status === 'available').length}</StatNumber>
                <StatHelpText>Ready for assignment</StatHelpText>
              </Stat>
            </CardBody>
          </Card>
        </SimpleGrid>

        {/* Routes Table */}
        <Card bg={cardBg} borderColor={borderColor}>
          <CardHeader>
            <Heading size="md">Current Routes</Heading>
          </CardHeader>
          <CardBody>
            {routes.length === 0 ? (
              <Alert status="info">
                <AlertIcon />
                <AlertTitle>No routes found</AlertTitle>
                <AlertDescription>
                  Create your first multiple drops route to get started.
                </AlertDescription>
              </Alert>
            ) : (
              <TableContainer>
                <Table variant="simple">
                  <Thead>
                    <Tr>
                      <Th>Route ID</Th>
                      <Th>Status</Th>
                      <Th>Driver</Th>
                      <Th>Drops</Th>
                      <Th>Progress</Th>
                      <Th>Value</Th>
                      <Th>Time Window</Th>
                      <Th>Actions</Th>
                    </Tr>
                  </Thead>
                  <Tbody>
                    {routes.map((route) => {
                      const StatusIcon = getStatusIcon(route.status);
                      const driverResponse = driverResponses[route.id];
                      
                      return (
                        <Tr key={route.id}>
                          <Td>
                            <Text fontFamily="mono" fontSize="sm">
                              {route.id.slice(-8)}
                            </Text>
                          </Td>
                          <Td>
                            <Badge
                              colorScheme={getStatusColor(route.status)}
                              variant="subtle"
                              display="flex"
                              alignItems="center"
                              gap={1}
                              w="fit-content"
                            >
                              <StatusIcon size={12} />
                              {route.status.replace('_', ' ')}
                            </Badge>
                          </Td>
                          <Td>
                            {route.driverName ? (
                              <VStack align="start" spacing={1}>
                                <Text fontSize="sm" fontWeight="medium">
                                  {route.driverName}
                                </Text>
                                {driverResponse && (
                                  <Badge
                                    size="sm"
                                    colorScheme={
                                      driverResponse.response === 'accept' ? 'green' :
                                      driverResponse.response === 'decline' ? 'red' :
                                      driverResponse.response === 'view_details' ? 'blue' : 'yellow'
                                    }
                                  >
                                    {driverResponse.response}
                                  </Badge>
                                )}
                              </VStack>
                            ) : (
                              <Text fontSize="sm" color="gray.500">
                                Unassigned
                              </Text>
                            )}
                          </Td>
                          <Td>
                            <Text fontSize="sm">
                              {route.completedDrops}/{route.totalDrops}
                            </Text>
                          </Td>
                          <Td>
                            <VStack align="start" spacing={1}>
                              <Progress
                                value={route.progress}
                                size="sm"
                                colorScheme="green"
                                w="60px"
                              />
                              <Text fontSize="xs" color="gray.500">
                                {Math.round(route.progress)}%
                              </Text>
                            </VStack>
                          </Td>
                          <Td>
                            <VStack align="start" spacing={0}>
                              <Text fontSize="sm" fontWeight="medium">
                                {formatCurrency(route.adminAdjustedPrice || route.totalValue)}
                              </Text>
                              {route.adminAdjustedPrice && route.adminAdjustedPrice !== route.totalValue && (
                                <Text fontSize="xs" color="gray.500">
                                  Was: {formatCurrency(route.totalValue)}
                                </Text>
                              )}
                            </VStack>
                          </Td>
                          <Td>
                            <VStack align="start" spacing={1}>
                              <Text fontSize="xs">
                                {new Date(route.timeWindowStart).toLocaleTimeString('en-GB', {
                                  hour: '2-digit',
                                  minute: '2-digit'
                                })}
                              </Text>
                              <Text fontSize="xs" color="gray.500">
                                to {new Date(route.timeWindowEnd).toLocaleTimeString('en-GB', {
                                  hour: '2-digit',
                                  minute: '2-digit'
                                })}
                              </Text>
                            </VStack>
                          </Td>
                          <Td>
                            <HStack spacing={1}>
                              <Tooltip label="View Details">
                                <IconButton
                                  aria-label="View route details"
                                  icon={<FiEye />}
                                  size="sm"
                                  variant="ghost"
                                  onClick={() => {
                                    setSelectedRoute(route);
                                    onDriverModalOpen();
                                  }}
                                />
                              </Tooltip>
                              {route.status === 'pending_assignment' && (
                                <>
                                  <Tooltip label="Edit Route">
                                    <IconButton
                                      aria-label="Edit route"
                                      icon={<FiEdit />}
                                      size="sm"
                                      variant="ghost"
                                      colorScheme="orange"
                                      onClick={() => editRoute(route)}
                                    />
                                  </Tooltip>
                                  <Tooltip label="Assign Driver">
                                    <IconButton
                                      aria-label="Assign driver"
                                      icon={<FiUser />}
                                      size="sm"
                                      variant="ghost"
                                      colorScheme="blue"
                                      onClick={() => {
                                        setSelectedRoute(route);
                                        onDriverModalOpen();
                                      }}
                                    />
                                  </Tooltip>
                                </>
                              )}
                              {route.isModifiedByAdmin && (
                                <Tooltip label="Modified by Admin">
                                  <Badge colorScheme="purple" size="sm">
                                    MODIFIED
                                  </Badge>
                                </Tooltip>
                              )}
                            </HStack>
                          </Td>
                        </Tr>
                      );
                    })}
                  </Tbody>
                </Table>
              </TableContainer>
            )}
          </CardBody>
        </Card>

        {/* Available Drops */}
        {availableDrops.length > 0 && (
          <Card bg={cardBg} borderColor={borderColor}>
            <CardHeader>
              <Heading size="md">Available Drops ({availableDrops.length})</Heading>
              <Text fontSize="sm" color="gray.600">
                Select drops to create a new route
              </Text>
            </CardHeader>
            <CardBody>
              <TableContainer>
                <Table variant="simple" size="sm">
                  <Thead>
                    <Tr>
                      <Th>Select</Th>
                      <Th>Reference</Th>
                      <Th>Customer</Th>
                      <Th>Pickup → Dropoff</Th>
                      <Th>Scheduled</Th>
                      <Th>Value</Th>
                      <Th>Priority</Th>
                    </Tr>
                  </Thead>
                  <Tbody>
                    {availableDrops.map((drop) => (
                      <Tr key={drop.id}>
                        <Td>
                          <input
                            type="checkbox"
                            checked={selectedDrops.includes(drop.id)}
                            onChange={(e) => {
                              if (e.target.checked) {
                                setSelectedDrops(prev => [...prev, drop.id]);
                              } else {
                                setSelectedDrops(prev => prev.filter(id => id !== drop.id));
                              }
                            }}
                          />
                        </Td>
                        <Td>
                          <Text fontFamily="mono" fontSize="sm">
                            {drop.reference}
                          </Text>
                        </Td>
                        <Td>
                          <VStack align="start" spacing={0}>
                            <Text fontSize="sm" fontWeight="medium">
                              {drop.booking?.customerName || drop.User?.name || 'Unknown'}
                            </Text>
                            <Text fontSize="xs" color="gray.500">
                              {drop.booking?.customerPhone || 'No phone'}
                            </Text>
                          </VStack>
                        </Td>
                        <Td>
                          <VStack align="start" spacing={1}>
                            <Text fontSize="xs" noOfLines={1}>
                              📍 {drop.pickupAddress}
                            </Text>
                            <Text fontSize="xs" color="gray.500" noOfLines={1}>
                              🎯 {drop.dropoffAddress}
                            </Text>
                          </VStack>
                        </Td>
                        <Td>
                          <Text fontSize="sm">
                            {new Date(drop.scheduledAt).toLocaleDateString('en-GB')}
                          </Text>
                          <Text fontSize="xs" color="gray.500">
                            {new Date(drop.scheduledAt).toLocaleTimeString('en-GB', {
                              hour: '2-digit',
                              minute: '2-digit'
                            })}
                          </Text>
                        </Td>
                        <Td>
                          <Text fontSize="sm" fontWeight="medium">
                            {formatCurrency(drop.totalAmount)}
                          </Text>
                        </Td>
                        <Td>
                          <Badge
                            colorScheme={
                              drop.priority === 'high' ? 'red' :
                              drop.priority === 'medium' ? 'orange' : 'gray'
                            }
                            size="sm"
                          >
                            {drop.priority}
                          </Badge>
                        </Td>
                      </Tr>
                    ))}
                  </Tbody>
                </Table>
              </TableContainer>
              
              {selectedDrops.length > 0 && (
                <Box mt={4} p={4} bg="blue.50" borderRadius="md">
                  <HStack justify="space-between">
                    <Text fontSize="sm" fontWeight="medium">
                      {selectedDrops.length} drops selected
                    </Text>
                    <Button
                      size="sm"
                      colorScheme="blue"
                      onClick={onRouteModalOpen}
                    >
                      Create Route
                    </Button>
                  </HStack>
                </Box>
              )}
            </CardBody>
          </Card>
        )}
      </VStack>

      {/* Create Route Modal */}
      <Modal isOpen={isRouteModalOpen} onClose={onRouteModalClose} size="lg">
        <ModalOverlay />
        <ModalContent>
          <ModalHeader>Create Multiple Drops Route</ModalHeader>
          <ModalCloseButton />
          <ModalBody>
            <VStack spacing={4} align="stretch">
              <Alert status="info">
                <AlertIcon />
                <Box>
                  <AlertTitle>Route Creation</AlertTitle>
                  <AlertDescription>
                    Creating a route with {selectedDrops.length} selected drops.
                  </AlertDescription>
                </Box>
              </Alert>
              
              <FormControl>
                <FormLabel>Service Tier</FormLabel>
                <Select placeholder="Select service tier">
                  <option value="small_van">Small Van</option>
                  <option value="large_van">Large Van</option>
                  <option value="truck">Truck</option>
                </Select>
              </FormControl>
              
              <SimpleGrid columns={2} spacing={4}>
                <FormControl>
                  <FormLabel>Time Window Start</FormLabel>
                  <Input type="time" />
                </FormControl>
                <FormControl>
                  <FormLabel>Time Window End</FormLabel>
                  <Input type="time" />
                </FormControl>
              </SimpleGrid>
              
              <FormControl>
                <FormLabel>Priority</FormLabel>
                <Select placeholder="Select priority">
                  <option value="low">Low</option>
                  <option value="medium">Medium</option>
                  <option value="high">High</option>
                </Select>
              </FormControl>
            </VStack>
          </ModalBody>
          <ModalFooter>
            <Button variant="ghost" mr={3} onClick={onRouteModalClose}>
              Cancel
            </Button>
            <Button
              colorScheme="blue"
              isLoading={isCreatingRoute}
              onClick={() => {
                // This would be implemented with form data
                createRoute({
                  dropIds: selectedDrops,
                  serviceTier: 'large_van',
                  timeWindowStart: new Date().toISOString(),
                  timeWindowEnd: new Date(Date.now() + 4 * 60 * 60 * 1000).toISOString(),
                  priority: 'medium',
                });
              }}
            >
              Create Route
            </Button>
          </ModalFooter>
        </ModalContent>
      </Modal>

      {/* Driver Assignment Modal */}
      <Modal isOpen={isDriverModalOpen} onClose={onDriverModalClose} size="xl">
        <ModalOverlay />
        <ModalContent>
          <ModalHeader>
            {selectedRoute?.driverName ? 'Route Details' : 'Assign Driver to Route'}
          </ModalHeader>
          <ModalCloseButton />
          <ModalBody>
            {selectedRoute && (
              <VStack spacing={4} align="stretch">
                <Card>
                  <CardBody>
                    <SimpleGrid columns={2} spacing={4}>
                      <Box>
                        <Text fontSize="sm" color="gray.500">Route ID</Text>
                        <Text fontFamily="mono">{selectedRoute.id}</Text>
                      </Box>
                      <Box>
                        <Text fontSize="sm" color="gray.500">Status</Text>
                        <Badge colorScheme={getStatusColor(selectedRoute.status)}>
                          {selectedRoute.status.replace('_', ' ')}
                        </Badge>
                      </Box>
                      <Box>
                        <Text fontSize="sm" color="gray.500">Total Drops</Text>
                        <Text>{selectedRoute.totalDrops}</Text>
                      </Box>
                      <Box>
                        <Text fontSize="sm" color="gray.500">Total Value</Text>
                        <Text fontWeight="medium">{formatCurrency(selectedRoute.totalValue)}</Text>
                      </Box>
                    </SimpleGrid>
                  </CardBody>
                </Card>
                
                {!selectedRoute.driverName && availableDrivers.length > 0 && (
                  <Card>
                    <CardHeader>
                      <Heading size="sm">Available Drivers</Heading>
                    </CardHeader>
                    <CardBody>
                      <VStack spacing={3}>
                        {availableDrivers.map((driver) => (
                          <Card key={driver.id} variant="outline" w="full">
                            <CardBody>
                              <HStack justify="space-between">
                                <HStack spacing={3}>
                                  <Avatar size="sm" name={driver.name} />
                                  <VStack align="start" spacing={0}>
                                    <Text fontWeight="medium">{driver.name}</Text>
                                    <Text fontSize="sm" color="gray.500">
                                      {driver.completedJobs} jobs • ⭐ {driver.rating.toFixed(1)}
                                    </Text>
                                  </VStack>
                                </HStack>
                                <Button
                                  size="sm"
                                  colorScheme="blue"
                                  onClick={() => assignDriverToRoute(selectedRoute.id, driver.id)}
                                >
                                  Assign
                                </Button>
                              </HStack>
                            </CardBody>
                          </Card>
                        ))}
                      </VStack>
                    </CardBody>
                  </Card>
                )}
                
                {selectedRoute.driverName && (
                  <Alert status="success">
                    <AlertIcon />
                    <Box>
                      <AlertTitle>Driver Assigned</AlertTitle>
                      <AlertDescription>
                        {selectedRoute.driverName} is assigned to this route.
                        Driver has 5 minutes to Accept/Decline/View Details.
                      </AlertDescription>
                    </Box>
                  </Alert>
                )}
              </VStack>
            )}
          </ModalBody>
          <ModalFooter>
            <Button onClick={onDriverModalClose}>Close</Button>
          </ModalFooter>
        </ModalContent>
      </Modal>

      {/* Edit Route Modal */}
      <Modal isOpen={isEditModalOpen} onClose={onEditModalClose} size="xl">
        <ModalOverlay />
        <ModalContent>
          <ModalHeader>Edit Route - Full Admin Control</ModalHeader>
          <ModalCloseButton />
          <ModalBody>
            {editingRoute && (
              <VStack spacing={6} align="stretch">
                {/* Route Info */}
                <Card>
                  <CardBody>
                    <SimpleGrid columns={2} spacing={4}>
                      <Box>
                        <Text fontSize="sm" color="gray.500">Route ID</Text>
                        <Text fontFamily="mono">{editingRoute.id}</Text>
                      </Box>
                      <Box>
                        <Text fontSize="sm" color="gray.500">Original Value</Text>
                        <Text fontWeight="medium">{formatCurrency(editingRoute.totalValue)}</Text>
                      </Box>
                      <Box>
                        <Text fontSize="sm" color="gray.500">Service Tier</Text>
                        <Badge colorScheme="blue">{editingRoute.serviceTier}</Badge>
                      </Box>
                      <Box>
                        <Text fontSize="sm" color="gray.500">Total Drops</Text>
                        <Text>{editingRoute.totalDrops}</Text>
                      </Box>
                    </SimpleGrid>
                  </CardBody>
                </Card>

                {/* Price Adjustment */}
                <Card>
                  <CardHeader>
                    <Heading size="sm">Price Adjustment</Heading>
                    <Text fontSize="sm" color="gray.600">
                      Set the final price for this route before assigning to driver
                    </Text>
                  </CardHeader>
                  <CardBody>
                    <FormControl>
                      <FormLabel>Adjusted Price (£)</FormLabel>
                      <Input
                        type="number"
                        step="0.01"
                        value={editedPrice}
                        onChange={(e) => setEditedPrice(parseFloat(e.target.value) || 0)}
                        placeholder="Enter adjusted price"
                      />
                      <Text fontSize="sm" color="gray.500" mt={1}>
                        Original: {formatCurrency(editingRoute.totalValue)} |
                        Adjustment: {editedPrice !== (editingRoute.adminAdjustedPrice || editingRoute.totalValue)
                          ? `${editedPrice > (editingRoute.adminAdjustedPrice || editingRoute.totalValue) ? '+' : ''}${
                              formatCurrency(editedPrice - (editingRoute.adminAdjustedPrice || editingRoute.totalValue))
                            }`
                          : 'No change'}
                      </Text>
                    </FormControl>
                  </CardBody>
                </Card>

                {/* Drops Management */}
                <Card>
                  <CardHeader>
                    <Heading size="sm">Manage Drops</Heading>
                    <Text fontSize="sm" color="gray.600">
                      Add or remove drops from this route
                    </Text>
                  </CardHeader>
                  <CardBody>
                    <VStack spacing={3} align="stretch">
                      <Text fontSize="sm" fontWeight="medium">
                        Current Drops ({editedDrops.length})
                      </Text>

                      {editingRoute.drops.map((drop) => (
                        <Card key={drop.id} variant="outline" size="sm">
                          <CardBody>
                            <HStack justify="space-between">
                              <VStack align="start" spacing={1}>
                                <HStack>
                                  <input
                                    type="checkbox"
                                    checked={editedDrops.includes(drop.id)}
                                    onChange={(e) => {
                                      if (e.target.checked) {
                                        setEditedDrops(prev => [...prev, drop.id]);
                                      } else {
                                        setEditedDrops(prev => prev.filter(id => id !== drop.id));
                                      }
                                    }}
                                  />
                                  <Text fontSize="sm" fontWeight="medium">
                                    {drop.reference}
                                  </Text>
                                </HStack>
                                <Text fontSize="xs" color="gray.500">
                                  {drop.booking?.customerName || drop.User?.name || 'Unknown'} • {formatCurrency(drop.totalAmount)}
                                </Text>
                                <Text fontSize="xs" noOfLines={1}>
                                  📍 {drop.pickupAddress} → 🎯 {drop.dropoffAddress}
                                </Text>
                              </VStack>
                              <Badge
                                colorScheme={
                                  editedDrops.includes(drop.id) ? 'green' : 'red'
                                }
                                size="sm"
                              >
                                {editedDrops.includes(drop.id) ? 'Included' : 'Excluded'}
                              </Badge>
                            </HStack>
                          </CardBody>
                        </Card>
                      ))}

                      {/* Add available drops */}
                      {availableDrops.length > 0 && (
                        <Box>
                          <Text fontSize="sm" fontWeight="medium" mb={2}>
                            Add from Available Drops
                          </Text>
                          <VStack spacing={2} align="stretch">
                            {availableDrops.slice(0, 5).map((drop) => (
                              <Card key={drop.id} variant="outline" size="sm">
                                <CardBody>
                                  <HStack justify="space-between">
                                    <VStack align="start" spacing={1}>
                                      <Text fontSize="sm" fontWeight="medium">
                                        {drop.reference}
                                      </Text>
                                      <Text fontSize="xs" color="gray.500">
                                        {drop.booking?.customerName || drop.User?.name || 'Unknown'} • {formatCurrency(drop.totalAmount)}
                                      </Text>
                                    </VStack>
                                    <Button
                                      size="xs"
                                      colorScheme="green"
                                      onClick={() => {
                                        setEditedDrops(prev => [...prev, drop.id]);
                                      }}
                                      isDisabled={editedDrops.includes(drop.id)}
                                    >
                                      {editedDrops.includes(drop.id) ? 'Added' : 'Add'}
                                    </Button>
                                  </HStack>
                                </CardBody>
                              </Card>
                            ))}
                          </VStack>
                        </Box>
                      )}
                    </VStack>
                  </CardBody>
                </Card>

                {/* Admin Notes */}
                <Card>
                  <CardHeader>
                    <Heading size="sm">Admin Notes</Heading>
                  </CardHeader>
                  <CardBody>
                    <FormControl>
                      <FormLabel>Internal Notes (Optional)</FormLabel>
                      <Textarea
                        value={editedNotes}
                        onChange={(e) => setEditedNotes(e.target.value)}
                        placeholder="Add notes about this route modification..."
                        rows={3}
                      />
                    </FormControl>
                  </CardBody>
                </Card>

                {/* Summary */}
                <Alert status="info">
                  <AlertIcon />
                  <Box>
                    <AlertTitle>Route Summary</AlertTitle>
                    <AlertDescription>
                      <VStack align="start" spacing={1}>
                        <Text>Drops: {editedDrops.length} (was {editingRoute.totalDrops})</Text>
                        <Text>Adjusted Price: {formatCurrency(editedPrice)}</Text>
                        <Text>Status: Will be marked as modified by admin</Text>
                      </VStack>
                    </AlertDescription>
                  </Box>
                </Alert>
              </VStack>
            )}
          </ModalBody>
          <ModalFooter>
            <Button variant="ghost" mr={3} onClick={onEditModalClose}>
              Cancel
            </Button>
            <Button
              colorScheme="blue"
              onClick={saveRouteEdits}
              isDisabled={!editingRoute}
            >
              Save Changes
            </Button>
          </ModalFooter>
        </ModalContent>
      </Modal>
    </Box>
  );
};

