// Flashing animations
const pulseAnimation = keyframes`
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.6; transform: scale(1.1); }
`;

const fastPulseAnimation = keyframes`
  0%, 100% { opacity: 1; transform: scale(1); box-shadow: 0 0 0 0 rgba(239, 68, 68, 0.7); }
  50% { opacity: 0.7; transform: scale(1.15); box-shadow: 0 0 0 10px rgba(239, 68, 68, 0); }
`;

// Priority calculation
function calculatePriority(scheduledAt: string) {
  const now = new Date();
  const scheduled = new Date(scheduledAt);
  const hoursUntil = differenceInHours(scheduled, now);
  const daysUntil = differenceInDays(scheduled, now);

  if (hoursUntil >= 0 && hoursUntil <= 48) {
    return {
      level: 'urgent',
      color: 'red.500',
      bgColor: 'red.50',
      label: 'URGENT - Tomorrow',
      animation: `${fastPulseAnimation} 1.5s ease-in-out infinite`,
    };
  }
  if (hoursUntil > 48 && hoursUntil <= 72) {
    return {
      level: 'high',
      color: 'orange.500',
      bgColor: 'orange.50',
      label: 'Day After Tomorrow',
      animation: `${pulseAnimation} 2s ease-in-out infinite`,
    };
  }
  if (daysUntil > 3 && daysUntil <= 7) {
    return {
      level: 'medium',
      color: 'yellow.500',
      bgColor: 'yellow.50',
      label: 'This Week',
      animation: `${pulseAnimation} 2.5s ease-in-out infinite`,
    };
  }
  if (daysUntil > 7 && daysUntil <= 14) {
    return {
      level: 'low',
      color: 'green.400',
      bgColor: 'green.50',
      label: 'Next Week',
      animation: `${pulseAnimation} 3s ease-in-out infinite`,
    };
  }
  return {
    level: 'future',
    color: 'green.600',
    bgColor: 'green.50',
    label: 'Scheduled',
    animation: `${pulseAnimation} 3.5s ease-in-out infinite`,
  };
}

// Calculate estimated driver earnings
function calculateDriverEarnings(order: any) {
  const distanceMiles = order.distanceMeters 
    ? order.distanceMeters / 1609.34 
    : order.baseDistanceMiles || 0;
  
  // Calculate realistic duration if not available
  let durationMinutes = 0;
  if (order.durationSeconds && order.durationSeconds > 3600) {
    durationMinutes = order.durationSeconds / 60;
  } else if (distanceMiles > 0) {
    // Estimate based on distance: 30mph average + 30min loading
    durationMinutes = (distanceMiles / 30) * 60 + 30;
  } else {
    durationMinutes = order.estimatedDurationMinutes || 0;
  }
  
  const baseFare = 25.00;
  const mileageFee = distanceMiles * 0.55;
  const timeFee = durationMinutes * 0.15;
  const total = baseFare + mileageFee + timeFee;
  
  return {
    base: baseFare,
    mileage: mileageFee,
    time: timeFee,
    total,
    formatted: `£${total.toFixed(2)}`
  };
}

interface OrderDetail {
  id: string;
  reference: string;
  status: string;
  scheduledAt: string;
  totalGBP: number;
  customerName: string;
  customerEmail: string;
  customerPhone: string;
  amountPaidGBP?: number;
  additionalPaymentStatus?: 'NONE' | 'PENDING' | 'PAID' | 'REFUNDED' | 'FAILED';
  additionalPaymentAmountGBP?: number;
  additionalPaymentRequestedAt?: string | null;
  additionalPaymentPaidAt?: string | null;
  additionalPaymentStripeIntent?: string | null;
  lastPaymentDate?: string | null;
  lastRefundDate?: string | null;
  pickupAddress?: {
    label: string;
    postcode: string;
    flatNumber?: string;
    lat?: number | null;
    lng?: number | null;
  };
  dropoffAddress?: {
    label: string;
    postcode: string;
    flatNumber?: string;
    lat?: number | null;
    lng?: number | null;
  };
  pickupProperty?: {
    propertyType: string;
    floors: number;
    accessType: string;
  };
  dropoffProperty?: {
    propertyType: string;
    floors: number;
    accessType: string;
  };
  driver?: {
    user: {
      name: string;
      email: string;
      phone: string;
    };
  };
  createdAt: string;
  paidAt?: string;
  durationSeconds?: number;
  distanceMeters?: number;
  baseDistanceMiles?: number;
  notes?: string;
  pickupTimeSlot?: string;
  serviceType?: string;
  orderType?: string;
  isMultiDrop?: boolean;
  routeId?: string | null;
  route?: {
    id: string;
    reference: string;
    status: string;
    totalDrops: number;
  } | null;
  items?: Array<{
    id: string;
    name: string;
    quantity: number;
    volumeM3: number;
    image?: string;
  }>;
  capacityCheck?: {
    isValid: boolean;
    weightUtilization: number;
    volumeUtilization: number;
    itemUtilization: number;
    warnings: string[];
    recommendations: string[];
    vansRequired?: number;
  };
}

interface OrderDetailDrawerProps {
  isOpen: boolean;
  onClose: () => void;
  orderCode?: string;
  variant?: 'standalone' | 'embedded';
  showSummaryCards?: boolean;
}

const OrderDetailDrawer: React.FC<OrderDetailDrawerProps> = ({
  isOpen,
  onClose,
  orderCode,
  variant = 'standalone',
  showSummaryCards = true,
}) => {
  const [order, setOrder] = useState<OrderDetail | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isEditing, setIsEditing] = useState(false);
  const [editedOrder, setEditedOrder] = useState<Partial<OrderDetail>>({});
  const [isSaving, setIsSaving] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [isGeneratingInvoice, setIsGeneratingInvoice] = useState(false);
  const [isAssigningDriver, setIsAssigningDriver] = useState(false);
  const [selectedDriverId, setSelectedDriverId] = useState('');
  const [assignmentReason, setAssignmentReason] = useState('');
  const [availableDrivers, setAvailableDrivers] = useState<any[]>([]);
  const [isLoadingDrivers, setIsLoadingDrivers] = useState(false);
  const [newCalculatedPrice, setNewCalculatedPrice] = useState<number | null>(null);
  const [adjustedTotalGBP, setAdjustedTotalGBP] = useState<number>(0);
  const [adjustmentReason, setAdjustmentReason] = useState('');
  const [isRequestingAdditionalPayment, setIsRequestingAdditionalPayment] = useState(false);
  const [isIssuingRefund, setIsIssuingRefund] = useState(false);
  const [isRecalculatingPrice, setIsRecalculatingPrice] = useState(false);
  const [isSendingEmail, setIsSendingEmail] = useState(false);
  const [isCancelling, setIsCancelling] = useState(false);
  const [isRemovingDriver, setIsRemovingDriver] = useState(false);
  const isEmbedded = variant === 'embedded';
  
  const toast = useToast();

  // Handle copy order code
  const handleCopyOrderCode = useCallback(() => {
    if (!orderCode) return;
    
    navigator.clipboard.writeText(orderCode).then(() => {
      toast({
        title: 'Copied!',
        description: `Order code ${orderCode} copied to clipboard`,
        status: 'success',
        duration: 2000,
        isClosable: true,
      });
    }).catch(() => {
      toast({
        title: 'Copy failed',
        description: 'Could not copy to clipboard',
        status: 'error',
        duration: 2000,
        isClosable: true,
      });
    });
  }, [orderCode, toast]);
  const { 
    isOpen: isCancelModalOpen, 
    onOpen: onCancelModalOpen, 
    onClose: onCancelModalClose 
  } = useDisclosure();
  const { 
    isOpen: isAssignModalOpen, 
    onOpen: onAssignModalOpen, 
    onClose: onAssignModalClose 
  } = useDisclosure();

  // Auto-load drivers when assign modal opens
  useEffect(() => {
    if (isAssignModalOpen && availableDrivers.length === 0) {
      loadAvailableDrivers();
    }
  }, [isAssignModalOpen]);

  // Auto-select driver if only one is available
  useEffect(() => {
    if (availableDrivers.length === 1 && !selectedDriverId && isAssignModalOpen) {
      const singleDriver = availableDrivers[0];
      if (singleDriver.isAvailable) {
        setSelectedDriverId(singleDriver.id);
        toast({
          title: 'Driver Auto-Selected',
          description: `Automatically selected ${singleDriver.name} as the only available driver`,
          status: 'info',
          duration: 3000,
          isClosable: true,
        });
      }
    }
  }, [availableDrivers, selectedDriverId, isAssignModalOpen]);
  const { 
    isOpen: isRemoveModalOpen, 
    onOpen: onRemoveModalOpen, 
    onClose: onRemoveModalClose 
  } = useDisclosure();

  // Dark theme with black background and white text
  const bgColor = '#000000'; // Pure black background
  const borderColor = '#333333'; // Dark gray border
  const textColor = '#FFFFFF'; // White text
  const secondaryTextColor = '#9ca3af'; // Light gray for secondary text
  const cardBg = '#111111'; // Dark gray for cards

  useEffect(() => {
    if (isOpen && orderCode) {
      fetchOrderDetails();
    }
  }, [isOpen, orderCode]);

  const fetchOrderDetails = async () => {
    if (!orderCode) return;

    setLoading(true);
    setError(null);

    try {
      const response = await fetch(`/api/admin/orders/${orderCode}`);
      if (!response.ok) {
        throw new Error('Failed to fetch order details');
      }

      const orderData = await response.json();
      setOrder(orderData);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An error occurred');
      toast({
        title: 'Error',
        description: 'Failed to load order details',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (order) {
      setAdjustedTotalGBP(order.totalGBP);
    }
  }, [order?.id, order?.totalGBP]);

  useEffect(() => {
    if (order && (order.amountPaidGBP ?? 0) > 0 && newCalculatedPrice) {
      setAdjustedTotalGBP(newCalculatedPrice);
    }
  }, [order, newCalculatedPrice]);

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'COMPLETED':
        return 'green';
      case 'CANCELLED':
        return 'red';
      case 'in_progress':
        return 'blue';
      case 'CONFIRMED':
        return 'yellow';
      case 'DRAFT':
        return 'gray';
      default:
        return 'gray';
    }
  };

  const formatCurrency = (amount: number) => {
    return `£${(amount / 100).toFixed(2)}`;
  };

  const formatDateTime = (value?: string | null) => {
    if (!value) return 'N/A';
    try {
      return new Date(value).toLocaleString('en-GB', {
        year: 'numeric',
        month: 'short',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit',
      });
    } catch (error) {
      return value;
    }
  };

  const formatDuration = (seconds?: number) => {
    if (!seconds || seconds === 0) return 'Not calculated';
    const hours = Math.floor(seconds / 3600);
    const minutes = Math.floor((seconds % 3600) / 60);
    if (hours === 0 && minutes === 0) return 'Not calculated';
    if (hours === 0) return `${minutes}m`;
    if (minutes === 0) return `${hours}h`;
    return `${hours}h ${minutes}m`;
  };

  const calculateEstimatedDuration = (order: OrderDetail) => {
    // If we have actual duration, use it
    if (order.durationSeconds && order.durationSeconds > 3600) {
      return order.durationSeconds;
    }
    
    // Calculate based on distance (if available)
    const distanceMiles = order.baseDistanceMiles || (order.distanceMeters ? order.distanceMeters / 1609.34 : 0);
    
    if (distanceMiles > 0) {
      // Estimate: 30mph average speed in city + 30min loading/unloading
      const drivingMinutes = (distanceMiles / 30) * 60;
      const loadingMinutes = 30;
      const totalMinutes = drivingMinutes + loadingMinutes;
      return Math.round(totalMinutes * 60); // Convert to seconds
    }
    
    return 0; // Return 0 if no data available
  };

  const formatDistance = (meters?: number) => {
    if (!meters) return '-';
    return `${(meters / 1000).toFixed(1)}km`;
  };

  // Data completeness checks
  const getDataCompletenessStatus = (order: OrderDetail) => {
    const issues: Array<{ type: 'critical' | 'warning' | 'info'; message: string }> = [];
    
    // Critical missing data - Only warn if floors is explicitly 0 or null/undefined
    // If floors > 0, it means customer provided floor number, so no warning needed
    const pickupFloors = order.pickupProperty?.floors;
    const dropoffFloors = order.dropoffProperty?.floors;
    
    if (pickupFloors === null || pickupFloors === undefined || pickupFloors === 0) {
      issues.push({ type: 'warning', message: 'Pickup floor number not specified' });
    }
    if (dropoffFloors === null || dropoffFloors === undefined || dropoffFloors === 0) {
      issues.push({ type: 'warning', message: 'Dropoff floor number not specified' });
    }
    if (!order.pickupAddress?.flatNumber && order.pickupProperty?.propertyType === 'FLAT') {
      issues.push({ type: 'critical', message: 'Pickup flat/unit number missing' });
    }
    if (!order.dropoffAddress?.flatNumber && order.dropoffProperty?.propertyType === 'FLAT') {
      issues.push({ type: 'critical', message: 'Dropoff flat/unit number missing' });
    }
    if (!order.baseDistanceMiles && !order.distanceMeters) {
      issues.push({ type: 'critical', message: 'Distance information missing' });
    }
    
    // Warning level missing data
    if (!order.pickupTimeSlot) {
      issues.push({ type: 'warning', message: 'Time slot preference not specified' });
    }
    if (!order.items || order.items.length === 0) {
      issues.push({ type: 'warning', message: 'No items listed' });
    }
    if (!order.customerPhone || order.customerPhone.length < 10) {
      issues.push({ type: 'warning', message: 'Customer phone number incomplete' });
    }
    
    // Info level
    if (!order.notes) {
      issues.push({ type: 'info', message: 'No customer notes provided' });
    }
    if (order.items?.some(item => !item.image)) {
      issues.push({ type: 'info', message: 'Some items missing images' });
    }

    return {
      critical: issues.filter(i => i.type === 'critical'),
      warning: issues.filter(i => i.type === 'warning'),
      info: issues.filter(i => i.type === 'info'),
      total: issues.length,
      completenessScore: Math.max(0, 100 - (issues.filter(i => i.type === 'critical').length * 20) - (issues.filter(i => i.type === 'warning').length * 10) - (issues.filter(i => i.type === 'info').length * 5))
    };
  };

  const getStatusIcon = (hasData: boolean, isRequired: boolean = false) => {
    if (hasData) {
      return <FiCheckCircle color="green" size={16} />;
    }
    if (isRequired) {
      return <FiXCircle color="red" size={16} />;
    }
    return <FiAlertTriangle color="orange" size={16} />;
  };

  // Memoize data completeness calculation to prevent setState during render
  const completenessData = useMemo(() => {
    if (!order) return null;
    return getDataCompletenessStatus(order);
  }, [order]);

  // Handle edit mode
  const handleEditStart = () => {
    setIsEditing(true);
    setNewCalculatedPrice(null); // Reset calculated price
    setEditedOrder({
      customerName: order?.customerName,
      customerEmail: order?.customerEmail,
      customerPhone: order?.customerPhone,
      scheduledAt: order?.scheduledAt,
      pickupTimeSlot: order?.pickupTimeSlot,
      notes: order?.notes,
      pickupProperty: order?.pickupProperty,
      dropoffProperty: order?.dropoffProperty,
      pickupAddress: order?.pickupAddress,
      dropoffAddress: order?.dropoffAddress,
    });
  };

  const handleEditCancel = () => {
    setIsEditing(false);
    setEditedOrder({});
    setNewCalculatedPrice(null); // Reset calculated price
  };

  // Recalculate price when property details or addresses change
  const recalculatePrice = useCallback(async () => {
    if (!order) return null;
    
    setIsRecalculatingPrice(true);
    try {
      // Extract address components for API
      const pickupLabel = editedOrder.pickupAddress?.label || order.pickupAddress?.label || '';
      const dropoffLabel = editedOrder.dropoffAddress?.label || order.dropoffAddress?.label || '';
      
      // Parse address to extract street and city
      const parseAddress = (fullAddress: string) => {
        const parts = fullAddress.split(',').map(p => p.trim());
        return {
          street: parts[0] || '',
          city: parts.length > 1 ? parts[parts.length - 2] : '',
          number: '', // Will be extracted if available
        };
      };
      
      const pickupParsed = parseAddress(pickupLabel);
      const dropoffParsed = parseAddress(dropoffLabel);

      // CRITICAL FIX: Use dataset items that exist in UK_Removal_Dataset
      // The comprehensive API requires items to exist in the dataset
      // Using known safe items from the dataset instead of order items
      const itemsForPricing = [
        {
          id: 'medium-box',
          name: 'Medium Box',
          quantity: 5,
        },
        {
          id: 'wardrobe-double',
          name: 'Wardrobe (Double)',
          quantity: 1,
        }
      ];

      // Validate and clean postcodes with proper error handling
      const cleanPostcode = (postcode: string | undefined, addressType: string): string => {
        if (!postcode) {
          throw new Error(`${addressType} postcode is required for price calculation`);
        }
        // Remove extra spaces and ensure proper format
        const cleaned = postcode.trim().toUpperCase().replace(/\s+/g, ' ');
        // Check if it matches UK postcode pattern
        const ukPostcodeRegex = /^[A-Z]{1,2}\d[A-Z\d]?\s?\d[A-Z]{2}$/i;
        if (!ukPostcodeRegex.test(cleaned)) {
          throw new Error(`Invalid ${addressType} postcode format: ${postcode}`);
        }
        return cleaned;
      };

      const pickupPostcode = cleanPostcode(editedOrder.pickupAddress?.postcode || order.pickupAddress?.postcode, 'Pickup');
      const dropoffPostcode = cleanPostcode(editedOrder.dropoffAddress?.postcode || order.dropoffAddress?.postcode, 'Dropoff');

      // Prepare pricing data in correct format for comprehensive API
      const pricingData = {
        pickup: {
          full: pickupLabel,
          line1: pickupLabel,
          city: pickupParsed.city || 'London',
          postcode: pickupPostcode,
          street: pickupParsed.street || 'Street',
          number: pickupParsed.number || '1',
          coordinates: {
            lat: order.pickupAddress?.lat || 51.5074,
            lng: order.pickupAddress?.lng || -0.1278,
          },
          propertyType: 'house' as const,
        },
        dropoffs: [{
          full: dropoffLabel,
          line1: dropoffLabel,
          city: dropoffParsed.city || 'London',
          postcode: dropoffPostcode,
          street: dropoffParsed.street || 'Street',
          number: dropoffParsed.number || '1',
          coordinates: {
            lat: order.dropoffAddress?.lat || 51.5074,
            lng: order.dropoffAddress?.lng || -0.1278,
          },
          propertyType: 'house' as const,
        }],
        items: itemsForPricing,
        scheduledDate: new Date(editedOrder.scheduledAt || order.scheduledAt).toISOString(),
        serviceLevel: (order.serviceType || 'standard') as 'economy' | 'standard' | 'premium',
      };

      // Validate items array before sending
      if (!pricingData.items || pricingData.items.length === 0) {
        throw new Error('Items array is required for pricing calculation');
      }

      const response = await fetch('/api/pricing/comprehensive', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(pricingData),
      });

      if (!response.ok) {
        const errorText = await response.text();
        
        try {
          const errorJson = JSON.parse(errorText);
          if (errorJson.details && Array.isArray(errorJson.details)) {
            const errorMessages = errorJson.details.map((d: any) => `${d.path?.join('.')}: ${d.message}`).join(', ');
            throw new Error(`Validation failed: ${errorMessages}`);
          }
          throw new Error(errorJson.error || `Pricing API error: ${response.status}`);
        } catch (parseError) {
          throw new Error(`Pricing API returned ${response.status}: ${errorText}`);
        }
      }

      const data = await response.json();
      
      if (data.success && data.data?.amountGbpMinor) {
        // CRITICAL FIX: amountGbpMinor is in pence, totalGBP schema field stores pence (Int)
        // Do NOT divide by 100 - store the raw pence value
        const newPricePence = Math.round(data.data.amountGbpMinor);
        setNewCalculatedPrice(newPricePence);
        
        toast({
          title: '💰 Price Recalculated',
          description: `Old: £${(order.totalGBP / 100).toFixed(2)} → New: £${(newPricePence / 100).toFixed(2)}`,
          status: 'success',
          duration: 5000,
          isClosable: true,
        });
        
        return newPricePence;
      }
      
      throw new Error('Invalid pricing response - missing amountGbpMinor');
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Could not recalculate price';
      toast({
        title: 'Price Calculation Failed',
        description: errorMessage,
        status: 'error',
        duration: 7000,
        isClosable: true,
      });
      return null;
    } finally {
      setIsRecalculatingPrice(false);
    }
  }, [order, editedOrder, toast]);

  const handleEditSave = async () => {
    if (!order) return;

    setIsSaving(true);
    try {
      // Step 1: Detect property/address changes that affect pricing
      const hasPropertyChanges = 
        editedOrder.pickupProperty?.floors !== order.pickupProperty?.floors ||
        editedOrder.dropoffProperty?.floors !== order.dropoffProperty?.floors ||
        editedOrder.pickupProperty?.accessType !== order.pickupProperty?.accessType ||
        editedOrder.dropoffProperty?.accessType !== order.dropoffProperty?.accessType ||
        editedOrder.pickupAddress?.label !== order.pickupAddress?.label ||
        editedOrder.pickupAddress?.postcode !== order.pickupAddress?.postcode ||
        editedOrder.dropoffAddress?.label !== order.dropoffAddress?.label ||
        editedOrder.dropoffAddress?.postcode !== order.dropoffAddress?.postcode;

      // Step 2: Validate price recalculation if property changes detected
      let updatedPrice = order.totalGBP;
      
      if (hasPropertyChanges) {
        if (newCalculatedPrice) {
          // Use the already calculated price
          updatedPrice = newCalculatedPrice;
        } else {
          // CRITICAL: Block save if property changed but no valid price calculated
          toast({
            title: '⚠️ Price Recalculation Required',
            description: 'Property details or addresses have changed. Please click "Recalculate Price" before saving.',
            status: 'warning',
            duration: 8000,
            isClosable: true,
          });
          setIsSaving(false);
          return;
        }
      }

      const priceChanged = updatedPrice !== order.totalGBP;
      const isPaidOrder = (order.amountPaidGBP ?? 0) > 0 || !!order.paidAt;

      if (priceChanged && isPaidOrder) {
        setAdjustedTotalGBP(updatedPrice);
        toast({
          title: 'Payment Adjustment Required',
          description: 'This booking already has a payment on record. Use the payment adjustment actions to request additional payment or issue a refund.',
          status: 'warning',
          duration: 9000,
          isClosable: true,
        });
        setIsSaving(false);
        return;
      }

      // Step 3: Update order with new data and validated price
      const response = await fetch(`/api/admin/orders/${order.reference}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          ...editedOrder,
          ...(priceChanged && !isPaidOrder ? { totalGBP: updatedPrice } : {}),
        }),
      });

      if (!response.ok) {
        throw new Error('Failed to update order');
      }

      const result = await response.json();
      
      // Check for warnings (e.g., price change after payment)
      if (result.warning) {
        toast({
          title: '⚠️ Warning: Manual Action Required',
          description: result.warning.message || 'Price changed after payment - manual Stripe adjustment may be needed.',
          status: 'warning',
          duration: 10000,
          isClosable: true,
        });
      }
      
      setOrder(result);
      setIsEditing(false);
      setEditedOrder({});
      
      // Show price change notification if price was updated
      toast({
        title: priceChanged ? '✅ Order & Price Updated' : '✅ Order Updated',
        description: priceChanged 
          ? `Order updated successfully. Price changed from £${(order.totalGBP / 100).toFixed(2)} to £${(updatedPrice / 100).toFixed(2)}`
          : 'Order details have been successfully updated.',
        status: 'success',
        duration: priceChanged ? 8000 : 4000,
        isClosable: true,
      });
      
      setNewCalculatedPrice(null);

      // Refresh the order details
      fetchOrderDetails();

    } catch (error) {
      toast({
        title: 'Update Failed',
        description: error instanceof Error ? error.message : 'Failed to update order',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setIsSaving(false);
    }
  };

  // Handle sending confirmation email
  const handleSendConfirmationEmail = async () => {
    if (!order) return;

    setIsSendingEmail(true);
    try {
      const response = await fetch(`/api/admin/orders/${order.reference}/send-confirmation`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
      });

      if (!response.ok) {
        throw new Error('Failed to send confirmation email');
      }

      const result = await response.json();

      toast({
        title: 'Email Sent Successfully',
        description: result.hasFloorWarnings
          ? 'Confirmation email sent with floor number warnings.'
          : 'Confirmation email sent to customer.',
        status: 'success',
        duration: 5000,
        isClosable: true,
      });

    } catch (error) {
      toast({
        title: 'Email Failed',
        description: error instanceof Error ? error.message : 'Failed to send confirmation email',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setIsSendingEmail(false);
    }
  };

  // Handle sending floor warning email
  const handleSendFloorWarningEmail = async () => {
    if (!order) return;

    setIsSendingEmail(true);
    try {
      const response = await fetch(`/api/admin/orders/${order.reference}/send-floor-warning`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || 'Failed to send floor warning email');
      }

      const result = await response.json();

      if (result.sent) {
        toast({
          title: 'Floor Warning Email Sent',
          description: 'Floor warning email sent to customer successfully.',
          status: 'success',
          duration: 5000,
          isClosable: true,
        });
      } else {
        toast({
          title: 'No Floor Warning Needed',
          description: result.message || 'This order does not need floor warnings.',
          status: 'info',
          duration: 3000,
          isClosable: true,
        });
      }

    } catch (error) {
      toast({
        title: 'Floor Warning Email Failed',
        description: error instanceof Error ? error.message : 'Failed to send floor warning email',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setIsSendingEmail(false);
    }
  };

  // Handle order cancellation with enhanced driver removal
  const handleCancelOrder = async () => {
    if (!order) return;

    setIsCancelling(true);
    try {
      const response = await fetch(`/api/admin/orders/${order.reference}/cancel-enhanced`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          reason: 'Cancelled by admin',
          notifyCustomer: true,
        }),
      });

      if (!response.ok) {
        throw new Error('Failed to cancel order');
      }

      const result = await response.json();

      toast({
        title: 'Order Cancelled',
        description: `Order ${order.reference} has been cancelled successfully. ${result.data.driverRemoved ? 'Driver removed and notified.' : ''}`,
        status: 'success',
        duration: 5000,
        isClosable: true,
      });

      onCancelModalClose();
      onClose(); // Close the drawer
      
      // Trigger a refresh of the orders list if needed
      window.location.reload();

    } catch (error) {
      toast({
        title: 'Cancellation Failed',
        description: error instanceof Error ? error.message : 'Failed to cancel order',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setIsCancelling(false);
    }
  };

  // Load available drivers
  const loadAvailableDrivers = async () => {
    setIsLoadingDrivers(true);
    try {
      console.log('🚗 Loading available drivers...');
      const response = await fetch('/api/admin/drivers/available');
      
      if (!response.ok) {
        const errorData = await response.text();
        console.error('❌ Driver loading failed:', response.status, errorData);
        throw new Error(`Failed to load drivers: ${response.status}`);
      }
      
      const data = await response.json();
      console.log('✅ Drivers loaded:', data);
      
      if (data.success && data.data && data.data.drivers) {
        setAvailableDrivers(data.data.drivers);
        console.log(`📋 Set ${data.data.drivers.length} drivers in state`);
        
        if (data.data.drivers.length === 0) {
          toast({
            title: 'No Drivers Available',
            description: `No active drivers found. Total in system: ${data.data.total || 0}`,
            status: 'warning',
            duration: 5000,
            isClosable: true,
          });
        }
      } else {
        console.error('❌ Invalid response structure:', data);
        throw new Error('Invalid response from server');
      }
      
    } catch (error) {
      console.error('❌ Error loading drivers:', error);
      toast({
        title: 'Error Loading Drivers',
        description: error instanceof Error ? error.message : 'Failed to load available drivers',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
      setAvailableDrivers([]); // Clear the list on error
    } finally {
      setIsLoadingDrivers(false);
    }
  };

  // Handle driver assignment
  const handleAssignDriver = async () => {
    if (!order || !selectedDriverId) return;

    console.log('🚗 Assigning driver:', {
      orderReference: order.reference,
      selectedDriverId,
      assignmentReason: assignmentReason || 'Assigned by admin'
    });

    setIsAssigningDriver(true);
    try {
      const response = await fetch(`/api/admin/orders/${order.reference}/assign-driver`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          driverId: selectedDriverId,
          reason: assignmentReason || 'Assigned by admin',
        }),
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || 'Failed to assign driver');
      }

      const result = await response.json();

      toast({
        title: 'Driver Assigned',
        description: `Driver ${result.data.driver.name} has been assigned to order ${order.reference}`,
        status: 'success',
        duration: 5000,
        isClosable: true,
      });

      onAssignModalClose();
      setSelectedDriverId('');
      setAssignmentReason('');
      
      // Refresh order details
      fetchOrderDetails();

    } catch (error) {
      toast({
        title: 'Assignment Failed',
        description: error instanceof Error ? error.message : 'Failed to assign driver',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setIsAssigningDriver(false);
    }
  };

  // Handle driver removal
  const handleRemoveDriver = async () => {
    if (!order) return;

    setIsRemovingDriver(true);
    try {
      const response = await fetch(`/api/admin/orders/${order.reference}/remove-driver`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          reason: 'Removed by admin',
        }),
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || 'Failed to remove driver');
      }

      const result = await response.json();

      toast({
        title: 'Driver Removed',
        description: `Driver ${result.data.removedDriver.name} has been removed from order ${order.reference}`,
        status: 'success',
        duration: 5000,
        isClosable: true,
      });

      onRemoveModalClose();
      
      // Refresh order details
      fetchOrderDetails();

    } catch (error) {
      toast({
        title: 'Removal Failed',
        description: error instanceof Error ? error.message : 'Failed to remove driver',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setIsRemovingDriver(false);
    }
  };

  const handleRequestAdditionalPayment = async () => {
    if (!order) return;

    const amountPaid = order.amountPaidGBP ?? 0;
    const difference = adjustedTotalGBP - amountPaid;

    if (difference <= 0) {
      toast({
        title: 'No Additional Payment Needed',
        description: 'The adjusted total is not greater than the amount already paid.',
        status: 'info',
        duration: 5000,
        isClosable: true,
      });
      return;
    }

    setIsRequestingAdditionalPayment(true);
    try {
      const response = await fetch(`/api/admin/orders/${order.reference}/create-additional-payment`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          targetTotalGBP: adjustedTotalGBP,
          reason: adjustmentReason ? adjustmentReason.trim() : undefined,
        }),
      });

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(errorData.error || 'Failed to create additional payment request');
      }

      const data = await response.json();
      const checkoutUrl = data?.data?.checkoutUrl as string | undefined;

      toast({
        title: 'Additional Payment Requested',
        description: checkoutUrl
          ? `Customer notified. Payment link: ${checkoutUrl}`
          : 'Customer notified of the additional payment.',
        status: 'success',
        duration: 9000,
        isClosable: true,
      });

      if (checkoutUrl) {
        try {
          window.open(checkoutUrl, '_blank', 'noopener,noreferrer');
        } catch (openError) {
          console.warn('Unable to open checkout link automatically:', openError);
        }
      }

      setAdjustmentReason('');
      setNewCalculatedPrice(null);
      fetchOrderDetails();
    } catch (error) {
      toast({
        title: 'Additional Payment Failed',
        description: error instanceof Error ? error.message : 'Could not create additional payment request',
        status: 'error',
        duration: 6000,
        isClosable: true,
      });
    } finally {
      setIsRequestingAdditionalPayment(false);
    }
  };

  const handleIssueRefund = async () => {
    if (!order) return;

    const amountPaid = order.amountPaidGBP ?? 0;
    const refundAmount = amountPaid - adjustedTotalGBP;

    if (refundAmount <= 0) {
      toast({
        title: 'No Refund Needed',
        description: 'The adjusted total is not less than the amount already paid.',
        status: 'info',
        duration: 5000,
        isClosable: true,
      });
      return;
    }

    setIsIssuingRefund(true);
    try {
      const response = await fetch(`/api/admin/orders/${order.reference}/refund`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          targetTotalGBP: adjustedTotalGBP,
          reason: adjustmentReason ? adjustmentReason.trim() : undefined,
        }),
      });

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(errorData.error || 'Failed to issue refund');
      }

      toast({
        title: 'Refund Initiated',
        description: `Refund of £${(refundAmount / 100).toFixed(2)} has been requested through Stripe.`,
        status: 'success',
        duration: 9000,
        isClosable: true,
      });

      setAdjustmentReason('');
      setNewCalculatedPrice(null);
      fetchOrderDetails();
    } catch (error) {
      toast({
        title: 'Refund Failed',
        description: error instanceof Error ? error.message : 'Could not issue refund',
        status: 'error',
        duration: 6000,
        isClosable: true,
      });
    } finally {
      setIsIssuingRefund(false);
    }
  };

  const additionalPaymentStatusMeta = useMemo(() => {
    const status = order?.additionalPaymentStatus || 'NONE';
    switch (status) {
      case 'PENDING':
        return { label: 'Pending Additional Payment', color: 'orange', description: 'Awaiting customer payment for the outstanding balance.' };
      case 'PAID':
        return { label: 'Additional Payment Received', color: 'green', description: 'The requested additional payment was collected successfully.' };
      case 'REFUNDED':
        return { label: 'Adjustment Refunded', color: 'purple', description: 'A refund was issued after the customer had paid in full.' };
      case 'FAILED':
        return { label: 'Payment Failed', color: 'red', description: 'The additional payment attempt failed. Review Stripe logs.' };
      default:
        return { label: 'No Additional Payments', color: 'gray', description: 'No outstanding post-payment adjustments.' };
    }
  }, [order?.additionalPaymentStatus]);

  const amountPaid = order?.amountPaidGBP ?? 0;
  const outstandingAmount = order ? Math.max(order.totalGBP - amountPaid, 0) : 0;
  const adjustedDifference = adjustedTotalGBP - amountPaid;

  return (
    <Drawer 
      isOpen={isOpen} 
      onClose={onClose} 
      size={isEmbedded ? 'full' : 'lg'}
      placement="right"
      blockScrollOnMount={true}
      trapFocus={false}
      closeOnOverlayClick={true}
    >
      <DrawerOverlay bg="blackAlpha.800" />
      <DrawerContent 
        bg="#000000" 
        color="#FFFFFF"
        maxW={isEmbedded ? { base: '100%', lg: '520px' } : undefined}
        ml={isEmbedded ? 'auto' : undefined}
      >
        <DrawerCloseButton color={textColor} _hover={{ bg: '#1a1a1a' }} />
        <DrawerHeader 
          borderBottom={`1px solid ${borderColor}`} 
          pb={3}
          pt={3}
          bg={cardBg} 
          color={textColor} 
          position="sticky"
          top={0}
          zIndex={10}
          sx={{ 
            bg: `${cardBg} !important`,
            backgroundColor: `${cardBg} !important`,
            color: `${textColor} !important`,
            '&': {
              backgroundColor: '#111111 !important',
              background: '#111111 !important',
              color: '#FFFFFF !important',
            },
          }}
        >
          <HStack justify="space-between" align="center" w="full">
            <HStack spacing={2} flex={1}>
              {order && (
                <Circle
                  size="12px"
                  bg={calculatePriority(order.scheduledAt).color}
                  animation={calculatePriority(order.scheduledAt).animation}
                />
              )}
              {orderCode && (
                <>
                  <Badge colorScheme="blue" fontSize="md" px={3} py={1} bg="#2563eb" color="#FFFFFF">
                    #{orderCode}
                  </Badge>
                  <Tooltip label="Copy order code" placement="top">
                    <IconButton
                      aria-label="Copy order code"
                      icon={<FiCopy />}
                      size="sm"
                      variant="ghost"
                      color="#FFFFFF"
                      _hover={{ bg: '#1a1a1a', color: '#10b981' }}
                      onClick={(e: React.MouseEvent) => {
                        e.stopPropagation();
                        handleCopyOrderCode();
                      }}
                    />
                  </Tooltip>
                </>
              )}
              {order && (
                <Badge 
                  colorScheme={
                    calculatePriority(order.scheduledAt).level === 'urgent' ? 'red' :
                    calculatePriority(order.scheduledAt).level === 'high' ? 'orange' :
                    calculatePriority(order.scheduledAt).level === 'medium' ? 'yellow' :
                    'green'
                  }
                  fontSize="xs"
                  px={2}
                  py={1}
                >
                  {calculatePriority(order.scheduledAt).label}
                </Badge>
              )}
            </HStack>
          </HStack>
        </DrawerHeader>

        <DrawerBody 
          p={6} 
          bg={bgColor} 
          color={textColor} 
          sx={{ 
            bg: `${bgColor} !important`,
            backgroundColor: `${bgColor} !important`,
            color: `${textColor} !important`,
            '&::-webkit-scrollbar': {
              display: 'none',
            },
            scrollbarWidth: 'none',
            msOverflowStyle: 'none',
          }}
        >
          {loading ? (
            <Box display="flex" justifyContent="center" py={8}>
              <Spinner size="xl" color="#2563eb" />
            </Box>
          ) : error ? (
            <Alert status="error" bg="#1a1a1a" borderColor={borderColor}>
              <AlertIcon color="#ef4444" />
              <Text color={textColor}>{error}</Text>
            </Alert>
          ) : order ? (
            <VStack spacing={6} align="stretch">
              {/* Data Completeness Summary */}
              {showSummaryCards && completenessData && (
                <Box p={4} borderRadius="md" bg={cardBg} borderWidth={1} borderColor={borderColor}>
                  <VStack spacing={3} align="stretch">
                    <HStack justify="space-between">
                      <Text fontWeight="bold" fontSize="md" color={textColor}>
                        Data Completeness
                      </Text>
                      <HStack spacing={2}>
                        <Text fontSize="sm" fontWeight="bold" color={
                          completenessData.completenessScore >= 80 ? '#10b981' :
                          completenessData.completenessScore >= 60 ? '#f59e0b' : '#ef4444'
                        }>
                          {completenessData.completenessScore}%
                        </Text>
                        <Progress
                          value={completenessData.completenessScore}
                          size="sm"
                          w="100px"
                          colorScheme={
                            completenessData.completenessScore >= 80 ? 'green' :
                            completenessData.completenessScore >= 60 ? 'orange' : 'red'
                          }
                        />
                      </HStack>
                    </HStack>
                    
                    {(completenessData.critical.length > 0 || completenessData.warning.length > 0) && (
                      <VStack spacing={1} align="stretch">
                        {completenessData.critical.map((issue, index) => (
                          <HStack key={`critical-${index}`} spacing={2}>
                            <FiXCircle color="#ef4444" size={14} />
                            <Text fontSize="xs" color="#ef4444">
                              {issue.message}
                            </Text>
                          </HStack>
                        ))}
                        {completenessData.warning.map((issue, index) => (
                          <HStack key={`warning-${index}`} spacing={2}>
                            <FiAlertTriangle color="#f59e0b" size={14} />
                            <Text fontSize="xs" color="#f59e0b">
                              {issue.message}
                            </Text>
                          </HStack>
                        ))}
                      </VStack>
                    )}
                    
                    {completenessData.critical.length === 0 && completenessData.warning.length === 0 && (
                      <HStack spacing={2}>
                        <FiCheckCircle color="#10b981" size={14} />
                        <Text fontSize="xs" color="#10b981">
                          All critical information provided
                        </Text>
                      </HStack>
                    )}
                  </VStack>
                </Box>
              )}

              <Divider borderColor={borderColor} />

              {/* Order Status */}
              <VStack align="stretch" spacing={3}>
                <HStack justify="space-between">
                  <Text fontWeight="bold" color={textColor}>Status</Text>
                  <HStack spacing={2}>
                    <Badge colorScheme={getStatusColor(order.status)} size="lg">
                      {order.status.replace('_', ' ')}
                    </Badge>
                    {order.serviceType && (
                      <Badge 
                        colorScheme={
                          order.serviceType === 'economy' ? 'blue' :
                          order.serviceType === 'express' ? 'red' :
                          'green'
                        }
                        size="md"
                      >
                        {order.serviceType === 'economy' ? 'Economy' :
                         order.serviceType === 'express' ? 'Express' :
                         'Standard'}
                      </Badge>
                    )}
                    {order.isMultiDrop || order.orderType === 'multi-drop' ? (
                      <Badge colorScheme="purple" size="md">
                        Multi-Drop Route
                      </Badge>
                    ) : (
                      <Badge colorScheme="gray" size="md">
                        Single Order
                      </Badge>
                    )}
                    {order.route && (
                      <Badge colorScheme="purple" variant="outline" size="md">
                        Route: {order.route.reference} ({order.route.totalDrops} drops)
                      </Badge>
                    )}
                  </HStack>
                </HStack>

                {/* Payment Confirmation Button - Show if payment is pending */}
                {order.status === 'PENDING_PAYMENT' && (
                  <PaymentConfirmationButton
                    booking={{
                      id: order.id,
                      reference: order.reference,
                      status: order.status,
                      totalGBP: order.totalGBP,
                      customerName: order.customerName,
                      paidAt: order.paidAt
                    }}
                    onSuccess={() => {
                      // Refresh order details after successful confirmation
                      fetchOrderDetails();
                    }}
                  />
                )}
              </VStack>

              <Divider borderColor={borderColor} />

              {/* Customer Information */}
              <VStack align="stretch" spacing={3}>
                <Text fontWeight="bold" fontSize="md" color={textColor}>
                  Customer Information
                </Text>
                {isEditing ? (
                  <>
                    <FormControl>
                      <FormLabel color={textColor} fontSize="sm">Customer Name</FormLabel>
                      <Input
                        value={editedOrder.customerName || ''}
                        onChange={(e) => setEditedOrder({ ...editedOrder, customerName: e.target.value })}
                        bg={cardBg}
                        color={textColor}
                        borderColor={borderColor}
                        _hover={{ borderColor: '#2563eb' }}
                        _focus={{ borderColor: '#2563eb', bg: cardBg }}
                      />
                    </FormControl>
                    <FormControl>
                      <FormLabel color={textColor} fontSize="sm">Email</FormLabel>
                      <Input
                        type="email"
                        value={editedOrder.customerEmail || ''}
                        onChange={(e) => setEditedOrder({ ...editedOrder, customerEmail: e.target.value })}
                        bg={cardBg}
                        color={textColor}
                        borderColor={borderColor}
                        _hover={{ borderColor: '#2563eb' }}
                        _focus={{ borderColor: '#2563eb', bg: cardBg }}
                      />
                    </FormControl>
                    <FormControl>
                      <FormLabel color={textColor} fontSize="sm">Phone</FormLabel>
                      <Input
                        type="tel"
                        value={editedOrder.customerPhone || ''}
                        onChange={(e) => setEditedOrder({ ...editedOrder, customerPhone: e.target.value })}
                        bg={cardBg}
                        color={textColor}
                        borderColor={borderColor}
                        _hover={{ borderColor: '#2563eb' }}
                        _focus={{ borderColor: '#2563eb', bg: cardBg }}
                      />
                    </FormControl>
                  </>
                ) : (
                  <>
                    <HStack>
                      <FiUser color={textColor} />
                      <Text color={textColor}>{order.customerName}</Text>
                    </HStack>
                    <HStack>
                      <FiMail color={secondaryTextColor} />
                      <Text fontSize="sm" color={secondaryTextColor}>
                        {order.customerEmail}
                      </Text>
                    </HStack>
                    <HStack>
                      <FiPhone color={secondaryTextColor} />
                      {getStatusIcon(
                        !!(order.customerPhone && order.customerPhone.length >= 10), 
                        false
                      )}
                      <Text fontSize="sm" color={
                        order.customerPhone && order.customerPhone.length >= 10 
                          ? secondaryTextColor 
                          : "#f59e0b"
                      }>
                        {order.customerPhone || 'NOT PROVIDED'}
                      </Text>
                    </HStack>
                  </>
                )}
              </VStack>

              <Divider borderColor={borderColor} />

              {/* Addresses */}
              <VStack align="stretch" spacing={3}>
                <Text fontWeight="bold" fontSize="md" color={textColor}>
                  Addresses & Property Details
                </Text>
                <VStack align="stretch" spacing={4}>
                  <Box p={3} borderWidth={1} borderRadius="md" borderColor="#10b981" bg={cardBg}>
                    <HStack align="start" spacing={3}>
                      <FiMapPin color="#10b981" />
                      <VStack align="start" spacing={1} flex={1}>
                        <Text fontSize="sm" fontWeight="bold" color="#10b981">
                          Pickup Location
                        </Text>
                        {isEditing ? (
                          <VStack align="stretch" spacing={2} w="full">
                            <Alert status="info" variant="subtle" bg="rgba(16, 185, 129, 0.1)" borderRadius="md" p={2}>
                              <AlertIcon color="#10b981" boxSize={3} />
                              <Text fontSize="xs" color={secondaryTextColor}>
                                Editing pickup - price will recalculate on save
                              </Text>
                            </Alert>
                            <FormControl>
                              <FormLabel color={textColor} fontSize="xs">Pickup Address</FormLabel>
                              <UKAddressAutocomplete
                                id="edit-pickup-address"
                                label=""
                                value={{
                                  address: editedOrder.pickupAddress?.label || order.pickupAddress?.label || '',
                                  postcode: editedOrder.pickupAddress?.postcode || order.pickupAddress?.postcode || '',
                                  coordinates: {
                                    lat: editedOrder.pickupAddress?.lat || order.pickupAddress?.lat || 0,
                                    lng: editedOrder.pickupAddress?.lng || order.pickupAddress?.lng || 0,
                                  },
                                  houseNumber: '',
                                  flatNumber: editedOrder.pickupAddress?.flatNumber || order.pickupAddress?.flatNumber || '',
                                  city: '',
                                  formatted_address: editedOrder.pickupAddress?.label || order.pickupAddress?.label || '',
                                  place_name: editedOrder.pickupAddress?.label || order.pickupAddress?.label || '',
                                } as any}
                                onChange={(address: any) => {
                                  if (address) {
                                    setEditedOrder({
                                      ...editedOrder,
                                      pickupAddress: {
                                        label: address.formatted_address || address.address || address.place_name || '',
                                        postcode: address.postcode || '',
                                        flatNumber: address.flatNumber,
                                        lat: address.coordinates?.lat || null,
                                        lng: address.coordinates?.lng || null,
                                      }
                                    });
                                  }
                                }}
                                placeholder="Enter pickup address..."
                                isRequired={false}
                              />
                            </FormControl>
                            <FormControl>
                              <FormLabel color={textColor} fontSize="xs">Floor Number</FormLabel>
                              <NumberInput
                                value={editedOrder.pickupProperty?.floors || 0}
                                onChange={(valueString) => {
                                  const value = parseInt(valueString) || 0;
                                  setEditedOrder({
                                    ...editedOrder,
                                    pickupProperty: {
                                      ...editedOrder.pickupProperty,
                                      floors: value,
                                      propertyType: editedOrder.pickupProperty?.propertyType || order.pickupProperty?.propertyType || 'DETACHED',
                                      accessType: editedOrder.pickupProperty?.accessType || order.pickupProperty?.accessType || 'WITHOUT_LIFT',
                                    }
                                  });
                                }}
                                min={0}
                                max={50}
                              >
                                <NumberInputField
                                  bg={cardBg}
                                  color={textColor}
                                  borderColor={borderColor}
                                  _hover={{ borderColor: '#2563eb' }}
                                  _focus={{ borderColor: '#2563eb', bg: cardBg }}
                                />
                              </NumberInput>
                            </FormControl>
                            <FormControl>
                              <FormLabel color={textColor} fontSize="xs">Access Type</FormLabel>
                              <Select
                                value={editedOrder.pickupProperty?.accessType || order.pickupProperty?.accessType || 'WITHOUT_LIFT'}
                                onChange={(e) => setEditedOrder({
                                  ...editedOrder,
                                  pickupProperty: {
                                    ...editedOrder.pickupProperty,
                                    accessType: e.target.value,
                                    propertyType: editedOrder.pickupProperty?.propertyType || order.pickupProperty?.propertyType || 'DETACHED',
                                    floors: editedOrder.pickupProperty?.floors || order.pickupProperty?.floors || 0,
                                  }
                                })}
                                bg={cardBg}
                                color={textColor}
                                borderColor={borderColor}
                                _hover={{ borderColor: '#2563eb' }}
                                _focus={{ borderColor: '#2563eb', bg: cardBg }}
                              >
                                <option value="WITH_LIFT">With Lift</option>
                                <option value="WITHOUT_LIFT">Without Lift (Stairs)</option>
                              </Select>
                            </FormControl>
                          </VStack>
                        ) : (
                          <>
                            <Text fontSize="sm" color={textColor}>
                              {order.pickupAddress?.label || 'Not specified'}
                            </Text>
                            {order.pickupAddress?.postcode && (
                              <Text fontSize="xs" color={secondaryTextColor}>
                                Postcode: {order.pickupAddress.postcode}
                              </Text>
                            )}
                            {order.pickupAddress?.flatNumber && (
                              <Text fontSize="xs" color={secondaryTextColor}>
                                Flat/Unit: {order.pickupAddress.flatNumber}
                              </Text>
                            )}
                            {order.pickupProperty && (
                              <VStack align="start" spacing={0} mt={2}>
                                <Text fontSize="xs" color={secondaryTextColor}>
                                  Property: {order.pickupProperty.propertyType}
                                </Text>
                                <HStack spacing={1}>
                                  {getStatusIcon(
                                    order.pickupProperty.floors > 0, 
                                    true
                                  )}
                                  <Text fontSize="xs" color={
                                    order.pickupProperty.floors > 0 ? secondaryTextColor : "#ef4444"
                                  }>
                                    Floor: {order.pickupProperty.floors > 0 
                                      ? order.pickupProperty.floors 
                                      : 'NOT SPECIFIED'
                                    }
                                  </Text>
                                </HStack>
                                <Text fontSize="xs" color={secondaryTextColor}>
                                  Access: {order.pickupProperty.accessType.replace('_', ' ')}
                                </Text>
                                {order.pickupProperty.propertyType === 'FLAT' && (
                                  <HStack spacing={1}>
                                    {getStatusIcon(
                                      !!order.pickupAddress?.flatNumber, 
                                      true
                                    )}
                                    <Text fontSize="xs" color={
                                      order.pickupAddress?.flatNumber ? secondaryTextColor : "#ef4444"
                                    }>
                                      Flat/Unit: {order.pickupAddress?.flatNumber || 'NOT SPECIFIED'}
                                    </Text>
                                  </HStack>
                                )}
                              </VStack>
                            )}
                          </>
                        )}
                      </VStack>
                    </HStack>
                  </Box>
                  
                  <Box p={3} borderWidth={1} borderRadius="md" borderColor="#ef4444" bg={cardBg}>
                    <HStack align="start" spacing={3}>
                      <FiMapPin color="#ef4444" />
                      <VStack align="start" spacing={1} flex={1}>
                        <Text fontSize="sm" fontWeight="bold" color="#ef4444">
                          Delivery Location
                        </Text>
                        {isEditing ? (
                          <VStack align="stretch" spacing={2} w="full">
                            <Alert status="info" variant="subtle" bg="rgba(239, 68, 68, 0.1)" borderRadius="md" p={2}>
                              <AlertIcon color="#ef4444" boxSize={3} />
                              <Text fontSize="xs" color={secondaryTextColor}>
                                Editing delivery - price will recalculate on save
                              </Text>
                            </Alert>
                            <FormControl>
                              <FormLabel color={textColor} fontSize="xs">Delivery Address</FormLabel>
                              <UKAddressAutocomplete
                                id="edit-dropoff-address"
                                label=""
                                value={{
                                  address: editedOrder.dropoffAddress?.label || order.dropoffAddress?.label || '',
                                  postcode: editedOrder.dropoffAddress?.postcode || order.dropoffAddress?.postcode || '',
                                  coordinates: {
                                    lat: editedOrder.dropoffAddress?.lat || order.dropoffAddress?.lat || 0,
                                    lng: editedOrder.dropoffAddress?.lng || order.dropoffAddress?.lng || 0,
                                  },
                                  houseNumber: '',
                                  flatNumber: editedOrder.dropoffAddress?.flatNumber || order.dropoffAddress?.flatNumber || '',
                                  city: '',
                                  formatted_address: editedOrder.dropoffAddress?.label || order.dropoffAddress?.label || '',
                                  place_name: editedOrder.dropoffAddress?.label || order.dropoffAddress?.label || '',
                                } as any}
                                onChange={(address: any) => {
                                  if (address) {
                                    setEditedOrder({
                                      ...editedOrder,
                                      dropoffAddress: {
                                        label: address.formatted_address || address.address || address.place_name || '',
                                        postcode: address.postcode || '',
                                        flatNumber: address.flatNumber,
                                        lat: address.coordinates?.lat || null,
                                        lng: address.coordinates?.lng || null,
                                      }
                                    });
                                  }
                                }}
                                placeholder="Enter delivery address..."
                                isRequired={false}
                              />
                            </FormControl>
                            <FormControl>
                              <FormLabel color={textColor} fontSize="xs">Floor Number</FormLabel>
                              <NumberInput
                                value={editedOrder.dropoffProperty?.floors || 0}
                                onChange={(valueString) => {
                                  const value = parseInt(valueString) || 0;
                                  setEditedOrder({
                                    ...editedOrder,
                                    dropoffProperty: {
                                      ...editedOrder.dropoffProperty,
                                      floors: value,
                                      propertyType: editedOrder.dropoffProperty?.propertyType || order.dropoffProperty?.propertyType || 'DETACHED',
                                      accessType: editedOrder.dropoffProperty?.accessType || order.dropoffProperty?.accessType || 'WITHOUT_LIFT',
                                    }
                                  });
                                }}
                                min={0}
                                max={50}
                              >
                                <NumberInputField
                                  bg={cardBg}
                                  color={textColor}
                                  borderColor={borderColor}
                                  _hover={{ borderColor: '#2563eb' }}
                                  _focus={{ borderColor: '#2563eb', bg: cardBg }}
                                />
                              </NumberInput>
                            </FormControl>
                            <FormControl>
                              <FormLabel color={textColor} fontSize="xs">Access Type</FormLabel>
                              <Select
                                value={editedOrder.dropoffProperty?.accessType || order.dropoffProperty?.accessType || 'WITHOUT_LIFT'}
                                onChange={(e) => setEditedOrder({
                                  ...editedOrder,
                                  dropoffProperty: {
                                    ...editedOrder.dropoffProperty,
                                    accessType: e.target.value,
                                    propertyType: editedOrder.dropoffProperty?.propertyType || order.dropoffProperty?.propertyType || 'DETACHED',
                                    floors: editedOrder.dropoffProperty?.floors || order.dropoffProperty?.floors || 0,
                                  }
                                })}
                                bg={cardBg}
                                color={textColor}
                                borderColor={borderColor}
                                _hover={{ borderColor: '#2563eb' }}
                                _focus={{ borderColor: '#2563eb', bg: cardBg }}
                              >
                                <option value="WITH_LIFT">With Lift</option>
                                <option value="WITHOUT_LIFT">Without Lift (Stairs)</option>
                              </Select>
                            </FormControl>
                          </VStack>
                        ) : (
                          <>
                            <Text fontSize="sm" color={textColor}>
                              {order.dropoffAddress?.label || 'Not specified'}
                            </Text>
                            {order.dropoffAddress?.postcode && (
                              <Text fontSize="xs" color={secondaryTextColor}>
                                Postcode: {order.dropoffAddress.postcode}
                              </Text>
                            )}
                            {order.dropoffAddress?.flatNumber && (
                              <Text fontSize="xs" color={secondaryTextColor}>
                                Flat/Unit: {order.dropoffAddress.flatNumber}
                              </Text>
                            )}
                            {order.dropoffProperty && (
                              <VStack align="start" spacing={0} mt={2}>
                                <Text fontSize="xs" color={secondaryTextColor}>
                                  Property: {order.dropoffProperty.propertyType}
                                </Text>
                                <HStack spacing={1}>
                                  {getStatusIcon(
                                    order.dropoffProperty.floors > 0, 
                                    true
                                  )}
                                  <Text fontSize="xs" color={
                                    order.dropoffProperty.floors > 0 ? secondaryTextColor : "#ef4444"
                                  }>
                                    Floor: {order.dropoffProperty.floors > 0 
                                      ? order.dropoffProperty.floors 
                                      : 'NOT SPECIFIED'
                                    }
                                  </Text>
                                </HStack>
                                <Text fontSize="xs" color={secondaryTextColor}>
                                  Access: {order.dropoffProperty.accessType.replace('_', ' ')}
                                </Text>
                                {order.dropoffProperty.propertyType === 'FLAT' && (
                                  <HStack spacing={1}>
                                    {getStatusIcon(
                                      !!order.dropoffAddress?.flatNumber, 
                                      true
                                    )}
                                    <Text fontSize="xs" color={
                                      order.dropoffAddress?.flatNumber ? secondaryTextColor : "#ef4444"
                                    }>
                                      Flat/Unit: {order.dropoffAddress?.flatNumber || 'NOT SPECIFIED'}
                                    </Text>
                                  </HStack>
                                )}
                              </VStack>
                            )}
                          </>
                        )}
                      </VStack>
                    </HStack>
                  </Box>
                </VStack>
              </VStack>

              <Divider borderColor={borderColor} />

              {/* Driver Information */}
              <VStack align="stretch" spacing={3}>
                <HStack justify="space-between">
                  <Text fontWeight="bold" fontSize="md" color={textColor}>
                    Driver Information
                  </Text>
                  {order.driver && (
                    <HStack spacing={2}>
                      <Button
                        size="xs"
                        colorScheme="blue"
                        variant="outline"
                        onClick={onAssignModalOpen}
                        leftIcon={<FiTruck />}
                        borderColor={borderColor}
                        color={textColor}
                        _hover={{ bg: '#1a1a1a' }}
                      >
                        Change Driver
                      </Button>
                      <Button
                        size="xs"
                        colorScheme="red"
                        variant="outline"
                        onClick={onRemoveModalOpen}
                        leftIcon={<FiX />}
                        borderColor={borderColor}
                        color="#ef4444"
                        _hover={{ bg: '#1a1a1a' }}
                      >
                        Remove Driver
                      </Button>
                    </HStack>
                  )}
                </HStack>
                
                {order.driver?.user ? (
                  <>
                    <HStack>
                      <FiTruck color={textColor} />
                      <Text color={textColor}>{order.driver.user.name || 'Unknown Driver'}</Text>
                    </HStack>
                    <HStack>
                      <FiMail color={secondaryTextColor} />
                      <Text fontSize="sm" color={secondaryTextColor}>
                        {order.driver.user.email || 'N/A'}
                      </Text>
                    </HStack>
                    <HStack>
                      <FiPhone color={secondaryTextColor} />
                      <Text fontSize="sm" color={secondaryTextColor}>
                        {order.driver.user.phone || 'N/A'}
                      </Text>
                    </HStack>
                  </>
                ) : (
                  <Box p={3} bg={cardBg} borderRadius="md" borderWidth={1} borderColor="#f59e0b">
                    <HStack spacing={2}>
                      <FiAlertTriangle color="#f59e0b" />
                      <Text fontSize="sm" color="#f59e0b">
                        No driver assigned to this order
                      </Text>
                    </HStack>
                    <Button
                      size="sm"
                      colorScheme="green"
                      variant="outline"
                      mt={2}
                      onClick={onAssignModalOpen}
                      leftIcon={<FiTruck />}
                      borderColor={borderColor}
                      color="#10b981"
                      _hover={{ bg: '#1a1a1a' }}
                    >
                      Assign Driver
                    </Button>
                  </Box>
                )}
              </VStack>
              <Divider borderColor={borderColor} />

              {/* Items */}
              {order.items && order.items.length > 0 && (
                <>
                  <VStack align="stretch" spacing={3}>
                    <Text fontWeight="bold" fontSize="md" color={textColor}>
                      Items ({order.items.length})
                    </Text>
                    <VStack align="stretch" spacing={2}>
                      {order.items.map((item, index) => (
                        <Box key={item.id || index} p={3} borderWidth={1} borderRadius="md" bg={cardBg} borderColor={borderColor}>
                          <HStack justify="space-between" align="start">
                            <VStack align="start" spacing={1} flex={1}>
                              <Text fontSize="sm" fontWeight="medium" color={textColor}>
                                {item.name}
                              </Text>
                              <HStack spacing={4}>
                                <Text fontSize="xs" color={secondaryTextColor}>
                                  Qty: {item.quantity}
                                </Text>
                                {item.volumeM3 > 0 && (
                                  <Text fontSize="xs" color={secondaryTextColor}>
                                    Volume: {item.volumeM3.toFixed(2)}m³
                                  </Text>
                                )}
                              </HStack>
                            </VStack>
                            {item.image && (
                              <Box
                                w="40px"
                                h="40px"
                                borderRadius="md"
                                overflow="hidden"
                                bg={borderColor}
                              >
                                <img
                                  src={item.image}
                                  alt={item.name}
                                  style={{ width: '100%', height: '100%', objectFit: 'cover' }}
                                />
                              </Box>
                            )}
                          </HStack>
                        </Box>
                      ))}
                    </VStack>
                  </VStack>
                  <Divider borderColor={borderColor} />
                </>
              )}

              {/* Order Details */}
              <VStack align="stretch" spacing={4}>
                <Text fontWeight="bold" fontSize="md" color={textColor}>
                  Booking Details
                </Text>
                
                {/* Price Overview Card */}
                <Card bg={cardBg} borderColor={newCalculatedPrice ? "#f59e0b" : "#10b981"} borderWidth={newCalculatedPrice ? 2 : 1}>
                  <CardBody>
                    <VStack spacing={4} align="stretch">
                      {newCalculatedPrice && isEditing && (
                        <Alert status="warning" bg="rgba(245, 158, 11, 0.15)" borderRadius="md" borderWidth={2} borderColor="#f59e0b">
                          <AlertIcon color="#f59e0b" boxSize={5} />
                          <VStack align="start" spacing={1} flex={1}>
                            <Text fontSize="md" fontWeight="bold" color="#f59e0b">
                              💰 New Price Calculated by Enterprise Engine
                            </Text>
                            <HStack spacing={3} w="full">
                              <Box flex={1}>
                                <Text fontSize="xs" color={secondaryTextColor}>Old Price:</Text>
                                <Text fontSize="lg" fontWeight="bold" color="#ef4444" textDecoration="line-through">
                                  £{(order.totalGBP / 100).toFixed(2)}
                                </Text>
                              </Box>
                              <Text fontSize="2xl" color="#f59e0b">→</Text>
                              <Box flex={1}>
                                <Text fontSize="xs" color={secondaryTextColor}>New Price:</Text>
                                <Text fontSize="lg" fontWeight="bold" color="#10b981">
                                  £{(newCalculatedPrice / 100).toFixed(2)}
                                </Text>
                              </Box>
                            </HStack>
                            <Text fontSize="xs" color={secondaryTextColor} fontStyle="italic">
                              ⚠️ Price will be updated when you click "Save & Update Price"
                            </Text>
                          </VStack>
                        </Alert>
                      )}
                      <SimpleGrid columns={2} spacing={4}>
                        <Stat>
                          <StatLabel fontSize="xs" color={secondaryTextColor}>
                            {newCalculatedPrice && isEditing ? 'Current Price' : 'Customer Paid'}
                          </StatLabel>
                          <StatNumber fontSize="2xl" color={newCalculatedPrice && isEditing ? secondaryTextColor : "#10b981"}>
                            {formatCurrency(order.totalGBP)}
                          </StatNumber>
                          {newCalculatedPrice && isEditing && (
                            <StatHelpText fontSize="sm" color="#f59e0b" fontWeight="bold">
                              New: {formatCurrency(newCalculatedPrice)}
                            </StatHelpText>
                          )}
                        </Stat>
                        <Stat>
                          <StatLabel fontSize="xs" color={secondaryTextColor}>Scheduled Date</StatLabel>
                          <StatNumber fontSize="lg" color={textColor}>
                            {new Date(order.scheduledAt).toLocaleString('en-GB', {
                              weekday: 'short',
                              day: 'numeric',
                              month: 'short',
                              year: 'numeric',
                              hour: '2-digit',
                              minute: '2-digit',
                            })}
                          </StatNumber>
                          <StatHelpText fontSize="xs" color={secondaryTextColor}>
                            Reference: {order.reference}
                          </StatHelpText>
                        </Stat>
                      </SimpleGrid>
                    </VStack>
                  </CardBody>
                </Card>

                {/* Capacity Check & Vehicles Required */}
                {order.capacityCheck && (order.capacityCheck.warnings.length > 0 || order.capacityCheck.vansRequired) && (
                  <Alert 
                    status={order.capacityCheck.vansRequired && order.capacityCheck.vansRequired > 1 ? "error" : "warning"} 
                    bg={order.capacityCheck.vansRequired && order.capacityCheck.vansRequired > 1 ? "rgba(239, 68, 68, 0.15)" : "rgba(245, 158, 11, 0.15)"} 
                    borderRadius="md" 
                    borderWidth={2} 
                    borderColor={order.capacityCheck.vansRequired && order.capacityCheck.vansRequired > 1 ? "#ef4444" : "#f59e0b"}
                  >
                    <AlertIcon color={order.capacityCheck.vansRequired && order.capacityCheck.vansRequired > 1 ? "#ef4444" : "#f59e0b"} boxSize={6} />
                    <VStack align="start" spacing={2} flex={1}>
                      {order.capacityCheck.vansRequired && order.capacityCheck.vansRequired > 1 && (
                        <Text fontSize="lg" fontWeight="bold" color="#ef4444">
                          🚛 REQUIRES {order.capacityCheck.vansRequired} VANS
                        </Text>
                      )}
                      <Text fontSize="sm" fontWeight="semibold" color={textColor}>
                        Capacity Warnings:
                      </Text>
                      <VStack align="start" spacing={1} w="full">
                        {order.capacityCheck.warnings.map((warning, idx) => (
                          <Text key={idx} fontSize="sm" color={textColor}>• {warning}</Text>
                        ))}
                      </VStack>
                      {order.capacityCheck.recommendations.length > 0 && (
                        <>
                          <Text fontSize="sm" fontWeight="semibold" color={textColor} mt={2}>
                            Recommendations:
                          </Text>
                          <VStack align="start" spacing={1} w="full">
                            {order.capacityCheck.recommendations.map((rec, idx) => (
                              <Text key={idx} fontSize="sm" color="#10b981">✓ {rec}</Text>
                            ))}
                          </VStack>
                        </>
                      )}
                      <SimpleGrid columns={3} spacing={3} w="full" mt={2}>
                        <Box p={2} bg="rgba(0,0,0,0.3)" borderRadius="md">
                          <Text fontSize="xs" color={secondaryTextColor}>Weight</Text>
                          <Text fontSize="md" fontWeight="bold" color={order.capacityCheck.weightUtilization > 100 ? "#ef4444" : "#10b981"}>
                            {order.capacityCheck.weightUtilization.toFixed(0)}%
                          </Text>
                        </Box>
                        <Box p={2} bg="rgba(0,0,0,0.3)" borderRadius="md">
                          <Text fontSize="xs" color={secondaryTextColor}>Volume</Text>
                          <Text fontSize="md" fontWeight="bold" color={order.capacityCheck.volumeUtilization > 100 ? "#ef4444" : "#10b981"}>
                            {order.capacityCheck.volumeUtilization.toFixed(0)}%
                          </Text>
                        </Box>
                        <Box p={2} bg="rgba(0,0,0,0.3)" borderRadius="md">
                          <Text fontSize="xs" color={secondaryTextColor}>Items</Text>
                          <Text fontSize="md" fontWeight="bold" color={order.capacityCheck.itemUtilization > 100 ? "#ef4444" : "#10b981"}>
                            {order.capacityCheck.itemUtilization.toFixed(0)}%
                          </Text>
                        </Box>
                      </SimpleGrid>
                    </VStack>
                  </Alert>
                )}

                {(amountPaid > 0 || order.paidAt) && (
                  <Card bg={cardBg} borderColor="#2563eb" borderWidth={1}>
                    <CardBody>
                      <VStack align="stretch" spacing={4}>
                        <HStack justify="space-between" align="center">
                          <VStack align="start" spacing={1}>
                            <Text fontWeight="bold" fontSize="md" color={textColor}>
                              Post-Payment Adjustments
                            </Text>
                            <Text fontSize="xs" color={secondaryTextColor}>
                              Manage additional charges or refunds after the customer has paid.
                            </Text>
                          </VStack>
                          <Badge colorScheme={additionalPaymentStatusMeta.color} fontSize="0.7rem" px={3} py={1} borderRadius="full">
                            {additionalPaymentStatusMeta.label}
                          </Badge>
                        </HStack>

                        <SimpleGrid columns={{ base: 1, md: 3 }} spacing={4}>
                          <Card bg="#0f172a" borderColor="#1f2937" borderWidth={1}>
                            <CardBody>
                              <HStack align="center" spacing={3}>
                                <Circle size="38px" bg="rgba(16, 185, 129, 0.15)">
                                  <FiTrendingUp color="#10b981" />
                                </Circle>
                                <VStack align="start" spacing={0}>
                                  <Text fontSize="xs" color={secondaryTextColor}>Total Collected</Text>
                                  <Text fontWeight="bold" color="#10b981">{formatCurrency(amountPaid)}</Text>
                                </VStack>
                              </HStack>
                            </CardBody>
                          </Card>
                          <Card bg="#0f172a" borderColor="#1f2937" borderWidth={1}>
                            <CardBody>
                              <HStack align="center" spacing={3}>
                                <Circle size="38px" bg="rgba(37, 99, 235, 0.15)">
                                  <FiDollarSign color="#2563eb" />
                                </Circle>
                                <VStack align="start" spacing={0}>
                                  <Text fontSize="xs" color={secondaryTextColor}>Current Total</Text>
                                  <Text fontWeight="bold" color={textColor}>{formatCurrency(order.totalGBP)}</Text>
                                </VStack>
                              </HStack>
                            </CardBody>
                          </Card>
                          <Card bg="#0f172a" borderColor="#1f2937" borderWidth={1}>
                            <CardBody>
                              <HStack align="center" spacing={3}>
                                <Circle size="38px" bg={adjustedDifference > 0 ? 'rgba(249, 115, 22, 0.15)' : 'rgba(14, 165, 233, 0.15)'}>
                                  {adjustedDifference > 0 ? <FiArrowUpRight color="#f97316" /> : adjustedDifference < 0 ? <FiArrowDownRight color="#0ea5e9" /> : <FiCheckCircle color="#10b981" />}
                                </Circle>
                                <VStack align="start" spacing={0}>
                                  <Text fontSize="xs" color={secondaryTextColor}>Adjustment vs Paid</Text>
                                  <Text fontWeight="bold" color={adjustedDifference > 0 ? '#f97316' : adjustedDifference < 0 ? '#0ea5e9' : '#10b981'}>
                                    {adjustedDifference === 0 ? 'No Adjustment' : formatCurrency(Math.abs(adjustedDifference))}
                                  </Text>
                                </VStack>
                              </HStack>
                            </CardBody>
                          </Card>
                        </SimpleGrid>

                        <VStack align="stretch" spacing={3}>
                          <FormControl>
                            <FormLabel fontSize="xs" color={secondaryTextColor}>Adjusted Order Total (£)</FormLabel>
                            <NumberInput
                              value={(adjustedTotalGBP / 100).toFixed(2)}
                              onChange={(valueString) => {
                                const numericValue = Number.parseFloat(valueString);
                                if (Number.isNaN(numericValue)) {
                                  setAdjustedTotalGBP(0);
                                  return;
                                }
                                setAdjustedTotalGBP(Math.round(numericValue * 100));
                              }}
                              min={0}
                              step={1}
                              precision={2}
                            >
                              <NumberInputField
                                bg={cardBg}
                                color={textColor}
                                borderColor={borderColor}
                                _hover={{ borderColor: '#2563eb' }}
                                _focus={{ borderColor: '#2563eb', bg: cardBg }}
                              />
                            </NumberInput>
                          </FormControl>

                          <FormControl>
                            <FormLabel fontSize="xs" color={secondaryTextColor}>Reason (shown to customer)</FormLabel>
                            <Textarea
                              value={adjustmentReason}
                              onChange={(event) => setAdjustmentReason(event.target.value)}
                              placeholder="Explain why the adjustment is needed..."
                              bg={cardBg}
                              color={textColor}
                              borderColor={borderColor}
                              _hover={{ borderColor: '#2563eb' }}
                              _focus={{ borderColor: '#2563eb', bg: cardBg }}
                              rows={3}
                            />
                          </FormControl>

                          <HStack spacing={3} flexWrap="wrap">
                            <Button
                              colorScheme="blue"
                              leftIcon={<FiArrowUpRight />}
                              onClick={handleRequestAdditionalPayment}
                              isLoading={isRequestingAdditionalPayment}
                              isDisabled={adjustedDifference <= 0}
                            >
                              Request Additional Payment
                            </Button>
                            <Button
                              colorScheme="cyan"
                              variant="outline"
                              leftIcon={<FiArrowDownRight />}
                              onClick={handleIssueRefund}
                              isLoading={isIssuingRefund}
                              isDisabled={adjustedDifference >= 0}
                            >
                              Issue Refund
                            </Button>
                            <Button
                              variant="ghost"
                              size="sm"
                              color={secondaryTextColor}
                              onClick={() => {
                                setAdjustedTotalGBP(order.totalGBP);
                                setAdjustmentReason('');
                              }}
                            >
                              Reset
                            </Button>
                          </HStack>
                        </VStack>

                        <VStack align="stretch" spacing={1} fontSize="xs" color={secondaryTextColor}>
                          <Text>{additionalPaymentStatusMeta.description}</Text>
                          <Text>Outstanding Balance: {formatCurrency(outstandingAmount)}</Text>
                          <Text>Last Payment: {formatDateTime(order.lastPaymentDate || order.paidAt || null)}</Text>
                          <Text>Last Refund: {formatDateTime(order.lastRefundDate)}</Text>
                          {order.additionalPaymentRequestedAt && (
                            <Text>Additional Payment Requested: {formatDateTime(order.additionalPaymentRequestedAt)}</Text>
                          )}
                          {order.additionalPaymentPaidAt && (
                            <Text>Additional Payment Received: {formatDateTime(order.additionalPaymentPaidAt)}</Text>
                          )}
                        </VStack>
                      </VStack>
                    </CardBody>
                  </Card>
                )}

                {/* Trip Metrics Card */}
                <Card bg={cardBg} borderColor="#2563eb" borderWidth={1}>
                  <CardBody>
                    <SimpleGrid columns={2} spacing={4}>
                      <VStack align="start" spacing={1}>
                        <HStack spacing={1}>
                          {getStatusIcon(!!(order.baseDistanceMiles || order.distanceMeters), true)}
                          <Text fontSize="xs" color={secondaryTextColor}>Distance</Text>
                        </HStack>
                        <Text fontWeight="bold" fontSize="lg" color={
                          (order.baseDistanceMiles || order.distanceMeters) ? "#2563eb" : "#ef4444"
                        }>
                          {order.baseDistanceMiles 
                            ? `${order.baseDistanceMiles.toFixed(1)} mi`
                            : order.distanceMeters
                              ? `${(order.distanceMeters / 1609.34).toFixed(1)} mi`
                              : 'NOT CALCULATED'
                          }
                        </Text>
                      </VStack>
                      <VStack align="start" spacing={1}>
                        <HStack spacing={1}>
                          <FiClock color={secondaryTextColor} />
                          <Text fontSize="xs" color={secondaryTextColor}>Duration</Text>
                        </HStack>
                        <Text fontWeight="bold" fontSize="lg" color="#2563eb">
                          {formatDuration(calculateEstimatedDuration(order))}
                        </Text>
                      </VStack>
                    </SimpleGrid>
                  </CardBody>
                </Card>
                
                {/* Driver Earnings Breakdown */}
                {(order.distanceMeters || order.baseDistanceMiles) && order.durationSeconds && (
                  <Card bg={cardBg} borderColor="#a855f7" borderWidth={1}>
                    <CardBody>
                      <VStack align="stretch" spacing={2}>
                        <HStack spacing={2}>
                          <FiTrendingUp color="#a855f7" />
                          <Text fontSize="sm" fontWeight="bold" color="#a855f7">
                            Driver Earnings Breakdown
                          </Text>
                        </HStack>
                        <Divider borderColor={borderColor} />
                        <HStack justify="space-between" fontSize="xs">
                          <Text color={secondaryTextColor}>Base Fare:</Text>
                          <Text fontWeight="medium" color={textColor}>£{calculateDriverEarnings(order).base.toFixed(2)}</Text>
                        </HStack>
                        <HStack justify="space-between" fontSize="xs">
                          <Text color={secondaryTextColor}>Mileage Fee:</Text>
                          <Text fontWeight="medium" color={textColor}>£{calculateDriverEarnings(order).mileage.toFixed(2)}</Text>
                        </HStack>
                        <HStack justify="space-between" fontSize="xs">
                          <Text color={secondaryTextColor}>Time Fee:</Text>
                          <Text fontWeight="medium" color={textColor}>£{calculateDriverEarnings(order).time.toFixed(2)}</Text>
                        </HStack>
                        <Divider borderColor={borderColor} />
                        <HStack justify="space-between">
                          <Text fontSize="sm" fontWeight="bold" color="#a855f7">Total Driver Gets:</Text>
                          <Text fontSize="md" fontWeight="bold" color="#a855f7">
                            {calculateDriverEarnings(order).formatted}
                          </Text>
                        </HStack>
                        <Text fontSize="xs" color={secondaryTextColor} fontStyle="italic">
                          * Actual earnings calculated at job completion
                        </Text>
                      </VStack>
                    </CardBody>
                  </Card>
                )}
                {isEditing ? (
                  <>
                    <FormControl>
                      <FormLabel color={textColor} fontSize="sm">Scheduled Date & Time</FormLabel>
                      <Input
                        type="datetime-local"
                        value={editedOrder.scheduledAt ? new Date(editedOrder.scheduledAt).toISOString().slice(0, 16) : ''}
                        onChange={(e) => setEditedOrder({
                          ...editedOrder,
                          scheduledAt: e.target.value ? new Date(e.target.value).toISOString() : order?.scheduledAt
                        })}
                        bg={cardBg}
                        color={textColor}
                        borderColor={borderColor}
                        _hover={{ borderColor: '#2563eb' }}
                        _focus={{ borderColor: '#2563eb', bg: cardBg }}
                      />
                    </FormControl>
                    <FormControl>
                      <FormLabel color={textColor} fontSize="sm">Time Slot</FormLabel>
                      <Input
                        type="text"
                        value={editedOrder.pickupTimeSlot || ''}
                        onChange={(e) => setEditedOrder({
                          ...editedOrder,
                          pickupTimeSlot: e.target.value
                        })}
                        placeholder="e.g., 8 AM - 12 PM"
                        bg={cardBg}
                        color={textColor}
                        borderColor={borderColor}
                        _hover={{ borderColor: '#2563eb' }}
                        _focus={{ borderColor: '#2563eb', bg: cardBg }}
                      />
                    </FormControl>
                  </>
                ) : (
                  <>
                    <HStack justify="space-between">
                      <Text color={textColor}>Scheduled Date</Text>
                      <Text color={textColor}>
                        {order.scheduledAt
                          ? new Date(order.scheduledAt).toLocaleDateString('en-GB', {
                              day: '2-digit',
                              month: '2-digit',
                              year: 'numeric'
                            })
                          : 'Not scheduled'}
                      </Text>
                    </HStack>
                    <HStack justify="space-between">
                      <Text color={textColor}>Scheduled Time</Text>
                      <Text color={textColor}>
                        {order.scheduledAt
                          ? new Date(order.scheduledAt).toLocaleTimeString('en-GB', {
                              hour: '2-digit',
                              minute: '2-digit'
                            })
                          : 'Not scheduled'}
                      </Text>
                    </HStack>
                    <HStack justify="space-between">
                      <HStack spacing={1}>
                        {getStatusIcon(!!order.pickupTimeSlot, false)}
                        <Text color={textColor}>Time Slot</Text>
                      </HStack>
                      <Text color={order.pickupTimeSlot ? textColor : "#f59e0b"}>
                        {order.pickupTimeSlot || 'NOT SPECIFIED'}
                      </Text>
                    </HStack>
                  </>
                )}
                <HStack justify="space-between">
                  <Text color={textColor}>Created</Text>
                  <Text color={textColor}>
                    {new Date(order.createdAt).toLocaleDateString('en-GB', {
                      day: '2-digit',
                      month: '2-digit',
                      year: 'numeric',
                      hour: '2-digit',
                      minute: '2-digit'
                    })}
                  </Text>
                </HStack>
                {order.paidAt && (
                  <HStack justify="space-between">
                    <Text color={textColor}>Paid At</Text>
                    <Text color={textColor}>
                      {new Date(order.paidAt).toLocaleDateString('en-GB', {
                        day: '2-digit',
                        month: '2-digit',
                        year: 'numeric',
                        hour: '2-digit',
                        minute: '2-digit'
                      })}
                    </Text>
                  </HStack>
                )}
              </VStack>

              {/* Notes */}
              <Divider borderColor={borderColor} />
              <VStack align="stretch" spacing={2}>
                <HStack spacing={1}>
                  {getStatusIcon(!!order.notes, false)}
                  <Text fontWeight="bold" fontSize="md" color={textColor}>
                    Customer Notes
                  </Text>
                </HStack>
                {isEditing ? (
                  <FormControl>
                    <Textarea
                      value={editedOrder.notes || ''}
                      onChange={(e) => setEditedOrder({
                        ...editedOrder,
                        notes: e.target.value
                      })}
                      placeholder="Enter customer notes or special instructions..."
                      rows={4}
                      bg={cardBg}
                      color={textColor}
                      borderColor={borderColor}
                      _hover={{ borderColor: '#2563eb' }}
                      _focus={{ borderColor: '#2563eb', bg: cardBg }}
                    />
                  </FormControl>
                ) : (
                  <Box 
                    p={3} 
                    borderRadius="md" 
                    bg={order.notes ? cardBg : cardBg}
                    borderWidth={1}
                    borderColor={order.notes ? "#2563eb" : borderColor}
                  >
                    <Text fontSize="sm" color={order.notes ? textColor : secondaryTextColor} fontStyle={!order.notes ? "italic" : "normal"}>
                      {order.notes || 'No customer notes provided'}
                    </Text>
                  </Box>
                )}
              </VStack>

              {/* Actions */}
              <Divider borderColor={borderColor} />
              {isEditing ? (
                <VStack spacing={3} pt={4} align="stretch">
                  {newCalculatedPrice && (
                    <Alert status="warning" bg="rgba(245, 158, 11, 0.15)" borderRadius="md" borderWidth={1} borderColor="#f59e0b">
                      <AlertIcon color="#f59e0b" />
                      <VStack align="start" spacing={0} flex={1}>
                        <Text fontSize="sm" fontWeight="bold" color="#f59e0b">
                          ⚠️ Price Will Be Updated
                        </Text>
                        <Text fontSize="xs" color={secondaryTextColor}>
                          New price £{(newCalculatedPrice / 100).toFixed(2)} will replace current £{(order.totalGBP / 100).toFixed(2)}
                        </Text>
                      </VStack>
                    </Alert>
                  )}
                  <HStack spacing={3}>
                    <Button
                      leftIcon={<FiSave />}
                      colorScheme="green"
                      size="sm"
                      flex={1}
                      onClick={handleEditSave}
                      isLoading={isSaving}
                      loadingText="Saving..."
                      bg="#10b981"
                      color="#FFFFFF"
                      _hover={{ bg: '#059669' }}
                    >
                      {newCalculatedPrice ? 'Save & Update Price' : 'Save Changes'}
                    </Button>
                    <Button
                      leftIcon={<FiX />}
                      variant="outline"
                      size="sm"
                      flex={1}
                      onClick={handleEditCancel}
                      isDisabled={isSaving}
                      borderColor={borderColor}
                      color={textColor}
                      _hover={{ bg: '#1a1a1a' }}
                    >
                      Cancel Edit
                    </Button>
                  </HStack>
                </VStack>
              ) : (
                <VStack spacing={3} pt={4}>
                  <HStack spacing={3} w="full">
                    <Button
                      leftIcon={<FiEdit />}
                      colorScheme="blue"
                      size="sm"
                      flex={1}
                      onClick={handleEditStart}
                      isDisabled={order?.status === 'CANCELLED'}
                      bg="#2563eb"
                      color="#FFFFFF"
                      _hover={{ bg: '#1d4ed8' }}
                      _disabled={{ bg: '#1a1a1a', color: secondaryTextColor, opacity: 0.5 }}
                    >
                      Edit Order
                    </Button>
                    <Button
                      leftIcon={<FiMail />}
                      colorScheme="green"
                      variant="outline"
                      size="sm"
                      flex={1}
                      onClick={handleSendConfirmationEmail}
                      isLoading={isSendingEmail}
                      loadingText="Sending..."
                      isDisabled={order?.status === 'CANCELLED'}
                      borderColor={borderColor}
                      color="#10b981"
                      _hover={{ bg: '#1a1a1a' }}
                      _disabled={{ borderColor: borderColor, color: secondaryTextColor, opacity: 0.5 }}
                    >
                      Send Confirmation
                    </Button>
                  </HStack>
                  
                  <HStack spacing={3} w="full">
                    <Button
                      leftIcon={<FiMail />}
                      colorScheme="orange"
                      variant="outline"
                      size="sm"
                      flex={1}
                      onClick={handleSendFloorWarningEmail}
                      borderColor={borderColor}
                      color="#f59e0b"
                      _hover={{ bg: '#1a1a1a' }}
                      isLoading={isSendingEmail}
                      loadingText="Sending..."
                      isDisabled={order?.status === 'CANCELLED'}
                      title="Send floor warning email to customer if they didn't specify floor numbers"
                    >
                      Send Floor Warning
                    </Button>
                    <Button
                      leftIcon={<FiTruck />}
                      variant="outline"
                      size="sm"
                      flex={1}
                      onClick={onAssignModalOpen}
                      isDisabled={order?.status === 'CANCELLED'}
                      borderColor={borderColor}
                      color={textColor}
                      _hover={{ bg: '#1a1a1a' }}
                      _disabled={{ borderColor: borderColor, color: secondaryTextColor, opacity: 0.5 }}
                    >
                      {order?.driver ? 'Change Driver' : 'Assign Driver'}
                    </Button>
                    {order?.driver && (
                      <Button
                        leftIcon={<FiTrash2 />}
                        colorScheme="orange"
                        variant="outline"
                        size="sm"
                        flex={1}
                        onClick={handleRemoveDriver}
                        isDisabled={order?.status === 'CANCELLED' || order?.status === 'COMPLETED'}
                        borderColor={borderColor}
                        color="#f59e0b"
                        _hover={{ bg: '#1a1a1a' }}
                        _disabled={{ borderColor: borderColor, color: secondaryTextColor, opacity: 0.5 }}
                      >
                        Remove Driver
                      </Button>
                    )}
                    <Button
                      leftIcon={<FiTrash2 />}
                      colorScheme="red"
                      variant="outline"
                      size="sm"
                      flex={1}
                      onClick={onCancelModalOpen}
                      isDisabled={order?.status === 'CANCELLED' || order?.status === 'COMPLETED'}
                      borderColor={borderColor}
                      color="#ef4444"
                      _hover={{ bg: '#1a1a1a' }}
                      _disabled={{ borderColor: borderColor, color: secondaryTextColor, opacity: 0.5 }}
                    >
                      Cancel Order
                    </Button>
                  </HStack>
                </VStack>
              )}
            </VStack>
          ) : (
            <Text color={textColor} textAlign="center" py={8}>
              No order selected
            </Text>
          )}
        </DrawerBody>
      </DrawerContent>

      {/* Cancel Order Confirmation Modal */}
      <Modal isOpen={isCancelModalOpen} onClose={onCancelModalClose}>
        <ModalOverlay bg="blackAlpha.800" />
        <ModalContent bg={bgColor} borderColor={borderColor} borderWidth={1}>
          <ModalHeader color="#ef4444" bg={cardBg} borderBottom={`1px solid ${borderColor}`}>
            <HStack spacing={2}>
              <FiTrash2 />
              <Text color="#ef4444">Cancel Order</Text>
            </HStack>
          </ModalHeader>
          <ModalCloseButton color={textColor} _hover={{ bg: '#1a1a1a' }} />
          <ModalBody bg={bgColor} color={textColor}>
            <VStack spacing={4} align="stretch">
              <Alert status="warning" bg="#1a1a1a" borderColor={borderColor}>
                <AlertIcon color="#f59e0b" />
                <VStack align="start" spacing={1}>
                  <Text fontWeight="bold" color={textColor}>This action cannot be undone!</Text>
                  <Text fontSize="sm" color={textColor}>
                    Cancelling this order will:
                  </Text>
                </VStack>
              </Alert>
              
              <VStack align="start" spacing={2} pl={4}>
                <Text fontSize="sm" color={textColor}>• Change order status to CANCELLED</Text>
                <Text fontSize="sm" color={textColor}>• Send cancellation notification to customer</Text>
                <Text fontSize="sm" color={textColor}>• Remove from active orders list</Text>
                <Text fontSize="sm" color={textColor}>• Trigger refund process if payment was made</Text>
              </VStack>

              {order && (
                <Box p={3} bg={cardBg} borderRadius="md" borderWidth={1} borderColor={borderColor}>
                  <Text fontWeight="bold" fontSize="sm" mb={1} color={textColor}>Order to Cancel:</Text>
                  <Text fontSize="sm" color={textColor}>Reference: {order.reference}</Text>
                  <Text fontSize="sm" color={textColor}>Customer: {order.customerName}</Text>
                  <Text fontSize="sm" color={textColor}>Amount: {formatCurrency(order.totalGBP)}</Text>
                </Box>
              )}
            </VStack>
          </ModalBody>

          <ModalFooter bg={cardBg} borderTop={`1px solid ${borderColor}`}>
            <HStack spacing={3}>
              <Button 
                variant="outline" 
                onClick={onCancelModalClose}
                isDisabled={isCancelling}
                borderColor={borderColor}
                color={textColor}
                _hover={{ bg: '#1a1a1a' }}
              >
                Keep Order
              </Button>
              <Button 
                colorScheme="red" 
                onClick={handleCancelOrder}
                isLoading={isCancelling}
                loadingText="Cancelling..."
                bg="#ef4444"
                color="#FFFFFF"
                _hover={{ bg: '#dc2626' }}
              >
                Yes, Cancel Order
              </Button>
            </HStack>
          </ModalFooter>
        </ModalContent>
      </Modal>

      {/* Assign Driver Modal */}
      <Modal isOpen={isAssignModalOpen} onClose={onAssignModalClose} size="xl" scrollBehavior="inside">
        <ModalOverlay bg="blackAlpha.800" />
        <ModalContent maxH="90vh" bg={bgColor} borderColor={borderColor} borderWidth={1}>
          <ModalHeader bg={cardBg} borderBottom={`1px solid ${borderColor}`} color={textColor}>
            <HStack spacing={2}>
              <FiTruck color={textColor} />
              <Text color={textColor}>{order?.driver ? 'Change Driver' : 'Assign Driver'}</Text>
            </HStack>
          </ModalHeader>
          <ModalCloseButton color={textColor} _hover={{ bg: '#1a1a1a' }} />
          <ModalBody overflowY="auto" maxH="60vh" bg={bgColor} color={textColor}>
            <VStack spacing={4} align="stretch">
              <Alert status="info" bg="#1a1a1a" borderColor={borderColor}>
                <AlertIcon color="#2563eb" />
                <Text fontSize="sm" color={textColor}>
                  {order?.driver 
                    ? 'Select a new driver to replace the current one. The current driver will be notified of the change.'
                    : 'Select a driver to assign to this order. The driver will be notified immediately.'
                  }
                </Text>
              </Alert>

              <FormControl>
                <FormLabel color={textColor}>Available Drivers</FormLabel>
                {isLoadingDrivers ? (
                  <HStack justify="center" py={4}>
                    <Spinner size="sm" color="#2563eb" />
                    <Text color={textColor}>Loading drivers...</Text>
                  </HStack>
                ) : availableDrivers.length === 0 ? (
                  <VStack spacing={3} align="stretch">
                    <Alert status="warning" bg="#1a1a1a" borderColor={borderColor}>
                      <AlertIcon color="#f59e0b" />
                      <VStack align="start" spacing={1}>
                        <Text fontSize="sm" fontWeight="bold" color={textColor}>No drivers found</Text>
                        <Text fontSize="xs" color={textColor}>
                          This could happen if no drivers are approved and active, or if all drivers are currently busy.
                        </Text>
                      </VStack>
                    </Alert>
                    <HStack spacing={2}>
                      <Button
                        size="sm"
                        colorScheme="blue"
                        variant="outline"
                        onClick={loadAvailableDrivers}
                        isLoading={isLoadingDrivers}
                        borderColor={borderColor}
                        color="#2563eb"
                        _hover={{ bg: '#1a1a1a' }}
                      >
                        Refresh Driver List
                      </Button>
                      <Button
                        size="sm"
                        colorScheme="orange"
                        variant="outline"
                        borderColor={borderColor}
                        color="#f59e0b"
                        _hover={{ bg: '#1a1a1a' }}
                        onClick={async () => {
                          try {
                            const response = await fetch('/api/admin/drivers/fix-availability', {
                              method: 'POST'
                            });
                            const result = await response.json();
                            
                            if (result.success) {
                              toast({
                                title: 'Availability Fixed',
                                description: `Created availability records for ${result.driversFixed} drivers`,
                                status: 'success',
                                duration: 3000,
                              });
                              // Reload drivers after fix
                              loadAvailableDrivers();
                            } else {
                              throw new Error(result.error || 'Fix failed');
                            }
                          } catch (error) {
                            toast({
                              title: 'Fix Failed',
                              description: error instanceof Error ? error.message : 'Failed to fix availability',
                              status: 'error',
                              duration: 5000,
                            });
                          }
                        }}
                      >
                        Fix Missing Records
                      </Button>
                    </HStack>
                  </VStack>
                ) : (
                  <VStack spacing={4} align="stretch">
                    {/* Interactive Driver Location Map */}
                    {order && order.pickupAddress && 
                     order.pickupAddress.lat !== null && order.pickupAddress.lat !== undefined && 
                     order.pickupAddress.lng !== null && order.pickupAddress.lng !== undefined && 
                     !isNaN(Number(order.pickupAddress.lat)) && !isNaN(Number(order.pickupAddress.lng)) &&
                     availableDrivers.length > 0 ? (
                      <VStack align="stretch" spacing={3}>
                        <HStack justify="space-between" align="center">
                          <Select
                            placeholder="👤 Click here to select a driver"
                            value={selectedDriverId}
                            onChange={(e) => setSelectedDriverId(e.target.value)}
                            bg="white"
                            color="black"
                            borderColor="gray.300"
                            focusBorderColor="blue.500"
                            size="md"
                            maxW="520px"
                            sx={{
                              option: { color: 'black', backgroundColor: 'white' },
                              'option:checked': { color: 'black', backgroundColor: 'white' }
                            }}
                          >
                            {availableDrivers.map((driver) => {
                              let distanceText = '';
                              const hasDriver = driver.DriverAvailability?.location?.lat && driver.DriverAvailability?.location?.lng && !isNaN(driver.DriverAvailability.location.lat) && !isNaN(driver.DriverAvailability.location.lng);
                              const pickupLatNum = Number(order?.pickupAddress?.lat ?? NaN);
                              const pickupLngNum = Number(order?.pickupAddress?.lng ?? NaN);
                              const dropoffLatNum = Number(order?.dropoffAddress?.lat ?? NaN);
                              const dropoffLngNum = Number(order?.dropoffAddress?.lng ?? NaN);
                              const hasPickup = !isNaN(pickupLatNum) && !isNaN(pickupLngNum);
                              const hasDropoff = !isNaN(dropoffLatNum) && !isNaN(dropoffLngNum);
                              if (hasDriver && (hasPickup || hasDropoff)) {
                                try {
                                  const driverLat = parseFloat(driver.DriverAvailability.location.lat);
                                  const driverLng = parseFloat(driver.DriverAvailability.location.lng);
                                  const targetLat = hasPickup ? pickupLatNum : dropoffLatNum;
                                  const targetLng = hasPickup ? pickupLngNum : dropoffLngNum;
                                  const R = 3959;
                                  const dLat = (targetLat - driverLat) * Math.PI / 180;
                                  const dLng = (targetLng - driverLng) * Math.PI / 180;
                                  const a = Math.sin(dLat/2) * Math.sin(dLat/2) + Math.cos(driverLat * Math.PI / 180) * Math.cos(targetLat * Math.PI / 180) * Math.sin(dLng/2) * Math.sin(dLng/2);
                                  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
                                  const distance = R * c;
                                  if (Number.isFinite(distance)) {
                                    distanceText = ` - ${distance.toFixed(1)} miles away`;
                                  }
                                } catch {
                                  distanceText = ' - Location unknown';
                                }
                              } else {
                                distanceText = ' - Location unknown';
                              }
                              return (
                                <option key={driver.id} value={driver.id}>
                                  {driver.name} - {driver.availabilityReason || 'Available'}
                                  {driver.DriverAvailability?.status && ` (${driver.DriverAvailability.status})`}
                                  {distanceText}
                                </option>
                              );
                            })}
                          </Select>
                          <Badge colorScheme="blue" variant="subtle">
                            {`Drivers with location: ${availableDrivers.filter(d => Number.isFinite(Number(d?.DriverAvailability?.location?.lat)) && Number.isFinite(Number(d?.DriverAvailability?.location?.lng))).length}/${availableDrivers.length}`}
                          </Badge>
                        </HStack>
                        <Box 
                          h="450px" 
                          bg={cardBg} 
                          borderRadius="md" 
                          border="1px solid" 
                          borderColor={borderColor}
                          position="relative"
                          overflow="hidden"
                        >
                          <iframe
                            srcDoc={`
                              <!DOCTYPE html>
                              <html>
                              <head>
                                <meta charset="utf-8">
                                <meta name="viewport" content="width=device-width, initial-scale=1">
                                <link href='https://api.mapbox.com/mapbox-gl-js/v2.15.0/mapbox-gl.css' rel='stylesheet' />
                                <script src='https://api.mapbox.com/mapbox-gl-js/v2.15.0/mapbox-gl.js'></script>
                                <style>
                                  body { margin: 0; padding: 0; }
                                  #map { position: absolute; top: 0; bottom: 0; width: 100%; }
                                </style>
                              </head>
                              <body>
                                <div id='map'></div>
                                <script>
                                  mapboxgl.accessToken = 'pk.eyJ1IjoiYWhtYWRhbHdha2FpIiwiYSI6ImNtZGNsZ3RsZDEzdGsya3F0ODFxeGRzbXoifQ.jfgGW0KNFTwATOShRDtQsg';
                                  
                                  const driversRaw = ${JSON.stringify(
                                    (availableDrivers || []).map(d => ({
                                      id: d.id,
                                      name: d.name,
                                      status: d.DriverAvailability?.status || 'unknown',
                                      activeJobs: d.totalActiveJobs || 0,
                                      reason: d.availabilityReason || 'Ready',
                                      lat: d.DriverAvailability?.location?.lat,
                                      lng: d.DriverAvailability?.location?.lng,
                                    }))
                                  )};
                                  const drivers = driversRaw
                                    .map(d => ({ ...d, lat: Number(d.lat), lng: Number(d.lng) }))
                                    .filter(d => Number.isFinite(d.lat) && Number.isFinite(d.lng));
                                  
                                  const ukBounds = [[-11.0, 49.0],[2.2, 61.0]]; // UK bounding box (approx)
                                  const map = new mapboxgl.Map({
                                    container: 'map',
                                    style: 'mapbox://styles/mapbox/streets-v12',
                                    center: [-1.5, 54.5], // Center over UK
                                    zoom: 5,
                                    maxBounds: ukBounds
                                  });
                                  
                                  map.addControl(new mapboxgl.NavigationControl(), 'top-right');
                                  map.addControl(new mapboxgl.FullscreenControl(), 'top-right');
                                  
                                  // Constrain panning to UK
                                  map.setMaxBounds(ukBounds);
                                  const pickupLng = Number("${(order as any)?.pickupAddress?.lng ?? ''}");
                                  const pickupLat = Number("${(order as any)?.pickupAddress?.lat ?? ''}");
                                  if (Number.isFinite(pickupLng) && Number.isFinite(pickupLat)) {
                                    const pickupEl = document.createElement('div');
                                    pickupEl.style.width = '14px';
                                    pickupEl.style.height = '14px';
                                    pickupEl.style.borderRadius = '50%';
                                    pickupEl.style.background = '#22c55e';
                                    pickupEl.style.boxShadow = '0 0 8px rgba(34,197,94,0.6)';
                                    new mapboxgl.Marker(pickupEl)
                                      .setLngLat([pickupLng, pickupLat])
                                      .setPopup(new mapboxgl.Popup({ offset: 25, maxWidth: '300px' })
                                        .setHTML('<strong>Pickup</strong><br/>${(order as any)?.pickupAddress?.label || ''}')
                                      )
                                      .addTo(map);
                                  }
                                  
                                  const dropoffLng = Number("${(order as any)?.dropoffAddress?.lng ?? ''}");
                                  const dropoffLat = Number("${(order as any)?.dropoffAddress?.lat ?? ''}");
                                  if (Number.isFinite(dropoffLng) && Number.isFinite(dropoffLat)) {
                                    const dropoffEl = document.createElement('div');
                                    dropoffEl.style.width = '14px';
                                    dropoffEl.style.height = '14px';
                                    dropoffEl.style.borderRadius = '50%';
                                    dropoffEl.style.background = '#ef4444';
                                    dropoffEl.style.boxShadow = '0 0 8px rgba(239,68,68,0.6)';
                                    new mapboxgl.Marker(dropoffEl)
                                      .setLngLat([dropoffLng, dropoffLat])
                                      .setPopup(new mapboxgl.Popup({ offset: 25, maxWidth: '300px' })
                                        .setHTML('<strong>Dropoff</strong><br/>${(order as any)?.dropoffAddress?.label || ''}')
                                      )
                                      .addTo(map);
                                  }
                                  
                                  // Add driver markers with tooltips
                                  drivers.forEach(driver => {
                                    if (!Number.isFinite(driver.lng) || !Number.isFinite(driver.lat)) return;
                                    const isOnline = driver.status === 'online';
                                    const el = document.createElement('div');
                                    el.style.width = '16px';
                                    el.style.height = '16px';
                                    el.style.borderRadius = '50%';
                                    el.style.background = isOnline ? '#3b82f6' : '#6b7280';
                                    el.style.boxShadow = '0 0 8px ' + (isOnline ? 'rgba(59,130,246,0.6)' : 'rgba(107,114,128,0.6)');
                                    el.style.border = '2px solid #ffffff';
                                    const popup = new mapboxgl.Popup({ 
                                      offset: 20,
                                      maxWidth: '260px'
                                    }).setHTML(
                                      '<div style="font-size: 14px; font-weight: 600; margin-bottom: 8px;">' + driver.name + '</div>' +
                                      '<span style="font-size: 12px; font-weight: 500; color: ' + (isOnline ? '#10B981' : '#6B7280') + ';">' + driver.status.toUpperCase() + '</span>' +
                                      '<div style="font-size: 11px; color: #6B7280; margin-bottom: 2px;">Active Jobs: <strong>' + driver.activeJobs + '</strong></div>' +
                                      '<div style="font-size: 11px; color: #9CA3AF;">' + driver.reason + '</div>'
                                    );
                                    new mapboxgl.Marker(el)
                                      .setLngLat([driver.lng, driver.lat])
                                      .setPopup(popup)
                                      .addTo(map);
                                  });
                                  
                                  // Fit bounds to UK and available points
                                  const bounds = new mapboxgl.LngLatBounds(ukBounds[0], ukBounds[1]);
                                  const maybeExtend = (lng, lat) => {
                                    if (Number.isFinite(lng) && Number.isFinite(lat)) {
                                      bounds.extend([lng, lat]);
                                    }
                                  };
                                  maybeExtend(pickupLng, pickupLat);
                                  maybeExtend(dropoffLng, dropoffLat);
                                  drivers.forEach(d => maybeExtend(d.lng, d.lat));
                                  map.fitBounds(bounds, { padding: 60, duration: 1000 });
                                </script>
                              </body>
                              </html>
                            `}
                            style={{ width: '100%', height: '100%', border: '0' }}
                          />
                        </Box>
                      </VStack>
                    ) : (
                      <Alert status="info" variant="left-accent">
                        <AlertIcon />
                        <Box>
                          <Text fontWeight="bold" fontSize="sm">No drivers available</Text>
                          <Text fontSize="xs" color="gray.600">We couldn't find any active drivers to show on the map.</Text>
                        </Box>
                      </Alert>
                    )}

                    <Select
                      placeholder="👤 Click here to select a driver"
                      value={selectedDriverId}
                      onChange={(e) => setSelectedDriverId(e.target.value)}
                      bg={selectedDriverId ? 'green.900' : 'gray.800'}
                      borderColor={selectedDriverId ? 'green.300' : 'gray.200'}
                      focusBorderColor="blue.500"
                      size="lg"
                    >
                      {availableDrivers.map((driver) => {
                        // Calculate distance from driver to pickup
                        let distanceText = '';
                        
                        // ✅ CRITICAL: Check all coordinates exist and are valid numbers
                        const hasDriver = driver.DriverAvailability?.location?.lat && driver.DriverAvailability?.location?.lng && !isNaN(driver.DriverAvailability.location.lat) && !isNaN(driver.DriverAvailability.location.lng);
                        const pickupLatNum = Number(order?.pickupAddress?.lat ?? NaN);
                        const pickupLngNum = Number(order?.pickupAddress?.lng ?? NaN);
                        const dropoffLatNum = Number(order?.dropoffAddress?.lat ?? NaN);
                        const dropoffLngNum = Number(order?.dropoffAddress?.lng ?? NaN);
                        const hasPickup = !isNaN(pickupLatNum) && !isNaN(pickupLngNum);
                        const hasDropoff = !isNaN(dropoffLatNum) && !isNaN(dropoffLngNum);
                        if (hasDriver && (hasPickup || hasDropoff)) {
                          try {
                            const driverLat = parseFloat(driver.DriverAvailability.location.lat);
                            const driverLng = parseFloat(driver.DriverAvailability.location.lng);
                            const targetLat = hasPickup ? pickupLatNum : dropoffLatNum;
                            const targetLng = hasPickup ? pickupLngNum : dropoffLngNum;
                            
                            // Haversine formula for distance
                            const R = 3959; // Earth radius in miles
                            const dLat = (targetLat - driverLat) * Math.PI / 180;
                            const dLng = (targetLng - driverLng) * Math.PI / 180;
                            const a = 
                              Math.sin(dLat/2) * Math.sin(dLat/2) +
                              Math.cos(driverLat * Math.PI / 180) * Math.cos(targetLat * Math.PI / 180) *
                              Math.sin(dLng/2) * Math.sin(dLng/2);
                            const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
                            const distance = R * c;
                            
                            if (!isNaN(distance) && isFinite(distance)) {
                              distanceText = ` - ${distance.toFixed(1)} miles away`;
                            }
                          } catch (error) {
                            console.warn('Error calculating distance:', error);
                            distanceText = ' - Location unknown';
                          }
                        } else {
                          // One or more coordinates are missing
                          distanceText = ' - Location unknown';
                        }
                        
                        return (
                          <option key={driver.id} value={driver.id}>
                            {driver.name} - {driver.availabilityReason || 'Available'}
                            {driver.DriverAvailability?.status && ` (${driver.DriverAvailability.status})`}
                            {distanceText}
                          </option>
                        );
                      })}
                    </Select>
                    
                    {!selectedDriverId && (
                      <Alert status="warning" size="sm">
                        <AlertIcon />
                        <Text fontSize="sm">
                          Please select a driver from the dropdown above to enable assignment
                        </Text>
                      </Alert>
                    )}
                    
                    {selectedDriverId && (
                      <Alert status="success" size="sm">
                        <AlertIcon />
                        <Text fontSize="sm">
                          Driver selected! Click "Assign Driver" to proceed
                        </Text>
                      </Alert>
                    )}
                    
                    {availableDrivers.length === 1 && !selectedDriverId && (
                      <HStack spacing={2}>
                        <Button
                          size="sm"
                          colorScheme="green"
                          variant="solid"
                          onClick={() => {
                            const driver = availableDrivers[0];
                            if (driver.isAvailable) {
                              setSelectedDriverId(driver.id);
                            }
                          }}
                          leftIcon={<FiTruck />}
                        >
                          Quick Select: {availableDrivers[0].name}
                        </Button>
                      </HStack>
                    )}
                    
                    <Text fontSize="xs" color="gray.600">
                      Found {availableDrivers.length} driver{availableDrivers.length !== 1 ? 's' : ''}
                      {availableDrivers.filter(d => d.isAvailable).length > 0 && 
                        ` (${availableDrivers.filter(d => d.isAvailable).length} available)`
                      }
                    </Text>
                  </VStack>
                )}
                <Button
                  size="xs"
                  variant="outline"
                  mt={2}
                  onClick={loadAvailableDrivers}
                  isLoading={isLoadingDrivers}
                >
                  Refresh Drivers
                </Button>
              </FormControl>

              <FormControl>
                <FormLabel>Reason (Optional)</FormLabel>
                <Textarea
                  placeholder="Enter reason for assignment/change..."
                  value={assignmentReason}
                  onChange={(e) => setAssignmentReason(e.target.value)}
                  rows={3}
                />
              </FormControl>

              {order && (
                <Box p={3} bg="gray.50" borderRadius="md">
                  <Text fontWeight="bold" fontSize="sm" mb={1}>Order Details:</Text>
                  <Text fontSize="sm">Reference: {order.reference}</Text>
                  <Text fontSize="sm">Customer: {order.customerName}</Text>
                  <Text fontSize="sm">Pickup: {order.pickupAddress?.label}</Text>
                  <Text fontSize="sm">Dropoff: {order.dropoffAddress?.label}</Text>
                </Box>
              )}

              {/* Spacer to ensure footer is visible */}
              <Box h={4}></Box>
            </VStack>
          </ModalBody>

          <ModalFooter bg="gray.800" borderTop="1px solid" borderColor="gray.600" position="sticky" bottom={0}>
            <HStack spacing={3} w="full" justify="space-between">
              <Button 
                variant="outline" 
                onClick={onAssignModalClose}
                isDisabled={isAssigningDriver}
                size="lg"
              >
                Cancel
              </Button>
              <Button 
                colorScheme={selectedDriverId ? "blue" : "gray"} 
                onClick={handleAssignDriver}
                isLoading={isAssigningDriver}
                loadingText="Assigning..."
                isDisabled={!selectedDriverId}
                size="lg"
                rightIcon={selectedDriverId ? <FiTruck /> : undefined}
                flex={1}
                maxW="300px"
              >
                {!selectedDriverId 
                  ? 'Select Driver First' 
                  : order?.driver 
                    ? 'Change Driver' 
                    : 'Assign Driver'
                }
              </Button>
            </HStack>
          </ModalFooter>
        </ModalContent>
      </Modal>

      {/* Remove Driver Modal */}
      <Modal isOpen={isRemoveModalOpen} onClose={onRemoveModalClose}>
        <ModalOverlay />
        <ModalContent>
          <ModalHeader color="red.600">
            <HStack spacing={2}>
              <FiX />
              <Text>Remove Driver</Text>
            </HStack>
          </ModalHeader>
          <ModalCloseButton />
          <ModalBody>
            <VStack spacing={4} align="stretch">
              <Alert status="warning">
                <AlertIcon />
                <VStack align="start" spacing={1}>
                  <Text fontWeight="bold">This action will remove the driver from this order!</Text>
                  <Text fontSize="sm">
                    The driver will be notified and the order will become available for other drivers.
                  </Text>
                </VStack>
              </Alert>
              
              {order?.driver?.user && (
                <Box p={3} bg="gray.50" borderRadius="md">
                  <Text fontWeight="bold" fontSize="sm" mb={1}>Driver to Remove:</Text>
                  <Text fontSize="sm">Name: {order.driver.user.name || 'Unknown'}</Text>
                  <Text fontSize="sm">Email: {order.driver.user.email || 'N/A'}</Text>
                  <Text fontSize="sm">Phone: {order.driver.user.phone || 'N/A'}</Text>
                </Box>
              )}

              {order && (
                <Box p={3} bg="blue.50" borderRadius="md">
                  <Text fontWeight="bold" fontSize="sm" mb={1}>Order Details:</Text>
                  <Text fontSize="sm">Reference: {order.reference}</Text>
                  <Text fontSize="sm">Customer: {order.customerName}</Text>
                </Box>
              )}
            </VStack>
          </ModalBody>

          <ModalFooter>
            <HStack spacing={3}>
              <Button 
                variant="outline" 
                onClick={onRemoveModalClose}
                isDisabled={isRemovingDriver}
              >
                Keep Driver
              </Button>
              <Button 
                colorScheme="red" 
                onClick={handleRemoveDriver}
                isLoading={isRemovingDriver}
                loadingText="Removing..."
              >
                Yes, Remove Driver
              </Button>
            </HStack>
          </ModalFooter>
        </ModalContent>
      </Modal>
    </Drawer>
  );
};

export default OrderDetailDrawer;

import React, { useState } from 'react';
import {
  Button,
  VStack,
  HStack,
  Text,
  Badge,
  Alert,
  AlertIcon,
  AlertTitle,
  AlertDescription,
  useToast,
  Modal,
  ModalOverlay,
  ModalContent,
  ModalHeader,
  ModalCloseButton,
  ModalBody,
  ModalFooter,
  useDisclosure,
  Box,
  Divider,
  Spinner,
  Code
} from '@chakra-ui/react';

interface PaymentConfirmationButtonProps {
  booking: {
    id: string;
    reference: string;
    status: string;
    totalGBP: number;
    customerName: string;
    paidAt?: string;
    stripePaymentIntentId?: string;
  };
  onSuccess?: () => void;
}

export default function PaymentConfirmationButton({ 
  booking, 
  onSuccess 
}: PaymentConfirmationButtonProps) {
  const [isLoading, setIsLoading] = useState(false);
  const [confirmationResult, setConfirmationResult] = useState<any>(null);
  const { isOpen, onOpen, onClose } = useDisclosure();
  const toast = useToast();

  const isPendingPayment = booking.status === 'PENDING_PAYMENT';

  const handleConfirmPayment = async () => {
    setIsLoading(true);
    try {
      const response = await fetch(`/api/admin/orders/${booking.reference}/confirm-payment`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
      });

      const result = await response.json();

      if (response.ok && result.success) {
        setConfirmationResult(result);
        toast({
          title: 'Payment Confirmed Successfully',
          description: `Booking ${booking.reference} has been confirmed and will appear in driver jobs`,
          status: 'success',
          duration: 5000,
          isClosable: true,
        });
        onSuccess?.();
        onOpen(); // Show details modal
      } else {
        throw new Error(result.error || 'Failed to confirm payment');
      }
    } catch (error) {
      console.error('Error confirming payment:', error);
      toast({
        title: 'Payment Confirmation Failed',
        description: error instanceof Error ? error.message : 'Unknown error occurred',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setIsLoading(false);
    }
  };

  if (!isPendingPayment) {
    return (
      <Badge colorScheme="green" size="sm">
        Payment Confirmed
      </Badge>
    );
  }

  return (
    <>
      <VStack spacing={2} align="stretch">
        <Alert status="warning" size="sm">
          <AlertIcon />
          <Box>
            <AlertTitle fontSize="sm">Payment Issue!</AlertTitle>
            <AlertDescription fontSize="xs">
              This booking shows as PENDING_PAYMENT but may have been paid. 
              This prevents it from appearing in driver jobs.
            </AlertDescription>
          </Box>
        </Alert>
        
        <Button
          size="sm"
          colorScheme="blue"
          onClick={handleConfirmPayment}
          isLoading={isLoading}
          loadingText="Confirming..."
          leftIcon={isLoading ? <Spinner size="sm" /> : undefined}
        >
          Manually Confirm Payment
        </Button>
      </VStack>

      {/* Success Details Modal */}
      <Modal isOpen={isOpen} onClose={onClose} size="lg">
        <ModalOverlay />
        <ModalContent>
          <ModalHeader>Payment Confirmed Successfully</ModalHeader>
          <ModalCloseButton />
          <ModalBody>
            {confirmationResult && (
              <VStack spacing={4} align="stretch">
                <Alert status="success">
                  <AlertIcon />
                  <Box>
                    <AlertTitle>Booking Fixed!</AlertTitle>
                    <AlertDescription>
                      Booking {confirmationResult.booking.reference} has been manually confirmed
                      and should now appear in the driver jobs dashboard.
                    </AlertDescription>
                  </Box>
                </Alert>

                <Box>
                  <Text fontWeight="bold" mb={2}>Booking Details:</Text>
                  <VStack spacing={1} align="stretch" fontSize="sm">
                    <HStack justify="space-between">
                      <Text>Reference:</Text>
                      <Code>{confirmationResult.booking.reference}</Code>
                    </HStack>
                    <HStack justify="space-between">
                      <Text>Previous Status:</Text>
                      <Badge colorScheme="orange">{confirmationResult.booking.previousStatus}</Badge>
                    </HStack>
                    <HStack justify="space-between">
                      <Text>New Status:</Text>
                      <Badge colorScheme="green">{confirmationResult.booking.status}</Badge>
                    </HStack>
                    <HStack justify="space-between">
                      <Text>Paid At:</Text>
                      <Text>{new Date(confirmationResult.booking.paidAt).toLocaleString()}</Text>
                    </HStack>
                  </VStack>
                </Box>

                {confirmationResult.stripeInfo && (
                  <Box>
                    <Text fontWeight="bold" mb={2}>Stripe Information:</Text>
                    <VStack spacing={1} align="stretch" fontSize="sm">
                      <HStack justify="space-between">
                        <Text>Payment Intent:</Text>
                        <Code fontSize="xs">{confirmationResult.stripeInfo.paymentIntentId}</Code>
                      </HStack>
                      <HStack justify="space-between">
                        <Text>Payment Status:</Text>
                        <Badge colorScheme="green">{confirmationResult.stripeInfo.paymentStatus}</Badge>
                      </HStack>
                    </VStack>
                  </Box>
                )}

                <Divider />

                <Box>
                  <Text fontWeight="bold" mb={2}>Next Steps:</Text>
                  <VStack spacing={1} align="stretch" fontSize="sm">
                    {confirmationResult.nextSteps?.map((step: string, index: number) => (
                      <Text key={index}>• {step}</Text>
                    ))}
                  </VStack>
                </Box>
              </VStack>
            )}
          </ModalBody>
          <ModalFooter>
            <Button colorScheme="blue" onClick={onClose}>
              Close
            </Button>
          </ModalFooter>
        </ModalContent>
      </Modal>
    </>
  );
}

/**
 * Real-time Performance Monitor Dashboard
 * 
 * React component for monitoring API performance metrics,
 * cache hit rates, and system optimization status
 */

'use client';

import React, { useState, useEffect, useCallback } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { 
  Activity, 
  TrendingUp, 
  TrendingDown, 
  Zap, 
  Database, 
  Server, 
  RefreshCw,
  AlertTriangle,
  CheckCircle,
  Clock,
  BarChart3,
  Gauge
} from 'lucide-react';

interface PerformanceMetrics {
  totalRequests: number;
  averageResponseTime: number;
  cacheHitRate: number;
  errorRate: number;
  endpointStats: Record<string, {
    requests: number;
    averageResponseTime: number;
    cacheHitRate: number;
    errorRate: number;
  }>;
}

interface OptimizationSuggestion {
  endpoint: string;
  issue: string;
  suggestion: string;
  priority: 'low' | 'medium' | 'high' | 'critical';
}

const PerformanceMonitorDashboard: React.FC = () => {
  const [metrics, setMetrics] = useState<PerformanceMetrics | null>(null);
  const [suggestions, setSuggestions] = useState<OptimizationSuggestion[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [lastUpdate, setLastUpdate] = useState<Date | null>(null);
  const [timeframe, setTimeframe] = useState<'hour' | 'day' | 'week'>('hour');
  const [autoRefresh, setAutoRefresh] = useState(true);

  // Fetch performance data
  const fetchPerformanceData = useCallback(async () => {
    setIsLoading(true);
    try {
      const response = await fetch(`/api/performance/routes?endpoint=analytics&timeframe=${timeframe}`);
      const data = await response.json();
      
      if (data.success) {
        setMetrics(data.data.performance);
        setSuggestions(data.data.optimizationSuggestions);
        setLastUpdate(new Date());
      }
    } catch (error) {
      console.error('Failed to fetch performance data:', error);
    } finally {
      setIsLoading(false);
    }
  }, [timeframe]);

  // Clear cache
  const clearCache = async (pattern?: string) => {
    setIsLoading(true);
    try {
      const response = await fetch('/api/performance/routes', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'clear_cache',
          pattern
        })
      });
      
      if (response.ok) {
        await fetchPerformanceData();
      }
    } catch (error) {
      console.error('Failed to clear cache:', error);
    } finally {
      setIsLoading(false);
    }
  };

  // Optimize database
  const optimizeDatabase = async () => {
    setIsLoading(true);
    try {
      const response = await fetch('/api/performance/routes', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'optimize_database'
        })
      });
      
      if (response.ok) {
        await fetchPerformanceData();
      }
    } catch (error) {
      console.error('Failed to optimize database:', error);
    } finally {
      setIsLoading(false);
    }
  };

  // Auto-refresh
  useEffect(() => {
    fetchPerformanceData();
    
    if (autoRefresh) {
      const interval = setInterval(fetchPerformanceData, 30000); // 30 seconds
      return () => clearInterval(interval);
    }
  }, [fetchPerformanceData, autoRefresh]);

  // Performance grade helper
  const getPerformanceGrade = (responseTime: number): { grade: string; color: string } => {
    if (responseTime <= 200) return { grade: 'A', color: 'text-green-600' };
    if (responseTime <= 500) return { grade: 'B', color: 'text-blue-600' };
    if (responseTime <= 1000) return { grade: 'C', color: 'text-yellow-600' };
    if (responseTime <= 2000) return { grade: 'D', color: 'text-orange-600' };
    return { grade: 'F', color: 'text-red-600' };
  };

  // Priority color helper
  const getPriorityColor = (priority: string): string => {
    switch (priority) {
      case 'critical': return 'text-red-600 bg-red-50 border-red-200';
      case 'high': return 'text-orange-600 bg-orange-50 border-orange-200';
      case 'medium': return 'text-yellow-600 bg-yellow-50 border-yellow-200';
      case 'low': return 'text-blue-600 bg-blue-50 border-blue-200';
      default: return 'text-gray-600 bg-gray-50 border-gray-200';
    }
  };

  return (
    <div className="space-y-6">
      {/* Header Controls */}
      <Card>
        <CardHeader>
          <div className="flex justify-between items-center">
            <div>
              <CardTitle className="flex items-center gap-2">
                <Activity className="w-5 h-5" />
                API Performance Monitor
              </CardTitle>
              <CardDescription>
                Real-time monitoring of multi-drop route API performance
              </CardDescription>
            </div>
            <div className="flex items-center gap-2">
              <div className="flex gap-1">
                {(['hour', 'day', 'week'] as const).map(tf => (
                  <Button
                    key={tf}
                    variant={timeframe === tf ? 'default' : 'outline'}
                    size="sm"
                    onClick={() => setTimeframe(tf)}
                  >
                    {tf === 'hour' ? '1H' : tf === 'day' ? '24H' : '7D'}
                  </Button>
                ))}
              </div>
              
              <Button
                variant="outline"
                size="sm"
                onClick={() => setAutoRefresh(!autoRefresh)}
              >
                <RefreshCw className={`w-4 h-4 mr-2 ${autoRefresh ? 'animate-spin' : ''}`} />
                {autoRefresh ? 'Auto' : 'Manual'}
              </Button>
              
              <Button
                variant="outline"
                size="sm"
                onClick={() => fetchPerformanceData()}
                disabled={isLoading}
              >
                <RefreshCw className={`w-4 h-4 mr-2 ${isLoading ? 'animate-spin' : ''}`} />
                Refresh
              </Button>
            </div>
          </div>
        </CardHeader>
      </Card>

      {/* Performance Overview */}
      {metrics && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
          <Card>
            <CardHeader className="pb-2">
              <CardTitle className="text-sm font-medium flex items-center gap-2">
                <BarChart3 className="w-4 h-4" />
                Total Requests
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">{metrics.totalRequests.toLocaleString()}</div>
              <div className="text-sm text-gray-500 mt-1">
                Last {timeframe === 'hour' ? 'hour' : timeframe === 'day' ? '24 hours' : 'week'}
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardHeader className="pb-2">
              <CardTitle className="text-sm font-medium flex items-center gap-2">
                <Gauge className="w-4 h-4" />
                Avg Response Time
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className={`text-2xl font-bold ${getPerformanceGrade(metrics.averageResponseTime).color}`}>
                {metrics.averageResponseTime}ms
              </div>
              <div className="flex items-center gap-1 mt-1">
                <Badge variant="outline" className="text-xs">
                  Grade {getPerformanceGrade(metrics.averageResponseTime).grade}
                </Badge>
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardHeader className="pb-2">
              <CardTitle className="text-sm font-medium flex items-center gap-2">
                <Zap className="w-4 h-4" />
                Cache Hit Rate
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className={`text-2xl font-bold ${
                metrics.cacheHitRate >= 80 ? 'text-green-600' :
                metrics.cacheHitRate >= 60 ? 'text-yellow-600' : 'text-red-600'
              }`}>
                {metrics.cacheHitRate.toFixed(1)}%
              </div>
              <div className="flex items-center gap-1 mt-1">
                {metrics.cacheHitRate >= 80 ? (
                  <CheckCircle className="w-4 h-4 text-green-600" />
                ) : (
                  <AlertTriangle className="w-4 h-4 text-yellow-600" />
                )}
                <span className="text-xs text-gray-500">
                  {metrics.cacheHitRate >= 80 ? 'Excellent' : metrics.cacheHitRate >= 60 ? 'Good' : 'Needs Improvement'}
                </span>
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardHeader className="pb-2">
              <CardTitle className="text-sm font-medium flex items-center gap-2">
                <AlertTriangle className="w-4 h-4" />
                Error Rate
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className={`text-2xl font-bold ${
                metrics.errorRate <= 1 ? 'text-green-600' :
                metrics.errorRate <= 5 ? 'text-yellow-600' : 'text-red-600'
              }`}>
                {metrics.errorRate.toFixed(1)}%
              </div>
              <div className="flex items-center gap-1 mt-1">
                {metrics.errorRate <= 1 ? (
                  <CheckCircle className="w-4 h-4 text-green-600" />
                ) : metrics.errorRate <= 5 ? (
                  <AlertTriangle className="w-4 h-4 text-yellow-600" />
                ) : (
                  <AlertTriangle className="w-4 h-4 text-red-600" />
                )}
                <span className="text-xs text-gray-500">
                  {metrics.errorRate <= 1 ? 'Excellent' : metrics.errorRate <= 5 ? 'Acceptable' : 'Critical'}
                </span>
              </div>
            </CardContent>
          </Card>
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Endpoint Performance */}
        {metrics && (
          <Card>
            <CardHeader>
              <CardTitle>Endpoint Performance</CardTitle>
              <CardDescription>Performance breakdown by API endpoint</CardDescription>
            </CardHeader>
            <CardContent>
              <div className="space-y-4">
                {Object.entries(metrics.endpointStats).map(([endpoint, stats]) => (
                  <div key={endpoint} className="border rounded-lg p-4">
                    <div className="flex justify-between items-start mb-2">
                      <span className="font-medium text-sm">{endpoint}</span>
                      <Badge variant="outline" className="text-xs">
                        {stats.requests} requests
                      </Badge>
                    </div>
                    
                    <div className="grid grid-cols-3 gap-4 text-sm">
                      <div>
                        <span className="text-gray-500">Avg Time:</span>
                        <div className={`font-medium ${getPerformanceGrade(stats.averageResponseTime).color}`}>
                          {stats.averageResponseTime}ms
                        </div>
                      </div>
                      <div>
                        <span className="text-gray-500">Cache Hit:</span>
                        <div className="font-medium">{stats.cacheHitRate.toFixed(1)}%</div>
                      </div>
                      <div>
                        <span className="text-gray-500">Error Rate:</span>
                        <div className={`font-medium ${
                          stats.errorRate <= 1 ? 'text-green-600' : 
                          stats.errorRate <= 5 ? 'text-yellow-600' : 'text-red-600'
                        }`}>
                          {stats.errorRate.toFixed(1)}%
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>
        )}

        {/* Optimization Suggestions */}
        <Card>
          <CardHeader>
            <CardTitle>Optimization Suggestions</CardTitle>
            <CardDescription>Recommendations to improve API performance</CardDescription>
          </CardHeader>
          <CardContent>
            <div className="space-y-4">
              {suggestions.length === 0 ? (
                <div className="text-center py-8 text-gray-500">
                  <CheckCircle className="w-8 h-8 mx-auto mb-2 text-green-500" />
                  No optimization suggestions at this time
                </div>
              ) : (
                suggestions.map((suggestion, index) => (
                  <div 
                    key={index}
                    className={`border rounded-lg p-4 ${getPriorityColor(suggestion.priority)}`}
                  >
                    <div className="flex justify-between items-start mb-2">
                      <span className="font-medium text-sm">{suggestion.endpoint}</span>
                      <Badge 
                        variant="outline"
                        className={`text-xs ${getPriorityColor(suggestion.priority)}`}
                      >
                        {suggestion.priority.toUpperCase()}
                      </Badge>
                    </div>
                    
                    <div className="text-sm mb-2">
                      <strong>Issue:</strong> {suggestion.issue}
                    </div>
                    
                    <div className="text-sm">
                      <strong>Suggestion:</strong> {suggestion.suggestion}
                    </div>
                  </div>
                ))
              )}
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Performance Actions */}
      <Card>
        <CardHeader>
          <CardTitle>Performance Actions</CardTitle>
          <CardDescription>Tools to optimize system performance</CardDescription>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <Button
              variant="outline"
              onClick={() => clearCache()}
              disabled={isLoading}
              className="flex items-center gap-2"
            >
              <Zap className="w-4 h-4" />
              Clear All Cache
            </Button>
            
            <Button
              variant="outline"
              onClick={() => clearCache('routes')}
              disabled={isLoading}
              className="flex items-center gap-2"
            >
              <Server className="w-4 h-4" />
              Clear Routes Cache
            </Button>
            
            <Button
              variant="outline"
              onClick={optimizeDatabase}
              disabled={isLoading}
              className="flex items-center gap-2"
            >
              <Database className="w-4 h-4" />
              Optimize Database
            </Button>
          </div>
          
          {lastUpdate && (
            <div className="mt-4 text-sm text-gray-500 flex items-center gap-1">
              <Clock className="w-4 h-4" />
              Last updated: {lastUpdate.toLocaleTimeString()}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
};

export default PerformanceMonitorDashboard;

/**
 * Admin Route Cluster Map Component
 * Shows proposed multi-drop routes on an interactive map for admin preview
 */

'use client';

import React, { useEffect, useRef } from 'react';
import { Box } from '@chakra-ui/react';
import mapboxgl from 'mapbox-gl';
import 'mapbox-gl/dist/mapbox-gl.css';

interface AdminRouteClusterMapProps {
  routes: Array<{
    id: string;
    drops: Array<{
      lat: number;
      lng: number;
      address: string;
    }>;
    color?: string;
  }>;
  height?: string;
}

const AdminRouteClusterMap: React.FC<AdminRouteClusterMapProps> = ({ 
  routes, 
  height = '400px' 
}) => {
  const mapContainer = useRef<HTMLDivElement>(null);
  const map = useRef<mapboxgl.Map | null>(null);

  useEffect(() => {
    if (!mapContainer.current || map.current) return;

    const mapboxToken = 'pk.eyJ1IjoiYWhtYWRhbHdha2FpIiwiYSI6ImNtZGNsZ3RsZDEzdGsya3F0ODFxeGRzbXoifQ.jfgGW0KNFTwATOShRDtQsg';
    if (!mapboxToken) {
      console.error('❌ Mapbox token not found');
      return;
    }

    mapboxgl.accessToken = mapboxToken;

    // Initialize map
    map.current = new mapboxgl.Map({
      container: mapContainer.current,
      style: 'mapbox://styles/mapbox/dark-v11',
      center: [-3.435973, 55.378051], // UK center
      zoom: 6,
    });

    // Add navigation controls
    map.current.addControl(new mapboxgl.NavigationControl(), 'top-right');

    return () => {
      map.current?.remove();
      map.current = null;
    };
  }, []);

  useEffect(() => {
    if (!map.current || routes.length === 0) return;

    const colors = [
      '#9333EA', // Purple
      '#3B82F6', // Blue
      '#10B981', // Green
      '#F59E0B', // Orange
      '#EF4444', // Red
      '#8B5CF6', // Violet
      '#06B6D4', // Cyan
    ];

    // Clear existing markers and layers
    const markers = document.querySelectorAll('.mapboxgl-marker');
    markers.forEach(marker => marker.remove());

    // Add markers for each route
    routes.forEach((route, routeIndex) => {
      const color = route.color || colors[routeIndex % colors.length];

      route.drops.forEach((drop, dropIndex) => {
        // Create custom marker element
        const el = document.createElement('div');
        el.className = 'route-marker';
        el.style.width = '30px';
        el.style.height = '30px';
        el.style.borderRadius = '50%';
        el.style.backgroundColor = color;
        el.style.border = '3px solid white';
        el.style.display = 'flex';
        el.style.alignItems = 'center';
        el.style.justifyContent = 'center';
        el.style.color = 'white';
        el.style.fontWeight = 'bold';
        el.style.fontSize = '12px';
        el.style.cursor = 'pointer';
        el.style.boxShadow = '0 2px 8px rgba(0,0,0,0.3)';
        el.textContent = `${dropIndex + 1}`;

        // Add marker to map
        const marker = new mapboxgl.Marker(el)
          .setLngLat([drop.lng, drop.lat])
          .setPopup(
            new mapboxgl.Popup({ offset: 25 })
              .setHTML(`
                <div style="padding: 8px; color: #000;">
                  <strong>Route ${routeIndex + 1} - Stop ${dropIndex + 1}</strong>
                  <p style="margin: 4px 0 0 0; font-size: 12px;">${drop.address}</p>
                </div>
              `)
          )
          .addTo(map.current!);
      });
    });

    // Fit map to show all markers
    if (routes.length > 0 && routes[0].drops.length > 0) {
      const bounds = new mapboxgl.LngLatBounds();
      
      routes.forEach(route => {
        route.drops.forEach(drop => {
          bounds.extend([drop.lng, drop.lat]);
        });
      });

      map.current.fitBounds(bounds, {
        padding: 50,
        maxZoom: 12,
      });
    }
  }, [routes]);

  return (
    <Box
      ref={mapContainer}
      h={height}
      w="100%"
      borderRadius="md"
      overflow="hidden"
      border="2px solid"
      borderColor="purple.500"
      boxShadow="0 0 20px rgba(147, 51, 234, 0.3)"
      position="relative"
      sx={{
        '.mapboxgl-popup-content': {
          backgroundColor: 'white',
          borderRadius: '8px',
          padding: '0',
        },
        '.mapboxgl-popup-close-button': {
          fontSize: '18px',
          padding: '4px 8px',
        },
      }}
    />
  );
};

export default AdminRouteClusterMap;

/**
 * Route Preview Modal Component
 * 
 * Shows route preview with map, stops, metrics, and approval/rejection buttons
 * before dispatching to driver
 */

'use client';

import React, { useState, useEffect } from 'react';
import {
  Modal,
  ModalOverlay,
  ModalContent,
  ModalHeader,
  ModalBody,
  ModalFooter,
  ModalCloseButton,
  Button,
  VStack,
  HStack,
  Text,
  Badge,
  Box,
  Divider,
  Stat,
  StatLabel,
  StatNumber,
  StatHelpText,
  SimpleGrid,
  Alert,
  AlertIcon,
  Select,
  Textarea,
  useToast,
  Icon,
  Table,
  Thead,
  Tbody,
  Tr,
  Th,
  Td,
  Spinner,
} from '@chakra-ui/react';
import {
  FaRoute,
  FaClock,
  FaMapMarkerAlt,
  FaPoundSign,
  FaTruck,
  FaCheckCircle,
  FaTimesCircle,
  FaExclamationTriangle,
} from 'react-icons/fa';
import { format } from 'date-fns';

interface RoutePreviewModalProps {
  isOpen: boolean;
  onClose: () => void;
  routeId?: string;
  bookingIds?: string[];
  onApprove?: (routeId: string, driverId?: string) => void;
  onReject?: (routeId: string, reason: string) => void;
  mode?: 'approval' | 'preview'; // approval = route already created, preview = create new
}

interface RoutePreviewData {
  estimatedDuration: number; // minutes
  estimatedDistance: number; // km
  totalDrops: number;
  totalValue: number; // pence
  stops: Array<{
    sequence: number;
    address: string;
    lat: number;
    lng: number;
    type: 'pickup' | 'delivery';
    estimatedTime: Date;
  }>;
  driver?: {
    id: string;
    name: string;
    currentLoad: number;
  };
  warnings: string[];
}

interface ApprovalData {
  id: string;
  routeId: string;
  status: string;
  submittedBy: string;
  submittedAt: string;
  autoGenerated: boolean;
  estimatedDuration: number;
  estimatedDistance: number;
  totalDrops: number;
  totalValue: number;
  routePreview: any;
}

export default function RoutePreviewModal({
  isOpen,
  onClose,
  routeId,
  bookingIds,
  onApprove,
  onReject,
  mode = 'preview',
}: RoutePreviewModalProps) {
  const [loading, setLoading] = useState(false);
  const [preview, setPreview] = useState<RoutePreviewData | null>(null);
  const [approval, setApproval] = useState<ApprovalData | null>(null);
  const [selectedDriver, setSelectedDriver] = useState<string>('');
  const [drivers, setDrivers] = useState<any[]>([]);
  const [rejectionReason, setRejectionReason] = useState('');
  const [isApproving, setIsApproving] = useState(false);
  const [isRejecting, setIsRejecting] = useState(false);
  const toast = useToast();

  useEffect(() => {
    if (isOpen) {
      if (mode === 'approval' && routeId) {
        loadApprovalData();
      } else if (mode === 'preview' && bookingIds?.length) {
        generatePreview();
      }
      loadAvailableDrivers();
    }
  }, [isOpen, routeId, bookingIds, mode]);

  const loadApprovalData = async () => {
    if (!routeId) return;

    setLoading(true);
    try {
      const response = await fetch('/api/admin/routing/approve');
      const data = await response.json();

      if (data.success) {
        const approval = data.data.find((a: any) => a.routeId === routeId);
        if (approval) {
          setApproval(approval);
          if (approval.routePreview) {
            setPreview(approval.routePreview);
          }
        }
      }
    } catch (error) {
      console.error('Failed to load approval data:', error);
      toast({
        title: 'Error',
        description: 'Failed to load route approval data',
        status: 'error',
        duration: 5000,
      });
    } finally {
      setLoading(false);
    }
  };

  const generatePreview = async () => {
    if (!bookingIds?.length) return;

    setLoading(true);
    try {
      const response = await fetch('/api/admin/routing/manual/preview', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ bookingIds }),
      });

      const data = await response.json();

      if (data.success) {
        setPreview(data.data);
      } else {
        throw new Error(data.error || 'Failed to generate preview');
      }
    } catch (error) {
      console.error('Failed to generate preview:', error);
      toast({
        title: 'Error',
        description: error instanceof Error ? error.message : 'Failed to generate preview',
        status: 'error',
        duration: 5000,
      });
    } finally {
      setLoading(false);
    }
  };

  const loadAvailableDrivers = async () => {
    try {
      const response = await fetch('/api/admin/drivers?status=active&available=true');
      const data = await response.json();

      if (data.success) {
        setDrivers(data.data || []);
      }
    } catch (error) {
      console.error('Failed to load drivers:', error);
    }
  };

  const handleApprove = async () => {
    if (!routeId) return;

    setIsApproving(true);
    try {
      if (onApprove) {
        await onApprove(routeId, selectedDriver || undefined);
      } else {
        const response = await fetch('/api/admin/routing/approve', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ routeId, driverId: selectedDriver || undefined }),
        });

        const data = await response.json();

        if (!data.success) {
          throw new Error(data.error || 'Failed to approve route');
        }
      }

      toast({
        title: 'Route Approved',
        description: 'Route has been approved and dispatched to driver',
        status: 'success',
        duration: 5000,
      });

      onClose();
    } catch (error) {
      toast({
        title: 'Error',
        description: error instanceof Error ? error.message : 'Failed to approve route',
        status: 'error',
        duration: 5000,
      });
    } finally {
      setIsApproving(false);
    }
  };

  const handleReject = async () => {
    if (!routeId || !rejectionReason.trim()) {
      toast({
        title: 'Error',
        description: 'Please provide a rejection reason',
        status: 'error',
        duration: 3000,
      });
      return;
    }

    setIsRejecting(true);
    try {
      if (onReject) {
        await onReject(routeId, rejectionReason);
      } else {
        const response = await fetch('/api/admin/routing/approve', {
          method: 'DELETE',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ routeId, reason: rejectionReason }),
        });

        const data = await response.json();

        if (!data.success) {
          throw new Error(data.error || 'Failed to reject route');
        }
      }

      toast({
        title: 'Route Rejected',
        description: 'Route has been rejected and released',
        status: 'success',
        duration: 5000,
      });

      onClose();
    } catch (error) {
      toast({
        title: 'Error',
        description: error instanceof Error ? error.message : 'Failed to reject route',
        status: 'error',
        duration: 5000,
      });
    } finally {
      setIsRejecting(false);
    }
  };

  const formatCurrency = (pence: number) => {
    return `£${(pence / 100).toFixed(2)}`;
  };

  const formatDuration = (minutes: number) => {
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    return hours > 0 ? `${hours}h ${mins}m` : `${mins}m`;
  };

  return (
    <Modal isOpen={isOpen} onClose={onClose} size="4xl" scrollBehavior="inside">
      <ModalOverlay />
      <ModalContent>
        <ModalHeader>
          <HStack>
            <Icon as={FaRoute} color="blue.500" />
            <Text>Route Preview & Approval</Text>
            {mode === 'approval' && approval && (
              <Badge colorScheme={approval.autoGenerated ? 'purple' : 'blue'}>
                {approval.autoGenerated ? 'Auto-Generated' : 'Manual'}
              </Badge>
            )}
          </HStack>
        </ModalHeader>
        <ModalCloseButton />

        <ModalBody>
          {loading ? (
            <HStack justify="center" py={10}>
              <Spinner size="lg" />
              <Text>Loading route preview...</Text>
            </HStack>
          ) : preview ? (
            <VStack align="stretch" spacing={6}>
              {/* Warnings */}
              {preview.warnings.length > 0 && (
                <Alert status="warning">
                  <AlertIcon />
                  <VStack align="start" spacing={1}>
                    {preview.warnings.map((warning, index) => (
                      <Text key={index} fontSize="sm">
                        {warning}
                      </Text>
                    ))}
                  </VStack>
                </Alert>
              )}

              {/* Route Metrics */}
              <SimpleGrid columns={4} spacing={4}>
                <Stat>
                  <StatLabel>
                    <HStack>
                      <Icon as={FaMapMarkerAlt} />
                      <Text>Total Stops</Text>
                    </HStack>
                  </StatLabel>
                  <StatNumber>{preview.totalDrops}</StatNumber>
                </Stat>

                <Stat>
                  <StatLabel>
                    <HStack>
                      <Icon as={FaClock} />
                      <Text>Duration</Text>
                    </HStack>
                  </StatLabel>
                  <StatNumber>{formatDuration(preview.estimatedDuration)}</StatNumber>
                </Stat>

                <Stat>
                  <StatLabel>
                    <HStack>
                      <Icon as={FaRoute} />
                      <Text>Distance</Text>
                    </HStack>
                  </StatLabel>
                  <StatNumber>{preview.estimatedDistance.toFixed(1)} km</StatNumber>
                </Stat>

                <Stat>
                  <StatLabel>
                    <HStack>
                      <Icon as={FaPoundSign} />
                      <Text>Total Value</Text>
                    </HStack>
                  </StatLabel>
                  <StatNumber>{formatCurrency(preview.totalValue)}</StatNumber>
                </Stat>
              </SimpleGrid>

              <Divider />

              {/* Route Stops */}
              <Box>
                <Text fontWeight="bold" mb={3}>
                  Route Stops
                </Text>
                <Box maxH="300px" overflowY="auto">
                  <Table size="sm" variant="simple">
                    <Thead position="sticky" top={0} bg="gray.800" zIndex={1}>
                      <Tr>
                        <Th width="60px">#</Th>
                        <Th width="100px">Type</Th>
                        <Th>Address</Th>
                        <Th width="120px">Est. Time</Th>
                      </Tr>
                    </Thead>
                    <Tbody>
                      {preview.stops.map((stop, index) => (
                        <Tr key={index}>
                          <Td fontWeight="bold">{stop.sequence}</Td>
                          <Td>
                            <Badge
                              colorScheme={stop.type === 'pickup' ? 'blue' : 'green'}
                            >
                              {stop.type}
                            </Badge>
                          </Td>
                          <Td fontSize="sm">{stop.address}</Td>
                          <Td fontSize="sm">
                            {format(new Date(stop.estimatedTime), 'HH:mm')}
                          </Td>
                        </Tr>
                      ))}
                    </Tbody>
                  </Table>
                </Box>
              </Box>

              <Divider />

              {/* Driver Assignment */}
              <Box>
                <Text fontWeight="bold" mb={3}>
                  Assign Driver (Optional)
                </Text>
                {preview.driver ? (
                  <Alert status="info">
                    <AlertIcon />
                    <VStack align="start" spacing={0}>
                      <Text fontWeight="medium">{preview.driver.name}</Text>
                      <Text fontSize="sm">Current Load: {preview.driver.currentLoad} jobs</Text>
                    </VStack>
                  </Alert>
                ) : (
                  <Select
                    placeholder="Select driver or leave unassigned"
                    value={selectedDriver}
                    onChange={(e) => setSelectedDriver(e.target.value)}
                  >
                    {drivers.map((driver) => (
                      <option key={driver.id} value={driver.id}>
                        {driver.name} - {driver.currentJobs || 0} active jobs
                      </option>
                    ))}
                  </Select>
                )}
              </Box>

              {/* Rejection Reason (only shown when rejecting) */}
              {isRejecting && (
                <Box>
                  <Text fontWeight="bold" mb={3}>
                    Rejection Reason *
                  </Text>
                  <Textarea
                    placeholder="Why are you rejecting this route?"
                    value={rejectionReason}
                    onChange={(e) => setRejectionReason(e.target.value)}
                    rows={3}
                  />
                </Box>
              )}
            </VStack>
          ) : (
            <Alert status="error">
              <AlertIcon />
              No preview data available
            </Alert>
          )}
        </ModalBody>

        <ModalFooter>
          <HStack spacing={3}>
            <Button variant="ghost" onClick={onClose}>
              Cancel
            </Button>
            
            {mode === 'approval' && (
              <>
                <Button
                  colorScheme="red"
                  leftIcon={<FaTimesCircle />}
                  onClick={() => setIsRejecting(true)}
                  isDisabled={isApproving || !preview}
                  display={isRejecting ? 'none' : 'flex'}
                >
                  Reject
                </Button>

                {isRejecting && (
                  <Button
                    colorScheme="red"
                    leftIcon={<FaTimesCircle />}
                    onClick={handleReject}
                    isLoading={isRejecting}
                  >
                    Confirm Rejection
                  </Button>
                )}

                <Button
                  colorScheme="green"
                  leftIcon={<FaCheckCircle />}
                  onClick={handleApprove}
                  isLoading={isApproving}
                  isDisabled={isRejecting || !preview}
                >
                  Approve & Dispatch
                </Button>
              </>
            )}

            {mode === 'preview' && (
              <Button
                colorScheme="blue"
                leftIcon={<FaCheckCircle />}
                onClick={handleApprove}
                isLoading={isApproving}
                isDisabled={!preview}
              >
                Create Route
              </Button>
            )}
          </HStack>
        </ModalFooter>
      </ModalContent>
    </Modal>
  );
}

/**
 * Routing Mode Toggle Component
 * 
 * Toggle switch to control Auto/Manual routing modes
 * Displays in Admin Dashboard with real-time status
 */

'use client';

import React, { useState, useEffect } from 'react';
import {
  Box,
  Switch,
  HStack,
  VStack,
  Text,
  Badge,
  Icon,
  Button,
  useToast,
  Tooltip,
  Card,
  CardBody,
  Spinner,
  Modal,
  ModalOverlay,
  ModalContent,
  ModalHeader,
  ModalBody,
  ModalFooter,
  ModalCloseButton,
  useDisclosure,
  Alert,
  AlertIcon,
} from '@chakra-ui/react';
import { FaRobot, FaUserCog, FaPlay, FaCog, FaHistory, FaClock } from 'react-icons/fa';
import { formatDistanceToNow } from 'date-fns';

interface RoutingConfig {
  routingMode: 'auto' | 'manual';
  autoRoutingEnabled: boolean;
  autoRoutingIntervalMin: number;
  maxDropsPerRoute: number;
  maxRouteDistanceKm: number;
  autoAssignDrivers: boolean;
  requireAdminApproval: boolean;
  minDropsForAutoRoute: number;
}

interface CronStatus {
  enabled: boolean;
  intervalMinutes: number;
  lastRun?: string;
  nextRun?: string;
  recentRuns: Array<{
    timestamp: string;
    result: string;
    details: any;
  }>;
}

export default function RoutingModeToggle() {
  const [config, setConfig] = useState<RoutingConfig | null>(null);
  const [cronStatus, setCronStatus] = useState<CronStatus | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [isSwitching, setIsSwitching] = useState(false);
  const [isTriggering, setIsTriggering] = useState(false);
  const toast = useToast();
  const { isOpen, onOpen, onClose } = useDisclosure();

  useEffect(() => {
    loadConfig();
    loadCronStatus();
    
    // Refresh every 30 seconds
    const interval = setInterval(() => {
      loadConfig();
      loadCronStatus();
    }, 30000);

    return () => clearInterval(interval);
  }, []);

  const loadConfig = async () => {
    try {
      const response = await fetch('/api/admin/routing/settings');
      const data = await response.json();
      
      if (data.success) {
        setConfig(data.data);
      }
    } catch (error) {
      console.error('Failed to load routing config:', error);
    } finally {
      setIsLoading(false);
    }
  };

  const loadCronStatus = async () => {
    try {
      const response = await fetch('/api/admin/routing/cron');
      const data = await response.json();
      
      if (data.success) {
        setCronStatus(data.data);
      }
    } catch (error) {
      console.error('Failed to load cron status:', error);
    }
  };

  const handleToggle = async () => {
    if (!config) return;

    const newMode = config.routingMode === 'auto' ? 'manual' : 'auto';
    setIsSwitching(true);

    try {
      const response = await fetch('/api/admin/routing/settings/mode', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ mode: newMode }),
      });

      const data = await response.json();

      if (data.success) {
        toast({
          title: 'Success',
          description: `Routing mode switched to ${newMode.toUpperCase()}`,
          status: 'success',
          duration: 3000,
        });
        await loadConfig();
      } else {
        throw new Error(data.error || 'Failed to switch mode');
      }
    } catch (error) {
      toast({
        title: 'Error',
        description: error instanceof Error ? error.message : 'Failed to switch routing mode',
        status: 'error',
        duration: 5000,
      });
    } finally {
      setIsSwitching(false);
    }
  };

  const handleTriggerAutoRouting = async () => {
    setIsTriggering(true);

    try {
      const response = await fetch('/api/admin/routing/trigger', {
        method: 'POST',
      });

      const data = await response.json();

      if (data.success) {
        toast({
          title: 'Auto-Routing Triggered',
          description: data.message,
          status: 'success',
          duration: 5000,
        });
        await loadConfig();
        await loadCronStatus();
      } else {
        throw new Error(data.error || 'Failed to trigger auto-routing');
      }
    } catch (error) {
      toast({
        title: 'Error',
        description: error instanceof Error ? error.message : 'Failed to trigger auto-routing',
        status: 'error',
        duration: 5000,
      });
    } finally {
      setIsTriggering(false);
    }
  };

  if (isLoading) {
    return (
      <Card>
        <CardBody>
          <HStack justify="center" py={4}>
            <Spinner size="sm" />
            <Text>Loading routing configuration...</Text>
          </HStack>
        </CardBody>
      </Card>
    );
  }

  if (!config) {
    return null;
  }

  const isAutoMode = config.routingMode === 'auto';

  return (
    <>
      <Card 
        bg={isAutoMode ? 'blue.50' : 'gray.50'} 
        borderWidth={2}
        borderColor={isAutoMode ? 'blue.400' : 'gray.300'}
      >
        <CardBody>
          <VStack align="stretch" spacing={4}>
            {/* Main Toggle */}
            <HStack justify="space-between">
              <HStack spacing={3}>
                <Icon
                  as={isAutoMode ? FaRobot : FaUserCog}
                  boxSize={6}
                  color={isAutoMode ? 'blue.500' : 'gray.600'}
                />
                <VStack align="start" spacing={0}>
                  <HStack>
                    <Text fontWeight="bold" fontSize="lg">
                      Routing Mode
                    </Text>
                    <Badge
                      colorScheme={isAutoMode ? 'blue' : 'gray'}
                      fontSize="sm"
                      px={2}
                      py={1}
                    >
                      {isAutoMode ? 'AUTO' : 'MANUAL'}
                    </Badge>
                  </HStack>
                  <Text fontSize="sm" color="gray.600">
                    {isAutoMode
                      ? 'System automatically creates optimized routes'
                      : 'Admin manually creates routes from orders'}
                  </Text>
                </VStack>
              </HStack>

              <Tooltip label={isSwitching ? 'Switching...' : `Switch to ${isAutoMode ? 'Manual' : 'Auto'} mode`}>
                <Switch
                  size="lg"
                  colorScheme="blue"
                  isChecked={isAutoMode}
                  onChange={handleToggle}
                  isDisabled={isSwitching}
                />
              </Tooltip>
            </HStack>

            {/* Auto Mode Details */}
            {isAutoMode && (
              <Box 
                bg="gray.800" 
                p={4} 
                borderRadius="md" 
                borderWidth={1}
                borderColor="blue.200"
              >
                <VStack align="stretch" spacing={3}>
                  <HStack justify="space-between">
                    <HStack>
                      <Icon as={FaClock} color="blue.500" />
                      <Text fontSize="sm" fontWeight="medium">
                        Auto-Routing Status
                      </Text>
                    </HStack>
                    <Badge colorScheme={cronStatus?.enabled ? 'green' : 'red'}>
                      {cronStatus?.enabled ? 'ACTIVE' : 'DISABLED'}
                    </Badge>
                  </HStack>

                  {cronStatus && (
                    <>
                      <HStack justify="space-between" fontSize="sm">
                        <Text color="gray.600">Interval:</Text>
                        <Text fontWeight="medium">Every {cronStatus.intervalMinutes} minutes</Text>
                      </HStack>

                      {cronStatus.lastRun && (
                        <HStack justify="space-between" fontSize="sm">
                          <Text color="gray.600">Last Run:</Text>
                          <Text fontWeight="medium">
                            {formatDistanceToNow(new Date(cronStatus.lastRun), { addSuffix: true })}
                          </Text>
                        </HStack>
                      )}

                      {cronStatus.nextRun && (
                        <HStack justify="space-between" fontSize="sm">
                          <Text color="gray.600">Next Run:</Text>
                          <Text fontWeight="medium">
                            {formatDistanceToNow(new Date(cronStatus.nextRun), { addSuffix: true })}
                          </Text>
                        </HStack>
                      )}
                    </>
                  )}

                  <HStack spacing={2} pt={2}>
                    <Button
                      size="sm"
                      colorScheme="blue"
                      leftIcon={<FaPlay />}
                      onClick={handleTriggerAutoRouting}
                      isLoading={isTriggering}
                      loadingText="Running..."
                    >
                      Trigger Now
                    </Button>
                    <Button
                      size="sm"
                      variant="outline"
                      leftIcon={<FaCog />}
                      onClick={onOpen}
                    >
                      Settings
                    </Button>
                    <Button
                      size="sm"
                      variant="outline"
                      leftIcon={<FaHistory />}
                      onClick={() => window.open('/admin/logs?type=auto_routing', '_blank')}
                    >
                      History
                    </Button>
                  </HStack>
                </VStack>
              </Box>
            )}

            {/* Manual Mode Info */}
            {!isAutoMode && (
              <Alert status="info" borderRadius="md">
                <AlertIcon />
                <Text fontSize="sm">
                  Manual mode active. Create routes from Orders page by selecting bookings and clicking "Create Route".
                </Text>
              </Alert>
            )}
          </VStack>
        </CardBody>
      </Card>

      {/* Settings Modal */}
      <Modal isOpen={isOpen} onClose={onClose} size="lg">
        <ModalOverlay />
        <ModalContent>
          <ModalHeader>Auto-Routing Settings</ModalHeader>
          <ModalCloseButton />
          <ModalBody>
            <VStack align="stretch" spacing={4}>
              <Box>
                <Text fontSize="sm" fontWeight="medium" mb={2}>
                  Configuration
                </Text>
                <VStack align="stretch" spacing={2} pl={4}>
                  <HStack justify="space-between" fontSize="sm">
                    <Text color="gray.600">Max Drops per Route:</Text>
                    <Text fontWeight="medium">{config.maxDropsPerRoute}</Text>
                  </HStack>
                  <HStack justify="space-between" fontSize="sm">
                    <Text color="gray.600">Max Route Distance:</Text>
                    <Text fontWeight="medium">{config.maxRouteDistanceKm} km</Text>
                  </HStack>
                  <HStack justify="space-between" fontSize="sm">
                    <Text color="gray.600">Min Drops for Auto:</Text>
                    <Text fontWeight="medium">{config.minDropsForAutoRoute}</Text>
                  </HStack>
                  <HStack justify="space-between" fontSize="sm">
                    <Text color="gray.600">Auto-Assign Drivers:</Text>
                    <Badge colorScheme={config.autoAssignDrivers ? 'green' : 'gray'}>
                      {config.autoAssignDrivers ? 'YES' : 'NO'}
                    </Badge>
                  </HStack>
                  <HStack justify="space-between" fontSize="sm">
                    <Text color="gray.600">Require Admin Approval:</Text>
                    <Badge colorScheme={config.requireAdminApproval ? 'orange' : 'green'}>
                      {config.requireAdminApproval ? 'YES' : 'NO'}
                    </Badge>
                  </HStack>
                </VStack>
              </Box>

              <Alert status="warning" fontSize="sm">
                <AlertIcon />
                To modify these settings, go to Settings → Orders Management
              </Alert>
            </VStack>
          </ModalBody>
          <ModalFooter>
            <Button onClick={onClose}>Close</Button>
          </ModalFooter>
        </ModalContent>
      </Modal>
    </>
  );
}

/**
 * Smart Route Generator Modal
 * Intelligent auto-route creation with preview and driver selection
 */

'use client';

import React, { useState, useEffect, useCallback } from 'react';
import {
  Modal,
  ModalOverlay,
  ModalContent,
  ModalHeader,
  ModalBody,
  ModalFooter,
  ModalCloseButton,
  Button,
  VStack,
  HStack,
  Box,
  Text,
  Badge,
  FormControl,
  FormLabel,
  Input,
  Select,
  Checkbox,
  Divider,
  Progress,
  Grid,
  Card,
  CardBody,
  Table,
  Thead,
  Tbody,
  Tr,
  Th,
  Td,
  Icon,
  Spinner,
  Alert,
  AlertIcon,
  AlertTitle,
  AlertDescription,
  Stat,
  StatLabel,
  StatNumber,
  StatHelpText,
  Tabs,
  TabList,
  TabPanels,
  Tab,
  TabPanel,
  useToast,
} from '@chakra-ui/react';
import {
  FiMapPin,
  FiPackage,
  FiClock,
  FiTruck,
  FiUser,
  FiCheck,
  FiAlertCircle,
  FiZap,
  FiEye,
  FiSettings,
  FiMap,
} from 'react-icons/fi';
import dynamic from 'next/dynamic';

// Lazy load map component for better performance
const AdminRouteClusterMap = dynamic(() => import('./RoutePreviewMap'), {
  ssr: false,
  loading: () => (
    <Box 
      h="400px" 
      bg="gray.900" 
      borderRadius="md" 
      display="flex" 
      alignItems="center" 
      justifyContent="center"
      borderWidth="2px"
      borderColor="gray.700"
    >
      <Spinner size="xl" color="purple.400" />
    </Box>
  )
});

interface PendingDrop {
  id: string;
  bookingId?: string | null;
  pickupAddress: string;
  deliveryAddress: string;
  timeWindowStart: Date;
  timeWindowEnd: Date;
  quotedPrice: number;
  weight: number;
  volume: number;
  serviceTier: string;
  customerName?: string;
}

interface AvailableDriver {
  id: string;
  name: string;
  email: string;
  status: string;
  onboardingStatus: string;
  rating?: number;
  activeRoutes?: number;
  DriverAvailability: {
    status: string;
    lastSeenAt?: Date;
    location?: {
      lat: number;
      lng: number;
    } | null;
    hasRecord: boolean;
  };
  activeJobs: Array<any>;
  isAvailable: boolean;
  totalActiveJobs: number;
  availabilityReason: string;
}

interface ProposedRoute {
  id: string;
  drops: string[];
  driverId?: string;
  driverName?: string;
  totalDrops: number;
  estimatedDistance: number;
  estimatedDuration: number;
  totalValue: number;
}

interface SmartRouteGeneratorModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSuccess: () => void;
}

const SmartRouteGeneratorModal: React.FC<SmartRouteGeneratorModalProps> = ({
  isOpen,
  onClose,
  onSuccess,
}) => {
  const toast = useToast();
  const [step, setStep] = useState<'config' | 'preview' | 'creating'>('config');
  
  // Configuration
  const [maxDropsPerRoute, setMaxDropsPerRoute] = useState(10);
  const [maxDistanceMiles, setMaxDistanceMiles] = useState(50);
  const [optimizeBy, setOptimizeBy] = useState<'distance' | 'time' | 'area'>('distance');
  const [autoAssign, setAutoAssign] = useState(true);
  const [selectedDriverIds, setSelectedDriverIds] = useState<string[]>([]);
  const [includePendingPayment, setIncludePendingPayment] = useState(true); // Include PENDING_PAYMENT bookings
  
  // Data
  const [pendingDrops, setPendingDrops] = useState<PendingDrop[]>([]);
  const [availableDrivers, setAvailableDrivers] = useState<AvailableDriver[]>([]);
  const [proposedRoutes, setProposedRoutes] = useState<ProposedRoute[]>([]);
  const [selectedRouteIds, setSelectedRouteIds] = useState<string[]>([]);
  const [pendingRoutes, setPendingRoutes] = useState<any[]>([]); // Routes without drivers
  
  // Loading states
  const [isLoadingDrops, setIsLoadingDrops] = useState(false);
  const [isLoadingDrivers, setIsLoadingDrivers] = useState(false);
  const [isGeneratingPreview, setIsGeneratingPreview] = useState(false);
  const [isCreatingRoutes, setIsCreatingRoutes] = useState(false);

  // Fetch pending drops
  const fetchPendingDrops = useCallback(async () => {
    setIsLoadingDrops(true);
    try {
      const url = `/api/admin/routes/pending-drops?includePendingPayment=${includePendingPayment}`;
      const response = await fetch(url);
      const data = await response.json();
      if (data.success) {
        // Ensure all drops have bookingId for route creation
        const dropsWithBookingIds = (data.drops || []).map((drop: any) => ({
          ...drop,
          bookingId: drop.bookingId || drop.id, // Use drop.id as fallback if bookingId is missing
        }));
        setPendingDrops(dropsWithBookingIds);
        console.log(`📦 Loaded ${dropsWithBookingIds.length} pending drops`);
      }
    } catch (error) {
      console.error('Failed to fetch pending drops:', error);
      toast({
        title: 'Error',
        description: 'Failed to load pending drops',
        status: 'error',
        duration: 3000,
      });
    } finally {
      setIsLoadingDrops(false);
    }
  }, [toast, includePendingPayment]);

  // Fetch available drivers
  const fetchAvailableDrivers = useCallback(async () => {
    setIsLoadingDrivers(true);
    try {
      const response = await fetch('/api/admin/drivers/available');
      const data = await response.json();
      console.log('📊 Available drivers API response:', data);
      if (data.success) {
        // API returns data in data.data.drivers structure
        const drivers = data.data?.drivers || data.drivers || [];
        console.log('✅ Loaded drivers:', drivers.length, 'Total:', drivers);
        setAvailableDrivers(drivers);
      }
    } catch (error) {
      console.error('Failed to fetch available drivers:', error);
      toast({
        title: 'Error',
        description: 'Failed to load available drivers',
        status: 'error',
        duration: 3000,
      });
    } finally {
      setIsLoadingDrivers(false);
    }
  }, [toast]);

  // Fetch pending routes (routes without drivers)
  const fetchPendingRoutes = useCallback(async () => {
    try {
      const response = await fetch('/api/admin/routes?status=pending_assignment');
      const data = await response.json();
      if (data.success) {
        // Filter out empty routes (0 drops or invalid data)
        const validRoutes = (data.routes || []).filter((route: any) => 
          route.totalDrops > 0 && 
          Number.isFinite(route.totalOutcome) &&
          route.totalOutcome > 0
        );
        setPendingRoutes(validRoutes);
        console.log(`📊 Loaded ${validRoutes.length} valid pending routes (filtered ${(data.routes?.length || 0) - validRoutes.length} empty routes)`);
      }
    } catch (error) {
      console.error('Failed to fetch pending routes:', error);
    }
  }, []);

  // Load data when modal opens
useEffect(() => {
  if (isOpen) {
    console.log('📂 Modal opened - loading data...');
    fetchPendingDrops();
    fetchAvailableDrivers();
    fetchPendingRoutes();
    setStep('config');
    setProposedRoutes([]);
    setSelectedRouteIds([]);
  }
}, [isOpen, fetchPendingDrops, fetchAvailableDrivers, fetchPendingRoutes]);

  // Generate preview
  const generatePreview = async () => {
    setIsGeneratingPreview(true);
    try {
      const response = await fetch('/api/admin/routes/preview', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          maxDropsPerRoute,
          maxDistanceKm: maxDistanceMiles, // Send as maxDistanceKm for API compatibility
          optimizeBy,
          autoAssign,
          driverIds: autoAssign ? [] : selectedDriverIds,
          includePendingPayment, // Include PENDING_PAYMENT filter
        }),
      });

      const data = await response.json();
      if (data.success) {
        const routes = data.proposedRoutes || [];
        setProposedRoutes(routes);
        setSelectedRouteIds(routes.map((route: ProposedRoute) => route.id));
        setStep('preview');
      } else {
        toast({
          title: 'Preview Failed',
          description: data.message || 'Failed to generate route preview',
          status: 'error',
          duration: 5000,
        });
      }
    } catch (error) {
      console.error('Failed to generate preview:', error);
      toast({
        title: 'Error',
        description: 'Failed to generate route preview',
        status: 'error',
        duration: 3000,
      });
    } finally {
      setIsGeneratingPreview(false);
    }
  };

  // Create routes from selected previews
  const createRoutes = async () => {
    setIsCreatingRoutes(true);
    setStep('creating');

    try {
      const routesToCreate = proposedRoutes.filter(route => selectedRouteIds.includes(route.id));

      if (routesToCreate.length === 0) {
        toast({
          title: 'No Routes Selected',
          description: 'Select at least one route from the preview before confirming.',
          status: 'warning',
          duration: 4000,
        });
        setIsCreatingRoutes(false);
        setStep('preview');
        return;
      }

      console.log(`📦 Creating ${routesToCreate.length} selected route(s)`);
      const creationResults: { id: string; success: boolean; message?: string }[] = [];

      for (const route of routesToCreate) {
        const bookingIds = route.drops
          .map(dropId => pendingDrops.find(drop => drop.id === dropId)?.bookingId)
          .filter((id): id is string => Boolean(id));

        if (bookingIds.length === 0) {
          console.warn(`⚠️ [SmartRouteGenerator] Route ${route.id} has no valid booking IDs`);
          creationResults.push({
            id: route.id,
            success: false,
            message: 'No valid bookings in this cluster',
          });
          continue;
        }

        let finalDriverId: string | undefined = route.driverId;

        if (!finalDriverId) {
          if (selectedDriverIds.length > 0) {
            finalDriverId = selectedDriverIds[0];
          } else if (autoAssign && availableDrivers.length > 0) {
            const onlineDrivers = availableDrivers.filter(d =>
              d.DriverAvailability?.status === 'online' || d.isAvailable
            );

            if (onlineDrivers.length > 0) {
              const bestDriver = [...onlineDrivers].sort((a, b) =>
                (a.activeRoutes || 0) - (b.activeRoutes || 0)
              )[0];
              finalDriverId = bestDriver.id;
            }
          }
        }

        console.log('🚀 [SmartRouteGenerator] Creating route cluster:', {
          routeId: route.id,
          bookingCount: bookingIds.length,
          driverId: finalDriverId,
        });

        const response = await fetch('/api/admin/routes/create', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            bookingIds,
            driverId: finalDriverId,
            startTime: new Date().toISOString(),
            isAutomatic: true,
          }),
        });

        const data = await response.json();
        console.log(`📊 Create route response [${route.id}]:`, data);

        if (response.ok && data.success) {
          creationResults.push({ id: route.id, success: true });
        } else {
          creationResults.push({
            id: route.id,
            success: false,
            message: data.details || data.error || 'Failed to create route',
          });
        }
      }

      const successCount = creationResults.filter(r => r.success).length;
      const failureCount = creationResults.length - successCount;

      if (successCount > 0) {
        toast({
          title: `🎉 ${successCount} route(s) created`,
          description: failureCount > 0
            ? `${failureCount} route(s) failed. Check console for details.`
            : 'All selected routes were created successfully.',
          status: failureCount > 0 ? 'warning' : 'success',
          duration: 6000,
          isClosable: true,
        });
        onSuccess();
        handleClose();
      } else {
        toast({
          title: 'Creation Failed',
          description: creationResults.map(r => r.message).filter(Boolean).join('\n') || 'Failed to create selected routes.',
          status: 'error',
          duration: 6000,
          isClosable: true,
        });
        setStep('preview');
      }
    } catch (error) {
      console.error('Failed to create routes:', error);
      toast({
        title: 'Error',
        description: 'Failed to create routes',
        status: 'error',
        duration: 3000,
      });
      setStep('preview');
    } finally {
      setIsCreatingRoutes(false);
    }
  };

// Initialize data when modal opens
useEffect(() => {
  if (isOpen) {
    fetchPendingDrops();
    fetchAvailableDrivers();
    fetchPendingRoutes();
    setStep('config');
    setProposedRoutes([]);
    setSelectedRouteIds([]);
  }
}, [isOpen, fetchPendingDrops, fetchAvailableDrivers, fetchPendingRoutes]);

const handleClose = () => {
  setStep('config');
  setProposedRoutes([]);
  setSelectedRouteIds([]);
  onClose();
};

  const handleDriverToggle = (driverId: string) => {
    setSelectedDriverIds(prev => 
      prev.includes(driverId)
        ? prev.filter(id => id !== driverId)
        : [...prev, driverId]
    );
  };

  // Calculate summary stats (with validation)
  const totalPendingVolume = pendingDrops.reduce((sum, drop) => sum + drop.volume, 0);
  const totalPendingValue = pendingDrops.reduce((sum, drop) => {
    const price = Number(drop.quotedPrice || 0);
    return (Number.isFinite(price) && price >= 0 && price <= Number.MAX_SAFE_INTEGER) ? sum + price : sum;
  }, 0);
  const onlineDrivers = availableDrivers.filter(d => d.DriverAvailability?.status === 'online' || d.isAvailable).length;
  const totalPendingRoutesValue = pendingRoutes.reduce((sum, route) => {
    const value = Number(route.totalOutcome || 0);
    return (Number.isFinite(value) && value >= 0 && value <= Number.MAX_SAFE_INTEGER) ? sum + value : sum;
  }, 0);
  const totalPendingRoutesDrops = pendingRoutes.reduce((sum, route) => sum + (route.totalDrops || 0), 0);

  return (
    <Modal 
      isOpen={isOpen} 
      onClose={handleClose} 
      size="6xl"
      scrollBehavior="inside"
      closeOnOverlayClick={false}
    >
      <ModalOverlay backdropFilter="blur(8px)" />
      <ModalContent bg="gray.900" maxH="90vh">
        <ModalHeader color="white" borderBottomWidth="1px" borderColor="gray.700">
          <HStack spacing={3}>
            <Icon as={FiZap} color="purple.400" boxSize={6} />
            <Box>
              <Text fontSize="xl" fontWeight="bold">Smart Route Generator</Text>
              <Text fontSize="sm" fontWeight="normal" color="gray.400">
                Automatically cluster ALL pending drops into optimized routes (flexible mode)
              </Text>
            </Box>
            <Badge 
              colorScheme={
                step === 'config' ? 'blue' : 
                step === 'preview' ? 'purple' : 
                'green'
              }
              fontSize="xs"
              px={2}
              py={1}
            >
              {step === 'config' ? 'Configuration' : 
               step === 'preview' ? 'Preview' : 
               'Creating...'}
            </Badge>
          </HStack>
        </ModalHeader>
        <ModalCloseButton color="white" isDisabled={isCreatingRoutes} />
        
        <ModalBody py={6}>
          {step === 'config' && (
            <Tabs variant="enclosed" colorScheme="purple">
              <TabList>
                <Tab _selected={{ bg: 'gray.800', color: 'purple.300' }}>
                  <Icon as={FiPackage} mr={2} /> Pending Drops ({pendingDrops.length})
                </Tab>
                <Tab _selected={{ bg: 'gray.800', color: 'purple.300' }}>
                  <Icon as={FiTruck} mr={2} /> Pending Routes ({pendingRoutes.length})
                </Tab>
                <Tab _selected={{ bg: 'gray.800', color: 'purple.300' }}>
                  <Icon as={FiUser} mr={2} /> Available Drivers ({onlineDrivers})
                </Tab>
                <Tab _selected={{ bg: 'gray.800', color: 'purple.300' }}>
                  <Icon as={FiSettings} mr={2} /> Settings
                </Tab>
              </TabList>

              <TabPanels>
                {/* Pending Drops Panel */}
                <TabPanel>
                  {isLoadingDrops ? (
                    <Box textAlign="center" py={8}>
                      <Spinner size="lg" color="purple.400" />
                      <Text color="gray.400" mt={4}>Loading pending drops...</Text>
                    </Box>
                  ) : pendingDrops.length === 0 ? (
                    <Alert status="info" borderRadius="md">
                      <AlertIcon />
                      <AlertTitle>No Pending Drops</AlertTitle>
                      <AlertDescription>
                        There are no pending drops available for route creation.
                      </AlertDescription>
                    </Alert>
                  ) : (
                    <VStack spacing={4} align="stretch">
                      {/* Summary Stats */}
                      <Grid templateColumns="repeat(3, 1fr)" gap={4}>
                        <Stat bg="gray.800" p={4} borderRadius="md">
                          <StatLabel color="gray.400">Total Drops</StatLabel>
                          <StatNumber color="white">{pendingDrops.length}</StatNumber>
                          <StatHelpText color="gray.500">Ready for assignment</StatHelpText>
                        </Stat>
                        <Stat bg="gray.800" p={4} borderRadius="md">
                          <StatLabel color="gray.400">Total Volume</StatLabel>
                          <StatNumber color="white">{totalPendingVolume.toFixed(1)} m³</StatNumber>
                          <StatHelpText color="gray.500">Combined volume</StatHelpText>
                        </Stat>
                        <Stat bg="gray.800" p={4} borderRadius="md">
                          <StatLabel color="gray.400">Total Value</StatLabel>
                          <StatNumber color="white">£{(totalPendingValue / 100).toFixed(2)}</StatNumber>
                          <StatHelpText color="gray.500">Revenue potential</StatHelpText>
                        </Stat>
                      </Grid>

                      {/* Drops List */}
                      <Box 
                        maxH="400px" 
                        overflowY="auto"
                        borderWidth="1px"
                        borderColor="gray.700"
                        borderRadius="md"
                      >
                        <Table variant="simple" size="sm">
                          <Thead bg="gray.800" position="sticky" top={0} zIndex={1}>
                            <Tr>
                              <Th color="gray.400">Address</Th>
                              <Th color="gray.400">Time Window</Th>
                              <Th color="gray.400" isNumeric>Volume</Th>
                              <Th color="gray.400">Tier</Th>
                              <Th color="gray.400" isNumeric>Value</Th>
                            </Tr>
                          </Thead>
                          <Tbody>
                            {pendingDrops.map((drop) => (
                              <Tr key={drop.id} _hover={{ bg: 'gray.800' }}>
                                <Td>
                                  <VStack align="start" spacing={0}>
                                    <Text color="white" fontSize="sm" fontWeight="medium">
                                      {drop.pickupAddress}
                                    </Text>
                                    <Text color="gray.400" fontSize="xs">
                                      → {drop.deliveryAddress}
                                    </Text>
                                  </VStack>
                                </Td>
                                <Td>
                                  <Text color="gray.300" fontSize="xs">
                                    {new Date(drop.timeWindowStart).toLocaleTimeString('en-GB', { 
                                      hour: '2-digit', 
                                      minute: '2-digit' 
                                    })}
                                  </Text>
                                </Td>
                                <Td isNumeric>
                                  <Text color="gray.300" fontSize="sm">
                                    {drop.volume.toFixed(1)} m³
                                  </Text>
                                </Td>
                                <Td>
                                  <Badge 
                                    colorScheme={
                                      drop.serviceTier === 'premium' ? 'purple' : 
                                      drop.serviceTier === 'standard' ? 'blue' : 
                                      'green'
                                    }
                                    fontSize="xs"
                                  >
                                    {drop.serviceTier}
                                  </Badge>
                                </Td>
                                <Td isNumeric>
                                  <Text color="white" fontSize="sm" fontWeight="medium">
                                    £{(drop.quotedPrice / 100).toFixed(2)}
                                  </Text>
                                </Td>
                              </Tr>
                            ))}
                          </Tbody>
                        </Table>
                      </Box>
                    </VStack>
                  )}
                </TabPanel>

                {/* Pending Routes Panel - Routes without drivers */}
                <TabPanel>
                  {pendingRoutes.length === 0 ? (
                    <Alert status="info" borderRadius="md">
                      <AlertIcon />
                      <AlertTitle>No Pending Routes</AlertTitle>
                      <AlertDescription>
                        There are no routes waiting for driver assignment.
                      </AlertDescription>
                    </Alert>
                  ) : (
                    <VStack spacing={4} align="stretch">
                      <Alert status="warning" borderRadius="md" bg="orange.900" borderColor="orange.600">
                        <AlertIcon color="orange.300" />
                        <VStack align="start" spacing={1}>
                          <Text color="white" fontSize="sm" fontWeight="bold">
                            {pendingRoutes.length} Routes Awaiting Driver Assignment
                          </Text>
                          <Text color="gray.300" fontSize="xs">
                            These routes have {totalPendingRoutesDrops} total drops worth £{(totalPendingRoutesValue / 100).toFixed(2)}. 
                            Assign drivers from Routes Dashboard.
                          </Text>
                        </VStack>
                      </Alert>
                      
                      {/* Summary Stats */}
                      <Grid templateColumns="repeat(3, 1fr)" gap={4}>
                        <Stat bg="gray.800" p={4} borderRadius="md" borderWidth="1px" borderColor="orange.500">
                          <StatLabel color="gray.400">Total Routes</StatLabel>
                          <StatNumber color="orange.300">{pendingRoutes.length}</StatNumber>
                          <StatHelpText color="gray.500">Waiting for drivers</StatHelpText>
                        </Stat>
                        <Stat bg="gray.800" p={4} borderRadius="md" borderWidth="1px" borderColor="orange.500">
                          <StatLabel color="gray.400">Total Drops</StatLabel>
                          <StatNumber color="orange.300">{totalPendingRoutesDrops}</StatNumber>
                          <StatHelpText color="gray.500">Across all routes</StatHelpText>
                        </Stat>
                        <Stat bg="gray.800" p={4} borderRadius="md" borderWidth="1px" borderColor="orange.500">
                          <StatLabel color="gray.400">Total Value</StatLabel>
                          <StatNumber color="orange.300">£{(totalPendingRoutesValue / 100).toFixed(2)}</StatNumber>
                          <StatHelpText color="gray.500">Revenue potential</StatHelpText>
                        </Stat>
                      </Grid>

                      <Grid templateColumns="repeat(auto-fill, minmax(320px, 1fr))" gap={4}>
                        {pendingRoutes.map((route) => (
                          <Card 
                            key={route.id}
                            bg="gray.800"
                            borderWidth="2px"
                            borderColor="orange.500"
                            cursor="pointer"
                            transition="all 0.2s"
                            _hover={{ 
                              borderColor: 'orange.300',
                              transform: 'translateY(-2px)',
                              shadow: 'lg'
                            }}
                          >
                            <CardBody>
                              <HStack justify="space-between" mb={3}>
                                <Badge colorScheme="orange" fontSize="sm" px={2} py={1}>
                                  {route.id.substring(0, 10)}
                                </Badge>
                                <Badge colorScheme="red" fontSize="xs">
                                  NO DRIVER
                                </Badge>
                              </HStack>

                              <VStack align="stretch" spacing={3}>
                                <HStack>
                                  <Icon as={FiPackage} color="orange.400" />
                                  <Text color="white" fontSize="sm" fontWeight="bold">
                                    {route.totalDrops || 0} drops
                                  </Text>
                                </HStack>

                                <HStack>
                                  <Icon as={FiMapPin} color="orange.400" />
                                  <Text color="white" fontSize="sm">
                                    {((route.optimizedDistanceKm || 0) / 1.609).toFixed(1)} miles
                                  </Text>
                                </HStack>

                                <HStack>
                                  <Icon as={FiClock} color="orange.400" />
                                  <Text color="white" fontSize="sm">
                                    ~{route.estimatedDuration || 0} minutes
                                  </Text>
                                </HStack>

                                <Divider borderColor="gray.700" />

                                <HStack justify="space-between">
                                  <Text color="gray.400" fontSize="sm">Total Value:</Text>
                                  <Text color="white" fontWeight="bold">
                                    £{((route.totalOutcome || 0) / 100).toFixed(2)}
                                  </Text>
                                </HStack>

                                <Text color="gray.400" fontSize="xs" fontStyle="italic">
                                  {route.adminNotes || 'Route awaiting assignment'}
                                </Text>
                              </VStack>
                            </CardBody>
                          </Card>
                        ))}
                      </Grid>

                      <Alert status="info" borderRadius="md">
                        <AlertIcon />
                        <Text fontSize="sm">
                          💡 Tip: Go to "Available Drivers" tab, select a driver, then return to Routes Dashboard to assign them.
                        </Text>
                      </Alert>
                    </VStack>
                  )}
                </TabPanel>

                {/* Available Drivers Panel */}
                <TabPanel>
                  {isLoadingDrivers ? (
                    <Box textAlign="center" py={8}>
                      <Spinner size="lg" color="purple.400" />
                      <Text color="gray.400" mt={4}>Loading available drivers...</Text>
                    </Box>
                  ) : availableDrivers.length === 0 ? (
                    <Alert status="warning" borderRadius="md">
                      <AlertIcon />
                      <AlertTitle>No Drivers Available</AlertTitle>
                      <AlertDescription>
                        There are no drivers currently online or available for assignment.
                      </AlertDescription>
                    </Alert>
                  ) : (
                    <VStack spacing={4} align="stretch">
                      {!autoAssign && (
                        <Alert status="info" borderRadius="md">
                          <AlertIcon />
                          <Text fontSize="sm">
                            Select specific drivers to assign routes to. Only selected drivers will be considered.
                          </Text>
                        </Alert>
                      )}
                      
                      <Grid templateColumns="repeat(auto-fill, minmax(300px, 1fr))" gap={4}>
                        {availableDrivers
                          .filter(d => d.DriverAvailability?.status === 'online' || d.isAvailable)
                          .map((driver) => (
                            <Card 
                              key={driver.id}
                              bg={selectedDriverIds.includes(driver.id) ? 'purple.900' : 'gray.800'}
                              borderWidth="2px"
                              borderColor={selectedDriverIds.includes(driver.id) ? 'purple.400' : 'gray.700'}
                              cursor={autoAssign ? 'default' : 'pointer'}
                              onClick={() => !autoAssign && handleDriverToggle(driver.id)}
                              transition="all 0.2s"
                              _hover={autoAssign ? {} : { 
                                borderColor: 'purple.400',
                                transform: 'translateY(-2px)',
                                shadow: 'lg'
                              }}
                            >
                              <CardBody>
                                <HStack justify="space-between" mb={3}>
                                  <HStack>
                                    <Icon as={FiUser} color="purple.400" />
                                    <Text color="white" fontWeight="bold">{driver.name}</Text>
                                  </HStack>
                                  <Badge colorScheme="green" fontSize="xs">
                                    {driver.status}
                                  </Badge>
                                </HStack>
                                
                                <VStack align="stretch" spacing={2} fontSize="sm">
                                  <HStack justify="space-between">
                                    <Text color="gray.400">Active Routes:</Text>
                                    <Text color="white" fontWeight="medium">{driver.activeRoutes}</Text>
                                  </HStack>
                                  {driver.rating && (
                                    <HStack justify="space-between">
                                      <Text color="gray.400">Rating:</Text>
                                      <Text color="white" fontWeight="medium">{driver.rating.toFixed(1)} ⭐</Text>
                                    </HStack>
                                  )}
                                </VStack>

                                {!autoAssign && selectedDriverIds.includes(driver.id) && (
                                  <Box mt={3} pt={3} borderTopWidth="1px" borderColor="gray.700">
                                    <HStack spacing={2} color="purple.300">
                                      <Icon as={FiCheck} />
                                      <Text fontSize="xs" fontWeight="medium">Selected for assignment</Text>
                                    </HStack>
                                  </Box>
                                )}
                              </CardBody>
                            </Card>
                          ))}
                      </Grid>
                    </VStack>
                  )}
                </TabPanel>

                {/* Settings Panel */}
                <TabPanel>
                  <VStack spacing={6} align="stretch">
                    <Alert status="info" borderRadius="md" bg="blue.900" borderColor="blue.600">
                      <AlertIcon color="blue.300" />
                      <VStack align="start" spacing={1}>
                        <Text color="white" fontSize="sm" fontWeight="bold">
                          Flexible Mode Active
                        </Text>
                        <Text color="gray.300" fontSize="xs">
                          Settings below are guidelines. System will cluster ALL pending drops optimally.
                        </Text>
                      </VStack>
                    </Alert>
                    
                    <Box>
                      <Text color="white" fontSize="lg" fontWeight="bold" mb={4}>
                        Route Configuration (Guidelines)
                      </Text>
                      
                      <Grid templateColumns="repeat(2, 1fr)" gap={6}>
                        <FormControl>
                          <FormLabel color="gray.400">Max Drops Per Route</FormLabel>
                          <Input 
                            type="number" 
                            value={maxDropsPerRoute}
                            onChange={(e) => setMaxDropsPerRoute(parseInt(e.target.value) || 10)}
                            min={1}
                            max={20}
                            bg="gray.800"
                            color="white"
                            borderColor="gray.700"
                            _hover={{ borderColor: 'gray.600' }}
                          />
                          <Text fontSize="xs" color="gray.500" mt={1}>
                            Guideline only - system will adapt to fit all drops
                          </Text>
                        </FormControl>

                        <FormControl>
                          <FormLabel color="gray.400">Max Distance (miles)</FormLabel>
                          <Input 
                            type="number" 
                            value={maxDistanceMiles}
                            onChange={(e) => setMaxDistanceMiles(parseInt(e.target.value) || 50)}
                            min={10}
                            max={200}
                            bg="gray.800"
                            color="white"
                            borderColor="gray.700"
                            _hover={{ borderColor: 'gray.600' }}
                          />
                          <Text fontSize="xs" color="gray.500" mt={1}>
                            Guideline only - flexible up to 2x for clustering
                          </Text>
                        </FormControl>

                        <FormControl>
                          <FormLabel color="gray.400">Optimize By</FormLabel>
                          <Select 
                            value={optimizeBy}
                            onChange={(e) => setOptimizeBy(e.target.value as any)}
                            bg="gray.800"
                            color="white"
                            borderColor="gray.700"
                            _hover={{ borderColor: 'gray.600' }}
                          >
                            <option value="distance">Distance (Shortest Routes)</option>
                            <option value="time">Time (Fastest Routes)</option>
                            <option value="area">Area (Geographic Clustering)</option>
                          </Select>
                          <Text fontSize="xs" color="gray.500" mt={1}>
                            Route optimization strategy
                          </Text>
                        </FormControl>
                      </Grid>
                    </Box>

                    <Divider borderColor="gray.700" />

                    <Box>
                      <Text color="white" fontSize="lg" fontWeight="bold" mb={4}>
                        Driver Assignment
                      </Text>
                      
                      <VStack spacing={4} align="stretch">
                        <VStack spacing={3} align="stretch">
                          <Box>
                            <Text color="white" fontWeight="medium" mb={2}>Driver Selection Mode</Text>
                            <Text color="gray.400" fontSize="xs" mb={3}>
                              Choose how to assign drivers to the created route
                            </Text>
                          </Box>

                          <Checkbox 
                            isChecked={autoAssign}
                            onChange={(e) => {
                              setAutoAssign(e.target.checked);
                              if (e.target.checked) {
                                setSelectedDriverIds([]);
                              }
                            }}
                            colorScheme="purple"
                          >
                            <VStack align="start" spacing={0}>
                              <Text color="white" fontWeight="medium">Smart Auto-Assignment</Text>
                              <Text color="gray.400" fontSize="xs">
                                System automatically picks the best available driver (least workload, highest rating)
                              </Text>
                            </VStack>
                          </Checkbox>

                          {!autoAssign ? (
                            <Alert status="info" borderRadius="md">
                              <AlertIcon />
                              <VStack align="start" spacing={1}>
                                <Text fontWeight="bold" fontSize="sm">Manual Driver Selection</Text>
                                <Text fontSize="xs">
                                  Go to "Available Drivers" tab to choose a specific driver.
                                  {selectedDriverIds.length > 0 && (
                                    <Text as="span" color="purple.300" fontWeight="bold">
                                      {` ✓ ${availableDrivers.find(d => d.id === selectedDriverIds[0])?.name} selected`}
                                    </Text>
                                  )}
                                  {selectedDriverIds.length === 0 && (
                                    <Text as="span" color="orange.300">
                                      {` No driver selected - route will be created as pending_assignment`}
                                    </Text>
                                  )}
                                </Text>
                              </VStack>
                            </Alert>
                          ) : (
                            <Alert status="success" borderRadius="md" bg="green.900" borderColor="green.600">
                              <AlertIcon color="green.300" />
                              <VStack align="start" spacing={1}>
                                <Text fontWeight="bold" fontSize="sm" color="white">Auto-Assignment Active</Text>
                                <Text fontSize="xs" color="gray.300">
                                  System will select: {availableDrivers.filter(d => d.DriverAvailability?.status === 'online' || d.isAvailable).length > 0 
                                    ? `Best driver from ${availableDrivers.filter(d => d.DriverAvailability?.status === 'online' || d.isAvailable).length} available`
                                    : 'No drivers available - route will be pending_assignment'}
                                </Text>
                              </VStack>
                            </Alert>
                          )}
                        </VStack>
                      </VStack>
                    </Box>

                    <Divider borderColor="gray.700" />

                    <Box>
                      <Text color="white" fontSize="lg" fontWeight="bold" mb={4}>
                        Booking Filters
                      </Text>
                      
                      <VStack spacing={4} align="stretch">
                        <Checkbox 
                          isChecked={includePendingPayment}
                          onChange={(e) => {
                            setIncludePendingPayment(e.target.checked);
                            // Refetch drops when filter changes
                            setTimeout(() => {
                              fetchPendingDrops();
                            }, 100);
                          }}
                          colorScheme="purple"
                        >
                          <VStack align="start" spacing={0}>
                            <Text color="white" fontWeight="medium">Include Pending Payment Orders</Text>
                            <Text color="gray.400" fontSize="xs">
                              Include bookings with PENDING_PAYMENT status (awaiting payment confirmation)
                            </Text>
                          </VStack>
                        </Checkbox>

                        <Alert status="info" borderRadius="md" size="sm">
                          <AlertIcon boxSize={4} />
                          <AlertDescription fontSize="xs">
                            By default, only CONFIRMED and DRAFT bookings are included. 
                            Enable this to also include PENDING_PAYMENT orders.
                          </AlertDescription>
                        </Alert>
                      </VStack>
                    </Box>
                  </VStack>
                </TabPanel>
              </TabPanels>
            </Tabs>
          )}

          {step === 'preview' && (
            <VStack spacing={6} align="stretch">
              {/* Preview Header */}
              <HStack justify="space-between">
                <Box>
                  <Text color="white" fontSize="lg" fontWeight="bold">
                    Route Preview
                  </Text>
                  <Text color="gray.400" fontSize="sm">
                    {selectedRouteIds.length} of {proposedRoutes.length} routes selected
                  </Text>
                </Box>
                <HStack spacing={2}>
                  <Button
                    variant="ghost"
                    colorScheme="gray"
                    size="sm"
                    onClick={() => setSelectedRouteIds(proposedRoutes.map(route => route.id))}
                    isDisabled={proposedRoutes.length === 0 || selectedRouteIds.length === proposedRoutes.length}
                  >
                    Select All
                  </Button>
                  <Button
                    variant="ghost"
                    colorScheme="gray"
                    size="sm"
                    onClick={() => setSelectedRouteIds([])}
                    isDisabled={selectedRouteIds.length === 0}
                  >
                    Clear Selection
                  </Button>
                  <Button
                    leftIcon={<FiSettings />}
                    variant="ghost"
                    colorScheme="gray"
                    size="sm"
                    onClick={() => setStep('config')}
                  >
                    Back to Settings
                  </Button>
                </HStack>
              </HStack>

              <Divider borderColor="gray.700" />

              {/* Proposed Routes */}
              {proposedRoutes.length === 0 ? (
                <Alert status="warning" borderRadius="md">
                  <AlertIcon />
                  <AlertTitle>No Routes Generated</AlertTitle>
                  <AlertDescription>
                    Unable to create routes with current settings. Try adjusting max drops or distance.
                  </AlertDescription>
                </Alert>
              ) : (
                <VStack spacing={6} align="stretch">
                  {/* Interactive Map Preview */}
                  <Box>
                    <HStack mb={3}>
                      <Icon as={FiMap} color="purple.400" boxSize={5} />
                      <Text color="white" fontSize="md" fontWeight="bold">
                        Route Map Preview
                      </Text>
                    </HStack>
                    <AdminRouteClusterMap
                      routes={proposedRoutes.map((route, index) => ({
                        id: route.id,
                        drops: route.drops.map((dropId) => {
                          const drop = pendingDrops.find(d => d.id === dropId);
                          return {
                            lat: 51.5074 + (Math.random() - 0.5) * 0.1, // Temporary mock coords
                            lng: -0.1278 + (Math.random() - 0.5) * 0.1,
                            address: drop?.pickupAddress || 'Unknown',
                          };
                        }),
                      }))}
                      height="400px"
                    />
                  </Box>

                  {/* Route Cards */}
                  <Box>
                    <Text color="white" fontSize="md" fontWeight="bold" mb={3}>
                      Route Details
                    </Text>
                    <Grid templateColumns="repeat(auto-fill, minmax(350px, 1fr))" gap={4}>
                      {proposedRoutes.map((route, index) => {
                        const isSelected = selectedRouteIds.includes(route.id);
                        return (
                          <Card
                            key={route.id}
                            bg={isSelected ? 'purple.900' : 'gray.800'}
                            borderWidth="2px"
                            borderColor={isSelected ? 'purple.400' : 'gray.700'}
                            cursor="pointer"
                            transition="all 0.2s ease-in-out"
                            onClick={() =>
                              setSelectedRouteIds(prev =>
                                prev.includes(route.id)
                                  ? prev.filter(id => id !== route.id)
                                  : [...prev, route.id]
                              )
                            }
                            _hover={{
                              borderColor: isSelected ? 'purple.300' : 'gray.500',
                              transform: 'translateY(-2px)',
                            }}
                          >
                            <CardBody>
                              <HStack justify="space-between" mb={3}>
                                <Badge colorScheme="purple" fontSize="sm" px={2} py={1}>
                                  Route {index + 1}
                                </Badge>
                                <Badge
                                  colorScheme={isSelected ? 'green' : 'gray'}
                                  fontSize="xs"
                                >
                                  {isSelected ? 'Selected' : 'Click to select'}
                                </Badge>
                              </HStack>

                              <VStack align="stretch" spacing={3}>
                                <HStack>
                                  <Icon as={FiPackage} color="purple.400" />
                                  <Text color="white" fontSize="sm">
                                    {route.totalDrops} drops
                                  </Text>
                                </HStack>

                                <HStack>
                                  <Icon as={FiMapPin} color="purple.400" />
                                  <Text color="white" fontSize="sm">
                                    {route.estimatedDistance.toFixed(1)} miles
                                  </Text>
                                </HStack>

                                <HStack>
                                  <Icon as={FiClock} color="purple.400" />
                                  <Text color="white" fontSize="sm">
                                    ~{route.estimatedDuration} minutes
                                  </Text>
                                </HStack>

                                <Divider borderColor="gray.700" />

                                <HStack justify="space-between">
                                  <Text color="gray.400" fontSize="sm">Total Value:</Text>
                                  <Text color="white" fontWeight="bold">
                                    £{(route.totalValue / 100).toFixed(2)}
                                  </Text>
                                </HStack>
                              </VStack>
                            </CardBody>
                          </Card>
                        );
                      })}
                    </Grid>
                  </Box>
                </VStack>
              )}
            </VStack>
          )}

          {step === 'creating' && (
            <Box textAlign="center" py={12}>
              <Spinner size="xl" color="purple.400" thickness="4px" />
              <Text color="white" fontSize="lg" fontWeight="bold" mt={6}>
                Creating Routes...
              </Text>
              <Text color="gray.400" mt={2}>
                Please wait while we process your request
              </Text>
              <Progress 
                size="sm" 
                isIndeterminate 
                colorScheme="purple" 
                mt={6}
                borderRadius="full"
              />
            </Box>
          )}
        </ModalBody>
        
        <ModalFooter borderTopWidth="1px" borderColor="gray.700">
          <HStack spacing={3}>
            <Button 
              variant="ghost" 
              onClick={handleClose}
              isDisabled={isCreatingRoutes || isGeneratingPreview}
            >
              Cancel
            </Button>
            
            {step === 'config' && (
              <Button
                leftIcon={<FiEye />}
                colorScheme="purple"
                onClick={generatePreview}
                isLoading={isGeneratingPreview}
                loadingText="Generating..."
                isDisabled={pendingDrops.length === 0}
              >
                Generate Preview
              </Button>
            )}
            
            {step === 'preview' && (
              <Button
                leftIcon={<FiCheck />}
                colorScheme="green"
                onClick={createRoutes}
                isLoading={isCreatingRoutes}
                loadingText="Creating..."
                isDisabled={proposedRoutes.length === 0}
              >
                Confirm & Create Routes
              </Button>
            )}
          </HStack>
        </ModalFooter>
      </ModalContent>
    </Modal>
  );
};

export default SmartRouteGeneratorModal;

'use client';

import React, { useState, useRef, useEffect } from 'react';
import {
  Box,
  VStack,
  HStack,
  Text,
  Input,
  Button,
  IconButton,
  Card,
  CardBody,
  Badge,
  Avatar,
  Spinner,
  useToast,
  Select,
  Flex,
  Divider,
  Textarea,
  SimpleGrid,
  Tag,
  useColorModeValue,
} from '@chakra-ui/react';
import {
  FiSend,
  FiMinimize2,
  FiMaximize2,
  FiX,
  FiMessageCircle,
  FiZap,
  FiUser,
  FiGlobe,
  FiCopy,
  FiThumbsUp,
  FiThumbsDown,
  FiDownload,
  FiSearch,
  FiBookOpen,
  FiCheck,
  FiUpload,
  FiMic,
  FiSidebar,
  FiClock,
  FiTool,
