}

interface Message {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  timestamp: Date;
  language?: 'en' | 'ar';
  feedback?: 'up' | 'down' | null;
  copied?: boolean;
}

interface LiveStatsSummary {
  text: string;
  generatedAt: string;
  metrics: {
    totalOrders: number;
    activeOrders: number;
    pendingOrders: number;
    oldUnassigned: number;
    totalDrivers: number;
    activeDrivers: number;
    driverUtilizationRate: number;
    activeRoutes: number;
    todayRevenue: number;
    averageDailyRevenue: number;
    revenueVsAverage: number;
    bookingsLast24h: number;
  };
  alerts: string[];
}

interface DriverAvailabilitySummary {
  text: string;
  generatedAt: string;
  drivers: Array<{
    id: string;
    name: string;
    phone?: string | null;
    activeJobs: number;
    status: 'free' | 'busy' | 'full';
    recommendation: 'BEST' | 'OK' | 'AVOID';
    nextJobTime?: string | null;
    nextJobDisplay?: string | null;
  }>;
}

interface PredictiveAnalyticsSummary {
  text: string;
  generatedAt: string;
  avgDailyRevenue: number;
  avgDailyOrders: number;
  projectedMonthRevenue: number;
  projectedMonthOrders: number;
  demandTrend: 'increasing' | 'decreasing';
  todayOrders: number;
}

interface ProactiveSuggestionsSummary {
  text: string;
  generatedAt: string;
  suggestions: string[];
  isClear: boolean;
}

interface AssistantMetadata {
  requestId: string;
  language: 'en' | 'ar';
  references: {
    orders: string[];
    routes: string[];
  };
  historyCount: number;
  contextualHelp?: string;
  liveStats?: LiveStatsSummary;
  driverAvailability?: DriverAvailabilitySummary;
  predictiveAnalytics?: PredictiveAnalyticsSummary;
  proactiveSuggestions?: ProactiveSuggestionsSummary;
  processingTimeMs?: number;
}

interface SpeedyAIChatbotProps {
  isOpen?: boolean;
  onClose?: () => void;
  initialLanguage?: 'en' | 'ar';
  adminName?: string;
  adminEmail?: string;
}

export default function SpeedyAIChatbot({
  isOpen: initialIsOpen = false,
  onClose,
  initialLanguage = 'en',
  adminName = 'Admin',
  adminEmail = '',
}: SpeedyAIChatbotProps) {
  // All state hooks - must be called unconditionally
  const [isOpen, setIsOpen] = useState(initialIsOpen);
  const [isMinimized, setIsMinimized] = useState(false);
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputMessage, setInputMessage] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [language, setLanguage] = useState<'en' | 'ar'>(initialLanguage);
  const [showSuggestions, setShowSuggestions] = useState(true);
  const [showExamples, setShowExamples] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [notificationCount, setNotificationCount] = useState(0);
  const [assistantInsights, setAssistantInsights] = useState<AssistantMetadata | null>(null);
  const [showSidebar, setShowSidebar] = useState(false);
  const [showLiveStatus, setShowLiveStatus] = useState(false);
  const [isRecording, setIsRecording] = useState(false);
  const [heySpeedyEnabled, setHeySpeedyEnabled] = useState(false);
  const [voiceOutputEnabled, setVoiceOutputEnabled] = useState(false);
  const [uploadedFile, setUploadedFile] = useState<File | null>(null);
  const [conversationHistory, setConversationHistory] = useState<Array<{id: string; title: string; timestamp: Date}>>([]);
  const [proactiveInsights, setProactiveInsights] = useState<ProactiveInsight[]>([]);
  const [sensitiveWarnings, setSensitiveWarnings] = useState<string[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const recognitionRef = useRef<any>(null);
  
  // All refs - must be called unconditionally
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLTextAreaElement>(null);
  
  // All Chakra hooks - must be called unconditionally and in the same order
  const toast = useToast();
  
  // ✅ Quick action prompts for admins
  const quickActions = language === 'ar' ? [
    { label: '📊 نظرة عامة', prompt: 'أعطني نظرة عامة على الوضع الحالي للنظام' },
    { label: '🚗 السائقون المتاحون', prompt: 'من هم السائقون المتاحون الآن؟' },
    { label: '📦 طلبات غير معيّنة', prompt: 'أي طلبات لم يتم تعيينها بعد؟' },
    { label: '💰 إيرادات اليوم', prompt: 'كم إيرادات اليوم؟' },
    { label: '🎯 اقتراحات', prompt: 'ما هي التحسينات التي تنصحني بها؟' },
  ] : [
    { label: '📊 System Overview', prompt: 'Give me a current system overview' },
    { label: '🚗 Available Drivers', prompt: 'Who are the available drivers right now?' },
    { label: '📦 Unassigned Orders', prompt: 'Which orders are still unassigned?' },
    { label: '💰 Today\'s Revenue', prompt: 'What\'s today\'s revenue?' },
    { label: '🎯 Suggestions', prompt: 'What improvements do you recommend?' },
  ];
  // ChatGPT-inspired dark theme colors
  const bgColor = '#343541'; // ChatGPT main background
  const borderColor = '#565869'; // ChatGPT border color
  const textColor = '#ECECF1'; // ChatGPT text color (off-white)
  const inputBg = '#40414f'; // ChatGPT input background
  const messageBgUser = '#343541'; // Same as main bg for user
  const messageBgAssistant = '#444654'; // Slightly lighter for assistant (ChatGPT style)
  const messagesBg = '#343541'; // Main background for messages
  const headerBg = '#202123'; // Darker header like ChatGPT
  
  // Non-hook values derived from hooks
  const messageBgUserText = '#FFFFFF'; // White text on user messages
  const messageBgAssistantText = '#FFFFFF'; // White text on assistant messages

  // Auto-scroll to bottom
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  // Focus input when opened
  useEffect(() => {
    if (isOpen && !isMinimized) {
      setTimeout(() => {
        inputRef.current?.focus();
      }, 100);
    }
  }, [isOpen, isMinimized]);

  // Initialize with welcome message
  useEffect(() => {
    if (isOpen && messages.length === 0) {
      const welcomeMessage = language === 'ar'
        ? `مرحباً ${adminName}! أنا Speedy AI، مساعدك الذكي في إدارة Speedy Van. كيف يمكنني مساعدتك اليوم؟`
        : `Hello ${adminName}! I'm Speedy AI, your intelligent assistant for managing Speedy Van. How can I help you today?`;

      setMessages([
        {
          id: 'welcome',
          role: 'assistant',
          content: welcomeMessage,
          timestamp: new Date(),
          language,
        },
      ]);
    }
  }, [isOpen, language, adminName]);

  const handleSendMessage = async () => {
    if (!inputMessage.trim() || isLoading) return;

    const sanitizedMessage = inputMessage.trim();
    const userMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: sanitizedMessage,
      timestamp: new Date(),
      language,
    };

    const conversationPayload = [...messages, userMessage].map((msg) => ({
      role: msg.role,
      content: msg.content,
      message: msg.content,
    }));

    setMessages((prev) => [...prev, userMessage]);
    setInputMessage('');
    setIsLoading(true);
    setShowSuggestions(false);
    setAssistantInsights(null);

    const streamingMessageId = (Date.now() + 1).toString();
    const streamingMessage: Message = {
      id: streamingMessageId,
      role: 'assistant',
      content: '',
      timestamp: new Date(),
      language,
    };
    setMessages((prev) => [...prev, streamingMessage]);

    try {
      const response = await fetch('/api/admin/ai/chat', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          message: sanitizedMessage,
          conversationHistory: conversationPayload,
          language,
          mode: 'stream',
        }),
      });

      if (!response.ok || !response.body) {
        throw new Error('Failed to get AI response');
      }

      const reader = response.body.getReader();
      const decoder = new TextDecoder();
      let buffer = '';
      let aggregatedResponse = '';
      let finalMetadata: AssistantMetadata | null = null;
      let finalLanguage: 'en' | 'ar' = language;

      const applyContentUpdate = (content: string) => {
        setMessages((prev) =>
          prev.map((msg) =>
            msg.id === streamingMessageId
              ? { ...msg, content, language: finalLanguage }
              : msg
          )
        );
      };

      const processLine = (line: string) => {
        if (!line) return;

        let payload: { event: string; data: any };
        try {
          payload = JSON.parse(line);
        } catch (err) {
          console.warn('Failed to parse stream chunk', err);
          return;
        }

        switch (payload.event) {
          case 'token': {
            const token = typeof payload.data === 'string' ? payload.data : '';
            if (token) {
              aggregatedResponse += token;
              applyContentUpdate(aggregatedResponse);
            }
            break;
          }
          case 'final': {
            const data = payload.data ?? {};
            if (typeof data.response === 'string') {
              aggregatedResponse = data.response;
              applyContentUpdate(aggregatedResponse);
            }
            if (data.language === 'ar' || data.language === 'en') {
              finalLanguage = data.language;
              setLanguage(data.language);
            }
            if (data.metadata) {
              finalMetadata = {
                ...(data.metadata as AssistantMetadata),
                processingTimeMs:
                  typeof data.processingTimeMs === 'number'
                    ? data.processingTimeMs
                    : undefined,
              };
            }
            break;
          }
          case 'error': {
            const message =
              typeof payload.data?.message === 'string'
                ? payload.data.message
                : language === 'ar'
                ? 'عذراً، حدث خطأ في الاتصال. يرجى المحاولة مرة أخرى.'
                : 'Sorry, an error occurred. Please try again.';
            throw new Error(message);
          }
          default:
            break;
        }
      };

      while (true) {
        const { value, done } = await reader.read();
        if (done) break;
        buffer += decoder.decode(value, { stream: true });

        let newlineIndex: number;
        while ((newlineIndex = buffer.indexOf('\n')) >= 0) {
          const line = buffer.slice(0, newlineIndex).trim();
          buffer = buffer.slice(newlineIndex + 1);
          if (line.length > 0) {
            processLine(line);
          }
        }
      }

      const remaining = buffer.trim();
      if (remaining) {
        processLine(remaining);
      }

      if (!aggregatedResponse) {
        aggregatedResponse =
          language === 'ar'
            ? 'تمت معالجة الطلب بنجاح.'
            : 'Request processed successfully.';
        applyContentUpdate(aggregatedResponse);
      }

      if (finalMetadata) {
        setAssistantInsights(finalMetadata);
      }
    } catch (error: any) {
      console.error('Chat error:', error);

      const errorMessage =
        error?.message ||
        (language === 'ar'
          ? 'عذراً، حدث خطأ في الاتصال. يرجى المحاولة مرة أخرى.'
          : 'Sorry, an error occurred. Please try again.');

      toast({
        title: language === 'ar' ? 'خطأ' : 'Error',
        description: errorMessage,
        status: 'error',
        duration: 3000,
        isClosable: true,
      });

      setMessages((prev) =>
        prev.map((msg) =>
          msg.id === streamingMessageId
            ? { ...msg, content: errorMessage }
            : msg
        )
      );
    } finally {
      setIsLoading(false);
    }
  };

  // Fix error message variable
  const getErrorMessage = (error: any) => {
    const errorMsg = language === 'ar'
      ? 'عذراً، حدث خطأ في الاتصال. يرجى المحاولة مرة أخرى.'
      : 'Sorry, an error occurred. Please try again.';

    return {
      id: (Date.now() + 1).toString(),
      role: 'assistant' as const,
      content: errorMsg,
      timestamp: new Date(),
      language,
    };
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage();
    }
  };

  const handleToggle = () => {
    if (isMinimized) {
      setIsMinimized(false);
    } else {
      setIsMinimized(true);
    }
  };

  const handleClose = () => {
    setIsOpen(false);
    if (onClose) {
      onClose();
    }
  };

  const handleClearChat = () => {
    setMessages([]);
    setInputMessage('');
    setAssistantInsights(null);
  };

  // ✅ NEW: Handle quick action click
  const handleQuickAction = (prompt: string) => {
    setInputMessage(prompt);
    setShowSuggestions(false);
    // Auto-send after a short delay
    setTimeout(() => {
      if (inputRef.current) {
        handleSendMessage();
      }
    }, 300);
  };

  // ✅ Feature 1: Copy message to clipboard
  const handleCopyMessage = async (messageId: string, content: string) => {
    try {
      await navigator.clipboard.writeText(content);
      setMessages(prev => prev.map(msg => 
        msg.id === messageId ? { ...msg, copied: true } : msg
      ));
      toast({
        title: language === 'ar' ? 'تم النسخ' : 'Copied',
        description: language === 'ar' ? 'تم نسخ الرسالة' : 'Message copied to clipboard',
        status: 'success',
        duration: 2000,
        isClosable: true,
      });
      // Reset copied state after 2 seconds
      setTimeout(() => {
        setMessages(prev => prev.map(msg => 
          msg.id === messageId ? { ...msg, copied: false } : msg
        ));
      }, 2000);
    } catch (error) {
      toast({
        title: language === 'ar' ? 'خطأ' : 'Error',
        description: language === 'ar' ? 'فشل النسخ' : 'Failed to copy',
        status: 'error',
        duration: 2000,
      });
    }
  };

  // ✅ NEW: Handle file upload
  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setUploadedFile(file);
    toast({
      title: language === 'ar' ? 'تم رفع الملف' : 'File Uploaded',
      description: `${file.name} (${(file.size / 1024).toFixed(2)} KB)`,
      status: 'success',
      duration: 3000,
    });

    // Upload file to server
    try {
      const formData = new FormData();
      formData.append('file', file);

      const response = await fetch('/api/admin/ai/upload', {
        method: 'POST',
        body: formData,
      });

      const data = await response.json();
      if (data.success) {
        // Add file context to next message
        const fileContext = `[File uploaded: ${file.name}]\n${data.extractedText || ''}`;
        setInputMessage(prev => prev + '\n' + fileContext);
      }
    } catch (error) {
      console.error('File upload error:', error);
    }
  };

  // ✅ NEW: Handle voice recording
  const handleVoiceToggle = async () => {
    if (!isRecording) {
      // Start recording
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
        setIsRecording(true);
        toast({
          title: language === 'ar' ? 'جاري التسجيل...' : 'Recording...',
          status: 'info',
          duration: 2000,
        });
        // Implement actual recording logic here
      } catch (error) {
        toast({
          title: language === 'ar' ? 'خطأ' : 'Error',
          description: language === 'ar' ? 'فشل الوصول إلى الميكروفون' : 'Microphone access denied',
          status: 'error',
          duration: 3000,
        });
      }
    } else {
      // Stop recording
      setIsRecording(false);
      toast({
        title: language === 'ar' ? 'تم إيقاف التسجيل' : 'Recording Stopped',
        status: 'success',
        duration: 2000,
      });
    }
  };

  // ✅ Feature 2: Submit feedback
  const handleFeedback = async (messageId: string, feedback: 'up' | 'down') => {
    setMessages(prev => prev.map(msg => 
      msg.id === messageId ? { ...msg, feedback } : msg
    ));
    
    // Log feedback to API
    try {
      await fetch('/api/admin/ai/feedback', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          messageId,
          feedback,
          adminEmail,
          timestamp: new Date().toISOString()
        }),
      });
    } catch (error) {
      console.warn('Failed to log feedback:', error);
    }
    
    toast({
      title: feedback === 'up' 
        ? (language === 'ar' ? 'شكراً!' : 'Thanks!')
        : (language === 'ar' ? 'سنحسّن' : 'We\'ll improve'),
      status: 'info',
      duration: 2000,
    });
  };

  // ✅ Feature 3: Export conversation
  const handleExportConversation = () => {
    const conversationText = messages
      .map(msg => `[${msg.timestamp.toLocaleString()}] ${msg.role === 'user' ? adminName : 'Speedy AI'}:\n${msg.content}\n`)
      .join('\n---\n\n');
    
    const blob = new Blob([conversationText], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `speedy-ai-chat-${new Date().toISOString().slice(0,10)}.txt`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    
    toast({
      title: language === 'ar' ? 'تم التصدير' : 'Exported',
      description: language === 'ar' ? 'تم حفظ المحادثة' : 'Conversation saved',
      status: 'success',
      duration: 2000,
    });
  };

  // ✅ Feature 8: Filter messages by search
  const filteredMessages = searchQuery.trim()
    ? messages.filter(msg => 
        msg.content.toLowerCase().includes(searchQuery.toLowerCase())
      )
    : messages;

  // ✅ Feature 6: Check for urgent notifications (fetch every 30s)
  useEffect(() => {
    const checkNotifications = async () => {
      try {
        const response = await fetch('/api/admin/ai/notifications');
        if (response.ok) {
          const data = await response.json();
          setNotificationCount(data.count || 0);
        }
      } catch (error) {
        console.warn('Failed to fetch notifications:', error);
      }
    };
    
    checkNotifications();
    const interval = setInterval(checkNotifications, 30000); // Every 30s
    
    return () => clearInterval(interval);
  }, []);

  const renderInsightsPanel = (metadata: AssistantMetadata) => {
    const isArabic = language === 'ar';
    const stats = metadata.liveStats?.metrics;
    const driverEntries = metadata.driverAvailability?.drivers ?? [];
    const predictive = metadata.predictiveAnalytics;
    const suggestions = metadata.proactiveSuggestions;

    const metricCard = (label: string, value: string, accentColor = '#f9fafb') => (
      <Box
        key={label}
        p={3}
        borderRadius="md"
        bg="rgba(15, 118, 255, 0.08)"
        border="1px solid rgba(37, 99, 235, 0.15)"
      >
        <Text fontSize="xs" color="#9ca3af" fontWeight="semibold">
          {label}
        </Text>
        <Text fontSize="md" fontWeight="bold" color={accentColor} mt={1}>
          {value}
        </Text>
      </Box>
    );

    const statusLabels = isArabic
      ? { free: 'متاح', busy: 'مشغول', full: 'ممتلئ' }
      : { free: 'Free', busy: 'Busy', full: 'Full' };
    const recommendationLabels = isArabic
      ? { BEST: 'الأفضل', OK: 'مناسب', AVOID: 'تجنّب' }
      : { BEST: 'BEST', OK: 'OK', AVOID: 'Avoid' };

    return (
      <VStack align="stretch" spacing={4}>
        <HStack justify="space-between" align="center">
          <HStack spacing={3}>
            <Text fontSize="sm" fontWeight="bold" color="#60a5fa" letterSpacing="0.5px">
              {isArabic ? 'رؤى فورية' : 'Real-Time Insights'}
            </Text>
            <Badge bg="rgba(96, 165, 250, 0.18)" color="#bfdbfe" borderRadius="md" px={2} py={1}>
              #{metadata.requestId.slice(0, 8).toUpperCase()}
            </Badge>
            {typeof metadata.processingTimeMs === 'number' && (
              <Badge bg="rgba(16, 185, 129, 0.15)" color="#a7f3d0" borderRadius="md" px={2} py={1}>
                {isArabic
                  ? `${metadata.processingTimeMs} مللي ثانية`
                  : `${metadata.processingTimeMs} ms`}
              </Badge>
            )}
          </HStack>
          <Button
            size="xs"
            variant="ghost"
            color="#9ca3af"
            _hover={{ color: '#f9fafb' }}
            onClick={() => setAssistantInsights(null)}
          >
            {isArabic ? 'إخفاء' : 'Hide'}
          </Button>
        </HStack>

        {metadata.references && (metadata.references.orders.length > 0 || metadata.references.routes.length > 0) && (
          <Box
            bg="rgba(37, 99, 235, 0.08)"
            borderRadius="md"
            p={3}
            border="1px solid rgba(37, 99, 235, 0.2)"
          >
            <Text fontSize="xs" fontWeight="semibold" color="#60a5fa" mb={2}>
              {isArabic ? 'مراجع ذات صلة' : 'Relevant References'}
            </Text>
            <HStack spacing={2} flexWrap="wrap">
              {metadata.references.orders.map((ref) => (
                <Tag key={`order-${ref}`} size="sm" variant="subtle" colorScheme="blue">
                  {isArabic ? `طلب ${ref}` : `Order ${ref}`}
                </Tag>
              ))}
              {metadata.references.routes.map((ref) => (
                <Tag key={`route-${ref}`} size="sm" variant="subtle" colorScheme="purple">
                  {isArabic ? `مسار ${ref}` : `Route ${ref}`}
                </Tag>
              ))}
            </HStack>
          </Box>
        )}

        {metadata.contextualHelp && (
          <Box
            bg="rgba(16, 185, 129, 0.1)"
            borderRadius="md"
            p={3}
            border="1px solid rgba(16, 185, 129, 0.2)"
          >
            <Text fontSize="xs" fontWeight="semibold" color="#34d399" mb={2}>
              {isArabic ? 'من قاعدة المعرفة' : 'Knowledge Base'}
            </Text>
            <Text fontSize="sm" color="#d1d5db" whiteSpace="pre-wrap">
              {metadata.contextualHelp}
            </Text>
          </Box>
        )}

        {stats && (
          <Box
            bg="rgba(37, 99, 235, 0.05)"
            borderRadius="md"
            p={3}
            border="1px solid rgba(37, 99, 235, 0.15)"
          >
            <Text fontSize="xs" fontWeight="semibold" color="#60a5fa" mb={3}>
              {isArabic ? 'نظرة عامة على النظام' : 'System Snapshot'}
            </Text>
            <SimpleGrid columns={{ base: 2, md: 3 }} spacing={3}>
              {metricCard(isArabic ? 'إجمالي الطلبات' : 'Total Orders', stats.totalOrders.toString())}
              {metricCard(isArabic ? 'الطلبات النشطة' : 'Active Orders', stats.activeOrders.toString())}
              {metricCard(
                isArabic ? 'بانتظار التعيين' : 'Pending Assignment',
                stats.pendingOrders.toString(),
                stats.pendingOrders > 0 ? '#facc15' : '#f9fafb'
              )}
              {metricCard(
                isArabic ? 'غير المعيّنة (>2 س)' : 'Unassigned >2h',
                stats.oldUnassigned.toString(),
                stats.oldUnassigned > 0 ? '#f87171' : '#34d399'
              )}
              {metricCard(
                isArabic ? 'توافر السائقين' : 'Driver Utilization',
                `${stats.driverUtilizationRate.toFixed(1)}%`,
                stats.driverUtilizationRate < 40 ? '#f97316' : '#34d399'
              )}
              {metricCard(
                isArabic ? 'إيراد اليوم' : 'Today’s Revenue',
                `£${stats.todayRevenue.toFixed(2)}`
              )}
              {metricCard(
                isArabic ? 'مقارنة بالمتوسط' : 'Vs Average',
                `${stats.revenueVsAverage.toFixed(1)}%`,
                stats.revenueVsAverage < 0 ? '#f87171' : '#34d399'
              )}
              {metricCard(
                isArabic ? 'المسارات النشطة' : 'Active Routes',
                stats.activeRoutes.toString()
              )}
              {metricCard(
                isArabic ? 'طلبات 24 ساعة' : 'Orders (24h)',
                stats.bookingsLast24h.toString()
              )}
            </SimpleGrid>
            {metadata.liveStats?.alerts?.length ? (
              <VStack align="stretch" spacing={1} mt={3}>
                {metadata.liveStats.alerts.map((alert, idx) => (
                  <Text key={idx} fontSize="xs" color="#fbbf24">
                    {alert}
                  </Text>
                ))}
              </VStack>
            ) : null}
          </Box>
        )}

        {driverEntries.length > 0 && (
          <Box
            bg="rgba(255, 255, 255, 0.03)"
            borderRadius="md"
            p={3}
            border="1px solid rgba(148, 163, 184, 0.15)"
          >
            <Text fontSize="xs" fontWeight="semibold" color="#e5e7eb" mb={2}>
              {isArabic ? 'أفضل السائقين المتاحين' : 'Top Available Drivers'}
            </Text>
            <VStack align="stretch" spacing={2}>
              {driverEntries.slice(0, 5).map((driver) => (
                <HStack
                  key={driver.id}
                  justify="space-between"
                  align="flex-start"
                  bg="rgba(37, 99, 235, 0.08)"
                  borderRadius="md"
                  p={2}
                  border="1px solid rgba(37, 99, 235, 0.15)"
                >
                  <VStack align="start" spacing={0}>
                    <Text fontSize="sm" color="#f9fafb" fontWeight="semibold">
                      {driver.name || (isArabic ? 'غير معروف' : 'Unknown')}
                    </Text>
                    <Text fontSize="xs" color="#9ca3af">
                      {isArabic
                        ? `وظائف نشطة: ${driver.activeJobs}${driver.nextJobDisplay ? `، القادم ${driver.nextJobDisplay}` : ''}`
                        : `Active: ${driver.activeJobs}${driver.nextJobDisplay ? `, next @${driver.nextJobDisplay}` : ''}`}
                    </Text>
                  </VStack>
                  <VStack align="end" spacing={1}>
                    <Badge colorScheme={driver.status === 'free' ? 'green' : driver.status === 'busy' ? 'yellow' : 'red'}>
                      {statusLabels[driver.status]}
                    </Badge>
                    <Badge
                      variant="outline"
                      colorScheme={driver.recommendation === 'BEST' ? 'green' : driver.recommendation === 'OK' ? 'yellow' : 'red'}
                    >
                      {recommendationLabels[driver.recommendation]}
                    </Badge>
                  </VStack>
                </HStack>
              ))}
            </VStack>
          </Box>
        )}

        {predictive && (
          <Box
            bg="rgba(59, 130, 246, 0.08)"
            borderRadius="md"
            p={3}
            border="1px solid rgba(59, 130, 246, 0.2)"
          >
            <Text fontSize="xs" fontWeight="semibold" color="#60a5fa" mb={2}>
              {isArabic ? 'توقعات الأداء' : 'Performance Forecast'}
            </Text>
            <SimpleGrid columns={{ base: 2, md: 4 }} spacing={3}>
              {metricCard(
                isArabic ? 'متوسط الإيرادات اليومية' : 'Avg Daily Revenue',
                `£${predictive.avgDailyRevenue.toFixed(2)}`
              )}
              {metricCard(
                isArabic ? 'متوسط الطلبات اليومية' : 'Avg Daily Orders',
                predictive.avgDailyOrders.toFixed(1).toString()
              )}
              {metricCard(
                isArabic ? 'توقع نهاية الشهر' : 'Month Projection',
                `£${predictive.projectedMonthRevenue.toFixed(2)}`
              )}
              {metricCard(
                isArabic ? 'طلبات اليوم' : 'Today’s Orders',
                predictive.todayOrders.toString()
              )}
              {metricCard(
                isArabic ? 'الاتجاه' : 'Trend',
                predictive.demandTrend === 'increasing'
                  ? (isArabic ? '📈 تصاعدي' : '📈 Increasing')
                  : (isArabic ? '📉 تنازلي' : '📉 Decreasing'),
                predictive.demandTrend === 'increasing' ? '#34d399' : '#f87171'
              )}
              {metricCard(
                isArabic ? 'إيراد متوقع (30 يوم)' : 'Projected Orders',
                predictive.projectedMonthOrders.toString()
              )}
            </SimpleGrid>
          </Box>
        )}

        {suggestions && (
          <Box
            bg="rgba(253, 224, 71, 0.08)"
            borderRadius="md"
            p={3}
            border="1px solid rgba(253, 224, 71, 0.2)"
          >
            <Text fontSize="xs" fontWeight="semibold" color="#facc15" mb={2}>
              {isArabic ? 'اقتراحات استباقية' : 'Proactive Suggestions'}
            </Text>
            {suggestions.suggestions.length > 0 ? (
              <VStack align="stretch" spacing={1}>
                {suggestions.suggestions.map((item, idx) => (
                  <Text key={idx} fontSize="sm" color="#f9fafb">
                    • {item}
                  </Text>
                ))}
              </VStack>
            ) : (
              <Text fontSize="sm" color="#d1d5db">
                {isArabic ? 'لا توجد مشاكل عاجلة حالياً.' : 'No urgent issues at the moment.'}
              </Text>
            )}
          </Box>
        )}
      </VStack>
    );
  };

  // Render content based on state - no early returns to ensure hooks are always called in same order
  if (!isOpen) {
    return (
      <Box position="fixed" bottom="20px" right="20px" zIndex={1000}>
        <IconButton
          aria-label="Open Speedy AI"
          icon={<FiMessageCircle style={{ color: '#FFFFFF' }} />}
          onClick={() => setIsOpen(true)}
          size="lg"
          bg="linear-gradient(135deg, #2563eb 0%, #1d4ed8 100%)"
          color="#FFFFFF"
          borderRadius="full"
          boxShadow="0 8px 25px rgba(37, 99, 235, 0.6), 0 0 50px rgba(37, 99, 235, 0.4), inset 0 1px 0 rgba(255, 255, 255, 0.2)"
          border="2px solid"
          borderColor="rgba(37, 99, 235, 0.3)"
          _hover={{
            bg: 'linear-gradient(135deg, #1d4ed8 0%, #1e40af 100%)',
            transform: 'scale(1.1) rotate(5deg)',
            boxShadow: '0 12px 35px rgba(37, 99, 235, 0.8), 0 0 60px rgba(37, 99, 235, 0.5), inset 0 1px 0 rgba(255, 255, 255, 0.2)',
          }}
          _active={{
            transform: 'scale(0.95)',
          }}
          transition="all 0.3s cubic-bezier(0.4, 0, 0.2, 1)"
          animation="pulse 3s infinite"
        />
        {/* ✅ Feature 6: Notification Badge */}
        {notificationCount > 0 && (
          <Badge
            position="absolute"
            top="-4px"
            right="-4px"
            bg="linear-gradient(135deg, #ef4444 0%, #dc2626 100%)"
            color="white"
            borderRadius="full"
            fontSize="xs"
            fontWeight="bold"
            px={2}
            py={0.5}
            boxShadow="0 0 15px rgba(239, 68, 68, 0.8), 0 2px 8px rgba(239, 68, 68, 0.4)"
            animation="pulse 2s infinite"
            border="2px solid #000000"
          >
            {notificationCount > 9 ? '9+' : notificationCount}
          </Badge>
        )}
      </Box>
    );
  }

  if (isMinimized) {
    return (
      <Card
        variant="unstyled"
        position="fixed"
        bottom="20px"
        right="20px"
        width="320px"
        boxShadow="0 12px 40px rgba(0, 0, 0, 0.9), 0 0 30px rgba(37, 99, 235, 0.4), inset 0 1px 0 rgba(255, 255, 255, 0.05)"
        zIndex={1000}
        bg={bgColor}
        border="1px solid"
        borderColor={borderColor}
        borderRadius="xl"
        transition="all 0.4s cubic-bezier(0.4, 0, 0.2, 1)"
        sx={{ 
          bg: `${bgColor} !important`,
          backgroundColor: `${bgColor} !important`,
          background: `${bgColor} !important`,
          borderColor: `${borderColor} !important`,
          '&': {
            backgroundColor: '#000000 !important',
            background: '#000000 !important',
          },
        }}
        __css={{
          backgroundColor: '#000000 !important',
          background: '#000000 !important',
        }}
        style={{
          backgroundColor: '#000000',
          background: '#000000',
        }}
        _hover={{
          boxShadow: '0 16px 50px rgba(0, 0, 0, 0.95), 0 0 40px rgba(37, 99, 235, 0.5), inset 0 1px 0 rgba(255, 255, 255, 0.05)',
          transform: 'translateY(-2px)',
        }}
        _before={{
          content: '""',
          position: 'absolute',
          top: 0,
          left: 0,
          right: 0,
          height: '1px',
          background: 'linear-gradient(90deg, transparent 0%, rgba(37, 99, 235, 0.5) 50%, transparent 100%)',
        }}
      >
        <CardBody 
          p={4} 
          bg={bgColor} 
          sx={{ 
            bg: `${bgColor} !important`,
            backgroundColor: `${bgColor} !important`,
            '&': {
              backgroundColor: '#000000 !important',
              background: '#000000 !important',
            },
          }}
          __css={{
            backgroundColor: '#000000 !important',
            background: '#000000 !important',
          }}
          css={{
            backgroundColor: '#000000 !important',
            background: '#000000 !important',
          }}
          style={{
            backgroundColor: '#000000',
            background: '#000000',
          }}
        >
          <HStack justify="space-between">
            <HStack spacing={3}>
              <Avatar 
                size="md" 
                bg="linear-gradient(135deg, #2563eb 0%, #1d4ed8 100%)"
                icon={<FiZap />}
                boxShadow="0 0 20px rgba(37, 99, 235, 0.6), 0 4px 12px rgba(37, 99, 235, 0.3)"
                border="2px solid"
                borderColor="rgba(37, 99, 235, 0.3)"
                transition="all 0.3s ease"
                _hover={{
                  transform: 'scale(1.1) rotate(5deg)',
                  boxShadow: '0 0 30px rgba(37, 99, 235, 0.8), 0 6px 15px rgba(37, 99, 235, 0.4)',
                }}
              />
              <VStack align="start" spacing={1}>
                <HStack spacing={2}>
                  <Text fontSize="md" fontWeight="bold" color={textColor} letterSpacing="0.5px">
                    Speedy AI
                  </Text>
                  <Badge 
                    bg="linear-gradient(135deg, #10b981 0%, #059669 100%)"
                    color="#FFFFFF"
                    fontSize="xs"
                    px={2}
                    py={0.5}
                    borderRadius="full"
                    boxShadow="0 0 10px rgba(16, 185, 129, 0.5)"
                    fontWeight="semibold"
                  >
                    {language === 'ar' ? 'متصل' : 'Online'}
                  </Badge>
                </HStack>
                <Text fontSize="xs" color="#9ca3af" fontWeight="medium">
                  {language === 'ar' ? 'جاهز للمساعدة' : 'Ready to help'}
                </Text>
              </VStack>
            </HStack>
            <HStack spacing={1}>
              <IconButton
                aria-label="Sidebar"
                icon={<FiSidebar />}
                size="sm"
                variant="ghost"
                color={showSidebar ? '#10b981' : textColor}
                borderRadius="md"
                _hover={{ bg: '#1a1a1a', color: '#10b981', transform: 'scale(1.1)' }}
                onClick={() => setShowSidebar(!showSidebar)}
                transition="all 0.2s ease"
              />
              <IconButton
                aria-label="Export"
                icon={<FiDownload />}
                size="sm"
                variant="ghost"
                color={textColor}
                borderRadius="md"
                _hover={{ bg: '#1a1a1a', color: '#10b981', transform: 'scale(1.1)' }}
                onClick={handleExportConversation}
                isDisabled={messages.length === 0}
                transition="all 0.2s ease"
              />
              <IconButton
                aria-label="Maximize"
                icon={<FiMaximize2 />}
                size="sm"
                variant="ghost"
                color={textColor}
                borderRadius="md"
                _hover={{ bg: '#1a1a1a', color: '#2563eb', transform: 'scale(1.1)' }}
                onClick={handleToggle}
                transition="all 0.2s ease"
              />
              <IconButton
                aria-label="Close"
                icon={<FiX />}
                size="sm"
                variant="ghost"
                color={textColor}
                borderRadius="md"
                _hover={{ bg: '#1a1a1a', color: '#ef4444', transform: 'scale(1.1)' }}
                onClick={handleClose}
                transition="all 0.2s ease"
              />
            </HStack>
          </HStack>
        </CardBody>
      </Card>
    );
  }

  return (
    <Card
      variant="unstyled"
      position="fixed"
      bottom="20px"
      right="20px"
      width="420px"
      height="650px"
      boxShadow="0 20px 60px rgba(0, 0, 0, 0.95), 0 0 50px rgba(37, 99, 235, 0.4), inset 0 1px 0 rgba(255, 255, 255, 0.05)"
      zIndex={1000}
      bg={bgColor}
      border="1px solid"
      borderColor={borderColor}
      borderRadius="2xl"
      display="flex"
      flexDirection="column"
      overflow="hidden"
      transition="all 0.4s cubic-bezier(0.4, 0, 0.2, 1)"
      sx={{ 
        bg: `${bgColor} !important`,
        backgroundColor: `${bgColor} !important`,
        background: `${bgColor} !important`,
        borderColor: `${borderColor} !important`,
        '&': {
          backgroundColor: '#000000 !important',
          background: '#000000 !important',
        },
      }}
      __css={{
        backgroundColor: '#000000 !important',
        background: '#000000 !important',
      }}
      style={{
        backgroundColor: '#000000',
        background: '#000000',
      }}
      _hover={{
        boxShadow: '0 25px 70px rgba(0, 0, 0, 0.98), 0 0 60px rgba(37, 99, 235, 0.5), inset 0 1px 0 rgba(255, 255, 255, 0.05)',
      }}
    >
      {/* Header */}
      <CardBody 
        p={0} 
        borderBottom="1px solid" 
        borderColor={borderColor}
        bg={headerBg}
        sx={{ 
          bg: `${headerBg} !important`, 
          backgroundColor: `${headerBg} !important`,
          borderColor: `${borderColor} !important`,
          background: `linear-gradient(135deg, ${headerBg} 0%, #0a0a0a 100%) !important`,
          backgroundImage: `linear-gradient(135deg, ${headerBg} 0%, #0a0a0a 100%) !important`,
          '&': {
            backgroundColor: '#111111 !important',
            background: 'linear-gradient(135deg, #111111 0%, #0a0a0a 100%) !important',
          },
        }}
        __css={{
          backgroundColor: '#111111 !important',
          background: 'linear-gradient(135deg, #111111 0%, #0a0a0a 100%) !important',
        }}
        css={{
          backgroundColor: '#111111 !important',
          background: 'linear-gradient(135deg, #111111 0%, #0a0a0a 100%) !important',
        }}
        style={{
          backgroundColor: '#111111',
          background: 'linear-gradient(135deg, #111111 0%, #0a0a0a 100%)',
        }}
        position="relative"
        _before={{
          content: '""',
          position: 'absolute',
          top: 0,
          left: 0,
          right: 0,
          height: '1px',
          background: 'linear-gradient(90deg, transparent 0%, rgba(37, 99, 235, 0.5) 50%, transparent 100%)',
        }}
      >
        <Flex justify="space-between" align="center" p={4} style={{ backgroundColor: '#111111' }}>
          <HStack spacing={3}>
            <Avatar 
              size="md" 
              bg="linear-gradient(135deg, #2563eb 0%, #1d4ed8 100%)"
              icon={<FiZap />}
              boxShadow="0 0 25px rgba(37, 99, 235, 0.7), 0 4px 15px rgba(37, 99, 235, 0.4)"
              border="2px solid"
              borderColor="rgba(37, 99, 235, 0.3)"
              transition="all 0.3s ease"
              _hover={{
                transform: 'scale(1.1) rotate(5deg)',
                boxShadow: '0 0 35px rgba(37, 99, 235, 0.9), 0 6px 20px rgba(37, 99, 235, 0.5)',
              }}
            />
            <VStack align="start" spacing={1}>
              <HStack spacing={2}>
                <Text fontSize="lg" fontWeight="bold" color={textColor} letterSpacing="0.5px">
                  Speedy AI
                </Text>
                <Badge 
                  bg="linear-gradient(135deg, #10b981 0%, #059669 100%)"
                  color="#FFFFFF"
                  fontSize="xs"
                  px={2.5}
                  py={1}
                  borderRadius="full"
                  boxShadow="0 0 15px rgba(16, 185, 129, 0.6), 0 2px 8px rgba(16, 185, 129, 0.3)"
                  fontWeight="semibold"
                  letterSpacing="0.5px"
                  position="relative"
                  _before={{
                    content: '""',
                    position: 'absolute',
                    top: '50%',
                    left: '6px',
                    transform: 'translateY(-50%)',
                    width: '6px',
                    height: '6px',
                    borderRadius: '50%',
                    bg: '#FFFFFF',
                    boxShadow: '0 0 8px rgba(255, 255, 255, 0.8)',
                    animation: 'pulse 2s infinite',
                  }}
                >
                  {language === 'ar' ? 'متصل' : 'Online'}
                </Badge>
              </HStack>
              <Text fontSize="xs" color="#9ca3af" fontWeight="medium">
                {language === 'ar' ? 'مساعدك الذكي' : 'Your AI Assistant'}
              </Text>
            </VStack>
          </HStack>
          <HStack spacing={1}>
            {/* ✅ Feature 4: Examples Button */}
            <IconButton
              aria-label="Examples"
              icon={<FiBookOpen />}
              size="sm"
              variant="ghost"
              color={textColor}
              borderRadius="md"
              _hover={{ bg: '#1a1a1a', color: '#10b981', transform: 'scale(1.1)' }}
              onClick={() => setShowExamples(!showExamples)}
              transition="all 0.2s ease"
              title={language === 'ar' ? 'أمثلة' : 'Examples'}
            />
            {/* ✅ Feature 3: Export Button */}
            {messages.length > 1 && (
              <IconButton
                aria-label="Export"
                icon={<FiDownload />}
                size="sm"
                variant="ghost"
                color={textColor}
                borderRadius="md"
                _hover={{ bg: '#1a1a1a', color: '#f59e0b', transform: 'scale(1.1)' }}
                onClick={handleExportConversation}
                transition="all 0.2s ease"
                title={language === 'ar' ? 'تصدير' : 'Export'}
              />
            )}
            <Select
              size="sm"
              value={language}
              onChange={(e) => setLanguage(e.target.value as 'en' | 'ar')}
              width="70px"
              bg={inputBg}
              color={textColor}
              borderColor={borderColor}
              borderRadius="md"
              fontWeight="medium"
              fontSize="xs"
              _focus={{
                borderColor: '#2563eb',
                boxShadow: '0 0 0 2px rgba(37, 99, 235, 0.2)',
                bg: inputBg,
              }}
              _hover={{
                borderColor: '#2563eb',
                bg: '#1f1f1f',
              }}
              transition="all 0.2s ease"
            >
              <option value="en" style={{ background: '#000000', color: '#FFFFFF' }}>EN</option>
              <option value="ar" style={{ background: '#000000', color: '#FFFFFF' }}>AR</option>
            </Select>
            <IconButton
              aria-label="Minimize"
              icon={<FiMinimize2 />}
              size="sm"
              variant="ghost"
              color={textColor}
              borderRadius="md"
              _hover={{ bg: '#1a1a1a', color: '#2563eb', transform: 'scale(1.1)' }}
              onClick={handleToggle}
              transition="all 0.2s ease"
            />
            <IconButton
              aria-label="Close"
              icon={<FiX />}
              size="sm"
              variant="ghost"
              color={textColor}
              borderRadius="md"
              _hover={{ bg: '#1a1a1a', color: '#ef4444', transform: 'scale(1.1)' }}
              onClick={handleClose}
              transition="all 0.2s ease"
            />
          </HStack>
        </Flex>
      </CardBody>

      {/* ✅ Feature 8: Search Bar */}
      {messages.length > 3 && (
        <CardBody p={3} borderBottom="1px solid" borderColor={borderColor} bg={headerBg}>
          <Input
            placeholder={language === 'ar' ? '🔍 بحث في المحادثة...' : '🔍 Search conversation...'}
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            size="sm"
            bg={inputBg}
            color={textColor}
            borderColor={borderColor}
            borderRadius="lg"
            fontSize="xs"
            _focus={{
              borderColor: '#2563eb',
              boxShadow: '0 0 0 2px rgba(37, 99, 235, 0.2)',
            }}
          />
        </CardBody>
      )}

      {/* ✅ Feature 4: Example Queries Panel */}
      {showExamples && (
        <CardBody p={4} borderBottom="1px solid" borderColor={borderColor} bg="rgba(37, 99, 235, 0.05)">
          <VStack align="stretch" spacing={2}>
            <HStack justify="space-between">
              <Text fontSize="xs" fontWeight="bold" color="#2563eb">
                {language === 'ar' ? '📚 أمثلة متقدمة' : '📚 ADVANCED EXAMPLES'}
              </Text>
              <IconButton
                aria-label="Close"
                icon={<FiX />}
                size="xs"
                variant="ghost"
                onClick={() => setShowExamples(false)}
              />
            </HStack>
            <VStack spacing={1} align="stretch">
              {(language === 'ar' ? [
                'أعطني تحليل كامل لطلب SV-12345',
                'ما هي أفضل 3 سائقين لمانشستر؟',
                'كيف يمكنني تحسين كفاءة المسارات؟',
                'اعرض لي توقعات الإيرادات للشهر القادم',
                'ما هي المشاكل الحالية التي تحتاج انتباهي؟'
              ] : [
                'Give me complete analysis of order SV-12345',
                'Who are the top 3 drivers for Manchester area?',
                'How can I improve route efficiency?',
                'Show me revenue forecast for next month',
                'What current issues need my attention?'
              ]).map((example, idx) => (
                <Text
                  key={idx}
                  fontSize="xs"
                  color="#9ca3af"
                  cursor="pointer"
                  p={2}
                  borderRadius="md"
                  _hover={{ bg: 'rgba(37, 99, 235, 0.1)', color: '#60a5fa' }}
                  onClick={() => {
                    setInputMessage(example);
                    setShowExamples(false);
                  }}
                  transition="all 0.2s ease"
                >
                  {example}
                </Text>
              ))}
            </VStack>
          </VStack>
        </CardBody>
      )}

      {/* Messages */}
      <Box
        flex={1}
        overflowY="auto"
        p={5}
        bg={messagesBg}
        sx={{ 
          bg: `${messagesBg} !important`,
          backgroundColor: `${messagesBg} !important`,
          '&': {
            backgroundColor: '#0a0a0a !important',
            background: '#0a0a0a !important',
          },
        }}
        __css={{
          backgroundColor: '#0a0a0a !important',
          background: '#0a0a0a !important',
        }}
        css={{
          backgroundColor: '#0a0a0a !important',
          background: '#0a0a0a !important',
          '&::-webkit-scrollbar': {
            width: '10px',
          },
          '&::-webkit-scrollbar-track': {
            background: '#0a0a0a',
            borderRadius: '10px',
          },
          '&::-webkit-scrollbar-thumb': {
            background: 'linear-gradient(180deg, #333333 0%, #444444 100%)',
            borderRadius: '10px',
            border: '2px solid #0a0a0a',
          },
          '&::-webkit-scrollbar-thumb:hover': {
            background: 'linear-gradient(180deg, #444444 0%, #555555 100%)',
          },
        }}
        style={{
          backgroundColor: '#0a0a0a',
          background: '#0a0a0a',
        }}
        _before={{
          content: '""',
          position: 'absolute',
          top: 0,
          left: 0,
          right: 0,
          height: '40px',
          background: 'linear-gradient(180deg, rgba(10, 10, 10, 0.9) 0%, transparent 100%)',
          pointerEvents: 'none',
          zIndex: 1,
        }}
        _after={{
          content: '""',
          position: 'absolute',
          bottom: 0,
          left: 0,
          right: 0,
          height: '40px',
          background: 'linear-gradient(0deg, rgba(10, 10, 10, 0.9) 0%, transparent 100%)',
          pointerEvents: 'none',
          zIndex: 1,
        }}
      >
        <VStack spacing={5} align="stretch" position="relative" zIndex={2}>
          {/* ✅ NEW: Quick Actions Panel (show only if no messages yet or after welcome) */}
          {showSuggestions && messages.length <= 1 && (
            <Box
              p={4}
              borderRadius="xl"
              bg="rgba(37, 99, 235, 0.05)"
              border="1px solid rgba(37, 99, 235, 0.2)"
              boxShadow="0 4px 15px rgba(37, 99, 235, 0.15)"
            >
              <Text 
                fontSize="xs" 
                fontWeight="bold" 
                color="#2563eb" 
                mb={3}
                letterSpacing="0.5px"
              >
                {language === 'ar' ? '⚡ إجراءات سريعة' : '⚡ QUICK ACTIONS'}
              </Text>
              <VStack spacing={2} align="stretch">
                {quickActions.map((action, idx) => (
                  <Button
                    key={idx}
                    size="sm"
                    variant="ghost"
                    justifyContent="flex-start"
                    onClick={() => handleQuickAction(action.prompt)}
                    color={textColor}
                    bg="rgba(255, 255, 255, 0.03)"
                    borderRadius="lg"
                    fontWeight="medium"
                    fontSize="xs"
                    h="auto"
                    py={2}
                    px={3}
                    _hover={{
                      bg: 'rgba(37, 99, 235, 0.15)',
                      transform: 'translateX(4px)',
                      color: '#60a5fa'
                    }}
                    transition="all 0.2s ease"
                    textAlign="left"
                  >
                    {action.label}
                  </Button>
                ))}
              </VStack>
            </Box>
          )}
          
          {filteredMessages.map((message, index) => (
            <Box
              key={message.id}
              opacity={0}
              animation={`fadeIn 0.3s ease forwards ${index * 0.1}s`}
              css={{
                '@keyframes fadeIn': {
                  from: { opacity: 0, transform: 'translateY(10px)' },
                  to: { opacity: 1, transform: 'translateY(0)' },
                },
              }}
            >
              <HStack
                align="flex-start"
                spacing={3}
                justify={message.role === 'user' ? 'flex-end' : 'flex-start'}
              >
                {message.role === 'assistant' && (
                  <Avatar 
                    size="md" 
                    bg="linear-gradient(135deg, #2563eb 0%, #1d4ed8 100%)"
                    icon={<FiZap />}
                    boxShadow="0 0 20px rgba(37, 99, 235, 0.6), 0 4px 12px rgba(37, 99, 235, 0.3)"
                    border="2px solid"
                    borderColor="rgba(37, 99, 235, 0.3)"
                    transition="all 0.3s ease"
                    _hover={{
                      transform: 'scale(1.1) rotate(5deg)',
                      boxShadow: '0 0 30px rgba(37, 99, 235, 0.8), 0 6px 15px rgba(37, 99, 235, 0.4)',
                    }}
                  />
                )}
                <VStack align={message.role === 'user' ? 'flex-end' : 'flex-start'} spacing={2} maxW="75%">
                  <Box
                    w="full"
                    p={4}
                    borderRadius="xl"
                    bg={
                      message.role === 'user'
                        ? 'linear-gradient(135deg, #2563eb 0%, #1d4ed8 100%)'
                        : messageBgAssistant
                    }
                    color={
                      message.role === 'user'
                        ? messageBgUserText
                        : messageBgAssistantText
                    }
                    sx={{
                      bg: message.role === 'user' 
                        ? 'linear-gradient(135deg, #2563eb 0%, #1d4ed8 100%) !important'
                        : `${messageBgAssistant} !important`,
                      color: `${message.role === 'user' ? messageBgUserText : messageBgAssistantText} !important`,
                    }}
                    boxShadow={
                      message.role === 'user'
                        ? '0 8px 20px rgba(37, 99, 235, 0.4), 0 2px 8px rgba(37, 99, 235, 0.2)'
                        : '0 8px 20px rgba(0, 0, 0, 0.6), 0 2px 8px rgba(0, 0, 0, 0.3)'
                    }
                    border={
                      message.role === 'assistant'
                        ? '1px solid rgba(51, 51, 51, 0.5)'
                        : 'none'
                    }
                    transition="all 0.3s cubic-bezier(0.4, 0, 0.2, 1)"
                    _hover={{
                      transform: 'translateY(-2px) scale(1.02)',
                      boxShadow: message.role === 'user'
                        ? '0 12px 28px rgba(37, 99, 235, 0.5), 0 4px 12px rgba(37, 99, 235, 0.3)'
                        : '0 12px 28px rgba(0, 0, 0, 0.7), 0 4px 12px rgba(0, 0, 0, 0.4)',
                    }}
                    position="relative"
                    _before={message.role === 'user' ? {
                      content: '""',
                      position: 'absolute',
                      top: 0,
                      left: 0,
                      right: 0,
                      height: '1px',
                      background: 'linear-gradient(90deg, transparent 0%, rgba(255, 255, 255, 0.2) 50%, transparent 100%)',
                    } : {}}
                  >
                    {/* ✅ Feature 7: Rich Formatting */}
                    <Text 
                      fontSize="sm" 
                      whiteSpace="pre-wrap" 
                      lineHeight="1.7"
                      fontWeight="medium"
                      letterSpacing="0.2px"
                      dangerouslySetInnerHTML={{
                        __html: message.content
                          .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
                          .replace(/\*(.*?)\*/g, '<em>$1</em>')
                          .replace(/`(.*?)`/g, '<code style="background: rgba(255,255,255,0.1); padding: 2px 6px; border-radius: 4px; font-family: monospace;">$1</code>')
                          .replace(/\n/g, '<br />')
                      }}
                    />
                    <HStack mt={2} justify="space-between">
                      <Text
                        fontSize="xs"
                        opacity={0.7}
                        fontWeight="medium"
                        color={message.role === 'user' ? 'rgba(255, 255, 255, 0.9)' : '#9ca3af'}
                      >
                        {message.timestamp.toLocaleTimeString([], {
                          hour: '2-digit',
                          minute: '2-digit',
                        })}
                      </Text>
                      
                      {/* ✅ Feature 1 & 2: Action Buttons (only for assistant messages) */}
                      {message.role === 'assistant' && (
                        <HStack spacing={1}>
                          <IconButton
                            aria-label="Copy"
                            icon={message.copied ? <FiCheck /> : <FiCopy />}
                            size="xs"
                            variant="ghost"
                            color={message.copied ? '#10b981' : '#9ca3af'}
                            onClick={() => handleCopyMessage(message.id, message.content)}
                            _hover={{ color: '#60a5fa', transform: 'scale(1.1)' }}
                            transition="all 0.2s ease"
                          />
                          <IconButton
                            aria-label="Thumbs up"
                            icon={<FiThumbsUp />}
                            size="xs"
                            variant="ghost"
                            color={message.feedback === 'up' ? '#10b981' : '#9ca3af'}
                            onClick={() => handleFeedback(message.id, 'up')}
                            _hover={{ color: '#10b981', transform: 'scale(1.1)' }}
                            transition="all 0.2s ease"
                          />
                          <IconButton
                            aria-label="Thumbs down"
                            icon={<FiThumbsDown />}
                            size="xs"
                            variant="ghost"
                            color={message.feedback === 'down' ? '#ef4444' : '#9ca3af'}
                            onClick={() => handleFeedback(message.id, 'down')}
                            _hover={{ color: '#ef4444', transform: 'scale(1.1)' }}
                            transition="all 0.2s ease"
                          />
                        </HStack>
                      )}
                    </HStack>
                  </Box>
                </VStack>
                {message.role === 'user' && (
                  <Avatar 
                    size="md" 
                    bg="linear-gradient(135deg, #4b5563 0%, #374151 100%)"
                    icon={<FiUser />}
                    boxShadow="0 0 15px rgba(75, 85, 99, 0.6), 0 4px 12px rgba(75, 85, 99, 0.3)"
                    border="2px solid"
                    borderColor="rgba(75, 85, 99, 0.3)"
                    transition="all 0.3s ease"
                    _hover={{
                      transform: 'scale(1.1) rotate(-5deg)',
                      boxShadow: '0 0 25px rgba(75, 85, 99, 0.8), 0 6px 15px rgba(75, 85, 99, 0.4)',
                    }}
                  />
                )}
              </HStack>
            </Box>
          ))}
          {isLoading && (
            <HStack align="flex-start" spacing={3} position="relative" zIndex={2}>
              <Avatar 
                size="md" 
                bg="linear-gradient(135deg, #2563eb 0%, #1d4ed8 100%)"
                icon={<FiZap />}
                boxShadow="0 0 20px rgba(37, 99, 235, 0.6), 0 4px 12px rgba(37, 99, 235, 0.3)"
                border="2px solid"
                borderColor="rgba(37, 99, 235, 0.3)"
                animation="pulse 2s infinite"
              />
              <Box
                p={4}
                borderRadius="xl"
                bg={messageBgAssistant}
                border="1px solid rgba(51, 51, 51, 0.5)"
                boxShadow="0 8px 20px rgba(0, 0, 0, 0.6), 0 2px 8px rgba(0, 0, 0, 0.3)"
                position="relative"
                overflow="hidden"
                _before={{
                  content: '""',
                  position: 'absolute',
                  top: 0,
                  left: 0,
                  right: 0,
                  height: '1px',
                  background: 'linear-gradient(90deg, transparent 0%, rgba(37, 99, 235, 0.5) 50%, transparent 100%)',
                }}
              >
                <HStack spacing={2}>
                  <Spinner size="sm" color="#2563eb" thickness="3px" speed="0.8s" />
                  <Text fontSize="xs" color="#9ca3af" fontWeight="medium">
                    {language === 'ar' ? 'جاري الكتابة...' : 'Typing...'}
                  </Text>
                </HStack>
              </Box>
            </HStack>
          )}
          <div ref={messagesEndRef} />
        </VStack>
      </Box>

      {assistantInsights && (
        <CardBody
          p={4}
          borderTop="1px solid"
          borderColor={borderColor}
          bg="rgba(15, 23, 42, 0.6)"
        >
          {renderInsightsPanel(assistantInsights)}
        </CardBody>
      )}

      {/* Input */}
      <CardBody 
        p={0} 
        borderTop="1px solid" 
        borderColor={borderColor}
        bg={headerBg}
        sx={{ 
          bg: `${headerBg} !important`,
          backgroundColor: `${headerBg} !important`,
          borderColor: `${borderColor} !important`,
          background: `linear-gradient(135deg, ${headerBg} 0%, #0a0a0a 100%) !important`,
          backgroundImage: `linear-gradient(135deg, ${headerBg} 0%, #0a0a0a 100%) !important`,
          '&': {
            backgroundColor: '#111111 !important',
            background: 'linear-gradient(135deg, #111111 0%, #0a0a0a 100%) !important',
          },
        }}
        __css={{
          backgroundColor: '#111111 !important',
          background: 'linear-gradient(135deg, #111111 0%, #0a0a0a 100%) !important',
        }}
        css={{
          backgroundColor: '#111111 !important',
          background: 'linear-gradient(135deg, #111111 0%, #0a0a0a 100%) !important',
        }}
        style={{
          backgroundColor: '#111111',
          background: 'linear-gradient(135deg, #111111 0%, #0a0a0a 100%)',
        }}
        position="relative"
        _before={{
          content: '""',
          position: 'absolute',
          top: 0,
          left: 0,
          right: 0,
          height: '1px',
          background: 'linear-gradient(90deg, transparent 0%, rgba(37, 99, 235, 0.3) 50%, transparent 100%)',
        }}
      >
        <VStack spacing={0} style={{ backgroundColor: '#111111' }}>
          <HStack p={4} spacing={3} align="flex-end" style={{ backgroundColor: '#111111' }}>
            <Textarea
              ref={inputRef}
              value={inputMessage}
              onChange={(e) => setInputMessage(e.target.value)}
              onKeyPress={handleKeyPress}
              placeholder={language === 'ar' ? 'اكتب رسالتك...' : 'Type your message...'}
              size="md"
              resize="none"
              rows={2}
              flex={1}
              bg={inputBg}
              color={textColor}
              borderColor={borderColor}
              borderRadius="xl"
              borderWidth="2px"
              fontWeight="medium"
              letterSpacing="0.2px"
              _placeholder={{
                color: '#6b7280',
                fontWeight: 'normal',
              }}
              _focus={{
                borderColor: '#2563eb',
                boxShadow: '0 0 0 3px rgba(37, 99, 235, 0.1), 0 0 20px rgba(37, 99, 235, 0.2)',
                bg: '#1f1f1f',
              }}
              _hover={{
                borderColor: '#2563eb',
                bg: '#1f1f1f',
              }}
              transition="all 0.3s cubic-bezier(0.4, 0, 0.2, 1)"
            />
            <VStack spacing={2} flexShrink={0}>
              <HStack spacing={1}>
                <input
                  ref={fileInputRef}
                  type="file"
                  accept=".pdf,.csv,.txt,.png,.jpg,.jpeg"
                  onChange={handleFileUpload}
                  style={{ display: 'none' }}
                />
                <IconButton
                  aria-label="Upload File"
                  icon={<FiUpload />}
                  size="sm"
                  variant="ghost"
                  color={uploadedFile ? '#10b981' : '#9ca3af'}
                  _hover={{ bg: '#1a1a1a', color: '#10b981', transform: 'scale(1.1)' }}
                  onClick={() => fileInputRef.current?.click()}
                  transition="all 0.2s ease"
                />
                <IconButton
                  aria-label="Voice Input"
                  icon={<FiMic />}
                  size="sm"
                  variant="ghost"
                  color={isRecording ? '#ef4444' : '#9ca3af'}
                  _hover={{ bg: '#1a1a1a', color: isRecording ? '#ef4444' : '#10b981', transform: 'scale(1.1)' }}
                  onClick={handleVoiceToggle}
                  transition="all 0.2s ease"
                  animation={isRecording ? 'pulse 1.5s infinite' : 'none'}
                />
              </HStack>
              <IconButton
                aria-label="Send"
                icon={<FiSend style={{ color: '#FFFFFF' }} />}
                bg="linear-gradient(135deg, #10b981 0%, #059669 100%)"
                color="#FFFFFF"
                size="md"
                borderRadius="xl"
                onClick={handleSendMessage}
                isLoading={isLoading}
                isDisabled={!inputMessage.trim() || isLoading}
                _hover={{
                  bg: 'linear-gradient(135deg, #059669 0%, #047857 100%)',
                  transform: 'scale(1.08) rotate(5deg)',
                  boxShadow: '0 0 25px rgba(16, 185, 129, 0.6), 0 8px 20px rgba(16, 185, 129, 0.4)',
                }}
                _active={{
                  transform: 'scale(0.95)',
                }}
                _disabled={{
                  bg: '#1a1a1a',
                  color: '#6b7280',
                  cursor: 'not-allowed',
                  opacity: 0.5,
                  border: '1px solid #333333',
                }}
                transition="all 0.3s cubic-bezier(0.4, 0, 0.2, 1)"
                boxShadow="0 0 15px rgba(16, 185, 129, 0.4), 0 4px 12px rgba(16, 185, 129, 0.2)"
                border="2px solid"
                borderColor="rgba(16, 185, 129, 0.3)"
              />
              {messages.length > 1 && (
                <Button
                  size="xs"
                  variant="ghost"
                  onClick={handleClearChat}
                  fontSize="xs"
                  color="#9ca3af"
                  fontWeight="medium"
                  borderRadius="md"
                  _hover={{
                    bg: '#1a1a1a',
                    color: '#ef4444',
                    transform: 'translateY(-1px)',
                  }}
                  transition="all 0.2s ease"
                >
                  {language === 'ar' ? 'مسح' : 'Clear'}
                </Button>
              )}
            </VStack>
          </HStack>
        </VStack>
      </CardBody>
    </Card>
  );
}

'use client';

import React, { useState, useRef, useEffect } from 'react';
import {
  Box,
  VStack,
  HStack,
  Text,
  IconButton,
  Avatar,
  Spinner,
  useToast,
  Textarea,
  Tooltip,
  Menu,
  MenuButton,
  MenuList,
  MenuItem,
} from '@chakra-ui/react';
import {
  FiSend,
  FiX,
  FiMessageCircle,
  FiUser,
  FiCopy,
  FiRotateCw,
  FiEdit3,
  FiTrash2,
  FiPlusCircle,
  FiMenu,
} from 'react-icons/fi';

interface Message {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  timestamp: Date;
}

interface SpeedyAIChatbotEnhancedProps {
  isOpen?: boolean;
  onClose?: () => void;
  adminName?: string;
}

export default function SpeedyAIChatbotEnhanced({
  isOpen: initialIsOpen = false,
  onClose,
  adminName = 'Admin',
}: SpeedyAIChatbotEnhancedProps) {
  const [isOpen, setIsOpen] = useState(initialIsOpen);
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputMessage, setInputMessage] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const toast = useToast();

  // Auto-scroll to bottom
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  // Focus textarea when opened
  useEffect(() => {
    if (isOpen) {
      setTimeout(() => textareaRef.current?.focus(), 100);
    }
  }, [isOpen]);

  // Initialize with welcome message
  useEffect(() => {
    if (isOpen && messages.length === 0) {
      setMessages([
        {
          id: 'welcome',
          role: 'assistant',
          content: `Hello ${adminName}! I'm Speedy AI, your intelligent assistant. How can I help you today?`,
          timestamp: new Date(),
        },
      ]);
    }
  }, [isOpen, adminName, messages.length]);

  const handleSendMessage = async () => {
    if (!inputMessage.trim() || isLoading) return;

    const userMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: inputMessage.trim(),
      timestamp: new Date(),
    };

    setMessages((prev) => [...prev, userMessage]);
    setInputMessage('');
    setIsLoading(true);

    try {
      const response = await fetch('/api/admin/ai/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          message: userMessage.content,
          conversationHistory: messages.map(m => ({ role: m.role, content: m.content })),
          language: 'en',
        }),
      });

      if (!response.ok) throw new Error('Failed to get AI response');

      const data = await response.json();
      const assistantMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: data.response || 'No response',
        timestamp: new Date(),
      };

      setMessages((prev) => [...prev, assistantMessage]);
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to get response from AI',
        status: 'error',
        duration: 3000,
      });
    } finally {
      setIsLoading(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage();
    }
  };

  const copyMessage = (content: string) => {
    navigator.clipboard.writeText(content);
    toast({
      title: 'Copied',
      status: 'success',
      duration: 2000,
    });
  };

  const clearChat = () => {
    setMessages([{
      id: 'welcome',
      role: 'assistant',
      content: `Hello ${adminName}! I'm Speedy AI, your intelligent assistant. How can I help you today?`,
      timestamp: new Date(),
    }]);
  };

  if (!isOpen) {
    return (
      <IconButton
        icon={<FiMessageCircle size={24} />}
        aria-label="Open AI Assistant"
        onClick={() => setIsOpen(true)}
        position="fixed"
        bottom={6}
        right={6}
        size="lg"
        colorScheme="blue"
        borderRadius="full"
        boxShadow="0 8px 32px rgba(37, 99, 235, 0.4)"
        _hover={{
          transform: 'scale(1.1)',
          boxShadow: '0 12px 48px rgba(37, 99, 235, 0.6)',
        }}
        transition="all 0.3s"
        zIndex={999}
      />
    );
  }

  return (
    <Box
      position="fixed"
      bottom={0}
      right={0}
      w={{ base: 'full', md: '400px', lg: '500px' }}
      h={{ base: 'full', md: '600px' }}
      bg="#2f2f2f"
      borderRadius={{ base: '0', md: '16px 16px 0 0' }}
      boxShadow="0 0 40px rgba(0,0,0,0.4)"
      zIndex={1000}
      display="flex"
      flexDirection="column"
      overflow="hidden"
    >
      {/* Header - ChatGPT style */}
      <HStack
        px={4}
        py={3}
        bg="#171717"
        borderBottom="1px solid #3d3d3d"
        justify="space-between"
      >
        <HStack spacing={3}>
          <Avatar 
            size="sm" 
            name="Speedy AI"
            bg="linear-gradient(135deg, #10b981 0%, #059669 100%)"
            color="white"
          />
          <VStack align="start" spacing={0}>
            <Text fontSize="sm" fontWeight="600" color="white">
              Speedy AI
            </Text>
            <Text fontSize="xs" color="gray.400">
              Always here to help
            </Text>
          </VStack>
        </HStack>
        
        <HStack spacing={1}>
          <Tooltip label="New chat">
            <IconButton
              icon={<FiPlusCircle />}
              aria-label="New chat"
              size="sm"
              variant="ghost"
              color="gray.400"
              _hover={{ color: 'white', bg: 'rgba(255,255,255,0.1)' }}
              onClick={clearChat}
            />
          </Tooltip>
          <Tooltip label="Menu">
            <Menu>
              <MenuButton
                as={IconButton}
                icon={<FiMenu />}
                aria-label="Menu"
                size="sm"
                variant="ghost"
                color="gray.400"
                _hover={{ color: 'white', bg: 'rgba(255,255,255,0.1)' }}
              />
              <MenuList bg="#2f2f2f" borderColor="#3d3d3d">
                <MenuItem 
                  icon={<FiTrash2 />} 
                  onClick={clearChat}
                  bg="transparent"
                  color="white"
                  _hover={{ bg: 'rgba(255,255,255,0.1)' }}
                >
                  Clear conversation
                </MenuItem>
              </MenuList>
            </Menu>
          </Tooltip>
          <Tooltip label="Close">
            <IconButton
              icon={<FiX />}
              aria-label="Close"
              size="sm"
              variant="ghost"
              color="gray.400"
              _hover={{ color: 'white', bg: 'rgba(255,255,255,0.1)' }}
              onClick={() => {
                setIsOpen(false);
                onClose?.();
              }}
            />
          </Tooltip>
        </HStack>
      </HStack>

      {/* Messages Area - ChatGPT style */}
      <VStack
        flex={1}
        overflowY="auto"
        spacing={0}
        bg="#212121"
        css={{
          '&::-webkit-scrollbar': { width: '8px' },
          '&::-webkit-scrollbar-track': { background: '#171717' },
          '&::-webkit-scrollbar-thumb': {
            background: '#3d3d3d',
            borderRadius: '4px',
          },
          '&::-webkit-scrollbar-thumb:hover': { background: '#4d4d4d' },
        }}
      >
        {messages.map((message, index) => (
          <Box
            key={message.id}
            w="full"
            bg={message.role === 'assistant' ? '#2f2f2f' : 'transparent'}
            borderBottom="1px solid #3d3d3d"
            py={6}
            px={4}
          >
            <HStack align="start" maxW="800px" mx="auto" spacing={4}>
              {/* Avatar */}
              <Avatar
                size="sm"
                name={message.role === 'user' ? adminName : 'Speedy AI'}
                bg={message.role === 'user' ? '#2563eb' : 'linear-gradient(135deg, #10b981 0%, #059669 100%)'}
                color="white"
                flexShrink={0}
              />

              {/* Message Content */}
              <VStack align="start" flex={1} spacing={2}>
                <Text
                  fontSize="sm"
                  color="white"
                  lineHeight="1.7"
                  whiteSpace="pre-wrap"
                  wordBreak="break-word"
                >
                  {message.content}
                </Text>

                {/* Message Actions */}
                {message.role === 'assistant' && index > 0 && (
                  <HStack spacing={2} mt={2}>
                    <Tooltip label="Copy">
                      <IconButton
                        icon={<FiCopy />}
                        aria-label="Copy message"
                        size="xs"
                        variant="ghost"
                        color="gray.500"
                        _hover={{ color: 'white', bg: 'rgba(255,255,255,0.1)' }}
                        onClick={() => copyMessage(message.content)}
                      />
                    </Tooltip>
                    <Tooltip label="Regenerate">
                      <IconButton
                        icon={<FiRotateCw />}
                        aria-label="Regenerate"
                        size="xs"
                        variant="ghost"
                        color="gray.500"
                        _hover={{ color: 'white', bg: 'rgba(255,255,255,0.1)' }}
                      />
                    </Tooltip>
                  </HStack>
                )}
              </VStack>
            </HStack>
          </Box>
        ))}

        {/* Loading indicator */}
        {isLoading && (
          <Box w="full" bg="#2f2f2f" borderBottom="1px solid #3d3d3d" py={6} px={4}>
            <HStack align="start" maxW="800px" mx="auto" spacing={4}>
              <Avatar
                size="sm"
                name="Speedy AI"
                bg="linear-gradient(135deg, #10b981 0%, #059669 100%)"
                color="white"
              />
              <HStack spacing={2} color="gray.400">
                <Spinner size="sm" />
                <Text fontSize="sm">Thinking...</Text>
              </HStack>
            </HStack>
          </Box>
        )}

        <div ref={messagesEndRef} />
      </VStack>

      {/* Input Area - ChatGPT style */}
      <Box
        bg="#2f2f2f"
        borderTop="1px solid #3d3d3d"
        p={4}
      >
        <HStack
          spacing={2}
          bg="#40414f"
          borderRadius="12px"
          border="1px solid #565869"
          p={2}
          _focusWithin={{
            borderColor: '#10b981',
            boxShadow: '0 0 0 1px #10b981',
          }}
          transition="all 0.2s"
        >
          <Textarea
            ref={textareaRef}
            value={inputMessage}
            onChange={(e) => setInputMessage(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder="Message Speedy AI..."
            resize="none"
            border="none"
            color="white"
            fontSize="sm"
            rows={1}
            maxH="200px"
            minH="24px"
            bg="transparent"
            _placeholder={{ color: 'gray.500' }}
            _focus={{ boxShadow: 'none' }}
            css={{
              '&::-webkit-scrollbar': { width: '6px' },
              '&::-webkit-scrollbar-track': { background: 'transparent' },
              '&::-webkit-scrollbar-thumb': {
                background: '#565869',
                borderRadius: '3px',
              },
            }}
          />
          <IconButton
            icon={<FiSend />}
            aria-label="Send message"
            size="sm"
            onClick={handleSendMessage}
            isDisabled={!inputMessage.trim() || isLoading}
            bg={inputMessage.trim() && !isLoading ? '#10b981' : 'transparent'}
            color={inputMessage.trim() && !isLoading ? 'white' : 'gray.500'}
            _hover={{
              bg: inputMessage.trim() && !isLoading ? '#059669' : 'rgba(255,255,255,0.1)',
            }}
            borderRadius="8px"
            transition="all 0.2s"
          />
        </HStack>
        
        <Text fontSize="xs" color="gray.600" mt={2} textAlign="center">
          Speedy AI can make mistakes. Verify important information.
        </Text>
      </Box>
    </Box>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import SpeedyAIChatbot from './SpeedyAIChatbot';
import AdminAIOverlay from './AdminAIOverlay';

interface AdminInfo {
  name: string;
  email: string;
}

export default function SpeedyAIChatbotProvider() {
  const [adminInfo, setAdminInfo] = useState<AdminInfo | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Fetch admin info with improved retry logic
    const fetchAdminInfo = async (retryCount = 0) => {
      try {
        const response = await fetch('/api/admin/me', {
          method: 'GET',
          headers: {
            'Content-Type': 'application/json',
          },
          credentials: 'include', // Include cookies for session
        });

        if (response.ok) {
          const result = await response.json();
          if (result.success && result.admin) {
            setAdminInfo({
              name: result.admin.name || 'Admin',
              email: result.admin.email || '',
            });
            setLoading(false);
            return; // Success - no need to retry
          } else {
            console.warn('Admin info response missing success or admin data:', result);
            // Use default values if API returns unexpected format
            setAdminInfo({
              name: 'Admin',
              email: '',
            });
            setLoading(false);
            return; // Got response - no need to retry
          }
        } else {
          // Handle non-OK responses
          if (response.status === 401) {
            console.warn('Unauthorized - Admin session may have expired');
            setAdminInfo({
              name: 'Admin',
              email: '',
            });
            setLoading(false);
            return; // Auth error - no need to retry
          } else if (response.status === 404) {
            // 404 means route doesn't exist - only retry once after a short delay
            if (retryCount < 1) {
              console.log(`Route not found, retrying once (attempt ${retryCount + 1})...`);
              setTimeout(() => fetchAdminInfo(retryCount + 1), 1500);
              return;
            } else {
              // After 1 retry, give up and use defaults
              console.warn('API route /api/admin/me not found - using default admin info');
              setAdminInfo({
                name: 'Admin',
                email: '',
              });
              setLoading(false);
              return;
            }
          } else {
            console.error('Failed to fetch admin info:', response.status, response.statusText);
            setAdminInfo({
              name: 'Admin',
              email: '',
            });
            setLoading(false);
            return; // Other errors - no retry
          }
        }
      } catch (error) {
        console.error('Failed to fetch admin info:', error);
        // Retry on network errors only once
        if (retryCount < 1) {
          console.log(`Network error, retrying once (attempt ${retryCount + 1})...`);
          setTimeout(() => fetchAdminInfo(retryCount + 1), 1500);
          return;
        }
        // After 1 retry, give up and use defaults
        console.warn('Failed to fetch admin info after retries - using default values');
        setAdminInfo({
          name: 'Admin',
          email: '',
        });
        setLoading(false);
      }
    };

    fetchAdminInfo();
  }, []);

  // Show chatbot even if loading fails (with default values)
  // Use the Enterprise Grid overlay by default
  return (
    <AdminAIOverlay
      adminName={adminInfo?.name || 'Admin'}
      adminEmail={adminInfo?.email || ''}
    />
  );
}

'use client';

import { useState } from 'react';
import {
  Modal,
  ModalOverlay,
  ModalContent,
  ModalHeader,
  ModalBody,
  ModalFooter,
  Button,
  VStack,
  HStack,
  Text,
  Box,
  Icon,
  Progress,
  Badge,
  Select,
  Checkbox,
  CheckboxGroup,
  Alert,
  AlertIcon,
  Divider,
  useToast,
} from '@chakra-ui/react';
import { FiPackage, FiCheckCircle, FiAlertCircle, FiDownload } from 'react-icons/fi';

interface BulkAction {
  id: string;
  type: 'assign' | 'update_status' | 'cancel' | 'export';
  label: string;
  description: string;
  requiresSelection: boolean;
}

const BULK_ACTIONS: BulkAction[] = [
  {
    id: 'assign_drivers',
    type: 'assign',
    label: 'تعيين سائقين تلقائياً',
    description: 'تعيين أفضل السائقين المتاحين للطلبات المحددة',
    requiresSelection: true,
  },
  {
    id: 'update_status',
    type: 'update_status',
    label: 'تحديث حالة الطلبات',
    description: 'تغيير حالة مجموعة من الطلبات دفعة واحدة',
    requiresSelection: true,
  },
  {
    id: 'cancel_multiple',
    type: 'cancel',
    label: 'إلغاء طلبات متعددة',
    description: 'إلغاء مجموعة من الطلبات مع استرداد تلقائي',
    requiresSelection: true,
  },
  {
    id: 'export_data',
    type: 'export',
    label: 'تصدير البيانات',
    description: 'تصدير الطلبات المحددة إلى Excel/CSV',
    requiresSelection: false,
  },
];

interface Order {
  id: string;
  reference: string;
  status: string;
  customerName: string;
  totalPrice: number;
}

interface BulkActionsMiniAppProps {
  isOpen: boolean;
  onClose: () => void;
  orders: Order[];
  onRefresh?: () => void;
}

export function BulkActionsMiniApp({
  isOpen,
  onClose,
  orders,
  onRefresh,
}: BulkActionsMiniAppProps) {
  const [step, setStep] = useState<'select_action' | 'configure' | 'confirm' | 'executing' | 'results'>('select_action');
  const [selectedAction, setSelectedAction] = useState<BulkAction | null>(null);
  const [selectedOrders, setSelectedOrders] = useState<string[]>([]);
  const [newStatus, setNewStatus] = useState('');
  const [progress, setProgress] = useState(0);
  const [results, setResults] = useState<{ success: number; failed: number; details: any[] }>({
    success: 0,
    failed: 0,
    details: [],
  });
  const toast = useToast();

  const handleSelectAction = (action: BulkAction) => {
    setSelectedAction(action);
    setStep('configure');
  };

  const handleSelectAll = () => {
    if (selectedOrders.length === orders.length) {
      setSelectedOrders([]);
    } else {
      setSelectedOrders(orders.map(o => o.id));
    }
  };

  const handleExecute = async () => {
    if (!selectedAction) return;

    setStep('executing');
    setProgress(0);

    try {
      let command = '';
      
      switch (selectedAction.type) {
        case 'assign':
          command = `auto assign ${selectedOrders.length} orders`;
          break;
        case 'update_status':
          command = `update status to ${newStatus} for orders ${selectedOrders.join(',')}`;
          break;
        case 'cancel':
          command = `cancel orders ${selectedOrders.join(',')}`;
          break;
        case 'export':
          command = `export orders ${selectedOrders.length > 0 ? selectedOrders.join(',') : 'all'}`;
          break;
      }

      // Simulate progress
      const progressInterval = setInterval(() => {
        setProgress(prev => {
          if (prev >= 90) {
            clearInterval(progressInterval);
            return 90;
          }
          return prev + 10;
        });
      }, 500);

      const response = await fetch('/api/admin/ai-assistant/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          message: command,
          autoExecute: true,
        }),
      });

      clearInterval(progressInterval);
      setProgress(100);

      const data = await response.json();

      if (data.success) {
        setResults({
          success: selectedOrders.length,
          failed: 0,
          details: data.results || [],
        });
        
        toast({
          title: 'نجح التنفيذ',
          description: `تم تنفيذ العملية على ${selectedOrders.length} طلب`,
          status: 'success',
          duration: 5000,
        });
        
        if (onRefresh) onRefresh();
      } else {
        setResults({
          success: 0,
          failed: selectedOrders.length,
          details: [{ error: data.message }],
        });
        
        toast({
          title: 'فشل التنفيذ',
          description: data.message,
          status: 'error',
          duration: 5000,
        });
      }

      setStep('results');
    } catch (error) {
      console.error('Bulk action error:', error);
      toast({
        title: 'خطأ',
        description: 'فشل تنفيذ العملية الجماعية',
        status: 'error',
        duration: 5000,
      });
      setStep('configure');
    }
  };

  const handleReset = () => {
    setStep('select_action');
    setSelectedAction(null);
    setSelectedOrders([]);
    setNewStatus('');
    setProgress(0);
    setResults({ success: 0, failed: 0, details: [] });
  };

  return (
    <Modal isOpen={isOpen} onClose={onClose} size="xl">
      <ModalOverlay bg="blackAlpha.800" backdropFilter="blur(10px)" />
      <ModalContent dir="rtl">
        <ModalHeader>
          <HStack spacing={3}>
            <Icon as={FiPackage} boxSize={6} color="purple.500" />
            <Text>معالج الإجراءات الجماعية</Text>
          </HStack>
        </ModalHeader>

        <ModalBody>
          {/* Step 1: Select Action */}
          {step === 'select_action' && (
            <VStack spacing={4} align="stretch">
              <Text color="gray.600" fontSize="sm">
                اختر العملية التي تريد تنفيذها على مجموعة من الطلبات
              </Text>

              {BULK_ACTIONS.map(action => (
                <Box
                  key={action.id}
                  p={4}
                  borderWidth="1px"
                  borderRadius="lg"
                  cursor="pointer"
                  _hover={{ bg: 'purple.50', borderColor: 'purple.500' }}
                  onClick={() => handleSelectAction(action)}
                  transition="all 0.2s"
                >
                  <VStack align="start" spacing={1}>
                    <Text fontWeight="bold">{action.label}</Text>
                    <Text fontSize="sm" color="gray.600">
                      {action.description}
                    </Text>
                    {action.requiresSelection && (
                      <Badge colorScheme="orange" fontSize="xs">
                        يتطلب تحديد الطلبات
                      </Badge>
                    )}
                  </VStack>
                </Box>
              ))}
            </VStack>
          )}

          {/* Step 2: Configure */}
          {step === 'configure' && selectedAction && (
            <VStack spacing={4} align="stretch">
              <Alert status="info" borderRadius="md">
                <AlertIcon />
                <Box>
                  <Text fontWeight="bold">{selectedAction.label}</Text>
                  <Text fontSize="sm">{selectedAction.description}</Text>
                </Box>
              </Alert>

              {selectedAction.requiresSelection && (
                <>
                  <HStack justify="space-between">
                    <Text fontWeight="bold">تحديد الطلبات:</Text>
                    <Button size="sm" variant="outline" onClick={handleSelectAll}>
                      {selectedOrders.length === orders.length ? 'إلغاء الكل' : 'تحديد الكل'}
                    </Button>
                  </HStack>

                  <Box
                    maxH="300px"
                    overflowY="auto"
                    borderWidth="1px"
                    borderRadius="md"
                    p={3}
                  >
                    <CheckboxGroup value={selectedOrders} onChange={(values) => setSelectedOrders(values as string[])}>
                      <VStack align="stretch" spacing={2}>
                        {orders.map(order => (
                          <Checkbox key={order.id} value={order.id}>
                            <HStack spacing={2}>
                              <Text fontSize="sm">{order.reference}</Text>
                              <Badge colorScheme="blue" fontSize="xs">
                                {order.status}
                              </Badge>
                              <Text fontSize="xs" color="gray.600">
                                {order.totalPrice} ر.س
                              </Text>
                            </HStack>
                          </Checkbox>
                        ))}
                      </VStack>
                    </CheckboxGroup>
                  </Box>

                  <Text fontSize="sm" color="gray.600">
                    تم تحديد {selectedOrders.length} من {orders.length} طلب
                  </Text>
                </>
              )}

              {selectedAction.type === 'update_status' && (
                <Box>
                  <Text mb={2} fontWeight="medium">الحالة الجديدة:</Text>
                  <Select
                    placeholder="اختر الحالة"
                    value={newStatus}
                    onChange={(e) => setNewStatus(e.target.value)}
                  >
                    <option value="confirmed">مؤكد</option>
                    <option value="assigned">معين</option>
                    <option value="in_progress">قيد التنفيذ</option>
                    <option value="completed">مكتمل</option>
                    <option value="cancelled">ملغي</option>
                  </Select>
                </Box>
              )}
            </VStack>
          )}

          {/* Step 3: Executing */}
          {step === 'executing' && (
            <VStack spacing={6} py={8}>
              <Icon as={FiPackage} boxSize={16} color="purple.500" />
              <Text fontSize="lg" fontWeight="bold">
                جاري التنفيذ...
              </Text>
              <Box w="full">
                <Progress value={progress} colorScheme="purple" size="lg" hasStripe isAnimated />
                <Text textAlign="center" mt={2} fontSize="sm" color="gray.600">
                  {progress}%
                </Text>
              </Box>
              <Text fontSize="sm" color="gray.600">
                يتم معالجة {selectedOrders.length} طلب
              </Text>
            </VStack>
          )}

          {/* Step 4: Results */}
          {step === 'results' && (
            <VStack spacing={4} align="stretch">
              <Alert
                status={results.failed === 0 ? 'success' : 'warning'}
                borderRadius="md"
              >
                <AlertIcon />
                <Box flex="1">
                  <Text fontWeight="bold">
                    {results.failed === 0 ? 'نجح التنفيذ بالكامل' : 'اكتمل التنفيذ مع بعض الأخطاء'}
                  </Text>
                  <HStack spacing={4} mt={1}>
                    <HStack>
                      <Icon as={FiCheckCircle} color="green.500" />
                      <Text fontSize="sm">نجح: {results.success}</Text>
                    </HStack>
                    {results.failed > 0 && (
                      <HStack>
                        <Icon as={FiAlertCircle} color="red.500" />
                        <Text fontSize="sm">فشل: {results.failed}</Text>
                      </HStack>
                    )}
                  </HStack>
                </Box>
              </Alert>

              <Divider />

              <VStack align="stretch" spacing={2}>
                <Text fontWeight="bold">التفاصيل:</Text>
                <Box
                  maxH="200px"
                  overflowY="auto"
                  bg="gray.50"
                  p={3}
                  borderRadius="md"
                >
                  {results.details.map((detail, index) => (
                    <Text key={index} fontSize="sm" mb={1}>
                      {detail.message || detail.error || JSON.stringify(detail)}
                    </Text>
                  ))}
                </Box>
              </VStack>
            </VStack>
          )}
        </ModalBody>

        <ModalFooter>
          <HStack spacing={3}>
            {step === 'select_action' && (
              <Button onClick={onClose}>إغلاق</Button>
            )}

            {step === 'configure' && (
              <>
                <Button variant="ghost" onClick={() => setStep('select_action')}>
                  رجوع
                </Button>
                <Button
                  colorScheme="purple"
                  onClick={handleExecute}
                  isDisabled={
                    selectedAction?.requiresSelection && selectedOrders.length === 0
                  }
                >
                  تنفيذ ({selectedOrders.length} طلب)
                </Button>
              </>
            )}

            {step === 'results' && (
              <>
                <Button onClick={onClose}>إغلاق</Button>
                <Button colorScheme="purple" variant="outline" onClick={handleReset}>
                  عملية جديدة
                </Button>
              </>
            )}
          </HStack>
        </ModalFooter>
      </ModalContent>
    </Modal>
  );
}

'use client';

import { useState } from 'react';
import {
  Modal,
  ModalOverlay,
  ModalContent,
  ModalHeader,
  ModalBody,
  ModalFooter,
  Button,
  VStack,
  HStack,
  Text,
  Box,
  Icon,
  Input,
  FormControl,
  FormLabel,
  FormHelperText,
  Select,
  Progress,
  Alert,
  AlertIcon,
  Badge,
  useToast,
} from '@chakra-ui/react';
import { FiUser, FiTruck, FiFileText, FiCheckCircle } from 'react-icons/fi';

interface OnboardingStep {
  id: number;
  title: string;
  description: string;
  icon: any;
  fields: string[];
}

const ONBOARDING_STEPS: OnboardingStep[] = [
  {
    id: 1,
    title: 'المعلومات الشخصية',
    description: 'معلومات السائق الأساسية',
    icon: FiUser,
    fields: ['name', 'email', 'phone', 'nationalId'],
  },
  {
    id: 2,
    title: 'معلومات المركبة',
    description: 'تفاصيل المركبة والترخيص',
    icon: FiTruck,
    fields: ['vehicleType', 'plateNumber', 'licenseNumber'],
  },
  {
    id: 3,
    title: 'المستندات',
    description: 'رخصة القيادة والتأمين',
    icon: FiFileText,
    fields: ['driverLicense', 'insurance'],
  },
  {
    id: 4,
    title: 'المراجعة والتأكيد',
    description: 'مراجعة جميع المعلومات',
    icon: FiCheckCircle,
    fields: [],
  },
];

interface DriverData {
  name: string;
  email: string;
  phone: string;
  nationalId: string;
  vehicleType: string;
  plateNumber: string;
  licenseNumber: string;
  driverLicense: string;
  insurance: string;
}

interface DriverOnboardingMiniAppProps {
  isOpen: boolean;
  onClose: () => void;
  onComplete?: (data: DriverData) => void;
}

export function DriverOnboardingMiniApp({
  isOpen,
  onClose,
  onComplete,
}: DriverOnboardingMiniAppProps) {
  const [currentStep, setCurrentStep] = useState(0);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [driverData, setDriverData] = useState<DriverData>({
    name: '',
    email: '',
    phone: '',
    nationalId: '',
    vehicleType: '',
    plateNumber: '',
    licenseNumber: '',
    driverLicense: '',
    insurance: '',
  });
  const toast = useToast();

  const progress = ((currentStep + 1) / ONBOARDING_STEPS.length) * 100;

  const handleNext = () => {
    // Validate current step
    const currentStepData = ONBOARDING_STEPS[currentStep];
    const hasEmptyFields = currentStepData.fields.some(
      field => !driverData[field as keyof DriverData]
    );

    if (hasEmptyFields && currentStep < 3) {
      toast({
        title: 'حقول مطلوبة',
        description: 'يرجى ملء جميع الحقول المطلوبة',
        status: 'warning',
        duration: 3000,
      });
      return;
    }

    if (currentStep < ONBOARDING_STEPS.length - 1) {
      setCurrentStep(currentStep + 1);
    }
  };

  const handleBack = () => {
    if (currentStep > 0) {
      setCurrentStep(currentStep - 1);
    }
  };

  const handleSubmit = async () => {
    setIsSubmitting(true);

    try {
      // Create user and driver accounts
      const response = await fetch('/api/admin/drivers', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: driverData.name,
          email: driverData.email,
          phone: driverData.phone,
          nationalId: driverData.nationalId,
          vehicle: {
            type: driverData.vehicleType,
            plateNumber: driverData.plateNumber,
            licenseNumber: driverData.licenseNumber,
          },
          documents: {
            driverLicense: driverData.driverLicense,
            insurance: driverData.insurance,
          },
        }),
      });

      if (response.ok) {
        toast({
          title: 'تم تسجيل السائق بنجاح',
          description: 'تم إنشاء حساب السائق وإرسال بيانات الدخول إلى بريده',
          status: 'success',
          duration: 5000,
        });

        if (onComplete) {
          onComplete(driverData);
        }

        onClose();
      } else {
        const error = await response.json();
        throw new Error(error.message || 'فشل تسجيل السائق');
      }
    } catch (error) {
      console.error('Driver onboarding error:', error);
      toast({
        title: 'خطأ في التسجيل',
        description: error instanceof Error ? error.message : 'حدث خطأ أثناء تسجيل السائق',
        status: 'error',
        duration: 5000,
      });
    } finally {
      setIsSubmitting(false);
    }
  };

  const updateField = (field: keyof DriverData, value: string) => {
    setDriverData(prev => ({ ...prev, [field]: value }));
  };

  const renderStepContent = () => {
    const step = ONBOARDING_STEPS[currentStep];

    switch (step.id) {
      case 1:
        return (
          <VStack spacing={4} align="stretch">
            <FormControl isRequired>
              <FormLabel>الاسم الكامل</FormLabel>
              <Input
                value={driverData.name}
                onChange={(e) => updateField('name', e.target.value)}
                placeholder="أحمد محمد"
              />
            </FormControl>

            <FormControl isRequired>
              <FormLabel>البريد الإلكتروني</FormLabel>
              <Input
                type="email"
                value={driverData.email}
                onChange={(e) => updateField('email', e.target.value)}
                placeholder="ahmad@example.com"
              />
              <FormHelperText>سيتم إرسال بيانات الدخول لهذا البريد</FormHelperText>
            </FormControl>

            <FormControl isRequired>
              <FormLabel>رقم الجوال</FormLabel>
              <Input
                value={driverData.phone}
                onChange={(e) => updateField('phone', e.target.value)}
                placeholder="05xxxxxxxx"
              />
            </FormControl>

            <FormControl isRequired>
              <FormLabel>رقم الهوية الوطنية</FormLabel>
              <Input
                value={driverData.nationalId}
                onChange={(e) => updateField('nationalId', e.target.value)}
                placeholder="1xxxxxxxxx"
              />
            </FormControl>
          </VStack>
        );

      case 2:
        return (
          <VStack spacing={4} align="stretch">
            <FormControl isRequired>
              <FormLabel>نوع المركبة</FormLabel>
              <Select
                value={driverData.vehicleType}
                onChange={(e) => updateField('vehicleType', e.target.value)}
                placeholder="اختر نوع المركبة"
              >
                <option value="van">فان</option>
                <option value="pickup">بيك اب</option>
                <option value="truck">شاحنة صغيرة</option>
              </Select>
            </FormControl>

            <FormControl isRequired>
              <FormLabel>رقم اللوحة</FormLabel>
              <Input
                value={driverData.plateNumber}
                onChange={(e) => updateField('plateNumber', e.target.value)}
                placeholder="أ ب ج 1234"
              />
            </FormControl>

            <FormControl isRequired>
              <FormLabel>رقم رخصة التشغيل</FormLabel>
              <Input
                value={driverData.licenseNumber}
                onChange={(e) => updateField('licenseNumber', e.target.value)}
                placeholder="رقم رخصة المركبة"
              />
            </FormControl>
          </VStack>
        );

      case 3:
        return (
          <VStack spacing={4} align="stretch">
            <Alert status="info" borderRadius="md">
              <AlertIcon />
              <Text fontSize="sm">
                يمكنك رفع المستندات لاحقاً. سيتم إرسال رابط للسائق لرفع المستندات المطلوبة.
              </Text>
            </Alert>

            <FormControl>
              <FormLabel>رخصة القيادة</FormLabel>
              <Input
                value={driverData.driverLicense}
                onChange={(e) => updateField('driverLicense', e.target.value)}
                placeholder="رقم رخصة القيادة"
              />
            </FormControl>

            <FormControl>
              <FormLabel>التأمين</FormLabel>
              <Input
                value={driverData.insurance}
                onChange={(e) => updateField('insurance', e.target.value)}
                placeholder="رقم وثيقة التأمين"
              />
            </FormControl>
          </VStack>
        );

      case 4:
        return (
          <VStack spacing={4} align="stretch">
            <Alert status="success" borderRadius="md">
              <AlertIcon />
              <Text fontWeight="bold">جاهز للتسجيل!</Text>
            </Alert>

            <Box bg="gray.50" p={4} borderRadius="md">
              <VStack align="stretch" spacing={3}>
                <Box>
                  <Text fontSize="sm" color="gray.600">الاسم:</Text>
                  <Text fontWeight="medium">{driverData.name}</Text>
                </Box>
                <Box>
                  <Text fontSize="sm" color="gray.600">البريد:</Text>
                  <Text fontWeight="medium">{driverData.email}</Text>
                </Box>
                <Box>
                  <Text fontSize="sm" color="gray.600">الجوال:</Text>
                  <Text fontWeight="medium">{driverData.phone}</Text>
                </Box>
                <Box>
                  <Text fontSize="sm" color="gray.600">المركبة:</Text>
                  <Text fontWeight="medium">
                    {driverData.vehicleType} - {driverData.plateNumber}
                  </Text>
                </Box>
              </VStack>
            </Box>

            <Alert status="info" borderRadius="md">
              <AlertIcon />
              <Text fontSize="sm">
                سيتم إرسال بيانات الدخول والتعليمات إلى البريد الإلكتروني للسائق
              </Text>
            </Alert>
          </VStack>
        );

      default:
        return null;
    }
  };

  return (
    <Modal isOpen={isOpen} onClose={onClose} size="lg" closeOnOverlayClick={false}>
      <ModalOverlay bg="blackAlpha.800" backdropFilter="blur(10px)" />
      <ModalContent dir="rtl">
        <ModalHeader>
          <VStack align="stretch" spacing={2}>
            <HStack spacing={3}>
              <Icon as={FiUser} boxSize={6} color="purple.500" />
              <Text>تسجيل سائق جديد</Text>
            </HStack>
            <Progress value={progress} colorScheme="purple" size="sm" />
          </VStack>
        </ModalHeader>

        <ModalBody>
          <VStack spacing={6} align="stretch">
            {/* Steps Indicator */}
            <HStack spacing={2} justify="center">
              {ONBOARDING_STEPS.map((step, index) => (
                <Box key={step.id} textAlign="center">
                  <Box
                    w={10}
                    h={10}
                    borderRadius="full"
                    bg={
                      index < currentStep
                        ? 'green.500'
                        : index === currentStep
                        ? 'purple.500'
                        : 'gray.200'
                    }
                    color="white"
                    display="flex"
                    alignItems="center"
                    justifyContent="center"
                    mx="auto"
                    mb={1}
                  >
                    <Icon
                      as={step.icon}
                      boxSize={5}
                      color={index <= currentStep ? 'white' : 'gray.500'}
                    />
                  </Box>
                  <Text fontSize="xs" color={index === currentStep ? 'purple.600' : 'gray.600'}>
                    {step.title}
                  </Text>
                </Box>
              ))}
            </HStack>

            {/* Step Content */}
            <Box>
              <VStack align="start" spacing={2} mb={4}>
                <Badge colorScheme="purple">
                  الخطوة {currentStep + 1} من {ONBOARDING_STEPS.length}
                </Badge>
                <Text fontSize="lg" fontWeight="bold">
                  {ONBOARDING_STEPS[currentStep].title}
                </Text>
                <Text fontSize="sm" color="gray.600">
                  {ONBOARDING_STEPS[currentStep].description}
                </Text>
              </VStack>

              {renderStepContent()}
            </Box>
          </VStack>
        </ModalBody>

        <ModalFooter>
          <HStack spacing={3}>
            <Button variant="ghost" onClick={onClose} isDisabled={isSubmitting}>
              إلغاء
            </Button>
            
            {currentStep > 0 && (
              <Button onClick={handleBack} isDisabled={isSubmitting}>
                رجوع
              </Button>
            )}

            {currentStep < ONBOARDING_STEPS.length - 1 ? (
              <Button colorScheme="purple" onClick={handleNext}>
                التالي
              </Button>
            ) : (
              <Button
                colorScheme="green"
                onClick={handleSubmit}
                isLoading={isSubmitting}
                loadingText="جاري التسجيل..."
              >
                تسجيل السائق
              </Button>
            )}
          </HStack>
        </ModalFooter>
      </ModalContent>
    </Modal>
  );
}

'use client';

import React from 'react';
import { Box } from '@chakra-ui/react';
import EnhancedAdminRoutesDashboard from '@/components/admin/EnhancedAdminRoutesDashboard';

interface MultiDropRoutesSectionProps {
  onCountChange?: (count: number) => void;
  declinedNotifications?: string[];
  acceptedNotifications?: string[];
  inProgressNotifications?: string[];
}

/**
 * Multi-Drop Routes Section
 * 
 * Wraps the existing routes dashboard component for use in the unified operations dashboard.
 * Manages multi-drop delivery routes with full admin control:
 * - Create routes (manual, automatic, AI-powered)
 * - Assign/reassign drivers
 * - Add/remove drops
 * - Optimize routes
 * - Track progress
 * - Cancel/split routes
 */
export default function MultiDropRoutesSection({ 
  onCountChange, 
  declinedNotifications,
  acceptedNotifications,
  inProgressNotifications
}: MultiDropRoutesSectionProps) {
  // Note: The count will be managed by the EnhancedAdminRoutesDashboard component internally
  // We can enhance this later to expose the count via props or context

  return (
    <Box>
      <EnhancedAdminRoutesDashboard 
        declinedNotifications={declinedNotifications}
        acceptedNotifications={acceptedNotifications}
        inProgressNotifications={inProgressNotifications}
      />
    </Box>
  );
}

