'use client';
import { useEffect, useState, useCallback, useMemo, type ReactNode } from 'react';
import { FaRoute } from 'react-icons/fa';
import {
  Box,
  Table,
  Thead,
  Tbody,
  Tr,
  Th,
  Td,
  InputGroup,
  InputLeftElement,
  Select,
  Button,
  HStack,
  VStack,
  Text,
  Badge,
  Flex,
  Spinner,
  Checkbox,
  Menu,
  MenuButton,
  MenuList,
  MenuItem,
  IconButton,
  useToast,
  Card,
  CardBody,
  CardHeader,
  Heading,
  Tooltip,
  Icon,
  Divider,
  Grid,
  GridItem,
  useDisclosure,
  Progress,
  Alert,
  AlertIcon,
  Modal,
  ModalOverlay,
  ModalContent,
  ModalHeader,
  ModalCloseButton,
  ModalBody,
  ModalFooter,
  Textarea,
  Circle,
} from '@chakra-ui/react';
import { keyframes } from '@emotion/react';
import ClientInput from '@/components/admin/ClientInput';
import {
  FaSearch,
  FaFilter,
  FaEllipsisV,
  FaEdit,
  FaUser,
  FaMapMarkerAlt,
  FaClock,
  FaPoundSign,
  FaCheck,
  FaTimes,
  FaDownload,
  FaEnvelope,
  FaEye,
  FaTruck,
  FaExclamationTriangle,
  FaCheckCircle,
  FaTrash,
  FaUserSlash,
} from 'react-icons/fa';
import { formatDistanceToNow, format, differenceInMinutes, differenceInDays, differenceInHours } from 'date-fns';
import {
  AdminShell,
  ViewToggle,
  type ViewType,
  OrderDetailDrawer,
} from '@/components/admin';

// Flashing animation for priority indicators
const pulseAnimation = keyframes`
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.6; transform: scale(1.1); }
`;

const fastPulseAnimation = keyframes`
  0%, 100% { opacity: 1; transform: scale(1); box-shadow: 0 0 0 0 rgba(239, 68, 68, 0.7); }
  50% { opacity: 0.7; transform: scale(1.15); box-shadow: 0 0 0 10px rgba(239, 68, 68, 0); }
`;

const waveAnimation = keyframes`
  0% { 
    transform: translateX(-100%) translateY(0) scaleY(1); 
    opacity: 0.3;
  }
  25% { 
    transform: translateX(-50%) translateY(-5px) scaleY(1.1); 
    opacity: 0.5;
  }
  50% { 
    transform: translateX(0%) translateY(-10px) scaleY(1.2); 
    opacity: 0.7;
  }
  75% { 
    transform: translateX(50%) translateY(-5px) scaleY(1.1); 
    opacity: 0.5;
  }
  100% { 
    transform: translateX(100%) translateY(0) scaleY(1); 
    opacity: 0.3;
  }
`;

// Priority calculation based on scheduled date
function calculatePriority(scheduledAt: string): {
  level: 'urgent' | 'high' | 'medium' | 'low' | 'future';
  color: string;
  bgColor: string;
  label: string;
  animation: string;
  sortOrder: number;
} {
  const now = new Date();
  const scheduled = new Date(scheduledAt);
  const hoursUntil = differenceInHours(scheduled, now);
  const daysUntil = differenceInDays(scheduled, now);

  // Tomorrow (within 24-48 hours)
  if (hoursUntil >= 0 && hoursUntil <= 48) {
    return {
      level: 'urgent',
      color: 'red.500',
      bgColor: 'red.50',
      label: 'Tomorrow',
      animation: `${fastPulseAnimation} 1.5s ease-in-out infinite`,
      sortOrder: 1
    };
  }
  
  // Day after tomorrow (48-72 hours)
  if (hoursUntil > 48 && hoursUntil <= 72) {
    return {
      level: 'high',
      color: 'orange.500',
      bgColor: 'orange.50',
      label: 'Day After',
      animation: `${pulseAnimation} 2s ease-in-out infinite`,
      sortOrder: 2
    };
  }
  
  // This week (3-7 days)
  if (daysUntil > 3 && daysUntil <= 7) {
    return {
      level: 'medium',
      color: 'yellow.500',
      bgColor: 'yellow.50',
      label: 'This Week',
      animation: `${pulseAnimation} 2.5s ease-in-out infinite`,
      sortOrder: 3
    };
  }
  
  // Next week (7-14 days)
  if (daysUntil > 7 && daysUntil <= 14) {
    return {
      level: 'low',
      color: 'green.400',
      bgColor: 'green.50',
      label: 'Next Week',
      animation: `${pulseAnimation} 3s ease-in-out infinite`,
      sortOrder: 4
    };
  }
  
  // Future (14+ days)
  return {
    level: 'future',
    color: 'green.600',
    bgColor: 'green.50',
    label: 'Future',
    animation: `${pulseAnimation} 3.5s ease-in-out infinite`,
    sortOrder: 5
  };
}

interface Order {
  id: string;
  reference: string;
  status: string;
  scheduledAt: string;
  totalGBP: number;
  customerName: string;
  customerEmail: string;
  customerPhone: string;
  pickupAddress?: {
    label: string;
    postcode: string;
  };
  dropoffAddress?: {
    label: string;
    postcode: string;
  };
  pickupProperty?: {
    propertyType: string;
    floors: number;
    accessType: string;
  };
  dropoffProperty?: {
    propertyType: string;
    floors: number;
    accessType: string;
  };
  customer?: {
    name: string;
    email: string;
  };
  driver?: {
    user: {
      name: string;
    };
  };
  route?: {
    id: string;
    reference: string;
    status: string;
    totalDrops: number;
  } | null;
  customerPreferences?: any;
  serviceType?: string;
  isEconomyService?: boolean;
  shouldBeMultiDrop?: boolean;
  orderType?: string;
  isMultiDrop?: boolean;
  routeId?: string | null;
  createdAt: string;
  paidAt?: string;
  durationSeconds?: number;
  assignment?: {
    status: string;
    claimedAt?: string;
  };
  preferredDate?: string;
  timeSlot?: string;
  pickupTimeSlot?: string;
  urgency?: string;
  distanceMeters?: number;
}

export interface OrdersClientProps {
  declinedNotifications?: string[];
  acceptedNotifications?: string[];
  inProgressNotifications?: string[];
}

export interface OrdersTableProps extends OrdersClientProps {
  hideActionBar?: boolean;
  onActionsChange?: (actions: React.ReactNode) => void;
  embedded?: boolean;
}

export function OrdersTable({ 
  hideActionBar = false,
  onActionsChange,
  embedded = false,
  declinedNotifications = [],
  acceptedNotifications = [],
  inProgressNotifications = []
}: OrdersTableProps) {
  const [orders, setOrders] = useState<Order[]>([]);
  const [selectedOrders, setSelectedOrders] = useState<string[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState('');
  const [paymentFilter, setPaymentFilter] = useState('');
  const [dateRange, setDateRange] = useState('');
  const [driverFilter, setDriverFilter] = useState('');
  const [areaFilter, setAreaFilter] = useState('');
  const [orderTypeFilter, setOrderTypeFilter] = useState<'all' | 'new' | 'existing'>('all');
  const [viewMode, setViewMode] = useState<ViewType>('card');
  const [showUnpaidOrders, setShowUnpaidOrders] = useState(false);
  const [selectedOrderCode, setSelectedOrderCode] = useState<
    string | undefined
  >();
  const [showAllOrders, setShowAllOrders] = useState(true); // Ensure all orders are shown by default
  const [pagination, setPagination] = useState({
    page: 1,
    limit: 100, // Increased limit to show more orders
    total: 0,
    hasMore: false,
  });
  const [newOrdersCount, setNewOrdersCount] = useState(0);
  const toast = useToast();

  const {
    isOpen: isDetailOpen,
    onOpen: onDetailOpen,
    onClose: onDetailClose,
  } = useDisclosure();

  const {
    isOpen: isRoutePreviewOpen,
    onOpen: onRoutePreviewOpen,
    onClose: onRoutePreviewClose,
  } = useDisclosure();
  
  const {
    isOpen: isRemoveOpen,
    onOpen: onRemoveOpen,
    onClose: onRemoveClose,
  } = useDisclosure();
  
  const [selectedOrderForRemoval, setSelectedOrderForRemoval] = useState<Order | null>(null);
  const [removalType, setRemovalType] = useState<'single' | 'all'>('single');
  const [removalReason, setRemovalReason] = useState('');
  
  // Driver Assignment State
  const {
    isOpen: isAssignOpen,
    onOpen: onAssignOpen,
    onClose: onAssignClose,
  } = useDisclosure();
  const [selectedOrderForAssign, setSelectedOrderForAssign] = useState<Order | null>(null);
  const [selectedDriverId, setSelectedDriverId] = useState('');
  const [assignReason, setAssignReason] = useState('');
  const [isAssigning, setIsAssigning] = useState(false);
  const [availableDrivers, setAvailableDrivers] = useState<any[]>([]);

  const loadOrders = useCallback(
    async (refresh = false) => {
      setLoading(true);
      try {
        const params = new URLSearchParams();
        if (searchQuery) params.set('q', searchQuery);
        if (statusFilter) params.set('status', statusFilter);
        if (paymentFilter) params.set('payment', paymentFilter);
        if (dateRange) params.set('dateRange', dateRange);
        if (driverFilter) params.set('driver', driverFilter);
        if (areaFilter) params.set('area', areaFilter);
        params.set('take', pagination.limit.toString());

        // Ensure we get all orders if no specific filters are applied
        if (
          !statusFilter &&
          !paymentFilter &&
          !dateRange &&
          !driverFilter &&
          !areaFilter &&
          !searchQuery
        ) {
          params.set('take', '500'); // Get maximum orders when no filters
        }

        if (!refresh && pagination.page > 1) {
          // For pagination, we'd need cursor-based pagination
          // For now, just reload all
        }

        const response = await fetch(`/api/admin/orders?${params.toString()}`);
        const data = await response.json();

        if (refresh) {
          setOrders(data.items || data);

          // Count new orders (pending and confirmed without driver)
          const newOrders = (data.items || data).filter(
            (order: Order) =>
              ['pending', 'CONFIRMED'].includes(order.status) && !order.driver
          );
          setNewOrdersCount(newOrders.length);

          setPagination(prev => ({
            ...prev,
            total: data.items?.length || 0,
            hasMore: data.nextCursor ? true : false,
          }));
        } else {
          setOrders(prev => [...prev, ...(data.items || data)]);
        }
      } catch (error) {
        toast({
          title: 'Error loading orders',
          description: 'Failed to fetch orders data',
          status: 'error',
          duration: 5000,
          isClosable: true,
        });
      } finally {
        setLoading(false);
      }
    },
    [
      searchQuery,
      statusFilter,
      paymentFilter,
      dateRange,
      driverFilter,
      areaFilter,
      pagination.limit,
      toast,
    ]
  );

  useEffect(() => {
    // Prevent unnecessary API calls during hot reload
    if (typeof window !== 'undefined') {
      loadOrders(true);
    }
  }, [
    statusFilter,
    paymentFilter,
    dateRange,
    driverFilter,
    areaFilter,
    orderTypeFilter,
    showAllOrders,
  ]);

  // Filter orders based on search query and type using useMemo for better performance
  const { filteredOrders, unpaidOrdersCount } = useMemo(() => {
    if (!orders.length) return { filteredOrders: [], unpaidOrdersCount: 0 };

    let filtered = orders;
    let unpaidCount = 0;

    // Count unpaid orders first
    unpaidCount = orders.filter(order => !order.paidAt).length;

    // Apply order type filter first
    if (orderTypeFilter !== 'all') {
      if (orderTypeFilter === 'new') {
        // New orders: PENDING_PAYMENT status or CONFIRMED without driver
        filtered = filtered.filter(
          order =>
            order.status === 'PENDING_PAYMENT' ||
            (order.status === 'CONFIRMED' && !order.driver)
        );
      } else if (orderTypeFilter === 'existing') {
        // Existing orders: All others
        filtered = filtered.filter(
          order =>
            order.status !== 'PENDING_PAYMENT' &&
            !(order.status === 'CONFIRMED' && !order.driver)
        );
      }
    }

    // Apply payment filter - hide unpaid orders by default unless explicitly shown
    if (!showUnpaidOrders) {
      // Hide unpaid orders by default (only show orders that have been paid)
      filtered = filtered.filter(order => {
        // Consider orders as "paid" if they have a paidAt date
        return !!order.paidAt;
      });
    }

    // Apply search query filter
    if (searchQuery) {
      filtered = filtered.filter(
        order =>
          String(order?.reference ?? '')
            .toLowerCase()
            .includes(searchQuery.toLowerCase()) ||
          String(order?.pickupAddress?.label ?? '')
            .toLowerCase()
            .includes(searchQuery.toLowerCase()) ||
          String(order?.dropoffAddress?.label ?? '')
            .toLowerCase()
            .includes(searchQuery.toLowerCase()) ||
          String(order?.customerName ?? '')
            .toLowerCase()
            .includes(searchQuery.toLowerCase()) ||
          String(order?.customerEmail ?? '')
            .toLowerCase()
            .includes(searchQuery.toLowerCase())
      );
    }

    // ✅ Sort by priority (urgent first) then by scheduled date
    filtered.sort((a, b) => {
      const priorityA = calculatePriority(a.scheduledAt);
      const priorityB = calculatePriority(b.scheduledAt);

      // Sort by priority level first (urgent → future)
      if (priorityA.sortOrder !== priorityB.sortOrder) {
        return priorityA.sortOrder - priorityB.sortOrder;
      }

      // Then by scheduled date (earliest first)
      return new Date(a.scheduledAt).getTime() - new Date(b.scheduledAt).getTime();
    });

    return { filteredOrders: filtered, unpaidOrdersCount: unpaidCount };
  }, [orders, searchQuery, orderTypeFilter, showUnpaidOrders]);

  const handleBulkAction = async (action: string) => {
    if (selectedOrders.length === 0) {
      toast({
        title: 'No orders selected',
        description: 'Please select orders to perform bulk actions',
        status: 'warning',
        duration: 3000,
        isClosable: true,
      });
      return;
    }

    try {
      const apiEndpoint = '/api/admin/orders/bulk';
      const requestBody: any = {
        orderIds: selectedOrders,
        action: action,
      };

      const response = await fetch(apiEndpoint, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(requestBody),
      });

      if (response.ok) {
        const result = await response.json();

        let description = result.message || `${action} applied to ${selectedOrders.length} orders`;

        // Special handling for floor warning results
        if (action === 'send-floor-warnings' && result.summary) {
          description = `Checked ${result.summary.totalChecked} orders. Sent ${result.summary.sent} floor warnings.`;
        }

        toast({
          title: 'Bulk action completed',
          description,
          status: 'success',
          duration: 5000,
          isClosable: true,
        });
        setSelectedOrders([]);
        loadOrders(true);
      } else {
        const errorData = await response.json();
        throw new Error(errorData.error || 'Bulk action failed');
      }
    } catch (error) {
      toast({
        title: 'Bulk action failed',
        description: 'Failed to perform bulk action',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    }
  };

  const handleCreateRouteFromOrders = async () => {
    if (selectedOrders.length < 2) {
      toast({
        title: 'Insufficient orders',
        description: 'Please select at least 2 orders to create a route',
        status: 'warning',
        duration: 3000,
        isClosable: true,
      });
      return;
    }

    try {
      // Call the route creation API with selected order IDs
      const response = await fetch('/api/admin/routes/create', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          bookingIds: selectedOrders,
        }),
      });

      if (response.ok) {
        const result = await response.json();
        toast({
          title: 'Route created successfully',
          description: `Created route ${result.route?.reference || result.route?.id} with ${selectedOrders.length} orders`,
          status: 'success',
          duration: 5000,
          isClosable: true,
        });
        setSelectedOrders([]);
        loadOrders(true);
        
        // Optionally redirect to operations page (routes tab)
        // window.location.href = '/admin/operations';
      } else {
        const errorData = await response.json();
        throw new Error(errorData.error || 'Failed to create route');
      }
    } catch (error) {
      console.error('Error creating route:', error);
      toast({
        title: 'Failed to create route',
        description: error instanceof Error ? error.message : 'An error occurred',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    }
  };

  const handleViewOrder = (orderCode: string) => {
    setSelectedOrderCode(orderCode);
    onDetailOpen();
  };

  const getStatusColor = (status: string | undefined) => {
    if (!status) return 'gray';

    switch (status) {
      case 'COMPLETED':
        return 'green';
      case 'CANCELLED':
        return 'red';
      case 'in_progress':
        return 'blue';
      case 'CONFIRMED':
        return 'yellow';
      case 'DRAFT':
        return 'gray';
      default:
        return 'gray';
    }
  };

  const getPaymentStatusColor = (status: string | undefined) => {
    if (!status) return 'gray';

    switch (status) {
      case 'paid':
        return 'green';
      case 'requires_action':
        return 'orange';
      case 'refunded':
        return 'red';
      default:
        return 'gray';
    }
  };

  const formatCurrency = (totalGBP: number) => {
    return `£${(totalGBP / 100).toFixed(2)}`;
  };

  const formatDuration = (seconds?: number) => {
    if (!seconds) return '-';
    const hours = Math.floor(seconds / 3600);
    const minutes = Math.floor((seconds % 3600) / 60);
    return `${hours}h ${minutes}m`;
  };

  // Quick data quality check for orders table
  const getDataQualityScore = (order: Order) => {
    let score = 100;
    
    // Critical checks (-20 each)
    if (!order.distanceMeters && !order.pickupAddress) score -= 20;
    if (!order.customerPhone || order.customerPhone.length < 10) score -= 20;
    
    // Warning checks (-10 each)  
    if (!order.pickupTimeSlot) score -= 10;
    if (!order.preferredDate && !order.scheduledAt) score -= 10;
    
    return Math.max(0, score);
  };

  const getQualityColor = (score: number) => {
    if (score >= 80) return 'green';
    if (score >= 60) return 'yellow';
    return 'red';
  };

  const formatDistance = (meters?: number) => {
    if (!meters) return '-';
    return `${(meters / 1000).toFixed(1)}km`;
  };

  const getSLAStatus = (order: Order) => {
    if (order.status === 'COMPLETED' || order.status === 'CANCELLED') {
      return { status: 'COMPLETED', message: 'Order completed' };
    }

    const now = new Date();
    const orderDate = order.scheduledAt
      ? new Date(order.scheduledAt)
      : new Date(order.createdAt);
    const minutesSinceOrder = differenceInMinutes(now, orderDate);

    if (minutesSinceOrder > 120) {
      // 2 hours
      return { status: 'overdue', message: `${minutesSinceOrder}min overdue` };
    } else if (minutesSinceOrder > 60) {
      // 1 hour
      return { status: 'warning', message: `${minutesSinceOrder}min old` };
    } else {
      return { status: 'ok', message: `${minutesSinceOrder}min old` };
    }
  };

  const handleCreateOrder = () => {
    window.open('/booking-luxury', '_blank');
  };

  const handleOpenRemoveModal = (order: Order) => {
    setSelectedOrderForRemoval(order);
    setRemovalType('single');
    setRemovalReason('');
    onRemoveOpen();
  };

  const handleOpenAssignModal = async (order: Order) => {
    setSelectedOrderForAssign(order);
    setSelectedDriverId('');
    setAssignReason('');
    
    // Load available drivers
    try {
      const response = await fetch('/api/admin/drivers?status=available');
      const data = await response.json();
      if (data.drivers) {
        setAvailableDrivers(data.drivers);
      }
    } catch (error) {
      console.error('Error loading drivers:', error);
      toast({
        title: 'Error',
        description: 'Failed to load available drivers',
        status: 'error',
        duration: 3000,
      });
    }
    
    onAssignOpen();
  };

  const handleAssignDriver = async () => {
    if (!selectedOrderForAssign || !selectedDriverId) return;

    setIsAssigning(true);
    try {
      const isReassign = !!selectedOrderForAssign.driver;
      const response = await fetch(
        `/api/admin/orders/${selectedOrderForAssign.reference}/assign-driver`,
        {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            driverId: selectedDriverId,
            reason: assignReason || (isReassign ? 'Reassigned by admin' : 'Assigned by admin')
          })
        }
      );

      const data = await response.json();

      if (data.success || response.ok) {
        toast({
          title: 'Success',
          description: isReassign 
            ? `Order ${selectedOrderForAssign.reference} reassigned successfully. Driver will be notified.` 
            : `Order ${selectedOrderForAssign.reference} assigned to driver. Notification sent.`,
          status: 'success',
          duration: 3000,
        });
        
        onAssignClose();
        loadOrders(true);
      } else {
        throw new Error(data.error || 'Failed to assign driver');
      }
    } catch (error) {
      console.error('Error assigning driver:', error);
      toast({
        title: 'Error',
        description: error instanceof Error ? error.message : 'Failed to assign driver',
        status: 'error',
        duration: 5000,
      });
    } finally {
      setIsAssigning(false);
    }
  };

  const handleCancelOrder = async (order: Order) => {
    const confirmCancel = window.confirm(
      `Are you sure you want to cancel order #${order.reference}?\n\n` +
      `This will:\n` +
      `- Cancel the order\n` +
      `- Notify the driver (if assigned)\n` +
      `- Update the customer\n` +
      `- Free up the driver's capacity\n\n` +
      `This action cannot be undone.`
    );

    if (!confirmCancel) return;

    const reason = window.prompt('Please provide a reason for cancellation:', 'Cancelled by admin');
    
    try {
      const response = await fetch(
        `/api/admin/orders/${order.reference}/cancel-enhanced`,
        {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            reason: reason || 'Cancelled by admin',
            notifyCustomer: true
          })
        }
      );

      const data = await response.json();

      if (data.success || response.ok) {
        toast({
          title: 'Success',
          description: `Order #${order.reference} has been cancelled. All notifications sent.`,
          status: 'success',
          duration: 4000,
        });
        
        loadOrders(true);
      } else {
        throw new Error(data.error || 'Failed to cancel order');
      }
    } catch (error) {
      console.error('Error cancelling order:', error);
      toast({
        title: 'Error',
        description: error instanceof Error ? error.message : 'Failed to cancel order',
        status: 'error',
        duration: 5000,
      });
    }
  };

  const handleRemoveOrder = async () => {
    if (!selectedOrderForRemoval) return;

    try {
      if (removalType === 'single') {
        // Remove single order
        const response = await fetch(
          `/api/admin/orders/${selectedOrderForRemoval.reference}/remove-driver`,
          {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              reason: removalReason || 'Removed by admin'
            })
          }
        );

        const data = await response.json();

        if (data.success) {
          toast({
            title: 'Order Removed',
            description: data.message,
            status: 'success',
            duration: 5000,
            isClosable: true,
          });
          loadOrders(true);
          onRemoveClose();
        } else {
          throw new Error(data.error || 'Failed to remove order');
        }
      } else if (removalType === 'all' && selectedOrderForRemoval.driver) {
        // Remove all orders from driver
        const driverId = (selectedOrderForRemoval as any).driverId;
        
        const response = await fetch(
          `/api/admin/drivers/${driverId}/remove-all`,
          {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              type: 'orders',
              reason: removalReason || 'Removed all orders by admin'
            })
          }
        );

        const data = await response.json();

        if (data.success) {
          toast({
            title: 'All Orders Removed',
            description: data.message,
            status: 'success',
            duration: 5000,
            isClosable: true,
          });
          loadOrders(true);
          onRemoveClose();
        } else {
          throw new Error(data.error || 'Failed to remove all orders');
        }
      }
    } catch (error) {
      toast({
        title: 'Removal Failed',
        description: error instanceof Error ? error.message : 'Failed to remove order',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    }
  };

  const renderOrdersTable = () => (
    <Card bg="#000000" borderColor="#333333">
      <CardBody p={0} bg="#000000">
        <Table 
          variant="simple"
          sx={{
            backgroundColor: '#000000',
            color: '#FFFFFF',
            '& thead tr': {
              backgroundColor: '#111111 !important',
            },
            '& thead th': {
              backgroundColor: '#111111 !important',
              color: '#FFFFFF !important',
              borderColor: '#333333 !important',
            },
            '& tbody tr:nth-of-type(even)': {
              backgroundColor: '#000000 !important',
            },
            '& tbody tr:nth-of-type(odd)': {
              backgroundColor: '#0a0a0a !important',
            },
            '& tbody tr': {
              backgroundColor: '#000000 !important',
              color: '#FFFFFF !important',
            },
            '& tbody td': {
              color: '#FFFFFF !important',
              borderColor: '#333333 !important',
            },
          }}
        >
          <Thead>
            <Tr>
              <Th px={4} color="#FFFFFF" bg="#111111" borderColor="#333333">
                <Checkbox
                  isChecked={
                    selectedOrders.length === filteredOrders.length &&
                    filteredOrders.length > 0
                  }
                  isIndeterminate={
                    selectedOrders.length > 0 &&
                    selectedOrders.length < filteredOrders.length
                  }
                  onChange={e => {
                    if (e.target.checked) {
                      setSelectedOrders(filteredOrders.map(order => order.id));
                    } else {
                      setSelectedOrders([]);
                    }
                  }}
                />
              </Th>
              <Th color="#FFFFFF" bg="#111111" borderColor="#333333">Code</Th>
              <Th color="#FFFFFF" bg="#111111" borderColor="#333333">Customer</Th>
              <Th color="#FFFFFF" bg="#111111" borderColor="#333333">Service</Th>
              <Th color="#FFFFFF" bg="#111111" borderColor="#333333">Type</Th>
              <Th color="#FFFFFF" bg="#111111" borderColor="#333333">Route</Th>
              <Th color="#FFFFFF" bg="#111111" borderColor="#333333">Time Window</Th>
              <Th color="#FFFFFF" bg="#111111" borderColor="#333333">Status</Th>
              <Th color="#FFFFFF" bg="#111111" borderColor="#333333">Driver</Th>
              <Th color="#FFFFFF" bg="#111111" borderColor="#333333">Price</Th>
              <Th color="#FFFFFF" bg="#111111" borderColor="#333333">Data Quality</Th>
              <Th color="#FFFFFF" bg="#111111" borderColor="#333333">Payment</Th>
              <Th color="#FFFFFF" bg="#111111" borderColor="#333333">SLA</Th>
              <Th color="#FFFFFF" bg="#111111" borderColor="#333333">Actions</Th>
            </Tr>
          </Thead>
          <Tbody>
            {loading ? (
              Array.from({ length: 5 }).map((_, i) => (
                <Tr key={`loading-${i}`}>
                  <Td colSpan={13}>
                    <Flex justify="center" py={8}>
                      <Spinner />
                    </Flex>
                  </Td>
                </Tr>
              ))
            ) : filteredOrders.length === 0 ? (
              <Tr>
                <Td colSpan={13} color="#FFFFFF">
                  <Flex justify="center" py={8}>
                    <Text color="#FFFFFF">No orders found</Text>
                  </Flex>
                </Td>
              </Tr>
            ) : (
              filteredOrders.map(order => {
                const slaStatus = getSLAStatus(order);
                const isDeclined = declinedNotifications.includes(order.id);
                const isAccepted = acceptedNotifications.includes(order.id);
                const isInProgress = inProgressNotifications.includes(order.id);
                
                return (
                  <Tr
                    key={order.id}
                    _hover={{ 
                      bg: isDeclined ? 'red.900' : 
                          isInProgress ? 'blue.900' :
                          isAccepted ? 'green.900' : 
                          '#1a1a1a' 
                    }}
                    cursor="pointer"
                    onClick={() => handleViewOrder(order.reference)}
                    bg={
                      isDeclined ? 'red.950' : 
                      isInProgress ? 'blue.950' :
                      isAccepted ? 'green.950' : 
                      'transparent'
                    }
                    color="#FFFFFF"
                    borderLeft={
                      isDeclined || isAccepted || isInProgress ? '4px solid' : 'none'
                    }
                    borderLeftColor={
                      isDeclined ? 'red.500' : 
                      isInProgress ? 'blue.500' :
                      isAccepted ? 'green.500' : 
                      'transparent'
                    }
                  >
                    <Td px={4} onClick={e => e.stopPropagation()}>
                      <Checkbox
                        isChecked={selectedOrders.includes(order.id)}
                        onChange={e => {
                          if (e.target.checked) {
                            setSelectedOrders([...selectedOrders, order.id]);
                          } else {
                            setSelectedOrders(
                              selectedOrders.filter(id => id !== order.id)
                            );
                          }
                        }}
                      />
                    </Td>
                    <Td>
                      <HStack spacing={2}>
                        <Circle
                          size="12px"
                          bg={
                            isDeclined ? '#E53E3E' : 
                            isInProgress ? '#3B82F6' :
                            isAccepted ? '#10B981' : 
                            calculatePriority(order.scheduledAt).color
                          }
                          animation={
                            isDeclined ? `${fastPulseAnimation} 1s ease-in-out infinite` : 
                            isInProgress ? `${pulseAnimation} 2s ease-in-out infinite` :
                            isAccepted ? `${pulseAnimation} 2s ease-in-out infinite` :
                            calculatePriority(order.scheduledAt).animation
                          }
                        />
                        <Text fontWeight="bold" color={
                          isDeclined ? 'red.400' : 
                          isInProgress ? 'blue.400' :
                          isAccepted ? 'green.400' :
                          '#FFFFFF'
                        }>
                          #{order.reference || 'N/A'}
                        </Text>
                      </HStack>
                    </Td>
                    <Td>
                      <VStack align="start" spacing={1}>
                        <Text fontWeight="medium" color="#FFFFFF">
                          {order.customerName || 'Unknown Customer'}
                        </Text>
                        <Text fontSize="sm" color="#9ca3af">
                          {order.customer?.email || order.customerEmail || '-'}
                        </Text>
                      </VStack>
                    </Td>
                    <Td>
                      <Badge 
                        colorScheme={
                          (order.serviceType?.toUpperCase() === 'ECONOMY' || order.isEconomyService) ? 'green' :
                          (order.serviceType?.toUpperCase() === 'PREMIUM' || order.urgency === 'next-day') ? 'purple' :
                          (order.serviceType?.toUpperCase() === 'ENTERPRISE' || order.urgency === 'same-day') ? 'red' :
                          'blue'
                        }
                        size="sm"
                        variant="solid"
                        fontSize="xs"
                      >
                        {(order.serviceType?.toUpperCase() === 'ECONOMY' || order.isEconomyService) ? '🟢 Economy' :
                         (order.serviceType?.toUpperCase() === 'PREMIUM' || order.urgency === 'next-day') ? '🟣 Premium' :
                         (order.serviceType?.toUpperCase() === 'ENTERPRISE' || order.urgency === 'same-day') ? '🔴 Enterprise' :
                         '🔵 Standard'}
                      </Badge>
                    </Td>
                    <Td>
                      <Badge 
                        colorScheme={order.isMultiDrop || order.orderType === 'multi-drop' ? 'purple' : 'gray'}
                        size="sm"
                      >
                        {order.isMultiDrop || order.orderType === 'multi-drop' ? 'Multi-Drop' : 'Single'}
                      </Badge>
                    </Td>
                    <Td>
                      <VStack align="start" spacing={1}>
                        <HStack>
                          <Icon
                            as={FaMapMarkerAlt}
                            color="green.500"
                            boxSize={3}
                          />
                          <Text fontSize="sm" noOfLines={1} maxW="200px" color="#FFFFFF">
                            {order.pickupAddress?.label || '-'}
                          </Text>
                        </HStack>
                        <HStack>
                          <Icon
                            as={FaMapMarkerAlt}
                            color="red.500"
                            boxSize={3}
                          />
                          <Text fontSize="sm" noOfLines={1} maxW="200px" color="#FFFFFF">
                            {order.dropoffAddress?.label || '-'}
                          </Text>
                        </HStack>
                        {order.route && (
                          <Text fontSize="xs" color="purple.400">
                            Route: {order.route.reference} ({order.route.totalDrops} drops)
                          </Text>
                        )}
                        <Text fontSize="xs" color="#9ca3af">
                          {formatDistance(order.distanceMeters)} •{' '}
                          {formatDuration(order.durationSeconds)}
                        </Text>
                      </VStack>
                    </Td>
                    <Td>
                      <VStack align="start" spacing={1}>
                        <Text fontSize="sm" color="#FFFFFF">
                          {order.scheduledAt
                            ? format(new Date(order.scheduledAt), 'MMM dd')
                            : '-'}
                        </Text>
                        <Text fontSize="xs" color="#9ca3af">
                          {order.pickupTimeSlot || order.timeSlot || '-'}
                        </Text>
                        {order.urgency && order.urgency !== 'scheduled' && (
                          <Badge size="sm" colorScheme={
                            order.urgency === 'same-day' ? 'red' : 
                            order.urgency === 'next-day' ? 'orange' : 'green'
                          }>
                            {order.urgency === 'same-day' ? 'Same Day' :
                             order.urgency === 'next-day' ? 'Next Day' : 'Scheduled'}
                          </Badge>
                        )}
                      </VStack>
                    </Td>
                    <Td>
                      <HStack spacing={2}>
                        <Badge colorScheme={getStatusColor(order.status)}>
                          {order.status
                            ? String(order.status).replace('_', ' ')
                            : 'Unknown'}
                        </Badge>
                        {isDeclined && (
                          <Badge 
                            colorScheme="red" 
                            variant="solid" 
                            animation={`${pulseAnimation} 2s ease-in-out infinite`}
                            fontSize="xs"
                            fontWeight="bold"
                          >
                            🚨 DECLINED
                          </Badge>
                        )}
                        {isAccepted && (
                          <Badge 
                            colorScheme="green" 
                            variant="solid" 
                            animation={`${pulseAnimation} 2s ease-in-out infinite`}
                            fontSize="xs"
                            fontWeight="bold"
                          >
                            ✅ ACCEPTED
                          </Badge>
                        )}
                        {isInProgress && (
                          <Badge 
                            colorScheme="blue" 
                            variant="solid" 
                            animation={`${pulseAnimation} 2s ease-in-out infinite`}
                            fontSize="xs"
                            fontWeight="bold"
                          >
                            🚀 IN PROGRESS
                          </Badge>
                        )}
                      </HStack>
                    </Td>
                    <Td>
                      <HStack>
                        {order.driver?.user?.name ? (
                          <>
                            <Icon as={FaTruck} color="blue.500" boxSize={3} />
                            <Text fontSize="sm" color="#FFFFFF">{order.driver.user.name}</Text>
                          </>
                        ) : (
                          <Text fontSize="sm" color="#9ca3af">
                            -
                          </Text>
                        )}
                      </HStack>
                    </Td>
                    <Td>
                      <Text fontWeight="bold" color="#FFFFFF">{formatCurrency(order.totalGBP || 0)}</Text>
                    </Td>
                    <Td>
                      <Tooltip label={`Data completeness: ${getDataQualityScore(order)}%`}>
                        <Badge colorScheme={getQualityColor(getDataQualityScore(order))} size="sm">
                          {getDataQualityScore(order)}%
                        </Badge>
                      </Tooltip>
                    </Td>
                    <Td>
                      <Badge colorScheme={getPaymentStatusColor(order.status)}>
                        {order.status
                          ? String(order.status).replace('_', ' ')
                          : 'Unknown'}
                      </Badge>
                    </Td>
                    <Td>
                      <Tooltip label={slaStatus.message}>
                        <HStack spacing={1}>
                          <Icon
                            as={
                              slaStatus.status === 'overdue'
                                ? FaExclamationTriangle
                                : slaStatus.status === 'warning'
                                  ? FaClock
                                  : FaCheckCircle
                            }
                            color={
                              slaStatus.status === 'overdue'
                                ? 'red.500'
                                : slaStatus.status === 'warning'
                                  ? 'orange.500'
                                  : 'green.500'
                            }
                            boxSize={3}
                          />
                          <Text
                            fontSize="xs"
                            color={
                              slaStatus.status === 'overdue'
                                ? 'red.400'
                                : slaStatus.status === 'warning'
                                  ? 'orange.400'
                                  : '#9ca3af'
                            }
                          >
                            {slaStatus.message}
                          </Text>
                        </HStack>
                      </Tooltip>
                    </Td>
                    <Td onClick={e => e.stopPropagation()}>
                      <Menu>
                        <MenuButton
                          as={IconButton}
                          icon={<FaEllipsisV />}
                          variant="ghost"
                          size="sm"
                        />
                        <MenuList>
                          <MenuItem
                            icon={<FaEye />}
                            onClick={() => handleViewOrder(order.reference)}
                          >
                            View Details
                          </MenuItem>
                          <MenuItem
                            icon={<FaEdit />}
                            onClick={() => handleBulkAction('edit')}
                          >
                            Edit Order
                          </MenuItem>
                          <MenuItem
                            icon={<FaUser />}
                            onClick={() => handleBulkAction('assign')}
                          >
                            Assign Driver
                          </MenuItem>
                          <MenuItem
                            icon={<FaEnvelope />}
                            onClick={() => handleBulkAction('email')}
                          >
                            Email Customer
                          </MenuItem>
                          <MenuItem
                            icon={<FaTruck />}
                            onClick={() => handleOpenAssignModal(order)}
                            color="blue.500"
                          >
                            {order.driver ? 'Reassign Driver' : 'Assign Driver'}
                          </MenuItem>
                          {order.driver && (
                            <MenuItem
                              icon={<FaUserSlash />}
                              onClick={() => handleOpenRemoveModal(order)}
                              color="red.500"
                            >
                              Remove Assignment
                            </MenuItem>
                          )}
                          {order.status !== 'CANCELLED' && order.status !== 'COMPLETED' && (
                            <MenuItem
                              icon={<FaTrash />}
                              onClick={() => handleCancelOrder(order)}
                              color="red.600"
                            >
                              Cancel Order
                            </MenuItem>
                          )}
                        </MenuList>
                      </Menu>
                    </Td>
                  </Tr>
                );
              })
            )}
          </Tbody>
        </Table>
      </CardBody>
    </Card>
  );

  const renderOrdersCards = () => (
    <Grid templateColumns="repeat(auto-fill, minmax(400px, 1fr))" gap={4}>
      {loading ? (
        Array.from({ length: 6 }).map((_, i) => (
          <Card key={`loading-${i}`}>
            <CardBody>
              <Flex justify="center" py={8}>
                <Spinner />
              </Flex>
            </CardBody>
          </Card>
        ))
      ) : filteredOrders.length === 0 ? (
        <GridItem colSpan={1}>
          <Card>
            <CardBody>
              <Flex justify="center" py={8}>
                <Text color="gray.500">No orders found</Text>
              </Flex>
            </CardBody>
          </Card>
        </GridItem>
      ) : (
        filteredOrders.map(order => {
          const slaStatus = getSLAStatus(order);
          return (
            <Card
              key={order.id}
              bg="#111111"
              borderColor="#333333"
              borderWidth="2px"
              borderRadius="xl"
              boxShadow="0 4px 16px rgba(0, 0, 0, 0.4), 0 0 0 1px rgba(255, 255, 255, 0.05)"
              cursor="pointer"
              onClick={() => handleViewOrder(order.reference)}
              transition="all 0.3s cubic-bezier(0.4, 0, 0.2, 1)"
              position="relative"
              overflow="hidden"
              _before={{
                content: '""',
                position: 'absolute',
                top: 0,
                left: 0,
                right: 0,
                height: '3px',
                background: `linear-gradient(90deg, ${getStatusColor(order.status) === 'green' ? '#10b981' : getStatusColor(order.status) === 'red' ? '#ef4444' : getStatusColor(order.status) === 'yellow' ? '#f59e0b' : '#2563eb'} 0%, transparent 100%)`,
              }}
              _hover={{
                transform: 'translateY(-4px)',
                boxShadow: '0 8px 24px rgba(37, 99, 235, 0.5), 0 0 0 1px rgba(37, 99, 235, 0.2)',
                borderColor: '#2563eb',
              }}
            >
              <CardBody bg="#111111" p={5}>
                <VStack align="stretch" spacing={4}>
                  <HStack justify="space-between">
                    <Text 
                      fontWeight="bold" 
                      color="#2563eb" 
                      fontSize="lg"
                      letterSpacing="0.5px"
                      textShadow="0 0 10px rgba(37, 99, 235, 0.3)"
                    >
                      #{order.reference}
                    </Text>
                    <Checkbox
                      isChecked={selectedOrders.includes(order.id)}
                      onChange={e => {
                        e.stopPropagation();
                        if (e.target.checked) {
                          setSelectedOrders([...selectedOrders, order.id]);
                        } else {
                          setSelectedOrders(
                            selectedOrders.filter(id => id !== order.id)
                          );
                        }
                      }}
                    />
                  </HStack>

                  <VStack align="start" spacing={2}>
                    <Text 
                      fontWeight="semibold" 
                      color="#FFFFFF"
                      fontSize="md"
                      letterSpacing="0.3px"
                    >
                      {order.customer && order.customer.name
                        ? order.customer.name
                        : order.customerName || '-'}
                    </Text>
                    <Text 
                      fontSize="sm" 
                      color="#9ca3af"
                      fontWeight="medium"
                    >
                      {order.customer && order.customer.email
                        ? order.customer.email
                        : order.customerEmail || '-'}
                    </Text>
                  </VStack>

                  <VStack align="start" spacing={2}>
                    <HStack spacing={2}>
                      <Icon as={FaMapMarkerAlt} color="#10b981" boxSize={4} />
                      <Text 
                        fontSize="sm" 
                        color="#FFFFFF"
                        fontWeight="medium"
                        noOfLines={1}
                      >
                        {order.pickupAddress?.label || '-'}
                      </Text>
                    </HStack>
                    <HStack spacing={2}>
                      <Icon as={FaMapMarkerAlt} color="#ef4444" boxSize={4} />
                      <Text 
                        fontSize="sm" 
                        color="#FFFFFF"
                        fontWeight="medium"
                        noOfLines={1}
                      >
                        {order.dropoffAddress?.label || '-'}
                      </Text>
                    </HStack>
                  </VStack>

                  <HStack justify="space-between" pt={2} borderTop="1px solid" borderColor="#333333">
                    <Badge 
                      colorScheme={getStatusColor(order.status)}
                      px={3}
                      py={1}
                      borderRadius="full"
                      fontWeight="semibold"
                      fontSize="xs"
                      letterSpacing="0.5px"
                      boxShadow="0 2px 8px rgba(0, 0, 0, 0.3)"
                    >
                      {order.status
                        ? String(order.status).replace('_', ' ')
                        : 'Unknown'}
                    </Badge>
                    <Text 
                      fontWeight="bold" 
                      color="#10b981"
                      fontSize="lg"
                      letterSpacing="0.5px"
                    >
                      {formatCurrency(order.totalGBP || 0)}
                    </Text>
                  </HStack>

                  <HStack
                    justify="space-between"
                    fontSize="sm"
                    color="gray.600"
                  >
                    <HStack>
                      {order.driver &&
                      order.driver.user &&
                      order.driver.user.name ? (
                        <>
                          <Icon as={FaTruck} color="blue.500" boxSize={3} />
                          <Text>{order.driver.user.name}</Text>
                        </>
                      ) : (
                        <Text>No driver</Text>
                      )}
                    </HStack>
                    <HStack>
                      <Icon
                        as={
                          slaStatus.status === 'overdue'
                            ? FaExclamationTriangle
                            : slaStatus.status === 'warning'
                              ? FaClock
                              : FaCheckCircle
                        }
                        color={
                          slaStatus.status === 'overdue'
                            ? 'red.500'
                            : slaStatus.status === 'warning'
                              ? 'orange.500'
                              : 'green.500'
                        }
                        boxSize={3}
                      />
                      <Text fontSize="xs">{slaStatus.message}</Text>
                    </HStack>
                  </HStack>
                </VStack>
              </CardBody>
            </Card>
          );
        })
      )}
    </Grid>
  );

  const renderOrdersKanban = () => (
    <Grid templateColumns="repeat(5, 1fr)" gap={4}>
      {['DRAFT', 'CONFIRMED', 'in_progress', 'COMPLETED', 'CANCELLED'].map(
        status => {
          const statusOrders = filteredOrders.filter(
            order => order.status === status
          );
          return (
            <Card 
              key={status}
              bg="#111111"
              borderColor="#333333"
              borderWidth="2px"
              borderRadius="xl"
              boxShadow="0 4px 16px rgba(0, 0, 0, 0.4)"
              overflow="hidden"
            >
              <CardHeader 
                bg="linear-gradient(135deg, #1a1a1a 0%, #111111 100%)"
                borderBottom="2px solid"
                borderColor="#333333"
                pb={3}
              >
                <HStack justify="space-between">
                  <Heading 
                    size="sm" 
                    textTransform="capitalize"
                    color="#FFFFFF"
                    fontWeight="bold"
                    letterSpacing="0.5px"
                  >
                    {status ? String(status).replace('_', ' ') : 'Unknown'}
                  </Heading>
                  <Badge 
                    colorScheme="blue" 
                    borderRadius="full"
                    px={3}
                    py={1}
                    fontWeight="bold"
                    fontSize="sm"
                    boxShadow="0 2px 8px rgba(37, 99, 235, 0.4)"
                  >
                    {statusOrders.length}
                  </Badge>
                </HStack>
              </CardHeader>
              <CardBody bg="#111111" p={4}>
                <VStack spacing={3} align="stretch">
                  {statusOrders.map(order => {
                    const slaStatus = getSLAStatus(order);
                    return (
                      <Card
                        key={order.id}
                        bg="#1a1a1a"
                        borderColor="#333333"
                        borderWidth="1px"
                        borderRadius="lg"
                        cursor="pointer"
                        onClick={() => handleViewOrder(order.reference)}
                        transition="all 0.2s cubic-bezier(0.4, 0, 0.2, 1)"
                        _hover={{
                          transform: 'translateX(4px)',
                          borderColor: '#2563eb',
                          boxShadow: '0 4px 12px rgba(37, 99, 235, 0.3)',
                        }}
                      >
                        <CardBody p={3}>
                          <VStack align="start" spacing={2}>
                            <Text 
                              fontWeight="bold" 
                              fontSize="sm"
                              color="#2563eb"
                              letterSpacing="0.3px"
                            >
                              #{order.reference}
                            </Text>
                            <Text 
                              fontSize="xs" 
                              color="#FFFFFF"
                              fontWeight="medium"
                            >
                              {order.customerName}
                            </Text>
                            <Text 
                              fontSize="xs" 
                              color="#9ca3af" 
                              noOfLines={1}
                              fontWeight="medium"
                            >
                              {order.pickupAddress?.label || '-'}
                            </Text>
                            <HStack justify="space-between" w="full" pt={1} borderTop="1px solid" borderColor="#333333">
                              <Text 
                                fontWeight="bold" 
                                fontSize="xs"
                                color="#10b981"
                              >
                                {formatCurrency(order.totalGBP || 0)}
                              </Text>
                              <Icon
                                as={
                                  slaStatus.status === 'overdue'
                                    ? FaExclamationTriangle
                                    : slaStatus.status === 'warning'
                                      ? FaClock
                                      : FaCheckCircle
                                }
                                color={
                                  slaStatus.status === 'overdue'
                                    ? '#ef4444'
                                    : slaStatus.status === 'warning'
                                      ? '#f59e0b'
                                      : '#10b981'
                                }
                                boxSize={4}
                              />
                            </HStack>
                          </VStack>
                        </CardBody>
                      </Card>
                    );
                  })}
                </VStack>
              </CardBody>
            </Card>
          );
        }
      )}
    </Grid>
  );

  const actionBar = useMemo(() => (
    <HStack spacing={3}>
      <ViewToggle view={viewMode} onViewChange={setViewMode} />
      <Button
        leftIcon={<FaDownload />}
        variant="outline"
        onClick={() => handleBulkAction('export')}
        isDisabled={selectedOrders.length === 0}
        bg="#111111"
        color="#FFFFFF"
        borderColor="#333333"
        borderWidth="2px"
        borderRadius="lg"
        px={4}
        py={2}
        fontWeight="semibold"
        letterSpacing="0.5px"
        boxShadow="0 4px 12px rgba(0, 0, 0, 0.3)"
        _hover={{
          bg: '#1a1a1a',
          borderColor: '#2563eb',
          transform: 'translateY(-2px)',
          boxShadow: '0 6px 20px rgba(37, 99, 235, 0.4)',
        }}
        _active={{
          transform: 'translateY(0)',
        }}
        _disabled={{
          opacity: 0.5,
          cursor: 'not-allowed',
          bg: '#0a0a0a',
          borderColor: '#1a1a1a',
        }}
        transition="all 0.2s cubic-bezier(0.4, 0, 0.2, 1)"
      >
        Export ({selectedOrders.length})
      </Button>
      <Button
        leftIcon={<FaEnvelope />}
        variant="outline"
        onClick={() => handleBulkAction('email')}
        isDisabled={selectedOrders.length === 0}
        bg="#111111"
        color="#FFFFFF"
        borderColor="#333333"
        borderWidth="2px"
        borderRadius="lg"
        px={4}
        py={2}
        fontWeight="semibold"
        letterSpacing="0.5px"
        boxShadow="0 4px 12px rgba(0, 0, 0, 0.3)"
        _hover={{
          bg: '#1a1a1a',
          borderColor: '#10b981',
          transform: 'translateY(-2px)',
          boxShadow: '0 6px 20px rgba(16, 185, 129, 0.4)',
        }}
        _active={{
          transform: 'translateY(0)',
        }}
        _disabled={{
          opacity: 0.5,
          cursor: 'not-allowed',
          bg: '#0a0a0a',
          borderColor: '#1a1a1a',
        }}
        transition="all 0.2s cubic-bezier(0.4, 0, 0.2, 1)"
      >
        Email Customers
      </Button>
      <Button
        leftIcon={<FaExclamationTriangle />}
        colorScheme="orange"
        variant="outline"
        onClick={() => handleBulkAction('send-floor-warnings')}
        isDisabled={selectedOrders.length === 0}
        title="Send floor warning emails to selected customers who didn't specify floor numbers"
        bg="linear-gradient(135deg, #f59e0b 0%, #d97706 100%)"
        color="#FFFFFF"
        borderColor="#f59e0b"
        borderWidth="2px"
        borderRadius="lg"
        px={4}
        py={2}
        fontWeight="bold"
        letterSpacing="0.5px"
        boxShadow="0 4px 16px rgba(245, 158, 11, 0.4), 0 0 20px rgba(245, 158, 11, 0.2)"
        _hover={{
          bg: 'linear-gradient(135deg, #d97706 0%, #b45309 100%)',
          borderColor: '#f59e0b',
          transform: 'translateY(-2px)',
          boxShadow: '0 6px 24px rgba(245, 158, 11, 0.6), 0 0 30px rgba(245, 158, 11, 0.3)',
        }}
        _active={{
          transform: 'translateY(0)',
        }}
        _disabled={{
          opacity: 0.5,
          cursor: 'not-allowed',
          bg: '#0a0a0a',
          borderColor: '#1a1a1a',
        }}
        transition="all 0.2s cubic-bezier(0.4, 0, 0.2, 1)"
      >
        Send Floor Warnings ({selectedOrders.length})
      </Button>
      <Button
        leftIcon={<Icon as={FaPoundSign} />}
        variant={showUnpaidOrders ? "solid" : "outline"}
        colorScheme={showUnpaidOrders ? "red" : "gray"}
        onClick={() => setShowUnpaidOrders(!showUnpaidOrders)}
        bg={showUnpaidOrders ? "rgba(239, 68, 68, 0.2)" : "#111111"}
        color="#FFFFFF"
        borderColor={showUnpaidOrders ? "#ef4444" : "#333333"}
        borderWidth="2px"
        borderRadius="lg"
        px={4}
        py={2}
        fontWeight="semibold"
        letterSpacing="0.5px"
        boxShadow="0 4px 12px rgba(0, 0, 0, 0.3)"
        _hover={{
          bg: showUnpaidOrders ? "rgba(239, 68, 68, 0.3)" : '#1a1a1a',
          borderColor: showUnpaidOrders ? '#ef4444' : '#2563eb',
          transform: 'translateY(-2px)',
          boxShadow: showUnpaidOrders ? '0 6px 20px rgba(239, 68, 68, 0.4)' : '0 6px 20px rgba(37, 99, 235, 0.4)',
        }}
        _active={{
          transform: 'translateY(0)',
        }}
        transition="all 0.2s cubic-bezier(0.4, 0, 0.2, 1)"
      >
        {showUnpaidOrders ? 'Hide Unpaid Orders' : `Show Unpaid Orders (${unpaidOrdersCount})`}
      </Button>
    </HStack>
  ), [handleBulkAction, selectedOrders.length, setViewMode, viewMode, showUnpaidOrders, unpaidOrdersCount]);

  useEffect(() => {
    if (onActionsChange) {
      onActionsChange(actionBar);
    }
  }, [actionBar, onActionsChange]);

  return (
    <>
      <Box>
        {!hideActionBar && (
          <Box mb={4}>
            {actionBar}
          </Box>
        )}
        <Box>
          {/* Pending Orders Banner */}
          {!embedded && newOrdersCount > 0 && (
            <Card 
              mb={6} 
              bg="linear-gradient(135deg, #f59e0b 0%, #d97706 100%)"
              borderColor="#f59e0b"
              borderWidth="2px"
              borderRadius="xl"
              boxShadow="0 8px 32px rgba(245, 158, 11, 0.3), 0 0 20px rgba(245, 158, 11, 0.2)"
              position="relative"
              overflow="hidden"
              _before={{
                content: '""',
                position: 'absolute',
                top: 0,
                left: 0,
                right: 0,
                bottom: 0,
                background: 'linear-gradient(135deg, rgba(245, 158, 11, 0.1) 0%, rgba(217, 119, 6, 0.1) 100%)',
                pointerEvents: 'none',
              }}
              _after={{
                content: '""',
                position: 'absolute',
                top: 0,
                left: '-100%',
                width: '200%',
                height: '100%',
                background: 'linear-gradient(90deg, transparent 0%, rgba(255, 255, 255, 0.5) 25%, rgba(255, 255, 255, 0.7) 50%, rgba(255, 255, 255, 0.5) 75%, transparent 100%)',
                animation: `${waveAnimation} 3s ease-in-out infinite`,
                pointerEvents: 'none',
                zIndex: 1,
                filter: 'blur(1px)',
              }}
              css={{
                '@keyframes wave': {
                  '0%': {
                    transform: 'translateX(-100%) translateY(0) scaleY(1)',
                    opacity: '0.3',
                  },
                  '25%': {
                    transform: 'translateX(-50%) translateY(-5px) scaleY(1.1)',
                    opacity: '0.5',
                  },
                  '50%': {
                    transform: 'translateX(0%) translateY(-10px) scaleY(1.2)',
                    opacity: '0.7',
                  },
                  '75%': {
                    transform: 'translateX(50%) translateY(-5px) scaleY(1.1)',
                    opacity: '0.5',
                  },
                  '100%': {
                    transform: 'translateX(100%) translateY(0) scaleY(1)',
                    opacity: '0.3',
                  },
                },
              }}
            >
              <CardBody p={4} position="relative" zIndex={2}>
                <HStack spacing={4} align="center" position="relative" zIndex={2}>
                  <Circle
                    size="48px"
                    bg="rgba(255, 255, 255, 0.2)"
                    backdropFilter="blur(10px)"
                    border="2px solid rgba(255, 255, 255, 0.3)"
                    boxShadow="0 4px 16px rgba(0, 0, 0, 0.2)"
                  >
                    <Icon
                      as={FaExclamationTriangle}
                      color="#FFFFFF"
                      boxSize="24px"
                      animation={`${fastPulseAnimation} 2s infinite`}
                    />
                  </Circle>
                  <VStack align="start" spacing={1} flex={1}>
                    <Text
                      fontSize="lg"
                      fontWeight="bold"
                      color="#FFFFFF"
                      letterSpacing="0.5px"
                      textShadow="0 2px 8px rgba(0, 0, 0, 0.3)"
                    >
                      {newOrdersCount} New Order{newOrdersCount > 1 ? 's' : ''} Pending Assignment
                    </Text>
                    <Text
                      fontSize="sm"
                      color="rgba(255, 255, 255, 0.9)"
                      fontWeight="medium"
                    >
                      These orders need driver assignment. Click to view and assign drivers.
                    </Text>
                  </VStack>
                  <Badge
                    bg="rgba(255, 255, 255, 0.2)"
                    color="#FFFFFF"
                    fontSize="lg"
                    fontWeight="bold"
                    px={4}
                    py={2}
                    borderRadius="full"
                    border="2px solid rgba(255, 255, 255, 0.3)"
                    boxShadow="0 4px 16px rgba(0, 0, 0, 0.2)"
                    backdropFilter="blur(10px)"
                  >
                    {newOrdersCount}
                  </Badge>
                </HStack>
              </CardBody>
            </Card>
          )}

          {/* Filters */}
          <Card mb={6} bg="#000000" borderColor="#333333">
            <CardBody bg="#000000">
              <VStack spacing={4} align="stretch">
                {/* Search and Quick Filters */}
                <Flex gap={4} wrap="wrap">
                  <Box flex="1" minW="300px">
                    <InputGroup>
                      <InputLeftElement color="#FFFFFF">
                        <FaSearch />
                      </InputLeftElement>
                      <ClientInput
                        placeholder="Search by code, address, customer..."
                        value={searchQuery}
                        onChange={e => setSearchQuery(e.target.value)}
                        bg="#111111"
                        color="#FFFFFF"
                        borderColor="#333333"
                        _placeholder={{ color: '#9ca3af' }}
                        _focus={{ borderColor: '#2563eb', bg: '#111111' }}
                      />
                    </InputGroup>
                  </Box>
                  <Select
                    value={statusFilter}
                    onChange={e => setStatusFilter(e.target.value)}
                    placeholder="All Status"
                    minW="150px"
                    bg="#111111"
                    color="#FFFFFF"
                    borderColor="#333333"
                    _hover={{ borderColor: '#2563eb' }}
                    _focus={{ borderColor: '#2563eb', bg: '#111111' }}
                  >
                    <option value="open" style={{ backgroundColor: '#111111', color: '#FFFFFF' }}>Open</option>
                    <option value="assigned" style={{ backgroundColor: '#111111', color: '#FFFFFF' }}>Assigned</option>
                    <option value="in_progress" style={{ backgroundColor: '#111111', color: '#FFFFFF' }}>In Progress</option>
                    <option value="completed" style={{ backgroundColor: '#111111', color: '#FFFFFF' }}>Completed</option>
                    <option value="cancelled" style={{ backgroundColor: '#111111', color: '#FFFFFF' }}>Cancelled</option>
                  </Select>
                  <Select
                    value={paymentFilter}
                    onChange={e => setPaymentFilter(e.target.value)}
                    placeholder="All Payments"
                    minW="150px"
                    bg="#111111"
                    color="#FFFFFF"
                    borderColor="#333333"
                    _hover={{ borderColor: '#2563eb' }}
                    _focus={{ borderColor: '#2563eb', bg: '#111111' }}
                  >
                    <option value="unpaid" style={{ backgroundColor: '#111111', color: '#FFFFFF' }}>Unpaid</option>
                    <option value="requires_action" style={{ backgroundColor: '#111111', color: '#FFFFFF' }}>Requires Action</option>
                    <option value="paid" style={{ backgroundColor: '#111111', color: '#FFFFFF' }}>Paid</option>
                    <option value="refunded" style={{ backgroundColor: '#111111', color: '#FFFFFF' }}>Refunded</option>
                  </Select>
                  <Select
                    value={orderTypeFilter}
                    onChange={e => setOrderTypeFilter(e.target.value as 'all' | 'new' | 'existing')}
                    placeholder="Order Type"
                    minW="150px"
                    bg="#111111"
                    color="#FFFFFF"
                    borderColor="#333333"
                    _hover={{ borderColor: '#2563eb' }}
                    _focus={{ borderColor: '#2563eb', bg: '#111111' }}
                  >
                    <option value="all" style={{ backgroundColor: '#111111', color: '#FFFFFF' }}>All Orders</option>
                    <option value="new" style={{ backgroundColor: '#111111', color: '#FFFFFF' }}>New Orders Only</option>
                    <option value="existing" style={{ backgroundColor: '#111111', color: '#FFFFFF' }}>Existing Orders Only</option>
                  </Select>
                  <Select
                    value={dateRange}
                    onChange={e => setDateRange(e.target.value)}
                    placeholder="Date Range"
                    minW="150px"
                    bg="#111111"
                    color="#FFFFFF"
                    borderColor="#333333"
                    _hover={{ borderColor: '#2563eb' }}
                    _focus={{ borderColor: '#2563eb', bg: '#111111' }}
                  >
                    <option value="today" style={{ backgroundColor: '#111111', color: '#FFFFFF' }}>Today</option>
                    <option value="week" style={{ backgroundColor: '#111111', color: '#FFFFFF' }}>This Week</option>
                    <option value="month" style={{ backgroundColor: '#111111', color: '#FFFFFF' }}>This Month</option>
                    <option value="custom" style={{ backgroundColor: '#111111', color: '#FFFFFF' }}>Custom Range</option>
                  </Select>
                </Flex>

                {/* Additional Filters */}
                <Flex gap={4} wrap="wrap">
                  <ClientInput
                    placeholder="Filter by driver name..."
                    value={driverFilter}
                    onChange={e => setDriverFilter(e.target.value)}
                    minW="200px"
                    bg="#111111"
                    color="#FFFFFF"
                    borderColor="#333333"
                    _placeholder={{ color: '#9ca3af' }}
                    _focus={{ borderColor: '#2563eb', bg: '#111111' }}
                  />
                  <ClientInput
                    placeholder="Filter by area..."
                    value={areaFilter}
                    onChange={e => setAreaFilter(e.target.value)}
                    minW="200px"
                    bg="#111111"
                    color="#FFFFFF"
                    borderColor="#333333"
                    _placeholder={{ color: '#9ca3af' }}
                    _focus={{ borderColor: '#2563eb', bg: '#111111' }}
                  />
                </Flex>

                {/* Bulk Actions */}
                {selectedOrders.length > 0 && (
                  <Alert status="info" bg="#1a1a1a" borderColor="#2563eb">
                    <AlertIcon color="#2563eb" />
                    <HStack justify="space-between" w="full">
                      <Text color="#FFFFFF">{selectedOrders.length} orders selected</Text>
                      <HStack spacing={2}>
                        <Button
                          size="sm"
                          onClick={() => handleBulkAction('assign')}
                          bg="#2563eb"
                          color="#FFFFFF"
                          _hover={{ bg: '#1d4ed8' }}
                        >
                          Assign Driver
                        </Button>
                        <Button
                          size="sm"
                          onClick={() => handleBulkAction('status')}
                          bg="#2563eb"
                          color="#FFFFFF"
                          _hover={{ bg: '#1d4ed8' }}
                        >
                          Change Status
                        </Button>
                        <Button 
                          size="sm" 
                          onClick={() => setSelectedOrders([])}
                          variant="outline"
                          borderColor="#333333"
                          color="#FFFFFF"
                          _hover={{ bg: '#1a1a1a' }}
                        >
                          Clear Selection
                        </Button>
                      </HStack>
                    </HStack>
                  </Alert>
                )}
              </VStack>
            </CardBody>
          </Card>

          {/* Orders View */}
          {viewMode === 'table' && renderOrdersTable()}
          {viewMode === 'card' && renderOrdersCards()}
          {viewMode === 'kanban' && renderOrdersKanban()}

          {/* Pagination and Summary */}
          <Flex justify="space-between" align="center" mt={4}>
            <Text color="#FFFFFF">
              Showing {filteredOrders.length} of {orders.length} orders
            </Text>
            <HStack spacing={2}>
              <Button
                size="sm"
                variant="outline"
                isDisabled={pagination.page === 1}
                onClick={() =>
                  setPagination(prev => ({ ...prev, page: prev.page - 1 }))
                }
                borderColor="#333333"
                color="#FFFFFF"
                _hover={{ bg: '#1a1a1a' }}
                _disabled={{ borderColor: '#333333', color: '#9ca3af', opacity: 0.5 }}
              >
                Previous
              </Button>
              <Button
                size="sm"
                variant="outline"
                isDisabled={!pagination.hasMore}
                onClick={() => {
                  setPagination(prev => ({ ...prev, page: prev.page + 1 }));
                  loadOrders();
                }}
                borderColor="#333333"
                color="#FFFFFF"
                _hover={{ bg: '#1a1a1a' }}
                _disabled={{ borderColor: '#333333', color: '#9ca3af', opacity: 0.5 }}
              >
                Next
              </Button>
            </HStack>
          </Flex>
        </Box>
      </Box>

      {/* Order Detail Drawer */}
      <OrderDetailDrawer
        isOpen={isDetailOpen}
        onClose={onDetailClose}
        orderCode={selectedOrderCode}
        variant={embedded ? 'embedded' : 'standalone'}
        showSummaryCards={!embedded}
      />

      {/* Assign/Reassign Driver Modal */}
      <Modal isOpen={isAssignOpen} onClose={onAssignClose} size="lg">
        <ModalOverlay />
        <ModalContent>
          <ModalHeader>
            {selectedOrderForAssign?.driver ? 'Reassign Driver' : 'Assign Driver'}
          </ModalHeader>
          <ModalCloseButton />
          <ModalBody>
            <VStack spacing={4} align="stretch">
              <Box>
                <Text fontWeight="bold" mb={2}>Order:</Text>
                <Text>#{selectedOrderForAssign?.reference}</Text>
                {selectedOrderForAssign?.driver && (
                  <Text fontSize="sm" color="gray.600" mt={1}>
                    Current Driver: {selectedOrderForAssign.driver.user?.name}
                  </Text>
                )}
              </Box>

              <Box>
                <Text fontWeight="bold" mb={2}>Select Driver:</Text>
                <Select
                  placeholder="Choose a driver..."
                  value={selectedDriverId}
                  onChange={(e) => setSelectedDriverId(e.target.value)}
                >
                  {availableDrivers.map((driver) => (
                    <option key={driver.id} value={driver.id}>
                      {driver.User?.name || driver.name} - {driver.status}
                    </option>
                  ))}
                </Select>
              </Box>

              <Box>
                <Text fontWeight="bold" mb={2}>Reason (Optional):</Text>
                <Textarea
                  placeholder="e.g., Original driver unavailable, Better route match, etc."
                  value={assignReason}
                  onChange={(e) => setAssignReason(e.target.value)}
                  rows={3}
                />
              </Box>
            </VStack>
          </ModalBody>
          <ModalFooter>
            <Button variant="ghost" mr={3} onClick={onAssignClose}>
              Cancel
            </Button>
            <Button 
              colorScheme="blue" 
              onClick={handleAssignDriver}
              isLoading={isAssigning}
              isDisabled={!selectedDriverId}
            >
              {selectedOrderForAssign?.driver ? 'Reassign' : 'Assign'}
            </Button>
          </ModalFooter>
        </ModalContent>
      </Modal>

      {/* Remove Assignment Modal */}
      <Modal isOpen={isRemoveOpen} onClose={onRemoveClose} size="lg">
        <ModalOverlay />
        <ModalContent>
          <ModalHeader>Remove Driver Assignment</ModalHeader>
          <ModalCloseButton />
          <ModalBody>
            <VStack spacing={4} align="stretch">
              <Alert status="warning">
                <AlertIcon />
                This will remove the driver assignment from the order and free it up for reassignment.
              </Alert>

              {selectedOrderForRemoval && (
                <Box>
                  <Text fontWeight="bold" mb={2}>Order Details:</Text>
                  <Text>Order: #{selectedOrderForRemoval.reference}</Text>
                  <Text>Customer: {selectedOrderForRemoval.customerName}</Text>
                  {selectedOrderForRemoval.driver && (
                    <Text>Current Driver: {selectedOrderForRemoval.driver.user.name}</Text>
                  )}
                </Box>
              )}

              <Divider />

              <Box>
                <Text fontWeight="bold" mb={2}>Removal Options:</Text>
                <VStack align="stretch" spacing={2}>
                  <Button
                    variant={removalType === 'single' ? 'solid' : 'outline'}
                    colorScheme={removalType === 'single' ? 'blue' : 'gray'}
                    onClick={() => setRemovalType('single')}
                    justifyContent="flex-start"
                  >
                    Remove this order only (#{selectedOrderForRemoval?.reference})
                  </Button>
                  {selectedOrderForRemoval?.driver && (
                    <Button
                      variant={removalType === 'all' ? 'solid' : 'outline'}
                      colorScheme={removalType === 'all' ? 'red' : 'gray'}
                      onClick={() => setRemovalType('all')}
                      justifyContent="flex-start"
                    >
                      Remove ALL orders from {selectedOrderForRemoval.driver.user.name}
                    </Button>
                  )}
                </VStack>
              </Box>

              <Box>
                <Text fontWeight="bold" mb={2}>Reason (Optional):</Text>
                <Textarea
                  placeholder="e.g., Van breakdown, driver unavailable, etc."
                  value={removalReason}
                  onChange={(e) => setRemovalReason(e.target.value)}
                  rows={3}
                />
              </Box>
            </VStack>
          </ModalBody>
          <ModalFooter>
            <Button variant="ghost" mr={3} onClick={onRemoveClose}>
              Cancel
            </Button>
            <Button 
              colorScheme="red" 
              onClick={handleRemoveOrder}
            >
              {removalType === 'all' ? 'Remove All Orders' : 'Remove Order'}
            </Button>
          </ModalFooter>
        </ModalContent>
      </Modal>
    </>
  );
}

export default function OrdersClient(props: OrdersClientProps) {
  const [actions, setActions] = useState<ReactNode | null>(null);

  return (
    <AdminShell
      title="Orders"
      subtitle="Manage and track all orders"
      showCreateButton={false}
      showDispatchMode={true}
      actions={actions}
    >
      <OrdersTable
        {...props}
        hideActionBar
        onActionsChange={setActions}
      />
    </AdminShell>
  );
}

/**
 * Google Analytics 4 Component
 * 
 * Tracks all user interactions and conversions
 * Integrates with Google Ads for conversion tracking
 */

'use client';

import Script from 'next/script';
import { useEffect } from 'react';
import { usePathname, useSearchParams } from 'next/navigation';

const GA_MEASUREMENT_ID = 'G-XXXXXXXXXX'; // Set your Google Analytics ID here if needed
const IS_PRODUCTION = typeof window !== 'undefined' && window.location.hostname !== 'localhost';

export default function GoogleAnalytics() {
  const pathname = usePathname();
  const searchParams = useSearchParams();

  useEffect(() => {
    if (pathname) {
      pageview(pathname);
    }
  }, [pathname, searchParams]);

  if (!IS_PRODUCTION) {
    return null;
  }

  return (
    <>
      <Script
        strategy="afterInteractive"
        src={`https://www.googletagmanager.com/gtag/js?id=${GA_MEASUREMENT_ID}`}
      />
      <Script
        id="google-analytics"
        strategy="afterInteractive"
        dangerouslySetInnerHTML={{
          __html: `
            window.dataLayer = window.dataLayer || [];
            function gtag(){dataLayer.push(arguments);}
            gtag('js', new Date());
            gtag('config', '${GA_MEASUREMENT_ID}', {
              page_path: window.location.pathname,
              send_page_view: true,
              cookie_flags: 'SameSite=None;Secure'
            });
          `,
        }}
      />
    </>
  );
}

// Track page views
export const pageview = (url: string) => {
  if (typeof window.gtag !== 'undefined') {
    window.gtag('config', GA_MEASUREMENT_ID, {
      page_path: url,
    });
  }
};

// Track events
export const event = ({
  action,
  category,
  label,
  value,
}: {
  action: string;
  category: string;
  label?: string;
  value?: number;
}) => {
  if (typeof window.gtag !== 'undefined') {
    window.gtag('event', action, {
      event_category: category,
      event_label: label,
      value: value,
    });
  }
};

// Track conversions
export const trackConversion = (conversionId: string, value?: number) => {
  if (typeof window.gtag !== 'undefined') {
    window.gtag('event', 'conversion', {
      send_to: conversionId,
      value: value,
      currency: 'GBP',
    });
  }
};

// Predefined event trackers
export const trackQuoteRequest = (quoteValue: number) => {
  event({
    action: 'generate_lead',
    category: 'engagement',
    label: 'quote_request',
    value: quoteValue,
  });
};

export const trackBookingStarted = () => {
  event({
    action: 'begin_checkout',
    category: 'ecommerce',
    label: 'booking_started',
  });
};

export const trackBookingCompleted = (bookingValue: number, bookingId: string) => {
  event({
    action: 'purchase',
    category: 'ecommerce',
    label: bookingId,
    value: bookingValue,
  });
  
  // Also track as conversion
  trackConversion('AW-XXXXXXXXX/XXXXXX', bookingValue);
};

export const trackPhoneClick = () => {
  event({
    action: 'phone_click',
    category: 'engagement',
    label: 'contact',
  });
};

export const trackEmailClick = () => {
  event({
    action: 'email_click',
    category: 'engagement',
    label: 'contact',
  });
};

export const trackCTAClick = (ctaLabel: string) => {
  event({
    action: 'cta_click',
    category: 'engagement',
    label: ctaLabel,
  });
};

// Extend Window interface for TypeScript
declare global {
  interface Window {
    dataLayer: any[];
  }
}

'use client';

import React, { useState, useEffect, useCallback } from 'react';
import {
  Box,
  VStack,
  HStack,
  Heading,
  Text,
  Button,
  Card,
  CardBody,
  SimpleGrid,
  FormControl,
  FormLabel,
  Input,
  Select,
  Badge,
  Icon,
  Circle,
  Alert,
  AlertIcon,
  AlertTitle,
  AlertDescription,
  useToast,
  useColorModeValue,
  Flex,
  Tooltip,
  Switch,
  Collapse,
  useDisclosure,
  IconButton,
  Divider,
} from '@chakra-ui/react';
import {
  FaCalendarAlt,
  FaClock,
  FaInfoCircle,
  FaCheckCircle,
  FaExclamationTriangle,
  FaBolt,
  FaSun,
  FaMoon,
  FaBusinessTime,
  FaEdit,
  FaSync,
} from 'react-icons/fa';

interface TimeSlot {
  value: string;
  label: string;
  time: string;
  emoji: string;
  color: string;
  description?: string;
  surcharge?: number;
  availability?: 'available' | 'limited' | 'unavailable';
}

interface DateTimeSelection {
  date: string;
  timeSlot: string;
  specificTime?: string;
  isFlexible: boolean;
  urgentDelivery: boolean;
  notes?: string;
}

interface EnhancedDateTimeCardProps {
  value: DateTimeSelection;
  onChange: (selection: DateTimeSelection) => void;
  isMultipleDrop?: boolean;
  serviceTier?: string;
  distance?: number;
  isEditable?: boolean;
  showPricing?: boolean;
  onPricingUpdate?: (surcharge: number) => void;
}

export const EnhancedDateTimeCard: React.FC<EnhancedDateTimeCardProps> = ({
  value,
  onChange,
  isMultipleDrop = false,
  serviceTier = 'large_van',
  distance = 0,
  isEditable = true,
  showPricing = true,
  onPricingUpdate,
}) => {
  const [selectedDate, setSelectedDate] = useState(value.date);
  const [selectedTimeSlot, setSelectedTimeSlot] = useState(value.timeSlot);
  const [isFlexible, setIsFlexible] = useState(value.isFlexible);
  const [urgentDelivery, setUrgentDelivery] = useState(value.urgentDelivery);
  const [specificTime, setSpecificTime] = useState(value.specificTime || '');
  const [notes, setNotes] = useState(value.notes || '');
  const [currentSurcharge, setCurrentSurcharge] = useState(0);
  
  const { isOpen: isAdvancedOpen, onToggle: onAdvancedToggle } = useDisclosure();
  const toast = useToast();
  const cardBg = useColorModeValue('white', 'gray.800');
  const borderColor = useColorModeValue('gray.200', 'gray.700');

  // Time slot configurations
  const timeSlots: TimeSlot[] = [
    {
      value: 'morning',
      label: 'Morning',
      time: '8:00 - 12:00',
      emoji: '🌅',
      color: 'yellow',
      description: 'Best for early starts',
      availability: 'available',
    },
    {
      value: 'afternoon',
      label: 'Afternoon',
      time: '12:00 - 17:00',
      emoji: '☀️',
      color: 'orange',
      description: 'Most popular time',
      availability: 'limited',
    },
    {
      value: 'evening',
      label: 'Evening',
      time: '17:00 - 20:00',
      emoji: '🌆',
      color: 'purple',
      description: 'After work hours',
      surcharge: 15,
      availability: 'available',
    },
    {
      value: 'express',
      label: 'Express',
      time: 'Within 2 hours',
      emoji: '⚡',
      color: 'red',
      description: 'Same-day urgent delivery',
      surcharge: 50,
      availability: distance < 20 ? 'available' : 'unavailable',
    },
    {
      value: 'flexible',
      label: 'Flexible',
      time: 'Any time',
      emoji: '🕐',
      color: 'blue',
      description: 'Best price, flexible timing',
      surcharge: -10,
      availability: 'available',
    },
  ];

  // Update parent component when values change
  useEffect(() => {
    const newSelection: DateTimeSelection = {
      date: selectedDate,
      timeSlot: selectedTimeSlot,
      specificTime: specificTime || undefined,
      isFlexible,
      urgentDelivery,
      notes: notes || undefined,
    };
    
    onChange(newSelection);
  }, [selectedDate, selectedTimeSlot, specificTime, isFlexible, urgentDelivery, notes, onChange]);

  // Calculate pricing surcharge
  useEffect(() => {
    let surcharge = 0;
    
    // Time slot surcharge
    const selectedSlot = timeSlots.find(slot => slot.value === selectedTimeSlot);
    if (selectedSlot?.surcharge) {
      surcharge += selectedSlot.surcharge;
    }
    
    // Urgent delivery surcharge
    if (urgentDelivery) {
      surcharge += 25;
    }
    
    // Multiple drop complexity surcharge
    if (isMultipleDrop && selectedTimeSlot !== 'flexible') {
      surcharge += 10;
    }
    
    // Weekend surcharge
    if (selectedDate) {
      const date = new Date(selectedDate);
      const dayOfWeek = date.getDay();
      if (dayOfWeek === 0 || dayOfWeek === 6) { // Sunday or Saturday
        surcharge += 20;
      }
    }
    
    setCurrentSurcharge(surcharge);
    
    if (onPricingUpdate) {
      onPricingUpdate(surcharge);
    }
  }, [selectedTimeSlot, urgentDelivery, isMultipleDrop, selectedDate, onPricingUpdate]);

  const handleDateSelect = useCallback((date: string) => {
    setSelectedDate(date);
    
    // Show weekend surcharge notification
    const selectedDateObj = new Date(date);
    const dayOfWeek = selectedDateObj.getDay();
    if (dayOfWeek === 0 || dayOfWeek === 6) {
      toast({
        title: 'Weekend Surcharge',
        description: 'A £20 weekend surcharge applies to this date',
        status: 'info',
        duration: 3000,
        isClosable: true,
      });
    }
  }, [toast]);

  const handleTimeSlotSelect = useCallback((slotValue: string) => {
    const slot = timeSlots.find(s => s.value === slotValue);
    
    if (slot?.availability === 'unavailable') {
      toast({
        title: 'Time Slot Unavailable',
        description: slot.value === 'express' ? 'Express delivery not available for distances over 20 miles' : 'This time slot is not available',
        status: 'warning',
        duration: 4000,
        isClosable: true,
      });
      return;
    }
    
    setSelectedTimeSlot(slotValue);
    
    // Show surcharge notification
    if (slot?.surcharge && slot.surcharge > 0) {
      toast({
        title: 'Additional Charge',
        description: `£${slot.surcharge} surcharge applies for ${slot.label.toLowerCase()} delivery`,
        status: 'info',
        duration: 3000,
        isClosable: true,
      });
    } else if (slot?.surcharge && slot.surcharge < 0) {
      toast({
        title: 'Discount Applied',
        description: `£${Math.abs(slot.surcharge)} discount for flexible timing`,
        status: 'success',
        duration: 3000,
        isClosable: true,
      });
    }
  }, [toast]);

  const getAvailabilityColor = (availability: string) => {
    switch (availability) {
      case 'available': return 'green';
      case 'limited': return 'orange';
      case 'unavailable': return 'red';
      default: return 'gray';
    }
  };

  const formatSurcharge = (amount: number) => {
    if (amount > 0) return `+£${amount}`;
    if (amount < 0) return `-£${Math.abs(amount)}`;
    return '';
  };

  return (
    <Card bg={cardBg} borderRadius="xl" shadow="md" border="1px solid" borderColor={borderColor}>
      <CardBody p={6}>
        <VStack spacing={6} align="stretch">
          {/* Header */}
          <Box textAlign="center">
            <HStack spacing={3} justify="center" mb={3}>
              <Circle size="50px" bg="blue.500" color="white">
                <Icon as={FaCalendarAlt} boxSize={6} />
              </Circle>
              <VStack align="start" spacing={0}>
                <HStack spacing={2}>
                  <Heading as="h3" size="xl" color="gray.700" bgGradient="linear(to-r, blue.600, purple.600)" bgClip="text">
                    📅 {isMultipleDrop ? 'Route Schedule' : 'When are we moving?'}
                  </Heading>
                  {selectedDate && selectedTimeSlot && (
                    <Badge colorScheme="blue" variant="solid" fontSize="xs">
                      ✓ Scheduled
                    </Badge>
                  )}
                </HStack>
                <Text fontSize="sm" color="gray.500">
                  {isMultipleDrop ? 'Plan your multiple drop route' : 'Select your preferred date and time'}
                </Text>
              </VStack>
            </HStack>
          </Box>

          {/* Pricing Summary */}
          {showPricing && currentSurcharge !== 0 && (
            <Alert status={currentSurcharge > 0 ? 'warning' : 'success'} borderRadius="md">
              <AlertIcon />
              <Box>
                <AlertTitle fontSize="sm">
                  {currentSurcharge > 0 ? 'Additional Charges' : 'Discount Applied'}
                </AlertTitle>
                <AlertDescription fontSize="xs">
                  {formatSurcharge(currentSurcharge)} for selected date and time options
                </AlertDescription>
              </Box>
            </Alert>
          )}

          {/* Date Selection */}
          <VStack spacing={4} align="stretch">
            <FormControl isRequired>
              <FormLabel fontSize="sm" fontWeight="bold" color="gray.700">
                <Icon as={FaCalendarAlt} mr={2} />
                {isMultipleDrop ? 'Route Start Date' : 'Pickup Date'}
              </FormLabel>
              
              {/* Quick Date Cards */}
              <Card bg="gray.50" borderRadius="xl" p={4} mb={4} border="2px solid" borderColor="gray.200">
                <VStack spacing={3}>
                  <Text fontSize="sm" fontWeight="semibold" color="gray.700" mb={2}>
                    Quick Date Selection
                  </Text>
                  <SimpleGrid columns={{ base: 1, sm: 2, md: 3, lg: 5 }} spacing={3} w="full">
                    {(() => {
                      const today = new Date();
                      const dates = [];
                      
                      for (let i = 0; i < 5; i++) {
                        const date = new Date(today);
                        date.setDate(today.getDate() + i);
                        dates.push(date);
                      }
                      
                      return dates.map((date, index) => {
                        const dateString = date.toISOString().split('T')[0];
                        const isSelected = selectedDate === dateString;
                        const dayName = date.toLocaleDateString('en-GB', { weekday: 'short' });
                        const dayNumber = date.getDate();
                        const monthName = date.toLocaleDateString('en-GB', { month: 'short' });
                        const isWeekend = date.getDay() === 0 || date.getDay() === 6;
                        
                        let label = '';
                        let colorScheme = 'gray';
                        let emoji = '';
                        
                        if (index === 0) {
                          label = 'Today';
                          colorScheme = isSelected ? 'red' : 'red';
                          emoji = '🔥';
                        } else if (index === 1) {
                          label = 'Tomorrow';
                          colorScheme = isSelected ? 'orange' : 'orange';
                          emoji = '⚡';
                        } else {
                          label = dayName;
                          colorScheme = isSelected ? 'blue' : 'blue';
                          emoji = isWeekend ? '🎉' : '💎';
                        }
                        
                        return (
                          <Card
                            key={dateString}
                            bg={isSelected ? `${colorScheme}.500` : 'white'}
                            borderColor={isSelected ? `${colorScheme}.500` : isWeekend ? 'orange.300' : 'gray.200'}
                            borderWidth="2px"
                            borderRadius="xl"
                            p={3}
                            cursor={isEditable ? "pointer" : "default"}
                            onClick={() => isEditable && handleDateSelect(dateString)}
                            _hover={isEditable ? { shadow: 'lg' } : {}}
                            transition="all 0.3s ease"
                            textAlign="center"
                            minH="100px"
                            display="flex"
                            flexDirection="column"
                            justifyContent="center"
                            alignItems="center"
                            position="relative"
                          >
                            {isWeekend && (
                              <Badge
                                position="absolute"
                                top={1}
                                right={1}
                                colorScheme="orange"
                                fontSize="2xs"
                                variant="solid"
                              >
                                +£20
                              </Badge>
                            )}
                            <Text fontSize="lg" mb={1}>{emoji}</Text>
                            <Text fontWeight="bold" fontSize="sm" lineHeight="1.2" color={isSelected ? 'white' : 'gray.700'} mb={1}>
                              {label}
                            </Text>
                            <Text fontSize="xs" color={isSelected ? 'white' : 'gray.500'} fontWeight="semibold">
                              {dayNumber} {monthName}
                            </Text>
                          </Card>
                        );
                      });
                    })()}
                  </SimpleGrid>
                  
                  {/* Custom Date Input */}
                  <Card bg="white" borderRadius="lg" p={4} border="2px solid" borderColor="gray.200">
                    <VStack spacing={3}>
                      <Text fontSize="sm" color="gray.600" fontWeight="medium">Or choose a custom date:</Text>
                      <Input
                        type="date"
                        value={selectedDate}
                        onChange={(e) => handleDateSelect(e.target.value)}
                        min={new Date().toISOString().split('T')[0]}
                        bg="gray.50"
                        borderColor="gray.300"
                        _hover={{ borderColor: "blue.400" }}
                        _focus={{ borderColor: "blue.500", boxShadow: "0 0 0 1px #3182ce" }}
                        size="md"
                        borderRadius="lg"
                        fontWeight="medium"
                        isDisabled={!isEditable}
                      />
                    </VStack>
                  </Card>
                </VStack>
              </Card>
            </FormControl>
          </VStack>

          {/* Time Slot Selection */}
          <FormControl isRequired>
            <FormLabel fontSize="md" fontWeight="bold" color="gray.700" mb={4}>
              <Icon as={FaClock} mr={2} />
              Choose Time Slot
            </FormLabel>
            
            <SimpleGrid columns={{ base: 1, sm: 2, md: 3, lg: 5 }} spacing={4}>
              {timeSlots.map((slot) => {
                const isSelected = selectedTimeSlot === slot.value;
                const isUnavailable = slot.availability === 'unavailable';
                
                return (
                  <Tooltip
                    key={slot.value}
                    label={isUnavailable ? 'Not available for this distance' : slot.description}
                    hasArrow
                  >
                    <Card
                      bg={isSelected ? `${slot.color}.50` : isUnavailable ? 'gray.100' : 'white'}
                      borderColor={isSelected ? `${slot.color}.500` : isUnavailable ? 'gray.300' : 'gray.200'}
                      borderWidth="2px"
                      borderRadius="xl"
                      p={4}
                      cursor={isEditable && !isUnavailable ? "pointer" : "not-allowed"}
                      onClick={() => isEditable && !isUnavailable && handleTimeSlotSelect(slot.value)}
                      _hover={isEditable && !isUnavailable ? { 
                        shadow: 'lg',
                        transform: 'translateY(-2px)',
                        borderColor: `${slot.color}.400`
                      } : {}}
                      transition="all 0.3s ease"
                      textAlign="center"
                      minH="120px"
                      display="flex"
                      flexDirection="column"
                      justifyContent="center"
                      alignItems="center"
                      position="relative"
                      opacity={isUnavailable ? 0.5 : 1}
                    >
                      {/* Availability Badge */}
                      <Badge
                        position="absolute"
                        top={2}
                        right={2}
                        colorScheme={getAvailabilityColor(slot.availability || 'available')}
                        fontSize="2xs"
                        variant="solid"
                      >
                        {slot.availability === 'limited' ? 'Limited' : slot.availability === 'unavailable' ? 'N/A' : '✓'}
                      </Badge>
                      
                      {/* Surcharge Badge */}
                      {slot.surcharge && (
                        <Badge
                          position="absolute"
                          top={2}
                          left={2}
                          colorScheme={slot.surcharge > 0 ? 'red' : 'green'}
                          fontSize="2xs"
                          variant="solid"
                        >
                          {formatSurcharge(slot.surcharge)}
                        </Badge>
                      )}
                      
                      <Text fontSize="2xl" mb={2}>{slot.emoji}</Text>
                      <Text fontSize="sm" fontWeight="bold" color={isSelected ? `${slot.color}.700` : 'gray.700'} mb={1}>
                        {slot.label}
                      </Text>
                      <Text fontSize="xs" color={isSelected ? `${slot.color}.600` : 'gray.500'}>
                        {slot.time}
                      </Text>
                    </Card>
                  </Tooltip>
                );
              })}
            </SimpleGrid>
          </FormControl>

          {/* Advanced Options */}
          <Card variant="outline">
            <CardBody>
              <VStack spacing={4} align="stretch">
                <HStack justify="space-between" cursor="pointer" onClick={onAdvancedToggle}>
                  <Text fontSize="md" fontWeight="semibold" color="gray.700">
                    Advanced Options
                  </Text>
                  <IconButton
                    aria-label="Toggle advanced options"
                    icon={<FaEdit />}
                    size="sm"
                    variant="ghost"
                  />
                </HStack>
                
                <Collapse in={isAdvancedOpen}>
                  <VStack spacing={4} align="stretch">
                    <Divider />
                    
                    {/* Specific Time */}
                    {selectedTimeSlot !== 'flexible' && selectedTimeSlot !== 'express' && (
                      <FormControl>
                        <FormLabel fontSize="sm">Specific Time (Optional)</FormLabel>
                        <Input
                          type="time"
                          value={specificTime}
                          onChange={(e) => setSpecificTime(e.target.value)}
                          placeholder="Leave empty for flexible timing within slot"
                          isDisabled={!isEditable}
                        />
                      </FormControl>
                    )}
                    
                    {/* Urgent Delivery Toggle */}
                    <FormControl display="flex" alignItems="center">
                      <FormLabel htmlFor="urgent-delivery" mb="0" fontSize="sm">
                        Urgent Delivery (+£25)
                      </FormLabel>
                      <Switch
                        id="urgent-delivery"
                        isChecked={urgentDelivery}
                        onChange={(e) => setUrgentDelivery(e.target.checked)}
                        colorScheme="red"
                        isDisabled={!isEditable}
                      />
                    </FormControl>
                    
                    {/* Flexible Timing Toggle */}
                    <FormControl display="flex" alignItems="center">
                      <FormLabel htmlFor="flexible-timing" mb="0" fontSize="sm">
                        I'm flexible with timing (-£10 discount)
                      </FormLabel>
                      <Switch
                        id="flexible-timing"
                        isChecked={isFlexible}
                        onChange={(e) => setIsFlexible(e.target.checked)}
                        colorScheme="green"
                        isDisabled={!isEditable}
                      />
                    </FormControl>
                    
                    {/* Special Notes */}
                    <FormControl>
                      <FormLabel fontSize="sm">Special Instructions</FormLabel>
                      <Input
                        value={notes}
                        onChange={(e) => setNotes(e.target.value)}
                        placeholder="Any special timing requirements..."
                        isDisabled={!isEditable}
                      />
                    </FormControl>
                  </VStack>
                </Collapse>
              </VStack>
            </CardBody>
          </Card>

          {/* Summary */}
          {selectedDate && selectedTimeSlot && (
            <Alert status="success" borderRadius="md">
              <AlertIcon />
              <Box>
                <AlertTitle fontSize="sm">
                  {isMultipleDrop ? 'Route Scheduled' : 'Pickup Scheduled'}
                </AlertTitle>
                <AlertDescription fontSize="xs">
                  {new Date(selectedDate).toLocaleDateString('en-GB', { 
                    weekday: 'long', 
                    year: 'numeric', 
                    month: 'long', 
                    day: 'numeric' 
                  })} • {timeSlots.find(s => s.value === selectedTimeSlot)?.time}
                  {specificTime && ` at ${specificTime}`}
                  {currentSurcharge !== 0 && ` • ${formatSurcharge(currentSurcharge)}`}
                </AlertDescription>
              </Box>
            </Alert>
          )}
        </VStack>
      </CardBody>
    </Card>
  );
};

export default EnhancedDateTimeCard;

'use client';

import React, { useState, useEffect, useCallback } from 'react';
import {
  Box,
  VStack,
  HStack,
  Heading,
  Text,
  Button,
  Card,
  CardBody,
  CardHeader,
  SimpleGrid,
  FormControl,
  FormLabel,
  Input,
  Select,
  Badge,
  Icon,
  Circle,
  Divider,
  Alert,
  AlertIcon,
  AlertTitle,
  AlertDescription,
  useToast,
  useColorModeValue,
  Flex,
  Tooltip,
  Switch,
  NumberInput,
  NumberInputField,
  NumberInputStepper,
  NumberIncrementStepper,
  NumberDecrementStepper,
  Modal,
  ModalOverlay,
  ModalContent,
  ModalHeader,
  ModalBody,
  ModalFooter,
  ModalCloseButton,
  useDisclosure,
  Collapse,
  IconButton,
} from '@chakra-ui/react';
import {
  FaCalendarAlt,
  FaClock,
  FaRoute,
  FaTruck,
  FaMapMarkerAlt,
  FaPlus,
  FaMinus,
  FaInfoCircle,
  FaCheckCircle,
  FaExclamationTriangle,
  FaEdit,
  FaTrash,
  FaArrowRight,
  FaSync,
} from 'react-icons/fa';

interface Drop {
  id: string;
  pickupAddress: string;
  dropoffAddress: string;
  scheduledTime?: string;
  timeWindow?: {
    start: string;
    end: string;
  };
  priority: 'low' | 'medium' | 'high';
  estimatedDuration: number;
  items: Array<{
    name: string;
    quantity: number;
  }>;
}

interface RouteSchedule {
  id: string;
  startDate: string;
  startTime: string;
  endTime: string;
  totalDuration: number;
  totalDistance: number;
  serviceTier: string;
  drops: Drop[];
  optimized: boolean;
  driverId?: string;
  driverName?: string;
}

interface MultipleDropsDateTimeCardProps {
  drops: Drop[];
  onScheduleUpdate: (schedule: RouteSchedule) => void;
  onDropUpdate: (dropId: string, updates: Partial<Drop>) => void;
  onDropRemove: (dropId: string) => void;
  serviceTier: string;
  isEditable?: boolean;
  showOptimization?: boolean;
}

export const MultipleDropsDateTimeCard: React.FC<MultipleDropsDateTimeCardProps> = ({
  drops,
  onScheduleUpdate,
  onDropUpdate,
  onDropRemove,
  serviceTier,
  isEditable = true,
  showOptimization = true,
}) => {
  const [schedule, setSchedule] = useState<RouteSchedule>({
    id: `route_${Date.now()}`,
    startDate: '',
    startTime: '',
    endTime: '',
    totalDuration: 0,
    totalDistance: 0,
    serviceTier,
    drops,
    optimized: false,
  });

  const [isOptimizing, setIsOptimizing] = useState(false);
  const [selectedDrop, setSelectedDrop] = useState<Drop | null>(null);
  const [timeConflicts, setTimeConflicts] = useState<string[]>([]);
  
  const { isOpen: isDropModalOpen, onOpen: onDropModalOpen, onClose: onDropModalClose } = useDisclosure();
  const { isOpen: isOptimizeModalOpen, onOpen: onOptimizeModalOpen, onClose: onOptimizeModalClose } = useDisclosure();
  
  const toast = useToast();
  const cardBg = useColorModeValue('white', 'gray.800');
  const borderColor = useColorModeValue('gray.200', 'gray.700');

  // Calculate total route metrics
  useEffect(() => {
    const totalDuration = drops.reduce((sum, drop) => sum + drop.estimatedDuration, 0);
    const totalDistance = drops.length * 8.5; // Estimated 8.5 miles per drop
    
    // Calculate end time based on start time and total duration
    let endTime = '';
    if (schedule.startTime) {
      const [hours, minutes] = schedule.startTime.split(':').map(Number);
      const startMinutes = hours * 60 + minutes;
      const endMinutes = startMinutes + totalDuration;
      const endHours = Math.floor(endMinutes / 60) % 24;
      const endMins = endMinutes % 60;
      endTime = `${endHours.toString().padStart(2, '0')}:${endMins.toString().padStart(2, '0')}`;
    }

    setSchedule(prev => ({
      ...prev,
      drops,
      totalDuration,
      totalDistance,
      endTime,
    }));
  }, [drops, schedule.startTime]);

  // Detect time conflicts
  useEffect(() => {
    const conflicts: string[] = [];
    
    drops.forEach((drop, index) => {
      if (drop.timeWindow) {
        const dropStart = new Date(`${schedule.startDate}T${drop.timeWindow.start}`);
        const dropEnd = new Date(`${schedule.startDate}T${drop.timeWindow.end}`);
        
        // Check for overlaps with other drops
        drops.forEach((otherDrop, otherIndex) => {
          if (index !== otherIndex && otherDrop.timeWindow) {
            const otherStart = new Date(`${schedule.startDate}T${otherDrop.timeWindow.start}`);
            const otherEnd = new Date(`${schedule.startDate}T${otherDrop.timeWindow.end}`);
            
            if ((dropStart < otherEnd && dropEnd > otherStart)) {
              conflicts.push(`Drop ${index + 1} conflicts with Drop ${otherIndex + 1}`);
            }
          }
        });
      }
    });
    
    setTimeConflicts([...new Set(conflicts)]);
  }, [drops, schedule.startDate]);

  const handleDateChange = useCallback((date: string) => {
    setSchedule(prev => ({ ...prev, startDate: date }));
  }, []);

  const handleStartTimeChange = useCallback((time: string) => {
    setSchedule(prev => ({ ...prev, startTime: time }));
  }, []);

  const handleDropTimeUpdate = useCallback((dropId: string, timeWindow: { start: string; end: string }) => {
    onDropUpdate(dropId, { timeWindow });
  }, [onDropUpdate]);

  const handleOptimizeRoute = useCallback(async () => {
    setIsOptimizing(true);
    
    try {
      // Simulate route optimization API call
      await new Promise(resolve => setTimeout(resolve, 2000));
      
      // Mock optimization: sort by priority and geographical proximity
      const optimizedDrops = [...drops].sort((a, b) => {
        const priorityOrder = { high: 3, medium: 2, low: 1 };
        return priorityOrder[b.priority] - priorityOrder[a.priority];
      });
      
      // Assign optimized time windows
      let currentTime = schedule.startTime ? new Date(`${schedule.startDate}T${schedule.startTime}`) : new Date();
      
      optimizedDrops.forEach((drop, index) => {
        const startTime = new Date(currentTime);
        const endTime = new Date(currentTime.getTime() + drop.estimatedDuration * 60000);
        
        onDropUpdate(drop.id, {
          timeWindow: {
            start: startTime.toTimeString().slice(0, 5),
            end: endTime.toTimeString().slice(0, 5),
          },
        });
        
        // Add travel time to next drop (15 minutes average)
        currentTime = new Date(endTime.getTime() + 15 * 60000);
      });
      
      setSchedule(prev => ({ ...prev, optimized: true }));
      
      toast({
        title: 'Route Optimized',
        description: `Route optimized for ${drops.length} drops with minimal travel time`,
        status: 'success',
        duration: 5000,
        isClosable: true,
      });
      
    } catch (error) {
      toast({
        title: 'Optimization Failed',
        description: 'Unable to optimize route. Please try again.',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setIsOptimizing(false);
      onOptimizeModalClose();
    }
  }, [drops, schedule.startTime, schedule.startDate, onDropUpdate, toast, onOptimizeModalClose]);

  const handleSaveSchedule = useCallback(() => {
    if (!schedule.startDate || !schedule.startTime) {
      toast({
        title: 'Missing Information',
        description: 'Please select both date and start time',
        status: 'warning',
        duration: 3000,
        isClosable: true,
      });
      return;
    }

    if (timeConflicts.length > 0) {
      toast({
        title: 'Time Conflicts Detected',
        description: 'Please resolve time conflicts before saving',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
      return;
    }

    onScheduleUpdate(schedule);
    
    toast({
      title: 'Schedule Saved',
      description: `Route scheduled for ${new Date(schedule.startDate).toLocaleDateString()} at ${schedule.startTime}`,
      status: 'success',
      duration: 5000,
      isClosable: true,
    });
  }, [schedule, timeConflicts, onScheduleUpdate, toast]);

  const getPriorityColor = (priority: string) => {
    switch (priority) {
      case 'high': return 'red';
      case 'medium': return 'orange';
      case 'low': return 'gray';
      default: return 'gray';
    }
  };

  const formatDuration = (minutes: number) => {
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    return hours > 0 ? `${hours}h ${mins}m` : `${mins}m`;
  };

  return (
    <Card bg={cardBg} borderRadius="xl" shadow="lg" border="1px solid" borderColor={borderColor}>
      <CardHeader>
        <VStack spacing={4} align="stretch">
          {/* Header */}
          <HStack justify="space-between" align="start">
            <VStack align="start" spacing={1}>
              <HStack spacing={3}>
                <Circle size="50px" bg="blue.500" color="white">
                  <Icon as={FaRoute} boxSize={6} />
                </Circle>
                <VStack align="start" spacing={0}>
                  <Heading size="lg" color="gray.700">
                    📅 Multiple Drops Schedule
                  </Heading>
                  <Text fontSize="sm" color="gray.500">
                    Plan your route with {drops.length} drop{drops.length !== 1 ? 's' : ''}
                  </Text>
                </VStack>
              </HStack>
            </VStack>
            
            <VStack align="end" spacing={2}>
              <Badge colorScheme={schedule.optimized ? 'green' : 'gray'} variant="solid">
                {schedule.optimized ? '✓ Optimized' : 'Not Optimized'}
              </Badge>
              {timeConflicts.length > 0 && (
                <Badge colorScheme="red" variant="solid">
                  {timeConflicts.length} Conflict{timeConflicts.length !== 1 ? 's' : ''}
                </Badge>
              )}
            </VStack>
          </HStack>

          {/* Route Summary */}
          <SimpleGrid columns={{ base: 2, md: 4 }} spacing={4}>
            <Card variant="outline">
              <CardBody textAlign="center" py={3}>
                <Text fontSize="xs" color="gray.500" mb={1}>Total Drops</Text>
                <Text fontSize="lg" fontWeight="bold">{drops.length}</Text>
              </CardBody>
            </Card>
            <Card variant="outline">
              <CardBody textAlign="center" py={3}>
                <Text fontSize="xs" color="gray.500" mb={1}>Duration</Text>
                <Text fontSize="lg" fontWeight="bold">{formatDuration(schedule.totalDuration)}</Text>
              </CardBody>
            </Card>
            <Card variant="outline">
              <CardBody textAlign="center" py={3}>
                <Text fontSize="xs" color="gray.500" mb={1}>Distance</Text>
                <Text fontSize="lg" fontWeight="bold">{schedule.totalDistance.toFixed(1)} mi</Text>
              </CardBody>
            </Card>
            <Card variant="outline">
              <CardBody textAlign="center" py={3}>
                <Text fontSize="xs" color="gray.500" mb={1}>Service</Text>
                <Text fontSize="lg" fontWeight="bold">{serviceTier.replace('_', ' ')}</Text>
              </CardBody>
            </Card>
          </SimpleGrid>
        </VStack>
      </CardHeader>

      <CardBody>
        <VStack spacing={6} align="stretch">
          {/* Date and Time Selection */}
          <Card variant="outline">
            <CardBody>
              <VStack spacing={4} align="stretch">
                <Heading size="md" color="gray.700">
                  <Icon as={FaCalendarAlt} mr={2} />
                  Route Date & Time
                </Heading>
                
                <SimpleGrid columns={{ base: 1, md: 2 }} spacing={4}>
                  <FormControl isRequired>
                    <FormLabel fontSize="sm">Start Date</FormLabel>
                    <Input
                      type="date"
                      value={schedule.startDate}
                      onChange={(e) => handleDateChange(e.target.value)}
                      min={new Date().toISOString().split('T')[0]}
                      isDisabled={!isEditable}
                    />
                  </FormControl>
                  
                  <FormControl isRequired>
                    <FormLabel fontSize="sm">Start Time</FormLabel>
                    <Input
                      type="time"
                      value={schedule.startTime}
                      onChange={(e) => handleStartTimeChange(e.target.value)}
                      isDisabled={!isEditable}
                    />
                  </FormControl>
                </SimpleGrid>
                
                {schedule.startTime && schedule.endTime && (
                  <Alert status="info" borderRadius="md">
                    <AlertIcon />
                    <Box>
                      <AlertTitle fontSize="sm">Estimated Completion</AlertTitle>
                      <AlertDescription fontSize="xs">
                        Route will finish around {schedule.endTime} ({formatDuration(schedule.totalDuration)} total)
                      </AlertDescription>
                    </Box>
                  </Alert>
                )}
              </VStack>
            </CardBody>
          </Card>

          {/* Time Conflicts Alert */}
          {timeConflicts.length > 0 && (
            <Alert status="error" borderRadius="md">
              <AlertIcon />
              <Box>
                <AlertTitle fontSize="sm">Time Conflicts Detected</AlertTitle>
                <AlertDescription fontSize="xs">
                  {timeConflicts.join(', ')}. Please adjust drop time windows.
                </AlertDescription>
              </Box>
            </Alert>
          )}

          {/* Drops List */}
          <Card variant="outline">
            <CardBody>
              <VStack spacing={4} align="stretch">
                <HStack justify="space-between">
                  <Heading size="md" color="gray.700">
                    <Icon as={FaTruck} mr={2} />
                    Drop Schedule
                  </Heading>
                  
                  {showOptimization && isEditable && (
                    <Button
                      size="sm"
                      colorScheme="blue"
                      variant="outline"
                      leftIcon={<FaSync />}
                      onClick={onOptimizeModalOpen}
                      isLoading={isOptimizing}
                    >
                      Optimize Route
                    </Button>
                  )}
                </HStack>
                
                <VStack spacing={3} align="stretch">
                  {drops.map((drop, index) => (
                    <Card key={drop.id} variant="outline" bg="gray.50">
                      <CardBody>
                        <VStack spacing={3} align="stretch">
                          <HStack justify="space-between" align="start">
                            <VStack align="start" spacing={1}>
                              <HStack>
                                <Badge colorScheme="blue" variant="outline">
                                  Drop {index + 1}
                                </Badge>
                                <Badge colorScheme={getPriorityColor(drop.priority)} size="sm">
                                  {drop.priority}
                                </Badge>
                              </HStack>
                              <Text fontSize="sm" fontWeight="medium">
                                {drop.pickupAddress} → {drop.dropoffAddress}
                              </Text>
                              <Text fontSize="xs" color="gray.500">
                                {drop.items.length} item{drop.items.length !== 1 ? 's' : ''} • {formatDuration(drop.estimatedDuration)}
                              </Text>
                            </VStack>
                            
                            {isEditable && (
                              <HStack>
                                <IconButton
                                  aria-label="Edit drop"
                                  icon={<FaEdit />}
                                  size="sm"
                                  variant="ghost"
                                  onClick={() => {
                                    setSelectedDrop(drop);
                                    onDropModalOpen();
                                  }}
                                />
                                <IconButton
                                  aria-label="Remove drop"
                                  icon={<FaTrash />}
                                  size="sm"
                                  variant="ghost"
                                  colorScheme="red"
                                  onClick={() => onDropRemove(drop.id)}
                                />
                              </HStack>
                            )}
                          </HStack>
                          
                          {/* Time Window */}
                          {drop.timeWindow && (
                            <HStack spacing={2} fontSize="xs">
                              <Icon as={FaClock} color="gray.500" />
                              <Text color="gray.600">
                                {drop.timeWindow.start} - {drop.timeWindow.end}
                              </Text>
                            </HStack>
                          )}
                          
                          {/* Time Window Editor */}
                          {isEditable && (
                            <Collapse in={selectedDrop?.id === drop.id}>
                              <SimpleGrid columns={2} spacing={2} mt={2}>
                                <FormControl size="sm">
                                  <FormLabel fontSize="xs">Start Time</FormLabel>
                                  <Input
                                    type="time"
                                    size="sm"
                                    value={drop.timeWindow?.start || ''}
                                    onChange={(e) => handleDropTimeUpdate(drop.id, {
                                      start: e.target.value,
                                      end: drop.timeWindow?.end || '',
                                    })}
                                  />
                                </FormControl>
                                <FormControl size="sm">
                                  <FormLabel fontSize="xs">End Time</FormLabel>
                                  <Input
                                    type="time"
                                    size="sm"
                                    value={drop.timeWindow?.end || ''}
                                    onChange={(e) => handleDropTimeUpdate(drop.id, {
                                      start: drop.timeWindow?.start || '',
                                      end: e.target.value,
                                    })}
                                  />
                                </FormControl>
                              </SimpleGrid>
                            </Collapse>
                          )}
                        </VStack>
                      </CardBody>
                    </Card>
                  ))}
                </VStack>
              </VStack>
            </CardBody>
          </Card>

          {/* Action Buttons */}
          {isEditable && (
            <HStack spacing={3} justify="end">
              <Button
                colorScheme="blue"
                leftIcon={<FaCheckCircle />}
                onClick={handleSaveSchedule}
                isDisabled={!schedule.startDate || !schedule.startTime || timeConflicts.length > 0}
              >
                Save Schedule
              </Button>
            </HStack>
          )}
        </VStack>
      </CardBody>

      {/* Route Optimization Modal */}
      <Modal isOpen={isOptimizeModalOpen} onClose={onOptimizeModalClose}>
        <ModalOverlay />
        <ModalContent>
          <ModalHeader>Optimize Route</ModalHeader>
          <ModalCloseButton />
          <ModalBody>
            <VStack spacing={4} align="stretch">
              <Alert status="info">
                <AlertIcon />
                <Box>
                  <AlertTitle fontSize="sm">Route Optimization</AlertTitle>
                  <AlertDescription fontSize="xs">
                    This will automatically arrange drops for minimal travel time and respect priority levels.
                  </AlertDescription>
                </Box>
              </Alert>
              
              <Text fontSize="sm" color="gray.600">
                The optimization will:
              </Text>
              <VStack align="start" spacing={1} pl={4}>
                <Text fontSize="xs">• Prioritize high-priority drops</Text>
                <Text fontSize="xs">• Minimize total travel distance</Text>
                <Text fontSize="xs">• Assign optimal time windows</Text>
                <Text fontSize="xs">• Resolve scheduling conflicts</Text>
              </VStack>
            </VStack>
          </ModalBody>
          <ModalFooter>
            <Button variant="ghost" mr={3} onClick={onOptimizeModalClose}>
              Cancel
            </Button>
            <Button
              colorScheme="blue"
              onClick={handleOptimizeRoute}
              isLoading={isOptimizing}
              loadingText="Optimizing..."
            >
              Optimize Route
            </Button>
          </ModalFooter>
        </ModalContent>
      </Modal>

      {/* Drop Edit Modal */}
      <Modal isOpen={isDropModalOpen} onClose={onDropModalClose}>
        <ModalOverlay />
        <ModalContent>
          <ModalHeader>Edit Drop Details</ModalHeader>
          <ModalCloseButton />
          <ModalBody>
            {selectedDrop && (
              <VStack spacing={4} align="stretch">
                <FormControl>
                  <FormLabel fontSize="sm">Priority</FormLabel>
                  <Select
                    value={selectedDrop.priority}
                    onChange={(e) => onDropUpdate(selectedDrop.id, { priority: e.target.value as 'low' | 'medium' | 'high' })}
                  >
                    <option value="low">Low Priority</option>
                    <option value="medium">Medium Priority</option>
                    <option value="high">High Priority</option>
                  </Select>
                </FormControl>
                
                <FormControl>
                  <FormLabel fontSize="sm">Estimated Duration (minutes)</FormLabel>
                  <NumberInput
                    value={selectedDrop.estimatedDuration}
                    onChange={(_, value) => onDropUpdate(selectedDrop.id, { estimatedDuration: value })}
                    min={15}
                    max={240}
                  >
                    <NumberInputField />
                    <NumberInputStepper>
                      <NumberIncrementStepper />
                      <NumberDecrementStepper />
                    </NumberInputStepper>
                  </NumberInput>
                </FormControl>
              </VStack>
            )}
          </ModalBody>
          <ModalFooter>
            <Button variant="ghost" mr={3} onClick={onDropModalClose}>
              Close
            </Button>
            <Button colorScheme="blue" onClick={onDropModalClose}>
              Save Changes
            </Button>
          </ModalFooter>
        </ModalContent>
      </Modal>
    </Card>
  );
};

export default MultipleDropsDateTimeCard;

/**
 * Quick Booking Widget
 * 
 * Reduces booking funnel to 2 clicks maximum
 * Always visible on every page for maximum conversion
 */

'use client';

import { useState } from 'react';
import {
  Box,
  Button,
  VStack,
  HStack,
  Input,
  Select,
  Text,
  useToast,
  Modal,
  ModalOverlay,
  ModalContent,
  ModalHeader,
  ModalBody,
  ModalCloseButton,
  useDisclosure,
  Icon,
  InputGroup,
  InputLeftElement,
} from '@chakra-ui/react';
import { FaMapMarkerAlt, FaPhone, FaCalendar, FaBox } from 'react-icons/fa';
import { useRouter } from 'next/navigation';

interface QuickBookingData {
  pickupPostcode: string;
  deliveryPostcode: string;
  serviceType: string;
  urgency: string;
  phone?: string;
}

export default function QuickBookingWidget({ variant = 'floating' }: { variant?: 'floating' | 'inline' }) {
  const { isOpen, onOpen, onClose } = useDisclosure();
  const [step, setStep] = useState(1);
  const [loading, setLoading] = useState(false);
  const [formData, setFormData] = useState<QuickBookingData>({
    pickupPostcode: '',
    deliveryPostcode: '',
    serviceType: 'standard',
    urgency: 'same-day',
  });
  const toast = useToast();
  const router = useRouter();

  const handleQuickQuote = async () => {
    if (!formData.pickupPostcode || !formData.deliveryPostcode) {
      toast({
        title: 'Missing Information',
        description: 'Please enter pickup and delivery postcodes',
        status: 'warning',
        duration: 3000,
      });
      return;
    }

    setLoading(true);

    try {
      // Calculate instant quote
      const response = await fetch('/api/booking/quick-quote', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData),
      });

      if (response.ok) {
        const data = await response.json();
        
        // Store quote in session
        sessionStorage.setItem('quickQuote', JSON.stringify(data));
        
        // Redirect to booking page with pre-filled data
        router.push(`/booking?quote=${data.quoteId}`);
      } else {
        throw new Error('Failed to get quote');
      }
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to get quote. Please try again.',
        status: 'error',
        duration: 5000,
      });
    } finally {
      setLoading(false);
    }
  };

  const FloatingButton = () => (
    <Box
      position="fixed"
      bottom={{ base: '20px', md: '40px' }}
      right={{ base: '20px', md: '40px' }}
      zIndex={1000}
    >
      <Button
        size="lg"
        colorScheme="green"
        onClick={onOpen}
        boxShadow="0 8px 24px rgba(0, 209, 143, 0.4)"
        _hover={{
          transform: 'scale(1.05)',
          boxShadow: '0 12px 32px rgba(0, 209, 143, 0.6)',
        }}
        transition="all 0.3s"
        borderRadius="full"
        px={8}
        py={7}
        fontSize="lg"
        fontWeight="bold"
      >
        📦 Book Now
      </Button>
    </Box>
  );

  const QuickBookingForm = () => (
    <VStack spacing={4} align="stretch">
      {/* Step 1: Postcodes */}
      {step === 1 && (
        <>
          <Text fontSize="lg" fontWeight="bold" textAlign="center">
            Get Instant Quote in 30 Seconds
          </Text>
          
          <InputGroup>
            <InputLeftElement pointerEvents="none">
              <Icon as={FaMapMarkerAlt} color="green.500" />
            </InputLeftElement>
            <Input
              placeholder="Pickup Postcode (e.g., G1 1AA)"
              value={formData.pickupPostcode}
              onChange={(e) =>
                setFormData({ ...formData, pickupPostcode: e.target.value.toUpperCase() })
              }
              size="lg"
              autoFocus
            />
          </InputGroup>

          <InputGroup>
            <InputLeftElement pointerEvents="none">
              <Icon as={FaMapMarkerAlt} color="blue.500" />
            </InputLeftElement>
            <Input
              placeholder="Delivery Postcode (e.g., EH1 1AA)"
              value={formData.deliveryPostcode}
              onChange={(e) =>
                setFormData({ ...formData, deliveryPostcode: e.target.value.toUpperCase() })
              }
              size="lg"
            />
          </InputGroup>

          <Select
            value={formData.serviceType}
            onChange={(e) => setFormData({ ...formData, serviceType: e.target.value })}
            size="lg"
            icon={<FaBox />}
          >
            <option value="parcel">Parcel/Small Items</option>
            <option value="furniture">Furniture</option>
            <option value="standard">Standard Delivery</option>
            <option value="multi-drop">Multiple Stops</option>
          </Select>

          <Select
            value={formData.urgency}
            onChange={(e) => setFormData({ ...formData, urgency: e.target.value })}
            size="lg"
            icon={<FaCalendar />}
          >
            <option value="same-day">Same Day (2-4 hours)</option>
            <option value="express">Express (1-2 hours)</option>
            <option value="next-day">Next Day</option>
            <option value="scheduled">Schedule for Later</option>
          </Select>

          <Button
            colorScheme="green"
            size="lg"
            onClick={handleQuickQuote}
            isLoading={loading}
            loadingText="Getting Quote..."
            w="full"
            py={7}
            fontSize="lg"
          >
            Get Instant Quote →
          </Button>

          <Text fontSize="xs" color="gray.500" textAlign="center">
            No payment required • Free quote • Book in 2 clicks
          </Text>
        </>
      )}
    </VStack>
  );

  if (variant === 'floating') {
    return (
      <>
        <FloatingButton />
        
        <Modal isOpen={isOpen} onClose={onClose} size="md" isCentered>
          <ModalOverlay backdropFilter="blur(4px)" />
          <ModalContent>
            <ModalHeader>Quick Booking</ModalHeader>
            <ModalCloseButton />
            <ModalBody pb={6}>
              <QuickBookingForm />
            </ModalBody>
          </ModalContent>
        </Modal>
      </>
    );
  }

  // Inline variant for homepage
  return (
    <Box
      bg="white"
      p={8}
      borderRadius="xl"
      boxShadow="2xl"
      maxW="500px"
      w="full"
    >
      <QuickBookingForm />
    </Box>
  );
}

'use client';

import React, { forwardRef, useMemo } from 'react';
import {
  Button as ChakraButton,
  ButtonProps as ChakraButtonProps,
  useColorModeValue,
} from '@chakra-ui/react';

// Enhanced type definitions for better type safety
type ButtonVariant = Exclude<ChakraButtonProps['variant'], undefined>;
type ButtonSize = Exclude<ChakraButtonProps['size'], undefined>;

interface ButtonProps extends Omit<ChakraButtonProps, 'variant'> {
  variant?: ButtonVariant;
  size?: ButtonSize;
  colorScheme?: string;
  isLoading?: boolean;
  loadingText?: string;
  leftIcon?: React.ReactElement;
  rightIcon?: React.ReactElement;
  fullWidth?: boolean;
  animate?: boolean;
  pulse?: boolean;
}

// Pre-defined style configurations for better performance
const VARIANT_STYLES = {
  outline: {
    _hover: {
      transform: 'translateY(-1px)',
      boxShadow: 'md',
      borderColor: 'currentColor',
    },
    _active: {
      transform: 'translateY(0)',
    },
  },
  solid: {
    _hover: {
      transform: 'translateY(-1px)',
      boxShadow: 'md',
    },
    _active: {
      transform: 'translateY(0)',
    },
  },
  ghost: {
    _hover: {
      transform: 'translateY(-1px)',
      bg: 'rgba(0, 194, 255, 0.1)',
    },
    _active: {
      transform: 'translateY(0)',
    },
  },
  link: {
    _hover: {
      textDecoration: 'underline',
    },
  },
} as const;

const Button = forwardRef<HTMLButtonElement, ButtonProps>(({
  variant = 'solid',
  size = 'md',
  colorScheme = 'blue',
  isLoading = false,
  loadingText,
  leftIcon,
  rightIcon,
  fullWidth = false,
  animate = true,
  pulse = false,
  _hover,
  _focus,
  ...props
}, ref) => {
  // Color mode values - must be called at top level
  const bgColor = useColorModeValue('white', 'gray.800');
  const borderColor = useColorModeValue('gray.200', 'gray.600');

  // Memoize computed styles for better performance
  const computedStyles = useMemo(() => {
    const baseStyles = VARIANT_STYLES[variant as keyof typeof VARIANT_STYLES] || {};

    // Enhanced hover styles with animation control
    const enhancedHover = animate ? {
      ...(baseStyles as any)._hover,
      ..._hover,
    } : _hover;

    // Enhanced focus styles for accessibility
    const enhancedFocus = {
      boxShadow: '0 0 0 3px rgba(0, 123, 191, 0.6)',
      ..._focus,
    };

    // Outline variant specific styles
    const outlineStyles = variant === 'outline' ? {
      bg: bgColor,
      borderColor: borderColor,
    } : {};

    return {
      enhancedHover,
      enhancedFocus,
      outlineStyles,
    };
  }, [variant, animate, _hover, _focus, bgColor, borderColor]);

  return (
    <ChakraButton
      ref={ref}
      variant={variant}
      size={size}
      colorScheme={colorScheme}
      isLoading={isLoading}
      loadingText={loadingText}
      leftIcon={leftIcon}
      rightIcon={rightIcon}
      w={fullWidth ? 'full' : undefined}
      _hover={computedStyles.enhancedHover}
      _focus={computedStyles.enhancedFocus}
      animation={pulse ? 'pulse 2s infinite' : undefined}
      transition="all 0.2s ease"
      {...computedStyles.outlineStyles}
      {...props}
    />
  );
});

Button.displayName = 'Button';

export default Button;

/**
 * Header button component for Speedy Van
 * Enhanced with improved type safety, performance, and accessibility
 */

import { Button, ButtonProps } from '@chakra-ui/react';
import { ReactNode, forwardRef, useMemo } from 'react';

// Define enhanced custom variant types for better type safety
type CustomVariant = 'glass' | 'neon' | 'primary' | 'gradient' | 'glow';
type HeaderButtonVariant = Exclude<ButtonProps['variant'], undefined> | CustomVariant;

interface HeaderButtonProps extends Omit<ButtonProps, 'variant'> {
  children: ReactNode;
  variant?: HeaderButtonVariant;
  size?: 'sm' | 'md' | 'lg';
  isLoading?: boolean;
  loadingText?: string;
  animate?: boolean;
  fullWidth?: boolean;
  pulse?: boolean;
  glow?: boolean;
  shimmer?: boolean;
}

// Enhanced custom variant styles with advanced animations and effects
const CUSTOM_VARIANT_STYLES = {
  glass: {
    bg: 'rgba(255, 255, 255, 0.1)',
    backdropFilter: 'blur(10px)',
    border: '1px solid rgba(255, 255, 255, 0.2)',
