    position: 'relative',
    overflow: 'hidden',
    _before: {
      content: '""',
      position: 'absolute',
      top: 0,
      left: '-100%',
      width: '100%',
      height: '100%',
      bg: 'linear-gradient(90deg, transparent, rgba(255,255,255,0.2), transparent)',
