    },
    _hover: {
      bg: 'linear-gradient(135deg, #002D6B, #001F3F)',
      transform: 'translateY(-2px) scale(1.02)',
      boxShadow: '0 8px 25px rgba(0, 180, 255, 0.6), 0 4px 12px rgba(0, 240, 255, 0.2)',
      _before: {
        left: '100%',
      },
    },
    _focus: {
      boxShadow: '0 0 0 3px rgba(0, 123, 191, 0.6), 0 8px 25px rgba(0, 194, 255, 0.4)',
    },
    _active: {
      transform: 'translateY(0) scale(1)',
      boxShadow: '0 2px 10px rgba(0, 194, 255, 0.2)',
    },
  },
  gradient: {
    bg: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
    color: 'white',
    position: 'relative',
    _hover: {
      bg: 'linear-gradient(135deg, #764ba2 0%, #667eea 100%)',
      transform: 'translateY(-2px) scale(1.02)',
      boxShadow: '0 8px 25px rgba(102, 126, 234, 0.4), 0 4px 12px rgba(118, 75, 162, 0.2)',
    },
    _focus: {
      boxShadow: '0 0 0 3px rgba(102, 126, 234, 0.6), 0 8px 25px rgba(102, 126, 234, 0.4)',
    },
    _active: {
      transform: 'translateY(0) scale(1)',
    },
  },
  glow: {
    bg: 'transparent',
    border: '2px solid',
    borderColor: 'purple.400',
    color: 'purple.400',
    boxShadow: '0 0 10px rgba(147, 51, 234, 0.3)',
    _hover: {
      bg: 'purple.400',
      color: 'white',
      transform: 'translateY(-2px)',
      boxShadow: '0 0 30px rgba(147, 51, 234, 0.6), 0 8px 20px rgba(147, 51, 234, 0.3)',
    },
    _focus: {
      boxShadow: '0 0 0 3px rgba(147, 51, 234, 0.6), 0 0 20px rgba(147, 51, 234, 0.6)',
    },
  },
} as const;

const HeaderButton = forwardRef<HTMLButtonElement, HeaderButtonProps>(({
  children,
  variant = 'solid',
  size = 'md',
  isLoading = false,
  loadingText,
  animate = true,
  fullWidth = false,
  pulse = false,
  glow: glowProp = false,
  shimmer = false,
  _hover,
  _focus,
  ...props
}, ref) => {
  // Memoize variant mapping and styles for better performance
  const { chakraVariant, customStyles } = useMemo(() => {
    // Map custom variants to Chakra variants
    const chakraVariant: ButtonProps['variant'] =
      variant === 'glass' || variant === 'neon' || variant === 'primary' || variant === 'gradient' || variant === 'glow'
        ? 'solid'
        : variant;

    // Get custom styles for special variants
    const customStyles = CUSTOM_VARIANT_STYLES[variant as CustomVariant] || {};

    return { chakraVariant, customStyles };
  }, [variant]);

  // Enhanced hover styles with advanced animation support
  const enhancedHoverStyles = useMemo(() => ({
    transform: animate ? 'translateY(-2px)' : undefined,
    boxShadow: animate ? 'md' : undefined,
    ..._hover,
  }), [animate, _hover]);

  // Enhanced focus styles for better accessibility
  const enhancedFocusStyles = useMemo(() => ({
    boxShadow: '0 0 0 3px rgba(0, 123, 191, 0.6)',
    ..._focus,
  }), [_focus]);

  // Advanced animation effects
  const animationStyles = useMemo(() => {
    const styles: any = {};

    if (pulse) {
      styles.animation = 'pulse 2s infinite';
    }

    if (glowProp && variant !== 'glow') {
      styles.boxShadow = '0 0 20px rgba(0, 194, 255, 0.5)';
    }

    if (shimmer && variant === 'primary') {
      styles._before = {
        content: '""',
        position: 'absolute',
        top: 0,
        left: '-100%',
        width: '100%',
        height: '100%',
        bg: 'linear-gradient(90deg, transparent, rgba(255,255,255,0.4), transparent)',
        transition: 'left 0.6s ease',
      };
      styles._hover = {
        ...styles._hover,
        _before: {
          left: '100%',
        },
      };
    }

    return styles;
  }, [pulse, glowProp, shimmer, variant]);

  return (
    <Button
      ref={ref}
      variant={chakraVariant}
      size={size}
      isLoading={isLoading}
      loadingText={loadingText}
      width={fullWidth ? '100%' : 'auto'}
      colorScheme="primary"
      fontWeight="medium"
      borderRadius="md"
      _focus={enhancedFocusStyles}
      transition="all 0.3s ease"
      {...animationStyles}
      {...customStyles}
      _hover={enhancedHoverStyles}
      {...props}
    >
      {children}
    </Button>
  );
});

HeaderButton.displayName = 'HeaderButton';

export default HeaderButton;

/**
 * Enterprise-Grade Image Component with Cloudinary CDN
 * 
 * CRITICAL FIX: Migrated from Next.js Image Optimization to Cloudinary
 * Next.js optimization on Render was causing 60-120s load times per image
 * 
 * Features:
 * - Cloudinary CDN for instant image delivery
 * - Automatic WebP/AVIF conversion
 * - Lazy loading with blur placeholder
 * - Responsive images (srcset)
 * - Core Web Vitals optimization
 * 
 * Based on best practices from:
 * - Amazon
 * - Netflix
 * - Airbnb
 */

'use client';

import Image, { ImageProps } from 'next/image';
import { useState } from 'react';
import { Box, Skeleton } from '@chakra-ui/react';
import { getCloudinaryUrl, localToCloudinary, CloudinaryTransformOptions } from '@/lib/cloudinary';

interface OptimizedImageProps extends Omit<ImageProps, 'onLoad'> {
  src: string;
  alt: string;
  width?: number;
  height?: number;
  priority?: boolean;
  quality?: number;
  sizes?: string;
  fill?: boolean;
  objectFit?: 'contain' | 'cover' | 'fill' | 'none' | 'scale-down';
  aspectRatio?: string;
  borderRadius?: string;
  showSkeleton?: boolean;
}

export default function OptimizedImage({
  src,
  alt,
  width,
  height,
  priority = false,
  quality = 85,
  sizes,
  fill = false,
  objectFit = 'cover',
  aspectRatio,
  borderRadius = '0',
  showSkeleton = true,
  ...props
}: OptimizedImageProps) {
  const [isLoading, setIsLoading] = useState(true);
  const [hasError, setHasError] = useState(false);

  // CRITICAL: Convert to Cloudinary URL for instant delivery
  // Checks if it's a local path and converts to Cloudinary
  const optimizedSrc = src.startsWith('/') 
    ? localToCloudinary(src, {
        width,
        height,
        quality: quality === 85 ? 'auto' : quality,
        format: 'auto',
        crop: fill ? 'fill' : 'scale',
      })
    : src; // External URLs pass through unchanged

  // Default sizes for responsive images
  const defaultSizes = sizes || '(max-width: 768px) 100vw, (max-width: 1200px) 50vw, 33vw';

  // Fallback image via Cloudinary
  const fallbackSrc = localToCloudinary('/images/placeholder.png', {
    width: width || 700,
    height: height || 475,
  });

  const handleLoad = () => {
    setIsLoading(false);
  };

  const handleError = () => {
    setHasError(true);
    setIsLoading(false);
  };

  return (
    <Box
      position="relative"
      width={fill ? '100%' : width}
      height={fill ? '100%' : height}
      aspectRatio={aspectRatio}
      borderRadius={borderRadius}
      overflow="hidden"
    >
      {/* Skeleton loader */}
      {isLoading && showSkeleton && (
        <Skeleton
          position="absolute"
          top={0}
          left={0}
          width="100%"
          height="100%"
          borderRadius={borderRadius}
        />
      )}

      {/* Cloudinary-Optimized Image */}
      <Image
        src={hasError ? fallbackSrc : optimizedSrc}
        alt={alt}
        width={fill ? undefined : width}
        height={fill ? undefined : height}
        fill={fill}
        quality={quality}
        sizes={defaultSizes}
        priority={priority}
        loading={priority ? 'eager' : 'lazy'}
        placeholder="blur"
        blurDataURL={`data:image/svg+xml;base64,${toBase64(shimmer(width || 700, height || 475))}`}
        onLoad={handleLoad}
        onError={handleError}
        style={{
          objectFit,
          transition: 'opacity 0.3s ease-in-out',
          opacity: isLoading ? 0 : 1,
        }}
        unoptimized // CRITICAL: Images already optimized by Cloudinary
        {...props}
      />
    </Box>
  );
}

/**
 * Generate shimmer effect for blur placeholder
 */
const shimmer = (w: number, h: number) => `
<svg width="${w}" height="${h}" version="1.1" xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink">
  <defs>
    <linearGradient id="g">
      <stop stop-color="#f6f7f8" offset="0%" />
      <stop stop-color="#edeef1" offset="20%" />
      <stop stop-color="#f6f7f8" offset="40%" />
      <stop stop-color="#f6f7f8" offset="100%" />
    </linearGradient>
  </defs>
  <rect width="${w}" height="${h}" fill="#f6f7f8" />
  <rect id="r" width="${w}" height="${h}" fill="url(#g)" />
  <animate xlink:href="#r" attributeName="x" from="-${w}" to="${w}" dur="1s" repeatCount="indefinite"  />
</svg>`;

/**
 * Convert SVG to base64
 */
const toBase64 = (str: string) =>
  typeof window === 'undefined' ? Buffer.from(str).toString('base64') : window.btoa(str);

/**
 * Preset configurations for common use cases
 */

// Hero image (above the fold)
export function HeroImage(props: Omit<OptimizedImageProps, 'priority' | 'quality'>) {
  return <OptimizedImage {...props} priority quality={90} />;
}

// Thumbnail image
export function ThumbnailImage(props: Omit<OptimizedImageProps, 'quality' | 'sizes'>) {
  return (
    <OptimizedImage
      {...props}
      quality={75}
      sizes="(max-width: 768px) 150px, 200px"
    />
  );
}

// Background image
export function BackgroundImage(props: Omit<OptimizedImageProps, 'fill' | 'objectFit'>) {
  return <OptimizedImage {...props} fill objectFit="cover" />;
}

// Avatar image
export function AvatarImage(props: Omit<OptimizedImageProps, 'borderRadius' | 'quality'>) {
  return <OptimizedImage {...props} borderRadius="full" quality={80} />;
}

/**
 * SEO Component
 * 
 * Reusable component for page-level SEO optimization
 * Includes meta tags, Open Graph, Twitter Cards, and Schema.org
 */

import Head from 'next/head';
import { SEO_DEFAULTS, SCHEMA_ORG } from '@/config/seo';

interface SEOProps {
  title?: string;
  description?: string;
  keywords?: string[];
  ogImage?: string;
  ogType?: 'website' | 'article' | 'product';
  canonical?: string;
  noindex?: boolean;
  nofollow?: boolean;
  schema?: any;
  breadcrumbs?: Array<{ name: string; url: string }>;
}

export default function SEO({
  title,
  description = SEO_DEFAULTS.defaultDescription,
  keywords = SEO_DEFAULTS.defaultKeywords,
  ogImage = SEO_DEFAULTS.ogImage,
  ogType = 'website',
  canonical,
  noindex = false,
  nofollow = false,
  schema,
  breadcrumbs,
}: SEOProps) {
  const fullTitle = title
    ? `${title} | ${SEO_DEFAULTS.siteName}`
    : SEO_DEFAULTS.defaultTitle;
  
  const fullOgImage = ogImage.startsWith('http')
    ? ogImage
    : `${SEO_DEFAULTS.siteUrl}${ogImage}`;
  
  const canonicalUrl = canonical || SEO_DEFAULTS.siteUrl;

  // Combine schemas
  const schemas = [
    SCHEMA_ORG.organization,
    SCHEMA_ORG.localBusiness,
    SCHEMA_ORG.service,
  ];

  if (breadcrumbs && breadcrumbs.length > 0) {
    schemas.push(SCHEMA_ORG.breadcrumb(breadcrumbs) as any);
  }

  if (schema) {
    schemas.push(schema);
  }

  return (
    <Head>
      {/* Basic Meta Tags */}
      <title>{fullTitle}</title>
      <meta name="description" content={description} />
      <meta name="keywords" content={keywords.join(', ')} />
      
      {/* Robots */}
      {(noindex || nofollow) && (
        <meta
          name="robots"
          content={`${noindex ? 'noindex' : 'index'},${nofollow ? 'nofollow' : 'follow'}`}
        />
      )}
      
      {/* Canonical URL */}
      <link rel="canonical" href={canonicalUrl} />
      
      {/* Open Graph */}
      <meta property="og:type" content={ogType} />
      <meta property="og:site_name" content={SEO_DEFAULTS.siteName} />
      <meta property="og:title" content={fullTitle} />
      <meta property="og:description" content={description} />
      <meta property="og:image" content={fullOgImage} />
      <meta property="og:image:width" content={String(SEO_DEFAULTS.ogImageWidth)} />
      <meta property="og:image:height" content={String(SEO_DEFAULTS.ogImageHeight)} />
      <meta property="og:url" content={canonicalUrl} />
      <meta property="og:locale" content="en_GB" />
      
      {/* Twitter Card */}
      <meta name="twitter:card" content={SEO_DEFAULTS.twitterCard} />
      <meta name="twitter:site" content={SEO_DEFAULTS.twitterSite} />
      <meta name="twitter:creator" content={SEO_DEFAULTS.twitterCreator} />
      <meta name="twitter:title" content={fullTitle} />
      <meta name="twitter:description" content={description} />
      <meta name="twitter:image" content={fullOgImage} />
      
      {/* Additional Meta */}
      <meta name="theme-color" content={SEO_DEFAULTS.themeColor} />
      <meta name="msapplication-TileColor" content={SEO_DEFAULTS.tileColor} />
      
      {/* Icons */}
      <link rel="icon" href={SEO_DEFAULTS.favicon} />
      
      {/* Viewport for mobile optimization */}
      <meta name="viewport" content="width=device-width, initial-scale=1, maximum-scale=5" />
      
      {/* Mobile Web App Capable */}
      <meta name="mobile-web-app-capable" content="yes" />
      
      {/* Schema.org JSON-LD */}
      {schemas.map((schemaItem, index) => (
        <script
          key={`schema-${index}`}
          type="application/ld+json"
          dangerouslySetInnerHTML={{ __html: JSON.stringify(schemaItem) }}
        />
      ))}
      
      {/* Preconnect to external domains for performance */}
      <link rel="preconnect" href="https://fonts.googleapis.com" />
      <link rel="preconnect" href="https://fonts.gstatic.com" crossOrigin="anonymous" />
      <link rel="dns-prefetch" href="https://www.google-analytics.com" />
      <link rel="dns-prefetch" href="https://www.googletagmanager.com" />
    </Head>
  );
}

