                  fontSize="2xl" 
                  color="white" 
                  fontWeight="bold"
                  textShadow="0 0 15px rgba(34, 197, 94, 0.9), 0 0 30px rgba(34, 197, 94, 0.6)"
                >
                  £{stats.earningsToday.toFixed(2)}
                </StatNumber>
                <StatHelpText fontSize="xs" color="white" opacity={0.7}>
                  Today's income
                </StatHelpText>
              </Stat>

              <Stat flex={1}>
                <StatLabel fontSize="sm" color="white" display="flex" alignItems="center" gap={2} opacity={0.8}>
                  <Icon as={FaStar} color="yellow.400" boxSize={4} />
                  Average Rating
                </StatLabel>
                <StatNumber 
                  fontSize="2xl" 
                  color="white" 
                  fontWeight="bold"
                  textShadow="0 0 15px rgba(251, 191, 36, 0.9), 0 0 30px rgba(251, 191, 36, 0.6)"
                >
                  {stats.averageRating.toFixed(1)}
                </StatNumber>
                <StatHelpText fontSize="xs" color="white" opacity={0.7}>
                  Customer satisfaction
                </StatHelpText>
              </Stat>
            </HStack>

            {/* Bottom Row - Summary Stats */}
            <HStack spacing={4} align="stretch">
              <Stat flex={1}>
                <StatLabel fontSize="sm" color="white" display="flex" alignItems="center" gap={2} opacity={0.8}>
                  <Icon as={FaChartLine} color="brand.400" boxSize={4} />
                  Total Completed
                </StatLabel>
                <StatNumber 
                  fontSize="xl" 
                  color="white" 
                  fontWeight="bold"
                  textShadow="0 0 12px rgba(59, 130, 246, 0.8), 0 0 24px rgba(59, 130, 246, 0.5)"
                >
                  {stats.totalCompleted}
                </StatNumber>
                <StatHelpText fontSize="xs" color="white" opacity={0.7}>
                  All time jobs
                </StatHelpText>
              </Stat>

              <Stat flex={1}>
                <StatLabel fontSize="sm" color="white" display="flex" alignItems="center" gap={2} opacity={0.8}>
                  <Icon as={FaClock} color="orange.400" boxSize={4} />
                  Available Jobs
                </StatLabel>
                <StatNumber 
                  fontSize="xl" 
                  color="white" 
                  fontWeight="bold"
                  textShadow="0 0 12px rgba(251, 191, 36, 0.8), 0 0 24px rgba(251, 191, 36, 0.5)"
                >
                  {stats.availableJobs}
                </StatNumber>
                <StatHelpText fontSize="xs" color="white" opacity={0.7}>
                  Ready to accept
                </StatHelpText>
              </Stat>
            </HStack>
          </VStack>

          {/* Total Earnings Badge - Matching Admin Style */}
          <Flex justify="center" pt={4}>
            <Badge
              bg="success.500"
              color="white"
              size="lg"
              borderRadius="full"
              px={6}
              py={3}
              fontSize="lg"
              fontWeight="bold"
              border={`2px solid`}
              borderColor="success.300"
              position="relative"
              overflow="hidden"
              boxShadow="0 0 20px rgba(34, 197, 94, 0.7), 0 0 40px rgba(34, 197, 94, 0.4)"
              animation="pulse-earnings 3s ease-in-out infinite"
              _hover={{
                boxShadow: "0 0 25px rgba(34, 197, 94, 0.9), 0 0 50px rgba(34, 197, 94, 0.5)",
                transform: "scale(1.05)",
                _before: {
                  content: '""',
                  position: "absolute",
                  top: "50%",
                  left: "50%",
                  width: "0",
                  height: "0",
                  borderRadius: "50%",
                  background: "rgba(255, 255, 255, 0.5)",
                  transform: "translate(-50%, -50%)",
                  animation: "ripple-earnings 0.6s ease-out"
                }
              }}
              sx={{
                "@keyframes pulse-earnings": {
                  "0%, 100%": { boxShadow: "0 0 15px rgba(34, 197, 94, 0.6), 0 0 30px rgba(34, 197, 94, 0.3)" },
                  "50%": { boxShadow: "0 0 25px rgba(34, 197, 94, 0.9), 0 0 50px rgba(34, 197, 94, 0.5)" }
                },
                "@keyframes ripple-earnings": {
                  "0%": { width: "0", height: "0", opacity: 1 },
                  "100%": { width: "200px", height: "200px", opacity: 0 }
                }
              }}
            >
              Total Earnings: £{stats.totalEarnings.toFixed(2)}
            </Badge>
          </Flex>
        </VStack>
      </CardBody>
    </Card>
  );
}

'use client';

import React from 'react';
import {
  Box,
  Flex,
  Text,
  Badge,
  HStack,
  VStack,
  Button,
  Icon,
  useColorModeValue,
  useColorMode,
  Avatar,
  IconButton,
  Tooltip,
  useBreakpointValue,
  useDisclosure,
  Circle,
  Container,
  Hide,
  Show,
} from '@chakra-ui/react';
import {
  FaBell,
  FaCog,
  FaSignOutAlt,
  FaTruck,
  FaMapMarkerAlt,
  FaBars,
  FaSync,
  FaHome,
  FaClipboardList,
  FaChartBar,
  FaMoon,
  FaSun,
} from 'react-icons/fa';
import { DriverDrawerMenu } from './DriverDrawerMenu';

interface Driver {
  id: string;
  name: string;
  status: string;
  location?: string;
  vehicle?: string;
}

interface EnhancedDriverHeaderProps {
  driver: Driver;
  onRefresh: () => void;
  onSettings: () => void;
  onLogout: () => void;
  isRefreshing?: boolean;
}

export function EnhancedDriverHeader({
  driver,
  onRefresh,
  onSettings,
  onLogout,
  isRefreshing = false,
}: EnhancedDriverHeaderProps) {
  const isMobile = useBreakpointValue({ base: true, md: false });
  const { isOpen: isDrawerOpen, onOpen: onDrawerOpen, onClose: onDrawerClose } = useDisclosure();
  const { colorMode, toggleColorMode } = useColorMode();
  
  // Use Admin dashboard styling - dark theme with neon accents
  const bgGradient = 'linear(to-r, bg.card, bg.surface)';
  const textColor = 'text.primary';
  const textSecondary = 'text.secondary';
  const accentColor = 'neon.400';

  const getStatusColor = (status: string) => {
    switch (status.toLowerCase()) {
      case 'active': return 'green';
      case 'busy': return 'orange';
      case 'offline': return 'red';
      default: return 'gray';
    }
  };

  return (
    <Box
      bgGradient={bgGradient}
      color={textColor}
      px={{ base: 4, md: 6 }}
      py={{ base: 4, md: 5 }}
      boxShadow="xl"
      position="relative"
      overflow="hidden"
    >
      {/* Background Pattern */}
      <Box
        position="absolute"
        top="0"
        right="0"
        w="200px"
        h="100%"
        bgGradient="linear(45deg, rgba(255,255,255,0.1), transparent)"
        transform="rotate(12deg)"
        transformOrigin="top"
      />
      
      <Container maxW="7xl" p={0}>
        <Flex justify="space-between" align="center" position="relative" zIndex="2">
          {/* Left: Brand + Logo */}
          <HStack spacing={4} flex="1">
            {/* Logo Circle with Icon */}
            <Circle
              size={{ base: "60px", md: "70px" }}
              bg={accentColor}
              color="blue.800"
              boxShadow="lg"
            >
              <Icon as={FaTruck} boxSize={{ base: "28px", md: "32px" }} />
            </Circle>
            
            {/* Brand Text */}
            <VStack align="start" spacing={0}>
              <Text
                fontSize={{ base: "2xl", md: "3xl" }}
                fontWeight="black"
                color={textColor}
                letterSpacing="tight"
                textShadow="0 2px 4px rgba(0,0,0,0.3)"
              >
                Speedy Van
              </Text>
              <Hide below="md">
                <Text
                  fontSize="sm"
                  color="blue.100"
                  fontWeight="semibold"
                  letterSpacing="wide"
                  textTransform="uppercase"
                >
                  Driver Portal
                </Text>
              </Hide>
            </VStack>
          </HStack>

          {/* Center: Driver Status (Desktop) */}
          <Hide below="lg">
            <VStack spacing={2} flex="1" maxW="300px">
              <HStack spacing={3}>
                <Avatar
                  size="md"
                  name={driver.name}
                  bg="white"
                  color="blue.800"
                />
                <VStack align="start" spacing={0}>
                  <Text fontSize="sm" fontWeight="bold" color="white">
                    {driver.name}
                  </Text>
                  <HStack spacing={2}>
                    <Badge
                      colorScheme={getStatusColor(driver.status)}
                      variant="solid"
                      fontSize="xs"
                      px={2}
                    >
                      {driver.status}
                    </Badge>
                    {driver.location && (
                      <HStack spacing={1}>
                        <Icon as={FaMapMarkerAlt} boxSize="10px" />
                        <Text fontSize="xs" color="blue.100">
                          {driver.location}
                        </Text>
                      </HStack>
                    )}
                  </HStack>
                </VStack>
              </HStack>
            </VStack>
          </Hide>

          {/* Right: Actions */}
          <HStack spacing={3} flex="1" justify="end">
            {/* Refresh Button */}
            <Tooltip label="Refresh Data" placement="bottom">
              <IconButton
                aria-label="Refresh"
                icon={<FaSync />}
                size="lg"
                colorScheme="whiteAlpha"
                variant="ghost"
                color="white"
                _hover={{ bg: 'whiteAlpha.200' }}
                _active={{ bg: 'whiteAlpha.300' }}
                isLoading={isRefreshing}
                onClick={onRefresh}
                borderRadius="xl"
                h="56px"
                w="56px"
              />
            </Tooltip>

            {/* Notifications */}
            <Tooltip label="Notifications" placement="bottom">
              <IconButton
                aria-label="Notifications"
                icon={<FaBell />}
                size="lg"
                colorScheme="whiteAlpha"
                variant="ghost"
                color="white"
                _hover={{ bg: 'whiteAlpha.200' }}
                _active={{ bg: 'whiteAlpha.300' }}
                borderRadius="xl"
                h="56px"
                w="56px"
                position="relative"
              />
            </Tooltip>

            {/* Dark Mode Toggle */}
            <Tooltip label={colorMode === 'dark' ? 'Light Mode' : 'Dark Mode'} placement="bottom">
              <IconButton
                aria-label="Toggle Dark Mode"
                icon={colorMode === 'dark' ? <FaSun /> : <FaMoon />}
                size="lg"
                colorScheme="whiteAlpha"
                variant="ghost"
                color={colorMode === 'dark' ? 'yellow.300' : 'blue.300'}
                _hover={{ bg: 'whiteAlpha.200', transform: 'rotate(20deg)' }}
                _active={{ bg: 'whiteAlpha.300', transform: 'rotate(0deg)' }}
                borderRadius="xl"
                h="56px"
                w="56px"
                onClick={toggleColorMode}
                transition="all 0.3s ease-in-out"
              />
            </Tooltip>

            {/* Settings Button - Desktop Only */}
            <Hide below="md">
              <Tooltip label="Settings" placement="bottom">
                <IconButton
                  aria-label="Settings"
                  icon={<FaCog />}
                  size="lg"
                  colorScheme="whiteAlpha"
                  variant="ghost"
                  color="white"
                  _hover={{ bg: 'whiteAlpha.200' }}
                  _active={{ bg: 'whiteAlpha.300' }}
                  borderRadius="xl"
                  h="56px"
                  w="56px"
                  onClick={onSettings}
                />
              </Tooltip>
            </Hide>

            {/* Sign Out Button - Desktop Only */}
            <Hide below="md">
              <Tooltip label="Sign Out" placement="bottom">
                <IconButton
                  aria-label="Sign Out"
                  icon={<FaSignOutAlt />}
                  size="lg"
                  colorScheme="red"
                  variant="ghost"
                  color="red.300"
                  _hover={{ bg: 'red.900', color: 'red.200' }}
                  _active={{ bg: 'red.800', color: 'red.100' }}
                  borderRadius="xl"
                  h="56px"
                  w="56px"
                  onClick={onLogout}
                />
              </Tooltip>
            </Hide>

            {/* Main Menu - Mobile & Access to all options */}
            <Tooltip label="Main Menu" placement="bottom">
              <IconButton
                aria-label="Main Menu"
                icon={<FaBars />}
                size="lg"
                colorScheme="whiteAlpha"
                variant="solid"
                bg="whiteAlpha.200"
                color="white"
                _hover={{ bg: 'whiteAlpha.300' }}
                _active={{ bg: 'whiteAlpha.400' }}
                borderRadius="xl"
                h="60px"
                w="60px"
                onClick={onDrawerOpen}
              />
            </Tooltip>
          </HStack>
        </Flex>

        {/* Mobile Driver Info */}
        <Show below="lg">
          <Box mt={4} pt={3} borderTop="1px solid" borderColor="whiteAlpha.300">
            <HStack spacing={3} justify="space-between">
              <HStack spacing={3}>
                <Avatar
                  size="md"
                  name={driver.name}
                  bg="white"
                  color="blue.800"
                />
                <VStack align="start" spacing={0}>
                  <Text fontSize="md" fontWeight="bold" color="white">
                    {driver.name}
                  </Text>
                  <HStack spacing={2}>
                    <Badge
                      colorScheme={getStatusColor(driver.status)}
                      variant="solid"
                      fontSize="sm"
                      px={3}
                      py={1}
                    >
                      {driver.status}
                    </Badge>
                  </HStack>
                </VStack>
              </HStack>
              
              {driver.location && (
                <HStack spacing={2} color="blue.100">
                  <Icon as={FaMapMarkerAlt} boxSize="14px" />
                  <Text fontSize="sm" noOfLines={1} maxW="120px">
                    {driver.location}
                  </Text>
                </HStack>
              )}
            </HStack>
          </Box>
        </Show>
      </Container>

      {/* Drawer Menu */}
      <DriverDrawerMenu
        isOpen={isDrawerOpen}
        onClose={onDrawerClose}
        driver={driver}
        onSettings={onSettings}
        onLogout={onLogout}
      />
    </Box>
  );
}

'use client';

import React from 'react';
import {
  Box as Card,
  Box as CardBody,
  VStack,
  HStack,
  Text,
  Button,
  Badge,
  Box,
  Divider,
  Icon,
  Flex,
  useColorModeValue,
  Link as ChakraLink,
  Tooltip,
  IconButton,
} from '@chakra-ui/react';
import {
  FaMapMarkerAlt,
  FaUser,
  FaPhone,
  FaClock,
  FaBox,
  FaTruck,
  FaMap,
  FaPhoneAlt,
  FaCheckCircle,
  FaExclamationTriangle,
} from 'react-icons/fa';

interface Job {
  id: string;
  reference: string;
  customer: string;
  customerPhone: string;
  date: string;
  time: string;
  from: string;
  to: string;
  distance: string;
  vehicleType: string;
  items: string;
  estimatedEarnings: number;
  status: string;
  priority?: string;
  duration?: string;
  crew?: string;
}

interface EnhancedJobCardProps {
  job: Job;
  onAccept?: (jobId: string) => void;
  onDecline?: (jobId: string) => void;
  onViewDetails?: (jobId: string) => void;
  isAccepting?: boolean;
  isDeclining?: boolean;
  variant?: 'assigned' | 'available';
}

export function EnhancedJobCard({
  job,
  onAccept,
  onDecline,
  onViewDetails,
  isAccepting = false,
  isDeclining = false,
  variant = 'available'
}: EnhancedJobCardProps) {
  // Use Admin dashboard styling - dark theme with neon accents
  const bgColor = 'bg.card';
  const borderColor = 'border.primary';
  const textColor = 'text.primary';
  const textSecondary = 'text.secondary';
  const primaryColor = variant === 'assigned' ? 'neon' : 'brand';
  const statusColor = variant === 'assigned' ? 'neon.500' : 'brand.500';

  const handleCallCustomer = () => {
    window.open(`tel:${job.customerPhone}`, '_self');
  };

  const handleOpenMap = (address: string) => {
    const encodedAddress = encodeURIComponent(address);
    window.open(`https://maps.google.com/maps?q=${encodedAddress}`, '_blank');
  };

  const getPriorityColor = (priority?: string) => {
    switch (priority?.toLowerCase()) {
      case 'urgent': return 'red';
      case 'high': return 'orange';
      case 'normal': return 'green';
      default: return 'gray';
    }
  };

  const getPriorityNeonColor = (priority?: string) => {
    switch (priority?.toLowerCase()) {
      case 'urgent': 
        return {
          shadow: "0 0 20px rgba(239, 68, 68, 0.5), 0 0 40px rgba(239, 68, 68, 0.3)",
          hoverShadow: "0 0 30px rgba(239, 68, 68, 0.7), 0 0 60px rgba(239, 68, 68, 0.4)",
          animation: "pulse-red-job 3s ease-in-out infinite"
        };
      case 'high': 
        return {
          shadow: "0 0 20px rgba(251, 191, 36, 0.5), 0 0 40px rgba(251, 191, 36, 0.3)",
          hoverShadow: "0 0 30px rgba(251, 191, 36, 0.7), 0 0 60px rgba(251, 191, 36, 0.4)",
          animation: "pulse-amber-job 3s ease-in-out infinite"
        };
      case 'normal': 
        return {
          shadow: "0 0 20px rgba(34, 197, 94, 0.5), 0 0 40px rgba(34, 197, 94, 0.3)",
          hoverShadow: "0 0 30px rgba(34, 197, 94, 0.7), 0 0 60px rgba(34, 197, 94, 0.4)",
          animation: "pulse-green-job 3s ease-in-out infinite"
        };
      default: 
        return {
          shadow: "0 0 20px rgba(59, 130, 246, 0.5), 0 0 40px rgba(59, 130, 246, 0.3)",
          hoverShadow: "0 0 30px rgba(59, 130, 246, 0.7), 0 0 60px rgba(59, 130, 246, 0.4)",
          animation: "pulse-blue-job 3s ease-in-out infinite"
        };
    }
  };

  const neonEffect = getPriorityNeonColor(job.priority);

  return (
    <Card
      bg={bgColor}
      border="1px solid"
      borderColor={borderColor}
      borderRadius="xl"
      position="relative"
      overflow="hidden"
      cursor="pointer"
      transition="all 0.3s"
      animation={neonEffect.animation}
      _hover={{
        transform: 'translateY(-4px)',
        borderColor: 'border.neon',
        _before: {
          content: '""',
          position: "absolute",
          top: "0",
          left: "-100%",
          width: "100%",
          height: "100%",
          background: "linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.3), transparent)",
          animation: "wave-job 0.8s ease-out",
          zIndex: 1
        }
      }}
      sx={{
        "@keyframes pulse-red-job": {
          "0%, 100%": { boxShadow: "0 0 15px rgba(239, 68, 68, 0.4), 0 0 30px rgba(239, 68, 68, 0.2)" },
          "50%": { boxShadow: "0 0 30px rgba(239, 68, 68, 0.7), 0 0 60px rgba(239, 68, 68, 0.4)" }
        },
        "@keyframes pulse-amber-job": {
          "0%, 100%": { boxShadow: "0 0 15px rgba(251, 191, 36, 0.4), 0 0 30px rgba(251, 191, 36, 0.2)" },
          "50%": { boxShadow: "0 0 30px rgba(251, 191, 36, 0.7), 0 0 60px rgba(251, 191, 36, 0.4)" }
        },
        "@keyframes pulse-green-job": {
          "0%, 100%": { boxShadow: "0 0 15px rgba(34, 197, 94, 0.4), 0 0 30px rgba(34, 197, 94, 0.2)" },
          "50%": { boxShadow: "0 0 30px rgba(34, 197, 94, 0.7), 0 0 60px rgba(34, 197, 94, 0.4)" }
        },
        "@keyframes pulse-blue-job": {
          "0%, 100%": { boxShadow: "0 0 15px rgba(59, 130, 246, 0.4), 0 0 30px rgba(59, 130, 246, 0.2)" },
          "50%": { boxShadow: "0 0 30px rgba(59, 130, 246, 0.7), 0 0 60px rgba(59, 130, 246, 0.4)" }
        },
        "@keyframes wave-job": {
          "0%": { left: "-100%" },
          "100%": { left: "100%" }
        }
      }}
      _after={{
        content: '""',
        position: 'absolute',
        inset: 0,
        borderRadius: 'xl',
        padding: '1px',
        background: 'linear-gradient(135deg, rgba(0,194,255,0.2), rgba(0,209,143,0.2))',
        WebkitMask: 'linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0)',
        WebkitMaskComposite: 'xor',
        maskComposite: 'exclude',
        pointerEvents: 'none',
      }}
    >
      <CardBody p={{ base: 5, md: 6 }} px={{ base: 6, md: 7 }} position="relative" zIndex={2}>
        <VStack spacing={{ base: 6, md: 7 }} align="stretch">
          {/* Header with Job ID and Price */}
          <Flex justify="space-between" align="center">
            <VStack align="start" spacing={1}>
              <Text
                fontWeight="bold"
                fontSize="lg"
                color="white"
                fontFamily="mono"
                textShadow="0 0 10px rgba(255, 255, 255, 0.6)"
              >
                {job.reference}
              </Text>
              {job.priority && (
                <Badge
                  colorScheme={getPriorityColor(job.priority)}
                  size="sm"
                  borderRadius="full"
                  px={3}
                  py={1}
                >
                  {job.priority.toUpperCase()}
                </Badge>
              )}
            </VStack>
            <VStack align="end" spacing={1}>
              <Text
                fontWeight="800"
                fontSize="2xl"
                color="white"
                textShadow="0 0 15px rgba(34, 197, 94, 0.8), 0 0 30px rgba(34, 197, 94, 0.5)"
              >
                £{isNaN(Number(job.estimatedEarnings)) ? '0.00' : Number(job.estimatedEarnings).toFixed(2)}
              </Text>
              <Badge
                colorScheme={primaryColor}
                size="lg"
                borderRadius="full"
                px={3}
                py={1}
                boxShadow="0 0 10px rgba(59, 130, 246, 0.6)"
              >
                {job.status.toUpperCase()}
              </Badge>
            </VStack>
          </Flex>

          <Divider borderColor="border.primary" borderWidth="1px" />

          {/* Customer Information */}
          <Box>
            <Text 
              fontWeight="semibold" 
              color="white" 
              mb={3} 
              fontSize="md"
              textShadow="0 0 8px rgba(255, 255, 255, 0.5)"
            >
              Customer Details
            </Text>
            <VStack spacing={4} align="stretch">
              <HStack spacing={4} align="center">
                <Icon as={FaUser} color={statusColor} boxSize={4} />
                <Text
                  fontWeight="medium"
                  color="white"
                  fontSize="16px"
                  lineHeight="24px"
                  flex="1"
                  textShadow="0 0 6px rgba(255, 255, 255, 0.4)"
                >
                  {job.customer || 'No customer info'}
                </Text>
              </HStack>
              <HStack spacing={4} align="center">
                <Icon as={FaPhone} color={statusColor} boxSize={4} />
                <Text
                  color="white"
                  fontSize="16px"
                  lineHeight="24px"
                  flex="1"
                  textShadow="0 0 6px rgba(255, 255, 255, 0.4)"
                >
                  {job.customerPhone || 'No contact info'}
                </Text>
                {job.customerPhone ? (
                  <Tooltip label="Call Customer">
                    <IconButton
                      aria-label="Call customer"
                      icon={<FaPhoneAlt />}
                      size="sm"
                      colorScheme="blue"
                      variant="ghost"
                      onClick={handleCallCustomer}
                    />
                  </Tooltip>
                ) : null}
              </HStack>
            </VStack>
          </Box>

          <Divider borderColor="border.primary" borderWidth="1px" />

          {/* Pickup Location */}
          <Box>
            <HStack spacing={3} mb={4} align="center">
              <Box
                p={2}
                borderRadius="lg"
                bg="bg.surface"
                border="1px solid"
                borderColor="border.secondary"
              >
                <Icon as={FaMapMarkerAlt} color="success.500" boxSize={5} />
              </Box>
              <Text 
                fontWeight="bold" 
                color="white" 
                fontSize="lg"
                textShadow="0 0 10px rgba(34, 197, 94, 0.8), 0 0 20px rgba(34, 197, 94, 0.5)"
              >
                Pickup Location
              </Text>
            </HStack>
            <VStack align="stretch" spacing={3} pl={2}>
                <Text
                  fontWeight="semibold"
                  color="white"
                  fontSize="17px"
                  lineHeight="26px"
                  textShadow="0 0 8px rgba(255, 255, 255, 0.4)"
                >
                  {job.from}
                </Text>
              <HStack spacing={4} align="center">
                <Badge
                  colorScheme="green"
                  size="md"
                  px={3}
                  py={1}
                  borderRadius="lg"
                  fontWeight="medium"
                >
                  📅 {job.date} at {job.time}
                </Badge>
                <Tooltip label="Open in Maps" hasArrow>
                  <IconButton
                    aria-label="Open pickup location in maps"
                    icon={<FaMap />}
                    size="sm"
                    colorScheme="green"
                    variant="outline"
                    borderRadius="lg"
                    onClick={() => handleOpenMap(job.from)}
                    _hover={{
                      transform: 'scale(1.05)',
                      boxShadow: 'md'
                    }}
                  />
                </Tooltip>
              </HStack>
            </VStack>
          </Box>

          <Divider borderColor="border.primary" borderWidth="1px" />

