                      content: '""',
                      position: "absolute",
                      top: "50%",
                      left: "50%",
                      width: "0",
                      height: "0",
                      borderRadius: "50%",
                      background: "rgba(255, 255, 255, 0.6)",
                      transform: "translate(-50%, -50%)",
                      animation: "ripple-accept 0.6s ease-out"
