                  }}
                  sx={{
                    "@keyframes ripple-accept": {
                      "0%": { width: "0", height: "0", opacity: 1 },
                      "100%": { width: "300px", height: "300px", opacity: 0 }
                    }
                  }}
                >
                  ✅ Accept
                </Button>
                {onDecline && (
                  <Button
                    colorScheme="red"
                    size="lg"
                    flex={1}
                    leftIcon={<FaExclamationTriangle />}
                    onClick={() => onDecline(job.id)}
                    isLoading={isDeclining}
                    loadingText="Declining..."
                    borderRadius="xl"
                    fontWeight="bold"
                    fontSize="md"
                    py={6}
                    position="relative"
                    overflow="hidden"
                    boxShadow="0 0 15px rgba(239, 68, 68, 0.5), 0 0 30px rgba(239, 68, 68, 0.3)"
                    _hover={{
                      transform: 'translateY(-2px)',
                      boxShadow: "0 0 20px rgba(239, 68, 68, 0.7), 0 0 40px rgba(239, 68, 68, 0.4)",
                      _before: {
                        content: '""',
                        position: "absolute",
                        top: "50%",
                        left: "50%",
                        width: "0",
                        height: "0",
                        borderRadius: "50%",
                        background: "rgba(255, 255, 255, 0.6)",
                        transform: "translate(-50%, -50%)",
                        animation: "ripple-decline 0.6s ease-out"
                      }
                    }}
                    sx={{
                      "@keyframes ripple-decline": {
                        "0%": { width: "0", height: "0", opacity: 1 },
                        "100%": { width: "300px", height: "300px", opacity: 0 }
                      }
                    }}
                  >
                    ❌ Decline
                  </Button>
                )}
              </HStack>
            )}
            {onViewDetails && (
              <Button
                variant="outline"
                size="md"
                width="full"
                onClick={() => onViewDetails(job.id)}
                borderRadius="xl"
                borderColor="neon.500"
                color="white"
                position="relative"
                overflow="hidden"
                boxShadow="0 0 10px rgba(59, 130, 246, 0.4)"
                _hover={{
                  bg: "rgba(59, 130, 246, 0.1)",
                  borderColor: "neon.400",
                  boxShadow: "0 0 15px rgba(59, 130, 246, 0.6), 0 0 30px rgba(59, 130, 246, 0.3)",
                  _before: {
                    content: '""',
                    position: "absolute",
                    top: "50%",
                    left: "50%",
                    width: "0",
                    height: "0",
                    borderRadius: "50%",
                    background: "rgba(255, 255, 255, 0.4)",
                    transform: "translate(-50%, -50%)",
                    animation: "ripple-view 0.6s ease-out"
                  }
                }}
                sx={{
                  "@keyframes ripple-view": {
                    "0%": { width: "0", height: "0", opacity: 1 },
                    "100%": { width: "300px", height: "300px", opacity: 0 }
                  }
                }}
              >
                View Full Details
              </Button>
            )}
          </VStack>
        </VStack>
      </CardBody>
    </Card>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import {
  Modal,
  ModalOverlay,
  ModalContent,
  ModalHeader,
  ModalFooter,
  ModalBody,
  ModalCloseButton,
  VStack,
  HStack,
  Text,
  Button,
  Badge,
  Divider,
  Box,
  Grid,
  GridItem,
  Icon,
  useToast,
  Spinner,
  Alert,
  AlertIcon,
  List,
  ListItem,
  ListIcon,
} from '@chakra-ui/react';
import {
  FaMapMarkerAlt,
  FaUser,
  FaPhone,
  FaEnvelope,
  FaClock,
  FaBox,
  FaMoneyBillWave,
  FaTruck,
  FaBuilding,
  FaCheckCircle,
  FaExclamationTriangle,
} from 'react-icons/fa';

interface JobDetailsModalProps {
  isOpen: boolean;
  onClose: () => void;
  jobId: string;
  onJobAccepted?: () => void;
}

export function JobDetailsModal({
  isOpen,
  onClose,
  jobId,
  onJobAccepted
}: JobDetailsModalProps) {
  const [jobDetails, setJobDetails] = useState<any>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isAccepting, setIsAccepting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const toast = useToast();

  // Load job details when modal opens
  useEffect(() => {
    if (isOpen && jobId) {
      loadJobDetails();
    }
  }, [isOpen, jobId]);

  const loadJobDetails = async () => {
    try {
      setIsLoading(true);
      setError(null);

      const response = await fetch(`/api/driver/jobs/${jobId}/details`);
      
      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || 'Failed to load job details');
      }

      const data = await response.json();
      setJobDetails(data.data);

    } catch (error) {
      console.error('❌ Error loading job details:', error);
      setError(error instanceof Error ? error.message : 'Failed to load job details');
    } finally {
      setIsLoading(false);
    }
  };

  const handleAcceptJob = async () => {
    try {
      setIsAccepting(true);
      
      const response = await fetch(`/api/driver/jobs/${jobId}/accept`, {
        method: 'POST',
      });
      
      const data = await response.json();
      
      if (data.success) {
        toast({
          title: 'Job Accepted!',
          description: 'You have successfully accepted this job.',
          status: 'success',
          duration: 5000,
          isClosable: true,
        });
        
        onJobAccepted?.();
        onClose();
      } else {
        throw new Error(data.error || 'Failed to accept job');
      }
    } catch (error) {
      console.error('❌ Error accepting job:', error);
      toast({
        title: 'Failed to Accept Job',
        description: error instanceof Error ? error.message : 'Please try again.',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setIsAccepting(false);
    }
  };

  const getPropertyTypeIcon = (type: string) => {
    switch (type?.toLowerCase()) {
      case 'flat':
      case 'apartment':
        return FaBuilding;
      case 'house':
      case 'detached':
      case 'semi_detached':
      case 'terrace':
        return FaBuilding;
      default:
        return FaBuilding;
    }
  };

  return (
    <Modal isOpen={isOpen} onClose={onClose} size="xl">
      <ModalOverlay bg="rgba(0,0,0,0.6)" backdropFilter="blur(4px)" />
      <ModalContent
        bg="bg.modal"
        border="1px solid"
        borderColor="border.primary"
        borderRadius="xl"
        _before={{
          content: '""',
          position: 'absolute',
          inset: 0,
          borderRadius: 'xl',
          padding: '1px',
          background: 'linear-gradient(135deg, rgba(0,194,255,0.3), rgba(0,209,143,0.3))',
          WebkitMask: 'linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0)',
          WebkitMaskComposite: 'xor',
          maskComposite: 'exclude',
          pointerEvents: 'none',
        }}
      >
        <ModalHeader color="text.primary">
          Job Details
          {jobDetails && (
            <Badge ml={3} bg="neon.500" color="dark.900">
              {jobDetails.reference}
            </Badge>
          )}
        </ModalHeader>
        <ModalCloseButton />
        
        <ModalBody>
          {isLoading && (
            <VStack spacing={4} py={8}>
              <Spinner size="lg" />
              <Text color="text.primary">Loading job details...</Text>
            </VStack>
          )}

          {error && (
            <Alert status="error" borderRadius="md">
              <AlertIcon />
              <Text>{error}</Text>
            </Alert>
          )}

          {jobDetails && (
            <VStack spacing={6} align="stretch">
              {/* Job Status */}
              <Box>
                <HStack mb={2}>
                  <Icon as={FaCheckCircle} color="green.500" />
                  <Text fontWeight="bold" fontSize="lg">
                    Job Status: {jobDetails.status}
                  </Text>
                </HStack>
                <Text fontSize="sm" color="gray.600">
                  Scheduled for: {new Date(jobDetails.scheduledAt).toLocaleString()}
                </Text>
              </Box>

              <Divider />

              {/* Customer Information */}
              <Box>
                <Text fontWeight="bold" mb={3} color="text.primary">
                  👤 Customer Information
                </Text>
                <Grid templateColumns="repeat(2, 1fr)" gap={4}>
                  <GridItem>
                    <HStack mb={2}>
                      <Icon as={FaUser} color="neon.500" />
                      <Text fontWeight="medium" color="text.secondary">Name</Text>
                    </HStack>
                    <Text fontSize="sm">{jobDetails.customerName}</Text>
                  </GridItem>
                  <GridItem>
                    <HStack mb={2}>
                      <Icon as={FaPhone} color="neon.500" />
                      <Text fontWeight="medium" color="text.secondary">Phone</Text>
                    </HStack>
                    <Text fontSize="sm">{jobDetails.customerPhone}</Text>
                  </GridItem>
                  <GridItem colSpan={2}>
                    <HStack mb={2}>
                      <Icon as={FaEnvelope} color="neon.500" />
                      <Text fontWeight="medium" color="text.secondary">Email</Text>
                    </HStack>
                    <Text fontSize="sm">{jobDetails.customerEmail}</Text>
                  </GridItem>
                </Grid>
              </Box>

              <Divider />

              {/* Addresses */}
              <Box>
                <Text fontWeight="bold" mb={3} color="text.primary">
                  📍 Addresses
                </Text>
                <Grid templateColumns="repeat(2, 1fr)" gap={4}>
                  <GridItem>
                    <HStack mb={2}>
                      <Icon as={FaMapMarkerAlt} color="success.500" />
                      <Text fontWeight="medium" color="text.secondary">Pickup</Text>
                    </HStack>
                    <Text fontSize="sm">
                      {jobDetails.pickupAddress?.label || 'Address not available'}
                    </Text>
                  </GridItem>
                  <GridItem>
                    <HStack mb={2}>
                      <Icon as={FaMapMarkerAlt} color="error.500" />
                      <Text fontWeight="medium" color="text.secondary">Dropoff</Text>
                    </HStack>
                    <Text fontSize="sm">
                      {jobDetails.dropoffAddress?.label || 'Address not available'}
                    </Text>
                  </GridItem>
                </Grid>
              </Box>

              <Divider />

              {/* Items */}
              {jobDetails.items && jobDetails.items.length > 0 && (
                <Box>
                  <Text fontWeight="bold" mb={3} color="text.primary">
                    📦 Items to Move ({jobDetails.items.length})
                  </Text>
                  <List spacing={2} pl={4}>
                    {jobDetails.items.map((item: any) => (
                      <ListItem key={item.id}>
                        <ListIcon as={FaBox} color="info.500" />
                        <Text as="span" fontSize="sm">
                          {item.name} (x{item.quantity})
                          {item.volumeM3 > 0 && ` - ${item.volumeM3}m³`}
                        </Text>
                      </ListItem>
                    ))}
                  </List>
                </Box>
              )}

              <Divider />

              {/* Property Details */}
              <Box>
                <Text fontWeight="bold" mb={3} color="text.primary">
                  🏠 Property Details
                </Text>
                <Grid templateColumns="repeat(2, 1fr)" gap={4}>
                  <GridItem>
                    <HStack mb={2}>
                      <Icon as={getPropertyTypeIcon(jobDetails.pickupProperty?.propertyType)} color="warning.500" />
                      <Text fontWeight="medium" color="text.secondary">Pickup Property</Text>
                    </HStack>
                    <Text fontSize="sm">
                      {jobDetails.pickupProperty?.propertyType || 'Not specified'}
                    </Text>
                  </GridItem>
                  <GridItem>
                    <HStack mb={2}>
                      <Icon as={getPropertyTypeIcon(jobDetails.dropoffProperty?.propertyType)} color="warning.500" />
                      <Text fontWeight="medium" color="text.secondary">Dropoff Property</Text>
                    </HStack>
                    <Text fontSize="sm">
                      {jobDetails.dropoffProperty?.propertyType || 'Not specified'}
                    </Text>
                  </GridItem>
                </Grid>
              </Box>

              {/* Assignment Status */}
              {jobDetails.assignment && (
                <Box>
                  <Text fontWeight="bold" mb={3} color="text.primary">
                    📋 Assignment Status
                  </Text>
                  <VStack align="stretch" spacing={2}>
                    <HStack justify="space-between">
                      <Text fontSize="sm" color="text.secondary">Status:</Text>
                      <Badge bg="neon.500" color="dark.900">{jobDetails.assignment.status}</Badge>
                    </HStack>
                    {jobDetails.assignment.claimedAt && (
                      <HStack justify="space-between">
                        <Text fontSize="sm" color="text.secondary">Claimed:</Text>
                        <Text fontSize="sm" color="text.primary">
                          {new Date(jobDetails.assignment.claimedAt).toLocaleString()}
                        </Text>
                      </HStack>
                    )}
                  </VStack>
                </Box>
              )}
            </VStack>
          )}
        </ModalBody>

        <ModalFooter>
          <HStack spacing={3}>
            <Button variant="outline" onClick={onClose}>
              Close
            </Button>
            {jobDetails && !jobDetails.assignment && (
              <Button
                colorScheme="brand"
                onClick={handleAcceptJob}
                isLoading={isAccepting}
                loadingText="Accepting..."
                leftIcon={<Icon as={FaCheckCircle} />}
              >
                Accept Job
              </Button>
            )}
            {jobDetails && jobDetails.assignment && (
              <>
                <Button
                  colorScheme="orange"
                  leftIcon={<Icon as={FaClock} />}
                  onClick={() => {
                    // Get next incomplete step
                    const nextStep = [
                      'navigate_to_pickup',
                      'arrived_at_pickup',
                      'loading_started',
                      'loading_completed',
                      'en_route_to_dropoff',
                      'arrived_at_dropoff',
                      'unloading_started',
                      'unloading_completed',
                      'job_completed',
                      'customer_signature',
                      'damage_notes',
                      'item_count_verification'
                    ].find(step => !jobDetails.assignment.events.some((event: any) => event.step === step));
                    
                    if (nextStep) {
                      // Update job step
                      fetch(`/api/driver/jobs/${jobId}/update-step`, {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({ step: nextStep })
                      }).then(response => {
                        if (response.ok) {
                          loadJobDetails();
                          toast({
                            title: 'Step Updated',
                            description: 'Job progress has been updated',
                            status: 'success',
                            duration: 3000
                          });
                        }
                      });
                    }
                  }}
                >
                  Next Step
                </Button>
              </>
            )}
          </HStack>
        </ModalFooter>
      </ModalContent>
    </Modal>
  );
}

import React, { useState, useEffect, useCallback } from 'react';
import {
  Box,
  VStack,
  HStack,
  Text,
  Button,
  Card,
  CardBody,
  Badge,
  Progress,
  Icon,
  Circle,
  useToast,
  Modal,
  ModalOverlay,
  ModalContent,
  ModalHeader,
  ModalFooter,
  ModalBody,
  ModalCloseButton,
  useDisclosure,
  Textarea,
  FormControl,
  FormLabel,
  Spinner,
  Divider,
  Alert,
  AlertIcon,
  AlertTitle,
  AlertDescription,
  SimpleGrid,
  Stat,
  StatLabel,
  StatNumber,
} from '@chakra-ui/react';
import {
  FaMapMarkerAlt,
  FaPlay,
  FaBox,
  FaCheck,
  FaTruck,
  FaFlag,
  FaSignature,
  FaExclamationTriangle,
  FaCamera,
  FaArrowRight,
} from 'react-icons/fa';

interface Drop {
  id: string;
  sequence: number;
  pickupAddress: string;
  dropoffAddress: string;
  customerName: string;
  customerPhone: string;
  items: Array<{ name: string; quantity: number; }>;
  status: 'pending' | 'loading' | 'en_route' | 'unloading' | 'completed';
}

interface Route {
  id: string;
  drops: Drop[];
  totalDrops: number;
}

interface JobStep {
  key: string;
  title: string;
  description: string;
  icon: React.ElementType;
  completed: boolean;
  current: boolean;
  optional?: boolean;
  dropId?: string;
  dropSequence?: number;
}

interface JobProgressTrackerProps {
  jobId: string;
  route: Route;
  currentStep: string;
  completedSteps: string[];
  onStepComplete: (step: string, notes?: string, dropId?: string) => Promise<void>;
  onCustomerTrackingUpdate?: (dropId: string, status: string) => Promise<void>;
  loading?: boolean;
}

// Generate dynamic steps based on route drops
const generateJobSteps = (route: Route): JobStep[] => {
  const steps: JobStep[] = [];

  // Sort drops by sequence
  const sortedDrops = [...route.drops].sort((a, b) => a.sequence - b.sequence);

  sortedDrops.forEach((drop, index) => {
    const dropNumber = drop.sequence;

    // Navigate to pickup (only for first drop or when moving to next pickup)
    if (index === 0) {
      steps.push({
        key: `navigate_to_pickup_${drop.id}`,
        title: `Navigate to Pickup ${dropNumber}`,
        description: `Drive to pickup location for Drop ${dropNumber}`,
        icon: FaMapMarkerAlt,
        completed: false,
        current: false,
        dropId: drop.id,
        dropSequence: drop.sequence,
      });
    }

    // Arrive at pickup
    steps.push({
      key: `arrived_at_pickup_${drop.id}`,
      title: `Arrived at Pickup ${dropNumber}`,
      description: `Confirm arrival at pickup for Drop ${dropNumber}`,
      icon: FaFlag,
      completed: false,
      current: false,
      dropId: drop.id,
      dropSequence: drop.sequence,
    });

    // Loading steps
    steps.push({
      key: `loading_started_${drop.id}`,
      title: `Loading Started - Drop ${dropNumber}`,
      description: `Begin loading items for Drop ${dropNumber}`,
      icon: FaBox,
      completed: false,
      current: false,
      dropId: drop.id,
      dropSequence: drop.sequence,
    });

    // Optional item verification
    steps.push({
      key: `item_count_verification_${drop.id}`,
      title: `Verify Items - Drop ${dropNumber}`,
      description: `Count and verify items for Drop ${dropNumber}`,
      icon: FaCheck,
      completed: false,
      current: false,
      optional: true,
      dropId: drop.id,
      dropSequence: drop.sequence,
    });

    steps.push({
      key: `loading_completed_${drop.id}`,
      title: `Loading Complete - Drop ${dropNumber}`,
      description: `All items for Drop ${dropNumber} loaded and secured`,
      icon: FaBox,
      completed: false,
      current: false,
      dropId: drop.id,
      dropSequence: drop.sequence,
    });

    // Navigate to dropoff
    steps.push({
      key: `en_route_to_dropoff_${drop.id}`,
      title: `En Route to Dropoff ${dropNumber}`,
      description: `Travelling to delivery location for Drop ${dropNumber}`,
      icon: FaTruck,
      completed: false,
      current: false,
      dropId: drop.id,
      dropSequence: drop.sequence,
    });

    // Arrive at dropoff
    steps.push({
      key: `arrived_at_dropoff_${drop.id}`,
      title: `Arrived at Dropoff ${dropNumber}`,
      description: `Reached delivery location for Drop ${dropNumber}`,
      icon: FaFlag,
      completed: false,
      current: false,
      dropId: drop.id,
      dropSequence: drop.sequence,
    });

    // Unloading steps
    steps.push({
      key: `unloading_started_${drop.id}`,
      title: `Unloading Started - Drop ${dropNumber}`,
      description: `Begin unloading items for Drop ${dropNumber}`,
      icon: FaBox,
      completed: false,
      current: false,
      dropId: drop.id,
      dropSequence: drop.sequence,
    });

    steps.push({
      key: `unloading_completed_${drop.id}`,
      title: `Unloading Complete - Drop ${dropNumber}`,
      description: `All items for Drop ${dropNumber} delivered`,
      icon: FaBox,
      completed: false,
      current: false,
      dropId: drop.id,
      dropSequence: drop.sequence,
    });

    // Customer signature
    steps.push({
      key: `customer_signature_${drop.id}`,
      title: `Customer Signature - Drop ${dropNumber}`,
      description: `Get customer confirmation for Drop ${dropNumber}`,
      icon: FaSignature,
      completed: false,
      current: false,
      dropId: drop.id,
      dropSequence: drop.sequence,
    });

    // Optional damage notes
    steps.push({
      key: `damage_notes_${drop.id}`,
      title: `Damage Report - Drop ${dropNumber}`,
      description: `Report any damages for Drop ${dropNumber} (if applicable)`,
      icon: FaExclamationTriangle,
      completed: false,
      current: false,
      optional: true,
      dropId: drop.id,
      dropSequence: drop.sequence,
    });
  });

  // Final job completion step
  steps.push({
    key: 'job_completed',
    title: 'All Drops Complete',
    description: 'Mark entire multi-drop route as finished',
    icon: FaCheck,
    completed: false,
    current: false,
  });

  return steps;
};

export default function JobProgressTracker({
  jobId,
  route,
  currentStep,
  completedSteps,
  onStepComplete,
  onCustomerTrackingUpdate,
  loading = false,
}: JobProgressTrackerProps) {
  const [steps, setSteps] = useState<JobStep[]>([]);
  const [selectedStep, setSelectedStep] = useState<JobStep | null>(null);
  const [notes, setNotes] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const { isOpen, onOpen, onClose } = useDisclosure();
  const toast = useToast();

  useEffect(() => {
    // Generate dynamic steps based on route
    const generatedSteps = generateJobSteps(route);

    // Update steps based on props - mark all steps before current as completed
    const currentStepIndex = generatedSteps.findIndex(step => step.key === currentStep);

    const updatedSteps = generatedSteps.map((step, index) => ({
      ...step,
      completed: index < currentStepIndex || completedSteps.includes(step.key),
      current: step.key === currentStep,
    }));

    setSteps(updatedSteps);

    console.log('🔄 JobProgressTracker steps updated for multi-drop route:', {
      routeId: route.id,
      totalDrops: route.totalDrops,
      currentStep,
      currentStepIndex,
      totalSteps: updatedSteps.length,
      completedCount: updatedSteps.filter(s => s.completed).length
    });
  }, [currentStep, completedSteps, route]);

  const handleStepClick = (step: JobStep) => {
    if (step.completed) return;
    
    // Check if this is the current step or next step in sequence
    const currentIndex = steps.findIndex(s => s.key === currentStep);
    const stepIndex = steps.findIndex(s => s.key === step.key);
    
    // If clicking on current step, advance to next step
    if (stepIndex === currentIndex) {
      const nextIndex = currentIndex + 1;
      if (nextIndex < steps.length) {
        const nextStep = steps[nextIndex];
        console.log('🔄 Desktop: Advancing from current step to next:', { 
          current: step.key, 
          next: nextStep.key 
        });
        setSelectedStep(nextStep);
        setNotes('');
        onOpen();
      } else {
        toast({
          title: 'Job Complete',
          description: 'All steps have been completed!',
          status: 'success',
          duration: 3000,
        });
      }
    } 
    // Allow clicking on next step
    else if (stepIndex === currentIndex + 1) {
      setSelectedStep(step);
      setNotes('');
      onOpen();
    } else {
      toast({
        title: 'Invalid Step',
        description: 'Please complete steps in order.',
        status: 'warning',
        duration: 3000,
        isClosable: true,
      });
    }
  };

  const handleSubmitStep = async () => {
    if (!selectedStep) return;

    setIsSubmitting(true);
    try {
      // Complete the step
      await onStepComplete(selectedStep.key, notes, selectedStep.dropId);

      // Update customer tracking if this step affects a specific drop
      if (selectedStep.dropId && onCustomerTrackingUpdate) {
        let trackingStatus = 'pending';

        if (selectedStep.key.includes('arrived_at_pickup')) {
          trackingStatus = 'pickup_arrived';
        } else if (selectedStep.key.includes('loading_started')) {
          trackingStatus = 'loading';
        } else if (selectedStep.key.includes('en_route_to_dropoff')) {
          trackingStatus = 'en_route';
        } else if (selectedStep.key.includes('arrived_at_dropoff')) {
          trackingStatus = 'dropoff_arrived';
        } else if (selectedStep.key.includes('unloading_started')) {
          trackingStatus = 'unloading';
        } else if (selectedStep.key.includes('customer_signature')) {
          trackingStatus = 'delivered';
        }

        await onCustomerTrackingUpdate(selectedStep.dropId, trackingStatus);
      }

      toast({
        title: 'Step Completed',
        description: `${selectedStep.title} marked as complete.`,
        status: 'success',
        duration: 3000,
        isClosable: true,
      });
      onClose();
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to update step. Please try again.',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setIsSubmitting(false);
    }
  };

  const getStepColor = (step: JobStep) => {
    if (step.completed) return 'success.500';
    if (step.current) return 'neon.500';
    return 'text.tertiary';
  };

  const getStepIcon = (step: JobStep) => {
    if (step.completed) return FaCheck;
    return step.icon;
  };

  const calculateProgress = () => {
    const totalSteps = steps.filter(s => !s.optional).length;
    const completedRequiredSteps = steps.filter(s => !s.optional && s.completed).length;
    return Math.round((completedRequiredSteps / totalSteps) * 100);
  };

  const getNextStep = () => {
    const currentIndex = steps.findIndex(s => s.current);
    return steps[currentIndex + 1];
  };

  const nextStep = getNextStep();

  return (
    <Card
      bg="bg.card"
      border="1px solid"
      borderColor="border.primary"
      borderRadius="xl"
      boxShadow="md"
      overflow="hidden"
      _before={{
        content: '""',
        position: 'absolute',
        inset: 0,
        borderRadius: 'xl',
        padding: '1px',
        background: 'linear-gradient(135deg, rgba(0,194,255,0.3), rgba(0,209,143,0.3))',
        WebkitMask: 'linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0)',
        WebkitMaskComposite: 'xor',
        maskComposite: 'exclude',
        pointerEvents: 'none',
      }}
    >
      <CardBody p={6}>
        <VStack spacing={6} align="stretch">
          {/* Progress Header */}
          <Box>
            <HStack justify="space-between" mb={4}>
              <Text fontSize="xl" fontWeight="bold" color="text.primary">
                Multi-Drop Route Progress
              </Text>
              <Badge bg="neon.500" color="dark.900" size="lg" px={3} py={1} borderRadius="full">
                {calculateProgress()}% Complete
              </Badge>
            </HStack>
            <Progress
              value={calculateProgress()}
              size="lg"
              bg="bg.surface"
              borderRadius="full"
              sx={{
                '& > div': {
                  background: 'linear-gradient(135deg, #00C2FF, #00D18F)',
                }
              }}
            />
          </Box>

          {/* Next Action */}
          {nextStep && (
            <Card
              bg="bg.surface"
              border="1px solid"
              borderColor="border.secondary"
              borderRadius="lg"
            >
              <CardBody p={4}>
                <HStack spacing={4}>
                  <Circle size="40px" bg="neon.500" color="dark.900">
                    <Icon as={nextStep.icon} />
                  </Circle>
                  <VStack align="start" spacing={1} flex={1}>
                    <Text fontWeight="bold" color="text.primary">
                      Next: {nextStep.title}
                    </Text>
                    <Text fontSize="sm" color="text.secondary">
                      {nextStep.description}
                    </Text>
                    {nextStep.dropSequence && (
                      <Badge bg="brand.500" color="white" size="sm">
                        Drop {nextStep.dropSequence}
                      </Badge>
                    )}
                  </VStack>
                  <Button
                    colorScheme="brand"
                    size="md"
                    rightIcon={<FaArrowRight />}
                    onClick={() => handleStepClick(nextStep)}
                    isLoading={loading}
                    loadingText="Processing..."
                  >
                    Mark Complete
                  </Button>
                </HStack>
              </CardBody>
            </Card>
          )}

          {/* Steps List */}
          <VStack spacing={3} align="stretch">
            {steps.map((step, index) => (
              <HStack
                key={step.key}
                p={4}
                borderRadius="lg"
                border="1px solid"
                borderColor={step.completed ? 'success.300' : step.current ? 'neon.300' : 'border.secondary'}
                bg={step.current ? 'bg.surface' : 'transparent'}
                cursor={step.completed ? 'default' : 'pointer'}
                onClick={() => handleStepClick(step)}
                transition="all 0.2s"
                _hover={
                  !step.completed
                    ? {
                        borderColor: 'neon.500',
                        transform: 'translateY(-1px)',
                        shadow: 'md',
                      }
                    : {}
                }
              >
                <Circle size="40px" bg={getStepColor(step)} color={step.completed ? 'white' : 'dark.900'}>
                  {step.completed ? (
                    <Icon as={FaCheck} />
                  ) : (
                    <Icon as={step.icon} />
                  )}
                </Circle>

                <VStack align="start" spacing={1} flex={1}>
                  <HStack>
                    <Text
                      fontWeight="semibold"
                      color={step.completed ? 'success.600' : step.current ? 'text.primary' : 'text.secondary'}
                    >
                      {step.title}
                    </Text>
                    {step.optional && (
                      <Badge bg="bg.surface" color="text.secondary" size="sm">
                        Optional
                      </Badge>
                    )}
                    {step.current && (
                      <Badge bg="neon.500" color="dark.900" size="sm">
                        Current
                      </Badge>
                    )}
                  </HStack>
                  <Text fontSize="sm" color="text.secondary">
                    {step.description}
                  </Text>
                  {step.dropSequence && (
                    <Badge bg="brand.500" color="white" size="sm">
                      Drop {step.dropSequence}
                    </Badge>
                  )}
                </VStack>

                {step.completed && (
                  <Badge bg="success.500" color="white" size="lg">
                    ✓ Done
                  </Badge>
                )}
                
                {step.current && !step.completed && (
                  <Spinner size="sm" color="neon.500" />
                )}
              </HStack>
            ))}
          </VStack>

          {/* Completion Message */}
          {calculateProgress() === 100 && (
            <Card bg="green.50" border="2px solid" borderColor="green.200">
              <CardBody p={4} textAlign="center">
                <Icon as={FaCheck} boxSize={8} color="green.500" mb={2} />
                <Text fontWeight="bold" color="green.700" fontSize="lg">
                  🎉 Job Completed Successfully!
                </Text>
                <Text fontSize="sm" color="green.600" mt={1}>
                  Great work! The customer has been notified.
                </Text>
              </CardBody>
            </Card>
          )}
        </VStack>
      </CardBody>

      {/* Step Completion Modal */}
      <Modal isOpen={isOpen} onClose={onClose} size="md">
        <ModalOverlay bg="rgba(0,0,0,0.6)" backdropFilter="blur(4px)" />
        <ModalContent
          bg="bg.modal"
          border="1px solid"
          borderColor="border.primary"
          borderRadius="xl"
          _before={{
            content: '""',
            position: 'absolute',
            inset: 0,
            borderRadius: 'xl',
            padding: '1px',
            background: 'linear-gradient(135deg, rgba(0,194,255,0.3), rgba(0,209,143,0.3))',
            WebkitMask: 'linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0)',
            WebkitMaskComposite: 'xor',
            maskComposite: 'exclude',
            pointerEvents: 'none',
          }}
        >
          <ModalHeader color="text.primary">
            <HStack>
              <Icon as={selectedStep?.icon} color="neon.500" />
              <Text>Complete: {selectedStep?.title}</Text>
              {selectedStep?.dropSequence && (
                <Badge bg="brand.500" color="white" size="sm">
                  Drop {selectedStep.dropSequence}
                </Badge>
              )}
            </HStack>
          </ModalHeader>
          <ModalCloseButton />
          
          <ModalBody>
            <VStack spacing={4} align="stretch">
              <Text color="text.secondary">
                {selectedStep?.description}
              </Text>
              
              <FormControl>
                <FormLabel color="text.primary">Notes (Optional)</FormLabel>
                <Textarea
                  placeholder="Add any notes about this step..."
                  value={notes}
                  onChange={(e) => setNotes(e.target.value)}
                  rows={3}
                />
              </FormControl>
            </VStack>
          </ModalBody>

          <ModalFooter>
            <Button variant="outline" mr={3} onClick={onClose}>
              Cancel
            </Button>
            <Button
              colorScheme="brand"
              onClick={handleSubmitStep}
              isLoading={isSubmitting}
              loadingText="Updating..."
            >
              Mark Complete
            </Button>
          </ModalFooter>
        </ModalContent>
      </Modal>
    </Card>
  );
}

import React, { useState, useRef, useCallback } from 'react';
import {
  Box,
  VStack,
  HStack,
  Text,
  Button,
  Card,
  CardBody,
  Icon,
  Image,
  Progress,
  Alert,
  AlertIcon,
  SimpleGrid,
  IconButton,
  useToast,
  Modal,
  ModalOverlay,
  ModalContent,
  ModalHeader,
  ModalBody,
  ModalCloseButton,
  useDisclosure,
  Badge,
  Flex,
  useColorModeValue,
  Spinner,
} from '@chakra-ui/react';
import {
  FaCamera,
  FaUpload,
  FaImage,
  FaFile,
  FaTrash,
  FaEye,
  FaCheck,
  FaTimes,
  FaSpinner,
} from 'react-icons/fa';

interface MediaFile {
  id: string;
  file: File;
  preview?: string;
  uploaded: boolean;
  uploading: boolean;
  progress: number;
  error?: string;
  url?: string;
}

interface MediaUploaderProps {
  jobId: string;
  step: string;
  onUploadComplete?: (urls: string[]) => void;
  maxFiles?: number;
  maxFileSize?: number; // in MB
  acceptedTypes?: string[];
  required?: boolean;
}

export default function MediaUploader({
  jobId,
  step,
  onUploadComplete,
  maxFiles = 5,
  maxFileSize = 10, // 10MB
  acceptedTypes = ['image/jpeg', 'image/png', 'image/webp'],
  required = false,
}: MediaUploaderProps) {
  const [files, setFiles] = useState<MediaFile[]>([]);
  const [isUploading, setIsUploading] = useState(false);
  const [previewFile, setPreviewFile] = useState<MediaFile | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const { isOpen, onOpen, onClose } = useDisclosure();
  const toast = useToast();

  const bgColor = useColorModeValue('white', 'gray.800');
  const borderColor = useColorModeValue('gray.200', 'gray.600');
  const dropBgColor = useColorModeValue('gray.50', 'gray.700');

  const createMediaFile = (file: File): MediaFile => ({
    id: `${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
    file,
    preview: file.type.startsWith('image/') ? URL.createObjectURL(file) : undefined,
    uploaded: false,
    uploading: false,
    progress: 0,
  });

  const validateFile = (file: File): string | null => {
    // Check file type
    if (!acceptedTypes.includes(file.type)) {
      return `File type ${file.type} not supported. Please use: ${acceptedTypes.join(', ')}`;
    }

    // Check file size
    if (file.size > maxFileSize * 1024 * 1024) {
      return `File size too large. Maximum size: ${maxFileSize}MB`;
    }

    return null;
  };

  const handleFileSelect = useCallback(
    (selectedFiles: FileList | null) => {
      if (!selectedFiles) return;

      const newFiles: MediaFile[] = [];
      const errors: string[] = [];

      Array.from(selectedFiles).forEach((file) => {
        // Check if we're at max files
        if (files.length + newFiles.length >= maxFiles) {
          errors.push(`Maximum ${maxFiles} files allowed`);
          return;
        }

        // Validate file
        const error = validateFile(file);
        if (error) {
          errors.push(`${file.name}: ${error}`);
          return;
        }

        // Check for duplicates
        const isDuplicate = files.some(
          (f) => f.file.name === file.name && f.file.size === file.size
        );
        if (isDuplicate) {
          errors.push(`${file.name}: File already selected`);
          return;
        }

        newFiles.push(createMediaFile(file));
      });

      if (errors.length > 0) {
        toast({
          title: 'File Selection Errors',
          description: errors.join('\n'),
          status: 'error',
          duration: 5000,
          isClosable: true,
        });
      }

      if (newFiles.length > 0) {
        setFiles((prev) => [...prev, ...newFiles]);
      }
    },
    [files, maxFiles, toast, acceptedTypes, maxFileSize]
  );

  const handleDrop = useCallback(
    (e: React.DragEvent) => {
      e.preventDefault();
      e.stopPropagation();
      handleFileSelect(e.dataTransfer.files);
    },
    [handleFileSelect]
  );

  const handleDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
  }, []);

  const removeFile = (fileId: string) => {
    setFiles((prev) => {
      const file = prev.find((f) => f.id === fileId);
      if (file?.preview) {
        URL.revokeObjectURL(file.preview);
      }
      return prev.filter((f) => f.id !== fileId);
    });
  };

  const uploadFile = async (mediaFile: MediaFile): Promise<string> => {
    const formData = new FormData();
    formData.append('file', mediaFile.file);
    formData.append('step', step);
    formData.append('jobId', jobId);

    const response = await fetch(`/api/driver/jobs/${jobId}/media`, {
      method: 'POST',
      body: formData,
    });

    if (!response.ok) {
      throw new Error(`Upload failed: ${response.statusText}`);
    }

    const result = await response.json();
    return result.url;
  };

  const uploadAllFiles = async () => {
    const filesToUpload = files.filter((f) => !f.uploaded && !f.uploading);
    
    if (filesToUpload.length === 0) {
      toast({
        title: 'No files to upload',
        status: 'info',
        duration: 3000,
      });
      return;
    }

    setIsUploading(true);

    try {
      const uploadPromises = filesToUpload.map(async (mediaFile) => {
        // Update file state to uploading
        setFiles((prev) =>
          prev.map((f) =>
            f.id === mediaFile.id
              ? { ...f, uploading: true, progress: 0 }
              : f
          )
        );

        try {
          const url = await uploadFile(mediaFile);
          
          // Update file state to uploaded
          setFiles((prev) =>
            prev.map((f) =>
              f.id === mediaFile.id
                ? { ...f, uploaded: true, uploading: false, progress: 100, url }
                : f
            )
          );

          return url;
        } catch (error) {
          // Update file state with error
          setFiles((prev) =>
            prev.map((f) =>
              f.id === mediaFile.id
                ? {
                    ...f,
                    uploading: false,
                    progress: 0,
                    error: error instanceof Error ? error.message : 'Upload failed',
                  }
                : f
            )
          );
          throw error;
        }
      });

      const uploadedUrls = await Promise.all(uploadPromises);
      
      toast({
        title: 'Upload Complete',
        description: `${uploadedUrls.length} file(s) uploaded successfully`,
        status: 'success',
        duration: 3000,
      });

      onUploadComplete?.(uploadedUrls);
    } catch (error) {
      toast({
        title: 'Upload Failed',
        description: 'Some files failed to upload. Please try again.',
        status: 'error',
        duration: 5000,
      });
    } finally {
      setIsUploading(false);
    }
  };

  const openCamera = () => {
    if (fileInputRef.current) {
      fileInputRef.current.setAttribute('capture', 'camera');
      fileInputRef.current.click();
    }
  };

  const openFileSelector = () => {
    if (fileInputRef.current) {
      fileInputRef.current.removeAttribute('capture');
      fileInputRef.current.click();
    }
  };

  const previewImage = (file: MediaFile) => {
    setPreviewFile(file);
    onOpen();
  };

  const allUploaded = files.length > 0 && files.every((f) => f.uploaded);
  const hasErrors = files.some((f) => f.error);
  const uploadProgress = files.length > 0 
    ? files.reduce((sum, f) => sum + f.progress, 0) / files.length 
    : 0;

  return (
    <Card bg={bgColor} shadow="md" borderRadius="lg">
      <CardBody p={6}>
        <VStack spacing={6} align="stretch">
          {/* Header */}
          <Box>
            <Text fontSize="lg" fontWeight="bold" mb={2}>
              Upload Media
            </Text>
            <Text fontSize="sm" color="gray.600">
              Add photos or documents for this step
              {required && <Text as="span" color="red.500"> (Required)</Text>}
            </Text>
          </Box>

          {/* File Input */}
          <input
            ref={fileInputRef}
            type="file"
            accept={acceptedTypes.join(',')}
            multiple
            style={{ display: 'none' }}
            onChange={(e) => handleFileSelect(e.target.files)}
          />

          {/* Upload Area */}
          <Box
            border="2px dashed"
            borderColor={borderColor}
            borderRadius="lg"
            p={8}
            textAlign="center"
            bg={dropBgColor}
            onDrop={handleDrop}
            onDragOver={handleDragOver}
            cursor="pointer"
            transition="all 0.2s"
            _hover={{
              borderColor: 'blue.400',
              bg: useColorModeValue('blue.50', 'blue.900'),
            }}
          >
            <VStack spacing={4}>
              <Icon as={FaUpload} boxSize={12} color="gray.400" />
              <VStack spacing={2}>
                <Text fontWeight="semibold">
                  Drop files here or click to select
                </Text>
                <Text fontSize="sm" color="gray.500">
                  Support: {acceptedTypes.join(', ')} (Max {maxFileSize}MB each)
                </Text>
              </VStack>
              
              <HStack spacing={4}>
                <Button
                  leftIcon={<FaCamera />}
                  colorScheme="blue"
                  variant="outline"
                  onClick={openCamera}
                >
                  Take Photo
                </Button>
                <Button
                  leftIcon={<FaFile />}
                  colorScheme="blue"
                  variant="outline"
                  onClick={openFileSelector}
                >
                  Choose Files
                </Button>
              </HStack>
            </VStack>
          </Box>

          {/* Files Grid */}
          {files.length > 0 && (
            <Box>
              <Text fontWeight="semibold" mb={4}>
                Selected Files ({files.length}/{maxFiles})
              </Text>
              
              <SimpleGrid columns={{ base: 1, md: 2 }} spacing={4} mb={4}>
                {files.map((file) => (
                  <Card key={file.id} shadow="sm" borderRadius="lg">
                    <CardBody p={4}>
                      <HStack spacing={4}>
                        {/* File Preview */}
                        <Box flexShrink={0}>
                          {file.preview ? (
                            <Image
                              src={file.preview}
                              alt={file.file.name}
                              boxSize="60px"
                              objectFit="cover"
                              borderRadius="md"
                              cursor="pointer"
                              onClick={() => previewImage(file)}
                            />
                          ) : (
                            <Flex
                              boxSize="60px"
                              bg="gray.100"
                              borderRadius="md"
                              align="center"
                              justify="center"
                            >
                              <Icon as={FaFile} color="gray.400" />
                            </Flex>
                          )}
                        </Box>

                        {/* File Info */}
                        <VStack align="start" spacing={1} flex={1}>
                          <Text fontSize="sm" fontWeight="medium" noOfLines={1}>
                            {file.file.name}
                          </Text>
                          <Text fontSize="xs" color="gray.500">
                            {(file.file.size / (1024 * 1024)).toFixed(2)} MB
                          </Text>
                          
                          {/* Status */}
                          {file.uploaded && (
                            <Badge colorScheme="green" size="sm">
                              <Icon as={FaCheck} mr={1} />
                              Uploaded
                            </Badge>
                          )}
                          
                          {file.uploading && (
                            <HStack spacing={2}>
                              <Spinner size="sm" color="blue.500" />
                              <Progress
                                value={file.progress}
                                size="sm"
                                colorScheme="blue"
                                flex={1}
                              />
                            </HStack>
                          )}
                          
                          {file.error && (
                            <Badge colorScheme="red" size="sm">
                              <Icon as={FaTimes} mr={1} />
                              Error
                            </Badge>
                          )}
                        </VStack>

                        {/* Actions */}
                        <VStack spacing={2}>
                          {file.preview && (
                            <IconButton
                              aria-label="Preview"
                              icon={<FaEye />}
                              size="sm"
                              variant="ghost"
                              onClick={() => previewImage(file)}
                            />
                          )}
                          <IconButton
                            aria-label="Remove"
                            icon={<FaTrash />}
                            size="sm"
                            variant="ghost"
                            colorScheme="red"
                            onClick={() => removeFile(file.id)}
                            isDisabled={file.uploading}
                          />
                        </VStack>
                      </HStack>
                      
                      {file.error && (
                        <Alert status="error" size="sm" mt={2} borderRadius="md">
                          <AlertIcon />
                          <Text fontSize="xs">{file.error}</Text>
                        </Alert>
                      )}
                    </CardBody>
                  </Card>
                ))}
              </SimpleGrid>

              {/* Upload Progress */}
              {isUploading && (
                <Box mb={4}>
                  <Text fontSize="sm" mb={2} fontWeight="medium">
                    Uploading... {Math.round(uploadProgress)}%
                  </Text>
                  <Progress 
                    value={uploadProgress} 
                    colorScheme="blue" 
                    borderRadius="full" 
                  />
                </Box>
              )}

              {/* Upload Button */}
              <HStack justify="space-between">
                <Text fontSize="sm" color="gray.500">
                  {files.filter(f => f.uploaded).length} of {files.length} uploaded
                </Text>
                
                <Button
                  colorScheme="blue"
                  onClick={uploadAllFiles}
                  isLoading={isUploading}
                  isDisabled={allUploaded || files.length === 0}
                  leftIcon={<FaUpload />}
                >
                  Upload All Files
                </Button>
              </HStack>
              
              {/* Success Message */}
              {allUploaded && !hasErrors && (
                <Alert status="success" borderRadius="md">
                  <AlertIcon />
                  All files uploaded successfully!
                </Alert>
              )}
            </Box>
          )}
        </VStack>
      </CardBody>

      {/* Image Preview Modal */}
      {previewFile && (
        <Modal isOpen={isOpen} onClose={onClose} size="xl">
          <ModalOverlay />
          <ModalContent>
            <ModalHeader>{previewFile.file.name}</ModalHeader>
            <ModalCloseButton />
            <ModalBody pb={6}>
              {previewFile.preview && (
                <Image
                  src={previewFile.preview}
                  alt={previewFile.file.name}
                  w="100%"
                  h="auto"
                  maxH="70vh"
                  objectFit="contain"
                  borderRadius="md"
                />
              )}
            </ModalBody>
          </ModalContent>
        </Modal>
      )}
    </Card>
  );
}

import React, { useState, useCallback, useRef } from 'react';
import {
  Box,
  VStack,
  HStack,
  Button,
  Text,
  Card,
  CardBody,
  IconButton,
  useColorModeValue,
  Collapse,
  ScaleFade,
  Flex,
  Badge,
  useToast,
  Tooltip,
  Drawer,
  DrawerBody,
  DrawerHeader,
  DrawerOverlay,
  DrawerContent,
  DrawerCloseButton,
  useDisclosure,
} from '@chakra-ui/react';
import {
  FaPhone,
  FaMap,
  FaDirections,
  FaChevronUp,
  FaChevronDown,
  FaLocationArrow,
  FaCopy,
  FaShare,
  FaExpandArrowsAlt,
  FaCompress,
} from 'react-icons/fa';

interface MobileJobActionsProps {
  jobDetails: {
    id: string;
    reference: string;
    customer: string;
    customerPhone: string;
    from: string;
    to: string;
    status: string;
    estimatedEarnings?: number;
  };
  onCallCustomer: () => void;
  onOpenMap: (address: string) => void;
  onGetDirections: (from: string, to: string) => void;
  isCompact?: boolean;
}

const MobileJobActions: React.FC<MobileJobActionsProps> = ({
  jobDetails,
  onCallCustomer,
  onOpenMap,
  onGetDirections,
  isCompact = false,
}) => {
  const [isExpanded, setIsExpanded] = useState(!isCompact);
  const [isFullScreen, setIsFullScreen] = useState(false);
  
  const { isOpen: isDrawerOpen, onOpen: onDrawerOpen, onClose: onDrawerClose } = useDisclosure();
  
  const toast = useToast();
  const cardRef = useRef<HTMLDivElement>(null);

  const bg = useColorModeValue('white', 'gray.800');
  const borderColor = useColorModeValue('gray.200', 'gray.600');
  const actionBg = useColorModeValue('gray.50', 'gray.700');

  const handleCopyReference = useCallback(() => {
    navigator.clipboard.writeText(jobDetails.reference);
    toast({
      title: 'Copied!',
      description: 'Job reference copied to clipboard',
      status: 'success',
      duration: 2000,
    });
  }, [jobDetails.reference, toast]);

  const handleShare = useCallback(async () => {
    const shareData = {
      title: `Job ${jobDetails.reference}`,
      text: `Customer: ${jobDetails.customer}\nFrom: ${jobDetails.from}\nTo: ${jobDetails.to}`,
      url: window.location.href,
    };

    if (navigator.share) {
      try {
        await navigator.share(shareData);
      } catch (error) {
        console.log('Share cancelled');
      }
    } else {
      // Fallback for browsers without Web Share API
      navigator.clipboard.writeText(
        `Job ${jobDetails.reference}\nCustomer: ${jobDetails.customer}\nFrom: ${jobDetails.from}\nTo: ${jobDetails.to}\n${window.location.href}`
      );
      toast({
        title: 'Copied!',
        description: 'Job details copied to clipboard',
        status: 'success',
        duration: 2000,
      });
    }
  }, [jobDetails, toast]);

  const toggleFullScreen = useCallback(() => {
    setIsFullScreen(!isFullScreen);
    setIsExpanded(true);
  }, [isFullScreen]);

  const quickActions = (
    <VStack spacing={3} width="100%">
      <HStack spacing={2} width="100%">
        <Button
          flex="1"
          colorScheme="green"
          leftIcon={<FaPhone />}
          onClick={onCallCustomer}
          size="lg"
          fontSize="md"
          height="60px"
          borderRadius="xl"
          _active={{ transform: 'scale(0.98)' }}
        >
          Call
        </Button>
        <Button
          flex="1"
          colorScheme="blue"
          leftIcon={<FaLocationArrow />}
          onClick={() => onOpenMap(jobDetails.from)}
          size="lg"
          fontSize="md"
          height="60px"
          borderRadius="xl"
          _active={{ transform: 'scale(0.98)' }}
        >
          Pickup
        </Button>
        <Button
          flex="1"
          colorScheme="purple"
          leftIcon={<FaDirections />}
          onClick={() => onGetDirections(jobDetails.from, jobDetails.to)}
          size="lg"
          fontSize="md"
          height="60px"
          borderRadius="xl"
          _active={{ transform: 'scale(0.98)' }}
        >
          Navigate
        </Button>
      </HStack>
      
      <Collapse in={isExpanded} animateOpacity>
        <VStack spacing={3} width="100%">
          <Button
            width="100%"
            variant="outline"
            leftIcon={<FaMap />}
            onClick={() => onOpenMap(jobDetails.to)}
            size="lg"
            height="50px"
            borderRadius="xl"
            _active={{ transform: 'scale(0.98)' }}
          >
            View Dropoff Location
          </Button>
          
          <HStack spacing={2} width="100%">
            <Button
              flex="1"
              variant="ghost"
              leftIcon={<FaCopy />}
              onClick={handleCopyReference}
              size="md"
              _active={{ transform: 'scale(0.98)' }}
            >
              Copy Ref
            </Button>
            <Button
              flex="1"
              variant="ghost"
              leftIcon={<FaShare />}
              onClick={handleShare}
              size="md"
              _active={{ transform: 'scale(0.98)' }}
            >
              Share
            </Button>
            <Button
              flex="1"
              variant="ghost"
              leftIcon={<FaExpandArrowsAlt />}
              onClick={onDrawerOpen}
              size="md"
              _active={{ transform: 'scale(0.98)' }}
            >
              Details
            </Button>
          </HStack>
        </VStack>
      </Collapse>
    </VStack>
  );

  return (
    <>
      {/* Mobile Quick Actions Card */}
      <ScaleFade in={true} initialScale={0.95}>
        <Card
          ref={cardRef}
          borderRadius="2xl"
          boxShadow="xl"
          overflow="hidden"
          bg={bg}
          border="1px"
          borderColor={borderColor}
          position="sticky"
          bottom={4}
          zIndex={10}
          mx={4}
        >
          <CardBody p={4}>
            <VStack spacing={4}>
              {/* Job Header */}
              <HStack justify="space-between" align="center" width="100%">
                <VStack align="start" spacing={1} flex="1">
                  <HStack>
                    <Text fontSize="sm" fontWeight="bold" color="blue.600">
                      {jobDetails.reference}
                    </Text>
                    <Badge colorScheme="green" size="sm">
                      {jobDetails.status}
                    </Badge>
                  </HStack>
                  <Text fontSize="xs" color="gray.600" noOfLines={1}>
                    {jobDetails.customer}
                  </Text>
                </VStack>
                
                <VStack align="end" spacing={1}>
                  <Text fontSize="lg" fontWeight="bold" color="green.600">
                    £{jobDetails.estimatedEarnings?.toFixed(2) || '0.00'}
                  </Text>
                  <IconButton
                    aria-label={isExpanded ? 'Collapse' : 'Expand'}
                    icon={isExpanded ? <FaChevronDown /> : <FaChevronUp />}
                    size="sm"
                    variant="ghost"
                    onClick={() => setIsExpanded(!isExpanded)}
                  />
                </VStack>
              </HStack>

              {/* Quick Actions */}
              {quickActions}
            </VStack>
          </CardBody>
        </Card>
      </ScaleFade>

      {/* Full Details Drawer */}
      <Drawer isOpen={isDrawerOpen} placement="bottom" onClose={onDrawerClose} size="full">
        <DrawerOverlay />
        <DrawerContent borderTopRadius="2xl">
          <DrawerCloseButton size="lg" />
          <DrawerHeader pb={2}>
            <VStack align="start" spacing={2}>
              <HStack>
                <Text fontSize="xl" fontWeight="bold">
                  Job {jobDetails.reference}
                </Text>
                <Badge colorScheme="green" size="lg">
                  {jobDetails.status}
                </Badge>
              </HStack>
              <Text fontSize="md" color="gray.600">
                {jobDetails.customer}
              </Text>
            </VStack>
          </DrawerHeader>

          <DrawerBody pb={8}>
            <VStack spacing={6} align="stretch">
              {/* Earnings */}
              <Card bg={actionBg} borderRadius="xl">
                <CardBody p={4} textAlign="center">
                  <Text fontSize="2xl" fontWeight="bold" color="green.600">
                    £{jobDetails.estimatedEarnings?.toFixed(2) || '0.00'}
                  </Text>
                  <Text fontSize="sm" color="gray.600">
                    Estimated Earnings
                  </Text>
                </CardBody>
              </Card>

              {/* Locations */}
              <VStack spacing={4}>
                <Card bg={actionBg} borderRadius="xl" width="100%">
                  <CardBody p={4}>
                    <VStack align="stretch" spacing={3}>
                      <Text fontWeight="bold" color="green.600">
                        📍 Pickup Location
                      </Text>
                      <Text fontSize="sm">{jobDetails.from}</Text>
                      <HStack spacing={2}>
                        <Button
                          size="sm"
                          colorScheme="green"
                          onClick={() => onOpenMap(jobDetails.from)}
                          flex="1"
                        >
                          View Map
                        </Button>
                        <Button
                          size="sm"
                          variant="outline"
                          onClick={() => onGetDirections("Current Location", jobDetails.from)}
                          flex="1"
                        >
                          Directions
                        </Button>
                      </HStack>
                    </VStack>
                  </CardBody>
                </Card>

                <Card bg={actionBg} borderRadius="xl" width="100%">
                  <CardBody p={4}>
                    <VStack align="stretch" spacing={3}>
                      <Text fontWeight="bold" color="red.600">
                        🚩 Dropoff Location
                      </Text>
                      <Text fontSize="sm">{jobDetails.to}</Text>
                      <HStack spacing={2}>
                        <Button
                          size="sm"
                          colorScheme="red"
                          onClick={() => onOpenMap(jobDetails.to)}
                          flex="1"
                        >
                          View Map
                        </Button>
                        <Button
                          size="sm"
                          variant="outline"
                          onClick={() => onGetDirections(jobDetails.from, jobDetails.to)}
                          flex="1"
                        >
                          Full Route
                        </Button>
                      </HStack>
                    </VStack>
                  </CardBody>
                </Card>
              </VStack>

              {/* Action Buttons */}
              <VStack spacing={3}>
                <Button
                  width="100%"
                  colorScheme="green"
                  size="lg"
                  leftIcon={<FaPhone />}
                  onClick={onCallCustomer}
                  height="60px"
                  fontSize="lg"
                  borderRadius="xl"
                >
                  Call Customer
                </Button>
                
                <HStack spacing={3} width="100%">
                  <Button
                    flex="1"
                    variant="outline"
                    leftIcon={<FaCopy />}
                    onClick={handleCopyReference}
                    size="lg"
                  >
                    Copy Reference
                  </Button>
                  <Button
                    flex="1"
                    variant="outline"
                    leftIcon={<FaShare />}
                    onClick={handleShare}
                    size="lg"
                  >
                    Share Job
                  </Button>
                </HStack>
              </VStack>
            </VStack>
          </DrawerBody>
        </DrawerContent>
      </Drawer>
    </>
  );
};

export default MobileJobActions;

import React, { useState, useCallback } from 'react';
import {
  Box,
  VStack,
  HStack,
  Button,
  Text,
  Card,
  CardBody,
  CardHeader,
  Progress,
  Badge,
  useColorModeValue,
  Modal,
  ModalOverlay,
  ModalContent,
  ModalHeader,
  ModalFooter,
  ModalBody,
  ModalCloseButton,
  useDisclosure,
  Input,
  Textarea,
  FormControl,
  FormLabel,
  useToast,
  Icon,
  Circle,
  Flex,
  Divider,
  ScaleFade,
  Collapse,
  IconButton,
} from '@chakra-ui/react';
import {
  FaCheckCircle,
  FaCircle,
  FaClock,
  FaMapMarkerAlt,
  FaBox,
  FaTruck,
  FaSignature,
  FaFlag,
  FaChevronRight,
  FaPlay,
  FaExpand,
  FaCompress,
} from 'react-icons/fa';

interface JobStep {
  id: string;
  label: string;
  description: string;
  icon: React.ElementType;
  status: 'completed' | 'current' | 'pending';
  isOptional?: boolean;
  estimatedDuration?: string;
}

interface MobileJobProgressProps {
  currentStep: string;
  jobId: string;
  onStepUpdate: (step: string, notes?: string) => Promise<void>;
  isCompact?: boolean;
  showEstimates?: boolean;
}

const JOB_STEPS: Record<string, JobStep> = {
  navigate_to_pickup: {
    id: 'navigate_to_pickup',
    label: 'Navigate to Pickup',
    description: 'Drive to the pickup location',
    icon: FaTruck,
    status: 'pending',
    estimatedDuration: '15-30 min',
  },
  arrived_at_pickup: {
    id: 'arrived_at_pickup',
    label: 'Arrived at Pickup',
    description: 'You have reached the pickup location',
    icon: FaMapMarkerAlt,
    status: 'pending',
  },
  loading_started: {
    id: 'loading_started',
    label: 'Loading Started',
    description: 'Begin loading items into vehicle',
    icon: FaBox,
    status: 'pending',
    estimatedDuration: '10-20 min',
  },
  loading_completed: {
    id: 'loading_completed',
    label: 'Loading Complete',
    description: 'All items have been loaded',
    icon: FaCheckCircle,
    status: 'pending',
  },
  en_route_to_dropoff: {
    id: 'en_route_to_dropoff',
    label: 'En Route to Delivery',
    description: 'Drive to the delivery location',
    icon: FaTruck,
    status: 'pending',
    estimatedDuration: '20-45 min',
  },
  arrived_at_dropoff: {
    id: 'arrived_at_dropoff',
    label: 'Arrived at Delivery',
    description: 'You have reached the delivery location',
    icon: FaMapMarkerAlt,
    status: 'pending',
  },
  unloading_started: {
    id: 'unloading_started',
    label: 'Unloading Started',
    description: 'Begin unloading items',
    icon: FaBox,
    status: 'pending',
    estimatedDuration: '10-15 min',
  },
  unloading_completed: {
    id: 'unloading_completed',
    label: 'Unloading Complete',
    description: 'All items have been unloaded',
    icon: FaCheckCircle,
    status: 'pending',
  },
  customer_signature: {
    id: 'customer_signature',
    label: 'Customer Signature',
    description: 'Obtain customer confirmation',
    icon: FaSignature,
    status: 'pending',
    isOptional: true,
  },
  job_completed: {
    id: 'job_completed',
    label: 'Job Complete',
    description: 'Job has been completed successfully',
    icon: FaFlag,
    status: 'pending',
  },
};

const MobileJobProgress: React.FC<MobileJobProgressProps> = ({
  currentStep,
  jobId,
  onStepUpdate,
  isCompact = false,
  showEstimates = true,
}) => {
  const [isUpdating, setIsUpdating] = useState<string | null>(null);
  const [notes, setNotes] = useState('');
  const [selectedStep, setSelectedStep] = useState<string | null>(null);
  const [isExpanded, setIsExpanded] = useState(!isCompact);
  
  const { isOpen, onOpen, onClose } = useDisclosure();
  const toast = useToast();

  const bg = useColorModeValue('white', 'gray.800');
  const borderColor = useColorModeValue('gray.200', 'gray.600');
  const completedColor = useColorModeValue('green.500', 'green.400');
  const currentColor = useColorModeValue('blue.500', 'blue.400');
  const pendingColor = useColorModeValue('gray.300', 'gray.600');

  // Get steps with status
  const getStepsWithStatus = useCallback(() => {
    const stepOrder = Object.keys(JOB_STEPS);
    const currentIndex = stepOrder.indexOf(currentStep);
    
    // Debug logging for development
    if (process.env.NODE_ENV === 'development') {
      console.log('🔍 Progress calculation:', {
        currentStep,
        currentIndex,
        stepOrder,
        totalSteps: stepOrder.length
      });
    }
    
    return stepOrder.map((stepId, index) => ({
      ...JOB_STEPS[stepId],
      status: index <= currentIndex 
        ? (index === currentIndex ? 'current' as const : 'completed' as const)
        : 'pending' as const
    }));
  }, [currentStep]);

  const steps = getStepsWithStatus();
  const currentStepIndex = steps.findIndex(step => step.status === 'current');
  const completedStepsCount = steps.filter(step => step.status === 'completed').length;
  
  // Progress calculation: (completed + 0.5 for current) / total * 100
  const progressPercentage = currentStepIndex >= 0 
    ? ((completedStepsCount + 0.5) / steps.length) * 100 
    : (completedStepsCount / steps.length) * 100;

  // Debug logging for development
  if (process.env.NODE_ENV === 'development') {
    console.log('📊 Progress details:', {
      currentStepIndex,
      completedStepsCount,
      totalSteps: steps.length,
      progressPercentage: Math.round(progressPercentage),
      currentStep
    });
  }

  const handleStepClick = useCallback((step: JobStep) => {
    // If clicking on current step, advance to next step instead of staying on same step
    if (step.status === 'current') {
      const nextStepIndex = currentStepIndex + 1;
      if (nextStepIndex < steps.length) {
        const nextStep = steps[nextStepIndex];
        console.log('🔄 Advancing from current step to next:', { 
          current: step.id, 
          next: nextStep.id 
        });
        setSelectedStep(nextStep.id);
        onOpen();
      } else {
        toast({
          title: 'Job Complete',
          description: 'All steps have been completed!',
          status: 'success',
          duration: 3000,
        });
      }
    } 
    // Allow clicking on next pending step
    else if (step.status === 'pending' && steps.findIndex(s => s.id === step.id) === currentStepIndex + 1) {
      setSelectedStep(step.id);
      onOpen();
    }
  }, [currentStepIndex, steps, onOpen, toast]);

  const handleStepUpdate = useCallback(async () => {
    if (!selectedStep) return;
    
    setIsUpdating(selectedStep);
    try {
      await onStepUpdate(selectedStep, notes);
      toast({
        title: 'Step Updated',
        description: `Successfully updated to: ${JOB_STEPS[selectedStep].label}`,
        status: 'success',
        duration: 3000,
      });
      setNotes('');
      onClose();
    } catch (error) {
      toast({
        title: 'Update Failed',
        description: 'Failed to update job step',
        status: 'error',
        duration: 5000,
      });
    } finally {
      setIsUpdating(null);
    }
  }, [selectedStep, notes, onStepUpdate, toast, onClose]);

  const getStepColor = (status: JobStep['status']) => {
    switch (status) {
      case 'completed': return completedColor;
      case 'current': return currentColor;
      case 'pending': return pendingColor;
    }
  };

  const getStepIcon = (step: JobStep) => {
    if (step.status === 'completed') return FaCheckCircle;
    if (step.status === 'current') return FaPlay;
    return step.icon;
  };

  return (
    <>
      <ScaleFade in={true} initialScale={0.95}>
        <Card borderRadius="2xl" boxShadow="xl" overflow="hidden" bg={bg} border="1px" borderColor={borderColor}>
          <CardHeader pb={2} px={4} pt={4}>
            <HStack justify="space-between" align="center">
              <VStack align="start" spacing={1} flex="1">
                <Text fontSize="lg" fontWeight="bold" color="blue.600">
                  Job Progress
                </Text>
                <Text fontSize="sm" color="gray.600">
                  Step {currentStepIndex + 1} of {steps.length}
                </Text>
              </VStack>
              
              <VStack align="end" spacing={1}>
                <Text fontSize="2xl" fontWeight="bold" color={currentColor}>
                  {Math.round(progressPercentage)}%
                </Text>
                <IconButton
                  aria-label={isExpanded ? 'Collapse' : 'Expand'}
                  icon={isExpanded ? <FaCompress /> : <FaExpand />}
                  size="sm"
                  variant="ghost"
                  onClick={() => setIsExpanded(!isExpanded)}
                />
              </VStack>
            </HStack>
            
            <Box mt={3}>
              <Progress 
                value={progressPercentage} 
                colorScheme="blue" 
                size="lg" 
                borderRadius="full"
                bg="gray.100"
              />
            </Box>
          </CardHeader>

          <Collapse in={isExpanded} animateOpacity>
            <CardBody pt={2} px={4} pb={4}>
              <VStack spacing={3} align="stretch">
                {steps.map((step, index) => {
                  const isNextStep = step.status === 'pending' && index === currentStepIndex + 1;
                  const isClickable = step.status === 'current' || isNextStep;
                  
                  return (
                    <Box key={step.id}>
                      <HStack
                        spacing={3}
                        p={3}
                        borderRadius="xl"
                        cursor={isClickable ? 'pointer' : 'default'}
                        bg={step.status === 'current' ? 'blue.50' : 'transparent'}
                        _hover={isClickable ? { bg: 'gray.50' } : {}}
                        _active={isClickable ? { transform: 'scale(0.98)' } : {}}
                        onClick={() => isClickable && handleStepClick(step)}
                        transition="all 0.2s"
                      >
                        <Circle
                          size="40px"
                          bg={getStepColor(step.status)}
                          color="white"
                        >
                          <Icon as={getStepIcon(step)} boxSize="18px" />
                        </Circle>
                        
                        <VStack align="start" spacing={0} flex="1">
                          <HStack>
                            <Text 
                              fontSize="md" 
                              fontWeight={step.status === 'current' ? 'bold' : 'medium'}
                              color={step.status === 'pending' ? 'gray.500' : 'inherit'}
                            >
                              {step.label}
                            </Text>
                            {step.isOptional && (
                              <Badge size="sm" colorScheme="gray" variant="outline">
                                Optional
                              </Badge>
                            )}
                          </HStack>
                          
                          <Text 
                            fontSize="sm" 
                            color="gray.600"
                            noOfLines={1}
                          >
                            {step.description}
                          </Text>
                          
                          {showEstimates && step.estimatedDuration && (
                            <HStack spacing={1}>
                              <Icon as={FaClock} boxSize="12px" color="gray.400" />
                              <Text fontSize="xs" color="gray.400">
                                {step.estimatedDuration}
                              </Text>
                            </HStack>
                          )}
                        </VStack>
                        
                        {step.status === 'current' && (
                          <VStack align="end" spacing={1}>
                            <Badge colorScheme="blue" size="sm">
                              Tap to Complete
                            </Badge>
                            <Icon as={FaChevronRight} color="blue.400" />
                          </VStack>
                        )}
                        {isNextStep && (
                          <Icon as={FaChevronRight} color="gray.400" />
                        )}
                      </HStack>
                      
                      {index < steps.length - 1 && (
                        <Box ml="20px" pl="20px">
                          <Divider 
                            orientation="vertical" 
                            height="8px"
                            borderColor={index < currentStepIndex ? completedColor : pendingColor}
                            borderWidth="2px"
                          />
                        </Box>
                      )}
                    </Box>
                  );
                })}
              </VStack>
            </CardBody>
          </Collapse>
        </Card>
      </ScaleFade>

      {/* Step Update Modal */}
      <Modal isOpen={isOpen} onClose={onClose} size="full">
        <ModalOverlay />
        <ModalContent>
          <ModalHeader>
            {selectedStep && JOB_STEPS[selectedStep] ? 
              `Complete: ${JOB_STEPS[selectedStep].label}` : 
              'Update Job Step'
            }
          </ModalHeader>
          <ModalCloseButton />
          <ModalBody>
            {selectedStep && (
              <VStack spacing={6} align="stretch">
                <Card bg="blue.50" borderRadius="xl">
                  <CardBody>
                    <VStack align="start" spacing={3}>
                      <HStack>
                        <Circle size="50px" bg="blue.500" color="white">
                          <Icon as={JOB_STEPS[selectedStep].icon} boxSize="24px" />
                        </Circle>
                        <VStack align="start" spacing={1}>
                          <Text fontSize="lg" fontWeight="bold">
                            {JOB_STEPS[selectedStep].label}
                          </Text>
                          <Text fontSize="sm" color="gray.600">
                            {JOB_STEPS[selectedStep].description}
                          </Text>
                        </VStack>
                      </HStack>
                    </VStack>
                  </CardBody>
                </Card>

                <FormControl>
                  <FormLabel>Notes (Optional)</FormLabel>
                  <Textarea
                    value={notes}
                    onChange={(e) => setNotes(e.target.value)}
                    placeholder="Add any notes about this step..."
                    rows={4}
                    resize="vertical"
                  />
                </FormControl>
              </VStack>
            )}
          </ModalBody>

          <ModalFooter>
            <HStack spacing={3} width="100%">
              <Button variant="ghost" onClick={onClose} flex="1">
                Cancel
              </Button>
              <Button
                colorScheme="blue"
                onClick={handleStepUpdate}
                isLoading={isUpdating === selectedStep}
                loadingText="Updating..."
                flex="2"
                size="lg"
              >
                Update Step
              </Button>
            </HStack>
          </ModalFooter>
        </ModalContent>
      </Modal>
    </>
  );
};

export default MobileJobProgress;

