          </Text>
        </VStack>

        {/* Tips */}
        <VStack spacing={4} align="stretch" w="full">
          <Text
            fontSize="sm"
            fontWeight="medium"
            color="white"
            textShadow="0 0 10px rgba(255, 255, 255, 0.6)"
          >
            💡 Tips to get more jobs:
          </Text>
          <VStack spacing={2} align="start" w="full" pl={4}>
