                position="relative"
                overflow="hidden"
                boxShadow="0 0 10px rgba(59, 130, 246, 0.4)"
                _hover={{
                  bg: "rgba(59, 130, 246, 0.1)",
                  borderColor: "neon.400",
                  boxShadow: "0 0 15px rgba(59, 130, 246, 0.6)"
                }}
              >
                👁️ View Details
              </Button>
            )}
          </VStack>
        </VStack>
      </CardBody>

      {/* View Details Modal */}
      <Modal isOpen={isOpen} onClose={onClose} size="xl" scrollBehavior="inside">
        <ModalOverlay bg="blackAlpha.800" />
        <ModalContent 
          bg="bg.card" 
          borderColor="border.primary" 
          borderWidth="1px"
          boxShadow="0 0 30px rgba(59, 130, 246, 0.5)"
        >
          <ModalHeader 
            color="white"
            textShadow="0 0 15px rgba(59, 130, 246, 0.8)"
          >
            Route Details - {route.drops.length} Stops
          </ModalHeader>
          <ModalCloseButton color="white" />
          <ModalBody>
            <VStack spacing={4} align="stretch">
              {route.drops.map((drop, index) => (
                <Box
                  key={drop.id}
                  p={4}
                  bg="rgba(59, 130, 246, 0.1)"
                  borderRadius="lg"
                  border="1px solid"
                  borderColor="rgba(59, 130, 246, 0.3)"
                  position="relative"
                  _hover={{
                    bg: "rgba(59, 130, 246, 0.15)",
                    borderColor: "rgba(59, 130, 246, 0.5)"
                  }}
                >
                  <VStack align="stretch" spacing={3}>
                    {/* Stop Header */}
                    <HStack justify="space-between">
                      <HStack>
                        <Circle size="8" bg="neon.500" color="white" fontWeight="bold">
                          {index + 1}
                        </Circle>
                        <VStack align="start" spacing={0}>
                          <Text 
                            fontWeight="bold" 
                            color="white"
                            textShadow="0 0 8px rgba(255, 255, 255, 0.6)"
                          >
                            {drop.customerName || drop.booking?.customerName || 'Unknown Customer'}
                          </Text>
                          <Text fontSize="xs" color="white" opacity={0.7}>
                            {drop.booking?.reference || drop.id.slice(-8)}
                          </Text>
                        </VStack>
                      </HStack>
                      <Badge 
                        colorScheme={drop.serviceTier === 'premium' ? 'purple' : 'blue'}
                        boxShadow="0 0 8px rgba(59, 130, 246, 0.5)"
                      >
                        {drop.serviceTier}
                      </Badge>
                    </HStack>

                    {/* Addresses */}
                    <VStack align="stretch" spacing={2}>
                      <HStack>
                        <Icon as={FaMapMarkerAlt} color="green.400" />
                        <VStack align="start" spacing={0} flex={1}>
                          <Text fontSize="xs" color="white" opacity={0.7}>Pickup:</Text>
                          <Text fontSize="sm" color="white" fontWeight="medium">
                            {drop.pickupAddress || drop.booking?.pickupAddress || 'Not specified'}
                          </Text>
                        </VStack>
                      </HStack>

                      <HStack>
                        <Icon as={FaMapMarkerAlt} color="red.400" />
                        <VStack align="start" spacing={0} flex={1}>
                          <Text fontSize="xs" color="white" opacity={0.7}>Delivery:</Text>
                          <Text fontSize="sm" color="white" fontWeight="medium">
                            {drop.deliveryAddress || drop.booking?.dropoffAddress}
                          </Text>
                        </VStack>
                      </HStack>
                    </VStack>

                    {/* Time Window */}
                    <HStack>
                      <Icon as={FaClock} color="neon.400" />
                      <Text fontSize="sm" color="white">
                        {formatTime(drop.timeWindowStart)} - {formatTime(drop.timeWindowEnd)}
                      </Text>
                    </HStack>

                    {/* Items */}
                    {drop.items && drop.items.length > 0 && (
                      <Box>
                        <Text 
                          fontSize="sm" 
                          fontWeight="semibold" 
                          color="white" 
                          mb={2}
                          textShadow="0 0 6px rgba(255, 255, 255, 0.5)"
                        >
                          <Icon as={FaBox} mr={2} color="amber.400" />
                          Items ({drop.items.length}):
                        </Text>
                        <VStack align="stretch" spacing={1} pl={6}>
                          {drop.items.map((item) => (
                            <HStack key={item.id} justify="space-between">
                              <Text fontSize="sm" color="white" opacity={0.9}>
                                • {item.name}
                              </Text>
                              <Badge colorScheme="blue" fontSize="xs">
                                {item.quantity}x ({item.volumeM3.toFixed(2)}m³)
                              </Badge>
                            </HStack>
                          ))}
                        </VStack>
                      </Box>
                    )}

                    {/* Special Instructions */}
                    {drop.specialInstructions && (
                      <Box 
                        p={2} 
                        bg="rgba(251, 191, 36, 0.1)" 
                        borderRadius="md"
                        border="1px solid"
                        borderColor="rgba(251, 191, 36, 0.3)"
                      >
                        <Text fontSize="xs" color="white" opacity={0.9}>
                          📝 {drop.specialInstructions}
                        </Text>
                      </Box>
                    )}
                  </VStack>
                </Box>
              ))}
            </VStack>
          </ModalBody>
          <ModalFooter>
            <Button onClick={onClose} colorScheme="blue">
              Close
            </Button>
          </ModalFooter>
        </ModalContent>
      </Modal>
    </Card>
  );
};

export default RouteCard;

'use client';

import React, { useState } from 'react';
import {
  Box,
  VStack,
  HStack,
  Text,
  Button,
  Badge,
  Progress,
  Icon,
  Card,
  CardBody,
  Divider,
  useColorModeValue,
  Flex,
  Circle,
  Textarea,
  Modal,
  ModalOverlay,
  ModalContent,
  ModalHeader,
  ModalBody,
  ModalFooter,
  ModalCloseButton,
  useDisclosure,
  Select,
  useToast,
  Alert,
  AlertIcon,
  Tooltip,
  Image
} from '@chakra-ui/react';
import {
  FaMapMarkerAlt,
  FaClock,
  FaCheckCircle,
  FaTruck,
  FaExclamationTriangle,
  FaPhone,
  FaCamera,
  FaForward,
  FaRoute,
  FaInfoCircle,
  FaCompass
} from 'react-icons/fa';
import { Drop, Route } from './RouteCard';

interface RouteDetailsProps {
  route: Route;
  onUpdateDropStatus?: (dropId: string, status: Drop['status'], notes?: string) => void;
  onSkipDrop?: (dropId: string, reason: string) => void;
  onCompleteRoute?: (routeId: string) => void;
  isLoading?: boolean;
}

const FAILURE_REASONS = [
  'Customer not available',
  'Address not found',
  'Access denied (security)',
  'Incorrect address details',
  'Customer refused delivery',
  'Package damaged',
  'Other (see notes)'
];

export const RouteDetails: React.FC<RouteDetailsProps> = ({
  route,
  onUpdateDropStatus,
  onSkipDrop,
  onCompleteRoute,
  isLoading = false
}) => {
  const [selectedDrop, setSelectedDrop] = useState<Drop | null>(null);
  const [failureReason, setFailureReason] = useState('');
  const [notes, setNotes] = useState('');
  const [proofPhoto, setProofPhoto] = useState<string | null>(null);
  
  const { isOpen: isFailureModalOpen, onOpen: onFailureModalOpen, onClose: onFailureModalClose } = useDisclosure();
  const { isOpen: isSkipModalOpen, onOpen: onSkipModalOpen, onClose: onSkipModalClose } = useDisclosure();
  
  const toast = useToast();
  // Use Admin dashboard styling - dark theme with neon accents
  const cardBg = 'bg.card';
  const borderColor = 'border.primary';
  const textSecondary = 'text.secondary';
  const textPrimary = 'text.primary';

  const completedDrops = route.drops.filter(drop => drop.status === 'completed').length;
  const progressPercentage = (completedDrops / route.drops.length) * 100;
  const currentDrop = route.drops.find(drop => drop.status === 'in_progress') || 
                     route.drops.find(drop => drop.status === 'assigned');

  const getDropStatusColor = (status: Drop['status']) => {
    switch (status) {
      case 'completed': return 'green';
      case 'in_progress': return 'blue';
      case 'failed': return 'red';
      case 'assigned': return 'orange';
      default: return 'gray';
    }
  };

  const formatTime = (dateString: string) => {
    return new Date(dateString).toLocaleTimeString('en-GB', {
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  const handleDropAction = (drop: Drop, action: 'start' | 'complete' | 'fail' | 'skip') => {
    switch (action) {
      case 'start':
        onUpdateDropStatus?.(drop.id, 'in_progress');
        break;
      case 'complete':
        onUpdateDropStatus?.(drop.id, 'completed', notes);
        setNotes('');
        break;
      case 'fail':
        setSelectedDrop(drop);
        onFailureModalOpen();
        break;
      case 'skip':
        setSelectedDrop(drop);
        onSkipModalOpen();
        break;
    }
  };

  const handleFailureSubmit = () => {
    if (!selectedDrop || !failureReason) {
      toast({
        title: 'Missing Information',
        description: 'Please select a failure reason',
        status: 'warning',
        duration: 3000
      });
      return;
    }

    onUpdateDropStatus?.(selectedDrop.id, 'failed', `${failureReason}: ${notes}`);
    onFailureModalClose();
    setFailureReason('');
    setNotes('');
    setSelectedDrop(null);
  };

  const handleSkipSubmit = () => {
    if (!selectedDrop || !notes) {
      toast({
        title: 'Missing Information',
        description: 'Please provide a reason for skipping',
        status: 'warning',
        duration: 3000
      });
      return;
    }

    onSkipDrop?.(selectedDrop.id, notes);
    onSkipModalClose();
    setNotes('');
    setSelectedDrop(null);
  };

  const openNavigation = (address: string) => {
    const encodedAddress = encodeURIComponent(address);
    // Try Google Maps first, fallback to Apple Maps on iOS
    const isMobile = /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);
    const isIOS = /iPhone|iPad|iPod/i.test(navigator.userAgent);
    
    if (isMobile) {
      if (isIOS) {
        window.open(`maps://maps.google.com/maps?q=${encodedAddress}`, '_blank');
      } else {
        window.open(`https://maps.google.com/maps?q=${encodedAddress}`, '_blank');
      }
    } else {
      window.open(`https://maps.google.com/maps?q=${encodedAddress}`, '_blank');
    }
  };

  return (
    <VStack spacing={6} align="stretch">
      {/* Route Header */}
      <Card bg={cardBg}>
        <CardBody>
          <VStack spacing={4}>
            <HStack justify="space-between" w="full">
              <VStack align="start" spacing={1}>
                <HStack>
                  <Icon as={FaRoute} color="blue.500" />
                  <Text fontSize="xl" fontWeight="bold">
                    Route #{route.id.slice(-8)}
                  </Text>
                </HStack>
                <Text color={textSecondary}>
                  {route.drops.length} stops • {route.estimatedDistance} km • £{route.estimatedEarnings}
                </Text>
              </VStack>
              <Badge colorScheme="blue" size="lg" p={2}>
                {route.status.toUpperCase()}
              </Badge>
            </HStack>

            {/* Progress */}
            <Box w="full">
              <Flex justify="space-between" mb={2}>
                <Text fontWeight="medium">
                  Progress: {completedDrops}/{route.drops.length} completed
                </Text>
                <Text color={textSecondary}>
                  {progressPercentage.toFixed(0)}%
                </Text>
              </Flex>
              <Progress 
                value={progressPercentage} 
                colorScheme="green" 
                size="md" 
                borderRadius="full"
              />
            </Box>

            {/* Current Drop Alert */}
            {currentDrop && (
              <Alert status="info" borderRadius="md">
                <AlertIcon />
                <VStack align="start" spacing={1} flex={1}>
                  <Text fontWeight="medium">Current Stop:</Text>
                  <Text>{currentDrop.deliveryAddress}</Text>
                  <Text fontSize="sm" color={textSecondary}>
                    Window: {formatTime(currentDrop.timeWindowStart)} - {formatTime(currentDrop.timeWindowEnd)}
                  </Text>
                </VStack>
                <Button
                  size="sm"
                  leftIcon={<Icon as={FaCompass} />}
                  onClick={() => openNavigation(currentDrop.deliveryAddress)}
                >
                  Navigate
                </Button>
              </Alert>
            )}
          </VStack>
        </CardBody>
      </Card>

      {/* Drops List */}
      <VStack spacing={3} align="stretch">
        <Text fontSize="lg" fontWeight="bold">Delivery Stops</Text>
        
        {route.drops.map((drop, index) => (
          <Card 
            key={drop.id} 
            bg={cardBg}
            borderLeft="4px solid"
            borderLeftColor={`${getDropStatusColor(drop.status)}.400`}
          >
            <CardBody>
              <VStack spacing={3} align="stretch">
                <HStack justify="space-between">
                  <HStack>
                    <Circle size="8" bg={`${getDropStatusColor(drop.status)}.100`}>
                      <Text fontSize="sm" fontWeight="bold" color={`${getDropStatusColor(drop.status)}.600`}>
                        {index + 1}
                      </Text>
                    </Circle>
                    <VStack align="start" spacing={1}>
                      <Text fontWeight="medium">{drop.customerName}</Text>
                      <HStack>
                        <Icon as={FaMapMarkerAlt} color={textSecondary} size="sm" />
                        <Text fontSize="sm" color={textSecondary}>
                          {drop.deliveryAddress}
                        </Text>
                      </HStack>
                      <HStack spacing={3}>
                        <HStack>
                          <Icon as={FaClock} color={textSecondary} size="sm" />
                          <Text fontSize="sm" color={textSecondary}>
                            {formatTime(drop.timeWindowStart)} - {formatTime(drop.timeWindowEnd)}
                          </Text>
                        </HStack>
                        <Badge colorScheme={drop.serviceTier === 'premium' ? 'purple' : 'blue'}>
                          {drop.serviceTier}
                        </Badge>
                      </HStack>
                    </VStack>
                  </HStack>
                  
                  <Badge colorScheme={getDropStatusColor(drop.status)} variant="solid">
                    {drop.status.toUpperCase()}
                  </Badge>
                </HStack>

                {drop.specialInstructions && (
                  <HStack>
                    <Icon as={FaInfoCircle} color="blue.400" />
                    <Text fontSize="sm" fontStyle="italic">
                      {drop.specialInstructions}
                    </Text>
                  </HStack>
                )}

                {drop.estimatedArrival && (
                  <Text fontSize="sm" color="green.500" fontWeight="medium">
                    ETA: {formatTime(drop.estimatedArrival)}
                  </Text>
                )}

                <Divider />

                {/* Action Buttons */}
                <HStack spacing={2} justify="end">
                  <Button
                    size="sm"
                    leftIcon={<Icon as={FaCompass} />}
                    variant="outline"
                    onClick={() => openNavigation(drop.deliveryAddress)}
                  >
                    Navigate
                  </Button>

                  {drop.status === 'assigned' && (
                    <Button
                      size="sm"
                      colorScheme="blue"
                      onClick={() => handleDropAction(drop, 'start')}
                      isLoading={isLoading}
                    >
                      Start
                    </Button>
                  )}

                  {drop.status === 'in_progress' && (
                    <>
                      <Button
                        size="sm"
                        colorScheme="green"
                        leftIcon={<Icon as={FaCheckCircle} />}
                        onClick={() => handleDropAction(drop, 'complete')}
                        isLoading={isLoading}
                      >
                        Complete
                      </Button>
                      <Button
                        size="sm"
                        colorScheme="red"
                        variant="outline"
                        leftIcon={<Icon as={FaExclamationTriangle} />}
                        onClick={() => handleDropAction(drop, 'fail')}
                      >
                        Failed
                      </Button>
                      <Button
                        size="sm"
                        variant="ghost"
                        leftIcon={<Icon as={FaForward} />}
                        onClick={() => handleDropAction(drop, 'skip')}
                      >
                        Skip
                      </Button>
                    </>
                  )}
                </HStack>
              </VStack>
            </CardBody>
          </Card>
        ))}
      </VStack>

      {/* Complete Route Button */}
      {completedDrops === route.drops.length && route.status !== 'completed' && (
        <Button
          size="lg"
          colorScheme="green"
          onClick={() => onCompleteRoute?.(route.id)}
          isLoading={isLoading}
          loadingText="Completing Route..."
        >
          Complete Route
        </Button>
      )}

      {/* Failure Modal */}
      <Modal isOpen={isFailureModalOpen} onClose={onFailureModalClose}>
        <ModalOverlay />
        <ModalContent>
          <ModalHeader>Report Delivery Failure</ModalHeader>
          <ModalCloseButton />
          <ModalBody>
            <VStack spacing={4} align="stretch">
              <Box>
                <Text mb={2} fontWeight="medium">Reason for failure:</Text>
                <Select
                  placeholder="Select a reason"
                  value={failureReason}
                  onChange={(e) => setFailureReason(e.target.value)}
                >
                  {FAILURE_REASONS.map(reason => (
                    <option key={reason} value={reason}>{reason}</option>
                  ))}
                </Select>
              </Box>

              <Box>
                <Text mb={2} fontWeight="medium">Additional notes:</Text>
                <Textarea
                  placeholder="Provide additional details about the failure..."
                  value={notes}
                  onChange={(e) => setNotes(e.target.value)}
                  rows={3}
                />
              </Box>
            </VStack>
          </ModalBody>
          <ModalFooter>
            <Button variant="ghost" mr={3} onClick={onFailureModalClose}>
              Cancel
            </Button>
            <Button colorScheme="red" onClick={handleFailureSubmit}>
              Submit Failure
            </Button>
          </ModalFooter>
        </ModalContent>
      </Modal>

      {/* Skip Modal */}
      <Modal isOpen={isSkipModalOpen} onClose={onSkipModalClose}>
        <ModalOverlay />
        <ModalContent>
          <ModalHeader>Skip Delivery</ModalHeader>
          <ModalCloseButton />
          <ModalBody>
            <VStack spacing={4} align="stretch">
              <Text color={textSecondary}>
                This will temporarily skip this delivery and continue with the next stop. 
                You can return to this delivery later.
              </Text>

              <Box>
                <Text mb={2} fontWeight="medium">Reason for skipping:</Text>
                <Textarea
                  placeholder="Why are you skipping this delivery? (e.g., customer not available, will return later)"
                  value={notes}
                  onChange={(e) => setNotes(e.target.value)}
                  rows={3}
                />
              </Box>
            </VStack>
          </ModalBody>
          <ModalFooter>
            <Button variant="ghost" mr={3} onClick={onSkipModalClose}>
              Cancel
            </Button>
            <Button colorScheme="orange" onClick={handleSkipSubmit}>
              Skip for Now
            </Button>
          </ModalFooter>
        </ModalContent>
      </Modal>
    </VStack>
  );
};

export default RouteDetails;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import {
  Alert,
  AlertIcon,
  AlertTitle,
  AlertDescription,
  Box,
  VStack,
  HStack,
  Button,
  Text,
  Badge,
  CloseButton,
  Flex,
  Progress,
  Icon,
  useColorModeValue,
  ScaleFade,
  Collapse,
  useDisclosure,
  IconButton,
  Tooltip,
} from '@chakra-ui/react';
import { useAudioNotification, showJobNotificationWithSound } from './AudioNotification';
import {
  FaBell,
  FaMapMarkerAlt,
  FaClock,
  FaExclamationTriangle,
  FaCheckCircle,
  FaInfoCircle,
  FaChevronUp,
  FaChevronDown,
  FaLocationArrow,
  FaRoute,
} from 'react-icons/fa';

interface SmartAlert {
  id: string;
  type: 'location' | 'time' | 'status' | 'proximity' | 'system';
  priority: 'low' | 'medium' | 'high' | 'urgent';
  title: string;
  message: string;
  timestamp: Date;
  actions?: Array<{
    label: string;
    action: string;
    style?: 'primary' | 'secondary' | 'success' | 'warning' | 'danger';
  }>;
  autoHide?: boolean;
  hideAfter?: number; // milliseconds
  progress?: number; // 0-100 for progress bars
  location?: {
    lat: number;
    lng: number;
    address?: string;
  };
}

interface SmartNotificationsProps {
  alerts: SmartAlert[];
  onActionClick?: (alertId: string, action: string) => void;
  onDismiss?: (alertId: string) => void;
  maxVisible?: number;
  compactMode?: boolean;
}

const SmartNotifications: React.FC<SmartNotificationsProps> = ({
  alerts,
  onActionClick,
  onDismiss,
  maxVisible = 3,
  compactMode = false,
}) => {
  const [visibleAlerts, setVisibleAlerts] = useState<SmartAlert[]>([]);
  const [expandedAlerts, setExpandedAlerts] = useState<Set<string>>(new Set());
  const [processedAlerts, setProcessedAlerts] = useState<Set<string>>(new Set());
  const { isOpen: showAll, onToggle: toggleShowAll } = useDisclosure();
  const audioNotification = useAudioNotification();

  const bg = useColorModeValue('white', 'gray.800');
  const borderColor = useColorModeValue('gray.200', 'gray.600');

  // Sort alerts by priority and timestamp - memoized to prevent re-creation on every render
  const sortedAlerts = useMemo(() => {
    return [...alerts].sort((a, b) => {
      const priorityOrder = { urgent: 4, high: 3, medium: 2, low: 1 };
      const priorityDiff = priorityOrder[b.priority] - priorityOrder[a.priority];
      if (priorityDiff !== 0) return priorityDiff;
      return b.timestamp.getTime() - a.timestamp.getTime();
    });
  }, [alerts]);

  // Memoized dismiss handler to prevent re-creation on every render
  const handleDismiss = useCallback((alertId: string) => {
    setVisibleAlerts(prev => prev.filter(alert => alert.id !== alertId));
    if (onDismiss) {
      onDismiss(alertId);
    }
  }, [onDismiss]);

  // Update visible alerts
  useEffect(() => {
    const alertsToShow = showAll ? sortedAlerts : sortedAlerts.slice(0, maxVisible);
    setVisibleAlerts(alertsToShow);
  }, [sortedAlerts, maxVisible, showAll]);

  // Auto-hide alerts
  useEffect(() => {
    const timers: ReturnType<typeof setTimeout>[] = [];

    visibleAlerts.forEach(alert => {
      if (alert.autoHide && alert.hideAfter) {
        const timer = setTimeout(() => {
          handleDismiss(alert.id);
        }, alert.hideAfter);
        timers.push(timer);
      }
    });

    return () => {
      timers.forEach(timer => clearTimeout(timer));
    };
  }, [visibleAlerts, handleDismiss]);

  // Handle audio notifications for new alerts
  useEffect(() => {
    alerts.forEach(alert => {
      // Only play sound for new unprocessed alerts
      if (!processedAlerts.has(alert.id)) {
        setProcessedAlerts(prev => new Set([...prev, alert.id]));
        
        // Play sound based on alert type and priority
        const playNotificationSound = async () => {
          try {
            console.log(`🔊 New job alert received: ${alert.title}`);
            
            if (alert.priority === 'urgent' || alert.priority === 'high') {
              // Play urgent notification with browser notification
              await showJobNotificationWithSound(
                alert.title,
                alert.message,
                {
                  urgent: alert.priority === 'urgent',
                  requireInteraction: alert.priority === 'urgent',
                }
              );
            } else {
              // Play regular notification sound
              await audioNotification.play('job-notification');
            }
          } catch (error) {
            console.error('❌ Failed to play notification sound:', error);
          }
        };

        // Play sound only for important notifications:
        // 1. New job offers (high priority)
        // 2. Job acceptance confirmations 
        // 3. Proximity alerts when near destination
        // 4. Urgent system alerts
        // NOT for routine status updates or progress tracking
        const shouldPlaySound = (
          (alert.type === 'status' && (
            alert.title.includes('New Job') || 
            alert.title.includes('Job Offer') || 
            alert.title.includes('Accepted Successfully')
          )) ||
          alert.type === 'proximity' ||
          alert.priority === 'urgent'
        );
        
        if (shouldPlaySound) {
          playNotificationSound();
        }
      }
    });

    // Clean up old processed alerts (keep only recent ones)
    const currentAlertIds = new Set(alerts.map(alert => alert.id));
    setProcessedAlerts(prev => {
      const filtered = new Set<string>();
      prev.forEach(id => {
        if (currentAlertIds.has(id)) {
          filtered.add(id);
        }
      });
      return filtered;
    });
  }, [alerts, processedAlerts, audioNotification]);

  const handleAction = useCallback((alertId: string, action: string) => {
    if (onActionClick) {
      onActionClick(alertId, action);
    }
  }, [onActionClick]);

  const toggleExpanded = (alertId: string) => {
    setExpandedAlerts(prev => {
      const newSet = new Set(prev);
      if (newSet.has(alertId)) {
        newSet.delete(alertId);
      } else {
        newSet.add(alertId);
      }
      return newSet;
    });
  };

  const getAlertIcon = (type: SmartAlert['type']) => {
    switch (type) {
      case 'location': return FaMapMarkerAlt;
      case 'time': return FaClock;
      case 'proximity': return FaLocationArrow;
      case 'status': return FaCheckCircle;
      case 'system': return FaInfoCircle;
      default: return FaBell;
    }
  };

  const getAlertStatus = (priority: SmartAlert['priority']) => {
    switch (priority) {
      case 'urgent': return 'error';
      case 'high': return 'warning';
      case 'medium': return 'info';
      case 'low': return 'success';
      default: return 'info';
    }
  };

  const getPriorityColor = (priority: SmartAlert['priority']) => {
    switch (priority) {
      case 'urgent': return 'red';
      case 'high': return 'orange';
      case 'medium': return 'yellow';
      case 'low': return 'green';
      default: return 'blue';
    }
  };

  const formatTimeAgo = (timestamp: Date) => {
    const now = new Date();
    const diff = now.getTime() - timestamp.getTime();
    const minutes = Math.floor(diff / 60000);
    
    if (minutes < 1) return 'Just now';
    if (minutes < 60) return `${minutes}m ago`;
    const hours = Math.floor(minutes / 60);
    if (hours < 24) return `${hours}h ago`;
    return `${Math.floor(hours / 24)}d ago`;
  };

  if (visibleAlerts.length === 0) {
    return null;
  }

  return (
    <Box width="100%" maxWidth="500px">
      <VStack spacing={2} align="stretch">
        {visibleAlerts.map((alert) => {
          const isExpanded = expandedAlerts.has(alert.id);
          const AlertIcon = getAlertIcon(alert.type);
          
          return (
            <ScaleFade key={alert.id} initialScale={0.9} in={true}>
              <Alert
                status={getAlertStatus(alert.priority)}
                variant="subtle"
                borderRadius="lg"
                bg={bg}
                border="1px"
                borderColor={borderColor}
                boxShadow="sm"
                p={compactMode ? 3 : 4}
              >
                <Icon as={AlertIcon} />
                <Box flex="1" ml={2}>
                  <Flex justify="space-between" align="flex-start">
                    <VStack align="flex-start" spacing={1} flex="1">
                      <HStack spacing={2}>
                        <AlertTitle fontSize={compactMode ? 'sm' : 'md'} mb={0}>
                          {alert.title}
                        </AlertTitle>
                        <Badge
                          colorScheme={getPriorityColor(alert.priority)}
                          size="sm"
                          textTransform="uppercase"
                        >
                          {alert.priority}
                        </Badge>
                        <Text fontSize="xs" color="gray.500">
                          {formatTimeAgo(alert.timestamp)}
                        </Text>
                      </HStack>
                      
                      <AlertDescription fontSize={compactMode ? 'xs' : 'sm'}>
                        {alert.message}
                      </AlertDescription>

                      {/* Progress bar for time-sensitive alerts */}
                      {alert.progress !== undefined && (
                        <Box width="100%" mt={2}>
                          <Progress 
                            value={alert.progress} 
                            size="sm" 
                            colorScheme={getPriorityColor(alert.priority)}
                            borderRadius="full"
                          />
                          <Text fontSize="xs" color="gray.500" mt={1}>
                            {alert.progress}% complete
                          </Text>
                        </Box>
                      )}

                      {/* Location info */}
                      {alert.location && isExpanded && (
                        <Box mt={2} p={2} bg="gray.50" borderRadius="md" width="100%">
                          <HStack spacing={2}>
                            <Icon as={FaMapMarkerAlt} color="blue.500" />
                            <VStack align="flex-start" spacing={0}>
                              <Text fontSize="xs" fontWeight="bold">Location</Text>
                              {alert.location.address ? (
                                <Text fontSize="xs">{alert.location.address}</Text>
                              ) : (
                                <Text fontSize="xs">
                                  {alert.location.lat.toFixed(6)}, {alert.location.lng.toFixed(6)}
                                </Text>
                              )}
                            </VStack>
                          </HStack>
                        </Box>
                      )}

                      {/* Action buttons */}
                      {alert.actions && alert.actions.length > 0 && (
                        <Collapse in={isExpanded} animateOpacity>
                          <HStack spacing={2} mt={2} flexWrap="wrap">
                            {alert.actions.map((action, index) => (
                              <Button
                                key={index}
                                size="sm"
                                variant={action.style === 'primary' ? 'solid' : 'outline'}
                                colorScheme={
                                  action.style === 'danger' ? 'red' :
                                  action.style === 'warning' ? 'orange' :
                                  action.style === 'success' ? 'green' :
                                  'blue'
                                }
                                onClick={() => handleAction(alert.id, action.action)}
                              >
                                {action.label}
                              </Button>
                            ))}
                          </HStack>
                        </Collapse>
                      )}
                    </VStack>

                    {/* Alert controls */}
                    <HStack spacing={1}>
                      {(alert.actions?.length || alert.location) && (
                        <Tooltip label={isExpanded ? 'Collapse' : 'Expand details'}>
                          <IconButton
                            aria-label="Toggle details"
                            icon={isExpanded ? <FaChevronUp /> : <FaChevronDown />}
                            size="sm"
                            variant="ghost"
                            onClick={() => toggleExpanded(alert.id)}
                          />
                        </Tooltip>
                      )}
                      
                      <Tooltip label="Dismiss">
                        <CloseButton
                          size="sm"
                          onClick={() => handleDismiss(alert.id)}
                        />
                      </Tooltip>
                    </HStack>
                  </Flex>
                </Box>
              </Alert>
            </ScaleFade>
          );
        })}

        {/* Show more/less button */}
        {sortedAlerts.length > maxVisible && (
          <Button
            variant="ghost"
            size="sm"
            onClick={toggleShowAll}
            leftIcon={showAll ? <FaChevronUp /> : <FaChevronDown />}
          >
            {showAll 
              ? `Show fewer (${maxVisible})` 
              : `Show all (${sortedAlerts.length - maxVisible} more)`
            }
          </Button>
        )}
      </VStack>
    </Box>
  );
};

// Helper function to create alerts
export const createSmartAlert = (
  type: SmartAlert['type'],
  priority: SmartAlert['priority'],
  title: string,
  message: string,
  options?: Partial<Pick<SmartAlert, 'actions' | 'autoHide' | 'hideAfter' | 'progress' | 'location'>>
): SmartAlert => ({
  id: `alert_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
  type,
  priority,
  title,
  message,
  timestamp: new Date(),
  ...options,
});

// Pre-built alert types for common scenarios
export const createProximityAlert = (
  location: string,
  distance: number,
  actions?: SmartAlert['actions']
): SmartAlert => createSmartAlert(
  'proximity',
  'medium',
  'Near Destination',
  `You are ${distance}m away from ${location}`,
  { actions, autoHide: true, hideAfter: 10000 }
);

