import { useRouter, useSearchParams } from 'next/navigation';
import { useCallback } from 'react';

/**
 * Custom hook to handle authentication redirect logic
 * Provides utilities for managing returnTo URLs and redirects after authentication
 */
export function useAuthRedirect() {
  const router = useRouter();
  const searchParams = useSearchParams();

  // Get returnTo from query params, with fallback to document.referrer
  const returnTo =
    searchParams?.get('returnTo') ||
    searchParams?.get('callbackUrl') ||
    (typeof window !== 'undefined' ? document.referrer : null);

  /**
   * Handle redirect after successful authentication
   * Cleans up URL parameters and redirects to the appropriate destination
   */
  const handleAuthRedirect = useCallback(() => {
    if (typeof window === 'undefined') return;

    // Clean up URL parameters after successful auth
    const url = new URL(window.location.href);
    url.searchParams.delete('returnTo');
    url.searchParams.delete('callbackUrl');
    url.searchParams.delete('showAuth');

    // Determine redirect destination
    let redirectUrl = '/';

    if (returnTo) {
      // Validate returnTo URL to prevent open redirects
      try {
        const returnToUrl = new URL(returnTo, window.location.origin);
        // Only allow same-origin redirects
        if (returnToUrl.origin === window.location.origin) {
          redirectUrl =
            returnToUrl.pathname + returnToUrl.search + returnToUrl.hash;
        }
      } catch (error) {
        console.warn('Invalid returnTo URL:', returnTo);
      }
    }

    // Update URL without the auth parameters
    window.history.replaceState({}, '', url.toString());

    // Perform redirect
    if (redirectUrl === '/') {
      // Default landing: stay on home page
      // No auto-redirect away from Home unless user came from a protected page
      router.replace('/');
    } else {
      router.replace(redirectUrl);
    }
  }, [returnTo, router]);

  /**
   * Check if the current URL has auth parameters
   */
  const hasAuthParams = useCallback(() => {
    return !!(
      searchParams?.get('returnTo') ||
      searchParams?.get('callbackUrl') ||
      searchParams?.get('showAuth')
    );
  }, [searchParams]);

  /**
   * Get the clean returnTo URL (validated and sanitized)
   */
  const getValidReturnTo = useCallback(() => {
    if (!returnTo) return null;

    try {
      const returnToUrl = new URL(
        returnTo,
        typeof window !== 'undefined'
          ? window.location.origin
          : 'http://localhost'
      );
      // Only allow same-origin redirects
      if (
        returnToUrl.origin ===
        (typeof window !== 'undefined'
          ? window.location.origin
          : 'http://localhost')
      ) {
        return returnToUrl.pathname + returnToUrl.search + returnToUrl.hash;
      }
    } catch (error) {
      console.warn('Invalid returnTo URL:', returnTo);
    }

    return null;
  }, [returnTo]);

  return {
    returnTo,
    handleAuthRedirect,
    hasAuthParams,
    getValidReturnTo,
  };
}

import { useState, useEffect, useCallback, useRef } from 'react';
import { useToast } from '@chakra-ui/react';

interface AutoStatusConfig {
  jobId: string;
  currentStep: string;
  driverId: string;
  enableGeoTracking?: boolean;
  enableTimeTracking?: boolean;
  enableProximityDetection?: boolean;
  proximityRadius?: number; // in meters
  autoAdvanceSteps?: boolean;
  notificationEnabled?: boolean;
}

interface LocationData {
  latitude: number;
  longitude: number;
  accuracy?: number;
  timestamp: number;
}

interface StepTrigger {
  step: string;
  condition: 'location' | 'time' | 'manual' | 'proximity';
  data?: any;
}

const STEP_SEQUENCE = [
  'navigate_to_pickup',
  'arrived_at_pickup',
  'loading_started',
  'loading_completed',
  'en_route_to_dropoff',
  'arrived_at_dropoff',
  'unloading_started',
  'unloading_completed',
  'customer_signature',
  'job_completed'
];

export const useAutoStatusUpdates = (config: AutoStatusConfig) => {
  const [currentLocation, setCurrentLocation] = useState<LocationData | null>(null);
  const [isTracking, setIsTracking] = useState(false);
  const [autoUpdatesEnabled, setAutoUpdatesEnabled] = useState(true);
  const [locationHistory, setLocationHistory] = useState<LocationData[]>([]);
  const [proximityAlerts, setProximityAlerts] = useState<string[]>([]);
  
  const toast = useToast();
  const watchIdRef = useRef<number | null>(null);
  const lastUpdateRef = useRef<number>(0);

  // Early return if config is not ready (but hooks are still called)
  const isConfigReady = config.jobId && config.driverId !== 'pending' && config.enableGeoTracking;

  // Get current step index in sequence
  const getCurrentStepIndex = useCallback(() => {
    return STEP_SEQUENCE.indexOf(config.currentStep);
  }, [config.currentStep]);

  // Check if next step should be auto-triggered
  const shouldAutoAdvanceToStep = useCallback((nextStep: string): boolean => {
    if (!config.autoAdvanceSteps) return false;
    
    const currentIndex = getCurrentStepIndex();
    const nextIndex = STEP_SEQUENCE.indexOf(nextStep);
    
    return nextIndex === currentIndex + 1;
  }, [config.autoAdvanceSteps, getCurrentStepIndex]);

  // Calculate distance between two coordinates (Haversine formula)
  const calculateDistance = useCallback(( // DEPRECATED - internal use only
    lat1: number, lon1: number, 
    lat2: number, lon2: number
  ): number => {
    const R = 6371e3; // Earth's radius in meters
    const φ1 = lat1 * Math.PI / 180;
    const φ2 = lat2 * Math.PI / 180;
    const Δφ = (lat2 - lat1) * Math.PI / 180;
    const Δλ = (lon2 - lon1) * Math.PI / 180;

    const a = Math.sin(Δφ/2) * Math.sin(Δφ/2) +
              Math.cos(φ1) * Math.cos(φ2) *
              Math.sin(Δλ/2) * Math.sin(Δλ/2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));

    return R * c;
  }, []);

  // Update job step via API
  const updateJobStep = useCallback(async (
    newStep: string, 
    trigger: StepTrigger,
    locationData?: LocationData
  ) => {
    try {
      const response = await fetch(`/api/driver/jobs/${config.jobId}/update-step`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          step: newStep,
          driverId: config.driverId,
          trigger,
          location: locationData,
          timestamp: new Date().toISOString(),
        }),
      });

      if (!response.ok) {
        throw new Error('Failed to update job step');
      }

      const result = await response.json();
      
      if (config.notificationEnabled) {
        toast({
          title: 'Status Updated',
          description: `Job step updated to: ${newStep}`,
          status: 'success',
          duration: 3000,
        });
      }

      return result;
    } catch (error) {
      console.error('Auto status update failed:', error);
      
      toast({
        title: 'Update Failed',
        description: 'Failed to update job status automatically',
        status: 'error',
        duration: 5000,
      });
      
      throw error;
    }
  }, [config.jobId, config.driverId, config.notificationEnabled, toast]);

  // Check proximity to pickup/dropoff locations
  const checkProximityTriggers = useCallback(async (location: LocationData) => {
    if (!isConfigReady || !config.enableProximityDetection) return;

    try {
      const response = await fetch(`/api/driver/jobs/${config.jobId}/details`);
      const jobDetails = await response.json();

      const pickupLocation = jobDetails.pickup_location;
      const dropoffLocation = jobDetails.dropoff_location;
      const proximityRadius = config.proximityRadius || 100; // 100m default

      // Check proximity to pickup
      if (pickupLocation && config.currentStep === 'navigate_to_pickup') {
        const distanceToPickup = calculateDistance( // DEPRECATED - internal use only
          location.latitude,
          location.longitude,
          pickupLocation.latitude,
          pickupLocation.longitude
        );

        if (distanceToPickup <= proximityRadius) {
          if (shouldAutoAdvanceToStep('arrived_at_pickup')) {
            await updateJobStep('arrived_at_pickup', {
              step: 'arrived_at_pickup',
              condition: 'proximity',
              data: { distance: distanceToPickup, radius: proximityRadius }
            }, location);
          } else {
            setProximityAlerts(prev => [...prev, 'Near pickup location']);
          }
        }
      }

      // Check proximity to dropoff
      if (dropoffLocation && config.currentStep === 'en_route_to_dropoff') {
        const distanceToDropoff = calculateDistance( // DEPRECATED - internal use only
          location.latitude,
          location.longitude,
          dropoffLocation.latitude,
          dropoffLocation.longitude
        );

        if (distanceToDropoff <= proximityRadius) {
          if (shouldAutoAdvanceToStep('arrived_at_dropoff')) {
            await updateJobStep('arrived_at_dropoff', {
              step: 'arrived_at_dropoff',
              condition: 'proximity',
              data: { distance: distanceToDropoff, radius: proximityRadius }
            }, location);
          } else {
            setProximityAlerts(prev => [...prev, 'Near dropoff location']);
          }
        }
      }
    } catch (error) {
      console.error('Proximity check failed:', error);
    }
  }, [
    isConfigReady,
    config.enableProximityDetection,
    config.proximityRadius,
    config.jobId,
    config.currentStep,
    calculateDistance, // DEPRECATED - internal use only
    shouldAutoAdvanceToStep,
    updateJobStep
  ]);

  // Handle location updates
  const handleLocationUpdate = useCallback((position: GeolocationPosition) => {
    const locationData: LocationData = {
      latitude: position.coords.latitude,
      longitude: position.coords.longitude,
      accuracy: position.coords.accuracy,
      timestamp: Date.now(),
    };

    setCurrentLocation(locationData);
    setLocationHistory(prev => [...prev.slice(-49), locationData]); // Keep last 50 locations

    // Throttle API calls (max once per 30 seconds)
    const now = Date.now();
    if (now - lastUpdateRef.current >= 30000) {
      lastUpdateRef.current = now;
      
      // Send location to tracking endpoint only if config is ready
      if (isConfigReady) {
        fetch(`/api/driver/tracking`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            bookingId: config.jobId,
            latitude: locationData.latitude,
            longitude: locationData.longitude,
            accuracy: locationData.accuracy,
          }),
        }).catch(error => {
          console.error('Location tracking failed:', error);
          // Optionally show a toast notification for tracking issues
        });
      }

      // Check proximity triggers
      checkProximityTriggers(locationData);
    }
  }, [isConfigReady, config.driverId, config.jobId, checkProximityTriggers]);

  // Handle geolocation errors
  const handleLocationError = useCallback((error: GeolocationPositionError) => {
    console.error('Geolocation error:', error);
    
    let message = 'Location access failed';
    switch (error.code) {
      case error.PERMISSION_DENIED:
        message = 'Location access denied. Please enable GPS permissions.';
        break;
      case error.POSITION_UNAVAILABLE:
        message = 'Location information unavailable';
        break;
      case error.TIMEOUT:
        message = 'Location request timed out';
        break;
    }

    toast({
      title: 'Location Error',
      description: message,
      status: 'warning',
      duration: 5000,
    });

    setIsTracking(false);
  }, [toast]);

  // Start location tracking
  const startTracking = useCallback(() => {
    if (!isConfigReady || !config.enableGeoTracking) return;

    if ('geolocation' in navigator) {
      const options: PositionOptions = {
        enableHighAccuracy: true,
        timeout: 10000,
        maximumAge: 30000, // 30 seconds
      };

      watchIdRef.current = navigator.geolocation.watchPosition(
        handleLocationUpdate,
        handleLocationError,
        options
      );

      setIsTracking(true);
    } else {
      toast({
        title: 'Geolocation Not Supported',
        description: 'Your device does not support location tracking',
        status: 'error',
        duration: 5000,
      });
    }
  }, [isConfigReady, config.enableGeoTracking, handleLocationUpdate, handleLocationError, toast]);

  // Stop location tracking
  const stopTracking = useCallback(() => {
    if (watchIdRef.current !== null) {
      navigator.geolocation.clearWatch(watchIdRef.current);
      watchIdRef.current = null;
    }
    setIsTracking(false);
  }, []);

  // Manual step update with validation
  const manualUpdateStep = useCallback(async (newStep: string) => {
    const trigger: StepTrigger = {
      step: newStep,
      condition: 'manual',
      data: { previousStep: config.currentStep }
    };

    return updateJobStep(newStep, trigger, currentLocation || undefined);
  }, [config.currentStep, updateJobStep, currentLocation]);

  // Time-based triggers (for future implementation)
  const checkTimeBasedTriggers = useCallback(() => {
    if (!config.enableTimeTracking) return;

    // Implement time-based logic here
    // e.g., auto-advance after certain duration in a step
  }, [config.enableTimeTracking]);

  // Initialize tracking on mount only if config is ready
  useEffect(() => {
    if (isConfigReady && autoUpdatesEnabled && config.enableGeoTracking) {
      startTracking();
    }

    return () => {
      stopTracking();
    };
  }, [isConfigReady, autoUpdatesEnabled, config.enableGeoTracking, startTracking, stopTracking]);

  // Clear proximity alerts after some time
  useEffect(() => {
    if (proximityAlerts.length > 0) {
      const timer = setTimeout(() => {
        setProximityAlerts([]);
      }, 10000); // Clear after 10 seconds

      return () => clearTimeout(timer);
    }
  }, [proximityAlerts]);

  return {
    // State
    currentLocation,
    isTracking: isConfigReady && isTracking,
    autoUpdatesEnabled,
    locationHistory,
    proximityAlerts,

    // Actions
    startTracking,
    stopTracking,
    manualUpdateStep,
    setAutoUpdatesEnabled,

    // Utilities
    getCurrentStepIndex,
    shouldAutoAdvanceToStep,
    calculateDistance, // DEPRECATED - internal use only

    // Config state
    isConfigReady,
  };
};

export default useAutoStatusUpdates;

import { useState, useEffect, useCallback } from 'react';
import { useSession } from 'next-auth/react';
// import { CustomerBooking } from '@/lib/customer-bookings';

interface CustomerBooking {
  id: string;
  reference: string;
  status: string;
}

interface UseCustomerBookingsReturn {
  bookings: {
    linkedBookings: CustomerBooking[];
    unlinkedBookings: CustomerBooking[];
    totalCount: number;
  } | null;
  stats: any;
  loading: boolean;
  error: string | null;
  refreshBookings: () => Promise<void>;
  linkExistingBookings: (
    email: string,
    phone: string
  ) => Promise<{
    success: boolean;
    message: string;
    linkedCount: number;
  }>;
  linkSpecificBooking: (bookingId: string) => Promise<{
    success: boolean;
    message: string;
  }>;
}

export function useCustomerBookings(): UseCustomerBookingsReturn {
  const { data: session, status } = useSession();
  const [bookings, setBookings] = useState<{
    linkedBookings: CustomerBooking[];
    unlinkedBookings: CustomerBooking[];
    totalCount: number;
  } | null>(null);
  const [stats, setStats] = useState<any>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const fetchBookings = useCallback(async () => {
    const userId = (session?.user as any)?.id as string | undefined;
    if (!userId) return;

    try {
      setLoading(true);
      setError(null);

      const response = await fetch('/api/customer/bookings');
      if (!response.ok) {
        throw new Error('Failed to fetch bookings');
      }

      const data = await response.json();
      setBookings(data);
    } catch (error) {
      console.error('Error fetching bookings:', error);
      setError(error instanceof Error ? error.message : 'Unknown error');
    } finally {
      setLoading(false);
    }
  }, [(session?.user as any)?.id]);

  const fetchStats = useCallback(async () => {
    const userId = (session?.user as any)?.id as string | undefined;
    if (!userId) return;

    try {
      const response = await fetch('/api/customer/bookings', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'get_stats' }),
      });

      if (response.ok) {
        const data = await response.json();
        setStats(data.stats);
      }
    } catch (error) {
      console.error('Error fetching stats:', error);
    }
  }, [(session?.user as any)?.id]);

  const refreshBookings = useCallback(async () => {
    await Promise.all([fetchBookings(), fetchStats()]);
  }, [fetchBookings, fetchStats]);

  const linkExistingBookings = useCallback(
    async (email: string, phone: string) => {
      const userId = (session?.user as any)?.id as string | undefined;
      if (!userId) {
        return {
          success: false,
          message: 'User not authenticated',
          linkedCount: 0,
        };
      }

      try {
        const response = await fetch('/api/customer/bookings', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            action: 'link_existing',
            data: { email, phone },
          }),
        });

        if (!response.ok) {
          throw new Error('Failed to link existing bookings');
        }

        const data = await response.json();

        // Refresh bookings after linking
        await refreshBookings();

        return {
          success: true,
          message: data.message,
          linkedCount: data.linkedBookings,
        };
      } catch (error) {
        console.error('Error linking existing bookings:', error);
        return {
          success: false,
          message: error instanceof Error ? error.message : 'Unknown error',
          linkedCount: 0,
        };
      }
    },
    [(session?.user as any)?.id, refreshBookings]
  );

  const linkSpecificBooking = useCallback(
    async (bookingId: string) => {
      const userId = (session?.user as any)?.id as string | undefined;
      if (!userId) {
        return {
          success: false,
          message: 'User not authenticated',
        };
      }

      try {
        const response = await fetch(
          `/api/customer/bookings/${bookingId}/link`,
          {
            method: 'POST',
          }
        );

        if (!response.ok) {
          const errorData = await response.json();
          throw new Error(errorData.error || 'Failed to link booking');
        }

        const data = await response.json();

        // Refresh bookings after linking
        await refreshBookings();

        return {
          success: true,
          message: data.message,
        };
      } catch (error) {
        console.error('Error linking specific booking:', error);
        return {
          success: false,
          message: error instanceof Error ? error.message : 'Unknown error',
        };
      }
    },
    [(session?.user as any)?.id, refreshBookings]
  );

  // Fetch bookings when session changes
  useEffect(() => {
    if (status === 'authenticated' && (session?.user as any)?.id) {
      refreshBookings();
    }
  }, [status, (session?.user as any)?.id, refreshBookings]);

  return {
    bookings,
    stats,
    loading,
    error,
    refreshBookings,
    linkExistingBookings,
    linkSpecificBooking,
  };
}

