  const [metrics, setMetrics] = useState({
    connectionUptime: 0,
    messageCount: 0,
    errorCount: 0,
    averageLatency: 0,
  });

  useEffect(() => {
    const interval = setInterval(() => {
      // In a real implementation, you'd collect these metrics
      // from the real-time manager and cache system
      setMetrics(prev => ({
        ...prev,
        connectionUptime: Date.now(),
      }));
    }, 5000);

    return () => clearInterval(interval);
  }, []);

  return metrics;
}

/**
 * Role-based redirect hook for Speedy Van
 */

import { useEffect } from 'react';
import { useSession } from 'next-auth/react';
import { useRouter } from 'next/navigation';
import { getDefaultRoute, type UserRole } from '@/lib/routing';

interface UseRoleBasedRedirectOptions {
  redirectTo?: string;
  requireAuth?: boolean;
  allowedRoles?: UserRole[];
}

export function useRoleBasedRedirect(options: UseRoleBasedRedirectOptions = {}) {
  const { data: session, status } = useSession();
  const router = useRouter();

  const {
    redirectTo,
    requireAuth = true,
    allowedRoles,
  } = options;

  useEffect(() => {
    if (status === 'loading') {
      return; // Still loading
    }

    if (!session && requireAuth) {
      // Not authenticated and auth is required
      router.push('/auth/login');
      return;
    }

    const role = (session?.user as any)?.role as UserRole | undefined;
    if (session && allowedRoles && (!role || !allowedRoles.includes(role))) {
      // User doesn't have required role
      const defaultRoute = getDefaultRoute(role || 'customer');
      router.push(defaultRoute);
      return;
    }

    if (session && redirectTo) {
      // Redirect to specified route
      router.push(redirectTo);
      return;
    }

    if (session && !redirectTo) {
      // Redirect to user's default route
      const defaultRoute = getDefaultRoute(((session?.user as any)?.role as UserRole) || 'customer');
      router.push(defaultRoute);
      return;
    }
  }, [session, status, router, redirectTo, requireAuth, allowedRoles]);

  return {
    user: session?.user,
    isLoading: status === 'loading',
    role: (session?.user as any)?.role,
    userRole: (session?.user as any)?.role,
  };
}

import { useMemo } from 'react';

// Attributes that commonly cause hydration mismatches
const PROBLEMATIC_ATTRIBUTES = [
  'fdprocessedid',
  'data-fdprocessedid',
  'data-form-id',
  'data-form-type',
  'data-form-version',
  'data-form-valid',
  'data-form-submitted',
  'data-form-errors',
  'data-form-warnings',
  'data-form-success',
  'data-form-loading',
  'data-form-disabled',
  'data-form-readonly',
  'data-form-required',
  'data-form-pattern',
  'data-form-minlength',
  'data-form-maxlength',
  'data-form-min',
  'data-form-max',
  'data-form-step',
  'data-form-multiple',
  'data-form-accept',
  'data-form-capture',
  'data-form-autocomplete',
  'data-form-autocorrect',
  'data-form-autocapitalize',
  'data-form-spellcheck',
  'data-form-inputmode',
  'data-form-enterkeyhint',
];

/**
 * Hook that filters out problematic attributes that can cause hydration warnings
 * @param props - The props object to filter
 * @returns A new props object with problematic attributes removed
 */
export function useSafeProps<T extends Record<string, any>>(props: T): T {
  return useMemo(() => {
    const safeProps = { ...props };

    // Filter out problematic attributes
    PROBLEMATIC_ATTRIBUTES.forEach(attr => {
      if (attr in safeProps) {
        delete (safeProps as any)[attr];
      }
    });

    // Also filter out any props that start with 'data-form-' or 'fdprocessedid'
    Object.keys(safeProps).forEach(key => {
      if (key.startsWith('data-form-') || key.includes('fdprocessedid')) {
        delete (safeProps as any)[key];
      }
    });

    return safeProps;
  }, [props]);
}

export default useSafeProps;

import { useEffect, useState, useRef } from 'react';
import Pusher, { Channel } from 'pusher-js';

interface TrackingUpdate {
  bookingId: string;
  driverId: string;
  lat: number;
  lng: number;
  timestamp: string;
  eta?: {
    estimatedArrival: string;
    minutesRemaining: number;
  };
  routeProgress?: number;
}

interface UseTrackingUpdatesOptions {
  bookingId?: string;
  enabled?: boolean;
  onUpdate?: (update: TrackingUpdate) => void;
}

export function useTrackingUpdates({
  bookingId,
  enabled = true,
  onUpdate,
}: UseTrackingUpdatesOptions = {}) {
  const [updates, setUpdates] = useState<TrackingUpdate[]>([]);
  const [isConnected, setIsConnected] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const pusherRef = useRef<Pusher | null>(null);
  const channelRef = useRef<Channel | null>(null);

  useEffect(() => {
    if (!enabled) {
      return;
    }

    // Initialize Pusher
    if (!pusherRef.current) {
      pusherRef.current = new Pusher(process.env.NEXT_PUBLIC_PUSHER_KEY || '', {
        cluster: process.env.NEXT_PUBLIC_PUSHER_CLUSTER || 'eu',
        authEndpoint: '/api/pusher/auth',
        auth: {
          headers: {
            'Content-Type': 'application/json',
          },
        },
      });

      pusherRef.current.connection.bind('connected', () => {
        setIsConnected(true);
        setError(null);
      });

      pusherRef.current.connection.bind('disconnected', () => {
        setIsConnected(false);
      });

      pusherRef.current.connection.bind('error', (err: any) => {
        setError(`Connection error: ${err.message}`);
        setIsConnected(false);
      });
    }

    // Subscribe to tracking channel
    const channelName = bookingId
      ? `private-tracking-${bookingId}`
      : 'private-tracking-updates';

    if (!channelRef.current) {
      channelRef.current = pusherRef.current.subscribe(channelName);

      channelRef.current.bind('location-update', (data: TrackingUpdate) => {
        setUpdates(prev => {
          const newUpdates = [...prev, data];
          // Keep only last 50 updates
          return newUpdates.slice(-50);
        });

        if (onUpdate) {
          onUpdate(data);
        }
      });

      channelRef.current.bind('status-update', (data: any) => {
        if (onUpdate) {
          onUpdate(data);
        }
      });

      channelRef.current.bind('subscription_succeeded', () => {
        console.log('Successfully subscribed to tracking channel');
      });

      channelRef.current.bind('subscription_error', (err: any) => {
        setError(`Subscription error: ${err.message}`);
      });
    }

    return () => {
      if (channelRef.current) {
        channelRef.current.unsubscribe();
        channelRef.current = null;
      }
    };
  }, [bookingId, enabled, onUpdate]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (channelRef.current) {
        channelRef.current.unsubscribe();
        channelRef.current = null;
      }
      if (pusherRef.current) {
        pusherRef.current.disconnect();
        pusherRef.current = null;
      }
    };
  }, []);

  const sendLocationUpdate = async (
    lat: number,
    lng: number,
    bookingId: string
  ) => {
    try {
      const response = await fetch('/api/driver/tracking', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          bookingId,
          latitude: lat,
          longitude: lng,
        }),
      });

      if (!response.ok) {
        throw new Error('Failed to send location update');
      }

      return await response.json();
    } catch (err) {
      setError(
        err instanceof Error ? err.message : 'Failed to send location update'
      );
      throw err;
    }
  };

  const getLatestUpdate = () => {
    return updates.length > 0 ? updates[updates.length - 1] : null;
  };

  const clearUpdates = () => {
    setUpdates([]);
  };

  return {
    updates,
    latestUpdate: getLatestUpdate(),
    isConnected,
    error,
    sendLocationUpdate,
    clearUpdates,
  };
}

// Hook for admin tracking dashboard
export function useAdminTrackingUpdates() {
  const [allUpdates, setAllUpdates] = useState<
    Record<string, TrackingUpdate[]>
  >({});
  const [isConnected, setIsConnected] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const pusherRef = useRef<Pusher | null>(null);
  const channelRef = useRef<Channel | null>(null);

  useEffect(() => {
    // Initialize Pusher for admin
    if (!pusherRef.current) {
      pusherRef.current = new Pusher(process.env.NEXT_PUBLIC_PUSHER_KEY || '', {
        cluster: process.env.NEXT_PUBLIC_PUSHER_CLUSTER || 'eu',
        authEndpoint: '/api/pusher/auth',
        auth: {
          headers: {
            'Content-Type': 'application/json',
          },
        },
      });

      pusherRef.current.connection.bind('connected', () => {
        setIsConnected(true);
        setError(null);
      });

      pusherRef.current.connection.bind('disconnected', () => {
        setIsConnected(false);
      });

      pusherRef.current.connection.bind('error', (err: any) => {
        setError(`Connection error: ${err.message}`);
        setIsConnected(false);
      });
    }

    // Subscribe to admin tracking channel
    if (!channelRef.current) {
      channelRef.current = pusherRef.current.subscribe(
        'private-admin-tracking'
      );

      channelRef.current.bind('location-update', (data: TrackingUpdate) => {
        setAllUpdates(prev => {
          const bookingUpdates = prev[data.bookingId] || [];
          const newUpdates = [...bookingUpdates, data];
          // Keep only last 20 updates per booking
          return {
            ...prev,
            [data.bookingId]: newUpdates.slice(-20),
          };
        });
      });

      channelRef.current.bind('booking-status-update', (data: any) => {
        // Handle booking status changes
        console.log('Booking status update:', data);
      });

      channelRef.current.bind('subscription_succeeded', () => {
        console.log('Successfully subscribed to admin tracking channel');
      });

      channelRef.current.bind('subscription_error', (err: any) => {
        setError(`Subscription error: ${err.message}`);
      });
    }

    return () => {
      if (channelRef.current) {
        channelRef.current.unsubscribe();
        channelRef.current = null;
      }
    };
  }, []);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (channelRef.current) {
        channelRef.current.unsubscribe();
        channelRef.current = null;
      }
      if (pusherRef.current) {
        pusherRef.current.disconnect();
        pusherRef.current = null;
      }
    };
  }, []);

  const getBookingUpdates = (bookingId: string) => {
    return allUpdates[bookingId] || [];
  };

  const getLatestBookingUpdate = (bookingId: string) => {
    const updates = getBookingUpdates(bookingId);
    return updates.length > 0 ? updates[updates.length - 1] : null;
  };

  const getAllLatestUpdates = () => {
    const latest: Record<string, TrackingUpdate> = {};
    Object.keys(allUpdates).forEach(bookingId => {
      const update = getLatestBookingUpdate(bookingId);
      if (update) {
        latest[bookingId] = update;
      }
    });
    return latest;
  };

  return {
    allUpdates,
    getBookingUpdates,
    getLatestBookingUpdate,
    getAllLatestUpdates,
    isConnected,
    error,
  };
}

'use client';

import { useEffect, useRef } from 'react';
import { v4 as uuidv4 } from 'uuid';

interface VisitorTrackingOptions {
  enabled?: boolean;
  trackPageViews?: boolean;
  trackActions?: boolean;
}

export function useVisitorTracking(options: VisitorTrackingOptions = {}) {
  const {
    enabled = true,
    trackPageViews = true,
    trackActions = true,
  } = options;

  const sessionIdRef = useRef<string | null>(null);
  const visitorIdRef = useRef<string | null>(null);
  const lastPageRef = useRef<string | null>(null);

  useEffect(() => {
    if (!enabled || typeof window === 'undefined') return;

    // Initialize session and visitor IDs
    initializeTracking();

    // Track initial page view
    if (trackPageViews) {
      trackPageView(window.location.pathname);
    }

    // Track page changes for SPAs
    const handleRouteChange = () => {
      const currentPage = window.location.pathname;
      if (currentPage !== lastPageRef.current && trackPageViews) {
        trackPageView(currentPage);
        lastPageRef.current = currentPage;
      }
    };

    // Listen for route changes
    window.addEventListener('popstate', handleRouteChange);
    
    // For Next.js or React Router (if using history API)
    const originalPushState = window.history.pushState;
    window.history.pushState = function (...args) {
      originalPushState.apply(window.history, args);
      handleRouteChange();
    };

    // Track when user leaves
    const handleBeforeUnload = () => {
      trackAction('session_end', { duration: Date.now() - sessionStartTime });
    };

    const sessionStartTime = Date.now();
    window.addEventListener('beforeunload', handleBeforeUnload);

    return () => {
      window.removeEventListener('popstate', handleRouteChange);
      window.removeEventListener('beforeunload', handleBeforeUnload);
      window.history.pushState = originalPushState;
    };
  }, [enabled, trackPageViews]);

  const initializeTracking = () => {
    // Skip if running on server
    if (typeof window === 'undefined') return;
    
    // Get or create session ID (expires after 30 minutes of inactivity)
    let sessionId = sessionStorage.getItem('visitor_session_id');
    const sessionTimestamp = sessionStorage.getItem('visitor_session_timestamp');
    
    const now = Date.now();
    const thirtyMinutes = 30 * 60 * 1000;

    if (!sessionId || !sessionTimestamp || now - parseInt(sessionTimestamp) > thirtyMinutes) {
      sessionId = uuidv4();
      sessionStorage.setItem('visitor_session_id', sessionId);
    }
    
    sessionStorage.setItem('visitor_session_timestamp', now.toString());
    sessionIdRef.current = sessionId;

    // Get or create visitor ID (persists across sessions)
    let visitorId = localStorage.getItem('visitor_id');
    if (!visitorId) {
      visitorId = uuidv4();
      localStorage.setItem('visitor_id', visitorId);
    }
    visitorIdRef.current = visitorId;
  };

  const getDeviceInfo = () => {
    if (typeof window === 'undefined') return {};

    return {
      userAgent: navigator.userAgent,
      screenResolution: `${window.screen.width}x${window.screen.height}`,
      language: navigator.language,
      timezone: Intl.DateTimeFormat().resolvedOptions().timeZone,
    };
  };

  // Geolocation removed to improve Lighthouse Best Practices score
  // Only request geolocation when explicitly needed by user action

  const trackPageView = async (page: string) => {
    try {
      // Skip if running on server
      if (typeof window === 'undefined') return;
      if (!sessionIdRef.current) return;

      const deviceInfo = getDeviceInfo();

      const trackingData = {
        sessionId: sessionIdRef.current,
        visitorId: visitorIdRef.current,
        page,
        referrer: typeof document !== 'undefined' ? document.referrer || undefined : undefined,
        ...deviceInfo,
      };

      await fetch('/api/visitors/track', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(trackingData),
      });

      lastPageRef.current = page;
    } catch (error) {
      console.error('Failed to track page view:', error);
    }
  };

  const trackAction = async (action: string, actionData?: any) => {
    try {
      // Skip if running on server
      if (typeof window === 'undefined') return;
      if (!trackActions || !sessionIdRef.current) return;

      const deviceInfo = getDeviceInfo();

      await fetch('/api/visitors/track', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          sessionId: sessionIdRef.current,
          visitorId: visitorIdRef.current,
          page: window.location.pathname,
          action,
          actionData,
          ...deviceInfo,
        }),
      });
    } catch (error) {
      console.error('Failed to track action:', error);
    }
  };

  return {
    trackAction,
    trackPageView,
    sessionId: sessionIdRef.current,
    visitorId: visitorIdRef.current,
  };
}

/**
 * Instrumentation Hook for Next.js
 * 
 * This file is automatically called when the server starts (if instrumentationHook is enabled).
 * Perfect for initializing cron jobs on Render/Railway/Heroku.
 * 
 * See: https://nextjs.org/docs/app/building-your-application/optimizing/instrumentation
 */

export async function register() {
  // Fix MaxListenersExceededWarning by increasing the limit
  // Multiple modules (Prisma, Redis, Queue, etc.) add SIGINT/SIGTERM listeners
  // Default limit is 10, we need more for graceful shutdown handlers
  if (typeof process !== 'undefined' && process.setMaxListeners) {
    process.setMaxListeners(20);
  }

  // Only run on server-side in production
  if (process.env.NEXT_RUNTIME === 'nodejs') {
    console.log('🚀 Server runtime detected - initializing cron jobs...');
    
    try {
      // Wait a bit for Prisma Client to be fully initialized
      await new Promise(resolve => setTimeout(resolve, 2000));
      
      // Verify Prisma is available before initializing cron jobs
      const { prisma } = await import('./lib/prisma');
      if (!prisma) {
        console.error('❌ Prisma Client not available, skipping cron jobs');
        return;
      }
      
      // Import and initialize cron jobs
      const { initializeCronJobs } = await import('./lib/cron');
      initializeCronJobs();
      
      console.log('✅ Cron jobs initialized successfully via instrumentation hook');
    } catch (error) {
      console.error('❌ Failed to initialize cron jobs:', error);
    }
  }
}

