  /**
   * Fetch order details from database
   */
  private async fetchOrderDetails(orderRef: string): Promise<any | null> {
    try {
      const order = await prisma.booking.findFirst({
        where: {
          OR: [
            { reference: orderRef },
            { id: orderRef }
          ]
        },
        include: {
          pickupAddress: true,
          dropoffAddress: true,
          customer: { select: { name: true, email: true, phone: true } },
          driver: { 
            include: { 
              User: { select: { name: true, email: true, phone: true } } 
            } 
          },
          BookingItem: true,
          Assignment: { 
            include: { 
              JobEvent: { orderBy: { createdAt: 'desc' }, take: 5 } 
            } 
          }
        }
      });

      return order;
    } catch (error) {
      console.error('Error fetching order:', error);
      return null;
    }
  }

  /**
   * Fetch route details from database
   */
  private async fetchRouteDetails(routeRef: string): Promise<any | null> {
    try {
      const route = await prisma.route.findFirst({
        where: {
          OR: [
            { reference: routeRef },
            { id: routeRef }
          ]
        },
        include: {
          drops: {
            include: {
              Booking: {
                include: {
                  pickupAddress: true,
                  dropoffAddress: true,
                  customer: { select: { name: true } }
                }
              }
            },
            orderBy: { deliverySequence: 'asc' } as any
          },
          driver: {
            include: {
              User: { select: { name: true, email: true, phone: true } }
            }
          } as any
        }
      });

      return route;
    } catch (error) {
      console.error('Error fetching route:', error);
      return null;
    }
  }

