export interface ApiResponse<T = any> {
  success: boolean;
  data?: T;
  error?: string;
  message?: string;
  code?: string;
  timestamp: string;
  requestId?: string;
  headers?: Record<string, string>;
}

export interface ApiError {
  message: string;
  code: string;
  details?: any;
  field?: string;
}

export function createSuccessResponse<T>(
  data: T,
  message?: string,
  requestId?: string
): ApiResponse<T> {
  return {
    success: true,
    data,
    message,
    timestamp: new Date().toISOString(),
    requestId,
  };
}

export function createErrorResponse(
  error: string | ApiError,
  code?: string,
  requestId?: string,
  details?: any,
  statusCode?: number
): ApiResponse {
  const errorMessage = typeof error === 'string' ? error : error.message;
  const errorCode = typeof error === 'string' ? code : error.code;

  return {
    success: false,
    error: errorMessage,
    code: errorCode,
    timestamp: new Date().toISOString(),
    requestId,
    ...(details && { details }),
    ...(statusCode && { statusCode }),
  };
}

