export default DynamicAvailabilityEngine;

import { logger } from '../logger';
import type { PrismaClient } from '@prisma/client';
import { availabilityMetrics } from '../observability/availability-metrics';

/**
 * Full structured address interface for Enterprise Engine
 * MANDATORY: All address inputs must include complete structure
 */
export interface FullStructuredAddress {
  street: string;
  number: string;
  city: string;
  postcode: string;
  county?: string;
  coordinates: {
    lat: number;
    lng: number;
  };
}

/**
 * Route capacity and vehicle specifications
 */
export interface VehicleSpecs {
  id: string;
  type: 'small_van' | 'large_van' | 'truck';
  maxWeightKg: number;
  maxVolumeM3: number;
  crewSize: number;
}

/**
 * Driver shift availability
 */
export interface DriverShift {
  driverId: string;
  date: Date;
  startTime: string; // "08:00"
  endTime: string; // "18:00"
  maxWorkingHours: number;
  vehicleId: string;
  status: 'available' | 'busy' | 'offline';
}

/**
 * Route candidate for optimization
 */
export interface RouteCandidate {
  id: string;
  corridor: string;
  date: Date;
  window: 'AM' | 'PM' | 'ALL_DAY';
  currentCapacityKg: number;
  currentVolumeM3: number;
  maxCapacityKg: number;
  maxVolumeM3: number;
  fillRate: number; // 0-100%
  estimatedStops: number;
  status: 'planning' | 'ready' | 'dispatched' | 'completed';
  driverId?: string;
  vehicleId: string;
}

/**
 * Booking capacity requirements
 */
export interface BookingCapacity {
  totalWeightKg: number;
  totalVolumeM3: number;
  estimatedDurationMinutes: number;
  crewRequired: number;
}

/**
 * Availability calculation result
 */
export interface AvailabilityResult {
  next_available_date: string; // ISO date
  window: 'AM' | 'PM' | 'ALL_DAY';
  route_type: 'economy' | 'standard' | 'express';
  confidence: number; // 0-100%
  explanation: string;
  capacity_used_pct: number;
  fill_rate: number;
  route_id?: string;
  estimated_dispatch_time?: string;
}

/**
 * Dynamic Availability Engine
 * 
 * ENTERPRISE REQUIREMENT: Consumes FULL structured addresses only
 * No postcode-only shortcuts allowed
 */
export class DynamicAvailabilityEngine {
  private readonly MIN_FILL_RATE = 50; // Minimum 50% fill for Economy routes
  private readonly HANDLING_TIME_PER_STOP = 45; // minutes
  private readonly MAX_ROUTE_DURATION = 10 * 60; // 10 hours in minutes
  private readonly CAPACITY_BUFFER = 0.1; // 10% safety buffer
  
  constructor(private prisma: PrismaClient) {}

  /**
   * Calculate next available date and route type
   * CRITICAL: pickup and drops must be full structured addresses
   */
  async calculateAvailability(
    pickup: FullStructuredAddress,
    drops: FullStructuredAddress[],
    capacity: BookingCapacity,
    requestId: string
  ): Promise<AvailabilityResult> {
    const startTime = Date.now();
    
    logger.info('Dynamic availability calculation started', {
      pickup: this.sanitizeAddressForLog(pickup),
      dropsCount: drops.length,
      capacity,
      timestamp: new Date().toISOString()
    }, { requestId });

    try {
      // Validate full address structure
      this.validateFullAddress(pickup, 'pickup');
      drops.forEach((drop, index) => 
        this.validateFullAddress(drop, `drop[${index}]`)
      );

      // Get corridor for route optimization
      const corridor = this.calculateCorridor(pickup, drops);
      
      // Check immediate availability (Express/Standard)
      const immediateResult = await this.checkImmediateAvailability(
        pickup, drops, capacity, corridor, requestId
      );
      
      if (immediateResult) {
        logger.info('Immediate availability found', {
          result: immediateResult,
          processingTimeMs: Date.now() - startTime
        }, { requestId });
        return immediateResult;
      }

      // Check Economy multi-drop availability
      const economyResult = await this.checkEconomyAvailability(
        pickup, drops, capacity, corridor, requestId
      );

      logger.info('Availability calculation completed', {
        result: economyResult,
        processingTimeMs: Date.now() - startTime
      }, { requestId });

      // Record metrics
      availabilityMetrics.recordCalculation({
        requestId,
        route_type: economyResult.route_type,
        projected_fill_rate: economyResult.fill_rate,
        capacity_pct: economyResult.capacity_used_pct,
        next_available_date: economyResult.next_available_date,
        reason: economyResult.explanation,
        processing_time_ms: Date.now() - startTime,
        success: true,
        corridor: this.calculateCorridor(pickup, drops)
      });

      return economyResult;

    } catch (error) {
      logger.error('Availability calculation failed', error instanceof Error ? error : new Error('Unknown error'), { requestId });
      
      // Record failed calculation metric
      availabilityMetrics.recordCalculation({
        requestId,
        route_type: 'standard',
        projected_fill_rate: 0,
        capacity_pct: 0,
        next_available_date: 'unknown',
        reason: error instanceof Error ? error.message : 'Unknown error',
        processing_time_ms: Date.now() - startTime,
        success: false,
        corridor: this.calculateCorridor(pickup, drops)
      });
      
      // Fallback to next business day
      return this.getFallbackAvailability(capacity);
    }
  }

  /**
   * Validate that address contains all required full structure
   */
  private validateFullAddress(address: FullStructuredAddress, context: string): void {
    const required = ['street', 'number', 'city', 'postcode'];
    const missing = required.filter(field => !address[field as keyof FullStructuredAddress]);
    
    if (missing.length > 0) {
      throw new Error(`${context} address missing required fields: ${missing.join(', ')}`);
    }

    if (!address.coordinates || !address.coordinates.lat || !address.coordinates.lng) {
      throw new Error(`${context} address missing coordinates`);
    }
  }

  /**
   * Calculate geographic corridor for route optimization
   */
  private calculateCorridor(pickup: FullStructuredAddress, drops: FullStructuredAddress[]): string {
    const allPoints = [pickup, ...drops];
    const lats = allPoints.map(p => p.coordinates.lat);
    const lngs = allPoints.map(p => p.coordinates.lng);
    
    const minLat = Math.min(...lats);
    const maxLat = Math.max(...lats);
    const minLng = Math.min(...lngs);
    const maxLng = Math.max(...lngs);
    
    // Create corridor identifier based on geographic bounds
    return `${Math.round(minLat * 100)}_${Math.round(maxLat * 100)}_${Math.round(minLng * 100)}_${Math.round(maxLng * 100)}`;
  }

  /**
   * Check for immediate Express/Standard availability
   */
  private async checkImmediateAvailability(
    pickup: FullStructuredAddress,
    drops: FullStructuredAddress[],
    capacity: BookingCapacity,
    corridor: string,
    requestId: string
  ): Promise<AvailabilityResult | null> {
    // Get available drivers for next 24 hours
    const tomorrow = new Date();
    tomorrow.setDate(tomorrow.getDate() + 1);
    
    const availableDrivers = await this.getAvailableDrivers(tomorrow);
    const suitableVehicles = await this.getSuitableVehicles(capacity);

    if (availableDrivers.length === 0 || suitableVehicles.length === 0) {
      return null;
    }

    // Estimate duration and check feasibility
    const estimatedDuration = this.estimateJobDuration(pickup, drops, capacity);
    
    if (estimatedDuration > this.MAX_ROUTE_DURATION) {
      logger.warn('Job exceeds maximum duration', {
        estimatedDuration,
        maxDuration: this.MAX_ROUTE_DURATION
      }, { requestId });
      return null;
    }

    // Express availability (dedicated route)
    if (availableDrivers.length >= 2) {
      return {
        next_available_date: tomorrow.toISOString().split('T')[0],
        window: 'ALL_DAY',
        route_type: 'express',
        confidence: 95,
        explanation: 'Dedicated vehicle available tomorrow',
        capacity_used_pct: 100,
        fill_rate: 100,
        estimated_dispatch_time: '08:00'
      };
    }

    // Standard availability (shared route, priority scheduling)
    return {
      next_available_date: tomorrow.toISOString().split('T')[0],
      window: 'AM',
      route_type: 'standard',
      confidence: 85,
      explanation: 'Priority slot available tomorrow morning',
      capacity_used_pct: 75,
      fill_rate: 75,
      estimated_dispatch_time: '09:00'
    };
  }

  /**
   * Check Economy multi-drop availability with route optimization
   */
  private async checkEconomyAvailability(
    pickup: FullStructuredAddress,
    drops: FullStructuredAddress[],
    capacity: BookingCapacity,
    corridor: string,
    requestId: string
  ): Promise<AvailabilityResult> {
    // Get existing route candidates in the corridor
    const candidates = await this.getRouteCandidates(corridor);
    
    for (const candidate of candidates) {
      const canFit = this.checkCapacityFit(candidate, capacity);
      const projectedFillRate = this.calculateProjectedFillRate(candidate, capacity);
      
      if (canFit && projectedFillRate >= this.MIN_FILL_RATE) {
        return {
          next_available_date: candidate.date.toISOString().split('T')[0],
          window: candidate.window,
          route_type: 'economy',
          confidence: 90,
          explanation: `Route ready with ${projectedFillRate.toFixed(0)}% fill rate`,
          capacity_used_pct: projectedFillRate,
          fill_rate: projectedFillRate,
          route_id: candidate.id,
          estimated_dispatch_time: candidate.window === 'AM' ? '08:00' : '13:00'
        };
      }
    }

    // No suitable existing route, predict next available date
    return this.predictNextEconomyDate(corridor, capacity, requestId);
  }

  /**
   * Get available drivers for a specific date
   */
  private async getAvailableDrivers(date: Date): Promise<DriverShift[]> {
    // Implementation would query driver shifts and assignments
    // For now, return mock data
    return [
      {
        driverId: 'driver1',
        date,
        startTime: '08:00',
        endTime: '18:00',
        maxWorkingHours: 10,
        vehicleId: 'vehicle1',
        status: 'available'
      }
    ];
  }

  /**
   * Get vehicles suitable for capacity requirements
   */
  private async getSuitableVehicles(capacity: BookingCapacity): Promise<VehicleSpecs[]> {
    // Implementation would query vehicle specifications
    return [
      {
        id: 'vehicle1',
        type: 'large_van',
        maxWeightKg: 1000,
        maxVolumeM3: 15,
        crewSize: 2
      }
    ];
  }

  /**
   * Get route candidates in a corridor
   */
  private async getRouteCandidates(corridor: string): Promise<RouteCandidate[]> {
    // Implementation would query routes table
    // Mock data for now
    const tomorrow = new Date();
    tomorrow.setDate(tomorrow.getDate() + 1);
    
    return [
      {
        id: 'route1',
        corridor,
        date: tomorrow,
        window: 'AM',
        currentCapacityKg: 300,
        currentVolumeM3: 5,
        maxCapacityKg: 1000,
        maxVolumeM3: 15,
        fillRate: 40,
        estimatedStops: 3,
        status: 'planning',
        vehicleId: 'vehicle1'
      }
    ];
  }

  /**
   * Check if booking capacity fits in route
   */
  private checkCapacityFit(route: RouteCandidate, capacity: BookingCapacity): boolean {
    const remainingWeight = route.maxCapacityKg - route.currentCapacityKg;
    const remainingVolume = route.maxVolumeM3 - route.currentVolumeM3;
    
    return (
      capacity.totalWeightKg <= remainingWeight * (1 - this.CAPACITY_BUFFER) &&
      capacity.totalVolumeM3 <= remainingVolume * (1 - this.CAPACITY_BUFFER)
    );
  }

  /**
   * Calculate projected fill rate after adding booking
   */
  private calculateProjectedFillRate(route: RouteCandidate, capacity: BookingCapacity): number {
    const newWeight = route.currentCapacityKg + capacity.totalWeightKg;
    const newVolume = route.currentVolumeM3 + capacity.totalVolumeM3;
    
    const weightUtilization = (newWeight / route.maxCapacityKg) * 100;
    const volumeUtilization = (newVolume / route.maxVolumeM3) * 100;
    
    // Return the higher utilization (limiting factor)
    return Math.max(weightUtilization, volumeUtilization);
  }

  /**
   * Estimate job duration including travel and handling time
   */
  private estimateJobDuration(
    pickup: FullStructuredAddress,
    drops: FullStructuredAddress[],
    capacity: BookingCapacity
  ): number {
    const stops = drops.length + 1; // pickup + drops
    const handlingTime = stops * this.HANDLING_TIME_PER_STOP;
    
    // Rough distance estimation (Haversine approximation)
    const totalDistance = this.estimateTotalDistance(pickup, drops);
    const travelTime = (totalDistance / 30) * 60; // 30 mph average speed
    
    return handlingTime + travelTime;
  }

  /**
   * Estimate total travel distance
   */
  private estimateTotalDistance(pickup: FullStructuredAddress, drops: FullStructuredAddress[]): number {
    let totalDistance = 0;
    let currentPoint = pickup;
    
    for (const drop of drops) {
      totalDistance += this.haversineDistance(
        currentPoint.coordinates.lat,
        currentPoint.coordinates.lng,
        drop.coordinates.lat,
        drop.coordinates.lng
      );
      currentPoint = drop;
    }
    
    return totalDistance;
  }

  /**
   * Calculate Haversine distance between two points
   */
  private haversineDistance(lat1: number, lng1: number, lat2: number, lng2: number): number {
    const R = 3959; // Earth's radius in miles
    const dLat = this.toRadians(lat2 - lat1);
    const dLng = this.toRadians(lng2 - lng1);
    
    const a = Math.sin(dLat / 2) * Math.sin(dLat / 2) +
      Math.cos(this.toRadians(lat1)) * Math.cos(this.toRadians(lat2)) *
      Math.sin(dLng / 2) * Math.sin(dLng / 2);
    
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
    return R * c;
  }

  private toRadians(degrees: number): number {
    return degrees * (Math.PI / 180);
  }

  /**
   * Predict next Economy availability date using data-driven approach
   */
  private async predictNextEconomyDate(
    corridor: string,
    capacity: BookingCapacity,
    requestId: string
  ): Promise<AvailabilityResult> {
    // Look ahead for next viable route date
    const searchDate = new Date();
    searchDate.setDate(searchDate.getDate() + 2); // Start checking from day after tomorrow
    
    // In production, this would use ML/analytics to predict optimal grouping
    logger.info('Predicting next Economy date', {
      corridor,
      capacity,
      searchStartDate: searchDate.toISOString()
    }, { requestId });

    return {
      next_available_date: searchDate.toISOString().split('T')[0],
      window: 'AM',
      route_type: 'economy',
      confidence: 75,
      explanation: 'Projected route consolidation based on demand patterns',
      capacity_used_pct: 85,
      fill_rate: 85,
      estimated_dispatch_time: '08:00'
    };
  }

  /**
   * Fallback availability when calculation fails
   */
  private getFallbackAvailability(capacity: BookingCapacity): AvailabilityResult {
    const nextWeek = new Date();
    nextWeek.setDate(nextWeek.getDate() + 7);
    
    return {
      next_available_date: nextWeek.toISOString().split('T')[0],
      window: 'ALL_DAY',
      route_type: 'standard',
      confidence: 60,
      explanation: 'Fallback scheduling - manual review required',
      capacity_used_pct: 50,
      fill_rate: 50
    };
  }

  /**
   * Sanitize address for logging (remove sensitive data)
   */
  private sanitizeAddressForLog(address: FullStructuredAddress): Partial<FullStructuredAddress> {
    return {
      city: address.city,
      postcode: address.postcode.substring(0, 4) + '***', // Partial postcode
      coordinates: address.coordinates
    };
  }
}

import { NextRequest } from 'next/server';
import { withPrisma, ensurePrismaConnection } from '@/lib/prisma';
import crypto from 'crypto';

/**
 * Extract Bearer token from Authorization header
 */
export function extractBearerToken(request: NextRequest): string | null {
  const authHeader = request.headers.get('authorization');
  
  console.log('🔍 Checking authorization header:', authHeader ? 'Present' : 'Missing');
  
  if (!authHeader) {
    console.log('❌ No authorization header found');
    return null;
  }
  
  if (!authHeader.startsWith('Bearer ')) {
    console.log('❌ Authorization header does not start with "Bearer "');
    return null;
  }
  
  const token = authHeader.substring(7); // Remove 'Bearer ' prefix
  console.log('✅ Bearer token extracted:', token.substring(0, 20) + '...');
  
  return token;
}

/**
 * Generate HMAC-SHA256 signature for token validation
 */
function generateHMAC(data: string, secret: string): string {
  return crypto.createHmac('sha256', secret).update(data).digest('hex');
}

/**
 * Validate user from decoded token data
 */
async function validateUserFromToken(userId: string, email: string): Promise<{
  isValid: boolean;
  user?: any;
  error?: string;
}> {
  console.log('🔍 Decoded token - userId:', userId, 'email:', email);
  
  if (!userId || !email) {
    console.log('❌ Invalid token format - missing userId or email');
    return { isValid: false, error: 'Invalid token format' };
  }

  // Ensure database connection before querying
  await ensurePrismaConnection();

  // Find user in database with connection check
  const user = await withPrisma(async (prisma) => {
    return await prisma.user.findUnique({
      where: { id: userId },
      include: { driver: true },
    });
  });

  if (!user) {
    console.log('❌ User not found for userId:', userId);
    return { isValid: false, error: 'User not found' };
  }

  if (!user.isActive) {
    console.log('❌ User account is inactive:', userId);
    return { isValid: false, error: 'User account is inactive' };
  }

  console.log('✅ Bearer token validated successfully for user:', userId, 'role:', user.role);

  return {
    isValid: true,
    user: {
      id: user.id,
      email: user.email,
      name: user.name,
      role: user.role,
      driver: user.driver,
    },
  };
}

/**
 * Decode and validate Bearer token with HMAC-SHA256 verification
 */
export async function validateBearerToken(token: string): Promise<{
  isValid: boolean;
  user?: any;
  error?: string;
}> {
  try {
    console.log('🔐 Validating bearer token with HMAC-SHA256...');
    
    // Check if token contains HMAC signature (new format)
    if (token.includes('.')) {
      const [payload, signature] = token.split('.');
      
      // Verify HMAC signature
      const secret = process.env.JWT_SECRET || process.env.NEXTAUTH_SECRET || 'fallback-secret';
      const expectedSignature = generateHMAC(payload, secret);
      
      if (signature !== expectedSignature) {
        console.log('❌ HMAC signature verification failed');
        return { isValid: false, error: 'Invalid token signature' };
      }
      
      console.log('✅ HMAC signature verified');
      
      // Decode the payload
      const decodedToken = Buffer.from(payload, 'base64').toString('utf-8');
      const [userId, email, timestamp] = decodedToken.split(':');
      
      // Check token expiration (24 hours)
      if (timestamp) {
        const tokenTime = parseInt(timestamp);
        const now = Date.now();
        const maxAge = 24 * 60 * 60 * 1000; // 24 hours
        
        if (now - tokenTime > maxAge) {
          console.log('❌ Token expired');
          return { isValid: false, error: 'Token expired' };
        }
      }
      
      return await validateUserFromToken(userId, email);
    }
    
    // Fallback to old base64 format for backward compatibility
    console.log('⚠️ Using legacy base64 token format (no HMAC)');
    const decodedToken = Buffer.from(token, 'base64').toString('utf-8');
    const [userId, email, timestamp] = decodedToken.split(':');
    
    return await validateUserFromToken(userId, email);
  } catch (error) {
    console.error('❌ Bearer token validation error:', error);
    return {
      isValid: false,
      error: error instanceof Error ? error.message : 'Unknown error',
    };
  }
}

/**
 * Middleware to authenticate Bearer tokens for mobile app
 */
export async function authenticateBearerToken(request: NextRequest): Promise<{
  success: boolean;
  user?: any;
  error?: string;
}> {
  console.log('🔑 Starting bearer token authentication...');
  
  const token = extractBearerToken(request);
  
  if (!token) {
    console.log('❌ No Bearer token provided in request');
    return { success: false, error: 'No Bearer token provided' };
  }

  const validation = await validateBearerToken(token);
  
  if (!validation.isValid) {
    console.log('❌ Bearer token validation failed:', validation.error);
    return { success: false, error: validation.error };
  }

  console.log('✅ Bearer token authentication successful');
  
  return {
    success: true,
    user: validation.user,
  };
}

// Define Item type locally to avoid import issues
export interface Item {
  id: string;
  name: string;
  description: string;
  category: string;
  size: 'small' | 'medium' | 'large';
  quantity: number;
  unitPrice: number;
  totalPrice: number;
  weight: number;
  volume: number;
  dimensions?: {
    length: number;
    width: number;
    height: number;
  };
  image?: string;
}
import { COMPREHENSIVE_CATALOG, type CatalogItem } from '../pricing/catalog-dataset';
import { getItemImageWithFallback } from '../images/item-images';

// Utility function to round to 2 decimal places and fix floating-point precision
export const roundToTwoDecimals = (value: number): number => {
  if (typeof value !== 'number' || isNaN(value)) {
    console.warn('⚠️ Invalid value passed to roundToTwoDecimals:', value, typeof value);
    return 0;
  }
  return Math.round(value * 100) / 100;
};

// Calculate required workers based on items
export const calculateRequiredWorkers = (items: Item[]): number => {
  let requiredWorkers = 2; // Base crew size
  
  items.forEach(item => {
    // Heavy items require additional workers
    const itemWeight = item.weight * item.quantity;
    const itemVolume = item.volume * item.quantity;
    
    // Heavy furniture requires extra workers
    if (item.category === 'furniture' && (itemWeight > 50 || itemVolume > 2)) {
      requiredWorkers += Math.ceil(itemWeight / 100); // 1 extra worker per 100kg
    }
    
    // Large appliances require extra workers
    if (item.category === 'appliances' && itemWeight > 40) {
      requiredWorkers += 1;
    }
    
    // Special items like piano require extra workers
    if (item.id === 'piano' || item.name.toLowerCase().includes('piano')) {
      requiredWorkers += 2; // Piano needs 4 people total
    }
  });
  
  return Math.min(requiredWorkers, 6); // Max 6 workers
};

// Convert comprehensive catalog to Item format for compatibility with proper image handling
export const convertCatalogToItems = (catalogItems: CatalogItem[]): Item[] => {
  return catalogItems.map(catalogItem => {
    // Get appropriate image using the image system
    const imageInfo = getItemImageWithFallback(catalogItem.id, catalogItem.category);
    
    // Calculate dimensions from volume (assuming roughly cubic shape)
    const cubeRoot = Math.cbrt(catalogItem.volume);
    const dimensions = {
      length: cubeRoot * 100, // Convert to cm
      width: cubeRoot * 100,
      height: cubeRoot * 100,
    };
    
    return {
      id: catalogItem.id,
      name: catalogItem.name,
      description: `${catalogItem.name} - ${catalogItem.keywords[0]}`,
      category: catalogItem.category as any,
      size: catalogItem.volume > 1.5 ? 'large' : catalogItem.volume > 0.5 ? 'medium' : 'small',
      quantity: 1,
      unitPrice: Math.round(catalogItem.volume * 20 + catalogItem.weight * 0.5), // Dynamic pricing based on volume and weight
      totalPrice: Math.round(catalogItem.volume * 20 + catalogItem.weight * 0.5),
      weight: catalogItem.weight,
      volume: catalogItem.volume,
      dimensions,
      image: imageInfo.primary, // Use the image system instead of hardcoded path
    };
  });
};

// Calculate total weight and volume for items
export const calculateTotals = (items: Item[]) => {
  const totalWeight = items.reduce((sum, item) => sum + (item.weight * item.quantity), 0);
  const totalVolume = items.reduce((sum, item) => sum + (item.volume * item.quantity), 0);
  return { totalWeight, totalVolume };
};

// Deep equality check for pricing objects
export const deepEqual = (obj1: any, obj2: any): boolean => {
  if (obj1 === obj2) return true;
  if (obj1 == null || obj2 == null) return false;
  if (typeof obj1 !== typeof obj2) return false;
  
  if (typeof obj1 === 'object') {
    const keys1 = Object.keys(obj1);
    const keys2 = Object.keys(obj2);
    
    if (keys1.length !== keys2.length) return false;
    
    for (let key of keys1) {
      if (!keys2.includes(key)) return false;
      if (!deepEqual(obj1[key], obj2[key])) return false;
    }
    
    return true;
  }
  
  return obj1 === obj2;
};

// Build enhanced booking data for pricing
export const buildEnhancedBookingData = (step1: any) => {
  const { totalWeight, totalVolume } = calculateTotals(step1.items);
  
  return {
    items: step1.items,
    scheduledDate: new Date().toISOString(),
    serviceType: step1.serviceType || 'standard',
    pickupProperty: step1.pickupProperty,
    dropoffProperty: step1.dropoffProperty,
    // Ensure proper address format for distance calculation
    pickupAddress: {
      ...(step1.pickupAddress || {}),
      formatted_address: `${step1.pickupAddress?.address || ''}, ${step1.pickupAddress?.city || ''}, ${step1.pickupAddress?.postcode || ''}`.trim(),
    },
    dropoffAddress: {
      ...(step1.dropoffAddress || {}),
      formatted_address: `${step1.dropoffAddress?.address || ''}, ${step1.dropoffAddress?.city || ''}, ${step1.dropoffAddress?.postcode || ''}`.trim(),
    },
    // Add worker count calculation based on items
    workerCount: calculateRequiredWorkers(step1.items),
    // Add total weight and volume for pricing
    totalWeight: totalWeight,
    totalVolume: totalVolume,
  };
};

// Calculate property surcharges
export const calculatePropertySurcharges = (pickupProperty: any, dropoffProperty: any) => {
  let propertySurcharge = 0;
  let propertyDetails: string[] = [];
  
  // Pickup property surcharge (only if floors > 0)
  const pickupFloors = pickupProperty?.floors || 0;
  if (pickupFloors > 0) {
    const pickupHasElevator = pickupProperty?.hasLift || false;
    const pickupFloorFee = roundToTwoDecimals(pickupFloors * (pickupHasElevator ? 2 : 5));
    propertySurcharge = roundToTwoDecimals(propertySurcharge + pickupFloorFee);
    propertyDetails.push(`Pickup: Floor ${pickupFloors} ${pickupHasElevator ? '(£2/floor with lift)' : '(£5/floor without lift)'}`);
  }
  
  // Dropoff property surcharge (only if floors > 0)
  const dropoffFloors = dropoffProperty?.floors || 0;
  if (dropoffFloors > 0) {
    const dropoffHasElevator = dropoffProperty?.hasLift || false;
    const dropoffFloorFee = roundToTwoDecimals(dropoffFloors * (dropoffHasElevator ? 2 : 5));
    propertySurcharge = roundToTwoDecimals(propertySurcharge + dropoffFloorFee);
    propertyDetails.push(`Dropoff: Floor ${dropoffFloors} ${dropoffHasElevator ? '(£2/floor with lift)' : '(£5/floor without lift)'}`);
  }
  
  return { propertySurcharge, propertyDetails };
};

// Calculate building type multiplier
export const calculateBuildingMultiplier = (pickupProperty: any, dropoffProperty: any) => {
  const buildingTypeMultiplier = {
    'house': 1.0,
    'apartment': 1.1,
    'office': 1.2,
    'warehouse': 0.9,
    'other': 1.1,
  };
  
  const pickupMultiplier = buildingTypeMultiplier[(pickupProperty?.type as keyof typeof buildingTypeMultiplier) || 'house'];
  const dropoffMultiplier = buildingTypeMultiplier[(dropoffProperty?.type as keyof typeof buildingTypeMultiplier) || 'house'];
  return (pickupMultiplier + dropoffMultiplier) / 2;
};

// Calculate worker surcharge
export const calculateWorkerSurcharge = (items: Item[]) => {
  const workerCount = calculateRequiredWorkers(items);
  return roundToTwoDecimals(workerCount > 2 ? (workerCount - 2) * 15 : 0); // £15 per additional worker
};

import type { Prisma } from '@prisma/client';

type BookingLike = {
  customerPreferences?: Prisma.JsonValue | null;
  urgency?: string | null;
  orderType?: string | null;
  isMultiDrop?: boolean | null;
  [key: string]: unknown;
};

export type ServiceCategory = 'ECONOMY' | 'STANDARD' | 'PREMIUM' | 'ENTERPRISE';

const ECONOMY_KEYWORDS = new Set([
  'economy',
  'economy_service',
  'economy-service',
  'shared',
  'multi-drop',
  'multi_drop',
  'return',
]);

const PREMIUM_KEYWORDS = new Set(['premium', 'luxury', 'white-glove', 'white_glove', 'signature']);
const ENTERPRISE_KEYWORDS = new Set(['enterprise', 'priority', 'express', 'same-day', 'same_day', 'next-day', 'next_day']);

const STANDARD_KEYWORDS = new Set(['standard', 'default', 'core', 'classic']);

function toRecord(value: Prisma.JsonValue | null | undefined): Record<string, unknown> {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    return {};
  }
  return value as Record<string, unknown>;
}

function normalizeString(value: unknown): string | undefined {
  if (typeof value === 'string') {
    const trimmed = value.trim();
    if (trimmed.length > 0) {
      return trimmed.toLowerCase();
    }
  }
  return undefined;
}

function pickFirstString(values: unknown[]): string | undefined {
  for (const value of values) {
    const normalized = normalizeString(value);
    if (normalized) {
      return normalized;
    }
  }
  return undefined;
}

function canonicalServiceType(value: string): ServiceCategory {
  if (ECONOMY_KEYWORDS.has(value)) {
    return 'ECONOMY';
  }
  if (ENTERPRISE_KEYWORDS.has(value)) {
    return 'ENTERPRISE';
  }
  if (PREMIUM_KEYWORDS.has(value)) {
    return 'PREMIUM';
  }
  if (STANDARD_KEYWORDS.has(value)) {
    return 'STANDARD';
  }
  return 'STANDARD';
}

export function deriveServiceMetadata(booking?: BookingLike | null): { serviceType: ServiceCategory; isEconomy: boolean } {
  const prefs = toRecord(booking?.customerPreferences);
  const candidates: unknown[] = [
    // Direct fields (if they exist)
    (booking as any)?.serviceType,
    // Preferences variations
    prefs.serviceType,
    prefs.service_type,
    prefs.serviceLevel,
    prefs.service_level,
    prefs.serviceTier,
    prefs.service_tier,
    prefs.tier,
    prefs.plan,
    prefs.package,
    // Fallbacks
    booking?.urgency,
    booking?.orderType,
  ];

  const normalized = pickFirstString(candidates) ?? 'standard';
  const serviceType = canonicalServiceType(normalized);

  const isEconomy =
    serviceType === 'ECONOMY' ||
    (booking?.orderType ?? '').toLowerCase().includes('multi-drop') ||
    booking?.isMultiDrop === true;

  return { serviceType, isEconomy };
}

export function isEconomyBooking(booking?: BookingLike | null): boolean {
  return deriveServiceMetadata(booking).isEconomy;
}

export function withServicePreference(
  preferences: Prisma.JsonValue | null | undefined,
  serviceType: ServiceCategory
): Prisma.JsonValue {
  const prefs = toRecord(preferences);
  const serviceValue = serviceType.toLowerCase();
  return {
    ...prefs,
    serviceType: serviceValue,
    service_level: serviceValue,
    serviceLevel: serviceValue,
    serviceTier: serviceValue,
  };
}

/**
 * Cache utilities for Speedy Van
 */

interface CacheItem<T> {
  data: T;
  timestamp: number;
  ttl: number;
}

class MemoryCache {
  private cache = new Map<string, CacheItem<any>>();

  set<T>(key: string, data: T, ttl: number = 300000): void { // 5 minutes default
    this.cache.set(key, {
      data,
      timestamp: Date.now(),
      ttl,
    });
  }

  get<T>(key: string): T | null {
    const item = this.cache.get(key);
    
    if (!item) {
      return null;
    }

    const now = Date.now();
    if (now - item.timestamp > item.ttl) {
      this.cache.delete(key);
      return null;
    }

    return item.data;
  }

  has(key: string): boolean {
    return this.get(key) !== null;
  }

  delete(key: string): boolean {
    return this.cache.delete(key);
  }

  clear(): void {
    this.cache.clear();
  }

  size(): number {
    return this.cache.size;
  }

  keys(): string[] {
    return Array.from(this.cache.keys());
  }

  // Clean up expired items
  cleanup(): void {
    const now = Date.now();
    for (const [key, item] of this.cache.entries()) {
      if (now - item.timestamp > item.ttl) {
        this.cache.delete(key);
      }
    }
  }
}

// Global cache instance
export const cache = new MemoryCache();

// Cache decorator for functions
export function cached<T extends (...args: any[]) => Promise<any>>(
  fn: T,
  ttl: number = 300000,
  keyGenerator?: (...args: Parameters<T>) => string
): T {
  return (async (...args: Parameters<T>) => {
    const key = keyGenerator 
      ? keyGenerator(...args)
      : `cache:${fn.name}:${JSON.stringify(args)}`;
    
    const cached = cache.get(key);
    if (cached) {
      return cached;
    }

    const result = await fn(...args);
    cache.set(key, result, ttl);
    return result;
  }) as T;
}

