      const stopTypes = stops.map(s => s.type);
      
      // Count transitions from pickup to dropoff
      let transitions = 0;
      for (let i = 0; i < stopTypes.length - 1; i++) {
        if (stopTypes[i] === 'pickup' && stopTypes[i + 1] === 'dropoff') {
