      if (provider === 'google') {
        return await this.getGooglePlaceDetails(placeId);
      } else {
        return await this.getMapboxPlaceDetails(placeId);
      }
    } catch (error) {
      console.error(`Failed to get place details from ${provider}:`, error);
      return null;
