          this.flags.set(flag.name, flag);
        });
      }
    } catch (error) {
      console.error('Failed to load flags from API:', error);
    }
  }

  setContext(context: FeatureFlagContext) {
    this.context = { ...this.context, ...context };
  }

  isEnabled(flagName: string): boolean {
    const flag = this.flags.get(flagName);
    if (!flag) {
      return false;
    }

    // Check if flag is globally enabled
    if (!flag.enabled) {
      return false;
    }

    // Check environment
    if (flag.targetEnvironments && flag.targetEnvironments.length > 0) {
      const currentEnv =
        this.context.environment || process.env.NODE_ENV || 'development';
      if (!flag.targetEnvironments.includes(currentEnv)) {
        return false;
      }
    }

    // Check role
    if (flag.targetRoles && flag.targetRoles.length > 0) {
      if (
        !this.context.userRole ||
        !flag.targetRoles.includes(this.context.userRole)
      ) {
        return false;
      }
    }

    // Check specific users
    if (flag.targetUsers && flag.targetUsers.length > 0) {
      if (
        !this.context.userId ||
        !flag.targetUsers.includes(this.context.userId)
      ) {
        return false;
      }
    }

    // Check date range
    const now = new Date();
    if (flag.startDate && now < flag.startDate) {
      return false;
    }
    if (flag.endDate && now > flag.endDate) {
      return false;
    }

    // Check rollout percentage
    if (flag.rolloutPercentage < 100) {
      const hash = this.hashString(
        this.context.userId || this.context.sessionId || 'anonymous'
      );
      const percentage = hash % 100;
      if (percentage >= flag.rolloutPercentage) {
        return false;
      }
    }

    return true;
  }

  getFlag(flagName: string): FeatureFlag | undefined {
    return this.flags.get(flagName);
  }

  getAllFlags(): FeatureFlag[] {
    return Array.from(this.flags.values());
  }

  getEnabledFlags(): FeatureFlag[] {
    return this.getAllFlags().filter(flag => this.isEnabled(flag.name));
  }

  // Hash function for consistent user assignment
  private hashString(str: string): number {
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
      const char = str.charCodeAt(i);
      hash = (hash << 5) - hash + char;
      hash = hash & hash; // Convert to 32-bit integer
    }
    return Math.abs(hash);
  }

  // Track feature flag usage
  trackFlagUsage(flagName: string, action: string = 'view') {
    if (typeof window !== 'undefined') {
      // Send to telemetry
      fetch('/api/telemetry/analytics', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          event: 'feature_flag_usage',
          properties: {
            flagName,
            action,
            enabled: this.isEnabled(flagName),
            context: this.context,
          },
          sessionId: this.context.sessionId,
          timestamp: Date.now(),
        }),
      }).catch(error => {
        console.error('Failed to track feature flag usage:', error);
      });
    }
  }
}

// Create singleton instance
export const featureFlags = new FeatureFlagService();

// React hook for feature flags
export function useFeatureFlag(flagName: string): boolean {
  const isEnabled = featureFlags.isEnabled(flagName);

  // Track usage
  if (typeof window !== 'undefined') {
    featureFlags.trackFlagUsage(flagName);
  }

  return isEnabled;
}

// Higher-order component for feature flags
export function withFeatureFlag<T extends object>(
  WrappedComponent: React.ComponentType<T>,
  flagName: string,
  fallback?: React.ComponentType<T>
) {
  return function FeatureFlagWrapper(props: T) {
    const isEnabled = useFeatureFlag(flagName);

    if (isEnabled) {
      return React.createElement(WrappedComponent, props);
    }

    if (fallback) {
      return React.createElement(fallback, props);
    }

    return null;
  };
}

// Utility function to check multiple flags
export function useFeatureFlags(flagNames: string[]): Record<string, boolean> {
  const result: Record<string, boolean> = {};

  flagNames.forEach(flagName => {
    result[flagName] = useFeatureFlag(flagName);
  });

  return result;
}

// Initialize feature flags with user context
export function initializeFeatureFlags(context: FeatureFlagContext) {
  featureFlags.setContext(context);
}

/**
 * File upload configuration for Speedy Van
 */

export interface UploadConfig {
  maxFileSize: number;
  allowedTypes: string[];
  allowedExtensions: string[];
  uploadPath: string;
}

export const UPLOAD_CONFIGS = {
  DOCUMENTS: {
    maxFileSize: 10 * 1024 * 1024, // 10MB
    allowedTypes: ['application/pdf', 'image/jpeg', 'image/png'],
    allowedExtensions: ['.pdf', '.jpg', '.jpeg', '.png'],
    uploadPath: '/uploads/documents',
  },
  IMAGES: {
    maxFileSize: 5 * 1024 * 1024, // 5MB
    allowedTypes: ['image/jpeg', 'image/png', 'image/webp'],
    allowedExtensions: ['.jpg', '.jpeg', '.png', '.webp'],
    uploadPath: '/uploads/images',
  },
  AVATARS: {
    maxFileSize: 2 * 1024 * 1024, // 2MB
    allowedTypes: ['image/jpeg', 'image/png'],
    allowedExtensions: ['.jpg', '.jpeg', '.png'],
    uploadPath: '/uploads/avatars',
  },
} as const;

export const UPLOAD_DIRS = {
  DOCUMENTS: '/uploads/documents',
  IMAGES: '/uploads/images',
  AVATARS: '/uploads/avatars',
} as const;

export function validateFile(
  file: File,
  config: UploadConfig
): { valid: boolean; error?: string } {
  // Check file size
  if (file.size > config.maxFileSize) {
    return {
      valid: false,
      error: `File size must be less than ${Math.round(config.maxFileSize / 1024 / 1024)}MB`,
    };
  }

  // Check file type
  if (!config.allowedTypes.includes(file.type)) {
    return {
      valid: false,
      error: `File type ${file.type} is not allowed`,
    };
  }

  // Check file extension
  const extension = '.' + file.name.split('.').pop()?.toLowerCase();
  if (!config.allowedExtensions.includes(extension)) {
    return {
      valid: false,
      error: `File extension ${extension} is not allowed`,
    };
  }

  return { valid: true };
}

export function generateSecureFilename(originalName: string): string {
  const timestamp = Date.now();
  const random = Math.random().toString(36).substring(2, 15);
  const extension = originalName.split('.').pop()?.toLowerCase() || '';
  return `${timestamp}-${random}.${extension}`;
}

export function getUploadConfig(type: keyof typeof UPLOAD_CONFIGS): UploadConfig {
  const config = UPLOAD_CONFIGS[type];
  return {
    maxFileSize: config.maxFileSize,
    allowedTypes: [...config.allowedTypes],
    allowedExtensions: [...config.allowedExtensions],
    uploadPath: config.uploadPath,
  };
}

export function validateFileSize(file: File | number, maxSize: number): { valid: boolean; error?: string } {
  const size = typeof file === 'number' ? file : file.size;
  const valid = size <= maxSize;
  return {
    valid,
    error: valid ? undefined : `File size must be less than ${Math.round(maxSize / 1024 / 1024)}MB`
  };
}

export function sanitizeFilename(filename: string): string {
  return filename
    .replace(/[^a-zA-Z0-9.-]/g, '_')
    .replace(/_{2,}/g, '_')
    .toLowerCase();
}

export function isPathSafe(path: string, baseDir?: string): boolean {
  const base = baseDir || '/uploads/';
  return !path.includes('..') && !path.includes('~') && path.startsWith(base);
}

export function scanFileForMalware(file: File | string): Promise<{ clean: boolean; threat?: string }> {
  // Mock implementation - in real app, integrate with antivirus service
  return Promise.resolve({ clean: true });
}

export function getCORSHeaders(origin?: string): Record<string, string> {
  return {
    'Access-Control-Allow-Origin': origin || '*',
    'Access-Control-Allow-Methods': 'GET, POST, PUT, DELETE, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type, Authorization',
  };
}

export function checkRateLimit(userId: string): Promise<{ allowed: boolean; resetTime?: number; remaining?: number }> {
  // Mock implementation - in real app, use Redis or similar
  return Promise.resolve({ allowed: true, remaining: 100 });
}

