// Utility functions
export function getAllImages(): ItemImage[] {
  return Object.values(IMAGE_DATA).flat();
}

export function getImagesByCategory(category: ImageCategory): ItemImage[] {
  return IMAGE_DATA[category] || [];
}

export function getImageById(id: string): ItemImage | undefined {
  return getAllImages().find(img => img.id === id);
}

export function searchImages(
  query: string,
  category?: ImageCategory
): ItemImage[] {
  const searchTerm = query.toLowerCase();
  const images = category ? getImagesByCategory(category) : getAllImages();

  return images.filter(
    img =>
      img.name.toLowerCase().includes(searchTerm) ||
      img.description?.toLowerCase().includes(searchTerm) ||
      img.tags.some(tag => tag.toLowerCase().includes(searchTerm))
  );
}

export function getCategories(): CategoryInfo[] {
  return Object.values(CATEGORIES);
}

export function getCategoryByName(name: string): CategoryInfo | undefined {
  return CATEGORIES[name as ImageCategory];
}

export function getPopularImages(limit: number = 10): ItemImage[] {
  // For now, return first N images from each category
  // In a real app, this would be based on usage analytics
  const popular: any[] = [];
  Object.values(IMAGE_DATA).forEach(categoryImages => {
    popular.push(
      ...categoryImages.slice(
        0,
        Math.ceil(limit / Object.keys(IMAGE_DATA).length)
      )
    );
  });
  return popular.slice(0, limit);
}

export function getRecentlyUsedImages(
  userId?: string,
  limit: number = 10
): ItemImage[] {
  // In a real app, this would fetch from user's history
  // For now, return popular images
  return getPopularImages(limit);
}

export function getSuggestionsBasedOnSelection(
  selectedImages: string[],
  limit: number = 5
): ItemImage[] {
  // Simple suggestion algorithm based on selected items
  const selected = selectedImages
    .map(id => getImageById(id))
    .filter(Boolean) as ItemImage[];
  const selectedCategories = [...new Set(selected.map(img => img.category))];
  const selectedTags = [...new Set(selected.flatMap(img => img.tags))];

  const suggestions = getAllImages()
    .filter(img => !selectedImages.includes(img.id))
    .filter(
      img =>
        selectedCategories.includes(img.category) ||
        img.tags.some(tag => selectedTags.includes(tag))
    )
    .slice(0, limit);

  return suggestions;
}

/**
 * Fuzzy Search Utility for Items
 * Uses Fuse.js for intelligent item searching with typo tolerance
 */

import Fuse from 'fuse.js';
import type { IFuseOptions } from 'fuse.js';

export interface SearchableItem {
  id: string;
  name: string;
  category: string;
  description?: string;
  keywords?: string[];
  [key: string]: any;
}

/**
 * Fuzzy search configuration
 */
const fuseOptions: IFuseOptions<SearchableItem> = {
  keys: [
    { name: 'name', weight: 0.5 },
    { name: 'category', weight: 0.2 },
    { name: 'description', weight: 0.2 },
    { name: 'keywords', weight: 0.1 },
  ],
  threshold: 0.4, // 0.0 = exact match, 1.0 = match anything
  distance: 100,
  minMatchCharLength: 2,
  includeScore: true,
  useExtendedSearch: true,
};

/**
 * Create a fuzzy search instance for items
 */
export function createItemSearch(items: SearchableItem[]) {
  return new Fuse(items, fuseOptions);
}

/**
 * Perform fuzzy search on items
 */
export function fuzzySearchItems(
  items: SearchableItem[],
  query: string,
  maxResults: number = 20
): SearchableItem[] {
  if (!query || query.trim().length < 2) {
    return items.slice(0, maxResults);
  }

  const fuse = createItemSearch(items);
  const results = fuse.search(query, { limit: maxResults });

  return results.map((result) => result.item);
}

/**
 * Get search suggestions based on partial input
 */
export function getSearchSuggestions(
  items: SearchableItem[],
  query: string,
  maxSuggestions: number = 5
): string[] {
  if (!query || query.trim().length < 2) {
    return [];
  }

  const fuse = createItemSearch(items);
  const results = fuse.search(query, { limit: maxSuggestions * 2 });

  // Extract unique item names as suggestions
  const suggestions = new Set<string>();
  
  for (const result of results) {
    if (suggestions.size >= maxSuggestions) break;
    suggestions.add(result.item.name);
  }

  return Array.from(suggestions);
}

/**
 * Search items by category with fuzzy matching
 */
export function searchItemsByCategory(
  items: SearchableItem[],
  category: string,
  query?: string,
  maxResults: number = 20
): SearchableItem[] {
  // Filter by category first
  const categoryItems = items.filter(
    (item) => item.category.toLowerCase() === category.toLowerCase()
  );

  // If no query, return all items in category
  if (!query || query.trim().length < 2) {
    return categoryItems.slice(0, maxResults);
  }

  // Apply fuzzy search within category
  return fuzzySearchItems(categoryItems, query, maxResults);
}

/**
 * Calculate relevance score for an item based on query
 */
export function calculateRelevanceScore(
  item: SearchableItem,
  query: string
): number {
  const fuse = createItemSearch([item]);
  const results = fuse.search(query);

  if (results.length === 0) return 0;

  // Fuse.js score is 0 (perfect match) to 1 (no match)
  // We invert it to make higher scores better
  return 1 - (results[0].score || 1);
}

/**
 * Background job to monitor unassigned orders and notify admin
 */
import { prisma } from '@/lib/prisma';
import { getPusherServer } from '@/lib/pusher';

interface UnassignedOrderAlert {
  id: string;
  reference: string;
  customerName: string;
  waitingMinutes: number;
  priority: 'normal' | 'high' | 'urgent';
  slaBreached: boolean;
}

// SLA thresholds (in minutes)
const SLA_THRESHOLDS = {
  NORMAL: 30,    // 30 minutes
  HIGH: 15,      // 15 minutes  
  URGENT: 5,     // 5 minutes
};

export class UnassignedOrdersMonitor {
  private intervalId: ReturnType<typeof setInterval> | null = null;
  private readonly checkInterval = 5 * 60 * 1000; // Check every 5 minutes

  async start() {
    if (this.intervalId) {
      console.warn('UnassignedOrdersMonitor already running');
      return;
    }

    console.log('🚨 Starting UnassignedOrdersMonitor...');
    this.intervalId = setInterval(() => {
      this.checkUnassignedOrders();
    }, this.checkInterval);

    // Run initial check
    await this.checkUnassignedOrders();
  }

  stop() {
    if (this.intervalId) {
      clearInterval(this.intervalId);
      this.intervalId = null;
      console.log('⏹️ Stopped UnassignedOrdersMonitor');
    }
  }

  private async checkUnassignedOrders() {
    try {
      console.log('🔍 Checking for unassigned orders...');

      const unassignedOrders = await prisma.booking.findMany({
        where: {
          status: 'CONFIRMED',
          driverId: null,
          createdAt: {
            lte: new Date(Date.now() - 5 * 60 * 1000) // Older than 5 minutes
          }
        },
        select: {
          id: true,
          reference: true,
          customerName: true,
          createdAt: true,
          scheduledAt: true,
          urgency: true,
        },
        orderBy: {
          createdAt: 'asc'
        }
      });

      if (unassignedOrders.length === 0) {
        console.log('✅ No unassigned orders found');
        return;
      }

      console.log(`⚠️ Found ${unassignedOrders.length} unassigned orders`);

      const alerts: UnassignedOrderAlert[] = unassignedOrders.map(order => {
        const now = new Date();
        const waitingMinutes = Math.floor((now.getTime() - order.createdAt.getTime()) / (1000 * 60));
        
        // Determine priority and SLA breach
        let priority: 'normal' | 'high' | 'urgent' = 'normal';
        let slaBreached = false;

        if (order.urgency === 'urgent') {
          priority = 'urgent';
          slaBreached = waitingMinutes > SLA_THRESHOLDS.URGENT;
        } else if (waitingMinutes > SLA_THRESHOLDS.HIGH) {
          priority = 'high';
          slaBreached = waitingMinutes > SLA_THRESHOLDS.NORMAL;
        } else if (waitingMinutes > SLA_THRESHOLDS.NORMAL) {
          slaBreached = true;
        }

        return {
          id: order.id,
          reference: order.reference,
          customerName: order.customerName,
          waitingMinutes,
          priority,
          slaBreached
        };
      });

      // Send alerts for SLA breached orders
      const breachedOrders = alerts.filter(alert => alert.slaBreached);
      
      if (breachedOrders.length > 0) {
        await this.sendAdminAlert(breachedOrders);
      }

      // Log all unassigned orders
      await this.logUnassignedOrders(alerts);

    } catch (error) {
      console.error('❌ Error in UnassignedOrdersMonitor:', error);
    }
  }

  private async sendAdminAlert(breachedOrders: UnassignedOrderAlert[]) {
    try {
      const pusher = getPusherServer();

      for (const order of breachedOrders) {
        await pusher.trigger('admin-notifications', 'unassigned-order-alert', {
          type: 'unassigned_order_sla_breach',
          orderId: order.id,
          orderReference: order.reference,
          customerName: order.customerName,
          waitingMinutes: order.waitingMinutes,
          priority: order.priority,
          message: `Order ${order.reference} has been unassigned for ${order.waitingMinutes} minutes`,
          timestamp: new Date().toISOString(),
          actionRequired: true,
          suggestedActions: [
            'Assign available driver',
            'Contact customer about delay',
            'Escalate to operations team'
          ]
        });

        console.log(`🚨 Sent admin alert for order ${order.reference} (${order.waitingMinutes}min wait)`);
      }

      // Send summary notification
      await pusher.trigger('admin-notifications', 'unassigned-orders-summary', {
        type: 'unassigned_orders_summary',
        totalUnassigned: breachedOrders.length,
        urgentCount: breachedOrders.filter(o => o.priority === 'urgent').length,
        highCount: breachedOrders.filter(o => o.priority === 'high').length,
        message: `${breachedOrders.length} orders need immediate attention`,
        timestamp: new Date().toISOString(),
      });

    } catch (error) {
      console.error('❌ Error sending admin alert:', error);
    }
  }

  private async logUnassignedOrders(alerts: UnassignedOrderAlert[]) {
    console.log('📊 Unassigned Orders Summary:');
    alerts.forEach(alert => {
      console.log(`  - ${alert.reference}: ${alert.waitingMinutes}min (${alert.priority}) ${alert.slaBreached ? '🚨 SLA BREACH' : '✅'}`);
    });
  }
}

