export default logger;

/**
 * STRUCTURED LOGGING SYSTEM - PRODUCTION GRADE
 * 
 * Enterprise-level logging infrastructure providing:
 * - Request tracing with correlation IDs
 * - Performance metrics and timing
 * - Error categorization and severity levels
 * - Structured JSON output for log aggregation
 * - Context-aware logging with metadata
 * - Security event logging
 * - Business metrics and KPIs
 * - Integration with monitoring systems
 */

import { randomUUID } from 'crypto';
import { AsyncLocalStorage } from 'async_hooks';

// Log levels with numeric values for filtering
export enum LogLevel {
  DEBUG = 10,
  INFO = 20,
  WARN = 30,
  ERROR = 40,
  FATAL = 50,
}

// Error categories for classification
export enum ErrorCategory {
  VALIDATION = 'validation',
  AUTHENTICATION = 'authentication',
  AUTHORIZATION = 'authorization',
  PAYMENT = 'payment',
  EXTERNAL_SERVICE = 'external_service',
  DATABASE = 'database',
  NETWORK = 'network',
  BUSINESS_LOGIC = 'business_logic',
  SYSTEM = 'system',
  SECURITY = 'security',
}

// Performance metric types
export enum MetricType {
  TIMING = 'timing',
  COUNTER = 'counter',
  GAUGE = 'gauge',
  HISTOGRAM = 'histogram',
}

// Business event types for KPI tracking
export enum BusinessEvent {
  QUOTE_REQUESTED = 'quote_requested',
  QUOTE_GENERATED = 'quote_generated',
  BOOKING_CREATED = 'booking_created',
  PAYMENT_INITIATED = 'payment_initiated',
  PAYMENT_COMPLETED = 'payment_completed',
  DRIVER_ASSIGNED = 'driver_assigned',
  JOB_COMPLETED = 'job_completed',
  USER_REGISTERED = 'user_registered',
}

// Request context stored in AsyncLocalStorage
interface RequestContext {
  correlationId: string;
  userId?: string;
  sessionId?: string;
  userAgent?: string;
  ipAddress?: string;
  endpoint?: string;
  method?: string;
  startTime: number;
}

// Base log entry structure
interface BaseLogEntry {
  timestamp: string;
  level: LogLevel;
  message: string;
  correlationId: string;
  service: string;
  environment: string;
  version: string;
  context?: Record<string, any>;
}

// Extended log entry types
interface ErrorLogEntry extends BaseLogEntry {
  error: {
    name: string;
    message: string;
    stack?: string;
    category: ErrorCategory;
    code?: string;
    severity: 'low' | 'medium' | 'high' | 'critical';
  };
}

interface PerformanceLogEntry extends BaseLogEntry {
  performance: {
    operation: string;
    duration: number;
    metricType: MetricType;
    unit: string;
    tags?: Record<string, string>;
  };
}

interface BusinessLogEntry extends BaseLogEntry {
  business: {
    event: BusinessEvent;
    entityId?: string;
    entityType?: string;
    value?: number;
    currency?: string;
    metadata?: Record<string, any>;
  };
}

interface SecurityLogEntry extends BaseLogEntry {
  security: {
    event: string;
    severity: 'info' | 'warning' | 'critical';
    userId?: string;
    ipAddress?: string;
    userAgent?: string;
    blocked?: boolean;
    reason?: string;
  };
}

// Logger configuration
interface LoggerConfig {
  service: string;
  environment: string;
  version: string;
  minLevel: LogLevel;
  enableConsole: boolean;
  enableFile: boolean;
  enableRemote: boolean;
  remoteEndpoint?: string;
  apiKey?: string;
}

// Performance timer for measuring operation duration
class PerformanceTimer {
  private startTime: number;
  private operation: string;
  private tags: Record<string, string>;

  constructor(operation: string, tags: Record<string, string> = {}) {
    this.operation = operation;
    this.tags = tags;
    this.startTime = performance.now();
  }

  end(additionalTags: Record<string, string> = {}): number {
    const duration = performance.now() - this.startTime;
    
    StructuredLogger.performance(this.operation, duration, {
      ...this.tags,
      ...additionalTags,
    });

    return duration;
  }
}

// Context manager for request tracing
class RequestTracer {
  private static storage = new AsyncLocalStorage<RequestContext>();

  static startTrace(context: Partial<RequestContext> = {}): string {
    const correlationId = context.correlationId || randomUUID();
    
    const requestContext: RequestContext = {
      correlationId,
      userId: context.userId,
      sessionId: context.sessionId,
      userAgent: context.userAgent,
      ipAddress: context.ipAddress,
      endpoint: context.endpoint,
      method: context.method,
      startTime: Date.now(),
    };

    this.storage.enterWith(requestContext);
    return correlationId;
  }

  static getContext(): RequestContext | undefined {
    return this.storage.getStore();
  }

  static getCorrelationId(): string {
    const context = this.getContext();
    return context?.correlationId || 'no-correlation-id';
  }

  static addContextData(data: Record<string, any>): void {
    const context = this.getContext();
    if (context) {
      Object.assign(context, data);
    }
  }
}

// Main structured logger class
export class StructuredLogger {
  private static config: LoggerConfig = {
    service: 'speedy-van',
    environment: process.env.NODE_ENV || 'development',
    version: process.env.APP_VERSION || '1.0.0',
    minLevel: process.env.LOG_LEVEL ? 
      LogLevel[process.env.LOG_LEVEL as keyof typeof LogLevel] || LogLevel.INFO : 
      LogLevel.INFO,
    enableConsole: true,
    enableFile: false,
    enableRemote: false,
  };

  static configure(config: Partial<LoggerConfig>): void {
    this.config = { ...this.config, ...config };
  }

  // Core logging method
  private static log(
    level: LogLevel, 
    message: string, 
    context?: Record<string, any>
  ): void {
    if (level < this.config.minLevel) {
      return;
    }

    const requestContext = RequestTracer.getContext();
    
    const entry: BaseLogEntry = {
      timestamp: new Date().toISOString(),
      level,
      message,
      correlationId: RequestTracer.getCorrelationId(),
      service: this.config.service,
      environment: this.config.environment,
      version: this.config.version,
      context: {
        ...context,
        ...(requestContext ? {
          userId: requestContext.userId,
          sessionId: requestContext.sessionId,
          endpoint: requestContext.endpoint,
          method: requestContext.method,
        } : {})
      },
    };

    this.output(entry);
  }

  // Standard log levels
  static debug(message: string, context?: Record<string, any>): void {
    this.log(LogLevel.DEBUG, message, context);
  }

  static info(message: string, context?: Record<string, any>): void {
    this.log(LogLevel.INFO, message, context);
  }

  static warn(message: string, context?: Record<string, any>): void {
    this.log(LogLevel.WARN, message, context);
  }

  static error(
    message: string, 
    error?: Error, 
    category: ErrorCategory = ErrorCategory.SYSTEM,
    severity: 'low' | 'medium' | 'high' | 'critical' = 'medium',
    context?: Record<string, any>
  ): void {
    const entry: ErrorLogEntry = {
      timestamp: new Date().toISOString(),
      level: LogLevel.ERROR,
      message,
      correlationId: RequestTracer.getCorrelationId(),
      service: this.config.service,
      environment: this.config.environment,
      version: this.config.version,
      context,
      error: {
        name: error?.name || 'UnknownError',
        message: error?.message || message,
        stack: error?.stack,
        category,
        severity,
        code: (error as any)?.code,
      },
    };

    this.output(entry);
  }

  static fatal(
    message: string, 
    error?: Error, 
    category: ErrorCategory = ErrorCategory.SYSTEM,
    context?: Record<string, any>
  ): void {
    const entry: ErrorLogEntry = {
      timestamp: new Date().toISOString(),
      level: LogLevel.FATAL,
      message,
      correlationId: RequestTracer.getCorrelationId(),
      service: this.config.service,
      environment: this.config.environment,
      version: this.config.version,
      context,
      error: {
        name: error?.name || 'FatalError',
        message: error?.message || message,
        stack: error?.stack,
        category,
        severity: 'critical',
        code: (error as any)?.code,
      },
    };

    this.output(entry);
  }

  // Performance logging
  static performance(
    operation: string,
    duration: number,
    tags: Record<string, string> = {},
    metricType: MetricType = MetricType.TIMING
  ): void {
    const entry: PerformanceLogEntry = {
      timestamp: new Date().toISOString(),
      level: LogLevel.INFO,
      message: `Performance metric: ${operation}`,
      correlationId: RequestTracer.getCorrelationId(),
      service: this.config.service,
      environment: this.config.environment,
      version: this.config.version,
      performance: {
        operation,
        duration,
        metricType,
        unit: 'ms',
        tags,
      },
    };

    this.output(entry);
  }

  // Business event logging
  static business(
    event: BusinessEvent,
    entityId?: string,
    entityType?: string,
    value?: number,
    currency?: string,
    metadata?: Record<string, any>
  ): void {
    const entry: BusinessLogEntry = {
      timestamp: new Date().toISOString(),
      level: LogLevel.INFO,
      message: `Business event: ${event}`,
      correlationId: RequestTracer.getCorrelationId(),
      service: this.config.service,
      environment: this.config.environment,
      version: this.config.version,
      business: {
        event,
        entityId,
        entityType,
        value,
        currency,
        metadata,
      },
    };

    this.output(entry);
  }

  // Security event logging
  static security(
    event: string,
    severity: 'info' | 'warning' | 'critical' = 'info',
    userId?: string,
    ipAddress?: string,
    userAgent?: string,
    blocked?: boolean,
    reason?: string
  ): void {
    const entry: SecurityLogEntry = {
      timestamp: new Date().toISOString(),
      level: severity === 'critical' ? LogLevel.FATAL : 
             severity === 'warning' ? LogLevel.WARN : LogLevel.INFO,
      message: `Security event: ${event}`,
      correlationId: RequestTracer.getCorrelationId(),
      service: this.config.service,
      environment: this.config.environment,
      version: this.config.version,
      security: {
        event,
        severity,
        userId,
        ipAddress,
        userAgent,
        blocked,
        reason,
      },
    };

    this.output(entry);
  }

  // Request lifecycle logging
  static requestStart(
    method: string,
    url: string,
    userId?: string,
    sessionId?: string,
    userAgent?: string,
    ipAddress?: string
  ): string {
    const correlationId = RequestTracer.startTrace({
      userId,
      sessionId,
      userAgent,
      ipAddress,
      endpoint: url,
      method,
    });

    this.info('Request started', {
      method,
      url,
      userId,
      sessionId,
    });

    return correlationId;
  }

  static requestEnd(
    statusCode: number,
    responseTime?: number,
    error?: Error
  ): void {
    const context = RequestTracer.getContext();
    const duration = responseTime || (context ? Date.now() - context.startTime : 0);

    if (error) {
      this.error('Request failed', error, ErrorCategory.SYSTEM, 'medium', {
        statusCode,
        responseTime: duration,
      });
    } else {
      this.info('Request completed', {
        statusCode,
        responseTime: duration,
      });
    }

    // Log performance metric
    if (context?.endpoint) {
      this.performance(`request_${context.method?.toLowerCase()}_${context.endpoint}`, duration, {
        method: context.method || 'unknown',
        endpoint: context.endpoint,
        status: statusCode.toString(),
      });
    }
  }

  // Timer utilities
  static startTimer(operation: string, tags: Record<string, string> = {}): PerformanceTimer {
    return new PerformanceTimer(operation, tags);
  }

  static async measureAsync<T>(
    operation: string,
    fn: () => Promise<T>,
    tags: Record<string, string> = {}
  ): Promise<T> {
    const timer = this.startTimer(operation, tags);
    try {
      const result = await fn();
      timer.end({ status: 'success' });
      return result;
    } catch (error) {
      timer.end({ status: 'error' });
      throw error;
    }
  }

  static measure<T>(
    operation: string,
    fn: () => T,
    tags: Record<string, string> = {}
  ): T {
    const timer = this.startTimer(operation, tags);
    try {
      const result = fn();
      timer.end({ status: 'success' });
      return result;
    } catch (error) {
      timer.end({ status: 'error' });
      throw error;
    }
  }

  // Output handling
  private static output(entry: any): void {
    if (this.config.enableConsole) {
      this.outputConsole(entry);
    }

    if (this.config.enableFile) {
      this.outputFile(entry);
    }

    if (this.config.enableRemote) {
      this.outputRemote(entry);
    }
  }

  private static outputConsole(entry: any): void {
    const logString = JSON.stringify(entry, null, this.config.environment === 'development' ? 2 : 0);
    
    switch (entry.level) {
      case LogLevel.DEBUG:
        console.debug(logString);
        break;
      case LogLevel.INFO:
        console.info(logString);
        break;
      case LogLevel.WARN:
        console.warn(logString);
        break;
      case LogLevel.ERROR:
      case LogLevel.FATAL:
        console.error(logString);
        break;
      default:
        console.log(logString);
    }
  }

  private static outputFile(entry: any): void {
    // File output implementation would go here
    // This could write to rotating log files, etc.
  }

  private static outputRemote(entry: any): void {
    // Remote logging implementation would go here
    // This could send to logging services like DataDog, LogDNA, etc.
    if (this.config.remoteEndpoint && this.config.apiKey) {
      // Implementation would send HTTP POST to logging service
    }
  }
}

