/**
 * Custom hook for safe session access
 */
export function useSafeSession(): {
  session: NextAuthSession | null;
  isLoading: boolean;
  isValid: boolean;
  userRole: string | null;
  userId: string | null;
  userEmail: string | null;
  userName: string | null;
} {
  const { data: session, status } = useSession();
  
  const isLoading = status === 'loading';
  const isValid = !!((session?.user as any)?.id && (session?.user as any)?.email && (session?.user as any)?.role);
  const userRole = (session?.user as any)?.role || null;
  const userId = (session?.user as any)?.id || null;
  const userEmail = (session?.user as any)?.email || null;
  const userName = (session?.user as any)?.name || null;

  return {
    session: session as any,
    isLoading,
    isValid,
    userRole,
    userId,
    userEmail,
    userName,
  };
}

/**
 * Safe sign in function
 */
export async function safeSignIn(
  provider: string = 'credentials',
  options?: any
): Promise<{ success: boolean; error?: string }> {
  try {
    const result = await signIn(provider, {
      redirect: false,
      ...options,
    });

    if (result?.error) {
      return { success: false, error: result.error };
    }

    return { success: true };
  } catch (error) {
    console.error('Sign in error:', error);
    return {
      success: false,
      error: error instanceof Error ? error.message : 'Unknown error',
    };
  }
}

/**
 * Safe sign out function
 */
export async function safeSignOut(): Promise<{ success: boolean; error?: string }> {
  try {
    await signOut({ redirect: false });
    return { success: true };
  } catch (error) {
    console.error('Sign out error:', error);
    return {
      success: false,
      error: error instanceof Error ? error.message : 'Unknown error',
    };
  }
}

