                console.error('❌ SMS sending failed:', smsResult.error);
              }
            } catch (smsError) {
              console.error('❌ SMS service error:', smsError);
            }
          } else {
            console.log('ℹ️ No phone number available for driver SMS notification');
          }
        } catch (emailError) {
          console.error('❌ Email notification failed:', emailError);
        }
      }

      // Log successful notification
      await prisma.systemAuditLog.create({
        data: {
          eventType: 'driver_notified',
          severity: 'info',
          actor: 'system',
          actorType: 'system',
          targetType: 'route',
          targetId: routeId,
          action: 'notify_driver',
          details: {
            driverId,
            driverName,
            routeId,
            totalDrops: route.totalDrops,
            channels: ['pusher', 'sms', 'push', 'email'],
          },
          result: 'success',
          timestamp: new Date(),
        }
      });

    } catch (error) {
      console.error('❌ Critical error in notifyDriver:', error);
      
      // Log error
      await prisma.systemAuditLog.create({
        data: {
          eventType: 'driver_notification_failed',
          severity: 'error',
          actor: 'system',
          actorType: 'system',
          targetType: 'route',
          targetId: routeId,
          action: 'notify_driver',
          details: {
            driverId,
            error: error instanceof Error ? error.message : 'Unknown error',
          },
          result: 'failure',
          errorMessage: error instanceof Error ? error.message : 'Unknown error',
          timestamp: new Date(),
        }
      });
    }
  }

