    doc.on('end', () => res(Buffer.concat(chunks as any)))
  );

  const amount = (input.Booking.totalGBP / 100).toFixed(2);

  doc
    .fontSize(18)
    .text(`${input.company.name} — Receipt`, { align: 'left' })
