// UK Postcode validation and formatting
const UK_POSTCODE_REGEX = /^[A-Z]{1,2}[0-9R][0-9A-Z]? [0-9][ABD-HJLNP-UW-Z]{2}$/i;

// Debug function to test postcode validation
