interface KeywordData {
  keyword: string;
  searchIntent: 'informational' | 'navigational' | 'transactional' | 'commercial';
  difficulty: 'low' | 'medium' | 'high';
  priority: number; // 1-10
  category: string;
}

/**
 * Generate comprehensive keywords for a city
 */
export function generateCityKeywords(city: UKCity): KeywordData[] {
  const keywords: KeywordData[] = [];
  const cityName = city.name.toLowerCase();
  const citySlug = city.slug;

  // 1. Service + City (50 keywords)
  SERVICES.forEach((service) => {
    keywords.push({
      keyword: `${service} ${cityName}`,
      searchIntent: 'transactional',
      difficulty: 'medium',
      priority: 9,
      category: 'service',
    });
  });

  // 2. Service + Modifier + City (2000+ keywords)
  SERVICES.forEach((service) => {
    SERVICE_MODIFIERS.forEach((modifier) => {
      keywords.push({
        keyword: `${modifier} ${service} ${cityName}`,
        searchIntent: 'transactional',
        difficulty: 'low',
        priority: 8,
        category: 'service-modified',
      });
    });
  });

  // 3. Vehicle + City (25 keywords)
  VEHICLES.forEach((vehicle) => {
    keywords.push({
      keyword: `${vehicle} ${cityName}`,
      searchIntent: 'transactional',
      difficulty: 'high',
      priority: 10,
      category: 'vehicle',
    });
  });

  // 4. Vehicle + Service + City (1250+ keywords)
  VEHICLES.forEach((vehicle) => {
    SERVICES.slice(0, 10).forEach((service) => {
      keywords.push({
        keyword: `${vehicle} for ${service} ${cityName}`,
        searchIntent: 'transactional',
        difficulty: 'low',
        priority: 7,
        category: 'vehicle-service',
      });
    });
  });

  // 5. Action + Vehicle + City (500 keywords)
  ACTIONS.forEach((action) => {
    VEHICLES.forEach((vehicle) => {
      keywords.push({
        keyword: `${action} ${vehicle} ${cityName}`,
        searchIntent: 'transactional',
        difficulty: 'medium',
        priority: 8,
        category: 'action-vehicle',
      });
    });
  });

  // 6. Moving Types + City (15 keywords)
  MOVING_TYPES.forEach((movingType) => {
    keywords.push({
      keyword: `${movingType} ${cityName}`,
      searchIntent: 'transactional',
      difficulty: 'medium',
      priority: 9,
      category: 'moving',
    });
  });

  // 7. Specific Item + Delivery + City (30 keywords)
  SPECIFIC_ITEMS.forEach((item) => {
    keywords.push({
      keyword: `${item} delivery ${cityName}`,
      searchIntent: 'transactional',
      difficulty: 'low',
      priority: 7,
      category: 'item-delivery',
    });
  });

  // 8. Specific Item + Moving + City (30 keywords)
  SPECIFIC_ITEMS.forEach((item) => {
    keywords.push({
      keyword: `${item} moving ${cityName}`,
      searchIntent: 'transactional',
      difficulty: 'low',
      priority: 7,
      category: 'item-moving',
    });
  });

  // 9. Question-based Keywords (400+ keywords)
  QUESTIONS.forEach((question) => {
    SERVICES.slice(0, 20).forEach((service) => {
      keywords.push({
        keyword: `${question} ${service} ${cityName}`,
        searchIntent: 'informational',
        difficulty: 'low',
        priority: 6,
        category: 'question',
      });
    });
  });

  // 10. Postcode-based Keywords (if available)
  if (city.postcode) {
    SERVICES.slice(0, 20).forEach((service) => {
      keywords.push({
        keyword: `${service} ${city.postcode}`,
        searchIntent: 'transactional',
        difficulty: 'low',
        priority: 8,
        category: 'postcode',
      });
    });
  }

  // 11. Near Me Keywords (50 keywords)
  [...SERVICES.slice(0, 25), ...VEHICLES.slice(0, 25)].forEach((term) => {
    keywords.push({
      keyword: `${term} near ${cityName}`,
      searchIntent: 'transactional',
      difficulty: 'medium',
      priority: 9,
      category: 'near-me',
    });
  });

  // 12. Comparison Keywords (100 keywords)
  const comparisons = ['best', 'top', 'cheapest', 'fastest', 'most reliable'];
  comparisons.forEach((comparison) => {
    SERVICES.slice(0, 20).forEach((service) => {
      keywords.push({
        keyword: `${comparison} ${service} ${cityName}`,
        searchIntent: 'commercial',
        difficulty: 'high',
        priority: 8,
        category: 'comparison',
      });
    });
  });

  // 13. Review Keywords (50 keywords)
  const reviewTerms = ['reviews', 'ratings', 'testimonials', 'feedback', 'recommendations'];
  reviewTerms.forEach((term) => {
    [...SERVICES.slice(0, 5), ...VEHICLES.slice(0, 5)].forEach((service) => {
      keywords.push({
        keyword: `${service} ${term} ${cityName}`,
        searchIntent: 'informational',
        difficulty: 'low',
        priority: 6,
        category: 'review',
      });
    });
  });

  // 14. Price Keywords (100 keywords)
  const priceTerms = ['price', 'cost', 'quote', 'estimate', 'rates'];
  priceTerms.forEach((term) => {
    SERVICES.slice(0, 20).forEach((service) => {
      keywords.push({
        keyword: `${service} ${term} ${cityName}`,
        searchIntent: 'commercial',
        difficulty: 'medium',
        priority: 8,
        category: 'price',
      });
    });
  });

  // 15. Time-based Keywords (200 keywords)
  const times = ['today', 'tonight', 'tomorrow', 'this weekend', 'next week'];
  times.forEach((time) => {
    SERVICES.slice(0, 40).forEach((service) => {
      keywords.push({
        keyword: `${service} ${time} ${cityName}`,
        searchIntent: 'transactional',
        difficulty: 'low',
        priority: 7,
        category: 'time-based',
      });
    });
  });

  return keywords;
}

/**
 * Get top priority keywords for a city
 */
export function getTopKeywords(city: UKCity, limit: number = 100): KeywordData[] {
  const allKeywords = generateCityKeywords(city);
  return allKeywords
    .sort((a, b) => b.priority - a.priority)
    .slice(0, limit);
}

/**
 * Get keywords by category
 */
export function getKeywordsByCategory(
  city: UKCity,
  category: string
): KeywordData[] {
  const allKeywords = generateCityKeywords(city);
  return allKeywords.filter((kw) => kw.category === category);
}

/**
 * Get keywords by search intent
 */
export function getKeywordsByIntent(
  city: UKCity,
  intent: KeywordData['searchIntent']
): KeywordData[] {
  const allKeywords = generateCityKeywords(city);
  return allKeywords.filter((kw) => kw.searchIntent === intent);
}

/**
 * Export keywords to CSV format
 */
export function exportKeywordsToCSV(city: UKCity): string {
  const keywords = generateCityKeywords(city);
  const header = 'Keyword,Search Intent,Difficulty,Priority,Category\n';
  const rows = keywords.map(
    (kw) =>
      `"${kw.keyword}",${kw.searchIntent},${kw.difficulty},${kw.priority},${kw.category}`
  );
  return header + rows.join('\n');
}

/**
 * Get keyword statistics
 */
export function getKeywordStats(city: UKCity) {
  const keywords = generateCityKeywords(city);
  
  return {
    total: keywords.length,
    byIntent: {
      transactional: keywords.filter((kw) => kw.searchIntent === 'transactional').length,
      informational: keywords.filter((kw) => kw.searchIntent === 'informational').length,
      commercial: keywords.filter((kw) => kw.searchIntent === 'commercial').length,
      navigational: keywords.filter((kw) => kw.searchIntent === 'navigational').length,
    },
    byDifficulty: {
      low: keywords.filter((kw) => kw.difficulty === 'low').length,
      medium: keywords.filter((kw) => kw.difficulty === 'medium').length,
      high: keywords.filter((kw) => kw.difficulty === 'high').length,
    },
    byCategory: keywords.reduce((acc, kw) => {
      acc[kw.category] = (acc[kw.category] || 0) + 1;
      return acc;
    }, {} as Record<string, number>),
    highPriority: keywords.filter((kw) => kw.priority >= 8).length,
  };
}

export default {
  generateCityKeywords,
  getTopKeywords,
  getKeywordsByCategory,
  getKeywordsByIntent,
  exportKeywordsToCSV,
  getKeywordStats,
};

import { getPusherServer } from '@/lib/pusher';

interface SmartNotificationData {
  type: 'job_update' | 'location_based' | 'time_sensitive' | 'priority_alert';
  title: string;
  message: string;
  data?: any;
  priority: 'low' | 'medium' | 'high' | 'urgent';
  location?: {
    lat: number;
    lng: number;
    radius?: number; // in meters
  };
  targetUsers?: string[];
  targetRoles?: ('driver' | 'customer' | 'admin')[];
  expiresAt?: Date;
  actions?: Array<{
    label: string;
    action: string;
    style?: 'primary' | 'secondary' | 'success' | 'warning' | 'danger';
  }>;
}

interface LocationBasedNotification extends SmartNotificationData {
  type: 'location_based';
  location: {
    lat: number;
    lng: number;
    radius: number;
  };
}

interface TimeBasedNotification extends SmartNotificationData {
  type: 'time_sensitive';
  expiresAt: Date;
  countdown?: boolean;
}

class SmartNotificationService {
  private pusher = getPusherServer();

  /**
   * Send a smart notification based on context
   */
  async sendSmartNotification(notification: SmartNotificationData) {
    const channels = this.determineChannels(notification);
    const enrichedData = this.enrichNotificationData(notification);

    const results = await Promise.all(
      channels.map(channel => 
        this.pusher.trigger(channel, 'smart-notification', enrichedData)
      )
    );

    // Log notification for analytics
    await this.logNotification(notification, channels);

    return {
      success: true,
      channelsSent: channels.length,
      results
    };
  }

  /**
   * Send job progress notification to all relevant parties
   */
  async notifyJobProgress(
    jobId: string, 
    step: string, 
    driverId: string, 
    customerId?: string, 
    bookingReference?: string
  ) {
    const notifications = [
      // Notify customer
      ...(customerId ? [{
        type: 'job_update' as const,
        title: 'Job Update',
        message: this.getJobStepMessage(step),
        data: { jobId, step, driverId, bookingReference },
        priority: 'medium' as const,
        targetUsers: [customerId],
        targetRoles: ['customer' as const],
      }] : []),
      
      // Notify admin dashboard
      {
        type: 'job_update' as const,
        title: 'Driver Progress Update',
        message: `Job ${bookingReference} - ${this.getJobStepMessage(step)}`,
        data: { jobId, step, driverId, customerId, bookingReference },
        priority: 'low' as const,
        targetRoles: ['admin' as const],
      },

      // Notify tracking system
      {
        type: 'job_update' as const,
        title: 'Tracking Update',
        message: `Step completed: ${step}`,
        data: { 
          jobId, 
          step, 
          driverId, 
          timestamp: new Date().toISOString(),
          type: 'step_completion'
        },
        priority: 'medium' as const,
        targetRoles: ['admin' as const],
      }
    ];

    return Promise.all(
      notifications.map(notification => this.sendSmartNotification(notification))
    );
  }

  /**
   * Send location-based notification to nearby drivers
   */
  async notifyNearbyDrivers(notification: LocationBasedNotification) {
    // Find nearby drivers
    const nearbyDrivers = await this.findNearbyDrivers(
      notification.location.lat,
      notification.location.lng,
      notification.location.radius
    );

    const enhancedNotification = {
      ...notification,
      targetUsers: (nearbyDrivers || []).map((d: any) => d.id),
      data: {
        ...notification.data,
        nearbyDriversCount: nearbyDrivers.length,
        location: notification.location,
      }
    };

    return this.sendSmartNotification(enhancedNotification);
  }

  /**
   * Send urgent notification with escalation
   */
  async sendUrgentNotification(
    notification: SmartNotificationData,
    escalationLevels: string[] = ['admin', 'supervisor', 'manager']
  ) {
    const urgentNotification: SmartNotificationData = {
      ...notification,
      priority: 'urgent' as const,
      actions: [
        { label: 'Acknowledge', action: 'acknowledge', style: 'primary' as const },
        { label: 'Escalate', action: 'escalate', style: 'warning' as const },
        { label: 'Handle', action: 'handle', style: 'success' as const },
      ]
    };

    // Send initial notification
    await this.sendSmartNotification(urgentNotification);

    // Set up escalation if not acknowledged
    setTimeout(async () => {
      const isAcknowledged = await this.checkNotificationStatus(notification);
      if (!isAcknowledged) {
        await this.escalateNotification(urgentNotification, escalationLevels);
      }
    }, 5 * 60 * 1000); // 5 minutes

    return { success: true, escalationSet: true };
  }

  /**
   * Send time-sensitive notification with countdown
   */
  async sendTimeBasedNotification(notification: TimeBasedNotification) {
    const timeBasedNotification = {
      ...notification,
      data: {
        ...notification.data,
        expiresAt: notification.expiresAt.toISOString(),
        timeRemaining: notification.expiresAt.getTime() - Date.now(),
      }
    };

    await this.sendSmartNotification(timeBasedNotification);

    // Set up expiration handler
    const timeUntilExpiry = notification.expiresAt.getTime() - Date.now();
    if (timeUntilExpiry > 0) {
      setTimeout(async () => {
        await this.sendSmartNotification({
          ...notification,
          type: 'priority_alert',
          title: 'Notification Expired',
          message: `Time-sensitive notification has expired: ${notification.message}`,
          priority: 'high',
        });
      }, timeUntilExpiry);
    }

    return { success: true, expirationSet: true };
  }

  /**
   * Batch send notifications efficiently
   */
  async sendBatchNotifications(notifications: SmartNotificationData[]) {
    // Group by channel for efficiency
    const channelGroups = new Map<string, SmartNotificationData[]>();
    
    notifications.forEach(notification => {
      const channels = this.determineChannels(notification);
      channels.forEach(channel => {
        if (!channelGroups.has(channel)) {
          channelGroups.set(channel, []);
        }
        channelGroups.get(channel)!.push(notification);
      });
    });

    const results = [];
    for (const [channel, channelNotifications] of channelGroups) {
      const batchResult = await this.pusher.trigger(
        channel,
        'batch-notifications',
        {
          notifications: channelNotifications.map(n => this.enrichNotificationData(n)),
          timestamp: new Date().toISOString(),
          count: channelNotifications.length,
        }
      );
      results.push({ channel, count: channelNotifications.length, result: batchResult });
    }

    return { success: true, batches: results };
  }

  // Private helper methods
  private determineChannels(notification: SmartNotificationData): string[] {
    const channels: string[] = [];

    // User-specific channels
    if (notification.targetUsers) {
      notification.targetUsers.forEach(userId => {
        channels.push(`user-${userId}`);
      });
    }

    // Role-based channels
    if (notification.targetRoles) {
      notification.targetRoles.forEach(role => {
        channels.push(`${role}-notifications`);
      });
    }

    // Default to admin if no specific targets
    if (channels.length === 0) {
      channels.push('admin-notifications');
    }

    // Add priority-based channels for urgent notifications
    if (notification.priority === 'urgent') {
      channels.push('urgent-notifications');
    }

    return channels;
  }

  private enrichNotificationData(notification: SmartNotificationData) {
    return {
      ...notification,
      id: `notification_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
      timestamp: new Date().toISOString(),
      source: 'smart-notification-service',
      version: '1.0',
    };
  }

  private getJobStepMessage(step: string): string {
    const messages: Record<string, string> = {
