        isMultiDrop: true,
        customerId: true,
        driverId: true
      };
      
      if (filters?.includeRoute) {
        select.multiDropRoute = {
          select: {
            id: true,
            status: true,
            totalDistance: true,
            estimatedDuration: true,
            stops: {
              select: {
                id: true,
                sequenceNumber: true,
                address: true,
                status: true
              },
              orderBy: { sequenceNumber: 'asc' }
            }
          }
        };
      }
      
      const where: any = {};
      
      if (filters?.status?.length) {
        where.status = { in: filters.status };
      }
      
      if (filters?.customerId) {
        where.customerId = filters.customerId;
      }
      
      if (filters?.driverId) {
        where.driverId = filters.driverId;
      }
      
      if (filters?.isMultiDrop !== undefined) {
        where.isMultiDrop = filters.isMultiDrop;
      }
      
      if (filters?.dateRange) {
        where.scheduledAt = {
          gte: filters.dateRange.start,
          lte: filters.dateRange.end
        };
      }
      
      return prisma.booking.findMany({
        where,
        select,
        take: filters?.limit || 50,
        skip: filters?.offset || 0,
        orderBy: { scheduledAt: 'desc' }
      });
    }, {
      tagResolver: (bookings) => (bookings || [])
        .map((booking: any) => booking?.id ? APIPerformanceService.getOrderTag(booking.id) : null)
        .filter((tag: string | null): tag is string => Boolean(tag))
    });
  }
  
  /**
   * Batch operations for improved performance
   */
  static async batchUpdateBookings(updates: Array<{
    bookingId: string;
    status?: string;
    actualArrival?: Date;
    coordinates?: { lat: number; lng: number };
  }>) {
    return prisma.$transaction(async (tx) => {
      const results = [];
      
      for (const update of updates) {
        const result = await tx.booking.update({
          where: { id: update.bookingId },
          data: {
            ...(update.status && { 
              status: update.status as any 
            }),
            ...(update.actualArrival && { 
              updatedAt: update.actualArrival 
            })
          }
        });
        results.push(result);
      }
      
      return results;
    });
  }
  
  /**
   * Database connection pooling optimization
   */
  static async optimizeConnection() {
    // Check connection health
    try {
      await prisma.$queryRaw`SELECT 1`;
      return { healthy: true };
    } catch (error) {
      console.error('Database connection error:', error);
      return { healthy: false, error };
    }
  }
  
  /**
   * Clear cache by pattern
   */
  static clearCache(pattern?: string) {
    if (pattern) {
      // Clear specific cache pattern
      for (const [cacheName, cache] of caches.entries()) {
        if (cacheName.includes(pattern)) {
          cache.clear();
        }
      }
    } else {
      // Clear all caches
      caches.forEach(cache => cache.clear());
    }
  }
  
  /**
   * Record performance metrics
   */
  static recordPerformance(
    endpoint: string,
    method: string,
    responseTime: number,
    cacheHit: boolean,
    statusCode: number
  ) {
    performanceMetrics.push({
      endpoint,
      method,
      responseTime,
      cacheHit,
      statusCode,
      timestamp: new Date()
    });
    
    // Keep only last 1000 metrics
    if (performanceMetrics.length > 1000) {
      performanceMetrics.splice(0, performanceMetrics.length - 1000);
    }
  }
  
  /**
   * Get performance analytics
   */
  static getPerformanceAnalytics(timeframe: 'hour' | 'day' | 'week' = 'hour') {
    const now = new Date();
    const timeframes = {
      hour: 60 * 60 * 1000,
      day: 24 * 60 * 60 * 1000,
      week: 7 * 24 * 60 * 60 * 1000
    };
    
    const cutoff = new Date(now.getTime() - timeframes[timeframe]);
    const recentMetrics = performanceMetrics.filter(m => m.timestamp >= cutoff);
    
    if (recentMetrics.length === 0) {
      return {
        totalRequests: 0,
        averageResponseTime: 0,
        cacheHitRate: 0,
        errorRate: 0,
        endpointStats: {}
      };
    }
    
    const totalRequests = recentMetrics.length;
    const averageResponseTime = recentMetrics.reduce((sum, m) => sum + m.responseTime, 0) / totalRequests;
    const cacheHits = recentMetrics.filter(m => m.cacheHit).length;
    const cacheHitRate = (cacheHits / totalRequests) * 100;
    const errors = recentMetrics.filter(m => m.statusCode >= 400).length;
    const errorRate = (errors / totalRequests) * 100;
    
    // Endpoint-specific stats
    const endpointStats: Record<string, any> = {};
    recentMetrics.forEach(m => {
      const key = `${m.method} ${m.endpoint}`;
      if (!endpointStats[key]) {
        endpointStats[key] = {
          requests: 0,
          totalResponseTime: 0,
          cacheHits: 0,
          errors: 0
        };
      }
      
      endpointStats[key].requests++;
      endpointStats[key].totalResponseTime += m.responseTime;
      if (m.cacheHit) endpointStats[key].cacheHits++;
      if (m.statusCode >= 400) endpointStats[key].errors++;
    });
    
    // Calculate averages for each endpoint
    Object.keys(endpointStats).forEach(key => {
      const stats = endpointStats[key];
      stats.averageResponseTime = stats.totalResponseTime / stats.requests;
      stats.cacheHitRate = (stats.cacheHits / stats.requests) * 100;
      stats.errorRate = (stats.errors / stats.requests) * 100;
    });
    
    return {
      totalRequests,
      averageResponseTime: Math.round(averageResponseTime),
      cacheHitRate: Math.round(cacheHitRate * 100) / 100,
      errorRate: Math.round(errorRate * 100) / 100,
      endpointStats
    };
  }
  
  /**
   * Performance middleware wrapper
   */
  static withPerformanceMonitoring(
    endpoint: string,
    handler: (request: NextRequest) => Promise<Response>
  ) {
    return async (request: NextRequest): Promise<Response> => {
      const startTime = Date.now();
      const cacheHit = false;
      let statusCode = 200;
      
      try {
        // Add cache hit detection to request context
        const originalJson = Response.prototype.json; void originalJson;
        const response: Response = await handler(request);
        statusCode = response.status;
        
        return response;
        
      } catch (error) {
        statusCode = 500;
        throw error;
        
      } finally {
        const responseTime = Date.now() - startTime;
        this.recordPerformance(
          endpoint,
          request.method,
          responseTime,
          cacheHit,
          statusCode
        );
      }
    };
  }
  
  /**
   * Query optimization suggestions
   */
  static async analyzeQueryPerformance() {
    const slowQueries = performanceMetrics
      .filter(m => m.responseTime > 1000) // Queries slower than 1 second
      .reduce((acc, m) => {
        const key = `${m.method} ${m.endpoint}`;
        if (!acc[key]) {
          acc[key] = {
            count: 0,
            averageTime: 0,
            totalTime: 0
          };
        }
        acc[key].count++;
        acc[key].totalTime += m.responseTime;
        acc[key].averageTime = acc[key].totalTime / acc[key].count;
        return acc;
      }, {} as Record<string, any>);
    
    const suggestions: string[] = [];
    
    Object.entries(slowQueries).forEach(([endpoint, stats]: [string, any]) => {
      if (stats.count >= 5) { // Multiple slow queries
        suggestions.push(endpoint);
      }
    });
    
    return suggestions;
  }
}

/**
 * Database query optimization helpers
 */
export class DatabaseOptimizer {
  
  /**
   * Create optimized indexes for multi-drop routes
   */
  static async createOptimizedIndexes() {
    const indexes = [
      // Multi-drop route indexes
      'CREATE INDEX IF NOT EXISTS idx_multidrop_routes_status_driver ON "MultiDropRoute" ("status", "driverId");',
      'CREATE INDEX IF NOT EXISTS idx_multidrop_routes_created_at ON "MultiDropRoute" ("createdAt");',
      'CREATE INDEX IF NOT EXISTS idx_multidrop_route_stops_route_sequence ON "MultiDropRouteStop" ("multiDropRouteId", "sequenceNumber");',
      'CREATE INDEX IF NOT EXISTS idx_multidrop_route_stops_booking ON "MultiDropRouteStop" ("bookingId");',
      
      // Booking indexes
      'CREATE INDEX IF NOT EXISTS idx_bookings_multidrop_status ON "Booking" ("isMultiDrop", "status");',
      'CREATE INDEX IF NOT EXISTS idx_bookings_scheduled_at ON "Booking" ("scheduledAt");',
      'CREATE INDEX IF NOT EXISTS idx_bookings_customer_driver ON "Booking" ("customerId", "driverId");',
      
      // Driver indexes
      'CREATE INDEX IF NOT EXISTS idx_drivers_status_location ON "Driver" ("status", "currentLocation");',
      
      // Performance indexes for reporting
      'CREATE INDEX IF NOT EXISTS idx_driver_earnings_date ON "DriverEarnings" ("createdAt");',
      'CREATE INDEX IF NOT EXISTS idx_assignments_claimed_at ON "Assignment" ("claimedAt") WHERE "claimedAt" IS NOT NULL;'
    ];
    
    const results = [];
    
    for (const indexSQL of indexes) {
      try {
        await prisma.$executeRawUnsafe(indexSQL);
        results.push({ sql: indexSQL, status: 'success' });
      } catch (error) {
        results.push({ 
          sql: indexSQL, 
          status: 'error', 
          error: error instanceof Error ? error.message : 'Unknown error' 
        });
      }
    }
    
    return results;
  }
  
  /**
   * Analyze query performance and suggest optimizations
   */
  static async analyzeQueryPerformance() {
    try {
      // Get query statistics (PostgreSQL specific)
      const slowQueries = await prisma.$queryRaw`
        SELECT 
          query,
          calls,
          total_time,
          mean_time,
          rows
        FROM pg_stat_statements 
        WHERE mean_time > 100 
        ORDER BY mean_time DESC 
        LIMIT 10;
      `;
      
      return {
        success: true,
        slowQueries,
        suggestions: [
          'Consider adding indexes for frequently queried columns',
          'Implement query result caching for repeated queries',
          'Use selective field loading to reduce data transfer',
          'Implement connection pooling for better resource management'
        ]
      };
      
    } catch (error) {
      // Fallback for non-PostgreSQL databases or missing pg_stat_statements
      return {
        success: false,
        message: 'Query performance analysis requires PostgreSQL with pg_stat_statements extension',
        error: error instanceof Error ? error.message : 'Unknown error'
      };
    }
  }
}

/**
 * Automatic Route Creation Scheduler
 * Runs every 15 minutes to create optimized routes from pending drops
 */

import { prisma } from '@/lib/prisma';

interface SchedulerStats {
  lastRun: Date | null;
  totalRuns: number;
  routesCreated: number;
  dropsProcessed: number;
  errors: number;
}

class AutoRouteScheduler {
  private isRunningFlag = false; // Flag for single run in progress
  private intervalId: ReturnType<typeof setInterval> | null = null;
  private stats: SchedulerStats = {
    lastRun: null,
    totalRuns: 0,
    routesCreated: 0,
    dropsProcessed: 0,
    errors: 0,
  };

  // Configuration
  private readonly INTERVAL_MS = 15 * 60 * 1000; // 15 minutes
  private readonly MAX_DROPS_PER_ROUTE = 10;
  private readonly MAX_DISTANCE_KM = 50;
  private readonly TIME_WINDOW_TOLERANCE_HOURS = 4;

  /**
   * Start the automatic scheduler
   */
  start() {
    if (this.intervalId) {
      console.log('⚠️  Auto Route Scheduler is already running');
      return;
    }

    console.log('🚀 Starting Auto Route Scheduler...');
    console.log(`📅 Will run every ${this.INTERVAL_MS / 60000} minutes`);

    // Run immediately on start
    this.runOrchestration();

    // Then run at intervals
    this.intervalId = setInterval(() => {
      this.runOrchestration();
    }, this.INTERVAL_MS);

    console.log('✅ Auto Route Scheduler started successfully');
  }

  /**
   * Stop the scheduler
   */
  stop() {
    if (this.intervalId) {
      clearInterval(this.intervalId);
      this.intervalId = null;
      console.log('🛑 Auto Route Scheduler stopped');
    }
  }

  /**
   * Get scheduler statistics
   */
  getStats(): SchedulerStats {
    return { ...this.stats };
  }

  /**
   * Check if scheduler is currently running
   */
  isRunning(): boolean {
    return this.intervalId !== null;
  }

  /**
   * Main orchestration logic
   */
  private async runOrchestration() {
    if (this.isRunningFlag) {
      console.log('⏭️  Skipping - previous run still in progress');
      return;
    }

    this.isRunningFlag = true;
    const startTime = Date.now();

    try {
      console.log('\n🔄 Starting Auto Route Orchestration...');
      console.log(`⏰ Time: ${new Date().toISOString()}`);

      // Get pending drops
      const pendingDrops = await prisma.drop.findMany({
        where: {
          status: 'booked',
          routeId: null,
        },
        select: {
          id: true,
          customerId: true,
          pickupAddress: true,
          deliveryAddress: true,
          timeWindowStart: true,
          timeWindowEnd: true,
          serviceTier: true,
          status: true,
          quotedPrice: true,
          weight: true,
          volume: true,
          User: {
            select: { name: true, email: true }
          }
        },
        orderBy: { timeWindowStart: 'asc' },
        take: 100, // Process in batches
      });

      if (pendingDrops.length === 0) {
        console.log('✅ No pending drops to process');
        this.stats.lastRun = new Date();
        this.stats.totalRuns++;
        return;
      }

      console.log(`📦 Found ${pendingDrops.length} pending drops`);

      // Get available drivers
      const availableDrivers = await prisma.driver.findMany({
        where: {
          status: 'active'
        },
        include: {
          User: { select: { name: true } }
        },
      });

      console.log(`👥 Found ${availableDrivers.length} available drivers`);

      // Create routes using clustering algorithm
      const routes = this.clusterDropsIntoRoutes(pendingDrops);
      console.log(`🗺️  Created ${routes.length} route clusters`);

      // Save routes to database
      let routesCreated = 0;
      let dropsAssigned = 0;

      for (let i = 0; i < routes.length; i++) {
        const dropGroup = routes[i];
        const assignedDriver = i < availableDrivers.length ? availableDrivers[i] : null;

        try {
          const totalOutcome = dropGroup.reduce((sum, d) => {
            const price = Number(d.quotedPrice || 0);
            return (Number.isFinite(price) && price >= 0 && price <= Number.MAX_SAFE_INTEGER) ? sum + price : sum;
          }, 0);
          const totalWeight = dropGroup.reduce((sum, d) => sum + (d.weight || 0), 0);
          const totalVolume = dropGroup.reduce((sum, d) => sum + (d.volume || 0), 0);

          const route = await prisma.route.create({
            data: {
              driverId: assignedDriver?.id || (await this.getOrCreateSystemDriver()).id,
              status: assignedDriver ? 'assigned' : 'planned',
              startTime: dropGroup[0].timeWindowStart,
              timeWindowStart: dropGroup[0].timeWindowStart,
              timeWindowEnd: dropGroup[dropGroup.length - 1].timeWindowEnd,
              serviceTier: dropGroup[0].serviceTier || 'standard',
              totalDrops: dropGroup.length,
              completedDrops: 0,
              totalOutcome,
              maxCapacityWeight: totalWeight,
              maxCapacityVolume: totalVolume,
              routeOptimizationVersion: '2.0-auto',
              routeNotes: `Auto-generated by scheduler at ${new Date().toISOString()}`,
              routeComplexityScore: Math.min(dropGroup.length, 5),
            }
          });

          // Update drops
          await prisma.drop.updateMany({
            where: { id: { in: dropGroup.map(d => d.id) } },
            data: {
              routeId: route.id,
              status: 'assigned_to_route',
            }
          });

          // Log optimization history (disabled - model not available)
          /*
          await prisma.routeOptimizationHistory.create({
            data: {
              routeId: route.id,
              optimizationType: 'initial',
              algorithmVersion: '2.0-auto-scheduler',
              inputParameters: {
                maxDropsPerRoute: this.MAX_DROPS_PER_ROUTE,
                maxDistanceKm: this.MAX_DISTANCE_KM,
                autoScheduled: true,
                timestamp: new Date().toISOString(),
              },
              optimizationResult: {
                dropsCount: dropGroup.length,
                estimatedDuration: dropGroup.length * 30,
                totalValue: totalOutcome,
                driverAssigned: !!assignedDriver,
              },
            }
          });
          */

          routesCreated++;
          dropsAssigned += dropGroup.length;

          console.log(`  ✅ Route ${i + 1}: ${dropGroup.length} drops${assignedDriver ? ` → ${assignedDriver.User?.name}` : ' (unassigned)'}`);

        } catch (error) {
          console.error(`  ❌ Failed to create route ${i + 1}:`, error);
          this.stats.errors++;
        }
      }

      // Update stats
      this.stats.lastRun = new Date();
      this.stats.totalRuns++;
      this.stats.routesCreated += routesCreated;
      this.stats.dropsProcessed += dropsAssigned;

      const duration = Date.now() - startTime;
      console.log(`\n✅ Orchestration Complete!`);
      console.log(`   📊 Routes Created: ${routesCreated}`);
      console.log(`   📦 Drops Assigned: ${dropsAssigned}/${pendingDrops.length}`);
      console.log(`   ⏱️  Duration: ${duration}ms`);
      console.log(`   📈 Total Runs: ${this.stats.totalRuns}`);

    } catch (error) {
      console.error('❌ Auto Route Orchestration failed:', error);
      this.stats.errors++;
    } finally {
      this.isRunningFlag = false;
    }
  }

  /**
   * Cluster drops into routes using simple algorithm
   */
  private clusterDropsIntoRoutes(drops: any[]): any[][] {
    const routes: any[][] = [];
    let currentGroup: any[] = [];
    let currentTime = drops[0]?.timeWindowStart;

    for (const drop of drops) {
      // Check if drop fits in current group
      const timeDiff = Math.abs(
        drop.timeWindowStart.getTime() - currentTime.getTime()
      ) / (1000 * 60 * 60); // Hours

      if (
        currentGroup.length >= this.MAX_DROPS_PER_ROUTE ||
        timeDiff > this.TIME_WINDOW_TOLERANCE_HOURS
      ) {
        // Create new group
        if (currentGroup.length > 0) {
          routes.push(currentGroup);
        }
        currentGroup = [drop];
        currentTime = drop.timeWindowStart;
      } else {
        currentGroup.push(drop);
      }
    }

    // Add last group
    if (currentGroup.length > 0) {
      routes.push(currentGroup);
    }

    return routes;
  }

  /**
   * Manual trigger (for testing or admin override)
   */
  async triggerNow(): Promise<void> {
    console.log('🔥 Manual trigger requested');
    await this.runOrchestration();
  }

  /**
   * Get or create a system driver for unassigned routes
   */
  private async getOrCreateSystemDriver() {
    try {
      // Try to find existing system driver
      let systemDriver = await prisma.user.findFirst({
        where: {
          email: 'system@speedy-van.co.uk',
          role: 'driver'
        }
      });

      if (!systemDriver) {
        // Create system driver if not exists
        systemDriver = await prisma.user.create({
          data: {
            email: 'system@speedy-van.co.uk',
            name: 'System Driver',
            password: 'system_password_not_used', // System user, password not used
            role: 'driver',
            isActive: true,
            emailVerified: true
          }
        });
      }

      return systemDriver;
    } catch (error) {
      console.error('❌ Failed to get/create system driver:', error);
      throw error;
    }
  }
}

