export const driverEarningsService = new DriverEarningsService();




// ============================================================================
// ✅ FIX #10: ROUTE EARNINGS CALCULATION
// ============================================================================

export interface RouteEarningsResult {
  routeId: string;
  totalEarnings: number; // in pence
  totalDistance: number; // in miles
  totalDuration: number; // in minutes
  numberOfStops: number;
  breakdowns: DriverEarningsBreakdown[];
  formattedEarnings: string;
  earningsPerStop: number;
  earningsPerMile: number;
  earningsPerHour: number;
}

/**
 * ✅ FIX #10: Calculate total earnings for an entire multi-drop route
 * This allows drivers to see their total earnings before accepting a route
 */
export async function calculateRouteEarnings(
  routeId: string
): Promise<RouteEarningsResult> {
  const route = await prisma.route.findUnique({
    where: { id: routeId },
    include: {
      Booking: {
        include: {
          BookingItem: true,
        },
      },
    },
  });
  
  if (!route) {
    throw new Error(`Route ${routeId} not found`);
  }
  
  const service = new DriverEarningsService();
  
  let totalEarnings = 0;
  const breakdowns: DriverEarningsBreakdown[] = [];
  
  // Calculate earnings for each booking in the route
  for (const booking of route.Booking) {
    const earnings = await service.calculateEarnings({
      assignmentId: `temp_${routeId}_${booking.id}`,
      driverId: route.driverId || 'unassigned',
      bookingId: booking.id,
      distanceMiles: booking.baseDistanceMiles || 0,
      durationMinutes: booking.estimatedDurationMinutes || 0,
      dropCount: route.Booking.length, // Total drops in route
      customerPaymentPence: booking.totalGBP,
      urgencyLevel: booking.urgency as any,
      serviceType: 'standard',
      onTimeDelivery: true, // Assume on-time for estimation
    });
    
    totalEarnings += earnings.breakdown.netEarnings;
    breakdowns.push(earnings.breakdown);
  }
  
  // ✅ FIX #8: Add multi-drop bonus to route total
  if (route.Booking.length > 2) {
    const multiDropBonus = Math.max(
      2000, // £20 minimum
      (route.Booking.length - 2) * 1000 // £10 per extra stop
    );
    totalEarnings += multiDropBonus;
  }
  
  const totalDistance = route.actualDistanceKm || route.optimizedDistanceKm || 0;
  const totalDuration = route.actualDuration || route.estimatedDuration || 0;
  
  return {
    routeId,
    totalEarnings,
    totalDistance,
    totalDuration,
    numberOfStops: route.Booking.length,
    breakdowns,
    formattedEarnings: `£${(totalEarnings / 100).toFixed(2)}`,
    earningsPerStop: totalEarnings / route.Booking.length,
    earningsPerMile: totalDistance > 0 ? totalEarnings / totalDistance : 0,
    earningsPerHour: totalDuration > 0 ? (totalEarnings / totalDuration) * 60 : 0,
  };
}

/**
 * Driver Tracking Service
 * 
 * Handles real-time driver location tracking and status management
 */

import { PrismaClient } from '@prisma/client';

const prisma = new PrismaClient();

export interface DriverLocation {
  driverId: string;
  latitude: number;
  longitude: number;
  accuracy?: number;
  timestamp: Date;
  speed?: number;
  heading?: number;
}

export interface DriverStatus {
  driverId: string;
  status: 'offline' | 'available' | 'on_route' | 'break';
  currentRouteId?: string;
  lastUpdate: Date;
  nextDropETA?: Date;
}

export interface TrackingUpdate {
  location: DriverLocation;
  status: DriverStatus;
  routeProgress?: {
    routeId: string;
    completedDrops: number;
    totalDrops: number;
    estimatedCompletion: Date;
  };
}

export class DriverTrackingService {
  /**
   * Update driver location and status
   */
  public static async updateDriverTracking(update: TrackingUpdate): Promise<void> {
    try {
      // 1. Update driver availability record
      await prisma.driverAvailability.upsert({
        where: { driverId: update.status.driverId },
        update: {
          status: update.status.status,
          lastSeenAt: update.location.timestamp,
          lastLat: update.location.latitude,
          lastLng: update.location.longitude
        },
        create: {
          driverId: update.status.driverId,
          status: update.status.status,
          lastSeenAt: update.location.timestamp,
          lastLat: update.location.latitude,
          lastLng: update.location.longitude
        }
      });

      // 2. Create tracking ping record
      await prisma.trackingPing.create({
        data: {
          id: `ping-${Date.now()}-${update.status.driverId}`, // Generate unique ID
          driverId: update.status.driverId,
          bookingId: update.status.currentRouteId || `booking-${update.status.driverId}`, // Use routeId as bookingId fallback
          lat: update.location.latitude,
          lng: update.location.longitude
        }
      });

      // 3. Update route progress if on route
      if (update.routeProgress && update.status.currentRouteId) {
        await this.updateRouteProgress(
          update.status.currentRouteId,
          update.routeProgress
        );
      }

      // 4. Send real-time notifications to admin dashboard
      await this.broadcastTrackingUpdate(update);

    } catch (error) {
      console.error('Error updating driver tracking:', error);
      throw error;
    }
  }

  /**
   * Get current location and status for all active drivers
   */
  public static async getActiveDrivers(): Promise<TrackingUpdate[]> {
    try {
      const activeDrivers = await prisma.driverAvailability.findMany({
        where: {
          status: { in: ['available', 'on_route'] },
          lastSeenAt: {
            gte: new Date(Date.now() - 15 * 60 * 1000) // Last 15 minutes
          }
        },
        include: {
          Driver: {
            include: {
              User: {
                select: {
                  id: true,
                  name: true,
                  email: true,
                  role: true,
                  createdAt: true,
                  isActive: true
                }
              },
              DriverProfile: true
            }
          }
        }
      });

      return activeDrivers.map(driver => ({
        location: {
          driverId: driver.driverId,
          latitude: driver.lastLat || 0,
          longitude: driver.lastLng || 0,
          timestamp: driver.lastSeenAt
        },
        status: {
          driverId: driver.driverId,
          status: driver.status as any,
          lastUpdate: driver.updatedAt
        }
      }));

    } catch (error) {
      console.error('Error getting active drivers:', error);
      return [];
    }
  }

