    try {
      const trackingPings = await prisma.trackingPing.findMany({
        where: {
          driverId,
          createdAt: {
            gte: timeRange.start,
            lte: timeRange.end
          }
        },
        orderBy: { createdAt: 'asc' }
      });

      return trackingPings.map(ping => ({
        driverId: ping.driverId,
