export class QuoteService {
  /**
   * Generate a new quote with dynamic pricing
   */
  public static async createQuote(request: QuoteRequest): Promise<QuoteResponse> {
    try {
      // 1. Get customer profile for segment-based pricing
      const customer = await prisma.user.findUnique({
        where: { id: request.customerId },
        include: { customerProfile: true }
      });

      if (!customer) {
        throw new Error('Customer not found');
      }

      // 2. Calculate distance and duration (would use real mapping service in production)
      const { distance, duration } = await this.calculateDistanceAndDuration( // DEPRECATED - internal use only
        request.pickupPostcode,
        request.deliveryPostcode
      );

      // 3. Get current market variables (using defaults for now)
      const marketVariables = {
        laneUtilization: 0.6,
        networkCapacity: 0.7,
        timeOfWeek: 'standard' as const,
        seasonalFactor: 1.0,
        fuelCostPence: 145,
        weatherConditions: 'good' as const,
        trafficConditions: 'moderate' as const,
        localEvents: false
      };

      // 4. Build pricing variables
      const pricingVariables: PricingVariables = {
        // Core job factors
        weight: request.weight || 10, // Default 10kg
        volume: request.volume || 0.1, // Default 0.1m3
        distance,
        urgency: 'standard', // Default urgency
        timeOfDay: 'standard', // Default time of day
        fragility: request.fragility || 'low',

        // Operational factors (from market data)
        laneUtilization: marketVariables.laneUtilization || 0.6,
        networkCapacity: marketVariables.networkCapacity || 0.7,
        timeOfWeek: marketVariables.timeOfWeek || 'standard',
        seasonalFactor: marketVariables.seasonalFactor || 1.0,

        // External factors
        fuelCostPence: marketVariables.fuelCostPence || 145,
        weatherConditions: marketVariables.weatherConditions || 'good',
        trafficConditions: marketVariables.trafficConditions || 'moderate',
        localEvents: marketVariables.localEvents || false,

        // Customer factors
        customerSegment: customer.customerProfile?.segment || 'bronze',
        serviceTier: 'standard', // Will be applied per tier
        loyaltyDiscount: this.calculateLoyaltyDiscount(customer.customerProfile),
        volumeDiscount: this.calculateVolumeDiscount(customer.customerProfile),

        // Geographic factors
        pickupPostcode: request.pickupPostcode,
        deliveryPostcode: request.deliveryPostcode,
        isUrbanPickup: this.isUrbanPostcode(request.pickupPostcode),
        isUrbanDelivery: this.isUrbanPostcode(request.deliveryPostcode),
        congestionZone: this.isCongestionZone(request.pickupPostcode, request.deliveryPostcode)
      };

      // 5. Calculate pricing
      const pricingResult = await dynamicPricingEngine.calculatePrice(pricingVariables);

      // 6. Store quote in database
      const quote = await prisma.quote.create({
        data: {
          customerId: request.customerId,
          pickupAddress: request.pickupAddress,
          deliveryAddress: request.deliveryAddress,
          weight: request.weight,
          volume: request.volume,
          distance,
          economyPrice: pricingResult.prices.economy,
          standardPrice: pricingResult.prices.standard,
          premiumPrice: pricingResult.prices.premium,
          validUntil: pricingResult.validUntil,
          variables: pricingVariables as any // Store for audit/analysis
        }
      });

      return {
        quoteId: quote.id,
        prices: pricingResult.prices,
        validUntil: pricingResult.validUntil,
        breakdown: pricingResult.breakdown,
        estimatedDistance: distance,
        estimatedDuration: duration
      };

    } catch (error) {
      console.error('Error creating quote:', error);
      throw new Error('Failed to generate quote');
    }
  }

  /**
   * Retrieve an existing quote
   */
  public static async getQuote(quoteId: string): Promise<QuoteResponse | null> {
    try {
      const quote = await prisma.quote.findUnique({
        where: { id: quoteId }
      });

      if (!quote) return null;

      // Check if quote is still valid
      if (new Date() > quote.validUntil) {
        return null; // Quote expired
      }

      return {
        quoteId: quote.id,
        prices: {
          economy: quote.economyPrice.toNumber(),
          standard: quote.standardPrice.toNumber(),
          premium: quote.premiumPrice.toNumber()
        },
        validUntil: quote.validUntil,
        breakdown: quote.variables,
        estimatedDistance: quote.distance || 0,
        estimatedDuration: 0 // Would calculate from stored data
      };

    } catch (error) {
      console.error('Error retrieving quote:', error);
      return null;
    }
  }

  /**
   * Calculate distance and duration between postcodes
   * In production, this would use Google Maps API or similar
   */
  private static async calculateDistanceAndDuration( // DEPRECATED - internal use only
    _pickupPostcode: string,
    _deliveryPostcode: string
  ): Promise<{ distance: number; duration: number }> {
    void _pickupPostcode; void _deliveryPostcode;
    // Mock calculation - in production use real mapping API
    const mockDistance = Math.random() * 50 + 5; // 5-55 km
    const mockDuration = mockDistance * 2 + 20; // Rough estimate in minutes

    return {
      distance: Math.round(mockDistance * 100) / 100,
      duration: Math.round(mockDuration)
    };
  }

  /**
   * Calculate loyalty discount based on customer history
   */
  private static calculateLoyaltyDiscount(customerProfile: any): number {
    if (!customerProfile) return 0;

    const totalSpent = customerProfile.totalSpent?.toNumber() || 0;
    
    if (totalSpent > 5000) return 0.1; // 10% for high-value customers
    if (totalSpent > 2000) return 0.05; // 5% for medium-value customers
    if (totalSpent > 500) return 0.02; // 2% for loyal customers
    
    return 0;
  }

  /**
   * Calculate volume discount for frequent customers
   */
  private static calculateVolumeDiscount(customerProfile: any): number {
    if (!customerProfile) return 0;

    const avgOrderValue = customerProfile.avgOrderValue?.toNumber() || 0;
    
    if (avgOrderValue > 200) return 0.05; // 5% for large orders
    if (avgOrderValue > 100) return 0.025; // 2.5% for medium orders
    
    return 0;
  }

  /**
   * Check if postcode is in urban area
   */
  private static isUrbanPostcode(postcode: string): boolean {
    // Major UK urban areas (simplified check)
    const urbanPrefixes = ['M', 'B', 'L', 'S', 'G', 'E', 'W', 'N', 'SE', 'SW', 'NW'];
    const prefix = postcode.substring(0, 2).toUpperCase();
    return urbanPrefixes.some(urban => prefix.startsWith(urban));
  }

  /**
   * Check if route passes through congestion charging zone
   */
  private static isCongestionZone(pickupPostcode: string, deliveryPostcode: string): boolean {
    // London congestion zone postcodes (simplified)
    const congestionZones = ['EC', 'WC', 'E1', 'SE1', 'SW1'];
    
    const pickupPrefix = pickupPostcode.substring(0, 2).toUpperCase();
    const deliveryPrefix = deliveryPostcode.substring(0, 2).toUpperCase();
    
    return congestionZones.includes(pickupPrefix) || congestionZones.includes(deliveryPrefix);
  }

  /**
   * Refresh an expired quote with current pricing
   */
  public static async refreshQuote(quoteId: string): Promise<QuoteResponse | null> {
    try {
      const existingQuote = await prisma.quote.findUnique({
        where: { id: quoteId },
        include: { customer: { include: { customerProfile: true } } }
      });

      if (!existingQuote) return null;

      // Create new quote with same parameters
      const newQuoteRequest: QuoteRequest = {
        customerId: existingQuote.customerId,
        pickupAddress: existingQuote.pickupAddress,
        deliveryAddress: existingQuote.deliveryAddress,
        pickupPostcode: this.extractPostcode(existingQuote.pickupAddress),
        deliveryPostcode: this.extractPostcode(existingQuote.deliveryAddress),
        weight: existingQuote.weight || undefined,
        volume: existingQuote.volume || undefined
      };

      return await this.createQuote(newQuoteRequest);

    } catch (error) {
      console.error('Error refreshing quote:', error);
      return null;
    }
  }

  /**
   * Extract postcode from address (simple implementation)
   */
  private static extractPostcode(address: string): string {
    // Simple regex to extract UK postcode
    const postcodeRegex = /[A-Z]{1,2}[0-9][A-Z0-9]? ?[0-9][A-Z]{2}/i;
    const match = address.match(postcodeRegex);
    return match ? match[0] : 'SW1A 1AA'; // Default London postcode
  }
}

import { prisma } from '@/lib/prisma';
import type { Driver, Booking, Route } from '@prisma/client';

export interface OptimizationRequest {
  bookingId: string;
  driverId?: string;
  constraints: {
    timeWindows: Array<{ start: Date; end: Date }>;
    vehicleCapacity: number;
    driverSkills: string[];
    maxDistance: number;
    priorityLevel: 'LOW' | 'STANDARD' | 'HIGH' | 'URGENT';
  };
  objectives: Array<'minimize_cost' | 'minimize_time' | 'maximize_satisfaction' | 'maximize_efficiency'>;
}

export interface DriverScore {
  driverId: string;
  score: number;
  estimatedCost: number;
  factors: {
    distance: number;
    performance: number;
    availability: number;
    skillMatch: number;
    cost: number;
    customerPreference: number;
  };
  tradeoffs: string[];
}

export interface BookingWithRoute extends Booking {
  route?: Route | null;
  pickupAddress?: {
    id: string;
    label: string;
    postcode: string;
    lat: number;
    lng: number;
  } | null;
  dropoffAddress?: {
    id: string;
    label: string;
    postcode: string;
    lat: number;
    lng: number;
  } | null;
}

export interface DriverWithRelations extends Driver {
  Assignment: Array<{
    Booking: Booking;
  }>;
  DriverShift: Array<{
    startTime: Date;
    endTime: Date;
  }>;
}

export interface DriverShift {
  startTime: Date;
  endTime: Date;
}

export interface OptimizationResult {
  optimizedRoute: {
    driverId: string;
    estimatedDuration: number;
    estimatedDistance: number;
    estimatedCost: number;
    waypoints: Array<{
      address: string;
      estimatedArrival: Date;
      serviceTime: number;
      priority: number;
    }>;
  };
  alternatives: Array<{
    driverId: string;
    score: number;
    tradeoffs: string[];
  }>;
  optimizationScore: number;
  recommendations: string[];
  confidence: number;
}

export interface ResourceAllocation {
  driverId: string;
  vehicleId: string;
  helperIds: string[];
  equipment: string[];
  estimatedUtilization: number;
  skillMatch: number;
  availabilityScore: number;
}

export class RealTimeOptimizationService {
  private static instance: RealTimeOptimizationService;

  static getInstance(): RealTimeOptimizationService {
    if (!RealTimeOptimizationService.instance) {
      RealTimeOptimizationService.instance = new RealTimeOptimizationService();
    }
    return RealTimeOptimizationService.instance;
  }

  async optimizeBookingAssignment(request: OptimizationRequest): Promise<OptimizationResult> {
    try {
      // Step 1: Get booking details
      const booking = await this.getBookingDetails(request.bookingId);
      if (!booking) {
        throw new Error('Booking not found');
      }

      // Step 2: Find available drivers
      const availableDrivers = await this.findAvailableDrivers(booking, request.constraints);

      // Step 3: Calculate optimization scores for each driver
      const driverScores = await Promise.all(
        availableDrivers.map(driver => this.calculateDriverScore(driver, booking, request))
      );

      // Step 4: Select optimal driver
      const optimalDriver = this.selectOptimalDriver(driverScores, request.objectives);

      if (!optimalDriver) {
        throw new Error('No suitable driver found for optimization');
      }

      // Step 5: Generate optimized route
      const optimizedRoute = await this.generateOptimizedRoute(optimalDriver, booking);

      // Step 6: Calculate alternatives
      const alternatives = this.generateAlternatives(driverScores, optimalDriver.driverId);

      // Step 7: Calculate overall optimization score
      const optimizationScore = this.calculateOptimizationScore(optimalDriver, booking, request);

      // Step 8: Generate recommendations
      const recommendations = this.generateOptimizationRecommendations(optimalDriver, booking, alternatives);

      return {
        optimizedRoute,
        alternatives,
        optimizationScore,
        recommendations,
        confidence: this.calculateConfidence(driverScores, optimizationScore)
      };

    } catch (error) {
      console.error('Optimization failed:', error);
      throw new Error('Failed to optimize booking assignment');
    }
  }

  async optimizeFleetUtilization(timeWindow: { start: Date; end: Date }): Promise<{
    currentUtilization: number;
    optimizedUtilization: number;
    recommendations: Array<{
      type: 'rebalance' | 'schedule_maintenance' | 'adjust_capacity';
      description: string;
      impact: number;
      priority: 'LOW' | 'MEDIUM' | 'HIGH';
    }>;
  }> {
    // Get current fleet status
    const fleetStatus = await this.getFleetStatus(timeWindow);
    
    // Calculate current utilization
    const currentUtilization = this.calculateFleetUtilization(fleetStatus);
    
    // Generate optimization recommendations
    const recommendations = await this.generateFleetOptimizationRecommendations(fleetStatus);
    
    // Calculate potential optimized utilization
    const optimizedUtilization = this.calculateOptimizedUtilization(currentUtilization, recommendations);

    return {
      currentUtilization,
      optimizedUtilization,
      recommendations
    };
  }

  async optimizeResourceAllocation(bookingIds: string[]): Promise<ResourceAllocation[]> {
    const allocations: ResourceAllocation[] = [];

    for (const bookingId of bookingIds) {
      const booking = await this.getBookingDetails(bookingId);
      if (!booking) continue;

      // Find optimal resource allocation for this booking
      const allocation = await this.findOptimalResourceAllocation(booking);
      allocations.push(allocation);
    }

    // Optimize across all allocations to avoid conflicts
    return this.resolveResourceConflicts(allocations);
  }

  private async getBookingDetails(bookingId: string) {
    return await prisma.booking.findUnique({
      where: { id: bookingId },
      include: {
        pickupAddress: true,
        dropoffAddress: true,
        BookingItem: true,
        customer: true,
      }
    });
  }

  private async findAvailableDrivers(booking: BookingWithRoute, constraints: OptimizationRequest['constraints']): Promise<Driver[]> {
    void constraints;
    const scheduledTime = new Date(booking.scheduledAt);
    const timeBuffer = 2 * 60 * 60 * 1000; // 2 hours buffer

    return await prisma.driver.findMany({
      where: {
        status: 'active',
        // Check availability in the time window
        DriverShift: {
          some: {
            startTime: { lte: new Date(scheduledTime.getTime() - timeBuffer) },
            endTime: { gte: new Date(scheduledTime.getTime() + timeBuffer) },
            isActive: true
          }
        },
        // Check if not already assigned
        Assignment: {
          none: {
            Booking: {
              scheduledAt: {
                gte: new Date(scheduledTime.getTime() - timeBuffer),
                lte: new Date(scheduledTime.getTime() + timeBuffer)
              },
              status: { in: ['CONFIRMED', 'COMPLETED'] }
            }
          }
        }
      },
      include: {
        User: {
          select: {
            id: true,
            name: true,
            email: true,
            role: true,
            createdAt: true,
            isActive: true
          }
        },
        DriverShift: {
          where: {
            startTime: { lte: new Date(scheduledTime.getTime() + timeBuffer) },
            endTime: { gte: new Date(scheduledTime.getTime() - timeBuffer) },
            isActive: true
          }
        }
      }
    });
  }

  private async calculateDriverScore(driver: Driver, booking: BookingWithRoute, request: OptimizationRequest): Promise<DriverScore> {
    let score = 0;
    const factors = {
      distance: 0,
      performance: 0,
      availability: 0,
      skillMatch: 0,
      cost: 0,
      customerPreference: 0
    };

    // Distance factor (closer is better)
    const driverPostcode = driver.basePostcode || 'SW1A 1AA'; // Default to London center
    const pickupPostcode = booking.pickupAddress?.postcode || 'SW1A 1AA';
    const distance = await this.calculateDistance(driverPostcode, pickupPostcode); // DEPRECATED - internal use only
    factors.distance = Math.max(0, 1 - (distance / request.constraints.maxDistance));

    // Performance factor (simplified - no performance data available)
    factors.performance = 0.8; // Default performance score

    // Availability factor
    factors.availability = this.calculateAvailabilityScore(driver as DriverWithRelations, booking.scheduledAt);

    // Skill match factor
    factors.skillMatch = this.calculateSkillMatch(driver as DriverWithRelations, booking, request.constraints.driverSkills);

    // Cost factor (lower cost is better for cost optimization)
    const estimatedCost = await this.estimateDriverCost(driver as DriverWithRelations, booking);
    factors.cost = 1 - (estimatedCost / 200); // Normalize against £200 baseline

    // Customer preference factor
    factors.customerPreference = await this.getCustomerPreferenceScore(driver.id, booking.customerId || '');

    // Weight factors based on objectives
    const weights = this.getObjectiveWeights(request.objectives);
    
    score = 
      factors.distance * weights.distance +
      factors.performance * weights.performance +
      factors.availability * weights.availability +
      factors.skillMatch * weights.skillMatch +
      factors.cost * weights.cost +
      factors.customerPreference * weights.customerPreference;

    return {
      driverId: driver.id,
      score,
      estimatedCost,
      factors,
      tradeoffs: []
    };
  }

  private selectOptimalDriver(driverScores: DriverScore[], objectives: string[]): DriverScore | null {
    // Sort by score (highest first)
    driverScores.sort((a, b) => b.score - a.score);
    
    // Apply additional selection criteria based on objectives
    if (objectives.includes('minimize_cost')) {
      // If cost is a primary objective, consider cost-performance ratio
      driverScores.sort((a, b) => (b.score / b.estimatedCost) - (a.score / a.estimatedCost));
    }

    return driverScores[0];
  }

