        estimatedArrival: new Date(booking.scheduledAt.getTime() + estimatedDuration * 60 * 1000),
        serviceTime: 45, // 45 minutes for dropoff
        priority: 1
      }
    ];

    return {
      driverId: optimalDriver.driverId,
      estimatedDuration,
      estimatedDistance: distance,
      estimatedCost,
      waypoints
    };
  }

