import * as Sentry from '@sentry/nextjs';

export interface TelemetryEvent {
  event: string;
  properties?: Record<string, any>;
  userId?: string;
  sessionId?: string;
  timestamp?: number;
  environment?: string;
}

export interface PerformanceMetric {
  name: string;
  value: number;
  unit: string;
  tags?: Record<string, string>;
  timestamp?: number;
}

export interface BusinessMetric {
  name: string;
  value: number;
  category: 'driver' | 'job' | 'earnings' | 'performance' | 'system';
  tags?: Record<string, string>;
  timestamp?: number;
}

class TelemetryService {
  private sessionId: string;
  private userId?: string;
  private environment: string;
  private isEnabled: boolean;

  constructor() {
    this.sessionId = this.generateSessionId();
    this.environment = process.env.NODE_ENV || 'development';
    this.isEnabled = process.env.NEXT_PUBLIC_TELEMETRY_ENABLED === 'true';

    // Initialize Sentry
    if (this.isEnabled && typeof window !== 'undefined') {
      Sentry.init({
        dsn: process.env.NEXT_PUBLIC_SENTRY_DSN,
        environment: this.environment,
        tracesSampleRate: 0.1,
        replaysSessionSampleRate: 0.1,
        replaysOnErrorSampleRate: 1.0,
      });
    }
  }

  private generateSessionId(): string {
    return `session_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  }

  setUserId(userId: string) {
    this.userId = userId;
    if (this.isEnabled) {
      Sentry.setUser({ id: userId });
    }
  }

  trackEvent(event: string, properties?: Record<string, any>) {
    if (!this.isEnabled) return;

    const telemetryEvent: TelemetryEvent = {
      event,
      properties,
      userId: this.userId,
      sessionId: this.sessionId,
      timestamp: Date.now(),
      environment: this.environment,
    };

    // Send to Sentry
    Sentry.addBreadcrumb({
      category: 'telemetry',
      message: event,
      data: properties,
      level: 'info',
    });

    // Send to analytics endpoint
    this.sendToAnalytics(telemetryEvent);
  }

  trackError(error: Error, context?: Record<string, any>) {
    if (!this.isEnabled) return;

    Sentry.captureException(error, {
      extra: context,
      tags: {
        component: 'driver-portal',
        sessionId: this.sessionId,
      },
    });

    // Also send to analytics endpoint
    const telemetryEvent: TelemetryEvent = {
      event: 'error',
      properties: {
        error: error.message,
        stack: error.stack,
        ...context,
      },
      userId: this.userId,
      sessionId: this.sessionId,
      timestamp: Date.now(),
      environment: this.environment,
    };

    this.sendToAnalytics(telemetryEvent);
  }

  trackPerformance(metric: PerformanceMetric) {
    if (!this.isEnabled) return;

    // Send to performance monitoring
    this.sendToPerformanceMonitoring(metric);
  }

  trackBusinessMetric(metric: BusinessMetric) {
    if (!this.isEnabled) return;

    // Send to business metrics endpoint
    this.sendToBusinessMetrics(metric);
  }

  // Driver-specific metrics
  trackDriverLogin(success: boolean, method: string = 'email') {
    this.trackEvent('driver_login', {
      success,
      method,
      timestamp: Date.now(),
    });
  }

  trackJobClaim(jobId: string, success: boolean, reason?: string) {
    this.trackEvent('job_claim', {
      jobId,
      success,
      reason,
      timestamp: Date.now(),
    });

    if (success) {
      this.trackBusinessMetric({
        name: 'jobs_claimed',
        value: 1,
        category: 'job',
        tags: { jobId },
      });
    }
  }

  trackJobCompletion(jobId: string, duration: number, steps: string[]) {
    this.trackEvent('job_completion', {
      jobId,
      duration,
      steps,
      timestamp: Date.now(),
    });

    this.trackBusinessMetric({
      name: 'jobs_completed',
      value: 1,
      category: 'job',
      tags: { jobId },
    });

    this.trackPerformance({
      name: 'job_completion_time',
      value: duration,
      unit: 'seconds',
      tags: { jobId },
    });
  }

  trackAvailabilityChange(status: 'online' | 'offline' | 'break') {
    this.trackEvent('availability_change', {
      status,
      timestamp: Date.now(),
    });
  }

  trackDocumentUpload(
    documentType: string,
    success: boolean,
    fileSize?: number
  ) {
    this.trackEvent('document_upload', {
      documentType,
      success,
      fileSize,
      timestamp: Date.now(),
    });
  }

  trackEarningsView(period: string) {
    this.trackEvent('earnings_view', {
      period,
      timestamp: Date.now(),
    });
  }

  trackNavigationUsage(feature: string, success: boolean) {
    this.trackEvent('navigation_usage', {
      feature,
      success,
      timestamp: Date.now(),
    });
  }

  // Customer Portal specific metrics
  trackCustomerPortalLoad(loadTime: number) {
    this.trackPerformance({
      name: 'customer_portal_load_time',
      value: loadTime,
      unit: 'milliseconds',
      tags: { portal: 'customer' },
    });
  }

  trackTimeToFirstContent(page: string, timeToFirstContent: number) {
    this.trackPerformance({
      name: 'time_to_first_content',
      value: timeToFirstContent,
      unit: 'milliseconds',
      tags: { page },
    });
  }

  trackSignInSuccess(method: string, role: string) {
    this.trackEvent('auth_sign_in_success', {
      method,
      role,
      timestamp: Date.now(),
    });
  }

  trackSignInFailure(method: string, reason: string) {
    this.trackEvent('auth_sign_in_failure', {
      method,
      reason,
      timestamp: Date.now(),
    });
  }

  trackApiError(endpoint: string, status: number, error: string) {
    this.trackEvent('api_error', {
      endpoint,
      status,
      error,
      timestamp: Date.now(),
    });
  }

  trackDeepLinkRedirect(originalUrl: string, success: boolean) {
    this.trackEvent('deep_link_redirect', {
      originalUrl,
      success,
      timestamp: Date.now(),
    });
  }

  trackUnauthorizedAccess(attemptedUrl: string, userRole: string) {
    this.trackEvent('unauthorized_access', {
      attemptedUrl,
      userRole,
      timestamp: Date.now(),
    });
  }

  trackAppCrash(error: Error, context?: Record<string, any>) {
    this.trackError(error, {
      ...context,
      crashType: 'app_crash',
      sessionId: this.sessionId,
    });
  }

  trackPageLoad(page: string, loadTime: number) {
    this.trackPerformance({
      name: 'page_load_time',
      value: loadTime,
      unit: 'milliseconds',
      tags: { page },
    });
  }

  trackApiCall(
    endpoint: string,
    method: string,
    duration: number,
    success: boolean
  ) {
    this.trackPerformance({
      name: 'api_call_duration',
      value: duration,
      unit: 'milliseconds',
      tags: { endpoint, method, success: success.toString() },
    });
  }

  // NPS tracking
  trackNPS(score: number, feedback?: string) {
    this.trackEvent('nps_survey', {
      score,
      feedback,
      timestamp: Date.now(),
    });

    this.trackBusinessMetric({
      name: 'nps_score',
      value: score,
      category: 'performance',
    });
  }

  // Feature usage tracking
  trackFeatureUsage(feature: string, action: string, success: boolean) {
    this.trackEvent('feature_usage', {
      feature,
      action,
      success,
      timestamp: Date.now(),
    });
  }

  private async sendToAnalytics(event: TelemetryEvent) {
    try {
      await fetch('/api/telemetry/analytics', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(event),
      });
    } catch (error) {
      console.error('Failed to send analytics event:', error);
    }
  }

  private async sendToPerformanceMonitoring(metric: PerformanceMetric) {
    try {
      await fetch('/api/telemetry/performance', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(metric),
      });
    } catch (error) {
      console.error('Failed to send performance metric:', error);
    }
  }

  private async sendToBusinessMetrics(metric: BusinessMetric) {
    try {
      await fetch('/api/telemetry/business', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(metric),
      });
    } catch (error) {
      console.error('Failed to send business metric:', error);
    }
  }
}

// Create singleton instance
export const telemetry = new TelemetryService();

// React hook for telemetry
export function useTelemetry() {
  return telemetry;
}

// Performance monitoring
export function trackPagePerformance() {
  if (typeof window === 'undefined') return;

  // Track page load time
  const navigation = performance.getEntriesByType(
    'navigation'
  )[0] as PerformanceNavigationTiming;
  if (navigation) {
    telemetry.trackPageLoad(
      window.location.pathname,
      navigation.loadEventEnd - navigation.loadEventStart
    );
  }

  // Track Core Web Vitals
  if ('web-vital' in window) {
    // This would be set up with web-vitals library
    const webVitals = (window as any)['web-vital'];
    if (webVitals) {
      webVitals.getCLS(telemetry.trackPerformance);
      webVitals.getFID(telemetry.trackPerformance);
      webVitals.getFCP(telemetry.trackPerformance);
      webVitals.getLCP(telemetry.trackPerformance);
      webVitals.getTTFB(telemetry.trackPerformance);
    }
  }
}

// Error boundary integration
export function setupErrorBoundary() {
  if (typeof window === 'undefined') return;

  window.addEventListener('error', event => {
    telemetry.trackError(event.error, {
      filename: event.filename,
      lineno: event.lineno,
      colno: event.colno,
    });
  });

  window.addEventListener('unhandledrejection', event => {
    telemetry.trackError(new Error(event.reason), {
      type: 'unhandledrejection',
    });
  });
}

import { NextRequest, NextResponse } from 'next/server';
import { performanceMonitor } from './performance-monitor';
import { sentryService } from './sentry';
import { renderAnalyticsService } from './render-analytics';

// API route instrumentation decorator
export function instrumentApiRoute<T extends any[]>(
  handler: (...args: T) => Promise<NextResponse>,
  options: {
    route: string;
    method: string;
    trackAnalytics?: boolean;
    trackPerformance?: boolean;
  } = { route: 'unknown', method: 'GET' }
) {
  return async (...args: T): Promise<NextResponse> => {
    const request = args[0] as NextRequest;
    const startTime = Date.now();
    
    // Set user context for Sentry
    const userId = request.headers.get('x-user-id');
    const userRole = request.headers.get('x-user-role');
    if (userId) {
      sentryService.setUser({
        id: userId,
        role: userRole || undefined,
      });
    }
    
    // Add breadcrumb for request tracking
    sentryService.addBreadcrumb(
      `${options.method} ${options.route}`,
      'http',
      'info',
      {
        method: options.method,
        route: options.route,
        userAgent: request.headers.get('user-agent'),
        ip: request.headers.get('x-forwarded-for') || request.ip,
        userId,
        userRole,
      }
    );
    
    try {
      const response = await performanceMonitor.monitorApiRoute(
        options.route,
        options.method,
        () => handler(...args)
      );
      
      const duration = Date.now() - startTime;
      
      // Track analytics if enabled
      if (options.trackAnalytics) {
        renderAnalyticsService.track('api_request', {
          route: options.route,
          method: options.method,
          statusCode: response.status,
          responseTime: duration,
          userId,
          userRole,
        });
      }
      
      // Track performance if enabled
      if (options.trackPerformance && duration > 1000) {
        renderAnalyticsService.trackApiSlowResponse({
          route: options.route,
          method: options.method,
          responseTime: duration,
          threshold: 1000,
        });
      }
      
      return response;
    } catch (error) {
      const duration = Date.now() - startTime;
      
      // Track error analytics
      if (options.trackAnalytics) {
        renderAnalyticsService.track('api_error', {
          route: options.route,
          method: options.method,
          error: (error as Error).message,
          responseTime: duration,
          userId,
          userRole,
        });
      }
      
      throw error;
    } finally {
      // Clear user context
      sentryService.clearUser();
    }
  };
}

// Database operation instrumentation
export function instrumentDbOperation<T extends any[]>(
  operation: string,
  table: string,
  handler: (...args: T) => Promise<any>
) {
  return async (...args: T): Promise<any> => {
    const startTime = Date.now();
    
    try {
      const result = await performanceMonitor.monitorDbOperation(
        operation,
        table,
        () => handler(...args)
      );
      
      const duration = Date.now() - startTime;
      
      // Track slow queries
      if (duration > 500) {
        renderAnalyticsService.trackDbSlowQuery({
          operation,
          table,
          queryTime: duration,
          threshold: 500,
        });
      }
      
      return result;
    } catch (error) {
      const duration = Date.now() - startTime;
      
      // Track database errors
      renderAnalyticsService.track('db_error', {
        operation,
        table,
        error: (error as Error).message,
        queryTime: duration,
      });
      
      throw error;
    }
  };
}

// Business operation instrumentation
export function instrumentBusinessOperation<T extends any[]>(
  operation: string,
  context: Record<string, any>,
  handler: (...args: T) => Promise<any>
) {
  return async (...args: T): Promise<any> => {
    const startTime = Date.now();
    
    try {
      const result = await performanceMonitor.monitorBusinessOperation(
        operation,
        context,
        () => handler(...args)
      );
      
      const duration = Date.now() - startTime;
      
      // Track business operation analytics
      renderAnalyticsService.track('business_operation', {
        operation,
        duration,
        success: true,
        ...context,
      });
      
      return result;
    } catch (error) {
      const duration = Date.now() - startTime;
      
      // Track business operation errors
      renderAnalyticsService.track('business_operation_error', {
        operation,
        duration,
        success: false,
        error: (error as Error).message,
        ...context,
      });
      
      throw error;
    }
  };
}

// Prisma client instrumentation
export function instrumentPrismaClient(prisma: any) {
  const originalQuery = prisma.$queryRaw;
  const originalExecute = prisma.$executeRaw;
  
  // Instrument raw queries
  prisma.$queryRaw = async (...args: any[]) => {
    const startTime = Date.now();
    const query = args[0];
    
    try {
      const result = await originalQuery.apply(prisma, args);
      const duration = Date.now() - startTime;
      
      // Track query performance
      renderAnalyticsService.track('prisma_query', {
        query: query.toString().substring(0, 100),
        duration,
        success: true,
      });
      
      return result;
    } catch (error) {
      const duration = Date.now() - startTime;
      
      // Track query errors
      renderAnalyticsService.track('prisma_query_error', {
        query: query.toString().substring(0, 100),
        duration,
        success: false,
        error: (error as Error).message,
      });
      
      throw error;
    }
  };
  
  // Instrument raw executions
  prisma.$executeRaw = async (...args: any[]) => {
    const startTime = Date.now();
    const query = args[0];
    
    try {
      const result = await originalExecute.apply(prisma, args);
      const duration = Date.now() - startTime;
      
      // Track execution performance
      renderAnalyticsService.track('prisma_execute', {
        query: query.toString().substring(0, 100),
        duration,
        success: true,
      });
      
      return result;
    } catch (error) {
      const duration = Date.now() - startTime;
      
      // Track execution errors
      renderAnalyticsService.track('prisma_execute_error', {
        query: query.toString().substring(0, 100),
        duration,
        success: false,
        error: (error as Error).message,
      });
      
      throw error;
    }
  };
  
  return prisma;
}

// Middleware for automatic instrumentation
export function withAutoInstrumentation<T extends any[]>(
  handler: (...args: T) => Promise<NextResponse>
) {
  return async (...args: T): Promise<NextResponse> => {
    const request = args[0] as NextRequest;
    const route = request.nextUrl.pathname;
    const method = request.method;
    
    // Determine if this is a critical route that needs monitoring
    const isCriticalRoute = route.startsWith('/api/') && 
      !route.includes('/health') && 
      !route.includes('/metrics');
    
    if (isCriticalRoute) {
      return instrumentApiRoute(handler, {
        route,
        method,
        trackAnalytics: true,
        trackPerformance: true,
      })(...args);
    }
    
    return handler(...args);
  };
}

// Logtail integration for structured logging
export class LogtailService {
  private static instance: LogtailService;
  private logtail: any = null;
  private isEnabled: boolean = false;

  private constructor() {
    this.isEnabled = !!process.env.LOGTAIL_TOKEN;
    
    // Logtail is optional - only enable if token is provided
    // Will use console.log as fallback
  }

  public static getInstance(): LogtailService {
    if (!LogtailService.instance) {
      LogtailService.instance = new LogtailService();
    }
    return LogtailService.instance;
  }

  // Log API request
  public logApiRequest(data: {
    method: string;
    route: string;
    statusCode: number;
    responseTime: number;
    userId?: string;
    userRole?: string;
    requestId?: string;
    ip?: string;
    userAgent?: string;
  }) {
    if (!this.isEnabled || !this.logtail) return;

    this.logtail.info('API Request', {
      type: 'api_request',
      method: data.method,
      route: data.route,
      status_code: data.statusCode,
      response_time_ms: data.responseTime,
      user_id: data.userId,
      user_role: data.userRole,
      request_id: data.requestId,
      ip: data.ip,
      user_agent: data.userAgent,
      timestamp: new Date().toISOString(),
    });
  }

  // Log API error
  public logApiError(data: {
    method: string;
    route: string;
    error: string;
    stack?: string;
    userId?: string;
    userRole?: string;
    requestId?: string;
    ip?: string;
    userAgent?: string;
  }) {
    if (!this.isEnabled || !this.logtail) return;

    this.logtail.error('API Error', {
      type: 'api_error',
      method: data.method,
      route: data.route,
      error: data.error,
      stack: data.stack,
      user_id: data.userId,
      user_role: data.userRole,
      request_id: data.requestId,
      ip: data.ip,
      user_agent: data.userAgent,
      timestamp: new Date().toISOString(),
    });
  }

  // Log database operation
  public logDbOperation(data: {
    operation: string;
    table: string;
    duration: number;
    success: boolean;
    error?: string;
    query?: string;
    userId?: string;
  }) {
    if (!this.isEnabled || !this.logtail) return;

    this.logtail.info('Database Operation', {
      type: 'db_operation',
      operation: data.operation,
      table: data.table,
      duration_ms: data.duration,
      success: data.success,
      error: data.error,
      query: data.query?.substring(0, 200), // Truncate long queries
      user_id: data.userId,
      timestamp: new Date().toISOString(),
    });
  }

  // Log business operation
  public logBusinessOperation(data: {
    operation: string;
    duration: number;
    success: boolean;
    context: Record<string, any>;
    error?: string;
    userId?: string;
  }) {
    if (!this.isEnabled || !this.logtail) return;

    this.logtail.info('Business Operation', {
      type: 'business_operation',
      operation: data.operation,
      duration_ms: data.duration,
      success: data.success,
      error: data.error,
      context: data.context,
      user_id: data.userId,
      timestamp: new Date().toISOString(),
    });
  }

  // Log performance issue
  public logPerformanceIssue(data: {
    type: string;
    operation: string;
    duration: number;
    threshold: number;
    context: Record<string, any>;
    userId?: string;
  }) {
    if (!this.isEnabled || !this.logtail) return;

    this.logtail.warn('Performance Issue', {
      type: 'performance_issue',
      issue_type: data.type,
      operation: data.operation,
      duration_ms: data.duration,
      threshold_ms: data.threshold,
      exceeded_by_ms: data.duration - data.threshold,
      context: data.context,
      user_id: data.userId,
      timestamp: new Date().toISOString(),
    });
  }

  // Log SLA violation
  public logSLAViolation(data: {
    violation_type: string;
    current_value: number;
    threshold: number;
    severity: 'warning' | 'critical';
    context: Record<string, any>;
  }) {
    if (!this.isEnabled || !this.logtail) return;

    this.logtail.error('SLA Violation', {
      type: 'sla_violation',
      violation_type: data.violation_type,
      current_value: data.current_value,
      threshold: data.threshold,
      severity: data.severity,
      context: data.context,
      timestamp: new Date().toISOString(),
    });
  }

  // Log user action
  public logUserAction(data: {
    action: string;
    category: string;
    userId: string;
    userRole: string;
    context: Record<string, any>;
    ip?: string;
    userAgent?: string;
  }) {
    if (!this.isEnabled || !this.logtail) return;

    this.logtail.info('User Action', {
      type: 'user_action',
      action: data.action,
      category: data.category,
      user_id: data.userId,
      user_role: data.userRole,
      context: data.context,
      ip: data.ip,
      user_agent: data.userAgent,
      timestamp: new Date().toISOString(),
    });
  }

  // Log system event
  public logSystemEvent(data: {
    event: string;
    level: 'info' | 'warn' | 'error';
    message: string;
    context: Record<string, any>;
  }) {
    if (!this.isEnabled || !this.logtail) return;

    this.logtail[data.level](data.message, {
      type: 'system_event',
      event: data.event,
      level: data.level,
      message: data.message,
      context: data.context,
      timestamp: new Date().toISOString(),
    });
  }

  // Log security event
  public logSecurityEvent(data: {
    event: string;
    severity: 'low' | 'medium' | 'high' | 'critical';
    message: string;
    userId?: string;
    ip?: string;
    userAgent?: string;
    context: Record<string, any>;
  }) {
    if (!this.isEnabled || !this.logtail) return;

    this.logtail.error('Security Event', {
      type: 'security_event',
      event: data.event,
      severity: data.severity,
      message: data.message,
      user_id: data.userId,
      ip: data.ip,
      user_agent: data.userAgent,
      context: data.context,
      timestamp: new Date().toISOString(),
    });
  }

  // Flush logs
  public async flush() {
    if (!this.isEnabled || !this.logtail) return;

    try {
      await this.logtail.flush();
    } catch (error) {
      console.error('Failed to flush Logtail logs:', error);
    }
  }
}

