import { NextRequest, NextResponse } from 'next/server';
import { performanceMonitor } from './performance-monitor';
import { sentryService } from './sentry';

// Performance monitoring middleware
export function withPerformanceMonitoring<T extends any[]>(
  handler: (...args: T) => Promise<NextResponse>
) {
  return async (...args: T): Promise<NextResponse> => {
    const request = args[0] as NextRequest;
    const route = request.nextUrl.pathname;
    const method = request.method;
    
    // Add breadcrumb for request tracking
    sentryService.addBreadcrumb(
      `${method} ${route}`,
      'http',
      'info',
      {
        method,
        route,
        userAgent: request.headers.get('user-agent'),
        ip: request.headers.get('x-forwarded-for') || request.ip,
      }
    );
    
    return performanceMonitor.monitorApiRoute(
      route,
      method,
      () => handler(...args)
    );
  };
}

// Database operation monitoring wrapper
export function withDbMonitoring<T extends any[]>(
  operation: string,
  table: string,
  handler: (...args: T) => Promise<any>
) {
  return async (...args: T): Promise<any> => {
    return performanceMonitor.monitorDbOperation(
      operation,
      table,
      () => handler(...args)
    );
  };
}

// Business operation monitoring wrapper
export function withBusinessMonitoring<T extends any[]>(
  operation: string,
  context: Record<string, any>,
  handler: (...args: T) => Promise<any>
) {
  return async (...args: T): Promise<any> => {
    return performanceMonitor.monitorBusinessOperation(
      operation,
      context,
      () => handler(...args)
    );
  };
}

// Error handling middleware
export function withErrorHandling<T extends any[]>(
  handler: (...args: T) => Promise<NextResponse>
) {
  return async (...args: T): Promise<NextResponse> => {
    try {
      return await handler(...args);
    } catch (error) {
      const request = args[0] as NextRequest;
      const route = request.nextUrl.pathname;
      const method = request.method;
      
      // Capture error in Sentry
      sentryService.captureApiError(error as Error, {
        route,
        method,
        requestId: request.headers.get('x-request-id') || undefined,
        body: request.body ? await request.clone().json().catch(() => null) : undefined,
      });
      
      // Return error response
      return NextResponse.json(
        {
          success: false,
          error: 'Internal server error',
          code: 'INTERNAL_ERROR',
          message: 'An unexpected error occurred',
          timestamp: new Date().toISOString(),
          requestId: request.headers.get('x-request-id') || undefined,
        },
        { status: 500 }
      );
    }
  };
}

// Combined middleware for API routes
export function withApiMonitoring<T extends any[]>(
  handler: (...args: T) => Promise<NextResponse>
) {
  return withErrorHandling(withPerformanceMonitoring(handler));
}

// Health check endpoint
export async function healthCheck(): Promise<NextResponse> {
  const startTime = Date.now();
  
  try {
    // Basic health checks
    const checks = {
      status: 'healthy',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memory: process.memoryUsage(),
      version: process.env.npm_package_version || '1.0.0',
      environment: process.env.NODE_ENV || 'development',
    };
    
    const duration = Date.now() - startTime;
    
    // Record health check metrics
    (performanceMonitor as any).recordMetric('health_check_duration', duration);
    
    return NextResponse.json(checks);
  } catch (error) {
    const duration = Date.now() - startTime;
    
    // Record error metrics
    (performanceMonitor as any).recordMetric('health_check_duration', duration, { error: 'true' });
    
    // Capture error
    sentryService.captureMessage('Health check failed', 'error', { error: (error as Error).message });
    
    return NextResponse.json(
      {
        status: 'unhealthy',
        timestamp: new Date().toISOString(),
        error: (error as Error).message,
      },
      { status: 503 }
    );
  }
}

// Metrics endpoint
export async function getMetrics(): Promise<NextResponse> {
  try {
    const stats = performanceMonitor.getStats();
    
    return NextResponse.json({
      success: true,
      data: {
        metrics: stats,
        timestamp: new Date().toISOString(),
      },
    });
  } catch (error) {
    sentryService.captureMessage('Failed to get metrics', 'error', { error: (error as Error).message });
    
    return NextResponse.json(
      {
        success: false,
        error: 'Failed to retrieve metrics',
        message: (error as Error).message,
      },
      { status: 500 }
    );
  }
}

import { NodeSDK } from '@opentelemetry/sdk-node';
import { getNodeAutoInstrumentations } from '@opentelemetry/auto-instrumentations-node';
import { OTLPTraceExporter } from '@opentelemetry/exporter-trace-otlp-http';
import { OTLPMetricExporter } from '@opentelemetry/exporter-metrics-otlp-http';
import { PeriodicExportingMetricReader } from '@opentelemetry/sdk-metrics';
import { resourceFromAttributes } from '@opentelemetry/resources';
import { SemanticResourceAttributes } from '@opentelemetry/semantic-conventions';
import winston from 'winston';
import { OpenTelemetryTransportV3 as OTELWinstonTransport } from '@opentelemetry/winston-transport';

// Initialize OpenTelemetry SDK
export function initializeOpenTelemetry() {
  const sdk = new NodeSDK({
    resource: resourceFromAttributes({
      [SemanticResourceAttributes.SERVICE_NAME]: 'speedy-van-web',
      [SemanticResourceAttributes.SERVICE_VERSION]: process.env.npm_package_version || '1.0.0',
      [SemanticResourceAttributes.DEPLOYMENT_ENVIRONMENT]: process.env.NODE_ENV || 'development',
    }),
    traceExporter: new OTLPTraceExporter({
      url: process.env.OTEL_EXPORTER_OTLP_TRACES_ENDPOINT || 'http://localhost:4318/v1/traces',
    }),
    metricReader: new PeriodicExportingMetricReader({
      exporter: new OTLPMetricExporter({
        url: process.env.OTEL_EXPORTER_OTLP_METRICS_ENDPOINT || 'http://localhost:4318/v1/metrics',
      }),
      exportIntervalMillis: 10000, // Export every 10 seconds
    }),
    instrumentations: [
      getNodeAutoInstrumentations({
        // Disable some instrumentations that might cause issues
        '@opentelemetry/instrumentation-fs': {
          enabled: false, // Disable file system instrumentation
        },
        '@opentelemetry/instrumentation-redis': {
          enabled: false, // Disable if not using Redis
        },
        '@opentelemetry/instrumentation-pg': {
          enabled: true, // Enable PostgreSQL instrumentation
        },
        '@opentelemetry/instrumentation-http': {
          enabled: true, // Enable HTTP instrumentation
        },
        '@opentelemetry/instrumentation-express': {
          enabled: true, // Enable Express instrumentation
        },
      }),
    ],
  });

  // Initialize the SDK and register with the OpenTelemetry API
  sdk.start();

  // Configure Winston → OpenTelemetry bridge (resolves transport module warning)
  try {
    const otelTransport = new OTELWinstonTransport({
      level: process.env.LOG_LEVEL || 'info',
    });
    const logger = winston.createLogger({
      level: process.env.LOG_LEVEL || 'info',
      transports: [new winston.transports.Console(), otelTransport],
    });
    // Example: attach to global for use elsewhere if needed
    (global as any).__SV_LOGGER__ = logger;
  } catch (err) {
    console.warn('OTel/Winston bridge initialization skipped:', err);
  }

  // Gracefully shut down the SDK on process exit
  process.on('SIGTERM', () => {
    sdk.shutdown()
      .then(() => console.log('OpenTelemetry terminated'))
      .catch((error) => console.log('Error terminating OpenTelemetry', error))
      .finally(() => process.exit(0));
  });

  return sdk;
}

// Custom metrics and tracing utilities
export class TelemetryService {
  private static instance: TelemetryService;
  private sdk: NodeSDK | null = null;

  private constructor() {}

  public static getInstance(): TelemetryService {
    if (!TelemetryService.instance) {
      TelemetryService.instance = new TelemetryService();
    }
    return TelemetryService.instance;
  }

  public initialize(sdk: NodeSDK) {
    this.sdk = sdk;
  }

  // Custom span creation for API routes
  public createApiSpan(route: string, method: string) {
    const { trace, context } = require('@opentelemetry/api');
    const tracer = trace.getTracer('speedy-van-api');
    
    return tracer.startSpan(`${method} ${route}`, {
      attributes: {
        'http.method': method,
        'http.route': route,
        'service.name': 'speedy-van-web',
      },
    });
  }

  // Custom span for database operations
  public createDbSpan(operation: string, table: string) {
    const { trace } = require('@opentelemetry/api');
    const tracer = trace.getTracer('speedy-van-db');
    
    return tracer.startSpan(`db.${operation}`, {
      attributes: {
        'db.operation': operation,
        'db.table': table,
        'service.name': 'speedy-van-web',
      },
    });
  }

  // Custom span for business logic
  public createBusinessSpan(operation: string, context: Record<string, any> = {}) {
    const { trace } = require('@opentelemetry/api');
    const tracer = trace.getTracer('speedy-van-business');
    
    return tracer.startSpan(`business.${operation}`, {
      attributes: {
        'business.operation': operation,
        'service.name': 'speedy-van-web',
        ...context,
      },
    });
  }

  // Record custom metrics
  public recordMetric(name: string, value: number, labels: Record<string, string> = {}) {
    const { metrics } = require('@opentelemetry/api');
    const meter = metrics.getMeter('speedy-van-metrics');
    
    const counter = meter.createCounter(name, {
      description: `Custom metric: ${name}`,
    });
    
    counter.add(value, labels);
  }

  // Record API response time
  public recordApiResponseTime(route: string, method: string, duration: number, statusCode: number) {
    this.recordMetric('api_response_time_ms', duration, {
      route,
      method,
      status_code: statusCode.toString(),
    });
  }

  // Record database query time
  public recordDbQueryTime(operation: string, table: string, duration: number) {
    this.recordMetric('db_query_time_ms', duration, {
      operation,
      table,
    });
  }

  // Record business operation time
  public recordBusinessOperationTime(operation: string, duration: number, success: boolean) {
    this.recordMetric('business_operation_time_ms', duration, {
      operation,
      success: success.toString(),
    });
  }

  // Record error
  public recordError(error: Error, context: Record<string, any> = {}) {
    const { trace } = require('@opentelemetry/api');
    const tracer = trace.getTracer('speedy-van-errors');
    
    const span = tracer.startSpan('error.occurred');
    span.setStatus({ code: 2, message: error.message }); // ERROR status
    span.setAttributes({
      'error.name': error.name,
      'error.message': error.message,
      'error.stack': error.stack || '',
      ...context,
    });
    span.end();
  }
}

