            service: 'speedy-van-web',
            environment: process.env.NODE_ENV,
          },
        })),
      });
    } catch (error) {
      console.error('Failed to batch track events:', error);
    }
  }

  // Get analytics configuration
  public getConfig() {
    return {
      enabled: this.isEnabled,
      apiKey: this.apiKey ? '***' : null,
      baseUrl: this.baseUrl,
    };
  }
}

