// Export utility functions
export const ukAddressUtils = {
  // Validate UK postcode format
  isValidUKPostcode: (postcode: string): boolean => {
    const ukPostcodeRegex = /^[A-Z]{1,2}[0-9R][0-9A-Z]? [0-9][ABD-HJLNP-UW-Z]{2}$/i;
    return ukPostcodeRegex.test(postcode.trim());
  },

  // Format UK postcode
  formatUKPostcode: (postcode: string): string => {
    return postcode.trim().toUpperCase().replace(/\s+/g, ' ');
  },

  // Extract postcode from address string
  extractPostcode: (address: string): string => {
    const match = address.match(/\b[A-Z]{1,2}[0-9][A-Z0-9]? ?[0-9][ABD-HJLNP-UW-Z]{2}\b/i);
    return match ? match[0].toUpperCase().replace(/\s+/g, ' ') : '';
  },

  // Check if address is in supported area
  isInSupportedArea: (postcode: string): boolean => {
    const supportedAreas = ['G21', 'SW1A', 'M1', 'B1', 'EH1'];
    return supportedAreas.some(area => postcode.startsWith(area));
  }
};

/**
 * Unified Error Handler V2 - Works with existing codebase
 * Provides consistent error handling between frontend and backend
 */

import { NextRequest, NextResponse } from 'next/server';
import { ZodError } from 'zod';
import {
  AppError,
  AuthenticationError,
  AuthorizationError,
  ValidationAppError,
  NotFoundError,
  ConflictError,
  DatabaseError,
  ExternalServiceError,
  RateLimitError,
  FileError,
  ErrorCode,
  formatZodErrors,
  getStatusCodeForError,
  isOperationalError,
  type ValidationError
} from './error-types';
import { 
  createErrorResponse, 
  createValidationErrorResponse,
  generateRequestId 
} from './api-response';

// ================================
// ERROR CONVERSION
// ================================

/**
 * Convert unknown error to AppError
 */
export function convertToAppError(error: unknown, context?: string): AppError {
  // Already an AppError
  if (error instanceof AppError) {
    return error;
  }

  // Zod validation error
  if (error instanceof ZodError) {
    const validationErrors = formatZodErrors(error);
    return new ValidationAppError('Validation failed', validationErrors, context);
  }

  // Database/Prisma errors
  if (error instanceof Error) {
    const message = error.message.toLowerCase();
    
    // Unique constraint violation
    if (message.includes('unique constraint') || message.includes('duplicate key')) {
      return new ConflictError('Resource already exists', context);
    }
    
    // Foreign key constraint
    if (message.includes('foreign key constraint')) {
      return new ValidationAppError('Referenced resource not found', [], context);
    }
    
    // Connection errors
    if (message.includes('connection') || message.includes('timeout')) {
      return new DatabaseError('Database connection error', context);
    }
    
    // Authentication errors
    if (message.includes('unauthorized') || message.includes('authentication')) {
      return new AuthenticationError(error.message);
    }
    
    // Authorization errors
    if (message.includes('forbidden') || message.includes('permission')) {
      return new AuthorizationError(error.message);
    }
    
    // Not found errors
    if (message.includes('not found')) {
      return new NotFoundError('Resource', context);
    }
  }

  // Generic error
  return new AppError(
    error instanceof Error ? error.message : 'An unexpected error occurred',
    ErrorCode.INTERNAL_ERROR,
    500,
    context
  );
}

// ================================
// BACKEND ERROR HANDLING
// ================================

/**
 * Handle API errors and return appropriate responses
 */
export function handleApiError(
  error: unknown, 
  request?: NextRequest, 
  context?: string
): NextResponse {
  const requestId = generateRequestId();
  const path = request ? new URL(request.url).pathname : undefined;
  const appError = convertToAppError(error, context);
  
  // Log error for debugging
  console.error(`[${requestId}] API Error:`, {
    error: appError.name,
    message: appError.message,
    code: appError.code,
    statusCode: appError.statusCode,
    path,
    context,
    stack: process.env.NODE_ENV === 'development' ? appError.stack : undefined,
  });

  // Handle validation errors specially
  if (appError instanceof ValidationAppError) {
    const validationErrors = appError.validationErrors.map(err => ({
      field: err.field,
      message: err.message,
    }));
    return NextResponse.json(createValidationErrorResponse(
      'validation',
      appError.message,
      requestId
    ));
  }

  // Use status code from error
  const statusCode = getStatusCodeForError(appError);
  
  return NextResponse.json(createErrorResponse(
    appError.message,
    appError.code,
    requestId,
    appError.details,
    statusCode
  ));
}

/**
 * API wrapper with unified error handling
 */
export function withUnifiedErrorHandler<T extends any[], R>(
  handler: (req: NextRequest, ...args: T) => Promise<NextResponse<R>>,
  context?: string
) {
  return async (req: NextRequest, ...args: T): Promise<NextResponse> => {
    try {
      return await handler(req, ...args);
    } catch (error) {
      return handleApiError(error, req, context);
    }
  };
}

// ================================
// VALIDATION HELPERS
// ================================

/**
 * Validate request data with Zod schema
 */
export function validateRequestData<T>(
  data: unknown,
  schema: any,
  context?: string
): T {
  try {
    return schema.parse(data);
  } catch (error) {
    if (error instanceof ZodError) {
      throw new ValidationAppError('Invalid request data', formatZodErrors(error), context);
    }
    throw convertToAppError(error, context);
  }
}

/**
 * Require authentication
 */
export function requireAuthentication(session: any, context?: string) {
  if (!session || !session.user) {
    throw new AuthenticationError('Authentication required', context);
  }
  return session;
}

/**
 * Require specific role
 */
export function requireRole(
  session: any,
  requiredRoles: string | string[],
  context?: string
) {
  const user = requireAuthentication(session, context).user;
  const userRole = user.role;
  const roles = Array.isArray(requiredRoles) ? requiredRoles : [requiredRoles];
  
  if (!roles.includes(userRole)) {
    throw new AuthorizationError(
      `Access denied. Required roles: ${roles.join(', ')}`,
      context
    );
  }
  
  return session;
}

// ================================
// EXTERNAL SERVICE ERROR HANDLING
// ================================

/**
 * Handle external service errors
 */
export function handleExternalServiceError(
  service: string,
  error: unknown,
  context?: string
): never {
  if (error instanceof AppError) {
    throw error;
  }
  
  const message = error instanceof Error ? error.message : String(error);
  throw new ExternalServiceError(service, message, context);
}

/**
 * Handle database errors
 */
export function handleDatabaseError(error: unknown, context?: string): never {
  if (error instanceof AppError) {
    throw error;
  }
  
  const message = error instanceof Error ? error.message : String(error);
  throw new DatabaseError('Database operation failed', `${context}: ${message}`);
}

// ================================
// UTILITY FUNCTIONS
// ================================

/**
 * Should we log this error?
 */
export function shouldLogError(error: unknown): boolean {
  // Log all non-operational errors and 5xx errors
  if (!isOperationalError(error)) return true;
  if (error instanceof AppError && error.statusCode >= 500) return true;
  return false;
}

/**
 * Create error for logging/monitoring systems
 */
export function createErrorForLogging(error: AppError, request?: NextRequest) {
  return {
    id: generateRequestId(),
    timestamp: error.timestamp,
    level: error.statusCode >= 500 ? 'error' : 'warn',
    category: error.code,
    source: request ? new URL(request.url).pathname : 'unknown',
    message: error.message,
    stackTrace: error.stack,
    context: error.context,
    details: error.details,
    metadata: {
      statusCode: error.statusCode,
      isOperational: error.isOperational,
      userAgent: request?.headers.get('user-agent'),
      ip: request?.headers.get('x-forwarded-for') || request?.headers.get('x-real-ip')
    }
  };
}

/**
 * Assignment Helper Utilities
 * 
 * These helpers handle the fact that Booking.Assignment is now an array (one-to-many)
 * instead of a single object (one-to-one), allowing us to track assignment history.
 */

import type { Assignment } from '@prisma/client';

/**
 * Get the active assignment from a booking's assignment array.
 * Returns the most recent non-cancelled/non-declined assignment.
 * 
 * @param assignments - Array of assignments from a booking
 * @returns The active assignment or null if none found
 */
export function getActiveAssignment<T extends Pick<Assignment, 'status' | 'createdAt'>>(
  assignments: T[] | T | null | undefined
): T | null {
  // Handle if it's already a single assignment (shouldn't happen, but defensive)
  if (!Array.isArray(assignments)) {
    if (!assignments) return null;
    if (assignments.status === 'cancelled' || assignments.status === 'declined') {
      return null;
    }
    return assignments;
  }

  // Filter out cancelled/declined assignments and get the most recent
  const activeAssignments = assignments
    .filter(a => a.status !== 'cancelled' && a.status !== 'declined')
    .sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());

  return activeAssignments[0] || null;
}

/**
 * Get the most recent assignment regardless of status (for history/audit purposes).
 * 
 * @param assignments - Array of assignments from a booking
 * @returns The most recent assignment or null if none found
 */
export function getLatestAssignment<T extends Pick<Assignment, 'createdAt'>>(
  assignments: T[] | T | null | undefined
): T | null {
  if (!Array.isArray(assignments)) {
    return assignments || null;
  }

  if (assignments.length === 0) return null;

  return assignments.sort((a, b) => 
    new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
  )[0];
}

/**
 * Check if a booking has an active assignment.
 * 
 * @param assignments - Array of assignments from a booking
 * @returns True if there's an active assignment
 */
export function hasActiveAssignment<T extends Pick<Assignment, 'status'>>(
  assignments: T[] | T | null | undefined
): boolean {
  if (!Array.isArray(assignments)) {
    if (!assignments) return false;
    return assignments.status !== 'cancelled' && assignments.status !== 'declined';
  }

  return assignments.some(a => a.status !== 'cancelled' && a.status !== 'declined');
}

/**
 * Prisma include configuration for getting active assignments only.
 * Use this in your Prisma queries to get only non-cancelled assignments.
 */
export const ACTIVE_ASSIGNMENT_INCLUDE = {
  where: {
    status: { notIn: ['cancelled', 'declined'] as const }
  },
  orderBy: { createdAt: 'desc' as const },
  take: 1
} as const;

/**
 * Safely upsert an assignment for a booking.
 * Since bookingId is not unique (one booking can have multiple assignments),
 * this helper finds an active assignment and updates it, or creates a new one.
 * 
 * @param prisma - Prisma client or transaction client
 * @param bookingId - The booking ID
 * @param data - Data to update or create with
 * @returns The upserted assignment
 */
export async function upsertAssignment(
  prisma: any,
  bookingId: string,
  data: {
    driverId: string;
    status: 'invited' | 'claimed' | 'accepted' | 'declined' | 'completed' | 'cancelled';
    expiresAt?: Date | null;
    claimedAt?: Date | null;
    score?: number | null;
    round?: number;
  }
) {
  // ✅ CRITICAL FIX: Find ANY existing assignment (not just invited/claimed)
  // This prevents duplicate assignments and P2002 errors
  const existingAssignment = await prisma.assignment.findFirst({
    where: {
      bookingId,
      // Don't filter by status - find ANY assignment
    },
    orderBy: { createdAt: 'desc' }
  });

  if (existingAssignment) {
    // ✅ Update existing assignment with new driver
    console.log(`✅ Updating existing assignment ${existingAssignment.id} for booking ${bookingId}`);
    return await prisma.assignment.update({
      where: { id: existingAssignment.id },
      data: {
        ...data,
        updatedAt: new Date()
      }
    });
  } else {
    // ✅ Create new assignment only if none exists
    console.log(`✅ Creating new assignment for booking ${bookingId}`);
    return await prisma.assignment.create({
      data: {
        id: `assignment_${Date.now()}_${bookingId}_${data.driverId}`,
        bookingId,
        ...data,
        createdAt: new Date(),
        updatedAt: new Date(),
      }
    });
  }
}

/**
 * Demo Guard - Prevent Demo Data in Production Accounts
 * 
 * This utility ensures demo/test data is ONLY allowed for the Apple Test Account.
 * All other accounts must use REAL data only.
 * 
 * Apple Test Account:
 * - Email: zadfad41@gmail.com
 * - Driver ID: xRLLVY7d0zwTCC9A
 */

// Apple Test Account - ONLY account allowed for demo data
const APPLE_TEST_ACCOUNT = {
  email: 'zadfad41@gmail.com',
  driverId: 'xRLLVY7d0zwTCC9A',
  userId: 'XYgJzjVjfn1hOH4z', // Can be updated if needed
};

/**
 * Check if a user is the Apple Test Account
 */
export function isAppleTestAccount(userEmail?: string | null, driverId?: string | null): boolean {
  if (!userEmail && !driverId) {
    return false;
  }

  return (
    userEmail === APPLE_TEST_ACCOUNT.email ||
    driverId === APPLE_TEST_ACCOUNT.driverId
  );
}

/**
 * Validate booking reference - prevent DEMO/TEST prefixes in production
 */
export function validateBookingReference(
  reference: string,
  userEmail?: string | null,
  driverId?: string | null
): { valid: boolean; error?: string } {
  // Check if reference has demo/test prefix
  const isDemoReference = 
    reference.startsWith('DEMO-') ||
    reference.startsWith('TEST-') ||
    reference.startsWith('MOCK-');

  if (!isDemoReference) {
    // Real reference - always valid
    return { valid: true };
  }

  // Demo reference - only valid for Apple Test Account
  if (isAppleTestAccount(userEmail, driverId)) {
    return { valid: true };
  }

  // Demo reference for production account - INVALID
  return {
    valid: false,
    error: 'Demo/Test booking references are not allowed in production accounts. Only real customer bookings are permitted.',
  };
}

/**
 * Validate customer data - prevent demo/test customer names
 */
export function validateCustomerData(
  customerName: string,
  customerEmail: string,
  driverEmail?: string | null,
  driverId?: string | null
): { valid: boolean; error?: string } {
  // Check for demo/test indicators
  const nameContainsDemo = /demo|test|mock/i.test(customerName);
  const emailContainsDemo = /demo|test|mock/i.test(customerEmail);

  if (!nameContainsDemo && !emailContainsDemo) {
    // Real customer data - always valid
    return { valid: true };
  }

  // Demo data detected - only valid for Apple Test Account
  if (isAppleTestAccount(driverEmail, driverId)) {
    return { valid: true };
  }

  // Demo customer for production account - INVALID
  return {
    valid: false,
    error: 'Demo/Test customer data is not allowed in production accounts. Only real customers are permitted.',
  };
}

/**
 * Get demo mode status for a user
 */
export function getDemoMode(userEmail?: string | null, driverId?: string | null): {
  isDemoAccount: boolean;
  canUseDemoData: boolean;
  accountType: 'production' | 'test';
} {
  const isDemoAccount = isAppleTestAccount(userEmail, driverId);

  return {
    isDemoAccount,
    canUseDemoData: isDemoAccount,
    accountType: isDemoAccount ? 'test' : 'production',
  };
}

/**
 * Filter out demo data for production accounts
 */
export function filterDemoData<T extends { reference?: string; customerName?: string }>(
  items: T[],
  userEmail?: string | null,
  driverId?: string | null
): T[] {
  // Apple Test Account can see all data (including demo)
  if (isAppleTestAccount(userEmail, driverId)) {
    return items;
  }

  // Production accounts - filter out demo data
  return items.filter(item => {
    // Check reference
    if (item.reference) {
      const isDemoRef = /^(DEMO-|TEST-|MOCK-)/i.test(item.reference);
      if (isDemoRef) return false;
    }

    // Check customer name
    if (item.customerName) {
      const isDemoCustomer = /demo|test|mock/i.test(item.customerName);
      if (isDemoCustomer) return false;
    }

    return true;
  });
}

export default {
  isAppleTestAccount,
  validateBookingReference,
  validateCustomerData,
  getDemoMode,
  filterDemoData,
  APPLE_TEST_ACCOUNT,
};

