import { BookingItem, PropertyInfo } from '@/types';

interface SmartSuggestion {
  type: 'info' | 'warning' | 'alert';
  category: 'workers' | 'equipment' | 'access' | 'handling' | 'tools' | 'zones' | 'timing';
  title: string;
  description: string;
}

export function generateSmartSuggestions(
  items: BookingItem[],
  pickupProperty: any, // Using any to handle database values
  dropoffProperty: any, // Using any to handle database values
  scheduledAt: Date,
  pickupPostcode?: string,
  dropoffPostcode?: string
): SmartSuggestion[] {
  const suggestions: SmartSuggestion[] = [];

  // Calculate totals
  const totalVolume = items.reduce((acc, item) => acc + (item.volume || 0), 0);
  const totalWeight = items.reduce((acc, item) => acc + (item.weight || 0), 0);

  // Analyze items
  const itemCategories = {
    fragile: items.some(item => 
      /glass|fragile|ceramic|mirror|electronics|tv|television/i.test(item.name)
    ),
    furniture: items.some(item =>
      /sofa|table|bed|wardrobe|cabinet|drawer|chair|desk/i.test(item.name)
    ),
    whiteGoods: items.some(item =>
      /fridge|freezer|washing|dishwasher|oven|cooker/i.test(item.name)
    ),
    heavyItems: items.some(item => (item.weight || 0) > 50),
    piano: items.some(item => /piano/i.test(item.name)),
    artworks: items.some(item => /painting|artwork|sculpture|antique/i.test(item.name))
  };

  // Worker recommendations
  if (totalVolume > 15 || itemCategories.piano) {
    suggestions.push({
      type: 'warning',
      category: 'workers',
      title: 'Large Team Required',
      description: `This job requires at least 3 workers due to ${
        itemCategories.piano ? 'presence of a piano' : 'the exceptionally large volume of items'
      }.`
    });
  } else if (totalVolume > 10 || itemCategories.whiteGoods || 
    (itemCategories.furniture && totalWeight > 150)) {
    suggestions.push({
      type: 'warning',
      category: 'workers',
      title: 'Additional Worker Needed',
      description: `Additional worker recommended due to ${
        itemCategories.whiteGoods ? 'presence of white goods' :
        itemCategories.furniture ? 'heavy furniture items' :
        'total volume exceeding 10m³'
      }.`
    });
  }

  // Equipment suggestions
  if (itemCategories.whiteGoods || itemCategories.heavyItems) {
    suggestions.push({
      type: 'warning',
      category: 'equipment',
      title: 'Heavy Duty Equipment Required',
      description: 'Bring appliance dolly, heavy-duty straps, and furniture sliders for safe handling.'
    });
  }

  if (itemCategories.piano) {
    suggestions.push({
      type: 'alert',
      category: 'equipment',
      title: 'Specialized Piano Equipment Required',
      description: 'Piano board, specialized straps, and piano dolly are essential. Ensure proper insurance coverage.'
    });
  }

  // Access considerations
  const pickupFloors = pickupProperty?.floors || 0;
  const dropoffFloors = dropoffProperty?.floors || 0;
  const pickupHasLift = pickupProperty?.accessType === 'WITH_LIFT';
  const dropoffHasLift = dropoffProperty?.accessType === 'WITH_LIFT';

  if ((pickupFloors > 0 && !pickupHasLift) || (dropoffFloors > 0 && !dropoffHasLift)) {
    const locations = [];
    if (pickupFloors > 0 && !pickupHasLift) locations.push(`pickup (${pickupFloors} floors)`);
    if (dropoffFloors > 0 && !dropoffHasLift) locations.push(`dropoff (${dropoffFloors} floors)`);
    
    suggestions.push({
      type: 'warning',
      category: 'access',
      title: 'Stair Carrying Required',
      description: `No lift access at ${locations.join(' and ')}. ${
        itemCategories.heavyItems || itemCategories.whiteGoods ? 
        'Additional workers and stair climbing equipment required.' :
        'Consider additional worker for safety.'
      }`
    });
  }

  // Special handling instructions
  if (itemCategories.fragile) {
    suggestions.push({
      type: 'info',
      category: 'handling',
      title: 'Fragile Items Present',
      description: 'Ensure sufficient bubble wrap, protective blankets, and corner protectors. Document item condition before moving.'
    });
  }

  if (itemCategories.artworks) {
    suggestions.push({
      type: 'info',
      category: 'handling',
      title: 'Artwork/Antiques Present',
      description: 'Use art boxes or crates for paintings. Take detailed photos before moving. Handle with extreme care.'
    });
  }

  // Tools needed
  if (itemCategories.furniture) {
    suggestions.push({
      type: 'info',
      category: 'tools',
      title: 'Furniture Tools Required',
      description: 'Bring basic tool kit (screwdrivers, Allen keys, wrench set) for furniture disassembly. Check with customer about disassembly preferences.'
    });
  }

  // Timing considerations
  const scheduledHour = scheduledAt.getHours();
  const isRushHour = (scheduledHour >= 7 && scheduledHour <= 9) || 
                     (scheduledHour >= 16 && scheduledHour <= 18);

  if (isRushHour) {
    suggestions.push({
      type: 'info',
      category: 'timing',
      title: 'Peak Traffic Hours',
      description: `Job scheduled during ${
        scheduledHour < 12 ? 'morning' : 'evening'
      } rush hour. Add 30-45 minutes to estimated travel time.`
    });
  }

  // Weather-based suggestions (could be expanded with weather API integration)
  const isWinterMonth = [11, 0, 1].includes(scheduledAt.getMonth());
  if (isWinterMonth) {
    suggestions.push({
      type: 'info',
      category: 'timing',
      title: 'Winter Weather Advisory',
      description: 'Check weather forecast. Bring covers to protect items from rain/snow. Allow extra time for adverse conditions.'
    });
  }

  // Zone-based suggestions (ULEZ/LEZ)
  if (pickupPostcode || dropoffPostcode) {
    const ulezPrefixes = ['EC1', 'EC2', 'EC3', 'EC4', 'WC1', 'WC2', 'SE1', 'E1'];
    const lezPrefixes = ['N1', 'E2', 'E8', 'SE11'];
    const congestionChargePrefixes = ['EC1', 'EC2', 'EC3', 'EC4', 'WC1', 'WC2'];
    
    const pickupInULEZ = pickupPostcode && ulezPrefixes.some(prefix => 
      pickupPostcode.toUpperCase().startsWith(prefix)
    );
    const dropoffInULEZ = dropoffPostcode && ulezPrefixes.some(prefix => 
      dropoffPostcode.toUpperCase().startsWith(prefix)
    );
    
    const pickupInLEZ = pickupPostcode && lezPrefixes.some(prefix => 
      pickupPostcode.toUpperCase().startsWith(prefix)
    );
    const dropoffInLEZ = dropoffPostcode && lezPrefixes.some(prefix => 
      dropoffPostcode.toUpperCase().startsWith(prefix)
    );
    
    const pickupInCongestion = pickupPostcode && congestionChargePrefixes.some(prefix => 
      pickupPostcode.toUpperCase().startsWith(prefix)
    );
    const dropoffInCongestion = dropoffPostcode && congestionChargePrefixes.some(prefix => 
      dropoffPostcode.toUpperCase().startsWith(prefix)
    );

    if (pickupInULEZ || dropoffInULEZ) {
      suggestions.push({
        type: 'alert',
        category: 'zones',
        title: 'ULEZ Zone Alert',
        description: `Route passes through ULEZ zone. Ensure vehicle meets ULEZ standards or factor in £12.50 daily charge. Check TfL ULEZ checker before departure.`
      });
    }

    if (pickupInLEZ || dropoffInLEZ) {
      suggestions.push({
        type: 'warning',
        category: 'zones',
        title: 'LEZ Zone Notice',
        description: `Route passes through Low Emission Zone. Ensure vehicle meets LEZ standards or factor in daily charges.`
      });
    }

    if (pickupInCongestion || dropoffInCongestion) {
      suggestions.push({
        type: 'warning',
        category: 'zones',
        title: 'Congestion Charge Zone',
        description: `Route passes through Congestion Charge Zone. Factor in £15 daily charge (Mon-Fri 7am-6pm).`
      });
    }
  }

  return suggestions;
}

/**
 * Address Structure Validation for Enterprise Engine
 * MANDATORY: All addresses must be full structured addresses from autocomplete
 * NO postcode-only shortcuts allowed
 */

import { z } from 'zod';

/**
 * Full structured address schema - ENTERPRISE REQUIREMENT
 * Rejects any address without complete structure
 */
export const FullStructuredAddressSchema = z.object({
  street: z.string().min(1, 'Street name is required'),
  number: z.string().min(1, 'House/building number is required'),
  city: z.string().min(1, 'City is required'),
  postcode: z.string().regex(/^[A-Z]{1,2}\d[A-Z\d]?\s?\d[A-Z]{2}$/i, 'Valid UK postcode is required'),
  county: z.string().optional(),
  coordinates: z.object({
    lat: z.number().min(-90).max(90, 'Invalid latitude'),
    lng: z.number().min(-180).max(180, 'Invalid longitude')
  }, { required_error: 'Coordinates are required for Enterprise Engine' })
});

/**
 * Legacy address schema (for compatibility)
 */
export const LegacyAddressSchema = z.object({
  full: z.string().optional(),
  line1: z.string().optional(),
  line2: z.string().optional(),
  city: z.string().optional(),
  postcode: z.string().optional(),
  coordinates: z.object({
    lat: z.number(),
    lng: z.number()
  }).optional(),
  formatted: z.object({
    street: z.string().optional(),
    houseNumber: z.string().optional(),
    flatNumber: z.string().optional()
  }).optional(),
  houseNumber: z.string().optional(),
});

export type FullStructuredAddress = z.infer<typeof FullStructuredAddressSchema>;
export type LegacyAddress = z.infer<typeof LegacyAddressSchema>;

/**
 * Convert legacy address format to Enterprise Engine format
 * Extracts required fields or throws validation error
 */
export function convertToFullStructuredAddress(
  legacyAddress: LegacyAddress,
  context: string = 'address'
): FullStructuredAddress {
  try {
    // Extract street and number from various possible fields
    const street = legacyAddress.formatted?.street || 
                  (legacyAddress.line1?.split(' ').slice(1).join(' ')) || 
                  '';
    
    const number = legacyAddress.formatted?.houseNumber || 
                  legacyAddress.houseNumber || 
                  (legacyAddress.line1?.split(' ')[0]) || 
                  '';

    const fullAddress = {
      street,
      number,
      city: legacyAddress.city || '',
      postcode: legacyAddress.postcode || '',
      coordinates: legacyAddress.coordinates || { lat: 0, lng: 0 }
    };

    // Validate using strict schema
    return FullStructuredAddressSchema.parse(fullAddress);
    
  } catch (error) {
    throw new Error(
      `${context}: Invalid address structure for Enterprise Engine. ` +
      `Required: street, number, city, postcode, coordinates. ` +
      `Error: ${error instanceof Error ? error.message : 'Unknown validation error'}`
    );
  }
}

/**
 * Validate array of addresses (for multi-drop)
 */
export function validateAddressArray(
  addresses: LegacyAddress[], 
  context: string = 'addresses'
): FullStructuredAddress[] {
  return addresses.map((address, index) => 
    convertToFullStructuredAddress(address, `${context}[${index}]`)
  );
}

/**
 * Check if legacy address has sufficient data for conversion
 */
export function hasMinimumAddressData(address: LegacyAddress): boolean {
  const hasCoordinates = address.coordinates?.lat && address.coordinates?.lng;
  const hasStreetInfo = address.line1 || address.formatted?.street;
  const hasLocationInfo = address.city && address.postcode;
  
  return !!(hasCoordinates && hasStreetInfo && hasLocationInfo);
}

/**
 * Get validation status for UI display
 */
export function getAddressValidationStatus(address: LegacyAddress) {
  try {
    convertToFullStructuredAddress(address);
    return {
      isValid: true,
      status: 'complete' as const,
      message: 'Address ready for Enterprise Engine'
    };
  } catch (error) {
    const hasMinimal = hasMinimumAddressData(address);
    return {
      isValid: false,
      status: hasMinimal ? 'partial' as const : 'missing' as const,
      message: error instanceof Error ? error.message : 'Address validation failed'
    };
  }
}

/**
 * Sanitize address for logging (remove sensitive data)
 */
export function sanitizeAddressForLog(address: FullStructuredAddress | LegacyAddress) {
  const baseInfo = {
    city: 'city' in address ? address.city : 'unknown',
    postcode: 'postcode' in address && address.postcode 
      ? address.postcode.substring(0, 4) + '***' 
      : 'unknown',
  };

  if ('coordinates' in address && address.coordinates) {
    return {
      ...baseInfo,
      coordinates: address.coordinates
    };
  }

  return baseInfo;
}

/**
 * Middleware for API route validation
 */
export function createAddressValidationMiddleware() {
  return (addresses: any[], context: string) => {
    if (!Array.isArray(addresses) || addresses.length === 0) {
      throw new Error(`${context}: No addresses provided`);
    }

    return addresses.map((address, index) => {
      if (!address) {
        throw new Error(`${context}[${index}]: Null or undefined address`);
      }

      // Check for postcode-only pattern (FORBIDDEN)
      if (typeof address === 'string' || 
          (typeof address === 'object' && Object.keys(address).length === 1 && address.postcode)) {
        throw new Error(
          `${context}[${index}]: Postcode-only addresses are forbidden. ` +
          `Enterprise Engine requires full structured addresses from autocomplete.`
        );
      }

      return convertToFullStructuredAddress(address, `${context}[${index}]`);
    });
  };
}

/**
 * Runtime assertion for API endpoints
 */
export function assertFullStructuredAddresses(
  addresses: any[], 
  context: string = 'API request'
): FullStructuredAddress[] {
  const validator = createAddressValidationMiddleware();
  return validator(addresses, context);
}

import { NextRequest, NextResponse } from 'next/server';
import { z, ZodError } from 'zod';
import { 
  ApiSuccessResponseSchema, 
  ApiErrorResponseSchema,
  validateApiRequest 
} from './schemas';

// Generic API validation wrapper
export function withValidation<T extends z.ZodTypeAny>(
  schema: T,
  handler: (data: z.infer<T>, request: NextRequest) => Promise<NextResponse>
) {
  return async (request: NextRequest): Promise<NextResponse> => {
    try {
      const body = await request.json();
      const validation = validateApiRequest(schema, body);
      
      if (!validation.success) {
        const errorResponse = ApiErrorResponseSchema.parse({
          success: false,
          error: 'Validation failed',
          code: 'VALIDATION_ERROR',
          message: 'Request data is invalid',
          details: 'One or more fields failed validation',
          validationErrors: validation.errors.errors.map(err => ({
            field: err.path.join('.'),
            message: err.message,
          })),
          statusCode: 400,
          timestamp: new Date().toISOString(),
          requestId: request.headers.get('x-request-id') || undefined,
          path: request.url,
        });
        
        return NextResponse.json(errorResponse, { status: 400 });
      }
      
      return await handler(validation.data, request);
    } catch (error) {
      console.error('API validation error:', error);
      
      const errorResponse = ApiErrorResponseSchema.parse({
        success: false,
        error: 'Internal server error',
        code: 'INTERNAL_ERROR',
        message: 'An unexpected error occurred',
        details: error instanceof Error ? error.message : 'Unknown error',
        statusCode: 500,
        timestamp: new Date().toISOString(),
        requestId: request.headers.get('x-request-id') || undefined,
        path: request.url,
      });
      
      return NextResponse.json(errorResponse, { status: 500 });
    }
  };
}

// Query parameter validation
export function withQueryValidation<T extends z.ZodTypeAny>(
  schema: T,
  handler: (data: z.infer<T>, request: NextRequest) => Promise<NextResponse>
) {
  return async (request: NextRequest): Promise<NextResponse> => {
    try {
      const { searchParams } = new URL(request.url);
      const queryData = Object.fromEntries(searchParams.entries());
      
      const validation = validateApiRequest(schema, queryData);
      
      if (!validation.success) {
        const errorResponse = ApiErrorResponseSchema.parse({
          success: false,
          error: 'Query validation failed',
          code: 'QUERY_VALIDATION_ERROR',
          message: 'Query parameters are invalid',
          details: 'One or more query parameters failed validation',
          validationErrors: validation.errors.errors.map(err => ({
            field: err.path.join('.'),
            message: err.message,
          })),
          statusCode: 400,
          timestamp: new Date().toISOString(),
          requestId: request.headers.get('x-request-id') || undefined,
          path: request.url,
        });
        
        return NextResponse.json(errorResponse, { status: 400 });
      }
      
      return await handler(validation.data, request);
    } catch (error) {
      console.error('Query validation error:', error);
      
      const errorResponse = ApiErrorResponseSchema.parse({
        success: false,
        error: 'Internal server error',
        code: 'INTERNAL_ERROR',
        message: 'An unexpected error occurred',
        details: error instanceof Error ? error.message : 'Unknown error',
        statusCode: 500,
        timestamp: new Date().toISOString(),
        requestId: request.headers.get('x-request-id') || undefined,
        path: request.url,
      });
      
      return NextResponse.json(errorResponse, { status: 500 });
    }
  };
}

// Response formatting helpers
export function createSuccessResponse<T>(
  data: T,
  message?: string,
  requestId?: string
): NextResponse {
  const response = ApiSuccessResponseSchema(z.any()).parse({
    success: true,
    data,
    message,
    timestamp: new Date().toISOString(),
    requestId,
  });
  
  return NextResponse.json(response);
}

export function createErrorResponse(
  error: string,
  code: string,
  message: string,
  statusCode: number = 400,
  details?: string,
  validationErrors?: Array<{ field: string; message: string }>,
  requestId?: string,
  path?: string
): NextResponse {
  const response = ApiErrorResponseSchema.parse({
    success: false,
    error,
    code,
    message,
    details,
    validationErrors,
    statusCode,
    timestamp: new Date().toISOString(),
    requestId,
    path,
  });
  
  return NextResponse.json(response, { status: statusCode });
}

// Prisma integration helpers
export function validatePrismaInput<T extends z.ZodTypeAny>(
  schema: T,
  data: unknown
): { success: true; data: z.infer<T> } | { success: false; error: string } {
  try {
    const result = schema.parse(data);
    return { success: true, data: result };
  } catch (error) {
    if (error instanceof ZodError) {
      return { 
        success: false, 
        error: `Validation failed: ${error.errors.map(e => e.message).join(', ')}` 
      };
    }
    return { 
      success: false, 
      error: error instanceof Error ? error.message : 'Unknown validation error' 
    };
  }
}

// Middleware for request validation
export function createValidationMiddleware<T extends z.ZodTypeAny>(schema: T) {
  return (request: NextRequest) => {
    try {
      const body = request.body ? request.json() : Promise.resolve({});
      return body.then((data: unknown) => {
        const validation = validateApiRequest(schema, data);
        if (!validation.success) {
          throw new Error('Validation failed');
        }
        return validation.data;
      });
    } catch (error) {
      throw new Error('Invalid request data');
    }
  };
}

import { NextRequest, NextResponse } from 'next/server';
