 */
class DispatchAgent extends BaseAgent {
  type: AgentType = 'dispatch';
  name = 'وكيل التوزيع';
  description = 'متخصص في تحسين المسارات وتعيين السائقين وكفاءة التوصيل';
  
  capabilities: AgentCapability[] = [
