/**
 * Multi-Agent System
 * Coordinates multiple specialized agents
 */
export class MultiAgentSystem {
  private agents: Map<AgentType, BaseAgent> = new Map();
  private taskQueue: AgentTask[] = [];

  constructor() {
    // Initialize all agents
    this.agents.set('ops', new OpsAgent());
    this.agents.set('finance', new FinanceAgent());
    this.agents.set('dispatch', new DispatchAgent());
    this.agents.set('analytics', new AnalyticsAgent());
  }

  /**
   * Route task to appropriate agent
   */
  routeTask(goal: string): AgentType | null {
    for (const [type, agent] of this.agents) {
      if (agent.canHandle(goal)) {
        return type;
      }
    }
    return null;
  }

  /**
   * Execute task with appropriate agent
   */
  async executeWithAgent(
    goal: string,
    context: ToolContext,
    agentType?: AgentType
  ): Promise<ToolResult<any>> {
    // Auto-route if agent not specified
    const targetAgent = agentType || this.routeTask(goal);

    if (!targetAgent) {
      return {
        success: false,
        error: 'لم أتمكن من تحديد الوكيل المناسب لهذه المهمة',
      };
    }

    const agent = this.agents.get(targetAgent);
    if (!agent) {
      return {
        success: false,
        error: 'الوكيل غير موجود',
      };
    }

    const task: AgentTask = {
      id: `task_${Date.now()}`,
      type: targetAgent,
      goal,
      context: {},
      priority: 'medium',
      status: 'in_progress',
    };

    try {
      const result = await agent.execute(task, context);
      task.status = result.success ? 'completed' : 'failed';
      task.result = result.data;
      task.error = result.error;

      return result;
    } catch (error) {
      task.status = 'failed';
      task.error = error instanceof Error ? error.message : 'Unknown error';

      return {
        success: false,
        error: task.error,
      };
    }
  }

  /**
   * Get all agents info
   */
  getAgentsInfo() {
    return Array.from(this.agents.values()).map(agent => agent.getInfo());
  }

  /**
   * Get agent by type
   */
  getAgent(type: AgentType): BaseAgent | undefined {
    return this.agents.get(type);
  }

  /**
   * Collaborate between multiple agents
   */
  async collaborate(
    goal: string,
    context: ToolContext,
    involvedAgents: AgentType[]
  ): Promise<ToolResult<any>> {
    const results: any[] = [];

    for (const agentType of involvedAgents) {
      const result = await this.executeWithAgent(goal, context, agentType);
      results.push({
        agent: agentType,
        result,
      });
    }

    const allSuccessful = results.every(r => r.result.success);

    return {
      success: allSuccessful,
      data: {
        collaboration: true,
        agents: involvedAgents,
        results,
        summary: `${results.length} agents collaborated on the task`,
      },
    };
  }
}

// Singleton instance
export const multiAgentSystem = new MultiAgentSystem();

import { prisma } from '@/lib/prisma';
import { createAuditLogEntry } from '@/lib/audit';
import { multiAgentSystem, MultiAgentSystem } from '../agents/MultiAgentSystem';
import { ToolContext, ToolResult } from '../tools/base/ToolExecutor';
import { orderTools } from '../tools/orderTools';
import { driverTools } from '../tools/driverTools';
import { financeTools } from '../tools/financeTools';
import { analyticsTools } from '../tools/analyticsTools';

/**
 * Intent types
 */
type IntentType = 
  | 'query'           // استعلام بيانات
  | 'action'          // تنفيذ عملية
  | 'analysis'        // تحليل
  | 'automation'      // أتمتة
  | 'collaboration'   // تعاون بين agents
  | 'unknown';        // غير محدد

/**
 * Intent classification
 */
interface Intent {
  type: IntentType;
  confidence: number;
  goal: string;
  entities: Record<string, any>;
  suggestedAgent?: string;
  suggestedTool?: string;
  requiresConfirmation: boolean;
  riskLevel: 'low' | 'medium' | 'high';
}

/**
 * Execution context
 */
interface ExecutionContext {
  userId: string;
  userRole: string;
  sessionId: string;
  timestamp: Date;
  metadata?: Record<string, any>;
}

/**
 * Orchestration result
 */
interface OrchestrationResult {
  success: boolean;
  intent: Intent;
  agent?: string;
  tool?: string;
  result?: any;
  error?: string;
  auditLogId?: string;
  executionTime: number;
  dashboardUpdate?: {
    type: string;
    data: any;
  };
}

/**
 * Safety check result
 */
interface SafetyCheckResult {
  safe: boolean;
  reasons?: string[];
  riskLevel: 'low' | 'medium' | 'high';
  requiresApproval: boolean;
}

/**
 * Core Orchestrator
 * المنسق الأساسي - يربط جميع مكونات النظام
 */
export class CoreOrchestrator {
  private multiAgent: MultiAgentSystem;
  private allTools: Map<string, any>;

  constructor() {
    this.multiAgent = multiAgentSystem;
    
    // Collect all available tools
    this.allTools = new Map();
    this.registerTools();
  }

  /**
   * Register all tools in the system
   */
  private registerTools() {
    [...orderTools, ...driverTools, ...financeTools, ...analyticsTools]
      .forEach(tool => {
        this.allTools.set(tool.name, tool);
      });
  }

  /**
   * Main orchestration method
   * نقطة الدخول الرئيسية لجميع العمليات
   */
  async orchestrate(
    userInput: string,
    context: ExecutionContext
  ): Promise<OrchestrationResult> {
    const startTime = Date.now();

    try {
      // Step 1: Analyze intent
      const intent = this.analyzeIntent(userInput);

      // Step 2: Safety check
      const safetyCheck = await this.performSafetyCheck(intent, context);
      
      if (!safetyCheck.safe) {
        return {
          success: false,
          intent,
          error: `عملية غير آمنة: ${safetyCheck.reasons?.join(', ')}`,
          executionTime: Date.now() - startTime,
        };
      }

      // Step 3: Requires confirmation?
      if (safetyCheck.requiresApproval && !context.metadata?.confirmed) {
        return {
          success: false,
          intent,
          error: 'requires_confirmation',
          executionTime: Date.now() - startTime,
        };
      }

      // Step 4: Execute based on intent type
      let result: any;
      let agent: string | undefined;
      let tool: string | undefined;

      switch (intent.type) {
        case 'automation':
          result = {
            success: false,
            error: 'Automation engine not yet implemented',
          };
          break;

        case 'collaboration':
          result = await this.executeCollaboration(intent, context);
          agent = 'multi-agent';
          break;

        case 'action':
        case 'query':
        case 'analysis':
          const execution = await this.executeWithAgent(intent, context);
          result = execution.result;
          agent = execution.agent;
          tool = execution.tool;
          break;

        default:
          result = {
            success: false,
            error: 'لم أتمكن من فهم الطلب',
          };
      }

      // Step 5: Create audit log
      const auditLogId = await this.createAuditLog(
        intent,
        context,
        result,
        agent,
        tool
      );

      // Step 6: Generate dashboard update
      const dashboardUpdate = this.generateDashboardUpdate(intent, result);

      // Step 7: Return result
      return {
        success: result.success !== false,
        intent,
        agent,
        tool,
        result: result.data || result,
        error: result.error,
        auditLogId,
        executionTime: Date.now() - startTime,
        dashboardUpdate,
      };

    } catch (error) {
      return {
        success: false,
        intent: { type: 'unknown', confidence: 0, goal: userInput, entities: {}, requiresConfirmation: false, riskLevel: 'low' },
        error: error instanceof Error ? error.message : 'خطأ غير متوقع',
        executionTime: Date.now() - startTime,
      };
    }
  }

  /**
   * Analyze user intent
   * تحليل نية المستخدم من النص
   */
  private analyzeIntent(input: string): Intent {
    const inputLower = input.toLowerCase();
    const inputArabic = input;

    // Initialize intent
    const intent: Intent = {
      type: 'unknown',
      confidence: 0,
      goal: input,
      entities: {},
      requiresConfirmation: false,
      riskLevel: 'low',
    };

    // Keywords mapping
    const keywords = {
      query: ['show', 'get', 'list', 'display', 'عرض', 'اعرض', 'أظهر', 'اطلع', 'كم'],
      action: ['assign', 'cancel', 'create', 'update', 'delete', 'عين', 'ألغ', 'أنشئ', 'حدث', 'احذف'],
      analysis: ['analyze', 'report', 'summary', 'trends', 'حلل', 'تقرير', 'ملخص', 'اتجاهات'],
      automation: ['automate', 'schedule', 'recurring', 'آلي', 'جدول', 'متكرر'],
      collaboration: ['optimize', 'best', 'recommend', 'حسن', 'أفضل', 'انصح'],
    };

    // Detect intent type
    for (const [type, words] of Object.entries(keywords)) {
      if (words.some(word => inputLower.includes(word) || inputArabic.includes(word))) {
        intent.type = type as IntentType;
        intent.confidence = 0.8;
        break;
      }
    }

    // Extract entities
    this.extractEntities(input, intent);

    // Determine risk level
    intent.riskLevel = this.determineRiskLevel(intent);

    // Requires confirmation?
    intent.requiresConfirmation = this.requiresConfirmation(intent);

    // Suggest agent
    intent.suggestedAgent = this.suggestAgent(intent);

    // Suggest tool
    intent.suggestedTool = this.suggestTool(intent);

    return intent;
  }

  /**
   * Extract entities from input
   */
  private extractEntities(input: string, intent: Intent) {
    const inputLower = input.toLowerCase();

    // Order ID
    const orderMatch = input.match(/order[:\s#]+(\d+)|طلب[:\s#]+(\d+)/i);
    if (orderMatch) {
      intent.entities.orderId = orderMatch[1] || orderMatch[2];
    }

    // Driver ID
    const driverMatch = input.match(/driver[:\s#]+(\d+)|سائق[:\s#]+(\d+)/i);
    if (driverMatch) {
      intent.entities.driverId = driverMatch[1] || driverMatch[2];
    }

    // Time period
    if (inputLower.includes('today') || input.includes('اليوم')) {
      intent.entities.period = 'today';
    } else if (inputLower.includes('week') || input.includes('أسبوع')) {
      intent.entities.period = 'week';
    } else if (inputLower.includes('month') || input.includes('شهر')) {
      intent.entities.period = 'month';
    }

    // Count/limit
    const countMatch = input.match(/(\d+)\s*(orders?|طلب)/i);
    if (countMatch) {
      intent.entities.limit = parseInt(countMatch[1]);
    }
  }

  /**
   * Determine risk level
   */
  private determineRiskLevel(intent: Intent): 'low' | 'medium' | 'high' {
    const dangerousActions = ['delete', 'cancel', 'refund', 'احذف', 'ألغ', 'استرداد'];
    const inputLower = intent.goal.toLowerCase();

    if (dangerousActions.some(action => inputLower.includes(action))) {
      return 'high';
    }

    if (intent.type === 'action') {
      return 'medium';
    }

    return 'low';
  }

  /**
   * Check if action requires confirmation
   */
  private requiresConfirmation(intent: Intent): boolean {
    return intent.riskLevel === 'high' || 
           (intent.type === 'action' && intent.riskLevel === 'medium');
  }

  /**
   * Suggest appropriate agent
   */
  private suggestAgent(intent: Intent): string | undefined {
    const goal = intent.goal.toLowerCase();

    if (goal.includes('assign') || goal.includes('driver') || goal.includes('سائق')) {
      return 'dispatch';
    }

    if (goal.includes('revenue') || goal.includes('payment') || goal.includes('مالي')) {
      return 'finance';
    }

    if (goal.includes('trend') || goal.includes('kpi') || goal.includes('تحليل')) {
      return 'analytics';
    }

    if (goal.includes('order') || goal.includes('طلب')) {
      return 'ops';
    }

    return undefined;
  }

  /**
   * Suggest appropriate tool
   */
  private suggestTool(intent: Intent): string | undefined {
    const goal = intent.goal.toLowerCase();

    // Order tools
    if (goal.includes('unassigned')) return 'get_unassigned_orders';
    if (goal.includes('assign') && intent.entities.orderId) return 'assign_driver_to_order';
    if (goal.includes('cancel') && intent.entities.orderId) return 'cancel_order';

    // Driver tools
    if (goal.includes('available') && goal.includes('driver')) return 'get_available_drivers';
    if (goal.includes('best driver')) return 'find_best_driver';

    // Finance tools
    if (goal.includes('revenue')) return 'generate_revenue_report';
    if (goal.includes('outstanding')) return 'get_outstanding_payments';

    // Analytics tools
    if (goal.includes('kpi')) return 'get_kpis';
    if (goal.includes('trend')) return 'get_order_trends';

    return undefined;
  }

  /**
   * Perform safety checks
   */
  private async performSafetyCheck(
    intent: Intent,
    context: ExecutionContext
  ): Promise<SafetyCheckResult> {
    const reasons: string[] = [];

    // Check user permissions
    if (intent.type === 'action' && context.userRole !== 'admin' && context.userRole !== 'superadmin') {
      reasons.push('صلاحيات غير كافية');
      return {
        safe: false,
        reasons,
        riskLevel: 'high',
        requiresApproval: true,
      };
    }

    // Check for dangerous operations
    if (intent.riskLevel === 'high') {
      return {
        safe: true,
        riskLevel: 'high',
        requiresApproval: true,
      };
    }

    // Rate limiting check (simple version)
    // TODO: Implement proper rate limiting with Redis

    return {
      safe: true,
      riskLevel: intent.riskLevel,
      requiresApproval: intent.requiresConfirmation,
    };
  }



  /**
   * Execute collaboration between agents
   */
  private async executeCollaboration(
    intent: Intent,
    context: ExecutionContext
  ): Promise<ToolResult<any>> {
    const agents = ['ops', 'dispatch', 'analytics'] as any[];
    
    return await this.multiAgent.collaborate(
      intent.goal,
      {
        userId: context.userId,
        userRole: context.userRole,
        sessionId: context.sessionId,
        timestamp: context.timestamp,
      },
      agents
    );
  }

  /**
   * Execute with specific agent
   */
  private async executeWithAgent(
    intent: Intent,
    context: ExecutionContext
  ): Promise<{ result: any; agent?: string; tool?: string }> {
    const toolContext: ToolContext = {
      userId: context.userId,
      userRole: context.userRole,
      sessionId: context.sessionId,
      timestamp: context.timestamp,
    };

    // Try direct tool execution first
    if (intent.suggestedTool) {
      const tool = this.allTools.get(intent.suggestedTool);
      if (tool) {
        try {
          const result = await tool.execute(intent.entities, toolContext);
          return {
            result,
            tool: intent.suggestedTool,
          };
        } catch (error) {
          // Fall through to agent execution
        }
      }
    }

    // Use agent
    if (intent.suggestedAgent) {
      const result = await this.multiAgent.executeWithAgent(
        intent.goal,
        toolContext,
        intent.suggestedAgent as any
      );
      return {
        result,
        agent: intent.suggestedAgent,
      };
    }

    // Let multi-agent system decide
    const result = await this.multiAgent.executeWithAgent(
      intent.goal,
      toolContext
    );
    
    return {
      result,
      agent: 'auto-routed',
    };
  }

  /**
   * Create audit log
   */
  private async createAuditLog(
    intent: Intent,
    context: ExecutionContext,
    result: any,
    agent?: string,
    tool?: string
  ): Promise<string> {
    try {
      const log = await createAuditLogEntry({
        actorId: context.userId,
        actorRole: context.userRole ?? 'system',
        action: `AI_${intent.type.toUpperCase()}_${tool || agent || 'ORCHESTRATOR'}`,
        targetType: 'ai_orchestrator',
        targetId: context.sessionId,
        ipAddress: context.metadata?.ipAddress ?? null,
        userAgent: context.metadata?.userAgent ?? null,
        details: {
          intent: intent.goal,
          intentType: intent.type,
          confidence: intent.confidence,
          agent,
          tool,
          entities: intent.entities,
          success: result.success !== false,
          riskLevel: intent.riskLevel,
        },
      });

      return log.id;
    } catch (error) {
      console.error('Failed to create audit log:', error);
      return 'failed';
    }
  }

  /**
   * Generate dashboard update
   */
  private generateDashboardUpdate(intent: Intent, result: any): any {
    if (!result.success) return undefined;

    // Order-related updates
    if (intent.entities.orderId) {
      return {
        type: 'order_updated',
        data: {
          orderId: intent.entities.orderId,
          action: intent.type,
        },
      };
    }

    // Driver-related updates
    if (intent.entities.driverId) {
      return {
        type: 'driver_updated',
        data: {
          driverId: intent.entities.driverId,
          action: intent.type,
        },
      };
    }

    // Analytics updates
    if (intent.type === 'analysis') {
      return {
        type: 'analytics_refresh',
        data: {
          metrics: result.data,
        },
      };
    }

    return undefined;
  }

  /**
   * Get orchestrator status
   */
  getStatus() {
    return {
      tools: this.allTools.size,
      agents: this.multiAgent.getAgentsInfo().length,
      timestamp: new Date(),
    };
  }
}

// Singleton instance
export const coreOrchestrator = new CoreOrchestrator();

import { prisma } from '@/lib/prisma';

// Redis types
type Redis = any;

// Initialize Redis if available (optional - falls back to in-memory)
let redis: Redis | null = null;
// Redis disabled for now - using in-memory storage only
if (false && process.env.UPSTASH_REDIS_REST_URL) {
  console.log('Redis support available but disabled');
}

/**
 * Memory types
 */
type MemoryType = 
  | 'conversation'    // سجل المحادثة
  | 'context'         // سياق الجلسة
  | 'learning'        // تعلم من الأفعال السابقة
  | 'preference';     // تفضيلات المستخدم

/**
 * Memory entry
 */
interface MemoryEntry {
  id: string;
  userId: string;
  sessionId: string;
  type: MemoryType;
  content: any;
  timestamp: Date;
  expiresAt?: Date;
  metadata?: Record<string, any>;
}

/**
 * Conversation turn
 */
interface ConversationTurn {
  role: 'user' | 'assistant' | 'system';
  content: string;
  timestamp: Date;
  intent?: string;
  entities?: Record<string, any>;
  result?: any;
}

/**
 * Session context
 */
interface SessionContext {
  userId: string;
  sessionId: string;
  currentTopic?: string;
  recentEntities: Record<string, any>;
  conversationHistory: ConversationTurn[];
  activeOrderId?: string;
  activeDriverId?: string;
  preferences: Record<string, any>;
  lastActivity: Date;
}

/**
 * Learning entry
 */
interface LearningEntry {
  pattern: string;
  action: string;
  successRate: number;
  occurrences: number;
  lastSeen: Date;
}

/**
 * Memory System
 * نظام الذاكرة - يحافظ على السياق والتعلم من التفاعلات
 */
export class MemorySystem {
  private inMemoryStorage: Map<string, SessionContext> = new Map();
  private learningPatterns: Map<string, LearningEntry> = new Map();
  private readonly MAX_CONVERSATION_HISTORY = 20; // آخر 20 رسالة
  private readonly SESSION_TIMEOUT_MINUTES = 30;
  private readonly CONTEXT_EXPIRY_HOURS = 24;

  /**
   * Get or create session context
   */
  async getSessionContext(userId: string, sessionId: string): Promise<SessionContext> {
    const key = `${userId}:${sessionId}`;

    // Try in-memory first
    if (this.inMemoryStorage.has(key)) {
      const context = this.inMemoryStorage.get(key)!;
      
      // Check if session expired
      const minutesSinceLastActivity = 
        (Date.now() - context.lastActivity.getTime()) / 1000 / 60;
      
      if (minutesSinceLastActivity < this.SESSION_TIMEOUT_MINUTES) {
        return context;
      }
    }

    // Try Redis if available
    if (redis) {
      try {
        const cached = await redis.get(key) as SessionContext | null;
        if (cached) {
          this.inMemoryStorage.set(key, cached);
          return cached;
        }
      } catch (error) {
        console.error('Redis get error:', error);
      }
    }

    // Create new context
    const newContext: SessionContext = {
      userId,
      sessionId,
      recentEntities: {},
      conversationHistory: [],
      preferences: await this.loadUserPreferences(userId),
      lastActivity: new Date(),
    };

    await this.saveSessionContext(newContext);
    return newContext;
  }

  /**
   * Save session context
   */
  private async saveSessionContext(context: SessionContext) {
    const key = `${context.userId}:${context.sessionId}`;
    
    // Update timestamp
    context.lastActivity = new Date();

    // Save to in-memory
    this.inMemoryStorage.set(key, context);

    // Save to Redis if available
    if (redis) {
      try {
        await redis.set(key, context, {
          ex: this.SESSION_TIMEOUT_MINUTES * 60, // TTL in seconds
        });
      } catch (error) {
        console.error('Redis set error:', error);
      }
    }
  }

  /**
   * Add conversation turn
   */
  async addConversationTurn(
    userId: string,
    sessionId: string,
    turn: Omit<ConversationTurn, 'timestamp'>
  ) {
    const context = await this.getSessionContext(userId, sessionId);

    // Add turn with timestamp
    context.conversationHistory.push({
      ...turn,
      timestamp: new Date(),
    });

    // Keep only recent history
    if (context.conversationHistory.length > this.MAX_CONVERSATION_HISTORY) {
      context.conversationHistory = context.conversationHistory.slice(-this.MAX_CONVERSATION_HISTORY);
    }

    // Extract and update entities from this turn
    if (turn.entities) {
      Object.entries(turn.entities).forEach(([key, value]) => {
        if (value) {
          context.recentEntities[key] = value;
        }
      });
    }

    // Update active references
    if (turn.entities?.orderId) {
      context.activeOrderId = turn.entities.orderId;
    }
    if (turn.entities?.driverId) {
      context.activeDriverId = turn.entities.driverId;
    }

    await this.saveSessionContext(context);
  }

  /**
   * Get conversation history
   */
  async getConversationHistory(
    userId: string,
    sessionId: string,
    limit?: number
  ): Promise<ConversationTurn[]> {
    const context = await this.getSessionContext(userId, sessionId);
    const history = context.conversationHistory;

    if (limit) {
      return history.slice(-limit);
    }

    return history;
  }

  /**
   * Get recent entities (contextual information)
   */
  async getRecentEntities(userId: string, sessionId: string): Promise<Record<string, any>> {
    const context = await this.getSessionContext(userId, sessionId);
    return context.recentEntities;
  }

  /**
   * Update context topic
   */
  async updateTopic(userId: string, sessionId: string, topic: string) {
    const context = await this.getSessionContext(userId, sessionId);
    context.currentTopic = topic;
    await this.saveSessionContext(context);
  }

  /**
   * Get contextual suggestions based on history
   */
  async getContextualSuggestions(
    userId: string,
    sessionId: string
  ): Promise<string[]> {
    const context = await this.getSessionContext(userId, sessionId);
    const suggestions: string[] = [];

    // Based on active order
    if (context.activeOrderId) {
      suggestions.push(`عرض تفاصيل الطلب #${context.activeOrderId}`);
      suggestions.push(`تعيين سائق للطلب #${context.activeOrderId}`);
    }

    // Based on active driver
    if (context.activeDriverId) {
      suggestions.push(`عرض أداء السائق #${context.activeDriverId}`);
    }

    // Based on recent conversation
    const lastTurn = context.conversationHistory[context.conversationHistory.length - 1];
    if (lastTurn?.intent === 'query' && lastTurn.result?.success) {
      suggestions.push('تصدير هذه البيانات');
      suggestions.push('تحديث العرض');
    }

    // Based on topic
    if (context.currentTopic === 'orders') {
      suggestions.push('عرض الطلبات غير المعينة');
      suggestions.push('تقرير الطلبات اليوم');
    }

    return suggestions.slice(0, 5); // Top 5 suggestions
  }

  /**
   * Learn from action
   */
  async learnFromAction(
    pattern: string,
    action: string,
    success: boolean
  ) {
    const key = `${pattern}:${action}`;
    
    let entry = this.learningPatterns.get(key);
    
    if (!entry) {
      entry = {
        pattern,
        action,
        successRate: 0,
        occurrences: 0,
        lastSeen: new Date(),
      };
    }

    // Update statistics
    entry.occurrences++;
    entry.lastSeen = new Date();
    
    // Update success rate (weighted average)
    const weight = 0.2; // Give more weight to recent results
    entry.successRate = success 
      ? entry.successRate * (1 - weight) + weight
      : entry.successRate * (1 - weight);

    this.learningPatterns.set(key, entry);

    // Persist to database periodically (every 10 occurrences)
    if (entry.occurrences % 10 === 0) {
      await this.persistLearningPattern(entry);
    }
  }

  /**
   * Get learned action for pattern
   */
  async getLearnedAction(pattern: string): Promise<string | null> {
    // Find best matching learned pattern
    let bestMatch: LearningEntry | null = null;
    let bestScore = 0;

    for (const entry of this.learningPatterns.values()) {
      if (pattern.includes(entry.pattern) || entry.pattern.includes(pattern)) {
        const score = entry.successRate * Math.min(entry.occurrences / 10, 1);
        if (score > bestScore) {
          bestScore = score;
          bestMatch = entry;
        }
      }
    }

    if (bestMatch && bestScore > 0.5) {
      return bestMatch.action;
    }

    return null;
  }

  /**
   * Persist learning pattern to database
   */
  private async persistLearningPattern(entry: LearningEntry) {
    try {
      // Check if table exists before attempting to persist
      const tableExists = await prisma.$queryRaw<Array<{ exists: boolean }>>`
        SELECT EXISTS (
          SELECT FROM information_schema.tables 
          WHERE table_schema = 'public' 
          AND table_name = 'AILearningPattern'
        );
      `.then(result => result[0]?.exists).catch(() => false);

      if (!tableExists) {
        // Silently skip - this is an optional feature
        return;
      }

      await prisma.aILearningPattern.upsert({
        where: {
          pattern_action: {
            pattern: entry.pattern,
            action: entry.action,
          },
        },
        create: {
          pattern: entry.pattern,
          action: entry.action,
          successRate: entry.successRate,
          occurrences: entry.occurrences,
          lastSeen: entry.lastSeen,
        },
        update: {
          successRate: entry.successRate,
          occurrences: entry.occurrences,
          lastSeen: entry.lastSeen,
        },
      });
    } catch (error) {
      // Silently fail - this is an optional feature
      // console.error('Failed to persist learning pattern:', error);
    }
  }

  /**
   * Load user preferences
   */
  private async loadUserPreferences(userId: string): Promise<Record<string, any>> {
    try {
      const user = await prisma.user.findUnique({
        where: { id: userId },
        select: { metadata: true },
      });

      return (user?.metadata as any)?.aiPreferences || {};
    } catch (error) {
      console.error('Failed to load user preferences:', error);
      return {};
    }
  }

  /**
   * Save user preference
   */
  async saveUserPreference(userId: string, key: string, value: any) {
    try {
      const user = await prisma.user.findUnique({
        where: { id: userId },
        select: { metadata: true },
      });

      const metadata = (user?.metadata as any) || {};
      if (!metadata.aiPreferences) {
        metadata.aiPreferences = {};
      }

      metadata.aiPreferences[key] = value;

      await prisma.user.update({
        where: { id: userId },
        data: { metadata },
      });

      // Update session context
      for (const context of this.inMemoryStorage.values()) {
        if (context.userId === userId) {
          context.preferences[key] = value;
        }
      }
    } catch (error) {
      console.error('Failed to save user preference:', error);
    }
  }

  /**
   * Clear session context
   */
  async clearSession(userId: string, sessionId: string) {
    const key = `${userId}:${sessionId}`;
    
    this.inMemoryStorage.delete(key);

    if (redis) {
      try {
        await redis.del(key);
      } catch (error) {
        console.error('Redis delete error:', error);
      }
    }
  }

  /**
   * Get memory summary for debugging
   */
  getMemorySummary(userId: string, sessionId: string): any {
    const key = `${userId}:${sessionId}`;
    const context = this.inMemoryStorage.get(key);

    if (!context) {
      return { status: 'no_active_session' };
    }

    return {
      status: 'active',
      conversationTurns: context.conversationHistory.length,
      recentEntities: Object.keys(context.recentEntities),
      currentTopic: context.currentTopic,
      activeOrderId: context.activeOrderId,
      activeDriverId: context.activeDriverId,
      lastActivity: context.lastActivity,
      preferences: Object.keys(context.preferences),
    };
  }

  /**
   * Initialize learning patterns from database
   * Optional feature - gracefully handles missing table
   */
  async initializeLearningPatterns() {
    try {
      // Check if table exists by attempting a count query first
      const tableExists = await prisma.$queryRaw<Array<{ exists: boolean }>>`
        SELECT EXISTS (
          SELECT FROM information_schema.tables 
          WHERE table_schema = 'public' 
          AND table_name = 'AILearningPattern'
        );
      `.then(result => result[0]?.exists).catch(() => false);

      if (!tableExists) {
        console.log('⚠️ AILearningPattern table not found - skipping learning patterns initialization (optional feature)');
        return;
      }

      const patterns = await prisma.aILearningPattern.findMany({
        where: {
          successRate: { gt: 0.3 }, // Only load patterns with decent success rate
        },
        orderBy: { occurrences: 'desc' },
        take: 100, // Top 100 patterns
      });

      patterns.forEach((pattern: any) => {
        const key = `${pattern.pattern}:${pattern.action}`;
        this.learningPatterns.set(key, {
          pattern: pattern.pattern,
          action: pattern.action,
          successRate: pattern.successRate,
          occurrences: pattern.occurrences,
          lastSeen: pattern.lastSeen,
        });
      });

      console.log(`✅ Loaded ${patterns.length} learning patterns`);
    } catch (error) {
      // Silently fail - this is an optional feature
      console.log('⚠️ Learning patterns initialization skipped (optional feature)');
    }
  }

  /**
   * Cleanup expired sessions
   */
  async cleanupExpiredSessions() {
    const now = Date.now();
    const expiredKeys: string[] = [];

    for (const [key, context] of this.inMemoryStorage.entries()) {
      const minutesSinceLastActivity = 
        (now - context.lastActivity.getTime()) / 1000 / 60;
      
      if (minutesSinceLastActivity > this.SESSION_TIMEOUT_MINUTES) {
        expiredKeys.push(key);
      }
    }

    expiredKeys.forEach(key => this.inMemoryStorage.delete(key));

    if (expiredKeys.length > 0) {
      console.log(`Cleaned up ${expiredKeys.length} expired sessions`);
    }
  }
}

// Singleton instance
export const memorySystem = new MemorySystem();

// Initialize learning patterns on startup
memorySystem.initializeLearningPatterns();

// Cleanup expired sessions every 5 minutes
setInterval(() => {
  memorySystem.cleanupExpiredSessions();
}, 5 * 60 * 1000);

import { BookingStatus } from '@prisma/client';
import { prisma } from '@/lib/prisma';
import { createAuditLogEntry } from '@/lib/audit';

/**
 * Command suggestion with context
 */
interface CommandSuggestion {
  command: string;
  reason: string;
  priority: 'high' | 'medium' | 'low';
  category: 'orders' | 'drivers' | 'finance' | 'analytics';
}

/**
 * User context for predictions
 */
interface UserContext {
  userId: string;
  currentTime: Date;
  lastCommands?: string[];
  recentActivity?: any[];
}

/**
 * Predictive Commands Engine
 * Suggests commands based on time, context, and patterns
 */
export class PredictiveCommandsEngine {
  /**
   * Get command suggestions for user
   */
  async getSuggestions(context: UserContext): Promise<CommandSuggestion[]> {
    const suggestions: CommandSuggestion[] = [];
    const hour = context.currentTime.getHours();
    const dayOfWeek = context.currentTime.getDay();

    // Time-based suggestions
    suggestions.push(...this.getTimeBasedSuggestions(hour, dayOfWeek));

    // Context-based suggestions (pending orders, drivers status, etc.)
    suggestions.push(...await this.getContextBasedSuggestions());

    // Pattern-based suggestions (user's history)
    if (context.lastCommands && context.lastCommands.length > 0) {
      suggestions.push(...this.getPatternBasedSuggestions(context.lastCommands));
    }

    // Sort by priority
    return suggestions.sort((a, b) => {
      const priorityOrder = { high: 3, medium: 2, low: 1 };
      return priorityOrder[b.priority] - priorityOrder[a.priority];
    });
  }

  /**
   * Time-based suggestions
   */
  private getTimeBasedSuggestions(hour: number, dayOfWeek: number): CommandSuggestion[] {
    const suggestions: CommandSuggestion[] = [];

    // Morning (6-10 AM)
    if (hour >= 6 && hour < 10) {
      suggestions.push({
        command: 'daily report',
        reason: 'بداية يوم العمل - مراجعة تقرير اليوم',
        priority: 'high',
        category: 'analytics',
      });
      suggestions.push({
        command: 'get unassigned orders',
        reason: 'طلبات جديدة قد تحتاج تعيين',
        priority: 'high',
        category: 'orders',
      });
    }

    // Midday (10 AM - 2 PM)
    if (hour >= 10 && hour < 14) {
      suggestions.push({
        command: 'get available drivers',
        reason: 'ذروة الطلبات - تحقق من توفر السائقين',
        priority: 'medium',
        category: 'drivers',
      });
    }

    // Afternoon (2-5 PM)
    if (hour >= 14 && hour < 17) {
      suggestions.push({
        command: 'get kpis',
        reason: 'مراجعة أداء اليوم حتى الآن',
        priority: 'medium',
        category: 'analytics',
      });
    }

    // Evening (5-8 PM)
    if (hour >= 17 && hour < 20) {
      suggestions.push({
        command: 'financial summary for today',
        reason: 'مراجعة إيرادات اليوم',
        priority: 'high',
        category: 'finance',
      });
      suggestions.push({
        command: 'get outstanding payments',
        reason: 'متابعة المدفوعات المعلقة',
        priority: 'medium',
        category: 'finance',
      });
    }

    // Monday specific
    if (dayOfWeek === 1) {
      suggestions.push({
        command: 'get order trends for last 7 days',
        reason: 'بداية الأسبوع - مراجعة اتجاهات الأسبوع الماضي',
        priority: 'medium',
        category: 'analytics',
      });
    }

    // Friday specific
    if (dayOfWeek === 5) {
      suggestions.push({
        command: 'generate revenue report for this week',
        reason: 'نهاية الأسبوع - تقرير الإيرادات الأسبوعي',
        priority: 'high',
        category: 'finance',
      });
    }

    return suggestions;
  }

  /**
   * Context-based suggestions (real-time data)
   */
  private async getContextBasedSuggestions(): Promise<CommandSuggestion[]> {
    const suggestions: CommandSuggestion[] = [];

    try {
      // Check unassigned orders
      const unassignedCount = await prisma.booking.count({
        where: {
          status: { in: [BookingStatus.CONFIRMED, BookingStatus.PENDING_PAYMENT] },
          driverId: null,
        },
      });

      if (unassignedCount > 5) {
        suggestions.push({
          command: 'auto assign orders to drivers',
          reason: `${unassignedCount} طلبات غير معينة - تعيين تلقائي مقترح`,
          priority: 'high',
          category: 'orders',
        });
      } else if (unassignedCount > 0) {
        suggestions.push({
          command: 'get unassigned orders',
          reason: `${unassignedCount} طلبات تحتاج تعيين`,
          priority: 'medium',
          category: 'orders',
        });
      }

      // Check available drivers
      const availableDrivers = await prisma.driver.count({
        where: {
          status: 'active',
          DriverAvailability: {
            status: 'online',
          },
        },
      });

      if (availableDrivers < 3) {
        suggestions.push({
          command: 'get available drivers',
          reason: `فقط ${availableDrivers} سائقين متاحين - قد تحتاج المزيد`,
          priority: 'high',
          category: 'drivers',
        });
      }

      // Check outstanding payments
      const outstandingResult = await prisma.$queryRaw<{ count: bigint }[]>`
        SELECT COUNT(*)::bigint AS count
        FROM "Booking"
        WHERE "status" = ${BookingStatus.COMPLETED}
          AND COALESCE("amountPaidGBP", 0) < "totalGBP"
      `;
      const outstandingCount = Number(outstandingResult[0]?.count ?? 0);

      if (outstandingCount > 10) {
        suggestions.push({
          command: 'get outstanding payments',
          reason: `${outstandingCount} طلب مكتمل بمدفوعات معلقة`,
          priority: 'medium',
          category: 'finance',
        });
      }

      // Check delayed orders
      const now = new Date();
      const oneHourAgo = new Date(now.getTime() - 60 * 60 * 1000);
      
      const delayedOrders = await prisma.booking.count({
        where: {
          status: BookingStatus.CONFIRMED,
          driverId: { not: null },
          scheduledAt: { lt: oneHourAgo },
        },
      });

      if (delayedOrders > 0) {
        suggestions.push({
          command: 'get operational efficiency',
          reason: `${delayedOrders} طلبات متأخرة - تحليل الكفاءة مطلوب`,
          priority: 'high',
          category: 'analytics',
        });
      }

    } catch (error) {
      console.error('Error getting context-based suggestions:', error);
    }

    return suggestions;
  }

  /**
   * Pattern-based suggestions (user history)
   */
  private getPatternBasedSuggestions(lastCommands: string[]): CommandSuggestion[] {
    const suggestions: CommandSuggestion[] = [];
    
    // Analyze command patterns
    const commandFrequency: Record<string, number> = {};
    lastCommands.forEach(cmd => {
      commandFrequency[cmd] = (commandFrequency[cmd] || 0) + 1;
    });

    // Find most frequent commands
    const frequentCommands = Object.entries(commandFrequency)
      .sort(([, a], [, b]) => b - a)
      .slice(0, 3);

    frequentCommands.forEach(([command, count]) => {
      if (count >= 2) {
        suggestions.push({
          command,
          reason: `استخدمت هذا الأمر ${count} مرات مؤخراً`,
          priority: 'low',
          category: this.categorizeCommand(command),
        });
      }
    });

    // If user frequently checks orders, suggest related commands
    if (lastCommands.some(cmd => cmd.includes('order'))) {
      suggestions.push({
        command: 'get order trends',
        reason: 'قد تهتم بتحليل اتجاهات الطلبات',
        priority: 'low',
        category: 'analytics',
      });
    }

    // If user frequently checks drivers, suggest performance analysis
    if (lastCommands.some(cmd => cmd.includes('driver'))) {
      suggestions.push({
        command: 'get driver performance analytics',
        reason: 'تحليل أداء السائقين قد يفيدك',
        priority: 'low',
        category: 'analytics',
      });
    }

    return suggestions;
  }

  /**
   * Categorize command
   */
  private categorizeCommand(command: string): 'orders' | 'drivers' | 'finance' | 'analytics' {
    const lower = command.toLowerCase();
    
    if (lower.includes('order') || lower.includes('طلب')) {
      return 'orders';
    }
    if (lower.includes('driver') || lower.includes('سائق')) {
      return 'drivers';
    }
    if (lower.includes('revenue') || lower.includes('payment') || lower.includes('إيراد') || lower.includes('دفع')) {
      return 'finance';
    }
    return 'analytics';
  }

  /**
   * Get smart quick actions based on current state
   */
  async getQuickActions(): Promise<{
    title: string;
    command: string;
    badge?: string;
    color: string;
  }[]> {
    const actions: {
      title: string;
      command: string;
      badge?: string;
      color: string;
    }[] = [];

    try {
      // Unassigned orders
      const unassignedCount = await prisma.booking.count({
        where: {
          status: { in: [BookingStatus.CONFIRMED, BookingStatus.PENDING_PAYMENT] },
          driverId: null,
        },
      });

      if (unassignedCount > 0) {
        actions.push({
          title: 'طلبات غير معينة',
          command: 'get unassigned orders',
          badge: unassignedCount.toString(),
          color: 'orange',
        });
      }

      // Available drivers
      const availableCount = await prisma.driver.count({
        where: {
          status: 'active',
          DriverAvailability: {
            status: 'online',
          },
        },
      });

      actions.push({
        title: 'سائقون متاحون',
        command: 'get available drivers',
        badge: availableCount.toString(),
        color: 'green',
      });

      // Today's summary
      actions.push({
        title: 'ملخص اليوم',
        command: 'daily report',
        color: 'purple',
      });

    } catch (error) {
      console.error('Error getting quick actions:', error);
    }

    return actions;
  }

  /**
   * Record command execution for learning
   */
  async recordCommandExecution(userId: string, command: string): Promise<void> {
    try {
      await createAuditLogEntry({
        actorId: userId,
        actorRole: 'system',
        action: 'AI_COMMAND_RECORDED',
        targetType: 'predictive_engine',
        targetId: command,
        details: {
          command,
          timestamp: new Date().toISOString(),
        },
      });
    } catch (error) {
      console.error('Error recording command:', error);
    }
  }
}

// Singleton instance
export const predictiveCommandsEngine = new PredictiveCommandsEngine();

import { prisma } from '@/lib/prisma';
import * as cron from 'node-cron';
import { createAuditLogEntry } from '@/lib/audit';
import { BookingStatus, AssignmentStatus } from '@prisma/client';

/**
 * Recurring task definition
 */
interface RecurringTask {
  id: string;
  name: string;
  description: string;
  schedule: string; // Cron expression
  enabled: boolean;
  lastRun?: Date;
  nextRun?: Date;
}

/**
 * Task execution result
 */
interface TaskResult {
  taskId: string;
  success: boolean;
  message: string;
  data?: any;
  duration: number;
}

/**
 * Recurring Tasks Bots
 * Automated tasks that run on schedule
 */
export class RecurringTasksBots {
  private tasks: Map<string, RecurringTask> = new Map();
  private scheduledJobs: Map<string, cron.ScheduledTask> = new Map();

  constructor() {
    this.initializeTasks();
  }

  /**
   * Initialize default tasks
   */
  private initializeTasks() {
    // Daily report at 8 AM
    this.registerTask({
      id: 'daily_report',
      name: 'تقرير يومي',
      description: 'إرسال تقرير يومي شامل للإدارة',
      schedule: '0 8 * * *', // 8 AM every day
      enabled: true,
    });

    // Payment reminders at 10 AM
    this.registerTask({
      id: 'payment_reminders',
      name: 'تذكيرات الدفع',
      description: 'إرسال تذكيرات للمدفوعات المعلقة',
      schedule: '0 10 * * *', // 10 AM every day
      enabled: true,
    });

    // Driver reassignment check every 30 minutes
    this.registerTask({
      id: 'driver_reassignment',
      name: 'إعادة تعيين السائقين',
      description: 'فحص الطلبات المتأخرة وإعادة التعيين',
      schedule: '*/30 * * * *', // Every 30 minutes
      enabled: true,
    });

    // Weekly performance report on Monday 9 AM
    this.registerTask({
      id: 'weekly_performance',
      name: 'تقرير أداء أسبوعي',
      description: 'تحليل أداء الأسبوع الماضي',
      schedule: '0 9 * * 1', // Monday 9 AM
      enabled: true,
    });

    // Monthly financial summary on 1st at 10 AM
    this.registerTask({
      id: 'monthly_financial',
      name: 'ملخص مالي شهري',
      description: 'تقرير مالي شامل للشهر الماضي',
      schedule: '0 10 1 * *', // 1st of month at 10 AM
      enabled: true,
    });

    // Auto-cleanup old logs every Sunday 2 AM
    this.registerTask({
      id: 'cleanup_logs',
      name: 'تنظيف السجلات القديمة',
      description: 'حذف سجلات المراجعة القديمة (أكثر من 90 يوم)',
      schedule: '0 2 * * 0', // Sunday 2 AM
      enabled: true,
    });
  }

  /**
   * Register a new task
   */
  registerTask(task: RecurringTask) {
    this.tasks.set(task.id, task);
    
    if (task.enabled) {
      this.scheduleTask(task);
    }
  }

  /**
   * Schedule a task
   */
  private scheduleTask(task: RecurringTask) {
    // Remove existing job if any
    this.unscheduleTask(task.id);

    try {
      const job = cron.schedule(task.schedule, async () => {
        await this.executeTask(task.id);
      });

      this.scheduledJobs.set(task.id, job);
      console.log(`✓ Scheduled task: ${task.name} (${task.schedule})`);
    } catch (error) {
      console.error(`Failed to schedule task ${task.id}:`, error);
    }
  }

  /**
   * Unschedule a task
   */
  private unscheduleTask(taskId: string) {
    const job = this.scheduledJobs.get(taskId);
    if (job) {
      job.stop();
      this.scheduledJobs.delete(taskId);
    }
  }

  /**
   * Execute a task
   */
  async executeTask(taskId: string): Promise<TaskResult> {
    const task = this.tasks.get(taskId);
    if (!task) {
      return {
        taskId,
        success: false,
        message: 'Task not found',
        duration: 0,
      };
    }

    const startTime = Date.now();
    console.log(`⚡ Executing task: ${task.name}`);

    try {
      let result: any;

      switch (taskId) {
        case 'daily_report':
          result = await this.generateDailyReport();
          break;
        case 'payment_reminders':
          result = await this.sendPaymentReminders();
          break;
        case 'driver_reassignment':
          result = await this.checkDriverReassignment();
          break;
        case 'weekly_performance':
          result = await this.generateWeeklyPerformance();
          break;
        case 'monthly_financial':
          result = await this.generateMonthlyFinancial();
          break;
        case 'cleanup_logs':
          result = await this.cleanupOldLogs();
          break;
        default:
          throw new Error('Unknown task');
      }

      const duration = Date.now() - startTime;

      // Log execution
      await createAuditLogEntry({
        actorId: 'system',
        actorRole: 'system',
        action: `RECURRING_TASK_${taskId.toUpperCase()}`,
        targetType: 'recurring_task',
        targetId: taskId,
        details: {
          taskName: task.name,
          result,
          duration,
          success: true,
        },
      });

      // Update task last run
      task.lastRun = new Date();

      console.log(`✓ Task completed: ${task.name} (${duration}ms)`);

      return {
        taskId,
        success: true,
        message: `Task ${task.name} completed successfully`,
        data: result,
        duration,
      };

    } catch (error) {
      const duration = Date.now() - startTime;
      console.error(`✗ Task failed: ${task.name}`, error);

      await createAuditLogEntry({
        actorId: 'system',
        actorRole: 'system',
        action: `RECURRING_TASK_${taskId.toUpperCase()}_FAILED`,
        targetType: 'recurring_task',
        targetId: taskId,
        details: {
          taskName: task.name,
          error: error instanceof Error ? error.message : 'Unknown error',
          duration,
          success: false,
        },
      });

      return {
        taskId,
        success: false,
        message: error instanceof Error ? error.message : 'Task execution failed',
        duration,
      };
    }
  }

  /**
   * Generate daily report
   */
  private async generateDailyReport() {
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    const [orders, revenue, drivers, issues] = await Promise.all([
      // Today's orders
      prisma.booking.count({
        where: { createdAt: { gte: today } },
      }),

      // Today's revenue
      prisma.booking.aggregate({
        where: {
          status: BookingStatus.COMPLETED,
          actualDeliveryTime: { gte: today },
        },
        _sum: { totalGBP: true },
      }),

      // Active drivers
      prisma.driver.count({
        where: { status: 'active' },
      }),

      // Pending issues
      prisma.booking.count({
        where: {
          status: { in: [BookingStatus.PENDING_PAYMENT, BookingStatus.CONFIRMED] },
          driverId: null,
        },
      }),
    ]);

    return {
      date: today.toISOString(),
      orders,
      revenue: revenue._sum?.totalGBP || 0,
      drivers,
      pendingAssignments: issues,
    };
  }

  /**
   * Send payment reminders
   */
  private async sendPaymentReminders() {
    const overduePayments = await prisma.booking.findMany({
      where: {
        status: BookingStatus.COMPLETED,
        paidAt: null,
        actualDeliveryTime: {
          lt: new Date(Date.now() - 3 * 24 * 60 * 60 * 1000), // 3 days ago
        },
      },
      include: {
        customer: true,
      },
      take: 50,
    });

    // TODO: Send actual reminders via email/SMS
    console.log(`📧 Sending ${overduePayments.length} payment reminders`);

    return {
      remindersSent: overduePayments.length,
      totalAmount: overduePayments.reduce((sum, b) => sum + (b.totalGBP || 0), 0),
    };
  }

  /**
   * Check driver reassignment for delayed orders
   */
  private async checkDriverReassignment() {
    const oneHourAgo = new Date(Date.now() - 60 * 60 * 1000);
    
    const delayedOrders = await prisma.booking.findMany({
      where: {
        status: BookingStatus.CONFIRMED,
        Assignment: {
          some: {
            status: { in: [AssignmentStatus.claimed, AssignmentStatus.accepted] },
            createdAt: { lt: oneHourAgo },
          },
        },
      },
      take: 20,
    });

    // TODO: Implement reassignment logic
    console.log(`🔄 Found ${delayedOrders.length} delayed orders for reassignment`);

    return {
      delayedOrders: delayedOrders.length,
      reassigned: 0, // Placeholder
    };
  }

  /**
   * Generate weekly performance report
   */
  private async generateWeeklyPerformance() {
    const weekAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);

    const [orders, revenue, completionRate] = await Promise.all([
      prisma.booking.count({
        where: { createdAt: { gte: weekAgo } },
      }),

      prisma.booking.aggregate({
        where: {
          status: BookingStatus.COMPLETED,
          actualDeliveryTime: { gte: weekAgo },
        },
        _sum: { totalGBP: true },
      }),

      prisma.booking.groupBy({
        by: ['status'],
        where: { createdAt: { gte: weekAgo } },
        _count: true,
      }),
    ]);

    return {
      period: 'last_7_days',
      totalOrders: orders,
      revenue: revenue._sum?.totalGBP || 0,
      statusBreakdown: completionRate,
    };
  }

  /**
   * Generate monthly financial summary
   */
  private async generateMonthlyFinancial() {
    const lastMonth = new Date();
    lastMonth.setMonth(lastMonth.getMonth() - 1);
    lastMonth.setDate(1);
    lastMonth.setHours(0, 0, 0, 0);

    const thisMonth = new Date(lastMonth);
    thisMonth.setMonth(thisMonth.getMonth() + 1);

    const [revenue, expenses, orders] = await Promise.all([
      prisma.booking.aggregate({
        where: {
          status: BookingStatus.COMPLETED,
          actualDeliveryTime: {
            gte: lastMonth,
            lt: thisMonth,
          },
        },
        _sum: { totalGBP: true },
      }),

      prisma.driverEarnings.aggregate({
        where: {
          createdAt: {
            gte: lastMonth,
            lt: thisMonth,
          },
        },
        _sum: { rawNetEarningsPence: true },
      }),

      prisma.booking.count({
        where: {
          createdAt: {
            gte: lastMonth,
            lt: thisMonth,
          },
        },
      }),
    ]);

    return {
      month: lastMonth.toISOString(),
      revenue: revenue._sum?.totalGBP || 0,
      driverPayouts: expenses._sum?.rawNetEarningsPence || 0,
      netProfit: (revenue._sum?.totalGBP || 0) - (expenses._sum?.rawNetEarningsPence || 0),
      totalOrders: orders,
    };
  }

  /**
   * Cleanup old logs
   */
  private async cleanupOldLogs() {
    const ninetyDaysAgo = new Date(Date.now() - 90 * 24 * 60 * 60 * 1000);

    const result = await prisma.auditLog.deleteMany({
      where: {
        createdAt: { lt: ninetyDaysAgo },
      },
    });

    console.log(`🗑️ Deleted ${result.count} old audit logs`);

    return {
      deletedCount: result.count,
      cutoffDate: ninetyDaysAgo.toISOString(),
    };
  }

  /**
   * Get all tasks
   */
  getTasks(): RecurringTask[] {
    return Array.from(this.tasks.values());
  }

  /**
   * Enable/disable a task
   */
  setTaskEnabled(taskId: string, enabled: boolean) {
    const task = this.tasks.get(taskId);
    if (!task) return;

    task.enabled = enabled;

    if (enabled) {
      this.scheduleTask(task);
    } else {
      this.unscheduleTask(taskId);
    }
  }

  /**
   * Start all enabled tasks
   */
  startAll() {
    this.tasks.forEach(task => {
      if (task.enabled) {
        this.scheduleTask(task);
      }
    });
    console.log(`✓ Started ${this.scheduledJobs.size} recurring tasks`);
  }

  /**
   * Stop all tasks
   */
  stopAll() {
    this.scheduledJobs.forEach(job => job.stop());
    this.scheduledJobs.clear();
    console.log('✓ Stopped all recurring tasks');
  }
}

// Singleton instance
export const recurringTasksBots = new RecurringTasksBots();

import { z } from 'zod';
import { BaseTool, ToolContext, ToolResult } from './base/ToolExecutor';
import { orderTools } from './orderTools';
import { driverTools } from './driverTools';
import { financeTools } from './financeTools';
import { analyticsTools } from './analyticsTools';

/**
 * Action plan step
 */
interface ActionStep {
  id: string;
  tool: string;
  input: Record<string, any>;
  description: string;
  requiresConfirmation?: boolean;
  dependsOn?: string[]; // IDs of steps that must complete first
}

/**
 * Action plan generated by AOE
 */
interface ActionPlan {
  id: string;
  goal: string;
  steps: ActionStep[];
  estimatedDuration: number; // seconds
  riskLevel: 'low' | 'medium' | 'high';
  createdAt: Date;
}

/**
 * Execution result for a step
 */
interface StepResult {
  stepId: string;
  success: boolean;
  data?: any;
  error?: string;
  duration: number;
}

/**
 * Autonomous Operations Engine (AOE)
 * Converts natural language requests into executable action plans
 */
export class AutonomousOpsEngine {
  private tools: Map<string, BaseTool<any, any>>;

  constructor() {
    // Register all available tools
    this.tools = new Map();
    
    [...orderTools, ...driverTools, ...financeTools, ...analyticsTools].forEach(tool => {
      this.tools.set(tool.name, tool);
    });
  }

  /**
   * Parse natural language request and generate action plan
   */
  async generateActionPlan(request: string, context: ToolContext): Promise<ActionPlan> {
    const requestLower = request.toLowerCase();
    const steps: ActionStep[] = [];
    let riskLevel: 'low' | 'medium' | 'high' = 'low';

    // Pattern matching for common requests
    // ORDER MANAGEMENT
    if (requestLower.includes('unassigned order') || requestLower.includes('orders without driver')) {
      steps.push({
        id: 'step_1',
        tool: 'get_unassigned_orders',
        input: { limit: 50 },
        description: 'Fetch all unassigned orders',
      });
    }

    if (requestLower.includes('assign') && requestLower.includes('driver')) {
      // Extract order and driver IDs if present
      const orderMatch = requestLower.match(/order[:\s]+([a-z0-9-]+)/i);
      const driverMatch = requestLower.match(/driver[:\s]+([a-z0-9-]+)/i);

      if (orderMatch && driverMatch) {
        steps.push({
          id: 'step_assign',
          tool: 'assign_driver_to_order',
          input: {
            orderId: orderMatch[1],
            driverId: driverMatch[1],
            reason: 'Admin assigned via AI Assistant',
          },
          description: `Assign driver ${driverMatch[1]} to order ${orderMatch[1]}`,
          requiresConfirmation: true,
        });
        riskLevel = 'medium';
      } else {
        // Auto-assign workflow
        steps.push({
          id: 'step_1',
          tool: 'get_unassigned_orders',
          input: { limit: 10, sortBy: 'scheduledAt' },
          description: 'Get next unassigned orders',
        });
      }
    }

    if (requestLower.includes('cancel order')) {
      const orderMatch = requestLower.match(/order[:\s]+([a-z0-9-]+)/i);
      if (orderMatch) {
        steps.push({
          id: 'step_cancel',
          tool: 'cancel_order',
          input: {
            orderId: orderMatch[1],
            reason: requestLower.includes('reason') 
              ? requestLower.split('reason')[1].trim()
              : 'Cancelled by admin',
          },
          description: `Cancel order ${orderMatch[1]}`,
          requiresConfirmation: true,
        });
        riskLevel = 'high';
      }
    }

    // DRIVER MANAGEMENT
    if (requestLower.includes('available driver') || requestLower.includes('free driver')) {
      steps.push({
        id: 'step_drivers',
        tool: 'get_available_drivers',
        input: {},
        description: 'Get all available drivers',
      });
    }

    if (requestLower.includes('driver status') && requestLower.includes('change')) {
      const driverMatch = requestLower.match(/driver[:\s]+([a-z0-9-]+)/i);
      const statusMatch = requestLower.match(/(active|inactive|suspended)/i);
      
      if (driverMatch && statusMatch) {
        steps.push({
          id: 'step_status',
          tool: 'update_driver_status',
          input: {
            driverId: driverMatch[1],
            status: statusMatch[1].toLowerCase(),
            reason: 'Status changed via AI Assistant',
          },
          description: `Update driver ${driverMatch[1]} status to ${statusMatch[1]}`,
          requiresConfirmation: true,
        });
        riskLevel = 'medium';
      }
    }

    if (requestLower.includes('driver performance') || requestLower.includes('top driver')) {
      steps.push({
        id: 'step_perf',
        tool: 'get_driver_performance_analytics',
        input: {
          period: requestLower.includes('week') ? 'week' : 'month',
          topN: 10,
        },
        description: 'Analyze driver performance',
      });
    }

    // FINANCE
    if (requestLower.includes('revenue') || requestLower.includes('income')) {
      steps.push({
        id: 'step_revenue',
        tool: 'generate_revenue_report',
        input: {
          startDate: new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString(),
          endDate: new Date().toISOString(),
          groupBy: 'day',
        },
        description: 'Generate revenue report',
      });
    }

    if (requestLower.includes('refund')) {
      const orderMatch = requestLower.match(/order[:\s]+([a-z0-9-]+)/i);
      const amountMatch = requestLower.match(/(\d+(?:\.\d+)?)/);
      
      if (orderMatch && amountMatch) {
        steps.push({
          id: 'step_refund',
          tool: 'process_refund',
          input: {
            orderId: orderMatch[1],
            amount: parseFloat(amountMatch[1]),
            reason: 'Refund processed via AI Assistant',
          },
          description: `Process refund for order ${orderMatch[1]}`,
          requiresConfirmation: true,
        });
        riskLevel = 'high';
      }
    }

    if (requestLower.includes('financial summary') || requestLower.includes('finance overview')) {
      steps.push({
        id: 'step_summary',
        tool: 'get_financial_summary',
        input: {
          period: requestLower.includes('today') ? 'today' 
            : requestLower.includes('week') ? 'week'
            : requestLower.includes('year') ? 'year'
            : 'month',
        },
        description: 'Get financial summary',
      });
    }

    if (requestLower.includes('outstanding') || requestLower.includes('unpaid')) {
      steps.push({
        id: 'step_outstanding',
        tool: 'get_outstanding_payments',
        input: { limit: 50 },
        description: 'Get outstanding payments',
      });
    }

    // ANALYTICS
    if (requestLower.includes('kpi') || requestLower.includes('metrics')) {
      steps.push({
        id: 'step_kpi',
        tool: 'get_kpis',
        input: {
          period: requestLower.includes('today') ? 'today' 
            : requestLower.includes('week') ? 'week'
            : 'month',
          compareWithPrevious: true,
        },
        description: 'Get key performance indicators',
      });
    }

    if (requestLower.includes('trend') || requestLower.includes('pattern')) {
      steps.push({
        id: 'step_trend',
        tool: 'get_order_trends',
        input: {
          days: requestLower.includes('week') ? 7 : 30,
          groupBy: 'day',
        },
        description: 'Analyze order trends',
      });
    }

    if (requestLower.includes('customer behavior') || requestLower.includes('customer analytics')) {
      steps.push({
        id: 'step_customer',
        tool: 'get_customer_behavior_analytics',
        input: {
          segment: requestLower.includes('new') ? 'new'
            : requestLower.includes('vip') ? 'vip'
            : 'all',
        },
        description: 'Analyze customer behavior',
      });
    }

    if (requestLower.includes('efficiency') || requestLower.includes('bottleneck')) {
      steps.push({
        id: 'step_efficiency',
        tool: 'get_operational_efficiency',
        input: { period: 'month' },
        description: 'Analyze operational efficiency',
      });
    }

    // COMBINED WORKFLOWS
    if (requestLower.includes('auto assign') || requestLower.includes('smart assign')) {
      steps.push(
        {
          id: 'step_1',
          tool: 'get_unassigned_orders',
          input: { limit: 10, sortBy: 'scheduledAt' },
          description: 'Get unassigned orders',
        },
        {
          id: 'step_2',
          tool: 'get_available_drivers',
          input: {},
          description: 'Get available drivers',
          dependsOn: ['step_1'],
        }
      );
      riskLevel = 'medium';
    }

    if (requestLower.includes('daily report') || requestLower.includes('daily summary')) {
      steps.push(
        {
          id: 'step_1',
          tool: 'get_kpis',
          input: { period: 'today', compareWithPrevious: true },
          description: 'Get today\'s KPIs',
        },
        {
          id: 'step_2',
          tool: 'get_financial_summary',
          input: { period: 'today' },
          description: 'Get today\'s financials',
        },
        {
          id: 'step_3',
          tool: 'get_available_drivers',
          input: {},
          description: 'Get current driver availability',
        },
        {
          id: 'step_4',
          tool: 'get_unassigned_orders',
          input: { limit: 20 },
          description: 'Get pending orders',
        }
      );
    }

    // If no steps matched, return error plan
    if (steps.length === 0) {
      return {
        id: `plan_${Date.now()}`,
        goal: request,
        steps: [],
        estimatedDuration: 0,
        riskLevel: 'low',
        createdAt: new Date(),
      };
    }

    return {
      id: `plan_${Date.now()}`,
      goal: request,
      steps,
      estimatedDuration: steps.length * 2, // 2 seconds per step estimate
      riskLevel,
      createdAt: new Date(),
    };
  }

  /**
   * Execute an action plan
   */
  async executeActionPlan(
    plan: ActionPlan,
    context: ToolContext,
    onProgress?: (step: ActionStep, result: StepResult) => void
  ): Promise<{
    success: boolean;
    results: StepResult[];
    summary: string;
  }> {
    const results: StepResult[] = [];
    const completedSteps = new Set<string>();

    for (const step of plan.steps) {
      // Check dependencies
      if (step.dependsOn) {
        const dependenciesMet = step.dependsOn.every(dep => completedSteps.has(dep));
        if (!dependenciesMet) {
          results.push({
            stepId: step.id,
            success: false,
            error: 'Dependencies not met',
            duration: 0,
          });
          continue;
        }
      }

      const tool = this.tools.get(step.tool);
      if (!tool) {
        results.push({
          stepId: step.id,
          success: false,
          error: `Tool ${step.tool} not found`,
          duration: 0,
        });
        continue;
      }

      const startTime = Date.now();
      let result: ToolResult<any>;

      try {
        if (step.requiresConfirmation) {
          result = await tool.executeWithConfirmation(
            step.input, 
            context, 
            'auto_confirmed',
            'Auto-confirmed by AOE'
          );
        } else {
          result = await tool.execute(step.input, context);
        }

        const stepResult: StepResult = {
          stepId: step.id,
          success: result.success,
          data: result.data,
          error: result.error,
          duration: Date.now() - startTime,
        };

        results.push(stepResult);
        completedSteps.add(step.id);

        if (onProgress) {
          onProgress(step, stepResult);
        }

        // Stop execution if step failed
        if (!result.success) {
          break;
        }
      } catch (error) {
        results.push({
          stepId: step.id,
          success: false,
          error: error instanceof Error ? error.message : 'Unknown error',
          duration: Date.now() - startTime,
        });
        break;
      }
    }

    const successCount = results.filter(r => r.success).length;
    const totalSteps = plan.steps.length;

    return {
      success: successCount === totalSteps,
      results,
      summary: `Completed ${successCount}/${totalSteps} steps for: ${plan.goal}`,
    };
  }

  /**
   * Get tool by name
   */
  getTool(name: string): BaseTool<any, any> | undefined {
    return this.tools.get(name);
  }

  /**
   * List all available tools
   */
  listTools(): Array<{ name: string; description: string; riskLevel: string }> {
    return Array.from(this.tools.values()).map(tool => ({
      name: tool.name,
      description: tool.description,
      riskLevel: tool.riskLevel,
    }));
  }
}

// Singleton instance
export const autonomousOpsEngine = new AutonomousOpsEngine();

import { z } from 'zod';
import { AssignmentStatus, BookingStatus } from '@prisma/client';
import { prisma } from '@/lib/prisma';
import { BaseTool, RiskLevel, ToolContext } from './base/ToolExecutor';

/**
 * Get key performance indicators
 */
export class GetKPIsTool extends BaseTool {
  name = 'get_kpis';
  description = 'Get key performance indicators for the platform';
  riskLevel = RiskLevel.LOW;
  inputSchema = z.object({
    period: z.enum(['today', 'week', 'month', 'year']).default('month'),
    compareWithPrevious: z.boolean().optional().default(false),
  });

  protected async executeInternal(input: z.infer<typeof this.inputSchema>, context: ToolContext) {
    const now = new Date();
    let startDate: Date;
    let previousStartDate: Date | null = null;

    switch (input.period) {
      case 'today':
        startDate = new Date(now.setHours(0, 0, 0, 0));
        previousStartDate = new Date(startDate.getTime() - 24 * 60 * 60 * 1000);
        break;
      case 'week':
        startDate = new Date(now.setDate(now.getDate() - 7));
        previousStartDate = new Date(startDate.getTime() - 7 * 24 * 60 * 60 * 1000);
        break;
      case 'month':
        startDate = new Date(now.setMonth(now.getMonth() - 1));
        previousStartDate = new Date(startDate);
        previousStartDate.setMonth(previousStartDate.getMonth() - 1);
        break;
      case 'year':
        startDate = new Date(now.setFullYear(now.getFullYear() - 1));
        previousStartDate = new Date(startDate);
        previousStartDate.setFullYear(previousStartDate.getFullYear() - 1);
        break;
    }

    // Current period metrics
    const currentOrders = await prisma.booking.count({
      where: { createdAt: { gte: startDate } },
    });

    const completedOrders = await prisma.booking.count({
      where: {
        status: BookingStatus.COMPLETED,
        actualDeliveryTime: { gte: startDate },
      },
    });

    const revenue = await prisma.booking.aggregate({
      where: {
        status: BookingStatus.COMPLETED,
        actualDeliveryTime: { gte: startDate },
      },
      _sum: { totalGBP: true },
    });

    const activeDrivers = await prisma.driver.count({
      where: {
        status: 'active',
        DriverAvailability: {
          status: 'online',
        },
      },
    });

    const newCustomers = await prisma.user.count({
      where: {
        role: 'customer',
        createdAt: { gte: startDate },
      },
    });

    // Calculate completion rate
    const completionRate = currentOrders > 0 ? (completedOrders / currentOrders * 100) : 0;

    // Average order value
    const avgOrderValue = completedOrders > 0 ? (revenue._sum.totalGBP || 0) / completedOrders : 0;

    const kpis = {
      period: input.period,
      metrics: {
        totalOrders: currentOrders,
        completedOrders,
        completionRate: Math.round(completionRate * 100) / 100,
        revenue: revenue._sum.totalGBP || 0,
        avgOrderValue: Math.round(avgOrderValue * 100) / 100,
        activeDrivers,
        newCustomers,
      },
    };

    // Compare with previous period if requested
    if (input.compareWithPrevious && previousStartDate) {
      const prevOrders = await prisma.booking.count({
        where: {
          createdAt: {
            gte: previousStartDate,
            lt: startDate,
          },
        },
      });

      const prevRevenue = await prisma.booking.aggregate({
        where: {
          status: BookingStatus.COMPLETED,
          actualDeliveryTime: {
            gte: previousStartDate,
            lt: startDate,
          },
        },
        _sum: { totalGBP: true },
      });

      return {
        success: true,
        data: {
          ...kpis,
          comparison: {
            ordersGrowth: ((currentOrders - prevOrders) / prevOrders * 100) || 0,
            revenueGrowth: (((revenue._sum.totalGBP || 0) - (prevRevenue._sum.totalGBP || 0)) / (prevRevenue._sum.totalGBP || 1) * 100) || 0,
          },
        },
      };
    }

    return {
      success: true,
      data: kpis,
    };
  }
}

/**
 * Get order trends
 */
export class GetOrderTrendsTool extends BaseTool {
  name = 'get_order_trends';
  description = 'Analyze order trends over time with predictive insights';
  riskLevel = RiskLevel.LOW;
  inputSchema = z.object({
    days: z.number().min(7).max(365).default(30),
    groupBy: z.enum(['day', 'week', 'month']).default('day'),
  });

  protected async executeInternal(input: z.infer<typeof this.inputSchema>, context: ToolContext) {
    const endDate = new Date();
    const startDate = new Date();
    startDate.setDate(startDate.getDate() - input.days);

    const orders = await prisma.booking.findMany({
      where: {
        createdAt: {
          gte: startDate,
          lte: endDate,
        },
      },
      select: {
        createdAt: true,
        status: true,
        totalGBP: true,
      },
    });

    // Group orders by time period
    const grouped: Record<string, { count: number; revenue: number; completed: number }> = {};

    orders.forEach((order: typeof orders[0]) => {
      const date = new Date(order.createdAt);
      let key: string;

      if (input.groupBy === 'day') {
        key = date.toISOString().split('T')[0];
      } else if (input.groupBy === 'week') {
        const weekStart = new Date(date);
        weekStart.setDate(date.getDate() - date.getDay());
        key = weekStart.toISOString().split('T')[0];
      } else {
        key = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`;
      }

      if (!grouped[key]) {
        grouped[key] = { count: 0, revenue: 0, completed: 0 };
      }

      grouped[key].count++;
      grouped[key].revenue += order.totalGBP;
      if (order.status === BookingStatus.COMPLETED) {
        grouped[key].completed++;
      }
    });

    // Convert to array and sort
    const trend = Object.entries(grouped)
      .map(([date, data]) => ({
        date,
        ...data,
        completionRate: data.count > 0 ? (data.completed / data.count * 100) : 0,
      }))
      .sort((a, b) => a.date.localeCompare(b.date));

    // Simple prediction: average of last 7 data points
    const recentData = trend.slice(-7);
    const avgOrders = recentData.reduce((sum, d) => sum + d.count, 0) / recentData.length;
    const avgRevenue = recentData.reduce((sum, d) => sum + d.revenue, 0) / recentData.length;

    return {
      success: true,
      data: {
        trend,
        summary: {
          totalOrders: orders.length,
          totalRevenue: orders.reduce((sum: number, o: typeof orders[0]) => sum + o.totalGBP, 0),
          avgOrdersPerPeriod: Math.round(avgOrders),
          avgRevenuePerPeriod: Math.round(avgRevenue),
        },
        prediction: {
          nextPeriodOrders: Math.round(avgOrders),
          nextPeriodRevenue: Math.round(avgRevenue),
          confidence: 'medium',
        },
      },
    };
  }
}

/**
 * Get driver performance analytics
 */
export class GetDriverPerformanceAnalyticsTool extends BaseTool {
  name = 'get_driver_performance_analytics';
  description = 'Analyze driver performance metrics and rankings';
  riskLevel = RiskLevel.LOW;
  inputSchema = z.object({
    period: z.enum(['week', 'month', 'year']).default('month'),
    topN: z.number().min(1).max(50).optional().default(10),
  });

  protected async executeInternal(input: z.infer<typeof this.inputSchema>, context: ToolContext) {
    const now = new Date();
    let startDate: Date;

    switch (input.period) {
      case 'week':
        startDate = new Date(now.setDate(now.getDate() - 7));
        break;
      case 'month':
        startDate = new Date(now.setMonth(now.getMonth() - 1));
        break;
      case 'year':
        startDate = new Date(now.setFullYear(now.getFullYear() - 1));
        break;
    }

    const drivers = await prisma.driver.findMany({
      include: {
        User: true,
        DriverPerformance: true,
        Assignment: {
          where: {
            createdAt: { gte: startDate },
          },
          include: {
            Booking: true,
          },
        },
        DriverEarnings: {
          where: {
            createdAt: { gte: startDate },
          },
        },
      },
    });

    const driverMetrics = drivers.map((driver: typeof drivers[0]) => {
      const completedAssignments = driver.Assignment.filter(
        (a: typeof driver.Assignment[0]) => a.status === AssignmentStatus.completed
      );
      
      const totalEarnings = driver.DriverEarnings.reduce(
        (sum: number, e: typeof driver.DriverEarnings[0]) => sum + (e.netAmountPence ?? 0),
        0
      );

      return {
        id: driver.id,
        name: driver.User.name,
        completedOrders: completedAssignments.length,
        totalEarnings,
        rating: driver.DriverPerformance?.averageRating || 0,
        completionRate: driver.DriverPerformance?.completionRate || 0,
        onTimeRate: driver.DriverPerformance?.onTimeRate || 0,
        score: (completedAssignments.length * 10) + 
               (totalEarnings / 100) + 
               ((driver.DriverPerformance?.averageRating || 0) * 20),
      };
    });

    // Sort by score
    driverMetrics.sort((a: typeof driverMetrics[0], b: typeof driverMetrics[0]) => b.score - a.score);

    return {
      success: true,
      data: {
        topDrivers: driverMetrics.slice(0, input.topN),
        summary: {
          totalDrivers: drivers.length,
          avgCompletedOrders: driverMetrics.reduce((sum: number, d: typeof driverMetrics[0]) => sum + d.completedOrders, 0) / drivers.length || 0,
          avgRating: driverMetrics.reduce((sum: number, d: typeof driverMetrics[0]) => sum + d.rating, 0) / drivers.length || 0,
          totalEarnings: driverMetrics.reduce((sum: number, d: typeof driverMetrics[0]) => sum + d.totalEarnings, 0),
        },
      },
    };
  }
}

/**
 * Get customer behavior analytics
 */
export class GetCustomerBehaviorAnalyticsTool extends BaseTool {
  name = 'get_customer_behavior_analytics';
  description = 'Analyze customer ordering patterns and behavior';
  riskLevel = RiskLevel.LOW;
  inputSchema = z.object({
    segment: z.enum(['all', 'new', 'returning', 'vip']).optional().default('all'),
  });

  protected async executeInternal(input: z.infer<typeof this.inputSchema>, context: ToolContext) {
    const thirtyDaysAgo = new Date();
    thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);

    let whereClause: any = { role: 'customer' };

    if (input.segment === 'new') {
      whereClause.createdAt = { gte: thirtyDaysAgo };
    }

    const customers = await prisma.user.findMany({
      where: whereClause,
      include: {
        Booking: {
          include: {
            Payment: true,
          },
        },
      },
    });

    const customerMetrics = customers.map((customer: typeof customers[0]) => {
      const totalOrders = customer.Booking.length;
      const completedOrders = customer.Booking.filter(
        (b: typeof customer.Booking[0]) => b.status === BookingStatus.COMPLETED
      ).length;
      
      const totalSpent = customer.Booking.reduce(
        (sum: number, b: typeof customer.Booking[0]) => sum + b.totalGBP,
        0
      );

      const avgOrderValue = totalOrders > 0 ? totalSpent / totalOrders : 0;

      let segment = 'regular';
      if (totalOrders === 0) segment = 'inactive';
      else if (totalOrders === 1) segment = 'new';
      else if (totalSpent > 1000) segment = 'vip';
      else if (totalOrders > 5) segment = 'returning';

      return {
        id: customer.id,
        name: customer.name,
        email: customer.email,
        totalOrders,
        completedOrders,
        totalSpent,
        avgOrderValue,
        segment,
        joinedAt: customer.createdAt,
      };
    });

    // Segment distribution
    const segmentCounts = customerMetrics.reduce((acc: Record<string, number>, c: typeof customerMetrics[0]) => {
      acc[c.segment] = (acc[c.segment] || 0) + 1;
      return acc;
    }, {});

    return {
      success: true,
      data: {
        customers: customerMetrics.slice(0, 100),
        summary: {
          totalCustomers: customers.length,
          avgOrdersPerCustomer: customerMetrics.reduce((sum: number, c: typeof customerMetrics[0]) => sum + c.totalOrders, 0) / customers.length || 0,
          avgLifetimeValue: customerMetrics.reduce((sum: number, c: typeof customerMetrics[0]) => sum + c.totalSpent, 0) / customers.length || 0,
          segmentDistribution: segmentCounts,
        },
      },
    };
  }
}

/**
 * Get operational efficiency metrics
 */
export class GetOperationalEfficiencyTool extends BaseTool {
  name = 'get_operational_efficiency';
  description = 'Analyze operational efficiency metrics and bottlenecks';
  riskLevel = RiskLevel.LOW;
  inputSchema = z.object({
    period: z.enum(['week', 'month']).default('month'),
  });

  protected async executeInternal(input: z.infer<typeof this.inputSchema>, context: ToolContext) {
    const now = new Date();
    const startDate = input.period === 'week'
      ? new Date(now.setDate(now.getDate() - 7))
      : new Date(now.setMonth(now.getMonth() - 1));

    // Get orders with timing data
    const orders = await prisma.booking.findMany({
      where: {
        createdAt: { gte: startDate },
        status: BookingStatus.COMPLETED,
      },
      include: {
        Assignment: true,
      },
    });

    // Calculate average times
    const avgAssignmentTime = orders
      .filter((o: typeof orders[0]) => o.Assignment && o.Assignment[0])
      .map((o: typeof orders[0]) => {
        const assignment = o.Assignment[0];
        return new Date(assignment.createdAt).getTime() - new Date(o.createdAt).getTime();
      })
      .reduce((sum: number, time: number, _: number, arr: number[]) => sum + time / arr.length, 0);

    // Orders by status
    const statusCounts = await prisma.booking.groupBy({
      by: ['status'],
      where: {
        createdAt: { gte: startDate },
      },
      _count: true,
    });

    // Cancellation rate
    const totalOrders = await prisma.booking.count({
      where: { createdAt: { gte: startDate } },
    });

    const cancelledOrders = await prisma.booking.count({
      where: {
        createdAt: { gte: startDate },
        status: BookingStatus.CANCELLED,
      },
    });

    const cancellationRate = totalOrders > 0 ? (cancelledOrders / totalOrders * 100) : 0;

    return {
      success: true,
      data: {
        period: input.period,
        metrics: {
          avgAssignmentTimeMinutes: Math.round(avgAssignmentTime / 1000 / 60),
          cancellationRate: Math.round(cancellationRate * 100) / 100,
          totalOrders,
          completedOrders: orders.length,
          statusBreakdown: statusCounts,
        },
        insights: [
          avgAssignmentTime > 15 * 60 * 1000 ? 'Assignment time is above optimal (>15 min)' : 'Assignment time is good',
          cancellationRate > 10 ? 'High cancellation rate detected' : 'Cancellation rate is healthy',
        ],
      },
    };
  }
}

