import { z } from 'zod';
import { createAuditLogEntry } from '@/lib/audit';

export enum RiskLevel {
  LOW = 'LOW',      // Auto execute
  MEDIUM = 'MEDIUM', // Single confirmation
  HIGH = 'HIGH'      // Dual confirmation + OTP
}

export interface ToolContext {
  userId: string;
  userRole: string;
  adminRole?: string;
  sessionId: string;
  timestamp: Date;
}

export interface ToolResult<T = any> {
  success: boolean;
  data?: T;
  error?: string;
  requiresConfirmation?: boolean;
  confirmationType?: 'single' | 'dual';
  auditId?: string;
  message?: string;
}

export interface ToolExecutionLog {
  id: string;
  toolName: string;
  action: string;
  context: ToolContext;
  input: any;
  output: any;
  riskLevel: RiskLevel;
  confirmed: boolean;
  confirmationType?: string;
  reason?: string;
  executedAt: Date;
  duration: number;
  status: 'success' | 'error' | 'pending_confirmation';
}

/**
 * Base class for all AI tools with enterprise-grade security
 */
export abstract class BaseTool<TInput = any, TOutput = any> {
  abstract name: string;
  abstract description: string;
  abstract riskLevel: RiskLevel;
  abstract inputSchema: z.ZodType<TInput>;

  /**
   * Validate input against schema
   */
  protected validateInput(input: unknown): TInput {
    try {
      return this.inputSchema.parse(input);
    } catch (error) {
      if (error instanceof z.ZodError) {
        throw new Error(`Input validation failed: ${error.errors.map(e => e.message).join(', ')}`);
      }
      throw error;
    }
  }

  /**
   * Check authorization for this tool
   */
  protected async checkAuthorization(context: ToolContext): Promise<void> {
    if (context.userRole !== 'admin') {
      throw new Error('Unauthorized: Admin access required');
    }

    // High risk tools require superadmin
    if (this.riskLevel === RiskLevel.HIGH && context.adminRole !== 'superadmin') {
      throw new Error('Unauthorized: Superadmin access required for high-risk operations');
    }
  }

  /**
   * Log tool execution to audit trail
   */
  protected async logExecution(
    context: ToolContext,
    input: TInput,
    output: ToolResult<TOutput>,
    duration: number
  ): Promise<string> {
    const log = await createAuditLogEntry({
      actorId: context.userId,
      actorRole: context.userRole,
      action: `AI_TOOL_${this.name.toUpperCase()}`,
      targetType: 'ai_tool',
      targetId: output.auditId ?? context.sessionId,
      details: {
        toolName: this.name,
        riskLevel: this.riskLevel,
        input,
        output: output.data,
        duration,
        sessionId: context.sessionId,
        confirmed: !output.requiresConfirmation,
        confirmationType: output.confirmationType,
      },
    });

    return log.id;
  }

  /**
   * Execute the tool with full safety checks
   */
  async execute(input: unknown, context: ToolContext): Promise<ToolResult<TOutput>> {
    const startTime = Date.now();

    try {
      // 1. Validate input
      const validatedInput = this.validateInput(input);

      // 2. Check authorization
      await this.checkAuthorization(context);

      // 3. Check if confirmation required
      if (this.riskLevel === RiskLevel.HIGH) {
        return {
          success: false,
          requiresConfirmation: true,
          confirmationType: 'dual',
          message: 'This is a high-risk operation and requires dual confirmation with OTP',
        };
      }

      if (this.riskLevel === RiskLevel.MEDIUM) {
        return {
          success: false,
          requiresConfirmation: true,
          confirmationType: 'single',
          message: 'This operation requires confirmation to proceed',
        };
      }

      // 4. Execute the actual tool logic
      const result = await this.executeInternal(validatedInput, context);

      // 5. Log execution
      const duration = Date.now() - startTime;
      const auditId = await this.logExecution(context, validatedInput, result, duration);

      return {
        ...result,
        auditId,
      };

    } catch (error) {
      const duration = Date.now() - startTime;
      
      // Log error
      await createAuditLogEntry({
        actorId: context.userId,
        actorRole: context.userRole,
        action: `AI_TOOL_${this.name.toUpperCase()}_ERROR`,
        targetType: 'ai_tool',
        targetId: context.sessionId,
        details: {
          toolName: this.name,
          error: error instanceof Error ? error.message : String(error),
          duration,
        },
      });

      return {
        success: false,
        error: error instanceof Error ? error.message : 'Unknown error occurred',
      };
    }
  }

  /**
   * Internal execution logic - to be implemented by each tool
   */
  protected abstract executeInternal(
    input: TInput,
    context: ToolContext
  ): Promise<ToolResult<TOutput>>;

  /**
   * Execute with confirmation (after user confirmed)
   */
  async executeWithConfirmation(
    input: unknown,
    context: ToolContext,
    confirmationToken: string,
    reason?: string
  ): Promise<ToolResult<TOutput>> {
    const startTime = Date.now();

    try {
      const validatedInput = this.validateInput(input);
      await this.checkAuthorization(context);

      // Verify confirmation token
      if (this.riskLevel === RiskLevel.HIGH) {
        // TODO: Verify OTP token
        // await verifyOTP(context.userId, confirmationToken);
      }

      // Execute
      const result = await this.executeInternal(validatedInput, context);

      // Log with confirmation details
      const duration = Date.now() - startTime;
      const auditEntry = await createAuditLogEntry({
        actorId: context.userId,
        actorRole: context.userRole,
        action: `AI_TOOL_${this.name.toUpperCase()}_CONFIRMED`,
        targetType: 'ai_tool',
        targetId: result.auditId ?? context.sessionId,
        details: {
          toolName: this.name,
          riskLevel: this.riskLevel,
          input: validatedInput,
          output: result.data,
          duration,
          confirmed: true,
          confirmationToken,
          reason,
        },
      });

      return {
        ...result,
        auditId: auditEntry.id,
      };

    } catch (error) {
      return {
        success: false,
        error: error instanceof Error ? error.message : 'Unknown error occurred',
      };
    }
  }
}

import { z } from 'zod';
import { prisma } from '@/lib/prisma';
import { AssignmentStatus } from '@prisma/client';
import { BaseTool, RiskLevel, ToolContext } from './base/ToolExecutor';

/**
 * Get available drivers
 */
export class GetAvailableDriversTool extends BaseTool {
  name = 'get_available_drivers';
  description = 'Get all drivers who are currently available for assignments';
  riskLevel = RiskLevel.LOW;
  inputSchema = z.object({
    location: z.object({
      lat: z.number(),
      lng: z.number(),
    }).optional(),
    radius: z.number().optional().default(50), // km
  });

  protected async executeInternal(input: z.infer<typeof this.inputSchema>, context: ToolContext) {
    const drivers = await prisma.driver.findMany({
      where: {
        status: 'active',
        DriverAvailability: {
          is: {
            status: 'online',
          },
        },
      },
      include: {
        User: true,
        DriverPerformance: true,
        DriverAvailability: true,
        DriverVehicle: true,
        Assignment: {
          where: {
            status: {
              in: [AssignmentStatus.claimed, AssignmentStatus.accepted],
            },
          },
          include: {
            Booking: true,
          },
        },
      },
    });

    return {
      success: true,
      data: {
        drivers: drivers.map((driver: typeof drivers[0]) => ({
          id: driver.id,
          name: driver.User.name,
          phone: driver.User.phone,
          rating: driver.DriverPerformance?.averageRating || 0,
          completionRate: driver.DriverPerformance?.completionRate || 0,
          currentAssignments: driver.Assignment.length,
          vehicle: driver.DriverVehicle && driver.DriverVehicle.length > 0 ? {
            type: driver.vehicleType || null,
            plate: driver.DriverVehicle[0].reg || null,
          } : null,
          isAvailable: driver.DriverAvailability?.status === 'online',
        })),
        count: drivers.length,
        message: `Found ${drivers.length} available drivers`,
      },
    };
  }
}

/**
 * Get driver details
 */
export class GetDriverDetailsTool extends BaseTool {
  name = 'get_driver_details';
  description = 'Get comprehensive details about a specific driver';
  riskLevel = RiskLevel.LOW;
  inputSchema = z.object({
    driverId: z.string(),
  });

  protected async executeInternal(input: z.infer<typeof this.inputSchema>, context: ToolContext) {
    const driver = await prisma.driver.findUnique({
      where: { id: input.driverId },
      include: {
        User: true,
        DriverPerformance: true,
        DriverAvailability: true,
        DriverVehicle: true,
        Assignment: {
          include: {
            Booking: {
              include: {
                pickupAddress: true,
                dropoffAddress: true,
              },
            },
          },
          orderBy: {
            createdAt: 'desc',
          },
          take: 10,
        },
        DriverEarnings: {
          orderBy: {
            createdAt: 'desc',
          },
          take: 5,
        },
      },
    });

    if (!driver) {
      return {
        success: false,
        error: 'Driver not found',
      };
    }

    const totalEarnings = await prisma.driverEarnings.aggregate({
      where: { driverId: input.driverId },
      _sum: {
        netAmountPence: true,
      },
    });

    const completedOrders = await prisma.assignment.count({
      where: {
        driverId: input.driverId,
        status: AssignmentStatus.completed,
      },
    });

    return {
      success: true,
      data: {
        driver,
        stats: {
          totalEarnings: totalEarnings._sum.netAmountPence || 0,
          completedOrders,
          rating: driver.DriverPerformance?.averageRating || 0,
          completionRate: driver.DriverPerformance?.completionRate || 0,
          onTimeRate: driver.DriverPerformance?.onTimeRate || 0,
        },
        recentAssignments: driver.Assignment,
        recentEarnings: driver.DriverEarnings,
      },
    };
  }
}

/**
 * Update driver status
 */
export class UpdateDriverStatusTool extends BaseTool {
  name = 'update_driver_status';
  description = 'Update a driver\'s status (active, inactive, suspended)';
  riskLevel = RiskLevel.MEDIUM;
  inputSchema = z.object({
    driverId: z.string(),
    status: z.enum(['active', 'inactive', 'suspended']),
    reason: z.string(),
  });

  protected async executeInternal(input: z.infer<typeof this.inputSchema>, context: ToolContext) {
    const driver = await prisma.driver.findUnique({
      where: { id: input.driverId },
      include: {
        User: true,
        Assignment: {
          where: {
            status: {
              in: [AssignmentStatus.claimed, AssignmentStatus.accepted],
            },
          },
        },
      },
    });

    if (!driver) {
      return {
        success: false,
        error: 'Driver not found',
      };
    }

    // Check for active assignments
    if (driver.Assignment.length > 0 && input.status !== 'active') {
      return {
        success: false,
        error: `Driver has ${driver.Assignment.length} active assignments. Cannot change status.`,
      };
    }

    const updated = await prisma.driver.update({
      where: { id: input.driverId },
      data: {
        status: input.status,
      },
    });

    // Log status change
    await prisma.auditLog.create({
      data: {
        actorId: context.userId,
        actorRole: context.userRole,
        action: 'driver_status_change',
        targetType: 'driver',
        targetId: input.driverId,
        before: { status: driver.status },
        after: { status: input.status },
        details: {
          reason: input.reason,
        },
      },
    });

    return {
      success: true,
      data: {
        driver: updated,
        message: `Driver ${driver.User.name} status changed from ${driver.status} to ${input.status}`,
      },
      auditId: updated.id,
    };
  }
}

/**
 * Update driver availability
 */
export class UpdateDriverAvailabilityTool extends BaseTool {
  name = 'update_driver_availability';
  description = 'Toggle driver availability for accepting new assignments';
  riskLevel = RiskLevel.LOW;
  inputSchema = z.object({
    driverId: z.string(),
    isAvailable: z.boolean(),
  });

  protected async executeInternal(input: z.infer<typeof this.inputSchema>, context: ToolContext) {
    const driver = await prisma.driver.findUnique({
      where: { id: input.driverId },
      include: { User: true },
    });

    if (!driver) {
      return {
        success: false,
        error: 'Driver not found',
      };
    }

    const availability = await prisma.driverAvailability.upsert({
      where: { driverId: input.driverId },
      update: {
        status: input.isAvailable ? 'online' : 'offline',
        lastSeenAt: new Date(),
      },
      create: {
        driverId: input.driverId,
        status: input.isAvailable ? 'online' : 'offline',
      },
    });

    return {
      success: true,
      data: {
        availability,
        message: `${driver.User.name} is now ${input.isAvailable ? 'available' : 'unavailable'}`,
      },
    };
  }
}

/**
 * Get driver earnings summary
 */
export class GetDriverEarningsTool extends BaseTool {
  name = 'get_driver_earnings';
  description = 'Get earnings summary for a driver over a time period';
  riskLevel = RiskLevel.LOW;
  inputSchema = z.object({
    driverId: z.string(),
    startDate: z.string().datetime().optional(),
    endDate: z.string().datetime().optional(),
  });

  protected async executeInternal(input: z.infer<typeof this.inputSchema>, context: ToolContext) {
    const whereClause: any = {
      driverId: input.driverId,
    };

    if (input.startDate || input.endDate) {
      whereClause.createdAt = {};
      if (input.startDate) whereClause.createdAt.gte = new Date(input.startDate);
      if (input.endDate) whereClause.createdAt.lte = new Date(input.endDate);
    }

    const earnings = await prisma.driverEarnings.findMany({
      where: whereClause,
      include: {
        Assignment: {
          include: {
            Booking: {
              include: {
                pickupAddress: true,
                dropoffAddress: true,
              },
            },
          },
        },
      },
      orderBy: {
        createdAt: 'desc',
      },
    });

    const summary = await prisma.driverEarnings.aggregate({
      where: whereClause,
      _sum: {
        netAmountPence: true,
        baseAmountPence: true,
        tipAmountPence: true,
        grossEarningsPence: true,
      },
      _count: true,
    });

    return {
      success: true,
      data: {
        earnings,
        summary: {
          totalEarnings: summary._sum.netAmountPence || 0,
          baseFare: summary._sum.baseAmountPence || 0,
          tips: summary._sum.tipAmountPence || 0,
          grossEarnings: summary._sum.grossEarningsPence || 0,
          completedOrders: summary._count,
        },
        message: `Total earnings: ${summary._sum.netAmountPence || 0} from ${summary._count} orders`,
      },
    };
  }
}

// Export all driver tools
export const driverTools = [
  new GetAvailableDriversTool(),
