  new UpdateDriverStatusTool(),
  new UpdateDriverAvailabilityTool(),
  new GetDriverEarningsTool(),
];

import { z } from 'zod';
import { BookingStatus, PaymentStatus, RefundStatus, Prisma } from '@prisma/client';
import { prisma } from '@/lib/prisma';
import { BaseTool, RiskLevel, ToolContext } from './base/ToolExecutor';

/**
 * Generate revenue report
 */
export class GenerateRevenueReportTool extends BaseTool {
  name = 'generate_revenue_report';
  description = 'Generate comprehensive revenue report for a time period';
  riskLevel = RiskLevel.LOW;
  inputSchema = z.object({
    startDate: z.string().datetime(),
    endDate: z.string().datetime(),
    groupBy: z.enum(['day', 'week', 'month']).optional().default('day'),
  });

  protected async executeInternal(input: z.infer<typeof this.inputSchema>, context: ToolContext) {
    const startDate = new Date(input.startDate);
    const endDate = new Date(input.endDate);

    // Get completed bookings in date range
    const bookings = await prisma.booking.findMany({
      where: {
        status: BookingStatus.COMPLETED,
        OR: [
          {
            actualDeliveryTime: {
              gte: startDate,
              lte: endDate,
            },
          },
          {
            actualDeliveryTime: null,
            updatedAt: {
              gte: startDate,
              lte: endDate,
            },
          },
        ],
      },
      include: {
        Payment: true,
      },
    });

    // Calculate revenue metrics
    const totalRevenue = bookings.reduce((sum: number, b: typeof bookings[0]) => 
      sum + b.totalGBP, 0
    );
    
    const paidRevenue = bookings.reduce((sum: number, b: typeof bookings[0]) => {
      const paid = b.Payment?.find((p: typeof b.Payment[0]) => p.status === PaymentStatus.paid);
      return sum + (paid?.amount || 0);
    }, 0);

    const unpaidRevenue = totalRevenue - paidRevenue;

    // Get payment method breakdown
    const paymentMethods = bookings.reduce((acc: Record<string, number>, b: typeof bookings[0]) => {
      const method = b.Payment?.find((p: typeof b.Payment[0]) => p.status === PaymentStatus.paid)?.provider || 'unpaid';
      acc[method] = (acc[method] || 0) + b.totalGBP;
      return acc;
    }, {});

    return {
      success: true,
      data: {
        period: {
          start: startDate,
          end: endDate,
        },
        metrics: {
          totalOrders: bookings.length,
          totalRevenue,
          paidRevenue,
          unpaidRevenue,
          averageOrderValue: totalRevenue / bookings.length || 0,
        },
        paymentMethodBreakdown: paymentMethods,
        bookings: bookings.slice(0, 100), // Limit for performance
      },
    };
  }
}

/**
 * Process refund
 */
export class ProcessRefundTool extends BaseTool {
  name = 'process_refund';
  description = 'Process a refund for a completed order (HIGH RISK)';
  riskLevel = RiskLevel.HIGH;
  inputSchema = z.object({
    orderId: z.string(),
    amount: z.number().positive(),
    reason: z.string().min(10),
  });

  protected async executeInternal(input: z.infer<typeof this.inputSchema>, context: ToolContext) {
    const order = await prisma.booking.findUnique({
      where: { id: input.orderId },
      include: {
        Payment: true,
      },
    });

    if (!order) {
      return {
        success: false,
        error: 'Order not found',
      };
    }

    const successfulPayment = order.Payment?.find((p: typeof order.Payment[0]) => 
      p.status === PaymentStatus.paid
    );

    if (!successfulPayment) {
      return {
        success: false,
        error: 'No successful payment found for this order',
      };
    }

    if (input.amount > successfulPayment.amount) {
      return {
        success: false,
        error: `Refund amount (${input.amount}) exceeds payment amount (${successfulPayment.amount})`,
      };
    }

    // Create refund record
    const refund = await prisma.refund.create({
      data: {
        paymentId: successfulPayment.id,
        amount: input.amount,
        reason: input.reason,
        status: RefundStatus.pending,
        metadata: {
          originalPaymentId: successfulPayment.id,
          processedBy: context.userId,
        },
      },
    });

    return {
      success: true,
      data: {
        refund,
        order,
        message: `Refund of ${input.amount} ${successfulPayment.currency} initiated for order ${order.reference}`,
      },
      auditId: refund.id,
    };
  }
}

/**
 * Get financial summary
 */
export class GetFinancialSummaryTool extends BaseTool {
  name = 'get_financial_summary';
  description = 'Get high-level financial summary with key metrics';
  riskLevel = RiskLevel.LOW;
  inputSchema = z.object({
    period: z.enum(['today', 'week', 'month', 'year']).default('month'),
  });

  protected async executeInternal(input: z.infer<typeof this.inputSchema>, context: ToolContext) {
    const now = new Date();
    let startDate: Date;

    switch (input.period) {
      case 'today':
        startDate = new Date(now.setHours(0, 0, 0, 0));
        break;
      case 'week':
        startDate = new Date(now.setDate(now.getDate() - 7));
        break;
      case 'month':
        startDate = new Date(now.setMonth(now.getMonth() - 1));
        break;
      case 'year':
        startDate = new Date(now.setFullYear(now.getFullYear() - 1));
        break;
    }

    const bookingWhere: Prisma.BookingWhereInput = {
      status: BookingStatus.COMPLETED,
      OR: [
        {
          actualDeliveryTime: {
            gte: startDate,
          },
        },
        {
          actualDeliveryTime: null,
          updatedAt: {
            gte: startDate,
          },
        },
      ],
    };

    const [revenueSum, completedOrders] = await Promise.all([
      prisma.booking.aggregate({
        where: bookingWhere,
        _sum: {
          totalGBP: true,
        },
      }),
      prisma.booking.count({ where: bookingWhere }),
    ]);

    // Driver earnings
    const driverEarnings = await prisma.driverEarnings.aggregate({
      where: {
        createdAt: {
          gte: startDate,
        },
      },
      _sum: {
        netAmountPence: true,
      },
    });

    // Refunds
    const refunds = await prisma.refund.aggregate({
      where: {
        createdAt: {
          gte: startDate,
        },
        status: RefundStatus.completed,
      },
      _sum: {
        amount: true,
      },
    });

    const grossRevenue = revenueSum._sum.totalGBP || 0;
    const driverPayout = driverEarnings._sum.netAmountPence || 0;
    const refundAmount = refunds._sum.amount || 0;
    const netRevenue = grossRevenue - driverPayout - refundAmount;
    const averageOrderValue = completedOrders > 0 ? grossRevenue / completedOrders : 0;
    const profitMargin = grossRevenue > 0 ? (netRevenue / grossRevenue) * 100 : 0;

    return {
      success: true,
      data: {
        period: input.period,
        metrics: {
          grossRevenue,
          driverPayout,
          refunds: refundAmount,
          netRevenue,
          completedOrders,
          averageOrderValue,
          profitMargin,
        },
        summary: `${input.period}: ${completedOrders} orders, ${grossRevenue} gross revenue, ${netRevenue} net profit`,
      },
    };
  }
}

/**
 * Generate invoice
 */
export class GenerateInvoiceTool extends BaseTool {
  name = 'generate_invoice';
  description = 'Generate an invoice for a completed order';
  riskLevel = RiskLevel.LOW;
  inputSchema = z.object({
    orderId: z.string(),
  });

  protected async executeInternal(input: z.infer<typeof this.inputSchema>, context: ToolContext) {
    const order = await prisma.booking.findUnique({
      where: { id: input.orderId },
      include: {
        pickupAddress: true,
        dropoffAddress: true,
        BookingItem: true,
        Payment: true,
      },
    });

    if (!order) {
      return {
        success: false,
        error: 'Order not found',
      };
    }

    if (order.status !== BookingStatus.COMPLETED) {
      return {
        success: false,
        error: 'Can only generate invoices for completed orders',
      };
    }

    const successfulPayment = order.Payment?.find((p: typeof order.Payment[0]) => 
      p.status === PaymentStatus.paid
    );

    const invoiceData = {
      invoiceNumber: `INV-${order.reference}`,
      orderId: order.id,
      orderReference: order.reference,
      customer: {
        name: order.customerName,
        email: order.customerEmail,
        phone: order.customerPhone,
      },
      lineItems: [
        {
          description: `Delivery from ${order.pickupAddress?.label ?? order.pickupAddress?.postcode} to ${order.dropoffAddress?.label ?? order.dropoffAddress?.postcode}`,
          quantity: 1,
          unitPrice: order.totalGBP,
          total: order.totalGBP,
        },
      ],
      items: order.BookingItem,
      subtotal: order.totalGBP,
      tax: 0,
      total: order.totalGBP,
      paymentStatus: successfulPayment ? 'paid' : 'unpaid',
      paymentMethod: successfulPayment?.provider ?? null,
      issuedAt: new Date(),
    };

    return {
      success: true,
      data: {
        invoice: invoiceData,
        message: `Invoice ${invoiceData.invoiceNumber} generated for order ${order.reference}`,
      },
    };
  }
}

/**
 * Get outstanding payments
 */
export class GetOutstandingPaymentsTool extends BaseTool {
  name = 'get_outstanding_payments';
  description = 'Get list of orders with outstanding/unpaid amounts';
  riskLevel = RiskLevel.LOW;
  inputSchema = z.object({
    limit: z.number().optional().default(50),
  });

  protected async executeInternal(input: z.infer<typeof this.inputSchema>, context: ToolContext) {
    const candidates = await prisma.booking.findMany({
      where: {
        status: {
          in: [BookingStatus.CONFIRMED, BookingStatus.COMPLETED],
        },
      },
      orderBy: {
        createdAt: 'desc',
      },
      take: input.limit * 3,
    });

    const enriched = candidates
      .map(order => {
        const paid = order.amountPaidGBP ?? 0;
        const outstandingAmount = Math.max(order.totalGBP - paid, 0);
        return {
          order,
          outstandingAmount,
        };
      })
      .filter(entry => entry.outstandingAmount > 0)
      .slice(0, input.limit);

    const totalOutstanding = enriched.reduce((sum, entry) => sum + entry.outstandingAmount, 0);

    return {
      success: true,
      data: {
        orders: enriched.map(({ order, outstandingAmount }) => ({
          id: order.id,
          reference: order.reference,
          customer: order.customerName,
          amount: outstandingAmount,
          status: order.status,
          createdAt: order.createdAt,
        })),
        summary: {
          totalOrders: enriched.length,
          totalOutstanding,
          averageAmount: enriched.length > 0 ? totalOutstanding / enriched.length : 0,
        },
      },
    };
  }
}

// Export all finance tools
export const financeTools = [
  new GenerateRevenueReportTool(),
  new ProcessRefundTool(),
  new GetFinancialSummaryTool(),
  new GenerateInvoiceTool(),
  new GetOutstandingPaymentsTool(),
];

import { z } from 'zod';
import { AssignmentStatus, BookingStatus, PaymentStatus, Prisma } from '@prisma/client';
import { prisma } from '@/lib/prisma';
import { BaseTool, RiskLevel, ToolContext } from './base/ToolExecutor';

/**
 * Get unassigned orders
 */
export class GetUnassignedOrdersTool extends BaseTool {
  name = 'get_unassigned_orders';
  description = 'Fetch all orders that have not been assigned to a driver yet';
  riskLevel = RiskLevel.LOW;
  inputSchema = z.object({
    limit: z.number().optional().default(50),
    sortBy: z.enum(['createdAt', 'scheduledAt', 'priority']).optional().default('scheduledAt'),
  });

  protected async executeInternal(input: z.infer<typeof this.inputSchema>, context: ToolContext) {
    const sortField = input.sortBy === 'priority' ? 'priority' : input.sortBy;
    const orderBy: Prisma.BookingOrderByWithRelationInput = {
      [sortField]: 'asc',
    };

    const orders = await prisma.booking.findMany({
      where: {
        status: {
          in: [BookingStatus.CONFIRMED, BookingStatus.PENDING_PAYMENT],
        },
        driverId: null,
      },
      include: {
        pickupAddress: true,
        dropoffAddress: true,
        BookingItem: true,
      },
      orderBy,
      take: input.limit,
    });

    const normalizedOrders = orders.map(order => {
      const { BookingItem, ...rest } = order;
      return {
        ...rest,
        items: BookingItem,
      };
    });

    return {
      success: true,
      data: {
        orders: normalizedOrders,
        count: normalizedOrders.length,
        message: `Found ${normalizedOrders.length} unassigned orders`,
      },
    };
  }
}

/**
 * Assign driver to order
 */
export class AssignDriverToOrderTool extends BaseTool {
  name = 'assign_driver_to_order';
  description = 'Assign a specific driver to an order';
  riskLevel = RiskLevel.MEDIUM;
  inputSchema = z.object({
    orderId: z.string(),
    driverId: z.string(),
    reason: z.string().optional(),
  });

  protected async executeInternal(input: z.infer<typeof this.inputSchema>, context: ToolContext) {
    // Validate order exists and is assignable
    const order = await prisma.booking.findUnique({
      where: { id: input.orderId },
    });

    if (!order) {
      return {
        success: false,
        error: 'Order not found',
      };
    }

    if (order.status === BookingStatus.COMPLETED || order.status === BookingStatus.CANCELLED) {
      return {
        success: false,
        error: `Cannot assign driver to ${order.status} order`,
      };
    }

    if (order.driverId) {
      return {
        success: false,
        error: 'Order already has a driver assigned',
      };
    }

    // Validate driver exists and is available
    const driver = await prisma.driver.findUnique({
      where: { id: input.driverId },
      include: { User: true },
    });

    if (!driver) {
      return {
        success: false,
        error: 'Driver not found',
      };
    }

    if (driver.status !== 'active') {
      return {
        success: false,
        error: `Driver is ${driver.status} and cannot accept orders`,
      };
    }

    // Create assignment
    const assignment = await prisma.assignment.create({
      data: {
        bookingId: input.orderId,
        driverId: input.driverId,
        // When AI assigns a driver we treat it as an accepted assignment
        status: AssignmentStatus.accepted,
      },
    });

    // Update order
    await prisma.booking.update({
      where: { id: input.orderId },
      data: {
        driverId: input.driverId,
        status: BookingStatus.CONFIRMED,
      },
    });

    return {
      success: true,
      data: {
        assignment,
        order: await prisma.booking.findUnique({
          where: { id: input.orderId },
          include: { driver: { include: { User: true } } },
        }),
        message: `Successfully assigned ${driver.User.name} to order ${order.reference}`,
      },
      auditId: assignment.id,
    };
  }
}

/**
 * Find best driver for order
 */
export class FindBestDriverForOrderTool extends BaseTool {
  name = 'find_best_driver';
  description = 'Find the most suitable driver for an order based on location, availability, and performance';
  riskLevel = RiskLevel.LOW;
  inputSchema = z.object({
    orderId: z.string(),
  });

  protected async executeInternal(input: z.infer<typeof this.inputSchema>, context: ToolContext) {
    const order = await prisma.booking.findUnique({
      where: { id: input.orderId },
      include: {
        pickupAddress: true,
        BookingItem: true,
      },
    });

    if (!order) {
      return {
        success: false,
        error: 'Order not found',
      };
    }

    // Get available drivers
    const drivers = await prisma.driver.findMany({
      where: {
        status: 'active',
      },
      include: {
        User: true,
        DriverPerformance: true,
        DriverAvailability: true,
        Assignment: {
          where: {
            status: {
              in: [AssignmentStatus.accepted, AssignmentStatus.claimed],
            },
          },
        },
      },
    });

    // Score drivers based on multiple factors
    const scoredDrivers = drivers.map((driver: typeof drivers[0]) => {
      let score = 100;

      // Penalize for current workload
      score -= driver.Assignment.length * 10;

      // Bonus for good performance
      if (driver.DriverPerformance) {
        score += (driver.DriverPerformance.averageRating || 0) * 10;
        score += (driver.DriverPerformance.completionRate || 0) * 5;
      }

      // Check availability
      const isAvailable = driver.DriverAvailability?.status === 'online';
      if (!isAvailable) {
        score -= 50;
      }

      return {
        driver,
        score,
        currentAssignments: driver.Assignment.length,
        rating: driver.DriverPerformance?.averageRating || 0,
      };
    });

    // Sort by score
    scoredDrivers.sort((a: typeof scoredDrivers[0], b: typeof scoredDrivers[0]) => b.score - a.score);

    const bestDriver = scoredDrivers[0];

    if (!bestDriver) {
      return {
        success: false,
        error: 'No available drivers found',
      };
    }

    return {
      success: true,
      data: {
        recommendedDriver: bestDriver.driver,
        score: bestDriver.score,
        reason: `Best match based on: ${bestDriver.currentAssignments} current assignments, ${bestDriver.rating.toFixed(1)} rating`,
        alternatives: scoredDrivers.slice(1, 4).map((d: typeof scoredDrivers[0]) => ({
          driver: d.driver,
          score: d.score,
        })),
      },
    };
  }
}

/**
 * Cancel order
 */
export class CancelOrderTool extends BaseTool {
  name = 'cancel_order';
  description = 'Cancel an order (HIGH RISK - requires confirmation)';
  riskLevel = RiskLevel.HIGH;
  inputSchema = z.object({
    orderId: z.string(),
    reason: z.string(),
    refundAmount: z.number().optional(),
  });

  protected async executeInternal(input: z.infer<typeof this.inputSchema>, context: ToolContext) {
    const order = await prisma.booking.findUnique({
      where: { id: input.orderId },
      include: { Payment: true },
    });

    if (!order) {
      return {
        success: false,
        error: 'Order not found',
      };
    }

    if (order.status === BookingStatus.CANCELLED) {
      return {
        success: false,
        error: 'Order is already cancelled',
      };
    }

    if (order.status === BookingStatus.COMPLETED) {
      return {
        success: false,
        error: 'Cannot cancel completed order',
      };
    }

    // Check if refund is needed
    const paidAmount =
      order.Payment?.find((p: typeof order.Payment[0]) => p.status === PaymentStatus.paid)?.amount ?? 0;
    const requiresRefund = paidAmount > 0;

    return {
      success: true,
      data: {
        order,
        requiresRefund,
        paidAmount,
        message: requiresRefund 
          ? 'Order cancellation will trigger refund workflow. Please confirm.'
          : 'Order will be cancelled without refund.',
      },
      requiresConfirmation: true,
      confirmationType: 'dual' as const,
    };
  }
}

/**
 * Get order details
 */
export class GetOrderDetailsTool extends BaseTool {
  name = 'get_order_details';
  description = 'Get complete details of a specific order';
  riskLevel = RiskLevel.LOW;
  inputSchema = z.object({
    orderId: z.string().optional(),
    reference: z.string().optional(),
  });

  protected async executeInternal(input: z.infer<typeof this.inputSchema>, context: ToolContext) {
    if (!input.orderId && !input.reference) {
      return {
        success: false,
        error: 'Either orderId or reference must be provided',
      };
    }

    const order = await prisma.booking.findFirst({
      where: input.orderId 
        ? { id: input.orderId }
        : { reference: input.reference },
      include: {
        pickupAddress: true,
        dropoffAddress: true,
        BookingItem: true,
        driver: {
          include: { User: true },
        },
        Assignment: true,
        Payment: true,
        TrackingPing: {
          orderBy: { createdAt: 'desc' },
          take: 1,
        },
      },
    });

    if (!order) {
      return {
        success: false,
        error: 'Order not found',
      };
    }

    const { BookingItem, ...orderRest } = order;
    const normalizedOrder = {
      ...orderRest,
      items: BookingItem,
    };

    return {
      success: true,
      data: {
        order: normalizedOrder,
        summary: {
          reference: normalizedOrder.reference,
          status: normalizedOrder.status,
          driver: normalizedOrder.driver?.User.name || 'Not assigned',
          createdAt: normalizedOrder.createdAt,
          totalAmount: normalizedOrder.totalGBP,
        },
      },
    };
  }
}

